--
-- Name: enforce_lam_region(); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.enforce_lam_region() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'au', 'public'
    AS $$
declare seat_region text;
begin
  if new.dm_seat_id is not null then
    select region_code into seat_region from au.seats where seat_id = new.dm_seat_id;
    if seat_region is distinct from new.operational_region_code then
      raise exception 'line_area_map(%,%): operational_region_code % must equal dm_seat % region %',
        new.line_code, new.area_code, new.operational_region_code, new.dm_seat_id, seat_region;
    end if;
  end if;
  return new;
end $$;

ALTER FUNCTION au.enforce_lam_region() OWNER TO postgres;

--
-- Name: f_attribution_config_fingerprint(); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_attribution_config_fingerprint() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select concat_ws('|',
    (select coalesce(sum(hashtextextended(m.*::text,0)),0)::text||':'||count(*)::text||':'||count(*) filter (where m.effective_to is null)::text from au.line_area_map m),
    (select coalesce(sum(hashtextextended(c.*::text,0)),0)::text||':'||count(*)::text from au.sos_area_crosswalk c),
    (select coalesce(sum(hashtextextended(l.*::text,0)),0)::text||':'||count(*)::text from au.sos_official_line_map l),
    (select coalesce(sum(hashtextextended(p.*::text,0)),0)::text||':'||count(*)::text from public.source_of_sales_products p),
    (select coalesce(sum(hashtextextended(d.*::text,0)),0)::text||':'||count(*)::text from au.direct_region_allocation d),
    (select coalesce(sum(hashtextextended((s.period, s.line_code, s.area_code, s.product_code, s.net_qty, s.net_effective_units)::text,0)),0)::text||':'||count(*)::text from au.monthly_store_split_net s)
  );
$$;

ALTER FUNCTION au.f_attribution_config_fingerprint() OWNER TO postgres;

--
-- Name: f_last_occupied_seat_by_hr_id(text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_last_occupied_seat_by_hr_id(p_hr_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select oh.seat_id
  from au.occupancy_history oh
  where oh.occupant_canonical_hr_id = lower(btrim(p_hr_id))
    and oh.node_type = 'person'
    and oh.effective_to is not null
  order by oh.effective_to desc
  limit 1;
$$;

ALTER FUNCTION au.f_last_occupied_seat_by_hr_id(p_hr_id text) OWNER TO postgres;

--
-- Name: FUNCTION f_last_occupied_seat_by_hr_id(p_hr_id text); Type: COMMENT; Schema: au; Owner: postgres
--

COMMENT ON FUNCTION au.f_last_occupied_seat_by_hr_id(p_hr_id text) IS 'The seat_id of the most recently CLOSED person-occupancy span for the given (normalized) HR_ID - i.e. the seat this person held immediately before their last resignation/transfer out. NULL if they never held an au seat. Deliberately restricted to CLOSED spans and ordered by effective_to, not effective_from: resign_occupant only ever closes the seat a person currently holds, so the most-recently-closed row is unambiguous regardless of how many earlier seats/transfers preceded it.';

--
-- Name: f_line_area_map_asof(date); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_line_area_map_asof(p_asof date) RETURNS TABLE(line_code text, area_code text, operational_region_code text, area_state text, other_type text, staffed_in_line_code text, dm_seat_id text, rep_seat_id text, carries_target boolean)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 150 PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select distinct on (m.line_code, m.area_code)
    m.line_code,
    m.area_code,
    m.operational_region_code,
    m.area_state,
    m.other_type,
    m.staffed_in_line_code,
    m.dm_seat_id,
    m.rep_seat_id,
    m.carries_target
  from au.line_area_map m
  order by
    m.line_code,
    m.area_code,
    (m.effective_from <= p_asof and (m.effective_to is null or m.effective_to > p_asof)) desc,
    m.effective_from asc;
$$;

ALTER FUNCTION au.f_line_area_map_asof(p_asof date) OWNER TO postgres;

--
-- Name: FUNCTION f_line_area_map_asof(p_asof date); Type: COMMENT; Schema: au; Owner: postgres
--

COMMENT ON FUNCTION au.f_line_area_map_asof(p_asof date) IS 'Canonical (line_code, area_code) -> DM/rep seat mapping as of p_asof. Exactly one row per key, so joining it can never fan out a sales fact row across a superseded and a current mapping.';

--
-- Name: f_line_area_occupancy_drift(); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_line_area_occupancy_drift() RETURNS TABLE(drift_kind text, line_code text, area_code text, area_state text, rep_seat_id text, occupant_hr_id text, detail text)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $_$
  select 'occupied_but_seat_vacant', m.line_code, m.area_code, m.area_state, m.rep_seat_id,
         null::text,
         'rep seat has no current occupant (vacated without the area being released)'
  from au.line_area_map m
  where m.effective_to is null
    and m.area_state = 'occupied'
    and m.rep_seat_id is not null
    and not exists (
      select 1 from au.occupancy_history o
      where o.seat_id = m.rep_seat_id and o.effective_to is null and o.occupant_hr_id is not null
    )

  union all
  select 'vacant_but_seat_occupied', m.line_code, m.area_code, m.area_state, m.rep_seat_id,
         o.occupant_hr_id,
         'rep seat is occupied (hired without the area being marked staffed)'
  from au.line_area_map m
  join au.occupancy_history o
    on o.seat_id = m.rep_seat_id and o.effective_to is null and o.occupant_hr_id is not null
  where m.effective_to is null
    and m.area_state = 'vacant_will_hire'

  union all
  select 'staffable_row_without_rep_seat', m.line_code, m.area_code, m.area_state, null::text,
         null::text,
         'area_state is occupied/vacant_will_hire but rep_seat_id is null'
  from au.line_area_map m
  where m.effective_to is null
    and m.area_state in ('occupied', 'vacant_will_hire')
    and m.rep_seat_id is null

  union all
  select 'other_row_with_rep_seat', m.line_code, m.area_code, m.area_state, m.rep_seat_id,
         null::text,
         'other_permanent/other_line_specific row carries a rep seat'
  from au.line_area_map m
  where m.effective_to is null
    and m.area_state in ('other_permanent', 'other_line_specific')
    and m.rep_seat_id is not null

  union all
  select 'rep_seat_absent_from_map', s.line_code, s.area_code, null::text, s.seat_id,
         o.occupant_hr_id,
         'REP seat has no open line_area_map row referencing it'
  from au.seats s
  left join au.occupancy_history o
    on o.seat_id = s.seat_id and o.effective_to is null
  where s.seat_tier = 'REP'
    and not exists (
      select 1 from au.line_area_map m
      where m.effective_to is null and m.rep_seat_id = s.seat_id
    )

  union all
  select 'seat_label_asserts_occupancy', s.line_code, s.area_code, null::text, s.seat_id,
         o.occupant_hr_id,
         'seat_label hard-codes an occupancy state (' || s.seat_label ||
           ') - occupancy belongs in au.v_org_tree.seat_display_label, which is derived'
  from au.seats s
  left join au.occupancy_history o
    on o.seat_id = s.seat_id and o.effective_to is null
  where s.seat_label ~* '\((?:vacant|occupied)\)\s*$';
$_$;

ALTER FUNCTION au.f_line_area_occupancy_drift() OWNER TO postgres;

--
-- Name: FUNCTION f_line_area_occupancy_drift(); Type: COMMENT; Schema: au; Owner: postgres
--

COMMENT ON FUNCTION au.f_line_area_occupancy_drift() IS 'Reconciles au.line_area_map.area_state against au.occupancy_history. Empty = consistent. Non-empty means a vacated area still reads as staffed (or the reverse) somewhere in the sales territory views.';

--
-- Name: f_monthly_achievement(text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_monthly_achievement(p_period text) RETURNS TABLE(period text, line_code text, region_code text, area_code text, area_state text, is_other boolean, rep_seat_id text, rep_hr_id text, dm_seat_id text, dm_hr_id text, product_code text, actual_units numeric, actual_value numeric, target_units numeric, target_value numeric, achievement_value numeric, achievement_units numeric, has_target boolean, has_actual boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
#variable_conflict use_column
declare
  v_period_end date := (date_trunc('month', to_date(p_period || '-01','YYYY-MM-DD')) + interval '1 month - 1 day')::date;
  v_meta_fp text;
begin
  -- Coverage + config-freshness gate: read the precomputed attribution money only when this period was
  -- refreshed AND the tiny config surface has not drifted since. Otherwise fall back to the exact live
  -- computation -- never serve stale attribution into targets/incentives.
  select config_fp into v_meta_fp from au.monthly_attribution_rollup_meta where period = p_period;
  if v_meta_fp is null or v_meta_fp <> au.f_attribution_config_fingerprint() then
    return query select * from au.f_monthly_achievement_live(p_period);
    return;
  end if;

  return query
  with attribution as (
    select a.line_code, a.area_code, a.region_code, a.product_code, a.sales_units, a.sales_value
    from au.monthly_attribution_rollup a
    where a.period = p_period
  ),
  actuals as (
    select
      at.line_code,
      at.area_code,
      case when at.area_code is null then at.region_code end as direct_region_code,
      at.product_code,
      sum(at.sales_units) as actual_units,
      sum(at.sales_value) as actual_value,
      true as matched,
      concat_ws(chr(31),
        coalesce(at.line_code, chr(30)),
        coalesce(at.area_code, chr(30)),
        coalesce(case when at.area_code is null then at.region_code end, chr(30)),
        coalesce(at.product_code, chr(30))) as join_key
    from attribution at
    group by at.line_code, at.area_code,
             case when at.area_code is null then at.region_code end,
             at.product_code
  ),
  tgt as (
    select t.line_code, t.area_code, null::text as direct_region_code,
           t.product_code, t.target_units, t.target_value,
      concat_ws(chr(31),
        coalesce(t.line_code, chr(30)),
        coalesce(t.area_code, chr(30)),
        coalesce(null::text, chr(30)),
        coalesce(t.product_code, chr(30))) as join_key
    from au.monthly_targets t
    where t.period = p_period
  ),
  keys as (
    select actuals.join_key, actuals.line_code, actuals.area_code, actuals.direct_region_code, actuals.product_code from actuals
    union
    select tgt.join_key, tgt.line_code, tgt.area_code, tgt.direct_region_code, tgt.product_code from tgt
  ),
  lam_asof as materialized (
    select
      l.line_code,
      l.area_code,
      l.operational_region_code,
      l.area_state,
      l.other_type,
      l.dm_seat_id,
      l.rep_seat_id,
      au.f_seat_occupant_asof(l.rep_seat_id, v_period_end) as rep_occupant_hr_id,
      au.f_seat_occupant_asof(l.dm_seat_id, v_period_end)  as dm_occupant_hr_id
    from au.f_line_area_map_asof(v_period_end) l
  ),
  region_dm as (
    select
      lam.line_code,
      lam.operational_region_code,
      min(lam.dm_seat_id)          as dm_seat_id,
      min(lam.dm_occupant_hr_id)   as dm_occupant_hr_id
    from lam_asof lam
    where lam.operational_region_code is not null
    group by lam.line_code, lam.operational_region_code
  )
  select
    p_period,
    k.line_code,
    coalesce(lam.operational_region_code, k.direct_region_code),
    k.area_code,
    lam.area_state,
    (lam.other_type is not null),
    lam.rep_seat_id, lam.rep_occupant_hr_id,
    coalesce(lam.dm_seat_id, rdm.dm_seat_id),
    coalesce(lam.dm_occupant_hr_id, rdm.dm_occupant_hr_id),
    k.product_code,
    coalesce(ac.actual_units, 0), coalesce(ac.actual_value, 0),
    tg.target_units, tg.target_value,
    case when tg.target_value is not null and tg.target_value <> 0
         then coalesce(ac.actual_value, 0) / tg.target_value end,
    case when tg.target_units is not null and tg.target_units <> 0
         then coalesce(ac.actual_units, 0) / tg.target_units end,
    (tg.line_code is not null),
    coalesce(ac.matched, false)
  from keys k
  left join actuals ac
    on ac.join_key = k.join_key
  left join tgt tg
    on tg.join_key = k.join_key
  left join lam_asof lam
    on lam.line_code = k.line_code
   and lam.area_code = k.area_code
  left join region_dm rdm
    on rdm.line_code = k.line_code
   and rdm.operational_region_code = k.direct_region_code;
end;
$$;

