--
-- Name: f_monthly_attribution(text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_monthly_attribution(p_period text) RETURNS TABLE(period text, channel text, line_code text, region_code text, area_code text, area_state text, is_other boolean, rep_seat_id text, rep_hr_id text, dm_seat_id text, dm_hr_id text, product_code text, sales_units numeric, sales_value numeric, mapped boolean, unmapped_reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
declare
  v_period_end date := (date_trunc('month', to_date(p_period || '-01','YYYY-MM-DD')) + interval '1 month - 1 day')::date;
begin
  return query
  with price as (
    select c.code,
           coalesce(
             (select h.factory_price from public.source_of_sales_product_price_history h
               where upper(btrim(h.product_code)) = c.code
                 and h.effective_period <= p_period
               order by h.effective_period desc limit 1),
             (select pr.factory_price from public.source_of_sales_products pr
               where upper(btrim(pr.product_code)) = c.code limit 1)
           ) as factory_price
    from (
      select upper(btrim(pm.product_code)) as code from public.source_of_sales_products pm
      union
      select upper(btrim(ph.product_code)) as code from public.source_of_sales_product_price_history ph
    ) c
  ),
  fact_raw as (
    -- One row per RAW key combination, summed. The text cleanup below then runs per group, not
    -- per fact row. Every amount is numeric, so these sums are exact.
    select f.official_line, f.region_code, f.area_code, f.product_code, f.is_direct,
           sum(f.total_qty) as total_qty,
           sum(f.effective_units) as effective_units,
           sum(f.direct_value) as direct_value
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b on b.id = f.batch_id and b.status = 'validated'
    where f.period = p_period
    group by f.official_line, f.region_code, f.area_code, f.product_code, f.is_direct
  ),
  fact as (
    select fr.official_line, fr.region_code as sos_region_code,
           nullif(btrim(fr.area_code),'') as sos_area_code,
           upper(btrim(coalesce(fr.product_code,''))) as product_code,
           fr.is_direct, fr.total_qty, fr.effective_units, fr.direct_value
    from fact_raw fr
    where upper(btrim(coalesce(fr.product_code,''))) not in ('LA003','LA004','SS001')
  ),
  priced as (
    select fa.sos_region_code, fa.product_code, fa.is_direct, fa.total_qty, fa.effective_units,
           fa.direct_value, lm.line_code, cw.canonical_area_code,
           coalesce(pp.factory_price,0) as factory_price
    from fact fa
    left join au.sos_official_line_map lm on lower(btrim(lm.official_line)) = lower(btrim(fa.official_line))
    left join au.sos_area_crosswalk cw on cw.sos_area_code = fa.sos_area_code
    left join price pp on pp.code = upper(btrim(fa.product_code))
  ),
  alloc as (
    select a.line_code, a.sos_region_code, a.target_region_code,
           a.weight / sum(a.weight) over (partition by a.line_code, a.sos_region_code) as share
    from au.direct_region_allocation a
  ),
  lam_asof as materialized (
    select l.line_code, l.area_code, l.operational_region_code, l.area_state, l.other_type,
           l.dm_seat_id, l.rep_seat_id,
           au.f_seat_occupant_asof(l.rep_seat_id, v_period_end) as rep_occupant_hr_id,
           au.f_seat_occupant_asof(l.dm_seat_id, v_period_end) as dm_occupant_hr_id
    from au.f_line_area_map_asof(v_period_end) l
  ),
  ind_base as (
    select pr.line_code, pr.canonical_area_code, pr.product_code,
           sum(pr.total_qty) as q, sum(pr.effective_units) as eu
    from priced pr
    where not pr.is_direct and pr.line_code is not null and pr.canonical_area_code is not null
    group by pr.line_code, pr.canonical_area_code, pr.product_code
  ),
  split as (
    select s.line_code, s.area_code, s.product_code, s.net_qty, s.net_effective_units
    from au.monthly_store_split_net s where s.period = p_period
  ),
  ind_keys as (
    select b.line_code, b.canonical_area_code as area_code, b.product_code from ind_base b
    union
    select s.line_code, s.area_code, s.product_code from split s
  ),
  ind_agg as (
    select k.line_code, k.area_code as canonical_area_code, k.product_code,
           coalesce(b.q,0) + coalesce(s.net_qty,0) as q,
           (coalesce(b.eu,0) + coalesce(s.net_effective_units,0)) * coalesce(pp.factory_price,0) as v
    from ind_keys k
    left join ind_base b on b.line_code=k.line_code and b.canonical_area_code=k.area_code and b.product_code=k.product_code
    left join split s on s.line_code=k.line_code and s.area_code=k.area_code and s.product_code=k.product_code
    left join price pp on pp.code = upper(btrim(k.product_code))
  ),
  dir_agg as (
    select pr.line_code, pr.canonical_area_code, pr.product_code,
           sum(pr.total_qty) as q, sum(pr.direct_value) as v
    from priced pr
    where pr.is_direct and pr.line_code is not null and pr.canonical_area_code is not null
    group by pr.line_code, pr.canonical_area_code, pr.product_code
  )
  select p_period, 'indirect'::text, lam.line_code, lam.operational_region_code, lam.area_code,
         lam.area_state, (lam.other_type is not null), lam.rep_seat_id, lam.rep_occupant_hr_id,
         lam.dm_seat_id, lam.dm_occupant_hr_id, ia.product_code, ia.q, ia.v, true, null::text
  from ind_agg ia
  join lam_asof lam on lam.line_code = ia.line_code and lam.area_code = ia.canonical_area_code
  union all
  select p_period, 'direct'::text, lam.line_code, lam.operational_region_code, lam.area_code,
         lam.area_state, (lam.other_type is not null), lam.rep_seat_id, lam.rep_occupant_hr_id,
         lam.dm_seat_id, lam.dm_occupant_hr_id, da.product_code, da.q, da.v, true, null::text
  from dir_agg da
  join lam_asof lam on lam.line_code = da.line_code and lam.area_code = da.canonical_area_code
  union all
  select p_period, 'direct'::text, pr.line_code,
         coalesce(alloc.target_region_code, coalesce(nullif(pr.sos_region_code,''), 'NATIONAL')),
         null, null, false, null, null, null, null, pr.product_code,
         sum(pr.total_qty * coalesce(alloc.share, 1)),
         sum(pr.direct_value * coalesce(alloc.share, 1)), true, null::text
  from priced pr
  left join lam_asof lam on lam.line_code = pr.line_code and lam.area_code = pr.canonical_area_code
  left join alloc on alloc.line_code = pr.line_code
                 and alloc.sos_region_code = coalesce(nullif(pr.sos_region_code,''), 'NATIONAL')
  where pr.is_direct and pr.line_code is not null
    and (pr.canonical_area_code is null or lam.line_code is null)
  group by pr.line_code,
           coalesce(alloc.target_region_code, coalesce(nullif(pr.sos_region_code,''),'NATIONAL')),
           pr.product_code
  union all
  select p_period, 'unmapped'::text, pr.line_code, null, pr.canonical_area_code, null, false,
         null, null, null, null, pr.product_code,
         sum(pr.total_qty),
         sum(case when pr.is_direct then pr.direct_value else pr.effective_units * pr.factory_price end),
         false,
         case when pr.line_code is null then 'unmapped_line'
              when (not pr.is_direct) and pr.canonical_area_code is null then 'blank_area'
              when (not pr.is_direct) then 'no_area_map'
              else 'unmapped_other' end
  from priced pr
  left join lam_asof lam on lam.line_code = pr.line_code and lam.area_code = pr.canonical_area_code
  where pr.line_code is null
     or ((not pr.is_direct) and (pr.canonical_area_code is null or lam.line_code is null))
  group by pr.line_code, pr.canonical_area_code, pr.is_direct,
           case when pr.line_code is null then 'unmapped_line'
                when (not pr.is_direct) and pr.canonical_area_code is null then 'blank_area'
                when (not pr.is_direct) then 'no_area_map'
                else 'unmapped_other' end,
           pr.product_code;
end;
$$;

ALTER FUNCTION au.f_monthly_attribution(p_period text) OWNER TO postgres;

--
-- Name: f_monthly_attribution_pre_split(text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_monthly_attribution_pre_split(p_period text) RETURNS TABLE(period text, channel text, line_code text, region_code text, area_code text, area_state text, is_other boolean, rep_seat_id text, rep_hr_id text, dm_seat_id text, dm_hr_id text, product_code text, sales_units numeric, sales_value numeric, mapped boolean, unmapped_reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
declare
  v_period_end date := (date_trunc('month', to_date(p_period || '-01','YYYY-MM-DD')) + interval '1 month - 1 day')::date;
begin
  return query
  with fact as (
    select f.official_line, f.region_code as sos_region_code,
      nullif(btrim(f.area_code),'') as sos_area_code,
      upper(btrim(coalesce(f.product_code,''))) as product_code,
      f.is_direct, f.total_qty, f.effective_units, f.direct_value
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b on b.id=f.batch_id and b.status='validated'
    where f.period = p_period
      and upper(btrim(coalesce(f.product_code,''))) not in ('LA003','LA004','SS001')
  ),
  priced as (
    select fa.sos_region_code, fa.product_code, fa.is_direct,
           fa.total_qty, fa.effective_units, fa.direct_value,
           lm.line_code, cw.canonical_area_code,
           coalesce(public.phx_factory_price(fa.product_code, p_period),0) as factory_price
    from fact fa
    left join au.sos_official_line_map lm on lower(btrim(lm.official_line))=lower(btrim(fa.official_line))
    left join au.sos_area_crosswalk cw on cw.sos_area_code=fa.sos_area_code
    left join public.source_of_sales_products pp on upper(btrim(pp.product_code))=fa.product_code
  ),
  alloc as (
    select a.line_code, a.sos_region_code, a.target_region_code,
      a.weight/sum(a.weight) over (partition by a.line_code, a.sos_region_code) as share
    from au.direct_region_allocation a
  ),
  lam_asof as materialized (
    select l.line_code, l.area_code, l.operational_region_code, l.area_state, l.other_type,
      l.dm_seat_id, l.rep_seat_id,
      au.f_seat_occupant_asof(l.rep_seat_id, v_period_end) as rep_occupant_hr_id,
      au.f_seat_occupant_asof(l.dm_seat_id, v_period_end) as dm_occupant_hr_id
    from au.f_line_area_map_asof(v_period_end) l
  ),
  ind_agg as (
    select pr.line_code, pr.canonical_area_code, pr.product_code,
           sum(pr.total_qty) as q, sum(pr.effective_units * pr.factory_price) as v
    from priced pr
    where not pr.is_direct and pr.line_code is not null and pr.canonical_area_code is not null
    group by pr.line_code, pr.canonical_area_code, pr.product_code
  ),
  dir_agg as (
    select pr.line_code, pr.canonical_area_code, pr.product_code,
           sum(pr.total_qty) as q, sum(pr.direct_value) as v
    from priced pr
    where pr.is_direct and pr.line_code is not null and pr.canonical_area_code is not null
    group by pr.line_code, pr.canonical_area_code, pr.product_code
  )
  select p_period, 'indirect'::text, lam.line_code, lam.operational_region_code, lam.area_code,
    lam.area_state, (lam.other_type is not null),
    lam.rep_seat_id, lam.rep_occupant_hr_id, lam.dm_seat_id, lam.dm_occupant_hr_id,
    ia.product_code, ia.q, ia.v, true, null::text
  from ind_agg ia
  join lam_asof lam on lam.line_code = ia.line_code and lam.area_code = ia.canonical_area_code

  union all
  select p_period, 'direct'::text, lam.line_code, lam.operational_region_code, lam.area_code,
    lam.area_state, (lam.other_type is not null),
    lam.rep_seat_id, lam.rep_occupant_hr_id, lam.dm_seat_id, lam.dm_occupant_hr_id,
    da.product_code, da.q, da.v, true, null::text
  from dir_agg da
  join lam_asof lam on lam.line_code = da.line_code and lam.area_code = da.canonical_area_code

  union all
  select p_period, 'direct'::text, pr.line_code,
    coalesce(alloc.target_region_code, coalesce(nullif(pr.sos_region_code,''), 'NATIONAL')),
    null, null, false, null, null, null, null,
    pr.product_code,
    sum(pr.total_qty * coalesce(alloc.share, 1)),
    sum(pr.direct_value * coalesce(alloc.share, 1)),
    true, null::text
  from priced pr
  left join lam_asof lam on lam.line_code = pr.line_code and lam.area_code = pr.canonical_area_code
  left join alloc on alloc.line_code = pr.line_code
                 and alloc.sos_region_code = coalesce(nullif(pr.sos_region_code,''), 'NATIONAL')
  where pr.is_direct and pr.line_code is not null
    and (pr.canonical_area_code is null or lam.line_code is null)
  group by pr.line_code,
           coalesce(alloc.target_region_code, coalesce(nullif(pr.sos_region_code,''),'NATIONAL')),
           pr.product_code

  union all
  select p_period, 'unmapped'::text, pr.line_code, null, pr.canonical_area_code, null, false,
    null, null, null, null, pr.product_code,
    sum(pr.total_qty),
    sum(case when pr.is_direct then pr.direct_value else pr.effective_units * pr.factory_price end),
    false,
    case
      when pr.line_code is null then 'unmapped_line'
      when (not pr.is_direct) and pr.canonical_area_code is null then 'blank_area'
      when (not pr.is_direct) then 'no_area_map'
      else 'unmapped_other'
    end
  from priced pr
  left join lam_asof lam on lam.line_code = pr.line_code and lam.area_code = pr.canonical_area_code
  where pr.line_code is null
     or ((not pr.is_direct) and (pr.canonical_area_code is null or lam.line_code is null))
  group by pr.line_code, pr.canonical_area_code, pr.is_direct,
           case
             when pr.line_code is null then 'unmapped_line'
             when (not pr.is_direct) and pr.canonical_area_code is null then 'blank_area'
             when (not pr.is_direct) then 'no_area_map'
             else 'unmapped_other'
           end,
           pr.product_code;
end;
$$;

ALTER FUNCTION au.f_monthly_attribution_pre_split(p_period text) OWNER TO postgres;

--
-- Name: f_monthly_attribution_reconcile(text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_monthly_attribution_reconcile(p_period text) RETURNS TABLE(line_code text, mapped_value numeric, unmapped_value numeric, attributed_value numeric, raw_value numeric, diff numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  with att as (
    select coalesce(a.line_code,'(unmapped)') as line_code,
           sum(a.sales_value) filter (where a.mapped)     as mapped_value,
           sum(a.sales_value) filter (where not a.mapped)  as unmapped_value,
           sum(a.sales_value)                              as attributed_value
    from au.f_monthly_attribution(p_period) a
    group by coalesce(a.line_code,'(unmapped)')
  ),
  raw as (
    select coalesce(lm.line_code,'(unmapped)') as line_code,
           sum(case when f.is_direct then f.direct_value
                    else f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period),0) end) as raw_value
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b on b.id = f.batch_id and b.status = 'validated'
    left join au.sos_official_line_map lm on lower(btrim(lm.official_line)) = lower(btrim(f.official_line))
    left join public.source_of_sales_products pp on upper(btrim(pp.product_code)) = upper(btrim(f.product_code))
    where f.period = p_period
      and upper(btrim(coalesce(f.product_code,''))) not in ('LA003','LA004','SS001')
    group by coalesce(lm.line_code,'(unmapped)')
  )
  select
    coalesce(att.line_code, raw.line_code)          as line_code,
    coalesce(att.mapped_value,0)                    as mapped_value,
    coalesce(att.unmapped_value,0)                  as unmapped_value,
    coalesce(att.attributed_value,0)                as attributed_value,
    coalesce(raw.raw_value,0)                       as raw_value,
    coalesce(att.attributed_value,0) - coalesce(raw.raw_value,0) as diff
  from att
  full join raw on raw.line_code = att.line_code
  order by 1;
$$;

ALTER FUNCTION au.f_monthly_attribution_reconcile(p_period text) OWNER TO postgres;

--
-- Name: f_rebuild_monthly_attribution_all(); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_rebuild_monthly_attribution_all() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare r record; n int := 0;
begin
  for r in
    select distinct f.period
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b on b.id = f.batch_id and b.status = 'validated'
    order by f.period
  loop
    perform au.f_refresh_monthly_attribution(r.period);
    n := n + 1;
  end loop;
  return n;
end;
$$;

ALTER FUNCTION au.f_rebuild_monthly_attribution_all() OWNER TO postgres;

--
-- Name: f_refresh_monthly_attribution(text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_refresh_monthly_attribution(p_period text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare
  v_frozen text[];
  v_any    boolean;
begin
  -- Serialize refreshes of the SAME period: two concurrent runs both delete and both insert, which
  -- doubled 2026-09 on 2026-09-29 (22 rows -> 44, 579,055.85 -> 1,158,111.70). Transaction-scoped on
  -- purpose — the sweep holds one per period to commit, and a crashed caller releases everything.
  perform pg_advisory_xact_lock(hashtext('au.f_refresh_monthly_attribution:' || coalesce(p_period, '')));

  -- 🔒 A PUBLISHED LINE KEEPS ITS ROLLUP; THE OTHER LINES OF THE SAME MONTH DO NOT FREEZE WITH IT.
  -- Fails closed: a published line Phoenix cannot map to a line_code freezes the whole period.
  if exists (
    select 1 from public.monthly_closing_publications pub
    left join au.sos_official_line_map lm
      on lower(btrim(lm.official_line)) = lower(btrim(pub.line))
    where pub.period = p_period and pub.unpublished_at is null
      and lm.line_code is null
  ) then
    raise notice 'f_refresh_monthly_attribution: % has a published line with no line_code — leaving the whole period frozen', p_period;
    return;
  end if;

  v_frozen := array(
    select distinct lm.line_code
    from public.monthly_closing_publications pub
    join au.sos_official_line_map lm
      on lower(btrim(lm.official_line)) = lower(btrim(pub.line))
    where pub.period = p_period and pub.unpublished_at is null
  );
  v_any := cardinality(v_frozen) > 0;

  if not exists (select 1 from au.sos_official_line_map lm where lm.line_code <> all (v_frozen)) then
    raise notice 'f_refresh_monthly_attribution: every line of % is published — leaving its attribution rollup frozen', p_period;
    return;
  end if;

  -- A row with no line_code belongs to no closing, so it stays frozen while ANY line is published.
  delete from au.monthly_attribution_rollup r
  where r.period = p_period
    and (not v_any or (r.line_code is not null and r.line_code <> all (v_frozen)));

  insert into au.monthly_attribution_rollup
    (period, line_code, area_code, region_code, product_code, sales_units, sales_value)
  select a.period, a.line_code, a.area_code, a.region_code, a.product_code, a.sales_units, a.sales_value
  from au.f_monthly_attribution(p_period) a
  where not v_any or (a.line_code is not null and a.line_code <> all (v_frozen));

  insert into au.monthly_attribution_rollup_meta(period, config_fp, refreshed_at)
  values (p_period, au.f_attribution_config_fingerprint(), now())
  on conflict (period) do update
    set config_fp = excluded.config_fp, refreshed_at = excluded.refreshed_at;
end;
$$;

ALTER FUNCTION au.f_refresh_monthly_attribution(p_period text) OWNER TO postgres;

--
-- Name: FUNCTION f_refresh_monthly_attribution(p_period text); Type: COMMENT; Schema: au; Owner: postgres
--

COMMENT ON FUNCTION au.f_refresh_monthly_attribution(p_period text) IS 'Rebuilds one period of au.monthly_attribution_rollup. Takes a transaction-scoped advisory lock on the period: two concurrent refreshes would otherwise both delete and both insert, doubling the month (measured 2026-09-29 on 2026-09). Refuses a published period, leaving its rollup frozen.';

--
-- Name: f_refresh_stale_attribution_periods(integer); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_refresh_stale_attribution_periods(p_limit integer DEFAULT 6) RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare
  v_fp text := au.f_attribution_config_fingerprint();
  v_limit integer := greatest(1, least(24, coalesce(p_limit, 6)));
  r record;
begin
  for r in
    select p.period
    from (
      -- Every distinct period, one index probe per step, instead of a DISTINCT over the whole rollup.
      with recursive periods(period) as (
        (
          select f.period
          from public.source_of_sales_fact_rollup f
          where f.period is not null
          order by f.period
          limit 1
        )
        union all
        select (
          select f.period
          from public.source_of_sales_fact_rollup f
          where f.period > periods.period
          order by f.period
          limit 1
        )
        from periods
        where periods.period is not null
      )
      select periods.period
      from periods
      -- Kept only when a VALIDATED batch holds a row of it, which is what the old join asked. LIMIT 1
      -- stops at the first such row; a plain EXISTS is flattened into a semi-join over the whole table.
      cross join lateral (
        select 1
        from public.source_of_sales_fact_rollup f
        join public.source_of_sales_import_batches b on b.id = f.batch_id and b.status = 'validated'
        where f.period = periods.period
        limit 1
      ) validated
      where periods.period is not null
    ) p
    left join au.monthly_attribution_rollup_meta m on m.period = p.period
    where (m.config_fp is null or m.config_fp <> v_fp)
      -- A period f_refresh_monthly_attribution would decline whole is excluded, so it neither takes
      -- a slot nor is reported as refreshed: a published line it cannot map, or every line published.
      -- A period with only SOME lines published is kept — its other lines still refresh.
      and not exists (
        select 1
        from public.monthly_closing_publications pub
        left join au.sos_official_line_map lm
          on lower(btrim(lm.official_line)) = lower(btrim(pub.line))
        where pub.period = p.period and pub.unpublished_at is null
          and lm.line_code is null
      )
      and exists (
        select 1
        from au.sos_official_line_map lm
        where lm.line_code not in (
          select lm2.line_code
          from public.monthly_closing_publications pub
          join au.sos_official_line_map lm2
            on lower(btrim(lm2.official_line)) = lower(btrim(pub.line))
          where pub.period = p.period and pub.unpublished_at is null
        )
      )
    order by p.period desc
    limit v_limit
  loop
    perform au.f_refresh_monthly_attribution(r.period);
    return next r.period;
  end loop;
end;
$$;

ALTER FUNCTION au.f_refresh_stale_attribution_periods(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION f_refresh_stale_attribution_periods(p_limit integer); Type: COMMENT; Schema: au; Owner: postgres
--

COMMENT ON FUNCTION au.f_refresh_stale_attribution_periods(p_limit integer) IS 'Refreshes up to p_limit stale attribution periods, newest first. Published periods are excluded: their rollup is deliberately frozen and never stamped, so before 2026-09-29 they were re-attempted on every call, occupied slots, and were REPORTED as refreshed when nothing happened. Reads monthly_closing_publications, not monthly_closing_locks. Since 2026-10-26 the candidate months come from a skip-scan of the period index with one LIMIT 1 validated-batch probe each (16 ms against 264 ms for the old DISTINCT over the whole rollup).';

--
-- Name: f_sales_area_trend(text, text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_sales_area_trend(p_line_code text, p_area_code text, p_product_code text DEFAULT NULL::text) RETURNS TABLE(period text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select f.period,
         sum(f.total_qty) as units,
         sum(f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period),0)) as value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches ib on ib.id = f.batch_id and ib.status = 'validated'
  join au.sos_official_line_map lm on lower(btrim(lm.official_line)) = lower(btrim(f.official_line)) and lm.line_code = p_line_code
  left join public.source_of_sales_products p on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  where not f.is_direct and f.area_code = p_area_code
    and (p_product_code is null or upper(btrim(f.product_code)) = upper(btrim(p_product_code)))
    and upper(btrim(coalesce(f.product_code,''))) not in ('LA003','LA004','SS001')
  group by f.period
  order by f.period;
$$;

ALTER FUNCTION au.f_sales_area_trend(p_line_code text, p_area_code text, p_product_code text) OWNER TO postgres;

--
-- Name: f_sales_brick_detail(text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_sales_brick_detail(p_period text) RETURNS TABLE(period text, line_code text, region_code text, area_code text, area_state text, rep_seat_id text, rep_hr_id text, dm_seat_id text, dm_hr_id text, brick_id text, brick_name text, block_code text, sales_units numeric, sales_value numeric, direct_value numeric, indirect_value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $_$
declare
  v_period_end date;
begin
  if p_period !~ '^\d{4}-\d{2}$' then
    return;
  end if;
  if to_date(p_period || '-01', 'YYYY-MM-DD') < date '2026-07-01' then
    return;
  end if;

  v_period_end := (date_trunc('month', to_date(p_period || '-01', 'YYYY-MM-DD'))
                   + interval '1 month - 1 day')::date;

  return query
  with fact as materialized (
    select
      f.official_line,
      nullif(btrim(f.area_code), '')            as sos_area_code,
      nullif(btrim(coalesce(f.brick_id, '')), '') as brick_id,
      upper(btrim(coalesce(f.product_code, ''))) as product_code,
      f.is_direct,
      f.total_qty,
      f.effective_units,
      f.direct_value
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b
      on b.id = f.batch_id and b.status = 'validated'
    where f.period = p_period
      and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  ),
  period_price as (
    select d.product_code,
           public.phx_factory_price(d.product_code, p_period) as period_price
    from (
      select distinct fa.product_code
      from fact fa
    ) d
  ),
  priced as materialized (
    select
      fa.*,
      lm.line_code,
      cw.canonical_area_code,
      coalesce(pp.period_price, 0) as factory_price
    from fact fa
    left join au.sos_official_line_map lm
      on lower(btrim(lm.official_line)) = lower(btrim(fa.official_line))
    left join au.sos_area_crosswalk cw
      on cw.sos_area_code = fa.sos_area_code
    left join period_price pp
      on pp.product_code = fa.product_code
  ),
  lam_asof as materialized (
    select
      l.line_code, l.area_code, l.operational_region_code, l.area_state,
      l.dm_seat_id, l.rep_seat_id,
      au.f_seat_occupant_asof(l.rep_seat_id, v_period_end) as rep_occupant_hr_id,
      au.f_seat_occupant_asof(l.dm_seat_id, v_period_end)  as dm_occupant_hr_id
    from au.f_line_area_map_asof(v_period_end) l
  )
  select
    p_period,
    lam.line_code,
    lam.operational_region_code,
    lam.area_code,
    lam.area_state,
    lam.rep_seat_id,
    lam.rep_occupant_hr_id,
    lam.dm_seat_id,
    lam.dm_occupant_hr_id,
    pr.brick_id,
    b.brick_name,
    b.block_code,
    sum(pr.total_qty),
    sum(case when pr.is_direct then pr.direct_value else pr.effective_units * pr.factory_price end),
    sum(case when pr.is_direct then pr.direct_value else 0 end),
    sum(case when pr.is_direct then 0 else pr.effective_units * pr.factory_price end)
  from priced pr
  join lam_asof lam
    on lam.line_code = pr.line_code and lam.area_code = pr.canonical_area_code
  left join public.source_of_sales_bricks b
    on b.brick_id = pr.brick_id
  where pr.line_code is not null and pr.canonical_area_code is not null
  group by
    lam.line_code, lam.operational_region_code, lam.area_code, lam.area_state,
    lam.rep_seat_id, lam.rep_occupant_hr_id, lam.dm_seat_id, lam.dm_occupant_hr_id,
    pr.brick_id, b.brick_name, b.block_code;
end;
$_$;

ALTER FUNCTION au.f_sales_brick_detail(p_period text) OWNER TO postgres;

--
-- Name: f_sales_direct_breakdown(text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_sales_direct_breakdown(p_period text, p_line_code text) RETURNS TABLE(region_code text, product_code text, product_name text, distributor_name text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select
    coalesce(nullif(btrim(f.region_code),''),'NATIONAL') as region_code,
    upper(btrim(f.product_code)) as product_code,
    max(coalesce(p.product_name, f.product_name)) as product_name,
    coalesce(d.distributor_name, f.distributor_code, '(direct)') as distributor_name,
    sum(f.total_qty) as units,
    sum(f.direct_value) as value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches ib on ib.id = f.batch_id and ib.status = 'validated'
  join au.sos_official_line_map lm on lower(btrim(lm.official_line)) = lower(btrim(f.official_line)) and lm.line_code = p_line_code
  left join public.source_of_sales_distributors d on d.distributor_code = f.distributor_code
  left join public.source_of_sales_products p on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  where f.period = p_period
    and f.is_direct
    and upper(btrim(coalesce(f.product_code,''))) not in ('LA003','LA004','SS001')
  group by coalesce(nullif(btrim(f.region_code),''),'NATIONAL'), upper(btrim(f.product_code)),
           coalesce(d.distributor_name, f.distributor_code, '(direct)')
  having sum(f.direct_value) <> 0
  order by value desc;
$$;

ALTER FUNCTION au.f_sales_direct_breakdown(p_period text, p_line_code text) OWNER TO postgres;

--
-- Name: f_sales_source_breakdown(text, text, text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_sales_source_breakdown(p_period text, p_line_code text, p_area_code text, p_product_code text DEFAULT NULL::text) RETURNS TABLE(product_code text, product_name text, distributor_name text, brick_name text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select
    upper(btrim(f.product_code)) as product_code,
    max(coalesce(p.product_name, f.product_name)) as product_name,
    coalesce(d.distributor_name, f.distributor_code, '(unknown distributor)') as distributor_name,
    coalesce(nullif(btrim(b.brick_name), ''), '(no brick)') as brick_name,
    sum(f.total_qty) as units,
    sum(f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period), 0)) as value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches ib on ib.id = f.batch_id and ib.status = 'validated'
  join au.sos_official_line_map lm on lower(btrim(lm.official_line)) = lower(btrim(f.official_line)) and lm.line_code = p_line_code
  left join public.source_of_sales_distributors d on d.distributor_code = f.distributor_code
  left join public.source_of_sales_bricks b on b.brick_id = f.brick_id
  left join public.source_of_sales_products p on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  where f.period = p_period
    and not f.is_direct
    and f.area_code = p_area_code
    and (p_product_code is null or upper(btrim(f.product_code)) = upper(btrim(p_product_code)))
    and upper(btrim(coalesce(f.product_code,''))) not in ('LA003','LA004','SS001')
  group by upper(btrim(f.product_code)),
           coalesce(d.distributor_name, f.distributor_code, '(unknown distributor)'),
           coalesce(nullif(btrim(b.brick_name), ''), '(no brick)')
  having sum(f.total_qty) <> 0 or sum(f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period),0)) <> 0
  order by value desc, units desc;
$$;

ALTER FUNCTION au.f_sales_source_breakdown(p_period text, p_line_code text, p_area_code text, p_product_code text) OWNER TO postgres;

--
-- Name: f_sales_source_breakdown_detail(text, text, text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_sales_source_breakdown_detail(p_period text, p_line_code text, p_area_code text, p_product_code text) RETURNS TABLE(brick_name text, distributor_name text, customer_name text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select
    coalesce(nullif(btrim(b.brick_name), ''), '(no brick)') as brick_name,
    coalesce(d.distributor_name, f.distributor_code, '(unknown distributor)') as distributor_name,
    coalesce(cn.customer_name, '(unmapped customer)') as customer_name,
    sum(f.total_qty) as units,
    sum(f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period), 0)) as value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches ib on ib.id = f.batch_id and ib.status = 'validated'
  join au.sos_official_line_map lm on lower(btrim(lm.official_line)) = lower(btrim(f.official_line)) and lm.line_code = p_line_code
  left join public.source_of_sales_distributors d on d.distributor_code = f.distributor_code
  left join public.source_of_sales_bricks b on b.brick_id = f.brick_id
  left join public.source_of_sales_products p on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  left join lateral (
    select cm.customer_name from public.source_of_sales_customer_map cm
    where cm.customer_code = f.client_code and cm.customer_name is not null
    order by (cm.distributor_code = f.distributor_code) desc nulls last
    limit 1
  ) cn on true
  where f.period = p_period and not f.is_direct and f.area_code = p_area_code
    and (p_product_code is null or upper(btrim(f.product_code)) = upper(btrim(p_product_code)))
    and upper(btrim(coalesce(f.product_code,''))) not in ('LA003','LA004','SS001')
  group by 1, 2, 3
  having sum(f.total_qty) <> 0 or sum(f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period),0)) <> 0
  order by value desc;
$$;

ALTER FUNCTION au.f_sales_source_breakdown_detail(p_period text, p_line_code text, p_area_code text, p_product_code text) OWNER TO postgres;

--
-- Name: f_sales_source_breakdown_line(text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_sales_source_breakdown_line(p_period text, p_line_code text) RETURNS TABLE(area_code text, product_code text, product_name text, distributor_name text, brick_name text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select
    f.area_code,
    upper(btrim(f.product_code)) as product_code,
    max(coalesce(p.product_name, f.product_name)) as product_name,
    coalesce(d.distributor_name, f.distributor_code, '(unknown distributor)') as distributor_name,
    coalesce(nullif(btrim(b.brick_name), ''), '(no brick)') as brick_name,
    sum(f.total_qty) as units,
    sum(f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period), 0)) as value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches ib on ib.id = f.batch_id and ib.status = 'validated'
  join au.sos_official_line_map lm on lower(btrim(lm.official_line)) = lower(btrim(f.official_line)) and lm.line_code = p_line_code
  left join public.source_of_sales_distributors d on d.distributor_code = f.distributor_code
  left join public.source_of_sales_bricks b on b.brick_id = f.brick_id
  left join public.source_of_sales_products p on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  where f.period = p_period
    and not f.is_direct
    and nullif(btrim(f.area_code),'') is not null
    and upper(btrim(coalesce(f.product_code,''))) not in ('LA003','LA004','SS001')
  group by f.area_code, upper(btrim(f.product_code)),
           coalesce(d.distributor_name, f.distributor_code, '(unknown distributor)'),
           coalesce(nullif(btrim(b.brick_name), ''), '(no brick)')
  having sum(f.total_qty) <> 0 or sum(f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period),0)) <> 0
  order by f.area_code, value desc;
$$;

ALTER FUNCTION au.f_sales_source_breakdown_line(p_period text, p_line_code text) OWNER TO postgres;

--
-- Name: f_sales_source_files(text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_sales_source_files(p_period text) RETURNS TABLE(distributor_name text, file_name text, uploaded_by text, uploaded_at timestamp with time zone, total_qty numeric, total_value numeric, importable_rows integer, status text)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select coalesce(ib.distributor_name, ib.distributor_code, '(unknown)') as distributor_name,
         ib.file_name, ib.uploaded_by, ib.created_at,
         ib.total_qty, ib.total_value, ib.importable_rows, ib.status
