--
-- Name: f_sales_vs_target_range(text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_sales_vs_target_range(p_from text, p_to text) RETURNS TABLE(period text, line_code text, region_code text, area_code text, area_state text, is_other boolean, rep_seat_id text, rep_hr_id text, dm_seat_id text, dm_hr_id text, product_code text, actual_units numeric, actual_value numeric, target_units numeric, target_value numeric, achievement_value numeric, achievement_units numeric, has_target boolean, has_actual boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $_$
declare
  -- The engine's DATA floor — the first month Source of Sales holds — not a policy floor.
  -- /sales-vs-target's July start month is enforced in TypeScript before the call.
  v_floor  constant date := date '2026-01-01';
  -- Each period costs one full attribution pass (~128ms on 2026-07 production volume).
  -- 24 months bounds a malformed or hostile range; the UI never asks for more.
  v_max_months constant int := 24;
  v_from date;
  v_to   date;
begin
  if p_from !~ '^\d{4}-\d{2}$' or p_to !~ '^\d{4}-\d{2}$' then
    return;
  end if;

  v_from := greatest(date_trunc('month', to_date(p_from || '-01', 'YYYY-MM-DD'))::date, v_floor);
  v_to   := date_trunc('month', to_date(p_to || '-01', 'YYYY-MM-DD'))::date;

  if v_to < v_from then
    return;
  end if;

  v_to := least(v_to, (v_from + make_interval(months => v_max_months - 1))::date);

  return query
  -- g.d comes back as timestamptz; ::date before to_char so the period label is a pure
  -- calendar month and cannot be shifted by whatever TimeZone the session happens to run.
  select a.*
  from generate_series(v_from, v_to, interval '1 month') g(d)
  cross join lateral au.f_monthly_achievement(to_char(g.d::date, 'YYYY-MM')) a;
end;
$_$;

ALTER FUNCTION au.f_sales_vs_target_range(p_from text, p_to text) OWNER TO postgres;

--
-- Name: f_seat_occupant_asof(text, date); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.f_seat_occupant_asof(p_seat_id text, p_asof date) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'au', 'public'
    AS $$
  select coalesce(
    -- 1. Today's wiring wins: whoever holds this seat now inherits its history.
    (
      select oh.occupant_hr_id
      from au.occupancy_history oh
      where oh.seat_id = p_seat_id
        and oh.effective_from <= (now() at time zone 'Africa/Cairo')::date
        and (oh.effective_to is null or oh.effective_to > (now() at time zone 'Africa/Cairo')::date)
      order by oh.effective_from desc
      limit 1
    ),
    -- 2. Seat vacant today ⇒ the person who actually held it in that period keeps the credit.
    (
      select oh.occupant_hr_id
      from au.occupancy_history oh
      where oh.seat_id = p_seat_id
        and oh.effective_from <= p_asof
        and (oh.effective_to is null or oh.effective_to > p_asof)
      order by oh.effective_from desc
      limit 1
    )
    -- 3. No third arm on purpose. The previous `effective_from asc` fallback returned the earliest
    --    occupant the seat EVER had whenever neither window matched — inventing an owner who never
    --    held the seat in that period. Nobody held it ⇒ NULL, and the sale stays area-level.
  );
$$;

ALTER FUNCTION au.f_seat_occupant_asof(p_seat_id text, p_asof date) OWNER TO postgres;

--
-- Name: FUNCTION f_seat_occupant_asof(p_seat_id text, p_asof date); Type: COMMENT; Schema: au; Owner: postgres
--

COMMENT ON FUNCTION au.f_seat_occupant_asof(p_seat_id text, p_asof date) IS 'Canonical seat-occupant resolver. Returns the occupant of p_seat_id as of p_asof: the occupancy span covering that date (half-open [effective_from, effective_to)), else the earliest span. NULL when that span is a vacant placeholder. Never resolve an occupant by taking the newest occupancy_history row - a resigned occupant is the newest NON-NULL row on a vacated seat.';

--
-- Name: hire_into_seat(text, text, date, text, boolean); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.hire_into_seat(p_seat_id text, p_hr_id text, p_effective_date date, p_actor text DEFAULT NULL::text, p_allow_dual_seat boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare
  v_cur au.occupancy_history;
  v_seat au.seats;
  v_mgr text;
  v_new bigint;
  v_other_seats text;
begin
  select * into v_seat from au.seats where seat_id = p_seat_id;
  if not found then raise exception 'hire: seat % not found', p_seat_id; end if;

  -- Person-level guard: one person, one open seat span. A deliberate acting
  -- arrangement (the only legitimate dual-seat state) must opt in explicitly.
  if not p_allow_dual_seat then
    select string_agg(seat_id, ', ' order by seat_id)
      into v_other_seats
      from au.occupancy_history
     where occupant_canonical_hr_id = lower(btrim(p_hr_id))
       and effective_to is null
       and occupant_hr_id is not null
       and seat_id <> p_seat_id;
    if v_other_seats is not null then
      raise exception 'hire: % already occupies seat(s) % - refusing to double-seat. Use public.phx_transfer_au_seat to move them, or pass p_allow_dual_seat => true for a deliberate acting arrangement.',
        p_hr_id, v_other_seats;
    end if;
  end if;

  select * into v_cur from au.occupancy_history where seat_id = p_seat_id and effective_to is null;
  if found then
    if v_cur.occupant_hr_id is not null then raise exception 'hire: seat % already occupied by %', p_seat_id, v_cur.occupant_hr_id; end if;
    -- A start before the vacant row began closes that row empty rather than inverted.
    update au.occupancy_history set effective_to = greatest(p_effective_date, v_cur.effective_from) where occupancy_id = v_cur.occupancy_id;
  end if;
  select occupant_hr_id into v_mgr from au.occupancy_history where seat_id = v_seat.parent_seat_id and effective_to is null;
  insert into au.occupancy_history(seat_id,occupant_hr_id,node_type,effective_from,event_type,line_code,region_code,area_code,manager_seat_id,manager_hr_id,prev_occupancy_id,change_reason,source_system,changed_by_hr_id)
  values (p_seat_id,p_hr_id,'person',p_effective_date,'hire',v_seat.line_code,v_seat.region_code,v_seat.area_code,v_seat.parent_seat_id,v_mgr,v_cur.occupancy_id,null,'hire_rpc',p_actor)
  returning occupancy_id into v_new;
  -- The seat is filled; the area is staffed again.
  perform au.sync_area_state_for_seat(p_seat_id, 'vacant_will_hire', 'occupied');
  return v_new;
end $$;

ALTER FUNCTION au.hire_into_seat(p_seat_id text, p_hr_id text, p_effective_date date, p_actor text, p_allow_dual_seat boolean) OWNER TO postgres;

--
-- Name: resign_occupant(text, date, text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.resign_occupant(p_seat_id text, p_effective_date date, p_reason text DEFAULT NULL::text, p_actor text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare v_cur au.occupancy_history; v_seat au.seats; v_mgr text; v_new bigint; v_end date;
begin
  select * into v_seat from au.seats where seat_id = p_seat_id;
  if not found then raise exception 'resign: seat % not found', p_seat_id; end if;
  select * into v_cur from au.occupancy_history where seat_id = p_seat_id and effective_to is null;
  if not found then raise exception 'resign: seat % has no open span', p_seat_id; end if;
  if v_cur.occupant_hr_id is null then raise exception 'resign: seat % is already vacant', p_seat_id; end if;
  -- Someone leaving before their start date never held the seat: an empty span, never an inverted one.
  v_end := greatest(p_effective_date, v_cur.effective_from);
  update au.occupancy_history set effective_to = v_end where occupancy_id = v_cur.occupancy_id;
  select occupant_hr_id into v_mgr from au.occupancy_history where seat_id = v_seat.parent_seat_id and effective_to is null;
  insert into au.occupancy_history(seat_id,occupant_hr_id,node_type,effective_from,event_type,line_code,region_code,area_code,manager_seat_id,manager_hr_id,prev_occupancy_id,change_reason,source_system,changed_by_hr_id)
  values (p_seat_id,null,'vacant_placeholder',v_end,'resign',v_seat.line_code,v_seat.region_code,v_seat.area_code,v_seat.parent_seat_id,v_mgr,v_cur.occupancy_id,p_reason,'resignation_rpc',p_actor)
  returning occupancy_id into v_new;
  -- The seat is now vacant; the area it serves must say so too.
  perform au.sync_area_state_for_seat(p_seat_id, 'occupied', 'vacant_will_hire');
  return v_new;
end $$;

ALTER FUNCTION au.resign_occupant(p_seat_id text, p_effective_date date, p_reason text, p_actor text) OWNER TO postgres;

--
-- Name: sync_area_state_for_seat(text, text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.sync_area_state_for_seat(p_seat_id text, p_from_state text, p_to_state text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare
  v_rows integer;
begin
  update au.line_area_map m
     set area_state = p_to_state
   where m.effective_to is null
     and m.rep_seat_id = p_seat_id
     and m.area_state = p_from_state
     and exists (
       select 1 from au.seats s
       where s.seat_id = p_seat_id and s.seat_tier = 'REP'
     );
  get diagnostics v_rows = row_count;
  return v_rows;
end $$;

ALTER FUNCTION au.sync_area_state_for_seat(p_seat_id text, p_from_state text, p_to_state text) OWNER TO postgres;

--
-- Name: FUNCTION sync_area_state_for_seat(p_seat_id text, p_from_state text, p_to_state text); Type: COMMENT; Schema: au; Owner: postgres
--

COMMENT ON FUNCTION au.sync_area_state_for_seat(p_seat_id text, p_from_state text, p_to_state text) IS 'Moves the OPEN au.line_area_map row whose rep_seat_id = p_seat_id from p_from_state to p_to_state, for REP seats only. Never touches other_permanent / other_line_specific (those rows have no rep seat, and their state matches no transition). Returns rows affected; 0 is a legitimate no-op.';

--
-- Name: transfer_occupant(text, text, text, date, text, text); Type: FUNCTION; Schema: au; Owner: postgres
--

CREATE FUNCTION au.transfer_occupant(p_hr_id text, p_from_seat text, p_to_seat text, p_effective_date date, p_reason text DEFAULT NULL::text, p_actor text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare v_new bigint;
begin
  perform au.resign_occupant(p_from_seat, p_effective_date, coalesce(p_reason,'transfer'), p_actor);
  update au.occupancy_history set event_type='transfer_out' where seat_id=p_from_seat and effective_to is null;
  v_new := au.hire_into_seat(p_to_seat, p_hr_id, p_effective_date, p_actor);
  update au.occupancy_history set event_type='transfer_in' where occupancy_id=v_new;
  return v_new;
end $$;

ALTER FUNCTION au.transfer_occupant(p_hr_id text, p_from_seat text, p_to_seat text, p_effective_date date, p_reason text, p_actor text) OWNER TO postgres;

--
-- Name: FUNCTION transfer_occupant(p_hr_id text, p_from_seat text, p_to_seat text, p_effective_date date, p_reason text, p_actor text); Type: COMMENT; Schema: au; Owner: postgres
--

COMMENT ON FUNCTION au.transfer_occupant(p_hr_id text, p_from_seat text, p_to_seat text, p_effective_date date, p_reason text, p_actor text) IS 'Moves an occupant between seats. Inherits area_state maintenance from au.resign_occupant (from-seat -> vacant_will_hire) and au.hire_into_seat (to-seat -> occupied); do not add a third copy of that UPDATE here.';

--
-- Name: log_sensitive_data_access(text, text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.log_sensitive_data_access(p_table_name text, p_row_ref text, p_action text DEFAULT 'select'::text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $$
begin
  insert into public.sensitive_data_access_audit (
    actor_auth_user_id,
    actor_hr_id,
    actor_role,
    action,
    table_name,
    row_ref,
    reason
  )
  values (
    (select auth.uid()),
    private.phx_current_hr_id(),
    private.phx_current_role(),
    coalesce(nullif(trim(p_action), ''), 'select'),
    coalesce(nullif(trim(p_table_name), ''), 'unknown'),
    nullif(trim(coalesce(p_row_ref, '')), ''),
    nullif(trim(coalesce(p_reason, '')), '')
  );
end;
$$;

ALTER FUNCTION private.log_sensitive_data_access(p_table_name text, p_row_ref text, p_action text, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION log_sensitive_data_access(p_table_name text, p_row_ref text, p_action text, p_reason text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.log_sensitive_data_access(p_table_name text, p_row_ref text, p_action text, p_reason text) IS 'Writes public.sensitive_data_access_audit. Functional but untravelled -- the table has never received a row. Its only caller is private.log_sensitive_data_access_event().';

--
-- Name: log_sensitive_data_access_event(text, text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.log_sensitive_data_access_event(p_table_name text, p_row_ref text, p_action text DEFAULT 'select'::text, p_reason text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $$
begin
  perform private.log_sensitive_data_access(p_table_name, p_row_ref, p_action, p_reason);
  return true;
end;
$$;

ALTER FUNCTION private.log_sensitive_data_access_event(p_table_name text, p_row_ref text, p_action text, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION log_sensitive_data_access_event(p_table_name text, p_row_ref text, p_action text, p_reason text); Type: COMMENT; Schema: private; Owner: postgres
--

COMMENT ON FUNCTION private.log_sensitive_data_access_event(p_table_name text, p_row_ref text, p_action text, p_reason text) IS 'Boolean wrapper over private.log_sensitive_data_access(), shaped to be called from a view WHERE clause. Its only caller is public.v_employee_locations_masked, which no application code selects. Always returns true; it is used for its side effect.';

--
-- Name: phx_approve_accepted_offer_v2(uuid, text, text, numeric, numeric, numeric, numeric, numeric, numeric, numeric, numeric, jsonb); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.phx_approve_accepted_offer_v2(p_offer_id uuid, p_approved_by_hr_id text DEFAULT NULL::text, p_employee_hr_id text DEFAULT NULL::text, p_gross_salary numeric DEFAULT NULL::numeric, p_fuel_allowance numeric DEFAULT NULL::numeric, p_extra_cost_of_living numeric DEFAULT NULL::numeric, p_base_salary numeric DEFAULT NULL::numeric, p_basic_salary numeric DEFAULT NULL::numeric, p_net_salary numeric DEFAULT NULL::numeric, p_social_insurance numeric DEFAULT NULL::numeric, p_taxes numeric DEFAULT NULL::numeric, p_compensation_lines jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $_$
declare
  v_offer public.job_offers%rowtype;
  v_employee_hr_id text;
  v_prefix text := 'PH';
  v_line_name text;
  v_line_code text;
  v_candidate integer;
  v_attempt integer := 0;
  v_matching_vacancy_id bigint;
  v_base_salary numeric;
  v_basic_salary numeric;
  v_gross_salary numeric;
  v_net_salary numeric;
  v_fuel_allowance numeric;
  v_extra_cost_of_living numeric;
  v_social_insurance numeric;
  v_taxes numeric;
  v_legacy_match_count integer := 0;
  v_compensation_lines jsonb := '[]'::jsonb;
  v_custom_earnings numeric := 0;
  v_custom_deductions numeric := 0;
begin
  perform pg_advisory_xact_lock(hashtext('phx_offer_hire_approval'));

  select *
    into v_offer
  from public.job_offers
  where id = p_offer_id
  for update;

  if not found then
    raise exception 'Offer not found.';
  end if;

  if v_offer.status = 'hired' and nullif(trim(coalesce(v_offer.employee_hr_id, '')), '') is not null then
    return jsonb_build_object(
      'already_hired', true,
      'employee_hr_id', v_offer.employee_hr_id,
      'offer_id', v_offer.id,
      'vacancy_id', v_offer.vacancy_id
    );
  end if;

  if v_offer.status <> 'accepted' then
    raise exception 'Only accepted offers can be approved.';
  end if;

  if coalesce(trim(v_offer.candidate_name), '') = '' then
    raise exception 'Cannot approve offer without candidate name.';
  end if;

  if coalesce(trim(v_offer.candidate_email), '') = '' then
    raise exception 'Cannot approve offer without candidate email.';
  end if;

  if v_offer.start_date is null then
    raise exception 'Cannot approve offer without hiring date.';
  end if;

  if v_offer.department_id is null then
    raise exception 'Cannot approve offer without department assignment.';
  end if;

  if v_offer.position_id is null then
    raise exception 'Cannot approve offer without position assignment.';
  end if;

  if v_offer.line_id is null then
    raise exception 'Cannot approve offer without line assignment.';
  end if;

  if v_offer.area_id is null then
    raise exception 'Cannot approve offer without area assignment.';
  end if;

  if coalesce(trim(v_offer.manager_hr_id), '') = '' then
    raise exception 'Cannot approve offer without manager HR ID.';
  end if;

  with normalized as (
    select
      coalesce(nullif(trim(line ->> 'id'), ''), 'offer-line-' || row_number() over ()) as id,
      case when lower(coalesce(line ->> 'category', 'earning')) = 'deduction' then 'deduction' else 'earning' end as category,
      left(trim(coalesce(line ->> 'label', '')), 120) as label,
      nullif(trim(coalesce(line ->> 'notes', '')), '') as notes,
      case
        when coalesce(line ->> 'value', '') ~ '^[0-9]+(\.[0-9]+)?$'
          then round(((line ->> 'value')::numeric), 2)
        else null
      end as amount
    from jsonb_array_elements(coalesce(p_compensation_lines, v_offer.compensation_lines, '[]'::jsonb)) as source(line)
  ),
  valid as (
    select *
    from normalized
    where amount is not null
      and amount > 0
      and label <> ''
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', id,
      'label', label,
      'category', category,
      'valueType', 'amount',
      'value', amount::text,
      'notes', notes
    ) order by id), '[]'::jsonb),
    coalesce(sum(case when category = 'earning' then amount else 0 end), 0),
    coalesce(sum(case when category = 'deduction' then amount else 0 end), 0)
  into v_compensation_lines, v_custom_earnings, v_custom_deductions
  from valid;

  v_base_salary := coalesce(p_base_salary, v_offer.base_salary);
  v_basic_salary := coalesce(p_basic_salary, v_offer.basic_salary, round(coalesce(v_base_salary, 0) * 0.7, 2));
  v_fuel_allowance := coalesce(p_fuel_allowance, v_offer.fuel_allowance, 0);
  v_extra_cost_of_living := coalesce(p_extra_cost_of_living, v_offer.extra_cost_of_living, 0);
  v_social_insurance := coalesce(p_social_insurance, v_offer.social_insurance, 0);
  v_taxes := coalesce(p_taxes, v_offer.taxes, 0);
  v_gross_salary := coalesce(p_gross_salary, v_offer.gross_salary, coalesce(v_base_salary, 0) + v_social_insurance + v_taxes);
  v_net_salary := greatest(0, coalesce(v_base_salary, 0) + v_extra_cost_of_living + v_fuel_allowance + v_custom_earnings - v_custom_deductions);

  if coalesce(v_base_salary, 0) <= 0 then
    raise exception 'Cannot approve offer without base salary.';
  end if;

  if v_offer.vacancy_id is not null then
    select pv.id
      into v_matching_vacancy_id
    from public.position_vacancies pv
    where pv.id = v_offer.vacancy_id
      and pv.status = 'open'
      and pv.department_id = v_offer.department_id
      and pv.position_id = v_offer.position_id
      and pv.line_id = v_offer.line_id
      and pv.area_id = v_offer.area_id
    limit 1
    for update;

    if v_matching_vacancy_id is null then
      raise exception 'Selected vacancy is no longer open or no longer matches this offer.';
    end if;
  else
    select count(*), max(pv.id)
      into v_legacy_match_count, v_matching_vacancy_id
    from public.position_vacancies pv
    where pv.status = 'open'
      and pv.department_id = v_offer.department_id
      and pv.position_id = v_offer.position_id
      and pv.line_id = v_offer.line_id
      and pv.area_id = v_offer.area_id
      and (
        pv.manager_hr_id = v_offer.manager_hr_id
        or pv.manager_hr_id is null
      );

    if v_legacy_match_count > 1 then
      raise exception 'Ambiguous vacancy match. Select an explicit vacancy before approving this offer.';
    end if;
  end if;

  v_employee_hr_id := nullif(trim(coalesce(p_employee_hr_id, v_offer.reserved_employee_hr_id, v_offer.employee_hr_id, '')), '');

  if v_employee_hr_id is null then
    select coalesce(name, ''), coalesce(code, '')
      into v_line_name, v_line_code
    from public.lines
    where id = v_offer.line_id;

    if position('anti' in lower(v_line_name || ' ' || v_line_code)) > 0 then
      v_prefix := 'AI';
    elsif position('pedia' in lower(v_line_name || ' ' || v_line_code)) > 0 then
      v_prefix := 'PD';
    elsif position('cns' in lower(v_line_name || ' ' || v_line_code)) > 0 then
      v_prefix := 'CN';
    elsif position('office' in lower(v_line_name || ' ' || v_line_code)) > 0 then
      v_prefix := 'OF';
    end if;

    loop
      v_attempt := v_attempt + 1;
      if v_attempt > 10 then
        raise exception 'Failed to generate a unique HR_ID for prefix %.', v_prefix;
      end if;

      select coalesce(max(candidate), 0) + 1
        into v_candidate
      from (
        select nullif(substring(upper(hr_id) from ('^' || v_prefix || '-([0-9]+)$')), '')::integer as candidate
        from public.employees
        where upper(hr_id) like v_prefix || '-%'
        union all
        select nullif(substring(upper(reserved_employee_hr_id) from ('^' || v_prefix || '-([0-9]+)$')), '')::integer as candidate
        from public.job_offers
        where reserved_employee_hr_id is not null
          and upper(reserved_employee_hr_id) like v_prefix || '-%'
      ) ids
      where candidate is not null;

      v_employee_hr_id := v_prefix || '-' || lpad(v_candidate::text, 4, '0');

      begin
        insert into public.employees (
          hr_id, full_name, work_email, mobile_number, job_title, hire_date,
          employment_status, manager_hr_id, department_id, line_id, area_id,
          position_id, base_salary, basic_salary, gross_salary, net_salary,
          fuel_allowance, extra_cost_of_living, social_insurance, taxes,
          payment_mode, created_at, updated_at
        ) values (
          v_employee_hr_id, v_offer.candidate_name, v_offer.candidate_email,
          v_offer.candidate_phone, v_offer.job_title, v_offer.start_date,
          'active', v_offer.manager_hr_id, v_offer.department_id, v_offer.line_id,
          v_offer.area_id, v_offer.position_id, v_base_salary, v_basic_salary,
          v_gross_salary, v_net_salary, v_fuel_allowance, v_extra_cost_of_living,
          v_social_insurance, v_taxes, 'two_parts', now(), now()
        );
        exit;
      exception
        when unique_violation then
          v_employee_hr_id := null;
      end;
    end loop;
  else
    if exists (
      select 1
      from public.employees
      where hr_id = v_employee_hr_id
        and hr_id <> coalesce(v_offer.employee_hr_id, '')
    ) then
      raise exception 'HR_ID % is already in use.', v_employee_hr_id;
    end if;

    insert into public.employees (
      hr_id, full_name, work_email, mobile_number, job_title, hire_date,
      employment_status, manager_hr_id, department_id, line_id, area_id,
      position_id, base_salary, basic_salary, gross_salary, net_salary,
      fuel_allowance, extra_cost_of_living, social_insurance, taxes,
      payment_mode, created_at, updated_at
    ) values (
      v_employee_hr_id, v_offer.candidate_name, v_offer.candidate_email,
      v_offer.candidate_phone, v_offer.job_title, v_offer.start_date,
      'active', v_offer.manager_hr_id, v_offer.department_id, v_offer.line_id,
      v_offer.area_id, v_offer.position_id, v_base_salary, v_basic_salary,
      v_gross_salary, v_net_salary, v_fuel_allowance, v_extra_cost_of_living,
      v_social_insurance, v_taxes, 'two_parts', now(), now()
    )
    on conflict (hr_id) do update
    set
      full_name = excluded.full_name,
      work_email = excluded.work_email,
      mobile_number = excluded.mobile_number,
      job_title = excluded.job_title,
      hire_date = excluded.hire_date,
      employment_status = excluded.employment_status,
      manager_hr_id = excluded.manager_hr_id,
      department_id = excluded.department_id,
      line_id = excluded.line_id,
      area_id = excluded.area_id,
      position_id = excluded.position_id,
      base_salary = excluded.base_salary,
      basic_salary = excluded.basic_salary,
      gross_salary = excluded.gross_salary,
      net_salary = excluded.net_salary,
      fuel_allowance = excluded.fuel_allowance,
      extra_cost_of_living = excluded.extra_cost_of_living,
      social_insurance = excluded.social_insurance,
      taxes = excluded.taxes,
      payment_mode = excluded.payment_mode,
      updated_at = now();
  end if;

  insert into public.employee_compensation (
    employee_hr_id, net_salary, comprehensive_wage, fuel_allowance,
    extra_cost_of_living, gross_salary, social_insurance, taxes,
    salary_details, payment_mode, updated_at
  ) values (
    v_employee_hr_id, v_net_salary, v_base_salary, v_fuel_allowance,
    v_extra_cost_of_living, v_gross_salary, v_social_insurance, v_taxes,
    v_compensation_lines, 'two_parts', now()
  )
  on conflict (employee_hr_id) do update
  set
    net_salary = excluded.net_salary,
    comprehensive_wage = excluded.comprehensive_wage,
    fuel_allowance = excluded.fuel_allowance,
    extra_cost_of_living = excluded.extra_cost_of_living,
    gross_salary = excluded.gross_salary,
    social_insurance = excluded.social_insurance,
    taxes = excluded.taxes,
    salary_details = excluded.salary_details,
    payment_mode = excluded.payment_mode,
    updated_at = now();

  if v_matching_vacancy_id is not null then
    update public.position_vacancies
    set status = 'filled',
        filled_by_hr_id = v_employee_hr_id,
        filled_at = now(),
        replacement_for_hr_id = null,
        note = 'Auto-closed by atomic offer approval for ' || v_employee_hr_id || '.',
        updated_at = now()
    where id = v_matching_vacancy_id;
  end if;

  update public.job_offers
  set employee_hr_id = v_employee_hr_id,
      reserved_employee_hr_id = v_employee_hr_id,
      onboarding_status = 'approved_hired',
      status = 'hired',
      base_salary = v_base_salary,
      basic_salary = v_basic_salary,
      gross_salary = v_gross_salary,
      net_salary = v_net_salary,
      salary_amount = v_net_salary,
      fuel_allowance = v_fuel_allowance,
      extra_cost_of_living = v_extra_cost_of_living,
      social_insurance = v_social_insurance,
      taxes = v_taxes,
      compensation_lines = v_compensation_lines,
      accepted_terms_snapshot = coalesce(
        accepted_terms_snapshot,
        jsonb_build_object(
          'candidateName', v_offer.candidate_name,
          'candidateEmail', v_offer.candidate_email,
          'jobTitle', v_offer.job_title,
          'startDate', v_offer.start_date,
          'departmentId', v_offer.department_id,
          'positionId', v_offer.position_id,
          'lineId', v_offer.line_id,
          'areaId', v_offer.area_id,
          'vacancyId', coalesce(v_offer.vacancy_id, v_matching_vacancy_id),
          'baseSalary', v_base_salary,
          'basicSalary', v_basic_salary,
          'grossSalary', v_gross_salary,
          'netSalary', v_net_salary,
          'fuelAllowance', v_fuel_allowance,
          'extraCostOfLiving', v_extra_cost_of_living,
          'socialInsurance', v_social_insurance,
          'taxes', v_taxes,
          'compensationLines', v_compensation_lines,
          'acceptedAt', v_offer.accepted_at,
          'approvedAt', now()
        )
      ),
      approval_repair_status = 'pending_post_approval',
      approval_repair_error = null,
      updated_at = now()
  where id = v_offer.id;

  insert into public.job_offer_audit_logs (
    offer_id, action, actor_type, actor_reference, details
  ) values (
    v_offer.id,
    'hire_approved',
    'hr',
    p_approved_by_hr_id,
    jsonb_build_object(
      'employeeHrId', v_employee_hr_id,
      'vacancyId', v_matching_vacancy_id,
      'status', 'hired',
      'customEarnings', v_custom_earnings,
      'customDeductions', v_custom_deductions,
      'atomic', true
    )
  );

  return jsonb_build_object(
    'already_hired', false,
    'employee_hr_id', v_employee_hr_id,
    'offer_id', v_offer.id,
    'vacancy_id', v_matching_vacancy_id
  );
end;
$_$;

ALTER FUNCTION private.phx_approve_accepted_offer_v2(p_offer_id uuid, p_approved_by_hr_id text, p_employee_hr_id text, p_gross_salary numeric, p_fuel_allowance numeric, p_extra_cost_of_living numeric, p_base_salary numeric, p_basic_salary numeric, p_net_salary numeric, p_social_insurance numeric, p_taxes numeric, p_compensation_lines jsonb) OWNER TO postgres;

--
-- Name: phx_assert_executive_dashboard_viewer(text, text, text, text, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.phx_assert_executive_dashboard_viewer(p_viewer_hr_id text, p_viewer_login_id text, p_viewer_role text, p_viewer_scope text, p_viewer_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $$
declare
  v_role text := nullif(trim(coalesce(p_viewer_role, '')), '');
  v_scope text := lower(nullif(trim(coalesce(p_viewer_scope, '')), ''));
  v_source text := lower(nullif(trim(coalesce(p_viewer_source, '')), ''));
  v_login_id text := lower(nullif(trim(coalesce(p_viewer_login_id, '')), ''));
  v_hr_id text := lower(nullif(trim(coalesce(p_viewer_hr_id, '')), ''));
  v_found boolean := false;
begin
  if v_source = 'system' or v_scope = 'system' then
    return jsonb_build_object(
      'role', coalesce(v_role, 'system'),
      'scope', 'system',
      'source', coalesce(v_source, 'system')
    );
  end if;

  if v_role not in ('CEO', 'Super Admin') or v_scope <> 'company' then
    raise exception 'Executive dashboard snapshot is restricted to CEO, Super Admin, or system scope.';
  end if;

  if v_login_id is not null and to_regclass('public.app_auth_users') is not null then
    select exists (
      select 1
      from public.app_auth_users a
      where lower(trim(a.login_id)) = v_login_id
        and coalesce(a.is_active, true) = true
        and a.role = v_role
    ) into v_found;
  end if;

  if not v_found and v_hr_id is not null and to_regclass('public.app_auth_users') is not null then
    select exists (
      select 1
      from public.app_auth_users a
      where lower(trim(a.hr_id)) = v_hr_id
        and coalesce(a.is_active, true) = true
        and a.role = v_role
    ) into v_found;
  end if;

  if not v_found and v_login_id is not null and to_regclass('public.user_access_profiles') is not null then
    select exists (
      select 1
      from public.user_access_profiles u
      where lower(trim(u.login_id)) = v_login_id
        and coalesce(u.is_active, true) = true
        and coalesce(u.phoenix_role, u.role) = v_role
    ) into v_found;
  end if;

  if not v_found and v_hr_id is not null and to_regclass('public.user_access_profiles') is not null then
    select exists (
      select 1
      from public.user_access_profiles u
      where lower(trim(u.hr_id)) = v_hr_id
        and coalesce(u.is_active, true) = true
        and coalesce(u.phoenix_role, u.role) = v_role
    ) into v_found;
  end if;

  if not v_found then
    raise exception 'Executive dashboard viewer could not be validated.';
  end if;

  return jsonb_build_object(
    'role', v_role,
    'scope', v_scope,
    'source', coalesce(v_source, 'session')
  );
end;
$$;

ALTER FUNCTION private.phx_assert_executive_dashboard_viewer(p_viewer_hr_id text, p_viewer_login_id text, p_viewer_role text, p_viewer_scope text, p_viewer_source text) OWNER TO postgres;

--
-- Name: phx_can_access_employee(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.phx_can_access_employee(target_hr_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with actor as (
    select e.hr_id, e.line_id, e.department_id
    from public.employees e
    where lower(e.hr_id) = lower(coalesce(private.phx_current_hr_id(), ''))
    limit 1
  ),
  target as (
    select e.hr_id, e.manager_hr_id, e.line_id, e.department_id, e.employment_status
    from public.employees e
    where lower(e.hr_id) = lower(coalesce(target_hr_id, ''))
    limit 1
  ),
  access_base as (
    select
      private.phx_has_company_access()
      or lower(coalesce(target_hr_id, '')) = lower(coalesce(private.phx_current_hr_id(), ''))
      or exists (
        select 1
        from target
        where private.phx_current_scope() in ('TEAM', 'HIERARCHY')
          and lower(coalesce(target.manager_hr_id, '')) = lower(coalesce(private.phx_current_hr_id(), ''))
      )
      or exists (
        select 1
        from actor
        join target on true
        where private.phx_current_scope() in ('LINE', 'HIERARCHY')
          and actor.line_id is not null
          and actor.line_id = target.line_id
      )
      or exists (
        select 1
        from actor
        join target on true
        where private.phx_current_scope() in ('DEPARTMENT', 'SUPER_ADMIN')
          and actor.department_id is not null
          and actor.department_id = target.department_id
      ) as can_access
  )
  select coalesce(can_access, false)
    and (
      not exists (
        select 1
        from target
        where lower(coalesce(target.employment_status, 'active')) in ('resigned', 'terminated', 'inactive', 'left')
      )
      or private.phx_has_company_access()
    )
  from access_base;
$$;

ALTER FUNCTION private.phx_can_access_employee(target_hr_id text) OWNER TO postgres;

--
-- Name: phx_can_access_line(text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.phx_can_access_line(target_line text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with actor as (
    select e.line_id, l.name as line_name
    from public.employees e
    left join public.lines l on l.id = e.line_id
    where lower(e.hr_id) = lower(coalesce(private.phx_current_hr_id(), ''))
    limit 1
  )
  select
    private.phx_has_company_access()
    or (
      target_line is not null
      and private.phx_current_scope() in ('LINE', 'HIERARCHY', 'TEAM')
      and exists (
        select 1
        from actor
        where lower(coalesce(actor.line_name, '')) = lower(coalesce(target_line, ''))
      )
    );
$$;

ALTER FUNCTION private.phx_can_access_line(target_line text) OWNER TO postgres;

