CREATE FUNCTION private.phx_resigned_hr_ids() RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select lower(e.hr_id)
  from public.employees e
  where lower(coalesce(e.employment_status, 'active')) in ('resigned','terminated','inactive','left');
$$;

ALTER FUNCTION private.phx_resigned_hr_ids() OWNER TO postgres;

--
-- Name: phx_visible_hr_ids(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.phx_visible_hr_ids() RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with me as (
    select lower(coalesce(private.phx_current_hr_id(), '')) as hr,
           private.phx_current_scope() as scope
  ),
  actor_row as (
    select e.line_id, e.department_id
    from public.employees e, me
    where me.hr <> '' and lower(e.hr_id) = me.hr
    limit 1
  )
  select lower(e.hr_id)
  from public.employees e, me
  where me.hr <> ''
    and (
      (me.scope in ('TEAM','HIERARCHY') and lower(coalesce(e.manager_hr_id, '')) = me.hr)
      or (me.scope in ('LINE','HIERARCHY') and e.line_id is not null
          and e.line_id = (select line_id from actor_row))
      or (me.scope in ('DEPARTMENT','SUPER_ADMIN') and e.department_id is not null
          and e.department_id = (select department_id from actor_row))
    );
$$;

ALTER FUNCTION private.phx_visible_hr_ids() OWNER TO postgres;

--
-- Name: accept_offer_and_create_employee(uuid, text, date, date, date, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.accept_offer_and_create_employee(p_offer_id uuid, p_hr_id text, p_hire_date date DEFAULT NULL::date, p_birth_date date DEFAULT NULL::date, p_contract_start_date date DEFAULT NULL::date, p_contract_renewal_date date DEFAULT NULL::date, p_probation_end_date date DEFAULT NULL::date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  o record;
  v_hire_date date;
  v_hr_id text;
begin
  select * into o
  from public.job_offers
  where id = p_offer_id;

  if not found then
    raise exception 'Offer % not found', p_offer_id;
  end if;

  if o.status not in ('sent','accepted') then
    raise exception 'Offer % is not in a valid status for acceptance. Current status: %', p_offer_id, o.status;
  end if;

  v_hr_id := trim(p_hr_id);
  if v_hr_id is null or v_hr_id = '' then
    raise exception 'HR_ID is required';
  end if;

  if exists (select 1 from public.employees where hr_id = v_hr_id)
     and coalesce(o.employee_hr_id, '') <> v_hr_id then
    raise exception 'HR_ID % already exists in employees', v_hr_id;
  end if;

  v_hire_date := coalesce(p_hire_date, o.start_date, (now() at time zone 'Africa/Cairo')::date);

  insert into public.employees (
    hr_id,
    full_name,
    work_email,
    mobile_number,
    job_title,
    hire_date,
    employment_status,
    manager_hr_id,
    department_id,
    line_id,
    area_id,
    position_id,
    birth_date,
    contract_start_date,
    contract_renewal_date,
    probation_end_date,
    onboarding_source,
    onboarding_status,
    payroll_eligible,
    organogram_visible,
    created_at,
    updated_at
  )
  values (
    v_hr_id,
    o.candidate_name,
    o.candidate_email,
    o.candidate_phone,
    o.job_title,
    v_hire_date,
    'active',
    o.manager_hr_id,
    o.department_id,
    o.line_id,
    o.area_id,
    o.position_id,
    p_birth_date,
    coalesce(p_contract_start_date, v_hire_date),
    p_contract_renewal_date,
    p_probation_end_date,
    'job_offer',
    'active',
    true,
    true,
    now(),
    now()
  )
  on conflict (hr_id) do update
  set
    full_name = excluded.full_name,
    work_email = excluded.work_email,
    mobile_number = excluded.mobile_number,
    job_title = excluded.job_title,
    hire_date = excluded.hire_date,
    employment_status = 'active',
    manager_hr_id = excluded.manager_hr_id,
    department_id = excluded.department_id,
    line_id = excluded.line_id,
    area_id = excluded.area_id,
    position_id = excluded.position_id,
    birth_date = coalesce(excluded.birth_date, public.employees.birth_date),
    contract_start_date = coalesce(excluded.contract_start_date, public.employees.contract_start_date),
    contract_renewal_date = coalesce(excluded.contract_renewal_date, public.employees.contract_renewal_date),
    probation_end_date = coalesce(excluded.probation_end_date, public.employees.probation_end_date),
    onboarding_source = 'job_offer',
    onboarding_status = 'active',
    payroll_eligible = true,
    organogram_visible = true,
    updated_at = now();

  insert into public.employee_compensation (
    employee_hr_id,
    gross_salary,
    net_salary,
    created_at,
    updated_at
  )
  values (
    v_hr_id,
    o.salary_amount,
    o.salary_amount,
    now(),
    now()
  )
  on conflict (employee_hr_id) do update
  set
    gross_salary = coalesce(excluded.gross_salary, public.employee_compensation.gross_salary),
    net_salary = coalesce(excluded.net_salary, public.employee_compensation.net_salary),
    updated_at = now();

  insert into public.employee_history (
    employee_hr_id,
    event_type,
    effective_from,
    department_id,
    line_id,
    area_id,
    position_id,
    note,
    created_at
  )
  values (
    v_hr_id,
    'hired_from_offer',
    v_hire_date,
    o.department_id,
    o.line_id,
    o.area_id,
    o.position_id,
    'Created from accepted job offer ' || coalesce(o.offer_code, o.id::text),
    now()
  );

  update public.job_offers
  set
    status = 'accepted',
    accepted_at = coalesce(accepted_at, now()),
    employee_hr_id = v_hr_id,
    onboarding_status = 'employee_created',
    updated_at = now()
  where id = p_offer_id;

  insert into public.job_offer_audit_logs (offer_id, action, actor_type, actor_reference, details, created_at)
  values (
    p_offer_id,
    'employee_created',
    'system',
    v_hr_id,
    jsonb_build_object('hr_id', v_hr_id, 'hire_date', v_hire_date),
    now()
  );

  perform public.generate_employee_lifecycle_notifications(v_hr_id);

  return v_hr_id;
end;
$$;

ALTER FUNCTION public.accept_offer_and_create_employee(p_offer_id uuid, p_hr_id text, p_hire_date date, p_birth_date date, p_contract_start_date date, p_contract_renewal_date date, p_probation_end_date date) OWNER TO postgres;

--
-- Name: coaching_report_number_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.coaching_report_number_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.coaching_report_number_seq OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: coaching_reports; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.coaching_reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_number text DEFAULT ((('CR-'::text || to_char(now(), 'YYYY'::text)) || '-'::text) || lpad((nextval('public.coaching_report_number_seq'::regclass))::text, 6, '0'::text)) NOT NULL,
    medical_rep_hr_id text NOT NULL,
    coach_hr_id text NOT NULL,
    coach_role text,
    line_id bigint,
    area_id bigint,
    team_id bigint,
    coaching_date date NOT NULL,
    coaching_month integer GENERATED ALWAYS AS ((EXTRACT(month FROM coaching_date))::integer) STORED,
    coaching_quarter integer GENERATED ALWAYS AS ((EXTRACT(quarter FROM coaching_date))::integer) STORED,
    coaching_year integer GENERATED ALWAYS AS ((EXTRACT(year FROM coaching_date))::integer) STORED,
    status text DEFAULT 'draft'::text NOT NULL,
    actual_score numeric(10,2) DEFAULT 0 NOT NULL,
    max_score numeric(10,2) DEFAULT 100 NOT NULL,
    final_score_percent numeric(6,2) DEFAULT 0 NOT NULL,
    performance_zone text,
    area_of_development text,
    strength_points text,
    general_remarks text,
    employee_acknowledged boolean DEFAULT false NOT NULL,
    acknowledged_at timestamp with time zone,
    submitted_at timestamp with time zone,
    locked_at timestamp with time zone,
    created_by text,
    updated_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT coaching_reports_percent_bounds_check CHECK (((final_score_percent >= (0)::numeric) AND (final_score_percent <= (100)::numeric))),
    CONSTRAINT coaching_reports_score_bounds_check CHECK (((actual_score >= (0)::numeric) AND (max_score > (0)::numeric) AND (actual_score <= max_score))),
    CONSTRAINT coaching_reports_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'reviewed_by_employee'::text, 'locked'::text, 'cancelled'::text]))),
    CONSTRAINT coaching_reports_zone_check CHECK (((performance_zone IS NULL) OR (performance_zone = ANY (ARRAY['critical_red'::text, 'red_zone'::text, 'yellow_zone'::text, 'green_zone'::text, 'excellence_zone'::text]))))
);

