--

CREATE FUNCTION public.ats_bulk_set_candidate_status(p_candidate_ids uuid[], p_status text, p_note text, p_actor_hr_id text) RETURNS TABLE(candidate_id uuid, from_status text, to_status text)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_now timestamptz := now();
  v_count integer := coalesce(cardinality(p_candidate_ids), 0);
begin
  if v_count = 0 then
    return;
  end if;

  if v_count > 200 then
    raise exception 'A bulk decision is capped at 200 candidates; this call passed %.', v_count
      using errcode = 'check_violation';
  end if;

  if p_status is null or btrim(p_status) = '' then
    raise exception 'A bulk decision needs a status.' using errcode = 'check_violation';
  end if;

  return query
  with before as (
    select c.id, c.status as from_status
    from public.ats_candidates c
    where c.id = any(p_candidate_ids)
  ),
  moved as (
    update public.ats_candidates c
    set status = p_status,
        status_changed_at = v_now,
        status_changed_by_hr_id = p_actor_hr_id,
        status_note = p_note,
        updated_at = v_now
    from before b
    where c.id = b.id
    returning c.id
  ),
  logged as (
    insert into public.ats_candidate_status_events
      (candidate_id, from_status, to_status, note, actor_hr_id)
    select b.id, b.from_status, p_status, p_note, p_actor_hr_id
    from before b
    join moved m on m.id = b.id
    returning public.ats_candidate_status_events.candidate_id
  )
  select b.id, b.from_status, p_status
  from before b
  join logged l on l.candidate_id = b.id;
end;
$$;

ALTER FUNCTION public.ats_bulk_set_candidate_status(p_candidate_ids uuid[], p_status text, p_note text, p_actor_hr_id text) OWNER TO postgres;

--
-- Name: FUNCTION ats_bulk_set_candidate_status(p_candidate_ids uuid[], p_status text, p_note text, p_actor_hr_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ats_bulk_set_candidate_status(p_candidate_ids uuid[], p_status text, p_note text, p_actor_hr_id text) IS 'One screening decision across many candidates, atomically: moves each candidate and writes its status-history row in the same transaction, returning one row per candidate actually moved with the status it came from. Capped at 200 per call as a blast-radius limit. Does not validate the status vocabulary (TypeScript is the single authority) and runs as its caller rather than as the table owner. EXECUTE is service_role only. Added 2026-09-05 to make clearing a 238-CV backlog one press instead of 238.';

--
-- Name: ats_candidates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    full_name text NOT NULL,
    national_id text,
    national_id_norm text,
    email text,
    email_norm text,
    phone text,
    phone_norm text,
    governorate text,
    current_employer text,
    years_experience numeric,
    expected_salary numeric,
    notice_period text,
    source text,
    cv_reference_name text,
    cv_external_url text,
    notes text,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'new'::text NOT NULL,
    address text,
    faculty text,
    university text,
    has_prior_work_experience boolean,
    has_medical_rep_experience boolean,
    medical_rep_employer text,
    medical_rep_experience_from date,
    medical_rep_experience_to date,
    position_specific_fields jsonb,
    whatsapp text,
    linkedin_url text,
    nationality text,
    date_of_birth date,
    place_of_birth text,
    gender text,
    marital_status text,
    military_status text,
    current_job_title text,
    professional_summary text,
    current_role_responsibilities text,
    degree text,
    graduation_year integer,
    grade text,
    manager_notified_hr_id text,
    manager_notified_name text,
    manager_notified_at timestamp with time zone,
    applied_for_job_title text,
    applied_for_evidence text,
    status_note text,
    status_changed_at timestamp with time zone,
    status_changed_by_hr_id text,
    manager_notified_job_title text,
    manager_notified_area text,
    manager_notified_region text,
    preferred_region_code text,
    preferred_area_name text,
    preferences_declared_at timestamp with time zone,
    sent_for_vacancy_id bigint,
    sent_for_job_title text,
    sent_for_area text,
    sent_for_line text,
    sent_for_region text,
    preferred_region_name text,
    folder_kind text,
    folder_key text,
    folder_filed_at timestamp with time zone,
    folder_filed_by_hr_id text,
    declared_background text,
    declared_experience text,
    screening_extra_answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    background_confirmed_outcome text,
    background_confirmed_at timestamp with time zone,
    background_confirmed_by_hr_id text,
    declared_expected_salary text,
    rating smallint,
    rated_by_hr_id text,
    rated_at timestamp with time zone,
    offer_id uuid,
    declared_role_family text,
    answer_marks jsonb DEFAULT '{}'::jsonb NOT NULL,
    rejection_reason text,
    rejection_reason_note text,
    archived_at timestamp with time zone,
    archived_by text,
    answers_expected smallint,
    answers_given smallint,
    missing_answer_keys text[],
    followup_sent_at timestamp with time zone,
    followup_sent_by text,
    CONSTRAINT ats_candidates_answer_marks_is_object CHECK ((jsonb_typeof(answer_marks) = 'object'::text)),
    CONSTRAINT ats_candidates_background_confirmation_complete CHECK ((((background_confirmed_outcome IS NULL) AND (background_confirmed_at IS NULL)) OR ((background_confirmed_outcome IS NOT NULL) AND (background_confirmed_at IS NOT NULL)))),
    CONSTRAINT ats_candidates_background_confirmed_outcome_known CHECK (((background_confirmed_outcome IS NULL) OR (background_confirmed_outcome = ANY (ARRAY['eligible'::text, 'paramedical'::text])))),
    CONSTRAINT ats_candidates_folder_complete CHECK ((((folder_kind IS NULL) AND (folder_key IS NULL) AND (folder_filed_at IS NULL)) OR ((folder_kind IS NOT NULL) AND (folder_key IS NOT NULL) AND (folder_filed_at IS NOT NULL)))),
    CONSTRAINT ats_candidates_folder_kind_known CHECK (((folder_kind IS NULL) OR (folder_kind = ANY (ARRAY['medical_rep'::text, 'district_manager'::text, 'other'::text, 'paramedical'::text, 'duplicate'::text])))),
    CONSTRAINT ats_candidates_rating_range CHECK (((rating IS NULL) OR ((rating >= 1) AND (rating <= 3)))),
    CONSTRAINT ats_candidates_rejection_reason_check CHECK (((rejection_reason IS NULL) OR (rejection_reason = ANY (ARRAY['wrong_degree'::text, 'outside_area'::text, 'salary_too_high'::text, 'not_enough_experience'::text, 'no_answer_to_calls'::text, 'no_longer_interested'::text, 'failed_interview'::text, 'duplicate_cv'::text, 'other'::text]))))
);

ALTER TABLE public.ats_candidates OWNER TO postgres;

--
-- Name: COLUMN ats_candidates.expected_salary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.expected_salary IS 'The expected monthly salary the applicant stated themselves over WhatsApp, verbatim as typed (a number, a range, "negotiable", or Arabic numerals). Never coerced to a number. Written only by the WhatsApp self-classification flow. Null means nobody asked them or they never answered.';

--
-- Name: COLUMN ats_candidates.medical_rep_employer; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.medical_rep_employer IS 'Company where the candidate worked as a Medical Rep / in medical sales promotion, distinct from current_employer (which may be a different, non-medical job).';

--
-- Name: COLUMN ats_candidates.position_specific_fields; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.position_specific_fields IS 'Repeating CV blocks keyed by the array field keys in src/lib/recruitment/cv-field-schemas.ts: workHistory, educationHistory, certifications, skills, languages. Each holds an array of objects shaped by that field''s itemFields. Scalars live in dedicated columns, not here.';

--
-- Name: COLUMN ats_candidates.nationality; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.nationality IS 'Nationality exactly as stated on the CV. Never inferred from name, university or phone country code. Backs the Egyptian-nationals-only hiring rule, which is why this is a filterable column rather than jsonb.';

--
-- Name: COLUMN ats_candidates.current_job_title; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.current_job_title IS 'The CANDIDATE''S OWN current/most recent job title from their CV — not the vacancy applied for. This field is what makes extraction job-title-agnostic: the title is now read from the CV instead of chosen as a template beforehand.';

--
-- Name: COLUMN ats_candidates.manager_notified_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.manager_notified_hr_id IS 'HR_ID of the manager this candidate was last pushed to directly (no requisition involved). Null = never pushed.';

--
-- Name: COLUMN ats_candidates.manager_notified_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.manager_notified_name IS 'The manager''s display name AS AT the moment of the send -- deliberately denormalised so history reads as what the recruiter saw.';

--
-- Name: COLUMN ats_candidates.manager_notified_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.manager_notified_at IS 'When the last direct push to a manager succeeded. Written only after delivery, never before.';

--
-- Name: COLUMN ats_candidates.applied_for_job_title; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.applied_for_job_title IS 'The vacancy this person is applying FOR, as they named it. Distinct from current_job_title, which is the job they already hold. Null = they never said.';

--
-- Name: COLUMN ats_candidates.applied_for_evidence; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.applied_for_evidence IS 'The verbatim wording the applied-for title was read from -- an email subject, a line of the covering note, or a sentence of the CV. Shown next to the title so a recruiter can overrule it.';

--
-- Name: COLUMN ats_candidates.status_note; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.status_note IS 'Free-text reason for the CURRENT status, typed by Talent Acquisition (e.g. "not an Egyptian national"). Overwritten by the next decision -- the durable history is ats_candidate_status_events.';

--
-- Name: COLUMN ats_candidates.status_changed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.status_changed_at IS 'When the status last changed. Null means it has never been changed from the default since this column existed.';

--
-- Name: COLUMN ats_candidates.status_changed_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.status_changed_by_hr_id IS 'HR_ID of whoever last changed the status. Null means "not recorded", never "system".';

--
-- Name: COLUMN ats_candidates.manager_notified_job_title; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.manager_notified_job_title IS 'The job title the notified manager held AT THE MOMENT OF THE SEND. Frozen on purpose — a later promotion must not rewrite what the recruiter saw.';

--
-- Name: COLUMN ats_candidates.manager_notified_area; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.manager_notified_area IS 'The area the notified manager owned at the moment of the send. Frozen for the same reason.';

--
-- Name: COLUMN ats_candidates.manager_notified_region; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.manager_notified_region IS 'The region the notified manager owned at the moment of the send. Frozen for the same reason.';

--
-- Name: COLUMN ats_candidates.preferred_region_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.preferred_region_code IS 'Company region the candidate chose for themselves (au.regions.region_code: CA/GZ/AB/D1/D2/UE/OT). Distinct from `governorate`, which is geography read off the CV, and from `manager_notified_region`, which records who was notified.';

--
-- Name: COLUMN ats_candidates.preferred_area_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.preferred_area_name IS 'Area the candidate chose for themselves, verbatim from au.canonical_areas.area_name.';

--
-- Name: COLUMN ats_candidates.preferences_declared_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.preferences_declared_at IS 'When the candidate stated the above themselves. Null means nobody asked them or they never answered — never inferred.';

--
-- Name: COLUMN ats_candidates.sent_for_vacancy_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.sent_for_vacancy_id IS 'The open vacancy this CV was sent for, when the recruiter picked one from the organogram. NULL for a free-typed position, and set to NULL rather than cascading if the vacancy is later removed — the send happened either way.';

--
-- Name: COLUMN ats_candidates.sent_for_job_title; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.sent_for_job_title IS 'The job title the candidate was sent FOR — not the notified manager''s own title. Frozen at send time so a renamed or closed vacancy cannot re-file an old send under a different folder.';

--
-- Name: COLUMN ats_candidates.sent_for_area; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.sent_for_area IS 'The area of the position being hired for, e.g. Nasr City. Frozen at send time for the same reason.';

--
-- Name: COLUMN ats_candidates.sent_for_line; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.sent_for_line IS 'The line of the position being hired for. Part of the folder identity, not decoration: Nasr City carries two Medical Representative seats on different lines reporting to different managers, and without the line they collapse into one folder belonging to neither.';

--
-- Name: COLUMN ats_candidates.sent_for_region; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.sent_for_region IS 'The region of the position being hired for. Frozen at send time; shown as folder context, never used as the folder key.';

--
-- Name: COLUMN ats_candidates.preferred_region_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.preferred_region_name IS 'The region the applicant stated in their own words, when it is not one of the company regions in preferred_region_code. Written only by the WhatsApp self-classification flow. Read it ALONGSIDE preferred_region_code, never instead of it: a candidate has one or the other, never both.';

--
-- Name: COLUMN ats_candidates.folder_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.folder_kind IS 'medical_rep (one folder per area) | district_manager (one folder per region) | other (one folder per job title) | paramedical (one folder, for graduates outside the five eligible disciplines — pharmacy, science, veterinary, medicine, dentistry). Paramedical is an eligibility answer rather than a role, and a CV only reaches it after an admin has read it: see candidate-background.ts for why the exclusive direction never auto-files.';

--
-- Name: COLUMN ats_candidates.folder_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.folder_key IS 'CV shelf: the folder itself — an area name, a candidateRegionCodes region CODE, or a job title, according to folder_kind.';

--
-- Name: COLUMN ats_candidates.folder_filed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.folder_filed_at IS 'CV shelf: when this CV was filed. Non-null is the single authority for "hidden from the main pool".';

--
-- Name: COLUMN ats_candidates.folder_filed_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.folder_filed_by_hr_id IS 'CV shelf: who filed it. Nullable because a dev-preview session carries no HR_ID, exactly like status_changed_by_hr_id.';

--
-- Name: COLUMN ats_candidates.declared_background; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.declared_background IS 'The graduation background the applicant stated themselves over WhatsApp (Pharmacy/Science/Veterinary, or their own typed words when they chose "Other"). Written only by the WhatsApp self-classification flow. Null means nobody asked them or they never answered — never inferred from the CV.';

--
-- Name: COLUMN ats_candidates.declared_experience; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.declared_experience IS 'The years-of-experience band the applicant stated themselves over WhatsApp (Fresh graduate / Less than 1 year / 1 - 3 years / 3 - 5 years / More than 5 years). Written only by the WhatsApp self-classification flow. Null means nobody asked them or they never answered — never inferred from the CV.';

--
-- Name: COLUMN ats_candidates.screening_extra_answers; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.screening_extra_answers IS 'Answers to the Super-Admin-defined WhatsApp screening questions, keyed by question_key. Written only by the WhatsApp self-classification flow, once the extra-question loop finishes. Distinct from position_specific_fields, which is CV-extraction data (cv-field-storage.ts) — the two must never be conflated.';

--
-- Name: COLUMN ats_candidates.background_confirmed_outcome; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.background_confirmed_outcome IS 'eligible | paramedical — an ADMIN''s answer on whether this graduate is in the five field-force disciplines (pharmacy, science, veterinary, medicine, dentistry). Distinct from declared_background, which is the APPLICANT''s own answer, and from faculty, which the CV extractor read off the document. This column outranks both: see src/lib/recruitment/background-review.ts. Null means nobody has been asked yet, which is where every row starts.';

--
-- Name: COLUMN ats_candidates.background_confirmed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.background_confirmed_at IS 'When the admin answered. Paired with background_confirmed_outcome by ats_candidates_background_confirmation_complete — one is never present without the other.';

--
-- Name: COLUMN ats_candidates.background_confirmed_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.background_confirmed_by_hr_id IS 'Who answered. Nullable for the same reason folder_filed_by_hr_id is: a caller without an HR id must not lose the decision in order to keep its attribution.';

--
-- Name: COLUMN ats_candidates.declared_expected_salary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.declared_expected_salary IS 'The expected salary the applicant typed on WhatsApp, VERBATIM — "Negotiable", "25 k to 30 k", a range, Arabic numerals. Never coerced. expected_salary (numeric) is the parsed figure and is filled alongside this one only when the answer is a bare number; a recruiter reads THIS column.';

--
-- Name: COLUMN ats_candidates.rating; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.rating IS 'How strongly the reader rated this CV: 1, 2 or 3 stars. NULL is unrated, never 0. Not a status -- it survives the decision. See 20260912113000_ats_candidate_rating.sql.';

--
-- Name: COLUMN ats_candidates.rated_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.rated_by_hr_id IS 'Who last set the star. Mirrors status_changed_by_hr_id; no FK, for the same reason that column has none.';

--
-- Name: COLUMN ats_candidates.rated_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.rated_at IS 'When the star was last set, Cairo-agnostic timestamptz like every other stamp on this table.';

--
-- Name: COLUMN ats_candidates.offer_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.offer_id IS 'The job offer currently in play for this candidate. Recruitment holds the pointer and the offers module learns nothing — offers and recruitment are deliberately independent. Null is normal. Never resolve an offer to a candidate by NAME: see the migration header.';

--
-- Name: COLUMN ats_candidates.declared_role_family; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.declared_role_family IS 'The role family the applicant tapped (WhatsApp) or chose (careers form) — raw, before the tab map. Read by the Talent Acquisition fence for people still in Needs placing.';

--
-- Name: COLUMN ats_candidates.answer_marks; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.answer_marks IS '{answer key: {by: "hr", hr_id, at}} for every answer HR typed. The applicant answering that key clears its mark.';

--
-- Name: COLUMN ats_candidates.followup_sent_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidates.followup_sent_at IS 'When HR last pressed "Ask again on WhatsApp" (the phx_application_followup template). Sent only on that press.';

--
-- Name: CONSTRAINT ats_candidates_folder_kind_known ON ats_candidates; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT ats_candidates_folder_kind_known ON public.ats_candidates IS 'The shelves a CV can be filed on. Four are positions (which seat is this good CV waiting for); "duplicate" is the one discard shelf, added 2026-09-05 — reversible, because a duplicate pairing is never proof.';

--
-- Name: ats_candidate_answer_value(public.ats_candidates, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_candidate_answer_value(p_row public.ats_candidates, p_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_key
    when 'background' then p_row.declared_background
    when 'experience' then p_row.declared_experience
    when 'salary' then p_row.declared_expected_salary
    else p_row.screening_extra_answers ->> p_key
  end
$$;

ALTER FUNCTION public.ats_candidate_answer_value(p_row public.ats_candidates, p_key text) OWNER TO postgres;

--
-- Name: ats_candidate_cv_search_text(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_candidate_cv_search_text(p_fields jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select concat_ws(' ',
    nullif(p_fields -> 'currentJobTitle' ->> 'value', ''),
    nullif(p_fields -> 'currentEmployer' ->> 'value', ''),
    nullif(p_fields -> 'university'      ->> 'value', ''),
    nullif(p_fields -> 'degree'          ->> 'value', ''),
    nullif(p_fields -> 'faculty'         ->> 'value', ''),
    (select string_agg(s ->> 'name', ' ')
       from jsonb_array_elements(
              case when jsonb_typeof(p_fields -> 'skills' -> 'value') = 'array'
                   then p_fields -> 'skills' -> 'value' else '[]'::jsonb end) s),
    public.ats_cv_work_text(p_fields -> 'workHistory' -> 'value'),
    public.ats_cv_education_text(p_fields -> 'educationHistory' -> 'value')
  );
$$;

ALTER FUNCTION public.ats_candidate_cv_search_text(p_fields jsonb) OWNER TO postgres;

--
-- Name: FUNCTION ats_candidate_cv_search_text(p_fields jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ats_candidate_cv_search_text(p_fields jsonb) IS 'Flattens one CV extraction into a single searchable string: job title, employer, university, degree, faculty, skill NAMES (not the raw [{"name":...}] JSON, which would make every candidate match the word "name"), plus work and education rendered through the same helpers the CV lifecycle view uses. Added 2026-09-05 — there is no raw CV text in this database, so the structured reading IS the searchable content.';

--
-- Name: ats_cv_education_text(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_cv_education_text(v jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(string_agg(line, ' · ' order by ord), '')
  from (
    select ord,
           nullif(
             concat_ws(' — ',
               nullif(e ->> 'degree', ''),
               nullif(e ->> 'institution', '')
             ) || coalesce(' (' || nullif(e ->> 'year', '') || ')', ''),
             ''
           ) as line
    from jsonb_array_elements(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end)
         with ordinality as t(e, ord)
  ) rows
  where line is not null
$$;

ALTER FUNCTION public.ats_cv_education_text(v jsonb) OWNER TO postgres;

--
-- Name: FUNCTION ats_cv_education_text(v jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ats_cv_education_text(v jsonb) IS 'Education history as "Degree — Institution (year)", joined by a middle dot.';

--
-- Name: ats_cv_names_text(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_cv_names_text(v jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(string_agg(coalesce(nullif(e ->> 'name', ''), e #>> '{}'), ', ' order by ord), '')
  from jsonb_array_elements(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end)
       with ordinality as t(e, ord)
  where coalesce(nullif(e ->> 'name', ''), e #>> '{}') is not null
$$;

ALTER FUNCTION public.ats_cv_names_text(v jsonb) OWNER TO postgres;

--
-- Name: FUNCTION ats_cv_names_text(v jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ats_cv_names_text(v jsonb) IS 'Skills / languages / certifications as one comma-separated line. Tolerates scalar arrays.';

--
-- Name: ats_cv_work_text(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_cv_work_text(v jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select nullif(string_agg(line, ' · ' order by ord), '')
  from (
    select ord,
           nullif(
             concat_ws(' — ',
               nullif(e ->> 'jobTitle', ''),
               nullif(e ->> 'employer', '')
             ) || coalesce(
               ' (' || coalesce(left(nullif(e ->> 'from', ''), 7), '?')
                    || '→'
                    || coalesce(left(nullif(e ->> 'to', ''), 7),
                                case when (e ->> 'isCurrent')::text = 'true' then 'now' else '?' end)
                    || ')',
               ''
             ),
             ''
           ) as line
    from jsonb_array_elements(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end)
         with ordinality as t(e, ord)
  ) rows
  where line is not null
$$;

ALTER FUNCTION public.ats_cv_work_text(v jsonb) OWNER TO postgres;

--
-- Name: FUNCTION ats_cv_work_text(v jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ats_cv_work_text(v jsonb) IS 'Work history as "Job title — Employer (YYYY-MM→YYYY-MM)", joined by a middle dot.';

--
-- Name: ats_merge_screening_answer(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_merge_screening_answer(p_candidate_id uuid, p_key text, p_value text, p_marked_by_hr_id text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_value text := nullif(btrim(coalesce(p_value, '')), '');
begin
  if p_key is null or btrim(p_key) = '' then
    raise exception 'An answer needs a question key.' using errcode = 'check_violation';
  end if;
  update public.ats_candidates c
  set screening_extra_answers = case
        when v_value is null then coalesce(c.screening_extra_answers, '{}'::jsonb) - p_key
        else coalesce(c.screening_extra_answers, '{}'::jsonb) || jsonb_build_object(p_key, v_value)
      end,
      answer_marks = case
        when p_marked_by_hr_id is null then coalesce(c.answer_marks, '{}'::jsonb) - p_key
        else coalesce(c.answer_marks, '{}'::jsonb)
             || jsonb_build_object(p_key, jsonb_build_object('by', 'hr', 'hr_id', p_marked_by_hr_id, 'at', now()))
      end,
      updated_at = now()
  where c.id = p_candidate_id;
end;
$$;

ALTER FUNCTION public.ats_merge_screening_answer(p_candidate_id uuid, p_key text, p_value text, p_marked_by_hr_id text) OWNER TO postgres;

--
-- Name: ats_revert_candidate_status(uuid[], text[], text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_revert_candidate_status(p_candidate_ids uuid[], p_statuses text[], p_notes text[], p_actor_hr_id text) RETURNS TABLE(candidate_id uuid, restored_to text)
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_now timestamptz := now();
  v_count integer := coalesce(cardinality(p_candidate_ids), 0);
begin
  if v_count = 0 then
    return;
  end if;

  if v_count > 200 then
    raise exception 'A revert is capped at 200 candidates; this call passed %.', v_count
      using errcode = 'check_violation';
  end if;

  if coalesce(cardinality(p_statuses), 0) <> v_count or coalesce(cardinality(p_notes), 0) <> v_count then
    raise exception 'A revert needs one status and one note per candidate; got % ids, % statuses, % notes.',
      v_count, coalesce(cardinality(p_statuses), 0), coalesce(cardinality(p_notes), 0)
      using errcode = 'check_violation';
  end if;

  if exists (select 1 from unnest(p_statuses) as s where s is null or btrim(s) = '') then
    raise exception 'A revert cannot restore a blank status.' using errcode = 'check_violation';
  end if;

  return query
  with want as (
    select t.id, t.status, t.note
    from unnest(p_candidate_ids, p_statuses, p_notes) as t(id, status, note)
  ),
  before as (
    select c.id, c.status as from_status
    from public.ats_candidates c
    where c.id in (select w.id from want w)
  ),
  moved as (
    update public.ats_candidates c
    set status = w.status,
        status_note = w.note,
        status_changed_at = v_now,
        status_changed_by_hr_id = p_actor_hr_id,
        updated_at = v_now
    from want w
    where c.id = w.id
    returning c.id
  ),
  logged as (
    insert into public.ats_candidate_status_events
      (candidate_id, from_status, to_status, note, actor_hr_id)
    select b.id, b.from_status, w.status, w.note, p_actor_hr_id
    from before b
    join want w on w.id = b.id
    join moved m on m.id = b.id
    returning public.ats_candidate_status_events.candidate_id
  )
  select b.id, w.status
  from before b
  join want w on w.id = b.id
  join logged l on l.candidate_id = b.id;
end;
$$;

ALTER FUNCTION public.ats_revert_candidate_status(p_candidate_ids uuid[], p_statuses text[], p_notes text[], p_actor_hr_id text) OWNER TO postgres;

--
-- Name: FUNCTION ats_revert_candidate_status(p_candidate_ids uuid[], p_statuses text[], p_notes text[], p_actor_hr_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ats_revert_candidate_status(p_candidate_ids uuid[], p_statuses text[], p_notes text[], p_actor_hr_id text) IS 'Puts candidates back to their own previous status and note, atomically — the undo behind a screening decision. Positional arrays, one status and one note per id, refused on a length mismatch. Writes a history row per candidate rather than erasing the original decision, so the record shows the change of mind. Deliberately separate from ats_bulk_set_candidate_status because a revert restores a per-row status and is not bound by the bulk-decision vocabulary. Added 2026-09-05.';

--
-- Name: ats_search_candidate_cvs(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_search_candidate_cvs(p_query text, p_limit integer DEFAULT 200) RETURNS TABLE(candidate_id uuid, matched_on text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  with parsed as (
    select websearch_to_tsquery('english', coalesce(btrim(p_query), '')) as base
  ),
  q as (
    select case
             when base::text = '' then base
             when length((regexp_match(base::text, '''([^'']+)''\s*$'))[1]) >= 4
               then (base::text || ':*')::tsquery
             else base
           end as tsq
    from parsed
  ),
  matched as (
    select e.candidate_id, e.extracted_fields, e.search_tsv, e.created_at
    from public.ats_candidate_cv_extractions e, q
    where q.tsq != ''::tsquery
      and e.search_tsv @@ q.tsq
      and e.candidate_id is not null
  ),
  newest as (
    select distinct on (e.candidate_id) e.candidate_id, e.created_at
    from public.ats_candidate_cv_extractions e
    order by e.candidate_id, e.created_at desc
  )
  select m.candidate_id,
         ts_headline(
           'english',
           public.ats_candidate_cv_search_text(m.extracted_fields),
           q.tsq,
           'StartSel="", StopSel="", MaxWords=26, MinWords=10, ShortWord=2, MaxFragments=2, FragmentDelimiter=" · "'
         ) as matched_on
  from matched m
  join newest n on n.candidate_id = m.candidate_id and n.created_at = m.created_at,
       q
  order by ts_rank(m.search_tsv, q.tsq) desc, m.candidate_id
  limit greatest(1, least(coalesce(p_limit, 200), 1000));
$_$;

ALTER FUNCTION public.ats_search_candidate_cvs(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION ats_search_candidate_cvs(p_query text, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.ats_search_candidate_cvs(p_query text, p_limit integer) IS 'Candidates whose newest CV reading contains EVERY term in the query (substring, case-insensitive). AND not OR, because "pharmacist cairo" means both. Substring and not tsvector, because a recruiter types "cardio" and a lexeme match would silently return nothing. Returns the candidate id and a snippet of what was searched. Reads only; applies no permission of its own — the caller is the service, which asserts candidates:read first.';

--
-- Name: ats_set_answer_mark(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_set_answer_mark(p_candidate_id uuid, p_key text, p_marked_by_hr_id text) RETURNS void
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  update public.ats_candidates c
  set answer_marks = case
        when p_marked_by_hr_id is null then coalesce(c.answer_marks, '{}'::jsonb) - p_key
        else coalesce(c.answer_marks, '{}'::jsonb)
             || jsonb_build_object(p_key, jsonb_build_object('by', 'hr', 'hr_id', p_marked_by_hr_id, 'at', now()))
      end
  where c.id = p_candidate_id;
$$;

ALTER FUNCTION public.ats_set_answer_mark(p_candidate_id uuid, p_key text, p_marked_by_hr_id text) OWNER TO postgres;

--
-- Name: ats_whatsapp_screening_questions_immutable_key(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_whatsapp_screening_questions_immutable_key() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.question_key is distinct from old.question_key then
    raise exception 'ats_whatsapp_screening_questions.question_key is immutable (was %, tried to set %)',
      old.question_key, new.question_key;
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.ats_whatsapp_screening_questions_immutable_key() OWNER TO postgres;

--
-- Name: ats_workspace_counts(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_workspace_counts(p jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with
  base_tabs as (select id from public.ats_workspace_filter(p - 'tab' - 'region' - 'area') as f(id)),
  tab_rows as (
    select pl.role_tab as k, count(distinct pl.candidate_id) as n
    from public.ats_candidate_placements pl
    join base_tabs b on b.id = pl.candidate_id
    where pl.role_tab = any(coalesce(array(select jsonb_array_elements_text(coalesce(p->'allowed_tabs', '[]'::jsonb))), '{}'::text[]))
    group by pl.role_tab
    union all
    select 'needs_placing', count(*)
    from base_tabs b
    where 'needs_placing' = any(coalesce(array(select jsonb_array_elements_text(coalesce(p->'allowed_tabs', '[]'::jsonb))), '{}'::text[]))
      and not exists (select 1 from public.ats_candidate_placements np where np.candidate_id = b.id)
  ),
  base_place as (select id from public.ats_workspace_filter(p - 'region' - 'area') as f(id)),
  place_rows as (
    select
      case
        when pl.role_tab = 'medical_rep' and pl.area_code is null then 'unspecified'
        when pl.region_code is null then 'unspecified'
        else pl.region_code
      end as region_key,
      case when pl.role_tab = 'medical_rep' then pl.area_code end as area_key,
      count(distinct pl.candidate_id) as n
    from public.ats_candidate_placements pl
    join base_place b on b.id = pl.candidate_id
    where pl.role_tab = nullif(p->>'tab', '')
    group by 1, 2
  ),
  base_status as (select id from public.ats_workspace_filter(p - 'statuses' - 'exclude_statuses') as f(id)),
  status_rows as (
    select coalesce(c.status, 'new') as k, count(*) as n
    from public.ats_candidates c join base_status b on b.id = c.id
    group by 1
  ),
  funnel as (
    select
      count(*) as received,
      count(*) filter (where c.status in ('shortlisted', 'sent_to_manager', 'hired')
        or exists (select 1 from public.ats_candidate_status_events e where e.candidate_id = c.id and e.to_status = 'shortlisted')) as shortlisted,
      count(*) filter (where exists (select 1 from public.ats_candidate_manager_sends s where s.candidate_id = c.id)
        or c.status = 'sent_to_manager') as sent_to_manager,
      count(*) filter (where exists (select 1 from public.ats_interview_bookings ib where ib.candidate_id = c.id and ib.starts_at < now())) as interviewed,
      count(*) filter (where c.offer_id is not null) as offered,
      count(*) filter (where c.status = 'hired') as hired
    from public.ats_candidates c join base_status b on b.id = c.id
  )
  select jsonb_build_object(
    'total', (select count(*) from public.ats_workspace_filter(p)),
    'by_tab', coalesce((select jsonb_object_agg(k, n) from tab_rows), '{}'::jsonb),
    'by_place', coalesce((select jsonb_agg(jsonb_build_object('region', region_key, 'area', area_key, 'n', n)) from place_rows), '[]'::jsonb),
    'by_status', coalesce((select jsonb_object_agg(k, n) from status_rows), '{}'::jsonb),
    'funnel', (select to_jsonb(funnel) from funnel)
  )
$$;

ALTER FUNCTION public.ats_workspace_counts(p jsonb) OWNER TO postgres;

--
-- Name: ats_workspace_filter(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_workspace_filter(p jsonb) RETURNS SETOF uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with pr as (
    select
      coalesce(array(select jsonb_array_elements_text(coalesce(p->'allowed_tabs', '[]'::jsonb))), '{}'::text[]) as allowed_tabs,
      coalesce((p->>'hide_hr_people')::boolean, false) as hide_hr_people,
      nullif(p->>'tab', '') as tab,
      nullif(p->>'region', '') as region,
      nullif(p->>'area', '') as area,
      case when jsonb_typeof(p->'statuses') = 'array' and jsonb_array_length(p->'statuses') > 0 then array(select jsonb_array_elements_text(p->'statuses')) end as statuses,
      case when jsonb_typeof(p->'exclude_statuses') = 'array' and jsonb_array_length(p->'exclude_statuses') > 0 then array(select jsonb_array_elements_text(p->'exclude_statuses')) end as exclude_statuses,
      case when jsonb_typeof(p->'sources') = 'array' and jsonb_array_length(p->'sources') > 0 then array(select jsonb_array_elements_text(p->'sources')) end as sources,
      case when jsonb_typeof(p->'exclude_sources') = 'array' and jsonb_array_length(p->'exclude_sources') > 0 then array(select jsonb_array_elements_text(p->'exclude_sources')) end as exclude_sources,
      nullif(p->>'from', '')::timestamptz as from_at,
      nullif(p->>'to', '')::timestamptz as to_at,
      case when p ? 'answers' and jsonb_typeof(p->'answers') = 'object' then p->'answers' end as answers,
      nullif(p->>'missing', '')::boolean as missing,
      case when jsonb_typeof(p->'call_results') = 'array' and jsonb_array_length(p->'call_results') > 0 then array(select jsonb_array_elements_text(p->'call_results')) end as call_results,
      case when jsonb_typeof(p->'exclude_call_results') = 'array' and jsonb_array_length(p->'exclude_call_results') > 0 then array(select jsonb_array_elements_text(p->'exclude_call_results')) end as exclude_call_results,
      nullif(p->>'returned', '')::boolean as returned,
      nullif(p->>'overdue', '')::boolean as overdue,
      coalesce(nullif(p->>'overdue_shortlist_days', '')::int, 14) as overdue_shortlist_days,
      coalesce(nullif(p->>'overdue_sent_days', '')::int, 7) as overdue_sent_days,
      case when jsonb_typeof(p->'folder_ids') = 'array' and jsonb_array_length(p->'folder_ids') > 0 then array(select jsonb_array_elements_text(p->'folder_ids'))::uuid[] end as folder_ids,
      coalesce(nullif(p->>'archived', ''), 'exclude') as archived,
      nullif(btrim(coalesce(p->>'search', '')), '') as search,
      case when jsonb_typeof(p->'search_ids') = 'array' and jsonb_array_length(p->'search_ids') > 0 then array(select jsonb_array_elements_text(p->'search_ids'))::uuid[] end as search_ids,
      case when p ? 'candidate_ids' then array(select jsonb_array_elements_text(p->'candidate_ids'))::uuid[] end as candidate_ids
  )
  select c.id
  from public.ats_candidates c
  cross join pr
  where
    -- the Talent Acquisition fence, by person
    (not pr.hide_hr_people or (
      coalesce(c.declared_role_family, '') not in ('hr_section_head', 'talent_acquisition', 'personnel', 'human_resources')
      and not exists (
        select 1 from public.ats_candidate_placements hp
        where hp.candidate_id = c.id and hp.role_tab in ('hr_section_head', 'talent_acquisition', 'personnel')
      )
    ))
    -- the tab
    and (
      case
        when pr.tab is null then (
          exists (select 1 from public.ats_candidate_placements ap
                  where ap.candidate_id = c.id and ap.role_tab = any(pr.allowed_tabs))
          or ('needs_placing' = any(pr.allowed_tabs)
              and not exists (select 1 from public.ats_candidate_placements np where np.candidate_id = c.id))
        )
        when pr.tab = 'needs_placing' then (
          'needs_placing' = any(pr.allowed_tabs)
          and not exists (select 1 from public.ats_candidate_placements np where np.candidate_id = c.id)
        )
        else (
          pr.tab = any(pr.allowed_tabs)
          and exists (
            select 1 from public.ats_candidate_placements tp
            where tp.candidate_id = c.id
              and tp.role_tab = pr.tab
              and (
                pr.region is null
                or (pr.region = 'unspecified' and (
                      (tp.role_tab = 'medical_rep' and tp.area_code is null)
                      or (tp.role_tab <> 'medical_rep' and tp.region_code is null)))
                or (pr.region <> 'unspecified' and tp.region_code = pr.region
                    and (tp.role_tab <> 'medical_rep' or tp.area_code is not null))
              )
              and (pr.area is null or tp.area_code = pr.area)
          )
        )
      end
    )
    and (case pr.archived
           when 'only' then c.archived_at is not null
           when 'include' then true
           else c.archived_at is null
         end)
    and (pr.statuses is null or c.status = any(pr.statuses))
    -- hide: a candidate with no status reads as 'new', the same key ats_workspace_counts uses
    and (pr.exclude_statuses is null or coalesce(c.status, 'new') <> all(pr.exclude_statuses))
    and (pr.sources is null or (
      case
        when lower(coalesce(c.source, '')) in ('whatsapp', 'email', 'website', 'interview_calendar') then lower(c.source)
        else 'other'
      end
    ) = any(pr.sources))
    and (pr.exclude_sources is null or (
      case
        when lower(coalesce(c.source, '')) in ('whatsapp', 'email', 'website', 'interview_calendar') then lower(c.source)
        else 'other'
      end
    ) <> all(pr.exclude_sources))
    and (pr.from_at is null or c.created_at >= pr.from_at)
    and (pr.to_at is null or c.created_at < pr.to_at)
    and (pr.answers is null or not exists (
      select 1 from jsonb_each(pr.answers) a
      where jsonb_typeof(a.value) = 'array'
        and jsonb_array_length(a.value) > 0
        and not (
          (public.ats_candidate_answer_value(c, a.key) is null and a.value ? '__missing__')
          or coalesce(public.ats_candidate_answer_value(c, a.key), '') in (select jsonb_array_elements_text(a.value))
        )
    ))
    and (pr.missing is null
         or (pr.missing and coalesce(cardinality(c.missing_answer_keys), 0) > 0)
         or (not pr.missing and c.missing_answer_keys is not null and cardinality(c.missing_answer_keys) = 0))
    and (pr.call_results is null or exists (
      select 1 from (
        select r.result from public.ats_candidate_call_results r
        where r.candidate_id = c.id
        order by r.created_at desc, r.id desc
        limit 1
      ) latest
      where latest.result = any(pr.call_results)
    ))
    -- hide: only the LATEST call result counts; a candidate never called stays in
    and (pr.exclude_call_results is null or not exists (
      select 1 from (
        select r.result from public.ats_candidate_call_results r
        where r.candidate_id = c.id
        order by r.created_at desc, r.id desc
        limit 1
      ) latest
      where latest.result = any(pr.exclude_call_results)
    ))
    and (pr.returned is null
         or (pr.returned = exists (select 1 from public.ats_v_candidate_returns rv where rv.candidate_id = c.id)))
    and (pr.overdue is null or pr.overdue = (
      (c.status = 'shortlisted'
        and coalesce(c.status_changed_at, c.created_at) < now() - make_interval(days => pr.overdue_shortlist_days))
      or (c.status = 'sent_to_manager'
        and coalesce(
              (select max(s.sent_at) from public.ats_candidate_manager_sends s where s.candidate_id = c.id),
              c.status_changed_at, c.created_at
            ) < now() - make_interval(days => pr.overdue_sent_days))
    ))
    and (pr.folder_ids is null or exists (
      select 1 from public.ats_cv_folder_items fi
      where fi.candidate_id = c.id and fi.folder_id = any(pr.folder_ids)
    ))
    and (pr.candidate_ids is null or c.id = any(pr.candidate_ids))
    and (pr.search is null and pr.search_ids is null
      or (pr.search is not null and (
            c.full_name ilike '%' || pr.search || '%'
            or c.email_norm ilike '%' || lower(pr.search) || '%'
            or (length(regexp_replace(pr.search, '\D', '', 'g')) >= 4
                and c.phone_norm like '%' || regexp_replace(pr.search, '\D', '', 'g') || '%')
          ))
      or (pr.search_ids is not null and c.id = any(pr.search_ids)))
$$;

ALTER FUNCTION public.ats_workspace_filter(p jsonb) OWNER TO postgres;

--
-- Name: ats_workspace_page(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ats_workspace_page(p jsonb) RETURNS TABLE(candidate_id uuid, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select c.id, c.created_at
  from public.ats_candidates c
  where c.id in (select public.ats_workspace_filter(p))
    and (
      p->'after' is null
      or (c.created_at, c.id) < ((p->'after'->>'created_at')::timestamptz, (p->'after'->>'id')::uuid)
    )
  order by c.created_at desc, c.id desc
  limit least(greatest(coalesce(nullif(p->>'limit', '')::int, 50), 1), 200)
$$;

ALTER FUNCTION public.ats_workspace_page(p jsonb) OWNER TO postgres;

--
-- Name: au_f_org_tree_as_of(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.au_f_org_tree_as_of(p_date date) RETURNS TABLE(seat_id text, parent_seat_id text, seat_tier text, line_code text, region_code text, area_code text, is_other_pseudo_dm boolean, occupant_hr_id text, is_vacant boolean, area_name text, region_name text, line_name text, line_id bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive alive as (
    select s.*
    from au.seats s
    where s.effective_from <= p_date
      and (s.effective_to is null or s.effective_to > p_date)
  ),
  dated as (
    select
      s.seat_id,
      case
        when o.manager_seat_id is not null
         and exists (select 1 from alive m where m.seat_id = o.manager_seat_id)
        then o.manager_seat_id
        else s.parent_seat_id
      end as eff_parent,
      s.seat_tier,
      coalesce(o.line_code, s.line_code) as line_code,
      coalesce(o.region_code, s.region_code) as region_code,
      coalesce(o.area_code, s.area_code) as area_code,
      s.is_other_pseudo_dm,
      nullif(btrim(o.occupant_hr_id), '') as occupant_hr_id
    from alive s
    left join lateral (
      select oh.occupant_hr_id, oh.manager_seat_id, oh.line_code, oh.region_code, oh.area_code
      from au.occupancy_history oh
      where oh.seat_id = s.seat_id
        and oh.effective_from <= p_date
        and (oh.effective_to is null or oh.effective_to > p_date)
      order by oh.effective_from desc
      limit 1
    ) o on true
  ),
  tree as (
    select d.*, array[d.seat_id] as path
    from dated d
    where d.eff_parent is null
    union all
    select c.*, t.path || c.seat_id
    from dated c
    join tree t on c.eff_parent = t.seat_id
    where not (c.seat_id = any (t.path))
  )
  select
    t.seat_id,
    t.eff_parent as parent_seat_id,
    t.seat_tier,
    t.line_code,
    t.region_code,
    t.area_code,
    t.is_other_pseudo_dm,
    t.occupant_hr_id,
    t.occupant_hr_id is null as is_vacant,
    ca.area_name,
    rg.region_name,
    ln.line_name,
    ln.line_id
  from tree t
  left join au.canonical_areas ca on ca.area_code = t.area_code
  left join au.regions rg on rg.region_code = t.region_code
  left join au.lines ln on ln.line_code = t.line_code;
$$;

ALTER FUNCTION public.au_f_org_tree_as_of(p_date date) OWNER TO postgres;

--
-- Name: FUNCTION au_f_org_tree_as_of(p_date date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.au_f_org_tree_as_of(p_date date) IS 'The organogram seat tree as it stood on p_date, same columns as au_v_org_tree. Seats by their own effective dates (is_active ignored so a retired seat still draws for the months it was live); occupant, manager, region, area and line from the au.occupancy_history span covering the day, else the seat itself. Half-open spans [effective_from, effective_to). Read-only; service_role only.';

--
-- Name: au_reclaim_reports_on_manager_hire(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.au_reclaim_reports_on_manager_hire() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_child record;
  v_count integer := 0;
begin
  -- Only when a seat becomes OCCUPIED by a person. A vacate writes effective_to, and a
  -- vacant_placeholder row carries a null occupant; neither should reclaim anything.
  if new.occupant_hr_id is null or new.effective_to is not null then
    return null;
  end if;

  -- Every seat directly beneath this one: its occupant now reports to the new arrival.
  for v_child in
    select o.occupant_hr_id as child_hr_id
      from au.seats s
      join au.occupancy_history o on o.seat_id = s.seat_id
     where s.parent_seat_id = new.seat_id
       and o.effective_to is null
       and o.occupant_hr_id is not null
       -- An acting DM occupies both the manager seat and their own rep seat beneath it; they
       -- must never become their own manager.
       and lower(btrim(o.occupant_hr_id)) is distinct from lower(btrim(new.occupant_hr_id))
  loop
    begin
      update public.employees
         set manager_hr_id = new.occupant_hr_id,
             -- Their own manager seat is now filled, so the "awaiting a replacement" marker is
             -- satisfied and must not linger as debris.
             pending_manager_replacement_for_hr_id = null,
             updated_at = now()
       where lower(btrim(hr_id)) = lower(btrim(v_child.child_hr_id))
         and (upper(coalesce(manager_hr_id, '')) is distinct from upper(new.occupant_hr_id)
              or pending_manager_replacement_for_hr_id is not null);

      if found then
        v_count := v_count + 1;
        insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, new_values)
        values (
          'system', 'employee_manager_reassignment', v_child.child_hr_id,
          format('Reclaimed by %s on hire into seat %s', new.occupant_hr_id, new.seat_id),
          jsonb_build_object(
            'managerHrId', new.occupant_hr_id,
            'seatId', new.seat_id,
            'trigger', 'au_reclaim_reports_on_manager_hire'
          )
        );
      end if;
    exception when others then
      -- A reporting-line sync must never fail a hire; the drift detector will surface anything
      -- this could not apply.
      null;
    end;
  end loop;

  return null;
end;
$$;

ALTER FUNCTION public.au_reclaim_reports_on_manager_hire() OWNER TO postgres;

