--
-- Name: claim_job_lease(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_job_lease(p_job_key text, p_holder text, p_ttl_seconds integer) RETURNS TABLE(held boolean, holder text, expires_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
begin
  if p_job_key is null or p_holder is null or p_ttl_seconds is null or p_ttl_seconds < 1 or p_ttl_seconds > 3600 then
    raise exception 'claim_job_lease: job key, holder and a ttl between 1 and 3600 seconds are required';
  end if;

  insert into public.job_leases as l (job_key, holder, expires_at, updated_at)
  values (p_job_key, p_holder, now() + make_interval(secs => p_ttl_seconds), now())
  on conflict (job_key) do update
    set holder = excluded.holder,
        expires_at = excluded.expires_at,
        updated_at = now()
    where l.holder = excluded.holder or l.expires_at < now();

  return query
    select (l.holder = p_holder) as held, l.holder, l.expires_at
    from public.job_leases l
    where l.job_key = p_job_key;
end;
$$;

ALTER FUNCTION public.claim_job_lease(p_job_key text, p_holder text, p_ttl_seconds integer) OWNER TO postgres;

--
-- Name: background_jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.background_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_type text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    params jsonb DEFAULT '{}'::jsonb NOT NULL,
    requested_by text,
    progress integer DEFAULT 0 NOT NULL,
    result_bucket text,
    result_path text,
    result_filename text,
    result_content_type text,
    error text,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT background_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'completed'::text, 'failed'::text])))
);

ALTER TABLE public.background_jobs OWNER TO postgres;

--
-- Name: claim_next_background_job(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_next_background_job(p_job_types text[]) RETURNS public.background_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  claimed public.background_jobs;
begin
  update public.background_jobs
     set status = 'processing',
         started_at = now(),
         updated_at = now(),
         attempts = attempts + 1
   where id = (
     select id
       from public.background_jobs
      where status = 'queued'
        and job_type = any (p_job_types)
      order by created_at
      for update skip locked
      limit 1
   )
  returning * into claimed;

  return claimed;
end;
$$;

ALTER FUNCTION public.claim_next_background_job(p_job_types text[]) OWNER TO postgres;

--
-- Name: ats_inbound_intake_queue; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_inbound_intake_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel text NOT NULL,
    provider_message_id text NOT NULL,
    source text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error text,
    claimed_at timestamp with time zone,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_inbound_intake_queue_channel_check CHECK ((channel = ANY (ARRAY['whatsapp'::text, 'email'::text]))),
    CONSTRAINT ats_inbound_intake_queue_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'done'::text, 'dead'::text])))
);

ALTER TABLE public.ats_inbound_intake_queue OWNER TO postgres;

--
-- Name: claim_next_inbound_intake(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_next_inbound_intake(p_limit integer DEFAULT 5) RETURNS SETOF public.ats_inbound_intake_queue
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  update public.ats_inbound_intake_queue
     set status = 'processing',
         attempts = attempts + 1,
         claimed_at = now(),
         updated_at = now()
   where id in (
     select id
       from public.ats_inbound_intake_queue
      where (status = 'queued' and next_attempt_at <= now())
         or (status = 'processing' and claimed_at < now() - interval '15 minutes')
      order by next_attempt_at
      for update skip locked
      limit greatest(1, p_limit)
   )
  returning *;
end;
$$;

ALTER FUNCTION public.claim_next_inbound_intake(p_limit integer) OWNER TO postgres;

--
-- Name: create_lifecycle_notification_event(text, text, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_lifecycle_notification_event(p_category text, p_employee_hr_id text, p_scheduled_for date, p_subject text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_event_key text;
begin
  if p_employee_hr_id is null or p_scheduled_for is null then
    return null;
  end if;

  v_event_key := p_category || ':' || p_employee_hr_id || ':' || p_scheduled_for::text;

  insert into public.notification_events (
    event_key,
    category,
    employee_hr_id,
    scheduled_for,
    recipients,
    subject,
    status,
    metadata,
    created_at,
    updated_at
  )
  values (
    v_event_key,
    p_category,
    p_employee_hr_id,
    p_scheduled_for,
    '{}'::text[],
    p_subject,
    'pending',
    coalesce(p_metadata, '{}'::jsonb),
    now(),
    now()
  )
  on conflict (event_key) do update
  set
    subject = excluded.subject,
    metadata = excluded.metadata,
    updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;

ALTER FUNCTION public.create_lifecycle_notification_event(p_category text, p_employee_hr_id text, p_scheduled_for date, p_subject text, p_metadata jsonb) OWNER TO postgres;

--
-- Name: crm_agent_crm_ids_calc(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crm_agent_crm_ids_calc(p_agent_hr_id text DEFAULT NULL::text) RETURNS TABLE(agent_hr_id text, agent_crm_id bigint)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 300
    SET search_path TO 'public'
    AS $$
  select distinct v.agent_hr_id, v.agent_crm_id
    from public.crm_visits_unified v
   where v.agent_crm_id is not null
     and v.agent_hr_id is not null
     and (p_agent_hr_id is null or v.agent_hr_id = p_agent_hr_id)
$$;

ALTER FUNCTION public.crm_agent_crm_ids_calc(p_agent_hr_id text) OWNER TO postgres;

--
-- Name: FUNCTION crm_agent_crm_ids_calc(p_agent_hr_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.crm_agent_crm_ids_calc(p_agent_hr_id text) IS 'The one body behind crm_agent_crm_ids_cache: distinct (agent_hr_id, agent_crm_id) pairs in crm_visits_unified, NULL keys excluded (they are unmatchable by every caller). Expensive by nature (~136k rows scanned, 220 ms); callers read the cache, not this.';

--
-- Name: crm_agent_crm_ids_rebuild(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crm_agent_crm_ids_rebuild() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rows integer;
begin
  delete from public.crm_agent_crm_ids_cache where true;
  insert into public.crm_agent_crm_ids_cache (agent_hr_id, agent_crm_id)
  select c.agent_hr_id, c.agent_crm_id
    from public.crm_agent_crm_ids_calc() c;
  get diagnostics v_rows = row_count;
  return v_rows;
end
$$;

ALTER FUNCTION public.crm_agent_crm_ids_rebuild() OWNER TO postgres;

--
-- Name: crm_agent_crm_ids_reconcile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crm_agent_crm_ids_reconcile() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_truth public.crm_agent_crm_ids_cache[];
  v_diff integer;
begin
  -- The ONE read of the view per run.
  v_truth := array(
    select row(c.agent_hr_id, c.agent_crm_id)::public.crm_agent_crm_ids_cache
      from public.crm_agent_crm_ids_calc() c
  );

  select count(*) into v_diff
    from (
      (select k.agent_hr_id, k.agent_crm_id from public.crm_agent_crm_ids_cache k
        except
       select t.agent_hr_id, t.agent_crm_id from unnest(v_truth) t)
      union all
      (select t.agent_hr_id, t.agent_crm_id from unnest(v_truth) t
        except
       select k.agent_hr_id, k.agent_crm_id from public.crm_agent_crm_ids_cache k)
    ) d;

  if v_diff > 0 then
    delete from public.crm_agent_crm_ids_cache where true;
    insert into public.crm_agent_crm_ids_cache (agent_hr_id, agent_crm_id)
    select t.agent_hr_id, t.agent_crm_id from unnest(v_truth) t;
    raise warning 'crm_agent_crm_ids_cache was % row(s) out of step with _calc() and has been rebuilt', v_diff;
  end if;

  return v_diff;
end
$$;

ALTER FUNCTION public.crm_agent_crm_ids_reconcile() OWNER TO postgres;

--
-- Name: crm_agent_crm_ids_reconcile_run(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crm_agent_crm_ids_reconcile_run() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_diff integer;
begin
  -- Uncaught on purpose: see the header. A raise here fails the run, and no success is recorded.
  v_diff := public.crm_agent_crm_ids_reconcile();

  perform public.phx_record_job_heartbeat(
    'phoenix-crm-agent-crm-ids-reconcile',
    'success',
    case
      when v_diff > 0 then format('rebuilt: %s row(s) were out of step with _calc()', v_diff)
      else 'in step: 0 differences against _calc()'
    end
  );

  return v_diff;
end
$$;

ALTER FUNCTION public.crm_agent_crm_ids_reconcile_run() OWNER TO postgres;

--
-- Name: crm_contact_fold_grade(text); Type: FUNCTION; Schema: public; Owner: postgres
