--
-- Name: crm_person_by_hr_key_rebuild(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crm_person_by_hr_key_rebuild() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rows integer;
begin
  delete from public.crm_person_by_hr_key_cache where true;
  insert into public.crm_person_by_hr_key_cache (hr_key, hr_id, crm_id, full_name, full_name_nz)
  select c.hr_key, c.hr_id, c.crm_id, c.full_name, c.full_name_nz
    from public.crm_person_by_hr_key_calc() c;
  get diagnostics v_rows = row_count;
  return v_rows;
end
$$;

ALTER FUNCTION public.crm_person_by_hr_key_rebuild() OWNER TO postgres;

--
-- Name: crm_person_by_hr_key_reconcile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crm_person_by_hr_key_reconcile() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_diff integer;
begin
  select count(*) into v_diff
    from (
      (select * from public.crm_person_by_hr_key_cache
        except
       select * from public.crm_person_by_hr_key_calc())
      union all
      (select * from public.crm_person_by_hr_key_calc()
        except
       select * from public.crm_person_by_hr_key_cache)
    ) d;

  if v_diff > 0 then
    perform public.crm_person_by_hr_key_rebuild();
    raise warning 'crm_person_by_hr_key_cache was % row(s) out of step with _calc() and has been rebuilt', v_diff;
  end if;

  return v_diff;
end
$$;

ALTER FUNCTION public.crm_person_by_hr_key_reconcile() OWNER TO postgres;

--
-- Name: crm_person_by_hr_key_reconcile_run(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crm_person_by_hr_key_reconcile_run() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_diff integer;
begin
  v_diff := public.crm_person_by_hr_key_reconcile();

  perform public.phx_record_job_heartbeat(
    'phoenix-crm-person-by-hr-key-reconcile',
    'success',
    case
      when v_diff > 0 then format('rebuilt: %s row(s) were out of step with _calc()', v_diff)
      else 'in step: 0 differences against _calc()'
    end
  );

  return v_diff;
end
$$;

ALTER FUNCTION public.crm_person_by_hr_key_reconcile_run() OWNER TO postgres;

