--
-- Name: deductions_publication_lines_guard_day_overlap(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.deductions_publication_lines_guard_day_overlap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_conflict record;
begin
  -- A withdrawn line no longer deducts anything, so it must not block a re-push
  -- of the same candidate/day or a genuine push of a different candidate.
  if new.line_status <> 'active' then
    return new;
  end if;

  -- A manual HR entry's date is a `${monthKey}-01` placeholder, not a day the
  -- employee was absent — it claims no day, so there is nothing to collide on.
  if exists (
    select 1 from public.deductions_candidates c
    where c.id = new.candidate_id and c.source_system = 'manual_hr'
  ) then
    return new;
  end if;

  select l.category, d.day, l.candidate_id
    into v_conflict
  from public.deductions_publication_lines l
  cross join lateral jsonb_array_elements_text(l.dates) as d(day)
  join public.deductions_publications p on p.id = l.publication_id
  left join public.deductions_candidates c on c.id = l.candidate_id
  where l.publication_id = new.publication_id
    and l.employee_hr_id_compact = new.employee_hr_id_compact
    and l.id <> new.id
    and l.line_status = 'active'
    and p.status = 'published'
    -- …and a manual line's placeholder never blocks a real day either.
    and coalesce(c.source_system, '') <> 'manual_hr'
    and d.day in (select jsonb_array_elements_text(new.dates))
  limit 1;

  if v_conflict.day is not null then
    raise exception
      'deductions_publication_lines: employee % is already being deducted for % under category "%" in this publication — one employee-day may only be deducted once (conflicting candidate %)',
      new.employee_hr_id_compact, v_conflict.day, v_conflict.category, v_conflict.candidate_id
      using errcode = 'unique_violation';
  end if;

  return new;
end;
$_$;

ALTER FUNCTION public.deductions_publication_lines_guard_day_overlap() OWNER TO postgres;

--
-- Name: FUNCTION deductions_publication_lines_guard_day_overlap(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.deductions_publication_lines_guard_day_overlap() IS 'Structural double-deduction guard: within one publication, an employee-day may be paid at most once across ALL categories. Fingerprint/CRM/No-Records-Activity can each flag the same absence day independently; without this the employee is deducted once per pipeline. Manual HR entries (source_system manual_hr) are exempt both ways — their date is a month placeholder, not a day (mirrors findDayCollisions).';

--
-- Name: early_birds_candidates_guard_frozen(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.early_birds_candidates_guard_frozen() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if (new.total_score, new.base_score, new.quality_weight, new.rank, new.candidate_rank, new.eligible)
     is distinct from
     (old.total_score, old.base_score, old.quality_weight, old.rank, old.candidate_rank, old.eligible)
  then
    raise exception 'early_birds_candidates rows are frozen; supersede the snapshot instead of editing candidate %', old.id
      using errcode = '23514';
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.early_birds_candidates_guard_frozen() OWNER TO postgres;

