--
-- Name: fill_salary_allowances(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fill_salary_allowances() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job_title TEXT;
  v_col       NUMERIC(14,2);
  v_fuel      NUMERIC(14,2);
BEGIN
  -- Only fill if caller left them at 0 (didn't pass explicit values)
  IF NEW.cost_of_living = 0 OR NEW.fuel_allowance = 0 THEN
    SELECT e.job_title INTO v_job_title
    FROM employees e
    WHERE e.hr_id = NEW.employee_hr_id
    LIMIT 1;

    SELECT
      COALESCE(d.cost_of_living, 1500),
      COALESCE(d.fuel_allowance, 500)
    INTO v_col, v_fuel
    FROM salary_allowance_defaults d
    WHERE d.job_title = v_job_title;

    -- Use looked-up value only when caller didn't supply one
    IF NEW.cost_of_living = 0 THEN
      NEW.cost_of_living := COALESCE(v_col, 1500);
    END IF;
    IF NEW.fuel_allowance = 0 THEN
      NEW.fuel_allowance := COALESCE(v_fuel, 500);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION public.fill_salary_allowances() OWNER TO postgres;

--
-- Name: finalize_manual_employee_lifecycle(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finalize_manual_employee_lifecycle(p_employee_hr_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  e record;
begin
  select * into e from public.employees where hr_id = p_employee_hr_id;
  if not found then
    raise exception 'Employee % not found', p_employee_hr_id;
  end if;

  update public.employees
  set
    employment_status = coalesce(employment_status, 'active'),
    onboarding_source = coalesce(onboarding_source, 'manual_add'),
    onboarding_status = coalesce(onboarding_status, 'active'),
    payroll_eligible = coalesce(payroll_eligible, true),
    organogram_visible = coalesce(organogram_visible, true),
    updated_at = now()
  where hr_id = p_employee_hr_id;

  insert into public.employee_compensation (employee_hr_id, created_at, updated_at)
  values (p_employee_hr_id, now(), now())
  on conflict (employee_hr_id) do nothing;

  insert into public.employee_history (
    employee_hr_id,
    event_type,
    effective_from,
    department_id,
    line_id,
    area_id,
    team_id,
    position_id,
    note,
    created_at
  )
  values (
    p_employee_hr_id,
    'manual_employee_finalized',
    coalesce(e.hire_date, (now() at time zone 'Africa/Cairo')::date),
    e.department_id,
    e.line_id,
    e.area_id,
    e.team_id,
    e.position_id,
    'Manual employee lifecycle finalized',
    now()
  );

  perform public.generate_employee_lifecycle_notifications(p_employee_hr_id);
end;
$$;

ALTER FUNCTION public.finalize_manual_employee_lifecycle(p_employee_hr_id text) OWNER TO postgres;

