--
-- Name: hiring_pack_custom_templates_archived_is_permanent(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hiring_pack_custom_templates_archived_is_permanent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception
    'hiring_pack_custom_templates: version % of template % is archived and cannot be deleted. A superseded paper has to stay reproducible as the document somebody signed.',
    old.version, old.key
    using errcode = 'restrict_violation';
end;
$$;

ALTER FUNCTION public.hiring_pack_custom_templates_archived_is_permanent() OWNER TO postgres;

--
-- Name: FUNCTION hiring_pack_custom_templates_archived_is_permanent(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.hiring_pack_custom_templates_archived_is_permanent() IS 'Refuses deletion of an archived custom-template version. The owner''s archive rule, enforced in the database because a revoke does not bind the table owner and every write path here runs as owner or service_role.';

--
-- Name: hiring_pack_document_field_history_is_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hiring_pack_document_field_history_is_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception
    'hiring_pack_document_field_history is append-only: % is refused. It is the only record of what a field used to print.',
    tg_op
    using errcode = 'restrict_violation';
  return null;
end;
$$;

ALTER FUNCTION public.hiring_pack_document_field_history_is_append_only() OWNER TO postgres;

--
-- Name: FUNCTION hiring_pack_document_field_history_is_append_only(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.hiring_pack_document_field_history_is_append_only() IS 'Refuses update, delete and truncate on the field history. A trigger rather than a revoke because neither a revoke nor a row trigger binds the table OWNER, and TRUNCATE fires no row triggers at all — so the three verbs need a row trigger and a statement-level BEFORE TRUNCATE trigger between them.';

--
-- Name: hiring_pack_document_field_history_record(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hiring_pack_document_field_history_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.hiring_pack_document_field_history (
    field_id, document, template_version_id, employee_hr_id, default_key, action,
    hidden, page, anchor_selector, anchor_dx, anchor_dy,
    x, y, w, h, align, font_size, source_kind, value_key, literal_text,
    was_updated_at, was_updated_by_hr_id, changed_by_hr_id
  ) values (
    old.id, old.document, old.template_version_id, old.employee_hr_id, old.default_key,
    lower(tg_op),
    old.hidden, old.page, old.anchor_selector, old.anchor_dx, old.anchor_dy,
    old.x, old.y, old.w, old.h, old.align, old.font_size,
    old.source_kind, old.value_key, old.literal_text,
    old.updated_at, old.updated_by_hr_id,
    case when tg_op = 'UPDATE' then new.updated_by_hr_id else null end
  );
  return null;
end;
$$;

ALTER FUNCTION public.hiring_pack_document_field_history_record() OWNER TO postgres;

--
-- Name: FUNCTION hiring_pack_document_field_history_record(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.hiring_pack_document_field_history_record() IS 'Writes the superseded state of a hiring-pack field row into hiring_pack_document_field_history. AFTER trigger, so recording can never block an edit. SECURITY DEFINER so the history is written even where the caller could not insert into it directly — which is every caller, since the table takes no writes from anyone but this function.';

--
-- Name: hiring_pack_replace_custom_template(uuid, text, text, text, text, smallint, text, numeric, numeric, text[], jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hiring_pack_replace_custom_template(p_key uuid, p_name text, p_name_ar text, p_group text, p_note text, p_default_copies smallint, p_print_sides text, p_page_width_pt numeric, p_page_height_pt numeric, p_printable_by_roles text[], p_pages jsonb, p_actor_hr_id text) RETURNS TABLE(new_version_id uuid, new_version integer, archived_version_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_current public.hiring_pack_custom_templates%rowtype;
  v_new_id uuid := gen_random_uuid();
begin
  if p_pages is null or jsonb_typeof(p_pages) <> 'array' or jsonb_array_length(p_pages) = 0 then
    raise exception 'hiring_pack_replace_custom_template: a new version needs at least one page.'
      using errcode = 'invalid_parameter_value';
  end if;

  select * into v_current
    from public.hiring_pack_custom_templates
   where key = p_key and status = 'current'
   for update;

  if not found then
    raise exception
      'hiring_pack_replace_custom_template: template % has no current version to replace. It may have just been replaced by somebody else.',
      p_key
      using errcode = 'no_data_found';
  end if;

  update public.hiring_pack_custom_templates
     set status = 'archived',
         superseded_on = (now() at time zone 'Africa/Cairo')::date,
         superseded_by = v_new_id,
         updated_by_hr_id = p_actor_hr_id
   where id = v_current.id;

  insert into public.hiring_pack_custom_templates (
    id, key, name, name_ar, document_group, note,
    default_copies, print_sides,
    page_width_pt, page_height_pt,
    printable_by_roles, applies_to,
    status, version,
    created_by_hr_id, updated_by_hr_id
  ) values (
    v_new_id, p_key, p_name, p_name_ar, p_group, p_note,
    p_default_copies, p_print_sides,
    p_page_width_pt, p_page_height_pt,
    p_printable_by_roles,
    v_current.applies_to,
    'current', v_current.version + 1,
    p_actor_hr_id, p_actor_hr_id
  );

  insert into public.hiring_pack_custom_template_pages (
    template_id, page_index, storage_path, content_type, size_bytes, width_px, height_px
  )
  select v_new_id,
         (page ->> 'page_index')::integer,
         page ->> 'storage_path',
         page ->> 'content_type',
         (page ->> 'size_bytes')::integer,
         (page ->> 'width_px')::integer,
         (page ->> 'height_px')::integer
    from jsonb_array_elements(p_pages) as page;

  return query select v_new_id, v_current.version + 1, v_current.id;
end;
$$;

ALTER FUNCTION public.hiring_pack_replace_custom_template(p_key uuid, p_name text, p_name_ar text, p_group text, p_note text, p_default_copies smallint, p_print_sides text, p_page_width_pt numeric, p_page_height_pt numeric, p_printable_by_roles text[], p_pages jsonb, p_actor_hr_id text) OWNER TO postgres;

--
-- Name: FUNCTION hiring_pack_replace_custom_template(p_key uuid, p_name text, p_name_ar text, p_group text, p_note text, p_default_copies smallint, p_print_sides text, p_page_width_pt numeric, p_page_height_pt numeric, p_printable_by_roles text[], p_pages jsonb, p_actor_hr_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.hiring_pack_replace_custom_template(p_key uuid, p_name text, p_name_ar text, p_group text, p_note text, p_default_copies smallint, p_print_sides text, p_page_width_pt numeric, p_page_height_pt numeric, p_printable_by_roles text[], p_pages jsonb, p_actor_hr_id text) IS 'Replaces a company template''s artwork: archives the current version and inserts the next one with its pages, in ONE transaction. The partial unique index, the archived-has-successor check and the deferred superseded_by foreign key are mutually blocking, so this cannot be done through separate PostgREST calls. Returns the new version''s id, its number, and the id of the version it archived.';

--
-- Name: import_marketing_request_atomic(jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_marketing_request_atomic(p_request jsonb, p_products jsonb DEFAULT '[]'::jsonb, p_pharmacies jsonb DEFAULT '[]'::jsonb, p_steps jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid;
begin
  insert into marketing_requests (
    request_code, requester_hr_id, customer_id, request_type_id, other_request_type,
    request_date, pay_date, roi_duration_months, estimated_cost, expected_roi_value,
    roi_status, notes, status, submitted_at, approved_at, created_by_hr_id, updated_by_hr_id
  )
  select
    r.request_code, r.requester_hr_id, r.customer_id, r.request_type_id, r.other_request_type,
    r.request_date, r.pay_date,
    coalesce(r.roi_duration_months, 1), coalesce(r.estimated_cost, 0), coalesce(r.expected_roi_value, 0),
    coalesce(nullif(r.roi_status, ''), 'not_calculated'), r.notes,
    coalesce(nullif(r.status, ''), 'draft'),
    r.submitted_at, r.approved_at, r.created_by_hr_id, r.updated_by_hr_id
  from jsonb_to_record(p_request) as r(
    request_code text, requester_hr_id text, customer_id uuid, request_type_id bigint, other_request_type text,
    request_date date, pay_date date, roi_duration_months integer, estimated_cost numeric, expected_roi_value numeric,
    roi_status text, notes text, status text, submitted_at timestamptz, approved_at timestamptz,
    created_by_hr_id text, updated_by_hr_id text
  )
  returning id into v_request_id;

  if jsonb_array_length(coalesce(p_products, '[]'::jsonb)) > 0 then
    insert into marketing_request_products (
      request_id, product_id, product_name_snapshot, factory_price_snapshot, forecast_quantity, value_share
    )
    select
      v_request_id, p.product_id, p.product_name_snapshot,
      coalesce(p.factory_price_snapshot, 0), coalesce(p.forecast_quantity, 0), coalesce(p.value_share, 0)
    from jsonb_to_recordset(p_products) as p(
      product_id bigint, product_name_snapshot text, factory_price_snapshot numeric,
      forecast_quantity numeric, value_share numeric
    );
  end if;

  if jsonb_array_length(coalesce(p_pharmacies, '[]'::jsonb)) > 0 then
    insert into marketing_request_pharmacies (
      request_id, distributor_code_id, tracking_status
    )
    select
      v_request_id, ph.distributor_code_id,
      coalesce(nullif(ph.tracking_status, ''), 'pending_validation')
    from jsonb_to_recordset(p_pharmacies) as ph(
      distributor_code_id uuid, tracking_status text
    );
  end if;

  if jsonb_array_length(coalesce(p_steps, '[]'::jsonb)) > 0 then
    insert into marketing_request_approval_steps (
      request_id, workflow_step_id, sequence, step_code, step_name, assigned_role,
      status, decision_at, decision_by_hr_id, decision_note
    )
    select
      v_request_id, s.workflow_step_id, s.sequence, s.step_code, s.step_name, s.assigned_role,
      coalesce(nullif(s.status, ''), 'pending'), s.decision_at, s.decision_by_hr_id, s.decision_note
    from jsonb_to_recordset(p_steps) as s(
      workflow_step_id bigint, sequence integer, step_code text, step_name text, assigned_role text,
      status text, decision_at timestamptz, decision_by_hr_id text, decision_note text
    );
  end if;

  return v_request_id;
end;
$$;

ALTER FUNCTION public.import_marketing_request_atomic(p_request jsonb, p_products jsonb, p_pharmacies jsonb, p_steps jsonb) OWNER TO postgres;

--
-- Name: FUNCTION import_marketing_request_atomic(p_request jsonb, p_products jsonb, p_pharmacies jsonb, p_steps jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.import_marketing_request_atomic(p_request jsonb, p_products jsonb, p_pharmacies jsonb, p_steps jsonb) IS 'Atomically inserts one bulk-imported marketing request plus its products, pharmacies, and approval steps in a single transaction (all-or-nothing per row). Called by executeBulkImport via the service-role client. Generated columns (required_roi_value, roi_coverage_ratio, expected_value) are intentionally not written.';

