--
-- Name: note_database_restart(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.note_database_restart() RETURNS TABLE(current_start_at timestamp with time zone, previous_start_at timestamp with time zone, is_new boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_start timestamptz := pg_catalog.pg_postmaster_start_time();
  v_prev timestamptz;
  v_inserted timestamptz;
begin
  select max(r.postmaster_start_at) into v_prev
    from public.database_restarts r
   where r.postmaster_start_at < v_start;

  insert into public.database_restarts (postmaster_start_at)
  values (v_start)
  on conflict (postmaster_start_at) do nothing
  returning database_restarts.postmaster_start_at into v_inserted;

  return query select v_start, v_prev, v_inserted is not null;
end;
$$;

ALTER FUNCTION public.note_database_restart() OWNER TO postgres;

--
-- Name: FUNCTION note_database_restart(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.note_database_restart() IS 'Records the live pg_postmaster_start_time() and reports whether it moved since the last call. Called every 15 minutes by the job-heartbeat sweep; service_role only.';

--
-- Name: phoenix_crm_add_pharmacy(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_add_pharmacy(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_name text := nullif(btrim(regexp_replace(coalesce(p ->> 'name', ''), '\s+', ' ', 'g')), '');
  v_from text := coalesce(p ->> 'from', 'list');
  v_phone text := nullif(regexp_replace(coalesce(p ->> 'phone', ''), '\s+', '', 'g'), '');
  v_pin jsonb := case when jsonb_typeof(p -> 'pin') = 'object' then p -> 'pin' else null end;
  v_resolved_id uuid;
  v_existing public.phoenix_crm_customers;
  v_added public.phoenix_crm_customers;
begin
  if v_seat is null or v_line is null or v_actor is null or v_name is null
    or char_length(v_name) > 120
    or v_from not in ('list', 'visit') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_phone is not null and v_phone !~ '^\+?[0-9]{7,15}$' then
    raise exception 'phoenix_crm:bad_phone';
  end if;
  if v_pin is not null and (v_pin -> 'lat') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  begin
    v_resolved_id := nullif(trim(coalesce(p ->> 'existing_customer_id', '')), '')::uuid;
  exception when invalid_text_representation then
    v_resolved_id := null;
  end;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm_add_pharmacy|' || v_seat || '|' || v_is_test::text));

  if v_resolved_id is not null then
    select c.* into v_existing
    from public.phoenix_crm_customers c
    where c.id = v_resolved_id
      and c.seat_id = v_seat
      and c.is_test = v_is_test
      and c.list_type = 'Pharmacy'
      and c.status in ('active', 'pending', 'outside');
  end if;

  if v_existing.id is null then
    select c.* into v_existing
    from public.phoenix_crm_customers c
    where c.seat_id = v_seat
      and c.is_test = v_is_test
      and c.list_type = 'Pharmacy'
      and c.status in ('active', 'pending', 'outside')
      and lower(btrim(regexp_replace(c.name, '\s+', ' ', 'g'))) = lower(v_name)
    order by (c.status = 'active') desc, c.id
    limit 1;
  end if;

  if v_existing.id is not null then
    if (v_phone is not null and v_existing.phone is null) or (v_pin is not null and v_existing.pharmacy_pin_lat is null) then
      update public.phoenix_crm_customers c
      set phone = case when v_phone is not null and c.phone is null then v_phone else c.phone end,
          pharmacy_pin_lat = case when v_pin is not null and c.pharmacy_pin_lat is null then (v_pin ->> 'lat')::double precision else c.pharmacy_pin_lat end,
          pharmacy_pin_lon = case when v_pin is not null and c.pharmacy_pin_lat is null then (v_pin ->> 'lon')::double precision else c.pharmacy_pin_lon end,
          pharmacy_pin_accuracy_meters = case when v_pin is not null and c.pharmacy_pin_lat is null then (v_pin ->> 'accuracy_meters')::numeric else c.pharmacy_pin_accuracy_meters end,
          pharmacy_pin_captured_at = case when v_pin is not null and c.pharmacy_pin_lat is null then coalesce((v_pin ->> 'captured_at')::timestamptz, now()) else c.pharmacy_pin_captured_at end,
          pharmacy_pin_captured_by_hr_id = case when v_pin is not null and c.pharmacy_pin_lat is null then v_actor else c.pharmacy_pin_captured_by_hr_id end,
          pharmacy_pin_address = case when v_pin is not null and c.pharmacy_pin_lat is null then left(v_pin ->> 'address', 400) else c.pharmacy_pin_address end,
          pharmacy_pin_governorate = case when v_pin is not null and c.pharmacy_pin_lat is null then left(v_pin ->> 'governorate', 120) else c.pharmacy_pin_governorate end,
          pharmacy_pin_area_code = case when v_pin is not null and c.pharmacy_pin_lat is null then left(v_pin ->> 'area_code', 40) else c.pharmacy_pin_area_code end,
          pharmacy_pin_area_name = case when v_pin is not null and c.pharmacy_pin_lat is null then left(v_pin ->> 'area_name', 120) else c.pharmacy_pin_area_name end,
          pharmacy_pin_brick_id = case when v_pin is not null and c.pharmacy_pin_lat is null then left(v_pin ->> 'brick_id', 40) else c.pharmacy_pin_brick_id end,
          pharmacy_pin_brick_name = case when v_pin is not null and c.pharmacy_pin_lat is null then left(v_pin ->> 'brick_name', 120) else c.pharmacy_pin_brick_name end,
          pharmacy_pin_brick_distance_km = case when v_pin is not null and c.pharmacy_pin_lat is null then (v_pin ->> 'brick_distance_km')::numeric else c.pharmacy_pin_brick_distance_km end,
          pharmacy_pin_brick_lookup = case when v_pin is not null and c.pharmacy_pin_lat is null then v_pin ->> 'brick_lookup' else c.pharmacy_pin_brick_lookup end,
          updated_at = now()
      where c.id = v_existing.id
      returning c.* into v_existing;
    end if;
    return jsonb_build_object('customer_id', v_existing.id, 'customer_name', v_existing.name, 'created', false);
  end if;

  insert into public.phoenix_crm_customers (
    seat_id, line_code, list_type, name, origin, status, created_by_hr_id, is_test, intake_note, phone,
    pharmacy_pin_lat, pharmacy_pin_lon, pharmacy_pin_accuracy_meters, pharmacy_pin_captured_at,
    pharmacy_pin_captured_by_hr_id, pharmacy_pin_address, pharmacy_pin_governorate,
    pharmacy_pin_area_code, pharmacy_pin_area_name, pharmacy_pin_brick_id, pharmacy_pin_brick_name,
    pharmacy_pin_brick_distance_km, pharmacy_pin_brick_lookup
  )
  values (
    v_seat, v_line, 'Pharmacy', v_name, 'new', 'pending', v_actor, v_is_test,
    case when v_from = 'visit' then 'Added by the rep on Pharmacy visit.' else 'Added by the rep on the List.' end,
    v_phone,
    (v_pin ->> 'lat')::double precision,
    (v_pin ->> 'lon')::double precision,
    (v_pin ->> 'accuracy_meters')::numeric,
    case when v_pin is null then null else coalesce((v_pin ->> 'captured_at')::timestamptz, now()) end,
    case when v_pin is null then null else v_actor end,
    left(v_pin ->> 'address', 400),
    left(v_pin ->> 'governorate', 120),
    left(v_pin ->> 'area_code', 40),
    left(v_pin ->> 'area_name', 120),
    left(v_pin ->> 'brick_id', 40),
    left(v_pin ->> 'brick_name', 120),
    (v_pin ->> 'brick_distance_km')::numeric,
    v_pin ->> 'brick_lookup'
  )
  returning * into v_added;

  return jsonb_build_object('customer_id', v_added.id, 'customer_name', v_added.name, 'created', true);
end;
$_$;

ALTER FUNCTION public.phoenix_crm_add_pharmacy(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_add_place(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_add_place(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_hold jsonb := case when jsonb_typeof(p -> 'hold_review') = 'object' then p -> 'hold_review' end;
  v_google jsonb := case when jsonb_typeof(p -> 'google') = 'object' then p -> 'google' end;
  v_review_id uuid;
  v_customer public.phoenix_crm_customers%rowtype;
  v_place jsonb;
begin
  if v_seat is null or v_actor is null or nullif(p ->> 'customer_id', '') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = (p ->> 'customer_id')::uuid
    and c.seat_id = v_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.status not in ('active', 'outside') then
    raise exception 'phoenix_crm:customer_dropped';
  end if;
  if (select count(*) from public.phoenix_crm_places pl where pl.customer_id = v_customer.id and pl.status = 'active') >= 5 then
    raise exception 'phoenix_crm:too_many_places';
  end if;

  v_place := public.phoenix_crm_insert_place(v_customer.id, v_seat, v_actor, v_is_test, p -> 'place');

  insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer.id, (v_place ->> 'place_id')::uuid, 'place_added', v_actor,
    case when v_google is not null then jsonb_build_object('google', v_google) else '{}'::jsonb end,
    v_is_test
  );

  if v_hold is not null then
    insert into public.phoenix_crm_validation_reviews (seat_id, customer_id, place_id, is_test, kind, google, created_by_hr_id)
    values (v_seat, v_customer.id, (v_place ->> 'place_id')::uuid, v_is_test, 'added_place', v_hold, v_actor)
    returning id into v_review_id;
    insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
    values (v_seat, v_customer.id, (v_place ->> 'place_id')::uuid, 'validation_held', v_actor, jsonb_build_object('kind', 'added_place'), v_is_test);
  end if;

  return v_place || jsonb_build_object(
    'customer_id', v_customer.id,
    'customer_name', v_customer.name,
    'held', v_hold is not null,
    'review_id', v_review_id
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_add_place(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_admin_delete(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_admin_delete(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind text := nullif(trim(coalesce(p ->> 'kind', '')), '');
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_seat text;
  v_record jsonb;
  v_children jsonb := '{}'::jsonb;
  v_ids uuid[];
  v_request_ids uuid[];
  v_week uuid;
  v_week_result jsonb;
  v_weeks jsonb := '[]'::jsonb;
begin
  if v_kind is null or v_id is null or v_actor is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  if v_kind = 'rep_plan' then
    select to_jsonb(x), x.seat_id into v_record, v_seat
    from public.phoenix_crm_plans x where x.id = v_id and x.is_test = v_is_test for update;
    if v_record is null then raise exception 'phoenix_crm:plan_not_found'; end if;
    perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

    select coalesce(array_agg(r.id), '{}') into v_request_ids
    from public.phoenix_crm_plan_edit_requests r where r.plan_id = v_id;

    v_children := jsonb_build_object(
      'items', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_plan_items t where t.plan_id = v_id),
      'activities', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_plan_activities t where t.plan_id = v_id),
      'day_starts', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_plan_day_starts t where t.plan_id = v_id),
      'events', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_plan_events t where t.plan_id = v_id),
      'edit_requests', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_plan_edit_requests t where t.plan_id = v_id),
      'edit_request_events', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_plan_edit_request_events t where t.request_id = any (v_request_ids)),
      'team_start_notices', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_team_start_notices t where t.plan_id = v_id)
    );
    insert into public.phoenix_crm_admin_deletions (kind, subject_id, seat_id, deleted_by_hr_id, is_test, record, children)
    values (v_kind, v_id, v_seat, v_actor, v_is_test, v_record, v_children);

    delete from public.phoenix_crm_plan_edit_request_events where request_id = any (v_request_ids);
    delete from public.phoenix_crm_plan_edit_requests where plan_id = v_id;
    delete from public.phoenix_crm_plan_items where plan_id = v_id;
    delete from public.phoenix_crm_plan_activities where plan_id = v_id;
    delete from public.phoenix_crm_plan_day_starts where plan_id = v_id;
    delete from public.phoenix_crm_plan_events where plan_id = v_id;
    delete from public.phoenix_crm_team_start_notices where plan_id = v_id;
    delete from public.phoenix_crm_plans where id = v_id;

    return jsonb_build_object('deleted', true, 'kind', v_kind, 'id', v_id, 'week_start', v_record ->> 'week_start',
      'edit_request_ids', to_jsonb(v_request_ids));

  elsif v_kind = 'manager_plan' then
    select to_jsonb(x), x.manager_seat_id into v_record, v_seat
    from public.phoenix_crm_manager_plans x where x.id = v_id and x.is_test = v_is_test for update;
    if v_record is null then raise exception 'phoenix_crm:plan_not_found'; end if;
    perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || coalesce(v_seat, '')));

    select coalesce(array_agg(r.id), '{}') into v_request_ids
    from public.phoenix_crm_manager_plan_edit_requests r where r.plan_id = v_id;

    v_children := jsonb_build_object(
      'slots', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_manager_plan_slots t where t.plan_id = v_id),
      'slot_customers', (
        select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb)
        from public.phoenix_crm_manager_plan_customers c
        join public.phoenix_crm_manager_plan_slots s on s.id = c.slot_id
        where s.plan_id = v_id),
      'events', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_manager_plan_events t where t.plan_id = v_id),
      'edit_requests', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_manager_plan_edit_requests t where t.plan_id = v_id)
    );
    insert into public.phoenix_crm_admin_deletions (kind, subject_id, seat_id, deleted_by_hr_id, is_test, record, children)
    values (v_kind, v_id, v_seat, v_actor, v_is_test, v_record, v_children);

    -- The slots, their customers, the events and the edit requests cascade from the plan; a manager's visit
    -- that was made against a slot keeps its row and loses only the link (ON DELETE SET NULL).
    delete from public.phoenix_crm_manager_plans where id = v_id;

    return jsonb_build_object('deleted', true, 'kind', v_kind, 'id', v_id, 'week_start', v_record ->> 'week_start',
      'edit_request_ids', to_jsonb(v_request_ids));

  elsif v_kind = 'visit' then
    select to_jsonb(x), x.seat_id into v_record, v_seat
    from public.phoenix_crm_visits x where x.id = v_id and x.is_test = v_is_test for update;
    if v_record is null then raise exception 'phoenix_crm:visit_not_found'; end if;
    perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

    -- The visit and any visit linked from it: that foreign key cascades, so they go together or not at all.
    with recursive family as (
      select v.id from public.phoenix_crm_visits v where v.id = v_id
      union
      select l.id from public.phoenix_crm_visits l join family f on l.linked_from_visit_id = f.id
    )
    select array_agg(f.id) into v_ids from family f;

    v_children := jsonb_build_object(
      'linked_visits', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_visits t where t.id = any (v_ids) and t.id <> v_id),
      'unplanned', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_unplanned_visits t where t.visit_id = any (v_ids)),
      'unplanned_events', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_unplanned_visit_events t where t.visit_id = any (v_ids)),
      'edits', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_visit_edits t where t.visit_id = any (v_ids)),
      'capture_provenance', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_visit_capture_provenance t where t.visit_id = any (v_ids)),
      'recordings', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_visit_recordings t where t.visit_id = any (v_ids)),
      'unlinked_asks', (select coalesce(jsonb_agg(t.id), '[]'::jsonb) from public.phoenix_crm_visit_asks t where t.visit_id = any (v_ids)),
      'unlinked_double_requests', (select coalesce(jsonb_agg(t.id), '[]'::jsonb) from public.phoenix_crm_double_visit_requests t where t.visit_id = any (v_ids))
    );
    insert into public.phoenix_crm_admin_deletions (kind, subject_id, seat_id, deleted_by_hr_id, is_test, record, children)
    values (v_kind, v_id, v_seat, v_actor, v_is_test, v_record, v_children);

    update public.phoenix_crm_visit_asks set visit_id = null where visit_id = any (v_ids);
    update public.phoenix_crm_double_visit_requests set visit_id = null where visit_id = any (v_ids);
    delete from public.phoenix_crm_unplanned_visit_events where visit_id = any (v_ids);
    delete from public.phoenix_crm_unplanned_visits where visit_id = any (v_ids);
    delete from public.phoenix_crm_visit_edits where visit_id = any (v_ids);
    delete from public.phoenix_crm_visit_capture_provenance where visit_id = any (v_ids);
    delete from public.phoenix_crm_visit_recordings where visit_id = any (v_ids);
    delete from public.phoenix_crm_visits where id = any (v_ids);

    return jsonb_build_object('deleted', true, 'kind', v_kind, 'id', v_id, 'visit_ids', to_jsonb(v_ids),
      'visit_date', v_record ->> 'visit_date');

  elsif v_kind = 'day_activity' then
    select to_jsonb(x), x.seat_id into v_record, v_seat
    from public.phoenix_crm_day_activities x where x.id = v_id and x.is_test = v_is_test for update;
    if v_record is null then raise exception 'phoenix_crm:activity_not_found'; end if;
    perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

    insert into public.phoenix_crm_admin_deletions (kind, subject_id, seat_id, deleted_by_hr_id, is_test, record, children)
    values (v_kind, v_id, v_seat, v_actor, v_is_test, v_record, v_children);
    delete from public.phoenix_crm_day_activities where id = v_id;

    return jsonb_build_object('deleted', true, 'kind', v_kind, 'id', v_id, 'activity_date', v_record ->> 'activity_date');

  elsif v_kind = 'monthly_plan' then
    select to_jsonb(x), x.seat_id into v_record, v_seat
    from public.phoenix_crm_monthly_plans x where x.id = v_id and x.is_test = v_is_test for update;
    if v_record is null then raise exception 'phoenix_crm:plan_not_found'; end if;
    perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

    -- The month's weeks: a field-week belongs to the month its Saturday (its week_start) falls in.
    select coalesce(array_agg(pl.id order by pl.week_start), '{}') into v_ids
    from public.phoenix_crm_plans pl
    where pl.seat_id = v_seat
      and pl.is_test = v_is_test
      and pl.week_start >= (v_record ->> 'month_start')::date
      and pl.week_start < ((v_record ->> 'month_start')::date + interval '1 month')::date;

    v_children := jsonb_build_object(
      'events', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.phoenix_crm_monthly_plan_events t where t.monthly_plan_id = v_id),
      'week_plan_ids', to_jsonb(v_ids)
    );
    insert into public.phoenix_crm_admin_deletions (kind, subject_id, seat_id, deleted_by_hr_id, is_test, record, children)
    values (v_kind, v_id, v_seat, v_actor, v_is_test, v_record, v_children);

    -- Each week goes through the very same deletion, so it keeps its own copy of itself and its children.
    foreach v_week in array v_ids loop
      v_week_result := public.phoenix_crm_admin_delete(
        jsonb_build_object('kind', 'rep_plan', 'id', v_week, 'actor_hr_id', v_actor, 'is_test', v_is_test));
      v_weeks := v_weeks || jsonb_build_array(
        jsonb_build_object('id', v_week, 'edit_request_ids', coalesce(v_week_result -> 'edit_request_ids', '[]'::jsonb)));
    end loop;

    delete from public.phoenix_crm_monthly_plan_events where monthly_plan_id = v_id;
    delete from public.phoenix_crm_monthly_plans where id = v_id;

    return jsonb_build_object('deleted', true, 'kind', v_kind, 'id', v_id, 'month_start', v_record ->> 'month_start',
      'weeks', v_weeks);

  elsif v_kind = 'manager_visit' then
    select to_jsonb(x), x.manager_seat_id into v_record, v_seat
    from public.phoenix_crm_manager_visits x where x.id = v_id and x.is_test = v_is_test for update;
    if v_record is null then raise exception 'phoenix_crm:visit_not_found'; end if;
    perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || coalesce(v_seat, '')));

    -- Nothing hangs off a manager's own visit: it is a row on its own.
    insert into public.phoenix_crm_admin_deletions (kind, subject_id, seat_id, deleted_by_hr_id, is_test, record, children)
    values (v_kind, v_id, v_seat, v_actor, v_is_test, v_record, v_children);
    delete from public.phoenix_crm_manager_visits where id = v_id;

    return jsonb_build_object('deleted', true, 'kind', v_kind, 'id', v_id, 'visit_date', v_record ->> 'visit_date');
  end if;

  raise exception 'phoenix_crm:bad_input';
end;
$$;

ALTER FUNCTION public.phoenix_crm_admin_delete(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_admin_edit_visit(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_admin_edit_visit(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'visit_id', '')::uuid;
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  -- Who was on the visit changes ONLY when the caller says so; otherwise the three slots below are
  -- ignored, so a typo in a comment can never re-check (or move) anybody.
  v_change_who boolean := coalesce((p ->> 'change_who')::boolean, false);
  v_kind text := coalesce(p ->> 'kind', '');
  v_manager text := upper(nullif(trim(coalesce(p ->> 'manager_hr_id', '')), ''));
  v_senior text := upper(nullif(trim(coalesce(p ->> 'senior_hr_id', '')), ''));
  v_product_manager text := upper(nullif(trim(coalesce(p ->> 'product_manager_hr_id', '')), ''));
  v_comment text := nullif(trim(coalesce(p ->> 'comment', '')), '');
  v_products text[];
  v_visit public.phoenix_crm_visits%rowtype;
  v_new_kind text;
  v_new_manager text;
  v_new_senior text;
  v_new_product_manager text;
  v_linked_before jsonb;
  -- Everyone on the visit, the fixed places and phoenix_crm_visit_companions together, sorted.
  v_before_set text[];
  v_after_set text[];
begin
  if v_id is null or v_seat is null or v_actor is null
    or v_comment is null or char_length(v_comment) > 1000 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select array_agg(trim(e.value) order by e.ordinality)
  into v_products
  from jsonb_array_elements_text(coalesce(p -> 'products', '[]'::jsonb)) with ordinality as e (value, ordinality)
  where nullif(trim(e.value), '') is not null;
  if v_products is null or cardinality(v_products) > 12 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  -- The same per-territory lock the rep's own save takes, so a correction and a save cannot interleave.
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select v.* into v_visit
  from public.phoenix_crm_visits v
  where v.id = v_id
    and v.seat_id = v_seat
    and v.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:visit_not_found';
  end if;

  v_before_set := public.phoenix_crm_visit_companion_ids(v_id);
  v_after_set := v_before_set;
  v_new_kind := v_visit.kind;
  v_new_manager := v_visit.manager_hr_id;
  v_new_senior := v_visit.senior_hr_id;
  v_new_product_manager := v_visit.product_manager_hr_id;

  if v_change_who then
    -- Only a visit the rep entered himself, or the Super Admin entered for him. A manager's own visit
    -- keeps its people: re-picking them would turn his record into one that reads as entered by
    -- somebody who was not on it.
    if v_visit.rep_hr_id is null
      or not (v_visit.entered_by_hr_id = v_visit.rep_hr_id or v_visit.capture_source = 'admin') then
      raise exception 'phoenix_crm:visit_people_fixed';
    end if;

    -- The shape `phoenix_crm_visits_participants` holds, for a visit that has a rep on it, refused here
    -- as a sentence rather than as a constraint violation.
    if not (
      (v_kind = 'single' and v_manager is null and v_senior is null and v_product_manager is null)
      or (v_kind = 'double' and v_manager is not null and v_senior is null and v_product_manager is null)
      or (v_kind = 'chain' and v_manager is not null and (v_senior is not null or v_product_manager is not null))
      or (v_kind = 'product_manager' and v_manager is null and v_senior is null and v_product_manager is not null)
    ) or v_manager = v_visit.rep_hr_id
      or v_senior = v_visit.rep_hr_id
      or v_senior = v_manager
      or v_product_manager = v_visit.rep_hr_id then
      raise exception 'phoenix_crm:bad_participants';
    end if;

    v_new_kind := v_kind;
    v_new_manager := v_manager;
    v_new_senior := v_senior;
    v_new_product_manager := v_product_manager;
    select coalesce(array_agg(distinct s.hr_id order by s.hr_id), '{}'::text[])
    into v_after_set
    from (
      select upper(btrim(h)) as hr_id
      from unnest(array[v_manager, v_senior, v_product_manager]) as h
      where nullif(btrim(coalesce(h, '')), '') is not null
      union
      select upper(btrim(e ->> 'hr_id'))
      from jsonb_array_elements(case when jsonb_typeof(p -> 'companions') = 'array' then p -> 'companions' else '[]'::jsonb end) as e
      where jsonb_typeof(e) = 'object'
        and nullif(btrim(coalesce(e ->> 'hr_id', '')), '') is not null
        and upper(btrim(e ->> 'hr_id')) <> upper(btrim(v_visit.rep_hr_id))
    ) s;
  end if;

  -- Nothing different: no copy, no write, and the caller is told so.
  if v_new_kind is not distinct from v_visit.kind
    and v_new_manager is not distinct from v_visit.manager_hr_id
    and v_new_senior is not distinct from v_visit.senior_hr_id
    and v_new_product_manager is not distinct from v_visit.product_manager_hr_id
    and v_after_set is not distinct from v_before_set
    and v_products is not distinct from v_visit.products
    and v_comment is not distinct from v_visit.comment then
    return jsonb_build_object('visit_id', v_id, 'changed', false);
  end if;

  -- The pharmacy visits this one filed carry the same products it does, so they follow it.
  select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'products', to_jsonb(l.products)) order by l.id), '[]'::jsonb)
  into v_linked_before
  from public.phoenix_crm_visits l
  where l.linked_from_visit_id = v_id;

  -- The copy first, so nothing is overwritten that is not already kept.
  insert into public.phoenix_crm_visit_edits (
    visit_id, seat_id, customer_id, visit_date, edited_by_hr_id, is_test, before_edit, after_edit
  )
  values (
    v_visit.id, v_visit.seat_id, v_visit.customer_id, v_visit.visit_date, v_actor, v_visit.is_test,
    jsonb_build_object(
      'kind', v_visit.kind,
      'manager_hr_id', v_visit.manager_hr_id,
      'senior_hr_id', v_visit.senior_hr_id,
      'product_manager_hr_id', v_visit.product_manager_hr_id,
      'companion_hr_ids', to_jsonb(v_before_set),
      'products', to_jsonb(v_visit.products),
      'comment', v_visit.comment,
      'linked_pharmacy_visits', v_linked_before
    ),
    jsonb_build_object(
      'kind', v_new_kind,
      'manager_hr_id', v_new_manager,
      'senior_hr_id', v_new_senior,
      'product_manager_hr_id', v_new_product_manager,
      'companion_hr_ids', to_jsonb(v_after_set),
      'products', to_jsonb(v_products),
      'comment', v_comment
    )
  );

  update public.phoenix_crm_visits
  set kind = v_new_kind,
      manager_hr_id = v_new_manager,
      senior_hr_id = v_new_senior,
      product_manager_hr_id = v_new_product_manager,
      products = v_products,
      comment = v_comment
  where id = v_id;

  if v_change_who then
    perform public.phoenix_crm_set_visit_companions(v_id, p -> 'companions');
    -- A manager added here may be the one this visit's off-plan approval waits for; his step is then
    -- unavailable and it goes to the SFE, as it would have had the rep recorded him (owner, 2026-10-12).
    perform public.phoenix_crm_unplanned_route_past_a_reviewer_on_the_visit(v_id);
  end if;

  update public.phoenix_crm_visits
  set products = v_products
  where linked_from_visit_id = v_id
    and products is distinct from v_products;

  return jsonb_build_object('visit_id', v_id, 'changed', true);
end;
$$;

ALTER FUNCTION public.phoenix_crm_admin_edit_visit(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_admin_enter_visit(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_admin_enter_visit(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_rep text := upper(nullif(trim(coalesce(p ->> 'rep_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_date date := nullif(p ->> 'visit_date', '')::date;
  -- Minutes past midnight, Cairo, on the chosen day; null = he gave no time, and noon stands in.
  v_minute integer := nullif(p ->> 'visit_minute', '')::integer;
  -- HIS choice, never inferred from the plan ("I choose planned or unplanned").
  v_planned boolean := (p ->> 'planned')::boolean;
  -- Single, double or chain — HIS choice too (owner, 2026-10-24). An older caller sends none: single.
  v_kind text := coalesce(nullif(trim(coalesce(p ->> 'kind', '')), ''), 'single');
  v_manager text := upper(nullif(trim(coalesce(p ->> 'manager_hr_id', '')), ''));
  v_senior text := upper(nullif(trim(coalesce(p ->> 'senior_hr_id', '')), ''));
  -- The first product-side person who came (2026-10-27); everyone past the fixed places is in
  -- phoenix_crm_visit_companions, written right after the visit.
  v_product_manager text := upper(nullif(trim(coalesce(p ->> 'product_manager_hr_id', '')), ''));
  v_comment text := nullif(trim(coalesce(p ->> 'comment', '')), '');
  v_clarification text := nullif(regexp_replace(trim(coalesce(p ->> 'unplanned_reason', '')), '\s+', ' ', 'g'), '');
  v_first_stage text := coalesce(p ->> 'unplanned_first_status', 'manager_pending');
  v_reviewer text := upper(nullif(trim(coalesce(p ->> 'reviewer_hr_id', '')), ''));
  v_products text[];
  v_existing public.phoenix_crm_visits%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  -- The visit day running now ends at 02:00 Cairo, exactly as phoenix_crm_save_visit dates a visit.
  v_running_day date := ((now() - interval '2 hours') at time zone 'Africa/Cairo')::date;
  v_captured_at timestamptz;
begin
  if v_id is null or v_seat is null or v_line is null or v_actor is null or v_rep is null
    or v_customer_id is null or v_date is null or v_planned is null
    or v_first_stage not in ('manager_pending', 'sfe_pending')
    or (v_minute is not null and (v_minute < 0 or v_minute > 1439))
    or (v_comment is not null and char_length(v_comment) > 1000)
    -- The four a rep logs himself (2026-10-27: the product side too — "Everything is applicable").
    or v_kind not in ('single', 'double', 'product_manager', 'chain')
    or (v_kind = 'single' and (v_manager is not null or v_senior is not null or v_product_manager is not null))
    or (v_kind = 'double' and (v_manager is null or v_senior is not null or v_product_manager is not null))
    or (v_kind = 'product_manager' and (v_manager is not null or v_senior is not null or v_product_manager is null))
    or (v_kind = 'chain' and (v_manager is null or (v_senior is null and v_product_manager is null)))
    or v_product_manager = v_rep then
    raise exception 'phoenix_crm:bad_input';
  end if;

  -- Anytime that has HAPPENED: a day that has not begun yet holds no visit to have missed.
  if v_date > v_running_day then
    raise exception 'phoenix_crm:future_day';
  end if;

  -- None is allowed on his entry (owner, 2026-10-24); twelve stays the most, as everywhere.
  select coalesce(array_agg(trim(e.value) order by e.ordinality), '{}'::text[])
  into v_products
  from jsonb_array_elements_text(coalesce(p -> 'products', '[]'::jsonb)) with ordinality as e (value, ordinality)
  where nullif(trim(e.value), '') is not null;
  if cardinality(v_products) > 12 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select v.* into v_existing from public.phoenix_crm_visits v where v.id = v_id;
  if found then
    -- The same entry sent twice (a dropped connection, a second press): the visit already saved answers,
    -- exactly as phoenix_crm_save_visit answers a rep's retry. Anything else under that id is refused.
    if v_existing.capture_source = 'admin'
       and v_existing.entered_by_hr_id = v_actor
       and v_existing.seat_id = v_seat
       and v_existing.customer_id = v_customer_id
       and v_existing.visit_date = v_date
       and v_existing.is_test = v_is_test then
      return jsonb_build_object(
        'id', v_existing.id,
        'visit_date', v_existing.visit_date,
        'captured_at', v_existing.captured_at,
        'customer_id', v_existing.customer_id,
        'customer_name', (select c.name from public.phoenix_crm_customers c where c.id = v_existing.customer_id),
        'list_type', v_existing.list_type,
        'kind', v_existing.kind,
        'is_unplanned', v_existing.is_unplanned,
        'unplanned_kind', v_existing.unplanned_kind,
        'capture_source', 'admin',
        'duplicate', true
      );
    end if;
    raise exception 'phoenix_crm:id_conflict';
  end if;

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id
    and c.seat_id = v_seat
    and c.is_test = v_is_test;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  -- His list: a validated customer, or one carried over and not validated yet. One met outside the list
  -- is still waiting to be admitted — his visit was saved at the door when he was validated — and one
  -- in the Archive has left the list.
  if v_customer.status = 'outside' then
    raise exception 'phoenix_crm:not_on_list';
  end if;
  if v_customer.status not in ('active', 'pending') then
    raise exception 'phoenix_crm:customer_dropped';
  end if;

  if exists (
    select 1
    from public.phoenix_crm_visits v
    where v.seat_id = v_seat
      and v.customer_id = v_customer.id
      and v.visit_date = v_date
      and v.is_test = v_is_test
  ) then
    raise exception 'phoenix_crm:already_visited';
  end if;

  if not v_planned and (v_clarification is null or char_length(v_clarification) < 10 or char_length(v_clarification) > 500) then
    raise exception 'phoenix_crm:clarification_required';
  end if;

  -- The time he gives, on the day he chose, in Cairo — noon when he gives none. A time before 02:00 is
  -- the small hours AFTER that day, which still belong to it: the visit day ends at 02:00.
  v_captured_at := (
    (v_date + case when coalesce(v_minute, 720) < 120 then 1 else 0 end)::timestamp
    + make_interval(mins => coalesce(v_minute, 720))
  ) at time zone 'Africa/Cairo';
  -- Never later than the moment it is entered: a time still ahead on today's day is today, now.
  if v_captured_at > now() then
    v_captured_at := now();
  end if;

  insert into public.phoenix_crm_visits (
    id, seat_id, line_code, customer_id, list_type, visit_date, captured_at, kind, rep_hr_id, manager_hr_id,
    senior_hr_id, product_manager_hr_id, entered_by_hr_id, products, comment, product_availability, samples_given, photo_path,
    lat, lon, accuracy_meters, place_id, distance_meters, location_flag, is_test,
    is_unplanned, unplanned_kind, capture_source, synced_at
  )
  values (
    v_id, v_seat, v_line, v_customer.id, v_customer.list_type, v_date, v_captured_at, v_kind, v_rep, v_manager,
    v_senior, v_product_manager, v_actor, v_products, v_comment, '{}'::jsonb, '{}'::jsonb, null,
    -- No reading: he was not at the door. 'no_place' says there is nothing to measure against.
    null, null, null, null, null, 'no_place', v_is_test,
    not v_planned, case when v_planned then null else 'out_of_plan' end, 'admin', now()
  );

  -- Everyone who came, BEFORE the off-plan row below: its reviewer trigger reads this list.
  perform public.phoenix_crm_set_visit_companions(v_id, p -> 'companions');

  if not v_planned then
    insert into public.phoenix_crm_unplanned_visits (
      visit_id, seat_id, line_code, rep_hr_id, entered_by_hr_id, customer_id, visit_date,
      clarification, status, manager_hr_id, is_test
    )
    values (
      v_id, v_seat, v_line, v_rep, v_actor, v_customer.id, v_date,
      v_clarification, v_first_stage, v_reviewer, v_is_test
    );
    insert into public.phoenix_crm_unplanned_visit_events (visit_id, event_type, actor_hr_id, to_status, version, note)
    values (v_id, 'raised', v_actor, v_first_stage, 1, v_clarification);
  end if;

  return jsonb_build_object(
    'id', v_id,
    'visit_date', v_date,
    'captured_at', v_captured_at,
    'customer_id', v_customer.id,
    'customer_name', v_customer.name,
    'list_type', v_customer.list_type,
    'kind', v_kind,
    'is_unplanned', not v_planned,
    'unplanned_kind', case when v_planned then null else 'out_of_plan' end,
    'capture_source', 'admin',
    'duplicate', false
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_admin_enter_visit(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_admin_remove_visit(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_admin_remove_visit(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'visit_id', '')::uuid;
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_visit public.phoenix_crm_visits%rowtype;
  v_unplanned jsonb;
  v_events jsonb;
begin
  if v_id is null or v_seat is null or v_actor is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select v.* into v_visit
  from public.phoenix_crm_visits v
  where v.id = v_id
    and v.seat_id = v_seat
    and v.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:visit_not_found';
  end if;

  -- Only a visit the Super Admin ENTERED for a rep, and only by the one who entered it. A rep's own
  -- visit is his record and is never removed here, whoever asks.
  if v_visit.capture_source <> 'admin' or v_visit.entered_by_hr_id is distinct from v_actor then
    raise exception 'phoenix_crm:not_entered_by_you';
  end if;

  select to_jsonb(u) into v_unplanned
  from public.phoenix_crm_unplanned_visits u
  where u.visit_id = v_id;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at, e.id), '[]'::jsonb) into v_events
  from public.phoenix_crm_unplanned_visit_events e
  where e.visit_id = v_id;

  -- The copy first, so nothing is deleted that is not already kept.
  insert into public.phoenix_crm_removed_visits (
    visit_id, seat_id, customer_id, visit_date, rep_hr_id, entered_by_hr_id, removed_by_hr_id, is_test,
    visit, unplanned, unplanned_events
  )
  values (
    v_visit.id, v_visit.seat_id, v_visit.customer_id, v_visit.visit_date, v_visit.rep_hr_id, v_visit.entered_by_hr_id,
    v_actor, v_visit.is_test, to_jsonb(v_visit), v_unplanned, v_events
  );

  -- Then the rows, children first: neither foreign key cascades.
  delete from public.phoenix_crm_unplanned_visit_events where visit_id = v_id;
  delete from public.phoenix_crm_unplanned_visits where visit_id = v_id;
  delete from public.phoenix_crm_visits where id = v_id;

  return jsonb_build_object(
    'removed', true,
    'visit_id', v_id,
    'visit_date', v_visit.visit_date,
    'customer_id', v_visit.customer_id,
    'was_unplanned', v_visit.is_unplanned
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_admin_remove_visit(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_answer_double_visit_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_answer_double_visit_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_decision text := coalesce(p ->> 'decision', '');
  v_day date := nullif(p ->> 'visit_on', '')::date;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_request public.phoenix_crm_double_visit_requests%rowtype;
  v_person public.phoenix_crm_double_visit_request_people%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
begin
  if v_id is null or v_actor is null or v_decision not in ('accept', 'decline') then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select r.* into v_request
  from public.phoenix_crm_double_visit_requests r
  where r.id = v_id and r.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:double_visit_not_found';
  end if;

  select q.* into v_person
  from public.phoenix_crm_double_visit_request_people q
  where q.request_id = v_request.id and q.asked_hr_id = v_actor;
  if not found then
    raise exception 'phoenix_crm:double_visit_not_asked';
  end if;

  if v_decision = 'accept' then
    -- One of the days the rep gave, and one that has not passed.
    if v_day is null or not (v_day = any (v_request.days)) or v_day < v_today then
      raise exception 'phoenix_crm:double_visit_bad_day';
    end if;
    update public.phoenix_crm_double_visit_request_people q
    set status = 'accepted', visit_on = v_day, answered_at = now(), updated_at = now()
    where q.id = v_person.id
    returning * into v_person;
  else
    update public.phoenix_crm_double_visit_request_people q
    set status = 'declined', visit_on = null, answered_at = now(), updated_at = now()
    where q.id = v_person.id
    returning * into v_person;
  end if;

  update public.phoenix_crm_double_visit_requests r set updated_at = now() where r.id = v_request.id;

  select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_request.customer_id;

  return jsonb_build_object(
    'id', v_request.id,
    'person_id', v_person.id,
    'status', v_person.status,
    'visit_on', v_person.visit_on,
    'seat_id', v_request.seat_id,
    'rep_hr_id', v_request.rep_hr_id,
    'customer_name', v_customer.name,
    'customer_list_type', v_customer.list_type,
    'is_test', v_request.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_answer_double_visit_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_answer_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_answer_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_request_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_reply text := nullif(regexp_replace(trim(coalesce(p ->> 'reply', '')), '\s+', ' ', 'g'), '');
  v_request public.phoenix_crm_list_requests%rowtype;
  v_back_to text;
  v_note text;
begin
  if v_seat is null or v_actor is null or v_request_id is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_reply is null then
    raise exception 'phoenix_crm:note_required';
  end if;
  if char_length(v_reply) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select q.* into v_request
  from public.phoenix_crm_list_requests q
  where q.id = v_request_id
    and q.seat_id = v_seat
    and q.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:request_not_found';
  end if;
  if v_request.status <> 'pending' then
    raise exception 'phoenix_crm:request_decided';
  end if;
  if v_request.stage is distinct from 'rep' then
    raise exception 'phoenix_crm:not_returned';
  end if;

  v_back_to := case when v_request.kind = 'grade' then null else 'sfe' end;

  v_note := v_request.note;
  if v_request.kind = 'drop' then
    v_note := case
      when v_request.note is null then v_reply
      when char_length(v_request.note || ' — ' || v_reply) <= 500 then v_request.note || ' — ' || v_reply
      else v_reply
    end;
  end if;

  update public.phoenix_crm_list_requests q
  set stage = v_back_to,
      rep_reply = v_reply,
      replied_at = now(),
      note = v_note
  where q.id = v_request.id
  returning q.* into v_request;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
  values (v_seat, v_request.customer_id, v_request.id, 'request_answered', v_actor, jsonb_build_object('kind', v_request.kind), v_is_test);

  return jsonb_build_object(
    'request_id', v_request.id,
    'seat_id', v_seat,
    'kind', v_request.kind,
    'status', 'pending',
    'stage', v_request.stage,
    'customer_name', v_request.customer_name,
    'returned_by_hr_id', v_request.returned_by_hr_id,
    'requested_by_hr_id', v_request.requested_by_hr_id,
    'replied_at', v_request.replied_at
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_answer_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_answer_visit_ask(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_answer_visit_ask(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'ask_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_decision text := coalesce(p ->> 'decision', '');
  v_day date := nullif(p ->> 'visit_on', '')::date;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_ask public.phoenix_crm_visit_asks%rowtype;
  v_customer_name text;
begin
  if v_id is null or v_actor is null or v_decision not in ('accept', 'decline') then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select a.* into v_ask
  from public.phoenix_crm_visit_asks a
  where a.id = v_id and a.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:visit_ask_not_found';
  end if;
  if v_ask.status = 'cancelled' then
    raise exception 'phoenix_crm:visit_ask_cancelled';
  end if;
  if v_ask.status <> 'waiting' then
    raise exception 'phoenix_crm:visit_ask_answered';
  end if;

  if v_decision = 'accept' then
    -- One of the rep's field days: today or later, four weeks at most, never a Friday. A public
    -- holiday is the application's to refuse — the national calendar lives outside this module.
    if v_day is null or v_day < v_today or v_day > v_today + 27 or extract(isodow from v_day) = 5 then
      raise exception 'phoenix_crm:visit_ask_bad_day';
    end if;
    update public.phoenix_crm_visit_asks a
    set status = 'accepted',
        visit_on = v_day,
        answered_by_hr_id = v_actor,
        answered_at = now(),
        updated_at = now()
    where a.id = v_ask.id
    returning * into v_ask;
  else
    update public.phoenix_crm_visit_asks a
    set status = 'declined',
        answered_by_hr_id = v_actor,
        answered_at = now(),
        updated_at = now()
    where a.id = v_ask.id
    returning * into v_ask;
  end if;

  select c.name into v_customer_name
  from public.phoenix_crm_customers c
  where c.id = v_ask.customer_id;

  return jsonb_build_object(
    'id', v_ask.id,
    'kind', v_ask.kind,
    'status', v_ask.status,
    'seat_id', v_ask.seat_id,
    'rep_hr_id', v_ask.rep_hr_id,
    'asked_hr_id', v_ask.asked_hr_id,
    'told_hr_id', v_ask.told_hr_id,
    'visit_on', v_ask.visit_on,
    'customer_name', v_customer_name,
    'is_test', v_ask.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_answer_visit_ask(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_apply_ireports360_conversion(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_apply_ireports360_conversion(p_items jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer;
begin
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) > 2000 then
    raise exception 'phoenix_crm:conversion_items_invalid'
      using hint = 'An array of at most 2,000 items: {visit_id, checkin_id, place_id, distance_meters, location_flag}.';
  end if;

  with item as (
    select
      (x ->> 'visit_id')::uuid as visit_id,
      (x ->> 'checkin_id')::bigint as checkin_id,
      nullif(x ->> 'place_id', '')::uuid as place_id,
      (x ->> 'distance_meters')::integer as distance_meters,
      x ->> 'location_flag' as location_flag
    from jsonb_array_elements(p_items) x
  ),
  upd as (
    update public.phoenix_crm_visits v
       set lat = m.lat,
           lon = m.lon,
           accuracy_meters = null,
           place_id = i.place_id,
           distance_meters = i.distance_meters,
           location_flag = i.location_flag,
           ireports360_checkin_id = m.crm_checkin_id
      from item i
      join public.phoenix_crm_ireports360_checkin_matches m on m.crm_checkin_id = i.checkin_id
     where v.id = i.visit_id
       and v.imported_from_ireports360_at is not null
       and v.archived_at is null
       and exists (
         select 1 from public.phoenix_crm_imported_visit_sources s
         where s.visit_id = v.id and s.crm_visit_id = m.crm_visit_id
       )
       -- A place answers ok or far; no place answers no_place with no distance.
       and (
         (i.place_id is null and i.location_flag = 'no_place' and i.distance_meters is null)
         or (
           i.place_id is not null and i.location_flag in ('ok', 'far') and i.distance_meters >= 0
           and exists (
             select 1 from public.phoenix_crm_places pl
             where pl.id = i.place_id and pl.customer_id = v.customer_id and pl.status = 'active'
           )
         )
       )
       and (v.lat, v.lon, v.place_id, v.distance_meters, v.location_flag, v.ireports360_checkin_id)
           is distinct from (m.lat, m.lon, i.place_id, i.distance_meters, i.location_flag, m.crm_checkin_id)
    returning 1
  )
  select count(*)::integer into v_count from upd;
  return v_count;
end;
$$;

ALTER FUNCTION public.phoenix_crm_apply_ireports360_conversion(p_items jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_archive_outside(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_archive_outside(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_customer public.phoenix_crm_customers%rowtype;
begin
  if v_seat is null or v_actor is null or nullif(p ->> 'customer_id', '') is null
    or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = (p ->> 'customer_id')::uuid
    and c.seat_id = v_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.status <> 'outside' then
    raise exception 'phoenix_crm:not_outside';
  end if;

  update public.phoenix_crm_customers c
  set status = 'dropped',
      dropped_reason = 'not_added',
      dropped_note = v_note,
      status_changed_at = now(),
      updated_at = now()
  where c.id = v_customer.id
  returning c.* into v_customer;

  with withdrawn as (
    update public.phoenix_crm_list_requests q
    set status = 'withdrawn',
        stage = null,
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decision_note = 'Dropped by the rep'
    where q.customer_id = v_customer.id
      and q.status = 'pending'
    returning q.id
  )
  insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
  select v_seat, v_customer.id, w.id, 'request_withdrawn', v_actor, jsonb_build_object('why', 'archived'), v_is_test
  from withdrawn w;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
  values (v_seat, v_customer.id, 'customer_archived', v_actor, jsonb_build_object('why', 'rep_dropped'), v_is_test);

  return jsonb_build_object('customer_id', v_customer.id, 'customer_name', v_customer.name, 'status', v_customer.status);
end;
$$;

ALTER FUNCTION public.phoenix_crm_archive_outside(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_cancel_visit_ask(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_cancel_visit_ask(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'ask_id', '')::uuid;
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_ask public.phoenix_crm_visit_asks%rowtype;
begin
  if v_id is null or v_seat is null or v_actor is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select a.* into v_ask
  from public.phoenix_crm_visit_asks a
  where a.id = v_id and a.seat_id = v_seat and a.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:visit_ask_not_found';
  end if;
  if v_ask.status in ('accepted', 'declined') then
    raise exception 'phoenix_crm:visit_ask_answered';
  end if;

  if v_ask.status = 'waiting' then
    update public.phoenix_crm_visit_asks a
    set status = 'cancelled',
        cancelled_by_hr_id = v_actor,
        cancelled_at = now(),
        updated_at = now()
    where a.id = v_ask.id
    returning * into v_ask;
  end if;

  return jsonb_build_object(
    'id', v_ask.id,
    'kind', v_ask.kind,
    'status', v_ask.status,
    'seat_id', v_ask.seat_id,
    'customer_id', v_ask.customer_id,
    'is_test', v_ask.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_cancel_visit_ask(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_claim_visit_recording(text, text, text, boolean, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_claim_visit_recording(p_path text, p_hr_id text, p_seat_id text, p_is_test boolean, p_visit_id uuid, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_slot public.phoenix_crm_visit_recordings%rowtype;
  v_bytes bigint;
  v_visit_saved boolean;
begin
  if p_visit_id is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select r.* into v_slot
  from public.phoenix_crm_visit_recordings r
  where r.path = p_path
  for update;

  if not found
    or v_slot.issued_to_hr_id <> upper(trim(p_hr_id))
    or v_slot.seat_id <> p_seat_id
    or v_slot.is_test <> p_is_test then
    raise exception 'phoenix_crm:recording_not_issued';
  end if;
  if v_slot.deleted_at is not null then
    raise exception 'phoenix_crm:recording_missing';
  end if;
  if v_slot.visit_id is not null and v_slot.visit_id <> p_visit_id
    and exists (select 1 from public.phoenix_crm_visits v where v.id = v_slot.visit_id) then
    raise exception 'phoenix_crm:recording_used';
  end if;
  if v_slot.issued_at < now() - interval '6 hours' then
    raise exception 'phoenix_crm:recording_expired';
  end if;
  if p_seconds is null or p_seconds < 30 then
    raise exception 'phoenix_crm:recording_too_short';
  end if;
  if p_seconds > 960 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select coalesce((o.metadata ->> 'size')::bigint, 0) into v_bytes
  from storage.objects o
  where o.bucket_id = 'phoenix-crm-recordings' and o.name = p_path;
  if not found or v_bytes < 1 then
    raise exception 'phoenix_crm:recording_missing';
  end if;

  v_visit_saved := exists (select 1 from public.phoenix_crm_visits v where v.id = p_visit_id);
  if v_visit_saved then
    -- The visit is already written: this is a save sent again. Only its own recording may stand on it.
    if exists (
      select 1 from public.phoenix_crm_visit_recordings r where r.visit_id = p_visit_id and r.path <> p_path
    ) then
      raise exception 'phoenix_crm:recording_used';
    end if;
  else
    -- A claim left by an earlier press whose visit was never written gives way.
    update public.phoenix_crm_visit_recordings r
    set visit_id = null, claimed_at = null
    where r.visit_id = p_visit_id and r.path <> p_path;
  end if;

  update public.phoenix_crm_visit_recordings r
  set visit_id = p_visit_id,
      claimed_at = coalesce(r.claimed_at, now()),
      seconds = p_seconds,
      bytes = least(v_bytes, 16777216)
  where r.path = p_path;

  return v_bytes;
end;
$$;

ALTER FUNCTION public.phoenix_crm_claim_visit_recording(p_path text, p_hr_id text, p_seat_id text, p_is_test boolean, p_visit_id uuid, p_seconds integer) OWNER TO postgres;

--
-- Name: phoenix_crm_comment_changed(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_comment_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from public.phoenix_crm_visit_comment_readings where visit_id = new.id;
  return null;
end;
$$;

ALTER FUNCTION public.phoenix_crm_comment_changed() OWNER TO postgres;

--
-- Name: phoenix_crm_comment_reading_queue(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_comment_reading_queue(p_limit integer) RETURNS TABLE(id uuid, seat_id text, visit_date date, comment text, detail_comment text, products text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.id, v.seat_id, v.visit_date, v.comment, v.detail_comment, v.products
  from public.phoenix_crm_visits v
  where v.visit_date >= (now() at time zone 'Africa/Cairo')::date - 120
    and v.is_test = false
    and v.imported_from_ireports360_at is null
    and (nullif(btrim(v.comment), '') is not null or nullif(btrim(v.detail_comment), '') is not null)
    and not exists (select 1 from public.phoenix_crm_visit_comment_readings r where r.visit_id = v.id)
  order by v.visit_date desc, v.captured_at desc
  limit greatest(p_limit, 0);
$$;

ALTER FUNCTION public.phoenix_crm_comment_reading_queue(p_limit integer) OWNER TO postgres;

--
-- Name: phoenix_crm_contact_truth_calc(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_contact_truth_calc(p_contact_crm_id bigint DEFAULT NULL::bigint) RETURNS TABLE(contact_crm_id bigint, name text, speciality text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct on (c.reference_contact_crm_id)
         c.reference_contact_crm_id as contact_crm_id,
         nullif(btrim(c.name), '') as name,
         nullif(btrim(c.speciality), '') as speciality
    from public.phoenix_crm_customers c
   where c.reference_contact_crm_id is not null
     and c.validated_at is not null
     and not c.is_test
     and c.status = any (array['active', 'pending', 'dropped'])
     and (p_contact_crm_id is null or c.reference_contact_crm_id = p_contact_crm_id)
   order by c.reference_contact_crm_id, (c.status = 'active') desc, c.validated_at desc, c.updated_at desc
$$;

ALTER FUNCTION public.phoenix_crm_contact_truth_calc(p_contact_crm_id bigint) OWNER TO postgres;

--
-- Name: phoenix_crm_contact_truth_on_customer(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_contact_truth_on_customer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform public.phoenix_crm_contact_truth_touch(old.reference_contact_crm_id);
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    perform public.phoenix_crm_contact_truth_touch(new.reference_contact_crm_id);
  end if;

  return null;
end;
$$;

ALTER FUNCTION public.phoenix_crm_contact_truth_on_customer() OWNER TO postgres;

--
-- Name: phoenix_crm_contact_truth_on_truncate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_contact_truth_on_truncate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.phoenix_crm_contact_truth_rebuild();
  return null;
end;
$$;

ALTER FUNCTION public.phoenix_crm_contact_truth_on_truncate() OWNER TO postgres;

--
-- Name: phoenix_crm_contact_truth_rebuild(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_contact_truth_rebuild() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from public.crm_contact_phoenix_truth_cache c
   where not exists (
     select 1 from public.phoenix_crm_contact_truth_calc() f where f.contact_crm_id = c.contact_crm_id
   );

  insert into public.crm_contact_phoenix_truth_cache (contact_crm_id, name, speciality, refreshed_at)
  select f.contact_crm_id, f.name, f.speciality, now()
    from public.phoenix_crm_contact_truth_calc() f
      on conflict (contact_crm_id) do update
         set name = excluded.name, speciality = excluded.speciality, refreshed_at = excluded.refreshed_at;
end;
$$;

ALTER FUNCTION public.phoenix_crm_contact_truth_rebuild() OWNER TO postgres;

--
-- Name: phoenix_crm_contact_truth_reconcile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_contact_truth_reconcile() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_differences bigint;
begin
  select count(*) into v_differences from (
    (
      select contact_crm_id, name, speciality from public.phoenix_crm_contact_truth_calc()
      except
      select contact_crm_id, name, speciality from public.crm_contact_phoenix_truth_cache
    )
    union all
    (
      select contact_crm_id, name, speciality from public.crm_contact_phoenix_truth_cache
      except
      select contact_crm_id, name, speciality from public.phoenix_crm_contact_truth_calc()
    )
  ) d;

  if v_differences > 0 then
    perform public.phoenix_crm_contact_truth_rebuild();
    raise warning 'crm_contact_phoenix_truth_cache was stale: % row(s) repaired', v_differences;
  end if;

  return v_differences;
end;
$$;

ALTER FUNCTION public.phoenix_crm_contact_truth_reconcile() OWNER TO postgres;

--
-- Name: phoenix_crm_contact_truth_reconcile_run(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_contact_truth_reconcile_run() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_diff bigint;
begin
  v_diff := public.phoenix_crm_contact_truth_reconcile();

  perform public.phx_record_job_heartbeat(
    'phoenix-crm-contact-truth-reconcile',
    'success',
    case
      when v_diff > 0 then format('rebuilt: %s row(s) were out of step with _calc()', v_diff)
      else 'in step: 0 differences against _calc()'
    end
  );

  return v_diff;
end
$$;

ALTER FUNCTION public.phoenix_crm_contact_truth_reconcile_run() OWNER TO postgres;

--
-- Name: phoenix_crm_contact_truth_touch(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_contact_truth_touch(p_contact_crm_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_contact_crm_id is null then
    return;
  end if;

  delete from public.crm_contact_phoenix_truth_cache where contact_crm_id = p_contact_crm_id;

  insert into public.crm_contact_phoenix_truth_cache (contact_crm_id, name, speciality, refreshed_at)
  select f.contact_crm_id, f.name, f.speciality, now()
    from public.phoenix_crm_contact_truth_calc(p_contact_crm_id) f
      on conflict (contact_crm_id) do update
         set name = excluded.name, speciality = excluded.speciality, refreshed_at = excluded.refreshed_at;
end;
$$;

ALTER FUNCTION public.phoenix_crm_contact_truth_touch(p_contact_crm_id bigint) OWNER TO postgres;

--
-- Name: phoenix_crm_counted_day_activity_windows(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_counted_day_activity_windows() RETURNS TABLE(seat_id text, counted_from date, stops_on date)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 240
    SET search_path TO 'public'
    AS $$
  with retired as (
    select (select (c.vendor_sync_retired_at at time zone 'Africa/Cairo')::date from public.crm_cutover c where c.id) as on_day
  ),
  started as (
    select t.seat_id, t.team_seat_id, t.starts_on, t.stops_on from public.phoenix_crm_started_team_seats() t
    union
    -- The manager's OWN seat ("Yes, the whole team"): a district manager has no territory of his own, so
    -- a day he recorded sits on his team seat. phoenix_crm_started_team_reps counts that seat the same way.
    select s.team_seat_id, s.team_seat_id, s.starts_on, s.stops_on from public.phoenix_crm_team_starts s
  ),
  counted as (
    select w.seat_id,
           -- From the team's start, or from its day_activities_from when that is EARLIER (never later),
           -- read from the SAME start run the seat came from (owner, 2026-10-10).
           least(w.starts_on, coalesce(run.day_activities_from, w.starts_on)) as counted_from,
           w.stops_on
      from started w
      left join public.phoenix_crm_team_starts run
        on run.team_seat_id = w.team_seat_id
       and run.starts_on = w.starts_on
       and run.stops_on is not distinct from w.stops_on
  )
  select k.seat_id, k.counted_from, least(k.stops_on, r.on_day)
    from counted k
    cross join retired r
   where k.counted_from < coalesce(r.on_day, 'infinity'::date)
  union all
  -- EVERY territory and every district-manager seat from the retirement day, open-ended.
  select s.seat_id, r.on_day, null::date
    from au.seats s
    cross join retired r
   where r.on_day is not null
     and s.seat_tier in ('REP', 'DM', 'ACTING_DM')
$$;

ALTER FUNCTION public.phoenix_crm_counted_day_activity_windows() OWNER TO postgres;

--
-- Name: phoenix_crm_counted_seat_windows(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_counted_seat_windows() RETURNS TABLE(seat_id text, starts_on date, stops_on date)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 200
    SET search_path TO 'public'
    AS $$
  -- ONE ROW, ALWAYS: a scalar subquery answers null when crm_cutover has no row, so the cross joins below
  -- can never come back empty and silently drop every window.
  with retired as (
    select (select (c.vendor_sync_retired_at at time zone 'Africa/Cairo')::date from public.crm_cutover c where c.id) as on_day
  )
  -- A started team's territory, for the days of its start that fall before the retirement day.
  -- least() skips a null, so an open start ends at the retirement day and an unset retirement keeps the stop.
  select t.seat_id, t.starts_on, least(t.stops_on, r.on_day)
    from public.phoenix_crm_started_team_seats() t
    cross join retired r
   where t.starts_on < coalesce(r.on_day, 'infinity'::date)
  union all
  -- EVERY territory from the retirement day, open-ended: a Stop or a seat added later no longer hides it.
  select s.seat_id, r.on_day, null::date
    from au.seats s
    cross join retired r
   where r.on_day is not null
     and s.seat_tier = 'REP'
$$;

ALTER FUNCTION public.phoenix_crm_counted_seat_windows() OWNER TO postgres;

--
-- Name: phoenix_crm_create_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_create_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_kind text := coalesce(p ->> 'kind', '');
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_contact bigint := nullif(p ->> 'reference_contact_crm_id', '')::bigint;
  v_grade text := nullif(p ->> 'proposed_grade', '');
  v_reason text := nullif(p ->> 'drop_reason', '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_first_stage text := coalesce(nullif(p ->> 'first_stage', ''), 'manager');
  v_customer public.phoenix_crm_customers%rowtype;
  v_ref record;
  v_name text;
  v_list_type text;
  v_current_grade text;
  v_never_admitted boolean;
  v_id uuid;
begin
  if v_seat is null or v_line is null or v_actor is null or v_kind not in ('grade', 'drop', 'add', 'restore')
    or (v_customer_id is null and v_contact is null)
    or v_first_stage not in ('manager', 'sfe') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_kind in ('grade', 'add') and coalesce(v_grade, '') not in ('A', 'B', 'C') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_kind = 'drop' and coalesce(v_reason, '') not in ('moved', 'retired', 'closed', 'not_target', 'duplicate', 'other') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_kind = 'drop' and v_reason = 'other' and v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  if v_customer_id is null then
    select r.* into v_ref
    from public.phoenix_crm_reference_entry(v_seat, v_contact, v_is_test) r;
    if not found then
      raise exception 'phoenix_crm:not_on_reference_list';
    end if;
    if v_ref.customer_id is not null then
      v_customer_id := v_ref.customer_id;
    elsif v_kind <> 'drop' then
      raise exception 'phoenix_crm:not_validated';
    else
      v_name := v_ref.name;
      v_list_type := v_ref.list_type;
      v_current_grade := v_ref.grade;
    end if;
  end if;

  if v_customer_id is not null then
    select c.* into v_customer
    from public.phoenix_crm_customers c
    where c.id = v_customer_id
      and c.seat_id = v_seat
      and c.is_test = v_is_test
    for update;
    if not found then
      raise exception 'phoenix_crm:customer_not_found';
    end if;
    -- Never admitted: met outside the list, or added and then dropped before anyone approved him.
    v_never_admitted := v_customer.origin = 'new' and v_customer.validated_at is null;

    if v_kind in ('grade', 'drop') then
      if v_customer.status = 'dropped' then
        raise exception 'phoenix_crm:customer_dropped';
      end if;
      -- A customer outside the list is dropped by the rep himself, straight to the Archive
      -- (phoenix_crm_archive_outside) — nothing of his is on the list to take off.
      if v_customer.status = 'outside' then
        raise exception 'phoenix_crm:not_on_list';
      end if;
    end if;
    -- A customer who is not validated yet can be dropped off the list, but his grade decides his visit
    -- target, so it is only proposed once he is real.
    if v_kind = 'grade' and v_customer.status <> 'active' then
      raise exception 'phoenix_crm:not_validated';
    end if;
    if v_kind = 'grade' and v_customer.grade is not distinct from v_grade then
      raise exception 'phoenix_crm:same_grade';
    end if;
    if v_kind = 'add' and not (v_customer.status = 'outside' or (v_customer.status = 'dropped' and v_never_admitted)) then
      raise exception 'phoenix_crm:not_outside';
    end if;
    if v_kind = 'restore' and not (v_customer.status = 'dropped' and not v_never_admitted) then
      raise exception 'phoenix_crm:not_archived';
    end if;
    v_name := v_customer.name;
    v_list_type := v_customer.list_type;
    v_current_grade := v_customer.grade;
    v_contact := v_customer.reference_contact_crm_id;
  end if;

  if exists (
    select 1
    from public.phoenix_crm_list_requests q
    where q.seat_id = v_seat
      and q.is_test = v_is_test
      and q.kind = v_kind
      and q.status = 'pending'
      and (
        (v_customer_id is not null and q.customer_id = v_customer_id)
        or (v_customer_id is null and q.customer_id is null and q.reference_contact_crm_id = v_contact)
      )
  ) then
    raise exception 'phoenix_crm:already_pending';
  end if;

  insert into public.phoenix_crm_list_requests (
    seat_id, line_code, kind, customer_id, reference_contact_crm_id, list_type, customer_name,
    current_grade, proposed_grade, drop_reason, note, requested_by_hr_id, is_test, stage
  )
  values (
    v_seat, v_line, v_kind, v_customer_id, v_contact, v_list_type, v_name,
    v_current_grade,
    case when v_kind in ('grade', 'add') then v_grade end,
    case when v_kind = 'drop' then v_reason end,
    v_note, v_actor, v_is_test,
    case when v_kind = 'grade' then null else v_first_stage end
  )
  returning id into v_id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer_id, v_id, 'request_created', v_actor,
    jsonb_build_object(
      'kind', v_kind, 'proposed_grade', v_grade, 'drop_reason', v_reason, 'reference_contact_crm_id', v_contact,
      'stage', case when v_kind = 'grade' then null else v_first_stage end
    ),
    v_is_test
  );

  return jsonb_build_object(
    'request_id', v_id,
    'kind', v_kind,
    'stage', case when v_kind = 'grade' then null else v_first_stage end,
    'customer_id', v_customer_id,
    'customer_name', v_name,
    'list_type', v_list_type
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_create_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_create_shared_place(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_create_shared_place(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_name text := nullif(regexp_replace(trim(coalesce(p ->> 'name', '')), '\s+', ' ', 'g'), '');
  v_kind text := coalesce(p ->> 'kind', '');
  v_place jsonb := case when jsonb_typeof(p -> 'place') = 'object' then p -> 'place' end;
  v_hold jsonb := case when jsonb_typeof(p -> 'hold_review') = 'object' then p -> 'hold_review' end;
  v_sign jsonb := case when jsonb_typeof(p -> 'signboard_check') = 'object' then p -> 'signboard_check' end;
  v_source text;
  v_captured_at timestamptz;
  v_id uuid;
begin
  if v_seat is null or v_line is null or v_actor is null or v_name is null or v_place is null
    or v_kind not in ('polyclinic', 'medical_centre', 'hospital_outpatient')
    or nullif(trim(coalesce(v_place ->> 'photo_path', '')), '') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  v_source := coalesce(v_place ->> 'point_source', 'pin');
  if v_source not in ('photo', 'pin') then
    v_source := 'pin';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  v_captured_at := public.phoenix_crm_take_photo(v_place ->> 'photo_path', v_actor, v_seat, 'place', v_is_test);

  insert into public.phoenix_crm_shared_places (
    seat_id, line_code, name, kind, lat, lon, accuracy_meters,
    pin_lat, pin_lon, pin_accuracy_meters, photo_lat, photo_lon, photo_accuracy_meters, photo_captured_at,
    point_source, photo_path, captured_at, device_skew_minutes, address, zone,
    brick_id, brick_name, brick_distance_km, brick_lookup, area_code, area_name, region_code, region_name,
    signboard_check, status, created_by_hr_id, is_test
  )
  values (
    v_seat,
    v_line,
    left(v_name, 200),
    v_kind,
    (v_place ->> 'lat')::double precision,
    (v_place ->> 'lon')::double precision,
    (v_place ->> 'accuracy_meters')::numeric,
    coalesce((v_place ->> 'pin_lat')::double precision, (v_place ->> 'lat')::double precision),
    coalesce((v_place ->> 'pin_lon')::double precision, (v_place ->> 'lon')::double precision),
    coalesce((v_place ->> 'pin_accuracy_meters')::numeric, (v_place ->> 'accuracy_meters')::numeric),
    (v_place ->> 'photo_lat')::double precision,
    (v_place ->> 'photo_lon')::double precision,
    (v_place ->> 'photo_accuracy_meters')::numeric,
    nullif(v_place ->> 'photo_captured_at', '')::timestamptz,
    v_source,
    v_place ->> 'photo_path',
    v_captured_at,
    (v_place ->> 'device_skew_minutes')::integer,
    nullif(trim(coalesce(v_place ->> 'address', '')), ''),
    nullif(trim(coalesce(v_place ->> 'zone', '')), ''),
    nullif(trim(coalesce(v_place ->> 'brick_id', '')), ''),
    nullif(trim(coalesce(v_place ->> 'brick_name', '')), ''),
    (v_place ->> 'brick_distance_km')::numeric,
    coalesce(nullif(trim(coalesce(v_place ->> 'brick_lookup', '')), ''), 'could_not_look'),
    nullif(trim(coalesce(v_place ->> 'area_code', '')), ''),
    nullif(trim(coalesce(v_place ->> 'area_name', '')), ''),
    nullif(trim(coalesce(v_place ->> 'region_code', '')), ''),
    nullif(trim(coalesce(v_place ->> 'region_name', '')), ''),
    coalesce(v_sign, v_hold),
    case when v_hold is null then 'active' else 'held' end,
    v_actor,
    v_is_test
  )
  returning id into v_id;

  return jsonb_build_object(
    'shared_place_id', v_id,
    'captured_at', v_captured_at,
    'held', v_hold is not null
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_create_shared_place(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_customer_counts_by_seat(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customer_counts_by_seat(p_seat_ids text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_object_agg(counted.seat_id, counted.customers), '{}'::jsonb)
  from (
    select c.seat_id, count(*)::integer as customers
    from public.phoenix_crm_customers c
    where c.seat_id = any (p_seat_ids)
      and c.is_test = false
      and c.status in ('active', 'pending', 'outside')
    group by c.seat_id
  ) counted;
$$;

ALTER FUNCTION public.phoenix_crm_customer_counts_by_seat(p_seat_ids text[]) OWNER TO postgres;

--
-- Name: phoenix_crm_customer_last_visits(text[], boolean, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customer_last_visits(p_seat_ids text[], p_is_test boolean, p_since date, p_hr_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with person as (
    select upper(regexp_replace(coalesce(p_hr_id, ''), '[^A-Za-z0-9]', '', 'g')) as key
  ),
  visits as materialized (
    select v.id, v.customer_id, v.visit_date, v.captured_at, v.kind, v.rep_hr_id, v.manager_hr_id, v.senior_hr_id,
           v.product_manager_hr_id, v.imported_from_ireports360_at is not null as imported
    from public.phoenix_crm_countable_visits_with_history v
    where v.seat_id = any (p_seat_ids)
      and v.is_test = p_is_test
      and v.visit_date >= p_since
      and v.customer_id is not null
  ),
  companions as (
    select c.visit_id, array_agg(c.hr_id order by c.position) as hr_ids
    from public.phoenix_crm_visit_companions c
    where c.visit_id in (select id from visits)
    group by c.visit_id
  ),
  latest as (
    select distinct on (v.customer_id) v.*
    from visits v
    order by v.customer_id, v.visit_date desc, v.captured_at desc nulls last, v.id desc
  ),
  named as (
    select v.*, row_number() over (partition by v.customer_id order by v.visit_date desc, v.captured_at desc nulls last, v.id desc) as rank
    from visits v
    left join companions c on c.visit_id = v.id
    cross join person p
    where p.key <> ''
      and (
        upper(regexp_replace(coalesce(v.manager_hr_id, ''), '[^A-Za-z0-9]', '', 'g')) = p.key
        or upper(regexp_replace(coalesce(v.senior_hr_id, ''), '[^A-Za-z0-9]', '', 'g')) = p.key
        or upper(regexp_replace(coalesce(v.product_manager_hr_id, ''), '[^A-Za-z0-9]', '', 'g')) = p.key
        or exists (select 1 from unnest(c.hr_ids) as h(hr_id) where upper(regexp_replace(coalesce(h.hr_id, ''), '[^A-Za-z0-9]', '', 'g')) = p.key)
      )
  )
  select jsonb_build_object(
    'latest', coalesce((
      select jsonb_agg(jsonb_build_object(
        'customer_id', l.customer_id, 'visit_id', l.id, 'visit_date', l.visit_date, 'captured_at', l.captured_at,
        'imported', l.imported, 'kind', l.kind, 'rep_hr_id', l.rep_hr_id, 'manager_hr_id', l.manager_hr_id,
        'senior_hr_id', l.senior_hr_id, 'product_manager_hr_id', l.product_manager_hr_id,
        'companion_hr_ids', coalesce(to_jsonb(c.hr_ids), '[]'::jsonb)
      ) order by l.customer_id)
      from latest l
      left join companions c on c.visit_id = l.id
    ), '[]'::jsonb),
    'with_person', coalesce((
      select jsonb_agg(jsonb_build_object(
        'customer_id', n.customer_id, 'visit_id', n.id, 'visit_date', n.visit_date, 'captured_at', n.captured_at,
        'imported', n.imported, 'kind', n.kind, 'rep_hr_id', n.rep_hr_id, 'manager_hr_id', n.manager_hr_id,
        'senior_hr_id', n.senior_hr_id, 'product_manager_hr_id', n.product_manager_hr_id,
        'companion_hr_ids', coalesce(to_jsonb(c.hr_ids), '[]'::jsonb)
      ) order by n.customer_id, n.rank)
      from named n
      left join companions c on c.visit_id = n.id
      where n.rank <= 3
    ), '[]'::jsonb),
    'hours', coalesce((
      select jsonb_agg(jsonb_build_object('customer_id', pl.customer_id, 'place_id', pl.id, 'label', pl.label, 'timings', pl.timings) order by pl.customer_id, pl.id)
      from public.phoenix_crm_places pl
      where pl.seat_id = any (p_seat_ids)
        and pl.is_test = p_is_test
        and pl.status = 'active'
        and jsonb_typeof(pl.timings) = 'array'
        and jsonb_array_length(pl.timings) > 0
    ), '[]'::jsonb)
  );
$$;

ALTER FUNCTION public.phoenix_crm_customer_last_visits(p_seat_ids text[], p_is_test boolean, p_since date, p_hr_id text) OWNER TO postgres;

--
-- Name: phoenix_crm_customer_merge_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customer_merge_counts(p_customer_ids uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'active_places', coalesce((
      select jsonb_object_agg(counted.customer_id, counted.n)
      from (
        select p.customer_id, count(*)::integer as n
        from public.phoenix_crm_places p
        where p.customer_id = any (p_customer_ids)
          and p.status = 'active'
        group by p.customer_id
      ) counted
    ), '{}'::jsonb),
    'visits', coalesce((
      select jsonb_object_agg(counted.customer_id, counted.n)
      from (
        select v.customer_id, count(*)::integer as n
        from public.phoenix_crm_visits v
        where v.customer_id = any (p_customer_ids)
        group by v.customer_id
      ) counted
    ), '{}'::jsonb),
    'moves', coalesce((
      select jsonb_object_agg(counted.customer_id, counted.n)
      from (
        select m.customer_id, count(*)::integer as n
        from public.phoenix_crm_customer_moves m
        where m.customer_id = any (p_customer_ids)
        group by m.customer_id
      ) counted
    ), '{}'::jsonb)
  );
$$;

ALTER FUNCTION public.phoenix_crm_customer_merge_counts(p_customer_ids uuid[]) OWNER TO postgres;

--
-- Name: phoenix_crm_customer_merged_away(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customer_merged_away(p_customer_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.phoenix_crm_list_events m
    where m.customer_id = p_customer_id
      and m.event_type = 'customer_merged_out'
      and not exists (
        select 1
        from public.phoenix_crm_list_events r
        where r.customer_id = p_customer_id
          and r.event_type = 'customer_restored'
          and r.details ->> 'why' = 'merge_reversed'
          and r.created_at >= m.created_at
      )
  );
$$;

ALTER FUNCTION public.phoenix_crm_customer_merged_away(p_customer_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_customer_merged_away(p_customer_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_customer_merged_away(p_customer_id uuid) IS 'True when this customer row was merged into another (customer_merged_out) and the owner never reversed that merge (customer_restored, why = merge_reversed). Sweep, 11 Nov 2026.';

--
-- Name: phoenix_crm_customer_pharmacy_feedback(text, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customer_pharmacy_feedback(p_seat_id text, p_is_test boolean, p_product_max integer) RETURNS TABLE(id uuid, customer_id uuid, pharmacy_name text, product_availability jsonb, captured_at timestamp with time zone, visits integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with feedback as (
    select
      v.id,
      v.customer_id,
      v.pharmacy_name,
      v.product_availability,
      v.captured_at,
      date_trunc('second', v.captured_at) as at_second,
      -- The parser reads a non-object as no answers at all, so it has no keys here either.
      case
        when jsonb_typeof(v.product_availability) = 'object'
          then (select count(*) from jsonb_object_keys(v.product_availability))
        else 0
      end as key_count
    from public.phoenix_crm_visits v
    where v.seat_id = p_seat_id
      and v.is_test = p_is_test
      and v.pharmacy_name is not null
  ),
  names as (
    select
      f.customer_id,
      f.pharmacy_name,
      min(f.at_second) as first_second,
      max(f.at_second) as last_second,
      count(*)::integer as visits
    from feedback f
    group by f.customer_id, f.pharmacy_name
  ),
  answers as (
    select f.id, f.customer_id, f.pharmacy_name, e.key, f.at_second
    from feedback f
    cross join lateral jsonb_each(
      case when jsonb_typeof(f.product_availability) = 'object' then f.product_availability else '{}'::jsonb end
    ) as e (key, value)
    where f.key_count <= p_product_max
      and e.value in ('"has"'::jsonb, '"missing"'::jsonb)
  ),
  answer_bounds as (
    select a.customer_id, a.pharmacy_name, a.key, min(a.at_second) as first_second, max(a.at_second) as last_second
    from answers a
    group by a.customer_id, a.pharmacy_name, a.key
  ),
  kept as (
    select f.id
    from feedback f
    join names n on n.customer_id = f.customer_id and n.pharmacy_name = f.pharmacy_name
    where f.at_second = n.first_second or f.at_second = n.last_second
    union
    select a.id
    from answers a
    join answer_bounds b on b.customer_id = a.customer_id and b.pharmacy_name = a.pharmacy_name and b.key = a.key
    where a.at_second = b.first_second or a.at_second = b.last_second
    union
    select f.id
    from feedback f
    where f.key_count > p_product_max
  ),
  -- The whole count rides on the newest row of each stored spelling, which (a) always keeps.
  counted as (
    select distinct on (f.customer_id, f.pharmacy_name) f.id, n.visits
    from feedback f
    join names n on n.customer_id = f.customer_id and n.pharmacy_name = f.pharmacy_name
    order by f.customer_id, f.pharmacy_name, f.captured_at desc, f.id desc
  )
  select f.id, f.customer_id, f.pharmacy_name, f.product_availability, f.captured_at, coalesce(c.visits, 0)
  from feedback f
  join kept k on k.id = f.id
  left join counted c on c.id = f.id
  order by f.id;
$$;

ALTER FUNCTION public.phoenix_crm_customer_pharmacy_feedback(p_seat_id text, p_is_test boolean, p_product_max integer) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_customer_pharmacy_feedback(p_seat_id text, p_is_test boolean, p_product_max integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_customer_pharmacy_feedback(p_seat_id text, p_is_test boolean, p_product_max integer) IS 'The visits of a seat that can change its doctors'' pharmacy cards: per stored pharmacy name and per answered product, the rows of the earliest and latest second, plus every row over the answer cap; `visits` carries each name''s whole count on its newest row. Read by loadCustomerPharmacies. See supabase/migrations/20261016180201_phoenix_crm_customer_pharmacy_feedback.sql.';

--
-- Name: phoenix_crm_customers_clear_import_mark(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customers_clear_import_mark() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  -- An Archive doctor the rep restores is his customer from then on: every reader counts it again.
  if old.status = 'dropped' and new.status <> 'dropped' and not new.campaign_visit_holder then
    new.imported_from_ireports360_at := null;
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.phoenix_crm_customers_clear_import_mark() OWNER TO postgres;

--
-- Name: phoenix_crm_customers_no_double_add(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customers_no_double_add() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.reference_contact_crm_id is not null and exists (
    select 1
    from public.phoenix_crm_customers c
    where c.seat_id = new.seat_id
      and c.is_test = new.is_test
      and c.own_contact_crm_id = new.reference_contact_crm_id
      and c.id <> new.id
  ) then
    raise exception 'phoenix_crm:doctor_already_on_list'
      using hint = 'A customer on this seat already answers to ' || new.reference_contact_crm_id
                || ' as his own id. That is this doctor; he is not added a second time.';
  end if;
  return new;
end $$;

ALTER FUNCTION public.phoenix_crm_customers_no_double_add() OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_customers_no_double_add(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_customers_no_double_add() IS 'Refuses a customer row whose reference_contact_crm_id is the own_contact_crm_id of a customer already on the same seat: that is a doctor the rep added himself, pointed at again (owner, 2026-10-12: "stop a rep adding a doctor who is already on his list"). Insert only; existing pairs are untouched.';

--
-- Name: phoenix_crm_customers_no_late_reference(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customers_no_late_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.reference_contact_crm_id is distinct from old.reference_contact_crm_id
     and old.reference_contact_crm_id is null
     and new.reference_contact_crm_id is not null then
    raise exception 'phoenix_crm:customer_already_has_own_contact_id'
      using hint = 'This customer already answers to own_contact_crm_id ' || old.own_contact_crm_id
                || ' in every report outside Phoenix CRM. Pointing him at a vendor id now would '
                || 'restate every month already read. Merge the two records instead.';
  end if;
  return new;
end $$;

ALTER FUNCTION public.phoenix_crm_customers_no_late_reference() OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_customers_no_late_reference(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_customers_no_late_reference() IS 'Refuses setting reference_contact_crm_id on a Phoenix CRM customer that had none, because the customer is already read by own_contact_crm_id everywhere outside Phoenix CRM and a late vendor id would restate months already published. Merge the two records instead. search_path is pinned empty: the body resolves nothing outside pg_catalog.';

--
-- Name: phoenix_crm_customers_no_merged_return(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customers_no_merged_return() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.status = 'dropped'
    and new.status is distinct from 'dropped'
    and coalesce(current_setting('phoenix_crm.allow_merge_reversal', true), '') <> 'on'
    and public.phoenix_crm_customer_merged_away(old.id) then
    raise exception 'phoenix_crm:merged_duplicate';
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.phoenix_crm_customers_no_merged_return() OWNER TO postgres;

--
-- Name: phoenix_crm_customers_validated_has_place(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customers_validated_has_place() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- The row as the transaction leaves it, never as the statement that fired this saw it.
  if not exists (
    select 1 from public.phoenix_crm_customers c
    where c.id = new.id and c.validated_at is not null and c.list_type in ('AM', 'PM')
  ) then
    return null;
  end if;
  if not exists (
    select 1 from public.phoenix_crm_places pl
    where pl.customer_id = new.id and pl.status = 'active'
  ) then
    raise exception 'phoenix_crm:validated_without_place';
  end if;
  return null;
end;
$$;

ALTER FUNCTION public.phoenix_crm_customers_validated_has_place() OWNER TO postgres;

--
-- Name: phoenix_crm_customers_write_contact_name_row(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_customers_write_contact_name_row() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  insert into public.crm_contacts as c (
    contact_crm_id, name, speciality, phone, source, first_seen_on
  )
  values (
    coalesce(new.reference_contact_crm_id, new.own_contact_crm_id),
    nullif(btrim(new.name), ''),
    nullif(btrim(new.speciality), ''),
    nullif(btrim(new.phone), ''),
    'phoenix',
    least((new.created_at at time zone 'Africa/Cairo')::date, (now() at time zone 'Africa/Cairo')::date)
  )
  on conflict (contact_crm_id) do update set
         -- Phoenix's value replaces the one on file; a blank offered keeps what is there.
         name = coalesce(excluded.name, c.name),
         speciality = coalesce(excluded.speciality, c.speciality),
         phone = coalesce(excluded.phone, c.phone),
         first_seen_on = least(c.first_seen_on, excluded.first_seen_on),
         updated_at = now()
   where (c.name, c.speciality, c.phone) is distinct from
         (coalesce(excluded.name, c.name), coalesce(excluded.speciality, c.speciality), coalesce(excluded.phone, c.phone))
      or c.first_seen_on > excluded.first_seen_on;
  return null;
end
$$;

ALTER FUNCTION public.phoenix_crm_customers_write_contact_name_row() OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_customers_write_contact_name_row(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_customers_write_contact_name_row() IS 'Writes a Phoenix-born doctor''s public.crm_contacts name row in the same transaction as his public.phoenix_crm_customers row, with the same key, values and conflict arm as crm_contact_master_refresh''s name-row pass, so the next refresh changes nothing about him. From 2026-10-22 Phoenix is the source of trust (owner): his name, speciality and phone replace what the row holds, and a blank never erases a value.';

--
-- Name: phoenix_crm_decide_full_name(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_full_name(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_decision text := lower(nullif(trim(coalesce(p ->> 'decision', '')), ''));
  -- The Super Admin's own spelling of the name (owner, 2026-11-08), honoured on approve only. The service
  -- has already refused everybody else and checked the three names; null means "the rep's name as held".
  v_corrected text := nullif(left(regexp_replace(trim(coalesce(p ->> 'name', '')), '\s+', ' ', 'g'), 200), '');
  v_customer public.phoenix_crm_customers%rowtype;
  v_held text;
  v_saved text;
begin
  if v_actor is null or v_customer_id is null or v_decision not in ('approve', 'reject') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_corrected is not null and v_decision <> 'approve' then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_customer_id;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_customer.seat_id));

  select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_customer_id for update;
  v_held := v_customer.full_name_held;
  if v_held is null then
    raise exception 'phoenix_crm:full_name_not_held';
  end if;
  v_saved := coalesce(v_corrected, v_held);

  if v_decision = 'approve' then
    if v_customer.status <> 'dropped' then
      -- The rep's own rename, so the name key, the contact's name row and the history move exactly as
      -- when he saves a name himself. The decider has looked at both names: a second customer of the
      -- same name is his to judge, not a refusal.
      perform public.phoenix_crm_rename_customer(jsonb_build_object(
        'seat_id', v_customer.seat_id,
        'actor_hr_id', v_actor,
        'is_test', v_customer.is_test,
        'customer_id', v_customer.id,
        'name', v_saved,
        'speciality', v_customer.speciality,
        'allow_same_name', true
      ));
    end if;
    update public.phoenix_crm_customers c
    set full_name_held = null,
        full_name_held_at = null,
        full_name_held_by_hr_id = null,
        full_name_held_score = null,
        full_name_held_board = null,
        updated_at = now()
    where c.id = v_customer.id;
  else
    update public.phoenix_crm_customers c
    set full_name_refused_at = now(),
        full_name_refused_name = v_held,
        full_name_held = null,
        full_name_held_at = null,
        full_name_held_by_hr_id = null,
        full_name_held_score = null,
        full_name_held_board = null,
        updated_at = now()
    where c.id = v_customer.id;
  end if;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
  values (
    v_customer.seat_id, v_customer.id,
    case when v_decision = 'approve' then 'full_name_approved' else 'full_name_refused' end,
    v_actor,
    -- A corrected name keeps what the rep wrote beside it, so the history shows both.
    jsonb_build_object('name', v_customer.name, 'full_name', v_saved)
      || case when v_corrected is not null and v_corrected is distinct from v_held
           then jsonb_build_object('rep_full_name', v_held, 'corrected', true) else '{}'::jsonb end,
    v_customer.is_test
  );

  return jsonb_build_object('customer_id', v_customer.id, 'decision', v_decision, 'full_name', v_saved);
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_full_name(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_decide_manager_customer_removal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_manager_customer_removal(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'manager_customer_id', '')::uuid;
  v_decision text := coalesce(p ->> 'decision', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_stage text := nullif(trim(coalesce(p ->> 'stage', '')), '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_row public.phoenix_crm_manager_customers%rowtype;
begin
  if v_id is null or v_actor is null or v_decision not in ('approve', 'refuse')
     or v_role is null or v_role not in ('first', 'second', 'administrator')
     or (v_stage is not null and v_stage not in ('first', 'second')) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_decision = 'refuse' and v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;

  select m.* into v_row from public.phoenix_crm_manager_customers m where m.id = v_id for update;
  if not found or v_row.is_test <> v_is_test then
    raise exception 'phoenix_crm:manager_customer_not_found';
  end if;
  v_stage := coalesce(v_stage, case when v_row.status = 'removal_first_approved' then 'second' else 'first' end);
  if (v_role = 'first' and v_stage <> 'first') or (v_role = 'second' and v_stage <> 'second') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if (v_stage = 'first' and v_row.status <> 'removal_pending')
     or (v_stage = 'second' and (v_row.status <> 'removal_first_approved' or v_row.removal_second_approver_hr_id is null)) then
    raise exception 'phoenix_crm:manager_customer_removal_decided';
  end if;

  if v_decision = 'approve' and v_stage = 'first' and v_row.removal_second_approver_hr_id is not null then
    -- The regional manager agrees: the customer stays on the list until the national sales manager above
    -- him approves too — whoever decided this first step.
    update public.phoenix_crm_manager_customers m
    set status = 'removal_first_approved',
        removal_first_decided_at = now(),
        removal_first_decided_by_hr_id = v_actor,
        removal_first_decided_role = v_role,
        removal_first_decision_note = v_note,
        updated_at = now()
    where m.id = v_row.id
    returning m.* into v_row;
  else
    update public.phoenix_crm_manager_customers m
    set status = case when v_decision = 'approve' then 'removed' else 'active' end,
        removal_decided_at = now(),
        removal_decided_by_hr_id = v_actor,
        removal_decided_role = v_role,
        removal_decision_note = v_note,
        updated_at = now()
    where m.id = v_row.id
    returning m.* into v_row;
  end if;

  return jsonb_build_object(
    'manager_customer_id', v_row.id,
    'manager_hr_id', v_row.manager_hr_id,
    'name', v_row.name,
    'status', v_row.status,
    'decision', v_decision,
    'stage', v_stage,
    'second_approver_hr_id', v_row.removal_second_approver_hr_id,
    'is_test', v_row.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_manager_customer_removal(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_decide_manager_plan_edit(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_manager_plan_edit(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_decision text := coalesce(p ->> 'decision', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_stage text := nullif(trim(coalesce(p ->> 'stage', '')), '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_manager text;
  v_week date;
  v_plan_id uuid;
  v_request public.phoenix_crm_manager_plan_edit_requests%rowtype;
  v_plan public.phoenix_crm_manager_plans%rowtype;
  v_from text;
begin
  if v_request_id is null or v_actor is null or v_decision not in ('reopen', 'refuse')
     or v_role is null or v_role not in ('first', 'second', 'administrator')
     or (v_stage is not null and v_stage not in ('first', 'second')) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select r.manager_hr_id, r.week_start, r.plan_id into v_manager, v_week, v_plan_id
  from public.phoenix_crm_manager_plan_edit_requests r where r.id = v_request_id;
  if not found then
    raise exception 'phoenix_crm:manager_plan_edit_not_found';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('phoenix_crm:manager_plan:' || v_manager || ':' || v_week::text || ':' || v_is_test::text)
  );

  select r.* into v_request from public.phoenix_crm_manager_plan_edit_requests r where r.id = v_request_id for update;
  select pl.* into v_plan from public.phoenix_crm_manager_plans pl where pl.id = v_plan_id for update;
  if v_request.is_test <> v_is_test or v_plan.is_test <> v_is_test then
    raise exception 'phoenix_crm:manager_plan_edit_not_found';
  end if;
  if v_expected is distinct from v_request.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  -- The step is the ask's own: a caller that names none (the code running before this migration) decides
  -- the step the ask is waiting on.
  v_stage := coalesce(v_stage, case when v_request.status = 'first_approved' then 'second' else 'first' end);
  if (v_role = 'first' and v_stage <> 'first') or (v_role = 'second' and v_stage <> 'second') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if (v_stage = 'first' and v_request.status <> 'pending')
     or (v_stage = 'second' and (v_request.status <> 'first_approved' or v_request.second_approver_hr_id is null)) then
    raise exception 'phoenix_crm:manager_plan_edit_decided';
  end if;
  if v_plan.week_start + 5 < v_today then
    raise exception 'phoenix_crm:week_passed';
  end if;

  if v_decision = 'refuse' then
    if v_note is null then
      raise exception 'phoenix_crm:note_required';
    end if;
    update public.phoenix_crm_manager_plan_edit_requests r
    set status = 'refused',
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decided_role = v_role,
        decision_note = v_note,
        version = r.version + 1,
        updated_at = now()
    where r.id = v_request.id
    returning r.* into v_request;
    insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
    values (v_plan.id, 'edit_refused', v_actor, v_role, v_plan.status, v_plan.status, v_plan.version, v_note,
            jsonb_build_object('request_id', v_request.id, 'stage', v_stage));
  elsif v_stage = 'first' and v_request.second_approver_hr_id is not null then
    -- The regional manager agrees: the ask passes on to the national sales manager above him. The week
    -- is NOT reopened until that second approval — whoever decided this first step.
    if v_plan.status not in ('submitted', 'first_approved', 'approved') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    update public.phoenix_crm_manager_plan_edit_requests r
    set status = 'first_approved',
        first_decided_at = now(),
        first_decided_by_hr_id = v_actor,
        first_decided_role = v_role,
        first_decision_note = v_note,
        version = r.version + 1,
        updated_at = now()
    where r.id = v_request.id
    returning r.* into v_request;
    insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
    values (v_plan.id, 'edit_first_approved', v_actor, v_role, v_plan.status, v_plan.status, v_plan.version, v_note,
            jsonb_build_object('request_id', v_request.id));
  else
    if v_plan.status not in ('submitted', 'first_approved', 'approved') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    v_from := v_plan.status;
    update public.phoenix_crm_manager_plans pl
    set status = 'draft',
        returned_day = null,
        returned_stage = null,
        first_decided_at = null,
        first_decided_by_hr_id = null,
        first_decided_role = null,
        first_decision_note = null,
        decided_at = null,
        decided_by_hr_id = null,
        decided_by_role = null,
        decision_note = null,
        hr_acknowledged_at = null,
        hr_acknowledged_by_hr_id = null,
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    update public.phoenix_crm_manager_plan_edit_requests r
    set status = 'reopened',
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decided_role = v_role,
        decision_note = v_note,
        reopened_plan_version = v_plan.version,
        version = r.version + 1,
        updated_at = now()
    where r.id = v_request.id
    returning r.* into v_request;
    insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
    values (v_plan.id, 'reopened', v_actor, v_role, v_from, 'draft', v_plan.version, v_note,
            jsonb_build_object('request_id', v_request.id));
  end if;

  return jsonb_build_object(
    'request_id', v_request.id,
    'plan_id', v_plan.id,
    'manager_hr_id', v_plan.manager_hr_id,
    'week_start', v_plan.week_start,
    'status', v_request.status,
    'stage', v_stage,
    'second_approver_hr_id', v_request.second_approver_hr_id,
    'version', v_request.version,
    'plan_status', v_plan.status,
    'plan_version', v_plan.version,
    'is_test', v_request.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_manager_plan_edit(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_decide_manager_single_visit_day(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_manager_single_visit_day(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_decision text := coalesce(p ->> 'decision', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_stage text := nullif(trim(coalesce(p ->> 'stage', '')), '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_manager text;
  v_week date;
  v_row public.phoenix_crm_manager_single_visit_days%rowtype;
begin
  if v_request_id is null or v_actor is null or v_decision not in ('approve', 'refuse')
     or v_role is null or v_role not in ('first', 'second', 'administrator')
     or (v_stage is not null and v_stage not in ('first', 'second')) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_decision = 'refuse' and v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;

  select d.manager_hr_id, d.week_start into v_manager, v_week
  from public.phoenix_crm_manager_single_visit_days d where d.id = v_request_id;
  if not found then
    raise exception 'phoenix_crm:single_visit_day_not_found';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('phoenix_crm:manager_plan:' || v_manager || ':' || v_week::text || ':' || v_is_test::text)
  );

  select d.* into v_row from public.phoenix_crm_manager_single_visit_days d where d.id = v_request_id for update;
  if v_row.is_test <> v_is_test then
    raise exception 'phoenix_crm:single_visit_day_not_found';
  end if;
  if v_expected is distinct from v_row.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  v_stage := coalesce(v_stage, case when v_row.status = 'first_approved' then 'second' else 'first' end);
  if (v_role = 'first' and v_stage <> 'first') or (v_role = 'second' and v_stage <> 'second') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if (v_stage = 'first' and v_row.status <> 'pending')
     or (v_stage = 'second' and (v_row.status <> 'first_approved' or v_row.second_approver_hr_id is null)) then
    raise exception 'phoenix_crm:single_visit_day_decided';
  end if;
  if v_row.visit_date < v_today then
    raise exception 'phoenix_crm:single_visit_day_passed';
  end if;

  if v_decision = 'refuse' then
    update public.phoenix_crm_manager_single_visit_days d
    set status = 'refused',
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decided_role = v_role,
        decision_note = v_note,
        version = d.version + 1,
        updated_at = now()
    where d.id = v_row.id
    returning d.* into v_row;
  elsif v_stage = 'first' and v_row.second_approver_hr_id is not null then
    -- The regional manager agrees: the ask passes on to the national sales manager above him. The date
    -- holds no extra single visits until that second approval — whoever decided this first step.
    update public.phoenix_crm_manager_single_visit_days d
    set status = 'first_approved',
        first_decided_at = now(),
        first_decided_by_hr_id = v_actor,
        first_decided_role = v_role,
        first_decision_note = v_note,
        version = d.version + 1,
        updated_at = now()
    where d.id = v_row.id
    returning d.* into v_row;
  else
    update public.phoenix_crm_manager_single_visit_days d
    set status = 'approved',
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decided_role = v_role,
        decision_note = v_note,
        version = d.version + 1,
        updated_at = now()
    where d.id = v_row.id
    returning d.* into v_row;
  end if;

  return jsonb_build_object(
    'request_id', v_row.id,
    'manager_hr_id', v_row.manager_hr_id,
    'week_start', v_row.week_start,
    'visit_date', v_row.visit_date,
    'status', v_row.status,
    'stage', v_stage,
    'second_approver_hr_id', v_row.second_approver_hr_id,
    'version', v_row.version,
    'is_test', v_row.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_manager_single_visit_day(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_decide_plan_edit_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_plan_edit_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_stage text := coalesce(p ->> 'stage', '');
  v_decision text := coalesce(p ->> 'decision', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_seat text;
  v_week date;
  v_request public.phoenix_crm_plan_edit_requests%rowtype;
  v_plan public.phoenix_crm_plans%rowtype;
  v_from text;
  v_to text;
  v_event text;
  v_plan_from text;
  v_reopened boolean := false;
begin
  if v_request_id is null or v_actor is null
    or v_stage not in ('manager', 'sfe', 'administrator')
    or (v_stage = 'administrator' and v_decision <> 'refuse')
    or (v_stage <> 'administrator' and v_decision not in ('approve', 'refuse'))
    or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_decision = 'refuse' and v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;

  select r.seat_id, r.week_start into v_seat, v_week from public.phoenix_crm_plan_edit_requests r where r.id = v_request_id;
  if not found then
    raise exception 'phoenix_crm:plan_edit_not_found';
  end if;

  -- The PLAN's lock, the same key every plan transition takes: an acknowledgement reopens the plan,
  -- so it must queue behind a send or a manager's decision on that week, never cross one.
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:plan:' || v_seat || ':' || v_week::text));

  select r.* into v_request from public.phoenix_crm_plan_edit_requests r where r.id = v_request_id for update;
  -- A test/real mix-up must read as "not there", never as a permission error.
  if v_request.is_test <> v_is_test then
    raise exception 'phoenix_crm:plan_edit_not_found';
  end if;
  if v_expected is distinct from v_request.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  v_from := v_request.status;
  if v_from not in ('manager_pending', 'sfe_pending') then
    raise exception 'phoenix_crm:plan_edit_decided';
  end if;
  -- The steps run in order: SFE cannot sign off a request the manager has not seen. The Administrator
  -- is not a step - he may decline a request waiting at EITHER one, and nothing ever waits for him.
  if (v_stage = 'manager' and v_from <> 'manager_pending')
    or (v_stage = 'sfe' and v_from <> 'sfe_pending') then
    raise exception 'phoenix_crm:plan_edit_wrong_stage';
  end if;

  -- A week that is over has nothing left to change. The request is closed as expired and that is
  -- WRITTEN — no exception, so the transaction commits and the queue stops showing it.
  if v_request.week_start + 5 < v_today then
    update public.phoenix_crm_plan_edit_requests r
    set status = 'expired', decided_at = now(), version = r.version + 1, updated_at = now()
    where r.id = v_request_id
    returning r.* into v_request;
    insert into public.phoenix_crm_plan_edit_request_events
      (request_id, event_type, actor_hr_id, actor_role, actor_stage, from_status, to_status, version, note)
    values
      (v_request_id, 'expired', v_actor, v_role, v_stage, v_from, 'expired', v_request.version, null);
    return jsonb_build_object(
      'request_id', v_request.id,
      'plan_id', v_request.plan_id,
      'seat_id', v_request.seat_id,
      'week_start', v_request.week_start,
      'rep_hr_id', v_request.rep_hr_id,
      'status', v_request.status,
      'version', v_request.version,
      'plan_version', null
    );
  end if;

  if v_decision = 'refuse' then
    v_to := 'refused';
    v_event := 'refused';
  elsif v_stage = 'manager' then
    v_to := 'sfe_pending';
    v_event := 'approved';
  else
    -- SFE's approval is the last one: the week opens for the rep now (owner, 2026-10-08 - the
    -- Administrator is no longer a step in this chain).
    v_to := 'reopened';
    v_event := 'approved';
    select pl.* into v_plan from public.phoenix_crm_plans pl where pl.id = v_request.plan_id for update;
    v_plan_from := v_plan.status;
    -- Reopened exactly as the rep's own take-back used to reopen it.
    if v_plan_from in ('submitted', 'approved') then
      update public.phoenix_crm_plans pl
      set status = 'draft',
          decided_at = null,
          decided_by_hr_id = null,
          decided_by_role = null,
          decision_note = null,
          version = pl.version + 1,
          updated_at = now()
      where pl.id = v_plan.id
      returning pl.* into v_plan;
      insert into public.phoenix_crm_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
      values (v_plan.id, 'reopened', v_actor, 'sfe_manager', v_plan_from, v_plan.status, v_plan.version, null,
              jsonb_build_object('edit_request_id', v_request_id));
      v_reopened := true;
    -- 🔴 A WEEK RETURNED FOR ONE DAY IS OPENED WHOLE, AND THE DAY IS CLEARED HERE. It was left exactly
    -- as it stood, which is right about the STATUS — he may change it either way — and wrong about the
    -- day: he asked to edit the WEEK, his manager and SFE agreed, so every day is his again. While
    -- returned_day stood, the plan's latest event still named it, and both readers of that event
    -- (phoenix_crm_save_visit's "was he planned", phoenix_crm_plan_day_status) went on counting the
    -- week's OTHER days as SENT — so a customer he added on one of them was stamped PLANNED, with no
    -- district manager and no SFE behind it and the reason he typed dropped. Clearing the day leaves
    -- those readers a plain whole-week return, which is authority on no day at all; the event is what
    -- they read, so it is written as well as the column being cleared.
    elsif v_plan_from = 'returned' and v_plan.returned_day is not null then
      update public.phoenix_crm_plans pl
      set returned_day = null,
          version = pl.version + 1,
          updated_at = now()
      where pl.id = v_plan.id
      returning pl.* into v_plan;
      insert into public.phoenix_crm_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
      values (v_plan.id, 'reopened', v_actor, 'sfe_manager', v_plan_from, v_plan.status, v_plan.version, null,
              jsonb_build_object('edit_request_id', v_request_id, 'opened_whole_week', true));
      v_reopened := true;
    end if;
  end if;

  update public.phoenix_crm_plan_edit_requests r
  set status = v_to,
      manager_decided_by_hr_id = case when v_stage = 'manager' then v_actor else r.manager_decided_by_hr_id end,
      manager_decided_at = case when v_stage = 'manager' then now() else r.manager_decided_at end,
      manager_note = case when v_stage = 'manager' then v_note else r.manager_note end,
      sfe_decided_by_hr_id = case when v_stage = 'sfe' then v_actor else r.sfe_decided_by_hr_id end,
      sfe_decided_at = case when v_stage = 'sfe' then now() else r.sfe_decided_at end,
      sfe_note = case when v_stage = 'sfe' then v_note else r.sfe_note end,
      admin_decided_by_hr_id = case when v_stage = 'administrator' then v_actor else r.admin_decided_by_hr_id end,
      admin_decided_at = case when v_stage = 'administrator' then now() else r.admin_decided_at end,
      admin_note = case when v_stage = 'administrator' then v_note else r.admin_note end,
      -- hr_acknowledged_at is the moment the week WAS OPENED: its readers (plan-rules, offplan-day) ask
      -- "was this week opened after the return", not who opened it, so SFE's approval stamps it and the
      -- by-person column stays empty.
      hr_acknowledged_at = case when v_to = 'reopened' then now() else r.hr_acknowledged_at end,
      reopened_plan_version = case when v_to = 'reopened' then v_plan.version else r.reopened_plan_version end,
      decided_at = case when v_to in ('reopened', 'refused') then now() else null end,
      version = r.version + 1,
      updated_at = now()
  where r.id = v_request_id
  returning r.* into v_request;

  insert into public.phoenix_crm_plan_edit_request_events
    (request_id, event_type, actor_hr_id, actor_role, actor_stage, from_status, to_status, version, note, details)
  values
    (v_request_id, v_event, v_actor, v_role, v_stage, v_from, v_to, v_request.version, v_note,
     case when v_to = 'reopened' then jsonb_build_object('plan_reopened', v_reopened, 'plan_status_before', v_plan_from)
          else '{}'::jsonb end);

  return jsonb_build_object(
    'request_id', v_request.id,
    'plan_id', v_request.plan_id,
    'seat_id', v_request.seat_id,
    'week_start', v_request.week_start,
    'rep_hr_id', v_request.rep_hr_id,
    'status', v_request.status,
    'version', v_request.version,
    'plan_version', v_request.reopened_plan_version
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_plan_edit_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_decide_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_request_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_decision text := coalesce(p ->> 'decision', '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_stage_in text := nullif(p ->> 'stage', '');
  v_approved_in text := nullif(p ->> 'approved_grade', '');
  v_potential_in text := nullif(p ->> 'potential_grade', '');
  v_request public.phoenix_crm_list_requests%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_status text;
  v_final boolean := true;
  v_has_place boolean;
begin
  if v_actor is null or v_request_id is null or v_decision not in ('approve', 'refuse') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if (v_approved_in is not null and v_approved_in not in ('A', 'B', 'C'))
    or (v_potential_in is not null and v_potential_in not in ('AA', 'AB', 'AC', 'BA', 'BB', 'BC')) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select q.* into v_request
  from public.phoenix_crm_list_requests q
  where q.id = v_request_id
    and q.is_test = v_is_test;
  if not found then
    raise exception 'phoenix_crm:request_not_found';
  end if;
  v_seat := v_request.seat_id;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select q.* into v_request
  from public.phoenix_crm_list_requests q
  where q.id = v_request_id
  for update;
  if v_request.status <> 'pending' then
    raise exception 'phoenix_crm:request_decided';
  end if;
  -- Two people deciding at once: the second one's step has already moved on.
  if v_stage_in is not null and v_stage_in is distinct from v_request.stage then
    raise exception 'phoenix_crm:request_wrong_stage';
  end if;

  -- ── The district manager's step of a two-step request: approving hands it to SFE ──────────────
  if v_decision = 'approve' and v_request.stage = 'manager' then
    if v_request.kind = 'add' then
      if v_potential_in is null then
        raise exception 'phoenix_crm:potential_grade_required';
      end if;
      v_approved_in := coalesce(v_approved_in, v_request.proposed_grade);
    else
      v_approved_in := null;
      v_potential_in := null;
    end if;

    update public.phoenix_crm_list_requests q
    set stage = 'sfe',
        manager_decided_by_hr_id = v_actor,
        manager_decided_at = now(),
        manager_note = v_note,
        approved_grade = v_approved_in,
        potential_grade = v_potential_in
    where q.id = v_request.id
    returning q.* into v_request;

    insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
    values (
      v_seat, v_request.customer_id, v_request.id, 'request_moved_on', v_actor,
      jsonb_build_object('kind', v_request.kind, 'to_stage', 'sfe', 'approved_grade', v_approved_in, 'potential_grade', v_potential_in),
      v_is_test
    );

    return jsonb_build_object(
      'request_id', v_request.id,
      'seat_id', v_seat,
      'kind', v_request.kind,
      'status', 'pending',
      'stage', 'sfe',
      'final', false,
      'customer_id', v_request.customer_id,
      'customer_name', v_request.customer_name,
      'list_type', v_request.list_type,
      'proposed_grade', v_request.proposed_grade,
      'drop_reason', v_request.drop_reason,
      'requested_by_hr_id', v_request.requested_by_hr_id
    );
  end if;

  if v_decision = 'approve' then
    v_status := 'approved';

    if v_request.kind = 'grade' then
      select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_request.customer_id for update;
      if not found or v_customer.status <> 'active' then
        raise exception 'phoenix_crm:customer_dropped';
      end if;
      update public.phoenix_crm_customers c
      set grade = v_request.proposed_grade, updated_at = now()
      where c.id = v_customer.id;

      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      values (
        v_seat, v_customer.id, v_request.id, 'grade_changed', v_actor,
        jsonb_build_object('from', v_customer.grade, 'to', v_request.proposed_grade), v_is_test
      );

    elsif v_request.kind = 'add' then
      select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_request.customer_id for update;
      if not found or not (
        v_customer.status = 'outside'
        or (v_customer.status = 'dropped' and v_customer.origin = 'new' and v_customer.validated_at is null)
      ) then
        raise exception 'phoenix_crm:not_outside';
      end if;
      -- 🔴 ADMITTED IS NOT VALIDATED (owner, 2026-11-11). Until this migration the approval stamped
      -- validated_at whatever had happened to the door since the request was filed, and 23 customers
      -- were validated with NO place — each one's only place had been rejected and retired first. A
      -- pharmacy is validated by its own pin and holds no place row, so it keeps the old door.
      v_has_place := v_customer.list_type not in ('AM', 'PM') or exists (
        select 1 from public.phoenix_crm_places pl
        where pl.customer_id = v_customer.id and pl.status = 'active'
      );
      if v_has_place then
        -- Admitted. validated_at is set NOW: the customer was validated at the door, and every visit
        -- logged against him since starts counting, in the month it happened (owner, 2026-09-29).
        update public.phoenix_crm_customers c
        set status = 'active',
            validated_at = now(),
            validated_by_hr_id = v_request.requested_by_hr_id,
            grade = coalesce(v_request.approved_grade, v_approved_in, v_request.proposed_grade),
            potential_grade = coalesce(v_request.potential_grade, v_potential_in),
            dropped_reason = null,
            dropped_note = null,
            status_changed_at = now(),
            updated_at = now()
        where c.id = v_customer.id
        returning c.* into v_customer;
      else
        -- Admitted with no door on file: he goes to "To validate", graded as approved, and the rep
        -- captures his place again. reopened_at is the same stamp a rejected validation leaves.
        update public.phoenix_crm_customers c
        set status = 'pending',
            validated_at = null,
            validated_by_hr_id = null,
            grade = coalesce(v_request.approved_grade, v_approved_in, v_request.proposed_grade),
            potential_grade = coalesce(v_request.potential_grade, v_potential_in),
            dropped_reason = null,
            dropped_note = null,
            reopened_at = now(),
            status_changed_at = now(),
            updated_at = now()
        where c.id = v_customer.id
        returning c.* into v_customer;
      end if;

      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      values (
        v_seat, v_customer.id, v_request.id, 'customer_admitted', v_actor,
        jsonb_build_object('grade', v_customer.grade, 'potential_grade', v_customer.potential_grade,
          'validated', v_has_place, 'to', v_customer.status), v_is_test
      );

    elsif v_request.kind = 'restore' then
      select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_request.customer_id for update;
      if not found or v_customer.status <> 'dropped' then
        raise exception 'phoenix_crm:not_archived';
      end if;
      -- Back where he was: on the list if he had been validated AND still holds a place, waiting to be
      -- validated if not. His last place can be retired while he sits in the Archive (a venue or a
      -- review rejected: both un-validate only an ACTIVE customer), and the stamp would then put him
      -- back on the list with nothing to measure a visit against (2026-11-11).
      v_has_place := v_customer.list_type not in ('AM', 'PM') or exists (
        select 1 from public.phoenix_crm_places pl
        where pl.customer_id = v_customer.id and pl.status = 'active'
      );
      update public.phoenix_crm_customers c
      set status = case when c.validated_at is not null and v_has_place then 'active' else 'pending' end,
          validated_at = case when v_has_place then c.validated_at else null end,
          validated_by_hr_id = case when v_has_place then c.validated_by_hr_id else null end,
          reopened_at = case when c.validated_at is not null and not v_has_place then now() else c.reopened_at end,
          dropped_reason = null,
          dropped_note = null,
          status_changed_at = now(),
          updated_at = now()
      where c.id = v_customer.id
      returning c.* into v_customer;

      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      values (v_seat, v_customer.id, v_request.id, 'customer_restored', v_actor, jsonb_build_object('to', v_customer.status, 'place', v_has_place), v_is_test);

    elsif v_request.customer_id is not null then
      select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_request.customer_id for update;
      -- Active or pending: both leave the list. A pending one keeps validated_at null, so the visits
      -- logged against him never start counting — he was never validated. His places are KEPT
      -- (owner, 2026-09-29): the clinic is still where it was, and a bring-back needs no new photo.
      if not found or v_customer.status = 'dropped' then
        raise exception 'phoenix_crm:customer_dropped';
      end if;
      update public.phoenix_crm_customers c
      set status = 'dropped',
          dropped_reason = v_request.drop_reason,
          dropped_note = v_request.note,
          status_changed_at = now(),
          updated_at = now()
      where c.id = v_customer.id;

      with withdrawn as (
        update public.phoenix_crm_list_requests q
        set status = 'withdrawn',
            stage = null,
            decided_at = now(),
            decided_by_hr_id = v_actor,
            decision_note = 'The customer left the list'
        where q.customer_id = v_customer.id
          and q.status = 'pending'
          and q.id <> v_request.id
        returning q.id
      )
      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      select v_seat, v_customer.id, w.id, 'request_withdrawn', v_actor, jsonb_build_object('why', 'dropped'), v_is_test
      from withdrawn w;

      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      values (
        v_seat, v_customer.id, v_request.id, 'customer_dropped', v_actor,
        jsonb_build_object('reason', v_request.drop_reason), v_is_test
      );

    else
      select c.* into v_customer
      from public.phoenix_crm_customers c
      where c.seat_id = v_seat
        and c.reference_contact_crm_id = v_request.reference_contact_crm_id
        and c.is_test = v_is_test
      for update;
      if found then
        if v_customer.status = 'active' then
          raise exception 'phoenix_crm:already_validated';
        end if;
        if v_customer.status = 'dropped' then
          raise exception 'phoenix_crm:customer_dropped';
        end if;
        -- Pending: the customer was carried over from iReports360 and never validated.
        update public.phoenix_crm_customers c
        set status = 'dropped',
            dropped_reason = v_request.drop_reason,
            dropped_note = v_request.note,
            status_changed_at = now(),
            updated_at = now()
        where c.id = v_customer.id
        returning c.* into v_customer;
      else
        insert into public.phoenix_crm_customers (
          seat_id, line_code, list_type, name, grade, origin, reference_contact_crm_id, status, validated_at,
          dropped_reason, dropped_note, status_changed_at, created_by_hr_id, is_test
        )
        values (
          v_seat, v_request.line_code, v_request.list_type, left(v_request.customer_name, 200), v_request.current_grade, 'reference',
          v_request.reference_contact_crm_id, 'dropped', null, v_request.drop_reason, v_request.note, now(),
          v_request.requested_by_hr_id, v_is_test
        )
        returning * into v_customer;
      end if;

      update public.phoenix_crm_list_requests q set customer_id = v_customer.id where q.id = v_request.id;

      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      values (
        v_seat, v_customer.id, v_request.id, 'customer_dropped', v_actor,
        jsonb_build_object('reason', v_request.drop_reason, 'reference_contact_crm_id', v_request.reference_contact_crm_id),
        v_is_test
      );
    end if;
  else
    v_status := 'refused';

    -- A refused add sends the customer to the Archive: he was never admitted, and the rep can still
    -- ask again from there.
    if v_request.kind = 'add' then
      select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_request.customer_id for update;
      if found and v_customer.status = 'outside' then
        update public.phoenix_crm_customers c
        set status = 'dropped',
            dropped_reason = 'not_admitted',
            dropped_note = v_note,
            status_changed_at = now(),
            updated_at = now()
        where c.id = v_customer.id
        returning c.* into v_customer;

        insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
        values (v_seat, v_customer.id, v_request.id, 'customer_archived', v_actor, jsonb_build_object('why', 'add_refused'), v_is_test);
      end if;
    end if;
  end if;

  update public.phoenix_crm_list_requests q
  set status = v_status,
      stage = null,
      decided_at = now(),
      decided_by_hr_id = v_actor,
      decision_note = v_note,
      manager_decided_by_hr_id = case when v_request.stage = 'manager' then v_actor else q.manager_decided_by_hr_id end,
      manager_decided_at = case when v_request.stage = 'manager' then now() else q.manager_decided_at end,
      manager_note = case when v_request.stage = 'manager' then v_note else q.manager_note end,
      sfe_decided_by_hr_id = case when v_request.stage = 'sfe' then v_actor else q.sfe_decided_by_hr_id end,
      sfe_decided_at = case when v_request.stage = 'sfe' then now() else q.sfe_decided_at end,
      sfe_note = case when v_request.stage = 'sfe' then v_note else q.sfe_note end,
      potential_grade = coalesce(q.potential_grade, case when v_request.kind = 'add' and v_status = 'approved' then v_potential_in end)
  where q.id = v_request.id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, coalesce(v_customer.id, v_request.customer_id), v_request.id, 'request_decided', v_actor,
    jsonb_build_object('kind', v_request.kind, 'decision', v_status, 'stage', v_request.stage), v_is_test
  );

  return jsonb_build_object(
    'request_id', v_request.id,
    'seat_id', v_seat,
    'kind', v_request.kind,
    'status', v_status,
    'stage', null,
    'final', v_final,
    'customer_id', coalesce(v_customer.id, v_request.customer_id),
    'customer_name', v_request.customer_name,
    'list_type', v_request.list_type,
    'proposed_grade', v_request.proposed_grade,
    'drop_reason', v_request.drop_reason,
    'requested_by_hr_id', v_request.requested_by_hr_id
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_decide_shared_place(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_shared_place(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'shared_place_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_decision text := coalesce(p ->> 'decision', '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_reason text := nullif(trim(coalesce(p ->> 'refusal_reason', '')), '');
  v_venue public.phoenix_crm_shared_places%rowtype;
  v_seated record;
  v_reopened jsonb := '[]'::jsonb;
  v_places integer := 0;
  v_validated jsonb := '[]'::jsonb;
begin
  if v_id is null or v_actor is null or v_decision not in ('approve', 'reject')
    or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select s.* into v_venue from public.phoenix_crm_shared_places s where s.id = v_id;
  if not found then
    raise exception 'phoenix_crm:shared_place_not_found';
  end if;
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_venue.seat_id));
  select s.* into v_venue from public.phoenix_crm_shared_places s where s.id = v_id for update;
  if v_venue.status = 'retired' then
    raise exception 'phoenix_crm:shared_place_retired';
  end if;

  if v_decision = 'approve' then
    update public.phoenix_crm_shared_places
    set status = 'active', decided_at = now(), decided_by_hr_id = v_actor, decision_note = v_note,
        refusal_reason = null, updated_at = now()
    where id = v_id;

    -- 🔴 APPROVING THE BUILDING CONFIRMS THE DOCTORS WAITING IN IT (owner, 2026-10-14: a visit to a doctor in
    -- a building the system was still checking counts in no KPI "until the admin confirm the polyclinic and
    -- the doctors in it"). A seating in a held venue left each customer pending
    -- (phoenix_crm_validate_customer); this is the one place that releases them. It is NOT a blanket
    -- validation: a building with no timetable on file, a timetable read as another name or as no
    -- schedule, and a customer whose own location is waiting on a validation review all STAY pending — the
    -- same three holds phoenix_crm_settle_venue_timetable keeps. `unjudged` and an unread board never hold
    -- (owner, 2026-10-08), so they are confirmed here.
    for v_seated in
      select pl.id as place_id, pl.customer_id, pl.schedule_check, pl.is_test, c.name as customer_name
      from public.phoenix_crm_places pl
      join public.phoenix_crm_customers c on c.id = pl.customer_id
      where pl.shared_place_id = v_id and pl.status = 'active' and c.status = 'pending'
      order by pl.created_at
    loop
      if v_venue.schedule_photo_path is null
        or (v_seated.schedule_check ->> 'verdict') in ('other_name', 'no_schedule')
        or exists (
          select 1 from public.phoenix_crm_validation_reviews r
          where r.customer_id = v_seated.customer_id and r.status = 'pending'
        ) then
        continue;
      end if;

      update public.phoenix_crm_customers c
      set status = 'active', validated_at = now(), validated_by_hr_id = v_actor, status_changed_at = now(), updated_at = now()
      where c.id = v_seated.customer_id and c.status = 'pending';
      if found then
        insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
        values (
          v_venue.seat_id, v_seated.customer_id, v_seated.place_id, 'customer_validated', v_actor,
          jsonb_build_object('why', 'shared_place_approved', 'shared_place_id', v_id, 'shared_place_name', v_venue.name),
          v_seated.is_test
        );
        v_validated := v_validated || jsonb_build_array(jsonb_build_object(
          'customer_id', v_seated.customer_id, 'customer_name', v_seated.customer_name, 'place_id', v_seated.place_id
        ));
      end if;
    end loop;
  else
    update public.phoenix_crm_shared_places
    set status = 'retired', decided_at = now(), decided_by_hr_id = v_actor, decision_note = v_note,
        refusal_reason = v_reason, retired_at = now(), retired_by_hr_id = v_actor, updated_at = now()
    where id = v_id;

    -- Every customer seated in a rejected venue goes back to To validate, exactly as a rejected place
    -- of his own would send him — place retired, customer pending when he has no other active place,
    -- `reopened_at` stamped so he is first in the rep's To validate order.
    for v_seated in
      select pl.id as place_id, pl.customer_id, pl.label, pl.lat, pl.lon, pl.is_test, pl.created_by_hr_id, c.name as customer_name
      from public.phoenix_crm_places pl
      join public.phoenix_crm_customers c on c.id = pl.customer_id
      where pl.shared_place_id = v_id and pl.status = 'active'
      order by pl.created_at
      -- NO `for update` row lock on the cursor, by choice: each row is locked by the `update` that
      -- retires it two lines below, the whole function runs in one transaction behind an advisory
      -- `lock_timeout`, and a venue is decided by one administrator at a time. (It also keeps the
      -- migration-hygiene sweep honest — it reads `for update of pl, c` and `for update\nloop` as
      -- writes to tables called `of` and `loop`.)
    loop
      update public.phoenix_crm_places pl
      set status = 'retired', retired_at = now(), retired_by_hr_id = v_actor, updated_at = now()
      where pl.id = v_seated.place_id;
      v_places := v_places + 1;

      insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
      values (
        v_venue.seat_id, v_seated.customer_id, v_seated.place_id, 'place_retired', v_actor,
        jsonb_build_object(
          'reason', coalesce(v_note, 'This place could not be confirmed.'),
          'label', v_seated.label, 'lat', v_seated.lat, 'lon', v_seated.lon,
          'why', 'shared_place_rejected', 'shared_place_id', v_id
        ),
        v_seated.is_test
      );

      if not exists (
        select 1 from public.phoenix_crm_places pl where pl.customer_id = v_seated.customer_id and pl.status = 'active'
      ) then
        update public.phoenix_crm_customers c
        set status = 'pending', validated_at = null, validated_by_hr_id = null, status_changed_at = now(), updated_at = now()
        where c.id = v_seated.customer_id and c.status = 'active';
        insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
        values (
          v_venue.seat_id, v_seated.customer_id, 'customer_pending', v_actor,
          jsonb_build_object('why', 'shared_place_rejected', 'shared_place_id', v_id), v_seated.is_test
        );
      end if;

      -- 🔴 Read from the TABLE, deliberately, so it sees the reopen above — and it fires for a
      -- customer who was already pending, which the branch above never does.
      update public.phoenix_crm_customers c
      set reopened_at = now(), updated_at = now()
      where c.id = v_seated.customer_id and c.status = 'pending';

      -- Who the service tells, and about whom. The rep is the one who captured the TIMETABLE, never
      -- the person deciding: it is his photo.
      if exists (select 1 from public.phoenix_crm_customers c where c.id = v_seated.customer_id and c.status = 'pending') then
        v_reopened := v_reopened || jsonb_build_array(jsonb_build_object(
          'customer_id', v_seated.customer_id,
          'customer_name', v_seated.customer_name,
          'rep_hr_id', v_seated.created_by_hr_id,
          'is_test', v_seated.is_test
        ));
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'shared_place_id', v_id,
    'status', case when v_decision = 'approve' then 'active' else 'retired' end,
    'seat_id', v_venue.seat_id,
    'is_test', v_venue.is_test,
    'name', v_venue.name,
    'places_retired', v_places,
    'validated', v_validated,
    'reopened', v_reopened,
    'refusal_reason', case when v_decision = 'reject' then v_reason else null end
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_shared_place(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_decide_unplanned_visit(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_unplanned_visit(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_visit_id uuid := nullif(p ->> 'visit_id', '')::uuid;
  v_stage text := coalesce(p ->> 'stage', '');
  v_decision text := coalesce(p ->> 'decision', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_row public.phoenix_crm_unplanned_visits%rowtype;
  v_from text;
  v_to text;
begin
  if v_visit_id is null or v_actor is null
    or v_stage not in ('manager', 'sfe')
    or v_decision not in ('approve', 'refuse')
    or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_decision = 'refuse' and v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;

  if not exists (select 1 from public.phoenix_crm_unplanned_visits u where u.visit_id = v_visit_id) then
    raise exception 'phoenix_crm:unplanned_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:unplanned:' || v_visit_id::text));

  select u.* into v_row from public.phoenix_crm_unplanned_visits u where u.visit_id = v_visit_id for update;
  -- A test/real mix-up must read as "not there", never as a permission error.
  if v_row.is_test <> v_is_test then
    raise exception 'phoenix_crm:unplanned_not_found';
  end if;
  if v_expected is distinct from v_row.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  v_from := v_row.status;
  if v_from not in ('manager_pending', 'sfe_pending') then
    raise exception 'phoenix_crm:unplanned_decided';
  end if;
  -- The stages run in order: the SFE cannot sign off a visit the manager has not seen, and the
  -- manager cannot decide one that has already left him.
  if (v_stage = 'manager') <> (v_from = 'manager_pending') then
    raise exception 'phoenix_crm:unplanned_wrong_stage';
  end if;

  if v_decision = 'refuse' then
    v_to := 'refused';
  elsif v_from = 'manager_pending' then
    v_to := 'sfe_pending';
  else
    v_to := 'approved';
  end if;

  update public.phoenix_crm_unplanned_visits u
  set status = v_to,
      manager_decided_by_hr_id = case when v_stage = 'manager' then v_actor else u.manager_decided_by_hr_id end,
      manager_decided_at = case when v_stage = 'manager' then now() else u.manager_decided_at end,
      manager_note = case when v_stage = 'manager' then v_note else u.manager_note end,
      sfe_decided_by_hr_id = case when v_stage = 'sfe' then v_actor else u.sfe_decided_by_hr_id end,
      sfe_decided_at = case when v_stage = 'sfe' then now() else u.sfe_decided_at end,
      sfe_note = case when v_stage = 'sfe' then v_note else u.sfe_note end,
      decided_at = case when v_to in ('approved', 'refused') then now() else null end,
      version = u.version + 1,
      updated_at = now()
  where u.visit_id = v_visit_id
  returning u.* into v_row;

  insert into public.phoenix_crm_unplanned_visit_events
    (visit_id, event_type, actor_hr_id, actor_role, actor_stage, from_status, to_status, version, note)
  values
    (v_visit_id, case when v_decision = 'refuse' then 'refused' else 'approved' end,
     v_actor, v_role, v_stage, v_from, v_to, v_row.version, v_note);

  return jsonb_build_object(
    'visit_id', v_row.visit_id,
    'seat_id', v_row.seat_id,
    'rep_hr_id', v_row.rep_hr_id,
    'customer_id', v_row.customer_id,
    'visit_date', v_row.visit_date,
    'status', v_row.status,
    'version', v_row.version
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_unplanned_visit(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_decide_validation_review(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_decide_validation_review(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'review_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_decision text := coalesce(p ->> 'decision', '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  -- what the rep is told about his own photo (2026-10-08). Accepted null here and REQUIRED by the
  -- service; the column CHECK is what guarantees the value is one of the eight.
  v_reason text := nullif(trim(coalesce(p ->> 'refusal_reason', '')), '');
  v_review public.phoenix_crm_validation_reviews%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_place public.phoenix_crm_places%rowtype;
  v_validated boolean := false;
  v_reopened boolean := false;
begin
  if v_id is null or v_actor is null or v_decision not in ('approve', 'reject')
    or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select r.* into v_review from public.phoenix_crm_validation_reviews r where r.id = v_id;
  if not found then
    raise exception 'phoenix_crm:review_not_found';
  end if;
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_review.seat_id));
  select r.* into v_review from public.phoenix_crm_validation_reviews r where r.id = v_id for update;
  -- 🔴 THE ONE EDIT OF THIS MIGRATION (owner, 2026-10-15: "make admin able to reject validation even
  -- if approved before"). A REJECT of an APPROVED review is the undo of that approval and runs the
  -- reject branch below exactly as a held review's rejection does — the place is retired, the
  -- customer goes back to To validate when it was his only one, reopened_at is stamped and the rep is
  -- told what is wrong with his photo. Everything else still raises review_decided: approving an
  -- approved review changes nothing, and a rejected one is reversed by
  -- phoenix_crm_restore_validation, which checks the place is still retired before it brings it back.
  if not (v_review.status = 'approved' and v_decision = 'reject') and v_review.status <> 'pending' then
    raise exception 'phoenix_crm:review_decided';
  end if;

  select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_review.customer_id for update;
  select pl.* into v_place from public.phoenix_crm_places pl where pl.id = v_review.place_id for update;

  if v_decision = 'approve' then
    update public.phoenix_crm_validation_reviews
    set status = 'approved', decided_by_hr_id = v_actor, decided_at = now(), decision_note = v_note
    where id = v_id;

    if v_review.kind = 'validation' and v_customer.status = 'pending' and v_place.status = 'active' then
      update public.phoenix_crm_customers c
      set status = 'active',
          validated_at = now(),
          validated_by_hr_id = v_review.created_by_hr_id,
          dropped_reason = null,
          dropped_note = null,
          status_changed_at = now(),
          updated_at = now()
      where c.id = v_customer.id;
      v_validated := true;

      with withdrawn as (
        update public.phoenix_crm_list_requests q
        set status = 'withdrawn',
            stage = null,
            decided_at = now(),
            decided_by_hr_id = v_actor,
            decision_note = 'Validated instead of dropped'
        where q.seat_id = v_review.seat_id
          and q.is_test = v_review.is_test
          and q.kind = 'drop'
          and q.status = 'pending'
          and (
            q.customer_id = v_customer.id
            or (q.customer_id is null and v_customer.reference_contact_crm_id is not null and q.reference_contact_crm_id = v_customer.reference_contact_crm_id)
          )
        returning q.id
      )
      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      select v_review.seat_id, v_customer.id, w.id, 'request_withdrawn', v_actor, jsonb_build_object('why', 'validated'), v_review.is_test
      from withdrawn w;
    end if;

    insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
    values (
      v_review.seat_id, v_customer.id, v_review.place_id, 'validation_review_approved', v_actor,
      jsonb_build_object('review_id', v_id, 'note', v_note, 'validated', v_validated), v_review.is_test
    );
  else
    update public.phoenix_crm_validation_reviews
    set status = 'rejected', decided_by_hr_id = v_actor, decided_at = now(), decision_note = v_note,
        refusal_reason = v_reason
    where id = v_id;

    if v_place.status = 'active' then
      update public.phoenix_crm_places pl
      set status = 'retired', retired_at = now(), retired_by_hr_id = v_actor, updated_at = now()
      where pl.id = v_place.id;
      insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
      values (
        v_review.seat_id, v_customer.id, v_place.id, 'place_retired', v_actor,
        jsonb_build_object('reason', coalesce(v_note, 'The location could not be confirmed against Google Maps.'), 'label', v_place.label,
          'lat', v_place.lat, 'lon', v_place.lon, 'why', 'validation_rejected'),
        v_review.is_test
      );
    end if;

    if v_customer.status = 'active' and not exists (
      select 1 from public.phoenix_crm_places pl where pl.customer_id = v_customer.id and pl.status = 'active'
    ) then
      update public.phoenix_crm_customers c
      set status = 'pending', validated_at = null, validated_by_hr_id = null, status_changed_at = now(), updated_at = now()
      where c.id = v_customer.id;
      v_reopened := true;
      insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
      values (v_review.seat_id, v_customer.id, 'customer_pending', v_actor,
        jsonb_build_object('reference_contact_crm_id', v_customer.reference_contact_crm_id, 'why', 'validation_rejected'), v_review.is_test);
    end if;

    -- he is waiting to capture this place again, from now (2026-10-08).
    -- 🔴 c.status is read from the TABLE, deliberately, so it sees the reopen above; and this fires
    -- for a customer who was ALREADY pending (a held first validation), which v_reopened never does.
    update public.phoenix_crm_customers c
    set reopened_at = now(), updated_at = now()
    where c.id = v_customer.id and c.status = 'pending';

    insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
    values (
      v_review.seat_id, v_customer.id, v_review.place_id, 'validation_review_rejected', v_actor,
      jsonb_build_object('review_id', v_id, 'note', v_note, 'reopened', v_reopened, 'refusal_reason', v_reason), v_review.is_test
    );
  end if;

  return jsonb_build_object(
    'review_id', v_id,
    'status', case when v_decision = 'approve' then 'approved' else 'rejected' end,
    'seat_id', v_review.seat_id,
    'customer_id', v_customer.id,
    'is_test', v_review.is_test,
    'validated', v_validated,
    'reopened', v_reopened,
    -- so the service notifies the rep without a second read. rep_hr_id is the rep who VALIDATED,
    -- never the person deciding: he is the one whose photo this is.
    'rep_hr_id', v_review.created_by_hr_id,
    'customer_name', v_customer.name,
    'refusal_reason', case when v_decision = 'reject' then v_reason else null end
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_decide_validation_review(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_doctor_list_reps(); Type: FUNCTION; Schema: public; Owner: postgres
