--
-- Name: phoenix_crm_edit_double_visit_request_days(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_edit_double_visit_request_days(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_days date[];
  v_request public.phoenix_crm_double_visit_requests%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_changed boolean := false;
  v_day date;
begin
  if v_id is null or v_seat is null or v_actor is null
     or jsonb_typeof(p -> 'days') is distinct from 'array' then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select coalesce(array_agg(d order by d), '{}'::date[]) into v_days
  from (select distinct (value #>> '{}')::date as d from jsonb_array_elements(p -> 'days')) days;
  if cardinality(v_days) < 1 or cardinality(v_days) > 3
     or cardinality(v_days) <> jsonb_array_length(p -> 'days') then
    raise exception 'phoenix_crm:double_visit_bad_days';
  end if;
  foreach v_day in array v_days loop
    if v_day < v_today or v_day > v_today + 27 or extract(isodow from v_day) = 5 then
      raise exception 'phoenix_crm:double_visit_bad_days';
    end if;
  end loop;

  select r.* into v_request
  from public.phoenix_crm_double_visit_requests r
  where r.id = v_id and r.seat_id = v_seat and r.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:double_visit_not_found';
  end if;
  -- Only the rep who raised it edits it; the application proves who the actor is.
  if v_request.rep_hr_id <> v_actor then
    raise exception 'phoenix_crm:double_visit_not_yours';
  end if;

  if v_request.days is distinct from v_days then
    update public.phoenix_crm_double_visit_requests r
    set days = v_days, edited_at = now(), edit_count = r.edit_count + 1, updated_at = now()
    where r.id = v_request.id
    returning * into v_request;
    -- The day a person agreed to is gone: back to waiting, asked again about the new days.
    update public.phoenix_crm_double_visit_request_people q
    set status = 'waiting', visit_on = null, answered_at = null, updated_at = now()
    where q.request_id = v_request.id and q.status = 'accepted' and not (q.visit_on = any (v_days));
    v_changed := true;
  end if;

  select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_request.customer_id;

  return jsonb_build_object(
    'id', v_request.id,
    'changed', v_changed,
    'seat_id', v_request.seat_id,
    'customer_name', v_customer.name,
    'customer_list_type', v_customer.list_type,
    'days', to_jsonb(v_request.days),
    'is_test', v_request.is_test,
    'people', coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'hr_id', q.asked_hr_id, 'role', q.role, 'status', q.status, 'visit_on', q.visit_on) order by q.created_at, q.asked_hr_id)
      from public.phoenix_crm_double_visit_request_people q
      where q.request_id = v_request.id
    ), '[]'::jsonb)
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_edit_double_visit_request_days(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_edit_visit_detail(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_edit_visit_detail(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_id uuid := nullif(p ->> 'visit_id', '')::uuid;
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  -- The long account written afterwards. Empty clears it; the before-image keeps what it said.
  v_detail text := nullif(trim(coalesce(p ->> 'detail_comment', '')), '');
  -- The outcome. Read here and validated below rather than trusted: the only thing the caller may do
  -- with a value it does not recognise is drop it (visit-outcome.ts), and the same holds here.
  v_next_step text := nullif(btrim(p ->> 'next_step'), '');
  v_next_step_on date := nullif(p ->> 'next_step_on', '')::date;
  v_objection text := nullif(btrim(p ->> 'objection'), '');
  v_objection_note text := nullif(regexp_replace(trim(coalesce(p ->> 'objection_note', '')), '\s+', ' ', 'g'), '');
  v_samples jsonb := p -> 'samples_given';
  v_availability jsonb := p -> 'product_availability';
  -- ADD-ONLY (owner, 2026-10-15). Null on the wire whenever he is not adding one.
  v_pharmacy text := nullif(trim(coalesce(p ->> 'pharmacy_name', '')), '');
  v_new_pharmacy text;
  v_visit public.phoenix_crm_visits%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_is_pharmacy boolean;
  -- The pharmacies a NEWLY added name points at, filed as visits of their own, exactly as
  -- phoenix_crm_save_visit files them on the day the rep logs the visit.
  v_links jsonb;
  v_entry jsonb;
  v_entry_name text;
  v_entry_id uuid;
  v_entry_new boolean;
  v_link public.phoenix_crm_customers%rowtype;
  v_link_visit uuid;
  v_link_created boolean;
  v_filed jsonb := '[]'::jsonb;
begin
  if v_id is null or v_seat is null or v_actor is null
    or (v_detail is not null and char_length(v_detail) > 2000)
    or (v_pharmacy is not null and char_length(v_pharmacy) > 120) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  -- The same per-territory lock the rep's own save takes, so a save and an edit cannot interleave.
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select v.* into v_visit
  from public.phoenix_crm_visits v
  where v.id = v_id
    and v.seat_id = v_seat
    and v.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:visit_not_found';
  end if;

  -- HIS OWN VISIT, AND ONLY HIS. A visit a manager entered for himself carries no rep at all; one the
  -- Super Admin entered for a visit the rep missed logging carries the REP, so it is the rep's to
  -- complete — he made the visit, the Super Admin only recorded it.
  if v_visit.rep_hr_id is null or v_visit.rep_hr_id <> v_actor then
    raise exception 'phoenix_crm:visit_not_yours';
  end if;

  -- The pharmacy visit a doctor's visit filed is part of that submission, never a second piece of
  -- work, so its detail belongs to the visit it came from.
  if v_visit.linked_from_visit_id is not null then
    raise exception 'phoenix_crm:visit_is_linked';
  end if;

  -- A visit copied from the old system is history (20261029212200). A pharmacy named on it would file a
  -- linked visit dated before his start and carrying no import mark, which every reader counts as real.
  if v_visit.imported_from_ireports360_at is not null then
    raise exception 'phoenix_crm:visit_is_history';
  end if;

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_visit.customer_id;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  v_is_pharmacy := v_customer.list_type = 'Pharmacy';

  -- ADD-ONLY. At a pharmacy the pharmacy IS the customer and the column is its name, so there is
  -- nothing to add; on a visit that already names one, changing it would delete the visit that name
  -- filed.
  if v_pharmacy is not null and (v_is_pharmacy or v_visit.pharmacy_name is not null) then
    raise exception 'phoenix_crm:pharmacy_name_fixed';
  end if;
  v_new_pharmacy := coalesce(v_visit.pharmacy_name, v_pharmacy);

  -- An unknown value is DROPPED, never raised — a phone one release behind must not cost a rep the
  -- detail he just typed. The dependants go with their parent, so the row can never say "by 30 Sept"
  -- under "Nothing to follow", or carry a note under "No objection".
  if v_next_step is not null and v_next_step not in ('follow_up', 'send_data', 'arrange_double', 'invite_event', 'pharmacy_stock', 'none') then
    v_next_step := null;
  end if;
  if v_next_step is null or v_next_step = 'none' then
    v_next_step_on := null;
  end if;
  if v_objection is not null and v_objection not in ('price', 'efficacy', 'safety', 'competitor', 'formulary', 'no_time', 'none') then
    v_objection := null;
  end if;
  if v_objection is null or v_objection = 'none' then
    v_objection_note := null;
  else
    v_objection_note := left(v_objection_note, 300);
  end if;

  -- A bag that is not a bag LEAVES WHAT THE VISIT HAS — deliberately NOT save_visit's '{}', which is
  -- that function's default for a brand-new row. Here an empty object is a real instruction ("I left
  -- nothing after all"), so a malformed one must not be read as that instruction and wipe his answers.
  if v_samples is null or jsonb_typeof(v_samples) <> 'object' or (select count(*) from jsonb_object_keys(v_samples)) > 20 then
    v_samples := v_visit.samples_given;
  end if;
  if v_availability is null or jsonb_typeof(v_availability) <> 'object' then
    v_availability := v_visit.product_availability;
  end if;

  -- Nothing different: no copy, no write, and the caller is told so.
  if v_detail is not distinct from v_visit.detail_comment
    and v_next_step is not distinct from v_visit.next_step
    and v_next_step_on is not distinct from v_visit.next_step_on
    and v_objection is not distinct from v_visit.objection
    and v_objection_note is not distinct from v_visit.objection_note
    and v_samples is not distinct from v_visit.samples_given
    and v_availability is not distinct from v_visit.product_availability
    and v_new_pharmacy is not distinct from v_visit.pharmacy_name then
    return jsonb_build_object('visit_id', v_id, 'changed', false, 'linked_pharmacies', '[]'::jsonb);
  end if;

  -- The copy first, so nothing is overwritten that is not already kept.
  insert into public.phoenix_crm_visit_edits (
    visit_id, seat_id, customer_id, visit_date, edited_by_hr_id, is_test, before_edit, after_edit
  )
  values (
    v_visit.id, v_visit.seat_id, v_visit.customer_id, v_visit.visit_date, v_actor, v_visit.is_test,
    jsonb_build_object(
      'detail_comment', v_visit.detail_comment,
      'next_step', v_visit.next_step,
      'next_step_on', v_visit.next_step_on,
      'objection', v_visit.objection,
      'objection_note', v_visit.objection_note,
      'samples_given', v_visit.samples_given,
      'product_availability', v_visit.product_availability,
      'pharmacy_name', v_visit.pharmacy_name
    ),
    jsonb_build_object(
      'detail_comment', v_detail,
      'next_step', v_next_step,
      'next_step_on', v_next_step_on,
      'objection', v_objection,
      'objection_note', v_objection_note,
      'samples_given', v_samples,
      'product_availability', v_availability,
      'pharmacy_name', v_new_pharmacy,
      -- Which door wrote it. The Super Admin's correction writes no such key, so a reader can tell
      -- the two apart without reading the shape of the blob.
      'edited_by', 'rep_detail'
    )
  );

  update public.phoenix_crm_visits
  set detail_comment = v_detail,
      next_step = v_next_step,
      next_step_on = v_next_step_on,
      objection = v_objection,
      objection_note = v_objection_note,
      samples_given = v_samples,
      product_availability = v_availability,
      pharmacy_name = v_new_pharmacy,
      detail_edited_at = now(),
      detail_edited_by_hr_id = v_actor
  where id = v_id;

  -- THE PHARMACY HE JUST NAMED IS A VISIT TO THAT PHARMACY TOO (owner, 2026-10-03), filed exactly as
  -- phoenix_crm_save_visit files it: on the PARENT's day and at the parent's reading, no photo and no
  -- place of its own, one box able to name several, five at most, a name the caller could not place
  -- skipped and never raised, and a pharmacy already visited that day keeping the visit it has.
  if not v_is_pharmacy and v_visit.pharmacy_name is null and v_pharmacy is not null then
    v_links := case
      when jsonb_typeof(p -> 'linked_pharmacies') = 'array' then p -> 'linked_pharmacies'
      else '[]'::jsonb
    end;

    for v_entry in
      select e.value from jsonb_array_elements(v_links) with ordinality as e(value, n) order by e.n limit 5
    loop
      v_entry_name := nullif(trim(coalesce(v_entry ->> 'name', '')), '');
      v_entry_id := case
        when (v_entry ->> 'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (v_entry ->> 'id')::uuid
      end;
      v_entry_new := coalesce((v_entry ->> 'new') = 'true', false);
      v_link := null;
      v_link_visit := null;
      v_link_created := false;
      continue when v_entry_name is null or char_length(v_entry_name) > 120;

      if v_entry_id is not null then
        select c.* into v_link
        from public.phoenix_crm_customers c
        where c.id = v_entry_id
          and c.seat_id = v_seat
          and c.is_test = v_is_test
          and c.list_type = 'Pharmacy'
          and c.status in ('active', 'pending', 'outside');
      elsif v_entry_new then
        -- The caller decided "new" from a read taken before this call, so the name is checked again
        -- here, under the SAME lock phoenix_crm_add_pharmacy takes: two edits naming one new pharmacy,
        -- or an edit racing Add a pharmacy, file one pharmacy, never two rows for it.
        perform pg_advisory_xact_lock(hashtext('phoenix_crm_add_pharmacy|' || v_seat || '|' || v_is_test::text));
        select c.* into v_link
        from public.phoenix_crm_customers c
        where c.seat_id = v_seat
          and c.is_test = v_is_test
          and c.list_type = 'Pharmacy'
          and c.status in ('active', 'pending', 'outside')
          and lower(btrim(regexp_replace(c.name, '\s+', ' ', 'g'))) = lower(btrim(regexp_replace(v_entry_name, '\s+', ' ', 'g')))
        order by (c.status = 'active') desc, c.id
        limit 1;
        if v_link.id is null then
          insert into public.phoenix_crm_customers (
            seat_id, line_code, list_type, name, origin, status, created_by_hr_id, is_test, intake_note
          )
          values (
            v_seat, v_customer.line_code, 'Pharmacy', v_entry_name, 'new', 'pending', v_actor, v_is_test,
            left('Added when the visit to ' || v_customer.name || ' named it.', 300)
          )
          returning * into v_link;
          v_link_created := true;
        end if;
      end if;

      if v_link.id is not null then
        insert into public.phoenix_crm_visits (
          id, seat_id, line_code, customer_id, list_type, visit_date, captured_at, kind, rep_hr_id, manager_hr_id,
          senior_hr_id, product_manager_hr_id, entered_by_hr_id, products, comment, pharmacy_name, product_availability,
          lat, lon, accuracy_meters, place_id, distance_meters, location_flag, is_test,
          is_unplanned, unplanned_kind, samples_given,
          capture_source, time_anchor_id, offline_seconds, synced_at,
          linked_from_visit_id
        )
        values (
          gen_random_uuid(), v_seat, v_visit.line_code, v_link.id, 'Pharmacy', v_visit.visit_date, v_visit.captured_at,
          'single', v_visit.rep_hr_id,
          case when v_visit.rep_hr_id is null then v_visit.manager_hr_id end,
          null, null, v_actor, v_visit.products, null, v_entry_name, '{}'::jsonb,
          v_visit.lat, v_visit.lon, v_visit.accuracy_meters,
          null, null, 'no_place', v_is_test,
          false, null, '{}'::jsonb,
          v_visit.capture_source, null, null, now(),
          v_id
        )
        on conflict (seat_id, customer_id, visit_date, is_test) do nothing
        returning id into v_link_visit;
        v_filed := v_filed || jsonb_build_array(jsonb_build_object(
          'customer_id', v_link.id, 'name', v_link.name, 'visit_id', v_link_visit, 'created', v_link_created
        ));
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'visit_id', v_id,
    'changed', true,
    'detail_edited_at', now(),
    'linked_pharmacies', v_filed
  );
end;
$_$;

ALTER FUNCTION public.phoenix_crm_edit_visit_detail(p jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_edit_visit_detail(p jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_edit_visit_detail(p jsonb) IS 'The REP fills in or corrects his own saved visit''s detail (owner, 2026-10-15): the detailed comment, the objection and its note, the next step and its day, what he left, the pharmacy stock answers, and a pharmacy name the visit does not yet carry. It never touches the customer, the day, the time, the location, the photo, the voice note, AM/PM, who was on the visit or the products, and it notifies nobody. What each save replaced is kept in phoenix_crm_visit_edits.';

--
-- Name: phoenix_crm_ensure_reference_customers(text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_ensure_reference_customers(p_seat_id text, p_line_code text, p_is_test boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p_seat_id, '')), '');
  v_line text := nullif(trim(coalesce(p_line_code, '')), '');
  v_count integer := 0;
begin
  -- A territory with no line yet cannot hold customers; it also cannot plan, so there is nothing to do.
  if v_seat is null or v_line is null then
    return 0;
  end if;

  with missing as (
    select r.*
    from public.phoenix_crm_seat_reference(array[v_seat], p_is_test) r
    where r.customer_id is null
      -- Both columns are NOT NULL on their tables. seat_reference cannot return a null rep or a blank
      -- name today, and if that ever changes this skips the one row rather than failing the whole
      -- read — the rep's list must never fail to open.
      and r.source_hr_id is not null
      and nullif(trim(coalesce(r.name, '')), '') is not null
      -- A doctor the rep added himself already IS a customer under his own id. seat_reference finds him
      -- now; this stays so that a later change to it can never mint his copy (and so that the insert
      -- trigger below is never what a read of the list runs into).
      and not exists (
        select 1
        from public.phoenix_crm_customers own
        where own.seat_id = v_seat
          and own.is_test = p_is_test
          and own.own_contact_crm_id = r.contact_crm_id
      )
  ),
  minted as (
    insert into public.phoenix_crm_customers (
      seat_id, line_code, list_type, name, speciality, grade, origin, reference_contact_crm_id,
      status, created_by_hr_id, is_test
    )
    select
      v_seat, v_line, m.list_type, left(m.name, 200), left(m.speciality, 120), m.grade, 'reference',
      m.contact_crm_id, 'pending', m.source_hr_id, p_is_test
    from missing m
    on conflict (seat_id, reference_contact_crm_id, is_test) where reference_contact_crm_id is not null
      do nothing
    returning id, reference_contact_crm_id, created_by_hr_id
  )
  insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
  select
    v_seat, mi.id, 'customer_pending', mi.created_by_hr_id,
    jsonb_build_object('reference_contact_crm_id', mi.reference_contact_crm_id), p_is_test
  from minted mi;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

ALTER FUNCTION public.phoenix_crm_ensure_reference_customers(p_seat_id text, p_line_code text, p_is_test boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_expire_manager_plan_edit_requests(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_expire_manager_plan_edit_requests(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_expired jsonb;
begin
  with expired as (
    update public.phoenix_crm_manager_plan_edit_requests r
    set status = 'expired',
        decided_at = now(),
        decided_by_hr_id = null,
        decided_role = 'system',
        version = r.version + 1,
        updated_at = now()
    where r.status in ('pending', 'first_approved')
      and r.week_start + 5 < v_today
    returning r.*
  ), trail as (
    insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, details)
    select e.plan_id, 'edit_expired', 'SYSTEM', 'system', pl.status, pl.status, pl.version, jsonb_build_object('request_id', e.id)
    from expired e
    join public.phoenix_crm_manager_plans pl on pl.id = e.plan_id
    returning 1
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'request_id', e.id, 'plan_id', e.plan_id, 'manager_hr_id', e.manager_hr_id,
           'approver_hr_id', e.approver_hr_id, 'week_start', e.week_start, 'is_test', e.is_test)), '[]'::jsonb)
  into v_expired
  from expired e;
  -- A data-modifying WITH runs to completion whether or not the outer query reads it, so the trail is
  -- written for every row the update expired.
  return jsonb_build_object('expired', v_expired);
end;
$$;

ALTER FUNCTION public.phoenix_crm_expire_manager_plan_edit_requests(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_expire_manager_single_visit_days(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_expire_manager_single_visit_days(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_expired jsonb;
begin
  with expired as (
    update public.phoenix_crm_manager_single_visit_days d
    set status = 'expired',
        decided_at = now(),
        decided_by_hr_id = null,
        decided_role = 'system',
        version = d.version + 1,
        updated_at = now()
    where d.status in ('pending', 'first_approved')
      and d.visit_date < v_today
    returning d.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'request_id', e.id, 'manager_hr_id', e.manager_hr_id, 'manager_seat_id', e.manager_seat_id,
           'visit_date', e.visit_date, 'week_start', e.week_start, 'is_test', e.is_test)), '[]'::jsonb)
  into v_expired
  from expired e;
  return jsonb_build_object('expired', v_expired);
end;
$$;

ALTER FUNCTION public.phoenix_crm_expire_manager_single_visit_days(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_expire_plan_edit_requests(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_expire_plan_edit_requests(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_row record;
  v_result jsonb;
  v_closed jsonb := '[]'::jsonb;
  v_stale integer := 0;
  v_failed integer := 0;
begin
  if v_actor is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  for v_row in
    select r.id, r.seat_id, r.week_start, r.rep_hr_id, r.status, r.version, r.is_test
    from public.phoenix_crm_plan_edit_requests r
    where r.status in ('manager_pending', 'sfe_pending', 'hr_pending')
      and r.week_start + 5 < v_today
    order by r.created_at
  loop
    v_stale := v_stale + 1;
    begin
      v_result := public.phoenix_crm_decide_plan_edit_request(jsonb_build_object(
        'request_id', v_row.id,
        'stage', case v_row.status when 'manager_pending' then 'manager' when 'sfe_pending' then 'sfe' else 'hr' end,
        'decision', case when v_row.status = 'hr_pending' then 'acknowledge' else 'approve' end,
        'actor_hr_id', v_actor,
        'actor_role', 'System',
        'note', null,
        'expected_version', v_row.version,
        'is_test', v_row.is_test
      ));
    exception
      when others then
        v_failed := v_failed + 1;
        continue;
    end;
    if v_result ->> 'status' = 'expired' then
      v_closed := v_closed || jsonb_build_array(jsonb_build_object(
        'request_id', v_result ->> 'request_id',
        'plan_id', v_result ->> 'plan_id',
        'seat_id', v_row.seat_id,
        'week_start', v_row.week_start,
        'rep_hr_id', v_row.rep_hr_id,
        'from_status', v_row.status,
        'version', (v_result ->> 'version')::integer,
        'is_test', v_row.is_test
      ));
    else
      v_failed := v_failed + 1;
    end if;
  end loop;

  return jsonb_build_object('cairo_today', v_today, 'stale', v_stale, 'failed', v_failed, 'closed', v_closed);
end;
$$;

ALTER FUNCTION public.phoenix_crm_expire_plan_edit_requests(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_fold_name(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_fold_name(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  -- The same rule as `normalizeContactName`, in the same order: NFKC, then the letter folds, then
  -- the diacritics and the tatweel, then everything that is not a letter or a number becomes a
  -- space, then the honorifics go, then the words are rejoined with single spaces.
  --
  -- Returns '' for a name that folds away to nothing. A caller must treat that as "no name" and
  -- never as a key — an empty key would collide every unnamed row onto one customer. The loader
  -- only ever reaches this with a non-empty name, because it refuses a nameless row earlier.
  select coalesce(btrim(string_agg(word, ' ' order by ord)), '')
  from (
    select word, ord
    from unnest(
      regexp_split_to_array(
        btrim(
          regexp_replace(
            regexp_replace(
              translate(lower(normalize(coalesce(p_name, ''), NFKC)), 'أإآٱىة', 'اااايه'),
              '[ًٌٍَُِّْٰـ]', '', 'g'),
            '[^[:alnum:][:space:]]', ' ', 'g')),
        '\s+')
    ) with ordinality as t(word, ord)
  ) words
  where word <> ''
    and word <> all (array[
      'د', 'دكتور', 'دكتوره', 'دكتورة', 'الدكتور', 'الدكتوره', 'دكتره',
      'dr', 'drs', 'doctor', 'prof', 'professor', 'mr', 'mrs', 'ms'
    ]);
$$;

ALTER FUNCTION public.phoenix_crm_fold_name(p_name text) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_fold_name(p_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_fold_name(p_name text) IS 'The Phoenix CRM customer name key: the SQL half of normalizeContactName. Folds Arabic orthography, diacritics, punctuation, honorifics and case so one customer has one key. Pinned by tests/phoenix-crm-customer-name-fold.test.ts.';

--
-- Name: phoenix_crm_hold_full_name(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_hold_full_name(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_name text := nullif(regexp_replace(trim(coalesce(p ->> 'name', '')), '\s+', ' ', 'g'), '');
  v_score smallint := nullif(p ->> 'score', '')::smallint;
  v_board jsonb := coalesce(p -> 'board_names', '[]'::jsonb);
  v_customer public.phoenix_crm_customers%rowtype;
begin
  if v_seat is null or v_actor is null or v_customer_id is null or v_name is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id
    and c.seat_id = v_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.status = 'dropped' then
    raise exception 'phoenix_crm:customer_dropped';
  end if;

  update public.phoenix_crm_customers c
  set full_name_held = left(v_name, 200),
      full_name_held_at = now(),
      full_name_held_by_hr_id = v_actor,
      full_name_held_score = v_score,
      full_name_held_board = v_board,
      updated_at = now()
  where c.id = v_customer.id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer.id, 'full_name_held', v_actor,
    jsonb_build_object('name', v_customer.name, 'full_name', left(v_name, 200), 'score', v_score, 'board_names', v_board),
    v_is_test
  );

  return jsonb_build_object('customer_id', v_customer.id, 'held', true);
end;
$$;

ALTER FUNCTION public.phoenix_crm_hold_full_name(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_import_ireports360_history(text, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_import_ireports360_history(p_seat text DEFAULT NULL::text, p_apply boolean DEFAULT false, p_after_start boolean DEFAULT false, p_leavers boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_seat text := nullif(btrim(coalesce(p_seat, '')), '');
  v_now timestamptz := now();
  v_archive_written integer := 0;
  v_holders_written integer := 0;
  v_written integer := 0;
  v_mapped integer := 0;
  v_unresolved integer := 0;
  v_seats jsonb;
begin
  if p_apply and v_seat is null then
    raise exception 'phoenix_crm:import_needs_a_seat'
      using hint = 'Apply one seat at a time: scripts/phoenix-crm-import-ireports360-history.ts loops them.';
  end if;

  if p_after_start and p_leavers then
    raise exception 'phoenix_crm:import_one_mode_at_a_time'
      using hint = 'Run --after-start and --leavers separately.';
  end if;

  -- One run at a time, so two runs never race for the same holder numbers.
  perform pg_advisory_xact_lock(hashtext('public.phoenix_crm_import_ireports360_history'));

  drop table if exists pg_temp.phx_import_links;
  drop table if exists pg_temp.phx_import_roles;
  drop table if exists pg_temp.phx_import_src;
  drop table if exists pg_temp.phx_import_archive;
  drop table if exists pg_temp.phx_import_slots;
  drop table if exists pg_temp.phx_import_holders;
  drop table if exists pg_temp.phx_import_keyed;
  drop table if exists pg_temp.phx_import_rows;
  drop table if exists pg_temp.phx_import_written;

  -- A doctor the rep added himself carries a Phoenix-only id from the reserved band and no vendor id, so
  -- only a confirmed identity link can say which old contact he is.
  create temp table phx_import_links on commit drop as
  select v.source_id::bigint as contact_crm_id, p.source_id::uuid as customer_id
  from public.customer_identity_links v
  join public.customer_identity_links p on p.master_id = v.master_id and p.source = 'phoenix_crm'
  where v.source = 'ireports360'
    and v.source_id ~ '^[0-9]{1,18}$'
    and p.source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  -- Asked for every customer of the seat on every old visit, so it is looked up, never scanned.
  create index on phx_import_links (contact_crm_id, customer_id);
  analyze phx_import_links;

  -- With no seat on the visit's day, the partner is judged by app role, as the visit form offers people
  -- (visit-ask-rules.ts): an active login first, never a test persona.
  create temp table phx_import_roles on commit drop as
  select distinct on (lower(u.hr_id)) lower(u.hr_id) as hr, u.role
  from public.app_auth_users u
  where u.hr_id is not null and not u.is_test_persona
  order by lower(u.hr_id), u.is_active desc, u.updated_at desc;

  -- Every old visit in scope, already-copied ones included (they are counted, never written again).
  create temp table phx_import_src on commit drop as
  with cur as (
    select o.seat_id, o.line_code, lower(o.occupant_canonical_hr_id) as hr, e.hr_id as rep_hr_id
    from public.au_v_seat_occupancy_all o
    join public.employees e on lower(e.hr_id) = lower(o.occupant_canonical_hr_id)
    where not p_leavers
      and o.effective_to is null
      and o.node_type = 'person'
      and o.seat_id like '%-REP-%'
      and e.employment_status = 'active'
      and (v_seat is null or o.seat_id = v_seat)
    union
    -- LEAVERS (owner, 7 Nov 2026): a person on NO current territory today — resigned, or moved off the
    -- REP seats — keeps the visits he made on a territory, filed under the seat he held THAT day, any
    -- status. A current rep's day on another seat stays out, as the first run decided.
    select o.seat_id, o.line_code, lower(o.occupant_canonical_hr_id) as hr, e.hr_id as rep_hr_id
    from public.au_v_seat_occupancy_all o
    join public.employees e on lower(e.hr_id) = lower(o.occupant_canonical_hr_id)
    where p_leavers
      and o.node_type = 'person'
      and o.seat_id like '%-REP-%'
      and (v_seat is null or o.seat_id = v_seat)
      and not exists (
        select 1 from public.au_v_seat_occupancy_all now_on
        where lower(now_on.occupant_canonical_hr_id) = lower(o.occupant_canonical_hr_id)
          and now_on.node_type = 'person' and now_on.effective_to is null and now_on.seat_id like '%-REP-%'
      )
  ),
  st as (
    select s.seat_id, min(s.starts_on) as starts_on
    from public.phoenix_crm_started_team_seats() s
    group by s.seat_id
  )
  select
    c.seat_id,
    c.line_code,
    c.rep_hr_id,
    iv.crm_visit_id,
    iv.visit_date,
    iv.visit_type,
    contact.id as contact_crm_id,
    nullif(btrim(iv.contact_name), '') as contact_name,
    nullif(btrim(iv.speciality), '') as speciality,
    nullif(btrim(iv.comment), '') as comment,
    case when upper(btrim(coalesce(iv.ampm, ''))) = 'AM' then 'AM' else 'PM' end as ampm_list,
    case
      when iv.visit_date_time is not null and (iv.visit_date_time at time zone 'UTC')::date = iv.visit_date
        then (iv.visit_date_time at time zone 'UTC') at time zone 'Africa/Cairo'
      else (iv.visit_date + time '12:00') at time zone 'Africa/Cairo'
    end as captured_at,
    case when partner.kind is not null then partner.hr_id end as partner_hr_id,
    coalesce(partner.kind, 'single') as kind,
    -- The old system named somebody and the copy files nobody: the totals count these.
    (nullif(btrim(iv.double_hr_id), '') is not null and lower(btrim(iv.double_hr_id)) <> c.hr and partner.kind is null) as partner_dropped,
    cust.id as customer_id,
    cust.list_type as customer_list_type,
    exists (
      select 1 from public.phoenix_crm_imported_visit_sources s where s.crm_visit_id = iv.crm_visit_id
    ) as already_imported
  from cur c
  -- A leaver's seat is read whether or not its team has started: his days are dated by the seat he held.
  left join st on st.seat_id = c.seat_id
  join public.ireports360_visits iv on lower(iv.agent_hr_id) = c.hr
  -- 0 is no contact: a campaign visit, which goes on a holder.
  cross join lateral (select nullif(iv.contact_crm_id, 0) as id) contact
  left join lateral (
    select
      pe.hr_id,
      -- The visit's own day decides. In a manager's seat that day, an acting one included, he was a manager
      -- whatever he is now; in only other seats, a rep's say, he was no partner, even if promoted since.
      -- Product and training managers hold no seat, so they land on today's role, as does anyone whose seat
      -- history does not reach that far back. Anyone the visit form would not offer is not a partner at all.
      case
        when that_day.in_manager_seat then 'double'
        when that_day.seated then null
        when who.role in ('Product Manager', 'Group Product Manager', 'Training Manager') then 'product_manager'
        when who.role = 'Marketing Manager' and lower(c.line_code) = 'cns' then 'product_manager'
        when who.role in ('District Manager', 'Regional Manager', 'National Sales Manager') then 'double'
      end as kind
    from public.employees pe
    left join phx_import_roles r on r.hr = lower(pe.hr_id)
    -- Somebody who has left may have no login; the title says the same thing in other words.
    cross join lateral (
      select coalesce(r.role, case btrim(pe.job_title)
        when 'District Sales Manager' then 'District Manager'
        when 'Senior District Manager' then 'District Manager'
        when 'Regional Sales Manager' then 'Regional Manager'
        else btrim(pe.job_title)
      end) as role
    ) who
    cross join lateral (
      select
        count(*) > 0 as seated,
        coalesce(bool_or(split_part(o.seat_id, '-', 3) in ('DM', 'ADM', 'RSM', 'NSM')), false) as in_manager_seat
      from public.au_v_seat_occupancy_all o
      where lower(o.occupant_canonical_hr_id) = lower(pe.hr_id) and o.node_type = 'person'
        and o.effective_from <= iv.visit_date and (o.effective_to is null or o.effective_to >= iv.visit_date)
    ) that_day
    where lower(pe.hr_id) = lower(btrim(iv.double_hr_id))
      and lower(pe.hr_id) <> c.hr
    order by pe.hr_id
    limit 1
  ) partner on true
  left join lateral (
    select cu.id, cu.list_type
    from public.phoenix_crm_customers cu
    where cu.seat_id = c.seat_id
      and not cu.is_test
      and contact.id is not null
      and (
        cu.reference_contact_crm_id = contact.id
        or exists (select 1 from phx_import_links l where l.contact_crm_id = contact.id and l.customer_id = cu.id)
      )
    -- His own customer before an Archive copy an earlier run made, even when only a link names him.
    order by (cu.imported_from_ireports360_at is null) desc, (cu.reference_contact_crm_id is not distinct from contact.id) desc, cu.created_at, cu.id
    limit 1
  ) cust on true
  where (p_leavers or st.seat_id is not null)
    -- 🔴 ONLY A REGULAR VISIT WITH A CHECK-IN LOCATION IS A VISIT (owner, 7 Nov 2026). A campaign visit is
    -- retired and never copied; a regular visit with no located check-in is not a visit. "Located" is the
    -- one table phoenix_crm_prepare_ireports360_conversion fills, so this and the archive never disagree.
    and iv.visit_type = 0
    and contact.id is not null
    and exists (select 1 from public.phoenix_crm_ireports360_checkin_matches m where m.crm_visit_id = iv.crm_visit_id)
    -- The vendor's catch-all names nobody and its visits are not campaign visits, so they are not copied:
    -- every check-in, coverage and territory figure leaves it out.
    and iv.contact_crm_id is distinct from 100000
    and iv.visit_date >= date '2026-01-01'
    -- BEFORE THE START: the archive's history, as the first run copied it (29 Oct). AFTER IT (p_after_start;
    -- owner, 6 Nov 2026: "Keep + show in Phoenix"): a day from the team's start to the day before iReports360
    -- was retired on which the rep made NO Phoenix entry. The door already counts that day from iReports360;
    -- the copy only lets Phoenix CRM's own screens show it, and it moves no count, because the countable view
    -- and the entry-days trigger both skip a copied visit. A day he has an entry is Phoenix's, never copied.
    and (
      -- LEAVERS: every 2026 day before iReports360 was retired, except a day he has a Phoenix entry.
      (
        p_leavers
        and iv.visit_date < coalesce((select (k.vendor_sync_retired_at at time zone 'Africa/Cairo')::date from public.crm_cutover k where k.id), '-infinity'::date)
        and not exists (
          select 1 from public.phoenix_crm_rep_entry_days_cache e
          where e.hr_key = c.hr and e.entry_day = iv.visit_date
        )
      )
      or (not p_leavers and not p_after_start and iv.visit_date < st.starts_on)
      or (
        p_after_start
        and iv.visit_date >= st.starts_on
        and iv.visit_date < coalesce((select (k.vendor_sync_retired_at at time zone 'Africa/Cairo')::date from public.crm_cutover k where k.id), '-infinity'::date)
        and not exists (
          select 1 from public.phoenix_crm_rep_entry_days_cache e
          where e.hr_key = c.hr and e.entry_day = iv.visit_date
        )
      )
    )
    -- He held this seat that day; or he held no seat at all that day and it is a campaign visit, which
    -- names no territory's doctor. A day on any other seat, rep or manager, is that seat's history.
    and (
      exists (
        select 1 from public.au_v_seat_occupancy_all o
        where lower(o.occupant_canonical_hr_id) = c.hr and o.node_type = 'person'
          and o.seat_id = c.seat_id
          and o.effective_from <= iv.visit_date and (o.effective_to is null or o.effective_to >= iv.visit_date)
      )
      or (
        iv.visit_type = -8
        and not exists (
          select 1 from public.au_v_seat_occupancy_all o
          where lower(o.occupant_canonical_hr_id) = c.hr and o.node_type = 'person'
            and o.effective_from <= iv.visit_date and (o.effective_to is null or o.effective_to >= iv.visit_date)
        )
      )
    );

  -- Doctors the seat does not have: one Archive doctor each.
  create temp table phx_import_archive on commit drop as
  select
    a.seat_id,
    a.contact_crm_id,
    a.line_code,
    a.rep_hr_id,
    left(coalesce(nullif(btrim(cc.name), ''), a.latest_name, 'Old system doctor ' || a.contact_crm_id), 200) as name,
    left(coalesce(nullif(btrim(cc.speciality), ''), a.latest_speciality), 120) as speciality,
    -- A pharmacy is a pharmacy whatever period the vendor tagged (contact-taxonomy.ts, isPharmacySpeciality).
    case
      when lower(regexp_replace(btrim(coalesce(nullif(btrim(cc.speciality), ''), a.latest_speciality, '')), '\s+', ' ', 'g')) = 'pharmacy' then 'Pharmacy'
      else coalesce(own_list.list_type, any_list.list_type, a.majority_list)
    end as list_type
  from (
    select
      s.seat_id,
      s.contact_crm_id,
      min(s.line_code) as line_code,
      min(s.rep_hr_id) as rep_hr_id,
      (array_agg(s.contact_name order by s.visit_date desc, s.crm_visit_id desc)
        filter (where s.contact_name is not null))[1] as latest_name,
      (array_agg(s.speciality order by s.visit_date desc, s.crm_visit_id desc)
        filter (where s.speciality is not null))[1] as latest_speciality,
      case
        when count(*) filter (where s.ampm_list = 'AM') > count(*) filter (where s.ampm_list = 'PM') then 'AM'
        else 'PM'
      end as majority_list
    from phx_import_src s
    where not s.already_imported and s.contact_crm_id is not null and s.customer_id is null
    group by s.seat_id, s.contact_crm_id
  ) a
  left join public.crm_contacts cc on cc.contact_crm_id = a.contact_crm_id
  left join lateral (
    select ca.list_type
    from public.crm_contact_assignments ca
    where ca.contact_crm_id = a.contact_crm_id
      and lower(ca.agent_hr_id) = lower(a.rep_hr_id)
      and ca.list_type in ('AM', 'PM', 'Pharmacy')
    order by ca.last_seen_on desc, ca.effective_from desc, ca.id desc
    limit 1
  ) own_list on true
  left join lateral (
    select ca.list_type
    from public.crm_contact_assignments ca
    where ca.contact_crm_id = a.contact_crm_id
      and ca.list_type in ('AM', 'PM', 'Pharmacy')
    order by ca.last_seen_on desc, ca.effective_from desc, ca.id desc
    limit 1
  ) any_list on true;

  -- Campaign visits name nobody: the Nth of a day and list goes on holder N, after any slot an earlier run
  -- already filled that day.
  create temp table phx_import_slots on commit drop as
  with used as (
    select v.seat_id, h.list_type, v.visit_date, count(*)::integer as n
    from public.phoenix_crm_visits v
    join public.phoenix_crm_customers h on h.id = v.customer_id and h.campaign_visit_holder
    where not v.is_test
      and (v_seat is null or v.seat_id = v_seat)
    group by v.seat_id, h.list_type, v.visit_date
  )
  select
    s.crm_visit_id,
    s.seat_id,
    s.line_code,
    s.rep_hr_id,
    s.ampm_list as list_type,
    (row_number() over (
      partition by s.seat_id, s.ampm_list, s.visit_date order by s.captured_at, s.crm_visit_id
    ))::integer + coalesce(u.n, 0) as slot
  from phx_import_src s
  left join used u on u.seat_id = s.seat_id and u.list_type = s.ampm_list and u.visit_date = s.visit_date
  where not s.already_imported and s.contact_crm_id is null;

  create temp table phx_import_holders on commit drop as
  select
    need.seat_id,
    need.list_type,
    n.slot,
    'Campaign visit ' || n.slot as name,
    need.line_code,
    need.rep_hr_id,
    h.id as customer_id,
    h.id is null as is_new
  from (
    select seat_id, list_type, max(slot) as top, min(line_code) as line_code, min(rep_hr_id) as rep_hr_id
    from phx_import_slots
    group by seat_id, list_type
  ) need
  cross join lateral generate_series(1, need.top) as n(slot)
  left join lateral (
    select c.id
    from public.phoenix_crm_customers c
    where c.seat_id = need.seat_id
      and c.list_type = need.list_type
      and c.campaign_visit_holder
      and not c.is_test
      and c.name = 'Campaign visit ' || n.slot
    order by c.created_at, c.id
    limit 1
  ) h on true;

  if p_apply then
    insert into public.phoenix_crm_customers (
      seat_id, line_code, list_type, name, speciality, origin, reference_contact_crm_id,
      status, dropped_reason, dropped_note, created_by_hr_id, imported_from_ireports360_at
    )
    select
      a.seat_id, a.line_code, a.list_type, a.name, a.speciality, 'reference', a.contact_crm_id,
      'dropped', 'imported_history',
      case when p_leavers
        then 'Visited in the old system by a rep who no longer holds this territory; added to the Archive with that history.'
        when p_after_start
        then 'Visited in the old system after this team started on Phoenix, on a day with no Phoenix entry; added to the Archive with that history.'
        else 'Visited in the old system before this team started on Phoenix; added to the Archive with that history.'
      end,
      a.rep_hr_id, v_now
    from phx_import_archive a
    order by a.seat_id, a.contact_crm_id
    on conflict (seat_id, reference_contact_crm_id, is_test) where reference_contact_crm_id is not null do nothing;
    get diagnostics v_archive_written = row_count;

    insert into public.phoenix_crm_customers (
      seat_id, line_code, list_type, name, origin, status, dropped_reason, dropped_note,
      created_by_hr_id, imported_from_ireports360_at, campaign_visit_holder
    )
    select
      h.seat_id, h.line_code, h.list_type, h.name, 'new', 'dropped', 'imported_history',
      'Holds the old system''s campaign visits, which name no doctor.',
      h.rep_hr_id, v_now, true
    from phx_import_holders h
    where h.is_new
    order by h.seat_id, h.list_type, h.slot;
    get diagnostics v_holders_written = row_count;

    update phx_import_holders h
       set customer_id = c.id
      from public.phoenix_crm_customers c
     where h.customer_id is null
       and c.seat_id = h.seat_id
       and c.list_type = h.list_type
       and c.campaign_visit_holder
       and not c.is_test
       and c.name = h.name;
  end if;

  -- One key per future row: the seat's customer, the Archive doctor still to be made, or holder N.
  create temp table phx_import_keyed on commit drop as
  select
    s.*,
    case
      when s.customer_id is not null then 'c:' || s.customer_id::text
      when s.contact_crm_id is not null then 'a:' || s.contact_crm_id::text
      else 'h:' || sl.list_type || ':' || sl.slot::text
    end as grp,
    case
      when s.customer_id is not null then s.customer_list_type
      when s.contact_crm_id is not null then a.list_type
      else sl.list_type
    end as list_type,
    coalesce(s.customer_id, ac.id, h.customer_id) as target_customer_id
  from phx_import_src s
  left join phx_import_archive a
    on s.customer_id is null and a.seat_id = s.seat_id and a.contact_crm_id = s.contact_crm_id
  left join public.phoenix_crm_customers ac
    on s.customer_id is null and s.contact_crm_id is not null
   and ac.seat_id = s.seat_id and ac.reference_contact_crm_id = s.contact_crm_id and not ac.is_test
  left join phx_import_slots sl on sl.crm_visit_id = s.crm_visit_id
  left join phx_import_holders h on h.seat_id = sl.seat_id and h.list_type = sl.list_type and h.slot = sl.slot
  where not s.already_imported;

  -- Two old visits by one rep to one customer on one day are one Phoenix row: the earlier time, planned if
  -- either was, the first partner, both notes.
  create temp table phx_import_rows on commit drop as
  select
    gen_random_uuid() as id,
    k.seat_id,
    min(k.line_code) as line_code,
    k.grp,
    k.visit_date,
    (array_agg(k.target_customer_id) filter (where k.target_customer_id is not null))[1] as customer_id,
    min(k.list_type) as list_type,
    min(k.captured_at) as captured_at,
    not bool_or(k.visit_type = 0) as is_unplanned,
    k.rep_hr_id,
    (array_agg(k.partner_hr_id order by k.captured_at, k.crm_visit_id)
      filter (where k.partner_hr_id is not null))[1] as partner_hr_id,
    (array_agg(k.kind order by k.captured_at, k.crm_visit_id)
      filter (where k.partner_hr_id is not null))[1] as partner_kind,
    left(string_agg(k.comment, ' · ' order by k.captured_at, k.crm_visit_id), 1000) as comment,
    array_agg(k.crm_visit_id order by k.crm_visit_id) as crm_visit_ids,
    count(*)::integer as sources,
    false as conflict
  from phx_import_keyed k
  group by k.seat_id, k.grp, k.visit_date, k.rep_hr_id;

  -- Two reps on one seat who saw one customer on one day: Phoenix holds one visit a day for a seat and
  -- customer, so the earlier is written. The later one maps to nothing, so it stays on the List's
  -- old-system line instead of vanishing under the other rep's name. That line is read by the customer's
  -- reference id, so a doctor found only through a link has none: conflicts_without_a_line counts those.
  update phx_import_rows r
     set conflict = true
   where exists (
     select 1 from phx_import_rows e
     where e.seat_id = r.seat_id and e.grp = r.grp and e.visit_date = r.visit_date
       and (e.captured_at, e.rep_hr_id) < (r.captured_at, r.rep_hr_id)
   );

  -- A Phoenix visit already on that customer and day stays; the old one is counted and left out.
  update phx_import_rows r
     set conflict = true
   where r.customer_id is not null
     and exists (
       select 1 from public.phoenix_crm_visits v
       where v.seat_id = r.seat_id and v.customer_id = r.customer_id and v.visit_date = r.visit_date
         and not v.is_test
     );

  create temp table phx_import_written (id uuid primary key) on commit drop;

  if p_apply then
    select count(*)::integer into v_unresolved from phx_import_rows r where r.customer_id is null;
    if v_unresolved > 0 then
      raise exception 'phoenix_crm:import_unresolved_customer'
        using hint = v_unresolved || ' rows on ' || v_seat || ' found no customer; nothing was written.';
    end if;

    with ins as (
      insert into public.phoenix_crm_visits (
        id, seat_id, line_code, customer_id, list_type, visit_date, captured_at, kind,
        rep_hr_id, manager_hr_id, product_manager_hr_id, entered_by_hr_id, products, comment,
        location_flag, is_unplanned, unplanned_kind, capture_source, imported_from_ireports360_at
      )
      select
        r.id, r.seat_id, r.line_code, r.customer_id, r.list_type, r.visit_date, r.captured_at,
        coalesce(r.partner_kind, 'single'),
        r.rep_hr_id,
        case when r.partner_kind = 'double' then r.partner_hr_id end,
        case when r.partner_kind = 'product_manager' then r.partner_hr_id end,
        r.rep_hr_id, '{}', r.comment,
        'no_place', r.is_unplanned,
        case when r.is_unplanned then 'out_of_list' end,
        'admin', v_now
      from phx_import_rows r
      where not r.conflict
      order by r.visit_date, r.captured_at, r.id
      on conflict (seat_id, customer_id, visit_date, is_test) do nothing
      returning id
    )
    insert into phx_import_written (id) select ins.id from ins;
    get diagnostics v_written = row_count;

    insert into public.phoenix_crm_imported_visit_sources (crm_visit_id, visit_id, imported_at)
    select src.crm_visit_id, r.id, v_now
    from phx_import_rows r
    join phx_import_written w on w.id = r.id
    cross join lateral unnest(r.crm_visit_ids) as src(crm_visit_id)
    on conflict (crm_visit_id) do nothing;
    get diagnostics v_mapped = row_count;
  end if;

  select coalesce(jsonb_agg(t.x order by t.seat_id), '[]'::jsonb)
    into v_seats
  from (
    select
      s.seat_id,
      jsonb_build_object(
        'seat_id', s.seat_id,
        'in_scope', s.in_scope,
        'already_imported', s.already_imported,
        'rows_to_write', coalesce(r.rows_to_write, 0),
        'merged_same_day', s.in_scope - s.already_imported - coalesce(r.rows_to_write, 0),
        'archive_doctors', coalesce(a.n, 0),
        'holders', coalesce(h.n, 0),
        'conflicts_skipped', coalesce(r.conflicts, 0),
        'written', coalesce(w.n, 0),
        'mapped', coalesce(w.mapped, 0)
      ) as x
    from (
      select seat_id, count(*)::integer as in_scope, (count(*) filter (where already_imported))::integer as already_imported
      from phx_import_src
      group by seat_id
    ) s
    left join (
      select seat_id, count(*)::integer as rows_to_write, (count(*) filter (where conflict))::integer as conflicts
      from phx_import_rows
      group by seat_id
    ) r on r.seat_id = s.seat_id
    left join (select seat_id, count(*)::integer as n from phx_import_archive group by seat_id) a on a.seat_id = s.seat_id
    left join (select seat_id, count(*)::integer as n from phx_import_holders where is_new group by seat_id) h
      on h.seat_id = s.seat_id
    left join (
      select r2.seat_id, count(*)::integer as n, sum(r2.sources)::integer as mapped
      from phx_import_written w2
      join phx_import_rows r2 on r2.id = w2.id
      group by r2.seat_id
    ) w on w.seat_id = s.seat_id
  ) t;

  return jsonb_build_object(
    'applied', p_apply,
    'seat', v_seat,
    'seats', v_seats,
    'totals', jsonb_build_object(
      'seats', jsonb_array_length(v_seats),
      'in_scope', (select count(*) from phx_import_src),
      'already_imported', (select count(*) from phx_import_src where already_imported),
      'rows_to_write', (select count(*) from phx_import_rows),
      'merged_same_day', (select count(*) from phx_import_keyed) - (select count(*) from phx_import_rows),
      'archive_doctors', case when p_apply then v_archive_written else (select count(*) from phx_import_archive) end,
      'holders', case when p_apply then v_holders_written else (select count(*) from phx_import_holders where is_new) end,
      'conflicts_skipped', (select count(*) from phx_import_rows where conflict)
        + case when p_apply then (select count(*) from phx_import_rows where not conflict) - v_written else 0 end,
      'written', v_written,
      'mapped', v_mapped,
      'partners_dropped', (select count(*) from phx_import_keyed where partner_dropped),
      'conflicts_without_a_line', (
        select count(*)
        from phx_import_rows r
        join public.phoenix_crm_customers cu on cu.id = r.customer_id
        where r.conflict and cu.reference_contact_crm_id is null and not cu.campaign_visit_holder
      )
    )
  );
end;
$_$;

ALTER FUNCTION public.phoenix_crm_import_ireports360_history(p_seat text, p_apply boolean, p_after_start boolean, p_leavers boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_insert_place(uuid, text, text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_insert_place(p_customer_id uuid, p_seat_id text, p_actor_hr_id text, p_is_test boolean, p_place jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_captured_at timestamptz;
  v_place_id uuid;
  v_source text := coalesce(p_place ->> 'point_source', 'pin');
  v_shared uuid := nullif(p_place ->> 'shared_place_id', '')::uuid;
  v_photo text := nullif(trim(coalesce(p_place ->> 'photo_path', '')), '');
  v_venue public.phoenix_crm_shared_places%rowtype;
  v_session text := nullif(trim(coalesce(p_place ->> 'session', '')), '');
begin
  if jsonb_typeof(p_place) is distinct from 'object'
    or jsonb_typeof(p_place -> 'timings') is distinct from 'array'
    or v_photo is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- A caller that names no source sent one reading, the pin, in lat/lon — exactly as before today.
  -- 'shared_place' joins the three: the point was copied from a venue this place must name.
  if v_source not in ('photo', 'pin', 'shared_place') then
    v_source := 'pin';
  end if;
  if v_source = 'shared_place' and v_shared is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  -- A seating is AM or PM (owner, 2026-10-10); a clinic of his own carries none and is read from the
  -- customer's list. A caller that names none (a build from before this) is seated in the customer's
  -- own list, which is what its visits counted in until now, so deploy and apply never have to be
  -- simultaneous.
  if v_shared is not null and v_session is null then
    select c.list_type into v_session from public.phoenix_crm_customers c where c.id = p_customer_id and c.list_type in ('AM', 'PM');
  end if;
  if v_shared is not null and (v_session is null or v_session not in ('AM', 'PM')) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_shared is null then
    v_session := null;
  end if;

  if v_shared is null then
    v_captured_at := public.phoenix_crm_take_photo(v_photo, p_actor_hr_id, p_seat_id, 'place', p_is_test);
  else
    -- 🔴 THE TIMETABLE IS THE BUILDING'S, PHOTOGRAPHED ONCE (owner, 2026-10-10). The venue's row is
    -- locked for the rest of this transaction, which is what makes the two checks below race-proof:
    -- two reps seating two doctors in the same building at the same second queue here.
    select s.* into v_venue from public.phoenix_crm_shared_places s where s.id = v_shared for update;
    if not found then
      raise exception 'phoenix_crm:shared_place_not_found';
    end if;
    if v_venue.status = 'retired' then
      raise exception 'phoenix_crm:shared_place_retired';
    end if;
    -- A HELD venue is seatable (owner, 2026-10-14: "make him able to choose him even if the system is
    -- still checking"). It used to raise shared_place_held here, and nothing released a held venue by
    -- itself, so a rep who captured a building could never add a customer to it. A REJECTION still
    -- retires every place seated in it (phoenix_crm_decide_shared_place), so nothing is stranded.
    -- 🔴 ONE CUSTOMER SITS IN ONE BUILDING ONCE, and this refusal is what replaces the idempotence the
    -- photo slot used to give a seating: a reused timetable consumes no slot, so a second Save would
    -- otherwise write a second identical row instead of answering photo_used. His hours are windows in
    -- the ONE row (`timings`), so a second row was never how a doctor receives twice in a building.
    if exists (
      select 1
      from public.phoenix_crm_places pl
      where pl.customer_id = p_customer_id
        and pl.shared_place_id = v_shared
        and pl.status = 'active'
    ) then
      raise exception 'phoenix_crm:already_seated';
    end if;

    if v_venue.schedule_photo_path is not null and v_photo = v_venue.schedule_photo_path then
      -- The board is already on file: no camera was opened, so there is no slot to consume and no
      -- phone clock to compare. The seating is dated NOW — when this customer was seated — and never
      -- the day the board was photographed.
      v_captured_at := now();
    else
      v_captured_at := public.phoenix_crm_take_photo(v_photo, p_actor_hr_id, p_seat_id, 'place', p_is_test);
      -- A fresh photograph of the board becomes the venue's timetable, whether it is the first one or
      -- a replacement for a board that changed. The earlier seatings keep the photo they were saved
      -- against, which is the evidence that was true of them.
      update public.phoenix_crm_shared_places
      set schedule_photo_path = v_photo,
          schedule_photo_captured_at = v_captured_at,
          schedule_photo_by_hr_id = upper(trim(p_actor_hr_id)),
          updated_at = now()
      where id = v_shared;
    end if;
  end if;

  -- Every location column here is the SERVER's own resolution of the fixed point (server/list.ts
  -- placePayload), not anything the phone typed. The two raw readings are kept beside it as evidence.
  insert into public.phoenix_crm_places (
    customer_id, seat_id, label, address, brick_id, brick_name, brick_distance_km, brick_lookup,
    area_code, area_name, region_code, region_name, zone, lat, lon, accuracy_meters,
    timings, photo_path, captured_at, device_skew_minutes, created_by_hr_id, is_test,
    pin_lat, pin_lon, pin_accuracy_meters, photo_lat, photo_lon, photo_accuracy_meters, photo_captured_at, point_source,
    shared_place_id, schedule_check, session
  )
  values (
    p_customer_id,
    p_seat_id,
    nullif(trim(coalesce(p_place ->> 'label', '')), ''),
    nullif(trim(coalesce(p_place ->> 'address', '')), ''),
    nullif(trim(coalesce(p_place ->> 'brick_id', '')), ''),
    nullif(trim(coalesce(p_place ->> 'brick_name', '')), ''),
    (p_place ->> 'brick_distance_km')::numeric,
    -- 2026-10-08. 🔴 The fallback is the UNKNOWN value, never 'matched': a caller that sends no key —
    -- an older build, a replayed body — must land on "nobody looked", which is both true of it and the
    -- safe direction. The column's CHECK rejects anything that is not one of the three.
    coalesce(nullif(trim(coalesce(p_place ->> 'brick_lookup', '')), ''), 'could_not_look'),
    nullif(trim(coalesce(p_place ->> 'area_code', '')), ''),
    nullif(trim(coalesce(p_place ->> 'area_name', '')), ''),
    nullif(trim(coalesce(p_place ->> 'region_code', '')), ''),
    nullif(trim(coalesce(p_place ->> 'region_name', '')), ''),
    nullif(trim(coalesce(p_place ->> 'zone', '')), ''),
    (p_place ->> 'lat')::double precision,
    (p_place ->> 'lon')::double precision,
    (p_place ->> 'accuracy_meters')::numeric,
    p_place -> 'timings',
    v_photo,
    v_captured_at,
    (p_place ->> 'device_skew_minutes')::integer,
    upper(trim(p_actor_hr_id)),
    p_is_test,
    coalesce((p_place ->> 'pin_lat')::double precision, (p_place ->> 'lat')::double precision),
    coalesce((p_place ->> 'pin_lon')::double precision, (p_place ->> 'lon')::double precision),
    coalesce((p_place ->> 'pin_accuracy_meters')::numeric, (p_place ->> 'accuracy_meters')::numeric),
    (p_place ->> 'photo_lat')::double precision,
    (p_place ->> 'photo_lon')::double precision,
    (p_place ->> 'photo_accuracy_meters')::numeric,
    nullif(p_place ->> 'photo_captured_at', '')::timestamptz,
    v_source,
    v_shared,
    case when jsonb_typeof(p_place -> 'schedule_check') = 'object' then p_place -> 'schedule_check' end,
    v_session
  )
  returning id into v_place_id;

  return jsonb_build_object('place_id', v_place_id, 'captured_at', v_captured_at);
end;
$$;

ALTER FUNCTION public.phoenix_crm_insert_place(p_customer_id uuid, p_seat_id text, p_actor_hr_id text, p_is_test boolean, p_place jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_ireports360_conversion_page(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_ireports360_conversion_page(p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with page as (
    select v.id, v.customer_id, v.lat, v.lon, v.place_id, v.distance_meters, v.location_flag,
           v.ireports360_checkin_id, v.ireports360_kpi_counted
    from public.phoenix_crm_visits v
    where v.imported_from_ireports360_at is not null
      and v.archived_at is null
      and not v.is_test
      and (p_after is null or v.id > p_after)
    order by v.id
    limit least(greatest(coalesce(p_limit, 500), 1), 2000)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'visit_id', p.id,
    'customer_id', p.customer_id,
    'lat', p.lat,
    'lon', p.lon,
    'place_id', p.place_id,
    'distance_meters', p.distance_meters,
    'location_flag', p.location_flag,
    'checkin_id', p.ireports360_checkin_id,
    'kpi_counted', p.ireports360_kpi_counted,
    'match', (
      select jsonb_build_object('checkin_id', m.crm_checkin_id, 'lat', m.lat, 'lon', m.lon)
      from public.phoenix_crm_imported_visit_sources s
      join public.ireports360_visits iv on iv.crm_visit_id = s.crm_visit_id and iv.visit_type = 0
      join public.phoenix_crm_ireports360_checkin_matches m on m.crm_visit_id = s.crm_visit_id
      where s.visit_id = p.id
      order by s.crm_visit_id
      limit 1
    ),
    'places', coalesce((
      select jsonb_agg(jsonb_build_object('id', pl.id, 'lat', pl.lat, 'lon', pl.lon) order by pl.id)
      from public.phoenix_crm_places pl
      where pl.customer_id = p.customer_id and pl.status = 'active' and not pl.is_test
    ), '[]'::jsonb)
  ) order by p.id), '[]'::jsonb)
  from page p
$$;

ALTER FUNCTION public.phoenix_crm_ireports360_conversion_page(p_after uuid, p_limit integer) OWNER TO postgres;

--
-- Name: phoenix_crm_list_only_reps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_list_only_reps() RETURNS TABLE(seat_id text, hr_id text, hr_key text, agent_crm_id bigint, counted_from date, counted_until date)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 30
    SET search_path TO 'public'
    AS $_$
  with lists as (
    select c.seat_id,
           min((c.created_at at time zone 'Africa/Cairo')::date) as list_built_on
      from public.phoenix_crm_customers c
     where not c.is_test
       and c.status in ('active', 'pending', 'dropped')
     group by c.seat_id
  )
  select o.seat_id,
         btrim(o.occupant_hr_id),
         lower(btrim(o.occupant_hr_id)),
         null::bigint,
         greatest(o.effective_from, l.list_built_on),
         o.effective_to
    from au.occupancy_history o
    join lists l on l.seat_id = o.seat_id
    join public.employees e on upper(btrim(e.hr_id)) = upper(btrim(o.occupant_hr_id))
   where nullif(btrim(o.occupant_hr_id), '') is not null
     -- No iReports360 account at all. A numeric `crm_id` or a `crm_username` is how every vendor
     -- pass finds a rep, so a rep carrying either is the vendor's and waits for his team's start.
     and (e.crm_id is null or e.crm_id !~ '^[0-9]+$')
     and nullif(btrim(e.crm_username), '') is null
     -- Belt beside the braces: a rep holding an open vendor row has a list already, whatever his
     -- identity columns say, and taking it to Phoenix without a team start is the one thing the
     -- team-start rule exists to prevent.
     and not exists (
       select 1
         from public.crm_contact_assignments a
        where a.effective_to is null
          and a.source = 'ireports360'
          and lower(btrim(a.agent_hr_id)) = lower(btrim(o.occupant_hr_id))
     )
     -- A started rep is already in the other half of the door, with his TEAM's start date. Returning
     -- him here too would offer the fifth pass a second, earlier window and backdate his periods to
     -- the day his list was built — CN-0009's list predates her team's start by five days.
     and not exists (
       select 1
         from public.phoenix_crm_started_team_reps() s
        where s.hr_key = lower(btrim(o.occupant_hr_id))
     )
     and (o.effective_to is null or o.effective_to > greatest(o.effective_from, l.list_built_on))
$_$;

ALTER FUNCTION public.phoenix_crm_list_only_reps() OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_list_only_reps(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_list_only_reps() IS 'Reps whose doctor list is Phoenix''s without a team start: a Phoenix CRM list, no iReports360 account, no open vendor row, team not started. Owner''s ruling 2026-10-15.';

--
-- Name: phoenix_crm_list_requests_with_rep_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_list_requests_with_rep_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.stage = 'rep' and new.status = 'approved' then
    raise exception 'phoenix_crm:request_with_rep';
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.phoenix_crm_list_requests_with_rep_guard() OWNER TO postgres;

--
-- Name: phoenix_crm_load_list_customers(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_load_list_customers(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_source text := nullif(trim(coalesce(p ->> 'source', '')), '');
  v_row jsonb;
  v_name text;
  v_list_type text;
  v_grade text;
  v_potential text;
  v_timings jsonb;
  v_customer public.phoenix_crm_customers%rowtype;
  v_loaded jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_hours_set jsonb := '[]'::jsonb;
  v_hours_skipped jsonb := '[]'::jsonb;
  v_target uuid;
  v_load_id uuid := gen_random_uuid();
begin
  if v_seat is null or v_line is null or v_actor is null or jsonb_typeof(p -> 'customers') is distinct from 'array' then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- A sheet holds a territory's list, not a book. The caller caps it too; this is the floor under that.
  if jsonb_array_length(p -> 'customers') > 1000 then
    raise exception 'phoenix_crm:too_many_rows';
  end if;
  if jsonb_typeof(p -> 'hours') = 'array' and jsonb_array_length(p -> 'hours') > 1000 then
    raise exception 'phoenix_crm:too_many_rows';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  for v_row in select value from jsonb_array_elements(p -> 'customers')
  loop
    v_name := nullif(regexp_replace(trim(coalesce(v_row ->> 'name', '')), '\s+', ' ', 'g'), '');
    v_list_type := coalesce(v_row ->> 'list_type', '');

    -- The caller has judged every one of these already (list-template-rules.ts). Checked again here
    -- because this function is the authority, and a refusal that reaches the sheet's own row number is
    -- more use to the SFE than one that aborts the whole load.
    if v_name is null or v_list_type not in ('AM', 'PM', 'Pharmacy') then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
        'row', v_row -> 'row', 'name', v_row -> 'name', 'reason', 'bad_input'));
      continue;
    end if;

    -- 🔴 GRADE AND POTENTIAL ARE OPTIONAL (owner, 2026-10-03). No row is refused over either one. The
    -- stored value is sanitised, not trusted: a pharmacy carries neither, and a doctor keeps his grade
    -- only when it is a real A/B/C and his potential only when it is a real AA..BC. Anything else —
    -- empty, unrecognised, or typed on a pharmacy — is written NULL. So a junk grade still cannot land;
    -- it is simply dropped instead of blocking the whole row.
    v_grade := case
      when v_list_type <> 'Pharmacy' and coalesce(v_row ->> 'grade', '') in ('A', 'B', 'C')
        then v_row ->> 'grade'
      else null
    end;
    v_potential := case
      when v_list_type <> 'Pharmacy' and coalesce(v_row ->> 'potential_grade', '') in ('AA', 'AB', 'AC', 'BA', 'BB', 'BC')
        then v_row ->> 'potential_grade'
      else null
    end;

    -- 🔴 THE DAYS AND HOURS ARE OPTIONAL IN EXACTLY THE SAME WAY (owner, 2026-10-05). The cell is free
    -- text a rep wrote; `list-sheet-hours.ts` reads it and hands over only what the module's own
    -- `parseTimings` accepted, so anything unreadable arrives as null and the row still loads. The shape
    -- is checked again here rather than trusted — this function is the authority — and the column's own
    -- CHECK is the floor under that.
    v_timings := case
      when jsonb_typeof(v_row -> 'timings') = 'array'
        and jsonb_array_length(v_row -> 'timings') between 1 and 60
        then v_row -> 'timings'
      else null
    end;

    -- The same guard a hand-typed customer meets, row by row rather than all or nothing: the SFE gets
    -- the ones that landed and a line naming each one that was already there.
    if exists (
      select 1
      from public.phoenix_crm_customers c
      where c.seat_id = v_seat
        and c.is_test = v_is_test
        and c.status in ('active', 'pending', 'outside')
        and c.list_type = v_list_type
        and public.phoenix_crm_fold_name(c.name) = public.phoenix_crm_fold_name(v_name)
    ) then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
        'row', v_row -> 'row', 'name', v_row -> 'name', 'reason', 'already_on_the_list'));
      continue;
    end if;

    insert into public.phoenix_crm_customers (
      seat_id, line_code, list_type, name, speciality, grade, potential_grade, origin, status,
      validated_at, validated_by_hr_id, created_by_hr_id, is_test, phone, intake_where, intake_note,
      intake_timings
    )
    values (
      v_seat, v_line, v_list_type, left(v_name, 200),
      left(nullif(trim(coalesce(v_row ->> 'speciality', '')), ''), 120),
      v_grade, v_potential, 'new', 'pending',
      -- NOT validated: he waits under To validate for the rep to validate him at the door.
      null, null, v_actor, v_is_test,
      nullif(regexp_replace(coalesce(v_row ->> 'phone', ''), '\s+', '', 'g'), ''),
      left(nullif(trim(coalesce(v_row ->> 'intake_where', '')), ''), 200),
      left(nullif(trim(coalesce(v_row ->> 'intake_note', '')), ''), 300),
      v_timings
    )
    returning * into v_customer;

    insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
    values (
      v_seat, v_customer.id, 'customer_loaded', v_actor,
      jsonb_build_object(
        'load_id', v_load_id,
        'source', coalesce(v_source, 'sheet'),
        'list_type', v_list_type,
        'grade', v_grade,
        'potential_grade', v_potential,
        'hours_from_sheet', v_timings is not null,
        'sheet_row', v_row -> 'row'
      ),
      v_is_test
    );

    v_loaded := v_loaded || jsonb_build_array(jsonb_build_object('customer_id', v_customer.id, 'name', v_customer.name, 'row', v_row -> 'row'));
  end loop;

  -- ── Hours for a customer who is already on the list ───────────────────────────────────────────────
  --
  -- 🔴 THIS PASS WRITES ONE COLUMN AND NOTHING ELSE. It inserts no customer, so the same-name guard
  -- above keeps its whole job; it never touches status, grade, potential, name, list or phone. It is the
  -- only way hours can reach the customers minted from iReports360, who are the overwhelming majority of
  -- everyone waiting to be validated.
  if jsonb_typeof(p -> 'hours') = 'array' then
    for v_row in select value from jsonb_array_elements(p -> 'hours')
    loop
      v_name := nullif(regexp_replace(trim(coalesce(v_row ->> 'name', '')), '\s+', ' ', 'g'), '');
      v_list_type := coalesce(v_row ->> 'list_type', '');
      v_timings := case
        when jsonb_typeof(v_row -> 'timings') = 'array'
          and jsonb_array_length(v_row -> 'timings') between 1 and 60
          then v_row -> 'timings'
        else null
      end;

      if v_name is null or v_list_type not in ('AM', 'PM', 'Pharmacy') or v_timings is null then
        v_hours_skipped := v_hours_skipped || jsonb_build_array(jsonb_build_object(
          'row', v_row -> 'row', 'name', v_row -> 'name', 'reason', 'bad_input'));
        continue;
      end if;

      -- 🔴 PENDING AND PLACELESS, which is the window in which the draft has been read by nobody. Once
      -- the rep has validated him the hours are HIS, on his place, and a re-upload must not reach back
      -- and disagree with what he confirmed at the door.
      select c.id into v_target
      from public.phoenix_crm_customers c
      where c.seat_id = v_seat
        and c.is_test = v_is_test
        and c.status = 'pending'
        and c.list_type = v_list_type
        and public.phoenix_crm_fold_name(c.name) = public.phoenix_crm_fold_name(v_name)
        and not exists (select 1 from public.phoenix_crm_places pl where pl.customer_id = c.id)
      order by c.created_at
      limit 1;

      if v_target is null then
        v_hours_skipped := v_hours_skipped || jsonb_build_array(jsonb_build_object(
          'row', v_row -> 'row', 'name', v_row -> 'name', 'reason', 'not_waiting_to_be_validated'));
        continue;
      end if;

      update public.phoenix_crm_customers
      set intake_timings = v_timings, updated_at = now()
      where id = v_target;

      insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
      values (
        v_seat, v_target, 'customer_hours_loaded', v_actor,
        jsonb_build_object(
          'load_id', v_load_id,
          'source', coalesce(v_source, 'sheet'),
          'list_type', v_list_type,
          'windows', jsonb_array_length(v_timings),
          'sheet_row', v_row -> 'row'
        ),
        v_is_test
      );

      v_hours_set := v_hours_set || jsonb_build_array(jsonb_build_object('customer_id', v_target, 'name', v_name, 'row', v_row -> 'row'));
    end loop;
  end if;

  -- One event for the load itself, so the act is readable without reading 300 rows.
  insert into public.phoenix_crm_list_events (seat_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, 'list_loaded', v_actor,
    jsonb_build_object(
      'load_id', v_load_id,
      'source', coalesce(v_source, 'sheet'),
      'loaded', jsonb_array_length(v_loaded),
      'skipped', jsonb_array_length(v_skipped),
      'hours_set', jsonb_array_length(v_hours_set),
      'hours_skipped', jsonb_array_length(v_hours_skipped)
    ),
    v_is_test
  );

  return jsonb_build_object(
    'load_id', v_load_id,
    'seat_id', v_seat,
    'loaded', v_loaded,
    'skipped', v_skipped,
    'hours_set', v_hours_set,
    'hours_skipped', v_hours_skipped
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_load_list_customers(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_manager_plan_transition(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_manager_plan_transition(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan_id uuid := nullif(p ->> 'plan_id', '')::uuid;
  v_action text := coalesce(p ->> 'action', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_stage text := nullif(trim(coalesce(p ->> 'stage', '')), '');
  v_first text := upper(nullif(trim(coalesce(p ->> 'first_approver_hr_id', '')), ''));
  v_second text := upper(nullif(trim(coalesce(p ->> 'second_approver_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_day date := nullif(p ->> 'day', '')::date;
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_hr_ack constant text := 'SYSTEM-AUTO-HR-ACK';
  v_manager text;
  v_week date;
  v_plan public.phoenix_crm_manager_plans%rowtype;
  v_from text;
  v_event text;
  v_details jsonb := '{}'::jsonb;
begin
  if v_plan_id is null or v_actor is null or v_action not in ('submit', 'approve', 'return') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_day is not null and v_action <> 'return' then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_action = 'submit' and (v_role is null or v_role not in ('manager', 'administrator')) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_action <> 'submit' and (v_stage is null or v_stage not in ('first', 'second')
     or v_role is null or v_role not in ('first', 'second', 'administrator')) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- An approver decides only his own stage; the Administrator may decide either.
  if v_action <> 'submit' and v_role <> 'administrator' and v_role <> v_stage then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select pl.manager_hr_id, pl.week_start into v_manager, v_week
  from public.phoenix_crm_manager_plans pl where pl.id = v_plan_id;
  if not found then
    raise exception 'phoenix_crm:manager_plan_not_found';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('phoenix_crm:manager_plan:' || v_manager || ':' || v_week::text || ':' || v_is_test::text)
  );

  select pl.* into v_plan from public.phoenix_crm_manager_plans pl where pl.id = v_plan_id for update;
  if v_plan.is_test <> v_is_test then
    raise exception 'phoenix_crm:manager_plan_not_found';
  end if;
  if v_expected is distinct from v_plan.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  v_from := v_plan.status;
  if v_action <> 'approve' and v_plan.week_start + 5 < v_today then
    raise exception 'phoenix_crm:week_passed';
  end if;

  if v_action = 'submit' then
    if v_from not in ('draft', 'returned') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    if not exists (select 1 from public.phoenix_crm_manager_plan_slots s where s.plan_id = v_plan.id) then
      raise exception 'phoenix_crm:empty_plan';
    end if;
    -- Office is never a district manager's (a post that changed under an open week leaves one behind).
    if v_plan.planner_kind = 'dm' and exists (
      select 1 from public.phoenix_crm_manager_plan_slots s where s.plan_id = v_plan.id and s.activity_type = 'office'
    ) then
      raise exception 'phoenix_crm:manager_plan_bad_kind';
    end if;
    if v_first is null then
      raise exception 'phoenix_crm:manager_plan_no_approver';
    end if;
    if v_first = v_plan.manager_hr_id or v_second = v_plan.manager_hr_id or v_second = v_first then
      raise exception 'phoenix_crm:bad_input';
    end if;
    -- Judged against its own deadline, 23:55 Cairo on its due date, from the server's clock, and
    -- accepted whenever it arrives. A week sent again after his approver reopened it keeps the verdict
    -- its first send earned: the change was agreed above him and must not read as lateness.
    update public.phoenix_crm_manager_plans pl
    set status = 'submitted',
        submitted_at = now(),
        submitted_by_hr_id = v_actor,
        due_on = public.phoenix_crm_week_due_on(pl.week_start),
        submitted_late = case
          when pl.submitted_late is not null and exists (
            select 1 from public.phoenix_crm_manager_plan_edit_requests r where r.plan_id = pl.id and r.status = 'reopened'
          ) then pl.submitted_late
          else now() > public.phoenix_crm_week_deadline_at(pl.week_start)
        end,
        first_approver_hr_id = v_first,
        second_approver_hr_id = v_second,
        first_decided_at = null,
        first_decided_by_hr_id = null,
        first_decided_role = null,
        first_decision_note = null,
        decided_at = null,
        decided_by_hr_id = null,
        decided_by_role = null,
        decision_note = null,
        returned_day = null,
        returned_stage = null,
        hr_acknowledged_at = null,
        hr_acknowledged_by_hr_id = null,
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    v_event := 'submitted';
    -- WHAT WAS SENT, kept on the send's own event: every half-day with its customers' names as they stood.
    v_details := jsonb_build_object(
      'slots', coalesce((
        select jsonb_agg(
                 jsonb_build_object(
                   'plan_date', s.plan_date, 'half', s.half, 'kind', s.kind,
                   'rep_seat_id', s.rep_seat_id, 'rep_hr_id', s.rep_hr_id,
                   'activity_type', s.activity_type, 'area_code', s.area_code, 'area_name', s.area_name,
                   'scope_dm_seat_id', s.scope_dm_seat_id, 'scope_line_code', s.scope_line_code,
                   'customers', coalesce((
                     select jsonb_agg(jsonb_build_object(
                              'customer_id', pc.customer_id,
                              'manager_customer_id', pc.manager_customer_id,
                              'name', coalesce(c.name, m.name))
                            order by coalesce(c.name, m.name), pc.id)
                     from public.phoenix_crm_manager_plan_customers pc
                     left join public.phoenix_crm_customers c on c.id = pc.customer_id
                     left join public.phoenix_crm_manager_customers m on m.id = pc.manager_customer_id
                     where pc.slot_id = s.id
                   ), '[]'::jsonb))
                 order by s.plan_date, s.half)
        from public.phoenix_crm_manager_plan_slots s
        where s.plan_id = v_plan.id
      ), '[]'::jsonb)
    );

  elsif v_action = 'approve' then
    if v_stage = 'first' then
      if v_from <> 'submitted' then
        raise exception 'phoenix_crm:bad_transition';
      end if;
      update public.phoenix_crm_manager_plans pl
      set status = case when pl.second_approver_hr_id is null then 'approved' else 'first_approved' end,
          first_decided_at = now(),
          first_decided_by_hr_id = v_actor,
          first_decided_role = v_role,
          first_decision_note = v_note,
          decided_at = case when pl.second_approver_hr_id is null then now() end,
          decided_by_hr_id = case when pl.second_approver_hr_id is null then v_actor end,
          decided_by_role = case when pl.second_approver_hr_id is null then v_role end,
          decision_note = case when pl.second_approver_hr_id is null then v_note end,
          version = pl.version + 1,
          updated_at = now()
      where pl.id = v_plan.id
      returning pl.* into v_plan;
    else
      if v_from <> 'first_approved' or v_plan.second_approver_hr_id is null then
        raise exception 'phoenix_crm:bad_transition';
      end if;
      update public.phoenix_crm_manager_plans pl
      set status = 'approved',
          decided_at = now(),
          decided_by_hr_id = v_actor,
          decided_by_role = v_role,
          decision_note = v_note,
          version = pl.version + 1,
          updated_at = now()
      where pl.id = v_plan.id
      returning pl.* into v_plan;
    end if;
    v_event := case when v_plan.status = 'first_approved' then 'first_approved' else 'approved' end;

  else
    -- The first approver returns a week waiting on him (or one he closed alone); the second returns one
    -- waiting on him or one he approved.
    if v_stage = 'first' and not (v_from = 'submitted' or (v_from = 'approved' and v_plan.second_approver_hr_id is null)) then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    if v_stage = 'second' and not (v_from in ('first_approved', 'approved') and v_plan.second_approver_hr_id is not null) then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    if v_note is null then
      raise exception 'phoenix_crm:note_required';
    end if;
    -- ONE DAY: a working day of this week that has not passed — he must still be able to change it.
    if v_day is not null and (v_day < v_plan.week_start or v_day > v_plan.week_start + 5 or v_day < v_today) then
      raise exception 'phoenix_crm:day_not_returnable';
    end if;
    update public.phoenix_crm_manager_plans pl
    set status = 'returned',
        returned_day = v_day,
        returned_stage = v_stage,
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decided_by_role = v_role,
        decision_note = v_note,
        hr_acknowledged_at = null,
        hr_acknowledged_by_hr_id = null,
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    v_event := 'returned';
    v_details := jsonb_build_object('stage', v_stage)
      || case when v_day is not null then jsonb_build_object('returned_day', v_day) else '{}'::jsonb end;
  end if;

  insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
  values (v_plan.id, v_event, v_actor, v_role, v_from, v_plan.status, v_plan.version, v_note, v_details);

  -- 🔴 AN ASK TO EDIT NEVER OUTLIVES THE SENT WEEK IT WAS RAISED ON. A week returned to its manager, or sent
  -- again, is no longer a week an approver can reopen — so any ask still open on it is closed in this same
  -- transaction, exactly as the daily expiry closes one (status 'expired', decided by 'system', one
  -- 'edit_expired' event). Left open, it would sit in the Hub, fail its Reopen with bad_transition, then
  -- come alive when the manager sent the week again and reopen the FRESHLY SENT week with one click (and
  -- refuse his next ask as already open). No notice goes with it: the manager is told the week came back, and
  -- the approver's "ask waiting" notice clears itself once the ask is no longer in his queue.
  if v_action in ('submit', 'return') then
    with closed as (
      update public.phoenix_crm_manager_plan_edit_requests r
      set status = 'expired',
          decided_at = now(),
          decided_by_hr_id = null,
          decided_role = 'system',
          version = r.version + 1,
          updated_at = now()
      where r.plan_id = v_plan.id
        and r.status in ('pending', 'first_approved')
      returning r.id
    )
    insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, details)
    select v_plan.id, 'edit_expired', 'SYSTEM', 'system', v_plan.status, v_plan.status, v_plan.version,
           jsonb_build_object('request_id', c.id, 'reason', case when v_action = 'return' then 'week_returned' else 'week_sent_again' end)
    from closed c;
  end if;

  -- "As today, HR auto acknowledge" (owner, 2026-10-17): the approval that closes a regional, national or
  -- product manager's week is acknowledged by HR at once, signed by the system, exactly as the legacy
  -- weekly plan's. Never on a district manager's week — his ruling for them is no HR step at all.
  if v_action = 'approve' and v_plan.status = 'approved' and v_plan.planner_kind <> 'dm' then
    update public.phoenix_crm_manager_plans pl
    set hr_acknowledged_at = now(),
        hr_acknowledged_by_hr_id = v_hr_ack,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version)
    values (v_plan.id, 'hr_acknowledged', v_hr_ack, 'system', v_plan.status, v_plan.status, v_plan.version);
  end if;

  return jsonb_build_object(
    'plan_id', v_plan.id,
    'manager_hr_id', v_plan.manager_hr_id,
    'manager_seat_id', v_plan.manager_seat_id,
    'planner_kind', v_plan.planner_kind,
    'week_start', v_plan.week_start,
    'status', v_plan.status,
    'from_status', v_from,
    'version', v_plan.version,
    'due_on', v_plan.due_on,
    'submitted_late', v_plan.submitted_late,
    'first_approver_hr_id', v_plan.first_approver_hr_id,
    'second_approver_hr_id', v_plan.second_approver_hr_id,
    'returned_day', v_plan.returned_day,
    'hr_acknowledged', v_plan.hr_acknowledged_at is not null,
    'is_test', v_plan.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_manager_plan_transition(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_merge_duplicate_customer(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_merge_duplicate_customer(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_keeper_id uuid := nullif(p ->> 'keeper_id', '')::uuid;
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_loser_ids uuid[];
  v_keeper public.phoenix_crm_customers%rowtype;
  v_loser public.phoenix_crm_customers%rowtype;
  v_loser_id uuid;
  v_n integer;
  v_places integer := 0;
  v_visits integer := 0;
  v_reviews integer := 0;
  v_plan_items integer := 0;
  v_unplanned integer := 0;
  v_asks integer := 0;
  v_requests integer := 0;
  v_withdrawn integer := 0;
  v_manager_plan integer := 0;
  v_manager_visits integer := 0;
begin
  select coalesce(array_agg(distinct x::uuid), '{}')
  into v_loser_ids
  from jsonb_array_elements_text(coalesce(p -> 'loser_ids', '[]'::jsonb)) as x;

  if v_actor is null or v_keeper_id is null or cardinality(v_loser_ids) = 0 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_keeper_id = any (v_loser_ids) then
    raise exception 'phoenix_crm:keeper_is_loser';
  end if;
  if v_note is null or char_length(v_note) < 10 or char_length(v_note) > 500 then
    raise exception 'phoenix_crm:note_required';
  end if;

  select c.* into v_keeper from public.phoenix_crm_customers c where c.id = v_keeper_id for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_keeper.status = 'dropped' then
    raise exception 'phoenix_crm:customer_dropped';
  end if;

  -- The seat's own lock, the key phoenix_crm_move_customer takes, so a merge and a move on one list
  -- can never interleave.
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_keeper.seat_id));

  foreach v_loser_id in array v_loser_ids loop
    select c.* into v_loser from public.phoenix_crm_customers c where c.id = v_loser_id for update;
    if not found then
      raise exception 'phoenix_crm:customer_not_found';
    end if;
    if v_loser.status = 'dropped' then
      raise exception 'phoenix_crm:customer_dropped';
    end if;
    if v_loser.seat_id <> v_keeper.seat_id or v_loser.is_test <> v_keeper.is_test then
      raise exception 'phoenix_crm:not_same_list';
    end if;
    if v_loser.list_type <> v_keeper.list_type then
      raise exception 'phoenix_crm:list_type_differs';
    end if;
    if v_loser.validated_at is not null and v_keeper.validated_at is null then
      raise exception 'phoenix_crm:keeper_not_validated';
    end if;
    if exists (select 1 from public.phoenix_crm_places pl where pl.customer_id = v_loser.id and pl.status = 'active')
       and not exists (select 1 from public.phoenix_crm_places pl where pl.customer_id = v_keeper.id and pl.status = 'active') then
      raise exception 'phoenix_crm:keeper_holds_no_place';
    end if;
    if exists (select 1 from public.phoenix_crm_customer_moves m where m.customer_id = v_loser.id) then
      raise exception 'phoenix_crm:loser_has_moves';
    end if;

    -- The four unique keys a repoint could collide on. Each measured 0 on 2026-10-08; each still
    -- refuses, so a collision can never be resolved silently by whichever row the update hit first.
    if exists (
      select 1 from public.phoenix_crm_visits a
      join public.phoenix_crm_visits b
        on b.seat_id = a.seat_id and b.visit_date = a.visit_date and b.is_test = a.is_test
      where a.customer_id = v_loser.id and b.customer_id = v_keeper.id
    ) then
      raise exception 'phoenix_crm:visit_same_day';
    end if;
    if exists (
      select 1 from public.phoenix_crm_plan_items a
      join public.phoenix_crm_plan_items b on b.plan_id = a.plan_id and b.plan_date = a.plan_date
      where a.customer_id = v_loser.id and b.customer_id = v_keeper.id
    ) then
      raise exception 'phoenix_crm:plan_same_day';
    end if;
    if exists (
      select 1 from public.phoenix_crm_visit_asks a
      join public.phoenix_crm_visit_asks b
        on b.seat_id = a.seat_id and b.kind = a.kind and b.is_test = a.is_test and b.status = 'waiting'
      where a.customer_id = v_loser.id and a.status = 'waiting' and b.customer_id = v_keeper.id
    ) then
      raise exception 'phoenix_crm:ask_waiting_twice';
    end if;
    -- The district manager's own visit (owner, 2026-10-16): one per customer per day, like a rep's.
    if exists (
      select 1 from public.phoenix_crm_manager_visits a
      join public.phoenix_crm_manager_visits b
        on b.manager_hr_id = a.manager_hr_id and b.visit_date = a.visit_date and b.is_test = a.is_test
      where a.customer_id = v_loser.id and b.customer_id = v_keeper.id
    ) then
      raise exception 'phoenix_crm:manager_visit_same_day';
    end if;

    -- Anything still waiting on the loser is withdrawn first — something waiting on a row that has
    -- left the list is a decision nobody can take — which also clears the one-pending unique key.
    with withdrawn as (
      update public.phoenix_crm_list_requests q
      set status = 'withdrawn',
          stage = null,
          decided_at = now(),
          decided_by_hr_id = v_actor,
          decision_note = 'Merged into the same customer entered once on this list'
      where q.customer_id = v_loser.id
        and q.status = 'pending'
      returning q.id
    )
    insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
    select v_loser.seat_id, v_loser.id, w.id, 'request_withdrawn', v_actor, jsonb_build_object('why', 'merged'), v_loser.is_test
    from withdrawn w;
    get diagnostics v_n = row_count;
    v_withdrawn := v_withdrawn + v_n;

    update public.phoenix_crm_places set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_places := v_places + v_n;
    update public.phoenix_crm_visits set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_visits := v_visits + v_n;
    update public.phoenix_crm_validation_reviews set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_reviews := v_reviews + v_n;
    update public.phoenix_crm_plan_items set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_plan_items := v_plan_items + v_n;
    update public.phoenix_crm_unplanned_visits set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_unplanned := v_unplanned + v_n;
    update public.phoenix_crm_visit_asks set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_asks := v_asks + v_n;
    update public.phoenix_crm_list_requests set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_requests := v_requests + v_n;
    -- The district manager's half-day already holding the keeper keeps that one row: it is one person.
    delete from public.phoenix_crm_manager_plan_customers a
    where a.customer_id = v_loser.id
      and exists (
        select 1 from public.phoenix_crm_manager_plan_customers b
        where b.slot_id = a.slot_id and b.customer_id = v_keeper.id
      );
    update public.phoenix_crm_manager_plan_customers set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_manager_plan := v_manager_plan + v_n;
    update public.phoenix_crm_manager_visits set customer_id = v_keeper.id where customer_id = v_loser.id;
    get diagnostics v_n = row_count;
    v_manager_visits := v_manager_visits + v_n;

    update public.phoenix_crm_customers c
    set status = 'dropped',
        dropped_reason = 'duplicate',
        dropped_note = v_note,
        status_changed_at = now(),
        updated_at = now()
    where c.id = v_loser.id;

    -- Two events on the one list's trail, the shape phoenix_crm_move_customer writes: the row that
    -- left reads where it went, and the row that stayed reads what joined it.
    insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
    values
      (v_loser.seat_id, v_loser.id, 'customer_merged_out', v_actor,
       jsonb_build_object('into_customer_id', v_keeper.id, 'note', v_note), v_loser.is_test),
      (v_keeper.seat_id, v_keeper.id, 'customer_merged_in', v_actor,
       jsonb_build_object('from_customer_id', v_loser.id, 'note', v_note), v_keeper.is_test);
  end loop;

  -- The five-active-place cap, after the repoint, so it reads exactly what the keeper now holds.
  select count(*) into v_n from public.phoenix_crm_places pl where pl.customer_id = v_keeper.id and pl.status = 'active';
  if v_n > 5 then
    raise exception 'phoenix_crm:too_many_places';
  end if;

  return jsonb_build_object(
    'keeper_id', v_keeper.id,
    'merged', cardinality(v_loser_ids),
    'places', v_places,
    'visits', v_visits,
    'validation_reviews', v_reviews,
    'plan_items', v_plan_items,
    'unplanned_visits', v_unplanned,
    'visit_asks', v_asks,
    'list_requests', v_requests,
    'requests_withdrawn', v_withdrawn,
    'manager_plan_customers', v_manager_plan,
    'manager_visits', v_manager_visits
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_merge_duplicate_customer(p jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_merge_duplicate_customer(p jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_merge_duplicate_customer(p jsonb) IS 'Merges one rep''s same-person duplicate rows into the keeper row the caller chose: repoints places, visits, reviews, plan items, unplanned visits, visit asks and list requests, withdraws anything pending on the loser, archives the loser as dropped/duplicate (never deleted), and writes customer_merged_out/in events. Refuses on any guard. Called only by scripts/phoenix-crm-merge-same-seat-duplicates.ts.';

--
-- Name: phoenix_crm_monthly_plan_transition(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_monthly_plan_transition(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan_id uuid := nullif(p ->> 'monthly_plan_id', '')::uuid;
  v_action text := coalesce(p ->> 'action', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_seat text;
  v_month date;
  v_month_end date;
  v_plan public.phoenix_crm_monthly_plans%rowtype;
  v_from text;
  v_event text;
  v_week_from text[];
  v_week_to text;
  v_late boolean;
begin
  if v_plan_id is null or v_actor is null or v_action not in ('submit', 'reopen', 'approve', 'return') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select mp.seat_id, mp.month_start into v_seat, v_month from public.phoenix_crm_monthly_plans mp where mp.id = v_plan_id;
  if not found then
    raise exception 'phoenix_crm:plan_not_found';
  end if;
  v_month_end := (v_month + interval '1 month' - interval '1 day')::date;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:monthly:' || v_seat || ':' || v_month::text));

  select mp.* into v_plan from public.phoenix_crm_monthly_plans mp where mp.id = v_plan_id for update;
  if v_plan.is_test <> v_is_test then
    raise exception 'phoenix_crm:plan_not_found';
  end if;
  if v_expected is distinct from v_plan.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  v_from := v_plan.status;
  if v_action <> 'approve' and v_month_end < v_today then
    raise exception 'phoenix_crm:month_passed';
  end if;

  if v_action = 'submit' then
    if v_from not in ('draft', 'returned') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    if not exists (
      select 1
      from public.phoenix_crm_plans pl
      join public.phoenix_crm_plan_items i on i.plan_id = pl.id
      where pl.seat_id = v_seat and pl.is_test = v_is_test
        and date_trunc('month', pl.week_start)::date = v_month
    ) then
      raise exception 'phoenix_crm:empty_plan';
    end if;
    -- Late, from the server's own clock. A month with no due date on file (one opened before this
    -- migration and never reopened) is never called late.
    v_late := v_plan.due_on is not null and v_today > v_plan.due_on;
    update public.phoenix_crm_monthly_plans mp
    set status = 'submitted', submitted_at = now(), submitted_by_hr_id = v_actor, submitted_late = v_late,
        decided_at = null, decided_by_hr_id = null, decided_by_role = null, decision_note = null,
        version = mp.version + 1, updated_at = now()
    where mp.id = v_plan.id
    returning mp.* into v_plan;
    v_event := 'submitted';
    v_week_from := array['draft', 'returned'];
    v_week_to := 'submitted';

  elsif v_action = 'reopen' then
    if v_from not in ('submitted', 'approved') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    update public.phoenix_crm_monthly_plans mp
    set status = 'draft', decided_at = null, decided_by_hr_id = null, decided_by_role = null, decision_note = null,
        version = mp.version + 1, updated_at = now()
    where mp.id = v_plan.id
    returning mp.* into v_plan;
    v_event := 'reopened';
    v_week_from := array['submitted', 'approved'];
    v_week_to := 'draft';

  elsif v_action = 'approve' then
    if v_from <> 'submitted' then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    update public.phoenix_crm_monthly_plans mp
    set status = 'approved', decided_at = now(), decided_by_hr_id = v_actor, decided_by_role = v_role,
        decision_note = v_note, version = mp.version + 1, updated_at = now()
    where mp.id = v_plan.id
    returning mp.* into v_plan;
    v_event := 'approved';
    v_week_from := array['submitted'];
    v_week_to := 'approved';

  else
    if v_from not in ('submitted', 'approved') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    if v_note is null then
      raise exception 'phoenix_crm:note_required';
    end if;
    update public.phoenix_crm_monthly_plans mp
    set status = 'returned', decided_at = now(), decided_by_hr_id = v_actor, decided_by_role = v_role,
        decision_note = v_note, version = mp.version + 1, updated_at = now()
    where mp.id = v_plan.id
    returning mp.* into v_plan;
    v_event := 'returned';
    v_week_from := array['submitted', 'approved'];
    v_week_to := 'returned';
  end if;

  -- Cascade the month's field-week plans and record each week's own event. A week sent with its
  -- month carries the MONTH's verdict: it is judged against the month's date, not its own Thursday.
  with moved as (
    update public.phoenix_crm_plans pl
    set status = v_week_to,
        submitted_at = case when v_week_to = 'submitted' then now() else (case when v_week_to = 'draft' then null else pl.submitted_at end) end,
        submitted_by_hr_id = case when v_week_to = 'submitted' then v_actor else (case when v_week_to = 'draft' then null else pl.submitted_by_hr_id end) end,
        due_on = coalesce(pl.due_on, pl.week_start - 2),
        submitted_late = case when v_week_to = 'submitted' then coalesce(v_late, false) else pl.submitted_late end,
        submitted_via = case when v_week_to = 'submitted' then 'month' else pl.submitted_via end,
        decided_at = case when v_week_to = 'approved' or v_week_to = 'returned' then now() else null end,
        decided_by_hr_id = case when v_week_to = 'approved' or v_week_to = 'returned' then v_actor else null end,
        decided_by_role = case when v_week_to = 'approved' or v_week_to = 'returned' then v_role else null end,
        decision_note = case when v_week_to = 'approved' or v_week_to = 'returned' then v_note else null end,
        version = pl.version + 1,
        updated_at = now()
    where pl.seat_id = v_seat and pl.is_test = v_is_test
      and date_trunc('month', pl.week_start)::date = v_month
      and pl.status = any (v_week_from)
      and (v_week_to <> 'submitted' or exists (select 1 from public.phoenix_crm_plan_items i where i.plan_id = pl.id))
    returning pl.id, pl.status, pl.version
  )
  insert into public.phoenix_crm_plan_events (plan_id, event_type, actor_hr_id, actor_role, to_status, version, note)
  select moved.id, v_event, v_actor, v_role, moved.status, moved.version, v_note from moved;

  insert into public.phoenix_crm_monthly_plan_events (monthly_plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note)
  values (v_plan.id, v_event, v_actor, v_role, v_from, v_plan.status, v_plan.version, v_note);

  return jsonb_build_object(
    'monthly_plan_id', v_plan.id,
    'seat_id', v_plan.seat_id,
    'line_code', v_plan.line_code,
    'month_start', v_plan.month_start,
    'status', v_plan.status,
    'version', v_plan.version,
    'due_on', v_plan.due_on,
    'submitted_late', v_plan.submitted_late
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_monthly_plan_transition(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_move_customer(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_move_customer(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_from_seat text := nullif(trim(coalesce(p ->> 'from_seat_id', '')), '');
  v_to_seat text := nullif(trim(coalesce(p ->> 'to_seat_id', '')), '');
  v_to_line text := nullif(trim(coalesce(p ->> 'to_line_code', '')), '');
  v_reason text := nullif(regexp_replace(trim(coalesce(p ->> 'reason', '')), '\s+', ' ', 'g'), '');
  v_customer public.phoenix_crm_customers%rowtype;
  v_from_line text;
  v_places integer := 0;
  v_move_id bigint;
begin
  if v_actor is null or v_customer_id is null or v_from_seat is null or v_to_seat is null or v_to_line is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_from_seat = v_to_seat then
    raise exception 'phoenix_crm:same_seat';
  end if;
  if v_reason is null or char_length(v_reason) < 10 or char_length(v_reason) > 500 then
    raise exception 'phoenix_crm:note_required';
  end if;

  -- Both seats, in a fixed order, so two moves in opposite directions cannot deadlock.
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || least(v_from_seat, v_to_seat)));
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || greatest(v_from_seat, v_to_seat)));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id
    and c.seat_id = v_from_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.status = 'dropped' then
    raise exception 'phoenix_crm:customer_dropped';
  end if;
  -- A customer met outside the list is on nobody's list, so there is nothing to hand over: he is
  -- admitted or archived where he stands (phoenix_crm_archive_outside).
  if v_customer.status = 'outside' then
    raise exception 'phoenix_crm:not_on_list';
  end if;
  v_from_line := v_customer.line_code;

  -- ONE CUSTOMER, ONE NAME KEY on the seat he joins — the same fold the sheet loader and the rename
  -- apply, so a move can never create the duplicate the duplicates board exists to raise. An archived
  -- namesake on the destination is not a clash: he is off the list.
  if exists (
    select 1
    from public.phoenix_crm_customers c
    where c.seat_id = v_to_seat
      and c.is_test = v_is_test
      and c.status <> 'dropped'
      and c.list_type = v_customer.list_type
      and public.phoenix_crm_fold_name(c.name) = public.phoenix_crm_fold_name(v_customer.name)
  ) then
    raise exception 'phoenix_crm:duplicate_at_destination';
  end if;
  -- And the destination cannot already carry his iReports360 row (phoenix_crm_customers_reference_uidx).
  if v_customer.reference_contact_crm_id is not null and exists (
    select 1
    from public.phoenix_crm_customers c
    where c.seat_id = v_to_seat
      and c.is_test = v_is_test
      and c.reference_contact_crm_id = v_customer.reference_contact_crm_id
  ) then
    raise exception 'phoenix_crm:duplicate_at_destination';
  end if;

  update public.phoenix_crm_customers c
  set seat_id = v_to_seat,
      line_code = v_to_line,
      updated_at = now()
  where c.id = v_customer.id
  returning c.* into v_customer;

  -- The clinics travel with him: the fixed point, the photo and the hours are the customer's, not the
  -- rep's, and a validated place is never captured twice.
  update public.phoenix_crm_places pl
  set seat_id = v_to_seat,
      updated_at = now()
  where pl.customer_id = v_customer.id;
  get diagnostics v_places = row_count;

  -- Anything still waiting belonged to the seat he left and its reviewers. It is withdrawn rather than
  -- carried over: the new rep did not ask for it, and the old rep's manager no longer decides for him.
  with withdrawn as (
    update public.phoenix_crm_list_requests q
    set status = 'withdrawn',
        stage = null,
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decision_note = 'The customer moved to another rep'
    where q.customer_id = v_customer.id
      and q.status = 'pending'
    returning q.id
  )
  insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
  select v_from_seat, v_customer.id, w.id, 'request_withdrawn', v_actor, jsonb_build_object('why', 'moved'), v_is_test
  from withdrawn w;

  insert into public.phoenix_crm_customer_moves (
    customer_id, from_seat_id, to_seat_id, from_line_code, to_line_code, reason, moved_by_hr_id, is_test
  )
  values (v_customer.id, v_from_seat, v_to_seat, v_from_line, v_to_line, v_reason, v_actor, v_is_test)
  returning id into v_move_id;

  -- Two events, one on each seat's trail: the list he left reads that he went, and the list he joined
  -- reads where he came from. One row on one seat would leave the other list with no history at all.
  insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
  values
    (v_from_seat, v_customer.id, 'customer_moved_out', v_actor,
     jsonb_build_object('to_seat_id', v_to_seat, 'to_line_code', v_to_line, 'reason', v_reason, 'places', v_places), v_is_test),
    (v_to_seat, v_customer.id, 'customer_moved_in', v_actor,
     jsonb_build_object('from_seat_id', v_from_seat, 'from_line_code', v_from_line, 'reason', v_reason, 'places', v_places), v_is_test);

  return jsonb_build_object(
    'move_id', v_move_id,
    'customer_id', v_customer.id,
    'customer_name', v_customer.name,
    'list_type', v_customer.list_type,
    'status', v_customer.status,
    'from_seat_id', v_from_seat,
    'to_seat_id', v_to_seat,
    'places', v_places
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_move_customer(p jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_move_customer(p jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_move_customer(p jsonb) IS 'Moves one Phoenix CRM customer and his clinics from one rep seat to another, in one transaction, with the written reason recorded in phoenix_crm_customer_moves. Refuses a duplicate at the destination. The SFE Manager''s own act — the app is the authority on who may call it.';

--
-- Name: phoenix_crm_move_place(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_move_place(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_reason text := nullif(regexp_replace(trim(coalesce(p ->> 'reason', '')), '\s+', ' ', 'g'), '');
  v_to jsonb := p -> 'location';
  v_place public.phoenix_crm_places%rowtype;
  v_after public.phoenix_crm_places%rowtype;
begin
  if v_seat is null or v_actor is null or nullif(p ->> 'place_id', '') is null
    or jsonb_typeof(v_to) is distinct from 'object'
    or (v_to ->> 'lat') is null or (v_to ->> 'lon') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_reason is null or char_length(v_reason) < 10 or char_length(v_reason) > 500 then
    raise exception 'phoenix_crm:move_reason_required';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select pl.* into v_place
  from public.phoenix_crm_places pl
  where pl.id = (p ->> 'place_id')::uuid
    and pl.seat_id = v_seat
    and pl.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:place_not_found';
  end if;
  if v_place.status <> 'active' then
    raise exception 'phoenix_crm:place_retired';
  end if;

  update public.phoenix_crm_places pl
  set lat = (v_to ->> 'lat')::double precision,
      lon = (v_to ->> 'lon')::double precision,
      accuracy_meters = (v_to ->> 'accuracy_meters')::numeric,
      address = nullif(trim(coalesce(v_to ->> 'address', '')), ''),
      zone = nullif(trim(coalesce(v_to ->> 'zone', '')), ''),
      brick_id = nullif(trim(coalesce(v_to ->> 'brick_id', '')), ''),
      brick_name = nullif(trim(coalesce(v_to ->> 'brick_name', '')), ''),
      brick_distance_km = (v_to ->> 'brick_distance_km')::numeric,
      -- 2026-10-08 — the move re-resolves the location through the same resolvePlaceLocation, so the
      -- lookup is re-stated here too. Without this line a moved place would keep describing the
      -- lookup done at coordinates it no longer sits on.
      brick_lookup = coalesce(nullif(trim(coalesce(v_to ->> 'brick_lookup', '')), ''), 'could_not_look'),
      area_code = nullif(trim(coalesce(v_to ->> 'area_code', '')), ''),
      area_name = nullif(trim(coalesce(v_to ->> 'area_name', '')), ''),
      region_code = nullif(trim(coalesce(v_to ->> 'region_code', '')), ''),
      region_name = nullif(trim(coalesce(v_to ->> 'region_name', '')), ''),
      point_source = 'moved',
      moved_at = now(),
      moved_by_hr_id = v_actor,
      move_reason = v_reason,
      updated_at = now()
  where pl.id = v_place.id
  returning pl.* into v_after;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_place.customer_id, v_place.id, 'place_moved', v_actor,
    jsonb_build_object(
      'reason', v_reason,
      'before', jsonb_build_object(
        'lat', v_place.lat, 'lon', v_place.lon, 'point_source', v_place.point_source,
        'address', v_place.address, 'brick_id', v_place.brick_id, 'area_code', v_place.area_code
      ),
      'after', jsonb_build_object(
        'lat', v_after.lat, 'lon', v_after.lon,
        'address', v_after.address, 'brick_id', v_after.brick_id, 'area_code', v_after.area_code
      )
    ),
    v_is_test
  );

  return jsonb_build_object('place_id', v_after.id, 'customer_id', v_after.customer_id, 'moved_at', v_after.moved_at);
end;
$$;

ALTER FUNCTION public.phoenix_crm_move_place(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_offplan_exempt(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_offplan_exempt(p_seat text, p_customer uuid, p_place uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.phoenix_crm_offplan_exemptions e
    where e.seat_id = p_seat
      and e.ended_at is null
      and (
        (e.customer_id is not null and e.customer_id = p_customer)
        or (
          (e.venue_name_key is not null or e.shared_place_id is not null)
          and p_place is not null
          and exists (
            select 1
            from public.phoenix_crm_places pl
            join public.phoenix_crm_shared_places sp on sp.id = pl.shared_place_id
            where pl.id = p_place
              and sp.seat_id = p_seat
              and (
                e.shared_place_id = sp.id
                or public.phoenix_crm_fold_name(sp.name) like '%' || e.venue_name_key || '%'
              )
          )
        )
      )
  );
$$;

ALTER FUNCTION public.phoenix_crm_offplan_exempt(p_seat text, p_customer uuid, p_place uuid) OWNER TO postgres;

--
-- Name: phoenix_crm_offplan_exempt_customers(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_offplan_exempt_customers(p_seat text) RETURNS TABLE(customer_id uuid, label text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct c.id, e.label
  from public.phoenix_crm_offplan_exemptions e
  join public.phoenix_crm_customers c on c.seat_id = e.seat_id
  where e.seat_id = p_seat
    and e.ended_at is null
    and (
      (e.customer_id is not null and c.id = e.customer_id)
      or (
        (e.venue_name_key is not null or e.shared_place_id is not null)
        and exists (
          select 1
          from public.phoenix_crm_places pl
          join public.phoenix_crm_shared_places sp on sp.id = pl.shared_place_id
          where pl.customer_id = c.id
            and sp.seat_id = e.seat_id
            and (
              e.shared_place_id = sp.id
              or public.phoenix_crm_fold_name(sp.name) like '%' || e.venue_name_key || '%'
            )
        )
      )
    );
$$;

ALTER FUNCTION public.phoenix_crm_offplan_exempt_customers(p_seat text) OWNER TO postgres;

--
-- Name: phoenix_crm_offplan_rep_exempt(text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_offplan_rep_exempt(p_seat text, p_rep text, p_day date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.phoenix_crm_offplan_exemptions e
    where e.seat_id = p_seat
      and e.rep_hr_id = p_rep
      and e.ended_at is null
      and p_day between e.valid_from and e.valid_until
  );
$$;

ALTER FUNCTION public.phoenix_crm_offplan_rep_exempt(p_seat text, p_rep text, p_day date) OWNER TO postgres;

--
-- Name: phoenix_crm_offplan_visit_cap(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_offplan_visit_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_daily integer;
  v_weekly integer;
  v_week_start date;
  v_day_doctors integer;
  v_week_doctors integer;
begin
  -- The Super Admin recording what already happened: there is no other day to plan it for.
  if new.capture_source = 'admin' then
    return new;
  end if;

  -- A visit under a named exception — a venue of this seat, or this rep's dated window — is not capped and
  -- is stamped, so no count below includes it.
  if public.phoenix_crm_offplan_exempt(new.seat_id, new.customer_id, new.place_id)
     or public.phoenix_crm_offplan_rep_exempt(new.seat_id, new.rep_hr_id, new.visit_date) then
    new.offplan_exempt := true;
    return new;
  end if;

  select s.offplan_daily_cap, s.offplan_weekly_cap into v_daily, v_weekly
  from public.phoenix_crm_settings s where s.id = 1;
  v_daily := coalesce(v_daily, 2);
  v_weekly := coalesce(v_weekly, 8);

  v_week_start := new.visit_date - ((extract(dow from new.visit_date)::integer + 1) % 7);

  select count(distinct v.customer_id) into v_day_doctors
  from public.phoenix_crm_visits v
  where v.seat_id = new.seat_id
    and v.is_test = new.is_test
    and v.unplanned_kind = 'out_of_plan'
    and v.list_type in ('AM', 'PM')
    and not v.offplan_exempt
    and v.visit_date = new.visit_date
    and v.customer_id <> new.customer_id;
  if v_day_doctors >= v_daily then
    raise exception 'phoenix_crm:offplan_day_full';
  end if;

  select count(distinct v.customer_id) into v_week_doctors
  from public.phoenix_crm_visits v
  where v.seat_id = new.seat_id
    and v.is_test = new.is_test
    and v.unplanned_kind = 'out_of_plan'
    and v.list_type in ('AM', 'PM')
    and not v.offplan_exempt
    and v.visit_date >= v_week_start
    and v.visit_date < v_week_start + 7
    and v.customer_id <> new.customer_id;
  if v_week_doctors >= v_weekly then
    raise exception 'phoenix_crm:offplan_week_full';
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phoenix_crm_offplan_visit_cap() OWNER TO postgres;

--
-- Name: phoenix_crm_open_monthly_plan(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_open_monthly_plan(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_month date := nullif(p ->> 'month_start', '')::date;
  v_due date;
  v_plan public.phoenix_crm_monthly_plans%rowtype;
begin
  if v_seat is null or v_line is null or v_actor is null or v_month is null
    or extract(day from v_month) <> 1 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  -- The last Thursday on or before the last day of the month before. isodow puts Thursday at 4.
  v_due := (v_month - 1) - ((extract(isodow from (v_month - 1))::integer - 4 + 7) % 7);

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:monthly:' || v_seat || ':' || v_month::text));

  select mp.* into v_plan
  from public.phoenix_crm_monthly_plans mp
  where mp.seat_id = v_seat and mp.month_start = v_month and mp.is_test = v_is_test
  for update;

  if not found then
    insert into public.phoenix_crm_monthly_plans (seat_id, line_code, month_start, status, version, created_by_hr_id, is_test, due_on)
    values (v_seat, v_line, v_month, 'draft', 1, v_actor, v_is_test, v_due)
    returning * into v_plan;

    insert into public.phoenix_crm_monthly_plan_events (monthly_plan_id, event_type, actor_hr_id, to_status, version)
    values (v_plan.id, 'created', v_actor, 'draft', 1);
  elsif v_plan.due_on is null then
    update public.phoenix_crm_monthly_plans mp set due_on = v_due where mp.id = v_plan.id returning mp.* into v_plan;
  end if;

  return jsonb_build_object(
    'monthly_plan_id', v_plan.id,
    'status', v_plan.status,
    'version', v_plan.version,
    'due_on', v_plan.due_on,
    'submitted_late', v_plan.submitted_late
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_open_monthly_plan(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_photos_to_fingerprint(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_photos_to_fingerprint(p jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with candidates as (
    select
      'visit'::text as subject_kind,
      v.id as subject_id,
      v.photo_path,
      v.seat_id,
      coalesce(v.rep_hr_id, v.manager_hr_id, v.entered_by_hr_id) as rep_hr_id,
      v.customer_id,
      v.captured_at,
      v.is_test
    from public.phoenix_crm_visits v
    where v.photo_path is not null
      and (coalesce((p ->> 'include_test')::boolean, false) or v.is_test = false)
    union all
    select
      'place'::text,
      pl.id,
      pl.photo_path,
      pl.seat_id,
      pl.created_by_hr_id,
      pl.customer_id,
      pl.captured_at,
      pl.is_test
    from public.phoenix_crm_places pl
    where pl.photo_path is not null
      and (coalesce((p ->> 'include_test')::boolean, false) or pl.is_test = false)
  )
  select coalesce(jsonb_agg(to_jsonb(picked) order by picked.captured_at), '[]'::jsonb)
  from (
    select c.*
    from candidates c
    left join public.phoenix_crm_photo_fingerprints f on f.photo_path = c.photo_path
    where f.photo_path is null
    order by c.captured_at
    limit greatest(1, least(2000, coalesce((p ->> 'limit')::int, 200)))
  ) picked;
$$;

ALTER FUNCTION public.phoenix_crm_photos_to_fingerprint(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_place_on_trusted_point(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_place_on_trusted_point(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := nullif(trim(coalesce(p ->> 'actor_hr_id', '')), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_loc jsonb := p -> 'location';
  v_basis jsonb := p -> 'basis';
  v_customer public.phoenix_crm_customers%rowtype;
  v_place_id uuid;
  v_event text;
  v_was text;
begin
  if v_seat is null or v_actor is null or p ->> 'customer_id' is null
    or jsonb_typeof(v_loc) is distinct from 'object'
    or jsonb_typeof(v_basis) is distinct from 'object'
    or (v_loc ->> 'lat') is null or (v_loc ->> 'lon') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = (p ->> 'customer_id')::uuid
    and c.seat_id = v_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.status = 'dropped' then
    raise exception 'phoenix_crm:archived';
  end if;
  if v_customer.status not in ('pending', 'active') then
    raise exception 'phoenix_crm:not_on_list';
  end if;
  if v_customer.list_type not in ('AM', 'PM') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if exists (
    select 1 from public.phoenix_crm_places pl
    where pl.customer_id = v_customer.id and pl.status = 'active'
  ) then
    raise exception 'phoenix_crm:already_has_place';
  end if;
  if exists (
    select 1 from public.phoenix_crm_validation_reviews r
    where r.customer_id = v_customer.id and r.status = 'pending'
  ) then
    raise exception 'phoenix_crm:location_in_review';
  end if;

  insert into public.phoenix_crm_places (
    customer_id, seat_id, lat, lon, accuracy_meters, timings, photo_path, captured_at, created_by_hr_id, is_test,
    point_source, trusted_basis, address, zone, brick_lookup, brick_id, brick_name, brick_distance_km,
    area_code, area_name, region_code, region_name
  )
  values (
    v_customer.id,
    v_seat,
    (v_loc ->> 'lat')::double precision,
    (v_loc ->> 'lon')::double precision,
    nullif(v_loc ->> 'accuracy_meters', '')::numeric,
    '[]'::jsonb,
    null,
    now(),
    v_actor,
    v_is_test,
    'trusted',
    v_basis,
    left(nullif(v_loc ->> 'address', ''), 200),
    left(nullif(v_loc ->> 'zone', ''), 80),
    coalesce(nullif(v_loc ->> 'brick_lookup', ''), 'could_not_look'),
    nullif(v_loc ->> 'brick_id', ''),
    nullif(v_loc ->> 'brick_name', ''),
    nullif(v_loc ->> 'brick_distance_km', '')::numeric,
    nullif(v_loc ->> 'area_code', ''),
    nullif(v_loc ->> 'area_name', ''),
    nullif(v_loc ->> 'region_code', ''),
    nullif(v_loc ->> 'region_name', '')
  )
  returning id into v_place_id;

  v_was := v_customer.status;
  if v_customer.status = 'pending' then
    update public.phoenix_crm_customers c
    set status = 'active',
        validated_at = now(),
        validated_by_hr_id = v_actor,
        status_changed_at = now(),
        updated_at = now()
    where c.id = v_customer.id;
    v_event := 'customer_validated';
  else
    v_event := 'place_added';
  end if;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer.id, v_place_id, v_event, v_actor,
    jsonb_build_object('mode', 'trusted_point', 'basis', v_basis, 'was', v_was),
    v_is_test
  );

  return jsonb_build_object(
    'place_id', v_place_id,
    'customer_id', v_customer.id,
    'status', 'active',
    'event', v_event
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_place_on_trusted_point(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_places_line_twin_follow(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_places_line_twin_follow() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_copy record;
begin
  if old.status = 'active' and new.status = 'retired' then
    for v_copy in
      update public.phoenix_crm_places pl
      set status = 'retired',
          retired_at = now(),
          retired_by_hr_id = 'SYSTEM',
          updated_at = now()
      where pl.point_source = 'line_twin'
        and pl.status = 'active'
        and (pl.trusted_basis ->> 'source_place_id') = new.id::text
      returning pl.id, pl.customer_id, pl.seat_id, pl.is_test
    loop
      insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
      values (v_copy.seat_id, v_copy.customer_id, v_copy.id, 'place_retired', 'SYSTEM',
        jsonb_build_object('why', 'source_retired', 'source_place_id', new.id), v_copy.is_test);

      if not exists (select 1 from public.phoenix_crm_places pl where pl.customer_id = v_copy.customer_id and pl.status = 'active') then
        update public.phoenix_crm_customers c
        set status = 'pending', validated_at = null, validated_by_hr_id = null, status_changed_at = now(), updated_at = now()
        where c.id = v_copy.customer_id and c.status = 'active';
        if found then
          insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
          values (v_copy.seat_id, v_copy.customer_id, 'customer_pending', 'SYSTEM',
            jsonb_build_object('why', 'line_twin_source_retired', 'source_place_id', new.id), v_copy.is_test);
        end if;
      end if;
    end loop;
  elsif new.status = 'active' and (old.lat is distinct from new.lat or old.lon is distinct from new.lon) then
    update public.phoenix_crm_places pl
    set lat = new.lat,
        lon = new.lon,
        accuracy_meters = new.accuracy_meters,
        address = new.address,
        zone = new.zone,
        brick_id = new.brick_id,
        brick_name = new.brick_name,
        brick_distance_km = new.brick_distance_km,
        brick_lookup = new.brick_lookup,
        area_code = new.area_code,
        area_name = new.area_name,
        region_code = new.region_code,
        region_name = new.region_name,
        pin_lat = null,
        pin_lon = null,
        pin_accuracy_meters = null,
        trusted_basis = pl.trusted_basis || jsonb_build_object('source_point_source', new.point_source, 'followed_at', now()),
        updated_at = now()
    where pl.point_source = 'line_twin'
      and pl.status = 'active'
      and (pl.trusted_basis ->> 'source_place_id') = new.id::text;
  end if;
  return null;
end;
$$;

ALTER FUNCTION public.phoenix_crm_places_line_twin_follow() OWNER TO postgres;

--
-- Name: phoenix_crm_plan_day_status(uuid, date, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_plan_day_status(p_plan_id uuid, p_day date, p_as_of timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- The plan's LATEST event as of the instant — phoenix_crm_save_visit's own subquery, word for word, for
  -- one plan (tests/phoenix-crm-visits-everywhere.test.ts holds the two together).
  select case
    when latest.to_status in ('submitted', 'approved') then latest.to_status
    when latest.to_status = 'returned'
      and p_day <> nullif(latest.details ->> 'returned_day', '')::date
      and not exists (
        select 1
        from public.phoenix_crm_plan_edit_requests r
        where r.plan_id = p_plan_id
          and r.hr_acknowledged_at > latest.created_at
          and r.hr_acknowledged_at <= p_as_of
      )
    -- What the week was when the day was returned: the RETURN event itself, never a later save (a save
    -- writes from_status = to_status = the plan's status, and is never a change of status).
    then coalesce((
      select case when rt.from_status = 'approved' then 'approved' end
      from public.phoenix_crm_plan_events rt
      where rt.plan_id = p_plan_id
        and rt.event_type = 'returned'
        and rt.created_at <= p_as_of
      order by rt.created_at desc, rt.id desc
      limit 1
    ), 'submitted')
  end
  from (
    select e.to_status, e.details, e.created_at
    from public.phoenix_crm_plan_events e
    where e.plan_id = p_plan_id
      and e.to_status is not null
      and e.created_at <= p_as_of
    order by e.created_at desc, e.id desc
    limit 1
  ) latest
$$;

ALTER FUNCTION public.phoenix_crm_plan_day_status(p_plan_id uuid, p_day date, p_as_of timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_plan_day_status(p_plan_id uuid, p_day date, p_as_of timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_plan_day_status(p_plan_id uuid, p_day date, p_as_of timestamp with time zone) IS 'What one weekly plan said about one day at one instant: submitted, approved, or null (not a sent day). phoenix_crm_save_visit''s own "was he planned" rule for one plan, with a one-day return of another day leaving the week as it stood.';

--
-- Name: phoenix_crm_plan_item_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_plan_item_counts(p_plan_ids uuid[]) RETURNS TABLE(plan_id uuid, items integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select i.plan_id, count(*)::integer as items
  from public.phoenix_crm_plan_items i
  where i.plan_id = any(p_plan_ids)
  group by i.plan_id;
$$;

ALTER FUNCTION public.phoenix_crm_plan_item_counts(p_plan_ids uuid[]) OWNER TO postgres;

--
-- Name: phoenix_crm_plan_transition(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_plan_transition(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan_id uuid := nullif(p ->> 'plan_id', '')::uuid;
  v_action text := coalesce(p ->> 'action', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_day date := nullif(p ->> 'day', '')::date;
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_seat text;
  v_week date;
  v_plan public.phoenix_crm_plans%rowtype;
  v_from text;
  v_event text;
  v_details jsonb := '{}'::jsonb;
begin
  if v_plan_id is null or v_actor is null or v_action not in ('submit', 'reopen', 'approve', 'return') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- Only a return names a day (owner, 2026-10-02).
  if v_day is not null and v_action <> 'return' then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select pl.seat_id, pl.week_start into v_seat, v_week from public.phoenix_crm_plans pl where pl.id = v_plan_id;
  if not found then
    raise exception 'phoenix_crm:plan_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:plan:' || v_seat || ':' || v_week::text));

  select pl.* into v_plan from public.phoenix_crm_plans pl where pl.id = v_plan_id for update;
  if v_plan.is_test <> v_is_test then
    raise exception 'phoenix_crm:plan_not_found';
  end if;
  if v_expected is distinct from v_plan.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  v_from := v_plan.status;
  if v_action <> 'approve' and v_plan.week_start + 5 < v_today then
    raise exception 'phoenix_crm:week_passed';
  end if;

  if v_action = 'submit' then
    if v_from not in ('draft', 'returned') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    if not exists (select 1 from public.phoenix_crm_plan_items i where i.plan_id = v_plan.id) then
      raise exception 'phoenix_crm:empty_plan';
    end if;
    -- Sent on its own, the week is judged against its own deadline — 23:55 Cairo on its due date, from
    -- the server's clock, and accepted whenever it arrives (owner, 2026-09-29; the hour, 2026-10-02).
    -- A week sent AGAIN after an acknowledged edit keeps the verdict its first send earned (owner,
    -- 2026-10-01): the change was agreed by his manager, SFE and HR, and must not read as lateness.
    -- A one-day return is answered by this send, so the week is whole again (owner, 2026-10-02).
    update public.phoenix_crm_plans pl
    set status = 'submitted',
        submitted_at = now(),
        submitted_by_hr_id = v_actor,
        due_on = public.phoenix_crm_week_due_on(pl.week_start),
        submitted_late = case
          when exists (
            select 1 from public.phoenix_crm_plan_edit_requests r where r.plan_id = pl.id and r.status = 'reopened'
          ) then pl.submitted_late
          else now() > public.phoenix_crm_week_deadline_at(pl.week_start)
        end,
        submitted_via = 'week',
        returned_day = null,
        decided_at = null,
        decided_by_hr_id = null,
        decided_by_role = null,
        decision_note = null,
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    v_event := 'submitted';
    -- WHAT WAS SENT, kept on the send's own event (owner, 2026-10-02): a week that comes back for
    -- review after a return or an acknowledged edit is shown only what changed against the version
    -- sent before it. Customers by day with the name as it stood — so one who has since left the list
    -- is still named — and every planned activity.
    v_details := jsonb_build_object(
      'items', coalesce((
        select jsonb_agg(
                 jsonb_build_object('plan_date', i.plan_date, 'customer_id', i.customer_id, 'list_type', i.list_type, 'name', c.name)
                 order by i.plan_date, i.list_type, c.name, i.customer_id)
        from public.phoenix_crm_plan_items i
        left join public.phoenix_crm_customers c on c.id = i.customer_id
        where i.plan_id = v_plan.id
      ), '[]'::jsonb),
      'activities', coalesce((
        select jsonb_agg(
                 jsonb_build_object('plan_date', a.plan_date, 'activity_type', a.activity_type, 'half_day', a.half_day)
                 order by a.plan_date, a.activity_type)
        from public.phoenix_crm_plan_activities a
        where a.plan_id = v_plan.id
      ), '[]'::jsonb)
    );

  elsif v_action = 'reopen' then
    if v_from not in ('submitted', 'approved') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    update public.phoenix_crm_plans pl
    set status = 'draft',
        returned_day = null,
        decided_at = null,
        decided_by_hr_id = null,
        decided_by_role = null,
        decision_note = null,
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    v_event := 'reopened';

  elsif v_action = 'approve' then
    if v_from <> 'submitted' then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    update public.phoenix_crm_plans pl
    set status = 'approved',
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decided_by_role = v_role,
        decision_note = v_note,
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    v_event := 'approved';

  else
    if v_from not in ('submitted', 'approved') then
      raise exception 'phoenix_crm:bad_transition';
    end if;
    if v_note is null then
      raise exception 'phoenix_crm:note_required';
    end if;
    -- ONE DAY (owner, 2026-10-02: "Only that day"): a working day of this week, Saturday to Thursday,
    -- that has not passed on the Cairo calendar — the rep must still be able to change it.
    if v_day is not null and (v_day < v_plan.week_start or v_day > v_plan.week_start + 5 or v_day < v_today) then
      raise exception 'phoenix_crm:day_not_returnable';
    end if;
    update public.phoenix_crm_plans pl
    set status = 'returned',
        returned_day = v_day,
        decided_at = now(),
        decided_by_hr_id = v_actor,
        decided_by_role = v_role,
        decision_note = v_note,
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    v_event := 'returned';
    if v_day is not null then
      v_details := jsonb_build_object('returned_day', v_day);
    end if;
  end if;

  insert into public.phoenix_crm_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
  values (v_plan.id, v_event, v_actor, v_role, v_from, v_plan.status, v_plan.version, v_note, v_details);

  return jsonb_build_object(
    'plan_id', v_plan.id,
    'seat_id', v_plan.seat_id,
    'line_code', v_plan.line_code,
    'week_start', v_plan.week_start,
    'status', v_plan.status,
    'from_status', v_from,
    'version', v_plan.version,
    'submitted_by_hr_id', v_plan.submitted_by_hr_id,
    'created_by_hr_id', v_plan.created_by_hr_id,
    'is_test', v_plan.is_test,
    'due_on', v_plan.due_on,
    'submitted_late', v_plan.submitted_late,
    'submitted_via', v_plan.submitted_via,
    'returned_day', v_plan.returned_day
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_plan_transition(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_planned_day(text, boolean, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_planned_day(p_seat_id text, p_is_test boolean, p_week_start date, p_day date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with plan as (
    select pl.id, pl.status, pl.version, pl.returned_day, pl.decided_at
    from public.phoenix_crm_plans pl
    where pl.seat_id = p_seat_id
      and pl.is_test = p_is_test
      and pl.week_start = p_week_start
    limit 1
  ),
  items as (
    select i.id, i.customer_id
    from public.phoenix_crm_plan_items i
    join plan pl on pl.id = i.plan_id
    where i.plan_date = p_day
  ),
  edits as (
    select e.*, pl.status as plan_status, pl.version as plan_version
    from public.phoenix_crm_plan_edit_requests e
    join plan pl on pl.id = e.plan_id
    where e.is_test = p_is_test
  ),
  return_events as (
    select ev.id, ev.plan_id, ev.from_status, ev.created_at
    from public.phoenix_crm_plan_events ev
    join plan pl on pl.id = ev.plan_id
    where ev.event_type = 'returned'
  )
  select jsonb_build_object(
    'plan', (select to_jsonb(pl.*) from plan pl),
    'items', coalesce((select jsonb_agg(i.customer_id order by i.id) from items i), '[]'::jsonb),
    'edits', coalesce(
      (select jsonb_agg(
         ((to_jsonb(e.*) - 'plan_status' - 'plan_version') || jsonb_build_object('plan', jsonb_build_object('status', e.plan_status, 'version', e.plan_version)))
         order by e.created_at desc, e.id desc
       ) from edits e),
      '[]'::jsonb
    ),
    'returns', coalesce(
      (select jsonb_agg(jsonb_build_object('plan_id', r.plan_id, 'from_status', r.from_status) order by r.created_at desc, r.id desc) from return_events r),
      '[]'::jsonb
    ),
    'stops', case
      when exists (select 1 from plan pl where pl.status <> 'draft')
        then public.phoenix_crm_territory_customers(
          p_seat_id,
          p_is_test,
          array['active', 'pending'],
          coalesce((select array_agg(i.customer_id) from items i), '{}'::uuid[])
        )
      else jsonb_build_object('customers', '[]'::jsonb, 'places', '[]'::jsonb, 'venues', '[]'::jsonb)
    end
  );
$$;

ALTER FUNCTION public.phoenix_crm_planned_day(p_seat_id text, p_is_test boolean, p_week_start date, p_day date) OWNER TO postgres;

--
-- Name: phoenix_crm_prepare_ireports360_conversion(boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_prepare_ireports360_conversion(p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_matches_written integer := 0;
  v_archive_written integer := 0;
  v_rows_archived integer := 0;
begin
  perform pg_advisory_xact_lock(hashtext('public.phoenix_crm_prepare_ireports360_conversion'));

  drop table if exists pg_temp.phx_conv_match;
  drop table if exists pg_temp.phx_conv_archive;
  drop table if exists pg_temp.phx_conv_rows;

  -- Every regular visit's check-in: the agent at that contact, on the visit's day as the doors read a
  -- check-in's day — its wall clock as stored (Cairo, labelled UTC: the vendor convention) — inside Egypt's
  -- box. Of several, the one nearest the visit's own time (both on the same wall clock), then the lowest id.
  -- Measured 7 Nov 2026: 101,829 of 106,231 regular visits match on that day; 96,478 on a Cairo-shifted day.
  create temp table phx_conv_match on commit drop as
  select iv.crm_visit_id, ck.crm_checkin_id, ck.lat, ck.lon, ck.check_date
  from public.ireports360_visits iv
  cross join lateral (
    select c.crm_checkin_id, c.lat, c.lon, c.check_date
    from public.ireports360_checkins c
    where c.agent_crm_id = iv.agent_crm_id
      and c.contact_crm_id = iv.contact_crm_id
      and c.check_date >= iv.visit_date::timestamp at time zone 'UTC'
      and c.check_date < (iv.visit_date + 1)::timestamp at time zone 'UTC'
      and c.lat between 21.5 and 32
      and c.lon between 24 and 37.5
    order by abs(extract(epoch from (c.check_date - coalesce(iv.visit_date_time, c.check_date)))), c.crm_checkin_id
    limit 1
  ) ck
  where iv.visit_type = 0
    and nullif(iv.contact_crm_id, 0) is not null;
  create unique index on phx_conv_match (crm_visit_id);
  analyze phx_conv_match;

  -- The archive: every campaign visit, and every regular visit with no check-in location. A visit already
  -- copied names its Phoenix row and that row's seat; one never copied names the territory its agent held
  -- that day, when he held one.
  create temp table phx_conv_archive on commit drop as
  select
    iv.crm_visit_id,
    iv.visit_date,
    iv.agent_crm_id,
    nullif(btrim(iv.agent_hr_id), '') as agent_hr_id,
    nullif(btrim(iv.agent_name), '') as agent_name,
    nullif(iv.contact_crm_id, 0) as contact_crm_id,
    nullif(btrim(iv.contact_name), '') as customer_name,
    iv.visit_type,
    case when iv.visit_type = -8 then 'campaign' else 'no_checkin_location' end as reason,
    s.visit_id,
    coalesce(pv.seat_id, held.seat_id) as seat_id,
    coalesce(pv.line_code, held.line_code) as line_code,
    -- A check-in on that day and contact that lay outside Egypt's box: counted, never used.
    (iv.visit_type = 0 and exists (
      select 1 from public.ireports360_checkins c
      where c.agent_crm_id = iv.agent_crm_id and c.contact_crm_id = iv.contact_crm_id
        and c.check_date >= iv.visit_date::timestamp at time zone 'UTC'
        and c.check_date < (iv.visit_date + 1)::timestamp at time zone 'UTC'
        and c.lat is not null and c.lon is not null
    )) as checkin_outside_box
  from public.ireports360_visits iv
  left join public.phoenix_crm_imported_visit_sources s on s.crm_visit_id = iv.crm_visit_id
  left join public.phoenix_crm_visits pv on pv.id = s.visit_id
  left join lateral (
    select o.seat_id, o.line_code
    from public.au_v_seat_occupancy_all o
    where pv.id is null
      and lower(o.occupant_canonical_hr_id) = lower(btrim(iv.agent_hr_id))
      and o.node_type = 'person'
      and o.seat_id like '%-REP-%'
      and o.effective_from <= iv.visit_date
      and (o.effective_to is null or o.effective_to >= iv.visit_date)
    order by o.effective_from desc, o.seat_id
    limit 1
  ) held on true
  where iv.visit_type = -8
     or (iv.visit_type = 0 and not exists (select 1 from phx_conv_match m where m.crm_visit_id = iv.crm_visit_id));

  -- A copied Phoenix row that is not a visit: none of its old visits is a regular visit (a campaign visit),
  -- or none of its regular ones had a check-in location. A row merging two old visits stands if either did.
  create temp table phx_conv_rows on commit drop as
  select
    v.id,
    case when bool_or(iv.visit_type = 0) then 'no_checkin_location' else 'campaign' end as reason
  from public.phoenix_crm_visits v
  join public.phoenix_crm_imported_visit_sources s on s.visit_id = v.id
  join public.ireports360_visits iv on iv.crm_visit_id = s.crm_visit_id
  left join phx_conv_match m on m.crm_visit_id = iv.crm_visit_id
  where v.imported_from_ireports360_at is not null
    and v.archived_at is null
  group by v.id
  having not bool_or(iv.visit_type = 0 and m.crm_visit_id is not null);

  if p_apply then
    insert into public.phoenix_crm_ireports360_checkin_matches (crm_visit_id, crm_checkin_id, lat, lon, check_date, matched_at)
    select m.crm_visit_id, m.crm_checkin_id, m.lat, m.lon, m.check_date, v_now
    from phx_conv_match m
    order by m.crm_visit_id
    on conflict (crm_visit_id) do nothing;
    get diagnostics v_matches_written = row_count;

    insert into public.phoenix_crm_visit_archive (
      crm_visit_id, visit_date, agent_crm_id, agent_hr_id, agent_name, contact_crm_id, customer_name,
      visit_type, reason, visit_id, seat_id, line_code, archived_at
    )
    select a.crm_visit_id, a.visit_date, a.agent_crm_id, a.agent_hr_id, a.agent_name, a.contact_crm_id,
           left(a.customer_name, 200), a.visit_type, a.reason, a.visit_id, a.seat_id, a.line_code, v_now
    from phx_conv_archive a
    order by a.crm_visit_id
    on conflict (crm_visit_id) do nothing;
    get diagnostics v_archive_written = row_count;

    -- NEVER a delete (production has no PITR): the row stays, marked, and every reader skips the mark.
    update public.phoenix_crm_visits v
       set archived_at = v_now,
           archive_reason = r.reason
      from phx_conv_rows r
     where v.id = r.id
       and v.archived_at is null;
    get diagnostics v_rows_archived = row_count;
  end if;

  return jsonb_build_object(
    'applied', p_apply,
    'regular_visits', (select count(*) from public.ireports360_visits where visit_type = 0),
    'regular_with_checkin_location', (select count(*) from phx_conv_match),
    'regular_with_checkin_location_no_hr_id', (
      select count(*) from phx_conv_match m join public.ireports360_visits iv on iv.crm_visit_id = m.crm_visit_id
      where nullif(btrim(iv.agent_hr_id), '') is null
    ),
    'archive', jsonb_build_object(
      'campaign_copied', (select count(*) from phx_conv_archive where reason = 'campaign' and visit_id is not null),
      'campaign_never_copied', (select count(*) from phx_conv_archive where reason = 'campaign' and visit_id is null),
      'no_checkin_location_copied', (select count(*) from phx_conv_archive where reason = 'no_checkin_location' and visit_id is not null),
      'no_checkin_location_never_copied', (select count(*) from phx_conv_archive where reason = 'no_checkin_location' and visit_id is null),
      'checkin_outside_box', (select count(*) from phx_conv_archive where checkin_outside_box)
    ),
    'copied_rows_to_archive', jsonb_build_object(
      'campaign', (select count(*) from phx_conv_rows where reason = 'campaign'),
      'no_checkin_location', (select count(*) from phx_conv_rows where reason = 'no_checkin_location')
    ),
    'copied_rows_with_no_source', (
      select count(*) from public.phoenix_crm_visits v
      where v.imported_from_ireports360_at is not null
        and not exists (select 1 from public.phoenix_crm_imported_visit_sources s where s.visit_id = v.id)
    ),
    'written', jsonb_build_object(
      'matches', v_matches_written,
      'archive', v_archive_written,
      'copied_rows_archived', v_rows_archived
    )
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_prepare_ireports360_conversion(p_apply boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_raise_double_visit_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_raise_double_visit_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_rep text := upper(nullif(trim(coalesce(p ->> 'rep_hr_id', '')), ''));
  v_visit_id uuid := nullif(p ->> 'visit_id', '')::uuid;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_days date[];
  v_customer public.phoenix_crm_customers%rowtype;
  v_request public.phoenix_crm_double_visit_requests%rowtype;
  v_found boolean := false;
  v_created boolean := false;
  v_person jsonb;
  v_asked text;
  v_role text;
  v_day date;
begin
  if v_seat is null or v_customer_id is null or v_rep is null
     or jsonb_typeof(p -> 'days') is distinct from 'array'
     or jsonb_typeof(p -> 'people') is distinct from 'array'
     or jsonb_array_length(p -> 'people') = 0 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  -- The days: one to three, each a field day from today to four weeks on, none twice, never a Friday.
  select coalesce(array_agg(d order by d), '{}'::date[]) into v_days
  from (select distinct (value #>> '{}')::date as d from jsonb_array_elements(p -> 'days')) days;
  if cardinality(v_days) < 1 or cardinality(v_days) > 3
     or cardinality(v_days) <> jsonb_array_length(p -> 'days') then
    raise exception 'phoenix_crm:double_visit_bad_days';
  end if;
  foreach v_day in array v_days loop
    if v_day < v_today or v_day > v_today + 27 or extract(isodow from v_day) = 5 then
      raise exception 'phoenix_crm:double_visit_bad_days';
    end if;
  end loop;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:double_visit_request:' || v_seat || ':' || v_customer_id::text || ':' || v_is_test::text));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id and c.seat_id = v_seat and c.is_test = v_is_test;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;

  -- Once per visit: a save sent twice raises the request once.
  if v_visit_id is not null then
    select r.* into v_request
    from public.phoenix_crm_double_visit_requests r
    where r.visit_id = v_visit_id;
    v_found := found;
  end if;

  if not v_found then
    -- An AM or PM account on the list: validated, or carried over and waiting to be. A pharmacy is
    -- neither, and a customer in the Archive is not on the list.
    if v_customer.list_type not in ('AM', 'PM') or v_customer.status not in ('active', 'pending') then
      raise exception 'phoenix_crm:double_visit_not_requestable';
    end if;

    insert into public.phoenix_crm_double_visit_requests (seat_id, line_code, customer_id, rep_hr_id, visit_id, days, is_test)
    values (v_seat, v_line, v_customer_id, v_rep, v_visit_id, v_days, v_is_test)
    returning * into v_request;

    for v_person in select value from jsonb_array_elements(p -> 'people') loop
      v_asked := upper(nullif(trim(coalesce(v_person ->> 'hr_id', '')), ''));
      v_role := coalesce(v_person ->> 'role', '');
      -- Nobody asks himself, and every role is one the module knows.
      if v_asked is null or v_asked = v_rep or v_role not in ('manager', 'product_manager') then
        raise exception 'phoenix_crm:bad_input';
      end if;
      insert into public.phoenix_crm_double_visit_request_people (request_id, asked_hr_id, role, is_test)
      values (v_request.id, v_asked, v_role, v_is_test)
      on conflict (request_id, asked_hr_id) do nothing;
    end loop;
    v_created := true;
  end if;

  return jsonb_build_object(
    'id', v_request.id,
    'created', v_created,
    'seat_id', v_request.seat_id,
    'customer_name', v_customer.name,
    'customer_list_type', v_customer.list_type,
    'days', to_jsonb(v_request.days),
    'is_test', v_request.is_test,
    'people', coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'hr_id', q.asked_hr_id, 'role', q.role, 'status', q.status) order by q.created_at, q.asked_hr_id)
      from public.phoenix_crm_double_visit_request_people q
      where q.request_id = v_request.id
    ), '[]'::jsonb)
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_raise_double_visit_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_raise_manager_plan_edit(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_raise_manager_plan_edit(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan_id uuid := nullif(p ->> 'plan_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_approver text := upper(nullif(trim(coalesce(p ->> 'approver_hr_id', '')), ''));
  v_second text := upper(nullif(trim(coalesce(p ->> 'second_approver_hr_id', '')), ''));
  v_reason text := nullif(regexp_replace(trim(coalesce(p ->> 'reason', '')), '\s+', ' ', 'g'), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_manager text;
  v_week date;
  v_plan public.phoenix_crm_manager_plans%rowtype;
  v_request public.phoenix_crm_manager_plan_edit_requests%rowtype;
begin
  if v_plan_id is null or v_actor is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_reason is null or char_length(v_reason) < 3 or char_length(v_reason) > 500 then
    raise exception 'phoenix_crm:note_required';
  end if;
  if v_approver is null then
    raise exception 'phoenix_crm:manager_plan_no_approver';
  end if;
  if v_second is not null and v_second = v_approver then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select pl.manager_hr_id, pl.week_start into v_manager, v_week
  from public.phoenix_crm_manager_plans pl where pl.id = v_plan_id;
  if not found then
    raise exception 'phoenix_crm:manager_plan_not_found';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('phoenix_crm:manager_plan:' || v_manager || ':' || v_week::text || ':' || v_is_test::text)
  );

  select pl.* into v_plan from public.phoenix_crm_manager_plans pl where pl.id = v_plan_id for update;
  if v_plan.is_test <> v_is_test then
    raise exception 'phoenix_crm:manager_plan_not_found';
  end if;
  if v_approver = v_plan.manager_hr_id or v_second = v_plan.manager_hr_id then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_plan.status not in ('submitted', 'first_approved', 'approved') then
    raise exception 'phoenix_crm:bad_transition';
  end if;
  if v_plan.week_start + 5 < v_today then
    raise exception 'phoenix_crm:week_passed';
  end if;
  if exists (
    select 1 from public.phoenix_crm_manager_plan_edit_requests r
    where r.plan_id = v_plan.id and r.status in ('pending', 'first_approved')
  ) then
    raise exception 'phoenix_crm:manager_plan_edit_already_open';
  end if;

  insert into public.phoenix_crm_manager_plan_edit_requests
    (plan_id, manager_hr_id, week_start, approver_hr_id, second_approver_hr_id, reason, status, plan_status_at_raise, is_test)
  values
    (v_plan.id, v_plan.manager_hr_id, v_plan.week_start, v_approver, v_second, v_reason, 'pending', v_plan.status, v_plan.is_test)
  returning * into v_request;

  insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
  values (v_plan.id, 'edit_asked', v_actor, case when v_actor = v_plan.manager_hr_id then 'manager' else 'administrator' end,
          v_plan.status, v_plan.status, v_plan.version, v_reason, jsonb_build_object('request_id', v_request.id));

  return jsonb_build_object(
    'request_id', v_request.id,
    'plan_id', v_plan.id,
    'manager_hr_id', v_plan.manager_hr_id,
    'week_start', v_plan.week_start,
    'approver_hr_id', v_request.approver_hr_id,
    'second_approver_hr_id', v_request.second_approver_hr_id,
    'status', v_request.status,
    'version', v_request.version,
    'is_test', v_request.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_raise_manager_plan_edit(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_raise_manager_single_visit_day(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_raise_manager_single_visit_day(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_manager text := upper(nullif(trim(coalesce(p ->> 'manager_hr_id', '')), ''));
  v_seat text := nullif(trim(coalesce(p ->> 'manager_seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_date date := nullif(p ->> 'visit_date', '')::date;
  v_approver text := upper(nullif(trim(coalesce(p ->> 'approver_hr_id', '')), ''));
  v_second text := upper(nullif(trim(coalesce(p ->> 'second_approver_hr_id', '')), ''));
  v_reason text := nullif(regexp_replace(trim(coalesce(p ->> 'reason', '')), '\s+', ' ', 'g'), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_week date;
  v_row public.phoenix_crm_manager_single_visit_days%rowtype;
begin
  if v_manager is null or v_actor is null or v_date is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- The reason is optional (owner, 2026-10-20: "make writing why optional"); only its length is held.
  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_approver is null then
    raise exception 'phoenix_crm:manager_plan_no_approver';
  end if;
  if v_approver = v_manager or v_second = v_manager or (v_second is not null and v_second = v_approver) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if extract(isodow from v_date) = 5 then
    raise exception 'phoenix_crm:single_visit_day_not_field';
  end if;
  if v_date < v_today then
    raise exception 'phoenix_crm:single_visit_day_passed';
  end if;
  -- This week or the coming one: the application names the exact weeks; this is the outer fence.
  if v_date > v_today + 13 then
    raise exception 'phoenix_crm:single_visit_day_too_far';
  end if;

  -- Saturday is isodow 6, so (isodow + 1) % 7 days back is the week's Saturday.
  v_week := v_date - ((extract(isodow from v_date)::integer + 1) % 7);

  -- The week's own lock, the one every half-day save of his week takes.
  perform pg_advisory_xact_lock(
    hashtext('phoenix_crm:manager_plan:' || v_manager || ':' || v_week::text || ':' || v_is_test::text)
  );

  if exists (
    select 1 from public.phoenix_crm_manager_single_visit_days d
    where d.manager_hr_id = v_manager and d.visit_date = v_date and d.is_test = v_is_test
      and d.status in ('pending', 'first_approved', 'approved')
  ) then
    raise exception 'phoenix_crm:single_visit_day_already_asked';
  end if;
  -- The second and the third day: two asked or approved a week at most.
  if (
    select count(*) from public.phoenix_crm_manager_single_visit_days d
    where d.manager_hr_id = v_manager and d.week_start = v_week and d.is_test = v_is_test
      and d.status in ('pending', 'first_approved', 'approved')
  ) >= 2 then
    raise exception 'phoenix_crm:single_visit_days_full';
  end if;

  insert into public.phoenix_crm_manager_single_visit_days
    (manager_hr_id, manager_seat_id, week_start, visit_date, reason, status, approver_hr_id, second_approver_hr_id, is_test)
  values
    (v_manager, v_seat, v_week, v_date, v_reason, 'pending', v_approver, v_second, v_is_test)
  returning * into v_row;

  return jsonb_build_object(
    'request_id', v_row.id,
    'manager_hr_id', v_row.manager_hr_id,
    'week_start', v_row.week_start,
    'visit_date', v_row.visit_date,
    'approver_hr_id', v_row.approver_hr_id,
    'second_approver_hr_id', v_row.second_approver_hr_id,
    'status', v_row.status,
    'version', v_row.version,
    'is_test', v_row.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_raise_manager_single_visit_day(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_raise_plan_edit_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_raise_plan_edit_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_plan_id uuid := nullif(p ->> 'plan_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_first text := coalesce(p ->> 'first_status', '');
  v_manager text := upper(nullif(trim(coalesce(p ->> 'manager_hr_id', '')), ''));
  v_expected integer := nullif(p ->> 'expected_plan_version', '')::integer;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_seat text;
  v_week date;
  v_plan public.phoenix_crm_plans%rowtype;
  v_request public.phoenix_crm_plan_edit_requests%rowtype;
begin
  if v_plan_id is null or v_actor is null or v_first not in ('manager_pending', 'sfe_pending') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- A request that starts with the manager names him; one that starts at SFE names nobody.
  if (v_first = 'manager_pending') <> (v_manager is not null) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select pl.seat_id, pl.week_start into v_seat, v_week from public.phoenix_crm_plans pl where pl.id = v_plan_id;
  if not found then
    raise exception 'phoenix_crm:plan_not_found';
  end if;

  -- The plan's own lock, so a request and a send, a decision or a save of the same week never cross.
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:plan:' || v_seat || ':' || v_week::text));

  select pl.* into v_plan from public.phoenix_crm_plans pl where pl.id = v_plan_id for update;
  if v_plan.is_test <> v_is_test then
    raise exception 'phoenix_crm:plan_not_found';
  end if;
  if v_expected is distinct from v_plan.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  if v_plan.week_start + 5 < v_today then
    raise exception 'phoenix_crm:week_passed';
  end if;
  if v_plan.status not in ('submitted', 'approved') then
    raise exception 'phoenix_crm:plan_edit_not_sent';
  end if;
  if exists (
    select 1 from public.phoenix_crm_plan_edit_requests r
    where r.plan_id = v_plan.id and r.status in ('manager_pending', 'sfe_pending', 'hr_pending')
  ) then
    raise exception 'phoenix_crm:plan_edit_already_open';
  end if;

  insert into public.phoenix_crm_plan_edit_requests
    (plan_id, seat_id, line_code, week_start, rep_hr_id, status, manager_hr_id, plan_status_at_raise, is_test)
  values
    (v_plan.id, v_plan.seat_id, v_plan.line_code, v_plan.week_start, v_actor, v_first,
     case when v_first = 'manager_pending' then v_manager else null end, v_plan.status, v_plan.is_test)
  returning * into v_request;

  insert into public.phoenix_crm_plan_edit_request_events
    (request_id, event_type, actor_hr_id, actor_role, actor_stage, from_status, to_status, version, details)
  values
    (v_request.id, 'raised', v_actor, 'rep', null, null, v_request.status, v_request.version,
     jsonb_build_object('plan_id', v_plan.id, 'plan_status', v_plan.status, 'plan_version', v_plan.version));

  return jsonb_build_object(
    'request_id', v_request.id,
    'plan_id', v_request.plan_id,
    'seat_id', v_request.seat_id,
    'week_start', v_request.week_start,
    'rep_hr_id', v_request.rep_hr_id,
    'status', v_request.status,
    'version', v_request.version
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_raise_plan_edit_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_raise_visit_ask(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_raise_visit_ask(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_kind text := coalesce(p ->> 'kind', '');
  v_rep text := upper(nullif(trim(coalesce(p ->> 'rep_hr_id', '')), ''));
  v_asked text := upper(nullif(trim(coalesce(p ->> 'asked_hr_id', '')), ''));
  v_told text := upper(nullif(trim(coalesce(p ->> 'told_hr_id', '')), ''));
  v_wished date := nullif(p ->> 'wished_on', '')::date;
  v_visit_id uuid := nullif(p ->> 'visit_id', '')::uuid;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_customer public.phoenix_crm_customers%rowtype;
  v_ask public.phoenix_crm_visit_asks%rowtype;
  v_found boolean := false;
  v_created boolean := false;
begin
  if v_seat is null or v_customer_id is null or v_rep is null or v_asked is null
     or v_kind not in ('double', 'product_manager', 'chain') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- Nobody asks himself, and the people on one ask are three different people.
  if v_asked = v_rep or v_told = v_rep or v_told = v_asked
     or (v_kind = 'double' and v_told is not null) or (v_kind = 'chain' and v_told is null) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('phoenix_crm:visit_ask:' || v_seat || ':' || v_customer_id::text || ':' || v_kind || ':' || v_is_test::text)
  );

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id and c.seat_id = v_seat and c.is_test = v_is_test;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;

  -- Once per visit: a save sent twice raises the ask once.
  if v_visit_id is not null then
    select a.* into v_ask
    from public.phoenix_crm_visit_asks a
    where a.visit_id = v_visit_id;
    v_found := found;
  end if;

  if not v_found then
    -- A customer on the list: validated, or carried over and waiting to be. Never one waiting outside
    -- the list, and never one in the Archive.
    if v_customer.status not in ('active', 'pending') then
      raise exception 'phoenix_crm:visit_ask_not_on_list';
    end if;

    -- One ask in play per territory, customer and kind: waiting, or accepted for a day still to come.
    select a.* into v_ask
    from public.phoenix_crm_visit_asks a
    where a.seat_id = v_seat
      and a.customer_id = v_customer_id
      and a.kind = v_kind
      and a.is_test = v_is_test
      and (a.status = 'waiting' or (a.status = 'accepted' and a.visit_on >= v_today))
    order by a.created_at desc
    limit 1;
    v_found := found;
    -- From the customer's page that is a second press. From a visit's next step it is the answer.
    if v_found and v_visit_id is null then
      raise exception 'phoenix_crm:visit_ask_already_open';
    end if;
  end if;

  if not v_found then
    -- A wished day is a wish: one that cannot be a field day to come is dropped, never refused.
    if v_wished is not null and (v_wished < v_today or v_wished > v_today + 27 or extract(isodow from v_wished) = 5) then
      v_wished := null;
    end if;
    insert into public.phoenix_crm_visit_asks
      (seat_id, line_code, customer_id, kind, rep_hr_id, asked_hr_id, told_hr_id, wished_on, visit_id, is_test)
    values
      (v_seat, v_line, v_customer_id, v_kind, v_rep, v_asked, v_told, v_wished, v_visit_id, v_is_test)
    returning * into v_ask;
    v_created := true;
  end if;

  return jsonb_build_object(
    'id', v_ask.id,
    'kind', v_ask.kind,
    'status', v_ask.status,
    'asked_hr_id', v_ask.asked_hr_id,
    'told_hr_id', v_ask.told_hr_id,
    'wished_on', v_ask.wished_on,
    'visit_on', v_ask.visit_on,
    'created', v_created,
    'customer_name', v_customer.name,
    'customer_list_type', v_customer.list_type,
    'is_test', v_ask.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_raise_visit_ask(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_reference_entry(text, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_reference_entry(p_seat_id text, p_contact_crm_id bigint, p_is_test boolean DEFAULT false) RETURNS TABLE(contact_crm_id bigint, list_type text, grade text, name text, speciality text, customer_id uuid, state text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- The live reference list first: while iReports360 still has the rep assigned, nothing changes.
  select r.contact_crm_id, r.list_type, r.grade, r.name, r.speciality, r.customer_id, r.state
  from public.phoenix_crm_seat_reference(array[p_seat_id], p_is_test) r
  where r.contact_crm_id = p_contact_crm_id
  union all
  -- The assignment ended, but the customer the rep carried over is still on his list, because that is
  -- the rule. He is resolved from his own row, with seat_reference's own state vocabulary so that
  -- every caller reads him exactly as it would read a live one.
  select
    c.reference_contact_crm_id,
    c.list_type,
    c.grade,
    c.name,
    c.speciality,
    c.id,
    case
      when c.status = 'dropped' then 'dropped'
      when c.status = 'active' then 'validated'
      when exists (
        select 1
        from public.phoenix_crm_list_requests q
        where q.seat_id = c.seat_id
          and q.kind = 'drop'
          and q.status = 'pending'
          and q.is_test = p_is_test
          and (q.customer_id = c.id or (q.customer_id is null and q.reference_contact_crm_id = c.reference_contact_crm_id))
      ) then 'drop_pending'
      else 'open'
    end
  from public.phoenix_crm_customers c
  where c.seat_id = p_seat_id
    and c.is_test = p_is_test
    and c.reference_contact_crm_id = p_contact_crm_id
    and not exists (
      select 1
      from public.phoenix_crm_seat_reference(array[p_seat_id], p_is_test) r2
      where r2.contact_crm_id = p_contact_crm_id
    )
  limit 1;
$$;

ALTER FUNCTION public.phoenix_crm_reference_entry(p_seat_id text, p_contact_crm_id bigint, p_is_test boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_rename_customer(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rename_customer(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_name text := nullif(regexp_replace(trim(coalesce(p ->> 'name', '')), '\s+', ' ', 'g'), '');
  v_speciality text := nullif(regexp_replace(trim(coalesce(p ->> 'speciality', '')), '\s+', ' ', 'g'), '');
  -- Present, even as null or empty, means "set it"; absent means "leave it".
  v_sets_phone boolean := (p -> 'phone') is not null;
  v_phone text := nullif(regexp_replace(coalesce(p ->> 'phone', ''), '\s+', '', 'g'), '');
  -- 2026-10-12: the same fold the door and the loader use. v_name is initialised above, and plpgsql
  -- evaluates DECLARE initialisers in order, so this one may read it.
  v_name_key text := public.phoenix_crm_fold_name(v_name);
  v_customer public.phoenix_crm_customers%rowtype;
  v_before jsonb;
begin
  if v_seat is null or v_actor is null or v_customer_id is null or v_name is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_phone is not null and v_phone !~ '^\+?[0-9]{7,15}$' then
    raise exception 'phoenix_crm:bad_phone';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id
    and c.seat_id = v_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.status = 'dropped' then
    raise exception 'phoenix_crm:customer_dropped';
  end if;

  -- The fold, not lower() — see phoenix_crm_validate_customer above for the rule and its fences. The
  -- scope here stays ('active', 'pending') as it was: an `outside` row is not on this rep's list, and
  -- widening it would be a rule change rather than a key change.
  if not coalesce((p ->> 'allow_same_name')::boolean, false) and v_name_key <> '' and exists (
    select 1
    from public.phoenix_crm_customers c
    where c.seat_id = v_seat
      and c.is_test = v_is_test
      and c.id <> v_customer.id
      and c.status in ('active', 'pending')
      and c.list_type = v_customer.list_type
      and public.phoenix_crm_fold_name(c.name) = v_name_key
  ) then
    raise exception 'phoenix_crm:same_name';
  end if;

  v_before := jsonb_build_object('name', v_customer.name, 'speciality', v_customer.speciality, 'phone', v_customer.phone);

  update public.phoenix_crm_customers c
  set name = left(v_name, 200),
      speciality = left(v_speciality, 120),
      phone = case when v_sets_phone then v_phone else c.phone end,
      updated_at = now()
  where c.id = v_customer.id
  returning c.* into v_customer;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer.id, 'customer_renamed', v_actor,
    jsonb_build_object(
      'from', v_before,
      'to', jsonb_build_object('name', v_customer.name, 'speciality', v_customer.speciality, 'phone', v_customer.phone)
    ),
    v_is_test
  );

  return jsonb_build_object(
    'customer_id', v_customer.id,
    'customer_name', v_customer.name,
    'speciality', v_customer.speciality,
    'phone', v_customer.phone
  );
end;
$_$;

ALTER FUNCTION public.phoenix_crm_rename_customer(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days() RETURNS TABLE(hr_key text, agent_crm_id bigint, entry_day date)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 400
    SET search_path TO 'public'
    AS $$
  select c.hr_key, c.agent_crm_id, c.entry_day
    from public.phoenix_crm_rep_entry_days_cache c
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days() OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_calc(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_calc(p_hr_key text DEFAULT NULL::text, p_day date DEFAULT NULL::date) RETURNS TABLE(hr_key text, agent_crm_id bigint, entry_day date)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 400
    SET search_path TO 'public'
    AS $_$
  with entries as (
    select lower(btrim(p.rep_hr_id)) as hr_key, p.visit_date as entry_day
      from public.phoenix_crm_countable_visits p
      join public.phoenix_crm_started_team_seats() team
        on team.seat_id = p.seat_id
       and p.visit_date >= team.starts_on
       and (team.stops_on is null or p.visit_date < team.stops_on)
     where not p.is_test
       and nullif(btrim(p.rep_hr_id), '') is not null
       and p.imported_from_ireports360_at is null
       and (p_day is null or p.visit_date = p_day)
       and (p_hr_key is null or lower(btrim(p.rep_hr_id)) = p_hr_key)
    union
    select lower(btrim(a.rep_hr_id)), a.activity_date
      from public.phoenix_crm_day_activities a
      join public.phoenix_crm_started_team_seats() team on team.seat_id = a.seat_id
      left join public.phoenix_crm_team_starts run
        on run.team_seat_id = team.team_seat_id
       and run.starts_on = team.starts_on
       and run.stops_on is not distinct from team.stops_on
     where not a.is_test
       and nullif(btrim(a.rep_hr_id), '') is not null
       and a.activity_date >= least(team.starts_on, coalesce(run.day_activities_from, team.starts_on))
       and (team.stops_on is null or a.activity_date < team.stops_on)
       and a.activity_type in ('meeting', 'conference', 'health_day', 'sales_day', 'training', 'admin_work', 'travel', 'group_meeting', 'rtd', 'interviews')
       and (p_day is null or a.activity_date = p_day)
       and (p_hr_key is null or lower(btrim(a.rep_hr_id)) = p_hr_key)
  )
  select e.hr_key, person.agent_crm_id, e.entry_day
    from entries e
    left join lateral (
      select case when emp.crm_id ~ '^[0-9]+$' then emp.crm_id::bigint end as agent_crm_id
        from public.employees emp
       where upper(btrim(emp.hr_id)) = upper(e.hr_key)
       order by emp.hr_id
       limit 1
    ) person on true
$_$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_calc(p_hr_key text, p_day date) OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_on_day_activity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_on_day_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform public.phoenix_crm_rep_entry_days_touch(old.rep_hr_id, old.activity_date);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform public.phoenix_crm_rep_entry_days_touch(new.rep_hr_id, new.activity_date);
  end if;
  return null;
end
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_on_day_activity() OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_on_team_start(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_on_team_start() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.phoenix_crm_rep_entry_days_rebuild();
  return null;
end
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_on_team_start() OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_on_visit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_on_visit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if old.imported_from_ireports360_at is null then
      perform public.phoenix_crm_rep_entry_days_touch(old.rep_hr_id, old.visit_date);
    end if;
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    if new.imported_from_ireports360_at is null then
      perform public.phoenix_crm_rep_entry_days_touch(new.rep_hr_id, new.visit_date);
    end if;
  end if;
  return null;
end
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_on_visit() OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_on_visit_child(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_on_visit_child() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ids   uuid[] := '{}';
  v_id    uuid;
  v_visit record;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    v_ids := array_append(v_ids, old.visit_id);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    v_ids := array_append(v_ids, new.visit_id);
  end if;
  foreach v_id in array v_ids loop
    for v_visit in
      select v.rep_hr_id, v.visit_date from public.phoenix_crm_visits v where v.id = v_id
    loop
      perform public.phoenix_crm_rep_entry_days_touch(v_visit.rep_hr_id, v_visit.visit_date);
    end loop;
  end loop;
  return null;
end
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_on_visit_child() OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_rebuild(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_rebuild() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rows integer;
begin
  delete from public.phoenix_crm_rep_entry_days_cache where true;
  insert into public.phoenix_crm_rep_entry_days_cache (hr_key, entry_day, agent_crm_id)
  select c.hr_key, c.entry_day, c.agent_crm_id
    from public.phoenix_crm_rep_entry_days_calc() c
  on conflict (hr_key, entry_day) do update
    set agent_crm_id = excluded.agent_crm_id,
        refreshed_at = now();
  select count(*) into v_rows from public.phoenix_crm_rep_entry_days_cache;
  return v_rows;
end
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_rebuild() OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_reconcile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_reconcile() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_diff integer;
begin
  with truth as (
    select c.hr_key, c.entry_day, c.agent_crm_id from public.phoenix_crm_rep_entry_days_calc() c
  ), cached as (
    select k.hr_key, k.entry_day, k.agent_crm_id from public.phoenix_crm_rep_entry_days_cache k
  )
  select count(*) into v_diff from (
    (select t.hr_key, t.entry_day, t.agent_crm_id from truth t
     except
     select c.hr_key, c.entry_day, c.agent_crm_id from cached c)
    union all
    (select c.hr_key, c.entry_day, c.agent_crm_id from cached c
     except
     select t.hr_key, t.entry_day, t.agent_crm_id from truth t)
  ) d;
  if v_diff > 0 then
    perform public.phoenix_crm_rep_entry_days_rebuild();
    raise warning 'phoenix_crm_rep_entry_days cache differed from phoenix_crm_rep_entry_days_calc() by % row(s) and was rebuilt', v_diff;
  end if;
  return v_diff;
end
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_reconcile() OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_reconcile_run(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_reconcile_run() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_diff integer;
begin
  v_diff := public.phoenix_crm_rep_entry_days_reconcile();

  perform public.phx_record_job_heartbeat(
    'phoenix-crm-rep-entry-days-reconcile',
    'success',
    case
      when v_diff > 0 then format('rebuilt: %s row(s) were out of step with _calc()', v_diff)
      else 'in step: 0 differences against _calc()'
    end
  );

  return v_diff;
end
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_reconcile_run() OWNER TO postgres;

--
-- Name: phoenix_crm_rep_entry_days_touch(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_entry_days_touch(p_hr_id text, p_day date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_key text := lower(btrim(p_hr_id));
begin
  -- A visit a manager entered carries no rep_hr_id, and _calc() never counts one: nothing to do.
  if v_key is null or v_key = '' or p_day is null then
    return;
  end if;
  delete from public.phoenix_crm_rep_entry_days_cache
   where hr_key = v_key and entry_day = p_day;
  insert into public.phoenix_crm_rep_entry_days_cache (hr_key, entry_day, agent_crm_id)
  select c.hr_key, c.entry_day, c.agent_crm_id
    from public.phoenix_crm_rep_entry_days_calc(v_key, p_day) c
  on conflict (hr_key, entry_day) do update
    set agent_crm_id = excluded.agent_crm_id,
        refreshed_at = now();
end
$$;

ALTER FUNCTION public.phoenix_crm_rep_entry_days_touch(p_hr_id text, p_day date) OWNER TO postgres;

--
-- Name: phoenix_crm_rep_exception_set(text[], text, text, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_rep_exception_set(p_seats text[], p_rep text, p_action text, p_from date, p_until date, p_actor text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rep text;
begin
  select e.hr_id into v_rep
  from public.employees e
  where upper(btrim(e.hr_id)) = upper(btrim(p_rep))
  limit 1;
  if v_rep is null then
    raise exception 'phoenix_crm:rep_exception_no_rep';
  end if;

  if p_action not in ('open', 'close') then
    raise exception 'phoenix_crm:rep_exception_action';
  end if;

  -- Written with explicit IS NULL, so a missing date can never pass a comparison.
  if p_action = 'open' and (
    p_from is null
    or p_until is null
    or p_from > p_until
    or p_until < (now() at time zone 'Africa/Cairo')::date
  ) then
    raise exception 'phoenix_crm:rep_exception_dates';
  end if;

  if p_action = 'open' and coalesce(array_length(p_seats, 1), 0) = 0 then
    raise exception 'phoenix_crm:rep_exception_no_rep';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('phoenix_crm_rep_exception:' || v_rep, 0));

  update public.phoenix_crm_offplan_exemptions e
  set ended_at = now(), ended_by_hr_id = p_actor
  where e.rep_hr_id = v_rep
    and e.ended_at is null;

  if p_action = 'open' then
    insert into public.phoenix_crm_offplan_exemptions (seat_id, rep_hr_id, valid_from, valid_until, label, note, granted_by_hr_id)
    select distinct seat.id, v_rep, p_from, p_until, 'Rep exception', 'Set on the Rep Exceptions page.', p_actor
    from unnest(p_seats) as seat(id);
  end if;
end;
$$;

ALTER FUNCTION public.phoenix_crm_rep_exception_set(p_seats text[], p_rep text, p_action text, p_from date, p_until date, p_actor text) OWNER TO postgres;

--
-- Name: phoenix_crm_report_brick_coverage(text[], date, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_report_brick_coverage(p_seat_ids text[], p_from date, p_to date, p_include_test boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with listed as (
    select c.id, c.seat_id, c.list_type, place.brick_id, place.brick_name, place.area_code, place.area_name
    from public.phoenix_crm_customers c
    left join lateral (
      select p.brick_id, p.brick_name, p.area_code, p.area_name
      from public.phoenix_crm_places p
      where p.customer_id = c.id
        and p.status = 'active'
        and (p_include_test or not p.is_test)
      order by p.captured_at asc, p.id asc
      limit 1
    ) place on true
    where c.seat_id = any (p_seat_ids)
      and (p_include_test or not c.is_test)
      and c.validated_at is not null
      and c.status = 'active'
  ),
  window_visits as (
    select v.customer_id, count(*)::integer as visits
    from public.phoenix_crm_countable_visits_with_history v
    where v.seat_id = any (p_seat_ids)
      and v.visit_date >= p_from
      and v.visit_date <= p_to
      and (p_include_test or not v.is_test)
    group by v.customer_id
  ),
  scored as (
    select l.seat_id, l.brick_id, l.brick_name, l.area_code, l.area_name, l.list_type,
           coalesce(wv.visits, 0) as visits
    from listed l
    left join window_visits wv on wv.customer_id = l.id
  )
  select coalesce(jsonb_agg(to_jsonb(r) order by r.seat_id, r.area_code nulls last, r.brick_name nulls last), '[]'::jsonb)
  from (
    select
      s.seat_id,
      s.brick_id,
      s.brick_name,
      s.area_code,
      s.area_name,
      count(*)::integer as customers,
      (count(*) filter (where s.list_type = 'AM'))::integer as am,
      (count(*) filter (where s.list_type = 'PM'))::integer as pm,
      (count(*) filter (where s.visits > 0))::integer as visited,
      (count(*) filter (where s.list_type = 'AM' and s.visits > 0))::integer as am_visited,
      (count(*) filter (where s.list_type = 'PM' and s.visits > 0))::integer as pm_visited,
      coalesce(sum(s.visits), 0)::integer as visits
    from scored s
    group by s.seat_id, s.brick_id, s.brick_name, s.area_code, s.area_name
  ) r;
$$;

ALTER FUNCTION public.phoenix_crm_report_brick_coverage(p_seat_ids text[], p_from date, p_to date, p_include_test boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_report_coverage(text[], date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_report_coverage(p_seat_ids text[], p_month_start date, p_include_test boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with bounds as (
    select
      date_trunc('month', p_month_start::timestamp)::date as month_start,
      (date_trunc('month', p_month_start::timestamp) + interval '1 month')::date as next_month
  ),
  targets as (
    select s.grade_targets from public.phoenix_crm_settings s where s.id = 1
  ),
  listed as (
    select c.id, c.seat_id, c.list_type, c.grade
    from public.phoenix_crm_customers c
    cross join bounds b
    where c.seat_id = any (p_seat_ids)
      and (p_include_test or not c.is_test)
      and c.validated_at is not null
      and (c.status = 'active' or c.status_changed_at >= (b.month_start::timestamp at time zone 'Africa/Cairo'))
  ),
  month_visits as (
    select v.customer_id, count(*)::integer as visits
    from public.phoenix_crm_countable_visits_with_history v
    cross join bounds b
    join public.phoenix_crm_customers c on c.id = v.customer_id and c.validated_at is not null
    where v.seat_id = any (p_seat_ids)
      and v.visit_date >= b.month_start
      and v.visit_date < b.next_month
      and (p_include_test or not v.is_test)
    group by v.customer_id
  ),
  scored as (
    select
      l.seat_id,
      l.list_type,
      coalesce(mv.visits, 0) as visits,
      case when l.grade is null then null else nullif(t.grade_targets -> l.list_type ->> l.grade, '')::integer end as target
    from listed l
    left join targets t on true
    left join month_visits mv on mv.customer_id = l.id
  )
  select coalesce(jsonb_agg(to_jsonb(r) order by r.seat_id, r.list_type), '[]'::jsonb)
  from (
    select
      s.seat_id,
      s.list_type,
      count(*)::integer as customers,
      (count(*) filter (where s.visits > 0))::integer as covered,
      (count(*) filter (where s.target is not null))::integer as with_target,
      (count(*) filter (where s.target is not null and s.visits = s.target))::integer as on_target,
      (count(*) filter (where s.target is not null and s.visits < s.target))::integer as under,
      (count(*) filter (where s.target is not null and s.visits > s.target))::integer as over,
      coalesce(sum(s.visits), 0)::integer as visits
    from scored s
    group by s.seat_id, s.list_type
  ) r;
$$;

ALTER FUNCTION public.phoenix_crm_report_coverage(p_seat_ids text[], p_month_start date, p_include_test boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_report_manager_visits(text[], date, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_report_manager_visits(p_hr_ids text[], p_from date, p_to date, p_include_test boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with people as (
    select distinct upper(trim(x.hr_id)) as hr_id
    from unnest(p_hr_ids) as x (hr_id)
    where nullif(trim(x.hr_id), '') is not null
  ),
  joined as (
    select pe.hr_id, 'manager'::text as role_on_visit, v.visit_date, v.seat_id, v.rep_hr_id, v.kind, v.list_type
    from people pe
    join public.phoenix_crm_countable_visits_with_history v on v.manager_hr_id = pe.hr_id
    join public.phoenix_crm_customers c on c.id = v.customer_id and c.validated_at is not null
    where v.visit_date between p_from and p_to
      and v.kind in ('double', 'chain')
      and (p_include_test or not v.is_test)
    union all
    select pe.hr_id, 'senior'::text, v.visit_date, v.seat_id, v.rep_hr_id, v.kind, v.list_type
    from people pe
    join public.phoenix_crm_countable_visits_with_history v on v.senior_hr_id = pe.hr_id
    join public.phoenix_crm_customers c on c.id = v.customer_id and c.validated_at is not null
    where v.visit_date between p_from and p_to
      and (p_include_test or not v.is_test)
    union all
    -- The product manager, in his own column. Both kinds he can be on: 'product_manager' (the rep
    -- ticked one person under "Double visit" and it was him) and 'chain' (he was the second person on
    -- a chain). No `kind` filter is needed — product_manager_hr_id is set on those two kinds alone,
    -- and the constraint phoenix_crm_visits_participants is what guarantees it.
    select pe.hr_id, 'product_manager'::text, v.visit_date, v.seat_id, v.rep_hr_id, v.kind, v.list_type
    from people pe
    join public.phoenix_crm_countable_visits_with_history v on v.product_manager_hr_id = pe.hr_id
    join public.phoenix_crm_customers c on c.id = v.customer_id and c.validated_at is not null
    where v.visit_date between p_from and p_to
      and (p_include_test or not v.is_test)
  )
  select coalesce(jsonb_agg(to_jsonb(t) order by t.hr_id, t.visit_date, t.seat_id), '[]'::jsonb)
  from (
    select
      j.hr_id,
      j.role_on_visit,
      j.visit_date,
      j.seat_id,
      j.rep_hr_id,
      (count(*) filter (where j.kind = 'double'))::integer as double_visits,
      (count(*) filter (where j.kind = 'chain'))::integer as chain_visits,
      -- Never added into double_visits: that figure is kind = 'double' on every board and district
      -- managers are judged on it.
      (count(*) filter (where j.kind = 'product_manager'))::integer as product_manager_visits,
      (count(*) filter (where j.list_type = 'AM'))::integer as am_visits,
      (count(*) filter (where j.list_type = 'PM'))::integer as pm_visits
    from joined j
    group by j.hr_id, j.role_on_visit, j.visit_date, j.seat_id, j.rep_hr_id
  ) t;
$$;

ALTER FUNCTION public.phoenix_crm_report_manager_visits(p_hr_ids text[], p_from date, p_to date, p_include_test boolean) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_report_manager_visits(p_hr_ids text[], p_from date, p_to date, p_include_test boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_report_manager_visits(p_hr_ids text[], p_from date, p_to date, p_include_test boolean) IS 'Every visit each named person was on, by the place they stood on it: manager_hr_id (a double or a chain visit), senior_hr_id (the senior manager of a chain), product_manager_hr_id (the line''s product manager, on the ''product_manager'' kind or as the second person on a chain). One row per person, role, day, territory and rep. `double_visits` counts kind = ''double'' and nothing else, because that figure is what managers are measured on; a product manager''s visits are `product_manager_visits` and are never folded into it.';

--
-- Name: phoenix_crm_report_plan_vs_actual(text[], date, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_report_plan_vs_actual(p_seat_ids text[], p_from date, p_to date, p_include_test boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with plan_days as (
    select distinct pl.id as plan_id, i.plan_date
    from public.phoenix_crm_plans pl
    join public.phoenix_crm_plan_items i on i.plan_id = pl.id
    where pl.seat_id = any (p_seat_ids)
      and pl.week_start between p_from - 6 and p_to
      and i.plan_date between p_from and p_to
      and (p_include_test or not pl.is_test)
  ),
  -- WAS THIS DAY ON A SENT PLAN? The plan's latest event by the end of that Cairo day — the same
  -- "before the next Cairo midnight" boundary as before, and the same test phoenix_crm_save_visit
  -- applies at the door (v_on_sent_plan) and plan-rules.ts applies on every screen (isPlanDaySent).
  --
  -- A draft is the rep's own to edit, so it is never authority; a week returned WHOLE is back with
  -- him too, so it is not authority either — which is what the old `in (..., 'returned')` got wrong.
  -- The one exception is a ONE-DAY return (owner, 2026-10-02, "Still planned"): that week still
  -- stands on every OTHER day exactly as it stood when the day was returned, until an acknowledged
  -- edit request opens the whole week to him, because a day he can change is never authority.
  --
  -- `cross join lateral … limit 1` rather than a scalar subquery because the branch needs THREE
  -- fields of that one latest event — its status, its details and its own time — and asking for them
  -- in three subqueries would let the three read different events on a tie.
  sent_days as (
    select d.plan_id, d.plan_date
    from plan_days d
    cross join lateral (
      select e.to_status, e.details, e.created_at
      from public.phoenix_crm_plan_events e
      where e.plan_id = d.plan_id
        and e.to_status is not null
        and e.created_at < ((d.plan_date + 1)::timestamp at time zone 'Africa/Cairo')
      order by e.created_at desc, e.id desc
      limit 1
    ) latest
    where latest.to_status in ('submitted', 'approved')
       or (
         latest.to_status = 'returned'
         and nullif(latest.details ->> 'returned_day', '') is not null
         and nullif(latest.details ->> 'returned_day', '')::date <> d.plan_date
         and not exists (
           select 1
           from public.phoenix_crm_plan_edit_requests r
           where r.plan_id = d.plan_id
             and r.hr_acknowledged_at > latest.created_at
             and r.hr_acknowledged_at < ((d.plan_date + 1)::timestamp at time zone 'Africa/Cairo')
         )
       )
  ),
  planned as (
    select pl.seat_id, pl.is_test, i.plan_date, i.customer_id, i.list_type
    from sent_days s
    join public.phoenix_crm_plans pl on pl.id = s.plan_id
    join public.phoenix_crm_plan_items i on i.plan_id = s.plan_id and i.plan_date = s.plan_date
    -- The DENOMINATOR: planning a customer who is not validated yet is never held against the rep.
    join public.phoenix_crm_customers c on c.id = i.customer_id and c.validated_at is not null
    -- 🔴 WHICH SEAT HELD HIM AT THE END OF THAT CAIRO DAY. The newest move at or before the day
    -- decides, so a customer who moved away and later moved back is counted on each seat exactly for
    -- the days he was there — a `max(moved_at)` would have excluded the days after his return. No move
    -- row at all means he never left, which is every customer until one is moved.
    left join lateral (
      select m.to_seat_id
      from public.phoenix_crm_customer_moves m
      where m.customer_id = i.customer_id
        and (m.moved_at at time zone 'Africa/Cairo')::date <= i.plan_date
      order by m.moved_at desc, m.id desc
      limit 1
    ) held_by on true
    -- 🔴 AND NEITHER IS A CUSTOMER WHO HAS LEFT THE LIST. phoenix_crm_save_visit raises
    -- `phoenix_crm:customer_dropped` for him, so a day planned after the drop is a visit the rep is
    -- REFUSED and was then counted as having missed. The day of the drop itself stays in — he was on
    -- the list for part of it — and the Cairo day is read from the instant, because
    -- `status_changed_at::date` would be the UTC one and would move every drop made in the first two
    -- or three hours of a Cairo day into the day before.
    where (
      c.status <> 'dropped'
      or i.plan_date <= ((c.status_changed_at at time zone 'Africa/Cairo')::date)
    )
      -- A day after he was handed to another rep is the same refusal in the other shape: this rep
      -- cannot visit him, so the day is out of HIS denominator and sits in the new rep's.
      and (held_by.to_seat_id is null or held_by.to_seat_id = pl.seat_id)
  ),
  -- The base table on purpose, not the countable view: this report's job is to SHOW the manager the
  -- off-plan work, and a visit that has vanished from it cannot be approved by anyone. What the
  -- decision changes is the two columns beside it.
  visited as (
    select v.seat_id, v.is_test, v.visit_date, v.customer_id, v.list_type, v.is_unplanned, u.status as unplanned_status,
      r.review_status as recording_status
    from public.phoenix_crm_visits v
    -- The NUMERATOR: the same filter, so both sides move together.
    join public.phoenix_crm_customers c on c.id = v.customer_id and c.validated_at is not null
    left join public.phoenix_crm_unplanned_visits u on u.visit_id = v.id
    -- A recorded visit waits for the Administrator (owner, 2026-10-16).
    left join public.phoenix_crm_visit_recordings r on r.visit_id = v.id
    where v.seat_id = any (p_seat_ids)
      and v.visit_date between p_from and p_to
      and (p_include_test or not v.is_test)
  ),
  joined as (
    select
      coalesce(pd.seat_id, vd.seat_id) as seat_id,
      coalesce(pd.plan_date, vd.visit_date) as day,
      coalesce(pd.list_type, vd.list_type) as list_type,
      pd.customer_id is not null as is_planned,
      vd.customer_id is not null as is_visited,
      coalesce(vd.is_unplanned, false) as is_unplanned,
      vd.unplanned_status,
      vd.recording_status
    from planned pd
    full join visited vd
      on vd.seat_id = pd.seat_id
     and vd.is_test = pd.is_test
     and vd.visit_date = pd.plan_date
     and vd.customer_id = pd.customer_id
  )
  select coalesce(jsonb_agg(to_jsonb(t) order by t.seat_id, t.day, t.list_type), '[]'::jsonb)
  from (
    select
      j.seat_id,
      j.day,
      j.list_type,
      (count(*) filter (where j.is_planned))::integer as planned,
      -- A visit the rep did not plan is not a plan he kept, however the plan was edited afterwards.
      (count(*) filter (where j.is_planned and j.is_visited and not j.is_unplanned and coalesce(j.recording_status, 'approved') = 'approved'))::integer as visited_planned,
      -- Beside it, never silently a miss: he was there, and it is waiting on somebody.
      (count(*) filter (where j.is_planned and j.is_visited and (
        (j.is_unplanned and j.unplanned_status in ('admin_pending', 'manager_pending', 'sfe_pending'))
        or (not j.is_unplanned and j.recording_status = 'pending')
      )))::integer as planned_waiting,
      (count(*) filter (where j.is_planned and not j.is_visited))::integer as missed,
      (count(*) filter (where j.is_visited and not j.is_planned))::integer as unplanned,
      (count(*) filter (where j.is_visited and not j.is_planned and (
        j.unplanned_status in ('admin_pending', 'manager_pending', 'sfe_pending')
        or (j.unplanned_status is null and j.recording_status = 'pending')
      )))::integer as unplanned_waiting,
      (count(*) filter (where j.is_visited and not j.is_planned and (j.unplanned_status = 'refused' or j.recording_status = 'refused')))::integer as unplanned_refused
    from joined j
    group by j.seat_id, j.day, j.list_type
  ) t;
$$;

ALTER FUNCTION public.phoenix_crm_report_plan_vs_actual(p_seat_ids text[], p_from date, p_to date, p_include_test boolean) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_report_plan_vs_actual(p_seat_ids text[], p_from date, p_to date, p_include_test boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_report_plan_vs_actual(p_seat_ids text[], p_from date, p_to date, p_include_test boolean) IS 'Plan versus actual per seat, day and list: a day counts only when it stood on a sent plan, a customer counts only while he is validated, on the list and on THAT seat, and an off-plan visit is shown beside the miss rather than inside it.';

--
-- Name: phoenix_crm_report_visits_by_day(text[], date, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_report_visits_by_day(p_seat_ids text[], p_from date, p_to date, p_include_test boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with counted as (
    select
      v.seat_id,
      v.rep_hr_id,
      (case when v.rep_hr_id is null then v.manager_hr_id end) as manager_hr_id,
      v.visit_date,
      v.list_type,
      count(*)::integer as visits,
      (count(*) filter (where v.kind = 'double'))::integer as double_visits,
      (count(*) filter (where v.kind = 'chain'))::integer as chain_visits,
      (count(*) filter (where v.location_flag = 'far'))::integer as far_visits,
      (count(*) filter (where v.is_test))::integer as test_visits
    from public.phoenix_crm_countable_visits_with_history v
    join public.phoenix_crm_customers c on c.id = v.customer_id and c.validated_at is not null
    where v.seat_id = any (p_seat_ids)
      and v.visit_date between p_from and p_to
      and (p_include_test or not v.is_test)
    group by v.seat_id, v.rep_hr_id, (case when v.rep_hr_id is null then v.manager_hr_id end), v.visit_date, v.list_type
  ),
  waiting as (
    select
      v.seat_id,
      v.rep_hr_id,
      (case when v.rep_hr_id is null then v.manager_hr_id end) as manager_hr_id,
      v.visit_date,
      v.list_type,
      count(*)::integer as unplanned_waiting
    from public.phoenix_crm_visits v
    join public.phoenix_crm_customers c on c.id = v.customer_id and c.validated_at is not null
    left join public.phoenix_crm_unplanned_visits u on u.visit_id = v.id
    left join public.phoenix_crm_visit_recordings r on r.visit_id = v.id
    where v.seat_id = any (p_seat_ids)
      and v.visit_date between p_from and p_to
      and (p_include_test or not v.is_test)
      and (
        u.status in ('admin_pending', 'manager_pending', 'sfe_pending')
        or (r.review_status = 'pending' and (u.status is null or u.status <> 'refused'))
      )
    group by v.seat_id, v.rep_hr_id, (case when v.rep_hr_id is null then v.manager_hr_id end), v.visit_date, v.list_type
  )
  select coalesce(jsonb_agg(to_jsonb(t) order by t.seat_id, t.visit_date, t.list_type, t.rep_hr_id, t.manager_hr_id), '[]'::jsonb)
  from (
    select
      coalesce(c.seat_id, w.seat_id) as seat_id,
      coalesce(c.rep_hr_id, w.rep_hr_id) as rep_hr_id,
      coalesce(c.manager_hr_id, w.manager_hr_id) as manager_hr_id,
      coalesce(c.visit_date, w.visit_date) as visit_date,
      coalesce(c.list_type, w.list_type) as list_type,
      coalesce(c.visits, 0) as visits,
      coalesce(c.double_visits, 0) as double_visits,
      coalesce(c.chain_visits, 0) as chain_visits,
      coalesce(c.far_visits, 0) as far_visits,
      coalesce(c.test_visits, 0) as test_visits,
      coalesce(w.unplanned_waiting, 0) as unplanned_waiting
    from counted c
    full join waiting w
      on w.seat_id = c.seat_id
     and w.visit_date = c.visit_date
     and w.list_type = c.list_type
     and w.rep_hr_id is not distinct from c.rep_hr_id
     and w.manager_hr_id is not distinct from c.manager_hr_id
  ) t;
$$;

ALTER FUNCTION public.phoenix_crm_report_visits_by_day(p_seat_ids text[], p_from date, p_to date, p_include_test boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_request_manager_customer_removal(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_request_manager_customer_removal(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'manager_customer_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_approver text := upper(nullif(trim(coalesce(p ->> 'approver_hr_id', '')), ''));
  v_second text := upper(nullif(trim(coalesce(p ->> 'second_approver_hr_id', '')), ''));
  v_reason text := nullif(regexp_replace(trim(coalesce(p ->> 'reason', '')), '\s+', ' ', 'g'), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_row public.phoenix_crm_manager_customers%rowtype;
begin
  if v_id is null or v_actor is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_reason is null or char_length(v_reason) < 3 or char_length(v_reason) > 500 then
    raise exception 'phoenix_crm:note_required';
  end if;
  if v_approver is null then
    raise exception 'phoenix_crm:manager_plan_no_approver';
  end if;
  if v_second is not null and v_second = v_approver then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select m.* into v_row from public.phoenix_crm_manager_customers m where m.id = v_id for update;
  if not found or v_row.is_test <> v_is_test then
    raise exception 'phoenix_crm:manager_customer_not_found';
  end if;
  if v_approver = v_row.manager_hr_id or v_second = v_row.manager_hr_id then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_row.status <> 'active' then
    raise exception 'phoenix_crm:manager_customer_not_active';
  end if;

  update public.phoenix_crm_manager_customers m
  set status = 'removal_pending',
      removal_reason = v_reason,
      removal_requested_at = now(),
      removal_requested_by_hr_id = v_actor,
      removal_approver_hr_id = v_approver,
      removal_second_approver_hr_id = v_second,
      removal_first_decided_at = null,
      removal_first_decided_by_hr_id = null,
      removal_first_decided_role = null,
      removal_first_decision_note = null,
      removal_decided_at = null,
      removal_decided_by_hr_id = null,
      removal_decided_role = null,
      removal_decision_note = null,
      updated_at = now()
  where m.id = v_row.id
  returning m.* into v_row;

  return jsonb_build_object(
    'manager_customer_id', v_row.id,
    'manager_hr_id', v_row.manager_hr_id,
    'name', v_row.name,
    'status', v_row.status,
    'approver_hr_id', v_row.removal_approver_hr_id,
    'second_approver_hr_id', v_row.removal_second_approver_hr_id,
    'is_test', v_row.is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_request_manager_customer_removal(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_restamp_visit_locations(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_restamp_visit_locations(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_items jsonb := coalesce(p -> 'items', '[]'::jsonb);
  v_count integer;
begin
  if v_seat is null or v_actor is null or v_customer_id is null or jsonb_typeof(v_items) is distinct from 'array' then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if exists (
    select 1
    from jsonb_to_recordset(v_items) as x (visit_id uuid, place_id uuid, distance_meters integer, location_flag text)
    where x.visit_id is null or x.location_flag not in ('ok', 'far', 'weak_gps', 'no_place')
      or (x.distance_meters is not null and x.distance_meters < 0)
  ) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  with changed as (
    update public.phoenix_crm_visits v
    set place_id = x.place_id,
        distance_meters = x.distance_meters,
        location_flag = x.location_flag
    from jsonb_to_recordset(v_items) as x (visit_id uuid, place_id uuid, distance_meters integer, location_flag text)
    where v.id = x.visit_id
      and v.customer_id = v_customer_id
      and v.seat_id = v_seat
      and v.is_test = v_is_test
      and (x.place_id is null or exists (
        select 1 from public.phoenix_crm_places pl where pl.id = x.place_id and pl.customer_id = v_customer_id
      ))
    returning v.id
  )
  select count(*)::integer into v_count from changed;

  if v_count > 0 then
    insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
    values (v_seat, v_customer_id, 'visit_locations_restamped', v_actor, jsonb_build_object('visits', v_count), v_is_test);
  end if;

  return jsonb_build_object('customer_id', v_customer_id, 'visits', v_count);
end;
$$;

ALTER FUNCTION public.phoenix_crm_restamp_visit_locations(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_restore_shared_place(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_restore_shared_place(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'shared_place_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  -- Optional, as every admin note on this page is since 2026-10-15 ("admin comment is optional").
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_venue public.phoenix_crm_shared_places%rowtype;
  v_retired_at timestamptz;
  v_seated record;
  v_places integer := 0;
  v_validated jsonb := '[]'::jsonb;
  v_still_waiting jsonb := '[]'::jsonb;
begin
  if v_id is null or v_actor is null or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select s.* into v_venue from public.phoenix_crm_shared_places s where s.id = v_id;
  if not found then
    raise exception 'phoenix_crm:shared_place_not_found';
  end if;
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_venue.seat_id));
  select s.* into v_venue from public.phoenix_crm_shared_places s where s.id = v_id for update;

  -- Only a REJECTED venue can be taken back, and only while it is still in the state the rejection
  -- left it in — the same pair of tests `phoenix_crm_restore_validation` makes about a place.
  if v_venue.status <> 'retired' or v_venue.retired_at is null then
    raise exception 'phoenix_crm:shared_place_not_retired';
  end if;
  v_retired_at := v_venue.retired_at;

  update public.phoenix_crm_shared_places
  set status = 'active',
      decided_at = now(),
      decided_by_hr_id = v_actor,
      decision_note = v_note,
      refusal_reason = null,
      retired_at = null,
      retired_by_hr_id = null,
      updated_at = now()
  where id = v_id;

  insert into public.phoenix_crm_list_events (seat_id, event_type, actor_hr_id, details, is_test)
  values (
    v_venue.seat_id, 'shared_place_restored', v_actor,
    jsonb_build_object(
      'shared_place_id', v_id, 'shared_place_name', v_venue.name, 'note', v_note,
      'rejected_by_hr_id', v_venue.retired_by_hr_id, 'rejected_at', v_retired_at,
      'rejection_note', v_venue.decision_note, 'refusal_reason', v_venue.refusal_reason
    ),
    v_venue.is_test
  );

  -- Exactly the places that rejection retired — see the header on why this is `retired_at`.
  for v_seated in
    select pl.id as place_id, pl.customer_id, pl.label, pl.schedule_check, pl.is_test,
           c.name as customer_name, c.status as customer_status
    from public.phoenix_crm_places pl
    join public.phoenix_crm_customers c on c.id = pl.customer_id
    where pl.shared_place_id = v_id
      and pl.status = 'retired'
      and pl.retired_at = v_retired_at
    order by pl.created_at
  loop
    update public.phoenix_crm_places pl
    set status = 'active', retired_at = null, retired_by_hr_id = null, updated_at = now()
    where pl.id = v_seated.place_id;
    v_places := v_places + 1;

    insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
    values (
      v_venue.seat_id, v_seated.customer_id, v_seated.place_id, 'place_restored', v_actor,
      jsonb_build_object(
        'reason', v_note, 'label', v_seated.label, 'why', 'shared_place_restored',
        'shared_place_id', v_id, 'rejected_at', v_retired_at
      ),
      v_seated.is_test
    );

    -- 🔴 THE SAME THREE HOLDS APPROVING A HELD VENUE KEEPS (owner, 2026-10-14): a building with no
    -- timetable on file, a timetable read as another name or as no schedule, and a customer whose own
    -- location is waiting on a validation review all STAY pending. That rule is lifted verbatim from
    -- the approve branch, never widened — bringing the building back must not confirm a doctor the
    -- building itself cannot answer for.
    if v_seated.customer_status = 'pending' then
      if v_venue.schedule_photo_path is null
        or (v_seated.schedule_check ->> 'verdict') in ('other_name', 'no_schedule')
        or exists (
          select 1 from public.phoenix_crm_validation_reviews r
          where r.customer_id = v_seated.customer_id and r.status = 'pending'
        ) then
        v_still_waiting := v_still_waiting || jsonb_build_array(jsonb_build_object(
          'customer_id', v_seated.customer_id, 'customer_name', v_seated.customer_name
        ));
        continue;
      end if;

      update public.phoenix_crm_customers c
      set status = 'active', validated_at = now(), validated_by_hr_id = v_actor,
          status_changed_at = now(), updated_at = now()
      where c.id = v_seated.customer_id and c.status = 'pending';
      if found then
        insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
        values (
          v_venue.seat_id, v_seated.customer_id, v_seated.place_id, 'customer_validated', v_actor,
          jsonb_build_object('why', 'shared_place_restored', 'shared_place_id', v_id, 'shared_place_name', v_venue.name),
          v_seated.is_test
        );
        v_validated := v_validated || jsonb_build_array(jsonb_build_object(
          'customer_id', v_seated.customer_id, 'customer_name', v_seated.customer_name, 'place_id', v_seated.place_id
        ));
      end if;
    end if;
  end loop;

  -- 🔴 THE WAIT IS CLEARED FOR WHOEVER IS BACK IN USE, AND KEPT FOR WHOEVER IS NOT. `reopened_at` is
  -- what puts a customer first in his rep's To validate order; a customer this restore confirmed has
  -- nothing left to capture, so leaving the stamp on would hold him at the top of a list he is no
  -- longer on. A customer still pending keeps it, because he really is still waiting.
  update public.phoenix_crm_customers c
  set reopened_at = null, updated_at = now()
  where c.status = 'active'
    and c.reopened_at is not null
    and exists (
      select 1 from public.phoenix_crm_places pl
      where pl.customer_id = c.id and pl.shared_place_id = v_id and pl.status = 'active'
    );

  return jsonb_build_object(
    'shared_place_id', v_id,
    'name', v_venue.name,
    'seat_id', v_venue.seat_id,
    'is_test', v_venue.is_test,
    'status', 'active',
    'places_restored', v_places,
    'validated', v_validated,
    'still_waiting', v_still_waiting
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_restore_shared_place(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_restore_validation(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_restore_validation(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := nullif(p ->> 'review_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  -- The Super Admin's own spelling of the customer's name (owner, 2026-11-10: "Both"). The service has
  -- already refused everybody else and checked the three names; null means "keep the name as it stands".
  v_corrected text := nullif(left(regexp_replace(trim(coalesce(p ->> 'name', '')), '\s+', ' ', 'g'), 200), '');
  v_review public.phoenix_crm_validation_reviews%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_place public.phoenix_crm_places%rowtype;
  v_validated boolean := false;
  v_renamed boolean := false;
begin
  -- 🔴 THE NOTE IS OPTIONAL SINCE 2026-10-15 (owner: "admin comment is optional"). It used to raise
  -- bad_input on a null note; the four events and the review row this writes all accept one, and
  -- `who` and `when` are on the record whether or not he writes a word about it.
  if v_id is null or v_actor is null or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select r.* into v_review from public.phoenix_crm_validation_reviews r where r.id = v_id;
  if not found then
    raise exception 'phoenix_crm:review_not_found';
  end if;
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_review.seat_id));
  select r.* into v_review from public.phoenix_crm_validation_reviews r where r.id = v_id for update;
  if v_review.status <> 'rejected' then
    raise exception 'phoenix_crm:review_not_rejected';
  end if;

  select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_review.customer_id for update;
  select pl.* into v_place from public.phoenix_crm_places pl where pl.id = v_review.place_id for update;

  -- The place must still be in the state the rejection left it in. A moved or already-active place is
  -- a different story and is not undone here.
  if v_place.status <> 'retired' then
    raise exception 'phoenix_crm:place_not_retired';
  end if;

  -- The corrected name first, so everything below reads the customer as he now is. The rep's own rename:
  -- the name key, the contact's name row and the history move exactly as when he saves a name himself, and
  -- a second customer of the same name is the administrator's to judge, never a refusal.
  if v_corrected is not null and v_corrected is distinct from v_customer.name and v_customer.status <> 'dropped' then
    perform public.phoenix_crm_rename_customer(jsonb_build_object(
      'seat_id', v_customer.seat_id,
      'actor_hr_id', v_actor,
      'is_test', v_customer.is_test,
      'customer_id', v_customer.id,
      'name', v_corrected,
      'speciality', v_customer.speciality,
      'allow_same_name', true
    ));
    -- A full name still waiting on "PM full names to check" is answered by the name he just wrote.
    update public.phoenix_crm_customers c
    set full_name_held = null,
        full_name_held_at = null,
        full_name_held_by_hr_id = null,
        full_name_held_score = null,
        full_name_held_board = null,
        updated_at = now()
    where c.id = v_customer.id and c.full_name_held is not null;
    select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_customer.id;
    v_renamed := true;
  end if;

  update public.phoenix_crm_places pl
  set status = 'active', retired_at = null, retired_by_hr_id = null, updated_at = now()
  where pl.id = v_place.id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
  values (
    v_review.seat_id, v_customer.id, v_place.id, 'place_restored', v_actor,
    jsonb_build_object('reason', v_note, 'label', v_place.label, 'why', 'validation_restored', 'review_id', v_id,
      'rejected_by_hr_id', v_review.decided_by_hr_id, 'rejection_note', v_review.decision_note),
    v_review.is_test
  );

  -- The rejection sent him back to To validate when this was his only place; the restore undoes that,
  -- in the REP's own name — he validated it, and a reversal does not take that away from him.
  if v_customer.status = 'pending' then
    update public.phoenix_crm_customers c
    set status = 'active',
        validated_at = now(),
        validated_by_hr_id = v_review.created_by_hr_id,
        dropped_reason = null,
        dropped_note = null,
        status_changed_at = now(),
        updated_at = now()
    where c.id = v_customer.id;
    v_validated := true;
  end if;

  -- One review row per place (the UNIQUE index), so this is an UPDATE. What it was before is kept in
  -- `google`, beside the events, rather than being thrown away.
  update public.phoenix_crm_validation_reviews r
  set status = 'approved',
      decided_by_hr_id = v_actor,
      decided_at = now(),
      decision_note = v_note,
      google = coalesce(r.google, '{}'::jsonb) || jsonb_build_object(
        'restored', true,
        'rejected_by_hr_id', v_review.decided_by_hr_id,
        'rejected_at', v_review.decided_at,
        'rejection_note', v_review.decision_note
      )
  where r.id = v_id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
  values (
    v_review.seat_id, v_customer.id, v_place.id, 'validation_review_approved', v_actor,
    jsonb_build_object('review_id', v_id, 'note', v_note, 'validated', v_validated, 'why', 'restored_after_rejection',
      'renamed', v_renamed),
    v_review.is_test
  );

  return jsonb_build_object(
    'review_id', v_id,
    'status', 'approved',
    'seat_id', v_review.seat_id,
    'customer_id', v_customer.id,
    'place_id', v_place.id,
    'is_test', v_review.is_test,
    'validated', v_validated,
    'renamed', v_renamed
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_restore_validation(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_retake_place_signboard(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_retake_place_signboard(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_photo text := nullif(trim(coalesce(p ->> 'photo_path', '')), '');
  v_check jsonb := p -> 'signboard_check';
  v_place public.phoenix_crm_places%rowtype;
begin
  if v_seat is null or v_actor is null or v_photo is null or nullif(p ->> 'place_id', '') is null
     or v_check is null or jsonb_typeof(v_check) <> 'object' then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select pl.* into v_place
  from public.phoenix_crm_places pl
  where pl.id = (p ->> 'place_id')::uuid
    and pl.seat_id = v_seat
    and pl.is_test = v_is_test
  for update;
  if not found or v_place.status <> 'active' then
    raise exception 'phoenix_crm:place_not_found';
  end if;
  if v_place.shared_place_id is not null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform public.phoenix_crm_take_photo(v_photo, v_actor, v_seat, 'place', v_is_test);

  update public.phoenix_crm_places pl
  set photo_path = v_photo,
      signboard_check = v_check
  where pl.id = v_place.id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_place.customer_id, v_place.id, 'place_signboard_retaken', v_actor,
    jsonb_build_object(
      'photo_path', v_photo,
      'before_photo_path', v_place.photo_path,
      'before_signboard_check', v_place.signboard_check,
      'verdict', v_check ->> 'verdict'
    ),
    v_is_test
  );

  return jsonb_build_object('place_id', v_place.id, 'customer_id', v_place.customer_id);
end;
$$;

ALTER FUNCTION public.phoenix_crm_retake_place_signboard(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_return_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_return_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_request_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_stage_in text := nullif(p ->> 'stage', '');
  v_seat text;
  v_request public.phoenix_crm_list_requests%rowtype;
begin
  if v_actor is null or v_request_id is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;
  if char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select q.* into v_request
  from public.phoenix_crm_list_requests q
  where q.id = v_request_id
    and q.is_test = v_is_test;
  if not found then
    raise exception 'phoenix_crm:request_not_found';
  end if;
  v_seat := v_request.seat_id;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select q.* into v_request
  from public.phoenix_crm_list_requests q
  where q.id = v_request_id
  for update;
  if v_request.status <> 'pending' then
    raise exception 'phoenix_crm:request_decided';
  end if;
  if v_request.stage = 'rep' then
    raise exception 'phoenix_crm:already_returned';
  end if;
  if v_stage_in is not null and v_stage_in is distinct from v_request.stage then
    raise exception 'phoenix_crm:request_wrong_stage';
  end if;
  if v_request.stage = 'manager' then
    raise exception 'phoenix_crm:cannot_return';
  end if;

  update public.phoenix_crm_list_requests q
  set stage = 'rep',
      return_note = v_note,
      returned_by_hr_id = v_actor,
      returned_at = now(),
      rep_reply = null,
      replied_at = null
  where q.id = v_request.id
  returning q.* into v_request;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
  values (v_seat, v_request.customer_id, v_request.id, 'request_returned', v_actor, jsonb_build_object('kind', v_request.kind), v_is_test);

  return jsonb_build_object(
    'request_id', v_request.id,
    'seat_id', v_seat,
    'kind', v_request.kind,
    'status', 'pending',
    'stage', 'rep',
    'returned_at', v_request.returned_at,
    'customer_id', v_request.customer_id,
    'customer_name', v_request.customer_name,
    'list_type', v_request.list_type,
    'requested_by_hr_id', v_request.requested_by_hr_id
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_return_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_reverse_list_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_reverse_list_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_seat text;
  v_request public.phoenix_crm_list_requests%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_old_grade text;
  v_reason text;
  v_has_place boolean;
begin
  if v_request_id is null or v_actor is null or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;

  select q.* into v_request from public.phoenix_crm_list_requests q where q.id = v_request_id and q.is_test = v_is_test;
  if not found then
    raise exception 'phoenix_crm:request_not_found';
  end if;
  v_seat := v_request.seat_id;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select q.* into v_request from public.phoenix_crm_list_requests q where q.id = v_request_id for update;
  if v_request.status <> 'approved' or v_request.customer_id is null then
    raise exception 'phoenix_crm:request_not_approved';
  end if;

  select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_request.customer_id for update;
  if not found then
    raise exception 'phoenix_crm:reverse_customer_moved_on';
  end if;

  -- Anything that touched this customer after the decision (another request, a place, a move) means the
  -- picture is no longer the one the decision made: say so, change nothing.
  if exists (
    select 1 from public.phoenix_crm_list_events ev
    where ev.customer_id = v_customer.id
      and ev.created_at > v_request.decided_at
      and ev.request_id is distinct from v_request.id
  ) or exists (
    select 1 from public.phoenix_crm_list_requests q2
    where q2.customer_id = v_customer.id and q2.id <> v_request.id and q2.requested_at > v_request.decided_at
  ) then
    raise exception 'phoenix_crm:reverse_customer_moved_on';
  end if;

  if v_request.kind = 'grade' then
    if v_customer.status <> 'active' or v_customer.grade is distinct from v_request.proposed_grade then
      raise exception 'phoenix_crm:reverse_customer_moved_on';
    end if;
    select e.details ->> 'from' into v_old_grade
    from public.phoenix_crm_list_events e
    where e.request_id = v_request.id and e.event_type = 'grade_changed'
    order by e.id desc limit 1;
    if v_old_grade is null then
      raise exception 'phoenix_crm:reverse_customer_moved_on';
    end if;
    update public.phoenix_crm_customers c set grade = v_old_grade, updated_at = now() where c.id = v_customer.id;
    insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
    values (v_seat, v_customer.id, v_request.id, 'grade_change_reversed', v_actor,
            jsonb_build_object('from', v_customer.grade, 'to', v_old_grade), v_is_test);

  elsif v_request.kind = 'add' then
    -- 'pending' too (2026-11-11): an add approved for a customer with no place admits him to
    -- "To validate", and that decision must stay as undoable as one that validated him. Anything
    -- that moved him since is already refused above.
    if v_customer.status not in ('active', 'pending') then
      raise exception 'phoenix_crm:reverse_customer_moved_on';
    end if;
    -- Back out the way a refused add leaves: in the Archive, never admitted, the rep may ask again.
    update public.phoenix_crm_customers c
    set status = 'dropped',
        dropped_reason = 'not_admitted',
        dropped_note = v_note,
        validated_at = null,
        validated_by_hr_id = null,
        status_changed_at = now(),
        updated_at = now()
    where c.id = v_customer.id;
    insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
    values (v_seat, v_customer.id, v_request.id, 'customer_archived', v_actor, jsonb_build_object('why', 'add_reversed'), v_is_test);

  elsif v_request.kind = 'restore' then
    if v_customer.status not in ('active', 'pending') then
      raise exception 'phoenix_crm:reverse_customer_moved_on';
    end if;
    select coalesce(nullif(e.details ->> 'reason', ''), case when e.event_type = 'customer_archived' then 'not_admitted' end)
      into v_reason
    from public.phoenix_crm_list_events e
    where e.customer_id = v_customer.id and e.event_type in ('customer_dropped', 'customer_archived') and e.created_at <= v_request.decided_at
    order by e.id desc limit 1;
    update public.phoenix_crm_customers c
    set status = 'dropped',
        dropped_reason = coalesce(v_reason, 'other'),
        dropped_note = v_note,
        status_changed_at = now(),
        updated_at = now()
    where c.id = v_customer.id;
    insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
    values (v_seat, v_customer.id, v_request.id, 'customer_archived', v_actor, jsonb_build_object('why', 'restore_reversed'), v_is_test);

  elsif v_request.kind = 'drop' then
    if v_customer.status <> 'dropped' then
      raise exception 'phoenix_crm:reverse_customer_moved_on';
    end if;
    -- Back where he was: on the list if he had been validated, waiting to be validated if not. The
    -- other requests the drop withdrew stay withdrawn - the rep asks again if he still needs them.
    -- ...and on the list only while he still holds a place (2026-11-11, the same door as a bring-back).
    v_has_place := v_customer.list_type not in ('AM', 'PM') or exists (
      select 1 from public.phoenix_crm_places pl
      where pl.customer_id = v_customer.id and pl.status = 'active'
    );
    update public.phoenix_crm_customers c
    set status = case when c.validated_at is not null and v_has_place then 'active' else 'pending' end,
        validated_at = case when v_has_place then c.validated_at else null end,
        validated_by_hr_id = case when v_has_place then c.validated_by_hr_id else null end,
        reopened_at = case when c.validated_at is not null and not v_has_place then now() else c.reopened_at end,
        dropped_reason = null,
        dropped_note = null,
        status_changed_at = now(),
        updated_at = now()
    where c.id = v_customer.id;
    insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
    values (v_seat, v_customer.id, v_request.id, 'customer_restored', v_actor, jsonb_build_object('why', 'drop_reversed', 'place', v_has_place), v_is_test);

  else
    raise exception 'phoenix_crm:reverse_customer_moved_on';
  end if;

  update public.phoenix_crm_list_requests q
  set status = 'refused',
      stage = null,
      decided_at = now(),
      decided_by_hr_id = v_actor,
      decision_note = v_note,
      admin_decided_by_hr_id = v_actor,
      admin_decided_at = now(),
      admin_note = v_note
  where q.id = v_request.id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
  values (v_seat, v_customer.id, v_request.id, 'request_reversed', v_actor,
          jsonb_build_object('kind', v_request.kind, 'was', 'approved'), v_is_test);

  return jsonb_build_object(
    'request_id', v_request.id,
    'seat_id', v_seat,
    'kind', v_request.kind,
    'status', 'refused',
    'stage', null,
    'final', true,
    'customer_id', v_customer.id,
    'customer_name', v_request.customer_name,
    'list_type', v_request.list_type,
    'proposed_grade', v_request.proposed_grade,
    'drop_reason', v_request.drop_reason,
    'requested_by_hr_id', v_request.requested_by_hr_id
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_reverse_list_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_reverse_plan_edit_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_reverse_plan_edit_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid := nullif(p ->> 'request_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_seat text;
  v_week date;
  v_request public.phoenix_crm_plan_edit_requests%rowtype;
  v_plan public.phoenix_crm_plans%rowtype;
  v_opened jsonb;
  v_before text;
  v_approval public.phoenix_crm_plan_events%rowtype;
begin
  if v_request_id is null or v_actor is null or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;

  select r.seat_id, r.week_start into v_seat, v_week from public.phoenix_crm_plan_edit_requests r where r.id = v_request_id;
  if not found then
    raise exception 'phoenix_crm:plan_edit_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:plan:' || v_seat || ':' || v_week::text));

  select r.* into v_request from public.phoenix_crm_plan_edit_requests r where r.id = v_request_id for update;
  if v_request.is_test <> v_is_test then
    raise exception 'phoenix_crm:plan_edit_not_found';
  end if;
  if v_expected is distinct from v_request.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  if v_request.status <> 'reopened' then
    raise exception 'phoenix_crm:plan_edit_not_reopened';
  end if;

  select e.details into v_opened
  from public.phoenix_crm_plan_edit_request_events e
  where e.request_id = v_request_id and e.to_status = 'reopened'
  order by e.id desc
  limit 1;
  v_before := v_opened ->> 'plan_status_before';

  select pl.* into v_plan from public.phoenix_crm_plans pl where pl.id = v_request.plan_id for update;

  if coalesce((v_opened ->> 'plan_reopened')::boolean, false) is not true
    or v_before not in ('submitted', 'approved')
    or v_plan.status <> 'draft'
    or v_plan.version is distinct from v_request.reopened_plan_version
    or v_request.week_start + 5 < v_today then
    raise exception 'phoenix_crm:plan_edit_cannot_reverse';
  end if;

  if v_before = 'approved' then
    select e.* into v_approval
    from public.phoenix_crm_plan_events e
    where e.plan_id = v_plan.id and e.event_type = 'approved' and e.created_at < v_request.decided_at
    order by e.id desc
    limit 1;
    if not found then
      raise exception 'phoenix_crm:plan_edit_cannot_reverse';
    end if;
    update public.phoenix_crm_plans pl
    set status = 'approved',
        decided_at = v_approval.created_at,
        decided_by_hr_id = v_approval.actor_hr_id,
        decided_by_role = v_approval.actor_role,
        decision_note = v_approval.note,
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    insert into public.phoenix_crm_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
    values (v_plan.id, 'approved', v_approval.actor_hr_id, v_approval.actor_role, 'draft', v_plan.status, v_plan.version, v_approval.note,
            jsonb_build_object('edit_request_id', v_request_id, 'restored_by', v_actor));
  else
    update public.phoenix_crm_plans pl
    set status = 'submitted',
        version = pl.version + 1,
        updated_at = now()
    where pl.id = v_plan.id
    returning pl.* into v_plan;
    insert into public.phoenix_crm_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version, note, details)
    values (v_plan.id, 'submitted', v_actor, 'administrator', 'draft', v_plan.status, v_plan.version, null,
            jsonb_build_object('edit_request_id', v_request_id, 'restored_by', v_actor));
  end if;

  update public.phoenix_crm_plan_edit_requests r
  set status = 'refused',
      admin_decided_by_hr_id = v_actor,
      admin_decided_at = now(),
      admin_note = v_note,
      hr_acknowledged_at = null,
      reopened_plan_version = null,
      decided_at = now(),
      version = r.version + 1,
      updated_at = now()
  where r.id = v_request_id
  returning r.* into v_request;

  insert into public.phoenix_crm_plan_edit_request_events
    (request_id, event_type, actor_hr_id, actor_role, actor_stage, from_status, to_status, version, note, details)
  values
    (v_request_id, 'refused', v_actor, 'administrator', 'administrator', 'reopened', 'refused', v_request.version, v_note,
     jsonb_build_object('reversed', true, 'plan_restored_to', v_before));

  return jsonb_build_object(
    'request_id', v_request.id,
    'plan_id', v_request.plan_id,
    'seat_id', v_request.seat_id,
    'week_start', v_request.week_start,
    'rep_hr_id', v_request.rep_hr_id,
    'status', v_request.status,
    'version', v_request.version,
    'plan_version', v_plan.version
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_reverse_plan_edit_request(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_reverse_unplanned_visit(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_reverse_unplanned_visit(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_visit_id uuid := nullif(p ->> 'visit_id', '')::uuid;
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_row public.phoenix_crm_unplanned_visits%rowtype;
begin
  if v_visit_id is null or v_actor is null or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;
  if not exists (select 1 from public.phoenix_crm_unplanned_visits u where u.visit_id = v_visit_id) then
    raise exception 'phoenix_crm:unplanned_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:unplanned:' || v_visit_id::text));

  select u.* into v_row from public.phoenix_crm_unplanned_visits u where u.visit_id = v_visit_id for update;
  if v_row.is_test <> v_is_test then
    raise exception 'phoenix_crm:unplanned_not_found';
  end if;
  if v_expected is distinct from v_row.version then
    raise exception 'phoenix_crm:version_conflict';
  end if;
  if v_row.status <> 'approved' then
    raise exception 'phoenix_crm:unplanned_not_approved';
  end if;

  update public.phoenix_crm_unplanned_visits u
  set status = 'refused',
      admin_decided_by_hr_id = v_actor,
      admin_decided_at = now(),
      admin_note = v_note,
      decided_at = now(),
      version = u.version + 1,
      updated_at = now()
  where u.visit_id = v_visit_id
  returning u.* into v_row;

  insert into public.phoenix_crm_unplanned_visit_events
    (visit_id, event_type, actor_hr_id, actor_role, actor_stage, from_status, to_status, version, note, details)
  values
    (v_visit_id, 'refused', v_actor, 'administrator', null, 'approved', 'refused', v_row.version, v_note,
     jsonb_build_object('reversed', true));

  return jsonb_build_object(
    'visit_id', v_row.visit_id,
    'seat_id', v_row.seat_id,
    'rep_hr_id', v_row.rep_hr_id,
    'customer_id', v_row.customer_id,
    'visit_date', v_row.visit_date,
    'status', v_row.status,
    'version', v_row.version
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_reverse_unplanned_visit(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_review_visit_recording(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_review_visit_recording(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_visit_id uuid := nullif(p ->> 'visit_id', '')::uuid;
  v_decision text := coalesce(p ->> 'decision', '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_role text := nullif(trim(coalesce(p ->> 'actor_role', '')), '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_rec public.phoenix_crm_visit_recordings%rowtype;
  v_visit public.phoenix_crm_visits%rowtype;
  v_row public.phoenix_crm_unplanned_visits%rowtype;
  v_status text;
  v_unplanned_status text := null;
  v_unplanned_version integer := null;
begin
  if v_visit_id is null or v_actor is null
    or v_decision not in ('approve', 'refuse')
    or (v_note is not null and char_length(v_note) > 500) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_decision = 'refuse' and v_note is null then
    raise exception 'phoenix_crm:note_required';
  end if;

  select r.* into v_rec from public.phoenix_crm_visit_recordings r where r.visit_id = v_visit_id for update;
  if not found then
    raise exception 'phoenix_crm:recording_review_not_found';
  end if;
  select v.* into v_visit from public.phoenix_crm_visits v where v.id = v_visit_id;
  if not found then
    raise exception 'phoenix_crm:recording_review_not_found';
  end if;
  if v_rec.review_status <> 'pending' then
    raise exception 'phoenix_crm:recording_reviewed';
  end if;

  v_status := case when v_decision = 'approve' then 'approved' else 'refused' end;
  update public.phoenix_crm_visit_recordings r
  set review_status = v_status,
      reviewed_by_hr_id = v_actor,
      reviewed_at = now(),
      review_note = v_note
  where r.path = v_rec.path;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:unplanned:' || v_visit_id::text));
  select u.* into v_row from public.phoenix_crm_unplanned_visits u where u.visit_id = v_visit_id for update;
  if found then
    if v_row.status = 'admin_pending' then
      update public.phoenix_crm_unplanned_visits u
      set status = case when v_decision = 'approve' then u.after_admin_status else 'refused' end,
          decided_at = case when v_decision = 'approve' then null else now() end,
          admin_decided_by_hr_id = v_actor,
          admin_decided_at = now(),
          admin_note = v_note,
          version = u.version + 1,
          updated_at = now()
      where u.visit_id = v_visit_id
      returning u.* into v_row;

      insert into public.phoenix_crm_unplanned_visit_events
        (visit_id, event_type, actor_hr_id, actor_role, actor_stage, from_status, to_status, version, note)
      values
        (v_visit_id, case when v_decision = 'refuse' then 'refused' else 'approved' end,
         v_actor, v_role, 'administrator', 'admin_pending', v_row.status, v_row.version, v_note);
    end if;
    v_unplanned_status := v_row.status;
    v_unplanned_version := v_row.version;
  end if;

  return jsonb_build_object(
    'visit_id', v_visit_id,
    'seat_id', v_visit.seat_id,
    'rep_hr_id', coalesce(v_visit.rep_hr_id, v_rec.issued_to_hr_id),
    'customer_id', v_visit.customer_id,
    'visit_date', v_visit.visit_date,
    'is_test', v_visit.is_test,
    'is_unplanned', v_visit.is_unplanned,
    'unplanned_kind', v_visit.unplanned_kind,
    'review_status', v_status,
    'unplanned_status', v_unplanned_status,
    'unplanned_version', v_unplanned_version
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_review_visit_recording(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_save_daily_forecast(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_save_daily_forecast(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(btrim(p ->> 'seat_id'), '');
  v_line text := lower(nullif(btrim(p ->> 'line_code'), ''));
  v_area text := nullif(btrim(p ->> 'area_code'), '');
  v_rep text := nullif(btrim(p ->> 'rep_hr_id'), '');
  v_actor text := nullif(btrim(p ->> 'actor_hr_id'), '');
  v_date date := nullif(p ->> 'forecast_date', '')::date;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_lines jsonb := p -> 'lines';
  v_line_item jsonb;
  v_product text;
  v_units integer;
  v_suggested integer;
  v_first timestamptz;
  v_count integer := 0;
begin
  if v_seat is null or v_actor is null or v_date is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_line is distinct from 'cns' then
    raise exception 'phoenix_crm:not_forecast_line';
  end if;
  if v_lines is null or jsonb_typeof(v_lines) <> 'array' or jsonb_array_length(v_lines) = 0 or jsonb_array_length(v_lines) > 50 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if (select count(distinct upper(btrim(item ->> 'product_code'))) from jsonb_array_elements(v_lines) item) <> jsonb_array_length(v_lines) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:daily_forecast:' || v_seat || ':' || v_date::text));

  select min(created_at) into v_first
  from public.phoenix_crm_daily_forecasts
  where seat_id = v_seat and forecast_date = v_date and is_test = v_is_test;

  delete from public.phoenix_crm_daily_forecasts
  where seat_id = v_seat and forecast_date = v_date and is_test = v_is_test;

  for v_line_item in select value from jsonb_array_elements(v_lines)
  loop
    v_product := upper(nullif(btrim(v_line_item ->> 'product_code'), ''));
    if v_product is null then
      raise exception 'phoenix_crm:bad_input';
    end if;
    if jsonb_typeof(v_line_item -> 'units') <> 'number' then
      raise exception 'phoenix_crm:bad_input';
    end if;
    v_units := (v_line_item ->> 'units')::integer;
    if v_units < 0 or v_units > 5000 then
      raise exception 'phoenix_crm:bad_input';
    end if;
    v_suggested := case
      when jsonb_typeof(v_line_item -> 'suggested_units') = 'number' then greatest(0, (v_line_item ->> 'suggested_units')::integer)
      else null
    end;

    insert into public.phoenix_crm_daily_forecasts (
      seat_id, line_code, area_code, rep_hr_id, entered_by_hr_id, forecast_date,
      product_code, units, suggested_units, is_test, created_at, updated_at
    )
    values (
      v_seat, v_line, v_area, v_rep, v_actor, v_date,
      v_product, v_units, v_suggested, v_is_test, coalesce(v_first, now()), now()
    );
    v_count := v_count + 1;
  end loop;

  return jsonb_build_object(
    'saved', v_count,
    'first_sent_at', coalesce(v_first, now()),
    'forecast_date', v_date
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_save_daily_forecast(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_save_day_activity(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_save_day_activity(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(btrim(p ->> 'seat_id'), '');
  v_line text := nullif(btrim(p ->> 'line_code'), '');
  v_rep text := nullif(btrim(p ->> 'rep_hr_id'), '');
  v_actor text := nullif(btrim(p ->> 'actor_hr_id'), '');
  v_date date := nullif(p ->> 'activity_date', '')::date;
  v_type text := nullif(btrim(p ->> 'activity_type'), '');
  v_half boolean := coalesce((p ->> 'half_day')::boolean, false);
  v_note text := nullif(btrim(p ->> 'note'), '');
  v_row public.phoenix_crm_day_activities%rowtype;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
begin
  if v_seat is null or v_actor is null or v_date is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:day_activity:' || v_seat || ':' || v_date::text));

  if v_type is null then
    delete from public.phoenix_crm_day_activities
    where seat_id = v_seat and activity_date = v_date and is_test = v_is_test;
    return jsonb_build_object('cleared', true);
  end if;

  if v_type not in ('meeting', 'training', 'conference', 'admin_work', 'travel', 'health_day', 'sales_day', 'rtd', 'group_meeting', 'interviews') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  insert into public.phoenix_crm_day_activities (
    seat_id, line_code, rep_hr_id, entered_by_hr_id, activity_date, activity_type, half_day, note, is_test
  )
  values (v_seat, v_line, v_rep, v_actor, v_date, v_type, v_half, v_note, v_is_test)
  on conflict (seat_id, activity_date, is_test) do update
    set activity_type = excluded.activity_type,
        half_day = excluded.half_day,
        note = excluded.note,
        entered_by_hr_id = excluded.entered_by_hr_id,
        line_code = excluded.line_code,
        rep_hr_id = excluded.rep_hr_id,
        updated_at = now()
  returning * into v_row;

  return jsonb_build_object(
    'cleared', false,
    'id', v_row.id,
    'activity_date', v_row.activity_date,
    'activity_type', v_row.activity_type,
    'half_day', v_row.half_day,
    'note', v_row.note
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_save_day_activity(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_save_double_visit_slot(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_save_double_visit_slot(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_manager text := upper(nullif(trim(coalesce(p ->> 'manager_hr_id', '')), ''));
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_date date := nullif(p ->> 'plan_date', '')::date;
  v_half text := coalesce(p ->> 'half', '');
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_rep text := upper(nullif(trim(coalesce(p ->> 'rep_hr_id', '')), ''));
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_expected text := nullif(trim(coalesce(p ->> 'expected_seat_id', '')), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_week date;
  v_this_week date;
  v_row public.phoenix_crm_double_visit_plans%rowtype;
  v_found boolean;
begin
  if v_manager is null or v_actor is null or v_date is null or v_half not in ('AM', 'PM') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- A pick names its rep; a clear names nobody.
  if v_seat is not null and v_rep is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- The field week: Saturday to Wednesday, AM and PM; Thursday a morning; never a Friday.
  if extract(isodow from v_date) = 5 or (extract(isodow from v_date) = 4 and v_half = 'PM') then
    raise exception 'phoenix_crm:double_visit_not_field_time';
  end if;
  -- A day that has passed keeps its plan, so plan against actual still reads what was planned.
  if v_date < v_today then
    raise exception 'phoenix_crm:double_visit_day_passed';
  end if;
  -- The Saturday that starts a day's field week (isodow: Saturday 6, Sunday 7; a Friday, 5, belongs to
  -- the week before it) — calendar.ts fieldWeekStart in SQL.
  v_week := v_date - ((extract(isodow from v_date)::integer + 1) % 7);
  v_this_week := v_today - ((extract(isodow from v_today)::integer + 1) % 7);
  -- This week from today on, and the coming week. Never a week beyond it.
  if v_week > v_this_week + 7 then
    raise exception 'phoenix_crm:double_visit_week_ahead';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('phoenix_crm:double_visit:' || v_manager || ':' || v_date::text || ':' || v_half || ':' || v_is_test::text)
  );

  select d.* into v_row
  from public.phoenix_crm_double_visit_plans d
  where d.manager_hr_id = v_manager and d.plan_date = v_date and d.half = v_half and d.is_test = v_is_test
  for update;
  v_found := found;

  -- The screen sends the rep seat it showed for this half-day (null for none). Anything else means
  -- another screen changed it first, and writing over it would lose that change without a word.
  if (case when v_found then v_row.seat_id else null end) is distinct from v_expected then
    raise exception 'phoenix_crm:double_visit_changed';
  end if;

  if v_seat is null then
    if v_found then
      delete from public.phoenix_crm_double_visit_plans d where d.id = v_row.id;
    end if;
  elsif v_found then
    update public.phoenix_crm_double_visit_plans d
    set seat_id = v_seat,
        rep_hr_id = v_rep,
        line_code = v_line,
        entered_by_hr_id = v_actor,
        updated_at = now()
    where d.id = v_row.id;
  else
    insert into public.phoenix_crm_double_visit_plans
      (manager_hr_id, week_start, plan_date, half, seat_id, rep_hr_id, line_code, entered_by_hr_id, is_test)
    values
      (v_manager, v_week, v_date, v_half, v_seat, v_rep, v_line, v_actor, v_is_test);
  end if;

  return jsonb_build_object(
    'manager_hr_id', v_manager,
    'week_start', v_week,
    'plan_date', v_date,
    'half', v_half,
    'seat_id', v_seat,
    'is_test', v_is_test
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_save_double_visit_slot(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_save_manager_plan_slot(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_save_manager_plan_slot(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_manager text := upper(nullif(trim(coalesce(p ->> 'manager_hr_id', '')), ''));
  v_seat text := nullif(trim(coalesce(p ->> 'manager_seat_id', '')), '');
  v_planner text := coalesce(nullif(trim(coalesce(p ->> 'planner_kind', '')), ''), 'dm');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_date date := nullif(p ->> 'plan_date', '')::date;
  v_half text := coalesce(p ->> 'half', '');
  v_kind text := nullif(trim(coalesce(p ->> 'kind', '')), '');
  v_rep_seat text := nullif(trim(coalesce(p ->> 'rep_seat_id', '')), '');
  v_rep text := upper(nullif(trim(coalesce(p ->> 'rep_hr_id', '')), ''));
  v_activity text := nullif(trim(coalesce(p ->> 'activity_type', '')), '');
  v_area_seat text := nullif(trim(coalesce(p ->> 'area_seat_id', '')), '');
  v_area_code text := nullif(trim(coalesce(p ->> 'area_code', '')), '');
  v_area_name text := nullif(trim(coalesce(p ->> 'area_name', '')), '');
  v_scope_seat text := nullif(trim(coalesce(p ->> 'scope_dm_seat_id', '')), '');
  v_scope_line text := nullif(trim(coalesce(p ->> 'scope_line_code', '')), '');
  v_dm_visit jsonb := p -> 'dm_visit';
  v_senior_visit jsonb := p -> 'senior_visit';
  v_region text := nullif(trim(coalesce(p ->> 'scope_region_code', '')), '');
  v_note text := nullif(regexp_replace(trim(coalesce(p ->> 'note', '')), '\s+', ' ', 'g'), '');
  v_customers jsonb := coalesce(p -> 'customers', '[]'::jsonb);
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_week date;
  v_this_week date;
  v_plan public.phoenix_crm_manager_plans%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_slot_id uuid;
  v_entry jsonb;
  v_cid uuid;
  v_mcid uuid;
begin
  if v_planner not in ('dm', 'rsm', 'nsm', 'pm', 'tm') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- A product manager and the Training Manager hold no seat; everybody else plans from his own.
  if v_manager is null or (v_seat is null and v_planner not in ('pm', 'tm')) or v_actor is null or v_date is null or v_half not in ('AM', 'PM') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if jsonb_typeof(v_customers) <> 'array' or jsonb_array_length(v_customers) > 60 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- A scope is the district manager seat (and its line) or a line alone; a district manager plans his
  -- own district, so his half-days carry none, and Admin never does. With a manager or product manager
  -- names the district manager seat for every planner but him (owner, 2026-10-25).
  if (v_scope_seat is not null and v_scope_line is null)
     or ((v_scope_seat is not null or v_scope_line is not null)
         and (v_planner = 'dm' or v_kind is distinct from 'with_rep' and v_kind is distinct from 'single_visit' and v_kind is distinct from 'with_dm' and v_kind is distinct from 'with_senior')) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- The Training Manager (owner, 2026-10-24): a region, then a rep or an area, or Admin — never a district
  -- manager or a line, never a customer. A region belongs to her and to her two kinds alone.
  if v_planner = 'tm' then
    if v_kind is not null and v_kind not in ('with_rep', 'with_area', 'admin') then
      raise exception 'phoenix_crm:manager_plan_bad_kind';
    end if;
    if v_scope_seat is not null or v_scope_line is not null or jsonb_array_length(v_customers) > 0 then
      raise exception 'phoenix_crm:bad_input';
    end if;
    if v_kind in ('with_rep', 'with_area') and v_region is null then
      raise exception 'phoenix_crm:bad_input';
    end if;
  elsif v_region is not null or v_kind = 'with_area' then
    raise exception 'phoenix_crm:manager_plan_bad_kind';
  end if;
  if v_region is not null and v_kind is distinct from 'with_rep' and v_kind is distinct from 'with_area' then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- Each kind carries its own fields and nothing else; a clear carries nothing.
  if v_kind is distinct from 'with_dm' and v_kind is distinct from 'with_area' and v_dm_visit is not null and jsonb_typeof(v_dm_visit) <> 'null' then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_kind is distinct from 'with_senior' and v_senior_visit is not null and jsonb_typeof(v_senior_visit) <> 'null' then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_kind is null then
    if jsonb_array_length(v_customers) > 0 then
      raise exception 'phoenix_crm:bad_input';
    end if;
  elsif v_kind = 'with_rep' then
    if v_rep_seat is null or v_rep is null or v_activity is not null or v_area_code is not null then
      raise exception 'phoenix_crm:bad_input';
    end if;
  elsif v_kind = 'admin' then
    if v_activity is null or v_activity not in ('meeting', 'training', 'conference', 'admin_work', 'travel', 'health_day', 'sales_day', 'rtd', 'group_meeting', 'interviews', 'office')
       or v_rep_seat is not null or v_area_code is not null or jsonb_array_length(v_customers) > 0 then
      raise exception 'phoenix_crm:bad_input';
    end if;
    -- Office belongs to the managers judged by their office days, never to a district manager's board.
    if v_activity = 'office' and v_planner = 'dm' then
      raise exception 'phoenix_crm:manager_plan_bad_kind';
    end if;
  elsif v_kind = 'single_visit' then
    if v_area_code is null or v_rep_seat is not null or v_activity is not null then
      raise exception 'phoenix_crm:bad_input';
    end if;
  elsif v_kind = 'with_dm' then
    -- With a district manager (owner, 2026-10-23): the regional, national and product managers only, in a
    -- district manager's own district, on the areas he ticked, and with no customer of anyone's.
    if v_planner = 'dm' then
      raise exception 'phoenix_crm:manager_plan_bad_kind';
    end if;
    if v_scope_seat is null or v_rep_seat is not null or v_activity is not null or v_area_code is not null
       or v_area_seat is not null or jsonb_array_length(v_customers) > 0
       or coalesce(jsonb_typeof(v_dm_visit), '') <> 'object'
       or (case when jsonb_typeof(v_dm_visit -> 'areas') = 'array' then jsonb_array_length(v_dm_visit -> 'areas') else 0 end) not between 1 and 60
       or exists (
         select 1 from jsonb_array_elements(v_dm_visit -> 'areas') a
         where nullif(trim(coalesce(a.value ->> 'seat_id', '')), '') is null
       ) then
      raise exception 'phoenix_crm:bad_input';
    end if;
  elsif v_kind = 'with_area' then
    -- An area (owner, 2026-10-24): the Training Manager's half-day in one area of her region — its seat, code
    -- and name, and every territory of it in dm_visit so Done reads the reps' visits there without a guess.
    if v_area_seat is null or v_area_code is null or v_area_name is null or v_rep_seat is not null or v_activity is not null
       or coalesce(jsonb_typeof(v_dm_visit), '') <> 'object'
       or (case when jsonb_typeof(v_dm_visit -> 'areas') = 'array' then jsonb_array_length(v_dm_visit -> 'areas') else 0 end) <> 1
       or exists (
         select 1 from jsonb_array_elements(v_dm_visit -> 'areas') a
         where nullif(trim(coalesce(a.value ->> 'seat_id', '')), '') is distinct from v_area_seat
       ) then
      raise exception 'phoenix_crm:bad_input';
    end if;
  elsif v_kind = 'with_senior' then
    -- With my manager or product manager (owner, 2026-10-23): a district manager in his own district (no scope,
    -- the clause above), with one person and the areas he ticked. Since 2026-10-27 (owner: "I want to be
    -- optional … all the doctor list of this area appear, but he is not required to choose") he may also name
    -- doctors of those areas' rep lists, or none; the loop below takes rep customers only and the application
    -- keeps them inside the ticked areas. Since 2026-10-25
    -- (owner: "in weekly plan for nsm make an option to dv with product manager … same to product manager option
    -- 2 double visit with nsm") the regional, national and product managers plan it too, in one district manager's
    -- district (the scope seat is required), never the Training Manager. Who may be picked is the application's
    -- (the chain of the line and its product managers, never a product manager beside another).
    if v_planner = 'tm' then
      raise exception 'phoenix_crm:manager_plan_bad_kind';
    end if;
    if v_planner <> 'dm' and v_scope_seat is null then
      raise exception 'phoenix_crm:bad_input';
    end if;
    if v_rep_seat is not null or v_activity is not null or v_area_code is not null
       or v_area_seat is not null
       or coalesce(jsonb_typeof(v_senior_visit), '') <> 'object'
       or nullif(trim(coalesce(v_senior_visit ->> 'senior_hr_id', '')), '') is null
       or upper(trim(v_senior_visit ->> 'senior_hr_id')) = v_manager
       or (case when jsonb_typeof(v_senior_visit -> 'areas') = 'array' then jsonb_array_length(v_senior_visit -> 'areas') else 0 end) not between 1 and 60
       or exists (
         select 1 from jsonb_array_elements(v_senior_visit -> 'areas') a
         where nullif(trim(coalesce(a.value ->> 'seat_id', '')), '') is null
       ) then
      raise exception 'phoenix_crm:bad_input';
    end if;
  else
    raise exception 'phoenix_crm:manager_plan_bad_kind';
  end if;
  -- A half-day with a rep or on a single visit names the customers he will see.
  -- The Training Manager's With a rep names the rep alone (owner, 2026-10-24: "he neevr choose dr").
  -- A national sales manager's and the Group Product Manager's customers are optional (owner, 2026-11-01: "rasha
  -- only and nsms"); the application tells a Group Product Manager from a Product Manager, both planner_kind 'pm'.
  if v_kind in ('with_rep', 'single_visit') and v_planner not in ('tm', 'nsm', 'pm') and jsonb_array_length(v_customers) = 0 then
    raise exception 'phoenix_crm:manager_plan_slot_empty';
  end if;

  -- The field week: Saturday to Wednesday, AM and PM; Thursday a morning; never a Friday.
  if extract(isodow from v_date) = 5 or (extract(isodow from v_date) = 4 and v_half = 'PM') then
    raise exception 'phoenix_crm:manager_plan_not_field_time';
  end if;
  -- A day that has passed keeps its plan, so actual against planned still reads what was planned.
  if v_date < v_today then
    raise exception 'phoenix_crm:manager_plan_day_passed';
  end if;
  -- calendar.ts fieldWeekStart in SQL. The week he is in and the coming one — the application narrows
  -- it to the one he plans (the coming week, or the week he is in while he never sent it).
  v_week := v_date - ((extract(isodow from v_date)::integer + 1) % 7);
  v_this_week := v_today - ((extract(isodow from v_today)::integer + 1) % 7);
  if v_week not in (v_this_week, v_this_week + 7) then
    raise exception 'phoenix_crm:manager_plan_week_closed';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('phoenix_crm:manager_plan:' || v_manager || ':' || v_week::text || ':' || v_is_test::text)
  );

  select pl.* into v_plan
  from public.phoenix_crm_manager_plans pl
  where pl.manager_hr_id = v_manager and pl.week_start = v_week and pl.is_test = v_is_test
  for update;

  if not found then
    -- The screen showed no week, so it sends no version. Anything else means another screen made it.
    if v_expected is not null then
      raise exception 'phoenix_crm:version_conflict';
    end if;
    if v_kind is null then
      return jsonb_build_object('plan_id', null, 'version', null, 'status', null, 'week_start', v_week, 'slot_id', null);
    end if;
    insert into public.phoenix_crm_manager_plans
      (manager_hr_id, manager_seat_id, planner_kind, line_code, week_start, status, version, due_on, created_by_hr_id, is_test)
    values
      (v_manager, v_seat, v_planner, v_line, v_week, 'draft', 1, public.phoenix_crm_week_due_on(v_week), v_actor, v_is_test)
    returning * into v_plan;
    insert into public.phoenix_crm_manager_plan_events (plan_id, event_type, actor_hr_id, actor_role, from_status, to_status, version)
    values (v_plan.id, 'created', v_actor, case when v_actor = v_manager then 'manager' else 'administrator' end, null, 'draft', v_plan.version);
  else
    if v_expected is distinct from v_plan.version then
      raise exception 'phoenix_crm:version_conflict';
    end if;
    -- A sent week changes only through his ask to edit it, decided above him.
    if v_plan.status not in ('draft', 'returned') then
      raise exception 'phoenix_crm:manager_plan_not_editable';
    end if;
    -- A week returned for ONE day changes on that day alone.
    if v_plan.status = 'returned' and v_plan.returned_day is not null and v_date <> v_plan.returned_day then
      raise exception 'phoenix_crm:manager_plan_day_not_returned';
    end if;
  end if;

  delete from public.phoenix_crm_manager_plan_slots s
  where s.plan_id = v_plan.id and s.plan_date = v_date and s.half = v_half;

  if v_kind is not null then
    insert into public.phoenix_crm_manager_plan_slots
      (plan_id, week_start, plan_date, half, kind, rep_seat_id, rep_hr_id, activity_type, area_seat_id, area_code, area_name,
       scope_dm_seat_id, scope_line_code, scope_region_code, dm_visit, senior_visit, note)
    values
      (v_plan.id, v_week, v_date, v_half, v_kind,
       case when v_kind = 'with_rep' then v_rep_seat end,
       case when v_kind = 'with_rep' then v_rep end,
       case when v_kind = 'admin' then v_activity end,
       case when v_kind in ('single_visit', 'with_area') then v_area_seat end,
       case when v_kind in ('single_visit', 'with_area') then v_area_code end,
       case when v_kind in ('single_visit', 'with_dm', 'with_senior', 'with_area') then v_area_name end,
       case when v_kind <> 'admin' then v_scope_seat end,
       case when v_kind <> 'admin' then v_scope_line end,
       case when v_kind in ('with_rep', 'with_area') then v_region end,
       case when v_kind in ('with_dm', 'with_area') then v_dm_visit end,
       case when v_kind = 'with_senior' then v_senior_visit end,
       v_note)
    returning id into v_slot_id;

    for v_entry in select value from jsonb_array_elements(v_customers) loop
      v_cid := nullif(v_entry ->> 'customer_id', '')::uuid;
      v_mcid := nullif(v_entry ->> 'manager_customer_id', '')::uuid;
      if (v_cid is null) = (v_mcid is null) then
        raise exception 'phoenix_crm:bad_input';
      end if;
      if v_cid is not null then
        select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_cid;
        if not found or v_customer.is_test <> v_is_test or v_customer.status = 'dropped' then
          raise exception 'phoenix_crm:manager_plan_customer_gone';
        end if;
        -- With a rep, every customer is that rep's own.
        if v_kind = 'with_rep' and v_customer.seat_id <> v_rep_seat then
          raise exception 'phoenix_crm:manager_plan_customer_not_reps';
        end if;
        insert into public.phoenix_crm_manager_plan_customers (slot_id, customer_id, source_seat_id, list_type)
        values (v_slot_id, v_cid, v_customer.seat_id, v_customer.list_type)
        on conflict do nothing;
      else
        -- His own list belongs to his single visits, and to him.
        if v_kind <> 'single_visit' then
          raise exception 'phoenix_crm:bad_input';
        end if;
        if not exists (
          select 1 from public.phoenix_crm_manager_customers m
          where m.id = v_mcid and m.manager_hr_id = v_manager and m.is_test = v_is_test and m.status <> 'removed'
        ) then
          raise exception 'phoenix_crm:manager_plan_customer_gone';
        end if;
        insert into public.phoenix_crm_manager_plan_customers (slot_id, manager_customer_id)
        values (v_slot_id, v_mcid)
        on conflict do nothing;
      end if;
    end loop;
  end if;

  -- The week follows who plans it now: a person whose post changed between two saves of an open week
  -- plans it under his new kind and seat (a send then refuses an Office half-day left on a district
  -- manager's week).
  update public.phoenix_crm_manager_plans pl
  set version = pl.version + 1,
      planner_kind = v_planner,
      manager_seat_id = v_seat,
      line_code = coalesce(v_line, pl.line_code),
      updated_at = now()
  where pl.id = v_plan.id
  returning pl.* into v_plan;

  return jsonb_build_object(
    'plan_id', v_plan.id,
    'version', v_plan.version,
    'status', v_plan.status,
    'week_start', v_plan.week_start,
    'planner_kind', v_plan.planner_kind,
    'slot_id', v_slot_id
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_save_manager_plan_slot(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_save_plan(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_save_plan(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_week date := nullif(p ->> 'week_start', '')::date;
  v_expected integer := nullif(p ->> 'expected_version', '')::integer;
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_days date[];
  v_plan public.phoenix_crm_plans%rowtype;
  v_items jsonb := p -> 'items';
  v_count integer;
begin
  if v_seat is null or v_line is null or v_actor is null or v_week is null
    or extract(isodow from v_week) <> 6
    or jsonb_typeof(v_items) is distinct from 'array'
    or jsonb_typeof(p -> 'editable_days') is distinct from 'array' then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select coalesce(array_agg(distinct d.value::date), '{}'::date[])
  into v_days
  from jsonb_array_elements_text(p -> 'editable_days') d;

  if exists (select 1 from unnest(v_days) d where d < v_today or d < v_week or d > v_week + 5) then
    raise exception 'phoenix_crm:day_not_editable';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:plan:' || v_seat || ':' || v_week::text));

  select pl.* into v_plan
  from public.phoenix_crm_plans pl
  where pl.seat_id = v_seat
    and pl.week_start = v_week
    and pl.is_test = v_is_test
  for update;

  if not found then
    if coalesce(v_expected, 0) <> 0 then
      raise exception 'phoenix_crm:version_conflict';
    end if;
    insert into public.phoenix_crm_plans (seat_id, line_code, week_start, status, version, created_by_hr_id, is_test)
    values (v_seat, v_line, v_week, 'draft', 1, v_actor, v_is_test)
    returning * into v_plan;

    insert into public.phoenix_crm_plan_events (plan_id, event_type, actor_hr_id, to_status, version)
    values (v_plan.id, 'created', v_actor, 'draft', 1);
  else
    if v_plan.status not in ('draft', 'returned') then
      raise exception 'phoenix_crm:not_editable';
    end if;
    if v_expected is distinct from v_plan.version then
      raise exception 'phoenix_crm:version_conflict';
    end if;
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_items) as x (plan_date date)
    where x.plan_date is null or not (x.plan_date = any (v_days))
  ) then
    raise exception 'phoenix_crm:day_not_editable';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_items) as x (customer_id uuid, place_id uuid, list_type text)
    where not exists (
      select 1
      from public.phoenix_crm_customers c
      where c.id = x.customer_id
        and c.seat_id = v_seat
        and c.is_test = v_is_test
        and c.status in ('active', 'pending')
        -- The session an item is filed in is the SEATING's when the place is seated in a polyclinic or
        -- centre (owner, 2026-10-10), otherwise the customer's own list, as before.
        and x.list_type = coalesce(
          (select pl.session from public.phoenix_crm_places pl where pl.id = x.place_id and pl.customer_id = c.id),
          c.list_type
        )
    )
  ) then
    raise exception 'phoenix_crm:customer_not_on_list';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_items) as x (customer_id uuid, place_id uuid)
    where x.place_id is not null
      and not exists (
        select 1
        from public.phoenix_crm_places pl
        where pl.id = x.place_id
          and pl.customer_id = x.customer_id
          and pl.status = 'active'
      )
  ) then
    raise exception 'phoenix_crm:place_changed';
  end if;

  delete from public.phoenix_crm_plan_items i
  where i.plan_id = v_plan.id
    and i.plan_date = any (v_days)
    and not exists (
      select 1
      from jsonb_to_recordset(v_items) as x (plan_date date, customer_id uuid)
      where x.plan_date = i.plan_date
        and x.customer_id = i.customer_id
    );

  insert into public.phoenix_crm_plan_items as t (
    plan_id, plan_date, customer_id, place_id, list_type, receives, start_minute, exception_type, exception_note
  )
  select distinct on (x.plan_date, x.customer_id)
    v_plan.id,
    x.plan_date,
    x.customer_id,
    x.place_id,
    x.list_type,
    coalesce(x.receives, false),
    x.start_minute,
    nullif(x.exception_type, ''),
    nullif(trim(coalesce(x.exception_note, '')), '')
  from jsonb_to_recordset(v_items) as x (
    plan_date date,
    customer_id uuid,
    place_id uuid,
    list_type text,
    receives boolean,
    start_minute integer,
    exception_type text,
    exception_note text
  )
  order by x.plan_date, x.customer_id
  on conflict (plan_id, plan_date, customer_id) do update
    set place_id = excluded.place_id,
        list_type = excluded.list_type,
        receives = excluded.receives,
        start_minute = excluded.start_minute,
        exception_type = excluded.exception_type,
        exception_note = excluded.exception_note,
        updated_at = now()
    -- An item sent back exactly as it is stored is left as it is (2026-10-16): every save carries every
    -- item of the open days, and rewriting the unchanged ones was most of a save's work.
    where (t.place_id, t.list_type, t.receives, t.start_minute, t.exception_type, t.exception_note)
      is distinct from
      (excluded.place_id, excluded.list_type, excluded.receives, excluded.start_minute, excluded.exception_type, excluded.exception_note);

  select count(*)::integer into v_count from public.phoenix_crm_plan_items i where i.plan_id = v_plan.id;

  update public.phoenix_crm_plans pl
  set version = pl.version + 1, updated_at = now()
  where pl.id = v_plan.id
  returning pl.* into v_plan;

  insert into public.phoenix_crm_plan_events (plan_id, event_type, actor_hr_id, from_status, to_status, version, details)
  values (
    v_plan.id, 'saved', v_actor, v_plan.status, v_plan.status, v_plan.version,
    -- A save never changes the week's status, so on a week returned for ONE day this event is the
    -- latest and must still name that day: every reader that takes "the latest event" (the visit
    -- save's Still planned test, the plan-vs-actual reads) would otherwise lose the one-day return
    -- and stamp the week's OTHER days off-plan the moment the rep saves his returned day.
    jsonb_build_object('items', v_count, 'days', to_jsonb(v_days))
      || case
           when v_plan.status = 'returned' and v_plan.returned_day is not null
             then jsonb_build_object('returned_day', v_plan.returned_day)
           else '{}'::jsonb
         end
  );

  return jsonb_build_object('plan_id', v_plan.id, 'status', v_plan.status, 'version', v_plan.version, 'item_count', v_count);
end;
$$;

ALTER FUNCTION public.phoenix_crm_save_plan(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_save_plan_activities(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_save_plan_activities(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_week date := nullif(p ->> 'week_start', '')::date;
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_items jsonb := coalesce(p -> 'activities', '[]'::jsonb);
  v_days date[];
  v_plan public.phoenix_crm_plans%rowtype;
  v_count integer;
begin
  if v_seat is null or v_actor is null or v_week is null
    or extract(isodow from v_week) <> 6
    or jsonb_typeof(v_items) is distinct from 'array'
    or jsonb_typeof(p -> 'editable_days') is distinct from 'array' then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select coalesce(array_agg(distinct d.value::date), '{}'::date[])
  into v_days
  from jsonb_array_elements_text(p -> 'editable_days') d;

  if exists (select 1 from unnest(v_days) d where d < v_today or d < v_week or d > v_week + 5) then
    raise exception 'phoenix_crm:day_not_editable';
  end if;
  if exists (
    select 1
    from jsonb_to_recordset(v_items) as x (plan_date date, activity_type text, note text)
    where x.plan_date is null or not (x.plan_date = any (v_days))
      or x.activity_type not in ('meeting', 'training', 'conference', 'admin_work', 'travel', 'health_day', 'sales_day', 'rtd', 'group_meeting', 'interviews')
      or (x.note is not null and char_length(x.note) > 300)
  ) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:plan:' || v_seat || ':' || v_week::text));

  select pl.* into v_plan
  from public.phoenix_crm_plans pl
  where pl.seat_id = v_seat
    and pl.week_start = v_week
    and pl.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:plan_not_found';
  end if;
  if v_plan.status not in ('draft', 'returned') then
    raise exception 'phoenix_crm:not_editable';
  end if;

  -- A kind the list no longer holds for its day comes off; the other kinds on that day stay.
  delete from public.phoenix_crm_plan_activities a
  where a.plan_id = v_plan.id
    and a.plan_date = any (v_days)
    and not exists (
      select 1
      from jsonb_to_recordset(v_items) as x (plan_date date, activity_type text)
      where x.plan_date = a.plan_date
        and x.activity_type = a.activity_type
    );

  -- One of each kind a day: a kind sent twice for one day is kept once, never a reason to lose the plan.
  insert into public.phoenix_crm_plan_activities (plan_id, plan_date, activity_type, half_day, note)
  select distinct on (x.plan_date, x.activity_type)
    v_plan.id, x.plan_date, x.activity_type, coalesce(x.half_day, false), nullif(trim(coalesce(x.note, '')), '')
  from jsonb_to_recordset(v_items) as x (plan_date date, activity_type text, half_day boolean, note text)
  order by x.plan_date, x.activity_type
  on conflict (plan_id, plan_date, activity_type) do update
    set half_day = excluded.half_day,
        note = excluded.note,
        updated_at = now();

  select count(*)::integer into v_count from public.phoenix_crm_plan_activities a where a.plan_id = v_plan.id;

  return jsonb_build_object('plan_id', v_plan.id, 'activity_count', v_count);
end;
$$;

ALTER FUNCTION public.phoenix_crm_save_plan_activities(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_save_plan_day_starts(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_save_plan_day_starts(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_week date := nullif(p ->> 'week_start', '')::date;
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_items jsonb := coalesce(p -> 'starts', '[]'::jsonb);
  v_days date[];
  v_plan public.phoenix_crm_plans%rowtype;
  v_count integer;
begin
  if v_seat is null or v_actor is null or v_week is null
    or extract(isodow from v_week) <> 6
    or jsonb_typeof(v_items) is distinct from 'array'
    or jsonb_typeof(p -> 'editable_days') is distinct from 'array' then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select coalesce(array_agg(distinct d.value::date), '{}'::date[])
  into v_days
  from jsonb_array_elements_text(p -> 'editable_days') d;

  if exists (select 1 from unnest(v_days) d where d < v_today or d < v_week or d > v_week + 5) then
    raise exception 'phoenix_crm:day_not_editable';
  end if;
  if exists (
    select 1
    from jsonb_to_recordset(v_items) as x (plan_date date, start_am_minute integer, start_pm_minute integer)
    where x.plan_date is null or not (x.plan_date = any (v_days))
      or (x.start_am_minute is not null and x.start_am_minute not between 0 and 1439)
      or (x.start_pm_minute is not null and x.start_pm_minute not between 0 and 1439)
  ) then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:plan:' || v_seat || ':' || v_week::text));

  select pl.* into v_plan
  from public.phoenix_crm_plans pl
  where pl.seat_id = v_seat
    and pl.week_start = v_week
    and pl.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:plan_not_found';
  end if;
  if v_plan.status not in ('draft', 'returned') then
    raise exception 'phoenix_crm:not_editable';
  end if;

  delete from public.phoenix_crm_plan_day_starts s
  where s.plan_id = v_plan.id
    and s.plan_date = any (v_days)
    and not exists (
      select 1
      from jsonb_to_recordset(v_items) as x (plan_date date, start_am_minute integer, start_pm_minute integer)
      where x.plan_date = s.plan_date
        and (x.start_am_minute is not null or x.start_pm_minute is not null)
    );

  insert into public.phoenix_crm_plan_day_starts (plan_id, plan_date, start_am_minute, start_pm_minute)
  select distinct on (x.plan_date)
    v_plan.id, x.plan_date, x.start_am_minute, x.start_pm_minute
  from jsonb_to_recordset(v_items) as x (plan_date date, start_am_minute integer, start_pm_minute integer)
  where x.start_am_minute is not null or x.start_pm_minute is not null
  order by x.plan_date
  on conflict (plan_id, plan_date) do update
    set start_am_minute = excluded.start_am_minute,
        start_pm_minute = excluded.start_pm_minute,
        updated_at = now();

  select count(*)::integer into v_count from public.phoenix_crm_plan_day_starts s where s.plan_id = v_plan.id;

  return jsonb_build_object('plan_id', v_plan.id, 'start_count', v_count);
end;
$$;

ALTER FUNCTION public.phoenix_crm_save_plan_day_starts(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_save_visit(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_save_visit(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_kind text := coalesce(p ->> 'kind', '');
  v_rep text := upper(nullif(trim(coalesce(p ->> 'rep_hr_id', '')), ''));
  v_manager text := upper(nullif(trim(coalesce(p ->> 'manager_hr_id', '')), ''));
  v_senior text := upper(nullif(trim(coalesce(p ->> 'senior_hr_id', '')), ''));
  -- The line's product manager who came along (owner, 2026-10-02). WHETHER he is one of the line's is
  -- settled by the caller before it gets here: he holds no seat in the organogram, so there is nothing
  -- in this database to check him against (src/lib/phoenix-crm/server/visits.ts loadLineProductManagers).
  v_product_manager text := upper(nullif(trim(coalesce(p ->> 'product_manager_hr_id', '')), ''));
  -- Optional since 2026-09-29: the one-tap Log visit sends none, and the server's clock dates it.
  v_photo text := nullif(trim(coalesce(p ->> 'photo_path', '')), '');
  v_reuse boolean := coalesce((p ->> 'reuse_place_photo')::boolean, false);
  v_place_id uuid := nullif(p ->> 'place_id', '')::uuid;
  v_list_type text;
  v_flag text := coalesce(p ->> 'location_flag', '');
  v_comment text := nullif(trim(coalesce(p ->> 'comment', '')), '');
  v_pharmacy text := nullif(trim(coalesce(p ->> 'pharmacy_name', '')), '');
  v_availability jsonb := coalesce(p -> 'product_availability', '{}'::jsonb);
  -- E2: what he handed over. Narrowed to the line's own products by the caller, exactly as
  -- product_availability is; here it only has to be a bag and not too big a one.
  v_samples jsonb := coalesce(p -> 'samples_given', '{}'::jsonb);
  -- D3: digits only, so a phone sending "abc" lands as null rather than raising. `::integer` on a
  -- free-text value would abort the whole save, and no rep loses a visit over a stopwatch.
  v_form_open integer := least(
    coalesce(nullif(regexp_replace(coalesce(p ->> 'form_open_seconds', ''), '[^0-9]', '', 'g'), '')::bigint, 0),
    7200
  )::integer;
  v_dwell integer;
  v_voice text := nullif(trim(coalesce(p ->> 'voice_note_path', '')), '');
  v_voice_seconds integer := nullif(p ->> 'voice_note_seconds', '')::integer;
  v_voice_bytes integer := nullif(p ->> 'voice_note_bytes', '')::integer;
  -- The rep's "why I went", and where his approval starts when he went off plan.
  v_clarification text := nullif(regexp_replace(trim(coalesce(p ->> 'unplanned_reason', '')), '\s+', ' ', 'g'), '');
  -- E3: the outcome. Read here and validated below rather than trusted, because the ONLY thing the
  -- caller is allowed to do with a value it does not recognise is drop it.
  v_next_step text := nullif(btrim(p ->> 'next_step'), '');
  v_next_step_on date := nullif(p ->> 'next_step_on', '')::date;
  v_objection text := nullif(btrim(p ->> 'objection'), '');
  v_objection_note text := nullif(regexp_replace(trim(coalesce(p ->> 'objection_note', '')), '\s+', ' ', 'g'), '');
  v_first_stage text := coalesce(p ->> 'unplanned_first_status', 'manager_pending');
  v_reviewer text := upper(nullif(trim(coalesce(p ->> 'reviewer_hr_id', '')), ''));
  v_on_sent_plan boolean;
  v_unplanned_kind text;
  v_products text[];
  v_existing public.phoenix_crm_visits%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_captured_at timestamptz;
  v_date date;
  -- A1: the offline path. `offline_captured_at` is derived IN TYPESCRIPT by
  -- src/lib/phoenix-crm/offline-clock.ts from a server-minted anchor plus elapsed MONOTONIC time,
  -- and passed in by saveVisit. 🔴 It is NEVER copied from the request body — the phone sends a
  -- duration and an anchor id, never a timestamp. The two bounds below are a second fence here.
  v_offline_at timestamptz := nullif(p ->> 'offline_captured_at', '')::timestamptz;
  v_anchor_id uuid := nullif(p ->> 'time_anchor_id', '')::uuid;
  v_offline_seconds integer;
  v_source text := 'server';
  -- The pharmacies NAMED on this visit are visits to those pharmacies too (owner, 2026-10-03). WHICH
  -- pharmacy on his list each name is was decided by the caller (pharmacy-call-rules.ts
  -- splitNamedPharmacies, then linkNamedPharmacy for each name, where both are tested); here each is
  -- only checked to be his, and filed. ONE BOX CAN NAME TWO PHARMACIES ("صيدليه التهامي، صيدليه الرحمه",
  -- 2026-10-03): the caller sends one entry per name in `linked_pharmacies`. A caller from before this
  -- sends one match as linked_pharmacy_id / linked_pharmacy_new — read below as a list of one, named
  -- with the whole box, exactly as 20261003175653 filed it.
  v_links jsonb;
  v_entry jsonb;
  v_entry_name text;
  v_entry_id uuid;
  v_entry_new boolean;
  v_link public.phoenix_crm_customers%rowtype;
  v_link_visit uuid;
  v_link_created boolean;
  v_filed jsonb := '[]'::jsonb;
  v_is_pharmacy boolean;
begin
  if v_id is null or v_seat is null or v_line is null or v_actor is null or v_customer_id is null
    or v_kind not in ('single', 'double', 'product_manager', 'chain')
    or v_flag not in ('ok', 'far', 'weak_gps', 'no_place')
    or v_first_stage not in ('manager_pending', 'sfe_pending')
    or (v_pharmacy is not null and char_length(v_pharmacy) > 120)
    or (v_reuse and v_photo is null) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if jsonb_typeof(v_availability) <> 'object' then
    v_availability := '{}'::jsonb;
  end if;
  -- E2: dropped, never raised. A bag of junk keys costs the rep nothing; the column's own CHECK
  -- would otherwise refuse the whole visit over a field that is not the visit.
  if jsonb_typeof(v_samples) <> 'object' or (select count(*) from jsonb_object_keys(v_samples)) > 20 then
    v_samples := '{}'::jsonb;
  end if;

  -- E3: an unknown value is DROPPED, never raised. The dependants go with their parent, so the row
  -- can never say "by 30 Sept" under "Nothing to follow".
  if v_next_step is not null and v_next_step not in ('follow_up', 'send_data', 'arrange_double', 'invite_event', 'pharmacy_stock', 'none') then
    v_next_step := null;
  end if;
  if v_next_step is null or v_next_step = 'none' then
    v_next_step_on := null;
  end if;
  if v_objection is not null and v_objection not in ('price', 'efficacy', 'safety', 'competitor', 'formulary', 'no_time', 'none') then
    v_objection := null;
  end if;
  if v_objection is null or v_objection = 'none' then
    v_objection_note := null;
  else
    v_objection_note := left(v_objection_note, 300);
  end if;
  -- A product manager rides in his OWN slot and in no other: never as the manager, which is the
  -- district manager and is what every board counts `double_visits` from, and never on a kind that did
  -- not ask for him. 2026-10-27 (owner: "Everything is applicable"): a CHAIN is the rep, a manager and
  -- AT LEAST one more — the manager above him, a product-side person, or both. Everyone past the three
  -- fixed places is in phoenix_crm_visit_companions, written right after the visit below.
  if not (
    (v_kind = 'single' and v_senior is null and ((v_rep is null) <> (v_manager is null)))
    or (v_kind = 'double' and v_rep is not null and v_manager is not null and v_senior is null)
    or (v_kind = 'chain' and v_rep is not null and v_manager is not null and (v_senior is not null or v_product_manager is not null))
    or (v_kind = 'product_manager' and v_rep is not null and v_manager is null and v_senior is null and v_product_manager is not null)
  ) or (v_kind not in ('product_manager', 'chain') and v_product_manager is not null)
    or (v_product_manager is not null and v_product_manager = coalesce(v_rep, '')) then
    raise exception 'phoenix_crm:bad_participants';
  end if;

  select array_agg(trim(e.value) order by e.ordinality)
  into v_products
  from jsonb_array_elements_text(coalesce(p -> 'products', '[]'::jsonb)) with ordinality as e (value, ordinality)
  where nullif(trim(e.value), '') is not null;
  if v_products is null or cardinality(v_products) > 12 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select v.* into v_existing from public.phoenix_crm_visits v where v.id = v_id;
  if not found then
    perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));
    -- A retry racing its own first attempt waits on the lock, then finds it here.
    select v.* into v_existing from public.phoenix_crm_visits v where v.id = v_id;
  end if;
  if found then
    if v_existing.seat_id <> v_seat or v_existing.entered_by_hr_id <> v_actor then
      raise exception 'phoenix_crm:id_conflict';
    end if;
    return jsonb_build_object(
      'id', v_existing.id,
      'visit_date', v_existing.visit_date,
      'captured_at', v_existing.captured_at,
      'customer_id', v_existing.customer_id,
      'is_unplanned', v_existing.is_unplanned,
      'unplanned_kind', v_existing.unplanned_kind,
      'duplicate', true
    );
  end if;

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id
    and c.seat_id = v_seat
    and c.is_test = v_is_test;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  -- A pending customer (carried over, not validated yet) and one met outside the list (validated at
  -- the door, waiting to be admitted) are both real, visitable customers. Only a customer in the
  -- Archive is refused here — "This customer has left the list."
  if v_customer.status not in ('active', 'pending', 'outside') then
    raise exception 'phoenix_crm:customer_dropped';
  end if;
  v_is_pharmacy := v_customer.list_type = 'Pharmacy';
  -- A pharmacy's own visit is named after the pharmacy (owner, 2026-10-03), so the day's Pharmacies
  -- figure — distinct pharmacy names — counts it, and counts it ONCE beside a doctor's visit that named
  -- the same pharmacy. A name the phone sent for it is not used: the pharmacy is the customer.
  if v_is_pharmacy then
    v_pharmacy := left(v_customer.name, 120);
  end if;
  if v_place_id is not null and not exists (
    select 1 from public.phoenix_crm_places pl where pl.id = v_place_id and pl.customer_id = v_customer.id
  ) then
    raise exception 'phoenix_crm:place_changed';
  end if;

  -- WHICH LIST THE VISIT COUNTS IN (owner, 2026-10-10). A visit at a place seated in a polyclinic or
  -- centre counts in that SEATING's session, AM or PM; every other visit counts in the customer's list.
  -- The visit's list_type is what every board reads, so AM and PM KPIs follow the session he planned.
  v_list_type := coalesce(
    (select pl.session from public.phoenix_crm_places pl where pl.id = v_place_id and pl.customer_id = v_customer.id),
    v_customer.list_type
  );

  if v_photo is null then
    -- THE ONE-TAP VISIT (owner, 2026-09-29): no photo, and the server's own clock dates it at the
    -- moment it arrives. The phone never states a time.
    v_captured_at := now();
    v_source := 'server';
  elsif v_reuse then
    select pl.captured_at into v_captured_at
    from public.phoenix_crm_places pl
    where pl.photo_path = v_photo
      and pl.customer_id = v_customer.id
      and pl.created_by_hr_id = v_actor
      and pl.is_test = v_is_test
      and pl.created_at > now() - interval '30 minutes';
    if not found then
      raise exception 'phoenix_crm:photo_not_issued';
    end if;
    if exists (select 1 from public.phoenix_crm_visits v where v.photo_path = v_photo) then
      raise exception 'phoenix_crm:photo_used';
    end if;
    v_source := 'slot';
  else
    v_captured_at := public.phoenix_crm_take_photo(v_photo, v_actor, v_seat, 'visit', v_is_test);
    v_source := 'slot';
  end if;

  -- 🔴 A PHOTO SLOT CANNOT REACH BACK PAST 02:00 INTO YESTERDAY'S VISIT DAY (2026-10-02).
  --
  -- A visit slot lives two hours (phoenix_crm_take_photo) and a reused place photo adds its own
  -- thirty-minute window on top of that, so a save arriving at 02:30 can carry an issue time of
  -- 01:00 — and THE VISIT DAY ENDS AT 02:00 (owner, 2026-09-29), so the row would be filed, counted
  -- and read as YESTERDAY's: a day whose plan is closed and whose figures have been read. A slot
  -- proves WHEN THE PHOTO WAS TAKEN. It was never evidence of which day the work belongs to, and the
  -- one-a-day key, the planned-or-not verdict and every report follow visit_date.
  --
  -- The offline anchor is the ONE path allowed to reach back, and it earns it twice over: the server
  -- brackets the claim at BOTH ends with its own two readings, and only the app can make the claim at
  -- all (src/lib/phoenix-crm/server/capture-client.ts).
  --
  -- Silently, never as a refusal (Golden Rule #1): the visit is real, so it is dated at arrival. The
  -- row then reads capture_source 'server' beside a photo_path, which is how the board can see that
  -- the slot's own time was not used — and dwell_seconds stays null rather than a made-up zero.
  if v_source = 'slot'
     and ((v_captured_at - interval '2 hours') at time zone 'Africa/Cairo')::date
       < ((now() - interval '2 hours') at time zone 'Africa/Cairo')::date then
    v_captured_at := now();
    v_source := 'server';
  end if;

  -- A1 · THE OFFLINE CAPTURE TIME. Two fences, both one-sided in the safe direction: never later than
  -- now(), never older than a day. Outside them the value is DROPPED and the visit is dated at arrival
  -- — never refused, and never explained to the rep.
  if v_offline_at is not null
     and v_offline_at <= now()
     and v_offline_at > now() - interval '1 day' then
    v_offline_seconds := greatest(floor(extract(epoch from (now() - v_offline_at)))::bigint, 0)::integer;
    v_captured_at := v_offline_at;
    v_source := 'offline_anchor';
  end if;

  -- THE VISIT DAY ENDS AT 02:00 (owner, 2026-09-29): "the visits of today are entered today, maximum
  -- 2 AM". A visit logged at 01:30 on Tuesday is Monday's; one at 02:00 is Tuesday's. The same
  -- arithmetic is src/lib/phoenix-crm/calendar.ts cairoBusinessDay, pinned by a test on both sides.
  v_date := ((v_captured_at - interval '2 hours') at time zone 'Africa/Cairo')::date;

  -- D3: how long the door photo has been in hand. Meaningful only when a photo slot dated the visit
  -- and the save followed the shutter by seconds — so NULL for the one-tap visit and for an offline
  -- one, never a number made up for them.
  v_dwell := case
    when v_source <> 'slot' then null
    else least(greatest(floor(extract(epoch from (now() - v_captured_at)))::bigint, 0), 7200)::integer
  end;

  if exists (
    select 1
    from public.phoenix_crm_visits v
    where v.seat_id = v_seat
      and v.customer_id = v_customer.id
      and v.visit_date = v_date
      and v.is_test = v_is_test
  ) then
    raise exception 'phoenix_crm:already_visited';
  end if;

  -- WAS HE PLANNED? The plan's status AS OF this visit's server-issued captured_at — the latest event
  -- wins, the shape phoenix_crm_report_plan_vs_actual's own sent_days uses. A draft or returned plan
  -- is the rep's to edit and is never authority. A manager's own single visit (no rep on it) was never
  -- on anybody's plan and belongs to nobody's call rate, so it is never raised for approval.
  --
  -- STILL PLANNED (owner, 2026-10-02). A week a reviewer returned for ONE day is still authority on
  -- every OTHER day: only the returned day waits for the rep to send the week again. That return is the
  -- latest event — to 'returned', with `returned_day` in its details (phoenix_crm_plan_transition) — and
  -- it counts for the days it left as sent until an edit request is acknowledged AFTER it: that
  -- acknowledgement opens the whole week to the rep (plan-rules.ts `standingReturnedDay`), and a day he
  -- can change is never authority. A week returned whole carries no day, and stays no authority at all.
  -- plan-rules.ts `planDayStatus` is this rule for every screen that asks.
  v_on_sent_plan := v_is_pharmacy or v_rep is null or exists (
    select 1
    from public.phoenix_crm_plans pl
    join public.phoenix_crm_plan_items i on i.plan_id = pl.id
    where pl.seat_id = v_seat
      and pl.is_test = v_is_test
      and i.plan_date = v_date
      and i.customer_id = v_customer.id
      and (
        select e.to_status
        from public.phoenix_crm_plan_events e
        where e.plan_id = pl.id
          and e.to_status is not null
          and e.created_at <= v_captured_at
        order by e.created_at desc, e.id desc
        limit 1
      ) in ('submitted', 'approved')
  ) or exists (
    select 1
    from public.phoenix_crm_plans pl
    join public.phoenix_crm_plan_items i on i.plan_id = pl.id
    where pl.seat_id = v_seat
      and pl.is_test = v_is_test
      and i.plan_date = v_date
      and i.customer_id = v_customer.id
      and v_date <> (
        select case
          when e.to_status = 'returned'
            and not exists (
              select 1
              from public.phoenix_crm_plan_edit_requests r
              where r.plan_id = pl.id
                and r.hr_acknowledged_at > e.created_at
                and r.hr_acknowledged_at <= v_captured_at
            )
          then nullif(e.details ->> 'returned_day', '')::date
        end
        from public.phoenix_crm_plan_events e
        where e.plan_id = pl.id
          and e.to_status is not null
          and e.created_at <= v_captured_at
        order by e.created_at desc, e.id desc
        limit 1
      )
  );

  -- Out of list: a customer the rep met and validated at the door. The district manager and SFE
  -- approve the CUSTOMER, not this visit, so no reason is asked and no approval row is raised; the
  -- visit counts once he is admitted, because every report joins his validated_at.
  --
  -- 🔴 A PHARMACY IS NEVER OUT OF PLAN, NEVER OUT OF LIST AND NEVER APPROVED (owner, 2026-10-02: "no
  -- approval for an unplanned pharmacy visit"; 2026-10-03: "Pharmacy don't need a validation. It is
  -- visit is logged normally."). Until 2026-10-03 this block filed EVERY pharmacy visit out_of_plan —
  -- a reason, then the manager and SFE — because a pharmacy is never on a plan; not one rep ever saved
  -- one. It is filed as planned whatever its status, and counts the moment it is saved.
  if v_is_pharmacy then
    v_on_sent_plan := true;
    v_unplanned_kind := null;
  elsif v_customer.status = 'outside' then
    v_on_sent_plan := false;
    v_unplanned_kind := 'out_of_list';
  elsif not v_on_sent_plan then
    v_unplanned_kind := 'out_of_plan';
    -- OPTIONAL (owner, 2026-10-29): a blank reason is null and the visit is still raised below for its
    -- approval; only a reason over the ceiling is refused.
    if v_clarification is not null and char_length(v_clarification) > 500 then
      raise exception 'phoenix_crm:clarification_required';
    end if;
  end if;

  -- The voice note, when there is one. It happens AFTER v_date is settled, so nothing it does can
  -- reach the date; phoenix_crm_take_voice returns VOID, so there is no value here to date it with.
  if v_voice is not null then
    perform public.phoenix_crm_take_voice(v_voice, v_actor, v_seat, v_is_test);
  end if;

  insert into public.phoenix_crm_visits (
    id, seat_id, line_code, customer_id, list_type, visit_date, captured_at, kind, rep_hr_id, manager_hr_id,
    senior_hr_id, product_manager_hr_id, entered_by_hr_id, products, comment, pharmacy_name, product_availability, photo_path, lat, lon,
    accuracy_meters, place_id, distance_meters, location_flag, device_skew_minutes, is_test,
    voice_note_path, voice_note_seconds, voice_note_bytes, is_unplanned, unplanned_kind,
    next_step, next_step_on, objection, objection_note,
    samples_given,
    dwell_seconds, form_open_seconds,
    capture_source, time_anchor_id, offline_seconds, synced_at,
    photo_lat, photo_lon, photo_accuracy_meters, photo_captured_at
  )
  values (
    v_id, v_seat, v_line, v_customer.id, v_list_type, v_date, v_captured_at, v_kind, v_rep, v_manager,
    v_senior, v_product_manager, v_actor, v_products, v_comment, v_pharmacy, v_availability, v_photo,
    (p ->> 'lat')::double precision,
    (p ->> 'lon')::double precision,
    (p ->> 'accuracy_meters')::numeric,
    v_place_id,
    (p ->> 'distance_meters')::integer,
    v_flag,
    (p ->> 'device_skew_minutes')::integer,
    v_is_test,
    v_voice, v_voice_seconds, v_voice_bytes, not v_on_sent_plan, v_unplanned_kind,
    v_next_step, v_next_step_on, v_objection, v_objection_note,
    v_samples,
    -- A zero form_open is "the page said nothing", not "he was there no time": stored as null.
    v_dwell, nullif(v_form_open, 0),
    -- synced_at is the server's own receipt and is stamped for EVERY visit.
    v_source, case when v_source = 'offline_anchor' then v_anchor_id else null end, v_offline_seconds, now(),
    -- The photo's own reading, when a photo was taken. NULL is NOT MEASURED, never "same place".
    (p ->> 'photo_lat')::double precision,
    (p ->> 'photo_lon')::double precision,
    (p ->> 'photo_accuracy_meters')::numeric,
    nullif(p ->> 'photo_captured_at', '')::timestamptz
  );

  -- Everyone who came, BEFORE the off-plan row below: its reviewer trigger reads this list.
  perform public.phoenix_crm_set_visit_companions(v_id, p -> 'companions');

  if v_unplanned_kind = 'out_of_plan' then
    insert into public.phoenix_crm_unplanned_visits (
      visit_id, seat_id, line_code, rep_hr_id, entered_by_hr_id, customer_id, visit_date,
      clarification, status, manager_hr_id, is_test
    )
    values (
      v_id, v_seat, v_line, coalesce(v_rep, v_actor), v_actor, v_customer.id, v_date,
      v_clarification, v_first_stage, v_reviewer, v_is_test
    );
    insert into public.phoenix_crm_unplanned_visit_events (visit_id, event_type, actor_hr_id, to_status, version, note)
    values (v_id, 'raised', v_actor, v_first_stage, 1, v_clarification);
  end if;

  -- 🔴 A PHARMACY NAMED ON A DOCTOR'S VISIT IS A VISIT TO THAT PHARMACY (owner, 2026-10-03: "consider
  -- this as a pharmacy visit and make it count everywhere"). He checks the pharmacy's stock beside the
  -- doctor and types its name on the doctor's visit; that pharmacy now gets its own visit, filed beside
  -- this one — same day, same time, same products.
  --   · it is a SINGLE visit by whoever's visit this is — the rep, or the manager on a visit of his own.
  --     A double, chain or product-manager visit is the doctor's: copying its people here would credit
  --     the manager with a second double visit for one stop (phoenix_crm_report_manager_visits counts
  --     every double and chain row);
  --   · it carries NO stock answers: they stay on the doctor's visit, where every stock reader has
  --     always found them by the pharmacy's name — a copy here would report each missing product twice;
  --   · the pharmacy must be HIS: this seat, this world, a pharmacy, not in the Archive. Anything else
  --     the caller sent is IGNORED, never raised: the doctor's visit is saved whatever becomes of it;
  --   · nothing on his list matched → it is added to his list (new, pending — a pharmacy needs no
  --     validation), and visited;
  --   · one a day, like every customer: a pharmacy already visited today keeps the visit it has;
  --   · ONE BOX, TWO PHARMACIES — "صيدليه التهامي، صيدليه الرحمه": each name is its own pharmacy and
  --     gets its own visit, named as he spelled it. Five at most; a name the caller could not place is
  --     skipped, never raised.
  -- It has no photo and no place reading of its own — nobody stood at the pharmacy with a phone for it
  -- — so the location report and the behaviour sweep leave it out by linked_from_visit_id.
  if not v_is_pharmacy and v_pharmacy is not null then
    v_links := case
      when jsonb_typeof(p -> 'linked_pharmacies') = 'array' then p -> 'linked_pharmacies'
      else jsonb_build_array(jsonb_build_object(
        'name', v_pharmacy,
        'id', nullif(p ->> 'linked_pharmacy_id', ''),
        'new', coalesce((p ->> 'linked_pharmacy_new')::boolean, false)
      ))
    end;

    for v_entry in
      select e.value from jsonb_array_elements(v_links) with ordinality as e(value, n) order by e.n limit 5
    loop
      v_entry_name := nullif(trim(coalesce(v_entry ->> 'name', '')), '');
      v_entry_id := case
        when (v_entry ->> 'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (v_entry ->> 'id')::uuid
      end;
      v_entry_new := coalesce((v_entry ->> 'new') = 'true', false);
      v_link := null;
      v_link_visit := null;
      v_link_created := false;
      continue when v_entry_name is null or char_length(v_entry_name) > 120;

      if v_entry_id is not null then
        select c.* into v_link
        from public.phoenix_crm_customers c
        where c.id = v_entry_id
          and c.seat_id = v_seat
          and c.is_test = v_is_test
          and c.list_type = 'Pharmacy'
          and c.status in ('active', 'pending', 'outside');
      elsif v_entry_new then
        -- The caller decided "new" from a read taken before this call, so the name is checked again
        -- here, under the SAME lock phoenix_crm_add_pharmacy takes: two saves naming one new pharmacy,
        -- or a save racing Add a pharmacy, file one pharmacy, never two rows for it.
        perform pg_advisory_xact_lock(hashtext('phoenix_crm_add_pharmacy|' || v_seat || '|' || v_is_test::text));
        select c.* into v_link
        from public.phoenix_crm_customers c
        where c.seat_id = v_seat
          and c.is_test = v_is_test
          and c.list_type = 'Pharmacy'
          and c.status in ('active', 'pending', 'outside')
          and lower(btrim(regexp_replace(c.name, '\s+', ' ', 'g'))) = lower(btrim(regexp_replace(v_entry_name, '\s+', ' ', 'g')))
        order by (c.status = 'active') desc, c.id
        limit 1;
        if v_link.id is null then
          insert into public.phoenix_crm_customers (
            seat_id, line_code, list_type, name, origin, status, created_by_hr_id, is_test, intake_note
          )
          values (
            v_seat, v_customer.line_code, 'Pharmacy', v_entry_name, 'new', 'pending', v_actor, v_is_test,
            left('Added when the visit to ' || v_customer.name || ' named it.', 300)
          )
          returning * into v_link;
          v_link_created := true;
        end if;
      end if;

      if v_link.id is not null then
        insert into public.phoenix_crm_visits (
          id, seat_id, line_code, customer_id, list_type, visit_date, captured_at, kind, rep_hr_id, manager_hr_id,
          senior_hr_id, product_manager_hr_id, entered_by_hr_id, products, comment, pharmacy_name, product_availability,
          lat, lon, accuracy_meters, place_id, distance_meters, location_flag, is_test,
          is_unplanned, unplanned_kind, samples_given,
          capture_source, time_anchor_id, offline_seconds, synced_at,
          linked_from_visit_id
        )
        values (
          gen_random_uuid(), v_seat, v_line, v_link.id, 'Pharmacy', v_date, v_captured_at, 'single', v_rep,
          case when v_rep is null then v_manager end,
          null, null, v_actor, v_products, null, v_entry_name, '{}'::jsonb,
          (p ->> 'lat')::double precision,
          (p ->> 'lon')::double precision,
          (p ->> 'accuracy_meters')::numeric,
          null, null, 'no_place', v_is_test,
          false, null, '{}'::jsonb,
          v_source, case when v_source = 'offline_anchor' then v_anchor_id else null end, v_offline_seconds, now(),
          v_id
        )
        on conflict (seat_id, customer_id, visit_date, is_test) do nothing
        returning id into v_link_visit;
        v_filed := v_filed || jsonb_build_array(jsonb_build_object(
          'customer_id', v_link.id, 'name', v_link.name, 'visit_id', v_link_visit, 'created', v_link_created
        ));
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'id', v_id,
    'visit_date', v_date,
    'captured_at', v_captured_at,
    'customer_id', v_customer.id,
    'customer_name', v_customer.name,
    'list_type', v_list_type,
    'is_unplanned', not v_on_sent_plan,
    'unplanned_kind', v_unplanned_kind,
    'capture_source', v_source,
    -- The first one filed, as before, for a caller that reads one; every one of them beside it.
    'linked_pharmacy', v_filed -> 0,
    'linked_pharmacies', v_filed,
    'duplicate', false
  );
end;
$_$;

ALTER FUNCTION public.phoenix_crm_save_visit(p jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_save_visit(p jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_save_visit(p jsonb) IS 'The ONE writer of a Phoenix CRM visit. Since 2026-10-02 a visit whose PHOTO SLOT would date it on an earlier visit day than the save arrived on is dated at arrival instead (capture_source server), silently: a slot lives two hours and a reused place photo longer, and the 02:00 cutoff made that a visit filed as yesterday''s. The offline anchor still dates a visit before arrival, which is what it is for.';

--
-- Name: phoenix_crm_seat_places_in_venue(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_seat_places_in_venue(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_reason text := nullif(regexp_replace(trim(coalesce(p ->> 'reason', '')), '\s+', ' ', 'g'), '');
  v_ids jsonb := case when jsonb_typeof(p -> 'place_ids') = 'array' then p -> 'place_ids' end;
  v_venue public.phoenix_crm_shared_places%rowtype;
  v_place public.phoenix_crm_places%rowtype;
  v_after public.phoenix_crm_places%rowtype;
  v_customer public.phoenix_crm_customers%rowtype;
  v_pid uuid;
  v_photo text;
  v_kept_photo boolean;
  v_seated jsonb := '[]'::jsonb;
  v_held jsonb := '[]'::jsonb;
begin
  if v_seat is null or v_actor is null or nullif(p ->> 'shared_place_id', '') is null or v_ids is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  -- He picks the building, then ticks the doctors, so an empty tick-list is its own sentence rather
  -- than "something in this entry is missing".
  if jsonb_array_length(v_ids) = 0 then
    raise exception 'phoenix_crm:no_places_chosen';
  end if;
  -- One rep's whole standalone book is 59 places at the widest point on production today. 60 is a
  -- ceiling on a hand-ticked list, not a business rule.
  if jsonb_array_length(v_ids) > 60 then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_reason is null or char_length(v_reason) < 10 or char_length(v_reason) > 500 then
    raise exception 'phoenix_crm:move_reason_required';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  -- The same three refusals `sharedPlaceForSeating` gives, repeated under the venue's row lock so a
  -- phone cannot get round them: gone, removed, or still being checked.
  select sp.* into v_venue
  from public.phoenix_crm_shared_places sp
  where sp.id = (p ->> 'shared_place_id')::uuid
    and sp.seat_id = v_seat
    and sp.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:shared_place_not_found';
  end if;
  if v_venue.status = 'retired' then
    raise exception 'phoenix_crm:shared_place_retired';
  end if;
  if v_venue.status <> 'active' then
    raise exception 'phoenix_crm:shared_place_held';
  end if;

  for v_pid in select distinct (value #>> '{}')::uuid from jsonb_array_elements(v_ids)
  loop
    select pl.* into v_place
    from public.phoenix_crm_places pl
    where pl.id = v_pid
      and pl.seat_id = v_seat
      and pl.is_test = v_is_test
    for update;
    if not found then
      raise exception 'phoenix_crm:place_not_found';
    end if;
    if v_place.status <> 'active' then
      raise exception 'phoenix_crm:place_retired';
    end if;
    -- A place already inside a building is never re-seated: its point is that building's, and moving
    -- it again would overwrite the audit of where it came from with a point that is not its own.
    if v_place.shared_place_id is not null then
      raise exception 'phoenix_crm:already_in_a_venue';
    end if;

    select c.* into v_customer
    from public.phoenix_crm_customers c
    where c.id = v_place.customer_id
    for update;
    if not found then
      raise exception 'phoenix_crm:customer_not_found';
    end if;
    if v_customer.status = 'dropped' then
      raise exception 'phoenix_crm:customer_dropped';
    end if;
    -- 🔴 A seated place carries the AM or PM session its customer's list follows
    -- (`phoenix_crm_places_seated_has_session`, found on staging). A pharmacy has neither, so it is
    -- never seated in a building.
    if v_customer.list_type not in ('AM', 'PM') then
      raise exception 'phoenix_crm:pharmacy_cannot_be_seated';
    end if;
    -- A customer may hold up to five places, so his OTHER places have to be checked too: two rows of
    -- one doctor behind one door would make him two clinics in the same building, and his hours are
    -- windows in the one row.
    if exists (
      select 1
      from public.phoenix_crm_places other
      where other.customer_id = v_place.customer_id
        and other.status = 'active'
        and other.shared_place_id = v_venue.id
    ) then
      raise exception 'phoenix_crm:already_seated';
    end if;

    -- The building's timetable when it has one; otherwise his own door photograph STAYS, because
    -- `photo_path` is not null and his evidence is the only evidence there is until a board exists.
    v_photo := coalesce(v_venue.schedule_photo_path, v_place.photo_path);
    v_kept_photo := v_photo = v_place.photo_path;

    -- 🔴 ONE STATEMENT, AND IT HAS TO BE. `phoenix_crm_places_photo_uidx` is partial — `where
    -- shared_place_id is null` — so the row only becomes free to share the building's timetable at the
    -- instant `shared_place_id` is set; and `phoenix_crm_places_moved` forces all three `moved_*`
    -- fields to empty in the same statement that leaves `point_source = 'moved'`.
    update public.phoenix_crm_places pl
    set shared_place_id = v_venue.id,
        point_source = 'shared_place',
        photo_path = v_photo,
        -- COPIED FROM THE VENUE, NEVER RE-RESOLVED: it is the SAME point, so re-resolving would pay
        -- for a second brick and map lookup to answer a question already answered at the building's
        -- door — and could answer it differently if the brick master changed in between, leaving two
        -- rows at one coordinate in two bricks.
        lat = v_venue.lat,
        lon = v_venue.lon,
        accuracy_meters = v_venue.accuracy_meters,
        address = v_venue.address,
        zone = v_venue.zone,
        brick_id = v_venue.brick_id,
        brick_name = v_venue.brick_name,
        brick_distance_km = v_venue.brick_distance_km,
        brick_lookup = v_venue.brick_lookup,
        area_code = v_venue.area_code,
        area_name = v_venue.area_name,
        region_code = v_venue.region_code,
        region_name = v_venue.region_name,
        -- No reading was taken at this row for this building. See the header.
        pin_lat = null,
        pin_lon = null,
        pin_accuracy_meters = null,
        photo_lat = null,
        photo_lon = null,
        photo_accuracy_meters = null,
        photo_captured_at = null,
        -- Both describe the photograph on the row. They survive only while that photograph does.
        device_skew_minutes = case when v_kept_photo then v_place.device_skew_minutes else null end,
        signboard_check = case when v_kept_photo then v_place.signboard_check else null end,
        -- The timetable question is now asked about the BUILDING's board, so any earlier verdict is
        -- about a different photograph. The read runs again after this transaction and lands here.
        schedule_check = null,
        session = v_customer.list_type,
        moved_at = null,
        moved_by_hr_id = null,
        move_reason = null,
        updated_at = now()
    where pl.id = v_place.id
    returning pl.* into v_after;

    insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
    values (
      v_seat, v_place.customer_id, v_place.id, 'place_seated', v_actor,
      jsonb_build_object(
        'reason', v_reason,
        'shared_place_id', v_venue.id,
        'shared_place_name', v_venue.name,
        'shared_place_kind', v_venue.kind,
        'timetable_on_file', v_venue.schedule_photo_path is not null,
        -- 🔴 THE DOOR PHOTOGRAPH THAT IS OVERWRITTEN IS RECOVERABLE FROM HERE AND NOWHERE ELSE, with
        -- the verdict that was read on it. Nothing else keeps it once the board takes its place.
        'before', jsonb_build_object(
          'lat', v_place.lat, 'lon', v_place.lon, 'point_source', v_place.point_source,
          'address', v_place.address, 'brick_id', v_place.brick_id, 'area_code', v_place.area_code,
          'photo_path', v_place.photo_path, 'signboard_check', v_place.signboard_check,
          'schedule_check', v_place.schedule_check
        ),
        'after', jsonb_build_object(
          'lat', v_after.lat, 'lon', v_after.lon,
          'address', v_after.address, 'brick_id', v_after.brick_id, 'area_code', v_after.area_code,
          'photo_path', v_after.photo_path
        )
      ),
      v_is_test
    );

    v_seated := v_seated || jsonb_build_array(jsonb_build_object(
      'place_id', v_place.id,
      'customer_id', v_place.customer_id,
      'customer_name', v_customer.name
    ));

    -- 🔴 THE HOLD, WHEN THE BUILDING HAS NO BOARD YET — his own ruling, and it is structural rather
    -- than a verdict on evidence: there is no photograph to read, so nothing was judged and nothing
    -- can be wrong. A venue that DOES have a board is settled by
    -- phoenix_crm_settle_venue_timetable, after the board has been read for each of them.
    --
    -- `reopened_at` is deliberately NOT set, unlike the rejected-venue path: he is not being asked to
    -- photograph this doctor's own door again — that would undo the seating. What is waiting is the
    -- BUILDING's timetable.
    if v_venue.schedule_photo_path is null then
      update public.phoenix_crm_customers c
      set status = 'pending',
          validated_at = null,
          validated_by_hr_id = null,
          status_changed_at = now(),
          updated_at = now()
      where c.id = v_place.customer_id
        and c.status = 'active';
      if found then
        insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
        values (
          v_seat, v_place.customer_id, v_place.id, 'customer_pending', v_actor,
          jsonb_build_object(
            'why', 'venue_timetable_missing',
            'shared_place_id', v_venue.id,
            'shared_place_name', v_venue.name
          ),
          v_is_test
        );
        v_held := v_held || jsonb_build_array(to_jsonb(v_place.customer_id));
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'shared_place_id', v_venue.id,
    'shared_place_name', v_venue.name,
    'seated', v_seated,
    'seated_count', jsonb_array_length(v_seated),
    'held', v_held,
    'timetable_on_file', v_venue.schedule_photo_path is not null
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_seat_places_in_venue(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_seat_readiness(text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_seat_readiness(p_seat_ids text[], p_mark_ready boolean DEFAULT false) RETURNS TABLE(seat_id text, reference_total integer, validated_count integer, dropped_count integer, drop_pending_count integer, open_count integer, ready_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with seats as (
    select distinct s.seat_id
    from unnest(p_seat_ids) as s (seat_id)
    where s.seat_id is not null
  ),
  refs as (
    select r.seat_id, r.state
    from public.phoenix_crm_seat_reference(p_seat_ids, false) r
  ),
  counts as (
    select
      s.seat_id,
      count(refs.state)::integer as reference_total,
      (count(*) filter (where refs.state = 'validated'))::integer as validated_count,
      (count(*) filter (where refs.state = 'dropped'))::integer as dropped_count,
      (count(*) filter (where refs.state = 'drop_pending'))::integer as drop_pending_count,
      (count(*) filter (where refs.state = 'open'))::integer as open_count
    from seats s
    left join refs on refs.seat_id = s.seat_id
    group by s.seat_id
  ),
  marked as (
    insert into public.phoenix_crm_territory_readiness (seat_id, reference_total, validated, dropped)
    select c.seat_id, c.reference_total, c.validated_count, c.dropped_count
    from counts c
    where p_mark_ready
      and c.reference_total > 0
      and c.open_count = 0
      and c.drop_pending_count = 0
    on conflict (seat_id) do nothing
    returning seat_id, ready_at
  )
  select
    c.seat_id,
    c.reference_total,
    c.validated_count,
    c.dropped_count,
    c.drop_pending_count,
    c.open_count,
    coalesce(t.ready_at, m.ready_at)
  from counts c
  left join public.phoenix_crm_territory_readiness t on t.seat_id = c.seat_id
  left join marked m on m.seat_id = c.seat_id;
$$;

ALTER FUNCTION public.phoenix_crm_seat_readiness(p_seat_ids text[], p_mark_ready boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_seat_reference(text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_seat_reference(p_seat_ids text[], p_is_test boolean DEFAULT false) RETURNS TABLE(seat_id text, source_hr_id text, source_is_current boolean, contact_crm_id bigint, list_type text, grade text, name text, speciality text, address text, city text, zone text, brick_id text, last_visited_on date, customer_id uuid, state text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with seats as (
    select distinct s.seat_id from unnest(p_seat_ids) as s (seat_id) where s.seat_id is not null
  ),
  candidates as (
    select o.seat_id, upper(trim(o.occupant_hr_id)) as hr_id, o.effective_to is null as is_current, o.effective_from, o.effective_to
    from au.occupancy_history o join seats s on s.seat_id = o.seat_id
    where o.node_type = 'person' and nullif(trim(o.occupant_hr_id), '') is not null
  ),
  with_list as (
    select c.* from candidates c
    where exists (select 1 from public.crm_contact_assignments a where a.effective_to is null and a.agent_hr_id = c.hr_id and a.list_type in ('AM', 'PM') and a.contact_crm_id <> 100000)
      and (c.is_current or not exists (
          select 1 from au.occupancy_history other join au.seats other_seat on other_seat.seat_id = other.seat_id
          where other.node_type = 'person' and upper(trim(other.occupant_hr_id)) = c.hr_id and other.seat_id <> c.seat_id
            and other_seat.seat_tier = 'REP' and (other.effective_to is null or other.effective_from > c.effective_from)))
  ),
  chosen as (
    select distinct on (w.seat_id) w.seat_id, w.hr_id, w.is_current from with_list w
    order by w.seat_id, w.is_current desc, w.effective_to desc nulls first, w.effective_from desc
  ),
  rep_spells as (
    select upper(trim(o.occupant_hr_id)) as hr_id, o.seat_id, o.effective_from, o.effective_to
    from au.occupancy_history o join au.seats s on s.seat_id = o.seat_id
    where o.node_type = 'person' and s.seat_tier = 'REP' and nullif(trim(o.occupant_hr_id), '') is not null
  ),
  seat_customer as (
    select distinct on (c.seat_id, coalesce(c.reference_contact_crm_id, c.own_contact_crm_id))
      c.seat_id, coalesce(c.reference_contact_crm_id, c.own_contact_crm_id) as contact_crm_id,
      c.seat_id || '|' || coalesce(c.reference_contact_crm_id, c.own_contact_crm_id)::text as seat_key, c.id, c.status
    from public.phoenix_crm_customers c join seats s on s.seat_id = c.seat_id
    where c.is_test = p_is_test
    order by c.seat_id, coalesce(c.reference_contact_crm_id, c.own_contact_crm_id), (c.status <> 'dropped') desc, (c.status = 'active') desc, c.created_at asc, c.id asc
  ),
  pending_drop_customer as (
    select distinct q.seat_id, q.customer_id from public.phoenix_crm_list_requests q join seats s on s.seat_id = q.seat_id
    where q.kind = 'drop' and q.status = 'pending' and q.is_test = p_is_test and q.customer_id is not null
  ),
  pending_drop_contact as (
    select distinct q.seat_id, q.reference_contact_crm_id from public.phoenix_crm_list_requests q join seats s on s.seat_id = q.seat_id
    where q.kind = 'drop' and q.status = 'pending' and q.is_test = p_is_test and q.customer_id is null and q.reference_contact_crm_id is not null
  )
  select ch.seat_id, ch.hr_id, ch.is_current, a.contact_crm_id, a.list_type,
    case when upper(trim(a.grade)) in ('A', 'B', 'C') then upper(trim(a.grade)) when upper(trim(a.grade)) = 'A+' then 'A' else null end,
    coalesce(nullif(trim(contact.name), ''), 'Unnamed customer'), nullif(trim(contact.speciality), ''), nullif(trim(contact.address), ''),
    nullif(trim(contact.city), ''), nullif(trim(contact.zone), ''), contact.brick_id, contact.last_visited_on, customer.id,
    case when customer.status = 'dropped' then 'dropped' when customer.status = 'active' then 'validated'
      when drop_by_customer.seat_id is not null or drop_by_contact.seat_id is not null then 'drop_pending' else 'open' end
  from chosen ch
  join public.crm_contact_assignments a
    on a.effective_to is null and a.agent_hr_id = ch.hr_id and a.list_type in ('AM', 'PM', 'Pharmacy') and a.contact_crm_id <> 100000
   and (exists (select 1 from rep_spells mine where mine.hr_id = ch.hr_id and mine.seat_id = ch.seat_id and a.effective_from >= mine.effective_from and (mine.effective_to is null or a.effective_from < mine.effective_to))
     or not exists (select 1 from rep_spells any_seat where any_seat.hr_id = ch.hr_id and a.effective_from >= any_seat.effective_from and (any_seat.effective_to is null or a.effective_from < any_seat.effective_to)))
  left join public.crm_contacts contact on contact.contact_crm_id = a.contact_crm_id
  left join seat_customer customer on customer.seat_key = ch.seat_id || '|' || a.contact_crm_id::text
  left join pending_drop_customer drop_by_customer on drop_by_customer.seat_id = ch.seat_id and drop_by_customer.customer_id = customer.id
  left join pending_drop_contact drop_by_contact on drop_by_contact.seat_id = ch.seat_id and drop_by_contact.reference_contact_crm_id = a.contact_crm_id;
$$;

ALTER FUNCTION public.phoenix_crm_seat_reference(p_seat_ids text[], p_is_test boolean) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_seat_reference(p_seat_ids text[], p_is_test boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_seat_reference(p_seat_ids text[], p_is_test boolean) IS 'A seat''s live iReports360 list — AM, PM and (since 2026-10-02) Pharmacy. The pharmacies are a reference the rep calls on, never planned and in no KPI; a wholesaler is filtered in TypeScript by wholesaler-venue-guard, which this function deliberately does not try to repeat.';

--
-- Name: phoenix_crm_seat_visit_firsts(text[], boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_seat_visit_firsts(p_seat_ids text[], p_is_test boolean) RETURNS TABLE(seat_id text, first_visit_on date, visits_ever integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select v.seat_id, min(v.visit_date) as first_visit_on, count(*)::integer as visits_ever
  from public.phoenix_crm_countable_visits v
  where v.seat_id = any(p_seat_ids)
    and v.is_test = p_is_test
    and v.imported_from_ireports360_at is null
  group by v.seat_id;
$$;

ALTER FUNCTION public.phoenix_crm_seat_visit_firsts(p_seat_ids text[], p_is_test boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_seats_with_activity(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_seats_with_activity(p jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(asked.seat_id), '[]'::jsonb)
  from (
    select distinct elem.seat_id
    from jsonb_array_elements_text(coalesce(p -> 'seat_ids', '[]'::jsonb)) as elem(seat_id)
  ) asked
  -- A visit copied from iReports360 history is not activity on Phoenix (20261029212200).
  where exists (select 1 from public.phoenix_crm_visits t where t.seat_id = asked.seat_id and t.is_test = false and t.imported_from_ireports360_at is null)
     or exists (select 1 from public.phoenix_crm_places t where t.seat_id = asked.seat_id and t.is_test = false)
     or exists (select 1 from public.phoenix_crm_plans t where t.seat_id = asked.seat_id and t.is_test = false)
     or exists (select 1 from public.phoenix_crm_monthly_plans t where t.seat_id = asked.seat_id and t.is_test = false)
     or exists (select 1 from public.phoenix_crm_day_activities t where t.seat_id = asked.seat_id and t.is_test = false)
     or exists (select 1 from public.phoenix_crm_list_requests t where t.seat_id = asked.seat_id and t.is_test = false);
$$;

ALTER FUNCTION public.phoenix_crm_seats_with_activity(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_set_pharmacy_details(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_set_pharmacy_details(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_sets_phone boolean := (p -> 'phone') is not null;
  v_phone text := nullif(regexp_replace(coalesce(p ->> 'phone', ''), '\s+', '', 'g'), '');
  v_sets_pin boolean := (p -> 'pin') is not null;
  v_pin jsonb := case when jsonb_typeof(p -> 'pin') = 'object' then p -> 'pin' else null end;
  v_customer public.phoenix_crm_customers%rowtype;
  v_before jsonb;
begin
  if v_seat is null or v_actor is null or v_customer_id is null or not (v_sets_phone or v_sets_pin) then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_phone is not null and v_phone !~ '^\+?[0-9]{7,15}$' then
    raise exception 'phoenix_crm:bad_phone';
  end if;
  if v_sets_pin and v_pin is not null and (v_pin -> 'lat') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id
    and c.seat_id = v_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.list_type is distinct from 'Pharmacy' then
    raise exception 'phoenix_crm:not_a_pharmacy';
  end if;
  if v_customer.status = 'dropped' then
    raise exception 'phoenix_crm:customer_dropped';
  end if;

  v_before := jsonb_build_object(
    'phone', v_customer.phone,
    'pin_lat', v_customer.pharmacy_pin_lat,
    'pin_lon', v_customer.pharmacy_pin_lon,
    'governorate', v_customer.pharmacy_pin_governorate,
    'area_name', v_customer.pharmacy_pin_area_name,
    'brick_name', v_customer.pharmacy_pin_brick_name
  );

  update public.phoenix_crm_customers c
  set phone = case when v_sets_phone then v_phone else c.phone end,
      pharmacy_pin_lat = case when v_sets_pin then (v_pin ->> 'lat')::double precision else c.pharmacy_pin_lat end,
      pharmacy_pin_lon = case when v_sets_pin then (v_pin ->> 'lon')::double precision else c.pharmacy_pin_lon end,
      pharmacy_pin_accuracy_meters = case when v_sets_pin then (v_pin ->> 'accuracy_meters')::numeric else c.pharmacy_pin_accuracy_meters end,
      pharmacy_pin_captured_at = case
        when not v_sets_pin then c.pharmacy_pin_captured_at
        when v_pin is null then null
        else coalesce((v_pin ->> 'captured_at')::timestamptz, now())
      end,
      pharmacy_pin_captured_by_hr_id = case
        when not v_sets_pin then c.pharmacy_pin_captured_by_hr_id
        when v_pin is null then null
        else v_actor
      end,
      pharmacy_pin_address = case when v_sets_pin then left(v_pin ->> 'address', 400) else c.pharmacy_pin_address end,
      pharmacy_pin_governorate = case when v_sets_pin then left(v_pin ->> 'governorate', 120) else c.pharmacy_pin_governorate end,
      pharmacy_pin_area_code = case when v_sets_pin then left(v_pin ->> 'area_code', 40) else c.pharmacy_pin_area_code end,
      pharmacy_pin_area_name = case when v_sets_pin then left(v_pin ->> 'area_name', 120) else c.pharmacy_pin_area_name end,
      pharmacy_pin_brick_id = case when v_sets_pin then left(v_pin ->> 'brick_id', 40) else c.pharmacy_pin_brick_id end,
      pharmacy_pin_brick_name = case when v_sets_pin then left(v_pin ->> 'brick_name', 120) else c.pharmacy_pin_brick_name end,
      pharmacy_pin_brick_distance_km = case when v_sets_pin then (v_pin ->> 'brick_distance_km')::numeric else c.pharmacy_pin_brick_distance_km end,
      pharmacy_pin_brick_lookup = case when v_sets_pin then v_pin ->> 'brick_lookup' else c.pharmacy_pin_brick_lookup end,
      updated_at = now()
  where c.id = v_customer.id
  returning c.* into v_customer;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer.id, 'pharmacy_details_set', v_actor,
    jsonb_build_object(
      'from', v_before,
      'to', jsonb_build_object(
        'phone', v_customer.phone,
        'pin_lat', v_customer.pharmacy_pin_lat,
        'pin_lon', v_customer.pharmacy_pin_lon,
        'governorate', v_customer.pharmacy_pin_governorate,
        'area_name', v_customer.pharmacy_pin_area_name,
        'brick_name', v_customer.pharmacy_pin_brick_name
      )
    ),
    v_is_test
  );

  return jsonb_build_object(
    'customer_id', v_customer.id,
    'customer_name', v_customer.name,
    'phone', v_customer.phone,
    'pinned', v_customer.pharmacy_pin_lat is not null
  );
end;
$_$;

ALTER FUNCTION public.phoenix_crm_set_pharmacy_details(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_set_primary_pharmacy(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_set_primary_pharmacy(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_customer_id uuid := nullif(p ->> 'customer_id', '')::uuid;
  v_pharmacy text := nullif(regexp_replace(trim(coalesce(p ->> 'pharmacy_name', '')), '\s+', ' ', 'g'), '');
  v_customer public.phoenix_crm_customers%rowtype;
  v_before text;
begin
  if v_seat is null or v_actor is null or v_customer_id is null then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_pharmacy is not null and char_length(v_pharmacy) > 120 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = v_customer_id
    and c.seat_id = v_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.status = 'dropped' then
    raise exception 'phoenix_crm:customer_dropped';
  end if;

  v_before := v_customer.primary_pharmacy_name;

  update public.phoenix_crm_customers c
  set primary_pharmacy_name = v_pharmacy,
      updated_at = now()
  where c.id = v_customer.id
  returning c.* into v_customer;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer.id, 'customer_primary_pharmacy_set', v_actor,
    jsonb_build_object('from', v_before, 'to', v_customer.primary_pharmacy_name),
    v_is_test
  );

  return jsonb_build_object(
    'customer_id', v_customer.id,
    'primary_pharmacy_name', v_customer.primary_pharmacy_name
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_set_primary_pharmacy(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_set_team_start(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_set_team_start(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_action text := coalesce(p ->> 'action', '');
  v_team text := nullif(btrim(coalesce(p ->> 'team_seat_id', '')), '');
  v_day date := nullif(p ->> 'day', '')::date;
  v_actor text := upper(nullif(btrim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_login text := nullif(btrim(coalesce(p ->> 'actor_login_id', '')), '');
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_floor date := date_trunc('month', (now() at time zone 'Africa/Cairo'))::date;
  v_row public.phoenix_crm_team_starts%rowtype;
  v_before jsonb;
begin
  if v_action not in ('start', 'stop') or v_team is null or v_actor is null then
    raise exception 'phoenix_crm_team_start:bad_input';
  end if;
  -- Only a team with territories can be started; one the organogram has since emptied can still be stopped.
  if v_action = 'start'
     and not exists (select 1 from au.seats s where s.parent_seat_id = v_team and s.seat_tier = 'REP') then
    raise exception 'phoenix_crm_team_start:no_team';
  end if;
  if v_day is not null and extract(isodow from v_day) <> 6 then
    raise exception 'phoenix_crm_team_start:not_saturday';
  end if;
  if v_day is not null and v_day < v_floor then
    raise exception 'phoenix_crm_team_start:before_month';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:team_start:' || v_team));

  if v_action = 'start' then
    if v_day is null then
      raise exception 'phoenix_crm_team_start:bad_input';
    end if;
    if exists (select 1 from public.phoenix_crm_team_starts t where t.team_seat_id = v_team and t.stops_on is null) then
      raise exception 'phoenix_crm_team_start:already_started';
    end if;
    -- A team started again begins on or after its last stop: no day is ever in two starts.
    if exists (select 1 from public.phoenix_crm_team_starts t where t.team_seat_id = v_team and t.stops_on > v_day) then
      raise exception 'phoenix_crm_team_start:overlaps';
    end if;
    insert into public.phoenix_crm_team_starts (team_seat_id, starts_on, started_by, started_by_hr_id)
    values (v_team, v_day, 'super_admin', v_actor)
    returning * into v_row;
    insert into public.audit_logs (actor_login_id, entity_type, entity_id, summary, new_values)
    values (coalesce(v_login, v_actor), 'crm_phoenix_team_start', v_team,
            'Team counted from Phoenix CRM from ' || to_char(v_day, 'Dy DD Mon YYYY'), to_jsonb(v_row));
    return to_jsonb(v_row) || jsonb_build_object('done', 'started');
  end if;

  select t.* into v_row
    from public.phoenix_crm_team_starts t
   where t.team_seat_id = v_team and t.stops_on is null
   for update;
  if not found then
    raise exception 'phoenix_crm_team_start:not_started';
  end if;
  v_before := to_jsonb(v_row);

  -- Not reached yet, or stopped on its own first Saturday: no day was ever counted from Phoenix by it,
  -- so it is taken back whole. A start that began in an earlier month can never get here: the stop day
  -- would have to be on or before it, and the month floor refuses that.
  if v_row.starts_on > v_today or (v_day is not null and v_day <= v_row.starts_on) then
    if v_row.starts_on < v_floor then
      raise exception 'phoenix_crm_team_start:before_month';
    end if;
    delete from public.phoenix_crm_team_starts t where t.id = v_row.id;
    insert into public.audit_logs (actor_login_id, entity_type, entity_id, summary, old_values)
    values (coalesce(v_login, v_actor), 'crm_phoenix_team_start', v_team,
            'Team start of ' || to_char(v_row.starts_on, 'Dy DD Mon YYYY') || ' taken back', v_before);
    return v_before || jsonb_build_object('done', 'cancelled');
  end if;

  if v_day is null then
    raise exception 'phoenix_crm_team_start:bad_input';
  end if;
  update public.phoenix_crm_team_starts t
     set stops_on = v_day,
         stopped_by_hr_id = v_actor,
         stopped_at = now()
   where t.id = v_row.id
  returning * into v_row;
  insert into public.audit_logs (actor_login_id, entity_type, entity_id, summary, old_values, new_values)
  values (coalesce(v_login, v_actor), 'crm_phoenix_team_start', v_team,
          'Team back on iReports360 from ' || to_char(v_day, 'Dy DD Mon YYYY'), v_before, to_jsonb(v_row));
  return to_jsonb(v_row) || jsonb_build_object('done', 'stopped');
end;
$$;

ALTER FUNCTION public.phoenix_crm_set_team_start(p jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phoenix_crm_set_team_start(p jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phoenix_crm_set_team_start(p jsonb) IS 'The one writer of phoenix_crm_team_starts: start a team from a Saturday, stop it from a Saturday, or take back a start not reached yet — never before the first day of the current Cairo month — and write its audit row in the same transaction. Service role only; the route in front of it is Super Admin only.';

--
-- Name: phoenix_crm_set_venue_timetable(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_set_venue_timetable(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_photo text := nullif(trim(coalesce(p ->> 'photo_path', '')), '');
  v_venue public.phoenix_crm_shared_places%rowtype;
  v_before text;
  v_captured_at timestamptz;
begin
  if v_seat is null or v_actor is null or v_photo is null or nullif(p ->> 'shared_place_id', '') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select sp.* into v_venue
  from public.phoenix_crm_shared_places sp
  where sp.id = (p ->> 'shared_place_id')::uuid
    and sp.seat_id = v_seat
    and sp.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:shared_place_not_found';
  end if;
  if v_venue.status = 'retired' then
    raise exception 'phoenix_crm:shared_place_retired';
  end if;
  if v_venue.status <> 'active' then
    raise exception 'phoenix_crm:shared_place_held';
  end if;

  -- The same slot discipline every photograph in this module goes through: it must be one this server
  -- issued to THIS person for THIS territory, it is single-use, and it dates the capture.
  v_captured_at := public.phoenix_crm_take_photo(v_photo, v_actor, v_seat, 'place', v_is_test);
  v_before := v_venue.schedule_photo_path;

  update public.phoenix_crm_shared_places sp
  set schedule_photo_path = v_photo,
      schedule_photo_captured_at = v_captured_at,
      schedule_photo_by_hr_id = v_actor,
      updated_at = now()
  where sp.id = v_venue.id;

  -- A venue-level event: no customer, which `phoenix_crm_list_events.customer_id` allows.
  insert into public.phoenix_crm_list_events (seat_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, 'venue_timetable_set', v_actor,
    jsonb_build_object(
      'shared_place_id', v_venue.id,
      'shared_place_name', v_venue.name,
      'photo_path', v_photo,
      -- Null the first time, the replaced board afterwards: "the timetable changed" is the same door.
      'before_photo_path', v_before
    ),
    v_is_test
  );

  return jsonb_build_object(
    'shared_place_id', v_venue.id,
    'shared_place_name', v_venue.name,
    'schedule_photo_path', v_photo,
    'captured_at', v_captured_at,
    'replaced', v_before is not null
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_set_venue_timetable(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_set_visit_companions(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_set_visit_companions(p_visit_id uuid, p_companions jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_visit public.phoenix_crm_visits%rowtype;
  v_list jsonb := case when jsonb_typeof(p_companions) = 'array' then p_companions else '[]'::jsonb end;
  v_count integer;
  v_managers integer;
begin
  select v.* into v_visit from public.phoenix_crm_visits v where v.id = p_visit_id;
  if not found then
    raise exception 'phoenix_crm:visit_not_found';
  end if;
  if jsonb_array_length(v_list) > 12 or exists (
    select 1
    from jsonb_array_elements(v_list) as e
    where jsonb_typeof(e) <> 'object'
      or nullif(btrim(coalesce(e ->> 'hr_id', '')), '') is null
      or char_length(btrim(e ->> 'hr_id')) > 40
      or coalesce(e ->> 'side', '') not in ('manager', 'product')
  ) then
    raise exception 'phoenix_crm:bad_participants';
  end if;

  delete from public.phoenix_crm_visit_companions where visit_id = p_visit_id;

  -- A visit with no rep is the manager's own, and the manager place is HIM: nobody came with him here.
  if v_visit.rep_hr_id is null then
    if jsonb_array_length(v_list) > 0 then
      raise exception 'phoenix_crm:bad_participants';
    end if;
    return 0;
  end if;

  -- The fixed places first, in their order, then the list; one row per person, the first side he
  -- arrived with kept; never the rep himself.
  insert into public.phoenix_crm_visit_companions (visit_id, hr_id, side, position)
  select p_visit_id, s.hr_id, s.side, (row_number() over (order by s.ord) - 1)::smallint
  from (
    select distinct on (x.hr_id) x.hr_id, x.side, x.ord
    from (
      select upper(btrim(v_visit.manager_hr_id)) as hr_id, 'manager'::text as side, 0::bigint as ord
      where nullif(btrim(coalesce(v_visit.manager_hr_id, '')), '') is not null
      union all
      select upper(btrim(v_visit.senior_hr_id)), 'manager', 1
      where nullif(btrim(coalesce(v_visit.senior_hr_id, '')), '') is not null
      union all
      select upper(btrim(v_visit.product_manager_hr_id)), 'product', 2
      where nullif(btrim(coalesce(v_visit.product_manager_hr_id, '')), '') is not null
      union all
      select upper(btrim(e.value ->> 'hr_id')), e.value ->> 'side', 2 + e.ordinality
      from jsonb_array_elements(v_list) with ordinality as e (value, ordinality)
    ) x
    where x.hr_id <> upper(btrim(v_visit.rep_hr_id))
    order by x.hr_id, x.ord
  ) s;
  get diagnostics v_count = row_count;

  select count(*) filter (where c.side = 'manager')
  into v_managers
  from public.phoenix_crm_visit_companions c
  where c.visit_id = p_visit_id;

  -- The kind still says who went, so the double-visit figure counts what it always counted.
  if v_count > 12 or not (
    (v_visit.kind = 'single' and v_count = 0)
    or (v_visit.kind = 'double' and v_count = 1 and v_managers = 1)
    or (v_visit.kind = 'product_manager' and v_count >= 1 and v_managers = 0)
    or (v_visit.kind = 'chain' and v_count >= 2 and v_managers >= 1)
  ) then
    raise exception 'phoenix_crm:bad_participants';
  end if;
  return v_count;
end;
$$;

ALTER FUNCTION public.phoenix_crm_set_visit_companions(p_visit_id uuid, p_companions jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_settle_venue_timetable(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_settle_venue_timetable(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_venue public.phoenix_crm_shared_places%rowtype;
  v_row record;
  v_verdict text;
  v_validated jsonb := '[]'::jsonb;
  v_held jsonb := '[]'::jsonb;
begin
  if v_seat is null or v_actor is null or nullif(p ->> 'shared_place_id', '') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select sp.* into v_venue
  from public.phoenix_crm_shared_places sp
  where sp.id = (p ->> 'shared_place_id')::uuid
    and sp.seat_id = v_seat
    and sp.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:shared_place_not_found';
  end if;

  for v_row in
    select pl.id as place_id, pl.customer_id, pl.schedule_check, c.status as customer_status, c.name as customer_name
    from public.phoenix_crm_places pl
    join public.phoenix_crm_customers c on c.id = pl.customer_id
    where pl.shared_place_id = v_venue.id
      and pl.status = 'active'
    order by pl.created_at
    -- No `for update` on the cursor, by choice, exactly as phoenix_crm_decide_shared_place records:
    -- each row is locked by the update that settles it, the whole function runs in one transaction
    -- behind the seat's advisory lock, and one venue is settled by one caller at a time.
  loop
    v_verdict := v_row.schedule_check ->> 'verdict';

    -- 🔴 A DECISION OF HIS IS NEVER UNDONE HERE: a place whose review the Super Admin already approved
    -- keeps its customer validated whatever the board says, because that approval was his own click.
    if exists (
      select 1 from public.phoenix_crm_validation_reviews r
      where r.place_id = v_row.place_id and r.status = 'approved'
    ) then
      null;
    elsif v_venue.schedule_photo_path is null or v_verdict in ('other_name', 'no_schedule') then
      -- Out of the KPIs: either the building has no board at all, or its board was read and does not
      -- name him. His visits are still planned, sent and recorded — that is his ruling.
      update public.phoenix_crm_customers c
      set status = 'pending',
          validated_at = null,
          validated_by_hr_id = null,
          status_changed_at = now(),
          updated_at = now()
      where c.id = v_row.customer_id
        and c.status = 'active';
      if found then
        insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
        values (
          v_seat, v_row.customer_id, v_row.place_id, 'customer_pending', v_actor,
          jsonb_build_object(
            'why', case when v_venue.schedule_photo_path is null then 'venue_timetable_missing' else coalesce(v_row.schedule_check ->> 'reason', v_verdict) end,
            'shared_place_id', v_venue.id,
            'shared_place_name', v_venue.name
          ),
          v_is_test
        );
        v_held := v_held || jsonb_build_array(jsonb_build_object(
          'customer_id', v_row.customer_id, 'customer_name', v_row.customer_name, 'place_id', v_row.place_id
        ));
      end if;

    -- 🔴 NEVER WHILE THE BUILDING ITSELF IS STILL WAITING FOR THE SUPER ADMIN (2026-10-14). A customer seated in
    -- a held venue is pending until that venue is approved, and a board that names him must not release him
    -- ahead of it — approving the venue is what does (phoenix_crm_decide_shared_place).
    elsif v_verdict = 'match' and v_row.customer_status = 'pending' and v_venue.status = 'active' then
      -- The board names him, so the board validates him — the same automatic validation the rep's own
      -- seating door performs on a match.
      --
      -- 🔴 NEVER WHILE A PERSON'S DECISION IS STILL WAITING. A seating the system held raised a
      -- pending `phoenix_crm_validation_reviews` row, and that row is the Super Admin's own click: a
      -- settle that validated past it would be an approval taken on his behalf, and would leave his
      -- board holding a pending review for a customer already validated.
      if not exists (
        select 1 from public.phoenix_crm_validation_reviews r
        where r.place_id = v_row.place_id and r.status = 'pending'
      ) then
        update public.phoenix_crm_customers c
        set status = 'active',
            validated_at = now(),
            validated_by_hr_id = v_actor,
            status_changed_at = now(),
            updated_at = now()
        where c.id = v_row.customer_id
          and c.status = 'pending';
        if found then
          insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
          values (
            v_seat, v_row.customer_id, v_row.place_id, 'customer_validated', v_actor,
            jsonb_build_object(
              'why', 'venue_timetable_names_customer',
              'shared_place_id', v_venue.id,
              'shared_place_name', v_venue.name
            ),
            v_is_test
          );
          v_validated := v_validated || jsonb_build_array(jsonb_build_object(
            'customer_id', v_row.customer_id, 'customer_name', v_row.customer_name, 'place_id', v_row.place_id
          ));
        end if;
      end if;
    end if;
    -- 🔴 EVERY OTHER CASE IS LEFT ALONE, AND `unjudged` IS THE ONE THAT MATTERS: no key, unreadable
    -- bytes, a call that failed. The locked rule is that `unjudged` NEVER holds (owner, 2026-10-08 —
    -- the key has run dry silently twice), and an outage at the model's end must never de-validate a
    -- rep's list. A null `schedule_check` is the same answer: not read yet, so nothing is decided.
  end loop;

  return jsonb_build_object(
    'shared_place_id', v_venue.id,
    'shared_place_name', v_venue.name,
    'timetable_on_file', v_venue.schedule_photo_path is not null,
    'validated', v_validated,
    'held', v_held
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_settle_venue_timetable(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_share_line_validation(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_share_line_validation(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_ids jsonb := p -> 'source_place_ids';
  v_customer public.phoenix_crm_customers%rowtype;
  v_source record;
  v_place_id uuid;
  v_place_ids uuid[] := '{}';
  v_source_customers uuid[] := '{}';
  v_validated_by text := upper(nullif(trim(coalesce(p ->> 'validated_by_hr_id', '')), ''));
  v_wanted int;
  v_found int;
begin
  if v_seat is null or v_actor is null or nullif(p ->> 'customer_id', '') is null
    or jsonb_typeof(v_ids) is distinct from 'array'
    or jsonb_array_length(v_ids) not between 1 and 5 then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select c.* into v_customer
  from public.phoenix_crm_customers c
  where c.id = (p ->> 'customer_id')::uuid
    and c.seat_id = v_seat
    and c.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:customer_not_found';
  end if;
  if v_customer.list_type not in ('AM', 'PM') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_customer.status <> 'pending' or v_customer.validated_at is not null then
    return jsonb_build_object('skipped', 'not_waiting', 'customer_id', v_customer.id);
  end if;
  if exists (select 1 from public.phoenix_crm_places pl where pl.customer_id = v_customer.id and pl.status = 'active') then
    return jsonb_build_object('skipped', 'has_place', 'customer_id', v_customer.id);
  end if;
  if exists (select 1 from public.phoenix_crm_validation_reviews r where r.customer_id = v_customer.id and r.status = 'pending') then
    return jsonb_build_object('skipped', 'in_review', 'customer_id', v_customer.id);
  end if;
  if exists (
    select 1 from public.phoenix_crm_list_requests q
    where q.seat_id = v_seat
      and q.is_test = v_is_test
      and q.kind = 'drop'
      and q.status = 'pending'
      and (
        q.customer_id = v_customer.id
        or (q.customer_id is null and v_customer.reference_contact_crm_id is not null and q.reference_contact_crm_id = v_customer.reference_contact_crm_id)
      )
  ) then
    return jsonb_build_object('skipped', 'drop_requested', 'customer_id', v_customer.id);
  end if;
  if v_customer.full_name_held is not null then
    return jsonb_build_object('skipped', 'full_name_held', 'customer_id', v_customer.id);
  end if;

  -- Every source must still be an own place of a Phoenix validation of the same list, on another seat and line.
  v_wanted := (select count(distinct e) from jsonb_array_elements_text(v_ids) e);
  select count(*) into v_found
  from public.phoenix_crm_places pl
  join public.phoenix_crm_customers sc on sc.id = pl.customer_id
  where pl.id in (select e::uuid from jsonb_array_elements_text(v_ids) e)
    and pl.status = 'active'
    and pl.point_source <> 'line_twin'
    and pl.is_test = v_is_test
    and pl.seat_id <> v_seat
    and sc.status = 'active'
    and sc.validated_at is not null
    and sc.list_type = v_customer.list_type
    and sc.is_test = v_is_test
    and sc.line_code is distinct from v_customer.line_code;
  if v_found <> v_wanted then
    return jsonb_build_object('skipped', 'source_gone', 'customer_id', v_customer.id);
  end if;

  for v_source in
    select pl.*, sc.line_code as source_line, sc.validated_at as source_validated_at, sc.validated_by_hr_id as source_validated_by, e.ord
    from jsonb_array_elements_text(v_ids) with ordinality as e(id, ord)
    join public.phoenix_crm_places pl on pl.id = e.id::uuid
    join public.phoenix_crm_customers sc on sc.id = pl.customer_id
    order by e.ord
  loop
    if not (v_source.customer_id = any (v_source_customers)) then
      v_source_customers := v_source_customers || v_source.customer_id;
    end if;
    v_validated_by := coalesce(v_validated_by, upper(v_source.source_validated_by));

    insert into public.phoenix_crm_places (
      customer_id, seat_id, label, address, brick_id, brick_name, zone, lat, lon, accuracy_meters, timings,
      photo_path, captured_at, created_by_hr_id, is_test, brick_distance_km, area_code, area_name, region_code,
      region_name, pin_lat, pin_lon, pin_accuracy_meters, photo_lat, photo_lon, photo_accuracy_meters,
      photo_captured_at, point_source, brick_lookup, session, trusted_basis
    )
    values (
      v_customer.id, v_seat, v_source.label, v_source.address, v_source.brick_id, v_source.brick_name, v_source.zone,
      v_source.lat, v_source.lon, v_source.accuracy_meters, v_source.timings,
      null, v_source.captured_at, v_actor, v_is_test, v_source.brick_distance_km, v_source.area_code, v_source.area_name,
      v_source.region_code, v_source.region_name,
      case when v_source.point_source in ('photo', 'pin') then v_source.pin_lat end,
      case when v_source.point_source in ('photo', 'pin') then v_source.pin_lon end,
      case when v_source.point_source in ('photo', 'pin') then v_source.pin_accuracy_meters end,
      v_source.photo_lat, v_source.photo_lon, v_source.photo_accuracy_meters, v_source.photo_captured_at,
      'line_twin', v_source.brick_lookup, v_source.session,
      jsonb_build_object(
        'kind', 'line_twin',
        'source_place_id', v_source.id,
        'source_customer_id', v_source.customer_id,
        'source_seat_id', v_source.seat_id,
        'source_line', v_source.source_line,
        'source_point_source', v_source.point_source,
        'source_validated_at', v_source.source_validated_at,
        'source_validated_by_hr_id', v_source.source_validated_by
      )
    )
    returning id into v_place_id;
    v_place_ids := v_place_ids || v_place_id;
  end loop;

  update public.phoenix_crm_customers c
  set status = 'active',
      validated_at = now(),
      validated_by_hr_id = coalesce(v_validated_by, v_actor),
      dropped_reason = null,
      dropped_note = null,
      status_changed_at = now(),
      updated_at = now()
  where c.id = v_customer.id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer.id, v_place_ids[1], 'customer_validated', v_actor,
    jsonb_build_object(
      'mode', 'line_twin',
      'place_ids', to_jsonb(v_place_ids),
      'source_place_ids', v_ids,
      'source_customer_ids', to_jsonb(v_source_customers),
      'validated_by_hr_id', coalesce(v_validated_by, v_actor),
      'reference_contact_crm_id', v_customer.reference_contact_crm_id
    ),
    v_is_test
  );

  return jsonb_build_object(
    'customer_id', v_customer.id,
    'place_ids', to_jsonb(v_place_ids),
    'status', 'active',
    'event', 'customer_validated'
  );
end;
$$;

ALTER FUNCTION public.phoenix_crm_share_line_validation(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_shared_place_day_cap(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_shared_place_day_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_shared uuid;
  v_cap integer;
  v_own integer;
  v_placed integer;
begin
  if new.place_id is null then
    return new;
  end if;
  select pl.shared_place_id into v_shared from public.phoenix_crm_places pl where pl.id = new.place_id;
  if v_shared is null then
    return new;
  end if;

  -- An out-of-plan visit under a named exception is not held to the venue's daily number.
  if new.unplanned_kind = 'out_of_plan'
     and public.phoenix_crm_offplan_exempt(new.seat_id, new.customer_id, new.place_id) then
    return new;
  end if;

  -- A venue the owner lifted outright (2026-10-31): no daily number there, planned or not.
  if exists (select 1 from public.phoenix_crm_venue_cap_lifted(new.seat_id) l where l.shared_place_id = v_shared) then
    return new;
  end if;

  select s.shared_place_daily_cap into v_cap from public.phoenix_crm_settings s where s.id = 1;
  -- A venue the owner raised (2026-11-02) holds its own number for its own seat, and never less than the company's.
  select sp.daily_cap into v_own from public.phoenix_crm_shared_places sp where sp.id = v_shared and sp.seat_id = new.seat_id;
  v_cap := greatest(coalesce(v_cap, 3), coalesce(v_own, 0));

  select count(*) into v_placed
  from public.phoenix_crm_visits v
  join public.phoenix_crm_places pl on pl.id = v.place_id
  where pl.shared_place_id = v_shared
    and v.visit_date = new.visit_date
    and v.is_test = new.is_test
    and not v.offplan_exempt;

  if v_placed >= v_cap then
    raise exception 'phoenix_crm:shared_place_day_full';
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.phoenix_crm_shared_place_day_cap() OWNER TO postgres;

--
-- Name: phoenix_crm_start_day(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_start_day(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(p ->> 'seat_id'), '');
  v_line text := nullif(trim(p ->> 'line_code'), '');
  v_rep text := nullif(trim(p ->> 'rep_hr_id'), '');
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_lat double precision := nullif(p ->> 'lat', '')::double precision;
  v_lon double precision := nullif(p ->> 'lon', '')::double precision;
  v_accuracy numeric(8, 1) := nullif(p ->> 'accuracy_meters', '')::numeric(8, 1);
  v_planned integer := nullif(p ->> 'planned_am_minute', '')::integer;
  v_today date := ((now() at time zone 'Africa/Cairo') - interval '2 hours')::date;
  v_row public.phoenix_crm_day_starts;
  v_created boolean := false;
begin
  if v_seat is null or v_rep is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:day_start:' || v_seat || ':' || v_today::text));

  select * into v_row
  from public.phoenix_crm_day_starts
  where seat_id = v_seat and started_on = v_today and is_test = v_is_test;

  if not found then
    insert into public.phoenix_crm_day_starts
      (seat_id, line_code, rep_hr_id, started_on, lat, lon, accuracy_meters, planned_am_minute, is_test)
    values
      (v_seat, v_line, v_rep, v_today, v_lat, v_lon, v_accuracy, v_planned, v_is_test)
    returning * into v_row;
    v_created := true;
  end if;

  return jsonb_build_object('created', v_created, 'day_start', to_jsonb(v_row));
end;
$$;

ALTER FUNCTION public.phoenix_crm_start_day(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_started_team_reps(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_started_team_reps() RETURNS TABLE(seat_id text, hr_id text, hr_key text, agent_crm_id bigint, counted_from date, counted_until date)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 60
    SET search_path TO 'public'
    AS $_$
  select w.seat_id,
         btrim(o.occupant_hr_id),
         lower(btrim(o.occupant_hr_id)),
         person.agent_crm_id,
         greatest(o.effective_from, w.starts_on),
         least(o.effective_to, w.stops_on)
    from (
      select territory.seat_id, territory.starts_on, territory.stops_on
        from public.phoenix_crm_started_team_seats() territory
      union all
      -- The team's own district-manager seat: his own iReports360 rows stop counting with his team's.
      select t.team_seat_id, t.starts_on, t.stops_on
        from public.phoenix_crm_team_starts t
    ) w
    join au.occupancy_history o on o.seat_id = w.seat_id
    left join lateral (
      select case when e.crm_id ~ '^[0-9]+$' then e.crm_id::bigint end as agent_crm_id
        from public.employees e
       where upper(btrim(e.hr_id)) = upper(btrim(o.occupant_hr_id))
       order by e.hr_id
       limit 1
    ) person on true
   where nullif(btrim(o.occupant_hr_id), '') is not null
     and (least(o.effective_to, w.stops_on) is null
          or least(o.effective_to, w.stops_on) > greatest(o.effective_from, w.starts_on))
$_$;

ALTER FUNCTION public.phoenix_crm_started_team_reps() OWNER TO postgres;

--
-- Name: phoenix_crm_started_team_seats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_started_team_seats() RETURNS TABLE(seat_id text, team_seat_id text, starts_on date, stops_on date)
    LANGUAGE sql STABLE SECURITY DEFINER ROWS 60
    SET search_path TO 'public'
    AS $$
  select s.seat_id, s.parent_seat_id, t.starts_on, t.stops_on
    from public.phoenix_crm_team_starts t
    join au.seats s on s.parent_seat_id = t.team_seat_id and s.seat_tier = 'REP'
$$;

ALTER FUNCTION public.phoenix_crm_started_team_seats() OWNER TO postgres;

--
-- Name: phoenix_crm_take_photo(text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_take_photo(p_path text, p_hr_id text, p_seat_id text, p_purpose text, p_is_test boolean) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_slot public.phoenix_crm_photo_uploads%rowtype;
begin
  select u.* into v_slot
  from public.phoenix_crm_photo_uploads u
  where u.path = p_path
  for update;

  if not found
    or v_slot.issued_to_hr_id <> upper(trim(p_hr_id))
    or v_slot.seat_id <> p_seat_id
    or v_slot.purpose <> p_purpose
    or v_slot.is_test <> p_is_test then
    raise exception 'phoenix_crm:photo_not_issued';
  end if;
  if v_slot.used_at is not null then
    raise exception 'phoenix_crm:photo_used';
  end if;
  if v_slot.issued_at < now() - interval '2 hours' then
    raise exception 'phoenix_crm:photo_expired';
  end if;
  if not exists (
    select 1 from storage.objects o where o.bucket_id = 'phoenix-crm-photos' and o.name = p_path
  ) then
    raise exception 'phoenix_crm:photo_missing';
  end if;

  update public.phoenix_crm_photo_uploads u set used_at = now() where u.path = p_path;
  return v_slot.issued_at;
end;
$$;

ALTER FUNCTION public.phoenix_crm_take_photo(p_path text, p_hr_id text, p_seat_id text, p_purpose text, p_is_test boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_take_voice(text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_take_voice(p_path text, p_hr_id text, p_seat_id text, p_is_test boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_slot public.phoenix_crm_voice_uploads%rowtype;
begin
  select u.* into v_slot
  from public.phoenix_crm_voice_uploads u
  where u.path = p_path
  for update;

  if not found
    or v_slot.issued_to_hr_id <> upper(trim(p_hr_id))
    or v_slot.seat_id <> p_seat_id
    or v_slot.is_test <> p_is_test then
    raise exception 'phoenix_crm:voice_not_issued';
  end if;
  if v_slot.used_at is not null then
    raise exception 'phoenix_crm:voice_used';
  end if;
  -- The same two hours the photo slot allows. Here it bounds nothing about dating, because nothing
  -- here dates anything — it bounds how long a signed upload URL is worth stealing.
  if v_slot.issued_at < now() - interval '2 hours' then
    raise exception 'phoenix_crm:voice_expired';
  end if;
  if not exists (
    select 1 from storage.objects o where o.bucket_id = 'phoenix-crm-voice' and o.name = p_path
  ) then
    raise exception 'phoenix_crm:voice_missing';
  end if;

  update public.phoenix_crm_voice_uploads u set used_at = now() where u.path = p_path;
end;
$$;

ALTER FUNCTION public.phoenix_crm_take_voice(p_path text, p_hr_id text, p_seat_id text, p_is_test boolean) OWNER TO postgres;

--
-- Name: phoenix_crm_territory_customers(text, boolean, text[], uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_territory_customers(p_seat_id text, p_is_test boolean, p_statuses text[] DEFAULT NULL::text[], p_customer_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with customers as (
    select c.*
    from public.phoenix_crm_customers c
    where c.seat_id = p_seat_id
      and c.is_test = p_is_test
      and c.campaign_visit_holder = false
      and (p_statuses is null or c.status = any(p_statuses))
      and (p_customer_ids is null or c.id = any(p_customer_ids))
  ),
  places as (
    select p.*
    from public.phoenix_crm_places p
    where p.seat_id = p_seat_id
      and p.is_test = p_is_test
      and p.status = 'active'
      and (p_customer_ids is null or p.customer_id = any(p_customer_ids))
  ),
  venues as (
    select v.id, v.name, v.kind, v.schedule_photo_path, v.status
    from public.phoenix_crm_shared_places v
    where v.id in (select distinct p.shared_place_id from places p where p.shared_place_id is not null)
  )
  select jsonb_build_object(
    'customers', coalesce((select jsonb_agg(to_jsonb(c.*) order by c.id) from customers c), '[]'::jsonb),
    'places', coalesce(
      (select jsonb_agg(
         ((to_jsonb(p.*) - 'signboard_check' - 'schedule_check') || jsonb_build_object('signboard_retake', p.signboard_check -> 'retake'))
         order by p.id
       ) from places p),
      '[]'::jsonb
    ),
    'venues', coalesce((select jsonb_agg(to_jsonb(v.*) order by v.id) from venues v), '[]'::jsonb)
  );
$$;

ALTER FUNCTION public.phoenix_crm_territory_customers(p_seat_id text, p_is_test boolean, p_statuses text[], p_customer_ids uuid[]) OWNER TO postgres;

--
-- Name: phoenix_crm_unplanned_a_reviewer_on_the_visit_skips_himself(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_unplanned_a_reviewer_on_the_visit_skips_himself() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'manager_pending'
    and new.manager_hr_id is not null
    and exists (
      select 1 from public.phoenix_crm_visits v
      where v.id = new.visit_id
        and upper(btrim(new.manager_hr_id)) in (
          upper(btrim(coalesce(v.manager_hr_id, ''))),
          upper(btrim(coalesce(v.senior_hr_id, ''))),
          upper(btrim(coalesce(v.product_manager_hr_id, '')))
        )
    ) or (
      new.status = 'manager_pending'
      and new.manager_hr_id is not null
      -- Anyone else who came (2026-10-27): the save writes this list before the off-plan row.
      and exists (
        select 1 from public.phoenix_crm_visit_companions c
        where c.visit_id = new.visit_id
          and c.hr_id = upper(btrim(new.manager_hr_id))
      )
    ) then
    new.status := 'sfe_pending';
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.phoenix_crm_unplanned_a_reviewer_on_the_visit_skips_himself() OWNER TO postgres;

--
-- Name: phoenix_crm_unplanned_route_past_a_reviewer_on_the_visit(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_unplanned_route_past_a_reviewer_on_the_visit(p_visit_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_on text[];
begin
  if p_visit_id is null then
    return;
  end if;
  -- The same lock the decision and the Administrator's review take, so a correction cannot cross a decision.
  perform pg_advisory_xact_lock(hashtext('phoenix_crm:unplanned:' || p_visit_id::text));
  -- Everyone on the visit: the fixed places and phoenix_crm_visit_companions, upper-cased and trimmed.
  v_on := public.phoenix_crm_visit_companion_ids(p_visit_id);

  update public.phoenix_crm_unplanned_visits u
  set status = case when u.status = 'manager_pending' then 'sfe_pending' else u.status end,
      after_admin_status = case when u.status = 'admin_pending' then 'sfe_pending' else u.after_admin_status end,
      version = u.version + 1,
      updated_at = now()
  where u.visit_id = p_visit_id
    and u.manager_hr_id is not null
    and upper(btrim(u.manager_hr_id)) = any (v_on)
    and (
      u.status = 'manager_pending'
      or (u.status = 'admin_pending' and u.after_admin_status = 'manager_pending')
    );
end;
$$;

ALTER FUNCTION public.phoenix_crm_unplanned_route_past_a_reviewer_on_the_visit(p_visit_id uuid) OWNER TO postgres;

--
-- Name: phoenix_crm_unplanned_waits_for_the_administrator(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_unplanned_waits_for_the_administrator() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status in ('manager_pending', 'sfe_pending')
    and exists (
      select 1 from public.phoenix_crm_visit_recordings r
      where r.visit_id = new.visit_id and r.review_status = 'pending'
    ) then
    new.after_admin_status := new.status;
    new.status := 'admin_pending';
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.phoenix_crm_unplanned_waits_for_the_administrator() OWNER TO postgres;

--
-- Name: phoenix_crm_update_place(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_update_place(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_action text := coalesce(p ->> 'action', '');
  v_reason text := nullif(regexp_replace(trim(coalesce(p ->> 'reason', '')), '\s+', ' ', 'g'), '');
  v_status text;
  v_place public.phoenix_crm_places%rowtype;
  v_after public.phoenix_crm_places%rowtype;
begin
  if v_seat is null or v_actor is null or nullif(p ->> 'place_id', '') is null or v_action not in ('edit', 'retire') then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select pl.* into v_place
  from public.phoenix_crm_places pl
  where pl.id = (p ->> 'place_id')::uuid
    and pl.seat_id = v_seat
    and pl.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:place_not_found';
  end if;
  if v_place.status <> 'active' then
    raise exception 'phoenix_crm:place_retired';
  end if;

  select c.status into v_status from public.phoenix_crm_customers c where c.id = v_place.customer_id;
  if v_status = 'dropped' then
    raise exception 'phoenix_crm:archived';
  end if;

  if v_action = 'edit' then
    if jsonb_typeof(p -> 'timings') is distinct from 'array' or jsonb_array_length(p -> 'timings') = 0 then
      raise exception 'phoenix_crm:bad_input';
    end if;
    update public.phoenix_crm_places pl
    set timings = p -> 'timings',
        label = nullif(trim(coalesce(p ->> 'label', '')), ''),
        updated_at = now()
    where pl.id = v_place.id
    returning pl.* into v_after;

    insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
    values (
      v_seat, v_place.customer_id, v_place.id, 'place_updated', v_actor,
      jsonb_build_object(
        'before', jsonb_build_object('timings', v_place.timings, 'label', v_place.label),
        'after', jsonb_build_object('timings', v_after.timings, 'label', v_after.label)
      ),
      v_is_test
    );
  else
    if v_reason is null or char_length(v_reason) < 10 or char_length(v_reason) > 500 then
      raise exception 'phoenix_crm:reason_required';
    end if;
    if not exists (
      select 1
      from public.phoenix_crm_places pl
      where pl.customer_id = v_place.customer_id
        and pl.status = 'active'
        and pl.id <> v_place.id
    ) then
      raise exception 'phoenix_crm:last_place';
    end if;
    update public.phoenix_crm_places pl
    set status = 'retired', retired_at = now(), retired_by_hr_id = v_actor, updated_at = now()
    where pl.id = v_place.id;

    insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
    values (
      v_seat, v_place.customer_id, v_place.id, 'place_retired', v_actor,
      jsonb_build_object('reason', v_reason, 'label', v_place.label, 'lat', v_place.lat, 'lon', v_place.lon),
      v_is_test
    );
  end if;

  return jsonb_build_object('place_id', v_place.id, 'customer_id', v_place.customer_id);
end;
$$;

ALTER FUNCTION public.phoenix_crm_update_place(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_validate_customer(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_validate_customer(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_line text := nullif(trim(coalesce(p ->> 'line_code', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_mode text := coalesce(p ->> 'mode', '');
  v_first_stage text := coalesce(nullif(p ->> 'first_stage', ''), 'manager');
  v_phone text := nullif(regexp_replace(coalesce(p ->> 'phone', ''), '\s+', '', 'g'), '');
  -- 2026-10-03: the Google check. `hold_review` holds the place for the Super Admin; `google` is the
  -- listing a matched place stood at. Both optional: a caller that sends neither gets the old function.
  v_hold jsonb := case when jsonb_typeof(p -> 'hold_review') = 'object' then p -> 'hold_review' end;
  v_google jsonb := case when jsonb_typeof(p -> 'google') = 'object' then p -> 'google' end;
  v_review_id uuid;
  v_customer public.phoenix_crm_customers%rowtype;
  v_ref record;
  v_name text;
  v_name_key text;
  v_list_type text;
  v_grade text;
  v_place jsonb;
  v_request_id uuid;
  v_request_kind text;
  v_event text := 'customer_validated';
  -- 2026-10-14: a seating in a venue the Super Admin has not decided yet. The customer is SAVED and can be
  -- planned, sent and visited, but he is not validated, so no KPI counts him until the venue is approved.
  v_venue_held boolean := false;
  v_validate_now boolean := true;
  -- 2026-11-07 (owner): a clinic doctor listed with only one or two names is validated with all three. The
  -- app sends the full name, already judged against the signboard, and it is written in this same
  -- transaction, so a refused validation writes no name. Optional: a caller that sends none gets the old
  -- function.
  v_full_name text := nullif(regexp_replace(trim(coalesce(p ->> 'full_name', '')), '\s+', ' ', 'g'), '');
begin
  if v_seat is null or v_line is null or v_actor is null or jsonb_typeof(p -> 'place') is distinct from 'object'
    or v_first_stage not in ('manager', 'sfe') then
    raise exception 'phoenix_crm:bad_input';
  end if;
  if v_phone is not null and v_phone !~ '^\+?[0-9]{7,15}$' then
    raise exception 'phoenix_crm:bad_phone';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  -- 🔴 READ UNDER THE SEAT'S LOCK, which phoenix_crm_decide_shared_place takes too, so an approval cannot
  -- land between this read and the insert below and leave a customer pending in an approved building.
  if nullif(p -> 'place' ->> 'shared_place_id', '') is not null then
    select (s.status = 'held') into v_venue_held
    from public.phoenix_crm_shared_places s
    where s.id = (p -> 'place' ->> 'shared_place_id')::uuid;
    v_venue_held := coalesce(v_venue_held, false);
  end if;
  v_validate_now := v_hold is null and not v_venue_held;

  if v_mode = 'reference' then
    select r.* into v_ref
    from public.phoenix_crm_reference_entry(v_seat, (p ->> 'reference_contact_crm_id')::bigint, v_is_test) r;
    if not found then
      raise exception 'phoenix_crm:not_on_reference_list';
    end if;
    if v_ref.state = 'validated' then
      raise exception 'phoenix_crm:already_validated';
    end if;
    -- A customer in the Archive comes back only through "Ask to bring back" — the district manager,
    -- then SFE (owner, 2026-09-29). Re-validating him was a door around that decision.
    if v_ref.state = 'dropped' then
      raise exception 'phoenix_crm:archived';
    end if;
    -- His location is already with the Super Admin: a second validation would add a second place
    -- beside the one being checked.
    if v_ref.customer_id is not null and exists (
      select 1 from public.phoenix_crm_validation_reviews r
      where r.customer_id = v_ref.customer_id and r.status = 'pending'
    ) then
      raise exception 'phoenix_crm:location_in_review';
    end if;

    if v_ref.customer_id is not null then
      perform 1 from public.phoenix_crm_customers c where c.id = v_ref.customer_id for update;

      if v_validate_now then
        update public.phoenix_crm_customers c
        set status = 'active',
            validated_at = now(),
            validated_by_hr_id = v_actor,
            dropped_reason = null,
            dropped_note = null,
            status_changed_at = now(),
            phone = coalesce(v_phone, c.phone),
            updated_at = now()
        where c.id = v_ref.customer_id
        returning c.* into v_customer;
      else
        -- Held: the place is saved, the customer is not validated until the Super Admin decides.
        update public.phoenix_crm_customers c
        set phone = coalesce(v_phone, c.phone),
            updated_at = now()
        where c.id = v_ref.customer_id
        returning c.* into v_customer;
      end if;
    else
      insert into public.phoenix_crm_customers (
        seat_id, line_code, list_type, name, speciality, grade, origin, reference_contact_crm_id,
        status, validated_at, validated_by_hr_id, created_by_hr_id, is_test, phone
      )
      values (
        v_seat, v_line, v_ref.list_type, left(v_ref.name, 200), left(v_ref.speciality, 120), v_ref.grade, 'reference', v_ref.contact_crm_id,
        case when v_validate_now then 'active' else 'pending' end,
        case when v_validate_now then now() end,
        case when v_validate_now then v_actor end,
        v_actor, v_is_test, v_phone
      )
      returning * into v_customer;
    end if;

    if v_validate_now then
      with withdrawn as (
        update public.phoenix_crm_list_requests q
        set status = 'withdrawn',
            stage = null,
            decided_at = now(),
            decided_by_hr_id = v_actor,
            decision_note = 'Validated instead of dropped'
        where q.seat_id = v_seat
          and q.is_test = v_is_test
          and q.kind = 'drop'
          and q.status = 'pending'
          and (
            q.customer_id = v_customer.id
            or (q.customer_id is null and q.reference_contact_crm_id = v_ref.contact_crm_id)
          )
        returning q.id
      )
      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      select v_seat, v_customer.id, w.id, 'request_withdrawn', v_actor, jsonb_build_object('why', 'validated'), v_is_test
      from withdrawn w;
    end if;

  elsif v_mode = 'listed' then
    -- A customer the SFE loaded from a sheet: already on the list, already graded by him, and carrying
    -- no iReports360 contact at all — so `phoenix_crm_reference_entry` can never find him and the
    -- reference branch above cannot serve him. He is validated at the door like any other.
    select c.* into v_customer
    from public.phoenix_crm_customers c
    where c.id = (p ->> 'customer_id')::uuid
      and c.seat_id = v_seat
      and c.is_test = v_is_test
    for update;
    if not found then
      raise exception 'phoenix_crm:customer_not_found';
    end if;
    if v_customer.status = 'dropped' then
      -- The Archive is frozen. He comes back through "Ask to bring back", never through a validation.
      raise exception 'phoenix_crm:archived';
    end if;
    if v_customer.status <> 'pending' then
      raise exception 'phoenix_crm:already_validated';
    end if;
    if exists (
      select 1 from public.phoenix_crm_validation_reviews r
      where r.customer_id = v_customer.id and r.status = 'pending'
    ) then
      raise exception 'phoenix_crm:location_in_review';
    end if;

    if v_validate_now then
      update public.phoenix_crm_customers c
      set status = 'active',
          validated_at = now(),
          validated_by_hr_id = v_actor,
          status_changed_at = now(),
          phone = coalesce(v_phone, c.phone),
          updated_at = now()
      where c.id = v_customer.id
      returning c.* into v_customer;

      with withdrawn as (
        update public.phoenix_crm_list_requests q
        set status = 'withdrawn',
            stage = null,
            decided_at = now(),
            decided_by_hr_id = v_actor,
            decision_note = 'Validated instead of dropped'
        where q.seat_id = v_seat
          and q.is_test = v_is_test
          and q.kind = 'drop'
          and q.status = 'pending'
          and q.customer_id = v_customer.id
        returning q.id
      )
      insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
      select v_seat, v_customer.id, w.id, 'request_withdrawn', v_actor, jsonb_build_object('why', 'validated'), v_is_test
      from withdrawn w;
    else
      update public.phoenix_crm_customers c
      set phone = coalesce(v_phone, c.phone),
          updated_at = now()
      where c.id = v_customer.id
      returning c.* into v_customer;
    end if;

  elsif v_mode in ('new', 'outside') then
    v_name := nullif(regexp_replace(trim(coalesce(p ->> 'name', '')), '\s+', ' ', 'g'), '');
    v_list_type := coalesce(p ->> 'list_type', '');
    v_grade := nullif(p ->> 'proposed_grade', '');
    if v_name is null or v_list_type not in ('AM', 'PM')
      or (v_mode = 'new' and coalesce(v_grade, '') not in ('A', 'B', 'C'))
      or (v_grade is not null and v_grade not in ('A', 'B', 'C')) then
      raise exception 'phoenix_crm:bad_input';
    end if;
    -- 2026-10-12: the DOOR folds the name, exactly as the bulk loader has since 2026-10-05 (owner:
    -- "ONE CUSTOMER, ONE NAME KEY — THE LOADER FOLDS THE NAME, IT DOES NOT lower() IT"). That rule was
    -- written about the loader and the door was simply not in the change, so lower() kept letting a
    -- second row for the same doctor through: 7 live groups and 9 rows in production on 2026-10-12,
    -- every one of them an honorific ("د.محمود سعد" beside "محمود سعد") or an alef/yeh spelling
    -- ("أشرف إدوارد" beside "اشرف ادوارد"). phoenix_crm_fold_name is the one authority on the key.
    --
    -- Three fences, all the owner's: it only ever SKIPS — nothing is merged, nothing is deleted, and
    -- there is NO unique index, because 55 live duplicate groups could not satisfy one; the scope stays
    -- the SEAT and the list (594 of 624 production pairs straddle two lines and are correct); and the
    -- key is never identityNameKey, which collapses محمود onto محمد.
    --
    -- An empty fold is NOT a key. The function returns '' for a name that folds away to nothing, and
    -- comparing '' would collide every such row onto one customer, so an empty key skips the check —
    -- the same reading the loader takes.
    v_name_key := public.phoenix_crm_fold_name(v_name);
    if not coalesce((p ->> 'allow_same_name')::boolean, false) and v_name_key <> '' and exists (
      select 1
      from public.phoenix_crm_customers c
      where c.seat_id = v_seat
        and c.is_test = v_is_test
        and c.status in ('active', 'pending', 'outside')
        and c.list_type = v_list_type
        and public.phoenix_crm_fold_name(c.name) = v_name_key
    ) then
      raise exception 'phoenix_crm:same_name';
    end if;

    insert into public.phoenix_crm_customers (
      seat_id, line_code, list_type, name, speciality, grade, origin, status, validated_at,
      validated_by_hr_id, created_by_hr_id, is_test, phone
    )
    values (
      v_seat, v_line, v_list_type, v_name, nullif(trim(coalesce(p ->> 'speciality', '')), ''), null, 'new', 'outside', null,
      null, v_actor, v_is_test, v_phone
    )
    returning * into v_customer;
    v_event := 'customer_met_outside';

    -- 2026-11-11 (sweep): an OUTSIDE customer with a grade is filed for approval too. The owner's rule is
    -- that a customer met outside the list is approved by the district manager and then SFE, but only
    -- `new` filed the request, so 159 outside customers and their visits waited with nobody asked. The
    -- rep's form now asks the grade on the outside entry as well; without one (an older phone) nothing
    -- changes and the customer waits as before.
    if v_mode = 'new' or v_grade is not null then
      insert into public.phoenix_crm_list_requests (
        seat_id, line_code, kind, customer_id, list_type, customer_name, current_grade, proposed_grade,
        requested_by_hr_id, is_test, stage
      )
      values (v_seat, v_line, 'add', v_customer.id, v_list_type, v_name, null, v_grade, v_actor, v_is_test, v_first_stage)
      returning id into v_request_id;
      v_request_kind := 'add';
    end if;

  -- The `restore` mode was retired on 2026-10-02: it inserted an ACTIVE place onto a customer sitting in
  -- the Archive, with no status check and outside the five-clinic cap. `listed` above is the shape it
  -- should always have had — a customer on the list, by id, `pending` only.
  else
    raise exception 'phoenix_crm:bad_input';
  end if;

  -- 2026-11-07: the three names the rep wrote at the door become the customer's name, through the rep's own
  -- rename (the name key, the contact's name row and the history move exactly as when he saves a name), and a
  -- full name the Super Admin was holding for him is settled by it. Only a listed customer: a new or outside
  -- customer already carries the name he typed.
  if v_full_name is not null and v_mode in ('reference', 'listed')
    and v_full_name is distinct from v_customer.name then
    perform public.phoenix_crm_rename_customer(jsonb_build_object(
      'seat_id', v_seat,
      'actor_hr_id', v_actor,
      'is_test', v_is_test,
      'customer_id', v_customer.id,
      'name', v_full_name,
      'speciality', v_customer.speciality,
      'allow_same_name', true
    ));
  end if;
  if v_full_name is not null and v_mode in ('reference', 'listed') then
    update public.phoenix_crm_customers c
    set full_name_held = null,
        full_name_held_at = null,
        full_name_held_by_hr_id = null,
        full_name_held_score = null,
        full_name_held_board = null,
        updated_at = now()
    where c.id = v_customer.id
      and c.full_name_held is not null;
    select c.* into v_customer from public.phoenix_crm_customers c where c.id = v_customer.id;
  end if;

  -- 2026-10-12: the five-place cap, which this path never had. phoenix_crm_add_place checks it and
  -- then calls phoenix_crm_insert_place; this function called insert_place DIRECTLY, so validating a
  -- listed customer who already holds five clinics added a sixth. Nothing pinned its absence, and the
  -- comment on the retired `restore` mode above has said "outside the five-clinic cap" since
  -- 2026-10-02 about exactly this shape. Production on 2026-10-12 holds no customer at or over the cap
  -- (the most on one is 2), so this is prevention, not a repair. Verbatim from add_place, including the
  -- error name, which src/lib/phoenix-crm/server/db.ts already answers 409 "A customer can have at
  -- most five places." for — a new error code would have reached the rep as an unexplained failure.
  if (select count(*) from public.phoenix_crm_places pl where pl.customer_id = v_customer.id and pl.status = 'active') >= 5 then
    raise exception 'phoenix_crm:too_many_places';
  end if;

  v_place := public.phoenix_crm_insert_place(v_customer.id, v_seat, v_actor, v_is_test, p -> 'place');

  if v_hold is not null and v_event = 'customer_validated' then
    v_event := 'validation_held';
  end if;
  -- A seating in a venue still waiting for the Super Admin leaves the customer pending, and the event says
  -- so — never 'customer_validated' for a customer no KPI counts.
  if v_venue_held and v_hold is null and v_customer.status = 'pending' and v_event = 'customer_validated' then
    v_event := 'customer_pending';
  end if;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
  values (
    v_seat, v_customer.id, (v_place ->> 'place_id')::uuid, v_event, v_actor,
    jsonb_build_object('mode', v_mode, 'reference_contact_crm_id', v_customer.reference_contact_crm_id)
      || case when v_event = 'customer_pending' then jsonb_build_object('why', 'venue_held', 'shared_place_id', p -> 'place' ->> 'shared_place_id') else '{}'::jsonb end
      || case when v_google is not null then jsonb_build_object('google', v_google) else '{}'::jsonb end,
    v_is_test
  );

  if v_hold is not null then
    insert into public.phoenix_crm_validation_reviews (seat_id, customer_id, place_id, is_test, kind, google, created_by_hr_id)
    values (v_seat, v_customer.id, (v_place ->> 'place_id')::uuid, v_is_test, 'validation', v_hold, v_actor)
    returning id into v_review_id;
    -- An outside customer's own event names his arrival; the hold gets its line beside it.
    if v_event <> 'validation_held' then
      insert into public.phoenix_crm_list_events (seat_id, customer_id, place_id, event_type, actor_hr_id, details, is_test)
      values (v_seat, v_customer.id, (v_place ->> 'place_id')::uuid, 'validation_held', v_actor, jsonb_build_object('mode', v_mode), v_is_test);
    end if;
  end if;

  if v_request_id is not null then
    insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
    values (
      v_seat, v_customer.id, v_request_id, 'request_created', v_actor,
      jsonb_build_object('kind', v_request_kind, 'proposed_grade', v_grade, 'stage', v_first_stage), v_is_test
    );
  end if;

  return jsonb_build_object(
    'customer_id', v_customer.id,
    'customer_name', v_customer.name,
    'list_type', v_customer.list_type,
    'status', v_customer.status,
    'place_id', v_place ->> 'place_id',
    'captured_at', v_place ->> 'captured_at',
    'restored', false,
    'grade_request_id', v_request_id,
    'request_id', v_request_id,
    'request_kind', v_request_kind,
    'phone', v_customer.phone,
    'held', v_hold is not null,
    'review_id', v_review_id
  );
end;
$_$;

ALTER FUNCTION public.phoenix_crm_validate_customer(p jsonb) OWNER TO postgres;

--
-- Name: phoenix_crm_validated_place_facts(uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_validated_place_facts(p_place_ids uuid[], p_customer_ids uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
  select jsonb_build_object(
    'customers', coalesce((
      select jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'list_type', c.list_type, 'speciality', c.speciality))
      from public.phoenix_crm_customers c
      where c.id = any(p_customer_ids)
    ), '[]'::jsonb),
    'reviews', coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'place_id', r.place_id, 'status', r.status, 'decided_by_hr_id', r.decided_by_hr_id, 'decided_at', r.decided_at))
      from public.phoenix_crm_validation_reviews r
      where r.customer_id = any(p_customer_ids)
    ), '[]'::jsonb),
    'visit_counts', coalesce((
      select jsonb_object_agg(v.place_id, v.n)
      from (
        select place_id, count(*) as n
        from public.phoenix_crm_visits
        where place_id = any(p_place_ids)
        group by place_id
      ) v
    ), '{}'::jsonb),
    'active_places', coalesce((
      select jsonb_object_agg(p.customer_id, p.n)
      from (
        select customer_id, count(*) as n
        from public.phoenix_crm_places
        where customer_id = any(p_customer_ids) and status = 'active'
        group by customer_id
      ) p
    ), '{}'::jsonb)
  );
$$;

ALTER FUNCTION public.phoenix_crm_validated_place_facts(p_place_ids uuid[], p_customer_ids uuid[]) OWNER TO postgres;

--
-- Name: phoenix_crm_venue_cap_board(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_venue_cap_board(p_seats text[]) RETURNS TABLE(shared_place_id uuid, seat_id text, name text, kind text, status text, seated integer, daily_cap integer, daily_cap_set_by_hr_id text, daily_cap_set_at timestamp with time zone, lifted boolean, lifted_by_hr_id text, lifted_at timestamp with time zone, unplanned_free boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select sp.id,
         sp.seat_id,
         sp.name,
         sp.kind,
         sp.status,
         (
           select count(*)::integer
           from public.phoenix_crm_places pl
           where pl.shared_place_id = sp.id and pl.retired_at is null and not pl.is_test
         ),
         sp.daily_cap,
         sp.daily_cap_set_by_hr_id,
         sp.daily_cap_set_at,
         lift.id is not null,
         lift.granted_by_hr_id,
         lift.created_at,
         partial.id is not null
  from public.phoenix_crm_shared_places sp
  left join lateral (
    select e.id, e.granted_by_hr_id, e.created_at
    from public.phoenix_crm_offplan_exemptions e
    where e.seat_id = sp.seat_id
      and e.ended_at is null
      and e.lifts_venue_cap
      and (
        e.shared_place_id = sp.id
        or (e.venue_name_key is not null and public.phoenix_crm_fold_name(sp.name) like '%' || e.venue_name_key || '%')
      )
    order by e.created_at desc
    limit 1
  ) lift on true
  left join lateral (
    select e.id
    from public.phoenix_crm_offplan_exemptions e
    where e.seat_id = sp.seat_id
      and e.ended_at is null
      and not e.lifts_venue_cap
      and (
        e.shared_place_id = sp.id
        or (e.venue_name_key is not null and public.phoenix_crm_fold_name(sp.name) like '%' || e.venue_name_key || '%')
      )
    limit 1
  ) partial on true
  where sp.seat_id = any(p_seats)
    and sp.retired_at is null
    and not sp.is_test
  order by sp.name, sp.id;
$$;

ALTER FUNCTION public.phoenix_crm_venue_cap_board(p_seats text[]) OWNER TO postgres;

--
-- Name: phoenix_crm_venue_cap_lifted(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_venue_cap_lifted(p_seat text) RETURNS TABLE(shared_place_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct sp.id
  from public.phoenix_crm_offplan_exemptions e
  join public.phoenix_crm_shared_places sp on sp.seat_id = e.seat_id
  where e.seat_id = p_seat
    and e.ended_at is null
    and e.lifts_venue_cap
    and (
      e.shared_place_id = sp.id
      or (
        e.venue_name_key is not null
        and public.phoenix_crm_fold_name(sp.name) like '%' || e.venue_name_key || '%'
      )
    );
$$;

ALTER FUNCTION public.phoenix_crm_venue_cap_lifted(p_seat text) OWNER TO postgres;

--
-- Name: phoenix_crm_venue_cap_set(text[], uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_venue_cap_set(p_seats text[], p_shared_place uuid, p_action text, p_cap integer, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_place public.phoenix_crm_shared_places%rowtype;
  v_setting integer;
  v_fold text;
  v_flag boolean;
  v_row record;
  v_other record;
  v_account uuid;
begin
  if p_shared_place is null
     or coalesce(trim(p_actor), '') = ''
     or coalesce(p_action, '') not in ('lift', 'unlift', 'end_partial', 'raise', 'standard') then
    raise exception 'phoenix_crm:bad_input';
  end if;

  select * into v_place
  from public.phoenix_crm_shared_places sp
  where sp.id = p_shared_place
    and sp.seat_id = any(p_seats)
    and sp.retired_at is null
    and not sp.is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:venue_not_on_seat';
  end if;
  v_fold := public.phoenix_crm_fold_name(v_place.name);

  if p_action = 'lift' then
    if not exists (select 1 from public.phoenix_crm_venue_cap_lifted(v_place.seat_id) l where l.shared_place_id = v_place.id) then
      select e.customer_id into v_account
      from public.phoenix_crm_offplan_exemptions e
      where e.seat_id = v_place.seat_id
        and e.lifts_venue_cap
        and e.customer_id is not null
        and e.ended_at is not null
        and e.ended_by_hr_id is not null
        and (
          e.shared_place_id = v_place.id
          or (e.venue_name_key is not null and v_fold like '%' || e.venue_name_key || '%')
        )
      order by e.ended_at desc
      limit 1;

      insert into public.phoenix_crm_offplan_exemptions
        (seat_id, label, shared_place_id, customer_id, note, granted_by_hr_id, lifts_venue_cap)
      values
        (v_place.seat_id, v_place.name, v_place.id, v_account, 'Switched on from the Polyclinic Caps page.', p_actor, true);
    end if;

  elsif p_action in ('unlift', 'end_partial') then
    v_flag := p_action = 'unlift';
    for v_row in
      select e.id, e.venue_name_key, e.customer_id
      from public.phoenix_crm_offplan_exemptions e
      where e.seat_id = v_place.seat_id
        and e.ended_at is null
        and e.lifts_venue_cap = v_flag
        and (
          e.shared_place_id = v_place.id
          or (e.venue_name_key is not null and v_fold like '%' || e.venue_name_key || '%')
        )
      for update of e
    loop
      if v_row.venue_name_key is not null then
        v_account := v_row.customer_id;
        if exists (
          select 1 from public.phoenix_crm_places pl
          where pl.customer_id = v_account and pl.shared_place_id = v_place.id and pl.retired_at is null
        ) then
          v_account := null;
        end if;

        -- A live venue first, so the account lands on a venue that is in use.
        for v_other in
          select other.id, other.seat_id, other.name
          from public.phoenix_crm_shared_places other
          where other.seat_id = v_place.seat_id
            and other.id <> v_place.id
            and not other.is_test
            and public.phoenix_crm_fold_name(other.name) like '%' || v_row.venue_name_key || '%'
          order by (other.retired_at is null) desc, other.name, other.id
        loop
          update public.phoenix_crm_offplan_exemptions kept
             set customer_id = coalesce(kept.customer_id, v_account)
           where kept.shared_place_id = v_other.id and kept.lifts_venue_cap = v_flag and kept.ended_at is null;
          if not found then
            insert into public.phoenix_crm_offplan_exemptions
              (seat_id, label, shared_place_id, customer_id, note, granted_by_hr_id, lifts_venue_cap)
            values
              (v_other.seat_id, v_other.name, v_other.id, v_account, 'Kept when a row that also named this venue was ended.', p_actor, v_flag);
          end if;
          v_account := null;
        end loop;
      end if;
      update public.phoenix_crm_offplan_exemptions
         set ended_at = now(), ended_by_hr_id = p_actor
       where id = v_row.id;
    end loop;

  elsif p_action = 'raise' then
    select s.shared_place_daily_cap into v_setting from public.phoenix_crm_settings s where s.id = 1;
    if p_cap is null or p_cap <= coalesce(v_setting, 3) or p_cap > 20 then
      raise exception 'phoenix_crm:venue_cap_out_of_range';
    end if;
    update public.phoenix_crm_shared_places
       set daily_cap = p_cap, daily_cap_set_by_hr_id = p_actor, daily_cap_set_at = now()
     where id = v_place.id;

  else
    update public.phoenix_crm_shared_places
       set daily_cap = null, daily_cap_set_by_hr_id = null, daily_cap_set_at = null
     where id = v_place.id;
  end if;

  return jsonb_build_object('sharedPlaceId', v_place.id, 'seatId', v_place.seat_id, 'action', p_action);
end;
$$;

ALTER FUNCTION public.phoenix_crm_venue_cap_set(p_seats text[], p_shared_place uuid, p_action text, p_cap integer, p_actor text) OWNER TO postgres;

--
-- Name: phoenix_crm_visit_companion_ids(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_visit_companion_ids(p_visit_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(array_agg(distinct x.hr_id order by x.hr_id), '{}'::text[])
  from (
    select upper(btrim(h)) as hr_id
    from public.phoenix_crm_visits v
    cross join lateral unnest(array[v.manager_hr_id, v.senior_hr_id, v.product_manager_hr_id]) as h
    where v.id = p_visit_id
      and v.rep_hr_id is not null
      and nullif(btrim(coalesce(h, '')), '') is not null
    union
    select c.hr_id
    from public.phoenix_crm_visit_companions c
    where c.visit_id = p_visit_id
  ) x;
$$;

ALTER FUNCTION public.phoenix_crm_visit_companion_ids(p_visit_id uuid) OWNER TO postgres;

--
-- Name: phoenix_crm_visits_old_system_far_archive(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_visits_old_system_far_archive() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.archive_reason is distinct from 'far' then
    delete from public.phoenix_crm_visit_archive a where a.visit_id = new.id and a.reason = 'far';
    return null;
  end if;

  insert into public.phoenix_crm_visit_archive (
    crm_visit_id, visit_date, agent_crm_id, agent_hr_id, agent_name, contact_crm_id, customer_name,
    visit_type, reason, visit_id, seat_id, line_code, archived_at,
    distance_meters, checkin_lat, checkin_lon, place_id, place_lat, place_lon
  )
  select iv.crm_visit_id, iv.visit_date, iv.agent_crm_id, nullif(btrim(iv.agent_hr_id), ''),
         nullif(btrim(iv.agent_name), ''), nullif(iv.contact_crm_id, 0), left(nullif(btrim(iv.contact_name), ''), 200),
         0, 'far', new.id, new.seat_id, new.line_code, new.archived_at,
         new.distance_meters, new.lat, new.lon, new.place_id, pl.lat, pl.lon
  from public.phoenix_crm_imported_visit_sources s
  join public.ireports360_visits iv on iv.crm_visit_id = s.crm_visit_id and iv.visit_type = 0
  join public.phoenix_crm_ireports360_checkin_matches m on m.crm_visit_id = s.crm_visit_id
  left join public.phoenix_crm_places pl on pl.id = new.place_id
  where s.visit_id = new.id
  order by iv.crm_visit_id
  on conflict (crm_visit_id) do update
    set distance_meters = excluded.distance_meters,
        checkin_lat = excluded.checkin_lat,
        checkin_lon = excluded.checkin_lon,
        place_id = excluded.place_id,
        place_lat = excluded.place_lat,
        place_lon = excluded.place_lon
    where phoenix_crm_visit_archive.reason = 'far';
  return null;
end;
$$;

ALTER FUNCTION public.phoenix_crm_visits_old_system_far_archive() OWNER TO postgres;

--
-- Name: phoenix_crm_visits_old_system_kpi(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_visits_old_system_kpi() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  -- Far BEYOND 500 m only: a far converted visit within 500 m is a normal visit, flagged (owner, 7 Nov 2026).
  v_far boolean := new.imported_from_ireports360_at is not null
    and new.ireports360_checkin_id is not null
    and new.place_id is not null
    and new.location_flag = 'far'
    and (new.distance_meters is null or new.distance_meters > 500);
begin
  if v_far and new.archived_at is null then
    new.archived_at := now();
    new.archive_reason := 'far';
  elsif not v_far and new.archive_reason = 'far' then
    new.archived_at := null;
    new.archive_reason := null;
  end if;

  new.ireports360_kpi_counted := new.imported_from_ireports360_at is not null
    and new.archived_at is null
    and new.ireports360_checkin_id is not null
    and new.lat is not null
    and new.place_id is not null
    and (
      new.location_flag in ('ok', 'weak_gps')
      or (new.location_flag = 'far' and new.distance_meters <= 500)
    );
  return new;
end;
$$;

ALTER FUNCTION public.phoenix_crm_visits_old_system_kpi() OWNER TO postgres;

