--
-- Name: phoenix_crm_week_due_on(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_week_due_on(p_week_start date) RETURNS date
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case p_week_start
    -- Owner, 2026-10-02: the Delta reps' week of 3 October, sent again on Friday after the wipe, is on time.
    when date '2026-10-03' then date '2026-10-02'
    else p_week_start - 2
  end;
$$;

