--
-- Name: phoenix_crm_withdraw_request(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phoenix_crm_withdraw_request(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seat text := nullif(trim(coalesce(p ->> 'seat_id', '')), '');
  v_actor text := upper(nullif(trim(coalesce(p ->> 'actor_hr_id', '')), ''));
  v_is_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_request public.phoenix_crm_list_requests%rowtype;
begin
  if v_seat is null or v_actor is null or nullif(p ->> 'request_id', '') is null then
    raise exception 'phoenix_crm:bad_input';
  end if;

  perform pg_advisory_xact_lock(hashtext('phoenix_crm:seat:' || v_seat));

  select q.* into v_request
  from public.phoenix_crm_list_requests q
  where q.id = (p ->> 'request_id')::uuid
    and q.seat_id = v_seat
    and q.is_test = v_is_test
  for update;
  if not found then
    raise exception 'phoenix_crm:request_not_found';
  end if;
  if v_request.status <> 'pending' then
    raise exception 'phoenix_crm:request_decided';
  end if;

  update public.phoenix_crm_list_requests q
  set status = 'withdrawn', stage = null, decided_at = now(), decided_by_hr_id = v_actor
  where q.id = v_request.id;

  insert into public.phoenix_crm_list_events (seat_id, customer_id, request_id, event_type, actor_hr_id, details, is_test)
  values (v_seat, v_request.customer_id, v_request.id, 'request_withdrawn', v_actor, jsonb_build_object('kind', v_request.kind), v_is_test);

  return jsonb_build_object('request_id', v_request.id, 'kind', v_request.kind, 'customer_name', v_request.customer_name);
end;
$$;

ALTER FUNCTION public.phoenix_crm_withdraw_request(p jsonb) OWNER TO postgres;

--
-- Name: monthly_closing_drift_acknowledgements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.monthly_closing_drift_acknowledgements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    line text NOT NULL,
    period text NOT NULL,
    drift_fingerprint text NOT NULL,
    drifted_cells integer NOT NULL,
    net_units_delta numeric NOT NULL,
    net_value_delta numeric,
    reason text NOT NULL,
    acknowledged_by text NOT NULL,
    acknowledged_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.monthly_closing_drift_acknowledgements OWNER TO postgres;

--
-- Name: TABLE monthly_closing_drift_acknowledgements; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.monthly_closing_drift_acknowledgements IS 'A person looked at a specific closing drift and accepted it. Scoped by fingerprint, never by line/period alone: if the drift changes the acknowledgement stops applying, so this can never hide a NEW restatement.';

--
-- Name: COLUMN monthly_closing_drift_acknowledgements.drift_fingerprint; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.monthly_closing_drift_acknowledgements.drift_fingerprint IS 'md5 over every drifted cell and BOTH its deltas, ordered. Includes the deltas on purpose: a price edit that moves value on the same cells must break the match. Proven on staging 2026-09-05 — a second price move on the SAME 49 cells flipped the verdict to CHANGED SINCE IT WAS ACKNOWLEDGED.';

--
-- Name: phx_acknowledge_closing_drift(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_acknowledge_closing_drift(p_line text, p_period text, p_actor text, p_reason text) RETURNS public.monthly_closing_drift_acknowledgements
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_fingerprint text := public.phx_closing_drift_fingerprint(p_line, p_period);
  v_cells integer;
  v_units numeric;
  v_value numeric;
  v_row   public.monthly_closing_drift_acknowledgements;
begin
  if btrim(coalesce(p_actor, '')) = '' then
    raise exception 'An acknowledgement must name who made it.';
  end if;
  if btrim(coalesce(p_reason, '')) = '' then
    raise exception 'An acknowledgement must say WHY the drift is expected.';
  end if;

  select count(*)::integer, coalesce(sum(d.units_delta), 0), sum(d.value_delta)
    into v_cells, v_units, v_value
  from public.phx_closing_publication_drift(p_line, p_period) d
  where d.area_code <> '(no snapshot)';

  if v_cells = 0 then
    raise exception 'There is no drift on % % to acknowledge.', p_line, p_period;
  end if;

  insert into public.monthly_closing_drift_acknowledgements
    (line, period, drift_fingerprint, drifted_cells, net_units_delta, net_value_delta, reason, acknowledged_by)
  values (p_line, p_period, v_fingerprint, v_cells, v_units, v_value, btrim(p_reason), btrim(p_actor))
  returning * into v_row;

  return v_row;
end;
$$;

ALTER FUNCTION public.phx_acknowledge_closing_drift(p_line text, p_period text, p_actor text, p_reason text) OWNER TO postgres;

--
-- Name: phx_admin_reset_module_data(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_admin_reset_module_data(p_module text, p_max_batches integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tables    jsonb := '[]'::jsonb;
  v_kept      jsonb := '[]'::jsonb;
  v_count     bigint;
  v_batch     uuid;
  v_batches   uuid[];
  v_limit     integer := greatest(coalesce(p_max_batches, 25), 1);
  v_remaining integer := 0;

  -- Source of Sales running totals, one per table, summed over the batches in this chunk.
  v_sos_summaries bigint := 0;
  v_sos_brick     bigint := 0;
  v_sos_channel   bigint := 0;
  v_sos_directory bigint := 0;
  v_sos_presence  bigint := 0;
  v_sos_distprod  bigint := 0;
  v_sos_fact      bigint := 0;
  v_sos_rows      bigint := 0;
  v_sos_batches   bigint := 0;

  -- Weekly Sales running totals.
  v_week_rows    bigint := 0;
  v_week_batches bigint := 0;

  -- What a live lock held back.
  v_kept_batches integer := 0;
  v_kept_rows    bigint  := 0;
  v_kept_periods text;
begin
  if p_module not in ('sales', 'weekly', 'marketing', 'all') then
    raise exception 'Invalid module: %. Must be sales, weekly, marketing, or all.', p_module;
  end if;

  ---------------------------------------------------------------- Source of Sales
  if p_module in ('sales', 'all') then
    -- Deletable batches only. A batch holding even one row of a locked closing is left whole.
    select coalesce(array_agg(pick.id), '{}'::uuid[])
      into v_batches
      from (
        select b.id
          from source_of_sales_import_batches b
         where not exists (
                 select 1
                   from source_of_sales_import_rows r
                   join monthly_closing_locks l
                     on l.period = r.invoice_period
                    and l.normalized_line = lower(btrim(coalesce(r.official_line, '')))
                    and l.unlocked_at is null
                  where r.batch_id = b.id
               )
         order by b.id
         limit v_limit
      ) pick;

    foreach v_batch in array v_batches loop
      delete from source_of_sales_import_summaries where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_summaries := v_sos_summaries + v_count;

      delete from source_of_sales_brick_move_files where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_brick := v_sos_brick + v_count;

      delete from source_of_sales_channel_customer_rollup where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_channel := v_sos_channel + v_count;

      delete from source_of_sales_customer_directory_rollup where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_directory := v_sos_directory + v_count;

      delete from source_of_sales_customer_presence_rollup where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_presence := v_sos_presence + v_count;

      delete from source_of_sales_distributor_product_rollup where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_distprod := v_sos_distprod + v_count;

      delete from source_of_sales_fact_rollup where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_fact := v_sos_fact + v_count;

      delete from source_of_sales_import_rows where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_rows := v_sos_rows + v_count;

      delete from source_of_sales_import_batches where id = v_batch;
      get diagnostics v_count = row_count;
      v_sos_batches := v_sos_batches + v_count;
    end loop;

    v_tables := v_tables
      || jsonb_build_array(
           jsonb_build_object('table', 'source_of_sales_import_summaries', 'deleted', v_sos_summaries),
           jsonb_build_object('table', 'source_of_sales_brick_move_files', 'deleted', v_sos_brick),
           jsonb_build_object('table', 'source_of_sales_channel_customer_rollup', 'deleted', v_sos_channel),
           jsonb_build_object('table', 'source_of_sales_customer_directory_rollup', 'deleted', v_sos_directory),
           jsonb_build_object('table', 'source_of_sales_customer_presence_rollup', 'deleted', v_sos_presence),
           jsonb_build_object('table', 'source_of_sales_distributor_product_rollup', 'deleted', v_sos_distprod),
           jsonb_build_object('table', 'source_of_sales_fact_rollup', 'deleted', v_sos_fact),
           jsonb_build_object('table', 'source_of_sales_import_rows', 'deleted', v_sos_rows),
           jsonb_build_object('table', 'source_of_sales_import_batches', 'deleted', v_sos_batches)
         );

    -- Everything a live lock held back, counted after the chunk so the number cannot drift.
    select count(*)::integer, coalesce(sum(held.row_count), 0)
      into v_kept_batches, v_kept_rows
      from (
        select (select count(*) from source_of_sales_import_rows r where r.batch_id = b.id) as row_count
          from source_of_sales_import_batches b
         where exists (
                 select 1
                   from source_of_sales_import_rows r
                   join monthly_closing_locks l
                     on l.period = r.invoice_period
                    and l.normalized_line = lower(btrim(coalesce(r.official_line, '')))
                    and l.unlocked_at is null
                  where r.batch_id = b.id
               )
      ) held;

    if v_kept_batches > 0 then
      select string_agg(distinct l.line || ' ' || l.period, ', ')
        into v_kept_periods
        from monthly_closing_locks l
       where l.unlocked_at is null
         and exists (
               select 1
                 from source_of_sales_import_rows r
                where r.invoice_period = l.period
                  and lower(btrim(coalesce(r.official_line, ''))) = l.normalized_line
             );

      v_kept := v_kept
        || jsonb_build_array(jsonb_build_object(
             'table', 'source_of_sales_import_batches',
             'batches', v_kept_batches,
             'rows', v_kept_rows,
             'reason', 'the monthly closing is still locked: ' || coalesce(v_kept_periods, 'unknown closing')
           ));
    end if;

    -- Deletable batches still waiting after this chunk.
    select count(*)::integer
      into v_count
      from source_of_sales_import_batches b
     where not exists (
             select 1
               from source_of_sales_import_rows r
               join monthly_closing_locks l
                 on l.period = r.invoice_period
                and l.normalized_line = lower(btrim(coalesce(r.official_line, '')))
                and l.unlocked_at is null
              where r.batch_id = b.id
           );
    v_remaining := v_remaining + v_count;
  end if;

  ---------------------------------------------------------------- Weekly Sales
  -- No lock guard and no triggers at all on these two; chunked only to keep each call short.
  if p_module in ('weekly', 'all') then
    select coalesce(array_agg(pick.id), '{}'::uuid[])
      into v_batches
      from (select b.id from weekly_sales_batches b order by b.id limit v_limit) pick;

    foreach v_batch in array v_batches loop
      delete from weekly_sales_rows where batch_id = v_batch;
      get diagnostics v_count = row_count;
      v_week_rows := v_week_rows + v_count;

      delete from weekly_sales_batches where id = v_batch;
      get diagnostics v_count = row_count;
      v_week_batches := v_week_batches + v_count;
    end loop;

    v_tables := v_tables
      || jsonb_build_array(
           jsonb_build_object('table', 'weekly_sales_rows', 'deleted', v_week_rows),
           jsonb_build_object('table', 'weekly_sales_batches', 'deleted', v_week_batches)
         );

    select count(*)::integer into v_count from weekly_sales_batches;
    v_remaining := v_remaining + v_count;
  end if;

  ---------------------------------------------------------------- Marketing Requests
  -- Small enough for one pass, and held to the final chunk so a long sales or weekly reset does
  -- not repeat it on every call.
  if p_module in ('marketing', 'all') and v_remaining = 0 then
    -- ON DELETE NO ACTION and NOT NULL: this row cannot be unlinked, only removed, and until it is
    -- it blocks the delete of `marketing_requests`.
    delete from direct_order_marketing_offsets where marketing_request_id is not null;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'direct_order_marketing_offsets', 'deleted', v_count));

    delete from marketing_roi_customer_facts where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_customer_facts', 'deleted', v_count));

    delete from marketing_roi_distributor_facts where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_distributor_facts', 'deleted', v_count));

    delete from marketing_roi_region_facts where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_region_facts', 'deleted', v_count));

    delete from marketing_roi_line_facts where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_line_facts', 'deleted', v_count));

    delete from marketing_roi_product_facts where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_product_facts', 'deleted', v_count));

    delete from marketing_roi_trend_facts where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_trend_facts', 'deleted', v_count));

    delete from marketing_roi_request_geo_facts where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_request_geo_facts', 'deleted', v_count));

    delete from marketing_roi_request_facts where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_request_facts', 'deleted', v_count));

    delete from marketing_roi_refresh_runs where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_refresh_runs', 'deleted', v_count));

    delete from marketing_roi_export_audit where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_roi_export_audit', 'deleted', v_count));

    delete from marketing_request_finance_requirements where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_request_finance_requirements', 'deleted', v_count));

    delete from marketing_request_approval_steps where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_request_approval_steps', 'deleted', v_count));

    delete from marketing_request_pharmacies where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_request_pharmacies', 'deleted', v_count));

    delete from marketing_request_products where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_request_products', 'deleted', v_count));

    -- `phx_capture_marketing_request_event` writes one `request_deleted` row per request as this
    -- runs. `marketing_request_events` is append-only by design and is never cleared here.
    delete from marketing_requests where true;
    get diagnostics v_count = row_count;
    v_tables := v_tables || jsonb_build_array(jsonb_build_object('table', 'marketing_requests', 'deleted', v_count));

    v_kept := v_kept
      || jsonb_build_array(jsonb_build_object(
           'table', 'marketing_request_events',
           'rows', (select count(*) from marketing_request_events),
           'reason', 'the request audit trail is append-only by design and is kept, with one request_deleted event added per deleted request'
         ));
  end if;

  return jsonb_build_object(
    'tables', v_tables,
    'kept', v_kept,
    'remaining', v_remaining,
    'done', v_remaining = 0
  );
end;
$$;

ALTER FUNCTION public.phx_admin_reset_module_data(p_module text, p_max_batches integer) OWNER TO postgres;

--
-- Name: FUNCTION phx_admin_reset_module_data(p_module text, p_max_batches integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_admin_reset_module_data(p_module text, p_max_batches integer) IS 'Admin "Reset module data". Every delete carries a WHERE clause, because safeupdate is preloaded on the PostgREST role and refuses a bare one. Source of Sales and Weekly Sales are cleared one BATCH at a time, at most p_max_batches per call; a batch holding any row of a still-locked monthly closing is kept whole and reported under "kept". Marketing runs in one pass on the last chunk. Returns {tables, kept, remaining, done}; the caller loops until done.';

--
-- Name: phx_admin_settle_service_fee(uuid, text, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_admin_settle_service_fee(p_order_id uuid, p_requester_hr_id text, p_request_type_code text, p_beneficiary_name text, p_amount numeric, p_note text, p_admin_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_amount        numeric(14, 2) := round(coalesce(p_amount, 0)::numeric, 2);
  v_name          text := regexp_replace(btrim(coalesce(p_beneficiary_name, '')), '\s+', ' ', 'g');
  v_normalized    text;
  v_order         public.direct_order_requests%rowtype;
  v_admin_id      text;
  v_req_id        text;
  v_req_manager   text;
  v_req_line      bigint;
  v_req_area      bigint;
  v_type_id       bigint;
  v_type_name     text;
  v_customer_id   uuid;
  v_request_id    uuid;
  v_request_code  text;
  v_template_id   uuid;
  v_other_offsets numeric(14, 2);
  v_outstanding   numeric(14, 2);
  v_remaining     numeric(14, 2);
  v_today         date := (now() at time zone 'Africa/Cairo')::date;
  v_note_text     text;
  v_offset_id     uuid;
  v_rungs         integer;
begin
  if v_amount <= 0 then
    raise exception 'service_fee_amount_invalid';
  end if;
  if v_name = '' then
    raise exception 'service_fee_beneficiary_required';
  end if;
  v_normalized := lower(v_name);

  select hr_id into v_admin_id from public.employees where upper(hr_id) = upper(btrim(coalesce(p_admin_hr_id, '')));
  if v_admin_id is null then
    raise exception 'service_fee_admin_unknown';
  end if;

  select hr_id, manager_hr_id, line_id, area_id
    into v_req_id, v_req_manager, v_req_line, v_req_area
    from public.employees where upper(hr_id) = upper(btrim(coalesce(p_requester_hr_id, '')));
  if v_req_id is null then
    raise exception 'service_fee_requester_unknown';
  end if;

  select id, name into v_type_id, v_type_name
    from public.marketing_request_types
   where code = p_request_type_code and active is true;
  if v_type_id is null then
    raise exception 'service_fee_type_unknown';
  end if;
  if p_request_type_code = 'other' and btrim(coalesce(p_note, '')) = '' then
    raise exception 'service_fee_description_required';
  end if;

  -- The order first, exactly as phx_record_direct_order_offset does, so two clicks cannot both pass.
  select * into v_order from public.direct_order_requests where id = p_order_id for update;
  if not found then
    raise exception 'offset_order_not_found';
  end if;
  if lower(coalesce(v_order.status, '')) <> 'approved' then
    raise exception 'offset_order_not_approved';
  end if;

  select coalesce(sum(amount), 0) into v_other_offsets
    from public.direct_order_marketing_offsets where direct_order_id = p_order_id;
  v_outstanding := round(coalesce(v_order.sales_value, 0)::numeric, 2)
                   - round(coalesce(v_order.paid_amount, 0)::numeric, 2)
                   - v_other_offsets;
  if v_amount > v_outstanding then
    raise exception 'offset_exceeds_outstanding';
  end if;

  -- A double click: the same amount settled against the same order by this path in the last ten minutes.
  if exists (
    select 1
      from public.direct_order_marketing_offsets o
      join public.marketing_requests r on r.id = o.marketing_request_id
     where o.direct_order_id = p_order_id
       and o.amount = v_amount
       and o.created_at > now() - interval '10 minutes'
       and r.notes like 'Recorded and executed by the Administrator%'
  ) then
    raise exception 'service_fee_duplicate';
  end if;

  -- The rungs are copied from the newest executed request, so the shape is the module's own.
  select r.id into v_template_id
    from public.marketing_requests r
   where r.executed_at is not null
     and r.status in ('active', 'roi_tracking', 'closed')
     and exists (select 1 from public.marketing_request_approval_steps s
                  where s.request_id = r.id and s.step_code = 'finance_execution')
   order by r.executed_at desc
   limit 1;
  if v_template_id is null then
    raise exception 'service_fee_chain_template_missing';
  end if;

  -- The beneficiary as a marketing customer (a doctor), found by name or created validated by the Administrator.
  select id into v_customer_id
    from public.marketing_customers
   where normalized_name = v_normalized
     and customer_type = 'doctor'
     and merged_into_customer_id is null
   order by created_at
   limit 1;
  if v_customer_id is null then
    insert into public.marketing_customers (
      customer_code, customer_type, display_name, normalized_name,
      owner_hr_id, manager_hr_id, line_id, area_id,
      validation_status, validated_by_hr_id, validated_at, validation_notes,
      created_by_hr_id, updated_by_hr_id
    ) values (
      'ADM-' || to_char(now() at time zone 'Africa/Cairo', 'YYYYMMDD') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)),
      'doctor', v_name, v_normalized,
      v_req_id, v_req_manager, v_req_line, v_req_area,
      'system_validated', v_admin_id, now(),
      'Added by the Administrator when settling a service fee against a direct order.',
      v_admin_id, v_admin_id
    ) returning id into v_customer_id;
  end if;

  v_note_text := 'Recorded and executed by the Administrator for a direct-order settlement; no cash moved. '
                 || coalesce(nullif(btrim(p_note), ''), 'Service fee kept by the hospital for ' || v_name || '.');
  v_request_code := 'MKT-REQ-' || to_char(now() at time zone 'Africa/Cairo', 'YYYYMMDD') || '-'
                    || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  insert into public.marketing_requests (
    request_code, requester_hr_id, manager_hr_id, line_id, area_id, customer_id, request_type_id,
    request_date, estimated_cost, status, notes, submitted_at, approved_at, executed_at,
    created_by_hr_id, updated_by_hr_id, track_direct_sales, origin
  ) values (
    v_request_code, v_req_id, v_req_manager, v_req_line, v_req_area, v_customer_id, v_type_id,
    v_today, v_amount, 'active', v_note_text, now(), now(), now(),
    v_admin_id, v_admin_id, false, 'phoenix'
  ) returning id into v_request_id;

  insert into public.marketing_request_approval_steps (
    request_id, workflow_step_id, sequence, step_code, step_name, assigned_role, assigned_hr_id,
    status, decision_by_hr_id, decision_at, decision_note, step_kind, decision_labels,
    terminal_status, allow_reject, is_cc, executed_at, allow_return
  )
  select v_request_id, t.workflow_step_id, t.sequence, t.step_code, t.step_name, t.assigned_role, v_admin_id,
         case when t.is_cc then 'skipped' else 'approved' end,
         v_admin_id, now(),
         case when t.is_cc then 'Copy-only rung; nothing to decide.'
              else 'Decided by the Administrator in the holder''s place; no cash moved, settled against a direct order.' end,
         t.step_kind, t.decision_labels, t.terminal_status, t.allow_reject, t.is_cc,
         case when t.step_code = 'finance_execution' and not t.is_cc then now() else null end,
         t.allow_return
    from public.marketing_request_approval_steps t
   where t.request_id = v_template_id
   order by t.sequence;
  get diagnostics v_rungs = row_count;

  insert into public.direct_order_marketing_offsets (direct_order_id, marketing_request_id, amount, note, created_by_hr_id)
  values (p_order_id, v_request_id, v_amount, nullif(btrim(coalesce(p_note, '')), ''), v_admin_id)
  returning id into v_offset_id;

  v_remaining := v_outstanding - v_amount;
  update public.direct_order_requests
     set remaining_amount = v_remaining,
         updated_at = now()
   where id = p_order_id;

  return jsonb_build_object(
    'offsetId',        v_offset_id,
    'requestId',       v_request_id,
    'requestCode',     v_request_code,
    'requestTypeName', v_type_name,
    'customerId',      v_customer_id,
    'rungs',           v_rungs,
    'amount',          v_amount,
    'remainingBefore', v_outstanding,
    'remainingAfter',  v_remaining
  );
end;
$$;

ALTER FUNCTION public.phx_admin_settle_service_fee(p_order_id uuid, p_requester_hr_id text, p_request_type_code text, p_beneficiary_name text, p_amount numeric, p_note text, p_admin_hr_id text) OWNER TO postgres;

--
-- Name: phx_analyze_tables_without_statistics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_analyze_tables_without_statistics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET lock_timeout TO '5s'
    AS $$
declare
  v_target record;
  v_analyzed integer := 0;
  v_described integer := 0;
  v_busy integer := 0;
begin
  for v_target in
    select c.oid, c.oid::regclass as ident
      from pg_catalog.pg_class c
      join pg_catalog.pg_namespace n on n.oid = c.relnamespace
      left join pg_catalog.pg_stat_all_tables s on s.relid = c.oid
     where n.nspname = 'public'
       and c.relkind = 'r'
       and c.relpersistence in ('p', 'u')
       and c.relpages > 0
       and (c.reltuples <> 0 or coalesce(s.n_mod_since_analyze, 0) > 0)
       and has_table_privilege(c.oid, 'MAINTAIN')
       and exists (
             select 1
               from pg_catalog.pg_attribute a
              where a.attrelid = c.oid
                and a.attnum > 0
                and not a.attisdropped
                and coalesce(a.attstattarget, -1) <> 0
           )
       and not exists (select 1 from pg_catalog.pg_statistic st where st.starelid = c.oid)
     order by c.relname
  loop
    begin
      execute format('analyze %s', v_target.ident);
    exception when lock_not_available then
      v_busy := v_busy + 1;
      continue;
    end;
    v_analyzed := v_analyzed + 1;
    if exists (select 1 from pg_catalog.pg_statistic st where st.starelid = v_target.oid) then
      v_described := v_described + 1;
    end if;
  end loop;

  return jsonb_build_object('analyzed', v_analyzed, 'described', v_described, 'busy', v_busy);
end
$$;

ALTER FUNCTION public.phx_analyze_tables_without_statistics() OWNER TO postgres;

--
-- Name: phx_analyze_tables_without_statistics_run(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_analyze_tables_without_statistics_run() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_out jsonb;
begin
  -- Uncaught on purpose: see the header. A raise here fails the run, and no success is recorded.
  v_out := public.phx_analyze_tables_without_statistics();

  perform public.phx_record_job_heartbeat(
    'phoenix-analyze-tables-without-statistics',
    'success',
    format(
      'analyzed %s table(s) that held data with no column statistics; %s of them now carry statistics; %s busy, tried again tomorrow',
      v_out ->> 'analyzed',
      v_out ->> 'described',
      v_out ->> 'busy'
    )
  );

  return v_out;
end
$$;

ALTER FUNCTION public.phx_analyze_tables_without_statistics_run() OWNER TO postgres;

--
-- Name: phx_apply_contract_renewal_workflow(uuid, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_apply_contract_renewal_workflow(p_request_id uuid, p_action text, p_actor text, p_note text DEFAULT NULL::text, p_decision_reason text DEFAULT NULL::text, p_new_contract_document_url text DEFAULT NULL::text, p_new_contract_document_name text DEFAULT NULL::text, p_signed_contract_url text DEFAULT NULL::text, p_signed_contract_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_request contract_renewal_requests%rowtype;
  v_employee record;
  v_updated contract_renewal_requests%rowtype;
  v_now timestamptz := now();
  v_start date;
  v_end date;
  v_completed_contract_id text := null;
begin
  if p_action not in ('manager_review', 'hr_review', 'renew', 'not_renew', 'upload_signed', 'cancel') then
    raise exception 'Unsupported contract renewal action.';
  end if;

  select *
  into v_request
  from public.contract_renewal_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'Contract renewal request not found.';
  end if;

  select hr_id, hire_date, employment_status
  into v_employee
  from public.employees
  where upper(hr_id) = upper(v_request.employee_hr_id)
  for update;

  if not found then
    raise exception 'Employee was not found in the directory.';
  end if;

  if lower(coalesce(v_employee.employment_status, 'active')) not in ('active', 'on_leave') then
    raise exception 'Contract renewals can only be updated for active employees.';
  end if;

  if p_action in ('renew', 'not_renew', 'cancel') and v_request.status in ('renewed', 'not_renewed', 'cancelled') then
    raise exception 'Finalized renewal requests cannot be decided again.';
  end if;

  if p_action = 'manager_review' then
    if v_request.status not in ('requested', 'manager_review') then
      raise exception 'Only requested renewals can be marked as manager reviewed.';
    end if;

    update public.contract_renewal_requests
    set status = 'manager_review',
        manager_reviewed_at = v_now,
        manager_reviewed_by = p_actor,
        updated_at = v_now,
        workflow_notes = public.phx_contract_note(workflow_notes, p_actor, p_action, p_note),
        new_contract_document_url = coalesce(nullif(trim(coalesce(p_new_contract_document_url, '')), ''), new_contract_document_url),
        new_contract_document_name = coalesce(nullif(trim(coalesce(p_new_contract_document_name, '')), ''), new_contract_document_name)
    where id = v_request.id
    returning * into v_updated;
  elsif p_action = 'hr_review' then
    if v_request.status not in ('requested', 'manager_review', 'hr_review') then
      raise exception 'Only active renewals can be marked as HR reviewed.';
    end if;

    update public.contract_renewal_requests
    set status = 'hr_review',
        hr_reviewed_at = v_now,
        hr_reviewed_by = p_actor,
        updated_at = v_now,
        workflow_notes = public.phx_contract_note(workflow_notes, p_actor, p_action, p_note),
        new_contract_document_url = coalesce(nullif(trim(coalesce(p_new_contract_document_url, '')), ''), new_contract_document_url),
        new_contract_document_name = coalesce(nullif(trim(coalesce(p_new_contract_document_name, '')), ''), new_contract_document_name)
    where id = v_request.id
    returning * into v_updated;
  elsif p_action = 'upload_signed' then
    if v_request.status not in ('hr_review', 'renewed') then
      raise exception 'Signed contracts can be uploaded after HR review or renewal.';
    end if;

    if nullif(trim(coalesce(p_signed_contract_url, '')), '') is null then
      raise exception 'Signed contract URL is required.';
    end if;

    update public.contract_renewal_requests
    set signed_contract_url = nullif(trim(coalesce(p_signed_contract_url, '')), ''),
        signed_contract_name = nullif(trim(coalesce(p_signed_contract_name, '')), ''),
        signed_at = v_now,
        updated_at = v_now,
        workflow_notes = public.phx_contract_note(workflow_notes, p_actor, p_action, p_note)
    where id = v_request.id
    returning * into v_updated;

    if v_updated.completed_contract_id is not null then
      update public.employee_contracts
      set signed_document_url = v_updated.signed_contract_url,
          signed_document_name = v_updated.signed_contract_name,
          updated_at = v_now
      where id::text = v_updated.completed_contract_id;
    end if;
  elsif p_action = 'renew' then
    if v_request.status not in ('requested', 'manager_review', 'hr_review') then
      raise exception 'Only active renewal requests can be renewed.';
    end if;

    if exists (
      select 1
      from public.contract_renewal_requests
      where upper(employee_hr_id) = upper(v_request.employee_hr_id)
        and id <> v_request.id
        and status in ('requested', 'manager_review', 'hr_review')
    ) then
      raise exception 'Another active renewal request exists for this employee.';
    end if;

    if exists (
      select 1
      from public.employee_contracts
      where upper(coalesce(employee_hr_id, hr_id)) = upper(v_request.employee_hr_id)
        and status = 'active'
        and (v_request.current_contract_id is null or id::text <> v_request.current_contract_id)
    ) then
      raise exception 'Another active contract exists for this employee.';
    end if;

    v_start := coalesce(v_request.proposed_start_date, v_request.requested_renewal_date);
    v_end := coalesce(v_request.proposed_end_date, (v_start + interval '1 year')::date);

    if v_employee.hire_date is not null and v_request.requested_renewal_date < v_employee.hire_date then
      raise exception 'Renewal date cannot be before the employee hire date.';
    end if;

    if v_request.current_renewal_date is not null and v_start < v_request.current_renewal_date then
      raise exception 'Proposed start date cannot be before the current renewal date.';
    end if;

    if v_end < v_start then
      raise exception 'Proposed end date cannot be before the proposed start date.';
    end if;

    if v_request.current_contract_id is not null then
      update public.employee_contracts
      set status = case when status = 'active' then 'expired' else status end,
          contract_end_date = coalesce(contract_end_date, v_start - 1),
          updated_at = v_now
      where id::text = v_request.current_contract_id;
    end if;

    insert into public.employee_contracts (
      employee_hr_id,
      hr_id,
      contract_type,
      contract_signed_date,
      contract_start_date,
      contract_end_date,
      contract_renewal_date,
      document_name,
      document_url,
      signed_document_name,
      signed_document_url,
      status,
      created_by,
      updated_at
    )
    values (
      v_request.employee_hr_id,
      v_request.employee_hr_id,
      'fixed-term',
      (now() at time zone 'Africa/Cairo')::date,
      v_start,
      v_end,
      v_end,
      v_request.new_contract_document_name,
      v_request.new_contract_document_url,
      v_request.signed_contract_name,
      v_request.signed_contract_url,
      'active',
      p_actor,
      v_now
    )
    returning id::text into v_completed_contract_id;

    update public.employees
    set contract_renewal_date = v_end,
        updated_at = v_now
    where upper(hr_id) = upper(v_request.employee_hr_id);

    update public.contract_renewal_requests
    set status = 'renewed',
        decision_at = v_now,
        decision_by = p_actor,
        decision_reason = nullif(trim(coalesce(p_decision_reason, '')), ''),
        completed_contract_id = v_completed_contract_id,
        updated_at = v_now,
        workflow_notes = public.phx_contract_note(workflow_notes, p_actor, p_action, p_note)
    where id = v_request.id
    returning * into v_updated;
  elsif p_action = 'not_renew' then
    if v_request.status not in ('requested', 'manager_review', 'hr_review') then
      raise exception 'Only active renewal requests can be marked not renewed.';
    end if;

    if v_request.current_contract_id is not null then
      update public.employee_contracts
      set status = 'not_renewed',
          updated_at = v_now
      where id::text = v_request.current_contract_id;
    end if;

    update public.contract_renewal_requests
    set status = 'not_renewed',
        decision_at = v_now,
        decision_by = p_actor,
        decision_reason = coalesce(nullif(trim(coalesce(p_decision_reason, '')), ''), 'No reason provided.'),
        updated_at = v_now,
        workflow_notes = public.phx_contract_note(workflow_notes, p_actor, p_action, p_note)
    where id = v_request.id
    returning * into v_updated;
  elsif p_action = 'cancel' then
    if v_request.status in ('renewed', 'not_renewed', 'cancelled') then
      raise exception 'Finalized renewal requests cannot be cancelled.';
    end if;

    update public.contract_renewal_requests
    set status = 'cancelled',
        decision_at = v_now,
        decision_by = p_actor,
        decision_reason = coalesce(nullif(trim(coalesce(p_decision_reason, '')), ''), 'Cancelled.'),
        updated_at = v_now,
        workflow_notes = public.phx_contract_note(workflow_notes, p_actor, p_action, p_note)
    where id = v_request.id
    returning * into v_updated;
  end if;

  insert into public.contract_renewal_history (
    action,
    actor,
    details,
    employee_hr_id,
    new_renewal_date,
    old_renewal_date,
    request_id
  )
  values (
    p_action,
    p_actor,
    jsonb_build_object('note', p_note, 'decisionReason', p_decision_reason),
    v_updated.employee_hr_id,
    case when p_action = 'renew' then v_end else v_updated.requested_renewal_date end,
    v_request.current_renewal_date,
    v_updated.id
  );

  return to_jsonb(v_updated);
end;
$$;

ALTER FUNCTION public.phx_apply_contract_renewal_workflow(p_request_id uuid, p_action text, p_actor text, p_note text, p_decision_reason text, p_new_contract_document_url text, p_new_contract_document_name text, p_signed_contract_url text, p_signed_contract_name text) OWNER TO postgres;

--
-- Name: direct_order_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.direct_order_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    requester_hr_id text NOT NULL,
    requester_role text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    line text NOT NULL,
    product_code text NOT NULL,
    product_name text NOT NULL,
    qty numeric(18,3) NOT NULL,
    bonus numeric(18,3) DEFAULT 0 NOT NULL,
    bonus_override_reason text,
    sales_value numeric(18,2) NOT NULL,
    pharmacy_id uuid NOT NULL,
    sales_month text,
    collection_date date,
    marketing_request_id uuid,
    payment_date date,
    paid_amount numeric(18,2),
    remaining_amount numeric(18,2),
    sos_batch_id uuid,
    reversal_of_request_id uuid,
    reversed_by_request_id uuid,
    submitted_at timestamp with time zone,
    decided_at timestamp with time zone,
    created_by_login_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deal_type text DEFAULT 'bonus'::text NOT NULL,
    discount_pct numeric(6,3),
    public_price_snapshot numeric(18,6),
    pharmacy_price_snapshot numeric(18,6),
    held_at timestamp with time zone,
    duplicate_of_request_id uuid,
    family_code text,
    invoice_storage_path text,
    invoice_content_type text,
    invoice_uploaded_at timestamp with time zone,
    CONSTRAINT direct_order_requests_bonus_check CHECK ((bonus >= (0)::numeric)),
    CONSTRAINT direct_order_requests_deal_type_check CHECK ((deal_type = ANY (ARRAY['bonus'::text, 'discount'::text]))),
    CONSTRAINT direct_order_requests_discount_pct_check CHECK (((discount_pct IS NULL) OR ((discount_pct >= (0)::numeric) AND (discount_pct <= (100)::numeric)))),
    CONSTRAINT direct_order_requests_duplicate_not_self_check CHECK (((duplicate_of_request_id IS NULL) OR (duplicate_of_request_id <> id))),
    CONSTRAINT direct_order_requests_invoice_content_type_check CHECK (((invoice_content_type IS NULL) OR (invoice_content_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'application/pdf'::text])))),
    CONSTRAINT direct_order_requests_invoice_pair_check CHECK (((invoice_storage_path IS NULL) = (invoice_content_type IS NULL))),
    CONSTRAINT direct_order_requests_pharmacy_price_snapshot_check CHECK (((pharmacy_price_snapshot IS NULL) OR (pharmacy_price_snapshot >= (0)::numeric))),
    CONSTRAINT direct_order_requests_qty_check CHECK ((qty > (0)::numeric)),
    CONSTRAINT direct_order_requests_sales_month_check CHECK ((sales_month ~ '^[0-9]{4}-[0-9]{2}$'::text)),
    CONSTRAINT direct_order_requests_sales_value_check CHECK ((sales_value >= (0)::numeric)),
    CONSTRAINT direct_order_requests_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'approved'::text, 'rejected'::text, 'returned'::text, 'reversed'::text, 'held'::text, 'expired'::text, 'cancelled'::text])))
);

ALTER TABLE public.direct_order_requests OWNER TO postgres;

--
-- Name: COLUMN direct_order_requests.product_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_requests.product_code IS 'Line 1''s product. For a multi-item basket, read direct_order_request_items for the full set.';

--
-- Name: COLUMN direct_order_requests.sales_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_requests.sales_value IS 'Basket TOTAL: the sum of direct_order_request_items.sales_value. Equal to line 1 for a one-item request.';

--
-- Name: COLUMN direct_order_requests.duplicate_of_request_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_requests.duplicate_of_request_id IS 'The surviving request this one duplicates. Set only when a request is cancelled as a duplicate, and it points at the copy that was KEPT — so the pair stays navigable and no order is ever silently lost.';

--
-- Name: COLUMN direct_order_requests.family_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_requests.family_code IS 'The one family every line of this request belongs to. Enforced by phx_direct_order_item_family_guard.';

--
-- Name: COLUMN direct_order_requests.invoice_storage_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_requests.invoice_storage_path IS 'The distributor invoice the requester used for this order, in the private direct-order-invoices bucket.';

--
-- Name: COLUMN direct_order_requests.invoice_content_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_requests.invoice_content_type IS 'image/jpeg, image/png or application/pdf — what the approver''s browser is asked to open.';

--
-- Name: phx_apply_direct_order_decision(uuid, integer, text, text, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_apply_direct_order_decision(p_request_id uuid, p_step_order integer, p_expected_status text, p_next_status text, p_step_next_status text, p_decided_by_hr_id text, p_decision_comment text, p_now timestamp with time zone, p_sales_month text) RETURNS public.direct_order_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.direct_order_requests;
  v_is_final boolean;
  v_original_month text;
begin
  select * into v_row from public.direct_order_requests where id = p_request_id for update;
  if not found then raise exception 'Direct order request was not found.' using errcode = 'P0002'; end if;
  if v_row.status is distinct from p_expected_status then
    raise exception 'Direct order request was updated by another user. Refresh and try again.' using errcode = '40001';
  end if;

  if p_step_next_status in ('approved', 'rejected') then
    update public.direct_order_approval_steps
       set status = p_step_next_status, decided_by_hr_id = p_decided_by_hr_id,
           decision_comment = p_decision_comment, decided_at = p_now, updated_at = p_now
     where request_id = p_request_id and step_order = p_step_order;
    if not found then raise exception 'Approval step % was not found for this request.', p_step_order using errcode = 'P0002'; end if;
  end if;

  v_is_final := p_next_status in ('approved', 'rejected');

  update public.direct_order_requests
     set status = p_next_status,
         decided_at = case when v_is_final then p_now else decided_at end,
         sales_month = case when p_next_status = 'approved' then coalesce(p_sales_month, sales_month) else sales_month end,
         updated_at = p_now
   where id = p_request_id
   returning * into v_row;

  if p_next_status = 'approved' then
    if v_row.reversal_of_request_id is not null then
      update public.direct_order_requests set status = 'reversed', updated_at = p_now
       where id = v_row.reversal_of_request_id returning sales_month into v_original_month;
      if v_original_month is not null then
        perform public.phx_rebuild_direct_order_sos_batch(v_original_month, p_decided_by_hr_id);
      end if;
    elsif v_row.sales_month is not null then
      perform public.phx_rebuild_direct_order_sos_batch(v_row.sales_month, p_decided_by_hr_id);
    end if;
  end if;

  return v_row;
end;
$$;

ALTER FUNCTION public.phx_apply_direct_order_decision(p_request_id uuid, p_step_order integer, p_expected_status text, p_next_status text, p_step_next_status text, p_decided_by_hr_id text, p_decision_comment text, p_now timestamp with time zone, p_sales_month text) OWNER TO postgres;

--
-- Name: v2_vacation_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.v2_vacation_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_hr_id text NOT NULL,
    employee_name text NOT NULL,
    employee_work_email text,
    employee_hire_date date,
    department_name text,
    line_name text,
    manager_hr_id text,
    manager_name text,
    manager_of_manager_hr_id text,
    manager_of_manager_name text,
    vacation_type text NOT NULL,
    day_part text NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    duration_days numeric(8,2) NOT NULL,
    payment_status text NOT NULL,
    unpaid_reason text,
    entitlement_days numeric(8,2) DEFAULT 0 NOT NULL,
    used_paid_days numeric(8,2) DEFAULT 0 NOT NULL,
    balance_before_days numeric(8,2) DEFAULT 0 NOT NULL,
    balance_after_days numeric(8,2) DEFAULT 0 NOT NULL,
    period_start date,
    period_end date,
    status text DEFAULT 'pending_manager'::text NOT NULL,
    submitted_by_hr_id text,
    submitted_by_login_id text,
    manager_decision text,
    manager_decision_by_hr_id text,
    manager_decision_at timestamp with time zone,
    manager_decision_comment text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    working_days numeric DEFAULT 1 NOT NULL,
    calendar_days numeric DEFAULT 1 NOT NULL,
    notes text,
    sick_attachment_bucket text,
    sick_attachment_object_path text,
    sick_attachment_original_name text,
    sick_attachment_content_type text,
    sick_attachment_size_bytes bigint,
    sick_attachment_uploaded_at timestamp with time zone,
    hr_decision text,
    hr_decision_by_hr_id text,
    hr_decision_at timestamp with time zone,
    hr_decision_comment text,
    compensatory_event_name text,
    compensatory_event_date date,
    compensatory_event_location text,
    compensatory_manager_1 text,
    compensatory_manager_2 text,
    compensatory_attachment_bucket text,
    compensatory_attachment_object_path text,
    compensatory_attachment_original_name text,
    compensatory_attachment_content_type text,
    compensatory_attachment_size_bytes bigint,
    compensatory_attachment_uploaded_at timestamp with time zone,
    paid_duration_days numeric(8,2) DEFAULT 0 NOT NULL,
    unpaid_duration_days numeric(8,2) DEFAULT 0 NOT NULL,
    weekly_off_policy_snapshot jsonb,
    employee_note text,
    request_code text NOT NULL,
    evidence_waiver_note text,
    CONSTRAINT v2_vacation_requests_compensatory_required_check CHECK (((vacation_type <> 'compensatory'::text) OR ((btrim(COALESCE(compensatory_event_name, ''::text)) <> ''::text) AND (compensatory_event_date IS NOT NULL) AND (btrim(COALESCE(compensatory_event_location, ''::text)) <> ''::text) AND (btrim(COALESCE(compensatory_manager_1, ''::text)) <> ''::text) AND ((compensatory_attachment_object_path IS NOT NULL) OR (btrim(COALESCE(evidence_waiver_note, ''::text)) <> ''::text))))),
    CONSTRAINT v2_vacation_requests_date_order CHECK ((end_date >= start_date)),
    CONSTRAINT v2_vacation_requests_day_part_check CHECK ((day_part = ANY (ARRAY['full_day'::text, 'am_only'::text, 'pm_only'::text]))),
    CONSTRAINT v2_vacation_requests_duration_days_check CHECK ((duration_days > (0)::numeric)),
    CONSTRAINT v2_vacation_requests_hr_decision_check CHECK (((hr_decision IS NULL) OR (hr_decision = ANY (ARRAY['approved'::text, 'rejected'::text])))),
    CONSTRAINT v2_vacation_requests_manager_decision_check CHECK (((manager_decision IS NULL) OR (manager_decision = ANY (ARRAY['approved'::text, 'rejected'::text])))),
    CONSTRAINT v2_vacation_requests_paid_unpaid_duration_check CHECK (((paid_duration_days >= (0)::numeric) AND (unpaid_duration_days >= (0)::numeric) AND (round((paid_duration_days + unpaid_duration_days), 2) = round((duration_days)::numeric, 2)))),
    CONSTRAINT v2_vacation_requests_payment_status_check CHECK ((payment_status = ANY (ARRAY['paid'::text, 'partial'::text, 'unpaid'::text]))),
    CONSTRAINT v2_vacation_requests_status_check CHECK ((status = ANY (ARRAY['needs_assignment'::text, 'pending_manager'::text, 'pending_hr'::text, 'approved'::text, 'rejected'::text, 'returned'::text, 'cancelled'::text]))),
    CONSTRAINT v2_vacation_requests_unpaid_reason_check CHECK (((unpaid_reason IS NULL) OR (unpaid_reason = ANY (ARRAY['first_six_months'::text, 'insufficient_balance'::text, 'missing_hire_date'::text])))),
    CONSTRAINT v2_vacation_requests_vacation_type_check CHECK ((vacation_type = ANY (ARRAY['annual'::text, 'emergency'::text, 'sick'::text, 'other'::text, 'compensatory'::text])))
);

ALTER TABLE public.v2_vacation_requests OWNER TO postgres;

--
-- Name: COLUMN v2_vacation_requests.evidence_waiver_note; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.v2_vacation_requests.evidence_waiver_note IS 'Owner-granted exception to the evidence requirement (who, when, why). When set, a compensatory day is complete without an attachment. Never write a placeholder attachment path instead.';

--
-- Name: phx_apply_vacation_paid_approval(uuid, text, text, text, text, text, timestamp with time zone, numeric, date, date, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_apply_vacation_paid_approval(p_request_id uuid, p_expected_status text, p_next_status text, p_step text, p_decision_by_hr_id text, p_decision_comment text, p_now timestamp with time zone, p_entitlement_days numeric, p_period_start date, p_period_end date, p_duration_days numeric, p_vacation_type text) RETURNS public.v2_vacation_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_hr_id text;
  v_used numeric;
  v_balance_before numeric;
  v_paid numeric;
  v_unpaid numeric;
  v_balance_after numeric;
  v_payment_status text;
  v_unpaid_reason text;
  v_row public.v2_vacation_requests;
begin
  -- Lock the target request row and enforce the status compare-and-swap. Different
  -- requests never contend on this row lock; it only guards this request's transition.
  select * into v_row from public.v2_vacation_requests where id = p_request_id for update;
  if not found then
    raise exception 'Vacation request was not found.' using errcode = 'P0002';
  end if;
  if v_row.status is distinct from p_expected_status then
    raise exception 'Vacation request was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;
  v_employee_hr_id := v_row.employee_hr_id;

  -- Serialize ALL paid-balance decisions for this employee for the rest of the
  -- transaction, so two concurrent approvals in the same period cannot both consume
  -- the same remaining entitlement. Released automatically at commit/rollback.
  perform pg_advisory_xact_lock(hashtext(lower(v_employee_hr_id)));

  -- Authoritative used-paid-days in the balance period. Mirrors approvedPaidDaysInPeriod:
  -- annual and emergency share one period bucket; other types match exactly. paid_duration_days
  -- is NOT NULL, so summing it is equivalent to the JS branch.
  select coalesce(sum(paid_duration_days), 0) into v_used
  from public.v2_vacation_requests
  where lower(employee_hr_id) = lower(v_employee_hr_id)
    and status = 'approved'
    and id <> p_request_id
    and start_date >= p_period_start
    and start_date <  p_period_end
    and (
      (p_vacation_type in ('annual', 'emergency') and vacation_type in ('annual', 'emergency'))
      or (p_vacation_type not in ('annual', 'emergency') and vacation_type = p_vacation_type)
    );

  -- ADDED 2026-09-15: annual leave already spent on attendance deductions. Same pool as annual
  -- and emergency requests, same lock (phx_attendance_settle_digest_line takes it too).
  if p_vacation_type in ('annual', 'emergency') then
    v_used := v_used + coalesce((
      select sum(days)
      from public.attendance_annual_balance_charges
      where lower(employee_hr_id) = lower(v_employee_hr_id)
        and work_date >= p_period_start
        and work_date <  p_period_end
    ), 0);
  end if;

  -- Paid/unpaid split (mirrors splitVacationPayment; roundDays = round to 2 decimals).
  v_used := round(v_used, 2);
  v_balance_before := round(greatest(0, p_entitlement_days - v_used), 2);
  v_paid := round(least(p_duration_days, greatest(0, v_balance_before)), 2);
  v_unpaid := round(greatest(0, p_duration_days - v_paid), 2);
  v_balance_after := round(greatest(0, v_balance_before - v_paid), 2);
  if v_unpaid > 0 and v_paid > 0 then
    v_payment_status := 'partial';
  elsif v_unpaid > 0 then
    v_payment_status := 'unpaid';
  else
    v_payment_status := 'paid';
  end if;
  v_unpaid_reason := case when v_unpaid > 0 then 'insufficient_balance' else null end;

  update public.v2_vacation_requests set
    status = p_next_status,
    updated_at = p_now,
    payment_status = v_payment_status,
    paid_duration_days = v_paid,
    unpaid_duration_days = v_unpaid,
    unpaid_reason = v_unpaid_reason,
    entitlement_days = round(p_entitlement_days, 2),
    used_paid_days = v_used,
    balance_before_days = v_balance_before,
    balance_after_days = v_balance_after,
    period_start = p_period_start,
    period_end = p_period_end,
    hr_decision = case when p_step = 'hr' then 'approved' else hr_decision end,
    hr_decision_by_hr_id = case when p_step = 'hr' then p_decision_by_hr_id else hr_decision_by_hr_id end,
    hr_decision_at = case when p_step = 'hr' then p_now else hr_decision_at end,
    hr_decision_comment = case when p_step = 'hr' then p_decision_comment else hr_decision_comment end,
    manager_decision = case when p_step <> 'hr' then 'approved' else manager_decision end,
    manager_decision_by_hr_id = case when p_step <> 'hr' then p_decision_by_hr_id else manager_decision_by_hr_id end,
    manager_decision_at = case when p_step <> 'hr' then p_now else manager_decision_at end,
    manager_decision_comment = case when p_step <> 'hr' then p_decision_comment else manager_decision_comment end
  where id = p_request_id
  returning * into v_row;

  return v_row;
end;
$$;

ALTER FUNCTION public.phx_apply_vacation_paid_approval(p_request_id uuid, p_expected_status text, p_next_status text, p_step text, p_decision_by_hr_id text, p_decision_comment text, p_now timestamp with time zone, p_entitlement_days numeric, p_period_start date, p_period_end date, p_duration_days numeric, p_vacation_type text) OWNER TO postgres;

--
-- Name: phx_apply_vacation_paid_approval_with_step(uuid, text, uuid, text, text, text, text, text, timestamp with time zone, numeric, date, date, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_apply_vacation_paid_approval_with_step(p_request_id uuid, p_expected_status text, p_step_id uuid, p_overridden_by_hr_id text, p_next_status text, p_step text, p_decision_by_hr_id text, p_decision_comment text, p_now timestamp with time zone, p_entitlement_days numeric, p_period_start date, p_period_end date, p_duration_days numeric, p_vacation_type text) RETURNS public.v2_vacation_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.v2_vacation_requests;
begin
  perform public.phx_apply_vacation_step_decision(
    p_request_id,
    p_expected_status,
    p_step_id,
    'approved',
    p_decision_comment,
    p_overridden_by_hr_id,
    p_decision_by_hr_id,
    p_now,
    null
  );

  select * into v_row
  from public.phx_apply_vacation_paid_approval(
    p_request_id,
    p_expected_status,
    p_next_status,
    p_step,
    p_decision_by_hr_id,
    p_decision_comment,
    p_now,
    p_entitlement_days,
    p_period_start,
    p_period_end,
    p_duration_days,
    p_vacation_type
  );
  if v_row.id is null then
    raise exception 'Vacation request was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;

  return v_row;
end;
$$;

ALTER FUNCTION public.phx_apply_vacation_paid_approval_with_step(p_request_id uuid, p_expected_status text, p_step_id uuid, p_overridden_by_hr_id text, p_next_status text, p_step text, p_decision_by_hr_id text, p_decision_comment text, p_now timestamp with time zone, p_entitlement_days numeric, p_period_start date, p_period_end date, p_duration_days numeric, p_vacation_type text) OWNER TO postgres;

--
-- Name: phx_apply_vacation_step_decision(uuid, text, uuid, text, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_apply_vacation_step_decision(p_request_id uuid, p_expected_status text, p_step_id uuid, p_step_status text, p_decision_comment text, p_overridden_by_hr_id text, p_actor_hr_id text, p_now timestamp with time zone, p_request_patch jsonb) RETURNS public.v2_vacation_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  -- The columns a decision writes on the request - applyVacationDecisionSequential and Sick leave's
  -- applyVacationDecisionLegacy build the same twenty - and nothing else.
  v_allowed constant text[] := array[
    'status',
    'updated_at',
    'hr_decision',
    'hr_decision_at',
    'hr_decision_by_hr_id',
    'hr_decision_comment',
    'manager_decision',
    'manager_decision_at',
    'manager_decision_by_hr_id',
    'manager_decision_comment',
    'balance_after_days',
    'balance_before_days',
    'entitlement_days',
    'payment_status',
    'paid_duration_days',
    'period_end',
    'period_start',
    'unpaid_reason',
    'unpaid_duration_days',
    'used_paid_days'
  ];
  v_unknown text;
  v_overridden_by text := nullif(p_overridden_by_hr_id, '');
  v_row public.v2_vacation_requests;
  v_new public.v2_vacation_requests;
  v_step_key text;
begin
  if p_step_status is null or p_step_status not in ('approved', 'rejected') then
    raise exception 'A vacation step decision is approved or rejected, not "%".', p_step_status
      using errcode = '22023';
  end if;
  if p_now is null then
    raise exception 'A vacation step decision needs its decision time.' using errcode = '22023';
  end if;
  if p_request_patch is not null then
    if jsonb_typeof(p_request_patch) <> 'object' then
      raise exception 'A vacation request patch must be an object.' using errcode = '22023';
    end if;
    select key into v_unknown
    from jsonb_object_keys(p_request_patch) as key
    where key <> all (v_allowed)
    limit 1;
    if v_unknown is not null then
      raise exception 'A vacation decision cannot change "%".', v_unknown using errcode = '22023';
    end if;
  end if;

  -- Request first, then steps: the same order the paid wrapper below takes, so two decisions on
  -- one request queue on this row lock instead of deadlocking.
  select * into v_row from public.v2_vacation_requests where id = p_request_id for update;
  if not found then
    raise exception 'Vacation request was not found.' using errcode = 'P0002';
  end if;
  if v_row.status is distinct from p_expected_status then
    raise exception 'Vacation request was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;

  -- recordVacationApprovalStepDecision: compare-and-set on status = 'pending'.
  update public.v2_vacation_approval_steps set
    decided_at = p_now,
    decision_comment = p_decision_comment,
    overridden_at = case when v_overridden_by is not null then p_now else null end,
    overridden_by_hr_id = v_overridden_by,
    status = p_step_status,
    updated_at = p_now
  where id = p_step_id
    and request_id = p_request_id
    and status = 'pending'
  returning step_key into v_step_key;
  if not found then
    if exists (
      select 1 from public.v2_vacation_approval_steps where id = p_step_id and request_id = p_request_id
    ) then
      raise exception 'This vacation approval step was already decided.' using errcode = '55000';
    end if;
    raise exception 'This vacation approval step does not belong to this request.' using errcode = '22023';
  end if;

  -- closeSiblingPendingHrApprovalSteps: HR is one authority - the first Super Admin to decide
  -- closes the HR step for every other account on this request.
  if v_step_key = 'hr' then
    update public.v2_vacation_approval_steps set
      decided_at = p_now,
      decision_comment = 'Auto-completed: HR step already decided by '
        || coalesce(p_actor_hr_id, 'another HR/Super Admin account') || '.',
      status = p_step_status,
      updated_at = p_now
    where request_id = p_request_id
      and step_key = 'hr'
      and status = 'pending'
      and id <> p_step_id;
  end if;

  if p_request_patch is null then
    return v_row;
  end if;

  -- Values not in the patch keep the row's own value (jsonb_populate_record with a non-null base).
  v_new := jsonb_populate_record(v_row, p_request_patch);

  update public.v2_vacation_requests set
    status = case when p_request_patch ? 'status' then v_new.status else status end,
    updated_at = case when p_request_patch ? 'updated_at' then v_new.updated_at else updated_at end,
    hr_decision = case when p_request_patch ? 'hr_decision' then v_new.hr_decision else hr_decision end,
    hr_decision_at = case when p_request_patch ? 'hr_decision_at' then v_new.hr_decision_at else hr_decision_at end,
    hr_decision_by_hr_id = case when p_request_patch ? 'hr_decision_by_hr_id' then v_new.hr_decision_by_hr_id else hr_decision_by_hr_id end,
    hr_decision_comment = case when p_request_patch ? 'hr_decision_comment' then v_new.hr_decision_comment else hr_decision_comment end,
    manager_decision = case when p_request_patch ? 'manager_decision' then v_new.manager_decision else manager_decision end,
    manager_decision_at = case when p_request_patch ? 'manager_decision_at' then v_new.manager_decision_at else manager_decision_at end,
    manager_decision_by_hr_id = case when p_request_patch ? 'manager_decision_by_hr_id' then v_new.manager_decision_by_hr_id else manager_decision_by_hr_id end,
    manager_decision_comment = case when p_request_patch ? 'manager_decision_comment' then v_new.manager_decision_comment else manager_decision_comment end,
    balance_after_days = case when p_request_patch ? 'balance_after_days' then v_new.balance_after_days else balance_after_days end,
    balance_before_days = case when p_request_patch ? 'balance_before_days' then v_new.balance_before_days else balance_before_days end,
    entitlement_days = case when p_request_patch ? 'entitlement_days' then v_new.entitlement_days else entitlement_days end,
    payment_status = case when p_request_patch ? 'payment_status' then v_new.payment_status else payment_status end,
    paid_duration_days = case when p_request_patch ? 'paid_duration_days' then v_new.paid_duration_days else paid_duration_days end,
    period_end = case when p_request_patch ? 'period_end' then v_new.period_end else period_end end,
    period_start = case when p_request_patch ? 'period_start' then v_new.period_start else period_start end,
    unpaid_reason = case when p_request_patch ? 'unpaid_reason' then v_new.unpaid_reason else unpaid_reason end,
    unpaid_duration_days = case when p_request_patch ? 'unpaid_duration_days' then v_new.unpaid_duration_days else unpaid_duration_days end,
    used_paid_days = case when p_request_patch ? 'used_paid_days' then v_new.used_paid_days else used_paid_days end
  where id = p_request_id
  returning * into v_row;

  return v_row;
end;
$$;

ALTER FUNCTION public.phx_apply_vacation_step_decision(p_request_id uuid, p_expected_status text, p_step_id uuid, p_step_status text, p_decision_comment text, p_overridden_by_hr_id text, p_actor_hr_id text, p_now timestamp with time zone, p_request_patch jsonb) OWNER TO postgres;

