--
-- Name: phx_ats_mr_hiring_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_ats_mr_hiring_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if pg_trigger_depth() > 1 then
    if tg_op = 'DELETE' then
      return old;
    end if;
    if tg_op = 'UPDATE'
       and old.booking_id is not null
       and new.booking_id is null
       and (to_jsonb(new) - 'booking_id') = (to_jsonb(old) - 'booking_id') then
      return new;
    end if;
  end if;
  raise exception '% is append-only; % is not permitted', tg_table_name, tg_op
    using errcode = 'restrict_violation';
end;
$$;

ALTER FUNCTION public.phx_ats_mr_hiring_append_only() OWNER TO postgres;

