--
-- Name: phx_attendance_balance_inputs(text, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_balance_inputs(p_employee_hr_id text, p_period_start date, p_period_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'requestDays', (
      select coalesce(sum(paid_duration_days), 0)
      from public.v2_vacation_requests
      where lower(employee_hr_id) = lower(p_employee_hr_id)
        and status = 'approved'
        and vacation_type in ('annual', 'emergency')
        and start_date >= p_period_start
        and start_date <  p_period_end
    ),
    'chargeDays', (
      select coalesce(sum(days), 0)
      from public.attendance_annual_balance_charges
      where lower(employee_hr_id) = lower(p_employee_hr_id)
        and work_date >= p_period_start
        and work_date <  p_period_end
    ),
    'copilotDays', (
      select coalesce(sum(balance_days_consumed), 0)
      from public.payroll_copilot_vacation_settlements
      where employee_hr_id_compact = regexp_replace(lower(p_employee_hr_id), '[^a-z0-9]+', '', 'g')
        and settlement_method in ('balance', 'partial_balance', 'defer_to_balance')
        and superseded_at is null
        and start_date >= p_period_start
        and start_date <  p_period_end
    )
  );
$$;

ALTER FUNCTION public.phx_attendance_balance_inputs(p_employee_hr_id text, p_period_start date, p_period_end date) OWNER TO postgres;

--
-- Name: phx_attendance_balance_reversal_shape(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_balance_reversal_shape() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_charge public.attendance_annual_balance_charges;
begin
  if new.reverses_charge_id is null then
    return new;
  end if;
  select * into v_charge from public.attendance_annual_balance_charges where id = new.reverses_charge_id;
  if not found or v_charge.days <= 0 then
    raise exception 'A reversal must reverse a charge.' using errcode = '23514';
  end if;
  if new.days <> -v_charge.days
     or new.digest_line_id is distinct from v_charge.digest_line_id
     or new.deduction_candidate_id is distinct from v_charge.deduction_candidate_id
     or new.source is distinct from v_charge.source
     or lower(new.employee_hr_id) <> lower(v_charge.employee_hr_id)
     or new.work_date <> v_charge.work_date
     or new.period_start <> v_charge.period_start
     or new.period_end <> v_charge.period_end then
    raise exception 'A reversal must mirror the charge it reverses exactly.' using errcode = '23514';
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.phx_attendance_balance_reversal_shape() OWNER TO postgres;

--
-- Name: phx_attendance_mark_digest_line(bigint, boolean, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_mark_digest_line(p_line_id bigint, p_deduct boolean, p_days numeric, p_actor_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_line public.attendance_digest_lines;
  v_digest public.attendance_weekly_digests;
  v_detected_days numeric;
  v_detected_value numeric;
  v_days numeric;
  v_value numeric;
  v_adjusted boolean;
  v_total_days numeric;
  v_total_value numeric;
  v_unpriced boolean;
begin
  if p_deduct is null then
    raise exception 'Say whether this day is deducted.' using errcode = '22023';
  end if;
  if coalesce(btrim(p_actor_hr_id), '') = '' then
    raise exception 'The person making this change is not known.' using errcode = '22023';
  end if;

  -- Lock the WEEK first, then the day — the order release takes them in. The other order deadlocks
  -- a tick against a release of the same employee's week.
  select * into v_digest from public.attendance_weekly_digests
  where id = (select digest_id from public.attendance_digest_lines where id = p_line_id)
  for update;
  if not found then
    raise exception 'That day was not found.' using errcode = 'P0002';
  end if;
  select * into v_line from public.attendance_digest_lines where id = p_line_id and digest_id = v_digest.id for update;
  if not found then
    raise exception 'That day was not found.' using errcode = 'P0002';
  end if;
  if v_digest.dry_run is distinct from false then
    raise exception 'This week was built as a trial run and cannot be changed.' using errcode = '40001';
  end if;
  if v_digest.status <> 'awaiting_release' then
    raise exception 'This week has already been released, so its days can no longer be changed.' using errcode = '40001';
  end if;
  if v_line.action <> 'pending' then
    raise exception 'That day has already been answered — reload and look again.' using errcode = '40001';
  end if;

  v_detected_days := coalesce(v_line.detected_days, v_line.deduction_days);
  v_detected_value := case when v_line.detected_days is null then v_line.deduction_value else v_line.detected_value end;
  v_days := coalesce(round(p_days, 3), v_line.deduction_days);
  -- More than zero (untick instead), at most 3: a typo guard, since he may raise the figure.
  if v_days <= 0 or v_days > 3 then
    raise exception 'One day can deduct more than 0 and at most 3 days.' using errcode = '22023';
  end if;
  v_adjusted := v_days <> v_detected_days;
  -- The estimate follows the days. An unpriced day stays unpriced — NULL is "not yet calculated",
  -- never "free".
  v_value := case
    when not v_adjusted then v_detected_value
    when v_detected_value is null or v_detected_days <= 0 then null
    else round(v_detected_value * v_days / v_detected_days, 2)
  end;

  update public.attendance_digest_lines set
    deduct = p_deduct,
    deduction_days = v_days,
    deduction_value = v_value,
    detected_days = v_detected_days,
    detected_value = v_detected_value,
    adjusted_by_hr_id = case when v_adjusted then p_actor_hr_id else null end,
    adjusted_at = case when v_adjusted then now() else null end,
    updated_at = now()
  where id = v_line.id;

  -- The week's total is what will be asked about: ticked days, plus any day already answered.
  select
    coalesce(sum(deduction_days), 0),
    coalesce(sum(deduction_value), 0),
    coalesce(bool_or(deduction_value is null), false)
  into v_total_days, v_total_value, v_unpriced
  from public.attendance_digest_lines
  where digest_id = v_digest.id
    and action <> 'removed'
    and (deduct or action <> 'pending');

  update public.attendance_weekly_digests set
    total_deduction_days = round(v_total_days, 3),
    total_deduction_value = case when v_unpriced then null else round(v_total_value, 2) end,
    has_unpriced_day = v_unpriced,
    updated_at = now()
  where id = v_digest.id;

  return jsonb_build_object(
    'lineId', v_line.id,
    'digestId', v_digest.id,
    'workDate', v_line.work_date,
    'deduct', p_deduct,
    'deductionDays', v_days,
    'deductionValue', v_value,
    'detectedDays', v_detected_days,
    'adjusted', v_adjusted,
    'totalDeductionDays', round(v_total_days, 3),
    'totalDeductionValue', case when v_unpriced then null else round(v_total_value, 2) end,
    'hasUnpricedDay', v_unpriced
  );
end;
$$;

ALTER FUNCTION public.phx_attendance_mark_digest_line(p_line_id bigint, p_deduct boolean, p_days numeric, p_actor_hr_id text) OWNER TO postgres;

--
-- Name: phx_attendance_release_digest(bigint, text, date, bigint[], numeric[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_release_digest(p_digest_id bigint, p_actor_hr_id text, p_answer_due_on date, p_seen_line_ids bigint[], p_seen_days numeric[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_digest public.attendance_weekly_digests;
  v_line public.attendance_digest_lines;
  v_reason constant text := 'Not ticked for deduction when the week was released.';
  v_cleared integer := 0;
  v_pending integer;
  v_disputed integer;
  v_kept integer;
  v_total_days numeric;
  v_total_value numeric;
  v_unpriced boolean;
  v_status text;
begin
  if p_answer_due_on is null or coalesce(btrim(p_actor_hr_id), '') = '' then
    raise exception 'A release needs who released it and the answer deadline.' using errcode = '22023';
  end if;
  if p_seen_line_ids is null or p_seen_days is null
     or coalesce(array_length(p_seen_line_ids, 1), 0) <> coalesce(array_length(p_seen_days, 1), 0) then
    raise exception 'The release did not say which days were on the page.' using errcode = '22023';
  end if;

  select * into v_digest from public.attendance_weekly_digests where id = p_digest_id for update;
  if not found then
    raise exception 'That week was not found.' using errcode = 'P0002';
  end if;
  -- Already released by another click, or a trial run: nothing to do, and nothing is cleared.
  if v_digest.status <> 'awaiting_release' or v_digest.dry_run is distinct from false then
    return jsonb_build_object('released', false, 'status', v_digest.status, 'pendingDays', 0, 'clearedDays', 0);
  end if;

  -- The days waiting now must be the days the page showed, at the figures it showed. The daily job adds
  -- days to a waiting week; one that arrived after the page loaded would be cleared below, unticked,
  -- without the Super Admin ever seeing it — so the whole release is refused and the page reloads.
  if exists (
    select 1
    from public.attendance_digest_lines l
    where l.digest_id = v_digest.id
      and l.action = 'pending'
      and not exists (
        select 1
        from unnest(p_seen_line_ids, p_seen_days) as seen(line_id, days)
        where seen.line_id = l.id
          and round(seen.days, 3) = round(l.deduction_days, 3)
      )
  ) then
    raise exception 'New or changed days arrived in this week after the page was loaded. Reload the page, check the days, then release again.' using errcode = '40001';
  end if;

  -- Every unticked day is cleared. The 'removed' settlement is the record payroll acts on: the bridge
  -- turns it into Do Not Take Action, and recordDecision refuses to approve the day.
  for v_line in
    select * from public.attendance_digest_lines
    where digest_id = v_digest.id and action = 'pending' and deduct = false
    order by work_date
    for update
  loop
    insert into public.attendance_settlements (
      digest_line_id, employee_hr_id, work_date, action, method,
      deduction_days, deduction_value, actor_hr_id, actor_role, reviewer_hr_id, reason
    ) values (
      v_line.id, v_digest.employee_hr_id, v_line.work_date, 'removed', null,
      0, 0, p_actor_hr_id, 'reviewer', p_actor_hr_id, v_reason
    );

    update public.attendance_digest_lines set
      action = 'removed',
      removed_at = now(),
      removed_by_hr_id = p_actor_hr_id,
      remove_reason = v_reason,
      updated_at = now()
    where id = v_line.id;

    v_cleared := v_cleared + 1;
  end loop;

  select
    count(*) filter (where action = 'pending'),
    count(*) filter (where action = 'disputed'),
    count(*) filter (where action <> 'removed'),
    coalesce(sum(deduction_days) filter (where action <> 'removed'), 0),
    coalesce(sum(deduction_value) filter (where action <> 'removed'), 0),
    coalesce(bool_or(deduction_value is null) filter (where action <> 'removed'), false)
  into v_pending, v_disputed, v_kept, v_total_days, v_total_value, v_unpriced
  from public.attendance_digest_lines
  where digest_id = v_digest.id;

  -- Nothing left: void, and nobody is told. Only days answered before the release step existed:
  -- settled. Otherwise open, with the deadline running.
  v_status := case
    when v_kept = 0 then 'void'
    when v_pending = 0 and v_disputed = 0 then 'settled'
    else 'open'
  end;

  update public.attendance_weekly_digests set
    status = v_status,
    released_at = case when v_status = 'void' then null else now() end,
    released_by_hr_id = case when v_status = 'void' then null else p_actor_hr_id end,
    answer_due_on = case when v_status = 'void' then null else p_answer_due_on end,
    total_deduction_days = round(v_total_days, 3),
    total_deduction_value = case when v_unpriced then null else round(v_total_value, 2) end,
    has_unpriced_day = v_unpriced,
    updated_at = now()
  where id = v_digest.id;

  return jsonb_build_object(
    'released', v_status <> 'void',
    'status', v_status,
    'pendingDays', v_pending,
    'clearedDays', v_cleared
  );
end;
$$;

ALTER FUNCTION public.phx_attendance_release_digest(p_digest_id bigint, p_actor_hr_id text, p_answer_due_on date, p_seen_line_ids bigint[], p_seen_days numeric[]) OWNER TO postgres;

--
-- Name: phx_attendance_remove_digest_line(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_remove_digest_line(p_line_id bigint, p_actor_hr_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_line public.attendance_digest_lines;
  v_digest public.attendance_weekly_digests;
  v_settlement_id bigint;
begin
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Say why this day is being removed.' using errcode = '22023';
  end if;

  select * into v_line from public.attendance_digest_lines where id = p_line_id for update;
  if not found then
    raise exception 'That day was not found.' using errcode = 'P0002';
  end if;

  select * into v_digest from public.attendance_weekly_digests where id = v_line.digest_id for update;
  if v_digest.status <> 'awaiting_release' then
    raise exception 'This week has already been released. A released day can only be cleared by upholding a dispute.'
      using errcode = '40001';
  end if;
  if v_line.action <> 'pending' then
    raise exception 'That day has already changed — reload and look again.' using errcode = '40001';
  end if;

  insert into public.attendance_settlements (
    digest_line_id, employee_hr_id, work_date, action, method,
    deduction_days, deduction_value, actor_hr_id, actor_role, reviewer_hr_id, reason
  ) values (
    v_line.id, v_digest.employee_hr_id, v_line.work_date, 'removed', null,
    0, 0, p_actor_hr_id, 'reviewer', p_actor_hr_id, btrim(p_reason)
  )
  returning id into v_settlement_id;

  update public.attendance_digest_lines set
    action = 'removed',
    removed_at = now(),
    removed_by_hr_id = p_actor_hr_id,
    remove_reason = btrim(p_reason),
    updated_at = now()
  where id = v_line.id;

  return jsonb_build_object('settlementId', v_settlement_id, 'digestId', v_digest.id, 'workDate', v_line.work_date);
end;
$$;

ALTER FUNCTION public.phx_attendance_remove_digest_line(p_line_id bigint, p_actor_hr_id text, p_reason text) OWNER TO postgres;

--
-- Name: phx_attendance_revise_digest_dispute(bigint, boolean, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_revise_digest_dispute(p_line_id bigint, p_uphold boolean, p_reviewer_hr_id text, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_line public.attendance_digest_lines;
  v_digest public.attendance_weekly_digests;
  v_charge public.attendance_annual_balance_charges;
  v_restored numeric := 0;
  v_previous_action text;
  v_previous_method text;
begin
  if p_reviewer_hr_id is null or btrim(p_reviewer_hr_id) = '' then
    raise exception 'A revised decision needs its reviewer.' using errcode = '22023';
  end if;

  select * into v_line from public.attendance_digest_lines where id = p_line_id for update;
  if not found then
    raise exception 'Digest line was not found.' using errcode = 'P0002';
  end if;
  if v_line.action not in ('dispute_upheld', 'dispute_rejected') then
    raise exception 'Only a decided dispute can be revised.' using errcode = '40001';
  end if;

  select * into v_digest from public.attendance_weekly_digests where id = v_line.digest_id for update;
  if v_digest.dry_run is distinct from false then
    raise exception 'This day belongs to a trial-run week.' using errcode = '40001';
  end if;

  v_previous_action := v_line.action;
  v_previous_method := v_line.chosen_method;

  if p_uphold then
    if v_line.action = 'dispute_upheld' then
      return jsonb_build_object('changed', false, 'previousAction', v_previous_action, 'previousMethod', v_previous_method);
    end if;
    update public.attendance_digest_lines
      set action = 'dispute_upheld',
          review_notes = coalesce(nullif(btrim(p_notes), ''), review_notes),
          updated_at = now()
      where id = v_line.id;

    -- The same lock key every balance writer takes, so a give-back cannot interleave a charge or a
    -- leave approval for this employee.
    perform pg_advisory_xact_lock(hashtext(lower(v_digest.employee_hr_id)));
    select * into v_charge from public.attendance_annual_balance_charges
      where digest_line_id = v_line.id and days > 0;
    if found and not exists (
      select 1 from public.attendance_annual_balance_charges where reverses_charge_id = v_charge.id
    ) then
      insert into public.attendance_annual_balance_charges (
        settlement_id, digest_line_id, employee_hr_id, work_date, days, period_start, period_end,
        created_by, reverses_charge_id, reversal_reason
      ) values (
        null, v_line.id, v_charge.employee_hr_id, v_charge.work_date, -v_charge.days,
        v_charge.period_start, v_charge.period_end, p_reviewer_hr_id, v_charge.id,
        coalesce(nullif(btrim(p_notes), ''), 'Dispute revised to upheld')
      );
      v_restored := v_charge.days;
    end if;
  else
    if v_line.action = 'dispute_rejected' then
      return jsonb_build_object('changed', false, 'previousAction', v_previous_action, 'previousMethod', v_previous_method);
    end if;
    update public.attendance_digest_lines
      set action = 'dispute_rejected',
          chosen_method = 'salary',
          review_notes = coalesce(nullif(btrim(p_notes), ''), review_notes),
          updated_at = now()
      where id = v_line.id;
  end if;

  return jsonb_build_object(
    'changed', true,
    'previousAction', v_previous_action,
    'previousMethod', v_previous_method,
    'restoredDays', v_restored,
    'employeeHrId', v_digest.employee_hr_id,
    'workDate', v_line.work_date,
    'deductionDays', v_line.deduction_days,
    'deductionValue', v_line.deduction_value
  );
end;
$$;

ALTER FUNCTION public.phx_attendance_revise_digest_dispute(p_line_id bigint, p_uphold boolean, p_reviewer_hr_id text, p_notes text) OWNER TO postgres;

--
-- Name: phx_attendance_settle_digest_line(bigint, text[], text, text, text, text, text, text, text, date, date, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_settle_digest_line(p_line_id bigint, p_expected_actions text[], p_action text, p_method text, p_actor_hr_id text, p_actor_role text, p_reviewer_hr_id text, p_reason text, p_review_notes text, p_period_start date, p_period_end date, p_seen_request_days numeric, p_seen_charge_days numeric, p_seen_copilot_days numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_line public.attendance_digest_lines;
  v_digest public.attendance_weekly_digests;
  v_charges_balance boolean;
  v_request_days numeric;
  v_charge_days numeric;
  v_copilot_days numeric;
  v_settlement_id bigint;
  v_days numeric;
  v_value numeric;
  v_remaining integer;
begin
  if p_action not in ('salary', 'annual_balance', 'auto_salary', 'dispute_upheld', 'dispute_rejected') then
    raise exception 'Unsupported settlement action %', p_action using errcode = '22023';
  end if;
  if p_method is not null and p_method not in ('salary', 'annual_balance') then
    raise exception 'Unsupported settlement method %', p_method using errcode = '22023';
  end if;

  select * into v_line from public.attendance_digest_lines where id = p_line_id for update;
  if not found then
    raise exception 'Digest line was not found.' using errcode = 'P0002';
  end if;
  if not (v_line.action = any (p_expected_actions)) then
    raise exception 'That day has already been answered — reload and look again.' using errcode = '40001';
  end if;

  select * into v_digest from public.attendance_weekly_digests where id = v_line.digest_id for update;
  if v_digest.status <> 'open' then
    raise exception 'This week is not open for answers.' using errcode = '40001';
  end if;
  -- A trial-run week is never released (owner 2026-09-15), so nothing in one may settle — not an
  -- answer, not a dispute decision, not the deadline sweep. The callers check too; this is the floor.
  if v_digest.dry_run is distinct from false then
    raise exception 'This week was built as a trial run and can never be settled.' using errcode = '40001';
  end if;

  v_charges_balance :=
    p_action = 'annual_balance'
    or (p_action = 'dispute_rejected' and p_method = 'annual_balance');

  v_days := v_line.deduction_days;
  v_value := case
    when p_action = 'dispute_upheld' then 0
    when v_charges_balance then 0
    else v_line.deduction_value
  end;

  if v_charges_balance then
    if p_period_start is null or p_period_end is null then
      raise exception 'An annual balance charge needs its balance period.' using errcode = '22023';
    end if;

    -- Same lock key as phx_apply_vacation_paid_approval, so a leave approval and a balance
    -- charge for one employee can never interleave.
    perform pg_advisory_xact_lock(hashtext(lower(v_digest.employee_hr_id)));

    -- THE DOUBLE-CHARGE GUARD. A balance charge is immutable, and salary is spared only because
    -- digest-bridge.ts later closes the day's month-end deduction with "Do Not Take Action" — which
    -- it can do only while that deduction is still Pending and unlocked. Once someone has decided
    -- it (approved it for payroll, or cleared it) or a publication has locked it, a balance charge
    -- would take the day twice or spend leave on a day payroll never charges. So refuse, and the
    -- employee is left with salary. recordDecision guards the other order: a day already charged
    -- to balance cannot be approved for payroll.
    if exists (
      select 1
      from public.deductions_candidates c
      left join public.deductions_decisions d on d.candidate_id = c.id
      -- HR ops bridge: a reviewed field day is charged by its own `field_review` deduction.
      where c.category = case when v_line.status = 'field_review' then 'field_review' else 'fingerprint' end
        and c.superseded_at is null
        and lower(c.source_record_id) = lower(v_digest.employee_hr_id || ':' || v_line.work_date::text)
        and (c.locked_at is not null or coalesce(d.decision_status, 'Pending') <> 'Pending')
    ) then
      raise exception 'This day has already been decided in the month-end deductions review, so annual balance can no longer be used for it.'
        using errcode = '55000';
    end if;

    select coalesce(sum(paid_duration_days), 0) into v_request_days
    from public.v2_vacation_requests
    where lower(employee_hr_id) = lower(v_digest.employee_hr_id)
      and status = 'approved'
      and vacation_type in ('annual', 'emergency')
      and start_date >= p_period_start
      and start_date <  p_period_end;

    select coalesce(sum(days), 0) into v_charge_days
    from public.attendance_annual_balance_charges
    where lower(employee_hr_id) = lower(v_digest.employee_hr_id)
      and work_date >= p_period_start
      and work_date <  p_period_end;

    select coalesce(sum(balance_days_consumed), 0) into v_copilot_days
    from public.payroll_copilot_vacation_settlements
    where employee_hr_id_compact = regexp_replace(lower(v_digest.employee_hr_id), '[^a-z0-9]+', '', 'g')
      and settlement_method in ('balance', 'partial_balance', 'defer_to_balance')
      and superseded_at is null
      and start_date >= p_period_start
      and start_date <  p_period_end;

    if round(v_request_days, 3) <> round(coalesce(p_seen_request_days, -1), 3)
       or round(v_charge_days, 3) <> round(coalesce(p_seen_charge_days, -1), 3)
       or round(v_copilot_days, 3) <> round(coalesce(p_seen_copilot_days, -1), 3) then
      raise exception 'The annual balance changed while this was being saved. Reload and try again.'
        using errcode = '40001';
    end if;
  end if;

  insert into public.attendance_settlements (
    digest_line_id, employee_hr_id, work_date, action, method,
    deduction_days, deduction_value, actor_hr_id, actor_role, reviewer_hr_id, reason
  ) values (
    v_line.id, v_digest.employee_hr_id, v_line.work_date, p_action,
    case
      when p_action in ('salary', 'auto_salary') then 'salary'
      when p_action = 'annual_balance' then 'annual_balance'
      else p_method
    end,
    case when p_action = 'dispute_upheld' then 0 else v_days end,
    v_value, p_actor_hr_id, p_actor_role, p_reviewer_hr_id, p_reason
  )
  returning id into v_settlement_id;

  if v_charges_balance then
    insert into public.attendance_annual_balance_charges (
      settlement_id, digest_line_id, employee_hr_id, work_date, days, period_start, period_end, created_by
    ) values (
      v_settlement_id, v_line.id, v_digest.employee_hr_id, v_line.work_date, v_days,
      p_period_start, p_period_end, coalesce(p_reviewer_hr_id, p_actor_hr_id)
    );
  end if;

  update public.attendance_digest_lines set
    action = p_action,
    chosen_method = case
      when p_action in ('salary', 'auto_salary') then 'salary'
      when p_action = 'annual_balance' then 'annual_balance'
      -- A rejected dispute records the method actually applied, which is salary when the
      -- balance the employee chose no longer covered the day.
      when p_action = 'dispute_rejected' then coalesce(p_method, chosen_method)
      else chosen_method
    end,
    review_notes = coalesce(p_review_notes, review_notes),
    acted_at = case when p_action in ('dispute_upheld', 'dispute_rejected') then acted_at else now() end,
    updated_at = now()
  where id = v_line.id;

  select count(*) into v_remaining
  from public.attendance_digest_lines
  where digest_id = v_digest.id
    and action in ('pending', 'disputed');
  if v_remaining = 0 then
    update public.attendance_weekly_digests
      set status = 'settled', updated_at = now()
      where id = v_digest.id and status = 'open';
  end if;

  return jsonb_build_object('settlementId', v_settlement_id, 'chargedBalance', v_charges_balance, 'digestSettled', v_remaining = 0);
end;
$$;

ALTER FUNCTION public.phx_attendance_settle_digest_line(p_line_id bigint, p_expected_actions text[], p_action text, p_method text, p_actor_hr_id text, p_actor_role text, p_reviewer_hr_id text, p_reason text, p_review_notes text, p_period_start date, p_period_end date, p_seen_request_days numeric, p_seen_charge_days numeric, p_seen_copilot_days numeric) OWNER TO postgres;

--
-- Name: phx_attendance_settlement_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_settlement_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'attendance_settlements rows are immutable (attempted DELETE)'
      using errcode = 'restrict_violation';
  end if;

  if (new.digest_line_id, new.employee_hr_id, new.work_date, new.action, new.method, new.deduction_days,
      new.deduction_value, new.actor_hr_id, new.actor_role, new.reviewer_hr_id, new.reason,
      new.decided_at)
     is distinct from
     (old.digest_line_id, old.employee_hr_id, old.work_date, old.action, old.method, old.deduction_days,
      old.deduction_value, old.actor_hr_id, old.actor_role, old.reviewer_hr_id, old.reason,
      old.decided_at)
  then
    raise exception 'attendance_settlements rows are immutable (only applied_candidate_id/applied_at may be stamped)'
      using errcode = 'restrict_violation';
  end if;

  if old.applied_candidate_id is not null
     and new.applied_candidate_id is distinct from old.applied_candidate_id then
    raise exception 'attendance_settlements.applied_candidate_id is write-once'
      using errcode = 'restrict_violation';
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_attendance_settlement_immutable() OWNER TO postgres;

--
-- Name: phx_attendance_sync_digest_days(text, text, integer, date, date, boolean, jsonb, date[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_attendance_sync_digest_days(p_employee_hr_id text, p_cycle_key text, p_week_index integer, p_week_start date, p_week_end date, p_dry_run boolean, p_days jsonb, p_cleared_dates date[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_hr text := btrim(coalesce(p_employee_hr_id, ''));
  v_days_json jsonb := coalesce(p_days, '[]'::jsonb);
  v_cleared_dates date[] := coalesce(p_cleared_dates, '{}'::date[]);
  v_digest public.attendance_weekly_digests;
  v_line public.attendance_digest_lines;
  v_day record;
  v_round smallint;
  v_created boolean := false;
  v_added integer := 0;
  v_updated integer := 0;
  v_cleared integer := 0;
  v_elsewhere integer := 0;
  v_removed_digest boolean := false;
  v_days numeric;
  v_value numeric;
  v_line_count integer;
  v_total_days numeric;
  v_total_value numeric;
  v_unpriced boolean;
begin
  if v_hr = '' or p_cycle_key !~ '^\d{4}-\d{2}$' or p_week_index is null or p_week_index not between 1 and 5
     or p_week_start is null or p_week_end is null or p_week_start > p_week_end or p_dry_run is null
     or jsonb_typeof(v_days_json) <> 'array' then
    raise exception 'The week to bring up to date is not valid.' using errcode = '22023';
  end if;
  if exists (
    select 1
    from jsonb_to_recordset(v_days_json) as d(work_date date, deduction_days numeric)
    where d.work_date is null
       or d.work_date < p_week_start
       or d.work_date > p_week_end
       or coalesce(d.deduction_days, 0) <= 0
       or d.work_date = any(v_cleared_dates)
  ) then
    raise exception 'A flagged day is outside its week, deducts nothing, or is also listed as cleared.' using errcode = '22023';
  end if;
  if (select count(*) from jsonb_to_recordset(v_days_json) as d(work_date date))
     <> (select count(distinct d.work_date) from jsonb_to_recordset(v_days_json) as d(work_date date)) then
    raise exception 'A flagged day is listed twice.' using errcode = '22023';
  end if;

  -- One sync of one employee-week at a time, whichever server runs it.
  perform pg_advisory_xact_lock(hashtextextended('attendance_digest_sync:' || upper(v_hr) || ':' || p_cycle_key || ':' || p_week_index::text, 0));

  -- The digest waiting for release, locked the way a tick and a release lock it.
  select * into v_digest
  from public.attendance_weekly_digests
  where upper(employee_hr_id) = upper(v_hr)
    and cycle_key = p_cycle_key
    and week_index = p_week_index
    and status = 'awaiting_release'
    and dry_run = p_dry_run
  order by id
  limit 1
  for update;

  for v_day in
    select *
    from jsonb_to_recordset(v_days_json) as d(
      work_date date,
      status text,
      late_minutes integer,
      short_minutes integer,
      worked_minutes integer,
      deduction_days numeric,
      deduction_value numeric,
      reason text,
      evidence jsonb
    )
    order by work_date
  loop
    -- A day already in another digest of this employee belongs to that digest: released, answered or
    -- cleared there. It is never asked about twice.
    if exists (
      select 1
      from public.attendance_digest_lines l
      join public.attendance_weekly_digests g on g.id = l.digest_id
      where upper(g.employee_hr_id) = upper(v_hr)
        and g.dry_run = p_dry_run
        and l.work_date = v_day.work_date
        and g.id is distinct from v_digest.id
    ) then
      v_elsewhere := v_elsewhere + 1;
      continue;
    end if;

    v_line := null;
    if v_digest.id is not null then
      select * into v_line
      from public.attendance_digest_lines
      where digest_id = v_digest.id and work_date = v_day.work_date
      for update;
    end if;

    if v_line.id is not null then
      -- Only a day still waiting is refreshed.
      if v_line.action <> 'pending' then
        continue;
      end if;
      -- HR ops bridge: a day decided in the HR operations report keeps the decision — the report never
      -- refreshes or overwrites it.
      if v_line.hr_ops_line_id is not null or v_line.status = 'field_review' then
        continue;
      end if;
      -- A day whose days the Super Admin changed keeps his figure; its estimate follows the new detection.
      -- Otherwise the charge follows what the report detects now. The tick is kept either way.
      if v_line.adjusted_by_hr_id is not null then
        v_days := v_line.deduction_days;
        v_value := case
          when v_day.deduction_value is null then null
          when v_days = round(v_day.deduction_days, 3) then round(v_day.deduction_value, 2)
          else round(v_day.deduction_value * v_days / v_day.deduction_days, 2)
        end;
      else
        v_days := round(v_day.deduction_days, 3);
        v_value := round(v_day.deduction_value, 2);
      end if;

      if (v_line.status, v_line.late_minutes, v_line.short_minutes, v_line.worked_minutes, v_line.deduction_days,
          v_line.deduction_value, v_line.detected_days, v_line.detected_value, v_line.reason, v_line.evidence)
         is distinct from
         (v_day.status, coalesce(v_day.late_minutes, 0), coalesce(v_day.short_minutes, 0), coalesce(v_day.worked_minutes, 0), v_days,
          v_value, round(v_day.deduction_days, 3), round(v_day.deduction_value, 2), coalesce(v_day.reason, ''), coalesce(v_day.evidence, '{}'::jsonb)) then
        update public.attendance_digest_lines set
          status = v_day.status,
          late_minutes = coalesce(v_day.late_minutes, 0),
          short_minutes = coalesce(v_day.short_minutes, 0),
          worked_minutes = coalesce(v_day.worked_minutes, 0),
          deduction_days = v_days,
          deduction_value = v_value,
          detected_days = round(v_day.deduction_days, 3),
          detected_value = round(v_day.deduction_value, 2),
          reason = coalesce(v_day.reason, ''),
          evidence = coalesce(v_day.evidence, '{}'::jsonb),
          updated_at = now()
        where id = v_line.id;
        v_updated := v_updated + 1;
      end if;
    else
      if v_digest.id is null then
        select coalesce(max(release_round), 0) + 1 into v_round
        from public.attendance_weekly_digests
        where upper(employee_hr_id) = upper(v_hr)
          and cycle_key = p_cycle_key
          and week_index = p_week_index;

        insert into public.attendance_weekly_digests (
          employee_hr_id, cycle_key, week_index, week_start, week_end, status,
          total_deduction_days, total_deduction_value, has_unpriced_day, dry_run, release_round
        ) values (
          v_hr, p_cycle_key, p_week_index, p_week_start, p_week_end, 'awaiting_release',
          0, 0, false, p_dry_run, v_round
        )
        returning * into v_digest;
        v_created := true;
      end if;

      -- A new day starts unticked (owner, 2026-09-15): nothing is deducted unless he ticks it.
      insert into public.attendance_digest_lines (
        digest_id, work_date, status, late_minutes, short_minutes, worked_minutes,
        deduction_days, deduction_value, detected_days, detected_value, reason, evidence, deduct
      ) values (
        v_digest.id, v_day.work_date, v_day.status, coalesce(v_day.late_minutes, 0), coalesce(v_day.short_minutes, 0),
        coalesce(v_day.worked_minutes, 0), round(v_day.deduction_days, 3), round(v_day.deduction_value, 2),
        round(v_day.deduction_days, 3), round(v_day.deduction_value, 2), coalesce(v_day.reason, ''),
        coalesce(v_day.evidence, '{}'::jsonb), false
      );
      v_added := v_added + 1;
    end if;
  end loop;

  if v_digest.id is null then
    return jsonb_build_object(
      'digestId', null, 'releaseRound', null, 'created', false, 'added', 0, 'updated', 0,
      'cleared', 0, 'alreadyElsewhere', v_elsewhere, 'removedDigest', false
    );
  end if;

  -- A waiting day the report now clears — an approved excuse, leave, or a corrected punch — is removed.
  -- Only a day the report positively cleared: a day missing from the report is left alone.
  if array_length(v_cleared_dates, 1) is not null then
    with gone as (
      delete from public.attendance_digest_lines l
      where l.digest_id = v_digest.id
        and l.action = 'pending'
        and l.work_date = any(v_cleared_dates)
        -- HR ops bridge: a day decided in the HR operations report is never removed by the report.
        and l.hr_ops_line_id is null and l.status <> 'field_review'
        and not exists (select 1 from public.attendance_settlements s where s.digest_line_id = l.id)
      returning 1
    )
    select count(*) into v_cleared from gone;
  end if;

  select
    count(*),
    coalesce(sum(deduction_days) filter (where action <> 'removed' and (deduct or action <> 'pending')), 0),
    coalesce(sum(deduction_value) filter (where action <> 'removed' and (deduct or action <> 'pending')), 0),
    coalesce(bool_or(deduction_value is null) filter (where action <> 'removed' and (deduct or action <> 'pending')), false)
  into v_line_count, v_total_days, v_total_value, v_unpriced
  from public.attendance_digest_lines
  where digest_id = v_digest.id;

  if v_line_count = 0 then
    -- Every day it held was cleared: nothing is left to release.
    delete from public.attendance_weekly_digests where id = v_digest.id and status = 'awaiting_release';
    v_removed_digest := true;
  elsif v_created or v_added > 0 or v_updated > 0 or v_cleared > 0 then
    update public.attendance_weekly_digests set
      total_deduction_days = round(v_total_days, 3),
      total_deduction_value = case when v_unpriced then null else round(v_total_value, 2) end,
      has_unpriced_day = v_unpriced,
      updated_at = now()
    where id = v_digest.id;
  end if;

  return jsonb_build_object(
    'digestId', case when v_removed_digest then null else v_digest.id end,
    'releaseRound', v_digest.release_round,
    'created', v_created and not v_removed_digest,
    'added', v_added,
    'updated', v_updated,
    'cleared', v_cleared,
    'alreadyElsewhere', v_elsewhere,
    'removedDigest', v_removed_digest and not v_created
  );
end;
$_$;

ALTER FUNCTION public.phx_attendance_sync_digest_days(p_employee_hr_id text, p_cycle_key text, p_week_index integer, p_week_start date, p_week_end date, p_dry_run boolean, p_days jsonb, p_cleared_dates date[]) OWNER TO postgres;

--
-- Name: phx_audit_position_vacancy_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_audit_position_vacancy_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old_status text := lower(coalesce(old.status, 'open'));
  v_new_status text := lower(coalesce(new.status, 'open'));
  v_actor text := coalesce(nullif(btrim(current_setting('phoenix.actor_login_id', true)), ''), 'system');
  v_line text;
  v_area text;
begin
  if tg_op = 'UPDATE' and v_old_status = v_new_status then
    return null;
  end if;

  begin
    select l.name into v_line from public.lines l where l.id = new.line_id;
    select a.name into v_area from public.areas a where a.id = new.area_id;

    insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, old_values, new_values)
    values (
      v_actor,
      'position_vacancy',
      coalesce(new.vacancy_code, new.id::text),
      case
        when tg_op = 'INSERT' then
          format('Vacancy %s opened for %s / %s%s',
            coalesce(new.vacancy_code, new.id::text),
            coalesce(v_line, 'unknown line'),
            coalesce(v_area, 'unknown area'),
            case when new.replacement_for_hr_id is not null
                 then ' (replacing ' || new.replacement_for_hr_id || ')' else '' end)
        else
          format('Vacancy %s: %s -> %s%s',
            coalesce(new.vacancy_code, new.id::text), v_old_status, v_new_status,
            case when new.filled_by_hr_id is not null
                 then ' (filled by ' || new.filled_by_hr_id || ')' else '' end)
      end,
      case when tg_op = 'UPDATE' then jsonb_build_object(
        'status', old.status,
        'filledByHrId', old.filled_by_hr_id,
        'replacementForHrId', old.replacement_for_hr_id
      ) else null end,
      jsonb_build_object(
        'vacancyId', new.id,
        'vacancyCode', new.vacancy_code,
        'status', new.status,
        'lineId', new.line_id,
        'lineName', v_line,
        'areaId', new.area_id,
        'areaName', v_area,
        'jobTitle', new.job_title,
        'managerHrId', new.manager_hr_id,
        'replacementForHrId', new.replacement_for_hr_id,
        'filledByHrId', new.filled_by_hr_id,
        'operation', tg_op
      )
    );
  exception when others then
    null;
  end;

  return null;
end;
$$;

ALTER FUNCTION public.phx_audit_position_vacancy_change() OWNER TO postgres;

--
-- Name: phx_auth_session_bundle(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_auth_session_bundle(p_sid uuid, p_login_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_session  jsonb;
  v_user     jsonb;
  v_employee jsonb;
  v_employee_lookup_failed boolean := false;
  v_employee_key text;
begin
  select to_jsonb(s) into v_session
    from (
      select id, login_id, hr_id, role, session_version, created_at, last_seen_at,
             idle_expires_at, absolute_expires_at, revoked_at, revoked_reason,
             supabase_session_required, supabase_session_available
        from public.app_sessions
       where id = p_sid
    ) s;

  select to_jsonb(u) into v_user
    from (
      select login_id, hr_id, role, is_active, session_version,
             is_test_persona, test_persona_of_hr_id
        from public.app_auth_users
       where login_id = p_login_id
    ) u;

  v_employee_key := nullif(btrim(coalesce(v_user->>'hr_id', '')), '');

  if v_employee_key is not null then
    begin
      select to_jsonb(e) into v_employee
        from (
          select employment_status, last_working_date
            from public.employees
           where hr_id = v_employee_key
        ) e;
    exception when others then
      v_employee_lookup_failed := true;
      v_employee := null;
    end;
  end if;

  return jsonb_build_object(
    'app_session', v_session,
    'auth_user', v_user,
    'employee', v_employee,
    'employee_lookup_failed', v_employee_lookup_failed,
    'employee_key', v_employee_key
  );
end;
$$;

ALTER FUNCTION public.phx_auth_session_bundle(p_sid uuid, p_login_id text) OWNER TO postgres;

--
-- Name: FUNCTION phx_auth_session_bundle(p_sid uuid, p_login_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_auth_session_bundle(p_sid uuid, p_login_id text) IS 'Resolves the auth trio (app_sessions, app_auth_users, employees lifecycle) in ONE round trip for src/lib/auth/server.ts. Returns rows, never decisions -- all policy stays in TypeScript. service_role only: the payload is session and account data for an arbitrary login_id.';

