--
-- Name: phx_automated_payroll_draft_cell_history_capture(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_automated_payroll_draft_cell_history_capture() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  new_doc jsonb := to_jsonb(new);
  old_doc jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  key text;
begin
  for key in select jsonb_object_keys(new_doc) loop
    if key in ('run_id', 'employee_hr_id', 'employee_hr_id_compact', 'updated_at', 'edited_by',
               'source', 'write_reason', 'write_step_key') then
      continue;
    end if;
    if tg_op = 'INSERT' and new_doc -> key = 'null'::jsonb then
      continue;
    end if;
    if tg_op = 'UPDATE' and (new_doc -> key) is not distinct from (old_doc -> key) then
      continue;
    end if;
    insert into public.automated_payroll_draft_cell_history
      (run_id, employee_hr_id, employee_hr_id_compact, column_name, old_value, new_value,
       changed_by, write_reason, step_key, input_mode)
    values
      (new.run_id, new.employee_hr_id, new.employee_hr_id_compact, key,
       case when old_doc -> key is null or old_doc -> key = 'null'::jsonb then null else old_doc ->> key end,
       case when new_doc -> key = 'null'::jsonb then null else new_doc ->> key end,
       new.edited_by, new.write_reason, new.write_step_key, new.source);
  end loop;
  return null;
end;
$$;

ALTER FUNCTION public.phx_automated_payroll_draft_cell_history_capture() OWNER TO postgres;

--
-- Name: phx_backfill_sos_customer_directory_rollup(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_backfill_sos_customer_directory_rollup() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
begin
  delete from public.source_of_sales_customer_directory_rollup;

  insert into public.source_of_sales_customer_directory_rollup (
    batch_id,
    period,
    distributor_code,
    client_code,
    product_code,
    is_direct,
    client_name,
    client_address,
    brick_id,
    area_code,
    region_code,
    official_line,
    latest_row_created_at,
    effective_units,
    total_qty,
    row_count
  )
  select
    r.batch_id,
    coalesce(nullif(btrim(r.invoice_period), ''), '') as period,
    coalesce(nullif(btrim(r.distributor_code), ''), b.distributor_code, '') as distributor_code,
    nullif(btrim(r.client_code), '') as client_code,
    coalesce(nullif(upper(btrim(r.product_code)), ''), '') as product_code,
    coalesce(r.is_direct, false) as is_direct,
    (array_agg(nullif(btrim(r.client_name), '') order by (nullif(btrim(r.client_name), '') is null), r.created_at desc nulls last))[1] as client_name,
    (array_agg(nullif(btrim(r.client_address), '') order by (nullif(btrim(r.client_address), '') is null), r.created_at desc nulls last))[1] as client_address,
    (array_agg(nullif(btrim(r.brick_id), '') order by (nullif(btrim(r.brick_id), '') is null), r.created_at desc nulls last))[1] as brick_id,
    (array_agg(nullif(btrim(r.area_code), '') order by (nullif(btrim(r.area_code), '') is null), r.created_at desc nulls last))[1] as area_code,
    (array_agg(nullif(btrim(r.region_code), '') order by (nullif(btrim(r.region_code), '') is null), r.created_at desc nulls last))[1] as region_code,
    (array_agg(nullif(btrim(r.official_line), '') order by (nullif(btrim(r.official_line), '') is null), r.created_at desc nulls last))[1] as official_line,
    max(coalesce(r.created_at, b.created_at, 'epoch'::timestamptz)) as latest_row_created_at,
    sum(coalesce(r.qty, 0)) as effective_units,
    sum(coalesce(r.qty, 0)) as total_qty,
    count(*)::integer as row_count
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b
    on b.id = r.batch_id
   and b.status = 'validated'
  where nullif(btrim(r.client_code), '') is not null
  group by
    r.batch_id,
    coalesce(nullif(btrim(r.invoice_period), ''), ''),
    coalesce(nullif(btrim(r.distributor_code), ''), b.distributor_code, ''),
    nullif(btrim(r.client_code), ''),
    coalesce(nullif(upper(btrim(r.product_code)), ''), ''),
    coalesce(r.is_direct, false);
end;
$$;

ALTER FUNCTION public.phx_backfill_sos_customer_directory_rollup() OWNER TO postgres;

--
-- Name: phx_backfill_sos_fact_rollup(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_backfill_sos_fact_rollup() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  rec record;
begin
  for rec in
    select id
    from public.source_of_sales_import_batches
    where status = 'validated' and period is not null
  loop
    perform public.phx_refresh_sos_fact_rollup(rec.id);
    perform public.phx_refresh_sos_channel_rollup(rec.id);
    perform public.phx_refresh_sos_distributor_product_rollup(rec.id);
    perform public.phx_refresh_monthly_attribution(rec.id);
  end loop;
end;
$$;

