--
-- Name: phx_brick_move_period_net_status(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_brick_move_period_net_status(p_since_days integer DEFAULT 30) RETURNS TABLE(period text, last_moved_at timestamp with time zone, net_computed_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'au', 'public'
    SET statement_timeout TO '60s'
    AS $$
  with moved as (
    select r.period as period, max(f.moved_at) as last_moved_at
    from public.source_of_sales_brick_move_files f
    join public.source_of_sales_fact_rollup r on r.batch_id = f.batch_id
    where f.moved_at >= now() - make_interval(days => greatest(coalesce(p_since_days, 30), 1))
    group by r.period
  ),
  net as (
    select n.period as period, min(n.computed_at) as net_computed_at
    from au.monthly_store_split_net n
    group by n.period
  )
  select m.period, m.last_moved_at, n.net_computed_at
  from moved m
  left join net n on n.period = m.period
  order by m.period desc;
$$;

ALTER FUNCTION public.phx_brick_move_period_net_status(p_since_days integer) OWNER TO postgres;

--
-- Name: phx_cancel_marketing_request(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_cancel_marketing_request(p_request_id uuid, p_expected_status text, p_actor_hr_id text, p_cancelled_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_status        text;
  v_closed_steps  integer := 0;
begin
  -- The request first, the same lock phx_decide_marketing_request_step takes first.
  select r.status into v_status
    from marketing_requests r
   where r.id = p_request_id
   for update;
  if not found then
    raise exception 'marketing_request_not_found: request % does not exist', p_request_id;
  end if;

  -- Compare-and-set against the status the caller read and judged cancellable.
  if v_status is distinct from p_expected_status then
    raise exception 'marketing_cancel_conflict: request % is %, not %', p_request_id, v_status, p_expected_status;
  end if;

  -- Stamping updated_by_hr_id / updated_at is what lets the AFTER UPDATE capture trigger record WHO
  -- cancelled it and from which state — exactly as the TypeScript update did.
  update marketing_requests
     set status           = 'cancelled',
         updated_at       = p_cancelled_at,
         updated_by_hr_id = p_actor_hr_id
   where id = p_request_id;

  -- Close every rung still open, exactly as a reject closes the rungs below it: 'skipped', no
  -- decision recorded (the Case File reads this as "Closed out without a decision"). Rungs already
  -- decided keep their decision; CC rows are already 'skipped'.
  update marketing_request_approval_steps
     set status     = 'skipped',
         updated_at = p_cancelled_at
   where request_id = p_request_id
     and status in ('current', 'pending')
     and is_cc = false;
  get diagnostics v_closed_steps = row_count;

  return jsonb_build_object(
    'requestId',      p_request_id,
    'previousStatus', v_status,
    'status',         'cancelled',
    'closedSteps',    v_closed_steps
  );
end;
$$;

ALTER FUNCTION public.phx_cancel_marketing_request(p_request_id uuid, p_expected_status text, p_actor_hr_id text, p_cancelled_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION phx_cancel_marketing_request(p_request_id uuid, p_expected_status text, p_actor_hr_id text, p_cancelled_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_cancel_marketing_request(p_request_id uuid, p_expected_status text, p_actor_hr_id text, p_cancelled_at timestamp with time zone) IS 'Cancels a marketing request (compare-and-set on the status the caller read) and closes its open approval rungs as skipped, under the request row lock.';

