--

COMMENT ON FUNCTION public.phx_capture_deduction_dispute_state(p_candidate_id uuid) IS 'The before-state of a deduction dispute decision (F-PAY-005): lock, decision row, publication lines, the month''s publications and the case''s refunds. Read by phx_restore_deduction_dispute_state.';

--
-- Name: phx_capture_marketing_request_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_capture_marketing_request_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.marketing_request_events
      (request_id, request_code, kind, actor_hr_id, occurred_at, to_status, payload)
    values
      (new.id, new.request_code, 'request_created',
       coalesce(new.created_by_hr_id, new.requester_hr_id), new.created_at, new.status,
       jsonb_build_object('estimated_cost', new.estimated_cost, 'origin', new.origin));
    return new;
  end if;

  if tg_op = 'DELETE' then
    insert into public.marketing_request_events
      (request_id, request_code, kind, actor_hr_id, occurred_at, from_status, payload)
    values
      (old.id, old.request_code, 'request_deleted', old.updated_by_hr_id, now(), old.status,
       jsonb_build_object('deleted_row', to_jsonb(old)));
    return old;
  end if;

  if new.status is distinct from old.status then
    insert into public.marketing_request_events
      (request_id, request_code, kind, actor_hr_id, occurred_at, from_status, to_status)
    values
      (new.id, new.request_code,
       case
         when old.status = 'draft' and new.status = 'pending_approval' then 'request_submitted'
         else 'request_status_changed'
       end,
       new.updated_by_hr_id, coalesce(new.updated_at, now()), old.status, new.status);
  end if;

  if new.estimated_cost is distinct from old.estimated_cost then
    insert into public.marketing_request_events
      (request_id, request_code, kind, actor_hr_id, occurred_at, payload)
    values
      (new.id, new.request_code, 'request_value_changed', new.updated_by_hr_id,
       coalesce(new.updated_at, now()),
       jsonb_build_object('from', old.estimated_cost, 'to', new.estimated_cost));
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_capture_marketing_request_event() OWNER TO postgres;

--
-- Name: phx_capture_marketing_step_event(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_capture_marketing_step_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_code text;
  v_kind         text;
begin
  if tg_op = 'INSERT' then
    if new.status <> 'current' then
      return new;
    end if;
    v_kind := 'step_opened';
  else
    if new.status is distinct from old.status then
      v_kind := case when new.status = 'current' then 'step_opened' else 'step_decided' end;
    elsif new.decision_note is distinct from old.decision_note then
      v_kind := 'step_commented';
    else
      return new;
    end if;
  end if;

  select r.request_code into v_request_code
  from public.marketing_requests r
  where r.id = new.request_id;

  insert into public.marketing_request_events
    (request_id, request_code, kind, actor_hr_id, occurred_at,
     from_status, to_status, step_sequence, step_name, note, payload)
  values
    (new.request_id, v_request_code, v_kind,
     coalesce(new.decision_by_hr_id, new.assigned_hr_id),
     coalesce(new.decision_at, new.updated_at, now()),
     case when tg_op = 'UPDATE' then old.status else null end,
     new.status, new.sequence, new.step_name, new.decision_note,
     jsonb_build_object('step_code', new.step_code, 'is_cc', new.is_cc));

  return new;
end;
$$;

ALTER FUNCTION public.phx_capture_marketing_step_event() OWNER TO postgres;

--
-- Name: phx_capture_query_stats(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_capture_query_stats(p_top integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  n integer;
begin
  -- Rank on THREE axes, not just cumulative time. Ranking by total_exec_time alone
  -- was the first version of this function, and it silently failed its own purpose:
  -- a 3.5s query called 15 times has ~50s cumulative and never enters a top-50 list
  -- headed by PostgREST queries with 6,917s. The query worth catching is the one that
  -- is slow PER CALL, long before its cumulative total climbs anywhere near the top.
  insert into public.pg_stat_statements_snapshots (
    queryid, query_sample, calls, total_exec_ms, mean_exec_ms, max_exec_ms,
    rows_returned, shared_blks_hit, shared_blks_read
  )
  with ranked as (
    select s.*,
           row_number() over (order by s.total_exec_time desc) as r_total,
           row_number() over (order by s.max_exec_time  desc)  as r_max,
           row_number() over (order by s.mean_exec_time desc)  as r_mean
    from extensions.pg_stat_statements s
    where s.dbid = (select oid from pg_database where datname = current_database())
      and s.queryid is not null
      and s.calls > 0
  )
  select r.queryid,
         left(regexp_replace(r.query, '\s+', ' ', 'g'), 300),
         r.calls, r.total_exec_time, r.mean_exec_time, r.max_exec_time,
         r.rows, r.shared_blks_hit, r.shared_blks_read
  from ranked r
  where r.r_total <= greatest(p_top, 1)
     or r.r_max   <= greatest(p_top, 1)
     or r.r_mean  <= greatest(p_top, 1);

  get diagnostics n = row_count;

  delete from public.pg_stat_statements_snapshots
  where captured_at < now() - interval '90 days';

  return n;
end;
$$;

ALTER FUNCTION public.phx_capture_query_stats(p_top integer) OWNER TO postgres;

--
-- Name: phx_ci_advisor_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_ci_advisor_counts() RETURNS TABLE(category text, current_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select 'rls_enabled_no_policy'::text, count(*)::integer
    from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid = c.relnamespace
   where c.relkind in ('r', 'p')
     and c.relrowsecurity
     and (select count(*) from pg_catalog.pg_policy p where p.polrelid = c.oid) = 0
     and n.nspname not in ('pg_catalog', 'information_schema', 'pg_toast',
                           'auth', 'storage', 'realtime', 'vault', 'extensions',
                           'graphql', 'graphql_public', 'cron', 'net', 'supabase_migrations')
     and n.nspname not like 'pg\\_%'
     and n.nspname not like 'pgsodium%'
     and n.nspname not like 'supabase\\_%'
  union all
  select 'function_search_path_mutable', count(*)::integer
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.prokind = 'f'
     and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) cfg
                      where cfg like 'search_path=%')
     and not exists (select 1 from pg_catalog.pg_depend d
                      where d.objid = p.oid
                        and d.classid = 'pg_proc'::regclass
                        and d.deptype = 'e')
  union all
  select 'extension_in_public', count(*)::integer
    from pg_catalog.pg_extension e
    join pg_catalog.pg_namespace n on n.oid = e.extnamespace
   where n.nspname = 'public'
  union all
  select 'authenticated_security_definer_function_executable', count(*)::integer
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.prosecdef
     and pg_catalog.has_function_privilege('authenticated', p.oid, 'EXECUTE')
  union all
  select 'unused_index', count(*)::integer
    from pg_catalog.pg_stat_user_indexes s
    join pg_catalog.pg_index i on i.indexrelid = s.indexrelid
   where s.idx_scan = 0
     and not i.indisunique
     and not i.indisprimary
     and not exists (select 1 from pg_catalog.pg_constraint ct where ct.conindid = i.indexrelid)
  union all
  select 'stats_age_hours',
         coalesce(extract(epoch from (now() - greatest(s.stats_reset, k.stats_reset))) / 3600, -1)::integer
    from pg_catalog.pg_stat_database s
   cross join pg_catalog.pg_stat_checkpointer k
   where s.datname = current_database();
$$;

ALTER FUNCTION public.phx_ci_advisor_counts() OWNER TO postgres;

--
-- Name: FUNCTION phx_ci_advisor_counts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_ci_advisor_counts() IS 'Supabase advisor categories recomputed from pg_catalog so CI can gate on them without the MCP get_advisors tool. Validated to match a live advisor run exactly on 2026-09-29 (rls_enabled_no_policy 176, function_search_path_mutable 10, extension_in_public 1, authenticated_security_definer_function_executable 14); unused_index uses our own stated definition. Reports only — scripts/check-advisor-baseline.ts holds the baseline and decides.';

--
-- Name: phx_ci_browser_reachability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_ci_browser_reachability() RETURNS TABLE(relname text, relkind text, anon_select boolean, auth_select boolean, rls_enabled boolean, policy_count integer, security_invoker boolean, open_policy text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  select
    c.relname::text,
    (case c.relkind
       when 'r' then 'table'  when 'p' then 'partitioned'
       when 'v' then 'view'   when 'm' then 'matview'
       else c.relkind::text end)::text,
    pg_catalog.has_table_privilege('anon', c.oid, 'SELECT'),
    pg_catalog.has_table_privilege('authenticated', c.oid, 'SELECT'),
    c.relrowsecurity,
    (select count(*)::integer from pg_catalog.pg_policy p where p.polrelid = c.oid),
    (case when c.relkind in ('v', 'm')
          then coalesce(c.reloptions::text[] @> array['security_invoker=true']
                     or c.reloptions::text[] @> array['security_invoker=on'], false)
          else null end),
    (select string_agg(distinct r.who, ',' order by r.who)
       from (
         select case when p.polroles = '{0}'::oid[] then 'PUBLIC'
                     else (select rl.rolname::text from pg_catalog.pg_roles rl
                            where rl.oid = any(p.polroles)
                              and rl.rolname in ('anon', 'authenticated')
                            limit 1) end as who
           from pg_catalog.pg_policy p
          where p.polrelid = c.oid
            and p.polpermissive
            and p.polcmd in ('r', '*')
            and (p.polqual is null
                 or pg_catalog.pg_get_expr(p.polqual, p.polrelid) ~ '^[[:space:]]*true[[:space:]]*$')
            and (p.polroles = '{0}'::oid[]
                 or p.polroles && array(select rl2.oid from pg_catalog.pg_roles rl2
                                         where rl2.rolname in ('anon', 'authenticated')))
       ) r
      where r.who is not null)::text
  from pg_catalog.pg_class c
  join pg_catalog.pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relkind in ('r', 'p', 'v', 'm')
    and (pg_catalog.has_table_privilege('anon', c.oid, 'SELECT')
      or pg_catalog.has_table_privilege('authenticated', c.oid, 'SELECT'))
  order by c.relname;
$_$;

ALTER FUNCTION public.phx_ci_browser_reachability() OWNER TO postgres;

--
-- Name: FUNCTION phx_ci_browser_reachability(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_ci_browser_reachability() IS 'Per-relation browser reachability in public, for the daily schema-shape check. Reports only relations granted to anon or authenticated. Two facts nothing else in this repo reads from the LIVE database: a permissive `true` read policy, and a granted view that is not security_invoker. Reports only — the allowlist and the verdict live in check-schema-shape.ts.';

--
-- Name: phx_ci_employee_keys(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_ci_employee_keys() RETURNS TABLE(table_schema text, table_name text, column_name text, constraint_name text, validated boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select
    n.nspname::text,
    r.relname::text,
    a.attname::text,
    c.conname::text,
    c.convalidated
  from pg_constraint c
  join pg_class r on r.oid = c.conrelid
  join pg_namespace n on n.oid = r.relnamespace
  join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
  join pg_attribute fa on fa.attrelid = c.confrelid and fa.attnum = c.confkey[1]
  where c.contype = 'f'
    and c.confrelid = 'public.employees'::regclass
    and array_length(c.confkey, 1) = 1
    and fa.attname = 'hr_id'
  order by n.nspname, r.relname, a.attname;
$$;

