--
-- Name: phx_ci_schema_shape(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_ci_schema_shape() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  with rel as (
    select c.oid, c.relname, c.relrowsecurity, c.relforcerowsecurity
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p')
  ),
  reachable as (
    select r.*,
           (has_table_privilege('anon', r.oid, 'SELECT')
             or has_table_privilege('anon', r.oid, 'INSERT')
             or has_table_privilege('anon', r.oid, 'UPDATE')
             or has_table_privilege('anon', r.oid, 'DELETE')
             or has_table_privilege('authenticated', r.oid, 'SELECT')
             or has_table_privilege('authenticated', r.oid, 'INSERT')
             or has_table_privilege('authenticated', r.oid, 'UPDATE')
             or has_table_privilege('authenticated', r.oid, 'DELETE')) as browser_reachable
    from rel r
  ),
  default_acl as (
    select pg_get_userbyid(d.defaclrole) as granting_role,
           case d.defaclobjtype
             when 'r' then 'TABLES'
             when 'S' then 'SEQUENCES'
             when 'f' then 'FUNCTIONS'
             when 'T' then 'TYPES'
             else d.defaclobjtype::text
           end as obj_type,
           coalesce(pg_get_userbyid(nullif(a.grantee, 0)), 'PUBLIC') as grantee,
           string_agg(a.privilege_type, ',' order by a.privilege_type) as privs
    from pg_default_acl d
    join pg_namespace n on n.oid = d.defaclnamespace
    cross join lateral aclexplode(d.defaclacl) a
    where n.nspname = 'public'
      and d.defaclobjtype in ('r', 'S', 'f')
      and (a.grantee = 0
           or a.grantee = to_regrole('anon')
           or a.grantee = to_regrole('authenticated'))
    group by 1, 2, 3
  )
  select jsonb_build_object(
    'tables_total',            (select count(*) from rel),
    'tables_rls_enabled',      (select count(*) from rel where relrowsecurity),
    'tables_force_rls',        (select count(*) from rel where relforcerowsecurity),
    'policies_total',          (select count(*) from pg_policies where schemaname = 'public'),
    'primary_keys_total',      (select count(*) from pg_constraint k join rel r on r.oid = k.conrelid where k.contype = 'p'),
    'unique_total',            (select count(*) from pg_constraint k join rel r on r.oid = k.conrelid where k.contype = 'u'),
    'foreign_keys_total',      (select count(*) from pg_constraint k join rel r on r.oid = k.conrelid where k.contype = 'f'),
    'check_total',             (select count(*) from pg_constraint k join rel r on r.oid = k.conrelid where k.contype = 'c'),
    'indexes_total',           (select count(*) from pg_indexes where schemaname = 'public'),
    'triggers_total',          (select count(*) from pg_trigger t join rel r on r.oid = t.tgrelid where not t.tgisinternal),
    'schema_usage', jsonb_build_object(
      'anon',          has_schema_privilege('anon', 'public', 'USAGE'),
      'authenticated', has_schema_privilege('authenticated', 'public', 'USAGE'),
      'service_role',  has_schema_privilege('service_role', 'public', 'USAGE')
    ),
    -- NULL when schema `private` is absent: the subquery returns no rows rather than
    -- has_schema_privilege() raising 3F000 on a database that never had the schema.
    'private_schema_usage', (
      select jsonb_build_object(
        'anon',          has_schema_privilege('anon',          n.oid, 'USAGE'),
        'authenticated', has_schema_privilege('authenticated', n.oid, 'USAGE'),
        'service_role',  has_schema_privilege('service_role',  n.oid, 'USAGE')
      )
      from pg_namespace n
      where n.nspname = 'private'
    ),
    -- How much RLS actually depends on reaching `private`. Matching on the rendered policy
    -- expression is deliberately broad — ANY reference to a private-schema object needs
    -- USAGE, not just the phx_* helpers — and it is what keeps the check an invariant
    -- rather than a snapshot: no policies, no demand, no allowlist to maintain.
    'policies_using_private_schema', (
      select count(*)
      from pg_policies
      where schemaname = 'public'
        and (coalesce(qual, '') like '%private.%' or coalesce(with_check, '') like '%private.%')
    ),
    'tables_exposed_without_rls',
      coalesce((select jsonb_agg(relname order by relname) from reachable
                 where browser_reachable and not relrowsecurity), '[]'::jsonb),
    'tables_rls_disabled',
      coalesce((select jsonb_agg(relname order by relname) from rel
                 where not relrowsecurity), '[]'::jsonb),
    'tables_without_primary_key',
      coalesce((select jsonb_agg(relname order by relname) from rel r
                 where not exists (select 1 from pg_constraint k
                                    where k.conrelid = r.oid and k.contype = 'p')), '[]'::jsonb),
    'tables_rls_enabled_without_policy',
      coalesce((select jsonb_agg(relname order by relname) from rel r
                 where r.relrowsecurity
                   and not exists (select 1 from pg_policies p
                                    where p.schemaname = 'public' and p.tablename = r.relname)), '[]'::jsonb),
    'default_acl_leaks',
      coalesce((select jsonb_agg(jsonb_build_object(
                          'granting_role', granting_role,
                          'obj_type',      obj_type,
                          'grantee',       grantee,
                          'privs',         privs)
                        order by granting_role, obj_type, grantee)
                from default_acl), '[]'::jsonb)
  );
$$;

ALTER FUNCTION public.phx_ci_schema_shape() OWNER TO postgres;

--
-- Name: FUNCTION phx_ci_schema_shape(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_ci_schema_shape() IS 'Read-only shape of the public schema (counts + object names, never row data) for the scheduled schema-drift monitor. See scripts/check-schema-shape.ts.';

--
-- Name: phx_ci_snapshot_tables_in_public(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_ci_snapshot_tables_in_public() RETURNS TABLE(table_name text, anon_select boolean, authenticated_select boolean, rls_enabled boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select
    c.relname::text,
    case when to_regrole('anon') is null then false
         else has_table_privilege('anon', c.oid, 'SELECT') end,
    case when to_regrole('authenticated') is null then false
         else has_table_privilege('authenticated', c.oid, 'SELECT') end,
    c.relrowsecurity
  from pg_catalog.pg_class c
  join pg_catalog.pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relkind in ('r', 'p')
    and (
      c.relname ~* '(^|_)(backup|backups|bak|undo|rollback)(_|$)'
      or (
        c.relname ~* '(^|_)(snapshot|old|copy|tmp|temp|orig|prev|pre)(_|$)'
        and c.relname ~ '(^|_)(19|20)[0-9]{6}(_|$)'
      )
    )
  order by c.relname;
$_$;

ALTER FUNCTION public.phx_ci_snapshot_tables_in_public() OWNER TO postgres;

--
-- Name: FUNCTION phx_ci_snapshot_tables_in_public(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_ci_snapshot_tables_in_public() IS 'CI gate: point-in-time snapshot tables sitting in public, where PostgREST serves them. Rule mirrors scripts/lib/snapshot-name.ts; remedy is docs/security/backup-table-placement.md.';

--
-- Name: phx_ci_stale_snapshot_schemas(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_ci_stale_snapshot_schemas(p_max_age_days integer DEFAULT 30) RETURNS TABLE(schema_name text, taken_on date, age_days integer, tables_count bigint, size_bytes bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with dated as (
    select n.nspname::text as schema_name,
           to_date(right(n.nspname, 8), 'YYYYMMDD') as taken_on
    from pg_namespace n
    where n.nspname ~ '[0-9]{8}$'
      and n.nspname not in ('public', 'au')
      and n.nspname !~ '^(pg_|information_schema)'
  )
  select d.schema_name,
         d.taken_on,
         -- Cairo, never UTC: production Postgres runs UTC, so an unzoned current_date reads
         -- as yesterday between Cairo 00:00 and 03:00 and would age every schema a day short.
         (((now() at time zone 'Africa/Cairo')::date) - d.taken_on)::integer as age_days,
         count(c.oid)                          as tables_count,
         coalesce(sum(pg_total_relation_size(c.oid)), 0)::bigint as size_bytes
  from dated d
  left join pg_class c
    on c.relnamespace = d.schema_name::regnamespace
   and c.relkind in ('r','p','m')
  where ((now() at time zone 'Africa/Cairo')::date) - d.taken_on > greatest(p_max_age_days, 1)
  group by d.schema_name, d.taken_on
  order by d.taken_on;
$_$;

ALTER FUNCTION public.phx_ci_stale_snapshot_schemas(p_max_age_days integer) OWNER TO postgres;

--
-- Name: FUNCTION phx_ci_stale_snapshot_schemas(p_max_age_days integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_ci_stale_snapshot_schemas(p_max_age_days integer) IS 'Dated snapshot schemas older than the retention window. Consumed by scripts/check-schema-shape.ts so a snapshot cannot be left behind silently.';

--
-- Name: phx_claim_automated_payroll_run_transition(uuid, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_claim_automated_payroll_run_transition(p_run_id uuid, p_expected_phases text[], p_action text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_token uuid := gen_random_uuid();
begin
  update public.automated_payroll_runs
     set transition_token = v_token,
         transition_action = p_action,
         transition_started_at = now()
   where id = p_run_id
     and phase = any (p_expected_phases)
     and (transition_token is null or transition_started_at < now() - interval '15 minutes');
  if not found then
    return null;
  end if;
  return v_token;
end;
$$;

