--
-- Name: phx_close_early_birds_period(text, date, date, text, text, smallint, jsonb, integer, text, text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_close_early_birds_period(p_period_key text, p_period_start date, p_period_end date, p_manager_hr_id text, p_manager_hr_id_compact text, p_scoring_version smallint, p_weights jsonb, p_contested_days integer, p_trigger text, p_computed_by text, p_replace boolean, p_candidates jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_existing public.early_birds_period_snapshots;
  v_snapshot public.early_birds_period_snapshots;
  v_decisions int := 0;
  v_winners int := 0;
  v_rep_count int := 0;
  v_candidate_count int := 0;
begin
  select * into v_existing
  from public.early_birds_period_snapshots
  where manager_hr_id_compact = p_manager_hr_id_compact
    and period_key = p_period_key
    and superseded_at is null
  for update;

  if found then
    if not coalesce(p_replace, false) then
      return jsonb_build_object('created', false, 'snapshot_id', v_existing.id, 'status', v_existing.status);
    end if;

    select count(*) into v_decisions from public.early_birds_decisions where snapshot_id = v_existing.id;
    select count(*) into v_winners from public.early_birds_winners
      where snapshot_id = v_existing.id and revoked_at is null;

    if v_decisions > 0 or v_winners > 0 then
      raise exception 'Early Birds % for % already has decisions; supersede is refused', p_period_key, p_manager_hr_id
        using errcode = '23514';
    end if;

    update public.early_birds_period_snapshots
      set superseded_at = now(), status = 'superseded'
      where id = v_existing.id;
  end if;

  insert into public.early_birds_period_snapshots (
    period_key, period_start, period_end, manager_hr_id, manager_hr_id_compact,
    scoring_version, weights, contested_days, trigger, computed_by
  ) values (
    p_period_key, p_period_start, p_period_end, p_manager_hr_id, p_manager_hr_id_compact,
    coalesce(p_scoring_version, 1::smallint), coalesce(p_weights, '{}'::jsonb),
    coalesce(p_contested_days, 0), coalesce(p_trigger, 'scheduler'), coalesce(p_computed_by, 'system')
  )
  returning * into v_snapshot;

  if v_existing.id is not null then
    update public.early_birds_period_snapshots
      set superseded_by_snapshot_id = v_snapshot.id
      where id = v_existing.id;
  end if;

  insert into public.early_birds_candidates (
    snapshot_id, period_key, manager_hr_id, employee_hr_id, employee_hr_id_compact, employee_name,
    candidate_key, rank, candidate_rank, eligible, ineligible_reasons,
    total_score, base_score, quality_weight, component_scores, median_start_minutes,
    days_with_submission, expected_working_days, total_visits, regular_visits,
    regular_visits_with_checkin, regular_visits_no_checkin, campaign_visits,
    gps_eligible_visits, gps_verified_visits, gps_share, daily_wins, evidence
  )
  select
    v_snapshot.id, p_period_key, p_manager_hr_id,
    row_value->>'employee_hr_id',
    row_value->>'employee_hr_id_compact',
    row_value->>'employee_name',
    row_value->>'candidate_key',
    (row_value->>'rank')::int,
    nullif(row_value->>'candidate_rank', '')::int,
    coalesce((row_value->>'eligible')::boolean, true),
    coalesce(
      (select array_agg(value::text) from jsonb_array_elements_text(row_value->'ineligible_reasons')),
      '{}'::text[]
    ),
    (row_value->>'total_score')::numeric,
    (row_value->>'base_score')::numeric,
    (row_value->>'quality_weight')::numeric,
    coalesce(row_value->'component_scores', '{}'::jsonb),
    nullif(row_value->>'median_start_minutes', '')::int,
    coalesce((row_value->>'days_with_submission')::int, 0),
    coalesce((row_value->>'expected_working_days')::int, 0),
    coalesce((row_value->>'total_visits')::int, 0),
    coalesce((row_value->>'regular_visits')::int, 0),
    coalesce((row_value->>'regular_visits_with_checkin')::int, 0),
    coalesce((row_value->>'regular_visits_no_checkin')::int, 0),
    coalesce((row_value->>'campaign_visits')::int, 0),
    coalesce((row_value->>'gps_eligible_visits')::int, 0),
    coalesce((row_value->>'gps_verified_visits')::int, 0),
    nullif(row_value->>'gps_share', '')::numeric,
    coalesce((row_value->>'daily_wins')::int, 0),
    coalesce(row_value->'evidence', '{}'::jsonb)
  from jsonb_array_elements(coalesce(p_candidates, '[]'::jsonb)) as row_value;

  select count(*) into v_rep_count from public.early_birds_candidates where snapshot_id = v_snapshot.id;
  select count(*) into v_candidate_count from public.early_birds_candidates
    where snapshot_id = v_snapshot.id and eligible;

  update public.early_birds_period_snapshots
    set rep_count = v_rep_count,
        candidate_count = v_candidate_count,
        status = case when v_candidate_count = 0 then 'exhausted' else 'open' end
    where id = v_snapshot.id
    returning * into v_snapshot;

  insert into public.early_birds_audit (snapshot_id, period_key, actor_hr_id, action, detail)
  values (v_snapshot.id, p_period_key, p_computed_by, 'period_closed',
          jsonb_build_object('rep_count', v_rep_count, 'candidate_count', v_candidate_count,
                             'trigger', p_trigger, 'replaced', v_existing.id is not null));

  return jsonb_build_object('created', true, 'snapshot_id', v_snapshot.id, 'status', v_snapshot.status,
                            'rep_count', v_rep_count, 'candidate_count', v_candidate_count);
end;
$$;

ALTER FUNCTION public.phx_close_early_birds_period(p_period_key text, p_period_start date, p_period_end date, p_manager_hr_id text, p_manager_hr_id_compact text, p_scoring_version smallint, p_weights jsonb, p_contested_days integer, p_trigger text, p_computed_by text, p_replace boolean, p_candidates jsonb) OWNER TO postgres;

--
-- Name: phx_closing_brick(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_brick(p_line text, p_period text) RETURNS TABLE(distributor_code text, region_code text, area_code text, brick_id text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with base as (
    select f.distributor_code, f.region_code, f.area_code, f.brick_id, f.product_code, f.total_qty, f.effective_units
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b
      on b.id = f.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
    where f.period = p_period
      and lower(btrim(f.official_line)) = lower(btrim(p_line))
      and not f.is_direct
      and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  ),
  period_price as (
    select d.product_code, public.phx_factory_price(d.product_code, p_period) as price
    from (select distinct base.product_code from base) d
  )
  select
    b.distributor_code,
    b.region_code,
    b.area_code,
    b.brick_id,
    sum(b.total_qty)                                     as units,
    sum(b.effective_units * coalesce(period_price.price, 0)) as value
  from base b
  left join period_price on period_price.product_code = b.product_code
  group by b.distributor_code, b.region_code, b.area_code, b.brick_id;
$$;

ALTER FUNCTION public.phx_closing_brick(p_line text, p_period text) OWNER TO postgres;

--
-- Name: phx_closing_channel_breakdown(text, text, text[], text[], text[], text[], text[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_channel_breakdown(p_line text, p_period text, p_store_stems text[], p_hospital_stems text[], p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text], p_pharmacy_override_codes text[] DEFAULT '{}'::text[], p_store_override_codes text[] DEFAULT '{}'::text[], p_rule jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'public', 'au'
    SET statement_timeout TO '60s'
    AS $$
  with
  period_price as (
    select d.product_code, public.phx_factory_price(d.product_code, p_period) as period_price
    from (
      select distinct f.product_code
      from public.source_of_sales_fact_rollup f
      where f.period = p_period
    ) d
  ),
  rule as (
    select case
             when p_rule is null or p_rule = '{}'::jsonb then jsonb_build_object(
               'hospitalStems', to_jsonb(coalesce(p_hospital_stems, '{}'::text[])),
               'storeStems', to_jsonb(coalesce(p_store_stems, '{}'::text[])),
               'pharmacyOverrideCodes', to_jsonb(coalesce(p_pharmacy_override_codes, '{}'::text[])),
               'storeOverrideKeys', to_jsonb(coalesce(p_store_override_codes, '{}'::text[]))
             )
             else p_rule
           end as payload
  ),
  names as (
    select r.distributor_code, r.client_code, r.client_name, r.folded_name
    from public.source_of_sales_channel_customer_rollup r
    where r.line_key = lower(btrim(p_line))
      and r.period = p_period
      and not r.is_direct
      and r.client_code is not null
  ),
  retail as (
    select
      upper(btrim(coalesce(f.product_code, ''))) as product_code,
      nullif(btrim(coalesce(f.product_name, '')), '') as product_name,
      nullif(btrim(coalesce(f.area_code, '')), '')    as area_code,
      nullif(btrim(coalesce(f.brick_id, '')), '')     as brick_id,
      f.client_code                                   as client_key,
      f.distributor_code                              as distributor_code,
      coalesce(n.client_name, '')                     as client_name,
      coalesce(n.folded_name, '')                     as folded_name,
      (f.client_code is null)                         as no_client_code,
      false                                           as is_direct,
      f.effective_units * coalesce(pp.period_price, 0) as value
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b
      on b.id = f.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
    left join period_price pp
      on pp.product_code = f.product_code
    left join names n
      on n.distributor_code = f.distributor_code
     and n.client_code = f.client_code
    where f.period = p_period
      and lower(btrim(f.official_line)) = lower(btrim(p_line))
      and not coalesce(f.is_direct, false)
      and upper(btrim(coalesce(f.product_code, ''))) <> all (
            select upper(btrim(x)) from unnest(coalesce(p_exclude_codes, '{}'::text[])) as x)
  ),
  direct as (
    select
      upper(btrim(coalesce(r.product_code, ''))) as product_code,
      nullif(btrim(coalesce(r.product_name, '')), '') as product_name,
      case when p_period <> '2026-07'
           then nullif(btrim(coalesce(r.area_code, '')), '') end as area_code,
      case when p_period <> '2026-07'
           then nullif(btrim(coalesce(r.brick_id, '')), '') end  as brick_id,
      null::text                                      as client_key,
      null::text                                      as distributor_code,
      btrim(coalesce(r.client_name, ''))              as client_name,
      public.phx_fold_customer_name(btrim(coalesce(r.client_name, ''))) as folded_name,
      false                                           as no_client_code,
      true                                            as is_direct,
      r.value                                         as value
    from public.source_of_sales_import_rows r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated'
    where r.invoice_period = p_period
      and lower(btrim(r.official_line)) = lower(btrim(p_line))
      and coalesce(r.is_direct, false)
      and r.validation_state = 'valid'
      and upper(btrim(coalesce(r.product_code, ''))) <> all (
            select upper(btrim(x)) from unnest(coalesce(p_exclude_codes, '{}'::text[])) as x)
  ),
  tagged as (
    select
      u.*,
      case
        when u.is_direct and btrim(u.client_name) = '' then 'direct_unnamed'
        when u.no_client_code then 'unidentified_no_code'
        when btrim(u.client_name) = '' then 'unidentified_no_name'
        else public.phx_customer_channel(
               u.client_name, u.client_key, u.distributor_code, p_period, p_line, rule.payload)
      end as channel
    from (select * from retail union all select * from direct) u
    cross join rule
  ),
  seated as (
    select
      t.*,
      s.seat_id,
      ca.area_name as seat_area_name,
      oh.occupant_hr_id
    from tagged t
    left join au.sos_area_crosswalk x
      on x.sos_area_code = t.area_code and x.effective_to is null
    left join au.sos_official_line_map lm
      on lower(btrim(lm.official_line)) = lower(btrim(p_line))
    left join au.seats s
      on s.area_code = x.canonical_area_code
     and s.line_code = lm.line_code
     and s.seat_tier = 'REP'
     and s.is_active
    left join au.occupancy_history oh
      on oh.seat_id = s.seat_id and oh.effective_to is null
    left join au.canonical_areas ca
      on ca.area_code = s.area_code
  ),
  keyed as (
    select 'product' as dimension,
           coalesce(nullif(sd.product_code, ''), '__NO_PRODUCT__') as key,
           coalesce(sd.product_name, '')                           as label,
           sd.channel, sd.value
    from seated sd
    union all
    select 'area',
           case when sd.area_code is not null then sd.area_code
                when sd.is_direct then '__DIRECT__'
                else '__NO_AREA__' end,
           '',
           sd.channel, sd.value
    from seated sd
    union all
    select 'brick',
           case when sd.brick_id is not null then sd.brick_id
                when sd.is_direct then '__DIRECT__'
                else '__NO_BRICK__' end,
           '',
           sd.channel, sd.value
    from seated sd
    union all
    select 'rep',
           case when sd.occupant_hr_id is not null then sd.occupant_hr_id::text
                when sd.seat_id is not null then '__VACANT__:' || sd.seat_id::text
                when sd.is_direct then '__DIRECT__'
                else '__NO_SEAT__' end,
           case when sd.occupant_hr_id is not null then coalesce(e.full_name, '')
                when sd.seat_id is not null then coalesce(sd.seat_area_name, '')
                else '' end,
           sd.channel, sd.value
    from seated sd
    left join public.employees e on e.hr_id = sd.occupant_hr_id
  ),
  grids as (
    select
      k.dimension,
      k.key,
      coalesce(max(nullif(k.label, '')), '')                                       as label,
      coalesce(sum(k.value) filter (where k.channel = 'hospital'), 0)              as hospital,
      coalesce(sum(k.value) filter (where k.channel = 'store'), 0)                 as store,
      coalesce(sum(k.value) filter (where k.channel = 'pharmacy'), 0)              as pharmacy,
      coalesce(sum(k.value) filter (where k.channel = 'unidentified_no_code'), 0)  as unidentified_no_code,
      coalesce(sum(k.value) filter (where k.channel = 'unidentified_no_name'), 0)  as unidentified_no_name,
      coalesce(sum(k.value) filter (where k.channel = 'direct_unnamed'), 0)        as direct_unnamed,
      coalesce(sum(k.value), 0)                                                    as total
    from keyed k
    group by k.dimension, k.key
  ),
  area_reps as (
    select distinct
      x.sos_area_code as area_code,
      case when oh.occupant_hr_id is not null then oh.occupant_hr_id::text
           when s.seat_id is not null then '__VACANT__:' || s.seat_id::text
           else '__NO_SEAT__' end as rep_key,
      case when oh.occupant_hr_id is not null then coalesce(e.full_name, '')
           when s.seat_id is not null then coalesce(ca.area_name, '')
           else '' end as rep_label
    from au.sos_area_crosswalk x
    left join au.sos_official_line_map lm
      on lower(btrim(lm.official_line)) = lower(btrim(p_line))
    left join au.seats s
      on s.area_code = x.canonical_area_code
     and s.line_code = lm.line_code
     and s.seat_tier = 'REP'
     and s.is_active
    left join au.occupancy_history oh
      on oh.seat_id = s.seat_id and oh.effective_to is null
    left join au.canonical_areas ca
      on ca.area_code = s.area_code
    left join public.employees e on e.hr_id = oh.occupant_hr_id
    where x.effective_to is null
      and x.sos_area_code is not null
  ),
  brick_area as (
    select
      case when sd.brick_id is null then '__NO_BRICK__' else sd.brick_id end as brick_key,
      coalesce(sd.area_code, '__NO_AREA__')                                  as area_key,
      sum(sd.value) filter (where sd.channel = 'store')                      as store
    from seated sd
    where not sd.is_direct
    group by 1, 2
    having coalesce(sum(sd.value) filter (where sd.channel = 'store'), 0) <> 0
  ),
  population as (
    select
      (
        select coalesce(sum(f.effective_units * coalesce(pp.period_price, 0)), 0)
        from public.source_of_sales_fact_rollup f
        join public.source_of_sales_import_batches b
          on b.id = f.batch_id and b.status = 'validated'
        left join public.source_of_sales_products p
          on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
        left join period_price pp
          on pp.product_code = f.product_code
        where f.period = p_period
          and lower(btrim(f.official_line)) = lower(btrim(p_line))
          and not coalesce(f.is_direct, false)
          and upper(btrim(coalesce(f.product_code, ''))) <> all (
                select upper(btrim(x)) from unnest(coalesce(p_exclude_codes, '{}'::text[])) as x)
      )
      +
      (
        select coalesce(sum(r.value), 0)
        from public.source_of_sales_import_rows r
        join public.source_of_sales_import_batches b
          on b.id = r.batch_id and b.status = 'validated'
        where r.invoice_period = p_period
          and lower(btrim(r.official_line)) = lower(btrim(p_line))
          and coalesce(r.is_direct, false)
          and r.validation_state = 'valid'
          and upper(btrim(coalesce(r.product_code, ''))) <> all (
                select upper(btrim(x)) from unnest(coalesce(p_exclude_codes, '{}'::text[])) as x)
      ) as value
  ),
  emitted as (
    select g.dimension, g.key, g.label,
           g.hospital, g.store, g.pharmacy,
           g.unidentified_no_code, g.unidentified_no_name, g.direct_unnamed,
           g.total,
           null::text as rep_key,
           null::text as area_key
    from grids g
    union all
    select 'area_rep', a.area_code, a.rep_label,
           0, 0, 0, 0, 0, 0, 0,
           a.rep_key, null::text
    from area_reps a
    union all
    select 'brick_area', ba.brick_key, '',
           0, ba.store, 0, 0, 0, 0,
           ba.store,
           null::text, ba.area_key
    from brick_area ba
    union all
    select 'population', 'TOTAL', '',
           0, 0, 0, 0, 0, 0, p.value,
           null::text, null::text
    from population p
  )
  select coalesce(jsonb_agg(row_to_json(e) order by e.dimension, e.total desc, e.key), '[]'::jsonb)
  from emitted e;
$$;

ALTER FUNCTION public.phx_closing_channel_breakdown(p_line text, p_period text, p_store_stems text[], p_hospital_stems text[], p_exclude_codes text[], p_pharmacy_override_codes text[], p_store_override_codes text[], p_rule jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phx_closing_channel_breakdown(p_line text, p_period text, p_store_stems text[], p_hospital_stems text[], p_exclude_codes text[], p_pharmacy_override_codes text[], p_store_override_codes text[], p_rule jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_closing_channel_breakdown(p_line text, p_period text, p_store_stems text[], p_hospital_stems text[], p_exclude_codes text[], p_pharmacy_override_codes text[], p_store_override_codes text[], p_rule jsonb) IS 'Monthly Closing channel breakdown grids. Classification is delegated to phx_customer_channel so these grids cannot drift from customer-channel.ts; the unidentified and direct buckets are decided here, above it.';

--
-- Name: phx_closing_channel_totals(text, text[], text[], text[], text[], text[], text[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_channel_totals(p_line text, p_periods text[], p_store_stems text[], p_hospital_stems text[], p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text], p_pharmacy_override_codes text[] DEFAULT '{}'::text[], p_store_override_codes text[] DEFAULT '{}'::text[], p_rule jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(period text, channel text, customers bigint, units numeric, value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_include_all boolean;
  v_rule jsonb;
begin
  if coalesce(cardinality(p_exclude_codes), 0) = 0 then
    v_include_all := true;
  elsif (
    select coalesce(array_agg(distinct upper(btrim(x)) order by upper(btrim(x))), '{}'::text[])
    from unnest(p_exclude_codes) as x
  ) = array['LA003', 'LA004', 'SS001']::text[] then
    v_include_all := false;
  else
    raise exception
      'phx_closing_channel_totals: p_exclude_codes must be empty or exactly {LA003,LA004,SS001}; got %', p_exclude_codes
      using errcode = '22023';
  end if;

  v_rule := case
              when p_rule is null or p_rule = '{}'::jsonb then jsonb_build_object(
                'hospitalStems', to_jsonb(coalesce(p_hospital_stems, '{}'::text[])),
                'storeStems', to_jsonb(coalesce(p_store_stems, '{}'::text[])),
                'pharmacyOverrideCodes', to_jsonb(coalesce(p_pharmacy_override_codes, '{}'::text[])),
                'storeOverrideKeys', to_jsonb(coalesce(p_store_override_codes, '{}'::text[]))
              )
              else p_rule
            end;

  return query
  with
  base as (
    select
      r.period,
      r.client_key,
      r.distributor_code,
      r.client_name,
      r.folded_name,
      r.no_client_code,
      r.is_direct,
      case when v_include_all then r.units_all else r.units_all - r.units_restricted end as units,
      case when v_include_all then r.value_all else r.value_all - r.value_restricted end as value,
      case when v_include_all then r.rows_all  else r.rows_all  - r.rows_restricted  end as rows_kept
    from public.source_of_sales_channel_customer_rollup r
    where r.line_key = lower(btrim(p_line))
      and r.period = any (p_periods)
  ),
  folded as (
    select b.* from base b where b.rows_kept > 0
  ),
  tagged as (
    select
      u.period,
      u.client_key,
      u.units,
      u.value,
      case
        when u.is_direct and btrim(u.client_name) = '' then 'direct_unnamed'
        when u.no_client_code then 'unidentified_no_code'
        when btrim(u.client_name) = '' then 'unidentified_no_name'
        else public.phx_customer_channel(
               u.client_name, u.client_key, u.distributor_code, u.period, p_line, v_rule)
      end as channel
    from folded u
  ),
  channels as (
    select
      t.period,
      t.channel,
      count(distinct t.client_key) as customers,
      sum(t.units)                 as units,
      sum(t.value)                 as value
    from tagged t
    group by t.period, t.channel
  ),
  population as (
    select b.period, sum(b.units) as units, sum(b.value) as value
    from base b
    group by b.period
  )
  select c.period, c.channel, c.customers, c.units, c.value from channels c
  union all
  select p.period, '__population__'::text, 0::bigint, p.units, p.value from population p;
end;
$$;

ALTER FUNCTION public.phx_closing_channel_totals(p_line text, p_periods text[], p_store_stems text[], p_hospital_stems text[], p_exclude_codes text[], p_pharmacy_override_codes text[], p_store_override_codes text[], p_rule jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phx_closing_channel_totals(p_line text, p_periods text[], p_store_stems text[], p_hospital_stems text[], p_exclude_codes text[], p_pharmacy_override_codes text[], p_store_override_codes text[], p_rule jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_closing_channel_totals(p_line text, p_periods text[], p_store_stems text[], p_hospital_stems text[], p_exclude_codes text[], p_pharmacy_override_codes text[], p_store_override_codes text[], p_rule jsonb) IS 'Monthly Closing channel totals per period. Classification is delegated to phx_customer_channel so this grid cannot drift from customer-channel.ts; the unidentified and direct buckets are decided here, above it.';

--
-- Name: phx_closing_corrections(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_corrections(p_period text) RETURNS TABLE(kind text, period text, other_period text, line text, distributor_code text, area_code text, product_code text, product_name text, client_name text, units numeric, value numeric, other_units numeric, other_value numeric, region_code text, other_net_units numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
with periods as (
  select p_period as cur,
         to_char((p_period || '-01')::date - interval '1 month', 'YYYY-MM') as prev,
         to_char((p_period || '-01')::date + interval '1 month', 'YYYY-MM') as next
),
-- Each product's price for each month, resolved ONCE. phx_factory_price is SECURITY DEFINER and
-- carries a SET, so Postgres cannot inline it and every row-level mention was a real call with two
-- correlated subqueries. The three sites below pass the row's own (product_code, period), the
-- function is STABLE, and this holds every pair any of them can ask for.
period_price as (
  select d.product_code, d.period,
         public.phx_factory_price(d.product_code, d.period) as period_price
  from (
    select distinct f.product_code, f.period
    from public.source_of_sales_fact_rollup f
    cross join periods pr
    where f.period in (pr.prev, pr.cur, pr.next)
  ) d
),
-- Per-distributor cells. Used by reversal_pair ONLY, where the distributor is the point: the
-- pattern is one distributor posting in one month and retracting in the next. A Direct row with no
-- area is keyed by its region, as the closing books it (see closing_cells).
cells as (
  select f.period as cell_period, f.official_line as cell_line, b.distributor_code as cell_dist,
         f.area_code as cell_area, f.product_code as cell_product,
         case when f.is_direct and btrim(coalesce(f.area_code, '')) = ''
              then upper(btrim(coalesce(f.region_code, ''))) end as cell_region,
         max(f.product_name) as cell_product_name,
         sum(f.total_qty) as cell_units,
         sum(case when f.is_direct then f.direct_value
                  else f.effective_units * coalesce(pp.period_price, 0) end) as cell_value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b on b.id = f.batch_id and b.status = 'validated'
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  left join period_price pp
    on pp.product_code = f.product_code and pp.period = f.period
  cross join periods pr
  where f.period in (pr.prev, pr.cur, pr.next)
    and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  group by f.period, f.official_line, b.distributor_code, f.area_code,
           case when f.is_direct and btrim(coalesce(f.area_code, '')) = ''
                then upper(btrim(coalesce(f.region_code, ''))) end,
           f.product_code
),
-- One pharmacy's own net in a per-distributor cell, per month. Its buys and returns inside the SAME
-- month net here first: a line posted twice and taken back leaves the month's own total right and
-- undoes nothing in the month before. Client codes are unique per distributor only, which the
-- distributor key already respects. A blank client code is no identity, so it never matches (the
-- same rule late_return applies).
clients as (
  select f.period as cl_period, f.official_line as cl_line, b.distributor_code as cl_dist,
         f.area_code as cl_area, f.product_code as cl_product,
         case when f.is_direct and btrim(coalesce(f.area_code, '')) = ''
              then upper(btrim(coalesce(f.region_code, ''))) end as cl_region,
         btrim(f.client_code) as cl_client,
         sum(f.total_qty) as cl_units,
         sum(case when f.is_direct then f.direct_value
                  else f.effective_units * coalesce(pp.period_price, 0) end) as cl_value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b on b.id = f.batch_id and b.status = 'validated'
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  left join period_price pp
    on pp.product_code = f.product_code and pp.period = f.period
  cross join periods pr
  where f.period in (pr.prev, pr.cur, pr.next)
    and nullif(btrim(f.client_code), '') is not null
    and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  group by f.period, f.official_line, b.distributor_code, f.area_code,
           case when f.is_direct and btrim(coalesce(f.area_code, '')) = ''
                then upper(btrim(coalesce(f.region_code, ''))) end,
           f.product_code, btrim(f.client_code)
),
-- What a cell's month TOOK BACK from the month before: each pharmacy that nets negative this month,
-- matched to its OWN purchase in the same cell the month before, capped at what it bought then.
-- Ordinary sales to other pharmacies that month cannot hide it. The value is the return's own
-- value, prorated when the cap cuts it.
taken_back as (
  select ret.cl_period as tb_period, ret.cl_line as tb_line, ret.cl_dist as tb_dist,
         ret.cl_area as tb_area, ret.cl_region as tb_region, ret.cl_product as tb_product,
         sum(least(-ret.cl_units, buy.cl_units)) as tb_units,
         sum(ret.cl_value * least(-ret.cl_units, buy.cl_units) / (-ret.cl_units)) as tb_value
  from clients ret
  join clients buy
    on buy.cl_line = ret.cl_line
   and buy.cl_dist = ret.cl_dist
   and buy.cl_area = ret.cl_area
   and buy.cl_region is not distinct from ret.cl_region
   and buy.cl_product = ret.cl_product
   and buy.cl_client = ret.cl_client
   and buy.cl_period = to_char((ret.cl_period || '-01')::date - interval '1 month', 'YYYY-MM')
  where ret.cl_units < 0
    and buy.cl_units > 0
  group by ret.cl_period, ret.cl_line, ret.cl_dist, ret.cl_area, ret.cl_region, ret.cl_product
),
-- THE CLOSING'S OWN CELL: area x product, every distributor together, exactly as
-- phx_monthly_closing_matrix groups it. This is what "the closing shows a negative there" means.
--
-- A direct row with NO AREA is the one exception, because the closing does not put it in an area
-- cell at all: phx_monthly_closing_direct returns it by REGION, and injectDirectIntoMatrix gives each
-- region its own "Direct" row. So such a row is keyed by its region here too (cell_region). Every
-- other row, a direct row that carries an area included, keeps cell_region NULL and groups by area
-- exactly as before, because the closing folds that direct money into the area's own row.
closing_cells as (
  select f.period as cell_period, f.official_line as cell_line,
         f.area_code as cell_area, f.product_code as cell_product,
         case when f.is_direct and btrim(coalesce(f.area_code, '')) = ''
              then upper(btrim(coalesce(f.region_code, ''))) end as cell_region,
         max(f.product_name) as cell_product_name,
         sum(f.total_qty) as cell_units,
         sum(case when f.is_direct then f.direct_value
                  else f.effective_units * coalesce(pp.period_price, 0) end) as cell_value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b on b.id = f.batch_id and b.status = 'validated'
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  left join period_price pp
    on pp.product_code = f.product_code and pp.period = f.period
  cross join periods pr
  where f.period = pr.cur
    and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  group by f.period, f.official_line, f.area_code,
           case when f.is_direct and btrim(coalesce(f.area_code, '')) = ''
                then upper(btrim(coalesce(f.region_code, ''))) end,
           f.product_code
)
-- A pair is found two ways, with the same thresholds: the next month's whole cell nets below zero
-- (the original test, kept so nothing it found is lost), OR the same pharmacies took back that much
-- (taken_back), however much else the cell sold that month. When the pharmacies' take-back
-- qualifies, it is what the row reports, because the cell's net understates it by exactly the other
-- sales. other_net_units is always the next month's whole-cell net for this distributor, so the
-- page can say how much of the take-back that month's own figures show.
select 'reversal_pair'::text, pos.cell_period, neg.cell_period, pos.cell_line, pos.cell_dist,
       pos.cell_area, pos.cell_product, pos.cell_product_name, null::text,
       pos.cell_units, round(pos.cell_value::numeric, 2),
       case when h.clients_hit then -tb.tb_units else neg.cell_units end,
       round((case when h.clients_hit then tb.tb_value else neg.cell_value end)::numeric, 2),
       pos.cell_region,
       neg.cell_units
from cells pos
join cells neg
  on neg.cell_line = pos.cell_line
 and neg.cell_dist = pos.cell_dist
 and neg.cell_area = pos.cell_area
 and neg.cell_region is not distinct from pos.cell_region
 and neg.cell_product = pos.cell_product
 and neg.cell_period = to_char((pos.cell_period || '-01')::date + interval '1 month', 'YYYY-MM')
left join taken_back tb
  on tb.tb_line = neg.cell_line
 and tb.tb_dist = neg.cell_dist
 and tb.tb_area = neg.cell_area
 and tb.tb_region is not distinct from neg.cell_region
 and tb.tb_product = neg.cell_product
 and tb.tb_period = neg.cell_period
cross join lateral (
  select coalesce(tb.tb_units, 0) between 0.5 * pos.cell_units and 1.5 * pos.cell_units as clients_hit
) h
cross join periods pr
where pos.cell_units >= 50
  and ((neg.cell_units < 0
        and abs(neg.cell_units) between 0.5 * pos.cell_units and 1.5 * pos.cell_units)
       or h.clients_hit)
  and (pos.cell_period = pr.cur or neg.cell_period = pr.cur)

union all
-- distributor_code is NULL here on purpose: this row is the whole cell, not one distributor's
-- share of it, and naming any single distributor would be the bug this replaced.
select 'net_negative'::text, c.cell_period, null, c.cell_line, null::text, c.cell_area,
       c.cell_product, c.cell_product_name, null,
       c.cell_units, round(c.cell_value::numeric, 2), null, null, c.cell_region, null::numeric
from closing_cells c
where c.cell_units < -20 or c.cell_value < -1000

union all
select 'late_return'::text, neg.neg_period, origin.origin_period, neg.neg_line, neg.neg_dist,
       neg.neg_area, neg.neg_product, neg.neg_product_name, neg.neg_client_name,
       neg.neg_units, round(neg.neg_value::numeric, 2), origin.origin_units, null, null::text, null::numeric
from (
  select b.period as neg_period, r.official_line as neg_line, b.distributor_code as neg_dist,
         r.area_code as neg_area, r.product_code as neg_product,
         max(r.product_name) as neg_product_name,
         btrim(r.client_code) as neg_client_code,
         max(r.client_name) as neg_client_name,
         sum(r.qty) as neg_units, sum(r.value) as neg_value
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
  cross join periods pr
  where b.period = pr.cur
    and nullif(btrim(r.client_code), '') is not null
    and upper(btrim(coalesce(r.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  group by b.period, r.official_line, b.distributor_code, r.area_code, r.product_code, btrim(r.client_code)
  having sum(r.qty) <= -10 or sum(r.value) <= -1000
) neg
left join lateral (
  select b2.period as origin_period, sum(r2.qty) as origin_units
  from public.source_of_sales_import_rows r2
  join public.source_of_sales_import_batches b2 on b2.id = r2.batch_id and b2.status = 'validated'
  where b2.period < neg.neg_period
    and b2.distributor_code = neg.neg_dist
    and btrim(r2.client_code) = neg.neg_client_code
    and upper(btrim(r2.product_code)) = upper(btrim(neg.neg_product))
    and r2.qty > 0
  group by b2.period
  order by b2.period desc
  limit 1
) origin on true;
$$;

ALTER FUNCTION public.phx_closing_corrections(p_period text) OWNER TO postgres;

--
-- Name: phx_closing_customers(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_customers(p_line text, p_period text) RETURNS TABLE(client_code text, client_name text, distributor_code text, region_code text, area_code text, brick_id text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with price as (
    select c.code,
           coalesce(
             (select h.factory_price from public.source_of_sales_product_price_history h
               where upper(btrim(h.product_code)) = c.code and h.effective_period <= p_period
               order by h.effective_period desc limit 1),
             (select pr.factory_price from public.source_of_sales_products pr
               where upper(btrim(pr.product_code)) = c.code limit 1)
           ) as factory_price
    from (
      select upper(btrim(pm.product_code)) as code from public.source_of_sales_products pm
      union
      select upper(btrim(ph.product_code)) as code from public.source_of_sales_product_price_history ph
    ) c
  ),
  agg as (
    select f.client_code, f.distributor_code,
           nullif(f.region_code,'') as fact_region, nullif(f.area_code,'') as fact_area,
           nullif(f.brick_id,'') as fact_brick,
           sum(f.total_qty) as units,
           sum(case when coalesce(f.is_direct,false) then coalesce(f.direct_value,0)
                    else f.effective_units * coalesce(pp.factory_price,0) end) as value
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b on b.id=f.batch_id and b.status='validated'
    left join price pp on pp.code = upper(btrim(f.product_code))
    where f.period = p_period
      and lower(btrim(f.official_line)) = lower(btrim(p_line))
      and f.client_code is not null
      and upper(btrim(coalesce(f.product_code,''))) not in ('LA003','LA004','SS001')
    group by f.client_code, f.distributor_code, nullif(f.region_code,''), nullif(f.area_code,''), nullif(f.brick_id,'')
  )
  select a.client_code, coalesce(cm.customer_name,'') as client_name, a.distributor_code,
         coalesce(a.fact_region, cm.region_code) as region_code,
         coalesce(a.fact_area, cm.area_code) as area_code,
         coalesce(a.fact_brick, cm.brick_id) as brick_id,
         a.units, a.value
  from agg a
  left join public.source_of_sales_customer_map cm
    on cm.distributor_code=a.distributor_code and cm.customer_code=a.client_code and cm.active;
$$;

ALTER FUNCTION public.phx_closing_customers(p_line text, p_period text) OWNER TO postgres;

--
-- Name: FUNCTION phx_closing_customers(p_line text, p_period text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_closing_customers(p_line text, p_period text) IS 'Closing detail by customer for one line and period. Resolves the factory price once per product (30 rows) rather than once per fact row - the per-row form measured 1,374 ms against 140 ms on 2026-08. Price arithmetic is identical to public.phx_factory_price.';

--
-- Name: phx_closing_customers_for_pairs(text, text[], jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_customers_for_pairs(p_line text, p_periods text[], p_pairs jsonb) RETURNS TABLE(period text, client_code text, client_name text, distributor_code text, region_code text, area_code text, brick_id text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $_$
  with wanted as (
    select distinct
      upper(btrim(x.distributor_code)) as distributor_code,
      btrim(x.client_code) as client_code,
      nullif(btrim(coalesce(x.brick_id, '')), '') as brick_id
    from jsonb_to_recordset(coalesce(p_pairs, '[]'::jsonb)) as x(distributor_code text, client_code text, brick_id text)
    where coalesce(btrim(x.distributor_code), '') <> ''
      and coalesce(btrim(x.client_code), '') <> ''
  ),
  months as (
    select distinct btrim(m) as period
    from unnest(coalesce(p_periods, array[]::text[])) as m
    where btrim(m) ~ '^[0-9]{4}-[0-9]{2}$'
  )
  select
    m.period,
    c.client_code,
    c.client_name,
    c.distributor_code,
    c.region_code,
    c.area_code,
    c.brick_id,
    c.units,
    c.value
  from months m
  cross join lateral public.phx_closing_customers(p_line, m.period) c
  where exists (
    select 1
    from wanted w
    where w.distributor_code = upper(btrim(c.distributor_code))
      and w.client_code = btrim(c.client_code)
      and (w.brick_id is null or w.brick_id = c.brick_id)
  );
$_$;

ALTER FUNCTION public.phx_closing_customers_for_pairs(p_line text, p_periods text[], p_pairs jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phx_closing_customers_for_pairs(p_line text, p_periods text[], p_pairs jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_closing_customers_for_pairs(p_line text, p_periods text[], p_pairs jsonb) IS 'Customer 360: the Monthly Closing''s own customer rows (phx_closing_customers, unchanged) for each month in p_periods, narrowed to the distributor code pairs in p_pairs ([{distributor_code, client_code, brick_id?}]; brick_id, when given, must match too — for a distributor whose code is not proof of a shop). Pass the line as the closing names it (''anti infective'', never ''anti_infective''). See supabase/migrations/20261018230827_customer_360_validated_relationships.sql.';

--
-- Name: phx_closing_distributor_product(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_distributor_product(p_line text, p_period text) RETURNS TABLE(distributor_code text, region_code text, area_code text, product_code text, product_name text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with base as (
    select r.distributor_code, r.region_code, r.area_code, r.product_code, r.product_name, r.units_qty, r.eff_units
    from public.source_of_sales_distributor_product_rollup r
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
    where r.period = p_period
      and r.line_key = lower(btrim(p_line))
  ),
  period_price as (
    select d.product_code, public.phx_factory_price(d.product_code, p_period) as price
    from (select distinct base.product_code from base) d
  )
  select
    b.distributor_code,
    b.region_code,
    b.area_code,
    b.product_code,
    max(b.product_name)                                  as product_name,
    sum(b.units_qty)                                     as units,
    sum(b.eff_units * coalesce(period_price.price, 0))   as value
  from base b
  left join period_price on period_price.product_code = b.product_code
  group by b.distributor_code, b.region_code, b.area_code, b.product_code;
$$;

ALTER FUNCTION public.phx_closing_distributor_product(p_line text, p_period text) OWNER TO postgres;

--
-- Name: phx_closing_drift_fingerprint(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_drift_fingerprint(p_line text, p_period text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.phx_closing_drift_fingerprint_of(public.phx_closing_drift_rows(p_line, p_period));
$$;

ALTER FUNCTION public.phx_closing_drift_fingerprint(p_line text, p_period text) OWNER TO postgres;

--
-- Name: phx_closing_drift_fingerprint_of(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_drift_fingerprint_of(p_rows jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select md5(coalesce(string_agg(
           d.area_code || '|' || d.product_code || '|' || d.is_direct::text
             || '|' || round(d.units_delta, 6)::text
             || '|' || coalesce(round(d.value_delta, 2)::text, 'null'),
           E'\n' order by d.area_code, d.product_code, d.is_direct), ''))
  from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb))
       as d(area_code text, product_code text, is_direct boolean,
            units_delta numeric, value_delta numeric);
$$;

ALTER FUNCTION public.phx_closing_drift_fingerprint_of(p_rows jsonb) OWNER TO postgres;

--
-- Name: phx_closing_drift_overview(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_closing_drift_overview(p_line text, p_period text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rows        jsonb   := public.phx_closing_drift_rows(p_line, p_period);
  v_fingerprint text    := public.phx_closing_drift_fingerprint_of(v_rows);
  v_cells       integer;
  v_units       numeric;
  v_value       numeric;
  v_ack         public.monthly_closing_drift_acknowledgements;
begin
  select count(*)::integer, coalesce(sum(d.units_delta), 0), sum(d.value_delta)
    into v_cells, v_units, v_value
  from jsonb_to_recordset(v_rows) as d(units_delta numeric, value_delta numeric);

  -- An acknowledgement counts only while it is the SAME drift: matched on the fingerprint, never on
  -- the line and period alone. That match is the blindfold this module exists to avoid.
  select * into v_ack
  from public.monthly_closing_drift_acknowledgements a
  where lower(btrim(a.line)) = lower(btrim(p_line))
    and a.period = p_period
    and a.drift_fingerprint = v_fingerprint
  order by a.acknowledged_at desc
  limit 1;

  return jsonb_build_object(
    'line', p_line,
    'period', p_period,
    'status', jsonb_build_object(
      'drifted_cells',   v_cells,
      'net_units_delta', v_units,
      'net_value_delta', v_value,
      'acknowledged',    v_ack.id is not null,
      'acknowledged_by', v_ack.acknowledged_by,
      'acknowledged_at', v_ack.acknowledged_at,
      'reason',          v_ack.reason,
      'verdict', case
        when v_cells = 0 then 'clean'
        when v_ack.id is not null then 'acknowledged'
        when exists (select 1 from public.monthly_closing_drift_acknowledgements a2
                      where lower(btrim(a2.line)) = lower(btrim(p_line)) and a2.period = p_period)
          then 'CHANGED SINCE IT WAS ACKNOWLEDGED'
        else 'unreviewed'
      end
    ),
    'cells', v_rows
  );
end;
$$;

ALTER FUNCTION public.phx_closing_drift_overview(p_line text, p_period text) OWNER TO postgres;

