CREATE FUNCTION public.phx_closing_drift_status(p_line text, p_period text) RETURNS TABLE(line text, period text, drifted_cells integer, net_units_delta numeric, net_value_delta numeric, acknowledged boolean, acknowledged_by text, acknowledged_at timestamp with time zone, reason text, verdict text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_status jsonb := public.phx_closing_drift_overview(p_line, p_period) -> 'status';
begin
  return query select
    p_line,
    p_period,
    (v_status->>'drifted_cells')::integer,
    (v_status->>'net_units_delta')::numeric,
    (v_status->>'net_value_delta')::numeric,
    (v_status->>'acknowledged')::boolean,
    v_status->>'acknowledged_by',
    (v_status->>'acknowledged_at')::timestamp with time zone,
    v_status->>'reason',
    v_status->>'verdict';
end;
$$;

