-- Name: phx_coaching_zone(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_coaching_zone(p_percent numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case
    when p_percent < 50 then 'critical_red'
    when p_percent <= 65 then 'red_zone'
    when p_percent <= 80 then 'yellow_zone'
    when p_percent <= 90 then 'green_zone'
    else 'excellence_zone'
  end;
$$;

