-- Name: phx_contract_note(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_contract_note(p_existing text, p_actor text, p_action text, p_note text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select concat_ws(
    E'\n',
    nullif(p_existing, ''),
    '[' || now()::text || '] ' || coalesce(nullif(p_actor, ''), 'system') || ': ' || p_action ||
      case when nullif(p_note, '') is null then '' else ' - ' || p_note end
  );
$$;

ALTER FUNCTION public.phx_contract_note(p_existing text, p_actor text, p_action text, p_note text) OWNER TO postgres;

--
-- Name: phx_create_contract_renewal_request(text, text, text, text, text, text, date, date, date, date, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_create_contract_renewal_request(p_employee_hr_id text, p_current_contract_id text, p_employee_name text, p_job_title text, p_line_name text, p_area_name text, p_current_renewal_date date, p_requested_renewal_date date, p_proposed_start_date date, p_proposed_end_date date, p_new_contract_document_url text, p_new_contract_document_name text, p_actor text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_active_contract_count integer := 0;
  v_employee record;
  v_request contract_renewal_requests%rowtype;
  v_start date := coalesce(p_proposed_start_date, p_requested_renewal_date);
  v_end date;
begin
  v_end := coalesce(p_proposed_end_date, (v_start + interval '1 year')::date);

  select hr_id, hire_date, employment_status
  into v_employee
  from public.employees
  where upper(hr_id) = upper(trim(p_employee_hr_id))
  for update;

  if not found then
    raise exception 'Employee was not found in the directory.';
  end if;

  if lower(coalesce(v_employee.employment_status, 'active')) not in ('active', 'on_leave') then
    raise exception 'Contract renewals can only be created for active employees.';
  end if;

  if p_requested_renewal_date is null then
    raise exception 'Requested renewal date is required.';
  end if;

  if v_employee.hire_date is not null and p_requested_renewal_date < v_employee.hire_date then
    raise exception 'Renewal date cannot be before the employee hire date.';
  end if;

  if v_employee.hire_date is not null and v_start < v_employee.hire_date then
    raise exception 'Proposed start date cannot be before the employee hire date.';
  end if;

  if p_current_renewal_date is not null and v_start < p_current_renewal_date then
    raise exception 'Proposed start date cannot be before the current renewal date.';
  end if;

  if v_end < v_start then
    raise exception 'Proposed end date cannot be before the proposed start date.';
  end if;

  select count(*)
  into v_active_contract_count
  from public.employee_contracts
  where upper(coalesce(employee_hr_id, hr_id, '')) = upper(v_employee.hr_id)
    and lower(coalesce(status, 'active')) = 'active';

  if v_active_contract_count > 1 then
    raise exception 'Employee has multiple active contracts. Resolve duplicate active contracts before renewal.';
  end if;

  if exists (
    select 1
    from public.contract_renewal_requests
    where upper(employee_hr_id) = upper(v_employee.hr_id)
      and status in ('requested', 'manager_review', 'hr_review')
  ) then
    raise exception 'An active renewal request already exists for this employee.';
  end if;

  insert into public.contract_renewal_requests (
    area_name,
    created_by,
    current_contract_id,
    current_renewal_date,
    employee_hr_id,
    employee_name,
    job_title,
    line_name,
    new_contract_document_name,
    new_contract_document_url,
    proposed_end_date,
    proposed_start_date,
    requested_renewal_date,
    status,
    workflow_notes
  )
  values (
    p_area_name,
    p_actor,
    p_current_contract_id,
    p_current_renewal_date,
    v_employee.hr_id,
    coalesce(p_employee_name, ''),
    p_job_title,
    p_line_name,
    nullif(trim(coalesce(p_new_contract_document_name, '')), ''),
    nullif(trim(coalesce(p_new_contract_document_url, '')), ''),
    v_end,
    v_start,
    p_requested_renewal_date,
    'requested',
    public.phx_contract_note(null, p_actor, 'created renewal request', p_note)
  )
  returning * into v_request;

  insert into public.contract_renewal_history (
    action,
    actor,
    details,
    employee_hr_id,
    new_renewal_date,
    old_renewal_date,
    request_id
  )
  values (
    'requested',
    p_actor,
    jsonb_build_object('note', p_note),
    v_request.employee_hr_id,
    v_request.requested_renewal_date,
    v_request.current_renewal_date,
    v_request.id
  );

  return to_jsonb(v_request);
end;
$$;

ALTER FUNCTION public.phx_create_contract_renewal_request(p_employee_hr_id text, p_current_contract_id text, p_employee_name text, p_job_title text, p_line_name text, p_area_name text, p_current_renewal_date date, p_requested_renewal_date date, p_proposed_start_date date, p_proposed_end_date date, p_new_contract_document_url text, p_new_contract_document_name text, p_actor text, p_note text) OWNER TO postgres;

--
-- Name: direct_order_pharmacy_code_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.direct_order_pharmacy_code_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.direct_order_pharmacy_code_seq OWNER TO postgres;

--
-- Name: direct_order_pharmacies; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.direct_order_pharmacies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    phoenix_pharmacy_code text DEFAULT ('DOP-'::text || lpad((nextval('public.direct_order_pharmacy_code_seq'::regclass))::text, 6, '0'::text)) NOT NULL,
    pharmacy_name text NOT NULL,
    brick_id text,
    area_code text,
    region_code text,
    doctor_name text,
    pharmacy_address text,
    distributor_code text,
    distributor_customer_code text,
    created_by_hr_id text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    geo_variance_resolved boolean DEFAULT false NOT NULL,
    geo_variance_resolution text,
    geo_variance_resolved_by text,
    geo_variance_resolved_at timestamp with time zone,
    verification_status text DEFAULT 'verified'::text NOT NULL,
    entry_source text DEFAULT 'catalogue'::text NOT NULL,
    verified_by_hr_id text,
    verified_at timestamp with time zone,
    trust_state text DEFAULT 'trusted'::text NOT NULL,
    probation_started_at timestamp with time zone,
    trusted_at timestamp with time zone,
    trusted_reason text,
    phantom_reported_at timestamp with time zone,
    hold_release_ground text,
    hold_release_reason text,
    hold_release_decided_by_hr_id text,
    hold_release_decided_at timestamp with time zone,
    merged_into_pharmacy_id uuid,
    merged_at timestamp with time zone,
    merged_by_hr_id text,
    contested_code_claims jsonb DEFAULT '[]'::jsonb NOT NULL,
    venue_type text DEFAULT 'pharmacy'::text NOT NULL,
    crm_contact_id bigint,
    crm_contact_linked_by_hr_id text,
    crm_contact_linked_at timestamp with time zone,
    CONSTRAINT direct_order_pharmacies_contested_claims_is_array CHECK ((jsonb_typeof(contested_code_claims) = 'array'::text)),
    CONSTRAINT direct_order_pharmacies_crm_contact_id_positive CHECK (((crm_contact_id IS NULL) OR (crm_contact_id > 0))),
    CONSTRAINT direct_order_pharmacies_entry_source_check CHECK ((entry_source = ANY (ARRAY['catalogue'::text, 'manual'::text, 'marketing_transfer'::text]))),
    CONSTRAINT direct_order_pharmacies_geo_variance_resolution_check CHECK ((geo_variance_resolution = ANY (ARRAY['kept'::text, 'applied'::text]))),
    CONSTRAINT direct_order_pharmacies_hold_release_ground_check CHECK (((hold_release_ground IS NULL) OR (hold_release_ground = ANY (ARRAY['admin_released'::text, 'kept_held'::text])))),
    CONSTRAINT direct_order_pharmacies_merged_not_self_check CHECK (((merged_into_pharmacy_id IS NULL) OR (merged_into_pharmacy_id <> id))),
    CONSTRAINT direct_order_pharmacies_rejected_is_inactive CHECK (((verification_status <> 'rejected'::text) OR (active = false))),
    CONSTRAINT direct_order_pharmacies_trust_state_check CHECK ((trust_state = ANY (ARRAY['trusted'::text, 'provisional'::text, 'phantom_suspected'::text]))),
    CONSTRAINT direct_order_pharmacies_venue_type_check CHECK ((venue_type = ANY (ARRAY['pharmacy'::text, 'nursery'::text]))),
    CONSTRAINT direct_order_pharmacies_verification_status_check CHECK ((verification_status = ANY (ARRAY['verified'::text, 'pending_review'::text, 'rejected'::text])))
);

ALTER TABLE public.direct_order_pharmacies OWNER TO postgres;

--
-- Name: COLUMN direct_order_pharmacies.distributor_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.distributor_code IS 'DEAD COLUMN - never read, and empty on every row. The live distributor link for a direct-order pharmacy is public.direct_order_pharmacy_distributor_codes (distributor_code, customer_code). Joining Source of Sales through this column returns zero rows with no error, which reads as "not linked" when the pharmacy is linked through the child table.';

--
-- Name: COLUMN direct_order_pharmacies.distributor_customer_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.distributor_customer_code IS 'DEAD COLUMN - never read, and empty on every row. The live customer code for a direct-order pharmacy is public.direct_order_pharmacy_distributor_codes.customer_code, paired with distributor_code in the same child row. Joining Source of Sales through this column returns zero rows with no error, which reads as "not linked" when the pharmacy is linked through the child table.';

--
-- Name: COLUMN direct_order_pharmacies.trust_state; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.trust_state IS 'trusted = came from the distributor sheets, or a footprint confirmed it. provisional = admitted by Super Admin validation, still owes a footprint. phantom_suspected = probation expired with no distributor sales and no payment (spec A3).';

--
-- Name: COLUMN direct_order_pharmacies.hold_release_ground; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.hold_release_ground IS 'A System Admin''s explicit ruling on a pharmacy whose distributor code proves nothing. admin_released = its held orders join the approval chain; kept_held = somebody looked and they stay. NULL means nobody has ruled, which is NOT the same as either answer and must never be collapsed into one.';

--
-- Name: COLUMN direct_order_pharmacies.merged_into_pharmacy_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.merged_into_pharmacy_id IS 'The surviving pharmacy this duplicate record was folded into. Its requests were moved there and this row deactivated. Identity is proven by a shared distributor customer code — never by a similar name.';

--
-- Name: COLUMN direct_order_pharmacies.contested_code_claims; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.contested_code_claims IS 'Distributor codes this pharmacy CLAIMED but does not own, because another pharmacy already holds them. Written only when the submitter was shown the incumbent and answered that theirs is a different pharmacy. Each element: {distributorCode, customerCode, heldByPharmacyId, heldByPharmacyCode, heldByPharmacyName, claimedAt}. An empty array is the normal case. This is evidence for the reviewer, never an attribution — the incumbent keeps the code until a human rules otherwise.';

--
-- Name: COLUMN direct_order_pharmacies.venue_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.venue_type IS 'pharmacy (default) or nursery. Mirrors marketing_pharmacies.venue_type so a nursery transferred from Marketing keeps its identity in Direct Orders.';

--
-- Name: COLUMN direct_order_pharmacies.crm_contact_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.crm_contact_id IS 'The CRM contact (ireports360 contact_crm_id) this venue IS, as declared by the person who registered it. Feeds rule 1 of contact-trade.ts, which beats every name/area inference. NULL is the normal case and blocks nothing. No foreign key on purpose: ireports360_contacts is a per-agent list, not a registry.';

--
-- Name: COLUMN direct_order_pharmacies.crm_contact_linked_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.crm_contact_linked_by_hr_id IS 'HR id of the person who declared crm_contact_id, written once at registration.';

--
-- Name: COLUMN direct_order_pharmacies.crm_contact_linked_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacies.crm_contact_linked_at IS 'When crm_contact_id was declared, written once at registration.';

--
-- Name: phx_create_direct_order_pharmacy(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_create_direct_order_pharmacy(p_pharmacy jsonb, p_codes jsonb DEFAULT '[]'::jsonb) RETURNS public.direct_order_pharmacies
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_row public.direct_order_pharmacies;
  v_crm_contact_id bigint;
begin
  begin
    v_crm_contact_id := nullif(btrim(coalesce(p_pharmacy->>'crm_contact_id', '')), '')::bigint;
  exception
    when others then v_crm_contact_id := null;
  end;
  if v_crm_contact_id is not null and v_crm_contact_id <= 0 then
    v_crm_contact_id := null;
  end if;

  insert into public.direct_order_pharmacies (
    pharmacy_name,
    brick_id,
    area_code,
    region_code,
    doctor_name,
    pharmacy_address,
    created_by_hr_id,
    verification_status,
    entry_source,
    contested_code_claims,
    venue_type,
    crm_contact_id,
    crm_contact_linked_by_hr_id,
    crm_contact_linked_at
  )
  values (
    nullif(btrim(coalesce(p_pharmacy->>'pharmacy_name', '')), ''),
    nullif(btrim(coalesce(p_pharmacy->>'brick_id', '')), ''),
    nullif(btrim(coalesce(p_pharmacy->>'area_code', '')), ''),
    nullif(btrim(coalesce(p_pharmacy->>'region_code', '')), ''),
    nullif(btrim(coalesce(p_pharmacy->>'doctor_name', '')), ''),
    nullif(btrim(coalesce(p_pharmacy->>'pharmacy_address', '')), ''),
    nullif(btrim(coalesce(p_pharmacy->>'created_by_hr_id', '')), ''),
    'pending_review',
    'manual',
    case
      when jsonb_typeof(p_pharmacy->'contested_code_claims') = 'array'
        then p_pharmacy->'contested_code_claims'
      else '[]'::jsonb
    end,
    case
      when lower(btrim(coalesce(p_pharmacy->>'venue_type', ''))) = 'nursery' then 'nursery'
      else 'pharmacy'
    end,
    v_crm_contact_id,
    case when v_crm_contact_id is null then null
         else nullif(btrim(coalesce(p_pharmacy->>'created_by_hr_id', '')), '') end,
    case when v_crm_contact_id is null then null else now() end
  )
  returning * into v_row;

  if jsonb_array_length(coalesce(p_codes, '[]'::jsonb)) > 0 then
    insert into public.direct_order_pharmacy_distributor_codes (
      pharmacy_id,
      distributor_code,
      customer_code,
      mapped_brick_id,
      mapped_area_code,
      mapped_region_code
    )
    select
      v_row.id,
      c.value->>'distributor_code',
      c.value->>'customer_code',
      nullif(btrim(coalesce(c.value->>'mapped_brick_id', '')), ''),
      nullif(btrim(coalesce(c.value->>'mapped_area_code', '')), ''),
      nullif(btrim(coalesce(c.value->>'mapped_region_code', '')), '')
    from jsonb_array_elements(coalesce(p_codes, '[]'::jsonb)) as c(value);
  end if;

  return v_row;
end;
$$;

ALTER FUNCTION public.phx_create_direct_order_pharmacy(p_pharmacy jsonb, p_codes jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phx_create_direct_order_pharmacy(p_pharmacy jsonb, p_codes jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_create_direct_order_pharmacy(p_pharmacy jsonb, p_codes jsonb) IS 'Creates a direct-order pharmacy and its distributor code rows in ONE transaction. Exists because the two inserts used to be separate client calls: the pharmacy committed, the codes hit the unique index, and the caller was told the whole thing failed while a codeless duplicate stayed behind (staging DOP-000014, 2026-08-13). Raises on conflict and leaves nothing.';

--
-- Name: phx_create_retention_conversation(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_create_retention_conversation(p_conversation jsonb, p_themes jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_allowed constant text[] := array[
    'kind',
    'employee_hr_id',
    'employee_name',
    'job_title',
    'conducted_on',
    'conducted_by',
    'resignation_id',
    'retention_risk',
    'is_regrettable',
    'would_rejoin',
    'summary',
    'follow_up_action',
    'follow_up_due',
    'created_by'
  ];
  v_unknown text;
  v_id uuid;
begin
  if p_conversation is null or jsonb_typeof(p_conversation) <> 'object' then
    raise exception 'A retention conversation must be an object.' using errcode = '22023';
  end if;

  select key into v_unknown
  from jsonb_object_keys(p_conversation) as key
  where key <> all (v_allowed)
  limit 1;
  if v_unknown is not null then
    raise exception 'A new retention conversation cannot set "%".', v_unknown using errcode = '22023';
  end if;

  insert into public.hr_retention_conversations (
    kind,
    employee_hr_id,
    employee_name,
    job_title,
    conducted_on,
    conducted_by,
    resignation_id,
    retention_risk,
    is_regrettable,
    would_rejoin,
    summary,
    follow_up_action,
    follow_up_due,
    created_by
  )
  select
    r.kind,
    r.employee_hr_id,
    r.employee_name,
    r.job_title,
    r.conducted_on,
    r.conducted_by,
    r.resignation_id,
    r.retention_risk,
    r.is_regrettable,
    r.would_rejoin,
    r.summary,
    r.follow_up_action,
    r.follow_up_due,
    r.created_by
  from jsonb_populate_record(null::public.hr_retention_conversations, p_conversation) as r
  returning id into v_id;

  -- Same transaction: a theme that fails (a duplicate, a bad sentiment) rolls the conversation
  -- back with it, so a retry never finds a half-written one to duplicate.
  perform public.phx_replace_retention_conversation_themes(v_id, coalesce(p_themes, '[]'::jsonb));

  return v_id;
end;
$$;

ALTER FUNCTION public.phx_create_retention_conversation(p_conversation jsonb, p_themes jsonb) OWNER TO postgres;

--
-- Name: phx_create_salary_batch(integer, integer, text, text, jsonb, jsonb, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_create_salary_batch(p_month integer, p_year integer, p_file_name text, p_uploaded_by text, p_records jsonb, p_flags jsonb, p_created_at timestamp with time zone, p_file_content_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_records jsonb := coalesce(p_records, '[]'::jsonb);
  v_flags jsonb := coalesce(p_flags, '[]'::jsonb);
begin
  if p_month < 1 or p_month > 12 then
    raise exception 'Payroll month must be between 1 and 12.' using errcode = '22023';
  end if;

  if p_year < 2000 or p_year > 2100 then
    raise exception 'Payroll year must be between 2000 and 2100.' using errcode = '22023';
  end if;

  if jsonb_typeof(v_records) <> 'array' then
    raise exception 'Payroll upload records must be a JSON array.' using errcode = '22023';
  end if;

  if jsonb_typeof(v_flags) <> 'array' then
    raise exception 'Payroll upload flags must be a JSON array.' using errcode = '22023';
  end if;

  if jsonb_array_length(v_records) = 0 then
    raise exception 'Payroll upload records must include at least one salary record.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(v_records) as record(value)
    where jsonb_typeof(record.value) <> 'object'
  ) then
    raise exception 'Payroll upload records must contain JSON objects.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(v_flags) as flag(value)
    where jsonb_typeof(flag.value) <> 'object'
  ) then
    raise exception 'Payroll upload flags must contain JSON objects.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_records) as r(hr_id text)
    where nullif(trim(coalesce(r.hr_id, '')), '') is null
  ) then
    raise exception 'Payroll upload records must include HR IDs.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_records) as r(payment_mode text)
    where coalesce(r.payment_mode, 'two_parts') not in ('one_part', 'two_parts')
  ) then
    raise exception 'Payroll upload payment_mode must be one_part or two_parts.' using errcode = '22023';
  end if;

  begin
    insert into public.salary_batches (
      file_name,
      month,
      year,
      status,
      uploaded_by,
      created_at,
      updated_at,
      file_content_hash
    )
    values (
      p_file_name,
      p_month,
      p_year,
      'uploaded',
      p_uploaded_by,
      p_created_at,
      p_created_at,
      p_file_content_hash
    )
    returning *
    into v_batch;
  exception
    when unique_violation then
      if sqlerrm ilike '%salary_batches_period_hash_uniq%' then
        raise exception 'This exact file has already been uploaded for payroll period %/%.', p_month, p_year using errcode = '23505';
      else
        raise exception 'Payroll period %/% already has a batch.', p_month, p_year using errcode = '23505';
      end if;
  end;

  insert into public.salary_records (
    area,
    base_salary,
    batch_id,
    bonus,
    crm,
    employment_income_tax,
    expenses,
    extra_cost_of_living,
    finger_print,
    first_part,
    fuel_allowance,
    full_name,
    governmental_deductions,
    gross_salary,
    hire_date,
    hr_id,
    incentive,
    job_title,
    line,
    loans,
    medical_insurance,
    month_salary,
    name_ar,
    net_salary,
    other_additions,
    other_deductions,
    overtime,
    comment,
    payment_mode,
    second_part,
    social_insurance,
    total_additions,
    total_deductions,
    unpaid_vacations,
    working_days,
    calendar_days
  )
  select
    r.area,
    coalesce(r.base_salary, 0),
    v_batch.id,
    r.bonus,
    r.crm,
    r.employment_income_tax,
    r.expenses,
    r.extra_cost_of_living,
    r.finger_print,
    r.first_part,
    r.fuel_allowance,
    r.full_name,
    r.governmental_deductions,
    r.gross_salary,
    r.hire_date,
    r.hr_id,
    r.incentive,
    r.job_title,
    r.line,
    r.loans,
    r.medical_insurance,
    r.month_salary,
    r.name_ar,
    r.net_salary,
    r.other_additions,
    r.other_deductions,
    r.overtime,
    r.comment,
    coalesce(r.payment_mode, 'two_parts'),
    r.second_part,
    r.social_insurance,
    r.total_additions,
    r.total_deductions,
    r.unpaid_vacations,
    r.working_days,
    r.calendar_days
  from jsonb_to_recordset(v_records) as r(
    area text,
    base_salary numeric,
    bonus numeric,
    crm numeric,
    employment_income_tax numeric,
    expenses numeric,
    extra_cost_of_living numeric,
    finger_print numeric,
    first_part numeric,
    fuel_allowance numeric,
    full_name text,
    governmental_deductions numeric,
    gross_salary numeric,
    hire_date date,
    hr_id text,
    incentive numeric,
    job_title text,
    line text,
    loans numeric,
    medical_insurance numeric,
    month_salary numeric,
    name_ar text,
    net_salary numeric,
    other_additions numeric,
    other_deductions numeric,
    overtime numeric,
    comment text,
    payment_mode text,
    second_part numeric,
    social_insurance numeric,
    total_additions numeric,
    total_deductions numeric,
    unpaid_vacations numeric,
    working_days integer,
    calendar_days integer
  );

  insert into public.salary_flags (
    batch_id,
    flag_type,
    hr_id,
    message,
    severity
  )
  select
    v_batch.id,
    f.flag_type,
    f.hr_id,
    f.message,
    coalesce(f.severity, 'warning')
  from jsonb_to_recordset(v_flags) as f(
    flag_type text,
    hr_id text,
    message text,
    severity text
  );

  return to_jsonb(v_batch);
end;
$$;

ALTER FUNCTION public.phx_create_salary_batch(p_month integer, p_year integer, p_file_name text, p_uploaded_by text, p_records jsonb, p_flags jsonb, p_created_at timestamp with time zone, p_file_content_hash text) OWNER TO postgres;

--
-- Name: phx_crm_agent_crm_ids_by_hr(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_crm_agent_crm_ids_by_hr(p_hr_ids text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_array(t.agent_hr_id, t.agent_crm_id) order by t.agent_hr_id), '[]'::jsonb)
  from (
    select u.agent_hr_id, max(u.agent_crm_id) as agent_crm_id
    from (
      select v.agent_hr_id, max(v.agent_crm_id) as agent_crm_id
      from public.ireports360_visits v
      where v.agent_hr_id = any(p_hr_ids) and v.agent_crm_id is not null
      group by v.agent_hr_id
      union all
      select p.agent_hr_id, max(p.agent_crm_id) as agent_crm_id
      from public.ireports360_plan_entries p
      where p.agent_hr_id = any(p_hr_ids) and p.agent_crm_id is not null
      group by p.agent_hr_id
    ) u
    group by u.agent_hr_id
  ) t;
$$;

ALTER FUNCTION public.phx_crm_agent_crm_ids_by_hr(p_hr_ids text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_crm_agent_crm_ids_by_hr(p_hr_ids text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_crm_agent_crm_ids_by_hr(p_hr_ids text[]) IS 'The highest CRM agent id per HR id across ireports360_visits and ireports360_plan_entries, as one jsonb array of [hr_id, agent_crm_id]. Read by loadCrmContactSyncTargets (src/lib/crm/contacts-sync.ts). See supabase/migrations/20261025233000_crm_plan_entries_agent_hr_id_index.sql.';

--
-- Name: phx_crm_agent_crm_ids_for_hr_ids(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_crm_agent_crm_ids_for_hr_ids(p_agent_hr_ids text[]) RETURNS TABLE(agent_crm_id bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
  select distinct c.agent_crm_id
  from public.crm_agent_crm_ids_cache c
  where c.agent_hr_id = any(p_agent_hr_ids)
$$;

ALTER FUNCTION public.phx_crm_agent_crm_ids_for_hr_ids(p_agent_hr_ids text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_crm_agent_crm_ids_for_hr_ids(p_agent_hr_ids text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_crm_agent_crm_ids_for_hr_ids(p_agent_hr_ids text[]) IS 'Distinct crm_visits_unified.agent_crm_id values for the given resolved agent_hr_ids, read from crm_agent_crm_ids_cache (rebuilt every 15 minutes). Backs the live departed-agent CRM exclusion in src/lib/crm/reads.ts. Raw scan: applies no exclusion of its own. Does NOT fall back to the live computation - an empty cache must surface, not hide.';

--
-- Name: phx_crm_brick_meta(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_crm_brick_meta(p_brick_ids text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_array(b.brick_id, b.brick_name, b.area_code, a.area_name, r.region_name)
      order by b.brick_id
    ),
    '[]'::jsonb
  )
  from public.source_of_sales_bricks b
  left join public.source_of_sales_areas a on a.area_code = b.area_code
  left join public.source_of_sales_regions r
    on r.region_code = coalesce(nullif(btrim(a.region_code), ''), nullif(btrim(b.region_code), ''))
  where b.brick_id = any (coalesce(p_brick_ids, '{}'::text[]))
    and b.active is distinct from false;
$$;

ALTER FUNCTION public.phx_crm_brick_meta(p_brick_ids text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_crm_brick_meta(p_brick_ids text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_crm_brick_meta(p_brick_ids text[]) IS 'The named bricks that are not retired, as one jsonb array of [brick_id, brick_name, area_code, area_name, region_name] - the region from the area''s region code, else the brick''s own. Read by loadBrickMeta (src/lib/crm/reps-list.ts). See supabase/migrations/20261102010000_phx_crm_board_reads_in_one_statement.sql.';

--
-- Name: phx_crm_contact_checkins(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_crm_contact_checkins(p_contact_ids bigint[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_array(c.contact_crm_id, c.agent_crm_id, c.agent_hr_id, c.lat, c.lon, c.address, c.check_date)
      order by c.check_date desc, c.crm_checkin_id desc
    ),
    '[]'::jsonb
  )
  from public.crm_checkins_unified c
  where c.source = 'ireports360'
    and c.contact_crm_id = any (coalesce(p_contact_ids, '{}'::bigint[]))
    and c.lat is not null
    and c.lon is not null;
$$;

ALTER FUNCTION public.phx_crm_contact_checkins(p_contact_ids bigint[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_crm_contact_checkins(p_contact_ids bigint[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_crm_contact_checkins(p_contact_ids bigint[]) IS 'The iReports360 check-ins with a pin of the named contacts, newest first, as one jsonb array of [contact_crm_id, agent_crm_id, agent_hr_id, lat, lon, address, check_date]. Read by loadCheckins (src/lib/crm/reps-list.ts). See supabase/migrations/20261102010000_phx_crm_board_reads_in_one_statement.sql.';

--
-- Name: phx_crm_contact_plan_dates(bigint[], date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_crm_contact_plan_dates(p_contact_crm_ids bigint[], p_from date) RETURNS TABLE(contact_crm_id bigint, plan_dates date[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.contact_crm_id,
    array_agg(p.plan_date order by p.plan_date desc)
  from public.crm_plan_entries_unified p
  where p.source = 'ireports360'
    and p.contact_crm_id = any (p_contact_crm_ids)
    and p.plan_date is not null
    and p.plan_date >= p_from
  group by p.contact_crm_id
  order by p.contact_crm_id;
$$;

ALTER FUNCTION public.phx_crm_contact_plan_dates(p_contact_crm_ids bigint[], p_from date) OWNER TO postgres;

--
-- Name: FUNCTION phx_crm_contact_plan_dates(p_contact_crm_ids bigint[], p_from date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_crm_contact_plan_dates(p_contact_crm_ids bigint[], p_from date) IS 'Per iReports360 contact: every iReports360 reference plan day on or after p_from (crm_plan_entries_unified, source ''ireports360''), newest first, duplicates kept. Read by loadPlanDatesFor (src/lib/crm/shared-customers.ts). See supabase/migrations/20261016180202_crm_contact_history_and_plan_dates_counted_in_sql.sql.';

--
-- Name: phx_crm_contact_roster(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_crm_contact_roster() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_array(a.id, a.contact_crm_id, a.agent_crm_id, a.agent_hr_id, c.name, c.phone, c.speciality, c.crm_region_name)
      order by a.id
    ),
    '[]'::jsonb
  )
  from public.crm_contact_assignments a
  left join public.crm_contacts c on c.contact_crm_id = a.contact_crm_id
  where a.effective_to is null;
$$;

ALTER FUNCTION public.phx_crm_contact_roster() OWNER TO postgres;

--
-- Name: FUNCTION phx_crm_contact_roster(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_crm_contact_roster() IS 'Every open crm_contact_assignments row with its crm_contacts name, phone, speciality and CRM region, as one jsonb array of [id, contact_crm_id, agent_crm_id, agent_hr_id, name, phone, speciality, crm_region_name], ordered by id. Read by loadContactRoster (src/lib/crm/reps-list.ts). See supabase/migrations/20261025231000_crm_contact_roster_read_in_one_statement.sql.';

--
-- Name: phx_crm_contact_visit_history(bigint[], date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_crm_contact_visit_history(p_contact_crm_ids bigint[], p_days_since date DEFAULT NULL::date) RETURNS TABLE(contact_crm_id bigint, visits integer, last_visited_on date, days date[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    v.contact_crm_id,
    count(*)::integer,
    max(v.visit_date),
    case
      when p_days_since is null then null
      else array_agg(v.visit_date order by v.visit_date desc) filter (where v.visit_date >= p_days_since)
    end
  from public.crm_visits_unified v
  where v.source = 'ireports360'
    and v.contact_crm_id = any (p_contact_crm_ids)
    -- An old visit already copied into Phoenix is counted there, never here as well (20261029212200).
    and not exists (
      select 1 from public.phoenix_crm_imported_visit_sources s where s.crm_visit_id = v.crm_visit_id
    )
  group by v.contact_crm_id
  order by v.contact_crm_id;
$$;

ALTER FUNCTION public.phx_crm_contact_visit_history(p_contact_crm_ids bigint[], p_days_since date) OWNER TO postgres;

--
-- Name: FUNCTION phx_crm_contact_visit_history(p_contact_crm_ids bigint[], p_days_since date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_crm_contact_visit_history(p_contact_crm_ids bigint[], p_days_since date) IS 'Per iReports360 contact: how many iReports360 visits the read door holds (crm_visits_unified, source ''ireports360''), the last one''s day, and — when p_days_since is given — the visit days on or after it, newest first. Read by readContactVisitHistory (src/lib/crm/reads.ts). See supabase/migrations/20261016180202_crm_contact_history_and_plan_dates_counted_in_sql.sql.';

--
-- Name: phx_crm_contact_visit_months(bigint[], date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_crm_contact_visit_months(p_contact_crm_ids bigint[], p_from date) RETURNS TABLE(contact_crm_id bigint, months jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with grouped as (
    select
      v.contact_crm_id,
      to_char(v.visit_date, 'YYYY-MM') as month,
      v.agent_hr_id,
      max(v.agent_name) as agent_name,
      v.ampm,
      v.source,
      v.speciality,
      v.visit_type,
      count(*)::integer as visits,
      max(v.visit_date) as last_visited_on
    from public.crm_visits_unified v
    where v.contact_crm_id = any (p_contact_crm_ids)
      and v.contact_crm_id <> 100000
      and v.visit_date >= p_from
    group by v.contact_crm_id, to_char(v.visit_date, 'YYYY-MM'), v.agent_hr_id, v.ampm, v.source, v.speciality, v.visit_type
  )
  select
    g.contact_crm_id,
    jsonb_agg(
      jsonb_build_object(
        'month', g.month,
        'agent_hr_id', g.agent_hr_id,
        'agent_name', g.agent_name,
        'ampm', g.ampm,
        'source', g.source,
        'speciality', g.speciality,
        'visit_type', g.visit_type,
        'visits', g.visits,
        'last_visited_on', g.last_visited_on
      )
      order by g.month, g.agent_hr_id
    )
  from grouped g
  group by g.contact_crm_id
  order by g.contact_crm_id;
$$;

ALTER FUNCTION public.phx_crm_contact_visit_months(p_contact_crm_ids bigint[], p_from date) OWNER TO postgres;

