--
-- Name: phx_custody_item_values_valid(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_custody_item_values_valid(v jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  select
    v is null
    or (
      jsonb_typeof(v) = 'object'
      and coalesce(
        (
          select bool_and(
            key ~ '^[1-9][0-9]?$'
            and jsonb_typeof(value) = 'number'
            and (value)::numeric >= 0
          )
          from jsonb_each(v)
        ),
        true
      )
    );
$_$;

ALTER FUNCTION public.phx_custody_item_values_valid(v jsonb) OWNER TO postgres;

