-- Name: FUNCTION phx_custody_item_values_valid(v jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_custody_item_values_valid(v jsonb) IS 'True when a custody item-value map is an object keyed by template item number with non-negative numeric amounts. Used by device_assignments_item_values_shape.';

--
-- Name: phx_customer_channel(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_customer_channel(p_client_name text, p_client_code text, p_distributor_code text, p_period text, p_official_line text, p_rule jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_spaced   text := public.phx_fold_customer_name(p_client_name);
  -- phx_squash_customer_name is this very expression around a second fold of the same name.
  v_squashed text := replace(v_spaced, ' ', '');
  v_code     text := ltrim(btrim(coalesce(p_client_code, '')), '0');
  v_dist     text := upper(btrim(coalesce(p_distributor_code, '')));
  v_line     text := regexp_replace(lower(btrim(coalesce(p_official_line, ''))), '[\s_-]+', ' ', 'g');
  v_from     text;
  v_active   boolean;
begin
  -- Hospital wins the name overlap: a name like "جمعيه ... (ص مستشفى)" carries both, and it is the
  -- hospital that identifies the customer.
  if exists (
    select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'hospitalStems', '[]'::jsonb)) s
    where s <> '' and v_spaced like '%' || s || '%'
  ) then
    return 'hospital';
  end if;

  -- Owner PHARMACY rulings by code outrank every store test. Keyed by customer code alone: the same
  -- shop is a pharmacy whichever distributor sold to it.
  if exists (
    select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'pharmacyOverrideCodes', '[]'::jsonb)) c
    where v_code = ltrim(btrim(c), '0')
  ) then
    return 'pharmacy';
  end if;

  -- Owner STORE rulings, keyed by distributor + code because a code is unique only inside one
  -- distributor's catalogue.
  if exists (
    select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'storeOverrideKeys', '[]'::jsonb)) k
    where v_dist = upper(btrim(split_part(k, '|', 1)))
      and v_code = ltrim(btrim(split_part(k, '|', 2)), '0')
  ) then
    return 'store';
  end if;

  -- Is the 2026-09-06 rule in force for this row's period AND line? The lines were published on
  -- different days and a published month never moves, so the cutover is per line. No payload, or a
  -- period before the cutover, falls to the rule exactly as it stood before: the six words plus the
  -- two code-keyed lists, both already answered above.
  v_from := coalesce(
    p_rule -> 'ruleFromPeriodByLine' ->> v_line,
    p_rule ->> 'ruleFromPeriodDefault'
  );
  v_active := v_from is not null
          and coalesce(p_period, '') ~ '^\d{4}-\d{2}$'
          and p_period >= v_from;

  if v_active then
    -- A ruling about one COMPANY, by name — it trades under several codes across distributors.
    if exists (
      select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'storeOverrideNameStems', '[]'::jsonb)) s
      where s <> '' and (v_spaced like '%' || s || '%' or v_squashed like '%' || replace(s, ' ', '') || '%')
    ) then
      return 'store';
    end if;

    -- A ruling about one company or a whole CHAIN that it is a pharmacy. Over-matching here is safe
    -- and is why a name is usable: this list can only ever refuse a store, never create one.
    if exists (
      select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'pharmacyOverrideNameStems', '[]'::jsonb)) s
      where s <> '' and (v_spaced like '%' || s || '%' or v_squashed like '%' || replace(s, ' ', '') || '%')
    ) then
      return 'pharmacy';
    end if;

    -- "Never a store": a pharmacy, a hospital, a paperwork note typed into the name field, or a
    -- government depot, which supplies its own institutions rather than a city's pharmacies.
    if exists (
      select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'neverStoreStems', '[]'::jsonb)) s
      where s <> '' and (v_spaced like '%' || s || '%' or v_squashed like '%' || replace(s, ' ', '') || '%')
    ) then
      return 'pharmacy';
    end if;

    -- A distributor whose entire customer base is wholesalers. The name test exists to guess at a
    -- customer nobody has classified; here there is nothing to guess.
    if v_dist <> '' and exists (
      select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'wholesaleOnlyDistributors', '[]'::jsonb)) d
      where v_dist = upper(btrim(d))
    ) then
      return 'store';
    end if;

    -- The six words, the start-anchored prefixes, and the trade phrase.
    if exists (
      select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'storeStems', '[]'::jsonb)) s
      where s <> '' and v_spaced like '%' || s || '%'
    ) then
      return 'store';
    end if;

    if exists (
      select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'storePrefixes', '[]'::jsonb)) s
      where s <> '' and v_spaced like s || '%'
    ) then
      return 'store';
    end if;

    -- The phrase: the name has to say its BUSINESS is trading or distributing, and then either name
    -- the goods or carry both halves of تجارة + توزيع. تجارة on its own is right 47% of the time.
    if exists (
      select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'tradeBusinessStems', '[]'::jsonb)) s
      where s <> '' and v_squashed like '%' || s || '%'
    ) and (
      (
        jsonb_array_length(coalesce(p_rule -> 'tradeBusinessPair', '[]'::jsonb)) > 0
        and not exists (
          select 1 from jsonb_array_elements_text(p_rule -> 'tradeBusinessPair') s
          where s = '' or v_squashed not like '%' || s || '%'
        )
      )
      or exists (
        select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'tradeGoodsStems', '[]'::jsonb)) s
        where s <> '' and v_squashed like '%' || s || '%'
      )
    ) then
      return 'store';
    end if;

    return 'pharmacy';
  end if;

  -- Pre-cutover, or no payload: the six words and nothing else.
  if exists (
    select 1 from jsonb_array_elements_text(coalesce(p_rule -> 'storeStems', '[]'::jsonb)) s
    where s <> '' and v_spaced like '%' || s || '%'
  ) then
    return 'store';
  end if;

  return 'pharmacy';
end;
$_$;

ALTER FUNCTION public.phx_customer_channel(p_client_name text, p_client_code text, p_distributor_code text, p_period text, p_official_line text, p_rule jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phx_customer_channel(p_client_name text, p_client_code text, p_distributor_code text, p_period text, p_official_line text, p_rule jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_customer_channel(p_client_name text, p_client_code text, p_distributor_code text, p_period text, p_official_line text, p_rule jsonb) IS 'THE channel rule in SQL, in one place. Payload is built by customerChannelSqlRule() in src/lib/sales/customer-channel-sql-rule.ts from the exported lists in customer-channel.ts, which stays the single edit point. An empty payload answers with the six store stems alone, which is what every caller sent before 2026-09-07.';

--
-- Name: phx_customer_directory(text[], text[], text[], text[], text, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_customer_directory(p_region_codes text[] DEFAULT NULL::text[], p_area_codes text[] DEFAULT NULL::text[], p_brick_codes text[] DEFAULT NULL::text[], p_distributor_codes text[] DEFAULT NULL::text[], p_from_period text DEFAULT NULL::text, p_to_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]) RETURNS TABLE(client_code text, client_name text, client_address text, distributor_code text, brick_id text, area_code text, region_code text, total_units numeric, total_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    SET work_mem TO '128MB'
    SET enable_nestloop TO 'off'
    AS $$
  with period_price as (
    select d.product_code || '|' || d.period as pair,
           public.phx_factory_price(d.product_code, d.period) as period_price
    from (
      select distinct c.product_code, c.period
      from public.source_of_sales_customer_directory_rollup c
      where (p_from_period is null or c.period >= p_from_period)
        and (p_to_period is null or c.period <= p_to_period)
    ) d
  ),
  filtered as materialized (
    select
      c.client_code,
      c.client_name,
      c.client_address,
      c.distributor_code,
      c.brick_id,
      c.area_code,
      c.region_code,
      c.latest_row_created_at,
      c.total_qty,
      c.effective_units * coalesce(pp.period_price, 0) as line_value
    from public.source_of_sales_customer_directory_rollup c
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = c.product_code
    left join period_price pp
      on pp.pair = c.product_code || '|' || c.period
    where (p_distributor_codes is null or cardinality(p_distributor_codes) = 0 or c.distributor_code = any(p_distributor_codes))
      and (p_region_codes is null or cardinality(p_region_codes) = 0 or c.region_code = any(p_region_codes))
      and (p_area_codes is null or cardinality(p_area_codes) = 0 or c.area_code = any(p_area_codes))
      and (p_brick_codes is null or cardinality(p_brick_codes) = 0 or c.brick_id = any(p_brick_codes))
      and (p_from_period is null or c.period >= p_from_period)
      and (p_to_period is null or c.period <= p_to_period)
      and upper(btrim(coalesce(c.product_code, ''))) <> all (array(
        select upper(btrim(x)) from unnest(coalesce(p_exclude_codes, '{}'::text[])) as x
      ))
  ),
  latest as (
    select distinct on (client_code, distributor_code)
      client_code,
      distributor_code,
      client_name,
      client_address,
      brick_id,
      area_code,
      region_code
    from filtered
    order by client_code, distributor_code, latest_row_created_at desc
  ),
  agg as (
    select
      client_code,
      distributor_code,
      sum(total_qty) as total_units,
      sum(line_value) as total_value
    from filtered
    group by client_code, distributor_code
  )
  select
    a.client_code,
    l.client_name,
    coalesce(
      nullif(btrim(l.client_address), ''),
      nullif(btrim(m.address), ''),
      ''
    ) as client_address,
    a.distributor_code,
    l.brick_id,
    l.area_code,
    l.region_code,
    a.total_units,
    a.total_value
  from agg a
  join latest l using (client_code, distributor_code)
  left join public.source_of_sales_customer_map m
    on m.distributor_code = a.distributor_code
   and m.customer_code = a.client_code
   and m.active;
$$;

ALTER FUNCTION public.phx_customer_directory(p_region_codes text[], p_area_codes text[], p_brick_codes text[], p_distributor_codes text[], p_from_period text, p_to_period text, p_exclude_codes text[]) OWNER TO postgres;

--
-- Name: phx_customer_directory_json(text[], text[], text[], text[], text, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_customer_directory_json(p_region_codes text[] DEFAULT NULL::text[], p_area_codes text[] DEFAULT NULL::text[], p_brick_codes text[] DEFAULT NULL::text[], p_distributor_codes text[] DEFAULT NULL::text[], p_from_period text DEFAULT NULL::text, p_to_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(row)), '[]'::jsonb)
  from (
    select *
    from public.phx_customer_directory(
      p_region_codes,
      p_area_codes,
      p_brick_codes,
      p_distributor_codes,
      p_from_period,
      p_to_period,
      p_exclude_codes
    )
  ) row;
$$;

ALTER FUNCTION public.phx_customer_directory_json(p_region_codes text[], p_area_codes text[], p_brick_codes text[], p_distributor_codes text[], p_from_period text, p_to_period text, p_exclude_codes text[]) OWNER TO postgres;

--
-- Name: phx_customer_sales(text, text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_customer_sales(p_distributor_code text, p_client_code text, p_from_period text DEFAULT NULL::text, p_to_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]) RETURNS TABLE(invoice_period text, product_code text, product_name text, official_line text, brick_id text, area_code text, region_code text, client_name text, client_address text, qty numeric, line_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with base as (
    select
      r.invoice_period, r.product_code, r.product_name, r.official_line, r.brick_id,
      r.area_code, r.region_code, r.client_name, r.client_address, r.qty
    from public.source_of_sales_import_rows r
    join public.source_of_sales_import_batches b on b.id = r.batch_id
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
    where b.status = 'validated'
      and r.distributor_code = p_distributor_code
      and r.client_code = p_client_code
      and (p_from_period is null or r.invoice_period >= p_from_period)
      and (p_to_period is null or r.invoice_period <= p_to_period)
      and upper(btrim(coalesce(r.product_code, ''))) <> all (
        select upper(btrim(x)) from unnest(coalesce(p_exclude_codes, '{}'::text[])) as x
      )
  ),
  period_price as (
    select d.product_code, d.invoice_period,
           public.phx_factory_price(d.product_code, d.invoice_period) as period_price
    from (select distinct base.product_code, base.invoice_period from base) d
  )
  select
    b.invoice_period, b.product_code, b.product_name, b.official_line, b.brick_id,
    b.area_code, b.region_code, b.client_name, b.client_address, b.qty,
    b.qty * coalesce(pp.period_price, 0) as line_value
  from base b
  left join period_price pp
    on pp.product_code is not distinct from b.product_code
   and pp.invoice_period is not distinct from b.invoice_period
  order by b.invoice_period, b.product_name;
$$;

ALTER FUNCTION public.phx_customer_sales(p_distributor_code text, p_client_code text, p_from_period text, p_to_period text, p_exclude_codes text[]) OWNER TO postgres;

--
-- Name: phx_decide_early_birds_candidate(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_decide_early_birds_candidate(p_snapshot_id uuid, p_candidate_id uuid, p_decision text, p_reason text, p_decided_by text, p_actor_role text, p_announcement jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_snapshot public.early_birds_period_snapshots;
  v_candidate public.early_birds_candidates;
  v_current_id uuid;
  v_decision_id uuid;
  v_winner_id uuid;
  v_remaining int := 0;
  v_next_status text;
begin
  select * into v_snapshot from public.early_birds_period_snapshots
    where id = p_snapshot_id for update;
  if not found then
    raise exception 'Early Birds snapshot % not found', p_snapshot_id using errcode = 'P0002';
  end if;
  if v_snapshot.status <> 'open' then
    return jsonb_build_object('error', 'snapshot_not_open', 'status', v_snapshot.status);
  end if;

  select c.id into v_current_id
  from public.early_birds_candidates c
  left join public.early_birds_decisions d on d.candidate_id = c.id
  where c.snapshot_id = p_snapshot_id and c.eligible and c.candidate_rank is not null and d.id is null
  order by c.candidate_rank asc
  limit 1;

  if v_current_id is null then
    return jsonb_build_object('error', 'no_candidate');
  end if;
  if v_current_id is distinct from p_candidate_id then
    return jsonb_build_object('error', 'stale_candidate', 'current_candidate_id', v_current_id);
  end if;

  select * into v_candidate from public.early_birds_candidates where id = p_candidate_id;

  insert into public.early_birds_decisions (
    snapshot_id, candidate_id, period_key, manager_hr_id, candidate_rank,
    decision_status, decision_reason, decided_by, actor_role_at_decision
  ) values (
    p_snapshot_id, p_candidate_id, v_snapshot.period_key, v_snapshot.manager_hr_id,
    v_candidate.candidate_rank, p_decision, coalesce(p_reason, ''), p_decided_by, p_actor_role
  )
  returning id into v_decision_id;

  if p_decision = 'approved' then
    insert into public.early_birds_winners (
      snapshot_id, decision_id, candidate_id, period_key, period_start, period_end,
      manager_hr_id, manager_hr_id_compact, employee_hr_id, employee_hr_id_compact,
      employee_name, area_name, region_name, line_name, hire_date, has_photo,
      rank_at_approval, total_score, component_scores, headline_stats, timeline,
      confirmation_source, confirmed_by
    ) values (
      p_snapshot_id, v_decision_id, p_candidate_id, v_snapshot.period_key,
      v_snapshot.period_start, v_snapshot.period_end,
      v_snapshot.manager_hr_id, v_snapshot.manager_hr_id_compact,
      v_candidate.employee_hr_id, v_candidate.employee_hr_id_compact,
      coalesce(p_announcement->>'employee_name', v_candidate.employee_name, v_candidate.employee_hr_id),
      p_announcement->>'area_name', p_announcement->>'region_name', p_announcement->>'line_name',
      nullif(p_announcement->>'hire_date', '')::date,
      coalesce((p_announcement->>'has_photo')::boolean, false),
      v_candidate.candidate_rank, v_candidate.total_score,
      v_candidate.component_scores,
      coalesce(p_announcement->'headline_stats', '{}'::jsonb),
      coalesce(p_announcement->'timeline', '[]'::jsonb),
      coalesce(p_announcement->>'confirmation_source', 'manager'),
      case when coalesce(p_announcement->>'confirmation_source', 'manager') = 'auto' then null else p_decided_by end
    )
    returning id into v_winner_id;

    v_next_status := 'decided';
  else
    select count(*) into v_remaining
    from public.early_birds_candidates c
    left join public.early_birds_decisions d on d.candidate_id = c.id
    where c.snapshot_id = p_snapshot_id and c.eligible and c.candidate_rank is not null and d.id is null;

    v_next_status := case when v_remaining > 0 then 'open' else 'exhausted' end;
  end if;

  update public.early_birds_period_snapshots set status = v_next_status where id = p_snapshot_id;

  insert into public.early_birds_audit (snapshot_id, candidate_id, period_key, actor_hr_id, action, detail)
  values (p_snapshot_id, p_candidate_id, v_snapshot.period_key, p_decided_by,
          'candidate_' || p_decision,
          jsonb_build_object('reason', coalesce(p_reason, ''), 'winner_id', v_winner_id,
                             'next_status', v_next_status));

  return jsonb_build_object('ok', true, 'decision_id', v_decision_id, 'winner_id', v_winner_id,
                            'status', v_next_status);
end;
$$;

ALTER FUNCTION public.phx_decide_early_birds_candidate(p_snapshot_id uuid, p_candidate_id uuid, p_decision text, p_reason text, p_decided_by text, p_actor_role text, p_announcement jsonb) OWNER TO postgres;

--
-- Name: phx_decide_expense_claim(text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_decide_expense_claim(p_claim_ref text, p_action text, p_expected_status text, p_actor_hr_id text, p_approved_total numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_claim public.expense_claims%rowtype;
  v_next text;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_linked boolean;
  v_py integer; v_pm integer; v_reperiod boolean := false;
  v_approved numeric := null;
  v_from_status text;
begin
  if p_actor_hr_id is null or btrim(p_actor_hr_id) = '' then
    raise exception 'An actor is required: every decision must be attributable.' using errcode = 'P0001';
  end if;

  select * into v_claim from public.expense_claims where claim_ref = p_claim_ref for update;

  if not found then
    raise exception 'Expense claim % was not found.', p_claim_ref using errcode = 'P0002';
  end if;

  v_from_status := v_claim.status;

  if v_claim.status is distinct from p_expected_status then
    raise exception
      'Expense claim % moved: expected "%" but it is "%". Refresh and retry.',
      p_claim_ref, p_expected_status, v_claim.status using errcode = 'P0001';
  end if;

  select exists (select 1 from public.expense_payroll_links l where l.claim_id = v_claim.id) into v_linked;

  if v_linked then
    raise exception
      'Expense claim % is already linked to a payroll batch; "%" is not allowed here. Unwinding a linked claim is a payroll operation.',
      p_claim_ref, p_action using errcode = 'P0001';
  end if;

  v_next := case
    when p_action = 'approve'   and v_claim.status in ('submitted', 'returned')             then 'approved'
    when p_action = 'reject'    and v_claim.status in ('submitted', 'returned', 'approved') then 'rejected'
    when p_action = 'return'    and v_claim.status in ('submitted')                         then 'returned'
    when p_action = 'reopen'    and v_claim.status in ('rejected')                          then 'submitted'
    when p_action = 'unapprove' and v_claim.status in ('approved')                          then 'submitted'
    when p_action = 'cancel'    and v_claim.status in ('submitted', 'returned')             then 'cancelled'
    else null
  end;

  if v_next is null then
    raise exception 'Action "%" is not allowed on an expense claim in status "%".',
      p_action, v_claim.status using errcode = 'P0001';
  end if;

  if p_action in ('reject', 'return') and v_reason is null then
    raise exception 'A reason is required to % expense claim %.', p_action, p_claim_ref using errcode = 'P0001';
  end if;

  if p_action = 'approve' then
    if p_approved_total is null then
      raise exception
        'An approved amount is required. Write it even when it equals the claim, so "reviewed and approved in full" stays distinguishable from "nobody touched it".'
        using errcode = 'P0001';
    end if;
    if p_approved_total < 0 or p_approved_total > v_claim.claimed_total then
      raise exception 'Approved amount % is outside [0, %] for claim %.',
        p_approved_total, v_claim.claimed_total, p_claim_ref using errcode = 'P0001';
    end if;
    if abs(p_approved_total - v_claim.claimed_total) > 0.005 and v_reason is null then
      raise exception 'A reason is required when the approved amount differs from the claim (% vs %).',
        p_approved_total, v_claim.claimed_total using errcode = 'P0001';
    end if;

    v_approved := round(p_approved_total, 2);
    select r.payout_year, r.payout_month, r.reperiodized into v_py, v_pm, v_reperiod
    from public.phx_resolve_expense_payout_period(v_claim.incurred_year, v_claim.incurred_month) r;
  end if;

  update public.expense_claims
  set status           = v_next,
      approved_total   = case when p_action = 'approve' then v_approved else null end,
      decided_by_hr_id = case when p_action in ('reopen', 'unapprove') then null else p_actor_hr_id end,
      decided_at       = case when p_action in ('reopen', 'unapprove') then null else now() end,
      decision_reason  = case when p_action in ('reopen', 'unapprove') then null else v_reason end,
      payout_year      = case when p_action = 'approve' then v_py else null end,
      payout_month     = case when p_action = 'approve' then v_pm else null end
  where id = v_claim.id;

  insert into public.expense_claim_events (claim_id, actor_hr_id, event_type, message, metadata)
  values (
    v_claim.id, p_actor_hr_id, 'decision.' || p_action,
    coalesce(v_reason, 'Action: ' || p_action),
    jsonb_strip_nulls(jsonb_build_object(
      'from_status', v_from_status, 'to_status', v_next,
      'from_approved', v_claim.approved_total, 'to_approved', v_approved,
      'claimed_total', v_claim.claimed_total,
      'payout_year', v_py, 'payout_month', v_pm,
      'reperiodized', case when v_reperiod then true else null end,
      'natural_period', case when v_reperiod
        then (v_claim.incurred_year::text || '-' || lpad((v_claim.incurred_month + 1)::text, 2, '0'))
        else null end
    ))
  );

  return jsonb_build_object(
    'claim_ref', p_claim_ref, 'from_status', v_from_status, 'status', v_next,
    'approved_total', v_approved, 'payout_year', v_py, 'payout_month', v_pm,
    'reperiodized', v_reperiod, 'decided_at', now()
  );
end;
$$;

ALTER FUNCTION public.phx_decide_expense_claim(p_claim_ref text, p_action text, p_expected_status text, p_actor_hr_id text, p_approved_total numeric, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION phx_decide_expense_claim(p_claim_ref text, p_action text, p_expected_status text, p_actor_hr_id text, p_approved_total numeric, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_decide_expense_claim(p_claim_ref text, p_action text, p_expected_status text, p_actor_hr_id text, p_approved_total numeric, p_reason text) IS 'One guarded, transactional expense-claim decision: approve | reject | return | reopen | unapprove | cancel. Compare-and-swap on p_expected_status; writes its own audit event; resolves payout to the earliest OPEN period on approve.';

--
-- Name: phx_decide_expense_claims(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_decide_expense_claims(p_decisions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item jsonb; v_applied jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb;
  v_result jsonb; v_msg text;
begin
  if jsonb_typeof(p_decisions) <> 'array' then
    raise exception 'p_decisions must be a JSON array of decision objects.' using errcode = 'P0001';
  end if;

  for v_item in select * from jsonb_array_elements(p_decisions) loop
    begin
      v_result := public.phx_decide_expense_claim(
        v_item->>'claim_ref', v_item->>'action', v_item->>'expected_status',
        v_item->>'actor_hr_id', nullif(v_item->>'approved_total', '')::numeric, v_item->>'reason'
      );
      v_applied := v_applied || jsonb_build_array(v_result);
    exception when others then
      get stacked diagnostics v_msg = message_text;
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
        'claim_ref', v_item->>'claim_ref', 'action', v_item->>'action', 'reason', v_msg
      ));
    end;
  end loop;

  return jsonb_build_object(
    'applied', jsonb_array_length(v_applied), 'skipped', jsonb_array_length(v_skipped),
    'applied_rows', v_applied, 'skipped_rows', v_skipped
  );
end;
$$;

ALTER FUNCTION public.phx_decide_expense_claims(p_decisions jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phx_decide_expense_claims(p_decisions jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_decide_expense_claims(p_decisions jsonb) IS 'Bulk wrapper over phx_decide_expense_claim: N decisions in ONE round trip. A per-row refusal is returned named instead of aborting the batch.';

--
-- Name: phx_decide_marketing_request_step(uuid, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_decide_marketing_request_step(p_step_id uuid, p_request_id uuid, p_decision text, p_decided_by text, p_decision_note text, p_decided_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_terminal_step_status text;
  v_step                 marketing_request_approval_steps%ROWTYPE;
  v_request              marketing_requests%ROWTYPE;
  v_next_step            marketing_request_approval_steps%ROWTYPE;
  v_has_next             boolean := false;
  v_terminal_status      text;
  v_is_execution         boolean := false;
  v_requester_hr_id      text;
  v_terminalised         integer := 0;
  v_invoice_days         integer;
  v_request_status       text;
BEGIN
  -- Lock the request row FIRST, and refuse unless it is still awaiting approval. Without this a
  -- decision could land on a request that was cancelled (or otherwise moved on) a moment ago and
  -- write it back to approved/rejected/returned. The caller maps this to the same 409 its own
  -- pre-check throws.
  SELECT r.status INTO v_request_status
  FROM marketing_requests r
  WHERE r.id = p_request_id
  FOR UPDATE;

  IF v_request_status IS DISTINCT FROM 'pending_approval' THEN
    RAISE EXCEPTION 'marketing_request_not_pending: request % is %, not pending_approval', p_request_id, COALESCE(v_request_status, 'missing');
  END IF;

  -- Map decision -> step terminal status
  v_terminal_step_status := CASE p_decision
    WHEN 'approve' THEN 'approved'
    WHEN 'reject'  THEN 'rejected'
    WHEN 'return'  THEN 'returned'
  END;

  IF v_terminal_step_status IS NULL THEN
    RAISE EXCEPTION 'Invalid marketing request decision: %', p_decision;
  END IF;

  -- 0. Nobody decides their own request. Checked before anything is written.
  SELECT r.requester_hr_id INTO v_requester_hr_id
  FROM marketing_requests r
  WHERE r.id = p_request_id;

  IF v_requester_hr_id IS NOT NULL
     AND lower(btrim(v_requester_hr_id)) = lower(btrim(COALESCE(p_decided_by, ''))) THEN
    -- Caller maps this to a 403.
    RAISE EXCEPTION 'marketing_self_approval_refused: % raised this request and may not decide it', p_decided_by
      USING errcode = 'check_violation';
  END IF;

  -- 1. Stamp the current step with optimistic-lock (status must still be 'current').
  UPDATE marketing_request_approval_steps SET
    decision_at       = p_decided_at,
    decision_by_hr_id = p_decided_by,
    decision_note     = NULLIF(btrim(COALESCE(p_decision_note, '')), ''),
    status            = v_terminal_step_status,
    updated_at        = p_decided_at
  WHERE id     = p_step_id
    AND status = 'current'
  RETURNING * INTO v_step;

  IF NOT FOUND THEN
    -- Signals a concurrent decision; caller maps this to a 409 conflict.
    RAISE EXCEPTION 'marketing_step_already_decided: step % was no longer current', p_step_id;
  END IF;

  -- Branch A: reject or return
  IF p_decision IN ('reject', 'return') THEN

    -- A REJECT ends the chain. Every rung still waiting is closed out as `skipped`, so nothing
    -- downstream keeps reporting it as outstanding work. Only `pending` non-CC rungs are touched:
    -- a rung that was already approved/rejected/returned keeps its decision untouched, and CC rows
    -- are already `skipped`.
    --
    -- A RETURN is left alone on purpose - the request goes back to the requester and the later
    -- rungs are genuinely still ahead of it; resubmission depends on them staying `pending`.
    IF p_decision = 'reject' THEN
      UPDATE marketing_request_approval_steps SET
        status     = 'skipped',
        updated_at = p_decided_at
      WHERE request_id = p_request_id
        AND status     = 'pending'
        AND is_cc      = false;
      GET DIAGNOSTICS v_terminalised = ROW_COUNT;
    END IF;

    UPDATE marketing_requests SET
      -- `returned_at` and `returned_step_sequence` are NO LONGER cleared by a reject. A request
      -- that was returned, resubmitted, then refused keeps the evidence that the return happened.
      -- Only a `return` sets them; a `reject` leaves whatever is already there.
      rejected_at            = CASE WHEN p_decision = 'reject' THEN p_decided_at ELSE rejected_at END,
      returned_at            = CASE WHEN p_decision = 'return' THEN p_decided_at ELSE returned_at END,
      returned_step_sequence = CASE WHEN p_decision = 'return' THEN v_step.sequence ELSE returned_step_sequence END,
      status                 = CASE WHEN p_decision = 'reject' THEN 'rejected'::text ELSE 'returned'::text END,
      updated_at             = p_decided_at,
      updated_by_hr_id       = p_decided_by
    WHERE id = p_request_id
      AND status = 'pending_approval'
    RETURNING * INTO v_request;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'marketing_request_not_pending: request % left pending_approval before the decision was written', p_request_id;
    END IF;

    RETURN jsonb_build_object(
      'branch',        p_decision,
      'step',          to_jsonb(v_step),
      'request',       to_jsonb(v_request),
      'nextStep',      NULL,
      'isExecution',   false,
      -- How many rungs were closed out, so the caller can log it rather than infer it.
      'terminalised',  v_terminalised
    );
  END IF;

  -- Branch B or C: approve
  UPDATE marketing_request_approval_steps SET
    status     = 'current',
    updated_at = p_decided_at
  WHERE id = (
    SELECT id
    FROM   marketing_request_approval_steps
    WHERE  request_id = p_request_id
      AND  status     = 'pending'
      AND  is_cc      = false
      AND  sequence   > v_step.sequence
    ORDER  BY sequence
    LIMIT  1
  )
  AND status = 'pending'
  RETURNING * INTO v_next_step;

  v_has_next := FOUND;

  -- Branch B: next approver exists
  IF v_has_next THEN
    SELECT * INTO v_request FROM marketing_requests WHERE id = p_request_id;

    RETURN jsonb_build_object(
      'branch',      'approve_next',
      'step',        to_jsonb(v_step),
      'request',     to_jsonb(v_request),
      'nextStep',    to_jsonb(v_next_step),
      'isExecution', false
    );
  END IF;

  -- Branch C: final approval
  v_terminal_status := COALESCE(v_step.terminal_status, 'approved');
  v_is_execution    := (v_terminal_status = 'active');

  UPDATE marketing_requests SET
    approved_at      = p_decided_at,
    executed_at      = CASE WHEN v_is_execution THEN p_decided_at ELSE executed_at END,
    status           = v_terminal_status,
    updated_at       = p_decided_at,
    updated_by_hr_id = p_decided_by
  WHERE id = p_request_id
    AND status = 'pending_approval'
  RETURNING * INTO v_request;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'marketing_request_not_pending: request % left pending_approval before the decision was written', p_request_id;
  END IF;

  IF v_is_execution THEN
    UPDATE marketing_request_approval_steps SET
      executed_at = p_decided_at,
      updated_at  = p_decided_at
    WHERE id = p_step_id
    RETURNING * INTO v_step;
  END IF;

  -- Record the invoice obligation this approval creates.
  --
  -- Inside the same transaction as the approval on purpose: this function exists precisely so a
  -- decision cannot half-apply, and an approval that commits without its obligation is exactly the
  -- half-state it was written to prevent.
  --
  -- A missing settings row falls back to 7 rather than raising. The deadline is a reminder; a
  -- deleted setting must not be able to make an approval fail.
  SELECT (setting_value ->> 'days')::integer
    INTO v_invoice_days
  FROM marketing_control_settings
  WHERE setting_key = 'finance_invoice_deadline_days';

  INSERT INTO marketing_request_finance_requirements (
    request_id,
    invoice_required,
    invoice_status,
    invoice_deadline_date,
    created_at,
    updated_at
  )
  VALUES (
    p_request_id,
    true,
    'pending',
    ((p_decided_at AT TIME ZONE 'Africa/Cairo')::date + COALESCE(v_invoice_days, 7)),
    p_decided_at,
    p_decided_at
  )
  ON CONFLICT (request_id) DO NOTHING;

  RETURN jsonb_build_object(
    'branch',      'approve_final',
    'step',        to_jsonb(v_step),
    'request',     to_jsonb(v_request),
    'nextStep',    NULL,
    'isExecution', v_is_execution
  );
END;
$$;

ALTER FUNCTION public.phx_decide_marketing_request_step(p_step_id uuid, p_request_id uuid, p_decision text, p_decided_by text, p_decision_note text, p_decided_at timestamp with time zone) OWNER TO postgres;

--
-- Name: phx_decline_offer_and_open_vacancy(text, text, text, date, text, text, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_decline_offer_and_open_vacancy(p_actor text, p_employee_hr_id text, p_employee_status text, p_last_working_date date, p_note text, p_submitted_by_hr_id text, p_submitted_date date, p_vacancy_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_employee public.employees;
  v_position_title text;
  v_manager_name text;
  v_vacancy_id bigint;
  v_seat_id text;
  -- p_last_working_date is the last day the person IS in the seat, so the seat falls vacant the
  -- day after it. A null date keeps the original meaning: vacate from today, Cairo-zoned.
  v_vacant_from date := coalesce(p_last_working_date + 1, (now() at time zone 'Africa/Cairo')::date);
begin
  if p_employee_status not in ('terminated', 'declined_offer') then
    raise exception 'phx_decline_offer_and_open_vacancy: employee status must be terminated or declined_offer, got %', p_employee_status;
  end if;

  select * into v_employee from public.employees where hr_id = p_employee_hr_id;
  if not found then
    raise exception 'phx_decline_offer_and_open_vacancy: employee % not found', p_employee_hr_id;
  end if;

  select title into v_position_title from public.positions where id = v_employee.position_id;
  select full_name into v_manager_name from public.employees where hr_id = v_employee.manager_hr_id;

  -- 1. Open the replacement vacancy (mirrors the resignation RPC's step 1).
  insert into public.position_vacancies (
    area_id, department_id, job_title, line_id, manager_hr_id, manager_name, note,
    position_id, region_name, replacement_for_hr_id, status, vacancy_code, created_at, updated_at
  ) values (
    v_employee.area_id, v_employee.department_id,
    coalesce(v_employee.job_title, v_position_title), v_employee.line_id,
    v_employee.manager_hr_id, v_manager_name,
    'Auto-opened from declined offer of ' || v_employee.full_name || ' (' || v_employee.hr_id || '). Last day ' || p_last_working_date,
    v_employee.position_id, v_employee.region_name, p_employee_hr_id, 'open', p_vacancy_code,
    now(), now()
  )
  returning id into v_vacancy_id;

  -- 2. Update the employee's own lifecycle fields. No employee_resignations row is
  --    written here — see the file header. exit_category is the durable, findable
  --    marker independent of which employment_status this exit lands on.
  update public.employees set
    employment_status = p_employee_status,
    exit_category = 'declined_offer',
    exit_reason = p_note,
    last_working_date = p_last_working_date,
    organogram_visible = false,
    payroll_eligible = false,
    resignation_date = p_submitted_date,
    updated_at = now()
  where hr_id = p_employee_hr_id;

  -- 3. Deactivate app access (DB-side only; Telegram deactivation is an external API
  --    call and stays in application code, same as the resignation RPC).
  update public.app_auth_users set is_active = false, updated_at = now() where hr_id = p_employee_hr_id;
  update public.user_access_profiles set is_active = false, updated_at = now() where hr_id = p_employee_hr_id;

  -- 4. Vacate the au seat, if any, in the same transaction (identical guard to the
  --    resignation RPC's step 5). A brand-new hire with no replacement_for_hr_id never
  --    occupies a seat at all, so this is routinely a no-op.
  select seat_id into v_seat_id
  from au.occupancy_history
  where occupant_hr_id = p_employee_hr_id and effective_to is null and node_type = 'person'
  limit 1;
  if v_seat_id is not null then
    perform au.resign_occupant(v_seat_id, v_vacant_from, coalesce(p_note, 'declined offer after hire'), p_actor);
  end if;

  return jsonb_build_object(
    'employee_hr_id', p_employee_hr_id,
    'employee_status', p_employee_status,
    'vacancy_code', p_vacancy_code
  );
end;
$$;

ALTER FUNCTION public.phx_decline_offer_and_open_vacancy(p_actor text, p_employee_hr_id text, p_employee_status text, p_last_working_date date, p_note text, p_submitted_by_hr_id text, p_submitted_date date, p_vacancy_code text) OWNER TO postgres;

--
-- Name: phx_deductions_charge_leave_balance(uuid, text, date, numeric, text, text, date, date, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_deductions_charge_leave_balance(p_candidate_id uuid, p_employee_hr_id text, p_work_date date, p_days numeric, p_comment text, p_actor_hr_id text, p_period_start date, p_period_end date, p_seen_request_days numeric, p_seen_charge_days numeric, p_seen_copilot_days numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_candidate public.deductions_candidates;
  v_request_days numeric;
  v_charge_days numeric;
  v_copilot_days numeric;
  v_already numeric;
  v_id bigint;
begin
  if coalesce(btrim(p_comment), '') = '' then
    raise exception 'Write the comment the employee will read.' using errcode = '22023';
  end if;
  if p_days is null or p_days <= 0 then
    raise exception 'There are no days to charge to the leave balance.' using errcode = '22023';
  end if;
  if p_period_start is null or p_period_end is null or p_work_date is null then
    raise exception 'A leave balance charge needs its balance period.' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext(lower(p_employee_hr_id)));

  select * into v_candidate from public.deductions_candidates where id = p_candidate_id for update;
  if not found then
    raise exception 'That deduction was not found.' using errcode = 'P0002';
  end if;
  if v_candidate.superseded_at is not null then
    raise exception 'That deduction was replaced by a newer one — reload and look again.' using errcode = '40001';
  end if;
  if v_candidate.locked_at is not null then
    raise exception 'That deduction is locked by a publication and can no longer be changed.' using errcode = '55000';
  end if;
  if v_candidate.category not in ('crm', 'crm_half_day', 'unpaid_vacation', 'insufficient_balance_vacation') then
    raise exception 'Only a CRM, CRM half-day, unpaid vacation or insufficient balance vacation deduction can be charged to the leave balance.'
      using errcode = '22023';
  end if;
  if lower(coalesce(v_candidate.employee_hr_id, '')) <> lower(p_employee_hr_id) then
    raise exception 'That deduction belongs to a different employee.' using errcode = '22023';
  end if;

  select coalesce(sum(days), 0) into v_already
  from public.attendance_annual_balance_charges
  where deduction_candidate_id = p_candidate_id;
  if v_already > 0.0005 then
    raise exception 'That deduction is already charged to the leave balance — reload and look again.' using errcode = '40001';
  end if;

  select coalesce(sum(paid_duration_days), 0) into v_request_days
  from public.v2_vacation_requests
  where lower(employee_hr_id) = lower(p_employee_hr_id)
    and status = 'approved'
    and vacation_type in ('annual', 'emergency')
    and start_date >= p_period_start
    and start_date <  p_period_end;

  select coalesce(sum(days), 0) into v_charge_days
  from public.attendance_annual_balance_charges
  where lower(employee_hr_id) = lower(p_employee_hr_id)
    and work_date >= p_period_start
    and work_date <  p_period_end;

  select coalesce(sum(balance_days_consumed), 0) into v_copilot_days
  from public.payroll_copilot_vacation_settlements
  where employee_hr_id_compact = regexp_replace(lower(p_employee_hr_id), '[^a-z0-9]+', '', 'g')
    and settlement_method in ('balance', 'partial_balance', 'defer_to_balance')
    and superseded_at is null
    and start_date >= p_period_start
    and start_date <  p_period_end;

  if round(v_request_days, 3) <> round(coalesce(p_seen_request_days, -1), 3)
     or round(v_charge_days, 3) <> round(coalesce(p_seen_charge_days, -1), 3)
     or round(v_copilot_days, 3) <> round(coalesce(p_seen_copilot_days, -1), 3) then
    raise exception 'The annual balance changed while this was being saved. Reload and try again.'
      using errcode = '40001';
  end if;

  insert into public.attendance_annual_balance_charges (
    source, deduction_candidate_id, employee_hr_id, work_date, days, period_start, period_end, created_by, comment
  ) values (
    'deductions', p_candidate_id, p_employee_hr_id, p_work_date, round(p_days, 3),
    p_period_start, p_period_end, p_actor_hr_id, btrim(p_comment)
  )
  returning id into v_id;

  return jsonb_build_object('chargeId', v_id, 'days', round(p_days, 3));
end;
$$;

ALTER FUNCTION public.phx_deductions_charge_leave_balance(p_candidate_id uuid, p_employee_hr_id text, p_work_date date, p_days numeric, p_comment text, p_actor_hr_id text, p_period_start date, p_period_end date, p_seen_request_days numeric, p_seen_charge_days numeric, p_seen_copilot_days numeric) OWNER TO postgres;

--
-- Name: phx_deductions_decisions_refuse_locked(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_deductions_decisions_refuse_locked() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_locked_at timestamptz;
begin
  -- Only a change to what the decision charges or says is refused; a write that leaves every
  -- deciding field as it was moves no money.
  if tg_op = 'UPDATE'
     and (new.candidate_id, new.decision_status, new.decision_reason, new.hr_note, new.applied_value,
          new.applied_amount, new.applied_dates, new.decided_by)
         is not distinct from
         (old.candidate_id, old.decision_status, old.decision_reason, old.hr_note, old.applied_value,
          old.applied_amount, old.applied_dates, old.decided_by) then
    return new;
  end if;

  select c.locked_at into v_locked_at
  from public.deductions_candidates c
  where c.id = new.candidate_id
  for share;

  if v_locked_at is null then
    return new;
  end if;

  -- recovery.restore_table deletes and re-inserts the whole table after taking its pre-image in the
  -- SAME transaction (taken_at is clock_timestamp(), so it is at or after this transaction's now()).
  if to_regclass('recovery.restore_preimages') is not null
     and exists (
       select 1 from recovery.restore_preimages rp
       where rp.source_schema = 'public'
         and rp.source_table = 'deductions_decisions'
         and rp.taken_at >= now()
     ) then
    return new;
  end if;

  raise exception
    'deductions_decisions: candidate % is locked by a publication (locked_at=%) — withdraw its line before deciding it again',
    new.candidate_id, v_locked_at
    using errcode = '55000';
end;
$$;

ALTER FUNCTION public.phx_deductions_decisions_refuse_locked() OWNER TO postgres;

--
-- Name: FUNCTION phx_deductions_decisions_refuse_locked(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_deductions_decisions_refuse_locked() IS 'BEFORE INSERT OR UPDATE ROW trigger on public.deductions_decisions (F-PAY-004): refuses a decision change on a candidate a publication has locked, under a FOR SHARE lock of the candidate row. Exempt: recovery.restore_table in the same transaction.';

--
-- Name: phx_deductions_return_leave_balance(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_deductions_return_leave_balance(p_candidate_id uuid, p_reason text, p_actor_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_candidate public.deductions_candidates;
  v_charge public.attendance_annual_balance_charges;
  v_employee text;
  v_returned numeric := 0;
begin
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'Say why this is going back to salary.' using errcode = '22023';
  end if;

  select employee_hr_id into v_employee
  from public.attendance_annual_balance_charges
  where deduction_candidate_id = p_candidate_id
  order by id
  limit 1;
  if v_employee is null then
    raise exception 'That deduction was never charged to the leave balance.' using errcode = 'P0002';
  end if;

  perform pg_advisory_xact_lock(hashtext(lower(v_employee)));

  select * into v_candidate from public.deductions_candidates where id = p_candidate_id for update;
  if found and v_candidate.locked_at is not null then
    raise exception 'That deduction is locked by a publication and can no longer be changed.' using errcode = '55000';
  end if;

  for v_charge in
    select c.*
    from public.attendance_annual_balance_charges c
    where c.deduction_candidate_id = p_candidate_id
      and c.days > 0
      and not exists (
        select 1 from public.attendance_annual_balance_charges r where r.reverses_charge_id = c.id
      )
    order by c.id
    for update
  loop
    insert into public.attendance_annual_balance_charges (
      source, deduction_candidate_id, employee_hr_id, work_date, days, period_start, period_end,
      created_by, reverses_charge_id, reversal_reason
    ) values (
      'deductions', v_charge.deduction_candidate_id, v_charge.employee_hr_id, v_charge.work_date,
      -v_charge.days, v_charge.period_start, v_charge.period_end, p_actor_hr_id, v_charge.id, btrim(p_reason)
    );
    v_returned := v_returned + v_charge.days;
  end loop;

  if v_returned <= 0 then
    raise exception 'That deduction is not charged to the leave balance any more — reload and look again.' using errcode = '40001';
  end if;

  return jsonb_build_object('returnedDays', v_returned);
end;
$$;

ALTER FUNCTION public.phx_deductions_return_leave_balance(p_candidate_id uuid, p_reason text, p_actor_hr_id text) OWNER TO postgres;

--
-- Name: phx_delete_salary_batch(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_delete_salary_batch(p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_deleted_flags integer := 0;
  v_deleted_records integer := 0;
begin
  if p_batch_id is null then
    raise exception 'Payroll upload id is required.' using errcode = '22023';
  end if;

  select *
  into v_batch
  from public.salary_batches
  where id = p_batch_id
  for update;

  if not found then
    raise exception 'Payroll upload not found.' using errcode = 'P0002';
  end if;

  -- Refuse a closed month outright, BEFORE the guards are bypassed below.
  if v_batch.status not in ('uploaded', 'part1_ready', 'rejected')
     or v_batch.part1_paid_at is not null then
    raise exception 'Payroll %/% is % and cannot be deleted. A month that has reached this stage is never deleted; correct it in the next month instead.',
      v_batch.month, v_batch.year, replace(v_batch.status, '_', ' ')
      using errcode = 'P0001';
  end if;

  perform set_config('request.phx_allow_salary_batch_delete', 'on', true);

  delete from public.salary_flags
  where batch_id = p_batch_id;
  get diagnostics v_deleted_flags = row_count;

  delete from public.salary_records
  where batch_id = p_batch_id;
  get diagnostics v_deleted_records = row_count;

  delete from public.salary_batches
  where id = p_batch_id;

  return jsonb_build_object(
    'id', v_batch.id,
    'month', v_batch.month,
    'year', v_batch.year,
    'status', v_batch.status,
    'file_name', v_batch.file_name,
    'records_deleted', v_deleted_records,
    'flags_deleted', v_deleted_flags
  );
end;
$$;

ALTER FUNCTION public.phx_delete_salary_batch(p_batch_id uuid) OWNER TO postgres;

--
-- Name: phx_device_issue(uuid, text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_device_issue(p_device_id uuid, p_employee_hr_id text, p_actor text, p_declaration_no text DEFAULT NULL::text, p_handover_place text DEFAULT NULL::text, p_issued_on date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device public.company_devices%rowtype;
  v_employee record;
  v_assignment_id uuid;
begin
  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'Issuing a device must record who handed it over.';
  end if;

  select * into v_device from public.company_devices where id = p_device_id;
  if not found then
    raise exception 'Device % was not found.', p_device_id;
  end if;

  -- A device that is lost, stolen, retired or in repair is not in the building. Issuing one
  -- produces a signed receipt for a machine nobody can hand over.
  if v_device.status <> 'in_stock' then
    raise exception 'Device % is %, not in stock. Only a device in stock can be issued.',
      v_device.asset_tag, v_device.status;
  end if;

  -- Belt and braces over uq_device_assignments_outstanding_device. The index is the real guard;
  -- this raises the readable error instead of a constraint-violation string.
  if exists (
    select 1 from public.device_assignments
    where device_id = p_device_id and status = 'outstanding'
  ) then
    raise exception 'Device % is already signed out to somebody.', v_device.asset_tag;
  end if;

  -- lower() on BOTH sides — hr_id is mixed case in this database and a plain `=` silently
  -- under-returns.
  select e.hr_id, e.full_name, e.nickname, e.job_title
  into v_employee
  from public.employees e
  where lower(e.hr_id) = lower(trim(p_employee_hr_id))
  limit 1;

  if not found then
    raise exception 'No employee matches HR ID %.', p_employee_hr_id;
  end if;

  insert into public.device_assignments (
    device_id, employee_hr_id, employee_name, job_title,
    declaration_no, handover_place, issued_on, issued_by, agreed_value_egp
  )
  values (
    p_device_id,
    v_employee.hr_id,
    coalesce(nullif(trim(v_employee.full_name), ''), v_employee.hr_id),
    v_employee.job_title,
    nullif(trim(p_declaration_no), ''),
    nullif(trim(p_handover_place), ''),
    coalesce(p_issued_on, (now() at time zone 'Africa/Cairo')::date),
    p_actor,
    -- Frozen here, on purpose. See the migration header: البند (9) makes the value shown at
    -- signature the agreed one, and البند (10) caps recovery at it.
    v_device.estimated_value_egp
  )
  returning id into v_assignment_id;

  update public.company_devices
  set status = 'assigned',
      status_reason = null,
      status_changed_at = now(),
      status_changed_by = p_actor,
      updated_at = now()
  where id = p_device_id;

  return v_assignment_id;
end;
$$;

ALTER FUNCTION public.phx_device_issue(p_device_id uuid, p_employee_hr_id text, p_actor text, p_declaration_no text, p_handover_place text, p_issued_on date) OWNER TO postgres;

--
-- Name: phx_device_mark(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_device_mark(p_device_id uuid, p_status text, p_actor text, p_reason text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device public.company_devices%rowtype;
begin
  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'A device status change must record who made it.';
  end if;

  -- Locked: an issue or a reservation racing this mark waits, and the checks below read what it left.
  select * into v_device from public.company_devices where id = p_device_id for update;
  if not found then
    raise exception 'Device % was not found.', p_device_id;
  end if;

  if p_status not in ('in_stock', 'repair', 'lost', 'stolen', 'retired') then
    raise exception 'Unknown device status %. Issue a device to make it assigned.', p_status;
  end if;

  if p_status in ('lost', 'stolen', 'retired', 'repair')
     and (p_reason is null or char_length(trim(p_reason)) = 0) then
    raise exception 'Marking a device % needs a written reason.', p_status;
  end if;

  -- NEW. A reservation is ended (revoked, or reconciled on day one) before the device's state moves.
  if v_device.status = 'reserved' or exists (
    select 1 from public.device_assignments
    where device_id = p_device_id and status = 'reserved'
  ) then
    raise exception
      'Marking % is refused while it is reserved for somebody. Revoke the reservation (or reconcile it) first.',
      v_device.asset_tag;
  end if;

  -- Unchanged: a lost or stolen device does NOT release its holder (البند 10, 11), and a device that
  -- is signed out is never put back in stock by hand — its return is recorded instead.
  if p_status = 'in_stock' and exists (
    select 1 from public.device_assignments
    where device_id = p_device_id and status = 'outstanding'
  ) then
    raise exception
      'Device % is signed out. Record the return (محضر رد العهدة) rather than putting it back in stock.',
      v_device.asset_tag;
  end if;

  update public.company_devices
  set status = p_status,
      status_reason = nullif(trim(p_reason), ''),
      status_changed_at = now(),
      status_changed_by = p_actor,
      updated_at = now()
  where id = p_device_id;

  return p_status;
end;
$$;

ALTER FUNCTION public.phx_device_mark(p_device_id uuid, p_status text, p_actor text, p_reason text) OWNER TO postgres;

--
-- Name: phx_device_reassign_placeholder(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_device_reassign_placeholder(p_assignment_id uuid, p_new_name text, p_actor text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.device_assignments%rowtype;
begin
  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'Reassigning a reservation must record who did it.';
  end if;
  if p_new_name is null or char_length(trim(p_new_name)) = 0 then
    raise exception 'A reservation needs the name it is being held for.';
  end if;

  select * into v_row from public.device_assignments where id = p_assignment_id;
  if not found then
    raise exception 'Device assignment % was not found.', p_assignment_id;
  end if;
  if v_row.status <> 'reserved' or not v_row.is_placeholder then
    raise exception 'Only a reservation can be reassigned to a different name. A signed custody is moved by recording its return and issuing it again.';
  end if;

  update public.device_assignments
  set placeholder_name = trim(p_new_name),
      updated_at = now()
  where id = p_assignment_id;

  return p_assignment_id;
end;
$$;

ALTER FUNCTION public.phx_device_reassign_placeholder(p_assignment_id uuid, p_new_name text, p_actor text) OWNER TO postgres;

--
-- Name: phx_device_reconcile(uuid, text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_device_reconcile(p_assignment_id uuid, p_employee_hr_id text, p_actor text, p_declaration_no text DEFAULT NULL::text, p_handover_place text DEFAULT NULL::text, p_issued_on date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.device_assignments%rowtype;
  v_device public.company_devices%rowtype;
  v_employee record;
begin
  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'Reconciling a reservation must record who handed the device over.';
  end if;

  -- Locked, so two presses on one reservation cannot both write.
  select * into v_row from public.device_assignments where id = p_assignment_id for update;
  if not found then
    raise exception 'Device assignment % was not found.', p_assignment_id;
  end if;
  if v_row.status <> 'reserved' or not v_row.is_placeholder then
    raise exception 'Only a reservation can be reconciled to an employee.';
  end if;

  select * into v_device from public.company_devices where id = v_row.device_id for update;
  if not found then
    raise exception 'Device % was not found.', v_row.device_id;
  end if;

  -- NEW. A reserved device marked lost, stolen, retired or in repair is not in the building.
  if v_device.status <> 'reserved' then
    raise exception
      'Reconciling % is refused: the device is %, not reserved, so it cannot be handed over.',
      v_device.asset_tag, v_device.status;
  end if;

  -- lower() on both sides — hr_id is mixed case in this database (see the register migration).
  select e.hr_id, e.full_name, e.nickname, e.job_title, e.employment_status
  into v_employee
  from public.employees e
  where lower(e.hr_id) = lower(trim(p_employee_hr_id))
  limit 1;
  if not found then
    raise exception 'No employee matches HR ID %.', p_employee_hr_id;
  end if;

  -- NEW. `employment_status` is stored in mixed case ('Resigned' and 'resigned' are both present).
  if lower(trim(coalesce(v_employee.employment_status, ''))) in ('resigned', 'terminated') then
    raise exception
      'Reconciling a reservation to % is refused: they have left the company (%).',
      coalesce(nullif(trim(v_employee.full_name), ''), v_employee.hr_id),
      lower(trim(v_employee.employment_status));
  end if;

  update public.device_assignments
  set status = 'outstanding',
      is_placeholder = false,
      placeholder_name = null,
      employee_hr_id = v_employee.hr_id,
      employee_name = coalesce(nullif(trim(v_employee.full_name), ''), v_employee.hr_id),
      job_title = v_employee.job_title,
      -- Frozen HERE, at the day-one signature — البند (9). Unchanged from the reservation migration.
      agreed_value_egp = v_device.estimated_value_egp,
      declaration_no = coalesce(nullif(trim(p_declaration_no), ''), declaration_no),
      handover_place = coalesce(nullif(trim(p_handover_place), ''), handover_place),
      issued_on = coalesce(p_issued_on, (now() at time zone 'Africa/Cairo')::date),
      issued_by = p_actor,
      updated_at = now()
  where id = p_assignment_id;

  update public.company_devices
  set status = 'assigned',
      status_reason = null,
      status_changed_at = now(),
      status_changed_by = p_actor,
      updated_at = now()
  where id = v_row.device_id;

  return p_assignment_id;
end;
$$;

ALTER FUNCTION public.phx_device_reconcile(p_assignment_id uuid, p_employee_hr_id text, p_actor text, p_declaration_no text, p_handover_place text, p_issued_on date) OWNER TO postgres;

--
-- Name: phx_device_reserve(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_device_reserve(p_device_id uuid, p_placeholder_name text, p_actor text, p_declaration_no text DEFAULT NULL::text, p_handover_place text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_device public.company_devices%rowtype;
  v_assignment_id uuid;
begin
  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'Reserving a device must record who did it.';
  end if;
  if p_placeholder_name is null or char_length(trim(p_placeholder_name)) = 0 then
    raise exception 'A reservation needs the name it is being held for.';
  end if;

  select * into v_device from public.company_devices where id = p_device_id;
  if not found then
    raise exception 'Device % was not found.', p_device_id;
  end if;

  if v_device.status <> 'in_stock' then
    raise exception 'Device % is %, not in stock. Only a device in stock can be reserved.',
      v_device.asset_tag, v_device.status;
  end if;

  if exists (
    select 1 from public.device_assignments
    where device_id = p_device_id and status in ('outstanding', 'reserved')
  ) then
    raise exception 'Device % already has a live holder or reservation.', v_device.asset_tag;
  end if;

  insert into public.device_assignments (
    device_id, employee_hr_id, employee_name, is_placeholder, placeholder_name,
    declaration_no, handover_place, issued_by, agreed_value_egp, status, note
  )
  values (
    p_device_id, null, null, true, trim(p_placeholder_name),
    nullif(trim(p_declaration_no), ''), nullif(trim(p_handover_place), ''), p_actor,
    null, 'reserved', nullif(trim(p_note), '')
  )
  returning id into v_assignment_id;

  update public.company_devices
  set status = 'reserved',
      status_reason = null,
      status_changed_at = now(),
      status_changed_by = p_actor,
      updated_at = now()
  where id = p_device_id;

  return v_assignment_id;
end;
$$;

ALTER FUNCTION public.phx_device_reserve(p_device_id uuid, p_placeholder_name text, p_actor text, p_declaration_no text, p_handover_place text, p_note text) OWNER TO postgres;

--
-- Name: phx_device_return(uuid, text, text, text, numeric, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_device_return(p_assignment_id uuid, p_actor text, p_condition text, p_shortfall_note text DEFAULT NULL::text, p_settlement_egp numeric DEFAULT NULL::numeric, p_returned_on date DEFAULT NULL::date, p_note text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.device_assignments%rowtype;
begin
  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'A return must record who received the device.';
  end if;

  select * into v_row from public.device_assignments where id = p_assignment_id;
  if not found then
    raise exception 'Device assignment % was not found.', p_assignment_id;
  end if;

  if v_row.status <> 'outstanding' then
    raise exception 'This custody record is already closed as %.', v_row.status;
  end if;

  if p_condition is null or p_condition not in ('good', 'damaged', 'incomplete') then
    raise exception 'A return must state the condition: good, damaged or incomplete.';
  end if;

  -- البند (10) in the database. The service checks it too, but a rule in a page is bypassed by the
  -- next page — and this one decides how much may come out of somebody's wages.
  if p_settlement_egp is not null
     and v_row.agreed_value_egp is not null
     and p_settlement_egp > v_row.agreed_value_egp then
    raise exception
      'A settlement of % exceeds the % agreed on the signed receipt. البند (10) caps recovery at the estimated value.',
      p_settlement_egp, v_row.agreed_value_egp;
  end if;

  -- Something missing or broken must say what. البند (10) prices «ما لم يُرد أو تكلفة إصلاح ما
  -- تلف» — an unexplained charge cannot be defended to the person paying it.
  if p_condition in ('damaged', 'incomplete')
     and (p_shortfall_note is null or char_length(trim(p_shortfall_note)) = 0) then
    raise exception 'A damaged or incomplete return must record what was missing or broken.';
  end if;

  update public.device_assignments
  set status = 'returned',
      returned_on = coalesce(p_returned_on, (now() at time zone 'Africa/Cairo')::date),
      returned_by = p_actor,
      return_condition = p_condition,
      shortfall_note = nullif(trim(p_shortfall_note), ''),
      settlement_egp = p_settlement_egp,
      note = coalesce(nullif(trim(p_note), ''), note),
      updated_at = now()
  where id = p_assignment_id;

  -- A device that came back broken goes to `repair`, not straight back into stock — issuing it to
  -- the next person is how a known fault becomes the next holder's liability under البند (1),
  -- which has him accepting it «بحالتها المدونة بهذا الإقرار».
  update public.company_devices
  set status = case when p_condition = 'good' then 'in_stock' else 'repair' end,
      status_reason = case
        when p_condition = 'good' then null
        else coalesce(nullif(trim(p_shortfall_note), ''), 'Returned ' || p_condition)
      end,
      status_changed_at = now(),
      status_changed_by = p_actor,
      updated_at = now()
  where id = v_row.device_id;

  return 'returned';
end;
$$;

ALTER FUNCTION public.phx_device_return(p_assignment_id uuid, p_actor text, p_condition text, p_shortfall_note text, p_settlement_egp numeric, p_returned_on date, p_note text) OWNER TO postgres;

--
-- Name: phx_device_revoke(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_device_revoke(p_assignment_id uuid, p_actor text, p_reason text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.device_assignments%rowtype;
begin
  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'Revoking a reservation must record who did it.';
  end if;

  select * into v_row from public.device_assignments where id = p_assignment_id;
  if not found then
    raise exception 'Device assignment % was not found.', p_assignment_id;
  end if;
  if v_row.status <> 'reserved' then
    raise exception 'Only a reservation can be revoked. A signed-out device must be returned (محضر رد العهدة) or written off.';
  end if;

  update public.device_assignments
  set status = 'revoked',
      reason = coalesce(nullif(trim(p_reason), ''), reason),
      updated_at = now()
  where id = p_assignment_id;

  update public.company_devices
  set status = 'in_stock',
      status_reason = null,
      status_changed_at = now(),
      status_changed_by = p_actor,
      updated_at = now()
  where id = v_row.device_id and status = 'reserved';

  return 'revoked';
end;
$$;

ALTER FUNCTION public.phx_device_revoke(p_assignment_id uuid, p_actor text, p_reason text) OWNER TO postgres;

--
-- Name: phx_device_write_off(uuid, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_device_write_off(p_assignment_id uuid, p_actor text, p_reason text, p_settlement_egp numeric DEFAULT NULL::numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.device_assignments%rowtype;
begin
  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'A write-off must record who decided it.';
  end if;
  if p_reason is null or char_length(trim(p_reason)) = 0 then
    raise exception 'A write-off needs a written reason — it ends a debt البند (10) created.';
  end if;

  select * into v_row from public.device_assignments where id = p_assignment_id;
  if not found then
    raise exception 'Device assignment % was not found.', p_assignment_id;
  end if;
  if v_row.status <> 'outstanding' then
    raise exception 'This custody record is already closed as %.', v_row.status;
  end if;

  if p_settlement_egp is not null
     and v_row.agreed_value_egp is not null
     and p_settlement_egp > v_row.agreed_value_egp then
    raise exception
      'A settlement of % exceeds the % agreed on the signed receipt. البند (10) caps recovery at the estimated value.',
      p_settlement_egp, v_row.agreed_value_egp;
  end if;

  update public.device_assignments
  set status = 'written_off',
      reason = trim(p_reason),
      settlement_egp = p_settlement_egp,
      updated_at = now()
  where id = p_assignment_id;

  return 'written_off';
end;
$$;

ALTER FUNCTION public.phx_device_write_off(p_assignment_id uuid, p_actor text, p_reason text, p_settlement_egp numeric) OWNER TO postgres;

--
-- Name: phx_direct_order_item_family_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_direct_order_item_family_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request_family text;
begin
  select family_code into v_request_family
  from public.direct_order_requests
  where id = new.request_id;

  -- A request whose family was never resolved (historic data) adopts its first line's family rather
  -- than refusing it. Refusing would make old requests uneditable for a reason their author could
  -- do nothing about.
  if v_request_family is null then
    update public.direct_order_requests set family_code = new.family_code where id = new.request_id;
    return new;
  end if;

  if upper(btrim(v_request_family)) <> upper(btrim(new.family_code)) then
    raise exception
      'direct order % is a % basket; % belongs to family % and cannot be added to it',
      new.request_id, v_request_family, new.product_code, new.family_code
      using errcode = 'check_violation';
  end if;

  return new;
end $$;

ALTER FUNCTION public.phx_direct_order_item_family_guard() OWNER TO postgres;

