--
-- Name: FUNCTION phx_direct_order_requests_requester_storage_form(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_direct_order_requests_requester_storage_form() IS 'Keeps direct_order_requests.requester_hr_id in the stored (upper-case, trimmed) form. 78 of 152 rows had shipped as the lower-case comparison key, so a plain join to employees.hr_id dropped 51% of direct orders silently.';

--
-- Name: phx_direct_order_search_keys(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_direct_order_search_keys(p_code text, p_name text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
declare
  s text;
  n int;
  i int;
  keys text[] := '{}';
begin
  s := lower(p_code);
  n := coalesce(char_length(s), 0);
  for i in 1..n loop
    keys := keys || ('c:' || substr(s, i, 1));
    if i < n then
      keys := keys || ('c:' || substr(s, i, 2));
    end if;
  end loop;

  s := lower(public.phx_normalize_arabic(p_name));
  n := coalesce(char_length(s), 0);
  for i in 1..n loop
    keys := keys || ('n:' || substr(s, i, 1));
    if i < n then
      keys := keys || ('n:' || substr(s, i, 2));
    end if;
  end loop;

  return keys;
end;
$$;

ALTER FUNCTION public.phx_direct_order_search_keys(p_code text, p_name text) OWNER TO postgres;

--
-- Name: FUNCTION phx_direct_order_search_keys(p_code text, p_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_direct_order_search_keys(p_code text, p_name text) IS 'Every 1- and 2-character piece of lower(customer_code) (prefix c:) and of the normalized, lower-cased name (prefix n:). IMMUTABLE index key for phx_search_direct_order_customers; a probe of one or two plain characters is looked up here instead of re-checking every row.';

--
-- Name: phx_direct_order_weekly_sync(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_direct_order_weekly_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_period text;
begin
  for v_period in
    select distinct p
      from unnest(array[
        case when tg_op = 'UPDATE' then old.sales_month end,
        new.sales_month
      ]) as p
     where p is not null
       and p ~ '^\d{4}-\d{2}$'
       and p >= '2026-08'
  loop
    begin
      perform public.phx_rebuild_direct_order_weekly_batches(v_period, 'system');
    exception when others then
      raise warning 'phx_direct_order_weekly_sync: weekly rebuild for % failed: %', v_period, sqlerrm;
      begin
        insert into public.direct_order_events (request_id, actor_hr_id, event_type, message, metadata)
        values (new.id, null, 'weekly_sync_failed',
                'The weekly sales rows for ' || v_period || ' could not be rebuilt from this order.',
                jsonb_build_object('period', v_period, 'error', sqlerrm));
      exception when others then
        null;
      end;
    end;
  end loop;
  return null;
end $_$;

ALTER FUNCTION public.phx_direct_order_weekly_sync() OWNER TO postgres;

--
-- Name: phx_direct_sales_reconciliation(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_direct_sales_reconciliation(p_period_from text DEFAULT NULL::text, p_period_to text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
  with direct_rollup as (
    select
      f.period,
      coalesce(nullif(btrim(f.official_line), ''), '(unassigned)')     as official_line,
      coalesce(nullif(btrim(f.region_code), ''), '(unspecified)')      as region_code,
      upper(btrim(coalesce(f.product_code, '')))                       as product_code,
      upper(btrim(f.distributor_code))                                 as distributor_code,
      f.direct_value,
      f.total_qty
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b
      on b.id = f.batch_id and b.status = 'validated'
    where f.is_direct
      and upper(btrim(f.distributor_code)) in ('DIRECT', 'DIRECTREQ')
      and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
      and (p_period_from is null or f.period >= p_period_from)
      and (p_period_to   is null or f.period <= p_period_to)
  ),
  grouped as (
    select
      period, official_line, region_code, product_code,
      coalesce(sum(direct_value) filter (where distributor_code = 'DIRECT'), 0)    as manual_value,
      coalesce(sum(total_qty)    filter (where distributor_code = 'DIRECT'), 0)    as manual_qty,
      coalesce(sum(direct_value) filter (where distributor_code = 'DIRECTREQ'), 0) as module_value,
      coalesce(sum(total_qty)    filter (where distributor_code = 'DIRECTREQ'), 0) as module_qty
    from direct_rollup
    group by period, official_line, region_code, product_code
  ),
  overlap_set as (
    select *, least(manual_value, module_value) as overlap_exposure
    from grouped
    where manual_value > 0 and module_value > 0
  )
  select jsonb_build_object(
    'periodFrom',        p_period_from,
    'periodTo',          p_period_to,
    'groupedRows',       (select count(*) from grouped),
    'overlapRows',       (select count(*) from overlap_set),
    'totalManualDirect', (select round(coalesce(sum(manual_value), 0), 2) from grouped),
    'totalModuleDirect', (select round(coalesce(sum(module_value), 0), 2) from grouped),
    'overlapExposure',   (select round(coalesce(sum(overlap_exposure), 0), 2) from overlap_set),
    'pass',              (select count(*) from overlap_set) = 0,
    'overlaps', coalesce((
      select jsonb_agg(jsonb_build_object(
        'period',          period,
        'line',            official_line,
        'regionCode',      region_code,
        'productCode',     product_code,
        'manualValue',     round(manual_value, 2),
        'manualQty',       manual_qty,
        'moduleValue',     round(module_value, 2),
        'moduleQty',       module_qty,
        'overlapExposure', round(overlap_exposure, 2)
      ) order by overlap_exposure desc)
      from overlap_set
    ), '[]'::jsonb),
    'byPeriod', coalesce((
      select jsonb_agg(jsonb_build_object(
        'period', period,
        'manualValue', round(manual_value, 2),
        'moduleValue', round(module_value, 2),
        'overlapExposure', round(overlap_exposure, 2)
      ) order by period)
      from (
        select period,
          sum(manual_value) as manual_value,
          sum(module_value) as module_value,
          sum(case when manual_value > 0 and module_value > 0 then least(manual_value, module_value) else 0 end) as overlap_exposure
        from grouped
        group by period
      ) p
    ), '[]'::jsonb)
  );
$$;

ALTER FUNCTION public.phx_direct_sales_reconciliation(p_period_from text, p_period_to text) OWNER TO postgres;

