--
-- Name: phx_employee_is_vacancy_autofill_eligible(public.employees); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_employee_is_vacancy_autofill_eligible(p_emp public.employees) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select lower(coalesce(p_emp.employment_status, 'active')) in ('active', 'on_leave')
     and coalesce(p_emp.payroll_eligible, true) is true
     and coalesce(p_emp.organogram_visible, true) is true
     and p_emp.area_id is not null
     and p_emp.line_id is not null
     and p_emp.position_id is not null
     and nullif(trim(coalesce(p_emp.manager_hr_id, '')), '') is not null;
$$;

ALTER FUNCTION public.phx_employee_is_vacancy_autofill_eligible(p_emp public.employees) OWNER TO postgres;

--
-- Name: phx_enforce_terminal_employee_lifecycle_flags(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_enforce_terminal_employee_lifecycle_flags() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if lower(coalesce(new.employment_status, 'active')) in ('resigned', 'terminated', 'inactive') then
    new.payroll_eligible := false;
    new.organogram_visible := false;
  elsif lower(coalesce(new.employment_status, 'active')) in ('active', 'on_leave') then
    new.payroll_eligible := coalesce(new.payroll_eligible, true);
    new.organogram_visible := coalesce(new.organogram_visible, true);
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_enforce_terminal_employee_lifecycle_flags() OWNER TO postgres;

--
-- Name: phx_ensure_terminal_employee_vacancy(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_ensure_terminal_employee_vacancy(p_employee_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee public.employees%rowtype;
  v_existing_vacancy_id bigint;
  v_manager_name text;
  v_vacancy_code text;
  v_effective_date date;
  v_blocked_reason text;
  v_occupant_hr_id text;
begin
  if nullif(trim(coalesce(p_employee_hr_id, '')), '') is null then
    return jsonb_build_object('applied', false, 'reason', 'missing_employee_hr_id');
  end if;

  select *
  into v_employee
  from public.employees
  where hr_id = upper(trim(p_employee_hr_id));

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'employee_not_found');
  end if;

  if lower(coalesce(v_employee.employment_status, 'active')) not in ('resigned', 'terminated', 'inactive') then
    return jsonb_build_object('applied', false, 'reason', 'employee_not_terminal');
  end if;

  -- NEW: is this footprint already held by someone still active? If so, the seat was backfilled
  -- before this terminal edit landed -- do not open or relink a vacancy against it.
  if v_employee.area_id is not null or v_employee.position_id is not null then
    select hr_id
    into v_occupant_hr_id
    from public.employees
    where hr_id <> v_employee.hr_id
      and lower(coalesce(employment_status, 'active')) = 'active'
      and area_id is not distinct from v_employee.area_id
      and line_id is not distinct from v_employee.line_id
      and position_id is not distinct from v_employee.position_id
    limit 1;

    if v_occupant_hr_id is not null then
      if to_regprocedure('public.phx_release_terminal_manager_ownership(text)') is not null then
        perform public.phx_release_terminal_manager_ownership(v_employee.hr_id);
      end if;

      return jsonb_build_object(
        'applied', false,
        'reason', 'seat_already_occupied',
        'employee_hr_id', v_employee.hr_id,
        'occupant_hr_id', v_occupant_hr_id
      );
    end if;
  end if;

  select full_name
  into v_manager_name
  from public.employees
  where hr_id = v_employee.manager_hr_id;

  v_effective_date := coalesce(
    v_employee.last_working_date,
    v_employee.resignation_date,
    v_employee.updated_at::date,
    v_employee.created_at::date,
    (now() at time zone 'Africa/Cairo')::date
  );

  select id
  into v_existing_vacancy_id
  from public.position_vacancies
  where lower(coalesce(status, 'open')) = 'open'
    and (
      replacement_for_hr_id = v_employee.hr_id
      or (
        nullif(trim(coalesce(replacement_for_hr_id, '')), '') is null
        and area_id is not distinct from v_employee.area_id
        and line_id is not distinct from v_employee.line_id
        and position_id is not distinct from v_employee.position_id
        and manager_hr_id is not distinct from v_employee.manager_hr_id
      )
    )
  order by
    case when replacement_for_hr_id = v_employee.hr_id then 0 else 1 end,
    created_at asc,
    id asc
  limit 1;

  if v_existing_vacancy_id is not null then
    update public.position_vacancies
    set
      area_id = v_employee.area_id,
      department_id = v_employee.department_id,
      job_title = v_employee.job_title,
      line_id = v_employee.line_id,
      manager_hr_id = v_employee.manager_hr_id,
      manager_name = v_manager_name,
      position_id = v_employee.position_id,
      region_name = v_employee.region_name,
      replacement_for_hr_id = v_employee.hr_id,
      note = case
        when coalesce(note, '') ilike '%Terminal employee vacancy guard:%' then note
        else concat_ws(
          E'\n',
          nullif(note, ''),
          'Terminal employee vacancy guard: linked open vacancy to terminal employee '
            || v_employee.hr_id || ' on ' || (now() at time zone 'Africa/Cairo')::date::text || '.'
        )
      end,
      updated_at = now()
    where id = v_existing_vacancy_id;
  else
    v_vacancy_code := 'VAC-TERM-'
      || regexp_replace(upper(v_employee.hr_id), '[^A-Z0-9]+', '', 'g')
      || '-'
      || substr(md5(v_employee.hr_id || '|' || coalesce(v_effective_date::text, (now() at time zone 'Africa/Cairo')::date::text)), 1, 6);

    -- Opening the vacancy is BEST-EFFORT from here down. The sub-block gives it its own
    -- subtransaction, so a refusal rolls back this insert alone and never the employee edit that
    -- fired the trigger. `on conflict` covers the deterministic-code collision (A);
    -- `when unique_violation` also catches phx_guard_single_open_rep_vacancy's RAISE (B), which
    -- uses that same errcode.
    begin
      insert into public.position_vacancies (
        area_id,
        created_at,
        department_id,
        job_title,
        line_id,
        manager_hr_id,
        manager_name,
        note,
        position_id,
        region_name,
        replacement_for_hr_id,
        status,
        updated_at,
        vacancy_code
      )
      values (
        v_employee.area_id,
        now(),
        v_employee.department_id,
        v_employee.job_title,
        v_employee.line_id,
        v_employee.manager_hr_id,
        v_manager_name,
        'Terminal employee vacancy guard: auto-opened from direct lifecycle edit for '
          || v_employee.full_name || ' (' || v_employee.hr_id || '). Effective '
          || coalesce(v_effective_date::text, (now() at time zone 'Africa/Cairo')::date::text) || '.',
        v_employee.position_id,
        v_employee.region_name,
        v_employee.hr_id,
        'open',
        now(),
        v_vacancy_code
      )
      on conflict (vacancy_code) do nothing
      returning id into v_existing_vacancy_id;
    exception
      when unique_violation then
        v_existing_vacancy_id := null;
        v_blocked_reason := 'vacancy_insert_blocked';
    end;

    if v_existing_vacancy_id is null then
      -- Nothing was opened, and that is correct in both cases:
      --   (A) the deterministic code is already held by this employee's own earlier vacancy,
      --       which a human has since cancelled or filled -- adopt it, never resurrect it;
      --   (B) the line/area already has its one permitted open medical-rep vacancy.
      -- Either way the caller's edit must still succeed.
      select id
      into v_existing_vacancy_id
      from public.position_vacancies
      where vacancy_code = v_vacancy_code;

      if v_existing_vacancy_id is not null then
        v_blocked_reason := coalesce(v_blocked_reason, 'existing_closed_vacancy');

        update public.position_vacancies
        set
          replacement_for_hr_id = coalesce(
            nullif(trim(coalesce(replacement_for_hr_id, '')), ''),
            v_employee.hr_id
          ),
          note = case
            when coalesce(note, '') ilike '%Terminal employee vacancy guard: closed vacancy%' then note
            else concat_ws(
              E'\n',
              nullif(note, ''),
              'Terminal employee vacancy guard: closed vacancy already covers terminal employee '
                || v_employee.hr_id || '; left as-is on '
                || (now() at time zone 'Africa/Cairo')::date::text || '.'
            )
          end,
          updated_at = now()
        where id = v_existing_vacancy_id;
      end if;

      if to_regprocedure('public.phx_release_terminal_manager_ownership(text)') is not null then
        perform public.phx_release_terminal_manager_ownership(v_employee.hr_id);
      end if;

      return jsonb_build_object(
        'applied', false,
        'reason', coalesce(v_blocked_reason, 'vacancy_insert_blocked'),
        'employee_hr_id', v_employee.hr_id,
        'vacancy_id', v_existing_vacancy_id,
        'vacancy_code', v_vacancy_code
      );
    end if;
  end if;

  if to_regprocedure('public.phx_release_terminal_manager_ownership(text)') is not null then
    perform public.phx_release_terminal_manager_ownership(v_employee.hr_id);
  end if;

  return jsonb_build_object(
    'applied', true,
    'employee_hr_id', v_employee.hr_id,
    'vacancy_id', v_existing_vacancy_id,
    'replacement_for_hr_id', v_employee.hr_id
  );
exception
  when undefined_column then
    raise notice 'Terminal employee vacancy guard skipped because expected lifecycle/vacancy columns are missing.';
    return jsonb_build_object('applied', false, 'reason', 'missing_schema_column');
end;
$$;

ALTER FUNCTION public.phx_ensure_terminal_employee_vacancy(p_employee_hr_id text) OWNER TO postgres;

--
-- Name: phx_exec_brick(text, text[], text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_exec_brick(p_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text], p_lines text[] DEFAULT NULL::text[], p_products text[] DEFAULT NULL::text[], p_regions text[] DEFAULT NULL::text[], p_areas text[] DEFAULT NULL::text[]) RETURNS TABLE(distributor_code text, region_code text, area_code text, brick_id text, units numeric, value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
#variable_conflict use_column
begin
  return query
  with period_price as (
    select d.product_code || '|' || d.period as pair,
           public.phx_factory_price(d.product_code, d.period) as period_price
    from (
      select distinct f.product_code, f.period
      from public.source_of_sales_fact_rollup f
      where (p_period is null or f.period = p_period)
    ) d
  )
  select
    f.distributor_code,
    f.region_code,
    f.area_code,
    f.brick_id,
    sum(f.total_qty)                                      as units,
    sum(f.effective_units * coalesce(pp.period_price, 0)) as value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b
    on b.id = f.batch_id and b.status = 'validated'
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  left join period_price pp
    on pp.pair = f.product_code || '|' || f.period
  where (p_period is null or f.period = p_period)
    and f.is_direct = false
    and (
      cardinality(p_exclude_codes) = 0
      or upper(btrim(coalesce(f.product_code, ''))) <> all (array(
           select upper(btrim(x)) from unnest(p_exclude_codes) as x))
    )
    and (p_lines    is null or f.official_line = any(p_lines))
    and (p_products is null or f.product_code  = any(p_products))
    and (p_regions  is null or f.region_code   = any(p_regions))
    and (p_areas    is null or f.area_code     = any(p_areas))
  group by f.distributor_code, f.region_code, f.area_code, f.brick_id;
end;
$$;

ALTER FUNCTION public.phx_exec_brick(p_period text, p_exclude_codes text[], p_lines text[], p_products text[], p_regions text[], p_areas text[]) OWNER TO postgres;

--
-- Name: phx_exec_customers(text, text[], text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_exec_customers(p_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text], p_lines text[] DEFAULT NULL::text[], p_products text[] DEFAULT NULL::text[], p_regions text[] DEFAULT NULL::text[], p_areas text[] DEFAULT NULL::text[]) RETURNS TABLE(client_code text, client_name text, distributor_code text, region_code text, area_code text, brick_id text, units numeric, value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    SET work_mem TO '96MB'
    AS $$
#variable_conflict use_column
begin
  return query
  with period_price as (
    select d.product_code || '|' || d.period as pair,
           public.phx_factory_price(d.product_code, d.period) as period_price
    from (
      select distinct r.product_code, r.period
      from public.source_of_sales_customer_directory_rollup r
      where (p_period is null or r.period = p_period)
      union
      select distinct f.product_code, f.period
      from public.source_of_sales_fact_rollup f
      where (p_period is null or f.period = p_period)
    ) d
  ),
  filtered as (
    select
      r.client_code, r.client_name, r.distributor_code, r.region_code, r.area_code, r.brick_id,
      r.latest_row_created_at, r.total_qty,
      case when r.is_direct then coalesce(r.direct_value, 0)
           else r.effective_units * coalesce(pp.period_price, 0) end as line_value
    from public.source_of_sales_customer_directory_rollup r
    join public.source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
    left join period_price pp on pp.pair = r.product_code || '|' || r.period
    where (p_period is null or r.period = p_period)
      and r.client_code is not null
      and (cardinality(p_exclude_codes) = 0
           or upper(btrim(coalesce(r.product_code, ''))) <> all (array(select upper(btrim(x)) from unnest(p_exclude_codes) as x)))
      and (p_lines    is null or r.official_line = any(p_lines))
      and (p_products is null or r.product_code  = any(p_products))
      and (p_regions  is null or r.region_code   = any(p_regions))
      and (p_areas    is null or r.area_code     = any(p_areas))
  ),
  latest as (
    select distinct on (client_code, distributor_code)
      client_code, distributor_code, client_name, region_code, area_code, brick_id
    from filtered
    order by client_code, distributor_code, latest_row_created_at desc
  ),
  agg as (
    select client_code, distributor_code, sum(total_qty) as units, sum(line_value) as value
    from filtered group by client_code, distributor_code
  ),
  office as (
    select
      'OFFICE'::text as client_code,
      'Office'::text as client_name,
      'Office'::text as distributor_code,
      null::text as region_code,
      null::text as area_code,
      null::text as brick_id,
      sum(f.total_qty) as units,
      sum(f.effective_units * coalesce(pp.period_price, 0)) as value
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b on b.id = f.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
    left join period_price pp on pp.pair = f.product_code || '|' || f.period
    where (p_period is null or f.period = p_period)
      and f.is_direct = false
      and upper(btrim(coalesce(f.distributor_code, ''))) = 'OFFICE'
      and (cardinality(p_exclude_codes) = 0
           or upper(btrim(coalesce(f.product_code, ''))) <> all (array(select upper(btrim(x)) from unnest(p_exclude_codes) as x)))
      and (p_lines    is null or f.official_line = any(p_lines))
      and (p_products is null or f.product_code  = any(p_products))
      and (p_regions  is null or f.region_code   = any(p_regions))
      and (p_areas    is null or f.area_code     = any(p_areas))
    having sum(f.total_qty) is not null
  )
  select a.client_code, l.client_name, a.distributor_code,
         l.region_code, l.area_code, l.brick_id, a.units, a.value
  from agg a join latest l using (client_code, distributor_code)
  union all
  select o.client_code, o.client_name, o.distributor_code,
         o.region_code, o.area_code, o.brick_id, o.units, o.value
  from office o;
end;
$$;

ALTER FUNCTION public.phx_exec_customers(p_period text, p_exclude_codes text[], p_lines text[], p_products text[], p_regions text[], p_areas text[]) OWNER TO postgres;

--
-- Name: phx_exec_distributor_product(text, text[], text[], text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_exec_distributor_product(p_period text DEFAULT NULL::text, p_lines text[] DEFAULT '{}'::text[], p_distributors text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[], p_areas text[] DEFAULT '{}'::text[], p_products text[] DEFAULT '{}'::text[], p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]) RETURNS TABLE(distributor_code text, official_line text, region_code text, area_code text, product_code text, product_name text, units numeric, value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
#variable_conflict use_column
begin
  if p_period is null then
    return query
    with period_price as (
      select d.product_code || '|' || d.period as pair,
             public.phx_factory_price(d.product_code, d.period) as period_price
      from (select distinct f.product_code, f.period from public.source_of_sales_fact_rollup f) d
    )
    select
      f.distributor_code,
      f.official_line,
      f.region_code,
      coalesce(nullif(f.area_code, ''), 'DIRECT') as area_code,
      f.product_code,
      max(f.product_name) as product_name,
      sum(f.total_qty) as units,
      sum(case when f.is_direct
               then f.direct_value
               else f.effective_units * coalesce(pp.period_price, 0) end) as value
    from public.source_of_sales_fact_rollup f
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
    left join period_price pp
      on pp.pair = f.product_code || '|' || f.period
    where (
        cardinality(p_lines) = 0
        or lower(btrim(coalesce(f.official_line, ''))) in (select lower(btrim(x)) from unnest(p_lines) as x)
      )
      and (
        cardinality(p_distributors) = 0
        or upper(btrim(coalesce(f.distributor_code, ''))) in (select upper(btrim(x)) from unnest(p_distributors) as x)
      )
      and (
        cardinality(p_regions) = 0
        or upper(btrim(coalesce(f.region_code, ''))) in (select upper(btrim(x)) from unnest(p_regions) as x)
      )
      and (
        cardinality(p_areas) = 0
        or upper(btrim(coalesce(nullif(f.area_code, ''), 'DIRECT'))) in (select upper(btrim(x)) from unnest(p_areas) as x)
      )
      and (
        cardinality(p_products) = 0
        or upper(btrim(coalesce(f.product_code, ''))) in (select upper(btrim(x)) from unnest(p_products) as x)
      )
      and (
        cardinality(p_exclude_codes) = 0
        or upper(btrim(coalesce(f.product_code, ''))) <> all (array(select upper(btrim(x)) from unnest(p_exclude_codes) as x))
      )
    group by f.distributor_code, f.official_line, f.region_code,
             coalesce(nullif(f.area_code, ''), 'DIRECT'), f.product_code;
  else
    return query
    with period_price as (
      select d.product_code || '|' || d.period as pair,
             public.phx_factory_price(d.product_code, d.period) as period_price
      from (
        select distinct f.product_code, f.period
        from public.source_of_sales_fact_rollup f
        where f.period = p_period
      ) d
    )
    select
      f.distributor_code,
      f.official_line,
      f.region_code,
      coalesce(nullif(f.area_code, ''), 'DIRECT') as area_code,
      f.product_code,
      max(f.product_name) as product_name,
      sum(f.total_qty) as units,
      sum(case when f.is_direct
               then f.direct_value
               else f.effective_units * coalesce(pp.period_price, 0) end) as value
    from public.source_of_sales_fact_rollup f
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
    left join period_price pp
      on pp.pair = f.product_code || '|' || f.period
    where f.period = p_period
      and (
        cardinality(p_lines) = 0
        or lower(btrim(coalesce(f.official_line, ''))) in (select lower(btrim(x)) from unnest(p_lines) as x)
      )
      and (
        cardinality(p_distributors) = 0
        or upper(btrim(coalesce(f.distributor_code, ''))) in (select upper(btrim(x)) from unnest(p_distributors) as x)
      )
      and (
        cardinality(p_regions) = 0
        or upper(btrim(coalesce(f.region_code, ''))) in (select upper(btrim(x)) from unnest(p_regions) as x)
      )
      and (
        cardinality(p_areas) = 0
        or upper(btrim(coalesce(nullif(f.area_code, ''), 'DIRECT'))) in (select upper(btrim(x)) from unnest(p_areas) as x)
      )
      and (
        cardinality(p_products) = 0
        or upper(btrim(coalesce(f.product_code, ''))) in (select upper(btrim(x)) from unnest(p_products) as x)
      )
      and (
        cardinality(p_exclude_codes) = 0
        or upper(btrim(coalesce(f.product_code, ''))) <> all (array(select upper(btrim(x)) from unnest(p_exclude_codes) as x))
      )
    group by f.distributor_code, f.official_line, f.region_code,
             coalesce(nullif(f.area_code, ''), 'DIRECT'), f.product_code;
  end if;
end;
$$;

ALTER FUNCTION public.phx_exec_distributor_product(p_period text, p_lines text[], p_distributors text[], p_regions text[], p_areas text[], p_products text[], p_exclude_codes text[]) OWNER TO postgres;

--
-- Name: phx_exec_distributor_product_bi(text, text[], text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_exec_distributor_product_bi(p_period text DEFAULT NULL::text, p_lines text[] DEFAULT '{}'::text[], p_distributors text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[], p_areas text[] DEFAULT '{}'::text[], p_products text[] DEFAULT '{}'::text[]) RETURNS TABLE(distributor_code text, official_line text, region_code text, area_code text, product_code text, product_name text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select *
  from public.phx_exec_distributor_product(
    p_period, p_lines, p_distributors, p_regions, p_areas, p_products,
    array['LA003', 'LA004', 'SS001']
  );
$$;

ALTER FUNCTION public.phx_exec_distributor_product_bi(p_period text, p_lines text[], p_distributors text[], p_regions text[], p_areas text[], p_products text[]) OWNER TO postgres;

--
-- Name: phx_exec_sos_trend(text[], text[], text[], text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_exec_sos_trend(p_periods text[] DEFAULT '{}'::text[], p_lines text[] DEFAULT '{}'::text[], p_distributors text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[], p_areas text[] DEFAULT '{}'::text[], p_products text[] DEFAULT '{}'::text[], p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]) RETURNS TABLE(period text, units numeric, value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
#variable_conflict use_column
declare
  -- Normalised ONCE, exactly as the old per-row sub-selects normalised them.
  v_lines         text[] := array(select lower(btrim(x)) from unnest(p_lines) as x);
  v_distributors  text[] := array(select upper(btrim(x)) from unnest(p_distributors) as x);
  v_regions       text[] := array(select upper(btrim(x)) from unnest(p_regions) as x);
  v_areas         text[] := array(select upper(btrim(x)) from unnest(p_areas) as x);
  v_products      text[] := array(select upper(btrim(x)) from unnest(p_products) as x);
  v_exclude_codes text[] := array(select upper(btrim(x)) from unnest(p_exclude_codes) as x);
begin
  if cardinality(p_lines) > 0 and not coalesce('' = any(v_lines), false) then
    -- Line-scoped and no blank line asked for: read only those lines' rows, on the line index.
    return query
    with g as (
      select
        f.period,
        f.official_line,
        case when cardinality(p_distributors) = 0 then null else f.distributor_code end as distributor_code,
        case when cardinality(p_regions) = 0 then null else f.region_code end as region_code,
        case when cardinality(p_areas) = 0 then null else f.area_code end as area_code,
        f.product_code,
        f.is_direct,
        sum(f.total_qty) as q,
        sum(f.effective_units) as eu,
        sum(f.direct_value) as dv
      from public.source_of_sales_fact_rollup f
      where lower(btrim(f.official_line)) = any (v_lines)
        and (cardinality(p_periods) = 0 or f.period = any (p_periods))
      group by 1, 2, 3, 4, 5, 6, 7
      offset 0 -- keeps the per-group predicates below from being pushed back down onto every row
    ),
    period_price as (
      select d.product_code, d.period,
             public.phx_factory_price(d.product_code, d.period) as period_price
      from (select distinct g.product_code, g.period from g) d
    )
    select
      g.period,
      sum(g.q) as units,
      sum(case when g.is_direct
               then g.dv
               else g.eu * coalesce(pp.period_price, 0) end) as value
    from g
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(g.product_code))
    left join period_price pp
      on pp.product_code = g.product_code and pp.period = g.period
    where (
        cardinality(p_lines) = 0
        or lower(btrim(coalesce(g.official_line, ''))) = any (v_lines)
      )
      and (
        cardinality(p_distributors) = 0
        or upper(btrim(coalesce(g.distributor_code, ''))) = any (v_distributors)
      )
      and (
        cardinality(p_regions) = 0
        or upper(btrim(coalesce(g.region_code, ''))) = any (v_regions)
      )
      and (
        cardinality(p_areas) = 0
        or upper(btrim(coalesce(nullif(g.area_code, ''), 'DIRECT'))) = any (v_areas)
      )
      and (
        cardinality(p_products) = 0
        or upper(btrim(coalesce(g.product_code, ''))) = any (v_products)
      )
      and (
        cardinality(p_exclude_codes) = 0
        or upper(btrim(coalesce(g.product_code, ''))) <> all (v_exclude_codes)
      )
    group by g.period;
  else
    return query
    with g as (
      select
        f.period,
        case when cardinality(p_lines) = 0 then null else f.official_line end as official_line,
        case when cardinality(p_distributors) = 0 then null else f.distributor_code end as distributor_code,
        case when cardinality(p_regions) = 0 then null else f.region_code end as region_code,
        case when cardinality(p_areas) = 0 then null else f.area_code end as area_code,
        f.product_code,
        f.is_direct,
        sum(f.total_qty) as q,
        sum(f.effective_units) as eu,
        sum(f.direct_value) as dv
      from public.source_of_sales_fact_rollup f
      where (cardinality(p_periods) = 0 or f.period = any (p_periods))
      group by 1, 2, 3, 4, 5, 6, 7
      offset 0 -- keeps the per-group predicates below from being pushed back down onto every row
    ),
    period_price as (
      select d.product_code, d.period,
             public.phx_factory_price(d.product_code, d.period) as period_price
      from (select distinct g.product_code, g.period from g) d
    )
    select
      g.period,
      sum(g.q) as units,
      sum(case when g.is_direct
               then g.dv
               else g.eu * coalesce(pp.period_price, 0) end) as value
    from g
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(g.product_code))
    left join period_price pp
      on pp.product_code = g.product_code and pp.period = g.period
    where (
        cardinality(p_lines) = 0
        or lower(btrim(coalesce(g.official_line, ''))) = any (v_lines)
      )
      and (
        cardinality(p_distributors) = 0
        or upper(btrim(coalesce(g.distributor_code, ''))) = any (v_distributors)
      )
      and (
        cardinality(p_regions) = 0
        or upper(btrim(coalesce(g.region_code, ''))) = any (v_regions)
      )
      and (
        cardinality(p_areas) = 0
        or upper(btrim(coalesce(nullif(g.area_code, ''), 'DIRECT'))) = any (v_areas)
      )
      and (
        cardinality(p_products) = 0
        or upper(btrim(coalesce(g.product_code, ''))) = any (v_products)
      )
      and (
        cardinality(p_exclude_codes) = 0
        or upper(btrim(coalesce(g.product_code, ''))) <> all (v_exclude_codes)
      )
    group by g.period;
  end if;
end;
$$;

ALTER FUNCTION public.phx_exec_sos_trend(p_periods text[], p_lines text[], p_distributors text[], p_regions text[], p_areas text[], p_products text[], p_exclude_codes text[]) OWNER TO postgres;

--
-- Name: phx_factory_price(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_factory_price(p_product_code text, p_period text) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select h.factory_price
       from public.source_of_sales_product_price_history h
      where upper(btrim(h.product_code)) = upper(btrim(p_product_code))
        and h.effective_period <= p_period
      order by h.effective_period desc
      limit 1),
    (select pr.factory_price
       from public.source_of_sales_products pr
      where upper(btrim(pr.product_code)) = upper(btrim(p_product_code))
      limit 1)
  );
$$;

ALTER FUNCTION public.phx_factory_price(p_product_code text, p_period text) OWNER TO postgres;

--
-- Name: FUNCTION phx_factory_price(p_product_code text, p_period text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_factory_price(p_product_code text, p_period text) IS 'The factory price that values one product in one period ''YYYY-MM''. Reads source_of_sales_product_price_history, falling back to source_of_sales_products.factory_price when no override covers that period. Added 2026-09-28 for the Saginko repricing, which the owner scoped to 1 October onward.';

--
-- Name: phx_finalize_sos_batch(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_finalize_sos_batch(p_batch_id uuid, p_distributor_code text, p_period text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
declare
  v_superseded jsonb;
  v_raw_count bigint;
  v_raw_units numeric;
  v_rollup_units numeric;
begin
  if not pg_try_advisory_xact_lock(hashtextextended(p_distributor_code || ':' || p_period, 0)) then
    raise exception 'Another upload for % / % is finalizing right now -- retry in a few seconds.', p_distributor_code, p_period
      using errcode = '55P03';
  end if;

  if to_regclass('public.monthly_sales_period_lock') is not null
     and exists (
       select 1 from public.monthly_sales_period_lock
       where period = p_period and locked = true
     ) then
    raise exception 'Period % is locked -- uploads and finalization are frozen until it is reopened.', p_period
      using errcode = '55P03';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'fileName', file_name,
    'distributorCode', distributor_code,
    'period', period,
    'status', status
  )), '[]'::jsonb)
  into v_superseded
  from public.source_of_sales_import_batches
  where distributor_code = p_distributor_code
    and period = p_period
    and id <> p_batch_id;

  delete from public.source_of_sales_import_batches
  where distributor_code = p_distributor_code
    and period = p_period
    and id <> p_batch_id;

  update public.source_of_sales_import_batches
  set status = 'validated', blocking_reasons = '{}'
  where id = p_batch_id;

  if not found then
    raise exception 'Batch % not found while finalizing.', p_batch_id;
  end if;

  perform public.phx_refresh_sos_fact_rollup(p_batch_id);
  perform public.phx_refresh_sos_customer_directory_rollup(p_batch_id);
  perform public.phx_refresh_marketing_roi_facts(p_batch_id);
  perform public.phx_refresh_sos_channel_rollup(p_batch_id);
  perform public.phx_refresh_sos_distributor_product_rollup(p_batch_id);
  perform public.phx_refresh_monthly_attribution(p_batch_id);
  perform public.phx_refresh_sos_import_summaries(p_batch_id);

  select count(*) into v_raw_count
  from public.source_of_sales_import_rows
  where batch_id = p_batch_id;

  select coalesce(sum(qty), 0) into v_raw_units
  from public.source_of_sales_import_rows
  where batch_id = p_batch_id
    and coalesce(validation_state, 'valid') <> 'failed';

  select coalesce(sum(total_qty), 0) into v_rollup_units
  from public.source_of_sales_fact_rollup
  where batch_id = p_batch_id;

  if round(v_raw_units, 4) <> round(v_rollup_units, 4) then
    raise exception 'Reconciliation failed for batch %: % raw units but % rolled up -- aborting.', p_batch_id, v_raw_units, v_rollup_units;
  end if;

  return jsonb_build_object('supersededBatches', v_superseded, 'rowCount', v_raw_count);
end;
$$;

ALTER FUNCTION public.phx_finalize_sos_batch(p_batch_id uuid, p_distributor_code text, p_period text) OWNER TO postgres;

--
-- Name: phx_finance_command_center(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_finance_command_center(p_actor_hr_id text DEFAULT NULL::text, p_trend_months integer DEFAULT 6) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '20s'
    AS $$
declare
  v_actor      text := nullif(btrim(coalesce(p_actor_hr_id, '')), '');
  v_months     int  := greatest(1, least(24, coalesce(p_trend_months, 6)));
  -- The current Cairo month as a HALF-OPEN interval [start, next). Resolved once so the two
  -- leaver counters below cannot drift apart, and so neither can be written with only one end.
  v_month_start date := date_trunc('month', (now() at time zone 'Africa/Cairo'))::date;
  v_month_next  date := (date_trunc('month', (now() at time zone 'Africa/Cairo')) + interval '1 month')::date;
  v_headcount  jsonb;
  v_parts      jsonb;
  v_channels   jsonb;
  v_committed  jsonb;
  v_runs       jsonb;
  v_direct     jsonb;
  v_marketing  jsonb;
  v_leave      jsonb;
begin
  -- Headcount, plus the two leaver figures finance needs before it can close a month: who resigned
  -- inside the current Cairo month, and whose last working day falls in it. The month boundary is
  -- taken in Africa/Cairo, never UTC — a resignation logged late on the 31st is this month's, and
  -- at UTC it would land in the next one.
  --
  -- BOTH ENDS, always. A notice period means these columns are routinely dated into the FUTURE,
  -- so a lower bound on its own quietly turns "this month" into "from this month onward".
  select jsonb_build_object(
           'activeEmployees',    count(*) filter (where lower(coalesce(employment_status, '')) in ('active', 'on_leave')),
           'payrollEligible',    count(*) filter (where payroll_eligible),
           'standingNet',        round(coalesce(sum(net_salary)   filter (where payroll_eligible), 0)::numeric, 2),
           'standingGross',      round(coalesce(sum(gross_salary) filter (where payroll_eligible), 0)::numeric, 2),
           'resignedThisMonth',  count(*) filter (where resignation_date  >= v_month_start and resignation_date  < v_month_next),
           'leavingThisMonth',   count(*) filter (where last_working_date >= v_month_start and last_working_date < v_month_next),
           'leaversTotal',       count(*) filter (where lower(coalesce(employment_status, '')) in ('resigned', 'terminated'))
         )
    into v_headcount
    from public.employees;

  -- First payment vs second. NULL folds into two_parts to match normalizePayrollPaymentMode.
  select jsonb_build_object(
           'firstOnlyCount', count(*) filter (where lower(coalesce(payment_mode, '')) = 'one_part'),
           'firstOnlyNet',   round(coalesce(sum(net_salary) filter (where lower(coalesce(payment_mode, '')) = 'one_part'), 0)::numeric, 2),
           'bothPartsCount', count(*) filter (where lower(coalesce(payment_mode, '')) <> 'one_part'),
           'bothPartsNet',   round(coalesce(sum(net_salary) filter (where lower(coalesce(payment_mode, '')) <> 'one_part'), 0)::numeric, 2)
         )
    into v_parts
    from public.employees
    where payroll_eligible;

  -- FAB / CIB / Treasury. Exhaustive and non-overlapping: anyone not on a named bank is Treasury.
  select jsonb_build_object(
           'fabCount',      count(*) filter (where upper(coalesce(bank_name, '')) = 'FAB'),
           'fabNet',        round(coalesce(sum(net_salary) filter (where upper(coalesce(bank_name, '')) = 'FAB'), 0)::numeric, 2),
           'cibCount',      count(*) filter (where upper(coalesce(bank_name, '')) = 'CIB'),
           'cibNet',        round(coalesce(sum(net_salary) filter (where upper(coalesce(bank_name, '')) = 'CIB'), 0)::numeric, 2),
           'treasuryCount', count(*) filter (where upper(coalesce(bank_name, '')) not in ('FAB', 'CIB')),
           'treasuryNet',   round(coalesce(sum(net_salary) filter (where upper(coalesce(bank_name, '')) not in ('FAB', 'CIB')), 0)::numeric, 2)
         )
    into v_channels
    from public.employees
    where payroll_eligible;

  -- Net and gross only. No deduction columns are selected at all.
  --
  -- ONE ROW PER MONTH, and the grouping key says so. `status` is a batch ATTRIBUTE, not part of
  -- the period this trend is keyed on, so it is aggregated rather than grouped: three consumers
  -- break silently the moment a month yields two rows — the chart keys its bars on `period`, the
  -- month-over-month delta chain compares each entry with the one before it, and the "Net payroll"
  -- tile reads the LAST entry. salary_batches carries a UNIQUE index on (year, month), so this was
  -- safe in practice — but it was safe because of a constraint declared in another file, which is
  -- not something a money figure should depend on silently.
  select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.period), '[]'::jsonb)
    into v_committed
    from (
      select
        to_char(make_date(b.year, b.month, 1), 'YYYY-MM')            as period,
        -- Exact today (one batch per month), and honest if that ever stops being true: two
        -- statuses in one month read "approved + locked" rather than silently picking one.
        string_agg(distinct b.status, ' + ' order by b.status)       as status,
        count(r.*)                                                   as employees,
        round(coalesce(sum(r.net_salary), 0)::numeric, 2)            as net,
        round(coalesce(sum(r.gross_salary), 0)::numeric, 2)          as gross
      from public.salary_batches b
      join public.salary_records r on r.batch_id = b.id
      group by b.year, b.month
      order by b.year desc, b.month desc
      limit v_months
    ) t;

  select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.month_key desc), '[]'::jsonb)
    into v_runs
    from (
      select
        r.month_key                                                                    as month_key,
        r.phase                                                                        as phase,
        (r.part1_confirmed_at is not null)                                             as part1_confirmed,
        (r.part2_confirmed_at is not null)                                             as part2_confirmed,
        (r.published_at is not null)                                                   as published,
        r.part2_confirmed_at                                                           as part2_confirmed_at,
        count(d.*) filter (where not coalesce(d.excluded, false))                      as rows_in_run,
        -- Held rows are IN the run but excluded from the payout, so they never reach a bank file.
        -- Finance has to clear them before a month can close, and nothing else on his page would
        -- tell him they exist.
        count(d.*) filter (where coalesce(d.on_hold, false) and not coalesce(d.excluded, false))  as on_hold_count,
        round(coalesce(sum(case when coalesce(d.excluded, false) then 0 else coalesce(d.expenses, 0) end), 0)::numeric, 2)  as expenses_paid,
        round(coalesce(sum(case when coalesce(d.excluded, false) then 0 else coalesce(d.incentive, 0) end), 0)::numeric, 2) as incentive
      from public.automated_payroll_runs r
      left join public.automated_payroll_draft_rows d on d.run_id = r.id
      group by r.month_key, r.phase, r.part1_confirmed_at, r.part2_confirmed_at, r.published_at
      order by r.month_key desc
      limit 6
    ) t;

  select jsonb_build_object(
           'awaitingCount',  count(*) filter (where lower(coalesce(status, '')) = 'approved' and sales_month is null),
           'awaitingValue',  round(coalesce(sum(sales_value) filter (where lower(coalesce(status, '')) = 'approved' and sales_month is null), 0)::numeric, 2),
           'awaitingOldest', min(decided_at) filter (where lower(coalesce(status, '')) = 'approved' and sales_month is null),
           'approvedCount',  count(*) filter (where lower(coalesce(status, '')) = 'approved'),
           'approvedValue',  round(coalesce(sum(sales_value) filter (where lower(coalesce(status, '')) = 'approved'), 0)::numeric, 2),
           'bookedCount',    count(*) filter (where sales_month is not null),
           'bookedValue',    round(coalesce(sum(sales_value) filter (where sales_month is not null), 0)::numeric, 2),
           'injectedCount',  count(*) filter (where sos_batch_id is not null),
           'collectedCount', count(*) filter (where payment_date is not null),
           'paidTotal',      round(coalesce(sum(paid_amount), 0)::numeric, 2),
           'remainingTotal', round(coalesce(sum(remaining_amount), 0)::numeric, 2),
           'pendingCount',   count(*) filter (where lower(coalesce(status, '')) = 'pending_approval'),
           'pendingValue',   round(coalesce(sum(sales_value) filter (where lower(coalesce(status, '')) = 'pending_approval'), 0)::numeric, 2),
           'heldCount',      count(*) filter (where lower(coalesce(status, '')) in ('held', 'expired')),
           'heldValue',      round(coalesce(sum(sales_value) filter (where lower(coalesce(status, '')) in ('held', 'expired')), 0)::numeric, 2),
           'byStatus',       coalesce((
             select jsonb_agg(jsonb_build_object('status', s.status, 'count', s.c, 'value', s.v) order by s.c desc)
             from (
               select lower(coalesce(status, 'unknown')) as status, count(*) as c,
                      round(coalesce(sum(sales_value), 0)::numeric, 2) as v
               from public.direct_order_requests group by 1
             ) s
           ), '[]'::jsonb)
         )
    into v_direct
    from public.direct_order_requests;

  select jsonb_build_object(
           'awaitingMyStep', (
             select count(*)
             from public.marketing_request_approval_steps s
             where v_actor is not null
               and upper(coalesce(s.assigned_hr_id, '')) = upper(v_actor)
               and coalesce(s.is_cc, false) = false
               and lower(coalesce(s.status, '')) = 'current'
           ),
           'approvedCount',   count(*) filter (where lower(coalesce(status, '')) in ('approved', 'active', 'roi_tracking', 'finance_hold')),
           'committedSpend',  round(coalesce(sum(estimated_cost) filter (where lower(coalesce(status, '')) in ('approved', 'active', 'roi_tracking', 'finance_hold')), 0)::numeric, 2),
           'requiredRoi',     round(coalesce(sum(required_roi_value) filter (where lower(coalesce(status, '')) in ('approved', 'active', 'roi_tracking', 'finance_hold')), 0)::numeric, 2),
           'executedCount',   count(*) filter (where executed_at is not null),
           'dueUnexecutedCount', count(*) filter (where lower(coalesce(status, '')) in ('approved', 'active', 'finance_hold') and pay_date is not null and executed_at is null),
           'dueUnexecutedValue', round(coalesce(sum(estimated_cost) filter (where lower(coalesce(status, '')) in ('approved', 'active', 'finance_hold') and pay_date is not null and executed_at is null), 0)::numeric, 2),
           'dueOldest',       min(pay_date) filter (where lower(coalesce(status, '')) in ('approved', 'active', 'finance_hold') and pay_date is not null and executed_at is null),
           'inApprovalCount', count(*) filter (where lower(coalesce(status, '')) = 'pending_approval'),
           'missingPaymentProof', (
             select count(*)
             from public.marketing_requests m
             join public.marketing_request_approval_steps s
               on s.request_id = m.id and s.step_kind = 'finance' and coalesce(s.is_cc, false) = false
             left join public.marketing_request_finance_requirements f on f.request_id = m.id
             where lower(coalesce(m.status, '')) in ('approved', 'active', 'roi_tracking', 'finance_hold')
               and f.money_transfer_proof_storage_path is null
               -- A request settled against a direct order's debt moved no money, so there is no
               -- transfer to prove. The offset row is its own record (direct_order_marketing_offsets).
               and not exists (select 1 from public.direct_order_marketing_offsets o where o.marketing_request_id = m.id)
           ),
           'missingInvoice', (
             select count(*)
             from public.marketing_requests m
             join public.marketing_request_approval_steps s
               on s.request_id = m.id and s.step_kind = 'finance' and coalesce(s.is_cc, false) = false
             left join public.marketing_request_finance_requirements f on f.request_id = m.id
             where lower(coalesce(m.status, '')) in ('approved', 'active', 'roi_tracking', 'finance_hold')
               and f.invoice_storage_path is null
           ),
           -- The three below are the ONLY figures on this page that read invoice_deadline_date.
           -- See the PREDICATE PARITY note in the header before changing either condition.
           'invoiceOverdueCount', (
             select count(*)
             from public.marketing_request_finance_requirements f
             where lower(coalesce(f.invoice_status, '')) = 'pending'
               and f.invoice_deadline_date is not null
               and f.invoice_deadline_date < (now() at time zone 'Africa/Cairo')::date
           ),
           'invoiceOverdueValue', (
             select round(coalesce(sum(m.estimated_cost), 0)::numeric, 2)
             from public.marketing_request_finance_requirements f
             join public.marketing_requests m on m.id = f.request_id
             where lower(coalesce(f.invoice_status, '')) = 'pending'
               and f.invoice_deadline_date is not null
               and f.invoice_deadline_date < (now() at time zone 'Africa/Cairo')::date
           ),
           -- The deadline that has been outstanding longest -- what makes the queue's AGE readable
           -- without opening it, the same job dueOldest does for the unexecuted queue beside it.
           'invoiceOverdueOldest', (
             select min(f.invoice_deadline_date)
             from public.marketing_request_finance_requirements f
             where lower(coalesce(f.invoice_status, '')) = 'pending'
               and f.invoice_deadline_date is not null
               and f.invoice_deadline_date < (now() at time zone 'Africa/Cairo')::date
           )
         )
    into v_marketing
    from public.marketing_requests;

  select jsonb_build_object(
           'awaitingMyDecision', (
             select count(*)
             from public.v2_vacation_approval_steps s
             join public.v2_vacation_requests v on v.id = s.request_id
             where v_actor is not null
               and upper(coalesce(s.approver_hr_id, '')) = upper(v_actor)
               and lower(coalesce(s.status, '')) = 'pending'
               and lower(coalesce(v.status, '')) in ('pending_manager', 'pending_hr', 'needs_assignment')
           )
         )
    into v_leave;

  return jsonb_build_object(
    'generatedAt',  now(),
    'headcount',    v_headcount,
    'payroll',      jsonb_build_object(
                      'committed', v_committed,
                      'runs',      v_runs,
                      'parts',     v_parts,
                      'channels',  v_channels
                    ),
    'directOrders', v_direct,
    'marketing',    v_marketing,
    'leave',        v_leave
  );
end;
$$;

ALTER FUNCTION public.phx_finance_command_center(p_actor_hr_id text, p_trend_months integer) OWNER TO postgres;

--
-- Name: FUNCTION phx_finance_command_center(p_actor_hr_id text, p_trend_months integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_finance_command_center(p_actor_hr_id text, p_trend_months integer) IS 'Finance Manager landing dashboard payload in ONE round trip: headcount, the payout split (first vs second payment, FAB/CIB/Treasury), the direct-order money pipeline, marketing spend/execution/ROI including invoices past their deadline, and his leave queue. Carries NO deduction figures by design.';

--
-- Name: phx_fold_customer_name(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_fold_customer_name(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select btrim(regexp_replace(
           lower(translate(
             replace(replace(replace(replace(replace(replace(replace(replace(
               regexp_replace(coalesce(p_name, ''), '[ً-ْـٰ]', '', 'g'),
               'ﻵ', 'لا'), 'ﻶ', 'لا'), 'ﻷ', 'لا'), 'ﻸ', 'لا'),
               'ﻹ', 'لا'), 'ﻺ', 'لا'), 'ﻻ', 'لا'), 'ﻼ', 'لا'),
             'أإآٱةىیک', 'ااااهييك')),
           '\s+', ' ', 'g'));
$$;

ALTER FUNCTION public.phx_fold_customer_name(p_name text) OWNER TO postgres;

--
-- Name: FUNCTION phx_fold_customer_name(p_name text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_fold_customer_name(p_name text) IS 'Customer name folded for comparison: harakat stripped, interchangeable letters unified, lam-alef ligatures expanded, latin lowercased, whitespace collapsed. Mirrors normalizeCustomerName() in src/lib/sales/customer-channel.ts.';

--
-- Name: phx_freeze_even_split_roster(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_freeze_even_split_roster(p_period text, p_actor text DEFAULT 'system'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_start   date := to_date(p_period || '-01', 'YYYY-MM-DD');
  v_end     date := (date_trunc('month', to_date(p_period || '-01','YYYY-MM-DD')) + interval '1 month - 1 day')::date;
  v_written integer := 0;
  c         record;
begin
  for c in select * from public.sos_even_split_customers where active loop
    -- Already frozen → leave it exactly as it is.
    if exists (
      select 1 from public.sos_even_split_roster r
      where r.period = p_period
        and r.client_code = c.client_code
        and r.official_line = c.official_line
    ) then
      continue;
    end if;

    insert into public.sos_even_split_roster
      (period, client_code, official_line, area_code, region_code,
       rep_hr_id, rep_name, landing_brick_id, frozen_by)
    select
      p_period, c.client_code, c.official_line,
      a.code, coalesce(lb.region_code, left(a.code, 2)),
      e.hr_id, e.full_name, lb.brick_id, p_actor
    from public.employees e
    join public.areas a on a.id = e.area_id
    join public.lines l on l.id = e.line_id
    left join lateral (
      select x.brick_id, x.region_code
      from (
        select r.brick_id, r.region_code, sum(r.qty) as units
        from public.source_of_sales_import_rows r
        join public.source_of_sales_import_batches b
          on b.id = r.batch_id and b.status = 'validated'
        where upper(btrim(coalesce(r.official_line,''))) = upper(c.official_line)
          and r.distributor_code <> 'Office'
          and coalesce(r.is_direct, false) = false
          and coalesce(btrim(r.brick_id), '') <> ''
          and r.area_code = a.code
        group by r.brick_id, r.region_code
      ) x
      order by x.units desc, x.brick_id
      limit 1
    ) lb on true
    where upper(btrim(l.name)) = upper(c.official_line)
      and e.job_title ilike '%rep%'
      and a.code like any (select p || '%' from unnest(c.area_prefixes) p)
      and e.hire_date is not null
      and e.hire_date <= v_end
      and (e.resignation_date is null or e.resignation_date >= v_start)
      and lb.brick_id is not null;

    get diagnostics v_written = row_count;
  end loop;

  return v_written;
end;
$$;

ALTER FUNCTION public.phx_freeze_even_split_roster(p_period text, p_actor text) OWNER TO postgres;

--
-- Name: FUNCTION phx_freeze_even_split_roster(p_period text, p_actor text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_freeze_even_split_roster(p_period text, p_actor text) IS 'Resolve and FREEZE the even-split roster for one period. No-op if already frozen — a settled month never re-splits.';

--
-- Name: phx_freeze_published_closing(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_freeze_published_closing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Only a LIVE publication freezes. A row arriving already-withdrawn (a backfill, a correction)
  -- is a record of history, not an act of publishing.
  if new.unpublished_at is not null then
    return null;
  end if;

  -- Idempotent: one ACTIVE lock per (line, period) is a unique index, and a re-publish must not
  -- try to take a second one. An already-locked month is the normal case here.
  if exists (
    select 1
      from public.monthly_closing_locks l
     where l.normalized_line = new.normalized_line
       and l.period = new.period
       and l.unlocked_at is null
  ) then
    return null;
  end if;

  perform public.phx_lock_monthly_closing(
    p_line   => new.line,
    p_period => new.period,
    p_actor  => coalesce(new.published_by, 'published')
  );

  return null;
end;
$$;

ALTER FUNCTION public.phx_freeze_published_closing() OWNER TO postgres;

--
-- Name: FUNCTION phx_freeze_published_closing(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_freeze_published_closing() IS 'Locks (line, period) the moment its closing is published, so a published month cannot be moved by a re-import, a migration, ad-hoc SQL or a direct-order booking. Unpublishing does not undo it — release is only ever phx_unlock_monthly_closing, with a reason.';

--
-- Name: phx_guard_single_open_rep_vacancy(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_guard_single_open_rep_vacancy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_position_code text;
  v_existing text;
begin
  if lower(coalesce(new.status, 'open')) <> 'open' then
    return new;
  end if;
  if tg_op = 'UPDATE' and lower(coalesce(old.status, 'open')) = 'open' then
    return new;
  end if;
  if new.line_id is null or new.area_id is null then
    return new;
  end if;

  select p.code into v_position_code from public.positions p where p.id = new.position_id;
  if coalesce(v_position_code, '') <> 'medical_representative' then
    return new;
  end if;

  select string_agg(coalesce(pv.vacancy_code, pv.id::text), ', ' order by pv.id)
    into v_existing
    from public.position_vacancies pv
    join public.positions p2 on p2.id = pv.position_id
   where lower(coalesce(pv.status, 'open')) = 'open'
     and pv.line_id = new.line_id
     and pv.area_id = new.area_id
     and p2.code = 'medical_representative'
     and pv.id is distinct from new.id;

  if v_existing is not null then
    raise exception 'vacancy: an open medical-rep vacancy already exists for this line/area (%) - close or cancel it before opening another, or the hire autofill will match neither', v_existing
      using errcode = 'unique_violation';
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_guard_single_open_rep_vacancy() OWNER TO postgres;

--
-- Name: phx_hire_into_seat_on_vacancy_filled(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_hire_into_seat_on_vacancy_filled() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_predecessor_hr_id text := nullif(btrim(old.replacement_for_hr_id), '');
  v_new_hr_id         text := nullif(btrim(new.filled_by_hr_id), '');
  v_seat_id           text;
  v_resolved_by       text;
  v_line_code         text;
  v_area_code         text;
  v_position_code     text;
  v_match_count       integer := 0;
  v_existing_seats    text;
  v_fill_day          date := coalesce(
    (new.filled_at at time zone 'Africa/Cairo')::date,
    (now() at time zone 'Africa/Cairo')::date
  );
  v_hire_date         date;
  v_created_day       date;
  v_has_accepted_offer boolean := false;
  v_effective_date    date;
  v_date_source       text;
begin
  if v_new_hr_id is null then
    return new;
  end if;

  v_seat_id := nullif(btrim(coalesce(new.seat_id, '')), '');
  if v_seat_id is not null then
    v_resolved_by := 'vacancy_seat_id';
  end if;

  if v_seat_id is null and v_predecessor_hr_id is not null then
    v_seat_id := au.f_last_occupied_seat_by_hr_id(v_predecessor_hr_id);
    if v_seat_id is not null then
      v_resolved_by := 'predecessor_seat';
    end if;
  end if;

  if v_seat_id is null then
    select l.code into v_line_code from public.lines l where l.id = new.line_id;
    select a.code into v_area_code from public.areas a where a.id = new.area_id;
    select p.code into v_position_code from public.positions p where p.id = new.position_id;

    if v_position_code = 'medical_representative'
       and v_line_code is not null and v_area_code is not null then
      select count(*), min(s.seat_id)
        into v_match_count, v_seat_id
        from au.seats s
       where s.seat_tier = 'REP' and s.is_active and s.effective_to is null
         and s.line_code = v_line_code and s.area_code = v_area_code
         and not exists (
           select 1 from au.occupancy_history o
            where o.seat_id = s.seat_id and o.effective_to is null and o.occupant_hr_id is not null);

      if v_match_count = 1 then
        v_resolved_by := 'line_area_match';
      else
        v_seat_id := null;
      end if;
    end if;
  end if;

  if v_seat_id is null then
    begin
      insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, new_values)
      values ('system', 'au_seat_hire_unresolved', v_new_hr_id,
        format('No au seat resolved for %s via vacancy %s - they will not appear on the organogram until a seat is assigned',
          v_new_hr_id, coalesce(new.vacancy_code, new.id::text)),
        jsonb_build_object('vacancyId', new.id, 'vacancyCode', new.vacancy_code,
          'predecessorHrId', v_predecessor_hr_id, 'lineCode', v_line_code, 'areaCode', v_area_code,
          'positionCode', v_position_code, 'candidateSeatMatches', v_match_count));
    exception when others then null;
    end;
    return new;
  end if;

  select string_agg(oh.seat_id, ', ' order by oh.seat_id)
    into v_existing_seats
    from au.occupancy_history oh
   where oh.occupant_canonical_hr_id = lower(v_new_hr_id)
     and oh.effective_to is null and oh.occupant_hr_id is not null;
  if v_existing_seats is not null then
    if v_existing_seats = v_seat_id then
      begin
        insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, new_values)
        values ('system', 'au_seat_hire', v_new_hr_id,
          format('%s already occupies au seat %s - vacancy %s closed with no seat change',
            v_new_hr_id, v_seat_id, coalesce(new.vacancy_code, new.id::text)),
          jsonb_build_object('seatId', v_seat_id, 'vacancyId', new.id, 'vacancyCode', new.vacancy_code,
            'resolvedBy', coalesce(v_resolved_by, 'unknown'), 'noop', true));
      exception when others then null;
      end;
    else
      begin
        insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, new_values)
        values ('system', 'au_seat_hire_blocked', v_new_hr_id,
          format('BLOCKED: %s already occupies seat(s) %s - refused to also seat them on %s via vacancy %s. Use the Transfer Seat action to move them instead.',
            v_new_hr_id, v_existing_seats, v_seat_id, coalesce(new.vacancy_code, new.id::text)),
          jsonb_build_object('targetSeatId', v_seat_id, 'existingSeatIds', v_existing_seats,
            'vacancyId', new.id, 'vacancyCode', new.vacancy_code,
            'predecessorHrId', v_predecessor_hr_id, 'resolvedBy', coalesce(v_resolved_by, 'unknown')));
      exception when others then null;
      end;
    end if;
    return new;
  end if;

  -- The seat starts on the Master's hire date, which is the job offer's start date. A date before the
  -- fill day is honoured only for someone arriving through this fill: a long-standing employee moved into
  -- a vacant seat took it on the fill day, and their hire date of years ago must not backdate it.
  begin
    select e.hire_date, (e.created_at at time zone 'Africa/Cairo')::date
      into v_hire_date, v_created_day
      from public.employees e
     where lower(btrim(e.hr_id)) = lower(v_new_hr_id)
     limit 1;

    select exists (
      select 1 from public.offers o
       where lower(btrim(o.employee_hr_id)) = lower(v_new_hr_id) and o.status = 'accepted'
    ) into v_has_accepted_offer;

    if v_hire_date is null then
      v_effective_date := v_fill_day;
      v_date_source := 'fill_day_no_hire_date';
    elsif v_hire_date >= v_fill_day or v_created_day >= v_fill_day or v_has_accepted_offer then
      v_effective_date := v_hire_date;
      v_date_source := 'employee_hire_date';
    else
      v_effective_date := v_fill_day;
      v_date_source := 'fill_day_long_standing_employee';
    end if;
  exception when others then
    v_effective_date := v_fill_day;
    v_date_source := 'fill_day_hire_date_read_failed';
  end;

  begin
    perform au.hire_into_seat(v_seat_id, v_new_hr_id, v_effective_date, 'vacancy_fill_trigger');
    insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, new_values)
    values ('system', 'au_seat_hire', v_new_hr_id,
      format('Auto-hired into au seat %s via vacancy %s (resolved by %s)',
        v_seat_id, coalesce(new.vacancy_code, new.id::text), v_resolved_by),
      jsonb_build_object('seatId', v_seat_id, 'predecessorHrId', v_predecessor_hr_id,
        'vacancyId', new.id, 'vacancyCode', new.vacancy_code, 'resolvedBy', v_resolved_by,
        'effectiveDate', v_effective_date, 'dateSource', v_date_source));
  exception when others then
    raise warning 'phx_hire_into_seat_on_vacancy_filled: au.hire_into_seat(%, %) failed: %',
      v_seat_id, v_new_hr_id, sqlerrm;
    begin
      insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, new_values)
      values ('system', 'au_seat_hire_failed', v_new_hr_id,
        format('Failed to auto-hire into au seat %s (resolved by %s): %s',
          v_seat_id, coalesce(v_resolved_by, 'unknown'), sqlerrm),
        jsonb_build_object('seatId', v_seat_id, 'predecessorHrId', v_predecessor_hr_id,
          'vacancyId', new.id, 'resolvedBy', v_resolved_by, 'error', sqlerrm));
    exception when others then null;
    end;
  end;

  return new;
end;
$$;

ALTER FUNCTION public.phx_hire_into_seat_on_vacancy_filled() OWNER TO postgres;

--
-- Name: FUNCTION phx_hire_into_seat_on_vacancy_filled(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_hire_into_seat_on_vacancy_filled() IS 'Trigger on public.position_vacancies: when a REPLACEMENT vacancy (replacement_for_hr_id set) transitions to status=filled, hires filled_by_hr_id into the departed predecessors last au seat via au.hire_into_seat. No-ops (not an error) for brand-new headcount or a predecessor with no au seat. Never raises - a failure is caught, warned, and written to public.audit_logs so it can never block the vacancy-fill transaction.';

--
-- Name: phx_hr_clearance_decide(uuid, text, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_hr_clearance_decide(p_item_id uuid, p_status text, p_actor text, p_reason text DEFAULT NULL::text, p_evidence_note text DEFAULT NULL::text, p_amount_due numeric DEFAULT NULL::numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_checklist_id uuid;
  v_checklist    text;
begin
  if p_status not in ('pending', 'cleared', 'blocked', 'waived') then
    raise exception 'Unknown clearance status "%".', p_status;
  end if;

  if p_status in ('blocked', 'waived') and coalesce(btrim(p_reason), '') = '' then
    raise exception 'A % decision needs a written reason.', p_status;
  end if;

  select i.checklist_id, c.status into v_checklist_id, v_checklist
  from public.hr_clearance_items i
  join public.hr_clearance_checklists c on c.id = i.checklist_id
  where i.id = p_item_id;

  if v_checklist_id is null then
    raise exception 'Clearance item % does not exist.', p_item_id;
  end if;

  -- A released checklist is the evidence behind a settlement that has already gone out. Editing it
  -- afterwards would rewrite the record the release was justified by.
  if v_checklist in ('released', 'cancelled') then
    raise exception 'This clearance is % and can no longer be edited.', v_checklist;
  end if;

  update public.hr_clearance_items
  set status = p_status,
      reason = case when p_status in ('blocked', 'waived') then btrim(p_reason) else null end,
      evidence_note = p_evidence_note,
      amount_due = case when p_status = 'blocked' then p_amount_due else null end,
      decided_at = case when p_status = 'pending' then null else now() end,
      decided_by = case when p_status = 'pending' then null else p_actor end,
      updated_at = now()
  where id = p_item_id;

  return public.phx_hr_clearance_refresh_status(v_checklist_id);
end;
$$;

ALTER FUNCTION public.phx_hr_clearance_decide(p_item_id uuid, p_status text, p_actor text, p_reason text, p_evidence_note text, p_amount_due numeric) OWNER TO postgres;

--
-- Name: phx_hr_clearance_open(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_hr_clearance_open(p_resignation_id uuid, p_actor text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_checklist_id uuid;
  v_res          record;
begin
  select r.id, r.employee_hr_id, r.employee_name, r.job_title, r.line_name, r.last_working_date
    into v_res
  from public.employee_resignations r
  where r.id = p_resignation_id;

  if v_res.id is null then
    raise exception 'Resignation % does not exist.', p_resignation_id;
  end if;

  insert into public.hr_clearance_checklists (
    resignation_id, employee_hr_id, employee_name, job_title, line_name, last_working_date, opened_by
  )
  values (
    v_res.id, v_res.employee_hr_id, v_res.employee_name, v_res.job_title, v_res.line_name,
    v_res.last_working_date, p_actor
  )
  on conflict (resignation_id) do nothing;

  select id into v_checklist_id
  from public.hr_clearance_checklists
  where resignation_id = p_resignation_id;

  -- Every active station this checklist does not already carry. `on conflict do nothing` covers
  -- the concurrent case and keeps a decided item from being reset to pending.
  insert into public.hr_clearance_items (checklist_id, station_key, station_label, sort_order)
  select v_checklist_id, s.station_key, s.label, s.sort_order
  from public.hr_clearance_stations s
  where s.is_active = true
  on conflict (checklist_id, station_key) do nothing;

  perform public.phx_hr_clearance_refresh_status(v_checklist_id);

  return v_checklist_id;
end;
$$;

ALTER FUNCTION public.phx_hr_clearance_open(p_resignation_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: phx_hr_clearance_refresh_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_hr_clearance_refresh_status(p_checklist_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_current    text;
  v_undecided  integer;
  v_next       text;
begin
  select status into v_current
  from public.hr_clearance_checklists
  where id = p_checklist_id
  for update;

  if v_current is null then
    raise exception 'Clearance checklist % does not exist.', p_checklist_id;
  end if;

  if v_current in ('released', 'cancelled') then
    return v_current;
  end if;

  select count(*) into v_undecided
  from public.hr_clearance_items
  where checklist_id = p_checklist_id
    and status in ('pending', 'blocked');

  v_next := case when v_undecided = 0 then 'ready' else 'open' end;

  update public.hr_clearance_checklists
  set status = v_next,
      -- Stamped the first time it becomes ready and cleared if it falls back, so "ready since"
      -- always means the current stretch rather than the first time it ever qualified.
      ready_at = case when v_next = 'ready' then coalesce(ready_at, now()) else null end,
      updated_at = now()
  where id = p_checklist_id;

  return v_next;
end;
$$;

ALTER FUNCTION public.phx_hr_clearance_refresh_status(p_checklist_id uuid) OWNER TO postgres;

--
-- Name: phx_hr_clearance_release(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_hr_clearance_release(p_checklist_id uuid, p_actor text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_status     text;
  v_undecided  text;
begin
  -- Recompute first: never gate on a stored status that a concurrent decision has just moved.
  v_status := public.phx_hr_clearance_refresh_status(p_checklist_id);

  if v_status = 'released' then
    raise exception 'This settlement was already recorded as released.';
  end if;

  if v_status = 'cancelled' then
    raise exception 'This clearance was cancelled and cannot be released.';
  end if;

  if v_status <> 'ready' then
    select string_agg(station_label, ', ' order by sort_order) into v_undecided
    from public.hr_clearance_items
    where checklist_id = p_checklist_id
      and status in ('pending', 'blocked');

    raise exception 'Clearance is not complete - still outstanding: %. Clear each station, or waive it with a reason.', coalesce(v_undecided, 'unknown');
  end if;

  update public.hr_clearance_checklists
  set status = 'released',
      settlement_released_at = now(),
      settlement_released_by = p_actor,
      settlement_note = p_note,
      updated_at = now()
  where id = p_checklist_id;
end;
$$;

ALTER FUNCTION public.phx_hr_clearance_release(p_checklist_id uuid, p_actor text, p_note text) OWNER TO postgres;

--
-- Name: phx_hr_ops_bridge_digest_day(uuid, text, text, date, text, integer, date, date, numeric, numeric, text, jsonb, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_hr_ops_bridge_digest_day(p_hr_ops_line_id uuid, p_section text, p_employee_hr_id text, p_work_date date, p_cycle_key text, p_week_index integer, p_week_start date, p_week_end date, p_days numeric, p_value numeric, p_reason text, p_evidence jsonb, p_decided_by_hr_id text, p_decided_at timestamp with time zone, p_allow_insert boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_hr text := btrim(coalesce(p_employee_hr_id, ''));
  v_actor text := btrim(coalesce(p_decided_by_hr_id, ''));
  v_days numeric := round(p_days, 3);
  v_found_id bigint;
  v_report_line public.hr_ops_report_lines;
  v_line public.attendance_digest_lines;
  v_digest public.attendance_weekly_digests;
  v_round smallint;
  v_digest_created boolean := false;
  v_total_days numeric;
  v_total_value numeric;
  v_unpriced boolean;
begin
  if p_hr_ops_line_id is null or coalesce(p_section, '') not in ('office', 'field') or v_hr = '' or v_actor = ''
     or p_work_date is null or coalesce(p_cycle_key, '') !~ '^\d{4}-\d{2}$'
     or p_week_index is null or p_week_index not between 1 and 5
     or p_week_start is null or p_week_end is null or p_work_date < p_week_start or p_work_date > p_week_end
     or p_allow_insert is null
     or (p_evidence is not null and jsonb_typeof(p_evidence) <> 'object') then
    raise exception 'The day to carry into the weekly attendance review is not valid.' using errcode = '22023';
  end if;
  -- The same typo guard a tick has: more than 0 (a zero decision deducts nothing) and at most 3.
  if v_days is null or v_days <= 0 or v_days > 3 then
    raise exception 'One day can deduct more than 0 and at most 3 days.' using errcode = '22023';
  end if;
  -- The report line FIRST, locked for the whole transaction: a decision saved at the same moment
  -- (decide.ts) waits for this carry to finish, and then finds the bridge_ref written below and refuses.
  select * into v_report_line from public.hr_ops_report_lines where id = p_hr_ops_line_id for update;
  if v_report_line.id is null
     or v_report_line.section is distinct from p_section
     or v_report_line.work_date is distinct from p_work_date
     or not coalesce(v_report_line.hr_key = lower(v_hr) or upper(btrim(v_report_line.hr_id)) = upper(v_hr), false) then
    raise exception 'That HR operations decision was not found for this person and day.' using errcode = 'P0002';
  end if;
  -- The days carried are the days decided, and only the decision that was sent: one changed or undone
  -- since the app read it is not carried — nothing is written, and the new decision travels on its own.
  if v_report_line.decision is distinct from 'approved'
     or round(v_report_line.decided_days, 3) is distinct from v_days
     or v_report_line.decided_at is distinct from p_decided_at then
    return jsonb_build_object('outcome', 'superseded');
  end if;

  -- The same lock the daily job takes for this employee-week, so the two never interleave.
  perform pg_advisory_xact_lock(hashtextextended('attendance_digest_sync:' || upper(v_hr) || ':' || p_cycle_key || ':' || p_week_index::text, 0));

  -- Already carried by an earlier run: the same day, nothing new.
  select l.id into v_found_id from public.attendance_digest_lines l where l.hr_ops_line_id = p_hr_ops_line_id;
  if v_found_id is null then
    -- The employee's day wherever it is — one day is held by one week (the daily job's own rule).
    select l.id into v_found_id
    from public.attendance_digest_lines l
    join public.attendance_weekly_digests g on g.id = l.digest_id
    where upper(g.employee_hr_id) = upper(v_hr)
      and g.dry_run = false
      and l.work_date = p_work_date
    order by l.id
    limit 1;
  end if;

  if v_found_id is not null then
    -- WEEK first, then the day: the order a tick and a release take them in.
    select * into v_digest from public.attendance_weekly_digests
    where id = (select digest_id from public.attendance_digest_lines where id = v_found_id)
    for update;
    select * into v_line from public.attendance_digest_lines where id = v_found_id for update;

    if v_line.hr_ops_line_id = p_hr_ops_line_id then
      -- A re-run (an earlier run wrote the day, then failed on its deduction). The decision is the one
      -- recorded now: while the day still waits for release, a figure that moved since the first run
      -- follows it through the same tick path. A day he unticked on the review page stays unticked.
      if v_digest.status = 'awaiting_release' and v_digest.dry_run = false and v_line.action = 'pending'
         and round(v_line.deduction_days, 3) <> v_days then
        perform public.phx_attendance_mark_digest_line(v_line.id, true, v_days, v_actor);
      end if;
      -- The report line points at its review day, in this transaction (an earlier run's save may not have).
      update public.hr_ops_report_lines set bridge_ref = v_line.id::text, updated_at = now()
      where id = p_hr_ops_line_id and bridge_ref is distinct from v_line.id::text;
      return jsonb_build_object(
        'outcome', 'bridged', 'lineId', v_line.id, 'digestId', v_digest.id,
        'digestEmployeeHrId', v_digest.employee_hr_id, 'lineStatus', v_line.status,
        'digestStatus', v_digest.status, 'created', false, 'alreadyBridged', true
      );
    end if;
    if v_line.hr_ops_line_id is not null then
      return jsonb_build_object(
        'outcome', 'conflict', 'lineId', v_line.id, 'digestId', v_digest.id,
        'message', 'This day was already decided by another line of the HR operations reports.'
      );
    end if;
    if v_digest.dry_run is distinct from false or v_digest.status <> 'awaiting_release' or v_line.action <> 'pending' then
      return jsonb_build_object(
        'outcome', 'week_released', 'lineId', v_line.id, 'digestId', v_digest.id,
        'digestStatus', v_digest.status, 'lineAction', v_line.action
      );
    end if;
    if (p_section = 'field') <> (v_line.status = 'field_review') then
      return jsonb_build_object(
        'outcome', 'conflict', 'lineId', v_line.id, 'digestId', v_digest.id,
        'message', case
          when p_section = 'field' then 'The weekly attendance review already holds this day as a fingerprint day, so a field decision cannot be added beside it. Decide it on the Weekly Attendance Review page.'
          else 'The weekly attendance review holds this day as a reviewed field day, so an office decision cannot be added beside it.'
        end
      );
    end if;

    update public.attendance_digest_lines set
      hr_ops_line_id = p_hr_ops_line_id,
      hr_ops_decided_by_hr_id = v_actor,
      hr_ops_decided_at = coalesce(p_decided_at, now()),
      updated_at = now()
    where id = v_line.id;
    -- The existing tick path: ticked, at the decided days, recorded as his change when it differs from
    -- what the report detected, and the week's total recomputed.
    perform public.phx_attendance_mark_digest_line(v_line.id, true, v_days, v_actor);
    -- The report line points at its review day, in this transaction: its decision is now fixed.
    update public.hr_ops_report_lines set bridge_ref = v_line.id::text, updated_at = now()
    where id = p_hr_ops_line_id;

    return jsonb_build_object(
      'outcome', 'bridged', 'lineId', v_line.id, 'digestId', v_digest.id,
      'digestEmployeeHrId', v_digest.employee_hr_id, 'lineStatus', v_line.status,
      'digestStatus', v_digest.status, 'created', false, 'alreadyBridged', false
    );
  end if;

  -- No day yet. An office day is only ever the daily job's to add — the month-end Fingerprint connector
  -- stays its one deduction writer — so the bridge never adds one; nor a field day it may not add.
  if p_section <> 'field' or not p_allow_insert then
    -- The employee's week already went out and nothing of it still waits for release: the decision
    -- arrived too late to be set on a day, and says so rather than waiting.
    if exists (
         select 1 from public.attendance_weekly_digests g
         where upper(g.employee_hr_id) = upper(v_hr) and g.cycle_key = p_cycle_key and g.week_index = p_week_index
           and g.dry_run = false and g.status <> 'awaiting_release'
       )
       and not exists (
         select 1 from public.attendance_weekly_digests g
         where upper(g.employee_hr_id) = upper(v_hr) and g.cycle_key = p_cycle_key and g.week_index = p_week_index
           and g.dry_run = false and g.status = 'awaiting_release'
       ) then
      return jsonb_build_object('outcome', 'week_released', 'lineId', null, 'lineAction', null);
    end if;
    return jsonb_build_object('outcome', 'waiting');
  end if;

  select * into v_digest
  from public.attendance_weekly_digests
  where upper(employee_hr_id) = upper(v_hr)
    and cycle_key = p_cycle_key
    and week_index = p_week_index
    and status = 'awaiting_release'
    and dry_run = false
  order by id
  limit 1
  for update;

  if v_digest.id is null then
    -- Exactly as the daily job opens a week: the next release round, waiting for release.
    select coalesce(max(release_round), 0) + 1 into v_round
    from public.attendance_weekly_digests
    where upper(employee_hr_id) = upper(v_hr)
      and cycle_key = p_cycle_key
      and week_index = p_week_index;

    insert into public.attendance_weekly_digests (
      employee_hr_id, cycle_key, week_index, week_start, week_end, status,
      total_deduction_days, total_deduction_value, has_unpriced_day, dry_run, release_round
    ) values (
      v_hr, p_cycle_key, p_week_index, p_week_start, p_week_end, 'awaiting_release',
      0, 0, false, false, v_round
    )
    returning * into v_digest;
    v_digest_created := true;
  end if;

  -- Ticked: he has already decided it. It still waits for his release like every other day, and the
  -- employee then chooses salary or annual balance, or disputes it.
  insert into public.attendance_digest_lines (
    digest_id, work_date, status, late_minutes, short_minutes, worked_minutes,
    deduction_days, deduction_value, detected_days, detected_value, reason, evidence, deduct,
    hr_ops_line_id, hr_ops_decided_by_hr_id, hr_ops_decided_at
  ) values (
    v_digest.id, p_work_date, 'field_review', 0, 0, 0,
    v_days, round(p_value, 2), v_days, round(p_value, 2), coalesce(p_reason, ''), coalesce(p_evidence, '{}'::jsonb), true,
    p_hr_ops_line_id, v_actor, coalesce(p_decided_at, now())
  )
  returning * into v_line;

  -- The week's total, counted the way the daily job and a tick count it.
  select
    coalesce(sum(deduction_days), 0),
    coalesce(sum(deduction_value), 0),
    coalesce(bool_or(deduction_value is null), false)
  into v_total_days, v_total_value, v_unpriced
  from public.attendance_digest_lines
  where digest_id = v_digest.id
    and action <> 'removed'
    and (deduct or action <> 'pending');

  update public.attendance_weekly_digests set
    total_deduction_days = round(v_total_days, 3),
    total_deduction_value = case when v_unpriced then null else round(v_total_value, 2) end,
    has_unpriced_day = v_unpriced,
    updated_at = now()
  where id = v_digest.id;

  -- The report line points at the day it added, in this transaction: its decision is now fixed.
  update public.hr_ops_report_lines set bridge_ref = v_line.id::text, updated_at = now()
  where id = p_hr_ops_line_id;

  return jsonb_build_object(
    'outcome', 'bridged', 'lineId', v_line.id, 'digestId', v_digest.id,
    'digestEmployeeHrId', v_digest.employee_hr_id, 'lineStatus', v_line.status,
    'digestStatus', v_digest.status, 'created', true, 'digestCreated', v_digest_created, 'alreadyBridged', false
  );
end;
$_$;

ALTER FUNCTION public.phx_hr_ops_bridge_digest_day(p_hr_ops_line_id uuid, p_section text, p_employee_hr_id text, p_work_date date, p_cycle_key text, p_week_index integer, p_week_start date, p_week_end date, p_days numeric, p_value numeric, p_reason text, p_evidence jsonb, p_decided_by_hr_id text, p_decided_at timestamp with time zone, p_allow_insert boolean) OWNER TO postgres;

--
-- Name: phx_import_approved_expenses_to_payroll(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_import_approved_expenses_to_payroll(p_month integer, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_imported_by text := coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''), 'service_role');
  v_target_period integer := p_year * 12 + p_month;
  v_imported_employees integer := 0;
  v_imported_total numeric := 0;
  v_current_total numeric := 0;
  v_carried_total numeric := 0;
  v_carried_rows integer := 0;
  v_locked_expenses integer := 0;
  v_matched_employees text[] := '{}'::text[];
  v_stranded_rows integer := 0;
  v_stranded_total numeric := 0;
  v_stranded_employees integer := 0;
begin
  select *
  into v_batch
  from public.salary_batches
  where month = p_month
    and year = p_year
  order by created_at desc, id desc
  limit 1
  for update;

  if not found then
    return jsonb_build_object(
      'imported_employees', 0,
      'imported_total', 0,
      'current_period_total', 0,
      'carried_forward_total', 0,
      'carried_forward_rows', 0,
      'locked_expenses', 0,
      'matched_employees', '[]'::jsonb,
      'stranded_rows', 0,
      'stranded_total', 0,
      'stranded_employees', 0,
      'target_batch_id', null,
      'target_batch_month', null,
      'target_batch_year', null
    );
  end if;

  -- GUARD 1. Automated Payroll already settled this month's outstation expenses inside the wizard,
  -- and it does not stamp the trips it consumed. Importing here would pay them a second time. This
  -- refuses rather than returning an empty result on purpose: a silent zero reads as "nothing was
  -- outstanding", which is the opposite of what is true.
  if public.phx_period_paid_by_automated_payroll(v_batch.year, v_batch.month) then
    raise exception 'Payroll batch %-% was produced by Automated Payroll, which pays outstation expenses inside the wizard. Importing them here would pay the same trips twice.', v_batch.year, v_batch.month
      using errcode = 'P0001';
  end if;

  if v_batch.status not in ('part1_paid', 'adjustments_open', 'part2_ready', 'under_review', 'rejected') then
    raise exception 'Payroll batch cannot import expenses while its status is %. Expenses import between Part 1 paid and review; a batch that is already approved or locked is closed.', v_batch.status using errcode = 'P0001';
  end if;

  with importable as (
    -- Every approved expense that has never been paid, from this period or any earlier one.
    select
      oe.id,
      oe.hr_id,
      -- Pay the HR-approved figure when HR adjusted the claim; otherwise the claim stands.
      -- approved_amount is NULL on every pre-existing row, so this is a no-op for them.
      coalesce(oe.approved_amount, oe.total) as amount,
      (oe.payout_year * 12 + oe.payout_month) as period_index
    from public.outstation_expenses oe
    where oe.hr_approved = true
      and oe.approved_at is not null
      and oe.approved_by is not null
      and oe.hr_id is not null
      and trim(oe.hr_id) <> ''
      and oe.payout_month is not null
      and oe.payout_year is not null
      -- IDEMPOTENCE, and the reason the additive write below is safe: a row already stamped as
      -- imported is excluded, so re-running adds nothing and no expense is ever paid twice.
      and oe.imported_to_payroll_at is null
      and oe.imported_payroll_batch_id is null
      -- CARRY FORWARD: at or before the target period, never after it.
      and (oe.payout_year * 12 + oe.payout_month) <= v_target_period
      -- GUARD 2, the carry-forward half. A trip whose own payout month was paid by Automated
      -- Payroll is settled, even though nothing stamped it. Without this, opening a legacy batch
      -- for any later month drags every wizard-paid trip in behind it, which is precisely the
      -- EGP 138,453 exposure this migration exists to close.
      and not public.phx_period_paid_by_automated_payroll(oe.payout_year, oe.payout_month)
  ),
  approved_totals as (
    select
      lower(hr_id) as normalized_hr_id,
      min(hr_id) as hr_id,
      sum(amount)::numeric(20,2) as approved_expense,
      coalesce(sum(amount) filter (where period_index = v_target_period), 0)::numeric(20,2) as current_expense,
      coalesce(sum(amount) filter (where period_index < v_target_period), 0)::numeric(20,2) as carried_expense,
      count(*) filter (where period_index < v_target_period)::integer as carried_rows
    from importable
    group by lower(hr_id)
  ),
  matched_totals as (
    -- INNER join, and the only thing that reaches the update below. An employee in this batch with
    -- no approved unimported claim produces no row here and is therefore never written to.
    select
      sr.id as salary_record_id,
      sr.hr_id,
      at.approved_expense,
      at.current_expense,
      at.carried_expense,
      at.carried_rows
    from public.salary_records sr
    join approved_totals at
      on lower(sr.hr_id) = at.normalized_hr_id
    where sr.batch_id = v_batch.id
  ),
  stranded as (
    -- Approved, unpaid, and its employee is not in this batch -- so it still cannot be paid here.
    -- Reported rather than silently skipped.
    select
      count(*)::integer as stranded_rows,
      coalesce(sum(i.amount), 0)::numeric(20,2) as stranded_total,
      count(distinct lower(i.hr_id))::integer as stranded_employees
    from importable i
    where not exists (
      select 1
      from public.salary_records sr
      where sr.batch_id = v_batch.id
        and lower(sr.hr_id) = lower(i.hr_id)
    )
  ),
  updated_rows as (
    update public.salary_records sr
    set expenses = coalesce(sr.expenses, 0) + mt.approved_expense,
        total_additions = coalesce(sr.total_additions, 0) + mt.approved_expense,
        second_part = coalesce(sr.second_part, 0) + mt.approved_expense,
        month_salary = coalesce(sr.month_salary, coalesce(sr.first_part, 0) + coalesce(sr.second_part, 0)) + mt.approved_expense
    from matched_totals mt
    where sr.id = mt.salary_record_id
      -- A claim HR adjusted down to zero still gets stamped below; it just has nothing to add.
      and mt.approved_expense <> 0
    returning sr.id
  ),
  marked_expenses as (
    -- Stamp exactly the rows that were summed. Selecting by id from `importable` rather than
    -- restating the predicate means the set paid and the set stamped cannot drift apart.
    update public.outstation_expenses pe
    set
      imported_payroll_batch_id = v_batch.id,
      imported_to_payroll_at = now(),
      imported_to_payroll_by = v_imported_by
    where pe.id in (
      select i.id
      from importable i
      join matched_totals mt
        on lower(mt.hr_id) = lower(i.hr_id)
    )
    returning pe.id
  )
  select
    count(*)::integer,
    coalesce(sum(approved_expense), 0)::numeric,
    coalesce(sum(current_expense), 0)::numeric,
    coalesce(sum(carried_expense), 0)::numeric,
    coalesce(sum(carried_rows), 0)::integer,
    (select count(*)::integer from marked_expenses),
    coalesce(array_agg(hr_id order by hr_id), '{}'::text[]),
    (select stranded_rows from stranded),
    (select stranded_total from stranded),
    (select stranded_employees from stranded)
  into
    v_imported_employees,
    v_imported_total,
    v_current_total,
    v_carried_total,
    v_carried_rows,
    v_locked_expenses,
    v_matched_employees,
    v_stranded_rows,
    v_stranded_total,
    v_stranded_employees
  from matched_totals;

  return jsonb_build_object(
    'imported_employees', v_imported_employees,
    'imported_total', v_imported_total,
    'current_period_total', v_current_total,
    'carried_forward_total', v_carried_total,
    'carried_forward_rows', v_carried_rows,
    'locked_expenses', v_locked_expenses,
    'matched_employees', to_jsonb(v_matched_employees),
    'stranded_rows', v_stranded_rows,
    'stranded_total', v_stranded_total,
    'stranded_employees', v_stranded_employees,
    'target_batch_id', v_batch.id,
    'target_batch_month', v_batch.month,
    'target_batch_year', v_batch.year
  );
end;
$$;

ALTER FUNCTION public.phx_import_approved_expenses_to_payroll(p_month integer, p_year integer) OWNER TO postgres;

--
-- Name: phx_in_app_notices(text, text, text, text, text[], date, integer, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_in_app_notices(p_hr_id text, p_user_id text, p_msg_hr_id text, p_login_id text, p_categories text[], p_today date, p_limit integer, p_other_kinds boolean, p_flooding_event_type text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with own as (
    select e.*
    from public.notification_events e
    where coalesce(p_hr_id, '') <> ''
      and e.employee_hr_id = upper(p_hr_id)
      and e.category = any (p_categories)
      and e.scheduled_for <= p_today
    order by e.created_at desc
    limit greatest(1, least(coalesce(p_limit, 8), 500))
  ),
  named as (
    select e.*
    from public.notification_events e
    where coalesce(p_hr_id, '') <> ''
      and e.recipients && array[p_hr_id]::text[]
      and e.category = any (p_categories)
      and e.scheduled_for <= p_today
    order by e.created_at desc
    limit greatest(1, least(coalesce(p_limit, 8), 500))
  ),
  other_kinds as (
    -- The Talent Acquisition seat: her two reads above fill with new-CV alerts and reach back only a
    -- day or two, so her other notices are read on their own (seat-notice-filter.ts).
    select e.*
    from public.notification_events e
    where coalesce(p_other_kinds, false)
      and coalesce(p_hr_id, '') <> ''
      and e.employee_hr_id = upper(p_hr_id)
      and e.category = any (p_categories)
      and e.scheduled_for <= p_today
      and (e.event_type is null or e.event_type <> p_flooding_event_type)
    order by e.created_at desc
    limit greatest(1, least(coalesce(p_limit, 8), 500))
  ),
  candidates as (
    select distinct on (c.id) c.*
    from (
      select * from own
      union all
      select * from named
      union all
      select * from other_kinds
    ) c
    order by c.id
  ),
  events as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', c.id,
          'category', c.category,
          'subject', c.subject,
          'scheduled_for', c.scheduled_for,
          'sent_at', c.sent_at,
          'status', c.status,
          'metadata', c.metadata,
          'recipients', c.recipients,
          'employee_hr_id', c.employee_hr_id,
          'created_at', c.created_at,
          'module', c.module,
          'priority', c.priority,
          'action_url', c.action_url,
          'event_type', c.event_type,
          'test_login_id', c.test_login_id
        )
        order by c.created_at desc
      ),
      '[]'::jsonb
    ) as j
    from candidates c
  ),
  states as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'notification_event_id', s.notification_event_id,
          'user_id', s.user_id,
          'hr_id', s.hr_id,
          'read_at', s.read_at,
          'archived_at', s.archived_at
        )
      ),
      '[]'::jsonb
    ) as j
    from public.notification_user_states s
    where s.notification_event_id in (select id from candidates)
      and (
        (coalesce(p_user_id, '') <> '' and s.user_id = p_user_id)
        or s.hr_id = p_hr_id
      )
  ),
  newest_messages as (
    select m.read_at, m.recipient_hr_id, m.recipient_login_id
    from public.internal_messages m
    where (coalesce(p_msg_hr_id, '') <> '' and (m.recipient_hr_id = p_msg_hr_id or m.sender_hr_id = p_msg_hr_id))
       or (coalesce(p_login_id, '') <> '' and (m.recipient_login_id = p_login_id or m.sender_login_id = p_login_id))
    order by m.created_at desc
    limit 20
  ),
  unread_messages as (
    select count(*)::integer as n
    from newest_messages m
    where m.read_at is null
      and (
        (coalesce(p_msg_hr_id, '') <> '' and upper(trim(m.recipient_hr_id)) = upper(p_msg_hr_id))
        or (coalesce(p_login_id, '') <> '' and lower(m.recipient_login_id) = lower(p_login_id))
      )
  )
  select jsonb_build_object(
    'events', (select j from events),
    'states', (select j from states),
    'unread_messages',
      case
        when coalesce(p_msg_hr_id, '') = '' and coalesce(p_login_id, '') = '' then null
        else (select n from unread_messages)
      end
  );
$$;

ALTER FUNCTION public.phx_in_app_notices(p_hr_id text, p_user_id text, p_msg_hr_id text, p_login_id text, p_categories text[], p_today date, p_limit integer, p_other_kinds boolean, p_flooding_event_type text) OWNER TO postgres;

--
-- Name: FUNCTION phx_in_app_notices(p_hr_id text, p_user_id text, p_msg_hr_id text, p_login_id text, p_categories text[], p_today date, p_limit integer, p_other_kinds boolean, p_flooding_event_type text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_in_app_notices(p_hr_id text, p_user_id text, p_msg_hr_id text, p_login_id text, p_categories text[], p_today date, p_limit integer, p_other_kinds boolean, p_flooding_event_type text) IS 'The in-app bell in one statement (1 Nov 2026): the viewer''s notices (own, named, and the flooded seat''s other kinds), each fenced scheduled_for <= p_today; their read/archive states; the unread count of the newest 20 internal messages. Called by listInAppNoticeBundleForViewer; the app keeps every post-read filter.';

--
-- Name: phx_insert_attendance_raw_punch(text, text, text, timestamp with time zone, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_insert_attendance_raw_punch(p_device_id text, p_device_user_id text, p_employee_hr_id text, p_punch_time timestamp with time zone, p_punch_type text, p_verify_mode text, p_raw_payload jsonb, p_source_run_id text) RETURNS bigint
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into public.attendance_raw_punches (
    device_id,
    device_user_id,
    employee_hr_id,
    punch_time,
    punch_type,
    verify_mode,
    raw_payload,
    source_run_id,
    ingested_at
  )
  values (
    p_device_id,
    p_device_user_id,
    p_employee_hr_id,
    p_punch_time,
    p_punch_type,
    p_verify_mode,
    coalesce(p_raw_payload, '{}'::jsonb),
    p_source_run_id,
    now()
  )
  on conflict do nothing
  returning id;
$$;

ALTER FUNCTION public.phx_insert_attendance_raw_punch(p_device_id text, p_device_user_id text, p_employee_hr_id text, p_punch_time timestamp with time zone, p_punch_type text, p_verify_mode text, p_raw_payload jsonb, p_source_run_id text) OWNER TO postgres;

--
-- Name: FUNCTION phx_insert_attendance_raw_punch(p_device_id text, p_device_user_id text, p_employee_hr_id text, p_punch_time timestamp with time zone, p_punch_type text, p_verify_mode text, p_raw_payload jsonb, p_source_run_id text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_insert_attendance_raw_punch(p_device_id text, p_device_user_id text, p_employee_hr_id text, p_punch_time timestamp with time zone, p_punch_type text, p_verify_mode text, p_raw_payload jsonb, p_source_run_id text) IS 'Idempotent single raw-punch insert for the fingerprint attendance agent. Uses ON CONFLICT DO NOTHING so re-pushed punches are silently ignored at the database level (no duplicate-key ERROR logged). Returns the new id, or NULL when the punch already existed.';

--
-- Name: phx_insert_attendance_raw_punches(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_insert_attendance_raw_punches(p_rows jsonb) RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with inserted as (
    insert into public.attendance_raw_punches (
      device_id,
      device_user_id,
      employee_hr_id,
      punch_time,
      punch_type,
      verify_mode,
      raw_payload,
      source_run_id,
      ingested_at
    )
    select
      r.device_id,
      r.device_user_id,
      r.employee_hr_id,
      r.punch_time,
      r.punch_type,
      r.verify_mode,
      coalesce(r.raw_payload, '{}'::jsonb),
      r.source_run_id,
      now()
    from jsonb_to_recordset(p_rows) as r(
      device_id text,
      device_user_id text,
      employee_hr_id text,
      punch_time timestamptz,
      punch_type text,
      verify_mode text,
      raw_payload jsonb,
      source_run_id text
    )
    on conflict do nothing
    returning 1
  )
  select count(*)::integer from inserted;
$$;

ALTER FUNCTION public.phx_insert_attendance_raw_punches(p_rows jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phx_insert_attendance_raw_punches(p_rows jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_insert_attendance_raw_punches(p_rows jsonb) IS 'Idempotent BATCH raw-punch insert for the fingerprint attendance agent: p_rows is a jsonb array of {device_id, device_user_id, employee_hr_id, punch_time, punch_type, verify_mode, raw_payload, source_run_id}. ON CONFLICT DO NOTHING skips punches the table already holds; returns the number of rows newly inserted.';

--
-- Name: phx_link_expense_claims_to_payroll(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_link_expense_claims_to_payroll(p_batch_id uuid, p_actor_hr_id text, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_planned jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_total numeric := 0; v_emps integer := 0; v_claims integer := 0;
  r record;
begin
  if p_actor_hr_id is null or btrim(p_actor_hr_id) = '' then
    raise exception 'An actor is required: linking money to payroll must be attributable.'
      using errcode = 'P0001';
  end if;

  select * into v_batch from public.salary_batches where id = p_batch_id for update;
  if not found then
    raise exception 'Payroll batch % was not found.', p_batch_id using errcode = 'P0002';
  end if;

  if v_batch.status in ('approved', 'locked') then
    raise exception
      'Payroll batch %-% is "%" and cannot receive expense links. Re-opening a closed batch and linking claims whose period was already paid by hand would pay them twice.',
      v_batch.year, lpad(v_batch.month::text, 2, '0'), v_batch.status
      using errcode = 'P0001';
  end if;

  for r in
    with agg as (
      select lower(c.employee_hr_id) as hr_key,
             min(c.employee_hr_id) as hr_id,
             min(c.employee_name) as employee_name,
             count(*) as claim_count,
             round(sum(coalesce(c.approved_total, c.claimed_total)), 2) as payable
      from public.expense_claims c
      where c.status = 'approved'
        and c.payout_year = v_batch.year and c.payout_month = v_batch.month
        and coalesce(c.evidence_gate_status, 'complete') in ('complete', 'grandfathered')
        and coalesce(c.workload_gate_status, 'complete') in ('complete', 'grandfathered', 'manual')
        and not exists (select 1 from public.expense_payroll_links l where l.claim_id = c.id)
      group by lower(c.employee_hr_id)
    )
    select a.hr_key, a.hr_id, a.employee_name, a.claim_count, a.payable,
           (select r2.id from public.salary_records r2
             where r2.batch_id = v_batch.id and lower(r2.hr_id) = a.hr_key limit 1) as salary_record_id
    from agg a order by a.hr_id
  loop
    if r.salary_record_id is null then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
        'employee_hr_id', r.hr_id, 'employee_name', r.employee_name,
        'claim_count', r.claim_count, 'payable_egp', r.payable,
        'reason', 'No salary record in this batch - the money has nowhere to land.'));
      continue;
    end if;

    v_planned := v_planned || jsonb_build_array(jsonb_build_object(
      'employee_hr_id', r.hr_id, 'employee_name', r.employee_name,
      'claim_count', r.claim_count, 'payable_egp', r.payable));
    v_total := v_total + r.payable; v_emps := v_emps + 1; v_claims := v_claims + r.claim_count;

    if not p_dry_run then
      update public.salary_records
      set expenses        = coalesce(expenses, 0)        + r.payable,
          total_additions = coalesce(total_additions, 0) + r.payable,
          second_part     = coalesce(second_part, 0)     + r.payable,
          month_salary    = coalesce(month_salary, 0)    + r.payable
      where id = r.salary_record_id;

      insert into public.expense_payroll_links
        (claim_id, salary_batch_id, salary_record_id, amount, linked_by_hr_id)
      select c.id, v_batch.id, r.salary_record_id,
             coalesce(c.approved_total, c.claimed_total), p_actor_hr_id
      from public.expense_claims c
      where c.status = 'approved'
        and c.payout_year = v_batch.year and c.payout_month = v_batch.month
        and lower(c.employee_hr_id) = r.hr_key
        and coalesce(c.evidence_gate_status, 'complete') in ('complete', 'grandfathered')
        and coalesce(c.workload_gate_status, 'complete') in ('complete', 'grandfathered', 'manual')
        and not exists (select 1 from public.expense_payroll_links l where l.claim_id = c.id);

      insert into public.expense_claim_events (claim_id, actor_hr_id, event_type, message, metadata)
      select c.id, p_actor_hr_id, 'payroll.linked',
             'Linked to payroll ' || v_batch.year || '-' || lpad(v_batch.month::text, 2, '0'),
             jsonb_build_object('salary_batch_id', v_batch.id, 'salary_record_id', r.salary_record_id,
               'amount', coalesce(c.approved_total, c.claimed_total),
               'from_status', c.status, 'to_status', 'in_payroll')
      from public.expense_claims c
      join public.expense_payroll_links l on l.claim_id = c.id
      where l.salary_batch_id = v_batch.id and lower(c.employee_hr_id) = r.hr_key
        and c.status = 'approved';

      update public.expense_claims c
      set status = 'in_payroll'
      from public.expense_payroll_links l
      where l.claim_id = c.id and l.salary_batch_id = v_batch.id
        and lower(c.employee_hr_id) = r.hr_key and c.status = 'approved';
    end if;
  end loop;

  return jsonb_build_object(
    'dry_run', p_dry_run,
    'batch', v_batch.year || '-' || lpad(v_batch.month::text, 2, '0'),
    'batch_status', v_batch.status,
    'employees', v_emps, 'claims', v_claims, 'total_egp', round(v_total, 2),
    'planned', v_planned, 'skipped_no_salary_record', v_skipped);
end;
$$;

ALTER FUNCTION public.phx_link_expense_claims_to_payroll(p_batch_id uuid, p_actor_hr_id text, p_dry_run boolean) OWNER TO postgres;

--
-- Name: FUNCTION phx_link_expense_claims_to_payroll(p_batch_id uuid, p_actor_hr_id text, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_link_expense_claims_to_payroll(p_batch_id uuid, p_actor_hr_id text, p_dry_run boolean) IS 'PULL contract: payroll asks outstation what it owes and links it. DRY RUN by default. Additive write (never SET), UNIQUE(claim_id) idempotency, refuses closed batches, and reports employees with no salary record instead of dropping them.';

--
-- Name: monthly_closing_locks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.monthly_closing_locks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    line text NOT NULL,
    normalized_line text NOT NULL,
    period text NOT NULL,
    locked_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_by text,
    snapshot_units numeric,
    snapshot_cells integer,
    snapshot_breakdown jsonb,
    unlocked_at timestamp with time zone,
    unlocked_by text,
    unlock_reason text
);

ALTER TABLE public.monthly_closing_locks OWNER TO postgres;

--
-- Name: TABLE monthly_closing_locks; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.monthly_closing_locks IS 'An active row here freezes that (line, period) in source_of_sales_import_rows, source_of_sales_fact_rollup and source_of_sales_customer_directory_rollup. Enforced by triggers, so migrations and ad-hoc SQL are stopped too, not just the application.';

--
-- Name: phx_lock_monthly_closing(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_lock_monthly_closing(p_line text, p_period text, p_actor text DEFAULT NULL::text) RETURNS public.monthly_closing_locks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_norm text := lower(btrim(coalesce(p_line, '')));
  v_row  public.monthly_closing_locks;
  v_units numeric;
  v_cells integer;
begin
  if v_norm = '' or btrim(coalesce(p_period, '')) = '' then
    raise exception 'A line and a period are required to lock a closing.';
  end if;

  select coalesce(sum(total_qty), 0), count(*)
    into v_units, v_cells
    from public.source_of_sales_fact_rollup
   where period = p_period and lower(btrim(coalesce(official_line, ''))) = v_norm;

  insert into public.monthly_closing_locks
    (line, normalized_line, period, locked_by, snapshot_units, snapshot_cells, snapshot_breakdown)
  values
    (btrim(p_line), v_norm, btrim(p_period), p_actor, v_units, v_cells,
     (select jsonb_agg(jsonb_build_object('a', f.area_code, 'p', f.product_code, 'd', f.is_direct,
                                          'u', f.total_qty,
                                          'v', case when coalesce(f.is_direct, false)
                                                    then coalesce(f.direct_value, 0)
                                                    else f.effective_units * coalesce(public.phx_factory_price(f.product_code, f.period), 0)
                                               end))
        from public.source_of_sales_fact_rollup f
        left join public.source_of_sales_products pr
          on upper(btrim(pr.product_code)) = upper(btrim(f.product_code))
       where f.period = p_period and lower(btrim(coalesce(f.official_line, ''))) = v_norm))
  returning * into v_row;

  return v_row;
end;
$$;

ALTER FUNCTION public.phx_lock_monthly_closing(p_line text, p_period text, p_actor text) OWNER TO postgres;

--
-- Name: phx_log_deduction_decision_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_log_deduction_decision_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  deciding constant text[] := array[
    'decision_status', 'decision_reason', 'hr_note',
    'applied_value', 'applied_amount', 'applied_dates', 'decided_by'
  ];
  o       jsonb := '{}'::jsonb;
  n       jsonb := to_jsonb(new);
  col     text;
  fields  text[] := '{}';
  before_ jsonb := '{}'::jsonb;
  after_  jsonb := '{}'::jsonb;
begin
  if tg_op = 'UPDATE' then
    o := to_jsonb(old);
  end if;

  foreach col in array deciding loop
    after_ := after_ || jsonb_build_object(col, n -> col);
    if tg_op = 'UPDATE' then
      before_ := before_ || jsonb_build_object(col, o -> col);
      if (o -> col) is distinct from (n -> col) then
        fields := array_append(fields, col);
      end if;
    elsif jsonb_typeof(n -> col) <> 'null' then
      fields := array_append(fields, col);
    end if;
  end loop;

  if tg_op = 'UPDATE' and array_length(fields, 1) is null then
    return null;
  end if;

  insert into public.deductions_audit (candidate_id, actor_hr_id, action, detail)
  values (
    new.candidate_id,
    new.decided_by,
    case when tg_op = 'INSERT' then 'decision_recorded' else 'decision_changed' end,
    jsonb_build_object(
      'decision_id', new.id,
      'changed_fields', to_jsonb(fields),
      'before', case when tg_op = 'INSERT' then null else before_ end,
      'after', after_,
      'decided_at', new.decided_at,
      'actor_role_at_decision', new.actor_role_at_decision
    )
  );

  return null;
end;
$$;

ALTER FUNCTION public.phx_log_deduction_decision_change() OWNER TO postgres;

--
-- Name: FUNCTION phx_log_deduction_decision_change(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_log_deduction_decision_change() IS 'AFTER INSERT OR UPDATE ROW trigger on public.deductions_decisions: appends the decision before and after to the append-only public.deductions_audit (actions decision_recorded, decision_changed).';

--
-- Name: phx_log_employee_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_log_employee_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  ignored constant text[] := array['updated_at', 'total_experience_years', 'total_experience_as_of'];
  masked  constant text[] := array[
    'base_salary', 'basic_salary', 'gross_salary', 'net_salary',
    'fuel_allowance', 'extra_cost_of_living', 'medical_insurance',
    'social_insurance', 'taxes', 'social_insurance_wage',
    'bank_account', 'national_id', 'social_insurance_number', 'medical_insurance_number',
    'health_card_number', 'kaab_elamaal_number', 'mobile_number', 'personal_email',
    'residence_address', 'birth_date'
  ];
  o        jsonb := '{}'::jsonb;
  n        jsonb := '{}'::jsonb;
  col      text;
  fields   text[] := '{}';
  hidden   text[] := '{}';
  old_diff jsonb := '{}'::jsonb;
  new_diff jsonb := '{}'::jsonb;
  v_hr_id  text;
  headers  json;
  v_login  text;
  v_hr     text;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    o := to_jsonb(old);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    n := to_jsonb(new);
  end if;
  v_hr_id := coalesce(n ->> 'hr_id', o ->> 'hr_id');

  for col in select k from jsonb_object_keys(o || n) as k order by k loop
    continue when col = any(ignored);
    -- On an insert a blank column is not a change; on a delete neither is a blank old value.
    continue when tg_op = 'INSERT' and jsonb_typeof(n -> col) = 'null';
    continue when tg_op = 'DELETE' and jsonb_typeof(o -> col) = 'null';
    continue when (o -> col) is not distinct from (n -> col);

    fields := array_append(fields, col);
    if col = any(masked) then
      hidden := array_append(hidden, col);
    else
      if tg_op <> 'INSERT' then old_diff := old_diff || jsonb_build_object(col, o -> col); end if;
      if tg_op <> 'DELETE' then new_diff := new_diff || jsonb_build_object(col, n -> col); end if;
    end if;
  end loop;

  if array_length(fields, 1) is null then
    return null;
  end if;

  -- Best-effort actor from the PostgREST request headers, exactly as the salary trigger reads it.
  begin
    headers := nullif(current_setting('request.headers', true), '')::json;
    v_login := nullif(headers ->> 'x-phoenix-actor-login-id', '');
    v_hr    := nullif(headers ->> 'x-phoenix-actor-hr-id', '');
  exception when others then
    v_login := null;
    v_hr    := null;
  end;

  insert into public.employee_change_log (
    employee_hr_id, change_kind, actor_login_id, actor_hr_id, actor_source,
    changed_fields, masked_fields, old_values, new_values
  ) values (
    v_hr_id, lower(tg_op), v_login, v_hr,
    case when v_login is not null or v_hr is not null then 'app' else 'unattributed' end,
    fields, hidden, old_diff, new_diff
  );

  return null;
end;
$$;

ALTER FUNCTION public.phx_log_employee_change() OWNER TO postgres;

--
-- Name: FUNCTION phx_log_employee_change(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_log_employee_change() IS 'AFTER ROW trigger on public.employees: writes public.employee_change_log. Values of the columns in its masked list are never stored, only named.';

--
-- Name: phx_log_employee_salary_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_log_employee_salary_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  salary_cols constant text[] := array[
    'base_salary', 'basic_salary', 'gross_salary', 'net_salary',
    'fuel_allowance', 'extra_cost_of_living', 'medical_insurance',
    'social_insurance', 'taxes', 'social_insurance_wage'
  ];
  is_insert   constant boolean := tg_op = 'INSERT';
  o           jsonb;
  n           jsonb := to_jsonb(new);
  col         text;
  old_diff    jsonb := '{}'::jsonb;
  new_diff    jsonb := '{}'::jsonb;
  fields      text[] := '{}';
  headers     json;
  v_login     text;
  v_hr        text;
begin
  o := case when is_insert then '{}'::jsonb else to_jsonb(old) end;

  foreach col in array salary_cols loop
    if is_insert then
      if (n ->> col) is not null then
        new_diff := new_diff || jsonb_build_object(col, n -> col);
        fields   := array_append(fields, col);
      end if;
    elsif (o ->> col) is distinct from (n ->> col) then
      old_diff := old_diff || jsonb_build_object(col, o -> col);
      new_diff := new_diff || jsonb_build_object(col, n -> col);
      fields   := array_append(fields, col);
    end if;
  end loop;

  if array_length(fields, 1) is null then
    return new;
  end if;

  begin
    headers := nullif(current_setting('request.headers', true), '')::json;
    v_login := nullif(headers ->> 'x-phoenix-actor-login-id', '');
    v_hr    := nullif(headers ->> 'x-phoenix-actor-hr-id', '');
  exception when others then
    v_login := null;
    v_hr    := null;
  end;

  insert into public.employee_salary_change_log (
    employee_hr_id, actor_login_id, actor_hr_id, actor_source,
    changed_fields, old_values, new_values
  ) values (
    new.hr_id, v_login, v_hr,
    case when v_login is not null or v_hr is not null then 'app' else 'unattributed' end,
    fields, old_diff, new_diff
  );

  return new;
end;
$$;

ALTER FUNCTION public.phx_log_employee_salary_change() OWNER TO postgres;

--
-- Name: phx_mailbox_offboarding_open(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_mailbox_offboarding_open(p_employee_hr_id text, p_actor text, p_source text DEFAULT 'resignation'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee record;
  v_existing uuid;
  v_task_id uuid;
begin
  select e.hr_id, e.full_name, e.work_email, e.job_title, e.last_working_date, e.employment_status
  into v_employee
  from public.employees e
  where lower(e.hr_id) = lower(trim(p_employee_hr_id))
  limit 1;

  if not found then
    raise exception 'No employee matches HR ID %.', p_employee_hr_id;
  end if;

  if v_employee.work_email is null or char_length(trim(v_employee.work_email)) = 0 then
    return null;
  end if;

  select id into v_existing
  from public.mailbox_offboarding_tasks
  where lower(employee_hr_id) = lower(v_employee.hr_id)
    and status in ('pending', 'in_progress')
  limit 1;

  if v_existing is not null then
    return v_existing;
  end if;

  insert into public.mailbox_offboarding_tasks (
    employee_hr_id, employee_name, work_email, job_title, last_working_date, source, opened_by
  )
  values (
    v_employee.hr_id,
    coalesce(nullif(trim(v_employee.full_name), ''), v_employee.hr_id),
    trim(v_employee.work_email),
    v_employee.job_title,
    v_employee.last_working_date,
    case when p_source in ('resignation', 'backfill', 'sweep') then p_source else 'resignation' end,
    p_actor
  )
  returning id into v_task_id;

  return v_task_id;
end;
$$;

ALTER FUNCTION public.phx_mailbox_offboarding_open(p_employee_hr_id text, p_actor text, p_source text) OWNER TO postgres;

--
-- Name: phx_mailbox_offboarding_record(uuid, text, text, text, text, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_mailbox_offboarding_record(p_task_id uuid, p_step text, p_actor text, p_disposition text DEFAULT NULL::text, p_forwarding_to text DEFAULT NULL::text, p_forwarding_expires_on date DEFAULT NULL::date, p_reason text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.mailbox_offboarding_tasks%rowtype;
begin
  select * into v_row from public.mailbox_offboarding_tasks where id = p_task_id;
  if not found then
    raise exception 'Mailbox offboarding task % was not found.', p_task_id;
  end if;

  -- A revoked row is frozen against further steps, but NOT against correction — see the 'reopen'
  -- branch below. A register with no correction path is a defect this repository has already paid
  -- for once: the marketing licence verdict is write-once at approval, and because the write gate
  -- requires a step that stops existing the moment the request is decided, not even a Super Admin
  -- can fix a wrong one. It is then displayed on a register indefinitely. The same shape here —
  -- an admin ticking "app passwords cleared" on the wrong row — would permanently assert that a
  -- live mailbox is shut, which is precisely the false negative this whole table exists to prevent.
  --
  -- The one exemption is a disposition on a row already revoked by BOTH steps. It cannot change
  -- the status, so it cannot weaken the assertion the freeze protects; and without it the third
  -- step of the workspace is unreachable in the order the workspace numbers it. The migration
  -- header carries the measurement that found this.
  if v_row.status = 'revoked'
     and p_step <> 'reopen'
     and not (
       p_step = 'disposition'
       and v_row.password_reset_at is not null
       and v_row.app_passwords_cleared_at is not null
     ) then
    raise exception 'This mailbox is already recorded as revoked. Reopen it before recording anything further.';
  end if;

  if p_actor is null or char_length(trim(p_actor)) = 0 then
    raise exception 'A step must record who performed it.';
  end if;

  if p_step = 'password_reset' then
    -- coalesce, not overwrite: the first admin to do it is who did it.
    update public.mailbox_offboarding_tasks
    set password_reset_at = coalesce(password_reset_at, now()),
        password_reset_by = coalesce(password_reset_by, p_actor),
        note = coalesce(nullif(trim(p_note), ''), note),
        updated_at = now()
    where id = p_task_id;

  elsif p_step = 'app_passwords_cleared' then
    update public.mailbox_offboarding_tasks
    set app_passwords_cleared_at = coalesce(app_passwords_cleared_at, now()),
        app_passwords_cleared_by = coalesce(app_passwords_cleared_by, p_actor),
        note = coalesce(nullif(trim(p_note), ''), note),
        updated_at = now()
    where id = p_task_id;

  elsif p_step = 'disposition' then
    if p_disposition is null or p_disposition not in ('deleted', 'suspended', 'forwarding', 'retained') then
      raise exception 'A disposition must be one of deleted, suspended, forwarding or retained.';
    end if;
    if p_disposition = 'forwarding' and (p_forwarding_to is null or char_length(trim(p_forwarding_to)) = 0) then
      raise exception 'Forwarding needs a destination address.';
    end if;

    update public.mailbox_offboarding_tasks
    set disposition = p_disposition,
        disposition_at = now(),
        disposition_by = p_actor,
        forwarding_to = case when p_disposition = 'forwarding' then trim(p_forwarding_to) else null end,
        forwarding_expires_on = case when p_disposition = 'forwarding' then p_forwarding_expires_on else null end,
        note = coalesce(nullif(trim(p_note), ''), note),
        updated_at = now()
    where id = p_task_id;

  elsif p_step = 'reopen' then
    if p_reason is null or char_length(trim(p_reason)) = 0 then
      raise exception 'Reopening a mailbox record needs a written reason.';
    end if;
    -- Clears the current state back to pending. The history is NOT lost: every step writes an
    -- audit row through writeRequiredAuditLog before it calls this function, so what was claimed,
    -- by whom and when survives the correction. This row is current state, the audit log is record.
    update public.mailbox_offboarding_tasks
    set status = 'pending',
        password_reset_at = null,
        password_reset_by = null,
        app_passwords_cleared_at = null,
        app_passwords_cleared_by = null,
        disposition = null,
        disposition_at = null,
        disposition_by = null,
        forwarding_to = null,
        forwarding_expires_on = null,
        revoked_at = null,
        reason = trim(p_reason),
        note = coalesce(nullif(trim(p_note), ''), note),
        updated_at = now()
    where id = p_task_id;
    return 'pending';

  elsif p_step = 'not_applicable' then
    if p_reason is null or char_length(trim(p_reason)) = 0 then
      raise exception 'Marking a mailbox not applicable needs a written reason.';
    end if;
    update public.mailbox_offboarding_tasks
    set status = 'not_applicable',
        reason = trim(p_reason),
        note = coalesce(nullif(trim(p_note), ''), note),
        updated_at = now()
    where id = p_task_id;
    return 'not_applicable';

  else
    raise exception 'Unknown mailbox offboarding step %.', p_step;
  end if;

  return public.phx_mailbox_offboarding_refresh_status(p_task_id);
end;
$$;

ALTER FUNCTION public.phx_mailbox_offboarding_record(p_task_id uuid, p_step text, p_actor text, p_disposition text, p_forwarding_to text, p_forwarding_expires_on date, p_reason text, p_note text) OWNER TO postgres;

--
-- Name: phx_mailbox_offboarding_refresh_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_mailbox_offboarding_refresh_status(p_task_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.mailbox_offboarding_tasks%rowtype;
  v_status text;
begin
  select * into v_row from public.mailbox_offboarding_tasks where id = p_task_id;
  if not found then
    raise exception 'Mailbox offboarding task % was not found.', p_task_id;
  end if;

  if v_row.status = 'not_applicable' then
    return v_row.status;
  end if;

  if v_row.disposition in ('deleted', 'suspended')
     or (v_row.password_reset_at is not null and v_row.app_passwords_cleared_at is not null) then
    v_status := 'revoked';
  elsif v_row.password_reset_at is not null
     or v_row.app_passwords_cleared_at is not null
     or v_row.disposition is not null then
    v_status := 'in_progress';
  else
    v_status := 'pending';
  end if;

  update public.mailbox_offboarding_tasks
  set status = v_status,
      revoked_at = case
        when v_status = 'revoked' then coalesce(revoked_at, now())
        else null
      end,
      updated_at = now()
  where id = p_task_id;

  return v_status;
end;
$$;

ALTER FUNCTION public.phx_mailbox_offboarding_refresh_status(p_task_id uuid) OWNER TO postgres;

--
-- Name: phx_make_it_happen_brick_units(text, text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_make_it_happen_brick_units(p_period text, p_line_codes text[] DEFAULT NULL::text[], p_area_codes text[] DEFAULT NULL::text[]) RETURNS TABLE(period text, line_code text, area_code text, rep_hr_id text, dm_hr_id text, brick_id text, brick_name text, product_code text, units numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'au', 'public'
    SET statement_timeout TO '45s'
    AS $_$
  with bounds as (
    select (date_trunc('month', to_date(p_period || '-01', 'YYYY-MM-DD'))
            + interval '1 month - 1 day')::date as period_end
    where p_period ~ '^\d{4}-\d{2}$'
      and to_date(p_period || '-01', 'YYYY-MM-DD') >= date '2026-07-01'
  ),
  fact as materialized (
    select
      f.official_line,
      nullif(btrim(f.area_code), '')                as sos_area_code,
      nullif(btrim(coalesce(f.brick_id, '')), '')   as brick_id,
      upper(btrim(coalesce(f.product_code, '')))    as product_code,
      f.total_qty
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b
      on b.id = f.batch_id and b.status = 'validated'
    where f.period = p_period
      and exists (select 1 from bounds)
      and not f.is_direct
      and nullif(btrim(coalesce(f.brick_id, '')), '') is not null
      and upper(btrim(coalesce(f.distributor_code, ''))) <> 'QM'
      and upper(btrim(coalesce(f.product_code, ''))) not in ('', 'LA003', 'LA004', 'SS001')
  ),
  lam_asof as materialized (
    select
      l.line_code, l.area_code,
      au.f_seat_occupant_asof(l.rep_seat_id, bo.period_end) as rep_occupant_hr_id,
      au.f_seat_occupant_asof(l.dm_seat_id, bo.period_end)  as dm_occupant_hr_id
    from bounds bo
    cross join lateral au.f_line_area_map_asof(bo.period_end) l
    where (p_line_codes is null or l.line_code = any (p_line_codes))
      and (p_area_codes is null or l.area_code = any (p_area_codes))
  )
  select
    p_period,
    lam.line_code,
    lam.area_code,
    lam.rep_occupant_hr_id,
    lam.dm_occupant_hr_id,
    fa.brick_id,
    sb.brick_name,
    fa.product_code,
    sum(fa.total_qty)
  from fact fa
  join au.sos_official_line_map lm
    on lower(btrim(lm.official_line)) = lower(btrim(fa.official_line))
  join au.sos_area_crosswalk cw
    on cw.sos_area_code = fa.sos_area_code
  join lam_asof lam
    on lam.line_code = lm.line_code and lam.area_code = cw.canonical_area_code
  left join public.source_of_sales_bricks sb
    on sb.brick_id = fa.brick_id
  group by
    lam.line_code, lam.area_code, lam.rep_occupant_hr_id, lam.dm_occupant_hr_id,
    fa.brick_id, sb.brick_name, fa.product_code;
$_$;

ALTER FUNCTION public.phx_make_it_happen_brick_units(p_period text, p_line_codes text[], p_area_codes text[]) OWNER TO postgres;

--
-- Name: automated_payroll_runs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    month integer NOT NULL,
    year integer NOT NULL,
    month_key text GENERATED ALWAYS AS ((((year)::text || '-'::text) || lpad((month)::text, 2, '0'::text))) STORED,
    phase text DEFAULT 'part1'::text NOT NULL,
    part1_confirmed_at timestamp with time zone,
    part1_confirmed_by text,
    part2_confirmed_at timestamp with time zone,
    part2_confirmed_by text,
    published_batch_id uuid,
    published_at timestamp with time zone,
    published_by text,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    transition_token uuid,
    transition_action text,
    transition_started_at timestamp with time zone,
    CONSTRAINT automated_payroll_runs_month_check CHECK (((month >= 1) AND (month <= 12))),
    CONSTRAINT automated_payroll_runs_phase_check CHECK ((phase = ANY (ARRAY['part1'::text, 'part2'::text, 'ready'::text, 'published'::text, 'cancelled'::text]))),
    CONSTRAINT automated_payroll_runs_year_check CHECK (((year >= 2000) AND (year <= 2100)))
);

ALTER TABLE public.automated_payroll_runs OWNER TO postgres;

--
-- Name: COLUMN automated_payroll_runs.transition_token; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_runs.transition_token IS 'Held while a phase transition is writing. Null when no transition holds the run.';

--
-- Name: COLUMN automated_payroll_runs.transition_action; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_runs.transition_action IS 'What the claiming transition is doing, in words, for the refusal a second request sees.';

--
-- Name: COLUMN automated_payroll_runs.transition_started_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_runs.transition_started_at IS 'When the claim was taken. A claim older than 15 minutes has lapsed and may be taken over.';

--
-- Name: phx_mark_automated_payroll_run_published(uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_mark_automated_payroll_run_published(p_run_id uuid, p_transition_token uuid, p_batch_id uuid, p_published_by text, p_actor_hr_id text, p_detail jsonb) RETURNS SETOF public.automated_payroll_runs
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_run public.automated_payroll_runs%rowtype;
begin
  -- The held list is the money record. A publish that cannot say who it held does not publish.
  if p_detail is null or jsonb_typeof(p_detail -> 'held') is distinct from 'array' then
    raise exception 'automated_payroll_publish_hold_record_missing: the publish record has no held list'
      using errcode = 'P0001';
  end if;

  -- Conditioned on the claim this publish holds (phx_claim_automated_payroll_run_transition) and on the
  -- phase, and clears the claim — the same rule as the app's conditioned phase write.
  update public.automated_payroll_runs
     set phase = 'published',
         published_batch_id = p_batch_id,
         published_at = now(),
         published_by = p_published_by,
         updated_at = now(),
         transition_token = null,
         transition_action = null,
         transition_started_at = null
   where id = p_run_id
     and phase = 'ready'
     and transition_token = p_transition_token
  returning * into v_run;

  if not found then
    raise exception 'automated_payroll_transition_claim_lost: [transition-claim-lost] the run was not marked published'
      using errcode = 'P0001';
  end if;

  insert into public.automated_payroll_audit (run_id, actor_hr_id, action, step_key, detail)
  values (p_run_id, p_actor_hr_id, 'published', null, p_detail);

  return next v_run;
end;
$$;

ALTER FUNCTION public.phx_mark_automated_payroll_run_published(p_run_id uuid, p_transition_token uuid, p_batch_id uuid, p_published_by text, p_actor_hr_id text, p_detail jsonb) OWNER TO postgres;

--
-- Name: FUNCTION phx_mark_automated_payroll_run_published(p_run_id uuid, p_transition_token uuid, p_batch_id uuid, p_published_by text, p_actor_hr_id text, p_detail jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_mark_automated_payroll_run_published(p_run_id uuid, p_transition_token uuid, p_batch_id uuid, p_published_by text, p_actor_hr_id text, p_detail jsonb) IS 'Marks an Automated Payroll run published and writes its published audit row (the held-salary record) in one transaction, under the publish claim. Refuses a detail with no held list (F-PAY-002).';

--
-- Name: phx_market_awareness_apply_decision(uuid, text, text, text, text, text, text, numeric, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, date, text, text, boolean, numeric, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_market_awareness_apply_decision(p_activity_id uuid, p_expected_status text, p_next_status text, p_step_code text, p_action text, p_actor_hr_id text, p_comment text DEFAULT NULL::text, p_amended_cost numeric DEFAULT NULL::numeric, p_approved_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_rejected_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_returned_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_withdrawn_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_closed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_executed_at date DEFAULT NULL::date, p_rep_hr_id_at_approval text DEFAULT NULL::text, p_dm_hr_id_at_approval text DEFAULT NULL::text, p_set_actual_cost boolean DEFAULT false, p_actual_cost numeric DEFAULT NULL::numeric, p_set_outcome_note boolean DEFAULT false, p_outcome_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  if coalesce(btrim(p_actor_hr_id), '') = '' then
    raise exception 'market awareness: a decision cannot be recorded without an actor'
      using errcode = 'check_violation';
  end if;

  select status into v_status
    from public.market_awareness_activities
   where id = p_activity_id
   for update;

  if not found then
    raise exception 'market awareness: activity % does not exist', p_activity_id
      using errcode = 'no_data_found';
  end if;

  if v_status is distinct from p_expected_status then
    return jsonb_build_object('applied', false, 'currentStatus', v_status);
  end if;

  update public.market_awareness_activities
     set status                 = p_next_status,
         updated_by_hr_id       = p_actor_hr_id,
         approved_at            = coalesce(p_approved_at, approved_at),
         rejected_at            = coalesce(p_rejected_at, rejected_at),
         returned_at            = case when p_next_status = 'returned' then p_returned_at else returned_at end,
         withdrawn_at           = coalesce(p_withdrawn_at, withdrawn_at),
         closed_at              = coalesce(p_closed_at, closed_at),
         executed_at            = coalesce(p_executed_at, executed_at),
         amended_cost           = coalesce(p_amended_cost, amended_cost),
         rep_hr_id_at_approval  = case when p_next_status = 'approved' then p_rep_hr_id_at_approval else rep_hr_id_at_approval end,
         dm_hr_id_at_approval   = case when p_next_status = 'approved' then p_dm_hr_id_at_approval else dm_hr_id_at_approval end,
         actual_cost            = case when p_set_actual_cost then p_actual_cost else actual_cost end,
         outcome_note           = case when p_set_outcome_note then p_outcome_note else outcome_note end
   where id = p_activity_id;

  insert into public.market_awareness_decisions (
    activity_id, step_code, actor_hr_id, action, comment, amended_cost
  ) values (
    p_activity_id, p_step_code, p_actor_hr_id, p_action, nullif(btrim(coalesce(p_comment, '')), ''), p_amended_cost
  );

  return jsonb_build_object('applied', true, 'currentStatus', p_next_status);
end;
$$;

ALTER FUNCTION public.phx_market_awareness_apply_decision(p_activity_id uuid, p_expected_status text, p_next_status text, p_step_code text, p_action text, p_actor_hr_id text, p_comment text, p_amended_cost numeric, p_approved_at timestamp with time zone, p_rejected_at timestamp with time zone, p_returned_at timestamp with time zone, p_withdrawn_at timestamp with time zone, p_closed_at timestamp with time zone, p_executed_at date, p_rep_hr_id_at_approval text, p_dm_hr_id_at_approval text, p_set_actual_cost boolean, p_actual_cost numeric, p_set_outcome_note boolean, p_outcome_note text) OWNER TO postgres;

--
-- Name: FUNCTION phx_market_awareness_apply_decision(p_activity_id uuid, p_expected_status text, p_next_status text, p_step_code text, p_action text, p_actor_hr_id text, p_comment text, p_amended_cost numeric, p_approved_at timestamp with time zone, p_rejected_at timestamp with time zone, p_returned_at timestamp with time zone, p_withdrawn_at timestamp with time zone, p_closed_at timestamp with time zone, p_executed_at date, p_rep_hr_id_at_approval text, p_dm_hr_id_at_approval text, p_set_actual_cost boolean, p_actual_cost numeric, p_set_outcome_note boolean, p_outcome_note text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_market_awareness_apply_decision(p_activity_id uuid, p_expected_status text, p_next_status text, p_step_code text, p_action text, p_actor_hr_id text, p_comment text, p_amended_cost numeric, p_approved_at timestamp with time zone, p_rejected_at timestamp with time zone, p_returned_at timestamp with time zone, p_withdrawn_at timestamp with time zone, p_closed_at timestamp with time zone, p_executed_at date, p_rep_hr_id_at_approval text, p_dm_hr_id_at_approval text, p_set_actual_cost boolean, p_actual_cost numeric, p_set_outcome_note boolean, p_outcome_note text) IS 'Applies one Market Awareness decision and its audit row in a single transaction, refusing to write at all when the activity has moved since the caller read it. The workflow rules stay in src/lib/market-awareness/ — this guarantees atomicity and the precondition, nothing else.';

--
-- Name: phx_market_awareness_apply_group_decision(uuid, text, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_market_awareness_apply_group_decision(p_activity_id uuid, p_expected_status text, p_action text, p_actor_hr_id text, p_slot_id bigint DEFAULT NULL::bigint, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
  v_held_at timestamptz;
  v_step_opened_at timestamptz;
  v_slot record;
  v_next_status text;
  v_pending integer;
  v_refused integer;
  v_now timestamptz := now();
begin
  if coalesce(btrim(p_actor_hr_id), '') = '' then
    raise exception 'market awareness: a decision cannot be recorded without an actor'
      using errcode = 'check_violation';
  end if;

  if p_action not in ('approve', 'reject', 'return', 'hold', 'release') then
    raise exception 'market awareness: % is not a group action', p_action
      using errcode = 'check_violation';
  end if;

  -- FOR UPDATE, so a second decision arriving at the same moment waits here and then reads the
  -- status this one wrote, rather than the status both of them read a moment ago.
  select status, held_at, step_opened_at
    into v_status, v_held_at, v_step_opened_at
    from public.market_awareness_activities
   where id = p_activity_id
   for update;

  if not found then
    raise exception 'market awareness: activity % does not exist', p_activity_id
      using errcode = 'no_data_found';
  end if;

  if v_status is distinct from p_expected_status then
    -- Not an error: somebody else decided it first. NOTHING has been written.
    return jsonb_build_object('applied', false, 'currentStatus', v_status);
  end if;

  if p_action in ('approve', 'reject', 'return') then
    if p_slot_id is null then
      raise exception 'market awareness: a group % needs the slot it answers', p_action
        using errcode = 'check_violation';
    end if;

    select * into v_slot
      from public.market_awareness_activity_approvers
     where id = p_slot_id
       and activity_id = p_activity_id
     for update;

    if not found then
      raise exception 'market awareness: approver slot % does not belong to activity %',
        p_slot_id, p_activity_id
        using errcode = 'no_data_found';
    end if;

    if v_slot.decision is not null then
      -- A double-click, or two tabs. Already answered is a real answer, not a failure.
      return jsonb_build_object(
        'applied', false,
        'currentStatus', v_status,
        'reason', 'slot_already_decided'
      );
    end if;

    update public.market_awareness_activity_approvers
       set decision         = p_action,
           decided_by_hr_id = p_actor_hr_id,
           decided_at       = v_now,
           comment          = nullif(btrim(coalesce(p_comment, '')), '')
     where id = p_slot_id;

    if p_action = 'approve' then
      -- The gate, asked of the rows as they now stand — this approval included.
      select count(*) filter (where decision is null),
             count(*) filter (where decision is not null and decision <> 'approve')
        into v_pending, v_refused
        from public.market_awareness_activity_approvers
       where activity_id = p_activity_id;

      -- Positive: everybody answered AND every answer was yes. "Nothing outstanding" would move an
      -- activity with no approvers at all straight to the CEO with nobody having looked at it.
      if v_pending = 0 and v_refused = 0 then
        v_next_status := 'pending_ceo';
      else
        v_next_status := 'pending_group';
      end if;
    elsif p_action = 'reject' then
      v_next_status := 'rejected';
    else
      v_next_status := 'returned';
    end if;

  elsif p_action = 'hold' then
    if coalesce(btrim(p_comment), '') = '' then
      raise exception 'market awareness: a hold has to say why'
        using errcode = 'check_violation';
    end if;
    v_next_status := 'on_hold';
  else
    v_next_status := 'pending_group';
  end if;

  update public.market_awareness_activities
     set status           = v_next_status,
         updated_by_hr_id = p_actor_hr_id,
         rejected_at      = case when v_next_status = 'rejected' then v_now else rejected_at end,
         returned_at      = case when v_next_status = 'returned' then v_now else returned_at end,
         held_by_hr_id    = case when p_action = 'hold' then p_actor_hr_id
                                 when p_action = 'release' then null
                                 else held_by_hr_id end,
         held_at          = case when p_action = 'hold' then v_now
                                 when p_action = 'release' then null
                                 else held_at end,
         hold_reason      = case when p_action = 'hold' then nullif(btrim(coalesce(p_comment, '')), '')
                                 when p_action = 'release' then null
                                 else hold_reason end,
         -- The CEO's clock starts when the group finishes, not when the activity was submitted.
         -- On release the clock is advanced by exactly how long it sat frozen, so a hold stops it
         -- instead of hiding a breach that had already accrued.
         step_opened_at   = case
                              when v_next_status = 'pending_ceo' then v_now
                              when p_action = 'release' and v_held_at is not null
                                then coalesce(v_step_opened_at, v_held_at) + (v_now - v_held_at)
                              else step_opened_at
                            end
   where id = p_activity_id;

  -- ONE decision row, under the identity of whoever actually acted. If this raises, everything above
  -- goes with it — which is the entire point of doing it here.
  insert into public.market_awareness_decisions (
    activity_id, step_code, actor_hr_id, action, comment
  ) values (
    p_activity_id, 'group', p_actor_hr_id, p_action,
    nullif(btrim(coalesce(p_comment, '')), '')
  );

  return jsonb_build_object(
    'applied', true,
    'currentStatus', v_next_status,
    'groupComplete', v_next_status = 'pending_ceo'
  );
end;
$$;

ALTER FUNCTION public.phx_market_awareness_apply_group_decision(p_activity_id uuid, p_expected_status text, p_action text, p_actor_hr_id text, p_slot_id bigint, p_comment text) OWNER TO postgres;

--
-- Name: FUNCTION phx_market_awareness_apply_group_decision(p_activity_id uuid, p_expected_status text, p_action text, p_actor_hr_id text, p_slot_id bigint, p_comment text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_market_awareness_apply_group_decision(p_activity_id uuid, p_expected_status text, p_action text, p_actor_hr_id text, p_slot_id bigint, p_comment text) IS 'Applies one Market Awareness group decision, its slot and its audit row in a single transaction, refusing to write at all when the activity or the slot has moved since the caller read it. The parallel gate — has everybody now approved — is computed inside the same lock, because asking it before the write lets two simultaneous approvals both see one still outstanding.';

--
-- Name: phx_market_awareness_areas(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_market_awareness_areas(p_line_code text) RETURNS TABLE(region_code text, region_name text, area_code text, area_name text, area_state text, selectable boolean, unselectable_reason text, rep_seat_id text, rep_hr_id text, rep_name text, dm_seat_id text, dm_hr_id text, dm_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
  with live_map as (
    select m.*
    from au.line_area_map m
    where lower(btrim(m.line_code)) = lower(btrim(p_line_code))
      and m.effective_to is null
  ),
  current_occupancy as (
    select distinct on (o.seat_id)
      o.seat_id,
      o.occupant_hr_id
    from au.occupancy_history o
    where o.effective_to is null
    order by o.seat_id, o.effective_from desc
  )
  select
    m.operational_region_code as region_code,
    coalesce(r.region_name, m.operational_region_code) as region_name,
    m.area_code,
    coalesce(ca.area_name, m.area_code) as area_name,
    m.area_state,
    (m.area_state in ('occupied', 'vacant_will_hire')) as selectable,
    case
      when m.area_state in ('occupied', 'vacant_will_hire') then null
      else 'Not a territory — this is a reporting bucket, not a place an activity can be held in'
    end as unselectable_reason,
    m.rep_seat_id,
    rep_occ.occupant_hr_id as rep_hr_id,
    rep_emp.full_name as rep_name,
    m.dm_seat_id,
    dm_occ.occupant_hr_id as dm_hr_id,
    dm_emp.full_name as dm_name
  from live_map m
  left join au.regions r
    on lower(btrim(r.region_code)) = lower(btrim(m.operational_region_code))
  left join au.canonical_areas ca
    on lower(btrim(ca.area_code)) = lower(btrim(m.area_code))
  left join current_occupancy rep_occ on rep_occ.seat_id = m.rep_seat_id
  left join current_occupancy dm_occ  on dm_occ.seat_id  = m.dm_seat_id
  left join public.employees rep_emp
    on lower(btrim(rep_emp.hr_id)) = lower(btrim(rep_occ.occupant_hr_id))
  left join public.employees dm_emp
    on lower(btrim(dm_emp.hr_id)) = lower(btrim(dm_occ.occupant_hr_id))
  order by m.operational_region_code, m.area_code;
$$;

ALTER FUNCTION public.phx_market_awareness_areas(p_line_code text) OWNER TO postgres;

--
-- Name: FUNCTION phx_market_awareness_areas(p_line_code text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_market_awareness_areas(p_line_code text) IS 'Region -> area cascade for one line, with the current rep and district manager resolved from au.occupancy_history. Non-territory areas are returned with selectable = false and a reason rather than filtered out, because the owner chose to show them greyed (2026-09-06).';

