-- Name: phx_market_awareness_products(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_market_awareness_products(p_line_code text) RETURNS TABLE(product_code text, product_name text, line_name text, factory_price numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    p.product_code,
    p.product_name,
    p.line as line_name,
    p.factory_price
  from public.source_of_sales_products p
  where p.active
    and lower(btrim(p.line)) in (
      select lower(btrim(m.official_line))
      from au.sos_official_line_map m
      join au.lines l on lower(btrim(l.line_code)) = lower(btrim(m.line_code))
      where lower(btrim(m.line_code)) = lower(btrim(p_line_code))
        and l.is_closing_line
        and l.is_active
    )
  order by p.product_name;
$$;

