COMMENT ON FUNCTION public.phx_market_awareness_region_managers(p_line_code text, p_region_code text) IS 'Every district manager seat in one region for one line, with its current occupant. A seat with a null dm_hr_id is a real vacancy, not a missing join — return it and let the caller say so.';

--
-- Name: phx_market_awareness_tracking(text, text, text, text, text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_market_awareness_tracking(p_line_code text, p_from_period text, p_to_period text, p_area_code text, p_brick_ids text[], p_product_codes text[]) RETURNS TABLE(period text, scope text, indirect_units numeric, indirect_value numeric, direct_units numeric, direct_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    SET enable_nestloop TO 'off'
    AS $$
  with period_price as (
    select d.product_code, d.period,
           public.phx_factory_price(d.product_code, d.period) as period_price
    from (
      select distinct f.product_code, f.period
      from public.source_of_sales_fact_rollup f
      where f.period between p_from_period and p_to_period
    ) d
  ),
  rows_in_window as (
    select
      f.period,
      f.area_code,
      f.brick_id,
      f.is_direct,
      f.total_qty,
      f.effective_units,
      f.direct_value,
      f.product_code
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b
      on b.id = f.batch_id and b.status = 'validated'
    where f.period between p_from_period and p_to_period
      and lower(btrim(f.official_line)) in (
        select lower(btrim(m.official_line))
        from au.sos_official_line_map m
        where lower(btrim(m.line_code)) = lower(btrim(p_line_code))
      )
      and upper(btrim(f.product_code)) = any (
        select upper(btrim(code)) from unnest(p_product_codes) as code
      )
      and (
        not f.is_direct
        or upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
      )
      and not (f.is_direct and f.period = '2026-07')
  ),
  priced as (
    select
      r.*,
      r.effective_units * coalesce(pp.period_price, 0) as indirect_value
    from rows_in_window r
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
    left join period_price pp
      on pp.product_code = r.product_code and pp.period = r.period
  ),
  scoped as (
    select 'brick'::text as scope, * from priced
     where brick_id = any (p_brick_ids)
    union all
    select 'area'::text, * from priced
     where btrim(area_code) = btrim(p_area_code)
    union all
    select 'area_bricked'::text, * from priced
     where btrim(area_code) = btrim(p_area_code)
       and brick_id is not null
       and btrim(brick_id) <> ''
  )
  select
    s.period,
    s.scope,
    coalesce(sum(s.total_qty)      filter (where not s.is_direct), 0) as indirect_units,
    coalesce(sum(s.indirect_value) filter (where not s.is_direct), 0) as indirect_value,
    coalesce(sum(s.total_qty)      filter (where s.is_direct), 0)     as direct_units,
    coalesce(sum(s.direct_value)   filter (where s.is_direct), 0)     as direct_value
  from scoped s
  group by s.period, s.scope;
$$;

ALTER FUNCTION public.phx_market_awareness_tracking(p_line_code text, p_from_period text, p_to_period text, p_area_code text, p_brick_ids text[], p_product_codes text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_market_awareness_tracking(p_line_code text, p_from_period text, p_to_period text, p_area_code text, p_brick_ids text[], p_product_codes text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_market_awareness_tracking(p_line_code text, p_from_period text, p_to_period text, p_area_code text, p_brick_ids text[], p_product_codes text[]) IS 'Market Awareness tracking series: brick, area, and area-counting-only-bricked-rows, per period, for one line and a product set. Reads source_of_sales_fact_rollup on validated batches, which reconciles exactly with phx_closing_distributor_product (verified 0 difference on all three tracked lines for 2026-08). Returns both halves of the closing separately so a caller can never quote one of them by accident.';

--
-- Name: phx_marketing_coverage_export_sales_detail(uuid[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_coverage_export_sales_detail(p_request_ids uuid[], p_exclude_product_codes text[] DEFAULT '{LA003,LA004,SS001}'::text[]) RETURNS TABLE(request_id uuid, distributor_code text, distributor_name text, invoice_period text, product_code text, product_name text, customer_code text, customer_name text, region_name text, qty numeric, value numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with excl as (
    select array(select upper(btrim(c)) from unnest(coalesce(p_exclude_product_codes, '{}'::text[])) c) as codes
  ),
  req as (
    select mr.id, mr.pay_date, greatest(coalesce(mr.roi_duration_months, 1), 1) as months
    from public.marketing_requests mr
    where mr.id = any(p_request_ids) and mr.pay_date is not null
  ),
  win as (
    select req.id as request_id, to_char(g, 'YYYY-MM') as period
    from req
    cross join lateral generate_series(
      date_trunc('month', req.pay_date),
      date_trunc('month', req.pay_date) + make_interval(months => req.months - 1),
      interval '1 month'
    ) g
  ),
  req_products as (
    select distinct mrp.request_id, sp.product_code
    from public.marketing_request_products mrp
    join public.marketing_products mp on mp.id = mrp.product_id
    join public.source_of_sales_products sp
      on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
    cross join excl
    where mrp.request_id = any(p_request_ids)
      and upper(btrim(sp.product_code)) <> all(excl.codes)
  ),
  req_targets as (
    -- join source_of_sales_distributors so a rollup code with no SoS distributor row is
    -- dropped IDENTICALLY to phx_marketing_request_roi_actuals / the single-request RPC.
    select distinct
      mrph.request_id,
      sd.distributor_code as family_code,
      ru.parent_distributor_code,
      mpdc.normalized_pharmacy_code as customer_code
    from public.marketing_request_pharmacies mrph
    join public.marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
    join public.marketing_distributors md on md.id = mpdc.distributor_id
    join public.marketing_roi_distributor_rollup ru on ru.marketing_normalized_name = md.normalized_name
    join public.source_of_sales_distributors sd on sd.distributor_code = ru.sos_distributor_code
    where mrph.request_id = any(p_request_ids)
      and coalesce(btrim(mpdc.normalized_pharmacy_code), '') <> ''
  ),
  target_products as (
    select distinct rt.request_id, rt.family_code, rt.parent_distributor_code, rt.customer_code, rp.product_code
    from req_targets rt
    join req_products rp on rp.request_id = rt.request_id
  ),
  hits as (
    -- dedup per (request, matched SoS row): the SAME underlying sale can legitimately
    -- satisfy more than one request in the batch, but must never appear twice for the
    -- SAME request (mirrors the single-request RPC's `distinct on (r.id)` exactly, just
    -- scoped per request instead of globally, since this now covers many requests at once).
    select distinct on (tp.request_id, r.id)
      tp.request_id,
      r.id as row_id,
      tp.parent_distributor_code,
      r.invoice_period,
      r.product_code,
      coalesce(sp.product_name, r.product_name, r.product_code) as product_name,
      tp.customer_code,
      r.client_name as customer_name,
      r.region_name,
      r.qty as qty,
      case when coalesce(r.is_direct, false)
           then coalesce(r.value, 0)
           else r.qty * coalesce(public.phx_factory_price(r.product_code, r.invoice_period), 0)
      end as value
    from target_products tp
    join win on win.request_id = tp.request_id
    join public.source_of_sales_import_rows r
      on r.distributor_code = tp.family_code
     and lower(btrim(regexp_replace(coalesce(r.client_code, ''), '\s+', ' ', 'g'))) = tp.customer_code
     and upper(btrim(r.product_code)) = upper(btrim(tp.product_code))
     and r.invoice_period = win.period
     and r.validation_state = 'valid'
    join public.source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
    join public.source_of_sales_products sp on upper(btrim(sp.product_code)) = upper(btrim(r.product_code))
    order by tp.request_id, r.id
  )
  select
    hits.request_id,
    hits.parent_distributor_code as distributor_code,
    coalesce(sd.distributor_name, hits.parent_distributor_code) as distributor_name,
    hits.invoice_period,
    hits.product_code,
    hits.product_name,
    hits.customer_code,
    hits.customer_name,
    hits.region_name,
    hits.qty::numeric,
    hits.value::numeric
  from hits
  left join public.source_of_sales_distributors sd on sd.distributor_code = hits.parent_distributor_code
  order by hits.request_id, hits.invoice_period, hits.parent_distributor_code, hits.product_code;
$$;

ALTER FUNCTION public.phx_marketing_coverage_export_sales_detail(p_request_ids uuid[], p_exclude_product_codes text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_coverage_export_sales_detail(p_request_ids uuid[], p_exclude_product_codes text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_coverage_export_sales_detail(p_request_ids uuid[], p_exclude_product_codes text[]) IS 'Marketing Coverage Report export — BULK per-sale detail (product + invoice month + pharmacy) across MANY requests in one call, each using its own default ROI window. Confidential products excluded unless an empty exclude array is passed (CEO/Super Admin only). Never call phx_marketing_request_view_sales in a loop for export.';

--
-- Name: phx_marketing_customer_merge_options(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_customer_merge_options() RETURNS TABLE(id uuid, customer_code text, display_name text, normalized_name text, customer_type text, line_name text, area_name text, owner_name text, evidence_status text, evidence_complete boolean, validation_status text, requests bigint, contacts bigint, links bigint, live_transfer boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
  select
    c.id,
    c.customer_code,
    c.display_name,
    c.normalized_name,
    c.customer_type,
    l.name,
    a.name,
    e.full_name,
    c.evidence_status,
    (c.evidence_status = 'complete' and c.captured_at is not null and c.evidence_photo_name is not null),
    c.validation_status,
    (select count(*) from marketing_requests q where q.customer_id = c.id),
    (select count(*) from marketing_customer_contacts k where k.customer_id = c.id),
    (select count(*) from marketing_customer_pharmacies p where p.customer_id = c.id),
    exists (select 1 from marketing_customer_direct_order_transfers t where t.customer_id = c.id and t.status = 'transferred')
  from marketing_customers c
  left join lines l on l.id = c.line_id
  left join areas a on a.id = c.area_id
  left join employees e on e.hr_id = c.owner_hr_id
  where c.active and c.merged_into_customer_id is null
  order by c.display_name;
$$;

ALTER FUNCTION public.phx_marketing_customer_merge_options() OWNER TO postgres;

--
-- Name: phx_marketing_pharmacy_mapping_coverage(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_pharmacy_mapping_coverage() RETURNS TABLE(total_targets integer, mapped_targets integer, total_requests integer, requests_with_unmapped integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with req_targets as (
    select distinct
      mrph.request_id,
      mpdc.normalized_pharmacy_code as customer_code,
      (select cmx.region_code
       from public.source_of_sales_customer_map cmx
       where lower(btrim(regexp_replace(coalesce(cmx.customer_code, ''), '\s+', ' ', 'g'))) = mpdc.normalized_pharmacy_code
         and cmx.active
         and (cmx.distributor_code = sd.distributor_code
              or exists (select 1 from public.marketing_roi_distributor_rollup rcm
                         where rcm.parent_distributor_code = sd.distributor_code
                           and rcm.sos_distributor_code = cmx.distributor_code))
       order by (cmx.distributor_code = sd.distributor_code) desc, cmx.region_code nulls last
       limit 1) as region_code
    from public.marketing_requests mr
    join public.marketing_request_pharmacies mrph on mrph.request_id = mr.id
    join public.marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
    join public.marketing_distributors md on md.id = mpdc.distributor_id
    join (select distinct marketing_normalized_name, parent_distributor_code from public.marketing_roi_distributor_rollup) ru
      on ru.marketing_normalized_name = md.normalized_name
    join public.source_of_sales_distributors sd on sd.distributor_code = ru.parent_distributor_code
    where mr.pay_date is not null
      and coalesce(btrim(mpdc.normalized_pharmacy_code), '') <> ''
      and coalesce(mpdc.active, true)
  )
  select
    count(*)::integer as total_targets,
    count(*) filter (where region_code is not null)::integer as mapped_targets,
    count(distinct request_id)::integer as total_requests,
    count(distinct request_id) filter (where region_code is null)::integer as requests_with_unmapped
  from req_targets;
$$;

ALTER FUNCTION public.phx_marketing_pharmacy_mapping_coverage() OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_pharmacy_mapping_coverage(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_pharmacy_mapping_coverage() IS 'Data Health: marketing-request pharmacy -> brick/region mapping coverage (rollup-family-aware). total/mapped target pharmacies + requests with an unmapped pharmacy.';

--
-- Name: phx_marketing_request_events_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_request_events_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  raise exception 'marketing_request_events is append-only; % is not permitted', tg_op
    using errcode = 'restrict_violation';
end;
$$;

