--
-- Name: phx_marketing_request_roi_actuals(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_request_roi_actuals(p_request_ids uuid[]) RETURNS TABLE(request_id uuid, actual_value numeric, actual_units numeric, sales_rows integer, exact_sales_rows integer, fallback_sales_rows integer, attribution_quality text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with req as (
    select mr.id, mr.pay_date, greatest(coalesce(mr.roi_duration_months, 1), 1) as months
    from public.marketing_requests mr
    where mr.id = any(p_request_ids) and mr.pay_date is not null
  ),
  periods as (
    select req.id, array_agg(to_char(g, 'YYYY-MM')) as periods
    from req
    cross join lateral generate_series(
      date_trunc('month', req.pay_date),
      date_trunc('month', req.pay_date) + make_interval(months => req.months - 1),
      interval '1 month'
    ) as g
    group by req.id
  ),
  req_products as (
    select distinct mrp.request_id, sp.product_code
    from public.marketing_request_products mrp
    join public.marketing_products mp on mp.id = mrp.product_id
    join public.source_of_sales_products sp
      on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
    where mrp.request_id = any(p_request_ids)
  ),
  req_targets as (
    select distinct
      mrph.request_id,
      sd.distributor_code,
      mpdc.normalized_pharmacy_code as customer_code
    from public.marketing_request_pharmacies mrph
    join public.marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
    join public.marketing_distributors md on md.id = mpdc.distributor_id
    join public.marketing_roi_distributor_rollup ru on ru.marketing_normalized_name = md.normalized_name
    join public.source_of_sales_distributors sd on sd.distributor_code = ru.sos_distributor_code
    where mrph.request_id = any(p_request_ids)
      and coalesce(btrim(mpdc.normalized_pharmacy_code), '') <> ''
  ),
  target_products as (
    select distinct rt.request_id, rt.distributor_code, rt.customer_code, rp.product_code
    from req_targets rt
    join req_products rp on rp.request_id = rt.request_id
  ),
  exact_hits as (
    select distinct
      tp.request_id,
      r.id as row_id,
      r.qty as units,
      case when coalesce(r.is_direct, false)
           then coalesce(r.value, 0)
           else r.qty * coalesce(public.phx_factory_price(r.product_code, r.invoice_period), 0)
      end as value
    from target_products tp
    join periods on periods.id = tp.request_id
    join public.source_of_sales_import_rows r
      on r.distributor_code = tp.distributor_code
     and lower(btrim(regexp_replace(coalesce(r.client_code, ''), '\s+', ' ', 'g'))) = tp.customer_code
     and upper(btrim(r.product_code)) = upper(btrim(tp.product_code))
     and r.invoice_period = any(periods.periods)
     and r.validation_state = 'valid'
    join public.source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
    join public.source_of_sales_products sp on upper(btrim(sp.product_code)) = upper(btrim(r.product_code))
  ),
  actuals as (
    select
      request_id,
      coalesce(sum(value), 0)::numeric as actual_value,
      coalesce(sum(units), 0)::numeric as actual_units,
      count(distinct row_id)::integer as sales_rows
    from exact_hits
    group by request_id
  )
  select
    req.id as request_id,
    coalesce(actuals.actual_value, 0)::numeric as actual_value,
    coalesce(actuals.actual_units, 0)::numeric as actual_units,
    coalesce(actuals.sales_rows, 0)::integer as sales_rows,
    coalesce(actuals.sales_rows, 0)::integer as exact_sales_rows,
    0::integer as fallback_sales_rows,
    case when coalesce(actuals.sales_rows, 0) = 0 then 'no_sales' else 'exact_customer' end as attribution_quality
  from req
  left join actuals on actuals.request_id = req.id;
$$;

ALTER FUNCTION public.phx_marketing_request_roi_actuals(p_request_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_request_roi_actuals(p_request_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_request_roi_actuals(p_request_ids uuid[]) IS 'Realized marketing ROI sales per request. Prefers exact distributor + customer_code attribution; uses brick fallback only when no exact request/brick/product sales rows exist. Server-only (service_role).';

--
-- Name: phx_marketing_request_roi_actuals_v2(uuid[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_request_roi_actuals_v2(p_request_ids uuid[], p_exclude_product_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]) RETURNS TABLE(request_id uuid, actual_value numeric, actual_units numeric, sales_rows integer, exact_sales_rows integer, fallback_sales_rows integer, attribution_quality text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with req as (
    select mr.id
    from public.marketing_requests mr
    where mr.id = any(p_request_ids) and mr.pay_date is not null
  ),
  actuals as (
    select
      l.request_id,
      coalesce(sum(l.value), 0)::numeric as actual_value,
      coalesce(sum(l.qty), 0)::numeric as actual_units,
      count(distinct l.source_row_id)::integer as sales_rows
    from public.phx_marketing_request_sales_lines(p_request_ids, p_exclude_product_codes) l
    group by l.request_id
  )
  select
    req.id as request_id,
    coalesce(actuals.actual_value, 0)::numeric as actual_value,
    coalesce(actuals.actual_units, 0)::numeric as actual_units,
    coalesce(actuals.sales_rows, 0)::integer as sales_rows,
    coalesce(actuals.sales_rows, 0)::integer as exact_sales_rows,
    0::integer as fallback_sales_rows,
    case when coalesce(actuals.sales_rows, 0) = 0 then 'no_sales' else 'exact_customer' end as attribution_quality
  from req
  left join actuals on actuals.request_id = req.id;
$$;

ALTER FUNCTION public.phx_marketing_request_roi_actuals_v2(p_request_ids uuid[], p_exclude_product_codes text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_request_roi_actuals_v2(p_request_ids uuid[], p_exclude_product_codes text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_request_roi_actuals_v2(p_request_ids uuid[], p_exclude_product_codes text[]) IS 'ROI per-request actuals with confidential-product exclusion (LA003/LA004/SS001 masking for non-revealing viewers). Empty exclude array == phx_marketing_request_roi_actuals.';

--
-- Name: phx_marketing_request_sales_lines(uuid[], text[], text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_request_sales_lines(p_request_ids uuid[], p_exclude_product_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text], p_from_period text DEFAULT NULL::text, p_to_period text DEFAULT NULL::text) RETURNS TABLE(request_id uuid, channel text, source_row_id text, distributor_code text, distributor_name text, customer_code text, customer_name text, product_code text, product_name text, invoice_period text, region_name text, qty numeric, value numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $_$
  with excl as (
    select array(select upper(btrim(c)) from unnest(coalesce(p_exclude_product_codes, '{}'::text[])) c) as codes
  ),
  req as (
    select mr.id, mr.pay_date, greatest(coalesce(mr.roi_duration_months, 1), 1) as months,
           coalesce(mr.track_direct_sales, false) as track_direct_sales
    from public.marketing_requests mr
    where mr.id = any(p_request_ids) and mr.pay_date is not null
  ),
  win as (
    select case
      when p_from_period ~ '^\d{4}-\d{2}$' and p_to_period ~ '^\d{4}-\d{2}$' and p_from_period <= p_to_period
        then array(
          select to_char(g, 'YYYY-MM')
          from generate_series(to_date(p_from_period, 'YYYY-MM'), to_date(p_to_period, 'YYYY-MM'), interval '1 month') g
        )
      else null::text[]
    end as periods
  ),
  pay_periods as (
    select req.id, array_agg(to_char(g, 'YYYY-MM')) as periods
    from req
    cross join lateral generate_series(
      date_trunc('month', req.pay_date),
      date_trunc('month', req.pay_date) + make_interval(months => req.months - 1),
      interval '1 month'
    ) as g
    group by req.id
  ),
  periods as (
    select ids.id, coalesce(win.periods, pay_periods.periods) as periods
    from (select distinct u.id from unnest(coalesce(p_request_ids, '{}'::uuid[])) as u(id)) ids
    cross join win
    left join pay_periods on pay_periods.id = ids.id
  ),
  req_products as (
    select distinct mrp.request_id, sp.product_code
    from public.marketing_request_products mrp
    join public.marketing_products mp on mp.id = mrp.product_id
    join public.source_of_sales_products sp
      on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
    cross join excl
    where mrp.request_id = any(p_request_ids)
      and upper(btrim(sp.product_code)) <> all(excl.codes)
  ),
  req_targets as (
    select distinct
      mrph.request_id,
      sd.distributor_code as family_code,
      ru.parent_distributor_code,
      mpdc.normalized_pharmacy_code as customer_code
    from public.marketing_request_pharmacies mrph
    join public.marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
    join public.marketing_distributors md on md.id = mpdc.distributor_id
    join public.marketing_roi_distributor_rollup ru on ru.marketing_normalized_name = md.normalized_name
    join public.source_of_sales_distributors sd on sd.distributor_code = ru.sos_distributor_code
    where mrph.request_id = any(p_request_ids)
      and coalesce(btrim(mpdc.normalized_pharmacy_code), '') <> ''
  ),
  target_products as (
    select distinct rt.request_id, rt.family_code, rt.parent_distributor_code, rt.customer_code, rp.product_code
    from req_targets rt
    join req_products rp on rp.request_id = rt.request_id
  ),
  retail_hits as (
    select distinct on (tp.request_id, r.id)
      tp.request_id,
      'retail'::text as channel,
      r.id::text as source_row_id,
      tp.parent_distributor_code::text as distributor_code,
      coalesce(sd.distributor_name, tp.parent_distributor_code)::text as distributor_name,
      tp.customer_code::text as customer_code,
      r.client_name::text as customer_name,
      r.product_code::text as product_code,
      coalesce(sp.product_name, r.product_name, r.product_code)::text as product_name,
      r.invoice_period::text as invoice_period,
      r.region_name::text as region_name,
      r.qty::numeric as qty,
      (case when coalesce(r.is_direct, false)
            then coalesce(r.value, 0)
            else r.qty * coalesce(public.phx_factory_price(r.product_code, r.invoice_period), 0)
       end)::numeric as value
    from target_products tp
    join periods on periods.id = tp.request_id
    join public.source_of_sales_import_rows r
      on r.distributor_code = tp.family_code
     and lower(btrim(regexp_replace(coalesce(r.client_code, ''), '\s+', ' ', 'g'))) = tp.customer_code
     and upper(btrim(r.product_code)) = upper(btrim(tp.product_code))
     and r.invoice_period = any(periods.periods)
     and r.validation_state = 'valid'
    join public.source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
    join public.source_of_sales_products sp on upper(btrim(sp.product_code)) = upper(btrim(r.product_code))
    left join public.source_of_sales_distributors sd on sd.distributor_code = tp.parent_distributor_code
    order by tp.request_id, r.id
  ),
  direct_hits as (
    select distinct on (mrph.request_id, dor.id)
      mrph.request_id,
      'direct'::text as channel,
      dor.id::text as source_row_id,
      sd.distributor_code::text as distributor_code,
      sd.distributor_name::text as distributor_name,
      mpdc.normalized_pharmacy_code::text as customer_code,
      null::text as customer_name,
      dor.product_code::text as product_code,
      null::text as product_name,
      dor.sales_month::text as invoice_period,
      null::text as region_name,
      coalesce(dor.qty, 0)::numeric as qty,
      coalesce(dor.sales_value, 0)::numeric as value
    from req
    join periods on periods.id = req.id
    join req_products rp on rp.request_id = req.id
    join public.marketing_request_pharmacies mrph on mrph.request_id = req.id
    join public.marketing_pharmacy_distributor_codes mpdc
      on mpdc.id = mrph.distributor_code_id and coalesce(mpdc.active, true)
    join public.marketing_distributors md on md.id = mpdc.distributor_id
    join public.marketing_roi_distributor_rollup ru on ru.marketing_normalized_name = md.normalized_name
    join public.source_of_sales_distributors sd on sd.distributor_code = ru.sos_distributor_code
    join public.direct_order_pharmacy_distributor_codes dopdc
      on lower(btrim(dopdc.distributor_code)) = lower(btrim(sd.distributor_code))
     and lower(btrim(regexp_replace(coalesce(dopdc.customer_code, ''), '\s+', ' ', 'g')))
       = lower(btrim(regexp_replace(coalesce(mpdc.normalized_pharmacy_code, ''), '\s+', ' ', 'g')))
    join public.direct_order_requests dor
      on dor.pharmacy_id = dopdc.pharmacy_id
     and dor.status = 'approved'
     and dor.reversal_of_request_id is null
     and dor.sales_month = any(periods.periods)
     and upper(btrim(dor.product_code)) = upper(btrim(rp.product_code))
    where req.track_direct_sales = true
    order by mrph.request_id, dor.id
  )
  select * from retail_hits
  union all
  select * from direct_hits;
$_$;

ALTER FUNCTION public.phx_marketing_request_sales_lines(p_request_ids uuid[], p_exclude_product_codes text[], p_from_period text, p_to_period text) OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_request_sales_lines(p_request_ids uuid[], p_exclude_product_codes text[], p_from_period text, p_to_period text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_request_sales_lines(p_request_ids uuid[], p_exclude_product_codes text[], p_from_period text, p_to_period text) IS 'Single source of truth for "which realized sales rows belong to a marketing request". Emits one line per (request, source row) with channel = retail (Source-of-Sales invoice rows) or direct (approved Direct Order Requests, gated on track_direct_sales). phx_marketing_request_roi_actuals_v2 aggregates it; phx_marketing_request_view_sales projects it filtered to retail. Change a matching rule HERE and both engines move together.';

--
-- Name: phx_marketing_request_view_sales(uuid, text, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_request_view_sales(p_request_id uuid, p_from_period text DEFAULT NULL::text, p_to_period text DEFAULT NULL::text, p_exclude_product_codes text[] DEFAULT '{LA003,LA004,SS001}'::text[]) RETURNS TABLE(distributor_code text, distributor_name text, invoice_period text, product_code text, product_name text, customer_code text, customer_name text, region_name text, qty numeric, value numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select
    l.distributor_code,
    l.distributor_name,
    l.invoice_period,
    l.product_code,
    l.product_name,
    l.customer_code,
    l.customer_name,
    l.region_name,
    l.qty::numeric,
    l.value::numeric
  from public.phx_marketing_request_sales_lines(
         array[p_request_id]::uuid[], p_exclude_product_codes, p_from_period, p_to_period) l
  where l.channel = 'retail'
  order by l.invoice_period, l.distributor_code, l.product_code, l.source_row_id;
$$;

ALTER FUNCTION public.phx_marketing_request_view_sales(p_request_id uuid, p_from_period text, p_to_period text, p_exclude_product_codes text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_request_view_sales(p_request_id uuid, p_from_period text, p_to_period text, p_exclude_product_codes text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_request_view_sales(p_request_id uuid, p_from_period text, p_to_period text, p_exclude_product_codes text[]) IS 'Marketing ROI View-Sales drill-down: per-request realized sales DETAIL rows (rolled-up distributors, customer-code-only match, canonical value formula, validated-batch gated). Confidential products excluded unless an empty exclude array is passed (CEO/Super Admin only).';

--
-- Name: phx_marketing_roi_customer_dashboard(text[], text[], text[], text[], text[], text[], text, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_roi_customer_dashboard(p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[], p_distributor_codes text[] DEFAULT '{}'::text[], p_product_codes text[] DEFAULT '{}'::text[], p_roi_statuses text[] DEFAULT '{}'::text[], p_attribution_qualities text[] DEFAULT '{}'::text[], p_customer_search text DEFAULT NULL::text, p_from_month text DEFAULT NULL::text, p_to_month text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $_$
  with params as (
    select
      greatest(10, least(coalesce(p_limit, 100), 100)) as row_limit,
      nullif(lower(btrim(coalesce(p_customer_search, ''))), '') as customer_search,
      case when coalesce(p_from_month, '') ~ '^\d{4}-\d{2}$' then p_from_month else null end as from_month,
      case when coalesce(p_to_month, '') ~ '^\d{4}-\d{2}$' then p_to_month else null end as to_month,
      public.phx_marketing_roi_latest_validated_period() as sales_as_of
  ),
  filter_lines as materialized (
    select lower(btrim(value)) as value
    from unnest(coalesce(p_lines, '{}'::text[])) as value
    where btrim(value) <> ''
  ),
  filter_regions as materialized (
    select lower(btrim(value)) as value
    from unnest(coalesce(p_regions, '{}'::text[])) as value
    where btrim(value) <> ''
  ),
  filter_distributors as materialized (
    select upper(btrim(value)) as value
    from unnest(coalesce(p_distributor_codes, '{}'::text[])) as value
    where btrim(value) <> ''
  ),
  filter_products as materialized (
    select upper(btrim(value)) as value
    from unnest(coalesce(p_product_codes, '{}'::text[])) as value
    where btrim(value) <> ''
  ),
  filter_roi_statuses as materialized (
    select lower(btrim(value)) as value
    from unnest(coalesce(p_roi_statuses, '{}'::text[])) as value
    where lower(btrim(value)) in ('behind', 'no_data', 'on_track')
  ),
  filter_attribution as materialized (
    select lower(btrim(value)) as value
    from unnest(coalesce(p_attribution_qualities, '{}'::text[])) as value
    where lower(btrim(value)) in ('exact_customer', 'no_sales')
  ),
  req_raw as materialized (
    select
      mr.id,
      mr.request_code,
      mr.status,
      mr.pay_date,
      to_char(date_trunc('month', mr.pay_date), 'YYYY-MM') as pay_month,
      greatest(coalesce(mr.roi_duration_months, 1), 1) as roi_duration_months,
      coalesce(mr.estimated_cost, 0)::numeric as estimated_cost,
      coalesce(mr.required_roi_value, coalesce(mr.estimated_cost, 0) * 10)::numeric as required_roi_value,
      coalesce(mr.expected_roi_value, 0)::numeric as expected_roi_value,
      coalesce(mr.roi_coverage_ratio, 0)::numeric as expected_coverage_ratio,
      mr.customer_id,
      mr.line_id,
      coalesce(l.name, 'Unassigned') as request_line,
      coalesce(mc.display_name, mr.customer_id::text) as customer_name,
      mc.customer_code,
      params.sales_as_of
    from public.marketing_requests mr
    left join public.employees emp_req on upper(btrim(emp_req.hr_id)) = upper(btrim(mr.requester_hr_id))
    left join public.lines l on l.id = coalesce(mr.line_id, emp_req.line_id)
    left join public.marketing_customers mc on mc.id = mr.customer_id
    cross join params
    where mr.status in ('approved', 'active', 'roi_tracking', 'closed', 'finance_hold')
      and mr.pay_date is not null
      and (params.from_month is null or to_char(date_trunc('month', mr.pay_date), 'YYYY-MM') >= params.from_month)
      and (params.to_month is null or to_char(date_trunc('month', mr.pay_date), 'YYYY-MM') <= params.to_month)
      and (
        params.customer_search is null
        or lower(mr.request_code) like '%' || params.customer_search || '%'
        or lower(coalesce(mc.display_name, '')) like '%' || params.customer_search || '%'
        or lower(coalesce(mc.customer_code, '')) like '%' || params.customer_search || '%'
      )
  ),
  req_products_all as materialized (
    select distinct
      mrp.request_id,
      upper(btrim(sp.product_code)) as product_code,
      coalesce(sp.product_name, mp.product_name, mrp.product_name_snapshot) as product_name,
      coalesce(nullif(btrim(sp.line), ''), nullif(btrim(mp.line), ''), nullif(btrim(mrp.line_snapshot), ''), 'Unassigned') as line_label,
      coalesce(mrp.expected_value, 0)::numeric as expected_value,
      coalesce(mrp.value_share, 0)::numeric as value_share,
      (sp.product_code is null) as missing_sales_product_mapping
    from public.marketing_request_products mrp
    join public.marketing_products mp on mp.id = mrp.product_id
    left join public.source_of_sales_products sp
      on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
    where mrp.request_id in (select id from req_raw)
  ),
  req_targets_all as materialized (
    select distinct
      mrph.request_id,
      sd.distributor_code,
      coalesce(sd.distributor_name, md.display_name, sd.distributor_code) as distributor_name,
      mpdc.normalized_pharmacy_code as customer_code,
      mph.id as pharmacy_id,
      coalesce(mph.display_name, mpdc.normalized_pharmacy_code) as pharmacy_name,
      cm.brick_id,
      cm.region_code,
      cm.area_code,
      (cm.brick_id is null) as missing_customer_mapping
    from public.marketing_request_pharmacies mrph
    join public.marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
    join public.marketing_distributors md on md.id = mpdc.distributor_id
    join public.marketing_pharmacies mph on mph.id = mrph.pharmacy_id
    join (select distinct marketing_normalized_name, parent_distributor_code from public.marketing_roi_distributor_rollup) ru on ru.marketing_normalized_name = md.normalized_name
    join public.source_of_sales_distributors sd on sd.distributor_code = ru.parent_distributor_code
    left join lateral (
      select cmx.brick_id, cmx.region_code, cmx.area_code
      from public.source_of_sales_customer_map cmx
      where lower(btrim(regexp_replace(coalesce(cmx.customer_code, ''), '\s+', ' ', 'g'))) = mpdc.normalized_pharmacy_code
        and cmx.active
        and (cmx.distributor_code = sd.distributor_code
             or exists (select 1 from public.marketing_roi_distributor_rollup rcm
                        where rcm.parent_distributor_code = sd.distributor_code
                          and rcm.sos_distributor_code = cmx.distributor_code))
      order by (cmx.distributor_code = sd.distributor_code) desc, cmx.region_code nulls last
      limit 1
    ) cm on true
    where mrph.request_id in (select id from req_raw)
      and coalesce(btrim(mpdc.normalized_pharmacy_code), '') <> ''
      and coalesce(mpdc.active, true)
  ),
  req as materialized (
    select
      rr.*,
      coalesce(
        nullif(btrim(rr.request_line), ''),
        (select max(rpa.line_label) from req_products_all rpa where rpa.request_id = rr.id),
        'Unassigned'
      ) as line_label
    from req_raw rr
    where (
        not exists (select 1 from filter_lines)
        or lower(btrim(coalesce(rr.request_line, ''))) in (select value from filter_lines)
        or exists (
          select 1
          from req_products_all rpa
          where rpa.request_id = rr.id
            and lower(btrim(rpa.line_label)) in (select value from filter_lines)
        )
      )
      and (
        not exists (select 1 from filter_regions)
        or exists (
          select 1
          from req_targets_all rta
          where rta.request_id = rr.id
            and lower(btrim(coalesce(rta.region_code, ''))) in (select value from filter_regions)
        )
      )
      and (
        not exists (select 1 from filter_distributors)
        or exists (
          select 1
          from req_targets_all rta
          where rta.request_id = rr.id
            and upper(btrim(rta.distributor_code)) in (select value from filter_distributors)
        )
      )
      and (
        not exists (select 1 from filter_products)
        or exists (
          select 1
          from req_products_all rpa
          where rpa.request_id = rr.id
            and upper(btrim(coalesce(rpa.product_code, ''))) in (select value from filter_products)
        )
      )
  ),
  req_products as materialized (
    select rpa.*
    from req_products_all rpa
    join req on req.id = rpa.request_id
    where (
      not exists (select 1 from filter_products)
      or upper(btrim(coalesce(rpa.product_code, ''))) in (select value from filter_products)
    )
    and upper(btrim(coalesce(rpa.product_code, ''))) <> all (array(
      select upper(btrim(c)) from unnest(p_exclude_codes) as c
    ))
  ),
  req_targets as materialized (
    select rta.*
    from req_targets_all rta
    join req on req.id = rta.request_id
    where (
        not exists (select 1 from filter_regions)
        or lower(btrim(coalesce(rta.region_code, ''))) in (select value from filter_regions)
      )
      and (
        not exists (select 1 from filter_distributors)
        or upper(btrim(rta.distributor_code)) in (select value from filter_distributors)
      )
  ),
  product_rollups as (
    select
      request_id,
      count(*)::numeric as product_count,
      coalesce(sum(nullif(value_share, 0)), 0)::numeric as value_share_total,
      coalesce(sum(expected_value), 0)::numeric as expected_total
    from req_products
    group by request_id
  ),
  request_product_allocations as materialized (
    select
      rp.request_id,
      rp.product_code,
      rp.product_name,
      rp.line_label,
      rp.expected_value,
      rp.value_share,
      rp.missing_sales_product_mapping,
      case
        when pr.value_share_total > 0 then rp.value_share / pr.value_share_total
        when pr.expected_total > 0 then rp.expected_value / pr.expected_total
        when pr.product_count > 0 then 1 / pr.product_count
        else 0
      end as share
    from req_products rp
    join product_rollups pr on pr.request_id = rp.request_id
  ),
  target_rollups as (
    select request_id, count(*)::numeric as target_count
    from req_targets
    group by request_id
  ),
  request_target_allocations as materialized (
    select
      rt.*,
      case when tr.target_count > 0 then 1 / tr.target_count else 0 end as share
    from req_targets rt
    join target_rollups tr on tr.request_id = rt.request_id
  ),
  periods as materialized (
    select req.id, array_agg(to_char(g, 'YYYY-MM')) as periods
    from req
    cross join lateral generate_series(
      date_trunc('month', req.pay_date),
      date_trunc('month', req.pay_date) + make_interval(months => req.roi_duration_months - 1),
      interval '1 month'
    ) as g
    group by req.id
  ),
  target_products as materialized (
    select distinct
      rt.request_id,
      rt.distributor_code,
      rt.customer_code,
      rpa.product_code
    from req_targets rt
    join request_product_allocations rpa on rpa.request_id = rt.request_id
    where rpa.product_code is not null
  ),
  -- Customer-code-only match (same rule as the per-request function).
  exact_hits as materialized (
    select distinct
      tp.request_id,
      r.id as row_id,
      tp.distributor_code,
      coalesce(sd.distributor_name, tp.distributor_code) as distributor_name,
      lower(btrim(regexp_replace(coalesce(r.client_code, ''), '\s+', ' ', 'g'))) as client_code,
      nullif(btrim(r.client_name), '') as client_name,
      r.region_code,
      coalesce(sr.region_name, r.region_name, r.region_code) as region_name,
      nullif(btrim(r.brick_id), '') as brick_id,
      upper(btrim(r.product_code)) as product_code,
      coalesce(sp.product_name, r.product_name, r.product_code) as product_name,
      coalesce(nullif(btrim(sp.line), ''), nullif(btrim(r.official_line), ''), 'Unassigned') as line_label,
      coalesce(r.qty, 0)::numeric as units,
      (
        case
          when coalesce(r.is_direct, false) then coalesce(r.value, 0)
          else coalesce(r.qty, 0) * coalesce(public.phx_factory_price(r.product_code, r.invoice_period), 0)
        end
      )::numeric as sales_value,
      'exact'::text as match_type
    from target_products tp
    join periods on periods.id = tp.request_id
    join public.marketing_roi_distributor_rollup rr on rr.parent_distributor_code = tp.distributor_code
    join public.source_of_sales_import_rows r
      on r.distributor_code = rr.sos_distributor_code
     and lower(btrim(regexp_replace(coalesce(r.client_code, ''), '\s+', ' ', 'g'))) = tp.customer_code
     and upper(btrim(r.product_code)) = upper(btrim(tp.product_code))
     and r.invoice_period = any(periods.periods)
     and r.validation_state = 'valid'
    join public.source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
    join public.source_of_sales_products sp on upper(btrim(sp.product_code)) = upper(btrim(r.product_code))
    left join public.source_of_sales_distributors sd on sd.distributor_code = tp.distributor_code
    left join public.source_of_sales_regions sr on sr.region_code = r.region_code
    where (
      not exists (select 1 from filter_regions)
      or lower(btrim(r.region_code)) in (select value from filter_regions)
    )
  ),
  all_hits as materialized (
    select * from exact_hits
  ),
  actuals as materialized (
    select
      request_id,
      coalesce(sum(sales_value), 0)::numeric as actual_value,
      coalesce(sum(units), 0)::numeric as actual_units,
      count(distinct row_id)::integer as sales_rows,
      (count(distinct row_id) filter (where match_type = 'exact'))::integer as exact_sales_rows,
      (count(distinct row_id) filter (where match_type = 'fallback'))::integer as fallback_sales_rows
    from all_hits
    group by request_id
  ),
  request_rows_base as materialized (
    select
      req.id,
      req.request_code,
      req.status,
      req.pay_date,
      req.pay_month,
      req.roi_duration_months,
      req.estimated_cost,
      req.required_roi_value,
      req.expected_roi_value,
      req.expected_coverage_ratio,
      req.customer_id,
      req.customer_name,
      req.customer_code,
      req.line_label,
      coalesce(actuals.actual_value, 0)::numeric as actual_sales_value,
      coalesce(actuals.actual_units, 0)::numeric as actual_sales_units,
      coalesce(actuals.sales_rows, 0)::integer as sales_rows,
      coalesce(actuals.exact_sales_rows, 0)::integer as exact_sales_rows,
      coalesce(actuals.fallback_sales_rows, 0)::integer as fallback_sales_rows,
      case
        when coalesce(actuals.sales_rows, 0) = 0 then 'no_sales'
        else 'exact_customer'
      end as attribution_quality,
      case
        when coalesce(actuals.sales_rows, 0) > 0
             and coalesce(actuals.actual_value, 0) >= req.required_roi_value then 'on_track'
        when req.pay_date is not null
             and req.sales_as_of is not null
             and to_char(
                   req.pay_date + make_interval(months => req.roi_duration_months - 1),
                   'YYYY-MM'
                 ) > req.sales_as_of then 'awaiting_data'
        when coalesce(actuals.sales_rows, 0) > 0 then 'behind'
        else 'no_data'
      end as actual_roi_status,
      case
        when req.required_roi_value > 0 then coalesce(actuals.actual_value, 0) / req.required_roi_value
        when coalesce(actuals.actual_value, 0) > 0 then 1
        else 0
      end as actual_coverage_ratio,
      greatest(req.required_roi_value - coalesce(actuals.actual_value, 0), 0)::numeric as coverage_gap,
      greatest(req.expected_roi_value - coalesce(actuals.actual_value, 0), 0)::numeric as expected_gap
    from req
    left join actuals on actuals.request_id = req.id
  ),
  request_rows as materialized (
    select
      rrb.*,
      case
        when rrb.actual_roi_status = 'on_track' then 'monitor'
        when rrb.attribution_quality = 'no_sales' then 'mapping_review'
        when rrb.actual_coverage_ratio < 0.5 and rrb.coverage_gap > 0 then 'high_risk_gap'
        else 'follow_up'
      end as recommended_action
    from request_rows_base rrb
    where (
        not exists (select 1 from filter_roi_statuses)
        or rrb.actual_roi_status in (select value from filter_roi_statuses)
      )
      and (
        not exists (select 1 from filter_attribution)
        or rrb.attribution_quality in (select value from filter_attribution)
      )
  ),
  filtered_hits as materialized (
    select ah.*
    from all_hits ah
    join request_rows rr on rr.id = ah.request_id
  ),
  actuals_by_line as (
    select line_label, sum(sales_value)::numeric as actual_sales_value, sum(units)::numeric as actual_sales_units
    from filtered_hits
    group by line_label
  ),
  actuals_by_region as (
    select region_code, max(region_name) as region_name, sum(sales_value)::numeric as actual_sales_value, sum(units)::numeric as actual_sales_units
    from filtered_hits
    group by region_code
  ),
  actuals_by_distributor as (
    select distributor_code, max(distributor_name) as distributor_name, sum(sales_value)::numeric as actual_sales_value, sum(units)::numeric as actual_sales_units
    from filtered_hits
    group by distributor_code
  ),
  actuals_by_product as (
    select product_code, max(product_name) as product_name, max(line_label) as line_label, sum(sales_value)::numeric as actual_sales_value, sum(units)::numeric as actual_sales_units
    from filtered_hits
    group by product_code
  ),
  line_request_report as (
    select
      rpa.line_label as value,
      rpa.line_label as label,
      count(distinct rr.id)::integer as request_count,
      count(distinct rr.customer_id)::integer as customer_count,
      (select count(distinct pharmacy_id) from request_target_allocations rta join request_rows rrx on rrx.id = rta.request_id where rrx.id in (select request_id from request_product_allocations where line_label = rpa.line_label))::integer as pharmacy_count,
      sum(rr.estimated_cost * rpa.share)::numeric as marketing_cost,
      sum(rr.required_roi_value * rpa.share)::numeric as required_roi_value,
      sum(rr.expected_roi_value * rpa.share)::numeric as expected_roi_value,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'on_track')::integer as on_track_requests,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'behind')::integer as behind_requests,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'no_data')::integer as no_data_requests,
      sum(rr.exact_sales_rows)::integer as exact_sales_rows,
      sum(rr.fallback_sales_rows)::integer as fallback_sales_rows
    from request_rows rr
    join request_product_allocations rpa on rpa.request_id = rr.id
    group by rpa.line_label
  ),
  product_request_report as (
    select
      rpa.product_code as value,
      max(rpa.product_name) as label,
      max(rpa.line_label) as line_label,
      count(distinct rr.id)::integer as request_count,
      count(distinct rr.customer_id)::integer as customer_count,
      (select count(distinct rta.pharmacy_id)
       from request_target_allocations rta
       join request_rows rrx on rrx.id = rta.request_id
       where rta.request_id in (select request_id from request_product_allocations where product_code = rpa.product_code))::integer as pharmacy_count,
      sum(rr.estimated_cost * rpa.share)::numeric as marketing_cost,
      sum(rr.required_roi_value * rpa.share)::numeric as required_roi_value,
      sum(rr.expected_roi_value * rpa.share)::numeric as expected_roi_value,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'on_track')::integer as on_track_requests,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'behind')::integer as behind_requests,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'no_data')::integer as no_data_requests,
      sum(rr.exact_sales_rows)::integer as exact_sales_rows,
      sum(rr.fallback_sales_rows)::integer as fallback_sales_rows
    from request_rows rr
    join request_product_allocations rpa on rpa.request_id = rr.id
    where rpa.product_code is not null
    group by rpa.product_code
  ),
  region_request_report as (
    select
      coalesce(rta.region_code, 'Unassigned') as value,
      coalesce(sr.region_name, rta.region_code, 'Unassigned') as label,
      count(distinct rr.id)::integer as request_count,
      count(distinct rr.customer_id)::integer as customer_count,
      count(distinct rta.pharmacy_id)::integer as pharmacy_count,
      sum(rr.estimated_cost * rta.share)::numeric as marketing_cost,
      sum(rr.required_roi_value * rta.share)::numeric as required_roi_value,
      sum(rr.expected_roi_value * rta.share)::numeric as expected_roi_value,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'on_track')::integer as on_track_requests,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'behind')::integer as behind_requests,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'no_data')::integer as no_data_requests,
      sum(rr.exact_sales_rows)::integer as exact_sales_rows,
      sum(rr.fallback_sales_rows)::integer as fallback_sales_rows
    from request_rows rr
    join request_target_allocations rta on rta.request_id = rr.id
    left join public.source_of_sales_regions sr on sr.region_code = rta.region_code
    group by coalesce(rta.region_code, 'Unassigned'), coalesce(sr.region_name, rta.region_code, 'Unassigned')
  ),
  distributor_request_report as (
    select
      rta.distributor_code as value,
      max(rta.distributor_name) as label,
      count(distinct rr.id)::integer as request_count,
      count(distinct rr.customer_id)::integer as customer_count,
      count(distinct rta.pharmacy_id)::integer as pharmacy_count,
      sum(rr.estimated_cost * rta.share)::numeric as marketing_cost,
      sum(rr.required_roi_value * rta.share)::numeric as required_roi_value,
      sum(rr.expected_roi_value * rta.share)::numeric as expected_roi_value,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'on_track')::integer as on_track_requests,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'behind')::integer as behind_requests,
      count(distinct rr.id) filter (where rr.actual_roi_status = 'no_data')::integer as no_data_requests,
      sum(rr.exact_sales_rows)::integer as exact_sales_rows,
      sum(rr.fallback_sales_rows)::integer as fallback_sales_rows
    from request_rows rr
    join request_target_allocations rta on rta.request_id = rr.id
    group by rta.distributor_code
  ),
  customer_request_report as (
    select
      rta.distributor_code || ':' || rta.customer_code as value,
      max(rta.pharmacy_name) as label,
      max(rta.distributor_code) as distributor_code,
      max(rta.distributor_name) as distributor_name,
      max(coalesce(sr.region_name, rta.region_code)) as region_name,
      count(distinct rr.id)::integer as request_count,
      count(distinct rr.customer_id)::integer as customer_count,
      count(distinct rta.pharmacy_id)::integer as pharmacy_count,
      sum(rr.estimated_cost * rta.share)::numeric as marketing_cost,
      sum(rr.required_roi_value * rta.share)::numeric as required_roi_value,
      sum(rr.expected_roi_value * rta.share)::numeric as expected_roi_value
    from request_rows rr
    join request_target_allocations rta on rta.request_id = rr.id
    left join public.source_of_sales_regions sr on sr.region_code = rta.region_code
    group by rta.distributor_code || ':' || rta.customer_code
  ),
  actuals_by_customer as (
    select
      distributor_code || ':' || client_code as value,
      coalesce(max(client_name), max(nullif(client_code, '')), max(client_code)) as label,
      max(distributor_code) as distributor_code,
      max(distributor_name) as distributor_name,
      max(region_name) as region_name,
      sum(sales_value)::numeric as actual_sales_value,
      sum(units)::numeric as actual_sales_units,
      count(distinct row_id)::integer as sales_rows,
      count(distinct row_id) filter (where match_type = 'exact')::integer as exact_sales_rows,
      count(distinct row_id) filter (where match_type = 'fallback')::integer as fallback_sales_rows
    from filtered_hits
    group by distributor_code || ':' || client_code
  ),
  roi_trend as (
    select
      pay_month as period,
      count(*)::integer as request_count,
      sum(estimated_cost)::numeric as marketing_cost,
      sum(required_roi_value)::numeric as required_roi_value,
      sum(expected_roi_value)::numeric as expected_roi_value,
      sum(actual_sales_value)::numeric as actual_sales_value,
      sum(coverage_gap)::numeric as coverage_gap,
      count(*) filter (where actual_roi_status = 'on_track')::integer as on_track_count,
      count(*) filter (where actual_roi_status = 'behind')::integer as behind_count,
      count(*) filter (where actual_roi_status = 'no_data')::integer as no_data_count
    from request_rows
    group by pay_month
  ),
  attribution_summary as (
    select
      coalesce(sum(exact_sales_rows), 0)::integer as exact_sales_rows,
      coalesce(sum(fallback_sales_rows), 0)::integer as fallback_sales_rows,
      count(*) filter (where attribution_quality = 'mixed')::integer as mixed_requests,
      count(*) filter (where attribution_quality = 'no_sales')::integer as no_sales_requests,
      (
        select count(*)::integer
        from req_targets rt
        join request_rows rr on rr.id = rt.request_id
        where rt.missing_customer_mapping
      ) + (
        select count(*)::integer
        from req_products rp
        join request_rows rr on rr.id = rp.request_id
        where rp.missing_sales_product_mapping
      ) as unmatched_mapping_count
    from request_rows
  ),
  dashboard_summary as (
    select
      count(*)::integer as marketing_request_count,
      count(*)::integer as paid_request_count,
      count(distinct customer_id)::integer as active_customers,
      (
        select count(distinct rta.pharmacy_id)::integer
        from request_target_allocations rta
        join request_rows rr on rr.id = rta.request_id
      ) as active_pharmacies,
      coalesce(sum(estimated_cost), 0)::numeric as total_marketing_cost,
      coalesce(sum(required_roi_value), 0)::numeric as required_roi_value,
      coalesce(sum(expected_roi_value), 0)::numeric as expected_roi_value,
      coalesce(sum(actual_sales_value), 0)::numeric as actual_sales_value,
      coalesce(sum(actual_sales_units), 0)::numeric as actual_sales_units,
      coalesce(sum(coverage_gap), 0)::numeric as coverage_gap,
      coalesce(sum(expected_gap), 0)::numeric as expected_gap,
      count(*) filter (where actual_roi_status = 'on_track')::integer as on_track_count,
      count(*) filter (where actual_roi_status = 'behind')::integer as behind_count,
      count(*) filter (where actual_roi_status = 'no_data')::integer as no_data_count,
      count(*) filter (where recommended_action <> 'monitor')::integer as action_required_count,
      coalesce(sum(estimated_cost) filter (where actual_roi_status in ('behind', 'no_data')), 0)::numeric as spend_at_risk,
      coalesce(sum(estimated_cost) filter (where actual_roi_status = 'no_data'), 0)::numeric as no_data_spend
    from request_rows
  )
  select jsonb_build_object(
    'generatedAt', now(),
    'limits', jsonb_build_object(
      'tableLimit', (select row_limit from params),
      'rawRowsReturned', 0
    ),
    'filters', jsonb_build_object(
      'selected', jsonb_build_object(
        'lines', coalesce(to_jsonb(p_lines), '[]'::jsonb),
        'regions', coalesce(to_jsonb(p_regions), '[]'::jsonb),
        'distributors', coalesce(to_jsonb(p_distributor_codes), '[]'::jsonb),
        'products', coalesce(to_jsonb(p_product_codes), '[]'::jsonb),
        'roiStatuses', coalesce(to_jsonb(p_roi_statuses), '[]'::jsonb),
        'attributionQualities', coalesce(to_jsonb(p_attribution_qualities), '[]'::jsonb),
        'customerSearch', p_customer_search,
        'fromMonth', p_from_month,
        'toMonth', p_to_month
      ),
      'lines', (
        select coalesce(jsonb_agg(jsonb_build_object('value', label, 'label', label) order by label), '[]'::jsonb)
        from (
          select distinct coalesce(nullif(btrim(line), ''), 'Unassigned') as label
          from public.source_of_sales_products
          where active
          union
          select distinct coalesce(nullif(btrim(line), ''), 'Unassigned') as label
          from public.marketing_products
          where active
        ) options
      ),
      'regions', (
        select coalesce(jsonb_agg(jsonb_build_object('value', region_code, 'label', region_name) order by region_name), '[]'::jsonb)
        from public.source_of_sales_regions
        where active
      ),
      'distributors', (
        select coalesce(jsonb_agg(jsonb_build_object('value', distributor_code, 'label', distributor_name) order by distributor_name), '[]'::jsonb)
        from public.source_of_sales_distributors
        where active
      ),
      'products', (
        select coalesce(jsonb_agg(jsonb_build_object('value', product_code, 'label', product_name) order by product_name), '[]'::jsonb)
        from public.source_of_sales_products
        where active
      ),
      'roiStatuses', jsonb_build_array(
        jsonb_build_object('value', 'behind', 'label', 'Behind'),
        jsonb_build_object('value', 'no_data', 'label', 'No data'),
        jsonb_build_object('value', 'on_track', 'label', 'On track')
      ),
      'attributionQualities', jsonb_build_array(
        jsonb_build_object('value', 'exact_customer', 'label', 'Exact customer'),
        jsonb_build_object('value', 'no_sales', 'label', 'No sales')
      )
    ),
    'summary', (
      select jsonb_build_object(
        'marketingRequestCount', marketing_request_count,
        'paidRequestCount', paid_request_count,
        'activeCustomers', active_customers,
        'activePharmacies', active_pharmacies,
        'totalMarketingCost', total_marketing_cost,
        'requiredRoiValue', required_roi_value,
        'expectedRoiValue', expected_roi_value,
        'actualAttributedSalesValue', actual_sales_value,
        'actualAttributedSalesUnits', actual_sales_units,
        'actualRoiCoverage', case when required_roi_value > 0 then actual_sales_value / required_roi_value else 0 end,
        'coverageGap', coverage_gap,
        'expectedGap', expected_gap,
        'onTrackRequests', on_track_count,
        'behindRequests', behind_count,
        'noDataRequests', no_data_count,
        'actionRequiredRequests', action_required_count,
        'spendAtRisk', spend_at_risk,
        'noDataSpend', no_data_spend
      )
      from dashboard_summary
    ),
    'decisionSummary', (
      select jsonb_build_object(
        'actionRequiredRequests', action_required_count,
        'spendAtRisk', spend_at_risk,
        'coverageGap', coverage_gap,
        'expectedGap', expected_gap,
        'noDataSpend', no_data_spend,
        'topRiskRequest', (
          select coalesce(jsonb_build_object(
            'id', id,
            'requestCode', request_code,
            'customerName', customer_name,
            'line', line_label,
            'estimatedCost', estimated_cost,
            'requiredRoiValue', required_roi_value,
            'actualSalesValue', actual_sales_value,
            'coverageGap', coverage_gap,
            'actualRoiCoverage', actual_coverage_ratio,
            'actualRoiStatus', actual_roi_status,
            'attributionQuality', attribution_quality,
            'recommendedAction', recommended_action
          ), '{}'::jsonb)
          from request_rows
          order by coverage_gap desc, estimated_cost desc
          limit 1
        )
      )
      from dashboard_summary
    ),
    'attributionHealth', (
      select jsonb_build_object(
        'exactSalesRows', exact_sales_rows,
        'fallbackSalesRows', fallback_sales_rows,
        'mixedRequests', mixed_requests,
        'noSalesRequests', no_sales_requests,
        'unmatchedMappingWarnings', unmatched_mapping_count
      )
      from attribution_summary
    ),
    'roiTrend', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'period', period,
        'requestCount', request_count,
        'marketingCost', marketing_cost,
        'requiredRoiValue', required_roi_value,
        'expectedRoiValue', expected_roi_value,
        'actualSalesValue', actual_sales_value,
        'coverageGap', coverage_gap,
        'onTrackCount', on_track_count,
        'behindCount', behind_count,
        'noDataCount', no_data_count
      ) order by period), '[]'::jsonb)
      from roi_trend
    ),
    'lineRoi', (
      select coalesce(jsonb_agg(row_json order by coverage_gap desc, marketing_cost desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'value', coalesce(lr.value, al.line_label, 'Unassigned'),
          'label', coalesce(lr.label, al.line_label, 'Unassigned'),
          'line', coalesce(lr.label, al.line_label, 'Unassigned'),
          'requestCount', coalesce(lr.request_count, 0),
          'customerCount', coalesce(lr.customer_count, 0),
          'pharmacyCount', coalesce(lr.pharmacy_count, 0),
          'marketingCost', coalesce(lr.marketing_cost, 0),
          'requiredRoiValue', coalesce(lr.required_roi_value, 0),
          'expectedRoiValue', coalesce(lr.expected_roi_value, 0),
          'actualSalesValue', coalesce(al.actual_sales_value, 0),
          'actualSalesUnits', coalesce(al.actual_sales_units, 0),
          'coverageGap', greatest(coalesce(lr.required_roi_value, 0) - coalesce(al.actual_sales_value, 0), 0),
          'actualRoiCoverage', case when coalesce(lr.required_roi_value, 0) > 0 then coalesce(al.actual_sales_value, 0) / lr.required_roi_value else 0 end,
          'onTrackRequests', coalesce(lr.on_track_requests, 0),
          'behindRequests', coalesce(lr.behind_requests, 0),
          'noDataRequests', coalesce(lr.no_data_requests, 0),
          'exactSalesRows', coalesce(lr.exact_sales_rows, 0),
          'fallbackSalesRows', coalesce(lr.fallback_sales_rows, 0)
        ) as row_json,
        greatest(coalesce(lr.required_roi_value, 0) - coalesce(al.actual_sales_value, 0), 0) as coverage_gap,
        coalesce(lr.marketing_cost, 0) as marketing_cost
        from line_request_report lr
        full join actuals_by_line al on lower(btrim(al.line_label)) = lower(btrim(lr.value))
        order by coverage_gap desc, marketing_cost desc
        limit (select row_limit from params)
      ) rows
    ),
    'productRoi', (
      select coalesce(jsonb_agg(row_json order by coverage_gap desc, marketing_cost desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'value', coalesce(pr.value, ap.product_code, 'Unassigned'),
          'label', coalesce(pr.label, ap.product_name, 'Unassigned'),
          'line', coalesce(pr.line_label, ap.line_label, 'Unassigned'),
          'requestCount', coalesce(pr.request_count, 0),
          'customerCount', coalesce(pr.customer_count, 0),
          'pharmacyCount', coalesce(pr.pharmacy_count, 0),
          'marketingCost', coalesce(pr.marketing_cost, 0),
          'requiredRoiValue', coalesce(pr.required_roi_value, 0),
          'expectedRoiValue', coalesce(pr.expected_roi_value, 0),
          'actualSalesValue', coalesce(ap.actual_sales_value, 0),
          'actualSalesUnits', coalesce(ap.actual_sales_units, 0),
          'coverageGap', greatest(coalesce(pr.required_roi_value, 0) - coalesce(ap.actual_sales_value, 0), 0),
          'actualRoiCoverage', case when coalesce(pr.required_roi_value, 0) > 0 then coalesce(ap.actual_sales_value, 0) / pr.required_roi_value else 0 end,
          'onTrackRequests', coalesce(pr.on_track_requests, 0),
          'behindRequests', coalesce(pr.behind_requests, 0),
          'noDataRequests', coalesce(pr.no_data_requests, 0),
          'exactSalesRows', coalesce(pr.exact_sales_rows, 0),
          'fallbackSalesRows', coalesce(pr.fallback_sales_rows, 0)
        ) as row_json,
        greatest(coalesce(pr.required_roi_value, 0) - coalesce(ap.actual_sales_value, 0), 0) as coverage_gap,
        coalesce(pr.marketing_cost, 0) as marketing_cost
        from product_request_report pr
        full join actuals_by_product ap on upper(btrim(ap.product_code)) = upper(btrim(pr.value))
        order by coverage_gap desc, marketing_cost desc
        limit (select row_limit from params)
      ) rows
    ),
    'regionRoi', (
      select coalesce(jsonb_agg(row_json order by coverage_gap desc, marketing_cost desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'value', coalesce(rr.value, ar.region_code, 'Unassigned'),
          'label', coalesce(rr.label, ar.region_name, 'Unassigned'),
          'requestCount', coalesce(rr.request_count, 0),
          'customerCount', coalesce(rr.customer_count, 0),
          'pharmacyCount', coalesce(rr.pharmacy_count, 0),
          'marketingCost', coalesce(rr.marketing_cost, 0),
          'requiredRoiValue', coalesce(rr.required_roi_value, 0),
          'expectedRoiValue', coalesce(rr.expected_roi_value, 0),
          'actualSalesValue', coalesce(ar.actual_sales_value, 0),
          'actualSalesUnits', coalesce(ar.actual_sales_units, 0),
          'coverageGap', greatest(coalesce(rr.required_roi_value, 0) - coalesce(ar.actual_sales_value, 0), 0),
          'actualRoiCoverage', case when coalesce(rr.required_roi_value, 0) > 0 then coalesce(ar.actual_sales_value, 0) / rr.required_roi_value else 0 end,
          'onTrackRequests', coalesce(rr.on_track_requests, 0),
          'behindRequests', coalesce(rr.behind_requests, 0),
          'noDataRequests', coalesce(rr.no_data_requests, 0),
          'exactSalesRows', coalesce(rr.exact_sales_rows, 0),
          'fallbackSalesRows', coalesce(rr.fallback_sales_rows, 0)
        ) as row_json,
        greatest(coalesce(rr.required_roi_value, 0) - coalesce(ar.actual_sales_value, 0), 0) as coverage_gap,
        coalesce(rr.marketing_cost, 0) as marketing_cost
        from region_request_report rr
        full join actuals_by_region ar on lower(btrim(ar.region_code)) = lower(btrim(rr.value))
        order by coverage_gap desc, marketing_cost desc
        limit (select row_limit from params)
      ) rows
    ),
    'distributorRoi', (
      select coalesce(jsonb_agg(row_json order by coverage_gap desc, marketing_cost desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'value', coalesce(dr.value, ad.distributor_code, 'Unassigned'),
          'label', coalesce(dr.label, ad.distributor_name, 'Unassigned'),
          'requestCount', coalesce(dr.request_count, 0),
          'customerCount', coalesce(dr.customer_count, 0),
          'pharmacyCount', coalesce(dr.pharmacy_count, 0),
          'marketingCost', coalesce(dr.marketing_cost, 0),
          'requiredRoiValue', coalesce(dr.required_roi_value, 0),
          'expectedRoiValue', coalesce(dr.expected_roi_value, 0),
          'actualSalesValue', coalesce(ad.actual_sales_value, 0),
          'actualSalesUnits', coalesce(ad.actual_sales_units, 0),
          'coverageGap', greatest(coalesce(dr.required_roi_value, 0) - coalesce(ad.actual_sales_value, 0), 0),
          'actualRoiCoverage', case when coalesce(dr.required_roi_value, 0) > 0 then coalesce(ad.actual_sales_value, 0) / dr.required_roi_value else 0 end,
          'onTrackRequests', coalesce(dr.on_track_requests, 0),
          'behindRequests', coalesce(dr.behind_requests, 0),
          'noDataRequests', coalesce(dr.no_data_requests, 0),
          'exactSalesRows', coalesce(dr.exact_sales_rows, 0),
          'fallbackSalesRows', coalesce(dr.fallback_sales_rows, 0)
        ) as row_json,
        greatest(coalesce(dr.required_roi_value, 0) - coalesce(ad.actual_sales_value, 0), 0) as coverage_gap,
        coalesce(dr.marketing_cost, 0) as marketing_cost
        from distributor_request_report dr
        full join actuals_by_distributor ad on upper(btrim(ad.distributor_code)) = upper(btrim(dr.value))
        order by coverage_gap desc, marketing_cost desc
        limit (select row_limit from params)
      ) rows
    ),
    'requestReport', (
      select coalesce(jsonb_agg(row_json order by risk_rank asc, coverage_gap desc, estimated_cost desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'id', id,
          'requestCode', request_code,
          'status', status,
          'payDate', pay_date,
          'payMonth', pay_month,
          'roiDurationMonths', roi_duration_months,
          'customerName', customer_name,
          'customerCode', customer_code,
          'line', line_label,
          'estimatedCost', estimated_cost,
          'requiredRoiValue', required_roi_value,
          'expectedRoiValue', expected_roi_value,
          'actualSalesValue', actual_sales_value,
          'actualSalesUnits', actual_sales_units,
          'actualRoiCoverage', actual_coverage_ratio,
          'coverageGap', coverage_gap,
          'expectedGap', expected_gap,
          'actualRoiStatus', actual_roi_status,
          'attributionQuality', attribution_quality,
          'recommendedAction', recommended_action,
          'exactSalesRows', exact_sales_rows,
          'fallbackSalesRows', fallback_sales_rows,
          'salesRows', sales_rows
        ) as row_json,
        case actual_roi_status when 'no_data' then 0 when 'behind' then 1 else 2 end as risk_rank,
        coverage_gap,
        estimated_cost
        from request_rows
        order by risk_rank asc, coverage_gap desc, estimated_cost desc
        limit (select row_limit from params)
      ) rows
    ),
    'customerImpact', (
      select coalesce(jsonb_agg(row_json order by coverage_gap desc, actual_sales_value desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'value', coalesce(cr.value, ac.value, 'Unassigned'),
          'label', coalesce(cr.label, ac.label, 'Unassigned'),
          'distributorCode', coalesce(cr.distributor_code, ac.distributor_code),
          'distributorName', coalesce(cr.distributor_name, ac.distributor_name),
          'regionName', coalesce(cr.region_name, ac.region_name),
          'requestCount', coalesce(cr.request_count, 0),
          'customerCount', coalesce(cr.customer_count, 0),
          'pharmacyCount', coalesce(cr.pharmacy_count, 0),
          'marketingCost', coalesce(cr.marketing_cost, 0),
          'requiredRoiValue', coalesce(cr.required_roi_value, 0),
          'expectedRoiValue', coalesce(cr.expected_roi_value, 0),
          'actualSalesValue', coalesce(ac.actual_sales_value, 0),
          'actualSalesUnits', coalesce(ac.actual_sales_units, 0),
          'coverageGap', greatest(coalesce(cr.required_roi_value, 0) - coalesce(ac.actual_sales_value, 0), 0),
          'actualRoiCoverage', case when coalesce(cr.required_roi_value, 0) > 0 then coalesce(ac.actual_sales_value, 0) / cr.required_roi_value else 0 end,
          'salesRows', coalesce(ac.sales_rows, 0),
          'exactSalesRows', coalesce(ac.exact_sales_rows, 0),
          'fallbackSalesRows', coalesce(ac.fallback_sales_rows, 0)
        ) as row_json,
        greatest(coalesce(cr.required_roi_value, 0) - coalesce(ac.actual_sales_value, 0), 0) as coverage_gap,
        coalesce(ac.actual_sales_value, 0) as actual_sales_value
        from customer_request_report cr
        full join actuals_by_customer ac on ac.value = cr.value
        order by coverage_gap desc, actual_sales_value desc
        limit (select row_limit from params)
      ) rows
    )
  );
$_$;

ALTER FUNCTION public.phx_marketing_roi_customer_dashboard(p_lines text[], p_regions text[], p_distributor_codes text[], p_product_codes text[], p_roi_statuses text[], p_attribution_qualities text[], p_customer_search text, p_from_month text, p_to_month text, p_limit integer, p_exclude_codes text[]) OWNER TO postgres;

--
-- Name: phx_marketing_roi_fast(text[], text[], text[], text[], text, text, text, text[], text[], integer, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_roi_fast(p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[], p_products text[] DEFAULT '{}'::text[], p_roi_statuses text[] DEFAULT '{}'::text[], p_from_month text DEFAULT NULL::text, p_to_month text DEFAULT NULL::text, p_customer_search text DEFAULT NULL::text, p_distributors text[] DEFAULT '{}'::text[], p_attribution_qualities text[] DEFAULT '{}'::text[], p_limit integer DEFAULT 100, p_exclude_codes text[] DEFAULT ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
with
-- The latest month whose Source-of-Sales upload is complete. A request whose ROI window still
-- ends after it is awaiting data, never behind and never no-data.
sales_as_of as (
  select public.phx_marketing_roi_latest_validated_period() as period
),
last_refresh as (
  select
    max(r.finished_at) filter (where r.status = 'success') as last_success_at,
    bool_or(r.status = 'running')                          as is_refreshing,
    bool_or(
      r.status = 'failed'
      and r.started_at > coalesce(
        (select max(r2.finished_at) from marketing_roi_refresh_runs r2
         where r2.status = 'success'),
        '1970-01-01'::timestamptz
      )
    ) as has_recent_failure,
    (
      select max(b.updated_at)
      from source_of_sales_import_batches b
      where b.status = 'validated'
    ) as latest_sos_at
  from marketing_roi_refresh_runs r
),
fr_raw as materialized (
  select
    rf.id, rf.refresh_run_id, rf.request_id, rf.request_code, rf.pay_month, rf.line_label,
    rf.customer_id, rf.customer_name, rf.customer_code,
    rf.estimated_cost, rf.required_roi_value, rf.expected_roi_value,
    rf.factory_price_snapshot, rf.exact_sales_rows, rf.fallback_sales_rows,
    rf.source_batch_ids, rf.source_periods, rf.calculation_version, rf.calculated_at,
    coalesce(mrw.roi_duration_months, 1) as roi_duration_months,
    case when cardinality(p_regions) = 0 and cardinality(p_distributors) = 0
         then rf.actual_sales_value else coalesce(geo.scoped_value, 0) end as actual_sales_value,
    case when cardinality(p_regions) = 0 and cardinality(p_distributors) = 0
         then rf.actual_sales_units else coalesce(geo.scoped_units, 0) end as actual_sales_units,
    case when cardinality(p_regions) = 0 and cardinality(p_distributors) = 0
         then rf.sales_rows else coalesce(geo.scoped_rows, 0) end as sales_rows
  from marketing_roi_request_facts rf
  left join marketing_requests mrw on mrw.id = rf.request_id
  left join lateral (
    select
      sum(g.actual_sales_value) as scoped_value,
      sum(g.actual_sales_units) as scoped_units,
      sum(g.sales_rows)::integer as scoped_rows
    from marketing_roi_request_geo_facts g
    where g.request_id = rf.request_id
      and (cardinality(p_regions) = 0 or g.region_code = any(p_regions))
      and (cardinality(p_distributors) = 0 or g.distributor_code = any(p_distributors))
  ) geo on true
  where
    (rf.request_status is null
       or rf.request_status in ('approved','active','roi_tracking','closed','finance_hold'))
    and (p_from_month is null or p_from_month = '' or rf.pay_month >= p_from_month)
    and (p_to_month   is null or p_to_month = ''   or rf.pay_month <= p_to_month)
    and (cardinality(p_lines) = 0
         or rf.line_label = any(p_lines))
    and (cardinality(p_attribution_qualities) = 0
         or rf.attribution_quality = any(p_attribution_qualities))
    and (p_customer_search is null or p_customer_search = ''
         or lower(btrim(coalesce(rf.customer_name,''))) like
            '%' || lower(btrim(p_customer_search)) || '%')
    and (
      cardinality(p_exclude_codes) = 0
      or not exists (
        select 1 from marketing_request_products mrp
        join marketing_products mp on mp.id = mrp.product_id
        left join source_of_sales_products sp
          on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
        where mrp.request_id = rf.request_id
          and upper(btrim(coalesce(sp.product_code,''))) = any(p_exclude_codes)
      )
    )
    and (
      cardinality(p_products) = 0
      or exists (
        select 1 from marketing_request_products mrp
        join marketing_products mp on mp.id = mrp.product_id
        left join source_of_sales_products sp
          on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
        where mrp.request_id = rf.request_id
          and upper(btrim(coalesce(sp.product_code,''))) = any(p_products)
      )
    )
    and (
      cardinality(p_distributors) = 0
      or exists (
        select 1 from marketing_request_pharmacies mrph
        join marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
        join marketing_distributors md on md.id = mpdc.distributor_id
        join marketing_roi_distributor_rollup ru
          on ru.marketing_normalized_name = md.normalized_name
        where mrph.request_id = rf.request_id
          and ru.parent_distributor_code = any(p_distributors)
      )
    )
    and (
      cardinality(p_regions) = 0
      or exists (
        select 1 from marketing_request_pharmacies mrph
        join marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
        left join lateral (
          select cmx.region_code
          from source_of_sales_customer_map cmx
          where lower(btrim(regexp_replace(coalesce(cmx.customer_code,''),'\s+',' ','g')))
                  = mpdc.normalized_pharmacy_code
            and cmx.active
          limit 1
        ) cm on true
        where mrph.request_id = rf.request_id
          and cm.region_code = any(p_regions)
      )
    )
),
fr_status as materialized (
  select
    fr_raw.*,
    case
      when fr_raw.sales_rows > 0
           and fr_raw.actual_sales_value >= fr_raw.required_roi_value then 'on_track'
      when sa.period is null or fr_raw.pay_month is null
           or to_char(
                to_date(fr_raw.pay_month, 'YYYY-MM')
                  + make_interval(months => greatest(coalesce(fr_raw.roi_duration_months, 1), 1) - 1),
                'YYYY-MM'
              ) > sa.period then 'awaiting_data'
      when fr_raw.sales_rows > 0 then 'behind'
      else 'no_data'
    end as actual_roi_status,
    case
      when fr_raw.sales_rows = 0 then 'no_sales'
      else 'exact_customer'
    end as attribution_quality,
    case
      when fr_raw.required_roi_value > 0 then fr_raw.actual_sales_value / fr_raw.required_roi_value
      when fr_raw.actual_sales_value > 0 then 1
      else 0
    end as actual_coverage_ratio,
    greatest(fr_raw.required_roi_value - fr_raw.actual_sales_value, 0) as coverage_gap,
    greatest(fr_raw.expected_roi_value - fr_raw.actual_sales_value, 0) as expected_gap
  from fr_raw
  cross join sales_as_of sa
),
fr as materialized (
  select
    fr_status.*,
    case
      when fr_status.actual_roi_status = 'on_track'   then 'monitor'
      when fr_status.attribution_quality = 'no_sales' then 'mapping_review'
      when fr_status.actual_coverage_ratio < 0.5
           and fr_status.coverage_gap > 0              then 'high_risk_gap'
      else 'follow_up'
    end as recommended_action
  from fr_status
  where (cardinality(p_roi_statuses) = 0
         or fr_status.actual_roi_status = any(p_roi_statuses))
),
rpa as materialized (
  select
    fr.request_id,
    upper(btrim(coalesce(sp.product_code,
           regexp_replace(mp.normalized_name,' ','','g'))))          as product_code,
    coalesce(sp.product_name, mp.product_name,
             mrp.product_name_snapshot)                              as product_name,
    coalesce(nullif(btrim(sp.line),''), nullif(btrim(mp.line),''),
             nullif(btrim(mrp.line_snapshot),''), 'Unassigned')      as line_label,
    case
      when sum(coalesce(nullif(mrp.value_share,0),0))
             over (partition by mrp.request_id) > 0
        then coalesce(nullif(mrp.value_share,0),0)
             / sum(coalesce(nullif(mrp.value_share,0),0))
               over (partition by mrp.request_id)
      when sum(coalesce(mrp.expected_value,0))
             over (partition by mrp.request_id) > 0
        then coalesce(mrp.expected_value,0)
             / sum(coalesce(mrp.expected_value,0))
               over (partition by mrp.request_id)
      else 1.0 / nullif(count(*) over (partition by mrp.request_id), 0)
    end as share
  from fr
  join marketing_request_products mrp on mrp.request_id = fr.request_id
  join marketing_products mp on mp.id = mrp.product_id
  left join source_of_sales_products sp
    on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
  where (
    cardinality(p_exclude_codes) = 0
    or upper(btrim(coalesce(sp.product_code,''))) != all(p_exclude_codes)
  )
),
-- Every paid request keeps every one of its target pharmacies here, LEFT-joined all the way
-- down: a pharmacy with no distributor account (a nursery, say) still carries its share of the
-- request's cost into the Region and Distributor reports, under 'Unassigned'.
rta as materialized (
  select
    fr.request_id,
    mrph.pharmacy_id,
    case
      when sd.distributor_code is not null then sd.distributor_code
      when mpdc.id is null                 then 'Unassigned'
      else 'Unmapped'
    end                                                                 as distributor_code,
    case
      when sd.distributor_code is not null
        then coalesce(sd.distributor_name, md.display_name, sd.distributor_code)
      when mpdc.id is null then 'No distributor account'
      else 'Unmapped distributor'
    end                                                                 as distributor_name,
    sd.distributor_code as family_code,
    cm.region_code,
    coalesce(sr.region_name, cm.region_code, 'Unassigned')             as region_name,
    1.0 / nullif(count(*) over (partition by fr.request_id), 0)        as share
  from fr
  left join marketing_request_pharmacies mrph on mrph.request_id = fr.request_id
  left join marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
  left join marketing_distributors md on md.id = mpdc.distributor_id
  left join (
    select distinct marketing_normalized_name, parent_distributor_code
    from marketing_roi_distributor_rollup
  ) ru on ru.marketing_normalized_name = md.normalized_name
  left join source_of_sales_distributors sd on sd.distributor_code = ru.parent_distributor_code
  left join lateral (
    select cmx.region_code
    from source_of_sales_customer_map cmx
    where lower(btrim(regexp_replace(coalesce(cmx.customer_code,''),'\s+',' ','g')))
            = mpdc.normalized_pharmacy_code
      and cmx.active
      and (sd.distributor_code is null
           or cmx.distributor_code = sd.distributor_code
           or exists (
             select 1 from marketing_roi_distributor_rollup rcm
             where rcm.parent_distributor_code = sd.distributor_code
               and rcm.sos_distributor_code = cmx.distributor_code
           ))
    order by (cmx.distributor_code = sd.distributor_code) desc nulls last
    limit 1
  ) cm on true
  left join source_of_sales_regions sr on sr.region_code = cm.region_code
),
-- One row per (request, target pharmacy), for the line and product pharmacy counts.
rph as (
  select distinct request_id, pharmacy_id from rta where pharmacy_id is not null
),
ds as (
  select
    count(*)::integer                                                as request_count,
    count(distinct customer_id)::integer                            as active_customers,
    -- The same target pharmacies the Region and Distributor rows count, so the card and the
    -- rows agree; a pharmacy with no distributor account is counted.
    (
      select count(distinct rta.pharmacy_id)::integer
      from rta
      where (cardinality(p_regions) = 0 or rta.region_code = any(p_regions))
        and (cardinality(p_distributors) = 0 or rta.distributor_code = any(p_distributors))
    )                                                                as active_pharmacies,
    coalesce(sum(estimated_cost),0)::numeric                        as total_cost,
    coalesce(sum(required_roi_value),0)::numeric                    as req_roi,
    coalesce(sum(expected_roi_value),0)::numeric                    as exp_roi,
    coalesce(sum(actual_sales_value),0)::numeric                    as actual_val,
    coalesce(sum(actual_sales_units),0)::numeric                    as actual_units,
    coalesce(sum(coverage_gap),0)::numeric                          as cov_gap,
    coalesce(sum(expected_gap),0)::numeric                          as exp_gap,
    count(*) filter (where actual_roi_status='on_track')::integer   as on_track,
    count(*) filter (where actual_roi_status='behind')::integer     as behind,
    count(*) filter (where actual_roi_status='no_data')::integer    as no_data,
    count(*) filter (where recommended_action in
      ('high_risk_gap','follow_up','mapping_review'))::integer       as action_req,
    coalesce(sum(estimated_cost) filter (where actual_roi_status in ('behind','no_data')),0)::numeric as spend_at_risk,
    coalesce(sum(estimated_cost) filter (where actual_roi_status='no_data'),0)::numeric               as no_data_spend,
    count(*) filter (where attribution_quality='mixed')::integer     as mixed_req,
    count(*) filter (where attribution_quality='no_sales')::integer  as no_sales_req,
    sum(exact_sales_rows)::integer                                   as exact_rows,
    sum(fallback_sales_rows)::integer                                as fallback_rows
  from fr
),
line_actuals as (
  select line_label,
         sum(actual_sales_value)::numeric as actual_sales_value,
         0::numeric                       as actual_sales_units
  from marketing_roi_line_facts
  where (p_from_month is null or p_from_month = '' or period >= p_from_month)
    and (p_to_month   is null or p_to_month   = '' or period <= p_to_month)
    and (cardinality(p_lines) = 0 or line_label = any(p_lines))
  group by line_label
),
product_actuals as (
  select product_code,
         max(product_name)                as product_name,
         max(line_label)                  as line_label,
         sum(actual_sales_value)::numeric as actual_sales_value,
         sum(actual_sales_units)::numeric as actual_sales_units
  from marketing_roi_product_facts
  where (p_from_month is null or p_from_month = '' or period >= p_from_month)
    and (p_to_month   is null or p_to_month   = '' or period <= p_to_month)
    and (cardinality(p_products) = 0 or product_code = any(p_products))
    and (cardinality(p_exclude_codes) = 0 or product_code != all(p_exclude_codes))
    and (cardinality(p_lines) = 0 or line_label = any(p_lines))
  group by product_code
),
region_actuals as (
  select region_code,
         max(region_name)                 as region_name,
         sum(actual_sales_value)::numeric as actual_sales_value,
         0::numeric                       as actual_sales_units
  from marketing_roi_region_facts
  where (p_from_month is null or p_from_month = '' or period >= p_from_month)
    and (p_to_month   is null or p_to_month   = '' or period <= p_to_month)
    and (cardinality(p_regions) = 0 or region_code = any(p_regions))
    and (cardinality(p_lines) = 0 or line_label = any(p_lines))
  group by region_code
),
distributor_actuals as (
  select distributor_code,
         family_code,
         max(distributor_name)            as distributor_name,
         sum(actual_sales_value)::numeric as actual_sales_value,
         0::numeric                       as actual_sales_units
  from marketing_roi_distributor_facts
  where (p_from_month is null or p_from_month = '' or period >= p_from_month)
    and (p_to_month   is null or p_to_month   = '' or period <= p_to_month)
    and (cardinality(p_distributors) = 0 or distributor_code = any(p_distributors))
    and (cardinality(p_lines) = 0 or line_label = any(p_lines))
  group by distributor_code, family_code
),
line_agg as (
  select
    rpa.line_label,
    count(distinct fr.request_id)::integer                                          as request_count,
    count(distinct fr.customer_id)::integer                                         as customer_count,
    sum(fr.estimated_cost * rpa.share)::numeric                                     as marketing_cost,
    sum(fr.required_roi_value * rpa.share)::numeric                                 as required_roi_value,
    sum(fr.expected_roi_value * rpa.share)::numeric                                 as expected_roi_value,
    sum(fr.exact_sales_rows)::integer                                               as exact_sales_rows,
    sum(fr.fallback_sales_rows)::integer                                            as fallback_sales_rows,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='on_track')   as on_track,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='behind')     as behind,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='no_data')    as no_data
  from fr join rpa on rpa.request_id = fr.request_id
  group by rpa.line_label
),
product_agg as (
  select
    rpa.product_code,
    max(rpa.product_name)                                                            as product_name,
    max(rpa.line_label)                                                              as line_label,
    count(distinct fr.request_id)::integer                                           as request_count,
    sum(fr.estimated_cost * rpa.share)::numeric                                      as marketing_cost,
    sum(fr.required_roi_value * rpa.share)::numeric                                  as required_roi_value,
    sum(fr.expected_roi_value * rpa.share)::numeric                                  as expected_roi_value,
    sum(fr.exact_sales_rows)::integer                                                as exact_sales_rows,
    sum(fr.fallback_sales_rows)::integer                                             as fallback_sales_rows,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='on_track')    as on_track,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='behind')      as behind,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='no_data')     as no_data
  from fr join rpa on rpa.request_id = fr.request_id
  where rpa.product_code is not null
  group by rpa.product_code
),
-- Counted apart from line_agg / product_agg so the pharmacy join cannot multiply their sums.
line_reach as (
  select rpa.line_label, count(distinct rph.pharmacy_id)::integer as pharmacy_count
  from rpa join rph on rph.request_id = rpa.request_id
  group by rpa.line_label
),
product_reach as (
  select
    rpa.product_code,
    count(distinct fr.customer_id)::integer  as customer_count,
    count(distinct rph.pharmacy_id)::integer as pharmacy_count
  from rpa
  join fr on fr.request_id = rpa.request_id
  left join rph on rph.request_id = rpa.request_id
  where rpa.product_code is not null
  group by rpa.product_code
),
region_agg as (
  select
    coalesce(rta.region_code,'Unassigned')                                           as region_code,
    max(rta.region_name)                                                             as region_name,
    count(distinct fr.request_id)::integer                                           as request_count,
    count(distinct fr.customer_id)::integer                                          as customer_count,
    count(distinct rta.pharmacy_id)::integer                                         as pharmacy_count,
    sum(fr.estimated_cost * rta.share)::numeric                                      as marketing_cost,
    sum(fr.required_roi_value * rta.share)::numeric                                  as required_roi_value,
    sum(fr.expected_roi_value * rta.share)::numeric                                  as expected_roi_value,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='on_track')    as on_track,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='behind')      as behind,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='no_data')     as no_data
  from fr join rta on rta.request_id = fr.request_id
  group by coalesce(rta.region_code,'Unassigned')
),
distributor_agg as (
  select
    rta.distributor_code,
    rta.family_code,
    max(rta.distributor_name)                                                        as distributor_name,
    count(distinct fr.request_id)::integer                                           as request_count,
    count(distinct fr.customer_id)::integer                                          as customer_count,
    count(distinct rta.pharmacy_id)::integer                                         as pharmacy_count,
    sum(fr.estimated_cost * rta.share)::numeric                                      as marketing_cost,
    sum(fr.required_roi_value * rta.share)::numeric                                  as required_roi_value,
    sum(fr.expected_roi_value * rta.share)::numeric                                  as expected_roi_value,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='on_track')    as on_track,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='behind')      as behind,
    count(distinct fr.request_id) filter (where fr.actual_roi_status='no_data')     as no_data
  from fr join rta on rta.request_id = fr.request_id
  group by rta.distributor_code, rta.family_code
),
-- One row per customer of the paid requests. Request count, cost, required and expected ROI
-- come from the requests, so the rows add up to the cards. Attributed sales come from the
-- customer facts, summed ONCE per customer: one customer's requests share one sales ledger, and
-- summing a per-request figure across them would count the same ledger row several times.
customer_req as (
  select
    fr.customer_id,
    max(fr.customer_name)                           as customer_name,
    count(distinct fr.request_id)::integer          as request_count,
    coalesce(sum(fr.estimated_cost),0)::numeric     as marketing_cost,
    coalesce(sum(fr.required_roi_value),0)::numeric as required_roi_value,
    coalesce(sum(fr.expected_roi_value),0)::numeric as expected_roi_value
  from fr
  group by fr.customer_id
),
customer_geo as (
  select
    fr.customer_id,
    string_agg(distinct rta.region_name, ' · ')
      filter (where rta.region_name <> 'Unassigned')                       as region_name,
    bool_or(rta.region_name = 'Unassigned')                                as has_unassigned_region,
    string_agg(distinct rta.distributor_name, ' · ')                       as distributor_name,
    case when count(distinct rta.distributor_code) = 1
         then min(rta.distributor_code) end                                as distributor_code,
    count(distinct rta.pharmacy_id)::integer                               as pharmacy_count
  from fr join rta on rta.request_id = fr.request_id
  group by fr.customer_id
),
customer_sales as (
  select
    cf.customer_id,
    sum(cf.actual_sales_value)::numeric                                      as actual_sales_value,
    sum(cf.actual_sales_units)::numeric                                      as actual_sales_units,
    sum(cf.exact_sales_rows)::integer                                        as exact_sales_rows,
    sum(cf.fallback_sales_rows)::integer                                     as fallback_sales_rows
  from marketing_roi_customer_facts cf
  where cf.customer_id in (select customer_id from customer_req where customer_id is not null)
    and (p_from_month is null or p_from_month = '' or cf.period >= p_from_month)
    and (p_to_month   is null or p_to_month   = '' or cf.period <= p_to_month)
  group by cf.customer_id
),
customer_agg as (
  select
    coalesce(cr.customer_id::text, 'Unassigned')                             as value,
    coalesce(cr.customer_name, 'Unassigned customer')                        as label,
    cg.distributor_code,
    cg.distributor_name,
    coalesce(cg.region_name,
             case when cg.has_unassigned_region then 'Unassigned' end)       as region_name,
    cr.request_count,
    1::integer                                                               as customer_count,
    coalesce(cg.pharmacy_count, 0)::integer                                  as pharmacy_count,
    cr.marketing_cost,
    cr.required_roi_value,
    cr.expected_roi_value,
    coalesce(cs.actual_sales_value, 0)::numeric                              as actual_sales_value,
    coalesce(cs.actual_sales_units, 0)::numeric                              as actual_sales_units,
    coalesce(cs.exact_sales_rows, 0)::integer                                as exact_sales_rows,
    coalesce(cs.fallback_sales_rows, 0)::integer                             as fallback_sales_rows,
    (coalesce(cs.exact_sales_rows, 0) + coalesce(cs.fallback_sales_rows, 0))::integer as sales_rows
  from customer_req cr
  left join customer_geo cg on cg.customer_id is not distinct from cr.customer_id
  left join customer_sales cs on cs.customer_id = cr.customer_id
)
select jsonb_build_object(
  'generatedAt', (select last_success_at from last_refresh),
  'limits', jsonb_build_object(
    'rawRowsReturned', (select count(*) from fr),
    'tableLimit', p_limit
  ),
  'filters', jsonb_build_object(
    'selected', jsonb_build_object(
      'attributionQualities', to_jsonb(p_attribution_qualities),
      'customerSearch',       to_jsonb(coalesce(p_customer_search,'')),
      'distributors',         to_jsonb(p_distributors),
      'fromMonth',            to_jsonb(coalesce(p_from_month,'')),
      'limit',                to_jsonb(p_limit),
      'lines',                to_jsonb(p_lines),
      'products',             to_jsonb(p_products),
      'regions',              to_jsonb(p_regions),
      'roiStatuses',          to_jsonb(p_roi_statuses),
      'toMonth',              to_jsonb(coalesce(p_to_month,''))
    ),
    'lines', (
      select coalesce(jsonb_agg(jsonb_build_object('value',name,'label',name) order by name),'[]'::jsonb)
      from public.lines
    ),
    'regions', (
      -- Only regions that hold customer geography: one with no active customer-map row can
      -- never match a pharmacy, so choosing it always returned nothing.
      select coalesce(jsonb_agg(jsonb_build_object('value',r.region_code,'label',r.region_name) order by r.region_name),'[]'::jsonb)
      from public.source_of_sales_regions r
      where r.active
        and exists (
          select 1 from public.source_of_sales_customer_map m
          where m.region_code = r.region_code and m.active
        )
    ),
    'distributors', (
      select coalesce(jsonb_agg(jsonb_build_object('value',distributor_code,'label',distributor_name) order by distributor_name),'[]'::jsonb)
      from public.source_of_sales_distributors where active
    ),
    'products', (
      select coalesce(jsonb_agg(jsonb_build_object('value',product_code,'label',product_name) order by product_name),'[]'::jsonb)
      from public.source_of_sales_products where active
    ),
    'roiStatuses', jsonb_build_array(
      jsonb_build_object('value','awaiting_data','label','Data pending'),
      jsonb_build_object('value','behind','label','Behind'),
      jsonb_build_object('value','no_data','label','No data'),
      jsonb_build_object('value','on_track','label','On track')
    ),
    'attributionQualities', jsonb_build_array(
      jsonb_build_object('value','exact_customer','label','Exact customer'),
      jsonb_build_object('value','brick_fallback','label','Brick fallback'),
      jsonb_build_object('value','mixed','label','Mixed'),
      jsonb_build_object('value','no_sales','label','No sales')
    )
  ),
  'summary', (
    select jsonb_build_object(
      'marketingRequestCount',      ds.request_count,
      'paidRequestCount',           ds.request_count,
      'activeCustomers',            ds.active_customers,
      'activePharmacies',           ds.active_pharmacies,
      'totalMarketingCost',         ds.total_cost,
      'requiredRoiValue',           ds.req_roi,
      'expectedRoiValue',           ds.exp_roi,
      'actualAttributedSalesValue', ds.actual_val,
      'actualAttributedSalesUnits', ds.actual_units,
      'actualRoiCoverage',          case when ds.req_roi > 0 then ds.actual_val / ds.req_roi else 0 end,
      'coverageGap',                ds.cov_gap,
      'expectedGap',                ds.exp_gap,
      'onTrackRequests',            ds.on_track,
      'behindRequests',             ds.behind,
      'noDataRequests',             ds.no_data,
      'actionRequiredRequests',     ds.action_req,
      'spendAtRisk',                ds.spend_at_risk,
      'noDataSpend',                ds.no_data_spend,
      'freshness', jsonb_build_object(
        'status', case
          when lr.is_refreshing                                                         then 'refreshing'
          when lr.has_recent_failure                                                    then 'failed'
          when lr.last_success_at is null                                               then 'stale'
          when lr.latest_sos_at is not null and lr.latest_sos_at > lr.last_success_at  then 'stale'
          else 'fresh'
        end,
        'lastRefreshedAt', lr.last_success_at
      )
    )
    from ds, last_refresh lr
  ),
  'decisionSummary', (
    select jsonb_build_object(
      'actionRequiredRequests', ds.action_req,
      'spendAtRisk',            ds.spend_at_risk,
      'coverageGap',            ds.cov_gap,
      'expectedGap',            ds.exp_gap,
      'noDataSpend',            ds.no_data_spend,
      'topRiskRequest', (
        select jsonb_build_object(
          'id',                 fr.request_id,
          'requestCode',        fr.request_code,
          'customerName',       coalesce(fr.customer_name,'Unassigned'),
          'line',               fr.line_label,
          'estimatedCost',      fr.estimated_cost,
          'requiredRoiValue',   fr.required_roi_value,
          'actualSalesValue',   fr.actual_sales_value,
          'coverageGap',        fr.coverage_gap,
          'actualRoiCoverage',  fr.actual_coverage_ratio,
          'actualRoiStatus',    fr.actual_roi_status,
          'attributionQuality', fr.attribution_quality,
          'recommendedAction',  fr.recommended_action
        )
        from fr
        order by fr.coverage_gap desc, fr.estimated_cost desc
        limit 1
      )
    )
    from ds
  ),
  'attributionHealth', (
    select jsonb_build_object(
      'exactSalesRows',            ds.exact_rows,
      'fallbackSalesRows',         ds.fallback_rows,
      'mixedRequests',             ds.mixed_req,
      'noSalesRequests',           ds.no_sales_req,
      'unmatchedMappingWarnings',  0
    )
    from ds
  ),
  'roiTrend', (
    select coalesce(jsonb_agg(row_data order by period), '[]'::jsonb)
    from (
      select
        pay_month as period,
        jsonb_build_object(
          'period',          pay_month,
          'requestCount',    count(*)::integer,
          'marketingCost',   sum(estimated_cost)::numeric,
          'requiredRoiValue',sum(required_roi_value)::numeric,
          'expectedRoiValue',sum(expected_roi_value)::numeric,
          'actualSalesValue',sum(actual_sales_value)::numeric,
          'coverageGap',     sum(coverage_gap)::numeric,
          'onTrackCount',    (count(*) filter (where actual_roi_status='on_track'))::integer,
          'behindCount',     (count(*) filter (where actual_roi_status='behind'))::integer,
          'noDataCount',     (count(*) filter (where actual_roi_status='no_data'))::integer
        ) as row_data
      from fr
      group by pay_month
    ) t
  ),
  'lineRoi', (
    select coalesce(
      jsonb_agg(row_data order by cov_gap desc, marketing_cost desc),
      '[]'::jsonb
    )
    from (
      select jsonb_build_object(
        'value',             coalesce(la.line_label, la2.line_label, 'Unassigned'),
        'label',             coalesce(la.line_label, la2.line_label, 'Unassigned'),
        'line',              coalesce(la.line_label, la2.line_label, 'Unassigned'),
        'requestCount',      coalesce(la.request_count,0),
        'customerCount',     coalesce(la.customer_count,0),
        'pharmacyCount',     coalesce(lr.pharmacy_count,0),
        'marketingCost',     coalesce(la.marketing_cost,0),
        'requiredRoiValue',  coalesce(la.required_roi_value,0),
        'expectedRoiValue',  coalesce(la.expected_roi_value,0),
        'actualSalesValue',  coalesce(la2.actual_sales_value,0),
        'actualSalesUnits',  coalesce(la2.actual_sales_units,0),
        'coverageGap',       greatest(coalesce(la.required_roi_value,0)-coalesce(la2.actual_sales_value,0),0),
        'actualRoiCoverage', case when coalesce(la.required_roi_value,0)>0
                               then coalesce(la2.actual_sales_value,0)/la.required_roi_value else 0 end,
        'onTrackRequests',   coalesce(la.on_track,0),
        'behindRequests',    coalesce(la.behind,0),
        'noDataRequests',    coalesce(la.no_data,0),
        'exactSalesRows',    coalesce(la.exact_sales_rows,0),
        'fallbackSalesRows', coalesce(la.fallback_sales_rows,0)
      ) as row_data,
      greatest(coalesce(la.required_roi_value,0)-coalesce(la2.actual_sales_value,0),0) as cov_gap,
      coalesce(la.marketing_cost,0) as marketing_cost
      from line_agg la
      left join line_reach lr on lr.line_label = la.line_label
      full join line_actuals la2 on lower(btrim(la2.line_label)) = lower(btrim(la.line_label))
      limit p_limit
    ) x
  ),
  'productRoi', (
    select coalesce(
      jsonb_agg(row_data order by cov_gap desc, marketing_cost desc),
      '[]'::jsonb
    )
    from (
      select jsonb_build_object(
        'value',             coalesce(pa.product_code, pa2.product_code, 'Unassigned'),
        'label',             coalesce(pa2.product_name, pa.product_name, pa.product_code, 'Unassigned'),
        'line',              coalesce(pa.line_label, pa2.line_label),
        'requestCount',      coalesce(pa.request_count,0),
        'customerCount',     coalesce(pr.customer_count,0),
        'pharmacyCount',     coalesce(pr.pharmacy_count,0),
        'marketingCost',     coalesce(pa.marketing_cost,0),
        'requiredRoiValue',  coalesce(pa.required_roi_value,0),
        'expectedRoiValue',  coalesce(pa.expected_roi_value,0),
        'actualSalesValue',  coalesce(pa2.actual_sales_value,0),
        'actualSalesUnits',  coalesce(pa2.actual_sales_units,0),
        'coverageGap',       greatest(coalesce(pa.required_roi_value,0)-coalesce(pa2.actual_sales_value,0),0),
        'actualRoiCoverage', case when coalesce(pa.required_roi_value,0)>0
                               then coalesce(pa2.actual_sales_value,0)/pa.required_roi_value else 0 end,
        'onTrackRequests',   coalesce(pa.on_track,0),
        'behindRequests',    coalesce(pa.behind,0),
        'noDataRequests',    coalesce(pa.no_data,0),
        'exactSalesRows',    coalesce(pa.exact_sales_rows,0),
        'fallbackSalesRows', coalesce(pa.fallback_sales_rows,0)
      ) as row_data,
      greatest(coalesce(pa.required_roi_value,0)-coalesce(pa2.actual_sales_value,0),0) as cov_gap,
      coalesce(pa.marketing_cost,0) as marketing_cost
      from product_agg pa
      left join product_reach pr on pr.product_code = pa.product_code
      full join product_actuals pa2 on upper(btrim(pa2.product_code)) = upper(btrim(pa.product_code))
      limit p_limit
    ) x
  ),
  'regionRoi', (
    select coalesce(
      jsonb_agg(row_data order by cov_gap desc, marketing_cost desc),
      '[]'::jsonb
    )
    from (
      select jsonb_build_object(
        'value',             coalesce(ra.region_code, ra2.region_code, 'Unassigned'),
        'label',             coalesce(ra.region_name, ra2.region_name, ra.region_code, 'Unassigned'),
        'line',              null,
        'requestCount',      coalesce(ra.request_count,0),
        'customerCount',     coalesce(ra.customer_count,0),
        'pharmacyCount',     coalesce(ra.pharmacy_count,0),
        'marketingCost',     coalesce(ra.marketing_cost,0),
        'requiredRoiValue',  coalesce(ra.required_roi_value,0),
        'expectedRoiValue',  coalesce(ra.expected_roi_value,0),
        'actualSalesValue',  coalesce(ra2.actual_sales_value,0),
        'actualSalesUnits',  coalesce(ra2.actual_sales_units,0),
        'coverageGap',       greatest(coalesce(ra.required_roi_value,0)-coalesce(ra2.actual_sales_value,0),0),
        'actualRoiCoverage', case when coalesce(ra.required_roi_value,0)>0
                               then coalesce(ra2.actual_sales_value,0)/ra.required_roi_value else 0 end,
        'onTrackRequests',   coalesce(ra.on_track,0),
        'behindRequests',    coalesce(ra.behind,0),
        'noDataRequests',    coalesce(ra.no_data,0),
        'exactSalesRows',    0,
        'fallbackSalesRows', 0
      ) as row_data,
      greatest(coalesce(ra.required_roi_value,0)-coalesce(ra2.actual_sales_value,0),0) as cov_gap,
      coalesce(ra.marketing_cost,0) as marketing_cost
      from region_agg ra
      full join region_actuals ra2 on lower(btrim(ra2.region_code)) = lower(btrim(ra.region_code))
      limit p_limit
    ) x
  ),
  'distributorRoi', (
    select coalesce(
      jsonb_agg(row_data order by cov_gap desc, marketing_cost desc),
      '[]'::jsonb
    )
    from (
      select jsonb_build_object(
        'value',             coalesce(da.distributor_code, da2.distributor_code, 'Unassigned'),
        'label',             coalesce(da.distributor_name, da2.distributor_name, da.distributor_code, 'Unassigned'),
        'line',              null,
        'requestCount',      coalesce(da.request_count,0),
        'customerCount',     coalesce(da.customer_count,0),
        'pharmacyCount',     coalesce(da.pharmacy_count,0),
        'marketingCost',     coalesce(da.marketing_cost,0),
        'requiredRoiValue',  coalesce(da.required_roi_value,0),
        'expectedRoiValue',  coalesce(da.expected_roi_value,0),
        'actualSalesValue',  coalesce(da2.actual_sales_value,0),
        'actualSalesUnits',  coalesce(da2.actual_sales_units,0),
        'coverageGap',       greatest(coalesce(da.required_roi_value,0)-coalesce(da2.actual_sales_value,0),0),
        'actualRoiCoverage', case when coalesce(da.required_roi_value,0)>0
                               then coalesce(da2.actual_sales_value,0)/da.required_roi_value else 0 end,
        'onTrackRequests',   coalesce(da.on_track,0),
        'behindRequests',    coalesce(da.behind,0),
        'noDataRequests',    coalesce(da.no_data,0),
        'exactSalesRows',    0,
        'fallbackSalesRows', 0
      ) as row_data,
      greatest(coalesce(da.required_roi_value,0)-coalesce(da2.actual_sales_value,0),0) as cov_gap,
      coalesce(da.marketing_cost,0) as marketing_cost
      from distributor_agg da
      full join distributor_actuals da2
        on upper(btrim(da2.distributor_code)) = upper(btrim(da.distributor_code))
       and da2.family_code is not distinct from da.family_code
      limit p_limit
    ) x
  ),
  'requestReport', (
    select coalesce(
      jsonb_agg(row_data order by risk_rank asc, cov_gap desc, cost desc),
      '[]'::jsonb
    )
    from (
      select jsonb_build_object(
        'id',                 fr.request_id,
        'requestCode',        fr.request_code,
        'status',             coalesce(mr.status, 'unknown'),
        'payDate',            mr.pay_date,
        'payMonth',           fr.pay_month,
        'roiDurationMonths',  coalesce(mr.roi_duration_months, 1),
        'customerName',       coalesce(fr.customer_name,'Unassigned'),
        'customerCode',       fr.customer_code,
        'line',               fr.line_label,
        'estimatedCost',      fr.estimated_cost,
        'requiredRoiValue',   fr.required_roi_value,
        'expectedRoiValue',   fr.expected_roi_value,
        'actualSalesValue',   fr.actual_sales_value,
        'actualSalesUnits',   fr.actual_sales_units,
        'actualRoiCoverage',  fr.actual_coverage_ratio,
        'coverageGap',        fr.coverage_gap,
        'expectedGap',        fr.expected_gap,
        'actualRoiStatus',    fr.actual_roi_status,
        'attributionQuality', fr.attribution_quality,
        'recommendedAction',  fr.recommended_action,
        'exactSalesRows',     fr.exact_sales_rows,
        'fallbackSalesRows',  fr.fallback_sales_rows,
        'salesRows',          fr.sales_rows
      ) as row_data,
      case fr.actual_roi_status
        when 'no_data' then 0 when 'behind' then 1 else 2
      end as risk_rank,
      fr.coverage_gap as cov_gap,
      fr.estimated_cost as cost
      from fr
      left join marketing_requests mr on mr.id = fr.request_id
      order by risk_rank asc, cov_gap desc, cost desc
      limit p_limit
    ) x
  ),
  'customerImpact', (
    select coalesce(
      jsonb_agg(row_data order by cov_gap desc, actual_sales_value desc),
      '[]'::jsonb
    )
    from (
      select jsonb_build_object(
        'value',             ca.value,
        'label',             ca.label,
        'distributorCode',   ca.distributor_code,
        'distributorName',   ca.distributor_name,
        'regionName',        ca.region_name,
        'requestCount',      ca.request_count,
        'customerCount',     ca.customer_count,
        'pharmacyCount',     ca.pharmacy_count,
        'marketingCost',     ca.marketing_cost,
        'requiredRoiValue',  ca.required_roi_value,
        'expectedRoiValue',  ca.expected_roi_value,
        'actualSalesValue',  ca.actual_sales_value,
        'actualSalesUnits',  ca.actual_sales_units,
        'coverageGap',       greatest(ca.required_roi_value-ca.actual_sales_value,0),
        'actualRoiCoverage', case when ca.required_roi_value>0
                               then ca.actual_sales_value/ca.required_roi_value else 0 end,
        'salesRows',         ca.sales_rows,
        'exactSalesRows',    ca.exact_sales_rows,
        'fallbackSalesRows', ca.fallback_sales_rows
      ) as row_data,
      greatest(ca.required_roi_value-ca.actual_sales_value,0) as cov_gap,
      ca.actual_sales_value
      from customer_agg ca
      order by cov_gap desc, ca.actual_sales_value desc
      limit p_limit
    ) x
  )
)
$$;

ALTER FUNCTION public.phx_marketing_roi_fast(p_lines text[], p_regions text[], p_products text[], p_roi_statuses text[], p_from_month text, p_to_month text, p_customer_search text, p_distributors text[], p_attribution_qualities text[], p_limit integer, p_exclude_codes text[]) OWNER TO postgres;

--
-- Name: phx_marketing_roi_health(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_roi_health() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $_$
with roi_all as (
  select * from phx_marketing_request_roi_actuals(
    array(select id from marketing_requests where request_code ~ '^REQ-[0-9]{4}$')
  )
),
elig as (
  select mr.id rid, mr.status,
         date_trunc('month', mr.pay_date)::date ws,
         (date_trunc('month', mr.pay_date) + make_interval(months => greatest(mr.roi_duration_months, 1) - 1))::date we
  from marketing_requests mr
  where mr.request_code ~ '^REQ-[0-9]{4}$'
    and mr.status in ('approved','active','roi_tracking','closed','finance_hold')
    and mr.pay_date is not null
),
hit as (
  select distinct e.rid, r.id row_id
  from elig e
  join marketing_request_products mrp on mrp.request_id = e.rid
  join marketing_products mp on mp.id = mrp.product_id
  join marketing_request_pharmacies mrph on mrph.request_id = e.rid
  join marketing_pharmacy_distributor_codes pdc on pdc.pharmacy_id = mrph.pharmacy_id
  join marketing_distributors md on md.id = pdc.distributor_id
  join marketing_roi_distributor_rollup ru on ru.marketing_normalized_name = md.normalized_name
  join source_of_sales_import_rows r on r.distributor_code = ru.sos_distributor_code
  join source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
  join source_of_sales_products sp on sp.product_code = r.product_code and sp.normalized_product_name = mp.normalized_name
  where r.validation_state = 'valid'
    and pdc.normalized_pharmacy_code = lower(btrim(regexp_replace(r.client_code, '\s+', ' ', 'g')))
    and to_date(r.invoice_period, 'YYYY-MM') between date_trunc('month', e.ws) and e.we
),
by_status as (
  select mr.status,
         count(*) filter (where coalesce(a.actual_value, 0) <> 0) reqs_with_value,
         round(coalesce(sum(a.actual_value), 0)::numeric, 2) val
  from marketing_requests mr
  left join roi_all a on a.request_id = mr.id
  where mr.request_code ~ '^REQ-[0-9]{4}$'
  group by mr.status
),
periods as (
  select r.invoice_period, count(*) n
  from source_of_sales_import_rows r
  join source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
  where r.validation_state = 'valid'
  group by r.invoice_period
),
orphans as (
  select d.distributor_code, count(*) n
  from source_of_sales_import_rows r
  join source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
  join source_of_sales_distributors d on d.distributor_code = r.distributor_code
  where r.validation_state = 'valid'
    and not exists (select 1 from marketing_distributors md where md.normalized_name = d.normalized_distributor_name)
    and not exists (select 1 from marketing_roi_distributor_rollup ru where ru.sos_distributor_code = d.distributor_code)
  group by d.distributor_code
),
dc as (
  select count(*) pairs, count(distinct row_id) distinct_rows,
         count(*) - count(distinct row_id) overcount,
         (select count(*) from (select row_id from hit group by row_id having count(distinct rid) > 1) z) shared
  from hit
)
select jsonb_build_object(
  'generated_at', now(),
  'blocked_batches', (select count(*) from source_of_sales_import_batches where status <> 'validated'),
  'validated_periods', (select coalesce(jsonb_agg(jsonb_build_object('period', invoice_period, 'rows', n) order by invoice_period), '[]'::jsonb) from periods),
  'roi_by_status', (select coalesce(jsonb_agg(jsonb_build_object('status', status, 'reqs_with_value', reqs_with_value, 'value', val) order by val desc), '[]'::jsonb) from by_status),
  'dashboard_headline_value', (select coalesce(val, 0) from by_status where status = 'approved'),
  'true_matched_total', (select coalesce(sum(val), 0) from by_status),
  'hidden_pending_value', (select coalesce(val, 0) from by_status where status = 'pending_approval'),
  'double_count', (select jsonb_build_object('pairs', pairs, 'distinct_rows', distinct_rows, 'overcount', overcount, 'rows_shared_by_multiple_requests', shared) from dc),
  'unbridged_distributor_codes_with_volume', (select coalesce(jsonb_agg(jsonb_build_object('code', distributor_code, 'rows', n) order by n desc), '[]'::jsonb) from orphans),
  'unbridged_marketing_products', (select coalesce(jsonb_agg(distinct mp.product_name), '[]'::jsonb)
    from marketing_request_products mrp
    join marketing_products mp on mp.id = mrp.product_id
    join marketing_requests mr on mr.id = mrp.request_id
    where mr.request_code ~ '^REQ-[0-9]{4}$'
      and not exists (select 1 from source_of_sales_products sp where sp.normalized_product_name = mp.normalized_name)),
  'requests_with_only_nonnumeric_codes', (select coalesce(jsonb_agg(rc), '[]'::jsonb) from (
    select mr.request_code rc from marketing_requests mr
    where mr.request_code ~ '^REQ-[0-9]{4}$'
      and exists (select 1 from marketing_request_pharmacies x where x.request_id = mr.id)
      and not exists (
        select 1 from marketing_request_pharmacies mrph
        join marketing_pharmacy_distributor_codes pdc on pdc.pharmacy_id = mrph.pharmacy_id
        where mrph.request_id = mr.id and pdc.normalized_pharmacy_code ~ '^[0-9]+$')) q),
  'overall_pass', (
    (select count(*) from source_of_sales_import_batches where status <> 'validated') = 0
    and (select overcount from dc) = 0
    and (select shared from dc) = 0)
)
$_$;

ALTER FUNCTION public.phx_marketing_roi_health() OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_roi_health(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_roi_health() IS 'Read-only post-upload health check for the marketing ROI pipeline. overall_pass = hard invariants (no blocked batch, no cross-request double-count). See scripts/verify-marketing-roi.ts.';

--
-- Name: phx_marketing_roi_latest_validated_period(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_roi_latest_validated_period() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with loaded as (
    select distinct b.period, b.distributor_code
    from public.source_of_sales_import_batches b
    where b.status = 'validated'
      and coalesce(btrim(b.period), '') <> ''
      and coalesce(b.template_key, '') <> 'direct_orders'
      and upper(coalesce(b.distributor_code, '')) <> 'DIRECTREQ'
      and b.period <= to_char(date_trunc('month', now() at time zone 'Africa/Cairo') - interval '1 month', 'YYYY-MM')
  ),
  months as (select distinct period from loaded),
  settled as (
    select period from months
    where period < (select max(period) from months)
  ),
  every_month as (
    select l.distributor_code
    from loaded l
    where l.period in (select period from settled)
    group by l.distributor_code
    having count(distinct l.period) = (select count(*) from settled)
  ),
  complete as (
    select max(m.period) as period
    from months m
    where not exists (
      select 1 from every_month e
      where not exists (
        select 1 from loaded l where l.period = m.period and l.distributor_code = e.distributor_code
      )
    )
  )
  select case
    when (select count(*) from settled) = 0 then (select max(period) from months)
    else (select period from complete)
  end;
$$;

ALTER FUNCTION public.phx_marketing_roi_latest_validated_period() OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_roi_latest_validated_period(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_roi_latest_validated_period() IS 'Latest validated Source-of-Sales invoice period (YYYY-MM) — the "sales data as of" trust badge for the marketing ROI report.';

--
-- Name: phx_marketing_vendor_code_counts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_marketing_vendor_code_counts() RETURNS TABLE(vendor_id bigint, codes_loaded bigint, codes_waiting bigint, customers_linked bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
  with loaded as (
    select r.distributor_id as id, count(*) as n
    from marketing_pharmacy_code_references r
    group by r.distributor_id
  ),
  waiting as (
    select c.distributor_id as id, count(*) as n
    from phx_v_sales_pharmacy_code_candidates c
    where not exists (
      select 1
      from marketing_pharmacy_code_references r
      where r.distributor_id = c.distributor_id
        and r.normalized_pharmacy_code = c.normalized_pharmacy_code
    )
    group by c.distributor_id
  ),
  linked as (
    select dc.distributor_id as id, count(distinct cp.customer_id) as n
    from marketing_customer_pharmacies cp
    join marketing_pharmacy_distributor_codes dc on dc.id = cp.distributor_code_id
    where cp.active
    group by dc.distributor_id
  )
  select
    d.id,
    coalesce(loaded.n, 0),
    coalesce(waiting.n, 0),
    coalesce(linked.n, 0)
  from marketing_distributors d
  left join loaded on loaded.id = d.id
  left join waiting on waiting.id = d.id
  left join linked on linked.id = d.id;
$$;

ALTER FUNCTION public.phx_marketing_vendor_code_counts() OWNER TO postgres;

--
-- Name: FUNCTION phx_marketing_vendor_code_counts(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_marketing_vendor_code_counts() IS 'For the Vendors panel on Marketing Control: per vendor, the pharmacy codes loaded, the codes the Sales map holds that are not loaded yet, and the customers with a live link through this vendor. Read-only.';

--
-- Name: phx_merge_ats_candidates(uuid, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_merge_ats_candidates(p_survivor_id uuid, p_duplicate_id uuid, p_borrow jsonb, p_status_event_provenance text, p_comment_provenance text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  -- The ONLY columns a merge may write onto the survivor: mergeableFields (candidate-merge.ts),
  -- the three _norm twins borrowedPayload adds, and screening_extra_answers. `status`, `notes`,
  -- `source` and the rest are deliberately absent — a borrowed status would undo a decision.
  v_allowed constant text[] := array[
    'national_id', 'email', 'phone', 'whatsapp', 'linkedin_url', 'nationality', 'date_of_birth',
    'place_of_birth', 'gender', 'marital_status', 'military_status', 'address', 'governorate',
    'current_job_title', 'applied_for_job_title', 'applied_for_evidence', 'professional_summary',
    'current_employer', 'current_role_responsibilities', 'years_experience', 'expected_salary',
    'declared_expected_salary', 'declared_background', 'declared_experience', 'notice_period',
    'cv_reference_name', 'cv_external_url', 'faculty', 'university', 'degree', 'graduation_year',
    'grade', 'medical_rep_employer', 'medical_rep_experience_from', 'medical_rep_experience_to',
    'offer_id',
    'email_norm', 'phone_norm', 'national_id_norm',
    'screening_extra_answers'
  ];
  -- Exactly the characters JavaScript's String.prototype.trim() removes (WhiteSpace + LineTerminator),
  -- so a copied note is trimmed the way describeCopiedHistoryLine trimmed it.
  v_ws constant text :=
    chr(9) || chr(10) || chr(11) || chr(12) || chr(13) || chr(32) || chr(160) || chr(5760)
    || chr(8192) || chr(8193) || chr(8194) || chr(8195) || chr(8196) || chr(8197) || chr(8198)
    || chr(8199) || chr(8200) || chr(8201) || chr(8202) || chr(8232) || chr(8233) || chr(8239)
    || chr(8287) || chr(12288) || chr(65279);
  v_first uuid;
  v_second uuid;
  v_uuid_ids uuid[];
  v_big_ids bigint[];
  v_text_ids text[];
  v_moved integer;
  v_count integer;
  v_deduped jsonb := '{}'::jsonb;
  v_reassigned jsonb := '{}'::jsonb;
  v_copied jsonb := '{}'::jsonb;
  v_relinked jsonb := '{}'::jsonb;
  v_bad text[];
  v_set text;
  v_candidate jsonb := null;
begin
  if p_survivor_id is null or p_duplicate_id is null then
    raise exception 'Both the candidate to keep and the duplicate are required.' using errcode = '22023';
  end if;
  if p_survivor_id = p_duplicate_id then
    raise exception 'A candidate cannot be merged into itself.' using errcode = '22023';
  end if;
  if coalesce(p_status_event_provenance, '') = '' or coalesce(p_comment_provenance, '') = '' then
    raise exception 'phx_merge_ats_candidates: both provenance lines are required' using errcode = '22023';
  end if;
  if p_borrow is not null and jsonb_typeof(p_borrow) <> 'object' then
    raise exception 'phx_merge_ats_candidates: p_borrow must be a jsonb object' using errcode = '22023';
  end if;
  select array_agg(k order by k) into v_bad
    from jsonb_object_keys(coalesce(p_borrow, '{}'::jsonb)) k
   where k <> all (v_allowed);
  if v_bad is not null then
    raise exception 'phx_merge_ats_candidates: these columns may not be written by a merge: %', v_bad
      using errcode = '22023';
  end if;

  -- ── THE LOCK — both rows, lowest id first, so two merges touching the same pair queue rather
  -- than deadlock. A row that is gone by now refuses the whole merge before anything is written.
  -- TypeScript read BOTH rows a moment before calling this, so a row missing HERE is a lost race
  -- (a concurrent merge or delete), never an unknown id: it raises its own SQLSTATE, PX409, which
  -- mergeCandidates turns into a 409 the recruiter can act on (refresh and try again).
  v_first := least(p_survivor_id, p_duplicate_id);
  v_second := greatest(p_survivor_id, p_duplicate_id);
  perform 1 from public.ats_candidates where id = v_first for update;
  if not found then
    raise exception 'phx_merge_ats_candidates: candidate % was merged or deleted by a concurrent change', v_first
      using errcode = 'PX409';
  end if;
  perform 1 from public.ats_candidates where id = v_second for update;
  if not found then
    raise exception 'phx_merge_ats_candidates: candidate % was merged or deleted by a concurrent change', v_second
      using errcode = 'PX409';
  end if;

  -- ── STEP 2 — the five tables UNIQUE on (candidate_id, key). A duplicate row whose key the
  -- survivor already holds is BLOCKED (the survivor's own row wins); every other row moves. A NULL
  -- or empty key never blocks. Mirrors dedupedChildTables / splitRowsByExistingKey exactly.

  -- ats_candidate_manager_sends — unique (candidate_id, manager_hr_id); FK cascades the blocked rows.
  select coalesce(array_agg(d.id), '{}') into v_uuid_ids
    from public.ats_candidate_manager_sends d
   where d.candidate_id = p_duplicate_id
     and coalesce(d.manager_hr_id::text, '') <> ''
     and exists (
       select 1 from public.ats_candidate_manager_sends s
        where s.candidate_id = p_survivor_id and s.manager_hr_id = d.manager_hr_id
     );
  update public.ats_candidate_manager_sends
     set candidate_id = p_survivor_id
   where candidate_id = p_duplicate_id and id <> all (v_uuid_ids);
  get diagnostics v_moved = row_count;
  v_deduped := v_deduped || jsonb_build_object('ats_candidate_manager_sends',
    jsonb_build_object('moved', v_moved, 'blocked', cardinality(v_uuid_ids)));

  -- ats_candidate_manager_folders — unique (candidate_id, manager_hr_id_norm); NO foreign key, so
  -- the blocked rows are deleted here or they outlive the duplicate as orphans.
  select coalesce(array_agg(d.id), '{}') into v_big_ids
    from public.ats_candidate_manager_folders d
   where d.candidate_id = p_duplicate_id
     and coalesce(d.manager_hr_id_norm::text, '') <> ''
     and exists (
       select 1 from public.ats_candidate_manager_folders s
        where s.candidate_id = p_survivor_id and s.manager_hr_id_norm = d.manager_hr_id_norm
     );
  update public.ats_candidate_manager_folders
     set candidate_id = p_survivor_id
   where candidate_id = p_duplicate_id and id <> all (v_big_ids);
  get diagnostics v_moved = row_count;
  delete from public.ats_candidate_manager_folders
   where candidate_id = p_duplicate_id and id = any (v_big_ids);
  v_deduped := v_deduped || jsonb_build_object('ats_candidate_manager_folders',
    jsonb_build_object('moved', v_moved, 'blocked', cardinality(v_big_ids)));

  -- ats_candidate_district_returns — PARTIAL unique (manager_hr_id, candidate_id) WHERE status =
  -- 'open': only an open row on BOTH sides can collide; a resolved return always travels.
  select coalesce(array_agg(d.id), '{}') into v_uuid_ids
    from public.ats_candidate_district_returns d
   where d.candidate_id = p_duplicate_id
     and coalesce(d.status::text, '') = 'open'
     and coalesce(d.manager_hr_id::text, '') <> ''
     and exists (
       select 1 from public.ats_candidate_district_returns s
        where s.candidate_id = p_survivor_id
          and coalesce(s.status::text, '') = 'open'
          and s.manager_hr_id = d.manager_hr_id
     );
  update public.ats_candidate_district_returns
     set candidate_id = p_survivor_id
   where candidate_id = p_duplicate_id and id <> all (v_uuid_ids);
  get diagnostics v_moved = row_count;
  v_deduped := v_deduped || jsonb_build_object('ats_candidate_district_returns',
    jsonb_build_object('moved', v_moved, 'blocked', cardinality(v_uuid_ids)));

  -- ats_candidate_views — primary key (candidate_id, viewer_hr_id), NO id column: its rows are
  -- named by viewer_hr_id. FK cascades the blocked rows.
  select coalesce(array_agg(d.viewer_hr_id), '{}') into v_text_ids
    from public.ats_candidate_views d
   where d.candidate_id = p_duplicate_id
     and coalesce(d.viewer_hr_id::text, '') <> ''
     and exists (
       select 1 from public.ats_candidate_views s
        where s.candidate_id = p_survivor_id and s.viewer_hr_id = d.viewer_hr_id
     );
  update public.ats_candidate_views
     set candidate_id = p_survivor_id
   where candidate_id = p_duplicate_id and viewer_hr_id <> all (v_text_ids);
  get diagnostics v_moved = row_count;
  v_deduped := v_deduped || jsonb_build_object('ats_candidate_views',
    jsonb_build_object('moved', v_moved, 'blocked', cardinality(v_text_ids)));

  -- ats_cv_folder_items — unique (folder_id, candidate_id); NO foreign key on candidate_id, so the
  -- blocked rows are deleted here.
  select coalesce(array_agg(d.id), '{}') into v_big_ids
    from public.ats_cv_folder_items d
   where d.candidate_id = p_duplicate_id
     and coalesce(d.folder_id::text, '') <> ''
     and exists (
       select 1 from public.ats_cv_folder_items s
        where s.candidate_id = p_survivor_id and s.folder_id = d.folder_id
     );
  update public.ats_cv_folder_items
     set candidate_id = p_survivor_id
   where candidate_id = p_duplicate_id and id <> all (v_big_ids);
  get diagnostics v_moved = row_count;
  delete from public.ats_cv_folder_items
   where candidate_id = p_duplicate_id and id = any (v_big_ids);
  v_deduped := v_deduped || jsonb_build_object('ats_cv_folder_items',
    jsonb_build_object('moved', v_moved, 'blocked', cardinality(v_big_ids)));

  -- ── STEP 3 — the plain child tables, re-pointed whole. Applications first: the only one with a
  -- unique index that can still refuse (recruitment_applications_active_uidx).
  update public.ats_applications set candidate_id = p_survivor_id where candidate_id = p_duplicate_id;
  get diagnostics v_count = row_count;
  v_reassigned := v_reassigned || jsonb_build_object('ats_applications', v_count);

  update public.ats_interview_bookings set candidate_id = p_survivor_id where candidate_id = p_duplicate_id;
  get diagnostics v_count = row_count;
  v_reassigned := v_reassigned || jsonb_build_object('ats_interview_bookings', v_count);

  update public.ats_files set candidate_id = p_survivor_id where candidate_id = p_duplicate_id;
  get diagnostics v_count = row_count;
  v_reassigned := v_reassigned || jsonb_build_object('ats_files', v_count);

  update public.ats_candidate_cv_extractions set candidate_id = p_survivor_id where candidate_id = p_duplicate_id;
  get diagnostics v_count = row_count;
  v_reassigned := v_reassigned || jsonb_build_object('ats_candidate_cv_extractions', v_count);

  update public.ats_cv_intake_events set candidate_id = p_survivor_id where candidate_id = p_duplicate_id;
  get diagnostics v_count = row_count;
  v_reassigned := v_reassigned || jsonb_build_object('ats_cv_intake_events', v_count);

  -- ── STEP 4 — the two append-only tables, COPIED (their triggers refuse an UPDATE). Every column
  -- carried verbatim, oldest first, and the note column gains the provenance line. Status-event
  -- originals stay (the trigger refuses DELETE too); comment originals — exactly the rows copied —
  -- are deleted, since nothing else would ever remove them.
  with src as (
    select e.id, e.actor_hr_id, e.created_at, e.from_status, e.note, e.to_status
      from public.ats_candidate_status_events e
     where e.candidate_id = p_duplicate_id
  ), ins as (
    insert into public.ats_candidate_status_events
      (candidate_id, actor_hr_id, created_at, from_status, note, to_status)
    select p_survivor_id, src.actor_hr_id, src.created_at, src.from_status,
           case when btrim(coalesce(src.note, ''), v_ws) <> ''
                then btrim(src.note, v_ws) || ' ' || p_status_event_provenance
                else p_status_event_provenance end,
           src.to_status
      from src
     order by src.created_at, src.id
    returning 1
  )
  select count(*) into v_count from ins;
  v_copied := v_copied || jsonb_build_object('ats_candidate_status_events', v_count);

  with src as (
    select c.id, c.author_hr_id, c.author_job_title, c.author_name, c.body, c.created_at
      from public.ats_candidate_comments c
     where c.candidate_id = p_duplicate_id
  ), ins as (
    insert into public.ats_candidate_comments
      (candidate_id, author_hr_id, author_job_title, author_name, body, created_at)
    select p_survivor_id, src.author_hr_id, src.author_job_title, src.author_name,
           case when btrim(coalesce(src.body, ''), v_ws) <> ''
                then btrim(src.body, v_ws) || ' ' || p_comment_provenance
                else p_comment_provenance end,
           src.created_at
      from src
     order by src.created_at, src.id
    returning 1
  ), del as (
    delete from public.ats_candidate_comments c
     where c.id in (select src.id from src)
    returning 1
  )
  select count(*) into v_count from ins;
  v_copied := v_copied || jsonb_build_object('ats_candidate_comments', v_count);

  -- ── STEP 5 — the record that links by a column of its own naming.
  update public.ats_whatsapp_classification_sessions
     set applied_candidate_id = p_survivor_id
   where applied_candidate_id = p_duplicate_id;
  get diagnostics v_count = row_count;
  v_relinked := v_relinked || jsonb_build_object('ats_whatsapp_classification_sessions', v_count);

  -- ── STEP 6 — the duplicate itself. Its email and national ID are freed here, before step 7
  -- writes them onto the survivor (both carry a partial UNIQUE index).
  delete from public.ats_candidates where id = p_duplicate_id;

  -- ── STEP 7 — the survivor's blanks, from the whitelisted columns TypeScript chose.
  if p_borrow is not null and p_borrow <> '{}'::jsonb then
    select string_agg(format('%I = r.%I', k, k), ', ' order by k) into v_set
      from jsonb_object_keys(p_borrow) k;
    execute format(
      'update public.ats_candidates c set %s, updated_at = now() '
      || 'from jsonb_populate_record(null::public.ats_candidates, $1) r '
      || 'where c.id = $2 returning to_jsonb(c)',
      v_set
    ) into v_candidate using p_borrow, p_survivor_id;
  end if;

  return jsonb_build_object(
    'deduped', v_deduped,
    'reassigned', v_reassigned,
    'copied', v_copied,
    'relinked', v_relinked,
    'candidate', v_candidate
  );
end;
$_$;

ALTER FUNCTION public.phx_merge_ats_candidates(p_survivor_id uuid, p_duplicate_id uuid, p_borrow jsonb, p_status_event_provenance text, p_comment_provenance text) OWNER TO postgres;

--
-- Name: FUNCTION phx_merge_ats_candidates(p_survivor_id uuid, p_duplicate_id uuid, p_borrow jsonb, p_status_event_provenance text, p_comment_provenance text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_merge_ats_candidates(p_survivor_id uuid, p_duplicate_id uuid, p_borrow jsonb, p_status_event_provenance text, p_comment_provenance text) IS 'Recruitment: every database write of a candidate merge in one transaction (candidate-merge-service.ts mergeCandidates). Locks both candidate rows FOR UPDATE lowest id first; refuses if either is gone. Returns per-table moved/blocked/copied counts and, when p_borrow wrote anything, the survivor row.';

--
-- Name: phx_merge_marketing_customers(uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_merge_marketing_customers(p_survivor_id uuid, p_retired_id uuid, p_reason text, p_actor_hr_id text, p_carry_evidence boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
declare
  s marketing_customers%rowtype;
  r marketing_customers%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
  v_carry boolean := coalesce(p_carry_evidence, false);
  v_requests uuid[];
  v_contacts uuid[];
  v_links uuid[];
  v_transfers uuid[];
  v_venues uuid[];
  v_earlier uuid[];
  v_links_left integer;
  v_links_reactivated uuid[];
  v_links_status_carried jsonb;
  v_links_switched_off uuid[];
  v_validation_carried text := null;
  v_note text;
  v_moved jsonb;
begin
  if p_survivor_id is null or p_retired_id is null then
    raise exception 'Both the customer that stays and the customer to retire must be named.';
  end if;
  if p_survivor_id = p_retired_id then
    raise exception 'A customer cannot be merged into itself.';
  end if;
  if v_reason = '' then
    raise exception 'A merge needs a written reason. It is the only record of why two rows were judged one customer.';
  end if;

  -- Both rows, locked in a fixed order so two merges touching the same pair cannot deadlock.
  perform 1 from marketing_customers where id in (p_survivor_id, p_retired_id) order by id for update;
  select * into s from marketing_customers where id = p_survivor_id;
  if not found then raise exception 'The customer that stays does not exist.'; end if;
  select * into r from marketing_customers where id = p_retired_id;
  if not found then raise exception 'The customer to retire does not exist.'; end if;

  if s.merged_into_customer_id is not null then
    raise exception '% was already merged into another customer, so it cannot stay.', s.display_name;
  end if;
  if r.merged_into_customer_id is not null then
    raise exception '% was already merged into another customer.', r.display_name;
  end if;
  if not s.active then raise exception '% is inactive, so it cannot stay.', s.display_name; end if;
  if not r.active then raise exception '% is already inactive.', r.display_name; end if;
  if s.validation_status = 'rejected' then
    raise exception '% was rejected, so it cannot be the customer that stays. Keep the other one.', s.display_name;
  end if;

  if s.line_id is distinct from r.line_id then
    raise exception 'These two are on different lines, and this screen merges only within one line.';
  end if;
  if s.customer_type is distinct from r.customer_type then
    raise exception 'These two are different kinds of customer (% and %).', s.customer_type, r.customer_type;
  end if;
  if s.area_id is distinct from r.area_id then
    raise exception 'These two are in different areas, and this screen merges only within one area.';
  end if;

  if exists (select 1 from marketing_customer_direct_order_transfers where customer_id = p_survivor_id and status = 'transferred')
     and exists (select 1 from marketing_customer_direct_order_transfers where customer_id = p_retired_id and status = 'transferred') then
    raise exception 'Both customers have a live Direct Orders transfer. Revert one of them first.';
  end if;

  if v_carry and not (
    r.evidence_status = 'complete'
    and r.captured_at is not null
    and r.evidence_photo_name is not null
    and s.evidence_status <> 'complete'
  ) then
    raise exception 'Evidence can be carried only from complete evidence onto a customer with none complete.';
  end if;

  with moved as (
    update marketing_requests set customer_id = p_survivor_id where customer_id = p_retired_id returning id
  ) select coalesce(array_agg(id), '{}') into v_requests from moved;

  with moved as (
    update marketing_customer_contacts set customer_id = p_survivor_id, updated_at = now()
    where customer_id = p_retired_id returning id
  ) select coalesce(array_agg(id), '{}') into v_contacts from moved;

  -- A link the survivor already holds cannot move (two unique indexes). If the survivor's copy is
  -- switched off and the retired row's is live, the live answer wins, before anything moves.
  with revived as (
    update marketing_customer_pharmacies kept
    set active = true, updated_at = now(), updated_by_hr_id = p_actor_hr_id
    from marketing_customer_pharmacies gone
    where kept.customer_id = p_survivor_id
      and gone.customer_id = p_retired_id
      and not kept.active
      and gone.active
      and (
        kept.distributor_code_id = gone.distributor_code_id
        or (kept.distributor_code_id is null and gone.distributor_code_id is null and kept.pharmacy_id = gone.pharmacy_id)
      )
    returning kept.id
  ) select coalesce(array_agg(id), '{}') into v_links_reactivated from revived;

  -- The survivor's copy of a shared link takes the retired row's standing when that is higher, under the
  -- customer's own rule: upward only, never over a rejection and never a rejection. The retired link's
  -- notes come too, because they say where the standing came from (a desk validation, a backfill).
  with pairs as (
    select
      kept.id as kept_id,
      kept.validation_status as from_status,
      gone.validation_status as to_status,
      kept.validation_notes as notes_before,
      gone.validation_notes as gone_notes
    from marketing_customer_pharmacies kept
    join marketing_customer_pharmacies gone
      on kept.distributor_code_id = gone.distributor_code_id
      or (kept.distributor_code_id is null and gone.distributor_code_id is null and kept.pharmacy_id = gone.pharmacy_id)
    where kept.customer_id = p_survivor_id
      and gone.customer_id = p_retired_id
      and gone.active
      and array_position(array['pending', 'system_validated', 'sfe_validated', 'admin_approved'], gone.validation_status)
        > array_position(array['pending', 'system_validated', 'sfe_validated', 'admin_approved'], kept.validation_status)
  ),
  carried as (
    update marketing_customer_pharmacies kept
    set validation_status = pairs.to_status,
        validation_notes = concat_ws(
          E'\n',
          nullif(btrim(pairs.notes_before), ''),
          format('Carried by the merge of %s (%s): %s.', r.display_name, r.customer_code, pairs.to_status),
          nullif(btrim(pairs.gone_notes), '')
        ),
        updated_at = now(),
        updated_by_hr_id = p_actor_hr_id
    from pairs
    where kept.id = pairs.kept_id
    returning pairs.kept_id, pairs.from_status, pairs.to_status, pairs.notes_before
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', kept_id, 'from', from_status, 'to', to_status, 'notesBefore', notes_before)), '[]'::jsonb)
  into v_links_status_carried
  from carried;

  with moved as (
    update marketing_customer_pharmacies link
    set customer_id = p_survivor_id, updated_at = now(), updated_by_hr_id = p_actor_hr_id
    where link.customer_id = p_retired_id
      and not exists (
        select 1 from marketing_customer_pharmacies kept
        where kept.customer_id = p_survivor_id
          and (
            kept.distributor_code_id = link.distributor_code_id
            or (kept.distributor_code_id is null and link.distributor_code_id is null and kept.pharmacy_id = link.pharmacy_id)
          )
      )
    returning link.id
  ) select coalesce(array_agg(id), '{}') into v_links from moved;

  select count(*) into v_links_left from marketing_customer_pharmacies where customer_id = p_retired_id;

  -- What is left is what the survivor already holds. Live, it would keep the retired customer on the
  -- Customer Database, the validation report, the vendor count and the daily field-capture nudge.
  with switched as (
    update marketing_customer_pharmacies
    set active = false, updated_at = now(), updated_by_hr_id = p_actor_hr_id
    where customer_id = p_retired_id and active
    returning id
  ) select coalesce(array_agg(id), '{}') into v_links_switched_off from switched;

  with moved as (
    update marketing_customer_direct_order_transfers set customer_id = p_survivor_id
    where customer_id = p_retired_id returning id
  ) select coalesce(array_agg(id), '{}') into v_transfers from moved;

  with moved as (
    update marketing_pharmacy_direct_order_venues set customer_id = p_survivor_id
    where customer_id = p_retired_id returning marketing_pharmacy_id
  ) select coalesce(array_agg(marketing_pharmacy_id), '{}') into v_venues from moved;

  -- A customer merged into the retired row earlier now points at the row that stays.
  with moved as (
    update marketing_customers set merged_into_customer_id = p_survivor_id
    where merged_into_customer_id = p_retired_id returning id
  ) select coalesce(array_agg(id), '{}') into v_earlier from moved;

  -- The validation, upward only and never over a rejection.
  if s.validation_status in ('pending', 'system_validated') and r.validation_status = 'sfe_validated' then
    v_validation_carried := 'sfe_validated';
  elsif s.validation_status = 'pending' and r.validation_status = 'system_validated'
        and (s.evidence_status = 'complete' or v_carry) then
    v_validation_carried := 'system_validated';
  end if;
  if v_validation_carried is not null then
    v_note := format(
      'Carried by the merge of %s (%s): %s, originally on %s by %s.',
      r.display_name, r.customer_code, r.validation_status,
      coalesce(to_char(r.validated_at at time zone 'Africa/Cairo', 'YYYY-MM-DD HH24:MI'), 'no recorded time'),
      coalesce(r.validated_by_hr_id, 'no recorded person')
    );
  end if;

  update marketing_customers set
    captured_address = case when v_carry then r.captured_address else captured_address end,
    captured_latitude = case when v_carry then r.captured_latitude else captured_latitude end,
    captured_longitude = case when v_carry then r.captured_longitude else captured_longitude end,
    captured_accuracy_meters = case when v_carry then r.captured_accuracy_meters else captured_accuracy_meters end,
    captured_at = case when v_carry then r.captured_at else captured_at end,
    evidence_photo_name = case when v_carry then r.evidence_photo_name else evidence_photo_name end,
    evidence_photo_captured_at = case when v_carry then r.evidence_photo_captured_at else evidence_photo_captured_at end,
    evidence_has_timestamp = case when v_carry then r.evidence_has_timestamp else evidence_has_timestamp end,
    evidence_status = case when v_carry then r.evidence_status else evidence_status end,
    extracted_area_name = case when v_carry then r.extracted_area_name else extracted_area_name end,
    extracted_governorate_name = case when v_carry then r.extracted_governorate_name else extracted_governorate_name end,
    validation_status = coalesce(v_validation_carried, validation_status),
    validated_by_hr_id = case
      when v_validation_carried = 'sfe_validated' then p_actor_hr_id
      when v_validation_carried = 'system_validated' then null
      else validated_by_hr_id
    end,
    validated_at = case when v_validation_carried is not null then now() else validated_at end,
    validation_notes = case
      when v_validation_carried is not null then concat_ws(E'\n', nullif(btrim(validation_notes), ''), v_note)
      else validation_notes
    end,
    owner_hr_id = coalesce(owner_hr_id, r.owner_hr_id),
    manager_hr_id = coalesce(manager_hr_id, r.manager_hr_id),
    region_name = coalesce(region_name, r.region_name),
    -- The five doctor-list columns travel together: a survivor with a matched doctor keeps its own.
    phoenix_crm_customer_id = coalesce(phoenix_crm_customer_id, r.phoenix_crm_customer_id),
    crm_list_status = case when phoenix_crm_customer_id is null and r.phoenix_crm_customer_id is not null then r.crm_list_status else coalesce(crm_list_status, r.crm_list_status) end,
    chosen_area_seat_id = case when phoenix_crm_customer_id is null and r.phoenix_crm_customer_id is not null then r.chosen_area_seat_id else coalesce(chosen_area_seat_id, r.chosen_area_seat_id) end,
    chosen_area_name = case when phoenix_crm_customer_id is null and r.phoenix_crm_customer_id is not null then r.chosen_area_name else coalesce(chosen_area_name, r.chosen_area_name) end,
    crm_list_source = case when phoenix_crm_customer_id is null and r.phoenix_crm_customer_id is not null then r.crm_list_source else coalesce(crm_list_source, r.crm_list_source) end,
    updated_at = now(),
    updated_by_hr_id = p_actor_hr_id
  where id = p_survivor_id;

  update marketing_customers set
    active = false,
    merged_into_customer_id = p_survivor_id,
    merged_at = now(),
    merged_by_hr_id = p_actor_hr_id,
    updated_at = now(),
    updated_by_hr_id = p_actor_hr_id
  where id = p_retired_id;

  v_moved := jsonb_build_object(
    'requests', to_jsonb(v_requests),
    'contacts', to_jsonb(v_contacts),
    'links', to_jsonb(v_links),
    'transfers', to_jsonb(v_transfers),
    'venues', to_jsonb(v_venues),
    'earlierMerges', to_jsonb(v_earlier),
    'linksLeftOnRetired', v_links_left,
    'linksReactivated', to_jsonb(v_links_reactivated),
    'linksStatusCarried', v_links_status_carried,
    'linksSwitchedOff', to_jsonb(v_links_switched_off),
    'validationCarried', v_validation_carried
  );

  insert into marketing_customer_merges (
    survivor_customer_id, retired_customer_id, reason, evidence_carried, moved,
    survivor_before, retired_before, merged_by_hr_id
  ) values (
    p_survivor_id, p_retired_id, v_reason, v_carry, v_moved,
    to_jsonb(s), to_jsonb(r), p_actor_hr_id
  );

  return jsonb_build_object(
    'requestsMoved', coalesce(array_length(v_requests, 1), 0),
    'contactsMoved', coalesce(array_length(v_contacts, 1), 0),
    'linksMoved', coalesce(array_length(v_links, 1), 0),
    'linksLeftOnRetired', v_links_left,
    'linksReactivated', coalesce(array_length(v_links_reactivated, 1), 0),
    'linksStatusCarried', jsonb_array_length(v_links_status_carried),
    'transfersMoved', coalesce(array_length(v_transfers, 1), 0),
    'venuesMoved', coalesce(array_length(v_venues, 1), 0),
    'validationCarried', v_validation_carried,
    'evidenceCarried', v_carry
  );
end;
$$;

ALTER FUNCTION public.phx_merge_marketing_customers(p_survivor_id uuid, p_retired_id uuid, p_reason text, p_actor_hr_id text, p_carry_evidence boolean) OWNER TO postgres;

