--
-- Name: phx_monthly_closing_direct(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_monthly_closing_direct(p_line text, p_period text) RETURNS TABLE(region_code text, area_code text, product_code text, sales_units numeric, sales_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select
    f.region_code,
    -- Same period rule as phx_closing_channel_breakdown, and for the same reason: a direct
    -- row's own area is honoured, EXCEPT in July 2026, whose placement belongs to the
    -- owner's overlay in july-2026-direct-orders.ts. Blank means "this month has no area",
    -- which is what the retired 2026-08 floor returned for every earlier month.
    case when p_period <> '2026-07'
         then coalesce(nullif(btrim(f.area_code), ''), '') else '' end as area_code,
    f.product_code,
    sum(f.total_qty)    as sales_units,
    sum(f.direct_value) as sales_value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b
    on b.id = f.batch_id and b.status = 'validated'
  where f.period = p_period
    and lower(btrim(f.official_line)) = lower(btrim(p_line))
    and f.is_direct
    and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  group by f.region_code,
           case when p_period <> '2026-07'
                then coalesce(nullif(btrim(f.area_code), ''), '') else '' end,
           f.product_code;
$$;

ALTER FUNCTION public.phx_monthly_closing_direct(p_line text, p_period text) OWNER TO postgres;

--
-- Name: phx_monthly_closing_matrix(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_monthly_closing_matrix(p_line text, p_period text) RETURNS TABLE(area_code text, product_code text, sales_units numeric, sales_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with base as (
    select f.area_code, f.product_code, f.total_qty, f.effective_units
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b
      on b.id = f.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
    where f.period = p_period
      and lower(btrim(f.official_line)) = lower(btrim(p_line))
      and not f.is_direct
      and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  ),
  period_price as (
    select d.product_code, public.phx_factory_price(d.product_code, p_period) as period_price
    from (select distinct base.product_code from base) d
  )
  select
    b.area_code,
    b.product_code,
    sum(b.total_qty)                                      as sales_units,
    sum(b.effective_units * coalesce(pp.period_price, 0)) as sales_value
  from base b
  left join period_price pp on pp.product_code = b.product_code
  group by b.area_code, b.product_code;
$$;

ALTER FUNCTION public.phx_monthly_closing_matrix(p_line text, p_period text) OWNER TO postgres;

