-- Name: phx_office_brick_share(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_office_brick_share(p_period text) RETURNS TABLE(product_code text, brick_id text, area_code text, region_code text, units numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    a.product_code,
    a.brick_id,
    a.area_code,
    a.region_code,
    sum(a.qty) as units
  from public.phx_sos_rows_attributed(p_period) a
  where a.distributor_code <> 'Office'
    and coalesce(a.is_direct, false) = false
    and coalesce(btrim(a.brick_id), '') <> ''
  group by a.product_code, a.brick_id, a.area_code, a.region_code;
$$;

