--
-- Name: phx_outstation_medical_trip_hr_id_canonical(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_outstation_medical_trip_hr_id_canonical() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_hr_id text;
begin
  if new.medical_trip_hr_id is null then
    return new;
  end if;
  if exists (select 1 from public.employees e where e.hr_id = new.medical_trip_hr_id) then
    return new;
  end if;

  select e.hr_id into v_hr_id
    from public.employees e
   where upper(e.hr_id) = upper(btrim(new.medical_trip_hr_id))
   limit 2;

  if found and (select count(*) from public.employees e
                 where upper(e.hr_id) = upper(btrim(new.medical_trip_hr_id))) = 1 then
    new.medical_trip_hr_id := v_hr_id;
  else
    -- Names nobody (or, never seen, two people at once): keep the name, drop the id.
    new.medical_trip_hr_id := null;
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.phx_outstation_medical_trip_hr_id_canonical() OWNER TO postgres;

--
-- Name: phx_page_timings_record(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_page_timings_record(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_written integer;
begin
  insert into public.page_timings as t (hour, path, kind, device, metric, count, p50_ms, p90_ms, max_ms)
  select r.hour, r.path, r.kind, r.device, r.metric, r.count, r.p50_ms, r.p90_ms, r.max_ms
  from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) as r(
    hour timestamptz, path text, kind text, device text, metric text,
    count integer, p50_ms integer, p90_ms integer, max_ms integer)
  where r.hour is not null and r.path is not null and r.kind is not null and r.device is not null
    and r.metric is not null and coalesce(r.count, 0) > 0
    and r.p50_ms is not null and r.p90_ms is not null and r.max_ms is not null
  on conflict (hour, path, kind, device, metric) do update set
    count = t.count + excluded.count,
    p50_ms = round((t.p50_ms::numeric * t.count + excluded.p50_ms::numeric * excluded.count) / (t.count + excluded.count))::integer,
    p90_ms = round((t.p90_ms::numeric * t.count + excluded.p90_ms::numeric * excluded.count) / (t.count + excluded.count))::integer,
    max_ms = greatest(t.max_ms, excluded.max_ms),
    updated_at = now();
  get diagnostics v_written = row_count;
  return v_written;
end;
$$;

ALTER FUNCTION public.phx_page_timings_record(p_rows jsonb) OWNER TO postgres;

--
-- Name: phx_page_timings_summary(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_page_timings_summary(p_since timestamp with time zone) RETURNS TABLE(path text, kind text, device text, metric text, count bigint, p50_ms integer, p90_ms integer, max_ms integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select t.path, t.kind, t.device, t.metric,
         sum(t.count)::bigint as count,
         round(sum(t.p50_ms::numeric * t.count) / sum(t.count))::integer as p50_ms,
         round(sum(t.p90_ms::numeric * t.count) / sum(t.count))::integer as p90_ms,
         max(t.max_ms) as max_ms
  from public.page_timings t
  where t.hour >= p_since
  group by t.path, t.kind, t.device, t.metric
$$;

ALTER FUNCTION public.phx_page_timings_summary(p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: phx_period_paid_by_automated_payroll(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_period_paid_by_automated_payroll(p_year integer, p_month integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.salary_batches b
    where b.year = p_year
      and b.month = p_month
      and (
        b.file_name like 'automated-payroll:%'
        or exists (
          select 1
          from public.automated_payroll_runs r
          where r.published_batch_id = b.id
        )
      )
  );
$$;

ALTER FUNCTION public.phx_period_paid_by_automated_payroll(p_year integer, p_month integer) OWNER TO postgres;

--
-- Name: FUNCTION phx_period_paid_by_automated_payroll(p_year integer, p_month integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_period_paid_by_automated_payroll(p_year integer, p_month integer) IS 'True when the salary batch for this month was produced by the Automated Payroll wizard. Used by phx_import_approved_expenses_to_payroll to refuse a month whose outstation trips the wizard already settled but never stamped.';

--
-- Name: phx_prevent_closed_salary_batch_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_prevent_closed_salary_batch_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(current_setting('request.phx_allow_salary_batch_delete', true), '') = 'on' then
    return old;
  end if;

  if old.status in ('approved', 'locked') or old.part1_paid_at is not null then
    raise exception 'Payroll batch cannot be deleted after Part 1 is paid or while status is %.', old.status using errcode = 'P0001';
  end if;

  return old;
end;
$$;

ALTER FUNCTION public.phx_prevent_closed_salary_batch_delete() OWNER TO postgres;

--
-- Name: phx_prevent_closed_salary_batch_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_prevent_closed_salary_batch_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.status in ('approved', 'locked') then
    if old.status = 'approved'
      and new.status = 'locked'
      and new.id is not distinct from old.id
      and new.month is not distinct from old.month
      and new.year is not distinct from old.year
      and new.file_name is not distinct from old.file_name
      and new.uploaded_by is not distinct from old.uploaded_by
      and new.approved_at is not distinct from old.approved_at
      and new.approved_by is not distinct from old.approved_by
      and new.part1_paid_at is not distinct from old.part1_paid_at
      and new.part1_paid_by is not distinct from old.part1_paid_by
      and new.part2_ready_at is not distinct from old.part2_ready_at
      and new.part2_ready_by is not distinct from old.part2_ready_by
      and new.rejected_reason is not distinct from old.rejected_reason
      and new.created_at is not distinct from old.created_at then
      return new;
    end if;

    raise exception 'Payroll batch cannot be updated while status is %.', old.status using errcode = 'P0001';
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_prevent_closed_salary_batch_update() OWNER TO postgres;

--
-- Name: phx_prevent_closed_salary_detail_mutation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_prevent_closed_salary_detail_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch_id uuid;
  v_batch_status text;
  v_part1_paid_at timestamptz;
begin
  if tg_op = 'DELETE' then
    v_batch_id := old.batch_id;
  else
    v_batch_id := new.batch_id;
  end if;

  select status, part1_paid_at
  into v_batch_status, v_part1_paid_at
  from public.salary_batches
  where id = v_batch_id;

  if v_batch_status in ('approved', 'locked') then
    raise exception 'Payroll batch cannot be changed while status is %.', v_batch_status using errcode = 'P0001';
  end if;

  if tg_table_name = 'salary_records' and v_part1_paid_at is not null then
    if tg_op <> 'UPDATE' then
      raise exception 'Salary records cannot be inserted or deleted after Part 1 is paid.' using errcode = 'P0001';
    end if;

    if new.batch_id is distinct from old.batch_id
      or new.hr_id is distinct from old.hr_id
      or new.full_name is distinct from old.full_name
      or new.name_ar is distinct from old.name_ar
      or new.job_title is distinct from old.job_title
      or new.line is distinct from old.line
      or new.area is distinct from old.area
      or new.hire_date is distinct from old.hire_date
      or new.base_salary is distinct from old.base_salary
      or new.gross_salary is distinct from old.gross_salary
      or new.net_salary is distinct from old.net_salary
      or new.first_part is distinct from old.first_part
      or new.extra_cost_of_living is distinct from old.extra_cost_of_living
      or new.fuel_allowance is distinct from old.fuel_allowance
      or new.social_insurance is distinct from old.social_insurance
      or new.employment_income_tax is distinct from old.employment_income_tax
      or new.governmental_deductions is distinct from old.governmental_deductions
      or new.payment_mode is distinct from old.payment_mode then
      raise exception 'Part 1 salary fields cannot be changed after Part 1 is paid.' using errcode = 'P0001';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_prevent_closed_salary_detail_mutation() OWNER TO postgres;

--
-- Name: phx_prevent_duplicate_salary_period(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_prevent_duplicate_salary_period() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if exists (
    select 1
    from public.salary_batches existing
    where existing.month = new.month
      and existing.year = new.year
      and existing.id is distinct from new.id
  ) then
    raise exception 'Payroll period %/% already has a batch.', new.month, new.year using errcode = '23505';
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_prevent_duplicate_salary_period() OWNER TO postgres;

--
-- Name: phx_prevent_employee_hr_id_update(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_prevent_employee_hr_id_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.hr_id is distinct from old.hr_id then
    raise exception 'HR_ID is immutable after employee creation. Use the governed HR_ID rename workflow.';
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_prevent_employee_hr_id_update() OWNER TO postgres;

--
-- Name: phx_prevent_terminal_employee_reactivation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_prevent_terminal_employee_reactivation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  old_status text := lower(trim(coalesce(old.employment_status, '')));
  new_status text := lower(trim(coalesce(new.employment_status, old.employment_status, '')));
  allow_override text := coalesce(current_setting('request.phx_allow_terminal_employee_reactivation', true), '');
begin
  if allow_override = 'on' then
    return new;
  end if;

  if old_status in ('resigned', 'terminated') and new_status not in ('resigned', 'terminated') then
    raise exception 'Terminal employees cannot be reactivated outside a governed workflow.'
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_prevent_terminal_employee_reactivation() OWNER TO postgres;

--
-- Name: phx_project_expense_payroll(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_project_expense_payroll(p_year integer, p_month integer) RETURNS TABLE(employee_hr_id text, employee_name text, claim_count bigint, payable_egp numeric, has_salary_record boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with agg as (
    select lower(c.employee_hr_id) as hr_key,
           min(c.employee_hr_id) as employee_hr_id,
           min(c.employee_name) as employee_name,
           count(*) as claim_count,
           round(sum(coalesce(c.approved_total, c.claimed_total)), 2) as payable_egp
    from public.expense_claims c
    where c.status = 'approved'
      and c.payout_year = p_year and c.payout_month = p_month
      and coalesce(c.evidence_gate_status, 'complete') in ('complete', 'grandfathered')
      and coalesce(c.workload_gate_status, 'complete') in ('complete', 'grandfathered', 'manual')
      and not exists (select 1 from public.expense_payroll_links l where l.claim_id = c.id)
    group by lower(c.employee_hr_id)
  )
  select a.employee_hr_id, a.employee_name, a.claim_count, a.payable_egp,
         exists (select 1 from public.salary_records r
                 join public.salary_batches b on b.id = r.batch_id
                 where b.year = p_year and b.month = p_month and lower(r.hr_id) = a.hr_key)
  from agg a order by 1;
$$;

ALTER FUNCTION public.phx_project_expense_payroll(p_year integer, p_month integer) OWNER TO postgres;

--
-- Name: FUNCTION phx_project_expense_payroll(p_year integer, p_month integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_project_expense_payroll(p_year integer, p_month integer) IS 'What outstation would contribute to a payout period, per employee. Read-only, needs no batch. has_salary_record=false is the B-175 failure mode: approved money with nowhere to land.';

--
-- Name: phx_prune_retention(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_prune_retention() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_batch integer;
  v_total integer;
  v_round integer;
  v_out jsonb := '{}'::jsonb;
begin
  -- audit_logs: 12 months
  v_total := 0; v_round := 0;
  loop
    delete from public.audit_logs where id in (
      select id from public.audit_logs where created_at < now() - interval '12 months' order by created_at limit 5000);
    get diagnostics v_batch = row_count;
    v_total := v_total + v_batch; v_round := v_round + 1;
    exit when v_batch < 5000 or v_round >= 100;
  end loop;
  v_out := v_out || jsonb_build_object('audit_logs', v_total);

  -- email_delivery_events: 6 months
  v_total := 0; v_round := 0;
  loop
    delete from public.email_delivery_events where id in (
      select id from public.email_delivery_events where occurred_at < now() - interval '6 months' order by occurred_at limit 5000);
    get diagnostics v_batch = row_count;
    v_total := v_total + v_batch; v_round := v_round + 1;
    exit when v_batch < 5000 or v_round >= 100;
  end loop;
  v_out := v_out || jsonb_build_object('email_delivery_events', v_total);

  -- attendance_raw_punches: 12 months
  v_total := 0; v_round := 0;
  loop
    delete from public.attendance_raw_punches where id in (
      select id from public.attendance_raw_punches where punch_time < now() - interval '12 months' order by punch_time limit 5000);
    get diagnostics v_batch = row_count;
    v_total := v_total + v_batch; v_round := v_round + 1;
    exit when v_batch < 5000 or v_round >= 100;
  end loop;
  v_out := v_out || jsonb_build_object('attendance_raw_punches', v_total);

  -- page_timings: 30 days (owner, 2026-11-01). A composite key, so the batch is picked by ctid.
  v_total := 0; v_round := 0;
  loop
    delete from public.page_timings where ctid in (
      select ctid from public.page_timings where hour < now() - interval '30 days' order by hour limit 5000);
    get diagnostics v_batch = row_count;
    v_total := v_total + v_batch; v_round := v_round + 1;
    exit when v_batch < 5000 or v_round >= 100;
  end loop;
  v_out := v_out || jsonb_build_object('page_timings', v_total);

  return v_out;
end;
$$;

ALTER FUNCTION public.phx_prune_retention() OWNER TO postgres;

--
-- Name: phx_prune_retention_run(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_prune_retention_run() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_out jsonb;
begin
  v_out := public.phx_prune_retention();

  perform public.phx_record_job_heartbeat('phoenix-data-retention', 'success', 'pruned: ' || v_out::text);

  return v_out;
end
$$;

ALTER FUNCTION public.phx_prune_retention_run() OWNER TO postgres;

--
-- Name: phx_publication_take_snapshot(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_publication_take_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_snap jsonb;
begin
  -- A caller that brought its own baseline keeps it. Only an unsnapshotted insert is filled.
  if new.snapshot_breakdown is not null or new.snapshot_taken_at is not null then
    return new;
  end if;

  -- Same shape the drift check compares against, value included (PR #3199).
  v_snap := public.phx_closing_publication_snapshot(new.line, new.period);

  new.snapshot_units      := (v_snap->>'units')::numeric;
  new.snapshot_cells      := (v_snap->>'cells')::integer;
  new.snapshot_breakdown  := v_snap->'breakdown';
  new.snapshot_taken_at   := now();

  return new;
end;
$$;

ALTER FUNCTION public.phx_publication_take_snapshot() OWNER TO postgres;

--
-- Name: FUNCTION phx_publication_take_snapshot(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_publication_take_snapshot() IS 'BEFORE INSERT on monthly_closing_publications: records units, cells and per-cell value as at the moment of publishing, so a later factory-price edit or re-attribution is detectable via phx_closing_publication_drift. Never fires on UPDATE - a re-publish must not restate the baseline. Added 2026-09-05.';

--
-- Name: daily_deductions_publications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.daily_deductions_publications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    range_start date NOT NULL,
    range_end date NOT NULL,
    status text DEFAULT 'published'::text NOT NULL,
    published_by text NOT NULL,
    published_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    superseded_by_publication_id uuid,
    employee_count integer DEFAULT 0 NOT NULL,
    line_count integer DEFAULT 0 NOT NULL,
    category_totals jsonb DEFAULT '{}'::jsonb NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT daily_deductions_publications_counts_non_negative CHECK (((employee_count >= 0) AND (line_count >= 0))),
    CONSTRAINT daily_deductions_publications_published_by_not_blank CHECK ((btrim(published_by) <> ''::text)),
    CONSTRAINT daily_deductions_publications_range_ordered CHECK ((range_start <= range_end)),
    CONSTRAINT daily_deductions_publications_status_check CHECK ((status = ANY (ARRAY['published'::text, 'superseded'::text])))
);

ALTER TABLE public.daily_deductions_publications OWNER TO postgres;

--
-- Name: TABLE daily_deductions_publications; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.daily_deductions_publications IS 'Daily Deductions module: one row per published running-tally snapshot over an operator-picked date range. A re-publish supersedes the prior active row; at most one active (status=published, superseded_at is null) row exists at a time. Governance/reporting only — no path here writes salary_records/salary_batches.';

--
-- Name: phx_publish_daily_deductions(date, date, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_publish_daily_deductions(p_range_start date, p_range_end date, p_lines jsonb, p_actor text, p_notes text DEFAULT NULL::text) RETURNS public.daily_deductions_publications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_publication public.daily_deductions_publications;
  v_actor text := btrim(coalesce(p_actor, ''));
begin
  if v_actor = '' then
    raise exception 'phx_publish_daily_deductions: an actor is required';
  end if;
  if p_range_start is null or p_range_end is null or p_range_start > p_range_end then
    raise exception 'phx_publish_daily_deductions: range_start must be <= range_end and neither may be null';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'phx_publish_daily_deductions: p_lines must be a JSON array';
  end if;

  perform pg_advisory_xact_lock(hashtext('daily_deductions_snapshot'));

  update public.daily_deductions_publications
     set status = 'superseded', superseded_at = now()
   where status = 'published' and superseded_at is null;

  insert into public.daily_deductions_publications (range_start, range_end, published_by, notes)
  values (p_range_start, p_range_end, v_actor, nullif(btrim(coalesce(p_notes, '')), ''))
  returning * into v_publication;

  update public.daily_deductions_publications
     set superseded_by_publication_id = v_publication.id
   where status = 'superseded' and superseded_at is not null
     and superseded_by_publication_id is null
     and id <> v_publication.id;

  insert into public.daily_deductions_lines (
    publication_id, category, employee_hr_id, employee_hr_id_compact, employee_name,
    unit, raw_days_count, days_count, amount, dates, source_system, reason, hr_note,
    released_at, released_by, range_start, range_end
  )
  select
    v_publication.id,
    line->>'category',
    line->>'employeeHrId',
    line->>'employeeHrIdCompact',
    nullif(line->>'employeeName', ''),
    coalesce(nullif(line->>'unit', ''), 'days'),
    coalesce((line->>'rawDaysCount')::numeric, 0),
    coalesce((line->>'daysCount')::numeric, 0),
    coalesce((line->>'amount')::numeric, 0),
    coalesce(line->'dates', '[]'::jsonb),
    coalesce(line->>'sourceSystem', ''),
    nullif(line->>'reason', ''),
    coalesce(line->>'hrNote', ''),
    now(),
    v_actor,
    p_range_start,
    p_range_end
  from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) as line;

  update public.daily_deductions_publications p
     set line_count = (
           select count(*)::int
           from public.daily_deductions_lines
           where publication_id = v_publication.id
         ),
         employee_count = (
           select count(distinct employee_hr_id_compact)::int
           from public.daily_deductions_lines
           where publication_id = v_publication.id
         ),
         category_totals = coalesce((
           select jsonb_object_agg(category, cat_total)
           from (
             select category, sum(amount) as cat_total
             from public.daily_deductions_lines
             where publication_id = v_publication.id
             group by category
           ) c
         ), '{}'::jsonb)
   where p.id = v_publication.id;

  select * into v_publication from public.daily_deductions_publications where id = v_publication.id;
  return v_publication;
end;
$$;

ALTER FUNCTION public.phx_publish_daily_deductions(p_range_start date, p_range_end date, p_lines jsonb, p_actor text, p_notes text) OWNER TO postgres;

--
-- Name: FUNCTION phx_publish_daily_deductions(p_range_start date, p_range_end date, p_lines jsonb, p_actor text, p_notes text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_publish_daily_deductions(p_range_start date, p_range_end date, p_lines jsonb, p_actor text, p_notes text) IS 'Daily Deductions module: atomically supersede any active snapshot and publish a fresh running-tally snapshot from app-computed lines. Counts/category_totals are derived from the inserted rows. SECURITY DEFINER, service_role only.';

--
-- Name: phx_publish_deductions(text, integer, integer, text, integer, integer, jsonb, text, jsonb, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_publish_deductions(p_month_key text, p_month integer, p_year integer, p_published_by text, p_candidate_count integer, p_employee_count integer, p_category_totals jsonb, p_notes text, p_lines jsonb, p_candidate_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_previous_id    uuid;
  v_publication_id uuid := gen_random_uuid();
  v_result         jsonb;
begin
  select id into v_previous_id
  from deductions_publications
  where month_key = p_month_key and status = 'published'
  for update;

  if v_previous_id is not null then
    update deductions_publications
    set status = 'superseded', superseded_at = now()
    where id = v_previous_id;
  end if;

  insert into deductions_publications (
    id, month, year, published_by, status,
    candidate_count, employee_count, category_totals, notes
  ) values (
    v_publication_id, p_month, p_year, p_published_by, 'published',
    p_candidate_count, p_employee_count, coalesce(p_category_totals, '{}'::jsonb),
    nullif(btrim(coalesce(p_notes, '')), '')
  );

  if v_previous_id is not null then
    update deductions_publications
    set superseded_by_publication_id = v_publication_id
    where id = v_previous_id;
  end if;

  insert into deductions_publication_lines (
    publication_id, candidate_id, decision_id, employee_hr_id, employee_hr_id_compact,
    employee_name, month_key, category, unit, original_value, applied_value,
    applied_amount, dates, reason, hr_note
  )
  select
    v_publication_id,
    (line->>'candidate_id')::uuid,
    (line->>'decision_id')::uuid,
    line->>'employee_hr_id',
    line->>'employee_hr_id_compact',
    nullif(line->>'employee_name', ''),
    line->>'month_key',
    line->>'category',
    line->>'unit',
    (line->>'original_value')::numeric,
    (line->>'applied_value')::numeric,
    (line->>'applied_amount')::numeric,
    coalesce(line->'dates', '[]'::jsonb),
    nullif(line->>'reason', ''),
    nullif(line->>'hr_note', '')
  from jsonb_array_elements(p_lines) as line;

  if array_length(p_candidate_ids, 1) > 0 then
    update deductions_candidates
    set locked_at = now()
    where id = any(p_candidate_ids) and locked_at is null;
  end if;

  insert into deductions_audit (publication_id, actor_hr_id, action, detail)
  values (
    v_publication_id, p_published_by, 'published',
    jsonb_build_object(
      'month_key', p_month_key,
      'candidate_count', p_candidate_count,
      'employee_count', p_employee_count,
      'superseded_publication_id', v_previous_id
    )
  );

  select jsonb_build_object(
    'id', id, 'month', month, 'year', year, 'month_key', month_key, 'status', status,
    'published_by', published_by, 'published_at', published_at,
    'candidate_count', candidate_count, 'employee_count', employee_count,
    'category_totals', category_totals, 'notes', notes, 'created_at', created_at
  ) into v_result
  from deductions_publications
  where id = v_publication_id;

  return v_result;
end;
$$;

ALTER FUNCTION public.phx_publish_deductions(p_month_key text, p_month integer, p_year integer, p_published_by text, p_candidate_count integer, p_employee_count integer, p_category_totals jsonb, p_notes text, p_lines jsonb, p_candidate_ids uuid[]) OWNER TO postgres;

--
-- Name: phx_purge_departed_personal_mailboxes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_purge_departed_personal_mailboxes() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  removed integer;
begin
  delete from public.personal_mailbox_connections c
  where not exists (
    select 1
    from public.app_auth_users u
    where u.is_active is true
      and (
        lower(trim(coalesce(u.hr_id, ''))) = lower(trim(c.owner_key))
        or lower(trim(coalesce(u.login_id, ''))) = lower(trim(c.owner_key))
      )
  );
  get diagnostics removed = row_count;
  return removed;
end;
$$;

ALTER FUNCTION public.phx_purge_departed_personal_mailboxes() OWNER TO postgres;

--
-- Name: phx_push_deduction(text, integer, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_push_deduction(p_month_key text, p_month integer, p_year integer, p_pushed_by text, p_line jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_publication_id uuid;
  v_candidate_id   uuid := (p_line->>'candidate_id')::uuid;
  v_new_line_id    uuid := gen_random_uuid();
  v_old_line_id    uuid;
  v_result         jsonb;
begin
  select id into v_publication_id
  from deductions_publications
  where month_key = p_month_key and status = 'published'
  for update;

  if v_publication_id is null then
    v_publication_id := gen_random_uuid();
    insert into deductions_publications (
      id, month, year, published_by, status,
      candidate_count, employee_count, category_totals, notes
    ) values (
      v_publication_id, p_month, p_year, p_pushed_by, 'published',
      0, 0, '{}'::jsonb, null
    );
  end if;

  update deductions_publication_lines
  set line_status = 'withdrawn'
  where publication_id = v_publication_id
    and candidate_id = v_candidate_id
    and line_status = 'active'
  returning id into v_old_line_id;

  insert into deductions_publication_lines (
    id, publication_id, candidate_id, decision_id, employee_hr_id, employee_hr_id_compact,
    employee_name, month_key, category, unit, original_value, applied_value, applied_amount,
    dates, reason, hr_note, line_status, pushed_by, pushed_at
  ) values (
    v_new_line_id, v_publication_id, v_candidate_id,
    nullif(p_line->>'decision_id', '')::uuid,
    p_line->>'employee_hr_id',
    p_line->>'employee_hr_id_compact',
    nullif(p_line->>'employee_name', ''),
    p_line->>'month_key',
    p_line->>'category',
    p_line->>'unit',
    (p_line->>'original_value')::numeric,
    (p_line->>'applied_value')::numeric,
    (p_line->>'applied_amount')::numeric,
    coalesce(p_line->'dates', '[]'::jsonb),
    nullif(p_line->>'reason', ''),
    nullif(p_line->>'hr_note', ''),
    'active', p_pushed_by, now()
  );

  if v_old_line_id is not null then
    update deductions_publication_lines
    set superseded_by_line_id = v_new_line_id
    where id = v_old_line_id;
  end if;

  update deductions_candidates
  set locked_at = now()
  where id = v_candidate_id and locked_at is null;

  with active as (
    select category, employee_hr_id_compact, applied_amount
    from deductions_publication_lines
    where publication_id = v_publication_id and line_status = 'active'
  ),
  by_cat as (
    select category, round(sum(applied_amount), 2) as amt
    from active
    group by category
  )
  update deductions_publications p set
    candidate_count = (select count(*) from active),
    employee_count  = (select count(distinct employee_hr_id_compact) from active),
    category_totals = coalesce((select jsonb_object_agg(category, amt) from by_cat), '{}'::jsonb)
  where p.id = v_publication_id;

  insert into deductions_audit (publication_id, candidate_id, actor_hr_id, action, detail)
  values (
    v_publication_id, v_candidate_id, p_pushed_by, 'pushed',
    jsonb_build_object(
      'line_id', v_new_line_id,
      'month_key', p_month_key,
      'category', p_line->>'category',
      'applied_amount', (p_line->>'applied_amount')::numeric
    )
  );

  select to_jsonb(l) into v_result
  from deductions_publication_lines l
  where l.id = v_new_line_id;

  return v_result;
end;
$$;

ALTER FUNCTION public.phx_push_deduction(p_month_key text, p_month integer, p_year integer, p_pushed_by text, p_line jsonb) OWNER TO postgres;

--
-- Name: phx_reassign_replacement_ownership(text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_reassign_replacement_ownership(p_previous_hr_id text, p_replacement_hr_id text, p_effective_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_previous_hr_id text := upper(trim(coalesce(p_previous_hr_id, '')));
  v_replacement_hr_id text := upper(trim(coalesce(p_replacement_hr_id, '')));
  v_effective_date date := coalesce(p_effective_date, (now() at time zone 'Africa/Cairo')::date);
  v_previous_status text;
  v_previous_line_id integer;
  v_previous_region text;
  v_replacement_name text;
  v_replacement_status text;
  v_replacement_line_id integer;
  v_replacement_region text;
  v_adopt_line_id integer;
  v_adopt_region text;
  v_count integer := 0;
  v_result jsonb := '{}'::jsonb;
begin
  if v_previous_hr_id = '' or v_replacement_hr_id = '' then
    return jsonb_build_object('applied', false, 'reason', 'missing_hr_id');
  end if;

  if v_previous_hr_id = v_replacement_hr_id then
    return jsonb_build_object('applied', false, 'reason', 'same_hr_id');
  end if;

  select lower(coalesce(employment_status, 'active')), line_id, lower(trim(coalesce(region_name, '')))
  into v_previous_status, v_previous_line_id, v_previous_region
  from public.employees
  where hr_id = v_previous_hr_id;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'previous_employee_not_found');
  end if;

  if v_previous_status not in ('resigned', 'terminated', 'inactive') then
    return jsonb_build_object('applied', false, 'reason', 'previous_employee_not_terminal');
  end if;

  select full_name, lower(coalesce(employment_status, 'active')), line_id, lower(trim(coalesce(region_name, '')))
  into v_replacement_name, v_replacement_status, v_replacement_line_id, v_replacement_region
  from public.employees
  where hr_id = v_replacement_hr_id
    and coalesce(payroll_eligible, true) is true
    and coalesce(organogram_visible, true) is true;

  if not found or v_replacement_status not in ('active', 'on_leave') then
    return jsonb_build_object('applied', false, 'reason', 'replacement_employee_not_active');
  end if;

  -- Unowned vacancies are adopted only when the replacement takes over the SAME line and region the
  -- replaced manager held; any difference (or a missing region) adopts nothing.
  if v_previous_line_id is not null
     and v_previous_line_id = v_replacement_line_id
     and v_previous_region <> ''
     and v_previous_region = v_replacement_region then
    v_adopt_line_id := v_previous_line_id;
    v_adopt_region := v_previous_region;
  end if;

  if to_regclass('public.app_auth_users') is not null then
    begin
      execute
        'update public.app_auth_users u
         set manager_hr_id = $2, updated_at = now()
         where u.is_active is true
           and (
             u.manager_hr_id = $1
             or exists (
               select 1
               from public.employees e
               where e.hr_id = u.hr_id
                 and e.pending_manager_replacement_for_hr_id = $1
             )
           )'
        using v_previous_hr_id, v_replacement_hr_id;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('app_auth_users_reassigned', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('app_auth_users_reassigned', null);
    end;
  end if;

  if to_regclass('public.user_access_profiles') is not null then
    begin
      execute
        'update public.user_access_profiles u
         set manager_hr_id = $2, updated_at = now()
         where u.is_active is true
           and (
             u.manager_hr_id = $1
             or exists (
               select 1
               from public.employees e
               where e.hr_id = u.hr_id
                 and e.pending_manager_replacement_for_hr_id = $1
             )
           )'
        using v_previous_hr_id, v_replacement_hr_id;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('user_access_profiles_reassigned', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('user_access_profiles_reassigned', null);
    end;
  end if;

  update public.employees
  set
    manager_hr_id = v_replacement_hr_id,
    pending_manager_replacement_for_hr_id = null,
    updated_at = now()
  where (
      manager_hr_id = v_previous_hr_id
      or pending_manager_replacement_for_hr_id = v_previous_hr_id
    )
    and lower(coalesce(employment_status, 'active')) in ('active', 'on_leave');

  get diagnostics v_count = row_count;
  v_result := v_result || jsonb_build_object('employees_reassigned', v_count);

  update public.position_vacancies
  set
    manager_hr_id = v_replacement_hr_id,
    manager_name = v_replacement_name,
    manager_replacement_for_hr_id = null,
    note = case
      when coalesce(note, '') ilike '%Replacement ownership engine:%' then note
      else concat_ws(
        E'\n',
        nullif(note, ''),
        'Replacement ownership engine: moved live vacancy manager from '
          || v_previous_hr_id || ' to ' || v_replacement_hr_id || ' on ' || (now() at time zone 'Africa/Cairo')::date::text || '.'
      )
    end,
    updated_at = now()
  where (
      manager_hr_id = v_previous_hr_id
      or manager_replacement_for_hr_id = v_previous_hr_id
    )
    and lower(coalesce(status, 'open')) = 'open';

  get diagnostics v_count = row_count;
  v_result := v_result || jsonb_build_object('vacancies_reassigned', v_count);

  -- A vacancy with NO manager is invisible to the update above (null = anything is never true).
  -- Adopt it when it sits on the replaced manager's line and region -- but never a vacancy that is
  -- itself a manager seat, which has no manager above it by design.
  if v_adopt_line_id is not null then
    update public.position_vacancies
    set
      manager_hr_id = v_replacement_hr_id,
      manager_name = v_replacement_name,
      note = case
        when coalesce(note, '') ilike '%Replacement ownership engine:%' then note
        else concat_ws(
          E'\n',
          nullif(note, ''),
          'Replacement ownership engine: gave the unowned live vacancy to ' || v_replacement_hr_id
            || ' on ' || (now() at time zone 'Africa/Cairo')::date::text || '.'
        )
      end,
      updated_at = now()
    where manager_hr_id is null
      and lower(coalesce(status, 'open')) = 'open'
      and line_id = v_adopt_line_id
      and lower(trim(coalesce(region_name, ''))) = v_adopt_region
      and coalesce(job_title, '') !~* '(manager|dsm)';

    get diagnostics v_count = row_count;
    v_result := v_result || jsonb_build_object('unowned_vacancies_adopted', v_count);
  end if;

  -- sales_records is FROZEN H1 history and is deliberately never touched here. See 20260814190000.
  v_result := v_result || jsonb_build_object('sales_records_reassigned', null);
  v_result := v_result || jsonb_build_object('sales_targets_reassigned', null);

  return jsonb_build_object(
    'applied', true,
    'previous_hr_id', v_previous_hr_id,
    'replacement_hr_id', v_replacement_hr_id,
    'effective_date', v_effective_date
  ) || v_result;
end;
$_$;

ALTER FUNCTION public.phx_reassign_replacement_ownership(p_previous_hr_id text, p_replacement_hr_id text, p_effective_date date) OWNER TO postgres;

--
-- Name: phx_rebuild_direct_order_sos_batch(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_rebuild_direct_order_sos_batch(p_period text, p_actor text DEFAULT 'system'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_batch_id     uuid;
  v_count        integer;
  v_total_qty    numeric;
  v_total_bonus  numeric;
  v_total_value  numeric;
  v_finalize     jsonb;
begin
  if p_period is null or p_period !~ '^\d{4}-\d{2}$' then
    raise exception 'phx_rebuild_direct_order_sos_batch: invalid period % (want YYYY-MM)', p_period;
  end if;

  -- Serialize concurrent rebuilds of this period. Re-entrant with the try-lock that
  -- phx_finalize_sos_batch takes on the same key within this same transaction.
  perform pg_advisory_xact_lock(hashtextextended('DirectReq:' || p_period, 0));

  -- The authoritative live set for this sales month: approved, not a reversal entry,
  -- not itself reversed (a reversed original is flipped to status='reversed').
  --
  -- Counted and summed over LINE ITEMS. A one-line request contributes exactly what it contributed
  -- before; a Lacto basket contributes both of its concentrations.
  select count(*),
         coalesce(sum(i.qty), 0),
         coalesce(sum(coalesce(i.bonus, 0)), 0),
         coalesce(sum(i.sales_value), 0)
    into v_count, v_total_qty, v_total_bonus, v_total_value
  from public.direct_order_requests r
  join public.direct_order_request_items i on i.request_id = r.id
  join public.direct_order_pharmacies ph on ph.id = r.pharmacy_id
  where r.status = 'approved'
    and r.reversal_of_request_id is null
    and r.sales_month = p_period;

  if v_count = 0 then
    -- Nothing live this month -> remove any prior DirectReq batch so the injected
    -- direct sales disappear (a reversal of the only order nets cleanly to zero).
    delete from public.source_of_sales_import_batches
     where distributor_code = 'DirectReq' and period = p_period;
    return jsonb_build_object('period', p_period, 'rowCount', 0, 'batchId', null, 'totalValue', 0);
  end if;

  insert into public.source_of_sales_import_batches
    (distributor_code, distributor_name, template_key, file_name, sheet_name, period,
     status, total_rows, importable_rows, failed_rows, warning_rows,
     total_qty, total_bonus_qty, total_value, uploaded_by)
  values
    ('DirectReq', 'Direct Order Requests', 'direct_orders',
     'direct-orders-' || p_period, 'DirectOrders', p_period,
     'pending', v_count, v_count, 0, 0,
     v_total_qty, v_total_bonus, v_total_value, coalesce(p_actor, 'system'))
  returning id into v_batch_id;

  insert into public.source_of_sales_import_rows
    (batch_id, row_number, distributor_code, invoice_period,
     region_code, region_name, area_code, area_name, brick_id,
     client_code, client_name, client_address,
     product_code, product_name, official_line,
     qty, bonus_qty, discount, value, is_direct, validation_state, raw_row)
  select
    v_batch_id,
    -- Ordered by request then line, so a basket's lines stay adjacent and the numbering is stable
    -- across rebuilds of the same period.
    row_number() over (order by r.created_at, r.id, i.line_no),
    'DirectReq',
    p_period,
    coalesce(ph.region_code, ''),
    coalesce(ph.region_code, ''),
    ph.area_code,
    ph.area_code,
    ph.brick_id,
    ph.phoenix_pharmacy_code,
    ph.pharmacy_name,
    ph.pharmacy_address,
    upper(btrim(i.product_code)),
    i.product_name,
    -- The LINE is a property of the request (the requester's line), not of the item. A basket is
    -- single-family and every family sits on one line once confidential products are excluded, so
    -- this stays the request's line exactly as before.
    r.line,
    i.qty,
    coalesce(i.bonus, 0),
    0,
    i.sales_value,
    true,
    'valid',
    jsonb_build_object(
      'source', 'direct_order_request',
      'requestId', r.id,
      'lineNo', i.line_no,
      'dealType', i.deal_type
    )
  from public.direct_order_requests r
  join public.direct_order_request_items i on i.request_id = r.id
  join public.direct_order_pharmacies ph on ph.id = r.pharmacy_id
  where r.status = 'approved'
    and r.reversal_of_request_id is null
    and r.sales_month = p_period;

  -- Supersede any prior DirectReq/period batch, validate this one, refresh the
  -- rollup, and reconcile raw rows == rollup grain (raises on any silent loss).
  v_finalize := public.phx_finalize_sos_batch(v_batch_id, 'DirectReq', p_period);

  -- Per REQUEST, not per line: a request has one batch id.
  update public.direct_order_requests r
     set sos_batch_id = v_batch_id, updated_at = now()
  from public.direct_order_pharmacies ph
  where ph.id = r.pharmacy_id
    and r.status = 'approved'
    and r.reversal_of_request_id is null
    and r.sales_month = p_period;

  return jsonb_build_object(
    'period', p_period,
    'rowCount', v_count,
    'batchId', v_batch_id,
    'totalValue', v_total_value,
    'finalize', v_finalize
  );
end $_$;

ALTER FUNCTION public.phx_rebuild_direct_order_sos_batch(p_period text, p_actor text) OWNER TO postgres;

--
-- Name: phx_rebuild_direct_order_weekly_batches(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_rebuild_direct_order_weekly_batches(p_period text, p_actor text DEFAULT 'system'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_month_start date;
  v_month_end   date;
  v_rows        integer := 0;
  v_batches     integer := 0;
  v_value       numeric := 0;
begin
  if p_period is null or p_period !~ '^\d{4}-\d{2}$' then
    raise exception 'phx_rebuild_direct_order_weekly_batches: invalid period % (want YYYY-MM)', p_period;
  end if;
  if p_period < '2026-08' then
    raise exception 'phx_rebuild_direct_order_weekly_batches: % came from uploaded Direct sheets; rebuilding it from orders would double count', p_period;
  end if;

  v_month_start := (p_period || '-01')::date;
  v_month_end   := (v_month_start + interval '1 month' - interval '1 day')::date;

  perform pg_advisory_xact_lock(hashtextextended('DirectWeekly:' || p_period, 0));

  delete from public.weekly_sales_batches
   where distributor_code = 'Direct'
     and template_key     = 'direct_orders_system'
     and cycle_month      = v_month_start;

  with live as (
    select r.id as request_id,
           least(greatest(
             coalesce(r.collection_date,
                      (r.decided_at at time zone 'Africa/Cairo')::date,
                      (r.created_at at time zone 'Africa/Cairo')::date),
             v_month_start), v_month_end)                              as placed_on,
           coalesce(ph.region_code, '')                                as region_code,
           -- The pharmacy's own area: the same column the Source-of-Sales rebuild writes, so Weekly
           -- and Monthly Closing credit the same area. Blank stays null (region-level, as before).
           nullif(upper(btrim(coalesce(ph.area_code, ''))), '')        as area_code,
           upper(btrim(i.product_code))                                as product_code,
           i.product_name,
           r.line                                                      as official_line,
           i.qty,
           coalesce(i.bonus, 0)                                        as bonus,
           i.sales_value,
           ph.pharmacy_name
      from public.direct_order_requests r
      join public.direct_order_request_items i on i.request_id = r.id
      join public.direct_order_pharmacies ph   on ph.id = r.pharmacy_id
     where r.status = 'approved'
       and r.reversal_of_request_id is null
       and r.sales_month = p_period
  ),
  wk as (
    select live.*,
           (case when extract(day from placed_on) <= 7  then 1
                 when extract(day from placed_on) <= 14 then 2
                 when extract(day from placed_on) <= 21 then 3
                 else 4 end)::smallint as week_number
      from live
  ),
  lines as (
    select week_number,
           (v_month_start + ((week_number - 1) * 7))::date              as week_start,
           region_code,
           area_code,
           product_code,
           official_line,
           min(product_name)                                            as product_name,
           sum(qty)                                                     as qty,
           sum(bonus)                                                   as bonus,
           sum(sales_value)                                             as line_value,
           jsonb_agg(distinct request_id)                               as request_ids,
           string_agg(distinct pharmacy_name, ', ' order by pharmacy_name) as pharmacy_names
      from wk
     group by week_number, region_code, area_code, product_code, official_line
  ),
  weeks as (
    select week_number, week_start, count(*)::integer as total_rows,
           sum(qty) as total_qty, sum(line_value) as total_value
      from lines
     group by week_number, week_start
  ),
  new_batches as (
    insert into public.weekly_sales_batches
      (distributor_code, distributor_name, template_key, file_name, sheet_name, week_start,
       status, total_rows, importable_rows, failed_rows, warning_rows,
       total_sales_qty, total_bonus_qty, total_sales_value, total_stock_qty,
       uploaded_by, total_return_qty, total_net_qty, column_contract_source,
       cycle_month, week_number)
    select 'Direct', 'Direct (Company)', 'direct_orders_system',
           'direct-orders-' || p_period || '-week-' || w.week_number, 'DirectOrders', w.week_start,
           'validated', w.total_rows, w.total_rows, 0, 0,
           w.total_qty, 0, w.total_value, 0,
           coalesce(p_actor, 'system'), 0, w.total_qty, 'code',
           v_month_start, w.week_number
      from weeks w
    returning id, week_number
  )
  insert into public.weekly_sales_rows
    (batch_id, row_number, week_start, distributor_code, distributor_name,
     region_code, region_name, branch_code, branch_name, item_code, product_code, product_name,
     official_line, sales_qty, bonus_qty, discount, sales_value, stock_qty,
     validation_state, validation_issues, raw_row, return_qty, net_qty,
     cycle_month, week_number, area_code)
  select b.id,
         (row_number() over (partition by l.week_number
                             order by l.region_code, l.area_code nulls first,
                                      l.product_code, l.official_line))::integer,
         l.week_start, 'Direct', 'Direct (Company)',
         l.region_code,
         coalesce((select sr.region_name from public.source_of_sales_regions sr
                    where sr.region_code = l.region_code limit 1), l.region_code),
         l.region_code,
         'Direct ' || chr(8211) || ' ' ||
           coalesce((select sr.region_name from public.source_of_sales_regions sr
                      where sr.region_code = l.region_code limit 1),
                    nullif(l.region_code, ''), '(no region)'),
         l.product_code, l.product_code, l.product_name,
         l.official_line, l.qty, 0, 0, l.line_value, 0,
         'valid', '[]'::jsonb,
         jsonb_build_object(
           'source', 'direct_order_request',
           'requestIds', l.request_ids,
           'pharmacyNames', l.pharmacy_names,
           'grossSalesQty', l.qty,
           'netQty', l.qty,
           'bonusUnitsNotCounted', l.bonus
         ),
         0, l.qty,
         v_month_start, l.week_number, l.area_code
    from lines l
    join new_batches b on b.week_number = l.week_number;

  get diagnostics v_rows = row_count;

  select count(*), coalesce(sum(total_sales_value), 0)
    into v_batches, v_value
    from public.weekly_sales_batches
   where distributor_code = 'Direct'
     and template_key     = 'direct_orders_system'
     and cycle_month      = v_month_start;

  return jsonb_build_object(
    'period', p_period, 'batches', v_batches, 'rowCount', v_rows, 'totalValue', v_value);
end $_$;

ALTER FUNCTION public.phx_rebuild_direct_order_weekly_batches(p_period text, p_actor text) OWNER TO postgres;

