--
-- Name: phx_record_direct_order_collection(uuid, numeric, date, numeric, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_record_direct_order_collection(p_order_id uuid, p_paid_amount numeric, p_payment_date date, p_expected_paid_amount numeric, p_expected_payment_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_order     public.direct_order_requests%rowtype;
  v_value     numeric(18, 2);
  v_paid      numeric(18, 2);
  v_offsets   numeric(18, 2);
  v_remaining numeric(18, 2);
begin
  -- The same lock every other writer of remaining_amount takes first (the offset RPCs and the
  -- service-fee settlement), so they queue behind each other instead of interleaving.
  select * into v_order from public.direct_order_requests where id = p_order_id for update;
  if not found then
    raise exception 'direct_order_collection_order_not_found';
  end if;

  -- Compare-and-set: the caller validated against the collection it READ. If anyone changed it
  -- since, this caller's decision was made on stale figures and it loses.
  if v_order.paid_amount is distinct from p_expected_paid_amount
     or v_order.payment_date is distinct from p_expected_payment_date then
    raise exception 'direct_order_collection_conflict: the collection on order % changed since it was read', p_order_id;
  end if;

  -- Read UNDER the lock: an offset recorded or removed a moment ago is counted here.
  select round(coalesce(sum(amount), 0)::numeric, 2) into v_offsets
    from public.direct_order_marketing_offsets
   where direct_order_id = p_order_id;

  v_value := round(coalesce(v_order.sales_value, 0)::numeric, 2);

  if p_paid_amount is null then
    -- Clearing: one explicit "nothing collected" state. The amount and the date reset together.
    if v_offsets <= 0 then
      v_remaining := null;
    else
      v_remaining := greatest(0, round(v_value - v_offsets, 2));
    end if;

    update public.direct_order_requests
       set paid_amount      = null,
           payment_date     = null,
           remaining_amount = v_remaining,
           updated_at       = now()
     where id = p_order_id;

    return jsonb_build_object(
      'paidAmount',              null,
      'paymentDate',             null,
      'remainingAmount',         v_remaining,
      'previousPaidAmount',      v_order.paid_amount,
      'previousPaymentDate',     v_order.payment_date,
      'previousRemainingAmount', v_order.remaining_amount
    );
  end if;

  if coalesce(v_order.status, '') <> 'approved' then
    raise exception 'direct_order_collection_not_approved';
  end if;
  if p_paid_amount <= 0 then
    raise exception 'direct_order_collection_amount_invalid';
  end if;
  if v_value <= 0 then
    raise exception 'direct_order_collection_no_value';
  end if;

  -- Round BEFORE comparing, exactly as collection-rules.ts does.
  v_paid := round(p_paid_amount, 2);
  if v_paid > v_value then
    raise exception 'direct_order_collection_exceeds_value';
  end if;
  if v_offsets > 0 and round(v_paid + v_offsets, 2) > v_value then
    raise exception 'direct_order_collection_exceeds_net_value';
  end if;
  if p_payment_date is null then
    raise exception 'direct_order_collection_date_required';
  end if;

  v_remaining := round(v_value - v_paid - v_offsets, 2);

  update public.direct_order_requests
     set paid_amount      = v_paid,
         payment_date     = p_payment_date,
         remaining_amount = v_remaining,
         updated_at       = now()
   where id = p_order_id;

  return jsonb_build_object(
    'paidAmount',              v_paid,
    'paymentDate',             p_payment_date,
    'remainingAmount',         v_remaining,
    'previousPaidAmount',      v_order.paid_amount,
    'previousPaymentDate',     v_order.payment_date,
    'previousRemainingAmount', v_order.remaining_amount
  );
end;
$$;

ALTER FUNCTION public.phx_record_direct_order_collection(p_order_id uuid, p_paid_amount numeric, p_payment_date date, p_expected_paid_amount numeric, p_expected_payment_date date) OWNER TO postgres;

--
-- Name: FUNCTION phx_record_direct_order_collection(p_order_id uuid, p_paid_amount numeric, p_payment_date date, p_expected_paid_amount numeric, p_expected_payment_date date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_record_direct_order_collection(p_order_id uuid, p_paid_amount numeric, p_payment_date date, p_expected_paid_amount numeric, p_expected_payment_date date) IS 'Records or clears (p_paid_amount null) the cash collected on a direct order, under the order row lock, compare-and-set against the paid amount and date the caller read. remaining_amount = sales_value - paid - offsets.';

--
-- Name: phx_record_direct_order_offset(uuid, uuid, numeric, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_record_direct_order_offset(p_request_id uuid, p_order_id uuid, p_amount numeric, p_note text, p_actor_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_order         public.direct_order_requests%rowtype;
  v_request       public.marketing_requests%rowtype;
  v_amount        numeric(14, 2) := round(coalesce(p_amount, 0)::numeric, 2);
  v_other_offsets numeric(14, 2);
  v_outstanding   numeric(14, 2);
  v_remaining     numeric(14, 2);
  v_offset_id     uuid;
begin
  if p_actor_hr_id is null or btrim(p_actor_hr_id) = '' then
    raise exception 'offset_actor_required';
  end if;
  if v_amount <= 0 then
    raise exception 'offset_amount_invalid';
  end if;

  -- Lock order first, request second, in every code path, so two callers cannot deadlock.
  select * into v_order from public.direct_order_requests where id = p_order_id for update;
  if not found then
    raise exception 'offset_order_not_found';
  end if;
  select * into v_request from public.marketing_requests where id = p_request_id for update;
  if not found then
    raise exception 'offset_request_not_found';
  end if;

  if lower(coalesce(v_order.status, '')) <> 'approved' then
    raise exception 'offset_order_not_approved';
  end if;
  -- Money-bearing statuses only: an offset stands in for a payout, so the request must be one the
  -- company has actually agreed to pay (the same set the Finance command centre counts).
  if lower(coalesce(v_request.status, '')) not in ('approved', 'active', 'roi_tracking', 'finance_hold') then
    raise exception 'offset_request_not_approved';
  end if;
  if exists (select 1 from public.direct_order_marketing_offsets where marketing_request_id = p_request_id) then
    raise exception 'offset_request_already_settled';
  end if;
  if v_amount > round(coalesce(v_request.estimated_cost, 0)::numeric, 2) then
    raise exception 'offset_exceeds_request_cost';
  end if;

  select coalesce(sum(amount), 0) into v_other_offsets
    from public.direct_order_marketing_offsets where direct_order_id = p_order_id;

  v_outstanding := round(coalesce(v_order.sales_value, 0)::numeric, 2)
                   - round(coalesce(v_order.paid_amount, 0)::numeric, 2)
                   - v_other_offsets;
  if v_amount > v_outstanding then
    raise exception 'offset_exceeds_outstanding';
  end if;

  insert into public.direct_order_marketing_offsets (direct_order_id, marketing_request_id, amount, note, created_by_hr_id)
  values (p_order_id, p_request_id, v_amount, nullif(btrim(coalesce(p_note, '')), ''), btrim(p_actor_hr_id))
  returning id into v_offset_id;

  v_remaining := v_outstanding - v_amount;
  update public.direct_order_requests
     set remaining_amount = v_remaining,
         updated_at = now()
   where id = p_order_id;

  return jsonb_build_object(
    'offsetId',        v_offset_id,
    'amount',          v_amount,
    'orderId',         p_order_id,
    'requestId',       p_request_id,
    'paidAmount',      v_order.paid_amount,
    'remainingBefore', v_outstanding,
    'remainingAfter',  v_remaining
  );
end;
$$;

ALTER FUNCTION public.phx_record_direct_order_offset(p_request_id uuid, p_order_id uuid, p_amount numeric, p_note text, p_actor_hr_id text) OWNER TO postgres;

--
-- Name: phx_record_factory_price_restatement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_record_factory_price_restatement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  begin
    with moved as (
      -- Only a real change to factory_price. Other columns on this table move for other reasons.
      select n.product_code,
             n.product_name,
             o.factory_price as old_price,
             n.factory_price as new_price
      from new_rows n
      join old_rows o on o.product_code = n.product_code
      where coalesce(n.factory_price, 0) is distinct from coalesce(o.factory_price, 0)
    ),
    impact as (
      select m.product_code, m.product_name, m.old_price, m.new_price,
             f.official_line, f.period,
             sum(f.effective_units) as units
      from moved m
      join public.source_of_sales_fact_rollup f
        on upper(btrim(f.product_code)) = upper(btrim(m.product_code))
      where not coalesce(f.is_direct, false)   -- a direct row's value is its source value
      group by 1, 2, 3, 4, 5, 6
      having sum(f.effective_units) <> 0
    ),
    totals as (
      -- Reach across EVERY period, settled or not, so a wide edit cannot report as a narrow one.
      select product_code,
             sum(units * (coalesce(new_price, 0) - coalesce(old_price, 0))) as all_periods_value_delta,
             count(*) as all_periods_cells
      from impact
      group by 1
    )
    insert into public.sales_audit_logs (action, actor_username, line, period, metadata)
    select 'factory_price_restated_settled_closing',
           current_user,
           i.official_line,
           i.period,
           jsonb_build_object(
             'product_code', i.product_code,
             'product_name', i.product_name,
             'old_factory_price', i.old_price,
             'new_factory_price', i.new_price,
             'units', round(i.units, 6),
             'value_delta', round(i.units * (coalesce(i.new_price, 0) - coalesce(i.old_price, 0)), 2),
             'closing_locked', exists (
               select 1 from public.monthly_closing_locks l
                where l.period = i.period
                  and l.normalized_line = lower(btrim(i.official_line))
                  and l.unlocked_at is null),
             'closing_published', exists (
               select 1 from public.monthly_closing_publications p
                where p.period = i.period
                  and p.normalized_line = lower(btrim(i.official_line))),
             'all_periods_value_delta', round(t.all_periods_value_delta, 2),
             'all_periods_cells', t.all_periods_cells,
             'note', 'Re-valuation at the current factory price is policy, not a fault. '
                     || 'This row records that a settled month changed value.'
           )
    from impact i
    join totals t on t.product_code = i.product_code
    where exists (
            select 1 from public.monthly_closing_locks l
             where l.period = i.period
               and l.normalized_line = lower(btrim(i.official_line))
               and l.unlocked_at is null)
       or exists (
            select 1 from public.monthly_closing_publications p
             where p.period = i.period
               and p.normalized_line = lower(btrim(i.official_line)));
  exception
    when others then
      -- The correction must stay possible: never turn a failed audit into a failed price fix.
      raise warning 'Could not record the factory-price restatement audit: % (%)', sqlerrm, sqlstate;
  end;

  return null;
end;
$$;

ALTER FUNCTION public.phx_record_factory_price_restatement() OWNER TO postgres;

--
-- Name: FUNCTION phx_record_factory_price_restatement(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_record_factory_price_restatement() IS 'AFTER UPDATE on source_of_sales_products: when factory_price moves, writes one sales_audit_logs row per actively-locked or published (line, period) it restates, with the all-periods total in metadata. Records, never refuses - re-valuation at the current price is the owner''s policy (2026-08-14); only its invisibility was the defect. Added 2026-09-05.';

--
-- Name: phx_record_job_heartbeat(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_record_job_heartbeat(p_slug text, p_outcome text, p_detail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
begin
  begin
    insert into public.job_heartbeats as h
      (slug, last_outcome, last_success_at, last_fail_at, last_detail, updated_at)
    values (
      p_slug,
      p_outcome,
      case when p_outcome = 'success' then v_now end,
      case when p_outcome = 'fail' then v_now end,
      left(p_detail, 2000),
      v_now
    )
    on conflict (slug) do update set
      last_outcome = excluded.last_outcome,
      -- Only the timestamp for THIS outcome moves. The gap between the two is the most useful thing
      -- the table records, and writing both would erase the last success on the first failure.
      last_success_at = case when excluded.last_outcome = 'success' then excluded.last_success_at else h.last_success_at end,
      last_fail_at = case when excluded.last_outcome = 'fail' then excluded.last_fail_at else h.last_fail_at end,
      last_detail = excluded.last_detail,
      updated_at = excluded.updated_at;
  exception when others then
    -- A register write that fails must not turn a working job into a failing one.
    raise warning 'job heartbeat write for % failed (non-fatal - the job''s own result is unaffected): % %',
      p_slug, sqlstate, sqlerrm;
  end;
end
$$;

ALTER FUNCTION public.phx_record_job_heartbeat(p_slug text, p_outcome text, p_detail text) OWNER TO postgres;

--
-- Name: phx_recovery_take_snapshots_run(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_recovery_take_snapshots_run() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_out jsonb;
begin
  v_out := recovery.take_snapshots();

  -- take_snapshots() catches per table and reports in `error`; see the header.
  if v_out ->> 'error' is not null then
    perform public.phx_record_job_heartbeat(
      'phoenix-recovery-snapshot', 'fail', 'take_snapshots() reported: ' || (v_out ->> 'error'));
  else
    perform public.phx_record_job_heartbeat('phoenix-recovery-snapshot', 'success', v_out::text);
  end if;

  return v_out;
end
$$;

ALTER FUNCTION public.phx_recovery_take_snapshots_run() OWNER TO postgres;

--
-- Name: phx_refresh_attribution_for_period(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_attribution_for_period(p_period text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    SET statement_timeout TO '120s'
    AS $_$
begin
  if p_period is null or p_period !~ '^\d{4}-\d{2}$' then
    raise exception 'phx_refresh_attribution_for_period: period must be YYYY-MM, got %', p_period;
  end if;
  perform au.f_refresh_monthly_attribution(p_period);
end;
