--
-- Name: phx_refresh_expense_claims(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_expense_claims() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_native_claims integer;
  v_payroll_links integer;
  v_claims        integer;
  v_imports       integer;
  v_flagged       integer;
begin
  select count(*) into v_native_claims
  from public.expense_claims
  where legacy_request_id is null and legacy_expense_id is null;

  if v_native_claims > 0 then
    raise exception
      'Refusing to rebuild: % claim(s) have no legacy link, so they were created natively. phx_refresh_expense_claims is a PHASE 2 tool and is unsafe once writes have cut over.',
      v_native_claims
      using errcode = 'P0001';
  end if;

  select count(*) into v_payroll_links from public.expense_payroll_links;

  if v_payroll_links > 0 then
    raise exception
      'Refusing to rebuild: % expense_payroll_links row(s) exist. This function DELETES that table and never rebuilds it, so rebuilding now would destroy payroll linkage that nothing can recover. Phase 4 has armed - retire this phase-2 refresh, or clear and re-link deliberately.',
      v_payroll_links
      using errcode = 'P0001';
  end if;

  -- `where true` is load-bearing: PostgREST's `authenticator` role preloads `safeupdate`, which
  -- refuses an unqualified DELETE. Removing it makes this function work by hand and fail hourly.
  delete from public.expense_claim_events where true;
  delete from public.expense_payroll_links where true;
  delete from public.expense_claims where true;
  delete from public.expense_imports where true;

  insert into public.expense_imports (file_name, uploaded_at, legacy_report_id)
  select e.source_file_name, min(r.created_at), (array_agg(r.id order by r.created_at))[1]
  from public.outstation_expenses e
  left join public.outstation_expense_reports r
         on r.id = e.report_id and r.file_name = e.source_file_name
  where e.source_file_name not like '%.workflow'
    and btrim(coalesce(e.source_file_name, '')) <> ''
  group by e.source_file_name;

  insert into public.expense_claims (
    claim_ref, employee_hr_id, employee_name, employee_role, line_name, area_name,
    source, status, transportation_type, expense_type, trip_start_date, trip_end_date,
    destination_label, distance_km, fuel_amount, allowance_amount, ticket_go_amount,
    ticket_return_amount, meeting_amount, other_amount, claimed_total, approved_total,
    decided_by_hr_id, decided_at, decision_reason, incurred_year, incurred_month,
    payout_year, payout_month, evidence_gate_status, workload_gate_status,
    legacy_request_id, legacy_expense_id, created_at)
  select 'OUTSTATION-' || r.id, r.employee_hr_id, r.employee_name, r.employee_role, r.line, r.area,
    case when adm.entity_id is not null then 'admin_manual' else 'wizard' end,
    case when r.status like 'rejected%' then 'rejected'
         when r.status like 'accepted%' or r.status = 'approved' then 'approved'
         else 'submitted' end,
    r.transportation_type, r.expense_type, r.trip_start_date, r.trip_end_date,
    coalesce(r.to_label, r.to_city, r.to_area), r.distance_from_residence_km,
    r.fuel_amount, r.allowance_amount, r.go_ticket_amount, r.return_ticket_amount,
    r.meeting_amount, r.other_amount,
    case when r.claimed_total_amount > 0 then r.claimed_total_amount else r.expected_total_amount end,
    -- Over-claim guard. Cast to the mirror's column type so this predicate sees exactly what
    -- `expense_claims_approved_total_range` will see. NULL here means "not representable", and the
    -- hold update further down records why.
    case when (r.status like 'accepted%' or r.status = 'approved')
          and coalesce(e.approved_amount, e.total)::numeric(12,2)
              <= (case when r.claimed_total_amount > 0 then r.claimed_total_amount
                       else r.expected_total_amount end)::numeric(12,2)
         then coalesce(e.approved_amount, e.total) end,
    case when (r.status like 'accepted%' or r.status = 'approved') then e.approved_by end,
    -- DECIDED-AT FALLBACK. `status` one line up is read from the REQUEST; this timestamp is read
    -- from the EXPENSE row, and the join to it below is a LEFT JOIN. An accepted request that never
    -- got an outstation_expenses row therefore produced status 'approved' with decided_at NULL,
    -- which `expense_claims_approved_needs_decision` rejects -- aborting the ENTIRE rebuild over one
    -- row, so the mirror went stale for everybody. Fall back to the request's own last-save time:
    -- the acceptance is real and must keep its status, but r.updated_at is when the request row was
    -- last written and is NOT a recorded decision. The hold block further down says so in words.
    case when (r.status like 'accepted%' or r.status = 'approved')
         then coalesce(e.approved_at, r.updated_at) end,
    nullif(btrim(coalesce(r.approval_reason, '')), ''),
    extract(year from r.trip_start_date)::int, extract(month from r.trip_start_date)::int,
    case when (r.status like 'accepted%' or r.status = 'approved') then e.payout_year end,
    case when (r.status like 'accepted%' or r.status = 'approved') then e.payout_month end,
    r.evidence_gate_status, r.workload_gate_status, r.id, e.id, r.created_at
  from public.outstation_expense_requests r
  left join public.outstation_expenses e on e.trip_id = 'OUTSTATION-' || r.id
  left join (
    select distinct entity_id from public.audit_logs
    where entity_type = 'outstation_request' and summary ilike 'Admin created%'
  ) adm on adm.entity_id = r.id::text;

  insert into public.expense_claims (
    claim_ref, employee_hr_id, employee_name, source, import_id, status,
    transportation_type, expense_type, trip_start_date, trip_end_date, destination_label,
    distance_km, fuel_amount, allowance_amount, meeting_amount, other_amount,
    claimed_total, approved_total, decided_by_hr_id, decided_at, decision_reason,
    incurred_year, incurred_month, payout_year, payout_month, legacy_expense_id, created_at)
  select e.trip_id, e.hr_id, coalesce(nullif(btrim(e.specialist), ''), e.hr_id),
    case when e.source_file_name like '%.workflow' then 'admin_manual' else 'import' end,
    imp.id,
    case when e.hr_approved then 'approved'
         when coalesce(e.status, '') ilike '%reject%' then 'rejected'
         else 'submitted' end,
    e.transportation_type, e.trip_type, e.expense_date::timestamptz,
    coalesce(e.to_date, e.expense_date)::timestamptz,
    coalesce(nullif(btrim(coalesce(e.to_location, '')), ''), e.location), e.km,
    e.travel_cost, e.allowance, e.meeting_amount, e.other_amount, e.total,
    -- The same over-claim guard as the request-derived insert above.
    case when e.hr_approved
          and coalesce(e.approved_amount, e.total)::numeric(12,2) <= e.total::numeric(12,2)
         then coalesce(e.approved_amount, e.total) end,
    case when e.hr_approved then e.approved_by end,
    -- The same decided-at fallback as the insert above, for the same constraint. No legacy row is
    -- in this state on production today (measured 2026-09-21: zero); this closes the hole before
    -- one is, rather than after a night of the mirror being down.
    case when e.hr_approved then coalesce(e.approved_at, e.created_at) end,
    nullif(btrim(coalesce(e.hr_comment, '')), ''),
    extract(year from e.expense_date)::int, extract(month from e.expense_date)::int,
    case when e.hr_approved then e.payout_year end,
    case when e.hr_approved then e.payout_month end,
    e.id, e.created_at
  from public.outstation_expenses e
  left join public.expense_imports imp
         on imp.file_name = e.source_file_name and e.source_file_name not like '%.workflow'
  where not exists (
    select 1 from public.outstation_expense_requests r where 'OUTSTATION-' || r.id = e.trip_id
  );

  update public.expense_claims c
  set data_quality_hold = true,
      data_quality_reason = 'Components do not sum to the claimed total (legacy). Owner deferred 2026-08-12.'
  where abs(c.claimed_total - (c.fuel_amount + c.allowance_amount + c.ticket_go_amount
          + c.ticket_return_amount + c.meeting_amount + c.other_amount)) > 0.005;

  update public.expense_claims c
  set data_quality_hold = true,
      data_quality_reason = coalesce(c.data_quality_reason || ' | ', '')
        || 'Legacy row was Rejected while still carrying an approver.'
  from public.outstation_expenses e
  where e.id = c.legacy_expense_id
    and coalesce(e.status, '') = 'Rejected'
    and (e.approved_at is not null or e.approved_by is not null);

  -- The over-claim hold. Names both amounts AND where each came from, because they live in
  -- different tables and a stale request header -- not an over-approval -- is what produced both
  -- known cases. A reason that misnames the cause sends the next reader after the wrong row.
  update public.expense_claims c
  set data_quality_hold = true,
      data_quality_reason = coalesce(c.data_quality_reason || ' | ', '')
        || 'Legacy approved amount '
        || to_char(coalesce(e.approved_amount, e.total)::numeric(12,2), 'FM999999990.00')
        || ' is above the recorded claim total '
        || to_char(c.claimed_total, 'FM999999990.00')
        || ', so no approved amount was mirrored. Those two figures come from different tables - '
        || 'the claim total from outstation_expense_requests, the approved amount from '
        || 'outstation_expenses - so check whether the expense components still sum to the '
        || 'recorded claim before treating this as an over-approval. Payroll reads the legacy row '
        || 'and is unaffected.'
  from public.outstation_expenses e
  where e.id = c.legacy_expense_id
    and c.status = 'approved'
    and c.approved_total is null
    and coalesce(e.approved_amount, e.total)::numeric(12,2) > c.claimed_total;

  -- The substituted-decision hold, request side. Same shape as the over-claim hold above and for
  -- the same reason: the status came from one table and the timestamp from another, and when the
  -- second had nothing to give we substituted rather than failing the whole rebuild. Say plainly
  -- which date is on the row, so nobody reads it as an approval time or as evidence of a decision.
  --
  -- WHICH CASE IT IS decides what the reader should DO, so the two are not worded alike. A trip
  -- whose evidence or workload gate is still pending has no outstation_expenses row BY DESIGN --
  -- the acceptance and the payroll hold are one action (`service.ts`: "the evidence gate is holding
  -- the trip out of payroll, so there is no row to carry either"), and outstation_expenses is what
  -- payroll pays from, so creating one by hand pays a trip the gate is deliberately holding. Only
  -- when the gates are CLEAR is a missing row a gap worth repairing; that is the 2026-09-07 shape.
  update public.expense_claims c
  set data_quality_hold = true,
      data_quality_reason = coalesce(c.data_quality_reason || ' | ', '')
        || case
             when coalesce(c.evidence_gate_status, '') like 'pending%'
               or coalesce(c.workload_gate_status, '') like 'pending%'
             then 'Accepted and HELD OUT OF PAYROLL in the same action: this trip''s evidence or '
               || 'workload gate has not landed yet, so no outstation_expenses row exists for it - '
               || 'that is the designed state of a held acceptance, not a missing row. The date '
               || 'shown is the request''s last save in outstation_expense_requests, NOT an '
               || 'approval time: the status comes from the request and the timestamp normally '
               || 'comes from the expense row, which is written when the gates clear. Do NOT create '
               || 'that row by hand - it is what payroll pays from, and the gate is holding this '
               || 'trip out on purpose. No approved amount was mirrored, and payroll reads the '
               || 'legacy rows, so pay is unaffected.'
             else 'Accepted with no recorded approval timestamp: the gates are clear, yet no '
               || 'outstation_expenses row exists for this request, so the decision date shown is '
               || 'the request''s last save in outstation_expense_requests, NOT an approval. The '
               || 'status comes from the request and the timestamp normally comes from the expense '
               || 'row. Repair the missing expense row rather than reading this date as a '
               || 'decision. No approved amount was mirrored, and payroll reads the legacy rows, '
               || 'so pay is unaffected.'
           end
  where c.status = 'approved'
    and c.legacy_request_id is not null
    and c.legacy_expense_id is null;

  -- The substituted-decision hold, legacy-expense side.
  update public.expense_claims c
  set data_quality_hold = true,
      data_quality_reason = coalesce(c.data_quality_reason || ' | ', '')
        || 'Legacy expense row is marked approved but carries no approval timestamp, so the date '
        || 'shown is when the row was created, not when it was approved.'
  from public.outstation_expenses e
  where e.id = c.legacy_expense_id
    and c.status = 'approved'
    and e.approved_at is null;

  insert into public.expense_claim_events (claim_id, actor_hr_id, event_type, message, metadata)
  select c.id, null, 'migrated',
    'Backfilled from ' || case
      when c.legacy_request_id is not null and c.legacy_expense_id is not null
        then 'outstation_expense_requests + outstation_expenses (merged)'
      when c.legacy_request_id is not null then 'outstation_expense_requests'
      else 'outstation_expenses' end,
    jsonb_strip_nulls(jsonb_build_object(
      'legacy_request_id', c.legacy_request_id, 'legacy_expense_id', c.legacy_expense_id,
      'source', c.source, 'status', c.status, 'claimed_total', c.claimed_total,
      'approved_total', c.approved_total,
      'component_sum', (c.fuel_amount + c.allowance_amount + c.ticket_go_amount
                        + c.ticket_return_amount + c.meeting_amount + c.other_amount),
      'data_quality_hold', case when c.data_quality_hold then true else null end,
      'data_quality_reason', c.data_quality_reason))
  from public.expense_claims c;

  select count(*) into v_claims  from public.expense_claims;
  select count(*) into v_imports from public.expense_imports;
  select count(*) into v_flagged from public.expense_claims where data_quality_hold;

  return jsonb_build_object('claims', v_claims, 'imports', v_imports,
                            'flagged', v_flagged, 'refreshed_at', now());
end;
$$;

ALTER FUNCTION public.phx_refresh_expense_claims() OWNER TO postgres;

--
-- Name: FUNCTION phx_refresh_expense_claims(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_refresh_expense_claims() IS 'PHASE 2 tool: rebuilds expense_claims/expense_imports/expense_claim_events from the legacy outstation tables. Idempotent. Refuses to run when any claim has no legacy link (writes have cut over) or when expense_payroll_links is non-empty (it deletes that table and cannot rebuild it). Deletes are WHERE-qualified because PostgREST''s authenticator role preloads safeupdate; statement_timeout is raised because that role caps statements at 8s.';

--
-- Name: phx_refresh_marketing_roi_facts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_marketing_roi_facts(p_batch_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_run_id uuid; v_lock_key bigint := abs(hashtext('marketing_roi_refresh')::bigint);
  v_affected_periods text[] := '{}'; v_affected_ids uuid[] := '{}'; v_source_batch_ids uuid[] := '{}';
  v_min_period text;
  v_cnt_requests bigint := 0; v_cnt_trends bigint := 0; v_cnt_lines bigint := 0; v_cnt_products bigint := 0;
  v_cnt_regions bigint := 0; v_cnt_distributors bigint := 0; v_cnt_customers bigint := 0; v_cnt_request_geo bigint := 0;
  -- The latest validated Source-of-Sales month: a window ending after it is still awaiting data.
  v_sales_as_of text := public.phx_marketing_roi_latest_validated_period();
begin
  if not pg_try_advisory_xact_lock(v_lock_key) then
    insert into marketing_roi_refresh_runs (triggered_by, trigger_batch_id, status, calculation_version)
    values (case when p_batch_id is not null then 'sos_import' else 'admin_manual' end, p_batch_id, 'skipped', '3')
    returning id into v_run_id;
    return jsonb_build_object('status', 'skipped', 'runId', v_run_id);
  end if;
  insert into marketing_roi_refresh_runs (triggered_by, trigger_batch_id, status, calculation_version)
  values (case when p_batch_id is not null then 'sos_import' else 'admin_manual' end, p_batch_id, 'running', '3')
  returning id into v_run_id;
  begin
    if p_batch_id is not null then
      select coalesce(array_agg(distinct invoice_period order by invoice_period), '{}'), min(invoice_period)
      into v_affected_periods, v_min_period
      from source_of_sales_import_rows where batch_id = p_batch_id and validation_state = 'valid';
    else
      -- The distinct valid invoice periods, read by SKIPPING from one period to the next on the partial
      -- index (`sos_smi_valid_period_line_region_idx`, leading column invoice_period) instead of
      -- aggregating all ~406,000 entries: 11 probes and ~50 pages against ~13,900 pages, which came
      -- from disk on the hourly run (about 5 s). Same array: ascending, one element per period, and a
      -- single NULL last when a valid row has no period, exactly as `array_agg(distinct ... order by)`.
      with recursive step(period) as (
        (select r.invoice_period from source_of_sales_import_rows r
          where r.validation_state = 'valid' and r.invoice_period is not null order by r.invoice_period limit 1)
        union all
        select (select r.invoice_period from source_of_sales_import_rows r
                 where r.validation_state = 'valid' and r.invoice_period > step.period order by r.invoice_period limit 1)
        from step where step.period is not null
      )
      select coalesce(array_agg(period order by period), '{}'::text[])
             || case when exists (select 1 from source_of_sales_import_rows r
                                   where r.validation_state = 'valid' and r.invoice_period is null)
                     then array[null::text] else '{}'::text[] end
        into v_affected_periods
      from step where period is not null;
    end if;
    -- An import rebuilds every request, as the hourly run does. The summary facts are deleted by whole
    -- pay month and customer facts claim each sale once across months, so rebuilding only the requests
    -- whose window overlaps the batch leaves the rest of those months out until the next full run.
    if p_batch_id is null or v_min_period is not null then
      select coalesce(array_agg(distinct id), '{}') into v_source_batch_ids from source_of_sales_import_batches where status = 'validated';
      select coalesce(array_agg(mr.id), '{}') into v_affected_ids from marketing_requests mr where mr.pay_date is not null;
    end if;
    if coalesce(array_length(v_affected_ids, 1), 0) = 0 then
      update marketing_roi_refresh_runs set status = 'success', finished_at = now(), affected_periods = v_affected_periods,
        row_counts = '{"requests":0,"trends":0,"lines":0,"products":0,"regions":0,"distributors":0,"customers":0,"requestGeo":0}'::jsonb
      where id = v_run_id;
      return jsonb_build_object('status','success','runId',v_run_id,'affectedRequests',0);
    end if;
    delete from marketing_roi_request_facts where request_id = any(v_affected_ids);
    delete from marketing_roi_request_geo_facts where request_id = any(v_affected_ids);
    delete from marketing_roi_trend_facts where period in (select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM') from marketing_requests where id = any(v_affected_ids));
    delete from marketing_roi_line_facts where period in (select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM') from marketing_requests where id = any(v_affected_ids));
    delete from marketing_roi_product_facts where period in (select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM') from marketing_requests where id = any(v_affected_ids));
    delete from marketing_roi_region_facts where period in (select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM') from marketing_requests where id = any(v_affected_ids));
    delete from marketing_roi_distributor_facts where period in (select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM') from marketing_requests where id = any(v_affected_ids));
    delete from marketing_roi_customer_facts where period in (select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM') from marketing_requests where id = any(v_affected_ids));
    with
    req_raw as materialized (
      select mr.id, mr.request_code, mr.pay_date, to_char(date_trunc('month', mr.pay_date), 'YYYY-MM') as pay_month,
        greatest(coalesce(mr.roi_duration_months,1),1) as roi_duration_months,
        coalesce(mr.estimated_cost, 0)::numeric as estimated_cost,
        coalesce(mr.required_roi_value, coalesce(mr.estimated_cost,0)*10)::numeric as required_roi_value,
        coalesce(mr.expected_roi_value, 0)::numeric as expected_roi_value, mr.customer_id,
        coalesce(l.name, 'Unassigned') as request_line, coalesce(mc.display_name, mr.customer_id::text) as customer_name,
        mc.customer_code, mr.status as request_status, coalesce(mr.track_direct_sales, false) as track_direct_sales
      from marketing_requests mr
      left join employees emp_req on upper(btrim(emp_req.hr_id)) = upper(btrim(mr.requester_hr_id))
      left join lines l on l.id = coalesce(mr.line_id, emp_req.line_id)
      left join marketing_customers mc on mc.id = mr.customer_id
      where mr.id = any(v_affected_ids)
    ),
    req_products_all as materialized (
      select distinct mrp.request_id, upper(btrim(sp.product_code)) as product_code,
        coalesce(sp.product_name, mp.product_name, mrp.product_name_snapshot) as product_name,
        coalesce(nullif(btrim(sp.line),''), nullif(btrim(mp.line),''), nullif(btrim(mrp.line_snapshot),''), 'Unassigned') as line_label,
        coalesce(mrp.expected_value, 0)::numeric as expected_value, coalesce(mrp.value_share, 0)::numeric as value_share
      from marketing_request_products mrp join marketing_products mp on mp.id = mrp.product_id
      left join source_of_sales_products sp on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
      where mrp.request_id in (select id from req_raw)
    ),
    req_targets_all as materialized (
      select distinct mrph.request_id, sd.distributor_code,
        coalesce(sd.distributor_name, md.display_name, sd.distributor_code) as distributor_name,
        sd.distributor_code as family_code, mpdc.normalized_pharmacy_code as customer_code,
        mph.id as pharmacy_id, coalesce(mph.display_name, mpdc.normalized_pharmacy_code) as pharmacy_name,
        cm.brick_id, cm.region_code, cm.area_code
      from marketing_request_pharmacies mrph
      join marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
      join marketing_distributors md on md.id = mpdc.distributor_id
      join marketing_pharmacies mph on mph.id = mrph.pharmacy_id
      join (select distinct marketing_normalized_name, parent_distributor_code from marketing_roi_distributor_rollup) ru on ru.marketing_normalized_name = md.normalized_name
      join source_of_sales_distributors sd on sd.distributor_code = ru.parent_distributor_code
      left join lateral (
        select cmx.brick_id, cmx.region_code, cmx.area_code from source_of_sales_customer_map cmx
        where lower(btrim(regexp_replace(coalesce(cmx.customer_code,''),'\s+',' ','g'))) = mpdc.normalized_pharmacy_code
          and cmx.active
          and (cmx.distributor_code = sd.distributor_code or exists (select 1 from marketing_roi_distributor_rollup rcm where rcm.parent_distributor_code = sd.distributor_code and rcm.sos_distributor_code = cmx.distributor_code))
        order by (cmx.distributor_code = sd.distributor_code) desc, cmx.region_code nulls last limit 1
      ) cm on true
      where mrph.request_id in (select id from req_raw) and coalesce(btrim(mpdc.normalized_pharmacy_code),'') <> '' and coalesce(mpdc.active, true)
    ),
    req as materialized (
      select rr.*, coalesce(nullif(btrim(rr.request_line),''), (select max(rpa.line_label) from req_products_all rpa where rpa.request_id = rr.id), 'Unassigned') as line_label
      from req_raw rr
    ),
    req_products as materialized (select rpa.* from req_products_all rpa join req on req.id = rpa.request_id),
    req_targets as materialized (select rta.* from req_targets_all rta join req on req.id = rta.request_id),
    product_rollups as (
      select request_id, count(*)::numeric as product_count, coalesce(sum(nullif(value_share,0)),0)::numeric as value_share_total, coalesce(sum(expected_value),0)::numeric as expected_total
      from req_products group by request_id
    ),
    request_product_allocations as materialized (
      select rp.request_id, rp.product_code, rp.product_name, rp.line_label, rp.expected_value, rp.value_share,
        case when pr.value_share_total > 0 then rp.value_share / pr.value_share_total
             when pr.expected_total > 0 then rp.expected_value / pr.expected_total
             when pr.product_count > 0 then 1 / pr.product_count else 0 end as share
      from req_products rp join product_rollups pr on pr.request_id = rp.request_id
    ),
    target_rollups as (select request_id, count(*)::numeric as target_count from req_targets group by request_id),
    request_target_allocations as materialized (
      select rt.*, case when tr.target_count > 0 then 1 / tr.target_count else 0 end as share
      from req_targets rt join target_rollups tr on tr.request_id = rt.request_id
    ),
    periods as materialized (
      select req.id, array_agg(to_char(g,'YYYY-MM')) as periods from req
      cross join lateral generate_series(date_trunc('month', req.pay_date), date_trunc('month', req.pay_date) + make_interval(months => req.roi_duration_months - 1), interval '1 month') as g
      group by req.id
    ),
    target_products as materialized (
      select distinct rt.request_id, rt.distributor_code, rt.customer_code, rt.brick_id, rpa.product_code
      from req_targets rt join request_product_allocations rpa on rpa.request_id = rt.request_id where rpa.product_code is not null
    ),
    exact_hits as materialized (
      select distinct tp.request_id, r.id::text as row_id, tp.distributor_code,
        coalesce(sd.distributor_name, tp.distributor_code) as distributor_name,
        lower(btrim(regexp_replace(coalesce(r.client_code,''),'\s+',' ','g'))) as client_code,
        nullif(btrim(r.client_name),'') as client_name, r.region_code,
        coalesce(sr.region_name, r.region_name, r.region_code) as region_name,
        nullif(btrim(r.brick_id),'') as brick_id, upper(btrim(r.product_code)) as product_code,
        coalesce(sp.product_name, r.product_name, r.product_code) as product_name,
        coalesce(nullif(btrim(sp.line),''), nullif(btrim(r.official_line),''), 'Unassigned') as line_label,
        coalesce(r.qty,0)::numeric as units,
        (case when coalesce(r.is_direct, false) then coalesce(r.value, 0) else coalesce(r.qty,0) * coalesce(public.phx_factory_price(r.product_code, r.invoice_period),0) end)::numeric as sales_value,
        'exact'::text as match_type
      from target_products tp
      join periods on periods.id = tp.request_id
      join marketing_roi_distributor_rollup rr_exact on rr_exact.parent_distributor_code = tp.distributor_code
      join source_of_sales_import_rows r on r.distributor_code = rr_exact.sos_distributor_code
       and lower(btrim(regexp_replace(coalesce(r.client_code,''),'\s+',' ','g'))) = tp.customer_code
       and upper(btrim(r.product_code)) = upper(btrim(tp.product_code))
       and r.invoice_period = any(periods.periods) and r.validation_state = 'valid'
      join source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
      join source_of_sales_products sp on upper(btrim(sp.product_code)) = upper(btrim(r.product_code))
      left join source_of_sales_distributors sd on sd.distributor_code = tp.distributor_code
      left join source_of_sales_regions sr on sr.region_code = r.region_code
    ),
    direct_hits as materialized (
      select distinct on (req.id, dor.id) req.id as request_id, dor.id::text as row_id, ru.parent_distributor_code as distributor_code,
        coalesce(parent_sd.distributor_name, ru.parent_distributor_code) as distributor_name,
        lower(btrim(regexp_replace(coalesce(dopdc.customer_code,''),'\s+',' ','g'))) as client_code,
        nullif(btrim(dph.pharmacy_name),'') as client_name, dopdc.mapped_region_code as region_code,
        coalesce(sr.region_name, dopdc.mapped_region_code) as region_name,
        nullif(btrim(dopdc.mapped_brick_id),'') as brick_id, upper(btrim(dor.product_code)) as product_code,
        coalesce(sp.product_name, dor.product_name, dor.product_code) as product_name,
        coalesce(nullif(btrim(sp.line),''), nullif(btrim(dor.line),''), 'Unassigned') as line_label,
        coalesce(dor.qty,0)::numeric as units, coalesce(dor.sales_value,0)::numeric as sales_value, 'direct'::text as match_type
      from req
      join periods on periods.id = req.id
      join req_products rp on rp.request_id = req.id
      join marketing_request_pharmacies mrph on mrph.request_id = req.id
      join marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id and coalesce(mpdc.active, true)
      join marketing_distributors md on md.id = mpdc.distributor_id
      join marketing_roi_distributor_rollup ru on ru.marketing_normalized_name = md.normalized_name
      left join source_of_sales_distributors parent_sd on parent_sd.distributor_code = ru.parent_distributor_code
      join direct_order_pharmacy_distributor_codes dopdc
        on lower(btrim(dopdc.distributor_code)) = lower(btrim(ru.sos_distributor_code))
       and lower(btrim(regexp_replace(coalesce(dopdc.customer_code,''),'\s+',' ','g'))) = lower(btrim(regexp_replace(coalesce(mpdc.normalized_pharmacy_code,''),'\s+',' ','g')))
      join direct_order_pharmacies dph on dph.id = dopdc.pharmacy_id
      join direct_order_requests dor on dor.pharmacy_id = dopdc.pharmacy_id and dor.status = 'approved' and dor.reversal_of_request_id is null
       and dor.sales_month = any(periods.periods) and upper(btrim(dor.product_code)) = upper(btrim(rp.product_code))
      left join source_of_sales_products sp on upper(btrim(sp.product_code)) = upper(btrim(dor.product_code))
      left join source_of_sales_regions sr on sr.region_code = dopdc.mapped_region_code
      where req.track_direct_sales = true
      order by req.id, dor.id, ru.parent_distributor_code, dopdc.distributor_code
    ),
    all_hits as materialized (select * from exact_hits union all select * from direct_hits),
    actuals as materialized (
      select request_id, coalesce(sum(sales_value),0)::numeric as actual_value, coalesce(sum(units),0)::numeric as actual_units,
        count(distinct row_id)::integer as sales_rows,
        count(distinct row_id) filter (where match_type='exact')::integer as exact_sales_rows,
        count(distinct row_id) filter (where match_type='fallback')::integer as fallback_sales_rows
      from all_hits group by request_id
    ),
    request_rows_base as materialized (
      select req.id, req.request_code, req.pay_month, req.roi_duration_months, req.estimated_cost, req.required_roi_value,
        req.expected_roi_value, req.customer_id, req.customer_name, req.customer_code, req.line_label, req.request_status,
        coalesce(a.actual_value, 0)::numeric as actual_sales_value, coalesce(a.actual_units, 0)::numeric as actual_sales_units,
        coalesce(a.sales_rows, 0)::integer as sales_rows, coalesce(a.exact_sales_rows, 0)::integer as exact_sales_rows,
        coalesce(a.fallback_sales_rows, 0)::integer as fallback_sales_rows,
        case when coalesce(a.sales_rows,0) = 0 then 'no_sales' else 'exact_customer' end as attribution_quality,
        -- Mirrors resolveRoiResultStatus: reaching the required value is on track at any time; a
        -- window still open past the validated month is awaiting data, never behind or no data.
        case
          when coalesce(a.sales_rows,0) > 0 and coalesce(a.actual_value,0) >= req.required_roi_value then 'on_track'
          when v_sales_as_of is null or req.pay_month is null
               or to_char(to_date(req.pay_month, 'YYYY-MM') + make_interval(months => greatest(coalesce(req.roi_duration_months, 1), 1) - 1), 'YYYY-MM') > v_sales_as_of
            then 'awaiting_data'
          when coalesce(a.sales_rows,0) > 0 then 'behind'
          else 'no_data'
        end as actual_roi_status,
        case when req.required_roi_value > 0 then coalesce(a.actual_value,0) / req.required_roi_value when coalesce(a.actual_value,0) > 0 then 1 else 0 end as actual_coverage_ratio,
        greatest(req.required_roi_value - coalesce(a.actual_value,0), 0)::numeric as coverage_gap,
        greatest(req.expected_roi_value - coalesce(a.actual_value,0), 0)::numeric as expected_gap
      from req left join actuals a on a.request_id = req.id
    ),
    request_rows as materialized (
      select rrb.*, case when rrb.actual_roi_status = 'on_track' then 'monitor' when rrb.attribution_quality = 'no_sales' then 'mapping_review'
        when rrb.actual_coverage_ratio < 0.5 and rrb.coverage_gap > 0 then 'high_risk_gap' else 'follow_up' end as recommended_action
      from request_rows_base rrb
    ),
    request_rows_approved as materialized (select * from request_rows where request_status in ('approved','active','roi_tracking','closed','finance_hold')),
    actuals_by_line as (select rr.pay_month, ah.line_label, sum(ah.sales_value)::numeric as actual_sales_value from all_hits ah join request_rows_approved rr on rr.id = ah.request_id group by rr.pay_month, ah.line_label),
    actuals_by_product as (select rr.pay_month, ah.product_code, sum(ah.sales_value)::numeric as actual_sales_value from all_hits ah join request_rows_approved rr on rr.id = ah.request_id group by rr.pay_month, ah.product_code),
    actuals_by_region as (select rr.pay_month, ah.region_code, ah.line_label, sum(ah.sales_value)::numeric as actual_sales_value from all_hits ah join request_rows_approved rr on rr.id = ah.request_id where ah.region_code is not null group by rr.pay_month, ah.region_code, ah.line_label),
    actuals_by_distributor as (select rr.pay_month, ah.distributor_code, ah.line_label, sum(ah.sales_value)::numeric as actual_sales_value from all_hits ah join request_rows_approved rr on rr.id = ah.request_id group by rr.pay_month, ah.distributor_code, ah.line_label),
    -- One customer's requests share one sales ledger: each sale counts once per customer, under the
    -- earliest pay month that claims it, so adding this customer's rows across months stays right.
    actuals_by_customer_dist as (
      select first_claim.pay_month, first_claim.customer_id, first_claim.distributor_code,
        sum(first_claim.sales_value)::numeric as actual_sales_value, sum(first_claim.units)::numeric as actual_sales_units,
        count(*) filter (where first_claim.match_type = 'exact')::integer as exact_sales_rows,
        count(*) filter (where first_claim.match_type = 'fallback')::integer as fallback_sales_rows
      from (
        select distinct on (rr.customer_id, ah.match_type, ah.row_id)
          rr.pay_month, rr.customer_id, ah.distributor_code, ah.match_type, ah.sales_value, ah.units
        from all_hits ah join request_rows_approved rr on rr.id = ah.request_id
        where rr.customer_id is not null
        order by rr.customer_id, ah.match_type, ah.row_id, rr.pay_month, ah.distributor_code
      ) first_claim
      group by first_claim.pay_month, first_claim.customer_id, first_claim.distributor_code
    ),
    actuals_by_request_geo as (select ah.request_id, ah.distributor_code, ah.region_code, sum(ah.sales_value)::numeric as actual_sales_value, sum(ah.units)::numeric as actual_sales_units, count(distinct ah.row_id)::integer as sales_rows from all_hits ah group by ah.request_id, ah.distributor_code, ah.region_code),
    ins_requests as (
      insert into marketing_roi_request_facts (refresh_run_id, request_id, request_code, pay_month, line_label, customer_id, customer_name, customer_code, estimated_cost, required_roi_value, expected_roi_value, actual_sales_value, actual_sales_units, sales_rows, exact_sales_rows, fallback_sales_rows, attribution_quality, actual_roi_status, actual_coverage_ratio, coverage_gap, expected_gap, recommended_action, source_batch_ids, source_periods, calculation_version, request_status)
      select v_run_id, rr.id, rr.request_code, rr.pay_month, rr.line_label, rr.customer_id, rr.customer_name, rr.customer_code, rr.estimated_cost, rr.required_roi_value, rr.expected_roi_value, rr.actual_sales_value, rr.actual_sales_units, rr.sales_rows, rr.exact_sales_rows, rr.fallback_sales_rows, rr.attribution_quality, rr.actual_roi_status, rr.actual_coverage_ratio, rr.coverage_gap, rr.expected_gap, rr.recommended_action, v_source_batch_ids, p.periods, '3', rr.request_status
      from request_rows rr left join periods p on p.id = rr.id returning 1
    ),
    ins_request_geo as (
      insert into marketing_roi_request_geo_facts (refresh_run_id, request_id, distributor_code, region_code, actual_sales_value, actual_sales_units, sales_rows, calculation_version)
      select v_run_id, abrg.request_id, abrg.distributor_code, abrg.region_code, abrg.actual_sales_value, abrg.actual_sales_units, abrg.sales_rows, '3' from actuals_by_request_geo abrg returning 1
    ),
    ins_trends as (
      insert into marketing_roi_trend_facts (refresh_run_id, period, request_count, marketing_cost, required_roi_value, expected_roi_value, actual_sales_value, coverage_gap, on_track_requests, behind_requests, no_data_requests, source_batch_ids, source_periods, calculation_version)
      select v_run_id, pay_month, count(*)::integer, sum(estimated_cost)::numeric, sum(required_roi_value)::numeric, sum(expected_roi_value)::numeric, sum(actual_sales_value)::numeric, sum(coverage_gap)::numeric, count(*) filter (where actual_roi_status='on_track')::integer, count(*) filter (where actual_roi_status='behind')::integer, count(*) filter (where actual_roi_status='no_data')::integer, v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved group by pay_month returning 1
    ),
    ins_lines as (
      insert into marketing_roi_line_facts (refresh_run_id, period, line_label, request_count, marketing_cost, required_roi_value, expected_roi_value, actual_sales_value, coverage_gap, on_track_requests, behind_requests, no_data_requests, source_batch_ids, source_periods, calculation_version)
      select v_run_id, rr.pay_month, rpa.line_label, count(distinct rr.id)::integer, sum(rr.estimated_cost * rpa.share)::numeric, sum(rr.required_roi_value * rpa.share)::numeric, sum(rr.expected_roi_value * rpa.share)::numeric, max(coalesce(abl.actual_sales_value, 0)), sum(rr.coverage_gap * rpa.share)::numeric, count(distinct rr.id) filter (where rr.actual_roi_status='on_track')::integer, count(distinct rr.id) filter (where rr.actual_roi_status='behind')::integer, count(distinct rr.id) filter (where rr.actual_roi_status='no_data')::integer, v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr join request_product_allocations rpa on rpa.request_id = rr.id left join actuals_by_line abl on abl.line_label = rpa.line_label and abl.pay_month = rr.pay_month group by rr.pay_month, rpa.line_label returning 1
    ),
    ins_products as (
      insert into marketing_roi_product_facts (refresh_run_id, period, product_code, product_name, line_label, request_count, marketing_cost, required_roi_value, expected_roi_value, actual_sales_value, actual_sales_units, coverage_gap, on_track_requests, behind_requests, no_data_requests, source_batch_ids, source_periods, calculation_version)
      select v_run_id, rr.pay_month, rpa.product_code, max(rpa.product_name), max(rpa.line_label), count(distinct rr.id)::integer, sum(rr.estimated_cost * rpa.share)::numeric, sum(rr.required_roi_value * rpa.share)::numeric, sum(rr.expected_roi_value * rpa.share)::numeric, max(coalesce(abp.actual_sales_value, 0)), coalesce(sum(rr.actual_sales_units * rpa.share), 0)::numeric, sum(rr.coverage_gap * rpa.share)::numeric, count(distinct rr.id) filter (where rr.actual_roi_status='on_track')::integer, count(distinct rr.id) filter (where rr.actual_roi_status='behind')::integer, count(distinct rr.id) filter (where rr.actual_roi_status='no_data')::integer, v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr join request_product_allocations rpa on rpa.request_id = rr.id left join actuals_by_product abp on abp.product_code = rpa.product_code and abp.pay_month = rr.pay_month where rpa.product_code is not null group by rr.pay_month, rpa.product_code returning 1
    ),
    ins_regions as (
      insert into marketing_roi_region_facts (refresh_run_id, period, region_code, region_name, line_label, request_count, marketing_cost, required_roi_value, expected_roi_value, actual_sales_value, coverage_gap, on_track_requests, behind_requests, no_data_requests, source_batch_ids, source_periods, calculation_version)
      select v_run_id, rr.pay_month, coalesce(rta.region_code, 'Unassigned'), max(coalesce(sr.region_name, rta.region_code, 'Unassigned')), rr.line_label, count(distinct rr.id)::integer, sum(rr.estimated_cost * rta.share)::numeric, sum(rr.required_roi_value * rta.share)::numeric, sum(rr.expected_roi_value * rta.share)::numeric, max(coalesce(abr.actual_sales_value, 0)), sum(rr.coverage_gap * rta.share)::numeric, count(distinct rr.id) filter (where rr.actual_roi_status='on_track')::integer, count(distinct rr.id) filter (where rr.actual_roi_status='behind')::integer, count(distinct rr.id) filter (where rr.actual_roi_status='no_data')::integer, v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr join request_target_allocations rta on rta.request_id = rr.id left join source_of_sales_regions sr on sr.region_code = rta.region_code left join actuals_by_region abr on abr.region_code = rta.region_code and abr.pay_month = rr.pay_month and abr.line_label = rr.line_label group by rr.pay_month, coalesce(rta.region_code, 'Unassigned'), rr.line_label returning 1
    ),
    ins_distributors as (
      insert into marketing_roi_distributor_facts (refresh_run_id, period, distributor_code, family_code, distributor_name, line_label, request_count, marketing_cost, required_roi_value, expected_roi_value, actual_sales_value, coverage_gap, on_track_requests, behind_requests, no_data_requests, source_batch_ids, source_periods, calculation_version)
      select v_run_id, rr.pay_month, rta.distributor_code, rta.family_code, max(rta.distributor_name), rr.line_label, count(distinct rr.id)::integer, sum(rr.estimated_cost * rta.share)::numeric, sum(rr.required_roi_value * rta.share)::numeric, sum(rr.expected_roi_value * rta.share)::numeric, max(coalesce(abd.actual_sales_value, 0)), sum(rr.coverage_gap * rta.share)::numeric, count(distinct rr.id) filter (where rr.actual_roi_status='on_track')::integer, count(distinct rr.id) filter (where rr.actual_roi_status='behind')::integer, count(distinct rr.id) filter (where rr.actual_roi_status='no_data')::integer, v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr join request_target_allocations rta on rta.request_id = rr.id left join actuals_by_distributor abd on abd.distributor_code = rta.distributor_code and abd.pay_month = rr.pay_month and abd.line_label = rr.line_label group by rr.pay_month, rta.distributor_code, rta.family_code, rr.line_label returning 1
    ),
    ins_customers as (
      insert into marketing_roi_customer_facts (refresh_run_id, period, customer_id, customer_code, customer_name, distributor_code, family_code, request_count, marketing_cost, required_roi_value, actual_sales_value, actual_sales_units, exact_sales_rows, fallback_sales_rows, attribution_quality, actual_roi_status, source_batch_ids, source_periods, calculation_version)
      select v_run_id, rr.pay_month, rr.customer_id, max(rr.customer_code), max(rr.customer_name), rta.distributor_code, max(rta.family_code), count(distinct rr.id)::integer, sum(rr.estimated_cost * rta.share)::numeric, sum(rr.required_roi_value * rta.share)::numeric, max(coalesce(acbd.actual_sales_value, 0)), max(coalesce(acbd.actual_sales_units, 0)), max(coalesce(acbd.exact_sales_rows, 0))::integer, max(coalesce(acbd.fallback_sales_rows, 0))::integer, case when bool_or(rr.attribution_quality = 'no_sales') then 'no_sales' else 'exact_customer' end, case when bool_or(rr.actual_roi_status = 'no_data') then 'no_data' when bool_or(rr.actual_roi_status = 'behind') then 'behind' when bool_or(rr.actual_roi_status = 'awaiting_data') then 'awaiting_data' else 'on_track' end, v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr join request_target_allocations rta on rta.request_id = rr.id left join actuals_by_customer_dist acbd on acbd.customer_id = rr.customer_id and acbd.distributor_code = rta.distributor_code and acbd.pay_month = rr.pay_month where rr.customer_id is not null group by rr.pay_month, rr.customer_id, rta.distributor_code returning 1
    )
    select (select count(*) from ins_requests)::bigint, (select count(*) from ins_trends)::bigint, (select count(*) from ins_lines)::bigint, (select count(*) from ins_products)::bigint, (select count(*) from ins_regions)::bigint, (select count(*) from ins_distributors)::bigint, (select count(*) from ins_customers)::bigint, (select count(*) from ins_request_geo)::bigint
    into v_cnt_requests, v_cnt_trends, v_cnt_lines, v_cnt_products, v_cnt_regions, v_cnt_distributors, v_cnt_customers, v_cnt_request_geo;
    update marketing_roi_refresh_runs set status = 'success', finished_at = now(), affected_periods = v_affected_periods,
      row_counts = jsonb_build_object('requests', v_cnt_requests, 'trends', v_cnt_trends, 'lines', v_cnt_lines, 'products', v_cnt_products, 'regions', v_cnt_regions, 'distributors', v_cnt_distributors, 'customers', v_cnt_customers, 'requestGeo', v_cnt_request_geo)
    where id = v_run_id;
    return jsonb_build_object('status', 'success', 'runId', v_run_id, 'affectedRequests', v_cnt_requests, 'rowCounts', jsonb_build_object('requests', v_cnt_requests, 'trends', v_cnt_trends, 'lines', v_cnt_lines, 'products', v_cnt_products, 'regions', v_cnt_regions, 'distributors', v_cnt_distributors, 'customers', v_cnt_customers, 'requestGeo', v_cnt_request_geo));
  exception when others then
    update marketing_roi_refresh_runs set status = 'failed', finished_at = now(), error = sqlerrm, affected_periods = v_affected_periods where id = v_run_id;
    raise;
  end;
end;
$$;

ALTER FUNCTION public.phx_refresh_marketing_roi_facts(p_batch_id uuid) OWNER TO postgres;

--
-- Name: phx_refresh_marketing_roi_facts_run(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_marketing_roi_facts_run() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_out jsonb;
begin
  v_out := public.phx_refresh_marketing_roi_facts();

  perform public.phx_record_job_heartbeat('phoenix-marketing-roi-refresh', 'success', v_out::text);

  return v_out;
end
$$;

ALTER FUNCTION public.phx_refresh_marketing_roi_facts_run() OWNER TO postgres;

--
-- Name: phx_refresh_monthly_attribution(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_monthly_attribution(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare r record;
begin
  for r in
    select distinct f.period
    from public.source_of_sales_fact_rollup f
    where f.batch_id = p_batch_id
  loop
    perform au.f_refresh_monthly_attribution(r.period);
  end loop;
end;
$$;

ALTER FUNCTION public.phx_refresh_monthly_attribution(p_batch_id uuid) OWNER TO postgres;

--
-- Name: phx_refresh_sos_channel_rollup(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_sos_channel_rollup(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtext('phx_refresh_sos_channel_rollup'), hashtext(p_batch_id::text));
  delete from public.source_of_sales_channel_customer_rollup where batch_id = p_batch_id;

  insert into public.source_of_sales_channel_customer_rollup
    (batch_id, line_key, official_line, period, distributor_code, client_code, client_key,
     client_name, folded_name, no_client_code, is_direct,
     units_all, value_all, rows_all, units_restricted, value_restricted, rows_restricted)
  with
  period_price as (
    select d.product_code, d.period,
           public.phx_factory_price(d.product_code, d.period) as period_price
    from (
      select distinct f.product_code, f.period
      from public.source_of_sales_fact_rollup f
      where f.batch_id = p_batch_id
    ) d
  ),
  names as (
    select distinct on (lower(btrim(d.official_line)), d.period, d.distributor_code, d.client_code)
      lower(btrim(d.official_line)) as line_key,
      d.period, d.distributor_code, d.client_code, d.client_name
    from public.source_of_sales_customer_directory_rollup d
    where d.batch_id = p_batch_id
    order by lower(btrim(d.official_line)), d.period, d.distributor_code, d.client_code,
             d.latest_row_created_at desc
  ),
  retail as (
    select
      f.batch_id,
      lower(btrim(f.official_line))                          as line_key,
      max(f.official_line)                                   as official_line,
      f.period,
      f.distributor_code,
      f.client_code,
      f.client_code                                          as client_key,
      coalesce(n.client_name, '')                            as client_name,
      public.phx_fold_customer_name(coalesce(n.client_name, '')) as folded_name,
      (f.client_code is null)                                as no_client_code,
      false                                                  as is_direct,
      sum(f.total_qty)                                       as units_all,
      sum(f.effective_units * coalesce(pp.period_price, 0))  as value_all,
      count(*)                                               as rows_all,
      coalesce(sum(f.total_qty)
        filter (where upper(btrim(coalesce(f.product_code, ''))) = any (array['LA003','LA004','SS001'])), 0) as units_restricted,
      coalesce(sum(f.effective_units * coalesce(pp.period_price, 0))
        filter (where upper(btrim(coalesce(f.product_code, ''))) = any (array['LA003','LA004','SS001'])), 0) as value_restricted,
      count(*)
        filter (where upper(btrim(coalesce(f.product_code, ''))) = any (array['LA003','LA004','SS001']))     as rows_restricted
    from public.source_of_sales_fact_rollup f
    join public.source_of_sales_import_batches b
      on b.id = f.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
    left join period_price pp
      on pp.product_code = f.product_code and pp.period = f.period
    left join names n
      on n.line_key = lower(btrim(f.official_line))
     and n.period = f.period
     and n.distributor_code = f.distributor_code
     and n.client_code = f.client_code
    where f.batch_id = p_batch_id
      and not coalesce(f.is_direct, false)
    group by f.batch_id, lower(btrim(f.official_line)), f.period, f.distributor_code,
             f.client_code, coalesce(n.client_name, '')
  ),
  direct as (
    select
      r.batch_id,
      lower(btrim(r.official_line))                          as line_key,
      max(r.official_line)                                   as official_line,
      r.invoice_period                                       as period,
      null::text                                             as distributor_code,
      null::text                                             as client_code,
      case when btrim(coalesce(r.client_name, '')) = '' then null
           else 'name:' || public.phx_fold_customer_name(r.client_name) end as client_key,
      btrim(coalesce(r.client_name, ''))                     as client_name,
      public.phx_fold_customer_name(btrim(coalesce(r.client_name, ''))) as folded_name,
      false                                                  as no_client_code,
      true                                                   as is_direct,
      sum(r.qty)                                             as units_all,
      sum(r.value)                                           as value_all,
      count(*)                                               as rows_all,
      coalesce(sum(r.qty)
        filter (where upper(btrim(coalesce(r.product_code, ''))) = any (array['LA003','LA004','SS001'])), 0) as units_restricted,
      coalesce(sum(r.value)
        filter (where upper(btrim(coalesce(r.product_code, ''))) = any (array['LA003','LA004','SS001'])), 0) as value_restricted,
      count(*)
        filter (where upper(btrim(coalesce(r.product_code, ''))) = any (array['LA003','LA004','SS001']))     as rows_restricted
    from public.source_of_sales_import_rows r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated'
    where r.batch_id = p_batch_id
      and coalesce(r.is_direct, false)
      and r.validation_state = 'valid'
    group by r.batch_id, lower(btrim(r.official_line)), r.invoice_period,
      case when btrim(coalesce(r.client_name, '')) = '' then null
           else 'name:' || public.phx_fold_customer_name(r.client_name) end,
      btrim(coalesce(r.client_name, ''))
  )
  select batch_id, line_key, official_line, period, distributor_code, client_code, client_key,
         client_name, folded_name, no_client_code, is_direct,
         units_all, value_all, rows_all, units_restricted, value_restricted, rows_restricted
  from retail
  union all
  select batch_id, line_key, official_line, period, distributor_code, client_code, client_key,
         client_name, folded_name, no_client_code, is_direct,
         units_all, value_all, rows_all, units_restricted, value_restricted, rows_restricted
  from direct;
end;
$$;

ALTER FUNCTION public.phx_refresh_sos_channel_rollup(p_batch_id uuid) OWNER TO postgres;

--
-- Name: phx_refresh_sos_customer_directory_rollup(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_sos_customer_directory_rollup(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
begin
  delete from public.source_of_sales_customer_directory_rollup
  where batch_id = p_batch_id;

  insert into public.source_of_sales_customer_directory_rollup (
    batch_id,
    period,
    distributor_code,
    client_code,
    product_code,
    is_direct,
    client_name,
    client_address,
    brick_id,
    area_code,
    region_code,
    official_line,
    latest_row_created_at,
    effective_units,
    total_qty,
    direct_value,
    row_count
  )
  select
    r.batch_id,
    coalesce(nullif(btrim(r.invoice_period), ''), '') as period,
    coalesce(nullif(btrim(r.distributor_code), ''), b.distributor_code, '') as distributor_code,
    nullif(btrim(r.client_code), '') as client_code,
    coalesce(nullif(upper(btrim(r.product_code)), ''), '') as product_code,
    coalesce(r.is_direct, false) as is_direct,
    (array_agg(nullif(btrim(r.client_name), '') order by (nullif(btrim(r.client_name), '') is null), r.created_at desc nulls last))[1] as client_name,
    (array_agg(nullif(btrim(r.client_address), '') order by (nullif(btrim(r.client_address), '') is null), r.created_at desc nulls last))[1] as client_address,
    (array_agg(nullif(btrim(r.brick_id), '') order by (nullif(btrim(r.brick_id), '') is null), r.created_at desc nulls last))[1] as brick_id,
    (array_agg(nullif(btrim(r.area_code), '') order by (nullif(btrim(r.area_code), '') is null), r.created_at desc nulls last))[1] as area_code,
    (array_agg(nullif(btrim(r.region_code), '') order by (nullif(btrim(r.region_code), '') is null), r.created_at desc nulls last))[1] as region_code,
    (array_agg(nullif(btrim(r.official_line), '') order by (nullif(btrim(r.official_line), '') is null), r.created_at desc nulls last))[1] as official_line,
    max(coalesce(r.created_at, b.created_at, 'epoch'::timestamptz)) as latest_row_created_at,
    sum(coalesce(r.qty, 0)) as effective_units,
    sum(coalesce(r.qty, 0)) as total_qty,
    sum(case when coalesce(r.is_direct, false) then coalesce(r.value, 0) else 0 end) as direct_value,
    count(*)::integer as row_count
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b
    on b.id = r.batch_id
   and b.status = 'validated'
  where r.batch_id = p_batch_id
    and nullif(btrim(r.client_code), '') is not null
    and coalesce(r.validation_state, 'valid') <> 'failed'
  group by
    r.batch_id,
    coalesce(nullif(btrim(r.invoice_period), ''), ''),
    coalesce(nullif(btrim(r.distributor_code), ''), b.distributor_code, ''),
    nullif(btrim(r.client_code), ''),
    coalesce(nullif(upper(btrim(r.product_code)), ''), ''),
    coalesce(r.is_direct, false);
end;
$$;

ALTER FUNCTION public.phx_refresh_sos_customer_directory_rollup(p_batch_id uuid) OWNER TO postgres;

--
-- Name: phx_refresh_sos_distributor_product_rollup(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_sos_distributor_product_rollup(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtext('phx_refresh_sos_distributor_product_rollup'), hashtext(p_batch_id::text));
  delete from public.source_of_sales_distributor_product_rollup where batch_id = p_batch_id;

  insert into public.source_of_sales_distributor_product_rollup
    (batch_id, line_key, official_line, period, distributor_code, region_code, area_code,
     product_code, product_name, units_qty, eff_units)
  select
    f.batch_id,
    lower(btrim(f.official_line))   as line_key,
    max(f.official_line)            as official_line,
    f.period,
    f.distributor_code,
    f.region_code,
    f.area_code,
    f.product_code,
    max(f.product_name)             as product_name,
    sum(f.total_qty)                as units_qty,
    sum(f.effective_units)          as eff_units
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b
    on b.id = f.batch_id and b.status = 'validated'
  where f.batch_id = p_batch_id
    and not coalesce(f.is_direct, false)
    and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  group by f.batch_id, lower(btrim(f.official_line)), f.period,
           f.distributor_code, f.region_code, f.area_code, f.product_code;
end;
$$;

ALTER FUNCTION public.phx_refresh_sos_distributor_product_rollup(p_batch_id uuid) OWNER TO postgres;

--
-- Name: phx_refresh_sos_fact_rollup(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_sos_fact_rollup(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
declare
  v_period text;
  v_drift_rows bigint;
  v_drift_value numeric;
begin
  perform pg_advisory_xact_lock(hashtext('phx_refresh_sos_fact_rollup'), hashtext(p_batch_id::text));
  select b.period into v_period
  from public.source_of_sales_import_batches b
  where b.id = p_batch_id;

  delete from public.source_of_sales_fact_rollup where batch_id = p_batch_id;
  delete from public.source_of_sales_customer_presence_rollup where batch_id = p_batch_id;

  insert into public.source_of_sales_fact_rollup
    (batch_id, period, distributor_code, official_line, region_code, area_code, brick_id,
     client_code, product_code, product_name, is_direct,
     effective_units, total_qty, total_bonus_qty, direct_value, row_count)
  select
    a.batch_id,
    v_period,
    a.distributor_code,
    a.official_line,
    a.region_code,
    a.area_code,
    a.brick_id,
    a.client_code,
    a.product_code,
    max(a.product_name),
    a.is_direct,
    sum(a.qty),
    sum(a.qty),
    sum(coalesce(a.bonus_qty, 0)),
    sum(case when a.is_direct then a.value else 0 end),
    count(*)
  from public.phx_sos_rows_attributed(v_period) a
  where a.batch_id = p_batch_id
    and coalesce(a.validation_state, 'valid') <> 'failed'
  group by
    a.batch_id, a.distributor_code, a.official_line, a.region_code,
    a.area_code, a.brick_id, a.client_code, a.product_code, a.is_direct;

  insert into public.source_of_sales_customer_presence_rollup
    (batch_id, period, client_code, official_line, region_code, present_any, present_nonexcluded)
  select
    r.batch_id,
    b.period,
    r.client_code,
    coalesce(r.official_line, ''),
    coalesce(r.region_code, ''),
    true,
    bool_or(coalesce(upper(btrim(r.product_code)) <> all (array['LA003','LA004','SS001']), false))
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b
    on b.id = r.batch_id and b.status = 'validated' and r.invoice_period = b.period
  where r.batch_id = p_batch_id
    and r.client_code is not null
    and coalesce(r.validation_state, 'valid') <> 'failed'
  group by
    r.batch_id, b.period, r.client_code, coalesce(r.official_line, ''), coalesce(r.region_code, '');

  select count(*), coalesce(sum(coalesce(r.value, 0)), 0)
    into v_drift_rows, v_drift_value
  from public.source_of_sales_import_rows r
  where r.batch_id = p_batch_id
    and coalesce(r.validation_state, 'valid') <> 'failed'
    and coalesce(nullif(btrim(r.invoice_period), ''), '') <> coalesce(v_period, '');

  if v_drift_rows > 0 then
    raise warning 'SoS period drift: batch % (period %) has % row(s) worth % on a different invoice_period; they are NOT in source_of_sales_fact_rollup. Run phx_sos_period_drift_count() for the breakdown.',
      p_batch_id, v_period, v_drift_rows, round(v_drift_value, 2);
  end if;
end;
$$;

ALTER FUNCTION public.phx_refresh_sos_fact_rollup(p_batch_id uuid) OWNER TO postgres;

--
-- Name: phx_refresh_sos_import_summaries(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refresh_sos_import_summaries(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
begin
  delete from public.source_of_sales_import_summaries
  where batch_id = p_batch_id;

  insert into public.source_of_sales_import_summaries (
    batch_id, group_type, group_key, group_label, group_code, official_line,
    row_count, total_qty, total_bonus_qty, total_value
  )
  -- ── Line ─────────────────────────────────────────────────────────────────
  -- The first UNION branch fixes the column types for every branch after it, so these casts are
  -- load-bearing: an untyped null/literal here resolves badly against the later branches.
  select
    p_batch_id,
    'line'::text,
    coalesce(r.official_line, '')::text,
    coalesce(r.official_line, '')::text,
    null::text,
    coalesce(r.official_line, '')::text,
    count(*),
    round(sum(r.qty), 6),
    round(sum(r.bonus_qty), 6),
    round(sum(r.value), 6)
  from public.source_of_sales_import_rows r
  where r.batch_id = p_batch_id
    and coalesce(r.validation_state, 'valid') <> 'failed'
  group by coalesce(r.official_line, '')

  union all

  -- ── Region ───────────────────────────────────────────────────────────────
  select
    p_batch_id,
    'region'::text,
    coalesce(r.region_code, '') || '|' || coalesce(r.region_name, ''),
    coalesce(r.region_name, ''),
    coalesce(r.region_code, ''),
    null::text,
    count(*),
    round(sum(r.qty), 6),
    round(sum(r.bonus_qty), 6),
    round(sum(r.value), 6)
  from public.source_of_sales_import_rows r
  where r.batch_id = p_batch_id
    and coalesce(r.validation_state, 'valid') <> 'failed'
  group by coalesce(r.region_code, ''), coalesce(r.region_name, '')

  union all

  -- ── Area ─────────────────────────────────────────────────────────────────
  -- Grouped on (area_code, area_name, region_code) to match the insert-time map key exactly --
  -- region_name is NOT part of that key, so the region NAME is taken from the group's first row
  -- (lowest row_number), which is the value the JS Map would have kept.
  select
    p_batch_id,
    'area',
    coalesce(r.area_code, '') || '|' || coalesce(r.area_name, '') || '|' || coalesce(r.region_code, ''),
    coalesce(r.area_name, ''),
    coalesce(r.area_code, ''),
    coalesce(
      nullif((array_agg(coalesce(r.region_name, '') order by r.row_number, r.id))[1], ''),
      coalesce(r.region_code, '')
    ),
    count(*),
    round(sum(r.qty), 6),
    round(sum(r.bonus_qty), 6),
    round(sum(r.value), 6)
  from public.source_of_sales_import_rows r
  where r.batch_id = p_batch_id
    and coalesce(r.validation_state, 'valid') <> 'failed'
  group by coalesce(r.area_code, ''), coalesce(r.area_name, ''), coalesce(r.region_code, '')

  union all

  -- ── Product ──────────────────────────────────────────────────────────────
  select
    p_batch_id,
    'product',
    coalesce(r.product_code, '') || '|' || coalesce(r.product_name, '') || '|' || coalesce(r.official_line, ''),
    coalesce(r.product_name, ''),
    coalesce(r.product_code, ''),
    coalesce(r.official_line, ''),
    count(*),
    round(sum(r.qty), 6),
    round(sum(r.bonus_qty), 6),
    round(sum(r.value), 6)
  from public.source_of_sales_import_rows r
  where r.batch_id = p_batch_id
    and coalesce(r.validation_state, 'valid') <> 'failed'
  group by coalesce(r.product_code, ''), coalesce(r.product_name, ''), coalesce(r.official_line, '')

  union all

  -- ── Brick ────────────────────────────────────────────────────────────────
  -- brick_name is not stored on the import row; it came from the brick master at parse time, so
  -- it is resolved from that same master here (source_of_sales_bricks.brick_id is unique --
  -- 700 rows, 700 distinct ids, verified 2026-08-30 -- so this join cannot fan out).
  select
    p_batch_id,
    'brick',
    coalesce(r.brick_id, '') || '|' || coalesce(bk.brick_name, '') || '|'
      || coalesce(r.area_code, '') || '|' || coalesce(r.region_code, ''),
    coalesce(bk.brick_name, ''),
    coalesce(r.brick_id, ''),
    coalesce(
      nullif((array_agg(coalesce(r.area_name, '') order by r.row_number, r.id))[1], ''),
      coalesce(r.area_code, '')
    ),
    count(*),
    round(sum(r.qty), 6),
    round(sum(r.bonus_qty), 6),
    round(sum(r.value), 6)
  from public.source_of_sales_import_rows r
  left join public.source_of_sales_bricks bk on bk.brick_id = r.brick_id
  where r.batch_id = p_batch_id
    and coalesce(r.validation_state, 'valid') <> 'failed'
  group by coalesce(r.brick_id, ''), coalesce(bk.brick_name, ''),
           coalesce(r.area_code, ''), coalesce(r.region_code, '');

  -- Batch header money + quantity, from the same rows, in the same pass. See the header comment
  -- for why the row-count columns are deliberately excluded.
  update public.source_of_sales_import_batches b
  set total_qty       = coalesce(t.total_qty, 0),
      total_bonus_qty = coalesce(t.total_bonus_qty, 0),
      total_value     = coalesce(t.total_value, 0),
      updated_at      = now()
  from (
    select
      round(sum(r.qty), 6)       as total_qty,
      round(sum(r.bonus_qty), 6) as total_bonus_qty,
      round(sum(r.value), 6)     as total_value
    from public.source_of_sales_import_rows r
    where r.batch_id = p_batch_id
      and coalesce(r.validation_state, 'valid') <> 'failed'
  ) t
  where b.id = p_batch_id;
end;
$$;

ALTER FUNCTION public.phx_refresh_sos_import_summaries(p_batch_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION phx_refresh_sos_import_summaries(p_batch_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_refresh_sos_import_summaries(p_batch_id uuid) IS 'Rebuilds source_of_sales_import_summaries for one batch from source_of_sales_import_rows, and re-derives that batch header''s total_qty/total_bonus_qty/total_value from the same rows. Run it wherever phx_refresh_sos_fact_rollup runs -- the summaries are what the Source of Sales dashboard reads, and before this existed they were frozen at insert while every other rollup refreshed.';

