ALTER FUNCTION public.phx_refresh_stale_attribution_periods(p_limit integer) OWNER TO postgres;

--
-- Name: phx_refuse_audit_trail_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refuse_audit_trail_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception
    'The % decision trail is append-only. % is refused.',
    tg_table_name, tg_op
    using hint =
      'These rows are the record behind real payments, and held settlements are '
      'reconstructed from them. Supersede a wrong decision with a NEW row. To '
      'remove one, drop this trigger deliberately in a migration.';
  return null;  -- unreachable; kept so the row-level signature stays honest
end;
$$;

ALTER FUNCTION public.phx_refuse_audit_trail_change() OWNER TO postgres;

--
-- Name: FUNCTION phx_refuse_audit_trail_change(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_refuse_audit_trail_change() IS 'Refuses UPDATE, DELETE and TRUNCATE on an append-only decision trail. Binds the table owner, which a REVOKE does not.';

--
-- Name: phx_refuse_history_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refuse_history_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'The % history is append-only. % is refused.', tg_table_name, tg_op
    using hint = 'A history row records what happened. To remove one, drop this trigger '
                 'deliberately in a migration, with the owner told first.';
  return null;
end;
$$;

ALTER FUNCTION public.phx_refuse_history_change() OWNER TO postgres;

--
-- Name: FUNCTION phx_refuse_history_change(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_refuse_history_change() IS 'Refuses UPDATE, DELETE and TRUNCATE on an append-only history table. Binds the table owner, which a REVOKE does not.';

--
-- Name: phx_refuse_publication_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_refuse_publication_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception
    'A monthly closing publication is never deleted. Unpublishing sets unpublished_at, so the '
    'record that % % was published survives. (This includes migrations and direct SQL.)',
    old.line, old.period
    using errcode = 'check_violation',
          hint = 'update public.monthly_closing_publications set unpublished_at = now() where id = ''' || old.id || ''';';
end;
$$;

ALTER FUNCTION public.phx_refuse_publication_delete() OWNER TO postgres;

--
-- Name: phx_reject_write_to_locked_closing(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_reject_write_to_locked_closing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_period_col text := tg_argv[0];
  v_line_col   text := tg_argv[1];
  v_hit        text;
begin
  if tg_op in ('INSERT', 'UPDATE') then
    execute format(
      'select l.line || '' '' || l.period
         from new_rows r
         join public.monthly_closing_locks l
           on l.period = r.%I
          and l.normalized_line = lower(btrim(coalesce(r.%I, '''')))
          and l.unlocked_at is null
        limit 1', v_period_col, v_line_col)
    into v_hit;
    if v_hit is not null then
      raise exception
        'Monthly closing % is LOCKED. No row may be added, changed or removed for it - this includes migrations and direct SQL. Unlock it first.', v_hit
        using errcode = 'check_violation', hint = 'select * from public.monthly_closing_locks where unlocked_at is null;';
    end if;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    execute format(
      'select l.line || '' '' || l.period
         from old_rows r
         join public.monthly_closing_locks l
           on l.period = r.%I
          and l.normalized_line = lower(btrim(coalesce(r.%I, '''')))
          and l.unlocked_at is null
        limit 1', v_period_col, v_line_col)
    into v_hit;
    if v_hit is not null then
      raise exception
        'Monthly closing % is LOCKED. No row may be added, changed or removed for it - this includes migrations and direct SQL. Unlock it first.', v_hit
        using errcode = 'check_violation', hint = 'select * from public.monthly_closing_locks where unlocked_at is null;';
    end if;
  end if;

  return null;
end;
$$;

ALTER FUNCTION public.phx_reject_write_to_locked_closing() OWNER TO postgres;

--
-- Name: FUNCTION phx_reject_write_to_locked_closing(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_reject_write_to_locked_closing() IS 'Statement-level guard: aborts any INSERT/UPDATE/DELETE touching a locked (line, period). Checks NEW rows on insert/update and OLD rows on update/delete, so a row cannot be moved out of a locked month either.';

--
-- Name: phx_release_daily_deduction_lines(date, date, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_release_daily_deduction_lines(p_range_start date, p_range_end date, p_lines jsonb, p_actor text, p_notes text DEFAULT NULL::text) RETURNS public.daily_deductions_publications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_publication public.daily_deductions_publications;
  v_actor text := btrim(coalesce(p_actor, ''));
  v_clash text;
begin
  if v_actor = '' then
    raise exception 'phx_release_daily_deduction_lines: an actor is required';
  end if;
  if p_range_start is null or p_range_end is null or p_range_start > p_range_end then
    raise exception 'phx_release_daily_deduction_lines: range_start must be <= range_end and neither may be null';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'phx_release_daily_deduction_lines: p_lines must be a non-empty JSON array';
  end if;

  -- A one-day row charges exactly its own day.
  select coalesce(line->>'employeeName', line->>'employeeHrId') into v_clash
    from jsonb_array_elements(p_lines) as line
   where nullif(line->>'deductionDate', '') is not null
     and coalesce(line->'dates', '[]'::jsonb) <> jsonb_build_array(line->>'deductionDate')
   limit 1;
  if v_clash is not null then
    raise exception 'phx_release_daily_deduction_lines: the one-day deduction for % must list exactly its own day', v_clash;
  end if;

  -- One release / withdraw / publish at a time, so the single-active-snapshot index can never race.
  perform pg_advisory_xact_lock(hashtext('daily_deductions_snapshot'));

  select * into v_publication
    from public.daily_deductions_publications
   where status = 'published' and superseded_at is null
   for update;

  if not found then
    insert into public.daily_deductions_publications (range_start, range_end, published_by, notes)
    values (p_range_start, p_range_end, v_actor, nullif(btrim(coalesce(p_notes, '')), ''))
    returning * into v_publication;
  end if;

  -- Never charge one day twice: a day released on its own may not sit inside an older whole-range
  -- row of the same employee x category, and a whole-range row may not cover a day already out alone.
  select coalesce(line->>'employeeName', line->>'employeeHrId') || ' on ' || (line->>'deductionDate') into v_clash
    from jsonb_array_elements(p_lines) as line
    join public.daily_deductions_lines l
      on l.publication_id = v_publication.id
     and l.employee_hr_id_compact = line->>'employeeHrIdCompact'
     and l.category = line->>'category'
     and l.deduction_date is null
     and l.dates ? (line->>'deductionDate')
   where nullif(line->>'deductionDate', '') is not null
   limit 1;
  if v_clash is not null then
    raise exception 'phx_release_daily_deduction_lines: % is already released inside an earlier whole-range deduction', v_clash;
  end if;

  select coalesce(line->>'employeeName', line->>'employeeHrId') || ' on ' || l.deduction_date::text into v_clash
    from jsonb_array_elements(p_lines) as line
    join public.daily_deductions_lines l
      on l.publication_id = v_publication.id
     and l.employee_hr_id_compact = line->>'employeeHrIdCompact'
     and l.category = line->>'category'
     and l.deduction_date is not null
     and coalesce(line->'dates', '[]'::jsonb) ? l.deduction_date::text
   where nullif(line->>'deductionDate', '') is null
   limit 1;
  if v_clash is not null then
    raise exception 'phx_release_daily_deduction_lines: % is already released on its own, so the whole range cannot be released over it', v_clash;
  end if;

  insert into public.daily_deductions_lines (
    publication_id, category, employee_hr_id, employee_hr_id_compact, employee_name,
    unit, raw_days_count, days_count, amount, dates, source_system, reason, hr_note,
    released_at, released_by, range_start, range_end, deduction_date
  )
  select
    v_publication.id,
    line->>'category',
    line->>'employeeHrId',
    line->>'employeeHrIdCompact',
    nullif(line->>'employeeName', ''),
    coalesce(nullif(line->>'unit', ''), 'days'),
    coalesce((line->>'rawDaysCount')::numeric, 0),
    coalesce((line->>'daysCount')::numeric, 0),
    coalesce((line->>'amount')::numeric, 0),
    coalesce(line->'dates', '[]'::jsonb),
    coalesce(line->>'sourceSystem', ''),
    nullif(line->>'reason', ''),
    coalesce(line->>'hrNote', ''),
    now(),
    v_actor,
    -- A one-day row is filed under its own day, never the window that was counted.
    coalesce(nullif(line->>'deductionDate', '')::date, p_range_start),
    coalesce(nullif(line->>'deductionDate', '')::date, p_range_end),
    nullif(line->>'deductionDate', '')::date
  from jsonb_array_elements(p_lines) as line
  on conflict (publication_id, employee_hr_id_compact, category, deduction_date) do update
    set employee_hr_id = excluded.employee_hr_id,
        employee_name  = excluded.employee_name,
        unit           = excluded.unit,
        raw_days_count = excluded.raw_days_count,
        days_count     = excluded.days_count,
        amount         = excluded.amount,
        dates          = excluded.dates,
        source_system  = excluded.source_system,
        reason         = excluded.reason,
        hr_note        = excluded.hr_note,
        released_at    = excluded.released_at,
        released_by    = excluded.released_by,
        range_start    = excluded.range_start,
        range_end      = excluded.range_end;

  -- Counts, totals and the window are derived from the rows that are actually there.
  update public.daily_deductions_publications p
     set range_start = coalesce((
           select min(coalesce(l.range_start, p.range_start))
             from public.daily_deductions_lines l where l.publication_id = p.id
         ), p.range_start),
         range_end = coalesce((
           select max(coalesce(l.range_end, p.range_end))
             from public.daily_deductions_lines l where l.publication_id = p.id
         ), p.range_end),
         line_count = (
           select count(*)::int from public.daily_deductions_lines where publication_id = p.id
         ),
         employee_count = (
           select count(distinct employee_hr_id_compact)::int
             from public.daily_deductions_lines where publication_id = p.id
         ),
         category_totals = coalesce((
           select jsonb_object_agg(category, cat_total)
             from (
               select category, sum(amount) as cat_total
                 from public.daily_deductions_lines
                where publication_id = p.id
                group by category
             ) c
         ), '{}'::jsonb)
   where p.id = v_publication.id;

  select * into v_publication from public.daily_deductions_publications where id = v_publication.id;
  return v_publication;
end;
$$;

ALTER FUNCTION public.phx_release_daily_deduction_lines(p_range_start date, p_range_end date, p_lines jsonb, p_actor text, p_notes text) OWNER TO postgres;

--
-- Name: FUNCTION phx_release_daily_deduction_lines(p_range_start date, p_range_end date, p_lines jsonb, p_actor text, p_notes text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_release_daily_deduction_lines(p_range_start date, p_range_end date, p_lines jsonb, p_actor text, p_notes text) IS 'Daily Deductions module: merge the given rows into the one active snapshot (creating it when none is active). A row is keyed by employee x category x deduction_date (null for a whole-range row); a row already released under the same key is replaced, every other row is untouched, and a day is never charged by both a one-day row and a whole-range row. SECURITY DEFINER, service_role only.';

--
-- Name: phx_release_terminal_manager_ownership(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_release_terminal_manager_ownership(p_previous_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_previous public.employees%rowtype;
  v_upstream_name text;
  v_count integer := 0;
  v_result jsonb := '{}'::jsonb;
begin
  select *
  into v_previous
  from public.employees
  where hr_id = upper(trim(coalesce(p_previous_hr_id, '')));

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'previous_employee_not_found');
  end if;

  if lower(coalesce(v_previous.employment_status, 'active')) not in ('resigned', 'terminated', 'inactive') then
    return jsonb_build_object('applied', false, 'reason', 'previous_employee_not_terminal');
  end if;

  if nullif(trim(coalesce(v_previous.manager_hr_id, '')), '') is null then
    return jsonb_build_object('applied', false, 'reason', 'upstream_manager_missing');
  end if;

  select full_name
  into v_upstream_name
  from public.employees
  where hr_id = v_previous.manager_hr_id;

  update public.employees
  set
    manager_hr_id = v_previous.manager_hr_id,
    pending_manager_replacement_for_hr_id = v_previous.hr_id,
    updated_at = now()
  where manager_hr_id = v_previous.hr_id
    and lower(coalesce(employment_status, 'active')) in ('active', 'on_leave');

  get diagnostics v_count = row_count;
  v_result := v_result || jsonb_build_object('employees_released_to_upstream', v_count);

  update public.position_vacancies
  set
    manager_hr_id = v_previous.manager_hr_id,
    manager_name = v_upstream_name,
    manager_replacement_for_hr_id = v_previous.hr_id,
    note = case
      when coalesce(note, '') ilike '%Pending replacement ownership:%' then note
      else concat_ws(
        E'\n',
        nullif(note, ''),
        'Pending replacement ownership: temporarily moved from terminal manager '
          || v_previous.hr_id || ' to upstream manager ' || v_previous.manager_hr_id
          || ' on ' || (now() at time zone 'Africa/Cairo')::date::text || '.'
      )
    end,
    updated_at = now()
  where manager_hr_id = v_previous.hr_id
    and lower(coalesce(status, 'open')) = 'open';

  get diagnostics v_count = row_count;
  v_result := v_result || jsonb_build_object('vacancies_released_to_upstream', v_count);

  if to_regclass('public.app_auth_users') is not null then
    begin
      execute
        'update public.app_auth_users
         set manager_hr_id = $2, updated_at = now()
         where manager_hr_id = $1 and is_active is true'
        using v_previous.hr_id, v_previous.manager_hr_id;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('app_auth_users_released_to_upstream', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('app_auth_users_released_to_upstream', null);
    end;
  end if;

  if to_regclass('public.user_access_profiles') is not null then
    begin
      execute
        'update public.user_access_profiles
         set manager_hr_id = $2, updated_at = now()
         where manager_hr_id = $1 and is_active is true'
        using v_previous.hr_id, v_previous.manager_hr_id;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('user_access_profiles_released_to_upstream', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('user_access_profiles_released_to_upstream', null);
    end;
  end if;

  return jsonb_build_object(
    'applied', true,
    'previous_hr_id', v_previous.hr_id,
    'upstream_manager_hr_id', v_previous.manager_hr_id
  ) || v_result;
end;
$_$;

ALTER FUNCTION public.phx_release_terminal_manager_ownership(p_previous_hr_id text) OWNER TO postgres;

--
-- Name: phx_release_terminal_manager_ownership_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_release_terminal_manager_ownership_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if lower(coalesce(new.employment_status, 'active')) in ('resigned', 'terminated', 'inactive') then
    perform public.phx_release_terminal_manager_ownership(new.hr_id);
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_release_terminal_manager_ownership_trigger() OWNER TO postgres;

--
-- Name: phx_remove_direct_order_offset(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_remove_direct_order_offset(p_request_id uuid, p_actor_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_offset        public.direct_order_marketing_offsets%rowtype;
  v_order         public.direct_order_requests%rowtype;
  v_left_offsets  numeric(14, 2);
  v_remaining     numeric(14, 2);
begin
  if p_actor_hr_id is null or btrim(p_actor_hr_id) = '' then
    raise exception 'offset_actor_required';
  end if;

  select * into v_offset from public.direct_order_marketing_offsets where marketing_request_id = p_request_id;
  if not found then
    raise exception 'offset_not_found';
  end if;

  select * into v_order from public.direct_order_requests where id = v_offset.direct_order_id for update;
  perform 1 from public.marketing_requests where id = p_request_id for update;

  delete from public.direct_order_marketing_offsets where id = v_offset.id;

  select coalesce(sum(amount), 0) into v_left_offsets
    from public.direct_order_marketing_offsets where direct_order_id = v_offset.direct_order_id;

  -- Nothing recorded at all (no collection, no offset left) reads as NULL, exactly as before any
  -- money was touched; otherwise the debt is the value less cash less the offsets that remain.
  if v_order.paid_amount is null and v_left_offsets = 0 then
    v_remaining := null;
  else
    v_remaining := round(coalesce(v_order.sales_value, 0)::numeric, 2)
                   - round(coalesce(v_order.paid_amount, 0)::numeric, 2)
                   - v_left_offsets;
  end if;

  update public.direct_order_requests
     set remaining_amount = v_remaining,
         updated_at = now()
   where id = v_offset.direct_order_id;

  return jsonb_build_object(
    'orderId',        v_offset.direct_order_id,
    'requestId',      p_request_id,
    'removedAmount',  v_offset.amount,
    'remainingAfter', v_remaining
  );
end;
$$;

ALTER FUNCTION public.phx_remove_direct_order_offset(p_request_id uuid, p_actor_hr_id text) OWNER TO postgres;

