CREATE FUNCTION public.phx_renew_dispute_case_decision(p_case_kind text, p_case_ref text, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.dispute_case_decision_claims
     set lapse_at = now() + interval '5 minutes'
   where case_kind = p_case_kind and case_ref = p_case_ref and claim_token = p_claim_token;
  return found;
end;
$$;

