--
-- Name: phx_reopen_rejected_marketing_request(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_reopen_rejected_marketing_request(p_request_id uuid, p_reopened_by text, p_reason text, p_reopened_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request  marketing_requests%rowtype;
  v_step     marketing_request_approval_steps%rowtype;
  v_restored integer := 0;
  v_reason   text;
begin
  v_reason := nullif(btrim(coalesce(p_reason, '')), '');
  if v_reason is null then
    -- The reason is the only record of why a recorded refusal was undone. Refused here as well as
    -- in the UI so the rule survives a caller that forgets it.
    raise exception 'marketing_reopen_reason_required: a reason is required to reopen a request'
      using errcode = 'check_violation';
  end if;

  -- Serialise against a concurrent decision on the same request.
  select * into v_request from marketing_requests where id = p_request_id for update;
  if not found then
    raise exception 'marketing_request_not_found: %', p_request_id
      using errcode = 'no_data_found';
  end if;

  -- Optimistic lock. A request someone already reopened, or that never was rejected, is refused
  -- rather than quietly re-reopened — the caller maps this to a 409.
  if v_request.status <> 'rejected' then
    raise exception 'marketing_request_not_rejected: % is %', p_request_id, v_request.status
      using errcode = 'check_violation';
  end if;

  -- The rung that ended the chain. Ordered descending so a request refused, reopened and refused
  -- again at a LATER rung comes back to the latest refusal, never the first one.
  select * into v_step
  from marketing_request_approval_steps
  where request_id = p_request_id
    and status     = 'rejected'
    and is_cc      = false
  order by sequence desc
  limit 1;

  if not found then
    raise exception 'marketing_reopen_no_rejected_step: % carries no rejected rung', p_request_id
      using errcode = 'check_violation';
  end if;

  -- 1. Put the refusing rung back on its approver's desk, decision cleared. The refusal text is
  --    NOT lost: marketing_request_events holds it as an append-only `step_decided` row.
  update marketing_request_approval_steps set
    status            = 'current',
    decision_at       = null,
    decision_by_hr_id = null,
    decision_note     = null,
    updated_at        = p_reopened_at
  where id = v_step.id
  returning * into v_step;

  -- 2. Restore ONLY the rungs the refusal closed out — see the migration header note.
  update marketing_request_approval_steps set
    status     = 'pending',
    updated_at = p_reopened_at
  where request_id    = p_request_id
    and status        = 'skipped'
    and is_cc         = false
    and decision_note is null
    and sequence      > v_step.sequence;
  get diagnostics v_restored = row_count;

  -- 3. Back in flight.
  update marketing_requests set
    status           = 'pending_approval',
    rejected_at      = null,
    updated_at       = p_reopened_at,
    updated_by_hr_id = p_reopened_by
  where id = p_request_id
  returning * into v_request;

  -- 4. The why, against the rung it concerns.
  --
  -- Deliberately `step_commented` and not a second `request_status_changed`: the status flip is
  -- already recorded by phx_capture_marketing_request_event on the update above, and two rows for
  -- one transition reads as a double reopen. What the trigger cannot capture is the reason, which
  -- belongs beside the rung being reopened.
  insert into public.marketing_request_events
    (request_id, request_code, kind, actor_hr_id, occurred_at,
     from_status, to_status, step_sequence, step_name, note, payload)
  values
    (p_request_id, v_request.request_code, 'step_commented', p_reopened_by, p_reopened_at,
     'rejected', 'current', v_step.sequence, v_step.step_name, v_reason,
     jsonb_build_object('action', 'reopen', 'restored_rungs', v_restored));

  return jsonb_build_object(
    'request',  to_jsonb(v_request),
    'step',     to_jsonb(v_step),
    'restored', v_restored
  );
end;
$$;

ALTER FUNCTION public.phx_reopen_rejected_marketing_request(p_request_id uuid, p_reopened_by text, p_reason text, p_reopened_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION phx_reopen_rejected_marketing_request(p_request_id uuid, p_reopened_by text, p_reason text, p_reopened_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_reopen_rejected_marketing_request(p_request_id uuid, p_reopened_by text, p_reason text, p_reopened_at timestamp with time zone) IS 'Reopens a rejected marketing request onto the rung that refused it, restoring only the rungs that refusal closed out (decision_note is null), atomically. Super Admin only — the role gate lives in the service layer.';

--
-- Name: phx_rep_bulk_dependency(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_rep_bulk_dependency(p_from text DEFAULT NULL::text, p_to text DEFAULT NULL::text) RETURNS TABLE(period text, rep_hr_id text, rep_name text, line_code text, region_code text, area_code text, area_name text, actual_value numeric, covered_actual numeric, target_value numeric, achievement_pct numeric, bulk_type text, bulk_ref text, bulk_name text, bulk_value numeric, bulk_share_pct numeric, achievement_without_pct numeric, flips boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'au'
    AS $$
  with params as (
    select coalesce(p_from, (select min(mcp.period) from public.monthly_closing_publications mcp)) as p_from,
           coalesce(p_to,   (select max(mcp.period) from public.monthly_closing_publications mcp)) as p_to
  ),
  pub as (
    select distinct replace(mcp.normalized_line, ' ', '_') as line_code, mcp.period
    from public.monthly_closing_publications mcp
  ),
  phx as (
    select r.*
    from params pm, lateral public.phx_sales_vs_target_range(pm.p_from, pm.p_to) r
  ),
  prod_line as (
    select distinct product_code, line_code
    from phx
    where line_code is not null and product_code is not null
  ),
  prod_direct as (
    select fr.period, fr.product_code,
           sum(fr.direct_value)    as direct_value,
           sum(fr.effective_units) as direct_units
    from public.source_of_sales_fact_rollup fr, params pm
    where fr.period between pm.p_from and pm.p_to
      and fr.is_direct
    group by fr.period, fr.product_code
  ),
  prod_actual as (
    select period, product_code,
           sum(actual_value) as actual_value,
           sum(actual_units) as actual_units
    from phx
    where product_code is not null
    group by period, product_code
  ),
  price as (
    select pa.period, pa.product_code,
           case when (pa.actual_units - coalesce(pd.direct_units, 0)) > 0
                then (pa.actual_value - coalesce(pd.direct_value, 0))
                   / (pa.actual_units - coalesce(pd.direct_units, 0))
                else 0 end as unit_price
    from prod_actual pa
    left join prod_direct pd
      on pd.period = pa.period and pd.product_code = pa.product_code
  ),
  rep_tot as (
    select period, rep_hr_id, line_code, region_code, area_code,
           sum(actual_value)                           as actual_value,
           sum(actual_value) filter (where has_target) as covered_actual,
           sum(target_value)                           as target_value
    from phx
    where rep_hr_id is not null and line_code is not null
    group by period, rep_hr_id, line_code, region_code, area_code
  ),
  direct_cand as (
    select fr.period, pl.line_code, fr.area_code, fr.product_code,
           max(fr.product_name) as product_name,
           sum(fr.direct_value) as bulk_value
    from public.source_of_sales_fact_rollup fr
    join prod_line pl on pl.product_code = fr.product_code
    cross join params pm
    where fr.period between pm.p_from and pm.p_to
      and fr.is_direct
    group by fr.period, pl.line_code, fr.area_code, fr.product_code
  ),
  direct_final as (
    select distinct on (period, line_code, area_code)
           period, line_code, area_code,
           'direct_order'::text as bulk_type,
           product_code as bulk_ref, product_name as bulk_name, bulk_value
    from direct_cand
    order by period, line_code, area_code, bulk_value desc
  ),
  whale_cand as (
    select fr.period, pl.line_code, fr.area_code, fr.client_code,
           sum(fr.effective_units * pr.unit_price) as bulk_value
    from public.source_of_sales_fact_rollup fr
    join prod_line pl on pl.product_code = fr.product_code
    join price pr on pr.period = fr.period and pr.product_code = fr.product_code
    cross join params pm
    where fr.period between pm.p_from and pm.p_to
      and not fr.is_direct
      and fr.client_code is not null
    group by fr.period, pl.line_code, fr.area_code, fr.client_code
  ),
  whale_final as (
    select distinct on (period, line_code, area_code)
           period, line_code, area_code,
           'whale_customer'::text as bulk_type,
           client_code as bulk_ref, null::text as bulk_name, bulk_value
    from whale_cand
    order by period, line_code, area_code, bulk_value desc
  ),
  biggest_bulk as (
    select coalesce(d.period, w.period)       as period,
           coalesce(d.line_code, w.line_code) as line_code,
           coalesce(d.area_code, w.area_code) as area_code,
           case when coalesce(d.bulk_value, 0) >= coalesce(w.bulk_value, 0)
                then d.bulk_type else w.bulk_type end as bulk_type,
           case when coalesce(d.bulk_value, 0) >= coalesce(w.bulk_value, 0)
                then d.bulk_ref  else w.bulk_ref  end as bulk_ref,
           case when coalesce(d.bulk_value, 0) >= coalesce(w.bulk_value, 0)
                then d.bulk_name else w.bulk_name end as bulk_name,
           greatest(coalesce(d.bulk_value, 0), coalesce(w.bulk_value, 0)) as bulk_value
    from direct_final d
    full join whale_final w
      on w.period = d.period and w.line_code = d.line_code and w.area_code = d.area_code
  )
  select
    t.period,
    t.rep_hr_id,
    e.full_name as rep_name,
    t.line_code,
    t.region_code,
    t.area_code,
    ca.area_name,
    round(t.actual_value, 2)   as actual_value,
    round(t.covered_actual, 2) as covered_actual,
    round(t.target_value, 2)   as target_value,
    round(100 * t.covered_actual / nullif(t.target_value, 0), 1) as achievement_pct,
    b.bulk_type,
    b.bulk_ref,
    coalesce(b.bulk_name, cm.customer_name) as bulk_name,
    round(b.bulk_value, 2) as bulk_value,
    round(100 * b.bulk_value / nullif(t.actual_value, 0), 1) as bulk_share_pct,
    round(100 * (t.covered_actual - coalesce(b.bulk_value, 0)) / nullif(t.target_value, 0), 1)
      as achievement_without_pct,
    (t.covered_actual / nullif(t.target_value, 0) >= 1
      and (t.covered_actual - coalesce(b.bulk_value, 0)) / nullif(t.target_value, 0) < 1) as flips
  from rep_tot t
  join pub
    on pub.line_code = t.line_code and pub.period = t.period
  left join biggest_bulk b
    on b.period = t.period and b.line_code = t.line_code and b.area_code = t.area_code
  left join public.employees e
    on e.hr_id = t.rep_hr_id
  left join au.canonical_areas ca
    on ca.area_code = t.area_code
  left join lateral (
    select m.customer_name
    from public.source_of_sales_customer_map m
    where b.bulk_type = 'whale_customer' and m.customer_code = b.bulk_ref
    order by m.confidence desc nulls last
    limit 1
  ) cm on true
  order by achievement_pct desc nulls last;
$$;

ALTER FUNCTION public.phx_rep_bulk_dependency(p_from text, p_to text) OWNER TO postgres;

--
-- Name: FUNCTION phx_rep_bulk_dependency(p_from text, p_to text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_rep_bulk_dependency(p_from text, p_to text) IS 'Per-rep bulk-order dependency: achievement with vs without each rep''s single largest direct order or whale customer. Read-only wrapper over phx_sales_vs_target_range; does NOT re-simulate the Office value-share spread (Office-heavy cases are understated). Gated to published closings.';

--
-- Name: phx_replace_retention_conversation_themes(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_replace_retention_conversation_themes(p_conversation_id uuid, p_themes jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_inserted integer := 0;
begin
  if p_themes is null or jsonb_typeof(p_themes) <> 'array' then
    raise exception 'Retention themes must be a list.' using errcode = '22023';
  end if;

  -- The row lock serialises two editors of the same conversation, so one replacement cannot
  -- interleave with another and leave a mix of both sets.
  select id into v_id
  from public.hr_retention_conversations
  where id = p_conversation_id
  for update;
  if not found then
    raise exception 'That conversation no longer exists.' using errcode = 'P0002';
  end if;

  delete from public.hr_retention_conversation_themes
  where conversation_id = p_conversation_id;

  insert into public.hr_retention_conversation_themes (conversation_id, theme_key, sentiment, note)
  select p_conversation_id, theme.theme_key, theme.sentiment, theme.note
  from jsonb_to_recordset(p_themes) as theme(theme_key text, sentiment text, note text);
  get diagnostics v_inserted = row_count;

  return v_inserted;
end;
$$;

ALTER FUNCTION public.phx_replace_retention_conversation_themes(p_conversation_id uuid, p_themes jsonb) OWNER TO postgres;

--
-- Name: phx_replace_salary_batch(uuid, integer, integer, text, text, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_replace_salary_batch(p_batch_id uuid, p_expected_month integer, p_expected_year integer, p_file_name text, p_uploaded_by text, p_records jsonb, p_flags jsonb, p_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_records jsonb := coalesce(p_records, '[]'::jsonb);
  v_flags jsonb := coalesce(p_flags, '[]'::jsonb);
begin
  if jsonb_typeof(v_records) <> 'array' then
    raise exception 'Payroll replacement records must be a JSON array.' using errcode = '22023';
  end if;

  if jsonb_typeof(v_flags) <> 'array' then
    raise exception 'Payroll replacement flags must be a JSON array.' using errcode = '22023';
  end if;

  if jsonb_array_length(v_records) = 0 then
    raise exception 'Payroll replacement records must include at least one salary record.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_records) as r(payment_mode text)
    where coalesce(r.payment_mode, 'two_parts') not in ('one_part', 'two_parts')
  ) then
    raise exception 'Payroll replacement payment_mode must be one_part or two_parts.' using errcode = '22023';
  end if;

  select *
  into v_batch
  from public.salary_batches
  where id = p_batch_id
  for update;

  if not found then
    raise exception 'Payroll upload not found.' using errcode = 'P0002';
  end if;

  if v_batch.part1_paid_at is not null or v_batch.status not in ('uploaded', 'part1_ready', 'rejected') then
    raise exception 'Payroll batch cannot be replaced after Part 1 is paid or while status is %.', v_batch.status using errcode = 'P0001';
  end if;

  if v_batch.month is distinct from p_expected_month or v_batch.year is distinct from p_expected_year then
    raise exception 'Payroll batch period changed before replacement could be applied.' using errcode = 'P0001';
  end if;

  delete from public.salary_records
  where batch_id = p_batch_id;

  insert into public.salary_records (
    area,
    base_salary,
    batch_id,
    bonus,
    crm,
    employment_income_tax,
    expenses,
    extra_cost_of_living,
    finger_print,
    first_part,
    fuel_allowance,
    full_name,
    governmental_deductions,
    gross_salary,
    hire_date,
    hr_id,
    incentive,
    job_title,
    line,
    loans,
    medical_insurance,
    month_salary,
    name_ar,
    net_salary,
    other_additions,
    other_deductions,
    overtime,
    comment,
    payment_mode,
    second_part,
    social_insurance,
    total_additions,
    total_deductions,
    unpaid_vacations,
    working_days,
    calendar_days
  )
  select
    r.area,
    coalesce(r.base_salary, 0),
    p_batch_id,
    r.bonus,
    r.crm,
    r.employment_income_tax,
    r.expenses,
    r.extra_cost_of_living,
    r.finger_print,
    r.first_part,
    r.fuel_allowance,
    r.full_name,
    coalesce(r.governmental_deductions, coalesce(r.social_insurance, 0) + coalesce(r.employment_income_tax, 0)),
    r.gross_salary,
    r.hire_date,
    r.hr_id,
    r.incentive,
    r.job_title,
    r.line,
    r.loans,
    r.medical_insurance,
    coalesce(r.month_salary, coalesce(r.first_part, 0) + coalesce(r.second_part, 0)),
    r.name_ar,
    r.net_salary,
    r.other_additions,
    r.other_deductions,
    r.overtime,
    r.comment,
    coalesce(r.payment_mode, 'two_parts'),
    r.second_part,
    r.social_insurance,
    r.total_additions,
    r.total_deductions,
    r.unpaid_vacations,
    r.working_days,
    r.calendar_days
  from jsonb_to_recordset(v_records) as r(
    area text,
    base_salary numeric,
    bonus numeric,
    crm numeric,
    employment_income_tax numeric,
    expenses numeric,
    extra_cost_of_living numeric,
    finger_print numeric,
    first_part numeric,
    fuel_allowance numeric,
    full_name text,
    governmental_deductions numeric,
    gross_salary numeric,
    hire_date date,
    hr_id text,
    incentive numeric,
    job_title text,
    line text,
    loans numeric,
    medical_insurance numeric,
    month_salary numeric,
    name_ar text,
    net_salary numeric,
    other_additions numeric,
    other_deductions numeric,
    overtime numeric,
    comment text,
    payment_mode text,
    second_part numeric,
    social_insurance numeric,
    total_additions numeric,
    total_deductions numeric,
    unpaid_vacations numeric,
    working_days integer,
    calendar_days integer
  );

  delete from public.salary_flags
  where batch_id = p_batch_id;

  insert into public.salary_flags (
    batch_id,
    flag_type,
    hr_id,
    message,
    severity
  )
  select
    p_batch_id,
    f.flag_type,
    f.hr_id,
    f.message,
    coalesce(f.severity, 'warning')
  from jsonb_to_recordset(v_flags) as f(
    flag_type text,
    hr_id text,
    message text,
    severity text
  );

  update public.salary_batches
  set
    approved_at = null,
    approved_by = null,
    file_name = p_file_name,
    locked_at = null,
    part1_paid_at = null,
    part1_paid_by = null,
    part2_ready_at = null,
    part2_ready_by = null,
    rejected_reason = null,
    status = 'uploaded',
    updated_at = p_updated_at,
    uploaded_by = p_uploaded_by
  where id = p_batch_id
  returning *
  into v_batch;

  return to_jsonb(v_batch);
end;
$$;

ALTER FUNCTION public.phx_replace_salary_batch(p_batch_id uuid, p_expected_month integer, p_expected_year integer, p_file_name text, p_uploaded_by text, p_records jsonb, p_flags jsonb, p_updated_at timestamp with time zone) OWNER TO postgres;

--
-- Name: phx_report_it_set_dashboard_access(text, boolean, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_report_it_set_dashboard_access(p_hr_id text, p_grant boolean, p_actor_hr_id text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_hr_id text := nullif(btrim(p_hr_id), '');
  v_changed boolean := false;
begin
  if v_hr_id is null then
    raise exception 'Validation: an employee is required.' using errcode = '22023';
  end if;
  if nullif(btrim(p_actor_hr_id), '') is null then
    raise exception 'Validation: the person making the change is required.' using errcode = '22023';
  end if;

  if p_grant then
    insert into public.report_it_dashboard_access (hr_id, granted_by)
    values (v_hr_id, p_actor_hr_id)
    on conflict (hr_id) do nothing;
    v_changed := found;
  else
    delete from public.report_it_dashboard_access where hr_id = v_hr_id;
    v_changed := found;
  end if;

  -- Only a real change is logged: pressing grant twice changed nothing about who can read.
  if v_changed then
    insert into public.report_it_audit_logs (report_id, actor_hr_id, action, metadata)
    values (
      null,
      p_actor_hr_id,
      case when p_grant then 'dashboard_access_granted' else 'dashboard_access_revoked' end,
      coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('hrId', v_hr_id)
    );
  end if;

  return v_changed;
end;
$$;

ALTER FUNCTION public.phx_report_it_set_dashboard_access(p_hr_id text, p_grant boolean, p_actor_hr_id text, p_metadata jsonb) OWNER TO postgres;

