--
-- Name: phx_resign_employee_and_open_vacancy(text, date, text, text, text, text, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_resign_employee_and_open_vacancy(p_actor text, p_effective_date date, p_employee_hr_id text, p_employee_status text, p_reason text, p_submitted_by_hr_id text, p_submitted_date date, p_vacancy_code text, p_workflow_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_employee public.employees;
  v_line_name text;
  v_position_title text;
  v_manager_name text;
  v_vacancy_id bigint;
  v_resignation_id uuid;
  v_seat_id text;
  -- p_effective_date IS the last working day — it is written to
  -- employees.last_working_date below — so the seat falls vacant the day AFTER
  -- it, never on it. A null date keeps this function's original meaning:
  -- vacate from today.
  v_vacant_from date := coalesce(p_effective_date + 1, (now() at time zone 'Africa/Cairo')::date);
begin
  select * into v_employee from public.employees where hr_id = p_employee_hr_id;
  if not found then
    raise exception 'phx_resign_employee_and_open_vacancy: employee % not found', p_employee_hr_id;
  end if;
  select name into v_line_name from public.lines where id = v_employee.line_id;
  select title into v_position_title from public.positions where id = v_employee.position_id;
  select full_name into v_manager_name from public.employees where hr_id = v_employee.manager_hr_id;
  insert into public.position_vacancies (
    area_id, department_id, job_title, line_id, manager_hr_id, manager_name, note,
    position_id, region_name, replacement_for_hr_id, status, vacancy_code, created_at, updated_at
  ) values (
    v_employee.area_id, v_employee.department_id,
    coalesce(v_employee.job_title, v_position_title), v_employee.line_id,
    v_employee.manager_hr_id, v_manager_name,
    'Auto-opened from resignation of ' || v_employee.full_name || ' (' || v_employee.hr_id || '). Effective ' || p_effective_date,
    v_employee.position_id, v_employee.region_name, p_employee_hr_id, 'open', p_vacancy_code,
    now(), now()
  )
  returning id into v_vacancy_id;
  insert into public.employee_resignations (
    employee_hr_id, employee_name, job_title, line_name,
    submitted_date, effective_date, resignation_date, last_working_date,
    reason, notes, workflow_notes, exit_status, status,
    create_vacancy, vacancy_id, submitted_by_hr_id, created_by, created_at, updated_at,
    crm_id_before
  ) values (
    p_employee_hr_id, v_employee.full_name, coalesce(v_position_title, v_employee.job_title), v_line_name,
    p_submitted_date, p_effective_date, p_submitted_date, p_effective_date,
    p_reason, coalesce(p_workflow_notes, p_reason), p_workflow_notes, 'submitted', 'submitted',
    true, v_vacancy_id, p_submitted_by_hr_id, p_actor, now(), now(),
    v_employee.crm_id
  )
  returning id into v_resignation_id;
  update public.employees set
    employment_status = p_employee_status,
    exit_reason = p_reason,
    exit_status = 'submitted',
    last_working_date = p_effective_date,
    organogram_visible = false,
    payroll_eligible = false,
    resignation_date = p_submitted_date,
    crm_id = null,
    updated_at = now()
  where hr_id = p_employee_hr_id;
  if p_effective_date is null or p_effective_date <= (now() at time zone 'Africa/Cairo')::date then
    update public.app_auth_users set is_active = false, updated_at = now() where hr_id = p_employee_hr_id;
    update public.user_access_profiles set is_active = false, updated_at = now() where hr_id = p_employee_hr_id;
  end if;
  for v_seat_id in
    select seat_id
    from au.occupancy_history
    where occupant_canonical_hr_id = lower(btrim(p_employee_hr_id))
      and effective_to is null
      and node_type = 'person'
    order by seat_id
  loop
    perform au.resign_occupant(v_seat_id, v_vacant_from, coalesce(p_reason, 'resignation'), p_actor);
  end loop;
  return jsonb_build_object(
    'employee_hr_id', p_employee_hr_id,
    'employee_status', p_employee_status,
    'resignation_id', v_resignation_id,
    'vacancy_code', p_vacancy_code
  );
end;
$$;

ALTER FUNCTION public.phx_resign_employee_and_open_vacancy(p_actor text, p_effective_date date, p_employee_hr_id text, p_employee_status text, p_reason text, p_submitted_by_hr_id text, p_submitted_date date, p_vacancy_code text, p_workflow_notes text) OWNER TO postgres;

--
-- Name: phx_resolve_directory_pharmacy(text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_resolve_directory_pharmacy(p_distributor_code text, p_customer_code text, p_pharmacy_name text, p_brick_id text, p_area_code text, p_region_code text, p_address text, p_hr_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_pharmacy_id uuid;
BEGIN
  -- 1. Try to find existing link
  SELECT pharmacy_id INTO v_pharmacy_id 
  FROM public.direct_order_pharmacy_distributor_codes 
  WHERE distributor_code = p_distributor_code AND customer_code = p_customer_code;
  
  IF v_pharmacy_id IS NOT NULL THEN
    RETURN v_pharmacy_id;
  END IF;

  -- 2. Insert shell and link using UPSERT to avoid exceptions
  WITH new_pharmacy AS (
    INSERT INTO public.direct_order_pharmacies (pharmacy_name, brick_id, area_code, region_code, pharmacy_address, created_by_hr_id, verification_status, entry_source, verified_by_hr_id, verified_at)
    VALUES (p_pharmacy_name, p_brick_id, p_area_code, p_region_code, p_address, p_hr_id, 'verified', 'catalogue', p_hr_id, now())
    RETURNING id
  ),
  new_link AS (
    INSERT INTO public.direct_order_pharmacy_distributor_codes (pharmacy_id, distributor_code, customer_code, mapped_brick_id, mapped_area_code, mapped_region_code)
    SELECT id, p_distributor_code, p_customer_code, p_brick_id, p_area_code, p_region_code FROM new_pharmacy
    ON CONFLICT (distributor_code, customer_code) DO NOTHING
    RETURNING pharmacy_id
  )
  SELECT pharmacy_id INTO v_pharmacy_id FROM new_link;

  -- 3. If ON CONFLICT DO NOTHING triggered, it means someone else won the race.
  IF v_pharmacy_id IS NULL THEN
    -- Another connection inserted the link just before we did. The new_pharmacy shell we just inserted is an orphan.
    -- (We can clean it up asynchronously or right here, but the unique constraint error is avoided).
    SELECT pharmacy_id INTO v_pharmacy_id 
    FROM public.direct_order_pharmacy_distributor_codes 
    WHERE distributor_code = p_distributor_code AND customer_code = p_customer_code;
  END IF;

  RETURN v_pharmacy_id;
END;
$$;

ALTER FUNCTION public.phx_resolve_directory_pharmacy(p_distributor_code text, p_customer_code text, p_pharmacy_name text, p_brick_id text, p_area_code text, p_region_code text, p_address text, p_hr_id text) OWNER TO postgres;

--
-- Name: phx_resolve_expense_payout_period(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_resolve_expense_payout_period(p_incurred_year integer, p_incurred_month integer) RETURNS TABLE(payout_year integer, payout_month integer, reperiodized boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_y integer; v_m integer; v_nat_y integer; v_nat_m integer; v_closed boolean; i integer := 0;
begin
  if p_incurred_year is null or p_incurred_month is null then
    return query select null::integer, null::integer, false;
    return;
  end if;

  v_y := p_incurred_year;
  v_m := p_incurred_month + 1;
  if v_m > 12 then v_m := 1; v_y := v_y + 1; end if;
  v_nat_y := v_y; v_nat_m := v_m;

  while i < 36 loop
    select exists (
      select 1 from public.salary_batches b
      where b.year = v_y and b.month = v_m and b.status in ('approved', 'locked')
    ) into v_closed;

    if not v_closed then
      return query select v_y, v_m, (v_y is distinct from v_nat_y or v_m is distinct from v_nat_m);
      return;
    end if;

    v_m := v_m + 1;
    if v_m > 12 then v_m := 1; v_y := v_y + 1; end if;
    i := i + 1;
  end loop;

  raise exception 'Could not resolve an open payout period within 36 months of %-%.',
    p_incurred_year, p_incurred_month using errcode = 'P0001';
end;
$$;

ALTER FUNCTION public.phx_resolve_expense_payout_period(p_incurred_year integer, p_incurred_month integer) OWNER TO postgres;

--
-- Name: FUNCTION phx_resolve_expense_payout_period(p_incurred_year integer, p_incurred_month integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_resolve_expense_payout_period(p_incurred_year integer, p_incurred_month integer) IS 'The first payout period at or after (incurred month + 1) whose payroll batch is not approved/locked. Returns reperiodized=true when the natural month was closed.';

--
-- Name: phx_resolve_marketing_pharmacy_codes(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_resolve_marketing_pharmacy_codes(p_code_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(match_kind text, code_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $_$
begin
  return query
  with fam as (
    select md.id as distributor_id,
           array_agg(distinct ru.sos_distributor_code) as sos_codes
    from public.marketing_distributors md
    join public.marketing_roi_distributor_rollup ru
      on ru.marketing_normalized_name = md.normalized_name
    group by md.id
  ),
  target as (
    select mpdc.id, mpdc.normalized_pharmacy_code, fam.sos_codes
    from public.marketing_pharmacy_distributor_codes mpdc
    left join fam on fam.distributor_id = mpdc.distributor_id
    where (p_code_ids is null or mpdc.id = any(p_code_ids))
      and (p_code_ids is not null or coalesce(mpdc.active, true))
  ),
  exact_c as (
    select t.id, cm.distributor_code, cm.customer_code, cm.brick_id, cm.area_code, cm.region_code
    from target t
    join public.source_of_sales_customer_map cm
      on cm.distributor_code = any(t.sos_codes)
     and coalesce(cm.active, true)
     and lower(btrim(cm.customer_code)) = t.normalized_pharmacy_code
  ),
  digit_c as (
    select t.id, cm.distributor_code, cm.customer_code, cm.brick_id, cm.area_code, cm.region_code
    from target t
    join public.source_of_sales_customer_map cm
      on cm.distributor_code = any(t.sos_codes)
     and coalesce(cm.active, true)
     and t.normalized_pharmacy_code ~ '^[0-9]+$'
     and btrim(cm.customer_code) ~ '^[0-9]+$'
     and ltrim(btrim(cm.customer_code), '0') = ltrim(t.normalized_pharmacy_code, '0')
    where not exists (select 1 from exact_c e where e.id = t.id)
  ),
  cand as (
    select 'exact'::text as kind, id, distributor_code, customer_code, brick_id, area_code, region_code
    from exact_c
    union all
    select 'digit_normalized'::text as kind, id, distributor_code, customer_code, brick_id, area_code, region_code
    from digit_c
  ),
  agg as (
    select c.id,
           min(c.kind)                as kind,
           count(distinct c.brick_id) as bricks,
           -- The territory columns get their own agreement test, independent of the brick.
           count(distinct c.area_code)                   as areas,
           count(*) filter (where c.area_code is null)   as areas_missing,
           count(distinct c.region_code)                 as regions,
           count(*) filter (where c.region_code is null) as regions_missing
    from cand c
    group by c.id
  ),
  pick as (
    select distinct on (c.id)
           c.id, c.distributor_code, c.customer_code, c.brick_id, c.area_code, c.region_code
    from cand c
    order by c.id, c.distributor_code, c.customer_code, c.brick_id
  ),
  verdict as (
    select t.id,
           case
             when a.id is null   then 'unresolved'
             when a.bricks = 1   then a.kind
             when a.bricks > 1   then 'ambiguous'
             else 'unresolved'
           end as kind,
           -- Agreed = every candidate carries the value, and they all carry the same one. Any
           -- candidate missing it means the set does not speak with one voice, so we say nothing.
           coalesce(a.areas = 1 and a.areas_missing = 0, false)     as area_agreed,
           coalesce(a.regions = 1 and a.regions_missing = 0, false) as region_agreed
    from target t
    left join agg a on a.id = t.id
  ),
  upd as (
    update public.marketing_pharmacy_distributor_codes m
    set
      -- Identity: only ever written for a pinned match. Unchanged.
      mapped_distributor_code = case when v.kind in ('exact', 'digit_normalized') then p.distributor_code end,
      mapped_customer_code    = case when v.kind in ('exact', 'digit_normalized') then p.customer_code    end,
      mapped_brick_id         = case when v.kind in ('exact', 'digit_normalized') then p.brick_id         end,
      -- Territory: written for a pinned match exactly as before, and ALSO for an ambiguous one
      -- whose candidates all agree. `pick` is safe to read here precisely because they agree --
      -- whichever candidate it chose carries the same value as the rest.
      mapped_area_code        = case
                                  when v.kind in ('exact', 'digit_normalized') then p.area_code
                                  when v.kind = 'ambiguous' and v.area_agreed  then p.area_code
                                end,
      mapped_region_code      = case
                                  when v.kind in ('exact', 'digit_normalized') then p.region_code
                                  when v.kind = 'ambiguous' and v.region_agreed then p.region_code
                                end,
      master_match_kind       = v.kind,
      master_resolved_at      = now()
    from verdict v
    left join pick p on p.id = v.id
    where m.id = v.id
    returning m.master_match_kind
  )
  select u.master_match_kind, count(*)::bigint
  from upd u
  group by u.master_match_kind
  order by u.master_match_kind;
end;
$_$;

ALTER FUNCTION public.phx_resolve_marketing_pharmacy_codes(p_code_ids uuid[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_resolve_marketing_pharmacy_codes(p_code_ids uuid[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_resolve_marketing_pharmacy_codes(p_code_ids uuid[]) IS 'Resolves marketing pharmacy codes against source_of_sales_customer_map via the marketing_roi_distributor_rollup code family. Pass 1 exact, pass 2 digit-normalized (0 rows today, forward guard). Single distinct brick -> copies identity; >1 brick -> ''ambiguous'' with mapped_* left NULL; none -> ''unresolved''. NULL p_code_ids resolves every active code. Idempotent. Returns counts per verdict. Expected on production: 269 exact / 6 ambiguous / 0 digit / 14 unresolved.';

--
-- Name: phx_restore_deduction_dispute_state(jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_restore_deduction_dispute_state(p_snapshot jsonb, p_left jsonb, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  deciding constant text[] := array[
    'decision_status', 'decision_reason', 'hr_note',
    'applied_value', 'applied_amount', 'applied_dates', 'decided_by'
  ];
  v_candidate       uuid := nullif(p_snapshot->>'candidateId', '')::uuid;
  v_ref             text := p_snapshot->>'candidateId';
  v_before_lines    jsonb := coalesce(p_snapshot->'lines', '[]'::jsonb);
  v_left_lines      jsonb := coalesce(p_left->'lines', '[]'::jsonb);
  v_before_refunds  jsonb := coalesce(p_snapshot->'refunds', '[]'::jsonb);
  v_left_refunds    jsonb := coalesce(p_left->'refunds', '[]'::jsonb);
  v_before_decision jsonb := case when jsonb_typeof(p_snapshot->'decision') = 'object' then p_snapshot->'decision' end;
  v_left_decision   jsonb := case when jsonb_typeof(p_left->'decision') = 'object' then p_left->'decision' end;
  v_before_lock     timestamptz := nullif(p_snapshot->>'lockedAt', '')::timestamptz;
  v_left_lock       timestamptz := nullif(p_left->>'lockedAt', '')::timestamptz;
  v_lock_touched    boolean;
  v_final_lock      timestamptz;
  v_conflicts       text[] := '{}';
  v_more            text[];
  v_pub_ids         uuid[];
  v_known_pubs      uuid[];
  v_left_pubs       uuid[];
  v_month_key       text;
  v_locked_now      timestamptz;
  v_item            jsonb;
  v_now             public.deductions_decisions%rowtype;
  v_now_json        jsonb;
  v_want            public.deductions_decisions%rowtype;
begin
  if v_candidate is null then
    raise exception 'phx_restore_deduction_dispute_state: the snapshot names no candidate';
  end if;
  if nullif(p_left->>'candidateId', '')::uuid is distinct from v_candidate then
    raise exception 'phx_restore_deduction_dispute_state: the before-state and the left-state name different candidates';
  end if;

  -- 1. Hold the candidate, its lines, its decision and the case's refunds for the whole undo, so
  --    nothing changes between the comparison below and the writes after it.
  select locked_at, month_key into v_locked_now, v_month_key
  from public.deductions_candidates
  where id = v_candidate
  for update;
  if not found then
    raise exception 'phx_restore_deduction_dispute_state: candidate % no longer exists', v_candidate;
  end if;
  perform 1 from public.deductions_publication_lines where candidate_id = v_candidate for update;
  select * into v_now from public.deductions_decisions where candidate_id = v_candidate for update;
  v_now_json := case when v_now.id is null then null else to_jsonb(v_now) end;
  perform 1 from public.dispute_refunds where case_kind = 'deduction' and case_ref = v_ref for update;

  -- 2. WHAT SOMEBODY ELSE CHANGED SINCE THIS ATTEMPT'S LAST WRITE. A row this attempt changed (it
  --    differs between the before-state and the left-state) must still be exactly as it was left; a row
  --    that is here now but not in the left-state, or was in the before-state and vanished, is somebody
  --    else's. A row this attempt never touched is not compared and not written.
  select coalesce(array_agg(msg order by msg), '{}') into v_more
  from (
    select format('payslip line %s', id) as msg
    from (select l.id, to_jsonb(l) as now_row
            from public.deductions_publication_lines l where l.candidate_id = v_candidate) cur
    full join (select nullif(s->>'id', '')::uuid as id, s as left_row from jsonb_array_elements(v_left_lines) s) lft using (id)
    full join (select nullif(s->>'id', '')::uuid as id, s as before_row from jsonb_array_elements(v_before_lines) s) bef using (id)
    where case
            when lft.left_row is null then true
            when lft.left_row is distinct from bef.before_row then cur.now_row is distinct from lft.left_row
            else false
          end
  ) q;
  v_conflicts := v_conflicts || v_more;

  if v_left_decision is distinct from v_before_decision and v_now_json is distinct from v_left_decision then
    v_conflicts := v_conflicts || array['the decision'];
  end if;

  select coalesce(array_agg(msg order by msg), '{}') into v_more
  from (
    select format('refund %s', id) as msg
    from (select r.id, to_jsonb(r) as now_row
            from public.dispute_refunds r where r.case_kind = 'deduction' and r.case_ref = v_ref) cur
    full join (select nullif(s->>'id', '')::uuid as id, s as left_row from jsonb_array_elements(v_left_refunds) s) lft using (id)
    full join (select nullif(s->>'id', '')::uuid as id, s as before_row from jsonb_array_elements(v_before_refunds) s) bef using (id)
    where case
            when lft.left_row is null then true
            when lft.left_row is distinct from bef.before_row then cur.now_row is distinct from lft.left_row
            else false
          end
  ) q;
  v_conflicts := v_conflicts || v_more;

  v_lock_touched := v_left_lock is distinct from v_before_lock;
  if v_lock_touched and v_locked_now is distinct from v_left_lock then
    v_conflicts := v_conflicts || array['the publication lock'];
  end if;

  if array_length(v_conflicts, 1) is not null then
    insert into public.deductions_audit (candidate_id, actor_hr_id, action, detail)
    values (
      v_candidate, p_actor, 'dispute_decision_undo_refused',
      jsonb_build_object('conflicts', to_jsonb(v_conflicts), 'restore_to', p_snapshot, 'left', p_left)
    );
    return jsonb_build_object('restored', false, 'conflicts', to_jsonb(v_conflicts), 'publicationsLeftEmpty', '[]'::jsonb);
  end if;

  select coalesce(array_agg((value #>> '{}')::uuid), '{}') into v_known_pubs
  from jsonb_array_elements(coalesce(p_snapshot->'publicationIds', '[]'::jsonb));

  -- Every publication whose totals this undo may move.
  select coalesce(array_agg(distinct x), '{}') into v_pub_ids
  from (
    select l.publication_id as x from public.deductions_publication_lines l where l.candidate_id = v_candidate
    union
    select nullif(s->>'publication_id', '')::uuid from jsonb_array_elements(v_before_lines) s
    union
    select p.id from public.deductions_publications p
     where p.month_key = v_month_key and not (p.id = any (v_known_pubs))
  ) q
  where x is not null;

  -- 3. Lines this attempt pushed are removed; lines it withdrew or superseded are set back, withdrawn
  --    ones first so the one-active-line index never sees two. Only this candidate's lines.
  delete from public.deductions_publication_lines l
   where l.candidate_id = v_candidate
     and exists (select 1 from jsonb_array_elements(v_left_lines) s where nullif(s->>'id', '')::uuid = l.id)
     and not exists (select 1 from jsonb_array_elements(v_before_lines) s where nullif(s->>'id', '')::uuid = l.id);

  for v_item in
    select b.value
      from jsonb_array_elements(v_before_lines) b
      join jsonb_array_elements(v_left_lines) a on a.value->>'id' = b.value->>'id'
     where a.value is distinct from b.value
     order by (b.value->>'line_status' = 'active')
  loop
    update public.deductions_publication_lines l
       set line_status           = r.line_status,
           superseded_by_line_id = r.superseded_by_line_id,
           notified_at           = r.notified_at,
           notification_status   = r.notification_status
      from jsonb_populate_record(null::public.deductions_publication_lines, v_item) r
     where l.id = r.id
       and l.candidate_id = v_candidate;
  end loop;

  -- 4. The decision, only where this attempt changed it. Written through the table, so
  --    phx_deductions_decisions_history records an update or an insert; a decision on a LOCKED
  --    candidate is refused by phx_deductions_decisions_refuse_locked, so the lock comes off first and
  --    goes back in step 6.
  if v_left_decision is distinct from v_before_decision then
    if v_locked_now is not null then
      update public.deductions_candidates set locked_at = null where id = v_candidate;
    end if;
    if v_before_decision is null then
      delete from public.deductions_decisions where candidate_id = v_candidate and id = v_now.id;
      -- The history trigger records inserts and updates only, so the removal is written here, in the
      -- trigger's own row shape (20261113151739_deduction_decision_history.sql), in this transaction.
      insert into public.deductions_audit (candidate_id, actor_hr_id, action, detail)
      values (
        v_candidate,
        p_actor,
        'decision_removed',
        jsonb_build_object(
          'decision_id', v_now.id,
          'changed_fields', (select coalesce(jsonb_agg(k), '[]'::jsonb) from unnest(deciding) k
                              where jsonb_typeof(v_now_json -> k) <> 'null'),
          'before', (select jsonb_object_agg(k, v_now_json -> k) from unnest(deciding) k),
          'after', null,
          'decided_at', v_now.decided_at,
          'actor_role_at_decision', v_now.actor_role_at_decision,
          'removed_by', 'phx_restore_deduction_dispute_state'
        )
      );
    else
      v_want := jsonb_populate_record(null::public.deductions_decisions, v_before_decision);
      if v_now.id is null then
        insert into public.deductions_decisions select v_want.*;
      else
        update public.deductions_decisions
           set decision_status        = v_want.decision_status,
               decision_reason        = v_want.decision_reason,
               hr_note                = v_want.hr_note,
               applied_value          = v_want.applied_value,
               applied_amount         = v_want.applied_amount,
               applied_dates          = v_want.applied_dates,
               decided_by             = v_want.decided_by,
               decided_at             = v_want.decided_at,
               actor_role_at_decision = v_want.actor_role_at_decision
         where candidate_id = v_candidate;
      end if;
    end if;
  end if;

  -- 5. The case's refunds: one this attempt recommended is removed; one it cancelled is live again.
  --    Cancelled first, so the one-live-refund-per-case index never sees two. Only this case's refunds.
  delete from public.dispute_refunds r
   where r.case_kind = 'deduction' and r.case_ref = v_ref
     and exists (select 1 from jsonb_array_elements(v_left_refunds) s where nullif(s->>'id', '')::uuid = r.id)
     and not exists (select 1 from jsonb_array_elements(v_before_refunds) s where nullif(s->>'id', '')::uuid = r.id);

  for v_item in
    select b.value
      from jsonb_array_elements(v_before_refunds) b
      join jsonb_array_elements(v_left_refunds) a on a.value->>'id' = b.value->>'id'
     where a.value is distinct from b.value
     order by (b.value->>'status' = 'recommended')
  loop
    update public.dispute_refunds d
       set status             = r.status,
           cancelled_at       = r.cancelled_at,
           cancelled_by_hr_id = r.cancelled_by_hr_id,
           cancel_reason      = r.cancel_reason
      from jsonb_populate_record(null::public.dispute_refunds, v_item) r
     where d.id = r.id
       and d.case_kind = 'deduction' and d.case_ref = v_ref;
  end loop;

  -- 6. The lock: back to the before-state where this attempt changed it, otherwise as it was found.
  v_final_lock := case when v_lock_touched then v_before_lock else v_locked_now end;
  update public.deductions_candidates
     set locked_at = v_final_lock
   where id = v_candidate
     and locked_at is distinct from v_final_lock;

  -- 7. The publications' counts and totals follow their active lines, as push and withdraw keep them.
  update public.deductions_publications p
     set candidate_count = t.candidate_count,
         employee_count  = t.employee_count,
         category_totals = t.category_totals
    from (
      select pub.id,
             (select count(*) from public.deductions_publication_lines a
               where a.publication_id = pub.id and a.line_status = 'active')::integer as candidate_count,
             (select count(distinct a.employee_hr_id_compact) from public.deductions_publication_lines a
               where a.publication_id = pub.id and a.line_status = 'active')::integer as employee_count,
             coalesce((select jsonb_object_agg(c.category, c.amt) from (
                select a.category, round(sum(a.applied_amount), 2) as amt
                from public.deductions_publication_lines a
                where a.publication_id = pub.id and a.line_status = 'active'
                group by a.category) c), '{}'::jsonb) as category_totals
      from public.deductions_publications pub
      where pub.id = any (v_pub_ids)
    ) t
   where p.id = t.id
     and (p.candidate_count, p.employee_count, p.category_totals)
         is distinct from (t.candidate_count, t.employee_count, t.category_totals);

  select coalesce(array_agg(p.id), '{}') into v_left_pubs
  from public.deductions_publications p
  where p.month_key = v_month_key and not (p.id = any (v_known_pubs));

  insert into public.deductions_audit (candidate_id, actor_hr_id, action, detail)
  values (
    v_candidate, p_actor, 'dispute_decision_undone',
    jsonb_build_object('restored_to', p_snapshot, 'left', p_left, 'publications_left_empty', to_jsonb(v_left_pubs))
  );

  return jsonb_build_object('restored', true, 'conflicts', '[]'::jsonb, 'publicationsLeftEmpty', to_jsonb(v_left_pubs));
end;
$$;

ALTER FUNCTION public.phx_restore_deduction_dispute_state(p_snapshot jsonb, p_left jsonb, p_actor text) OWNER TO postgres;

--
-- Name: FUNCTION phx_restore_deduction_dispute_state(p_snapshot jsonb, p_left jsonb, p_actor text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_restore_deduction_dispute_state(p_snapshot jsonb, p_left jsonb, p_actor text) IS 'Undo of a deduction dispute decision that failed after its first write (F-PAY-005): puts back the lines, the decision, the refunds and the lock THIS attempt changed, only while each still equals what the attempt left; otherwise refuses whole and names the rows changed by somebody else. One transaction. Writes the decision through the table so its history trigger still fires, and writes the history row for a removed decision itself.';

--
-- Name: phx_restore_employee_after_cancelled_resignation(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_restore_employee_after_cancelled_resignation(p_resignation_id uuid, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_res public.employee_resignations;
  v_emp public.employees;
  v_last_day date;
  v_newer integer;
  v_taken text;
  v_filled text;
  v_span record;
  v_seats text[] := array[]::text[];
  v_cancelled text[] := array[]::text[];
  v_today date := (now() at time zone 'Africa/Cairo')::date;
  v_rehired text;
  v_actor text := coalesce(nullif(btrim(p_actor), ''), 'system');
begin
  select * into v_res from public.employee_resignations where id = p_resignation_id for update;
  if not found then
    raise exception 'restore: resignation % not found', p_resignation_id;
  end if;
  if lower(coalesce(v_res.status, v_res.exit_status, '')) = 'completed' then
    raise exception 'restore: a completed resignation cannot be cancelled';
  end if;

  select * into v_emp
    from public.employees
   where lower(btrim(hr_id)) = lower(btrim(v_res.employee_hr_id))
   for update;
  if not found then
    raise exception 'restore: employee % not found', v_res.employee_hr_id;
  end if;

  if lower(coalesce(v_emp.employment_status, '')) not in ('resigned', 'terminated') then
    return jsonb_build_object('restored', false, 'reason', 'employee_not_terminal', 'employeeHrId', v_emp.hr_id);
  end if;

  if nullif(btrim(coalesce(v_emp.national_id, '')), '') is not null then
    select string_agg(e.hr_id, ', ' order by e.hr_id) into v_rehired
      from public.employees e
     where btrim(e.national_id) = btrim(v_emp.national_id)
       and lower(btrim(e.hr_id)) <> lower(btrim(v_emp.hr_id))
       and lower(coalesce(e.employment_status, '')) not in
         ('resigned', 'terminated', 'declined_offer', 'historical_payroll_record', 'system_placeholder');
    if v_rehired is not null then
      raise exception 'restore: % was re-hired as % — cancelling would put the same person on payroll twice; keep the new record, or end it before cancelling',
        v_emp.hr_id, v_rehired;
    end if;
  end if;

  select count(*) into v_newer
    from public.employee_resignations r
   where lower(btrim(r.employee_hr_id)) = lower(btrim(v_emp.hr_id))
     and r.id <> v_res.id
     and r.created_at > v_res.created_at
     and lower(coalesce(r.status, r.exit_status, '')) not in ('cancelled', 'rejected');
  if v_newer > 0 then
    raise exception 'restore: % has a newer exit record — cancel that one instead', v_emp.hr_id;
  end if;

  v_last_day := coalesce(v_res.last_working_date, v_res.effective_date);
  if v_emp.last_working_date is distinct from v_last_day then
    raise exception 'restore: % ended on % on the employee record but this resignation says % — they were taken out by something else',
      v_emp.hr_id, coalesce(v_emp.last_working_date::text, 'no date'), coalesce(v_last_day::text, 'no date');
  end if;

  select string_agg(p.seat_id || ' (now ' || cur.occupant_hr_id || ')', ', ' order by p.seat_id)
    into v_taken
    from au.occupancy_history p
    join au.occupancy_history cur
      on cur.seat_id = p.seat_id and cur.effective_to is null and cur.occupant_hr_id is not null
   where p.occupant_canonical_hr_id = lower(btrim(v_emp.hr_id))
     and p.node_type = 'person'
     and p.effective_to in (v_last_day, v_last_day + 1)
     and cur.occupant_canonical_hr_id <> lower(btrim(v_emp.hr_id));
  if v_taken is not null then
    raise exception 'restore: the seat % left has since been given to someone else: % — move them first', v_emp.hr_id, v_taken;
  end if;

  select string_agg(coalesce(v.vacancy_code, v.id::text) || ' (' || v.filled_by_hr_id || ')', ', ')
    into v_filled
    from public.position_vacancies v
   where (v.id = v_res.vacancy_id or v.replacement_for_hr_id = v_emp.hr_id)
     and lower(coalesce(v.status, 'open')) = 'filled'
     and v.filled_at >= v_res.created_at;
  if v_filled is not null then
    raise exception 'restore: the replacement vacancy for % was already filled: % — move that person first', v_emp.hr_id, v_filled;
  end if;

  with closed as (
    update public.position_vacancies v
       set status = 'cancelled',
           note = concat_ws(E'\n', nullif(v.note, ''),
             format('Cancelled %s: the resignation of %s was cancelled and they are back in this job.', v_today, v_emp.hr_id)),
           updated_at = now()
     where (v.id = v_res.vacancy_id or v.replacement_for_hr_id = v_emp.hr_id)
       and lower(coalesce(v.status, 'open')) = 'open'
    returning coalesce(v.vacancy_code, v.id::text) as code
  )
  select coalesce(array_agg(code order by code), array[]::text[]) into v_cancelled from closed;

  for v_span in
    select ph.occupancy_id as placeholder_id, ph.seat_id, ph.prev_occupancy_id
      from au.occupancy_history ph
      join au.occupancy_history p on p.occupancy_id = ph.prev_occupancy_id
     where ph.effective_to is null
       and ph.occupant_hr_id is null
       and ph.event_type = 'resign'
       and p.occupant_canonical_hr_id = lower(btrim(v_emp.hr_id))
       and p.effective_to = ph.effective_from
       and ph.effective_from in (v_last_day, v_last_day + 1)
     order by ph.seat_id
  loop
    delete from au.occupancy_history where occupancy_id = v_span.placeholder_id;
    update au.occupancy_history set effective_to = null where occupancy_id = v_span.prev_occupancy_id;
    perform au.sync_area_state_for_seat(v_span.seat_id, 'vacant_will_hire', 'occupied');
    v_seats := v_seats || v_span.seat_id::text;
  end loop;

  perform set_config('request.phx_allow_terminal_employee_reactivation', 'on', true);
  update public.employees
     set employment_status = 'active',
         payroll_eligible = true,
         organogram_visible = true,
         exit_reason = null,
         exit_status = null,
         exit_category = null,
         last_working_date = null,
         resignation_date = null,
         crm_id = coalesce(crm_id, v_res.crm_id_before),
         updated_at = now()
   where hr_id = v_emp.hr_id;
  perform set_config('request.phx_allow_terminal_employee_reactivation', '', true);

  update public.app_auth_users set is_active = true, updated_at = now() where hr_id = v_emp.hr_id;
  update public.user_access_profiles set is_active = true, updated_at = now() where hr_id = v_emp.hr_id;

  begin
    insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, new_values)
    values (
      v_actor,
      'employee_resignation_cancel_restore',
      v_emp.hr_id,
      format('Resignation cancelled: %s is active again, on payroll, back on %s', v_emp.hr_id,
        coalesce(nullif(array_to_string(v_seats, ', '), ''), 'no seat')),
      jsonb_build_object(
        'resignationId', v_res.id,
        'lastWorkingDayUndone', v_last_day,
        'seatsRestored', to_jsonb(v_seats),
        'vacanciesCancelled', to_jsonb(v_cancelled),
        'crmIdRestored', v_emp.crm_id is null and v_res.crm_id_before is not null
      )
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'restored', true,
    'employeeHrId', v_emp.hr_id,
    'seatsRestored', to_jsonb(v_seats),
    'vacanciesCancelled', to_jsonb(v_cancelled),
    'crmIdRestored', v_emp.crm_id is null and v_res.crm_id_before is not null
  );
end;
$$;

ALTER FUNCTION public.phx_restore_employee_after_cancelled_resignation(p_resignation_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: phx_resubmit_marketing_request(uuid, text, jsonb, jsonb, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_resubmit_marketing_request(p_request_id uuid, p_resubmitted_by text, p_request jsonb, p_products jsonb, p_pharmacies jsonb, p_steps jsonb, p_resubmitted_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request    marketing_requests%rowtype;
  v_in         marketing_requests%rowtype;
  v_open       marketing_request_approval_steps%rowtype;
  v_planned    integer;
  v_written    integer;
  v_current    integer;
  v_products   jsonb;
  v_pharmacies jsonb;
begin
  -- Serialise against a concurrent resubmit, decision, cancel or reopen on the same request. A
  -- second resubmit WAITS here, then finds the request no longer `returned` and is refused below.
  select * into v_request from marketing_requests where id = p_request_id for update;
  if not found then
    raise exception 'marketing_request_not_found: %', p_request_id
      using errcode = 'no_data_found';
  end if;

  if v_request.status <> 'returned' then
    raise exception 'marketing_request_not_returned: % is %', p_request_id, v_request.status
      using errcode = 'check_violation';
  end if;

  if lower(btrim(coalesce(v_request.requester_hr_id, ''))) <> lower(btrim(coalesce(p_resubmitted_by, ''))) then
    raise exception 'marketing_resubmit_not_requester: % did not raise %', p_resubmitted_by, p_request_id
      using errcode = 'insufficient_privilege';
  end if;

  if p_products is null or jsonb_typeof(p_products) <> 'array' or jsonb_array_length(p_products) = 0 then
    raise exception 'marketing_resubmit_no_products: a resubmit must carry at least one product'
      using errcode = 'check_violation';
  end if;
  if p_pharmacies is null or jsonb_typeof(p_pharmacies) <> 'array' or jsonb_array_length(p_pharmacies) = 0 then
    raise exception 'marketing_resubmit_no_targets: a resubmit must name at least one target'
      using errcode = 'check_violation';
  end if;
  if p_steps is null or jsonb_typeof(p_steps) <> 'array' or jsonb_array_length(p_steps) = 0 then
    raise exception 'marketing_resubmit_invalid_steps: no approval rung was given to reopen'
      using errcode = 'check_violation';
  end if;

  -- 1. The edited products replace the old ones. `expected_value` is GENERATED ALWAYS, so it is
  --    deliberately not in the column list.
  delete from marketing_request_products where request_id = p_request_id;
  insert into marketing_request_products
    (request_id, product_id, product_name_snapshot, line_snapshot,
     factory_price_snapshot, forecast_quantity, value_share)
  select p_request_id, r.product_id, r.product_name_snapshot, r.line_snapshot,
         r.factory_price_snapshot, r.forecast_quantity, r.value_share
  from jsonb_populate_recordset(null::marketing_request_products, p_products) r;

  -- 2. The edited targets replace the old ones. `tracking_status` takes its column default.
  delete from marketing_request_pharmacies where request_id = p_request_id;
  insert into marketing_request_pharmacies
    (request_id, pharmacy_id, distributor_code_id, notes)
  select p_request_id, r.pharmacy_id, r.distributor_code_id, r.notes
  from jsonb_populate_recordset(null::marketing_request_pharmacies, p_pharmacies) r;

  -- 3. Rewrite the rungs the plan names: the first real gate `current`, every other gate `pending`,
  --    every earlier decision cleared. Only gating rungs of THIS request are touched - a CC row or a
  --    rung of another request in the list matches nothing, and the count check below refuses it.
  v_planned := jsonb_array_length(p_steps);
  update marketing_request_approval_steps s set
    status            = x.status,
    decision_at       = null,
    decision_by_hr_id = null,
    decision_note     = null,
    updated_at        = p_resubmitted_at
  from jsonb_to_recordset(p_steps) as x("stepId" uuid, status text)
  where s.id         = x."stepId"
    and s.request_id = p_request_id
    and s.is_cc      = false
    and x.status in ('current', 'pending');
  get diagnostics v_written = row_count;

  if v_written <> v_planned then
    raise exception 'marketing_resubmit_invalid_steps: % rung(s) planned, % matched this request', v_planned, v_written
      using errcode = 'check_violation';
  end if;

  -- 4. The invariant this whole function exists to keep: a request that goes back into
  --    `pending_approval` has exactly ONE gating rung in `current`. Zero strands it (nobody can
  --    decide it); two lets two people decide the same step. Raising here rolls back everything above.
  select count(*) into v_current
  from marketing_request_approval_steps
  where request_id = p_request_id and is_cc = false and status = 'current';
  if v_current <> 1 then
    raise exception 'marketing_resubmit_no_single_current_step: % gating rung(s) would be current', v_current
      using errcode = 'check_violation';
  end if;

  select * into v_open
  from marketing_request_approval_steps
  where request_id = p_request_id and is_cc = false and status = 'current';

  -- 5. The request itself. Its editable columns arrive as one jsonb object and are read through
  --    `jsonb_populate_record`, so each is cast to its real column type; a NOT NULL column the
  --    caller left out fails the whole transaction instead of being written as NULL.
  v_in := jsonb_populate_record(null::marketing_requests, p_request);
  update marketing_requests set
    area_id                = v_in.area_id,
    customer_contact_id    = v_in.customer_contact_id,
    customer_id            = v_in.customer_id,
    estimated_cost         = v_in.estimated_cost,
    expected_roi_value     = v_in.expected_roi_value,
    line_id                = v_in.line_id,
    notes                  = v_in.notes,
    other_request_type     = v_in.other_request_type,
    pay_date               = v_in.pay_date,
    request_type_id        = v_in.request_type_id,
    roi_duration_months    = v_in.roi_duration_months,
    roi_status             = v_in.roi_status,
    returned_at            = null,
    returned_step_sequence = null,
    status                 = 'pending_approval',
    submitted_at           = p_resubmitted_at,
    updated_at             = p_resubmitted_at,
    -- the stored requester id, not the argument: the match above ignores letter case, but the
    -- foreign key to employees does not
    updated_by_hr_id       = v_request.requester_hr_id
  where id = p_request_id
  returning * into v_request;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.created_at, p.id), '[]'::jsonb)
    into v_products
  from marketing_request_products p where p.request_id = p_request_id;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.created_at, p.id), '[]'::jsonb)
    into v_pharmacies
  from marketing_request_pharmacies p where p.request_id = p_request_id;

  return jsonb_build_object(
    'request',     to_jsonb(v_request),
    'currentStep', to_jsonb(v_open),
    'products',    v_products,
    'pharmacies',  v_pharmacies
  );
end;
$$;

ALTER FUNCTION public.phx_resubmit_marketing_request(p_request_id uuid, p_resubmitted_by text, p_request jsonb, p_products jsonb, p_pharmacies jsonb, p_steps jsonb, p_resubmitted_at timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION phx_resubmit_marketing_request(p_request_id uuid, p_resubmitted_by text, p_request jsonb, p_products jsonb, p_pharmacies jsonb, p_steps jsonb, p_resubmitted_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_resubmit_marketing_request(p_request_id uuid, p_resubmitted_by text, p_request jsonb, p_products jsonb, p_pharmacies jsonb, p_steps jsonb, p_resubmitted_at timestamp with time zone) IS 'Puts an edited, returned marketing request back into the approval chain in one transaction: replaces its products and targets, rewrites the approval rungs the service planned, and refuses to commit unless exactly one gating rung is current. The restart rule lives in the service (resubmit-rule.ts); the requester-only and customer-scope checks live there too, and the requester check is repeated here.';

--
-- Name: phx_revoke_departed_employee_access(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_revoke_departed_employee_access() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_logins integer := 0;
  v_profiles integer := 0;
  v_revoked text[] := '{}';
begin
  with departed as (
    select lower(btrim(e.hr_id)) as hr_id
    from public.employees e
    where lower(btrim(coalesce(e.employment_status, ''))) in ('resigned', 'terminated', 'not_renewed')
      and e.last_working_date is not null
      and e.last_working_date <= (now() at time zone 'Africa/Cairo')::date
  ),
  revoked as (
    update public.app_auth_users a
    set is_active = false, updated_at = now()
    from departed d
    where lower(btrim(a.hr_id)) = d.hr_id
      and a.is_active
    returning a.hr_id
  )
  select coalesce(array_agg(r.hr_id order by r.hr_id), '{}') into v_revoked from revoked r;
  v_logins := coalesce(array_length(v_revoked, 1), 0);
  with departed as (
    select lower(btrim(e.hr_id)) as hr_id
    from public.employees e
    where lower(btrim(coalesce(e.employment_status, ''))) in ('resigned', 'terminated', 'not_renewed')
      and e.last_working_date is not null
      and e.last_working_date <= (now() at time zone 'Africa/Cairo')::date
  )
  update public.user_access_profiles u
  set is_active = false, updated_at = now()
  from departed d
  where lower(btrim(u.hr_id)) = d.hr_id
    and u.is_active;
  get diagnostics v_profiles = row_count;
  return jsonb_build_object(
    'logins_revoked', v_logins,
    'access_profiles_revoked', v_profiles,
    'revoked_hr_ids', to_jsonb(v_revoked)
  );
end;
$$;

ALTER FUNCTION public.phx_revoke_departed_employee_access() OWNER TO postgres;

