--
-- Name: phx_sales_pharmacy_code_sync_preflight(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sales_pharmacy_code_sync_preflight() RETURNS TABLE(ambiguous_pairs integer, would_retire integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    (
      select count(*)::integer
      from (
        select 1
        from public.marketing_pharmacy_code_references r
        group by r.distributor_id, r.normalized_pharmacy_code
        having count(*) > 1
      ) pairs
    ),
    (
      select count(*)::integer
      from public.marketing_pharmacy_code_references r
      where r.source_file = 'source_of_sales_customer_map'
        and not exists (
          select 1 from public.phx_v_sales_pharmacy_code_candidates c
          where c.distributor_id = r.distributor_id
            and c.normalized_pharmacy_code = r.normalized_pharmacy_code
        )
        and not exists (
          select 1 from public.phx_v_sales_pharmacy_code_candidates c2
          where c2.normalized_pharmacy_code = r.normalized_pharmacy_code
        )
        and not exists (
          select 1 from public.marketing_pharmacy_distributor_codes dc
          where dc.reference_id = r.id
        )
    );
$$;

ALTER FUNCTION public.phx_sales_pharmacy_code_sync_preflight() OWNER TO postgres;

--
-- Name: FUNCTION phx_sales_pharmacy_code_sync_preflight(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_sales_pharmacy_code_sync_preflight() IS 'Read-only counts for the nightly pharmacy-code sync: duplicated (distributor, code) pairs, and what the next retirement pass would delete. Same predicate as the sync function. Server-only (service_role).';

