--
-- Name: phx_sales_vs_target_cache_token(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sales_vs_target_cache_token() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'au', 'public'
    SET statement_timeout TO '45s'
    AS $$
  select md5(concat_ws('|',
    au.f_attribution_config_fingerprint(),
    (select coalesce(sum(hashtextextended(o.*::text, 0)), 0)::text || ':' || count(*)::text
       from au.occupancy_history o),
    (select coalesce(sum(hashtextextended(t.*::text, 0)), 0)::text || ':' || count(*)::text
       from au.monthly_targets t),
    (select coalesce(sum(hashtextextended(m.*::text, 0)), 0)::text || ':' || count(*)::text
       from au.monthly_attribution_rollup_meta m),
    (now() at time zone 'Africa/Cairo')::date::text
  ));
$$;

ALTER FUNCTION public.phx_sales_vs_target_cache_token() OWNER TO postgres;

--
-- Name: FUNCTION phx_sales_vs_target_cache_token(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_sales_vs_target_cache_token() IS 'Single-round-trip freshness stamp for the Sales-vs-Target achievement range cache. Hashes the attribution config fingerprint + occupancy_history + monthly_targets + monthly_attribution_rollup_meta + today''s Cairo date, so the app can fold it into an unstable_cache key and get self-invalidating caching of phx_sales_vs_target_range without hunting every org/seat/target write path. Read-only.';

