--
-- Name: phx_save_attendance_policy(bigint, text, text, text, text, text, integer, date, date, boolean, smallint[], jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_save_attendance_policy(p_id bigint, p_policy_name text, p_target_type text, p_target_value text, p_sched_start text, p_sched_end text, p_grace_minutes integer, p_effective_from date, p_effective_to date, p_is_active boolean, p_weekdays smallint[], p_rules jsonb, p_now timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id bigint;
BEGIN
  IF p_id IS NOT NULL THEN
    UPDATE attendance_policy_groups SET
      policy_name      = p_policy_name,
      target_type      = p_target_type,
      target_value     = p_target_value,
      scheduled_start  = p_sched_start::time,
      scheduled_end    = p_sched_end::time,
      grace_minutes    = p_grace_minutes,
      effective_from   = p_effective_from,
      effective_to     = p_effective_to,
      is_active        = p_is_active,
      working_weekdays = p_weekdays,
      updated_at       = p_now
    WHERE id = p_id;
    v_id := p_id;
  ELSE
    INSERT INTO attendance_policy_groups (
      policy_name, target_type, target_value, scheduled_start, scheduled_end,
      grace_minutes, effective_from, effective_to, is_active, working_weekdays,
      created_at, updated_at
    ) VALUES (
      p_policy_name, p_target_type, p_target_value,
      p_sched_start::time, p_sched_end::time,
      p_grace_minutes, p_effective_from, p_effective_to, p_is_active, p_weekdays,
      p_now, p_now
    )
    RETURNING id INTO v_id;
  END IF;

  -- Atomically replace rules — the delete+insert pair is inside this transaction,
  -- so there is no window where the policy can have zero rules.
  DELETE FROM attendance_policy_rules WHERE policy_id = v_id;

  INSERT INTO attendance_policy_rules (
    policy_id, event_type, from_minutes, to_minutes, recommended_action,
    deduction_days, deduction_value, is_active, sort_order, updated_at
  )
  SELECT
    v_id,
    (r->>'event_type')::text,
    NULLIF(r->>'from_minutes', '')::integer,
    NULLIF(r->>'to_minutes',   '')::integer,
    (r->>'recommended_action')::text,
    NULLIF(r->>'deduction_days',  '')::numeric,
    NULLIF(r->>'deduction_value', '')::numeric,
    COALESCE((r->>'is_active')::boolean, true),
    (r->>'sort_order')::integer,
    p_now
  FROM jsonb_array_elements(p_rules) AS r
  WHERE (r->>'event_type') IS NOT NULL;

  RETURN v_id;
END;
$$;

ALTER FUNCTION public.phx_save_attendance_policy(p_id bigint, p_policy_name text, p_target_type text, p_target_value text, p_sched_start text, p_sched_end text, p_grace_minutes integer, p_effective_from date, p_effective_to date, p_is_active boolean, p_weekdays smallint[], p_rules jsonb, p_now timestamp with time zone) OWNER TO postgres;

--
-- Name: phx_search_direct_order_customers(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_search_direct_order_customers(p_query text, p_distributor_code text DEFAULT NULL::text, p_limit integer DEFAULT 30) RETURNS TABLE(source text, distributor_code text, customer_code text, customer_name text, address text, brick_id text, area_code text, region_code text, phoenix_pharmacy_code text, verification_status text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  with probe as (
    select
      btrim(coalesce(p_query, ''))         as raw,
      public.phx_normalize_arabic(p_query) as norm
  ),
  probe_kind as (
    select
      p0.raw,
      p0.norm,
      (p0.raw ~ U&'^[0-9A-Za-z\0621-\064A]{1,2}$') as short_probe,
      array['c:' || lower(p0.raw)]
        || case when p0.norm is not null then array['n:' || lower(p0.norm)] else array[]::text[] end as keys
    from probe p0
  ),
  hits as (
    select
      'directory'::text     as source,
      m.distributor_code,
      m.customer_code,
      m.customer_name,
      m.address,
      m.brick_id,
      m.area_code,
      m.region_code,
      null::text            as phoenix_pharmacy_code,
      null::text            as verification_status,
      (m.customer_code = p.raw)              as exact_code,
      (m.customer_code ilike p.raw || '%')   as prefix_code
    from public.source_of_sales_customer_map m, probe_kind p
    where m.active
      and p.raw <> ''
      and not p.short_probe
      and (p_distributor_code is null or m.distributor_code = p_distributor_code)
      and (
        m.customer_code ilike p.raw || '%'
        or m.customer_code ilike '%' || p.raw || '%'
        or (p.norm is not null
            and public.phx_normalize_arabic(m.customer_name) ilike '%' || p.norm || '%')
      )

    union all

    select
      'directory'::text     as source,
      m.distributor_code,
      m.customer_code,
      m.customer_name,
      m.address,
      m.brick_id,
      m.area_code,
      m.region_code,
      null::text            as phoenix_pharmacy_code,
      null::text            as verification_status,
      (m.customer_code = p.raw)              as exact_code,
      (m.customer_code ilike p.raw || '%')   as prefix_code
    from public.source_of_sales_customer_map m, probe_kind p
    where m.active
      and p.raw <> ''
      and p.short_probe
      and (p_distributor_code is null or m.distributor_code = p_distributor_code)
      and public.phx_direct_order_search_keys(m.customer_code, m.customer_name) && p.keys

    union all

    select
      'phoenix'::text       as source,
      c.distributor_code,
      c.customer_code,
      ph.pharmacy_name      as customer_name,
      ph.pharmacy_address   as address,
      coalesce(c.mapped_brick_id,  ph.brick_id)   as brick_id,
      coalesce(c.mapped_area_code, ph.area_code)  as area_code,
      coalesce(c.mapped_region_code, ph.region_code) as region_code,
      ph.phoenix_pharmacy_code,
      ph.verification_status,
      (c.customer_code = p.raw)              as exact_code,
      (c.customer_code ilike p.raw || '%')   as prefix_code
    from public.direct_order_pharmacies ph
    left join public.direct_order_pharmacy_distributor_codes c on c.pharmacy_id = ph.id
    cross join probe_kind p
    where ph.active
      and p.raw <> ''
      and (p_distributor_code is null or c.distributor_code = p_distributor_code)
      and (
        c.customer_code ilike p.raw || '%'
        or c.customer_code ilike '%' || p.raw || '%'
        or ph.phoenix_pharmacy_code ilike '%' || p.raw || '%'
        or (p.norm is not null
            and public.phx_normalize_arabic(ph.pharmacy_name) ilike '%' || p.norm || '%')
      )
  )
  select h.source, h.distributor_code, h.customer_code, h.customer_name, h.address,
         h.brick_id, h.area_code, h.region_code, h.phoenix_pharmacy_code, h.verification_status
  from hits h
  order by
    (h.source = 'phoenix') desc,
    h.exact_code desc nulls last,
    h.prefix_code desc nulls last,
    (h.customer_name is not null) desc,
    h.customer_name asc nulls last,
    h.customer_code asc nulls last
  limit least(greatest(coalesce(p_limit, 30), 1), 100);
$_$;

ALTER FUNCTION public.phx_search_direct_order_customers(p_query text, p_distributor_code text, p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION phx_search_direct_order_customers(p_query text, p_distributor_code text, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_search_direct_order_customers(p_query text, p_distributor_code text, p_limit integer) IS 'Type-ahead over the SoS customer directory for the direct-order form. Matches customer_code (prefix, then contains) OR the Arabic-normalized customer_name. Unnamed customers ARE returned -- the caller labels them "(no name on file)" rather than hiding them. The direct-orders service applies the caller''s area scope to these rows; this function does not.';

--
-- Name: phx_seat_start_follows_hire_date(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_seat_start_follows_hire_date() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_span record;
begin
  for v_span in
    select oh.occupancy_id, oh.seat_id, oh.effective_from, oh.prev_occupancy_id
      from au.occupancy_history oh
     where oh.occupant_canonical_hr_id = lower(btrim(new.hr_id))
       and oh.effective_to is null
       and oh.node_type = 'person'
       and oh.event_type = 'hire'
       and oh.source_system = 'hire_rpc'
       and oh.effective_from is distinct from new.hire_date
       and (old.hire_date is null or oh.effective_from = old.hire_date)
  loop
    begin
      update au.occupancy_history
         set effective_from = new.hire_date
       where occupancy_id = v_span.occupancy_id;

      update au.occupancy_history p
         set effective_to = greatest(new.hire_date, p.effective_from)
       where p.occupancy_id = v_span.prev_occupancy_id
         and p.node_type = 'vacant_placeholder';

      insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, old_values, new_values)
      values ('system', 'au_seat_start_moved', new.hr_id,
        format('Seat %s start moved from %s to %s with the Employee Master hire date',
          v_span.seat_id, v_span.effective_from, new.hire_date),
        jsonb_build_object('seatId', v_span.seat_id, 'effectiveFrom', v_span.effective_from),
        jsonb_build_object('seatId', v_span.seat_id, 'effectiveFrom', new.hire_date));
    exception when others then
      raise warning 'phx_seat_start_follows_hire_date: seat % for % failed: %', v_span.seat_id, new.hr_id, sqlerrm;
    end;
  end loop;

  return null;
exception when others then
  raise warning 'phx_seat_start_follows_hire_date: % failed: %', new.hr_id, sqlerrm;
  return null;
end;
$$;

ALTER FUNCTION public.phx_seat_start_follows_hire_date() OWNER TO postgres;

--
-- Name: phx_sos_distinct_distributors(text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sos_distinct_distributors(p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[]) RETURNS TABLE(distributor_code text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '10s'
    AS $$
  with recursive codes(code) as (
    (
      select f.distributor_code
      from public.source_of_sales_fact_rollup f
      where f.distributor_code is not null
      order by f.distributor_code
      limit 1
    )
    union all
    select (
      select f.distributor_code
      from public.source_of_sales_fact_rollup f
      where f.distributor_code > c.code
      order by f.distributor_code
      limit 1
    )
    from codes c
    where c.code is not null
  ),
  wanted as (
    select array(select lower(btrim(x)) from unnest(p_lines) as x) as lines,
           array(select upper(btrim(x)) from unnest(p_regions) as x) as regions
  )
  select c.code
  from codes c
  cross join wanted w
  -- A NULL array matched nothing before (NULL OR false), so it still returns nothing.
  where c.code is not null
    and p_lines is not null
    and p_regions is not null
    and case
      when cardinality(p_lines) > 0 and cardinality(p_regions) > 0 then exists (
        select 1 from public.source_of_sales_fact_rollup f
        where f.distributor_code = c.code
          and lower(btrim(coalesce(f.official_line, ''))) = any (w.lines)
          and upper(btrim(coalesce(f.region_code, ''))) = any (w.regions))
      when cardinality(p_lines) > 0 then exists (
        select 1 from public.source_of_sales_fact_rollup f
        where f.distributor_code = c.code
          and lower(btrim(coalesce(f.official_line, ''))) = any (w.lines))
      when cardinality(p_regions) > 0 then exists (
        select 1 from public.source_of_sales_fact_rollup f
        where f.distributor_code = c.code
          and upper(btrim(coalesce(f.region_code, ''))) = any (w.regions))
      else true
    end
  union all
  -- The old DISTINCT also returned one NULL code when a matching row had none (0 such rows on
  -- production, 2026-09-17); kept so the two bodies agree on every table, not just today's.
  select null::text
  from wanted w
  where p_lines is not null
    and p_regions is not null
    and exists (
      select 1 from public.source_of_sales_fact_rollup f
      where f.distributor_code is null
        and (cardinality(p_lines) = 0 or lower(btrim(coalesce(f.official_line, ''))) = any (w.lines))
        and (cardinality(p_regions) = 0 or upper(btrim(coalesce(f.region_code, ''))) = any (w.regions)));
$$;

ALTER FUNCTION public.phx_sos_distinct_distributors(p_lines text[], p_regions text[]) OWNER TO postgres;

--
-- Name: phx_sos_geo_aggregates_without_restricted(uuid[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sos_geo_aggregates_without_restricted(p_batch_ids uuid[], p_exclude_codes text[] DEFAULT '{LA003,LA004,SS001}'::text[]) RETURNS TABLE(group_type text, group_key text, group_label text, group_code text, official_line text, row_count bigint, total_qty numeric, total_bonus_qty numeric, total_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
  with excluded as materialized (
    select upper(btrim(c)) as code
    from unnest(coalesce(p_exclude_codes, '{}'::text[])) as c
    where btrim(c) <> ''
  ),
  base as materialized (
    select
      r.batch_id,
      r.region_code,
      r.region_name,
      r.area_code,
      r.area_name,
      r.brick_id,
      r.official_line,
      r.qty,
      r.bonus_qty,
      r.value
    from source_of_sales_import_rows r
    where r.batch_id = any(p_batch_ids)
      and r.validation_state = 'valid'
      and (
        not exists (select 1 from excluded)
        or upper(btrim(coalesce(r.product_code, ''))) not in (select code from excluded)
      )
  )
  -- ── Region ───────────────────────────────────────────────────────────────
  select
    'region'::text                                                           as group_type,
    coalesce(region_code, '') || '|' || coalesce(region_name, '')           as group_key,
    coalesce(region_name, region_code, '')                                   as group_label,
    region_code::text                                                        as group_code,
    null::text                                                               as official_line,
    count(*)::bigint                                                         as row_count,
    sum(qty)::numeric                                                        as total_qty,
    sum(bonus_qty)::numeric                                                  as total_bonus_qty,
    sum(value)::numeric                                                      as total_value
  from base
  group by region_code, region_name

  union all

  -- ── Area ─────────────────────────────────────────────────────────────────
  select
    'area'::text,
    coalesce(area_code, '') || '|' || coalesce(area_name, '') || '|' || coalesce(region_code, ''),
    coalesce(area_name, area_code, ''),
    area_code::text,
    coalesce(region_name, region_code)::text,
    count(*)::bigint,
    sum(qty)::numeric,
    sum(bonus_qty)::numeric,
    sum(value)::numeric
  from base
  group by area_code, area_name, region_code, region_name

  union all

  -- ── Brick ────────────────────────────────────────────────────────────────
  -- brick_name is NOT stored in import rows; the JS layer resolves it from
  -- source_of_sales_bricks after the fact (same as for CEO path).
  select
    'brick'::text,
    coalesce(brick_id, '') || '||' || coalesce(area_code, '') || '|' || coalesce(region_code, ''),
    coalesce(brick_id, ''),
    brick_id::text,
    coalesce(area_name, area_code)::text,
    count(*)::bigint,
    sum(qty)::numeric,
    sum(bonus_qty)::numeric,
    sum(value)::numeric
  from base
  group by brick_id, area_code, area_name, region_code
$$;

