--
-- Name: FUNCTION phx_sos_geography_version(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_sos_geography_version() IS 'Monotonic stamp bumped by a statement-level trigger on every table the closing store-split reads for geography. src/lib/sales/closing-store-split-net.ts keys its cache on it, so a direct SQL geography re-stamp can no longer leave the Monthly Closing screen serving an hour-old Office spread.';

--
-- Name: phx_sos_period_drift_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sos_period_drift_count() RETURNS TABLE(batch_period text, row_period text, rows bigint, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select b.period, r.invoice_period, count(*)::bigint, coalesce(sum(r.value), 0)
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b
    on b.id = r.batch_id and b.status = 'validated'
  where coalesce(r.invoice_period, '~') <> coalesce(b.period, '~')
  group by b.period, r.invoice_period
  order by 3 desc;
$$;

ALTER FUNCTION public.phx_sos_period_drift_count() OWNER TO postgres;

--
-- Name: phx_sos_rows_attributed(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sos_rows_attributed(p_period text) RETURNS TABLE(batch_id uuid, invoice_period text, distributor_code text, official_line text, region_code text, area_code text, brick_id text, client_code text, product_code text, product_name text, is_direct boolean, qty numeric, discount numeric, bonus_qty numeric, value numeric, validation_state text, split_applied boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with base as (
    select r.*
    from public.source_of_sales_import_rows r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated' and r.invoice_period = b.period
    where r.invoice_period = p_period
  ),
  roster as (
    select
      ro.client_code, ro.official_line, ro.area_code, ro.region_code, ro.landing_brick_id,
      count(*)     over (partition by ro.client_code, ro.official_line) as n,
      row_number() over (partition by ro.client_code, ro.official_line order by ro.area_code) as rn
    from public.sos_even_split_roster ro
    where ro.period = p_period
  ),
  tagged as (
    select
      base.*,
      (
        select 1 from public.sos_even_split_customers c
        join roster ro
          on ro.client_code = c.client_code and ro.official_line = c.official_line
        where c.active
          and c.client_code = base.client_code
          and upper(c.official_line) = upper(btrim(coalesce(base.official_line, '')))
        limit 1
      ) is not null
      and coalesce(base.is_direct, false) = false
      as is_split
    from base
  )
  select
    t.batch_id, t.invoice_period, t.distributor_code, t.official_line,
    t.region_code, t.area_code, t.brick_id, t.client_code,
    t.product_code, t.product_name, coalesce(t.is_direct, false),
    t.qty, t.discount, t.bonus_qty, t.value, t.validation_state,
    false
  from tagged t
  where not t.is_split

  union all

  select
    t.batch_id, t.invoice_period, t.distributor_code, t.official_line,
    ro.region_code, ro.area_code, ro.landing_brick_id, t.client_code,
    t.product_code, t.product_name, false,
    round(t.qty / ro.n, 6)
      + case when ro.rn = 1 then t.qty - round(t.qty / ro.n, 6) * ro.n else 0 end,
    t.discount,
    round(coalesce(t.bonus_qty, 0) / ro.n, 6)
      + case when ro.rn = 1 then coalesce(t.bonus_qty, 0) - round(coalesce(t.bonus_qty, 0) / ro.n, 6) * ro.n else 0 end,
    round(coalesce(t.value, 0) / ro.n, 6)
      + case when ro.rn = 1 then coalesce(t.value, 0) - round(coalesce(t.value, 0) / ro.n, 6) * ro.n else 0 end,
    t.validation_state,
    true
  from tagged t
  join public.sos_even_split_customers c
    on c.client_code = t.client_code
   and upper(c.official_line) = upper(btrim(coalesce(t.official_line, '')))
   and c.active
  join roster ro
    on ro.client_code = c.client_code and ro.official_line = c.official_line
  where t.is_split;
$$;

ALTER FUNCTION public.phx_sos_rows_attributed(p_period text) OWNER TO postgres;

