--
-- Name: phx_stamp_vacancy_seat_from_predecessor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_stamp_vacancy_seat_from_predecessor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_seat_id text;
  v_open_seats integer := 0;
  v_predecessor text := nullif(btrim(coalesce(new.replacement_for_hr_id, '')), '');
begin
  if new.seat_id is not null or v_predecessor is null then
    return new;
  end if;

  select count(*), min(oh.seat_id)
    into v_open_seats, v_seat_id
    from au.occupancy_history oh
   where oh.occupant_canonical_hr_id = lower(v_predecessor)
     and oh.occupant_hr_id is not null
     and oh.effective_to is null;

  if v_open_seats <> 1 then
    v_seat_id := null;
  end if;

  if v_seat_id is null and v_open_seats = 0 then
    v_seat_id := au.f_last_occupied_seat_by_hr_id(v_predecessor);
  end if;

  if v_seat_id is not null and not exists (
    select 1 from public.position_vacancies pv
     where pv.seat_id = v_seat_id
       and lower(coalesce(pv.status, 'open')) = 'open'
       and pv.id is distinct from new.id
  ) then
    new.seat_id := v_seat_id;
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_stamp_vacancy_seat_from_predecessor() OWNER TO postgres;

--
-- Name: phx_suggest_direct_order_pharmacies(text, numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_suggest_direct_order_pharmacies(p_name text, p_min_score numeric DEFAULT 0.35, p_limit integer DEFAULT 5) RETURNS TABLE(distributor_code text, customer_code text, customer_name text, address text, brick_id text, area_code text, region_code text, score numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with probe as (select public.phx_normalize_arabic(p_name) as norm)
  select distinct on (m.distributor_code, m.customer_code)
         m.distributor_code, m.customer_code, m.customer_name, m.address,
         m.brick_id, m.area_code, m.region_code,
         round(extensions.similarity(public.phx_normalize_arabic(m.customer_name), p.norm)::numeric, 3) as score
  from public.source_of_sales_customer_map m, probe p
  where m.active
    and p.norm is not null
    and m.customer_name is not null
    -- A nameless customer cannot be suggested BY NAME: offering a bare code as "did you mean"
    -- gives the rep nothing to recognise, and a suggestion they cannot judge is noise.
    and btrim(m.customer_name) <> ''
    and extensions.similarity(public.phx_normalize_arabic(m.customer_name), p.norm) >= coalesce(p_min_score, 0.35)
  order by m.distributor_code, m.customer_code, score desc
  limit least(greatest(coalesce(p_limit, 5), 1), 20);
$$;

ALTER FUNCTION public.phx_suggest_direct_order_pharmacies(p_name text, p_min_score numeric, p_limit integer) OWNER TO postgres;

