-- Name: FUNCTION phx_suggest_direct_order_pharmacies(p_name text, p_min_score numeric, p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_suggest_direct_order_pharmacies(p_name text, p_min_score numeric, p_limit integer) IS 'Did-you-mean suggestions for a claimed pharmacy name (spec B4). Arabic-normalized trigram similarity — deterministic on purpose, because a suggestion the rep was shown and refused is recorded as evidence and must reproduce identically later.';

--
-- Name: phx_supersede_daily_deductions(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_supersede_daily_deductions(p_publication_id uuid, p_actor text) RETURNS public.daily_deductions_publications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_publication public.daily_deductions_publications;
begin
  if btrim(coalesce(p_actor, '')) = '' then
    raise exception 'phx_supersede_daily_deductions: an actor is required';
  end if;

  update public.daily_deductions_publications
     set status = 'superseded', superseded_at = coalesce(superseded_at, now())
   where id = p_publication_id
   returning * into v_publication;

  if not found then
    raise exception 'phx_supersede_daily_deductions: publication % not found', p_publication_id;
  end if;
  return v_publication;
end;
$$;

ALTER FUNCTION public.phx_supersede_daily_deductions(p_publication_id uuid, p_actor text) OWNER TO postgres;

