-- Name: FUNCTION phx_supersede_daily_deductions(p_publication_id uuid, p_actor text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_supersede_daily_deductions(p_publication_id uuid, p_actor text) IS 'Daily Deductions module: mark a snapshot superseded (withdraw it) without publishing a replacement. SECURITY DEFINER, service_role only.';

--
-- Name: phx_sync_open_vacancy_managers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sync_open_vacancy_managers() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_changed integer;
  v_adopted integer;
begin
  with want as (
    select x.id, m.manager_hr_id, m.manager_name, m.region_name
      from public.position_vacancies x
     cross join lateral public.phx_vacancy_seat_manager(x.seat_id) m
     where lower(coalesce(x.status, 'open')) = 'open'
       and x.seat_id is not null
       and (
         x.manager_hr_id is distinct from m.manager_hr_id
         or x.manager_name is distinct from m.manager_name
         or x.region_name is distinct from coalesce(m.region_name, x.region_name)
       )
  )
  update public.position_vacancies v
     set manager_hr_id = want.manager_hr_id,
         manager_name = want.manager_name,
         region_name = coalesce(want.region_name, v.region_name),
         updated_at = now()
    from want
   where v.id = want.id;

  get diagnostics v_changed = row_count;

  with want as (
    select x.id, m.manager_hr_id, m.manager_name
      from public.position_vacancies x
     cross join lateral public.phx_vacancy_region_manager(x.line_id, x.region_name) m
     where lower(coalesce(x.status, 'open')) = 'open'
       and x.manager_hr_id is null
       and m.manager_hr_id is not null
  )
  update public.position_vacancies v
     set manager_hr_id = want.manager_hr_id,
         manager_name = want.manager_name,
         updated_at = now()
    from want
   where v.id = want.id;

  get diagnostics v_adopted = row_count;

  return coalesce(v_changed, 0) + coalesce(v_adopted, 0);
end;
$$;

ALTER FUNCTION public.phx_sync_open_vacancy_managers() OWNER TO postgres;

--
-- Name: phx_sync_sales_pharmacy_codes_into_marketing(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sync_sales_pharmacy_codes_into_marketing() RETURNS TABLE(distributors_created integer, references_synced integer, references_skipped_existing integer, references_retired integer, references_retained_linked integer, references_held_hidden_vendor integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_distributors_created       integer := 0;
  v_source_pairs               integer := 0;
  v_references_synced          integer := 0;
  v_references_retired         integer := 0;
  v_references_retained_linked integer := 0;
  v_references_held_hidden_vendor integer := 0;
  v_batch uuid := gen_random_uuid();
begin
  -- Ensure every sales distributor that has customer-map rows has a matching marketing
  -- distributor (matched by normalized name; created only when missing). A new vendor is born
  -- HIDDEN (owner, 2026-11-03), so its codes wait until he allows it.
  with sales_distributors as (
    select d.distributor_code, d.distributor_name, d.normalized_distributor_name
    from public.source_of_sales_distributors d
    where d.normalized_distributor_name is not null
      and btrim(d.distributor_name) <> ''
      and exists (
        select 1
        from public.source_of_sales_customer_map m
        where m.distributor_code = d.distributor_code and m.active
      )
  ), created as (
    insert into public.marketing_distributors (distributor_code, display_name, normalized_name, source_name, active)
    select
      'SOS_' || sd.distributor_code,
      sd.distributor_name,
      sd.normalized_distributor_name,
      sd.distributor_name,
      false
    from sales_distributors sd
    where not exists (
      select 1 from public.marketing_distributors md
      where md.normalized_name = sd.normalized_distributor_name
    )
    returning 1
  )
  select count(*) into v_distributors_created from created;

  -- RETIREMENT. Three conditions now, all required:
  --   1. the row is one of ours (source_file);
  --   2. the live map does not justify it under THIS vendor;
  --   3. the live map does not carry the code under ANY vendor  <-- the merge guard, new here;
  --   4. nothing links to it.
  -- Condition 3 is what keeps a merged code alive. Without it this pass deletes the 2,671 rows
  -- the owner's two vendor merges produced, because the map can only ever justify them under the
  -- hidden child vendor they were merged away from.
  with retired as (
    delete from public.marketing_pharmacy_code_references r
    where r.source_file = 'source_of_sales_customer_map'
      and not exists (
        select 1 from public.phx_v_sales_pharmacy_code_candidates c
        where c.distributor_id = r.distributor_id
          and c.normalized_pharmacy_code = r.normalized_pharmacy_code
      )
      and not exists (
        select 1 from public.phx_v_sales_pharmacy_code_candidates c2
        where c2.normalized_pharmacy_code = r.normalized_pharmacy_code
      )
      and not exists (
        select 1 from public.marketing_pharmacy_distributor_codes dc
        where dc.reference_id = r.id
      )
    returning 1
  )
  select count(*) into v_references_retired from retired;

  -- Stale under this vendor but kept: either something links it, or the code is still live
  -- somewhere in the map (the merge case). Reported so the number is never a silent surprise.
  select count(*) into v_references_retained_linked
  from public.marketing_pharmacy_code_references r
  where r.source_file = 'source_of_sales_customer_map'
    and not exists (
      select 1 from public.phx_v_sales_pharmacy_code_candidates c
      where c.distributor_id = r.distributor_id
        and c.normalized_pharmacy_code = r.normalized_pharmacy_code
    );

  -- ADDITIVE INSERT. Unchanged from 20260819210000.
  with inserted as (
    insert into public.marketing_pharmacy_code_references (
      distributor_id,
      raw_distributor_name,
      normalized_distributor_name,
      raw_pharmacy_code,
      raw_pharmacy_address,
      raw_region,
      raw_area,
      source_file,
      source_row,
      import_batch_id
    )
    select
      c.distributor_id,
      c.raw_distributor_name,
      c.normalized_distributor_name,
      c.raw_pharmacy_code,
      c.raw_pharmacy_address,
      c.raw_region,
      c.raw_area,
      'source_of_sales_customer_map',
      c.source_row,
      v_batch
    from public.phx_v_sales_pharmacy_code_candidates c
    where c.distributor_active
      and not exists (
        select 1 from public.marketing_pharmacy_code_references r
        where r.distributor_id = c.distributor_id
          and r.normalized_pharmacy_code = c.normalized_pharmacy_code
      )
      and not exists (
        select 1 from public.marketing_pharmacy_code_references r
        where r.distributor_id = c.distributor_id
          and r.compact_pharmacy_code = c.compact_pharmacy_code
      )
    returning 1
  )
  select count(*) into v_references_synced from inserted;

  select
    count(*) filter (where c.distributor_active),
    count(*) filter (where not c.distributor_active)
  into v_source_pairs, v_references_held_hidden_vendor
  from public.phx_v_sales_pharmacy_code_candidates c;

  return query select
    v_distributors_created,
    v_references_synced,
    greatest(v_source_pairs - v_references_synced, 0),
    v_references_retired,
    v_references_retained_linked,
    v_references_held_hidden_vendor;
end;
$$;

ALTER FUNCTION public.phx_sync_sales_pharmacy_codes_into_marketing() OWNER TO postgres;

--
-- Name: FUNCTION phx_sync_sales_pharmacy_codes_into_marketing(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_sync_sales_pharmacy_codes_into_marketing() IS 'Idempotent: copies source_of_sales_customer_map into marketing_pharmacy_code_references, bridged to a marketing distributor by normalized name. Additive — never inserts a (distributor_id, normalized_pharmacy_code) pair that already exists under ANY source_file, and never inserts under an inactive vendor. A vendor it creates starts hidden until the owner allows it. Retires only its own rows whose code has left the live map ENTIRELY and that nothing references, so a code merged onto another vendor is never deleted. Server-only (service_role).';

--
-- Name: phx_sync_sos_reconciliation(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sync_sos_reconciliation(p_periods text[] DEFAULT NULL::text[]) RETURNS TABLE(official_line text, period text, rollup_total_qty numeric, raw_total_qty numeric, rollup_effective_units numeric, raw_effective_units numeric, rollup_row_count bigint, raw_row_count bigint, geo_mismatch_rows bigint, unrollup_rows bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
  with roll as (
    select
      coalesce(nullif(btrim(r.official_line), ''), 'Unknown') as official_line,
      r.period,
      sum(r.total_qty)       as total_qty,
      sum(r.effective_units) as effective_units,
      sum(r.row_count)::bigint as row_count
    from public.source_of_sales_customer_directory_rollup r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated'
    where (p_periods is null or r.period = any (p_periods))
      and nullif(btrim(r.client_code), '') is not null
    group by 1, 2
  ),
  raw as (
    select
      coalesce(nullif(btrim(r.official_line), ''), 'Unknown') as official_line,
      coalesce(nullif(btrim(r.invoice_period), ''), '')       as period,
      sum(coalesce(r.qty, 0))                                       as total_qty,
      sum(coalesce(r.qty, 0))       as effective_units,
      count(*)::bigint                                              as row_count
    from public.source_of_sales_import_rows r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated'
    where (p_periods is null or coalesce(nullif(btrim(r.invoice_period), ''), '') = any (p_periods))
      and nullif(btrim(r.client_code), '') is not null
    group by 1, 2
  ),
  -- Every validated import row, keyed on the rollup's exact grain so the left join below is
  -- apples-to-apples with phx_refresh_sos_customer_directory_rollup.
  rows_keyed as (
    select
      r.batch_id,
      coalesce(nullif(btrim(r.invoice_period), ''), '')                       as period,
      coalesce(nullif(btrim(r.distributor_code), ''), b.distributor_code, '') as distributor_code,
      nullif(btrim(r.client_code), '')                                        as client_code,
      coalesce(nullif(upper(btrim(r.product_code)), ''), '')                  as product_code,
      coalesce(r.is_direct, false)                                            as is_direct,
      coalesce(nullif(btrim(r.official_line), ''), 'Unknown')                 as official_line,
      nullif(btrim(r.brick_id), '')                                           as brick_id,
      nullif(btrim(r.area_code), '')                                          as area_code,
      nullif(btrim(r.region_code), '')                                        as region_code
    from public.source_of_sales_import_rows r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated'
    where (p_periods is null or coalesce(nullif(btrim(r.invoice_period), ''), '') = any (p_periods))
      and nullif(btrim(r.client_code), '') is not null
  ),
  geo as (
    select
      k.official_line,
      k.period,
      count(*) filter (
        where d.batch_id is not null
          and (   k.brick_id    is distinct from d.brick_id
               or k.area_code   is distinct from d.area_code
               or k.region_code is distinct from d.region_code )
      )::bigint as geo_mismatch_rows,
      count(*) filter (where d.batch_id is null)::bigint as unrollup_rows
    from rows_keyed k
    left join public.source_of_sales_customer_directory_rollup d
      on  d.batch_id         = k.batch_id
      and d.period           = k.period
      and d.distributor_code = k.distributor_code
      and d.client_code      = k.client_code
      and d.product_code     = k.product_code
      and d.is_direct        = k.is_direct
    group by 1, 2
  )
  select
    coalesce(roll.official_line, raw.official_line)  as official_line,
    coalesce(roll.period, raw.period)                as period,
    coalesce(roll.total_qty, 0)                      as rollup_total_qty,
    coalesce(raw.total_qty, 0)                       as raw_total_qty,
    coalesce(roll.effective_units, 0)                as rollup_effective_units,
    coalesce(raw.effective_units, 0)                 as raw_effective_units,
    coalesce(roll.row_count, 0)                      as rollup_row_count,
    coalesce(raw.row_count, 0)                       as raw_row_count,
    coalesce(geo.geo_mismatch_rows, 0)               as geo_mismatch_rows,
    coalesce(geo.unrollup_rows, 0)                   as unrollup_rows
  from roll
  full outer join raw using (official_line, period)
  left join geo
    on  geo.official_line = coalesce(roll.official_line, raw.official_line)
    and geo.period        = coalesce(roll.period, raw.period);
$$;

ALTER FUNCTION public.phx_sync_sos_reconciliation(p_periods text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_sync_sos_reconciliation(p_periods text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_sync_sos_reconciliation(p_periods text[]) IS 'Read-only proof for Territory Sync. Compares the customer-directory rollup against the raw validated import rows per official_line x period: quantities (total_qty, effective_units, row_count) AND geography (geo_mismatch_rows = rows whose brick/area/region differs from their own rollup row; unrollup_rows = rows with no rollup row at all). The geography columns exist because the re-stamp changes ONLY geography, so a quantity-only comparison is invariant under it and certified 4,265 mis-stamped rows as reconciled on 2026-08-31.';

--
-- Name: phx_sync_sos_restamp_import_rows(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sync_sos_restamp_import_rows(p_periods text[] DEFAULT NULL::text[]) RETURNS TABLE(updated_rows integer, affected_batch_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
declare
  v_rows integer := 0;
  v_batches uuid[] := '{}'::uuid[];
begin
  with target as (
    select
      m.distributor_code,
      m.customer_code,
      m.brick_id,
      b.area_code,
      b.region_code,
      a.area_name,
      g.region_name
    from public.source_of_sales_customer_map m
    join public.source_of_sales_bricks b on b.brick_id = m.brick_id
    left join public.source_of_sales_areas a on a.area_code = b.area_code
    left join public.source_of_sales_regions g on g.region_code = b.region_code
    where m.active
      and m.brick_id is not null
  ),
  updated as (
    update public.source_of_sales_import_rows r
    set brick_id = t.brick_id,
        area_code = t.area_code,
        area_name = coalesce(t.area_name, r.area_name),
        region_code = t.region_code,
        region_name = coalesce(t.region_name, r.region_name)
    from target t
    where r.distributor_code = t.distributor_code
      and r.client_code = t.customer_code
      and (   r.brick_id    is distinct from t.brick_id
           or r.area_code   is distinct from t.area_code
           or r.region_code is distinct from t.region_code )
      and (p_periods is null or r.invoice_period = any (p_periods))
    returning r.batch_id
  )
  select count(*), coalesce(array_agg(distinct batch_id), '{}'::uuid[])
    into v_rows, v_batches
  from updated;

  return query select v_rows, v_batches;
end;
$$;

ALTER FUNCTION public.phx_sync_sos_restamp_import_rows(p_periods text[]) OWNER TO postgres;

--
-- Name: phx_sync_sos_run(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_sync_sos_run(p_periods text[] DEFAULT NULL::text[]) RETURNS TABLE(restamped_rows integer, refreshed_batches integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '300s'
    AS $$
declare
  v_rows integer := 0;
  v_batches uuid[] := '{}'::uuid[];
  v_batch uuid;
  v_refreshed integer := 0;
begin
  with target as (
    select
      m.distributor_code,
      m.customer_code,
      m.brick_id,
      b.area_code,
      b.region_code,
      a.area_name,
      g.region_name
    from public.source_of_sales_customer_map m
    join public.source_of_sales_bricks b on b.brick_id = m.brick_id
    left join public.source_of_sales_areas a on a.area_code = b.area_code
    left join public.source_of_sales_regions g on g.region_code = b.region_code
    where m.active
      and m.brick_id is not null
  ),
  updated as (
    update public.source_of_sales_import_rows r
    set brick_id = t.brick_id,
        area_code = t.area_code,
        area_name = coalesce(t.area_name, r.area_name),
        region_code = t.region_code,
        region_name = coalesce(t.region_name, r.region_name)
    from target t
    where r.distributor_code = t.distributor_code
      and r.client_code = t.customer_code
      -- Any of the three CODES, not brick alone: a re-parented brick keeps its id and changes area.
      and (   r.brick_id    is distinct from t.brick_id
           or r.area_code   is distinct from t.area_code
           or r.region_code is distinct from t.region_code )
      and (p_periods is null or r.invoice_period = any (p_periods))
    returning r.batch_id
  )
  select count(*), coalesce(array_agg(distinct batch_id), '{}'::uuid[])
    into v_rows, v_batches
  from updated;

  if array_length(v_batches, 1) is not null then
    foreach v_batch in array v_batches loop
      perform public.phx_refresh_sos_fact_rollup(v_batch);
      perform public.phx_refresh_sos_customer_directory_rollup(v_batch);
      perform public.phx_refresh_marketing_roi_facts(v_batch);
      perform public.phx_refresh_sos_channel_rollup(v_batch);
      perform public.phx_refresh_sos_distributor_product_rollup(v_batch);
      perform public.phx_refresh_monthly_attribution(v_batch);
      -- THE FIX. The dashboard's own aggregate, refreshed from the rows this run just re-stamped,
      -- exactly as phx_finalize_sos_batch does at import time. Without it the six refreshes above
      -- correct every number the closing reads and none of the numbers on screen.
      --
      -- Period-safe: phx_refresh_sos_import_summaries recomputes ONLY from this batch's own rows
      -- (its single outward join is to source_of_sales_bricks, for the brick NAME). It never
      -- resolves geography at the run date, so it cannot re-date a closed month — the period
      -- filtering stays where it already is, on the re-stamp above.
      perform public.phx_refresh_sos_import_summaries(v_batch);
      v_refreshed := v_refreshed + 1;
    end loop;
  end if;

  return query select v_rows, v_refreshed;
end;
$$;

ALTER FUNCTION public.phx_sync_sos_run(p_periods text[]) OWNER TO postgres;

--
-- Name: FUNCTION phx_sync_sos_run(p_periods text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.phx_sync_sos_run(p_periods text[]) IS 'Re-stamps source_of_sales_import_rows from the customer map + brick master, then rebuilds the rollups for every batch touched. The UPDATE fires when the brick OR the area code OR the region code differs — gating on brick alone let an area re-parent (same brick, new area) go un-stamped forever, which stranded 14 rows / EGP 5,274.90 in 2026-07 while the sync reported 0 re-stamped. area_name/region_name are written but deliberately NOT in the predicate: no rollup carries a name. Refreshes SEVEN rollups, not six: source_of_sales_import_summaries is the Source of Sales dashboard''s own aggregate, and it was omitted until 20260905003000 — so a mapping correction rebuilt everything the monthly closing reads and nothing the dashboard reads.';

