--
-- Name: phx_terminal_employee_vacancy_guard_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_terminal_employee_vacancy_guard_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if lower(coalesce(new.employment_status, 'active')) in ('resigned', 'terminated', 'inactive') then
    perform public.phx_ensure_terminal_employee_vacancy(new.hr_id);
  end if;

  return new;
end;
$$;

