--
-- Name: phx_terminate_employee_for_non_renewal(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_terminate_employee_for_non_renewal(p_contract_request_id uuid, p_actor_login_id text) RETURNS TABLE(resignation_id uuid, employee_hr_id text, vacancy_code text, contract_renewal_request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request public.contract_renewal_requests%rowtype;
  v_effective_date date;
  v_submitted_date date := (now() at time zone 'utc')::date;
  v_vacancy_code text;
  v_reason text;
  v_workflow_notes text;
begin
  if p_contract_request_id is null then
    raise exception 'contract_request_id is required';
  end if;
  if coalesce(btrim(p_actor_login_id), '') = '' then
    raise exception 'actor_login_id is required';
  end if;

  -- Lock the renewal request row to avoid racing with concurrent workflow actions.
  select *
    into v_request
    from public.contract_renewal_requests
   where id = p_contract_request_id
   for update;

  if not found then
    raise exception 'contract_renewal_request % not found', p_contract_request_id;
  end if;

  if v_request.status is distinct from 'not_renewed' then
    raise exception 'contract_renewal_request % is not in not_renewed status (current: %)',
      p_contract_request_id, v_request.status;
  end if;

  v_effective_date := coalesce(
    v_request.proposed_end_date,
    v_request.current_renewal_date,
    v_request.requested_renewal_date,
    v_submitted_date
  );

  v_reason := format('Contract not renewed (request %s).', p_contract_request_id::text);
  v_workflow_notes := format(
    'Triggered by contract non-renewal.%scontract_renewal_request_id: %s',
    E'\n',
    p_contract_request_id::text
  );

  -- TODO (staging review): confirm the exact column / argument mapping for
  -- public.phx_resign_employee_and_open_vacancy on the live database. The
  -- existing service-layer call uses the following named arguments:
  --   p_actor, p_effective_date, p_employee_hr_id, p_employee_status,
  --   p_reason, p_submitted_by_hr_id, p_submitted_date, p_vacancy_code,
  --   p_workflow_notes
  -- The wrapper below delegates with the same names. The returned vacancy_code
  -- / resignation_id must be captured from the underlying function's result
  -- shape (verify before applying — adjust the SELECT INTO accordingly).
  perform public.phx_resign_employee_and_open_vacancy(
    p_actor := p_actor_login_id,
    p_effective_date := v_effective_date,
    p_employee_hr_id := v_request.employee_hr_id,
    p_employee_status := 'terminated',
    p_reason := v_reason,
    p_submitted_by_hr_id := p_actor_login_id,
    p_submitted_date := v_submitted_date,
    p_vacancy_code := null,
    p_workflow_notes := v_workflow_notes
  );

  -- Backfill the new traceability column for the resignation row that was just
  -- created by the delegated RPC. We match on the employee + reason marker so
  -- the link is established even if the underlying RPC does not yet expose
  -- the new resignation id directly.
  update public.employee_resignations
     set contract_renewal_request_id = p_contract_request_id
   where employee_hr_id = v_request.employee_hr_id
     and contract_renewal_request_id is null
     and (workflow_notes is not null and workflow_notes like '%' || p_contract_request_id::text || '%')
   returning id, employee_hr_id, vacancy_code, contract_renewal_request_id
        into resignation_id, employee_hr_id, vacancy_code, contract_renewal_request_id;

  return next;
end;
$$;

ALTER FUNCTION public.phx_terminate_employee_for_non_renewal(p_contract_request_id uuid, p_actor_login_id text) OWNER TO postgres;

--
-- Name: phx_territory_area_pharmacies(text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_territory_area_pharmacies(p_area_codes text[], p_periods text[], p_lines text[]) RETURNS TABLE(brick_id text, client_code text, client_name text, official_line text, product_code text, product_name text, period text, units numeric, value numeric, scope_total_units numeric, scope_total_value numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
#variable_conflict use_column
begin
  return query
  with period_price as (
    select d.product_code, d.period,
           public.phx_factory_price(d.product_code, d.period) as period_price
    from (
      select distinct r.product_code, r.period
      from public.source_of_sales_customer_directory_rollup r
      where r.period = any (p_periods)
    ) d
  ),
  filtered as (
    select
      coalesce(nullif(btrim(r.brick_id), ''), '(unmapped)') as brick_id,
      r.client_code,
      r.client_name,
      coalesce(nullif(btrim(r.official_line), ''), 'Unknown') as official_line,
      coalesce(nullif(btrim(r.product_code), ''), '') as product_code,
      coalesce(nullif(btrim(p.product_name), ''), 'Unknown product') as product_name,
      r.period,
      r.latest_row_created_at,
      r.total_qty as row_units,
      case when r.is_direct then coalesce(r.direct_value, 0)
           else r.total_qty * coalesce(pp.period_price, 0) end as row_value
    from public.source_of_sales_customer_directory_rollup r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
    left join period_price pp
      on pp.product_code = r.product_code and pp.period = r.period
    where upper(btrim(coalesce(r.area_code, ''))) in (
        select upper(btrim(x)) from unnest(p_area_codes) as x
      )
      and r.period = any (p_periods)
      and r.client_code is not null
      and (
        cardinality(p_lines) = 0
        or lower(btrim(coalesce(r.official_line, ''))) in (
          select lower(btrim(x)) from unnest(p_lines) as x
        )
      )
      and upper(btrim(coalesce(r.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  ),
  latest_name as (
    select distinct on (client_code) client_code, client_name
    from filtered
    where client_name is not null
    order by client_code, latest_row_created_at desc
  ),
  agg as (
    select brick_id, client_code, official_line, product_code, product_name, period,
           sum(row_units) as units, sum(row_value) as value
    from filtered
    group by brick_id, client_code, official_line, product_code, product_name, period
  )
  select
    a.brick_id,
    a.client_code,
    coalesce(ln.client_name, 'Unknown'),
    a.official_line,
    a.product_code,
    a.product_name,
    a.period,
    a.units,
    a.value,
    sum(a.units) over (),
    sum(a.value) over ()
  from agg a
  left join latest_name ln using (client_code);
end;
$$;

ALTER FUNCTION public.phx_territory_area_pharmacies(p_area_codes text[], p_periods text[], p_lines text[]) OWNER TO postgres;

