--
-- Name: phx_transfer_au_seat(text, text, text, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_transfer_au_seat(p_actor text, p_employee_hr_id text, p_to_seat_id text, p_effective_date date DEFAULT NULL::date, p_from_seat_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_hr_input text := nullif(btrim(p_employee_hr_id), '');
  v_to_seat_id text := nullif(btrim(p_to_seat_id), '');
  v_from_input text := nullif(btrim(p_from_seat_id), '');
  v_effective date := coalesce(p_effective_date, (now() at time zone 'Africa/Cairo')::date);
  v_emp record;
  v_emp_line_code text;
  v_seat au.seats;
  v_target_occupant text;
  v_open_spans text[];
  v_from_seat_id text;
  v_remaining integer;
  v_mode text;
  v_new_occupancy bigint;
  v_area record;
  v_region_code text;
  v_region_name text;
  v_new_manager text;
  v_synced jsonb := '{}'::jsonb;
begin
  if v_hr_input is null then
    raise exception 'transfer: employee HR ID is required';
  end if;
  if v_to_seat_id is null then
    raise exception 'transfer: destination seat is required';
  end if;

  select hr_id, full_name, line_id, employment_status
    into v_emp
    from public.employees
   where lower(btrim(hr_id)) = lower(v_hr_input)
   limit 1;
  if not found then
    raise exception 'transfer: employee % not found', v_hr_input;
  end if;
  if lower(coalesce(v_emp.employment_status, '')) not in ('active', 'on_leave') then
    raise exception 'transfer: employee % is % - only an active employee can be moved onto a seat',
      v_emp.hr_id, coalesce(v_emp.employment_status, 'missing employment status');
  end if;

  select * into v_seat
    from au.seats
   where seat_id = v_to_seat_id and is_active and effective_to is null;
  if not found then
    raise exception 'transfer: seat % not found or inactive', v_to_seat_id;
  end if;

  select l.code into v_emp_line_code from public.lines l where l.id = v_emp.line_id;
  if v_emp_line_code is distinct from v_seat.line_code then
    raise exception 'transfer: seat % belongs to line % but % is on line % - cross-line moves are not supported here',
      v_to_seat_id, v_seat.line_code, v_emp.hr_id, coalesce(v_emp_line_code, 'none');
  end if;

  select occupant_hr_id into v_target_occupant
    from au.occupancy_history
   where seat_id = v_to_seat_id and effective_to is null and occupant_hr_id is not null;
  if v_target_occupant is not null then
    raise exception 'transfer: seat % is already occupied by %', v_to_seat_id, v_target_occupant;
  end if;

  select coalesce(array_agg(seat_id order by seat_id), '{}')
    into v_open_spans
    from au.occupancy_history
   where occupant_canonical_hr_id = lower(btrim(v_emp.hr_id))
     and effective_to is null
     and occupant_hr_id is not null;

  if cardinality(v_open_spans) = 0 then
    -- Unseated active employee (the "hired but never reached the seat model" repair).
    if v_from_input is not null then
      raise exception 'transfer: % holds no seat, so a source seat cannot be specified - leave it empty to seat them directly', v_emp.hr_id;
    end if;
    v_mode := 'seated';
    v_from_seat_id := null;
    v_new_occupancy := au.hire_into_seat(v_to_seat_id, v_emp.hr_id, v_effective, p_actor, false);
  else
    if cardinality(v_open_spans) = 1 then
      v_from_seat_id := v_open_spans[1];
      if v_from_input is not null and v_from_input <> v_from_seat_id then
        raise exception 'transfer: % occupies seat %, not % - refusing the mismatched source', v_emp.hr_id, v_from_seat_id, v_from_input;
      end if;
    else
      if v_from_input is null then
        raise exception 'transfer: % occupies more than one seat (%) - specify which one to vacate',
          v_emp.hr_id, array_to_string(v_open_spans, ', ');
      end if;
      if not (v_from_input = any(v_open_spans)) then
        raise exception 'transfer: % does not occupy seat % (their seats: %)',
          v_emp.hr_id, v_from_input, array_to_string(v_open_spans, ', ');
      end if;
      v_from_seat_id := v_from_input;
    end if;
    if v_from_seat_id = v_to_seat_id then
      raise exception 'transfer: % already occupies seat %', v_emp.hr_id, v_to_seat_id;
    end if;

    v_mode := 'transferred';
    v_remaining := cardinality(v_open_spans) - 1;

    -- Same sequence as au.transfer_occupant, but with the source verified above and
    -- the dual-seat opt-in derived from reality: a dual-seat holder moving ONE of
    -- their seats keeps the others open, which the strict hire guard must allow.
    perform au.resign_occupant(v_from_seat_id, v_effective, coalesce(p_reason, 'seat transfer'), p_actor);
    update au.occupancy_history set event_type = 'transfer_out'
     where seat_id = v_from_seat_id and effective_to is null;
    v_new_occupancy := au.hire_into_seat(v_to_seat_id, v_emp.hr_id, v_effective, p_actor, v_remaining > 0);
    update au.occupancy_history set event_type = 'transfer_in'
     where occupancy_id = v_new_occupancy;
  end if;

  -- Sync the employee master so the legacy columns follow the seat model instead of
  -- drifting. Area fields only exist for REP seats (manager seats carry no area_code).
  -- employees keeps the area as a link (area_id) only; its area_name label column is dropped.
  if v_seat.area_code is not null then
    select ar.id, ar.name into v_area
      from public.areas ar
     where ar.code = v_seat.area_code and ar.is_active
     order by ar.id
     limit 1;
    select lam.operational_region_code into v_region_code
      from au.line_area_map lam
     where lam.line_code = v_seat.line_code
       and lam.area_code = v_seat.area_code
       and lam.effective_to is null;
    select r.region_name into v_region_name from au.regions r where r.region_code = v_region_code;
    if v_area.id is not null then
      update public.employees
         set area_id = v_area.id,
             region_code = coalesce(v_region_code, region_code),
             region_name = coalesce(v_region_name, region_name),
             updated_at = now()
       where hr_id = v_emp.hr_id;
      v_synced := v_synced || jsonb_build_object(
        'areaId', v_area.id, 'areaName', v_area.name,
        'regionCode', v_region_code, 'regionName', v_region_name);
    end if;
  end if;

  select occupant_hr_id into v_new_manager
    from au.occupancy_history
   where seat_id = v_seat.parent_seat_id and effective_to is null and occupant_hr_id is not null;
  if v_new_manager is not null then
    update public.employees set manager_hr_id = v_new_manager, updated_at = now()
     where hr_id = v_emp.hr_id;
    v_synced := v_synced || jsonb_build_object('managerHrId', v_new_manager);
  else
    v_synced := v_synced || jsonb_build_object('managerUnchanged', 'destination manager seat is vacant');
  end if;

  begin
    insert into public.audit_logs(actor_login_id, entity_type, entity_id, summary, new_values)
    values (
      coalesce(nullif(btrim(p_actor), ''), 'system'),
      'au_seat_transfer',
      v_emp.hr_id,
      case
        when v_mode = 'seated' then
          format('Seated %s on au seat %s effective %s', v_emp.hr_id, v_to_seat_id, v_effective)
        else
          format('Transferred %s from au seat %s to %s effective %s', v_emp.hr_id, v_from_seat_id, v_to_seat_id, v_effective)
      end,
      jsonb_build_object(
        'mode', v_mode,
        'employeeHrId', v_emp.hr_id,
        'fromSeatId', v_from_seat_id,
        'toSeatId', v_to_seat_id,
        'effectiveDate', v_effective,
        'reason', p_reason,
        'occupancyId', v_new_occupancy,
        'employeesSync', v_synced
      )
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'mode', v_mode,
    'employeeHrId', v_emp.hr_id,
    'fromSeatId', v_from_seat_id,
    'toSeatId', v_to_seat_id,
    'effectiveDate', v_effective,
    'occupancyId', v_new_occupancy,
    'employeesSync', v_synced
  );
end;
$$;

ALTER FUNCTION public.phx_transfer_au_seat(p_actor text, p_employee_hr_id text, p_to_seat_id text, p_effective_date date, p_from_seat_id text, p_reason text) OWNER TO postgres;

--
-- Name: phx_unlock_monthly_closing(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_unlock_monthly_closing(p_line text, p_period text, p_actor text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS public.monthly_closing_locks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_norm text := lower(btrim(coalesce(p_line, '')));
  v_row  public.monthly_closing_locks;
begin
  update public.monthly_closing_locks
     set unlocked_at = now(),
         unlocked_by = p_actor,
         unlock_reason = nullif(btrim(coalesce(p_reason, '')), '')
   where normalized_line = v_norm and period = btrim(p_period) and unlocked_at is null
  returning * into v_row;

  if v_row.id is null then
    raise exception 'No active lock found for % %.', p_line, p_period;
  end if;
  return v_row;
end;
$$;

ALTER FUNCTION public.phx_unlock_monthly_closing(p_line text, p_period text, p_actor text, p_reason text) OWNER TO postgres;

--
-- Name: phx_update_retention_conversation(uuid, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_update_retention_conversation(p_conversation_id uuid, p_patch jsonb, p_themes jsonb, p_expected_updated_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_allowed constant text[] := array[
    'updated_at',
    'summary',
    'retention_risk',
    'is_regrettable',
    'would_rejoin',
    'follow_up_action',
    'follow_up_due',
    'follow_up_done_at'
  ];
  v_unknown text;
  v_row public.hr_retention_conversations;
  v_new public.hr_retention_conversations;
begin
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'A retention conversation update must be an object.' using errcode = '22023';
  end if;

  select key into v_unknown
  from jsonb_object_keys(p_patch) as key
  where key <> all (v_allowed)
  limit 1;
  if v_unknown is not null then
    raise exception 'A retention conversation update cannot change "%".', v_unknown using errcode = '22023';
  end if;

  select * into v_row
  from public.hr_retention_conversations
  where id = p_conversation_id
  for update;
  if not found then
    raise exception 'That conversation no longer exists.' using errcode = 'P0002';
  end if;

  if p_expected_updated_at is not null and v_row.updated_at is distinct from p_expected_updated_at then
    raise exception 'This conversation was changed by someone else since you opened it. Reload it and try again.'
      using errcode = '40001';
  end if;

  -- Values not in the patch keep the row's own value (jsonb_populate_record with a non-null base).
  v_new := jsonb_populate_record(v_row, p_patch);

  update public.hr_retention_conversations set
    updated_at = case when p_patch ? 'updated_at' then v_new.updated_at else updated_at end,
    summary = case when p_patch ? 'summary' then v_new.summary else summary end,
    retention_risk = case when p_patch ? 'retention_risk' then v_new.retention_risk else retention_risk end,
    is_regrettable = case when p_patch ? 'is_regrettable' then v_new.is_regrettable else is_regrettable end,
    would_rejoin = case when p_patch ? 'would_rejoin' then v_new.would_rejoin else would_rejoin end,
    follow_up_action = case when p_patch ? 'follow_up_action' then v_new.follow_up_action else follow_up_action end,
    follow_up_due = case when p_patch ? 'follow_up_due' then v_new.follow_up_due else follow_up_due end,
    follow_up_done_at = case when p_patch ? 'follow_up_done_at' then v_new.follow_up_done_at else follow_up_done_at end
  where id = p_conversation_id
  returning * into v_row;

  if p_themes is not null then
    perform public.phx_replace_retention_conversation_themes(p_conversation_id, p_themes);
  end if;

  return v_row.updated_at;
end;
$$;

ALTER FUNCTION public.phx_update_retention_conversation(p_conversation_id uuid, p_patch jsonb, p_themes jsonb, p_expected_updated_at timestamp with time zone) OWNER TO postgres;

--
-- Name: phx_upsert_monthly_targets(jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_upsert_monthly_targets(p_rows jsonb, p_actor text DEFAULT NULL::text, p_source text DEFAULT 'upload'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $$
declare
  v_count integer;
begin
  insert into au.monthly_targets (period, line_code, area_code, product_code, target_units, target_value, source, created_by, updated_at)
  select r.period, r.line_code, r.area_code, r.product_code, r.target_units, r.target_value, p_source, p_actor, now()
  from jsonb_to_recordset(p_rows) as r(
    period text, line_code text, area_code text, product_code text, target_units numeric, target_value numeric
  )
  on conflict (period, line_code, area_code, product_code)
  do update set
    target_units = excluded.target_units,
    target_value = excluded.target_value,
    source       = excluded.source,
    created_by   = excluded.created_by,
    updated_at   = now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

ALTER FUNCTION public.phx_upsert_monthly_targets(p_rows jsonb, p_actor text, p_source text) OWNER TO postgres;

--
-- Name: phx_vacancy_manager_from_seat(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_vacancy_manager_from_seat() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v record;
begin
  if lower(coalesce(new.status, 'open')) <> 'open' then
    return new;
  end if;

  if new.seat_id is not null then
    select * into v from public.phx_vacancy_seat_manager(new.seat_id);
    if v.manager_hr_id is not null then
      new.manager_hr_id := v.manager_hr_id;
      new.manager_name := v.manager_name;
      new.region_name := coalesce(v.region_name, new.region_name);
      return new;
    end if;
  end if;

  if new.manager_hr_id is null then
    select * into v from public.phx_vacancy_region_manager(new.line_id, new.region_name);
    if v.manager_hr_id is not null then
      new.manager_hr_id := v.manager_hr_id;
      new.manager_name := v.manager_name;
    end if;
  end if;

  return new;
end;
$$;

ALTER FUNCTION public.phx_vacancy_manager_from_seat() OWNER TO postgres;

--
-- Name: phx_vacancy_region_manager(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_vacancy_region_manager(p_line_id bigint, p_region_name text) RETURNS TABLE(manager_hr_id text, manager_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select max(s.occupant_hr_id)::text, max(e.full_name)::text
    from au.v_org_tree s
    join public.employees e on e.hr_id = s.occupant_hr_id
   where s.seat_tier = 'DM'
     and s.line_id = p_line_id
     and s.region_name = p_region_name
     and s.occupant_hr_id is not null
     and p_line_id is not null
     and p_region_name is not null
  having count(distinct s.occupant_hr_id) = 1;
$$;

ALTER FUNCTION public.phx_vacancy_region_manager(p_line_id bigint, p_region_name text) OWNER TO postgres;

--
-- Name: phx_vacancy_seat_manager(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_vacancy_seat_manager(p_seat_id text) RETURNS TABLE(manager_hr_id text, manager_name text, region_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.occupant_hr_id::text, e.full_name::text, s.region_name::text
    from au.v_org_tree s
    join au.v_org_tree p on p.seat_id = s.parent_seat_id
    join public.employees e on e.hr_id = p.occupant_hr_id
   where s.seat_id = p_seat_id
     and p.occupant_hr_id is not null;
$$;

ALTER FUNCTION public.phx_vacancy_seat_manager(p_seat_id text) OWNER TO postgres;

--
-- Name: phx_vacate_au_seats_for_employee(text, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_vacate_au_seats_for_employee(p_actor text, p_effective_date date, p_employee_hr_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_seat_id text;
  v_vacant_from date;
  v_vacated text[] := array[]::text[];
begin
  if p_employee_hr_id is null or btrim(p_employee_hr_id) = '' then
    raise exception 'phx_vacate_au_seats_for_employee: employee hr_id is required';
  end if;

  -- p_effective_date is the resignation's effective date, i.e. the employee's LAST WORKING DAY,
  -- so the seat falls vacant the day after it. A null date keeps this function's original
  -- meaning: vacate from today, in Cairo (AGENTS.md § 4), never an unzoned current_date.
  v_vacant_from := coalesce(p_effective_date + 1, (now() at time zone 'Africa/Cairo')::date);

  -- Same lookup as step 5 of public.phx_resign_employee_and_open_vacancy: canonical HR_ID,
  -- open span only, person spans only, ordered for a stable and reproducible vacate order.
  -- Zero rows is the expected, non-error outcome for an employee who holds no seat.
  for v_seat_id in
    select seat_id
    from au.occupancy_history
    where occupant_canonical_hr_id = lower(btrim(p_employee_hr_id))
      and effective_to is null
      and node_type = 'person'
    order by seat_id
  loop
    perform au.resign_occupant(
      v_seat_id,
      v_vacant_from,
      coalesce(nullif(btrim(p_reason), ''), 'resignation'),
      coalesce(nullif(btrim(p_actor), ''), 'system')
    );
    v_vacated := v_vacated || v_seat_id;
  end loop;

  return jsonb_build_object(
    'employee_hr_id', p_employee_hr_id,
    'effective_date', v_vacant_from,
    'last_working_date', p_effective_date,
    'seats_vacated', to_jsonb(v_vacated),
    'vacated_count', coalesce(array_length(v_vacated, 1), 0)
  );
end;
$$;

ALTER FUNCTION public.phx_vacate_au_seats_for_employee(p_actor text, p_effective_date date, p_employee_hr_id text, p_reason text) OWNER TO postgres;

--
-- Name: phx_vacation_report_rows(text[], jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_vacation_report_rows(p_visible_employee_hr_ids text[] DEFAULT NULL::text[], p_filters jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0) RETURNS SETOF public.v2_vacation_requests
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select requests.*
  from public.v2_vacation_requests requests
  where (
    p_visible_employee_hr_ids is null
    or requests.employee_hr_id = any(p_visible_employee_hr_ids)
  )
  and (
    nullif(p_filters->>'status', '') is null
    or p_filters->>'status' = 'all'
    or requests.status = p_filters->>'status'
  )
  and (
    nullif(p_filters->>'paymentStatus', '') is null
    or p_filters->>'paymentStatus' = 'all'
    or requests.payment_status = p_filters->>'paymentStatus'
  )
  and (
    nullif(p_filters->>'vacationType', '') is null
    or p_filters->>'vacationType' = 'all'
    or requests.vacation_type = p_filters->>'vacationType'
  )
  and (
    nullif(p_filters->>'employee', '') is null
    or requests.employee_hr_id ilike p_filters->>'employee'
  )
  and (
    nullif(p_filters->>'manager', '') is null
    or requests.manager_hr_id ilike p_filters->>'manager'
  )
  and (
    nullif(p_filters->>'department', '') is null
    or requests.department_name = p_filters->>'department'
  )
  and (
    nullif(p_filters->>'line', '') is null
    or requests.line_name = p_filters->>'line'
  )
  and (
    nullif(p_filters->>'dateFrom', '') is null
    or requests.start_date >= (p_filters->>'dateFrom')::date
  )
  and (
    nullif(p_filters->>'dateTo', '') is null
    or requests.start_date <= (p_filters->>'dateTo')::date
  )
  and (
    nullif(p_filters->>'requestId', '') is null
    or requests.id::text = p_filters->>'requestId'
  )
  and (
    nullif(p_filters->>'search', '') is null
    or concat_ws(
      ' ',
      requests.id::text,
      requests.employee_hr_id,
      requests.employee_name,
      requests.manager_hr_id,
      requests.manager_name,
      requests.department_name,
      requests.line_name,
      requests.vacation_type,
      requests.status,
      requests.payment_status
    ) ilike '%' || (p_filters->>'search') || '%'
  )
  order by requests.created_at desc
  limit greatest(1, least(coalesce(p_limit, 1000), 5000))
  offset greatest(0, coalesce(p_offset, 0));
$$;

ALTER FUNCTION public.phx_vacation_report_rows(p_visible_employee_hr_ids text[], p_filters jsonb, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: phx_weekly_plan_acknowledge(uuid, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_acknowledge(p_plan_id uuid, p_expected_revision integer, p_hr_id text, p_login_id text, p_role_label text, p_comment text) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status text;
  current_revision integer;
  next_status text;
  now_ts timestamptz := now();
begin
  select status, revision into current_status, current_revision
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  next_status := public.phx_weekly_plan_next_status(current_status, 'hr_acknowledge', true);

  insert into public.employee_plan_hr_acknowledgements
    (plan_id, hr_id, login_id, role_label, comment)
    values
    (p_plan_id, p_hr_id, p_login_id, p_role_label, nullif(btrim(coalesce(p_comment, '')), ''))
    on conflict (plan_id, hr_id) do update
      set login_id = excluded.login_id,
          role_label = excluded.role_label,
          comment = excluded.comment,
          acknowledged_at = now();

  update public.employee_plan_headers
    set status = next_status,
        revision = revision + 1,
        updated_at = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_hr_id, p_login_id, p_role_label, 'hr_acknowledge', current_status, next_status, p_comment);

  return query select next_status, current_revision + 1;
end;
$$;

ALTER FUNCTION public.phx_weekly_plan_acknowledge(p_plan_id uuid, p_expected_revision integer, p_hr_id text, p_login_id text, p_role_label text, p_comment text) OWNER TO postgres;

