ALTER FUNCTION public.phx_weekly_plan_cancel(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_comment text) OWNER TO postgres;

--
-- Name: phx_weekly_plan_decide(uuid, integer, text, text, text, text, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_decide(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_action text, p_comment text, p_return_notes jsonb, p_bypass_ceo boolean DEFAULT false) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status text;
  current_revision integer;
  header_parent_id uuid;
  header_employee_hr_id text;
  header_plan_kind text;
  header_period_key text;
  parent_status text;
  next_status text;
  now_ts timestamptz := now();
  note jsonb;
  matched_item record;
begin
  if p_action not in (
    'manager_approve', 'manager_reject', 'manager_return',
    'ceo_approve',     'ceo_reject',     'ceo_return'
  ) then
    raise exception 'weekly_plan_invalid_transition: phx_weekly_plan_decide does not accept action ''%''', p_action using errcode = 'P0001';
  end if;

  select status, revision, parent_plan_id, employee_hr_id, plan_kind, period_key
    into current_status, current_revision, header_parent_id, header_employee_hr_id, header_plan_kind, header_period_key
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  next_status := public.phx_weekly_plan_next_status(
    current_status,
    p_action,
    nullif(btrim(coalesce(p_comment, '')), '') is not null,
    p_bypass_ceo
  );

  if next_status = 'final_approved' and header_parent_id is not null then
    select status
      into parent_status
      from public.employee_plan_headers
      where id = header_parent_id
        and employee_hr_id = header_employee_hr_id
        and plan_kind = header_plan_kind
        and period_key = header_period_key
      for update;

    if parent_status in ('final_approved', 'hr_acknowledged') then
      update public.employee_plan_headers
        set status = 'cancelled',
            revision = revision + 1,
            updated_at = now_ts
        where id = header_parent_id;

      insert into public.employee_plan_decisions
        (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
        values
        (header_parent_id, p_actor_hr_id, p_actor_login_id, p_actor_role, 'cancel', parent_status, 'cancelled',
         'Replaced by the revised version of this plan, which has just been approved.');
    end if;
  end if;

  update public.employee_plan_headers
    set status = next_status,
        manager_decision_at      = case when p_action like 'manager%' then now_ts             else manager_decision_at end,
        manager_decision_by_hr_id = case when p_action like 'manager%' then p_actor_hr_id     else manager_decision_by_hr_id end,
        manager_decision_comment = case when p_action like 'manager%' then p_comment          else manager_decision_comment end,
        ceo_decision_at          = case when p_action like 'ceo%'     then now_ts             else ceo_decision_at end,
        ceo_decision_by_hr_id    = case when p_action like 'ceo%'     then p_actor_hr_id     else ceo_decision_by_hr_id end,
        ceo_decision_comment     = case when p_action like 'ceo%'     then p_comment          else ceo_decision_comment end,
        final_approved_at        = case when next_status = 'final_approved' then now_ts        else final_approved_at end,
        revision = revision + 1,
        updated_at = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role, p_action, current_status, next_status, p_comment);

  if p_action in ('manager_return', 'ceo_return') and p_return_notes is not null then
    for note in select * from jsonb_array_elements(p_return_notes)
    loop
      select id, activity_date, activity_title, sort_order into matched_item
        from public.employee_plan_items
        where id = (note->>'itemId')::uuid
          and plan_id = p_plan_id;

      if matched_item.id is null then
        raise exception 'weekly_plan_invalid_transition: return-note item % does not belong to plan %', note->>'itemId', p_plan_id using errcode = 'P0001';
      end if;

      insert into public.employee_plan_item_return_notes
        (plan_id, item_id, actor_hr_id, actor_login_id, actor_role, action,
         activity_date, activity_title, sort_order, note)
        values
        (p_plan_id, matched_item.id, p_actor_hr_id, p_actor_login_id, p_actor_role, p_action,
         matched_item.activity_date, matched_item.activity_title, matched_item.sort_order, note->>'note');
    end loop;
  end if;

  return query select next_status, current_revision + 1;
end;
$$;

ALTER FUNCTION public.phx_weekly_plan_decide(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_action text, p_comment text, p_return_notes jsonb, p_bypass_ceo boolean) OWNER TO postgres;

--
-- Name: phx_weekly_plan_decide_edit_request(uuid, integer, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_decide_edit_request(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_decision text, p_comment text) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status text;
  current_revision integer;
  next_status text;
  action_name text;
  now_ts timestamptz := now();
begin
  if p_decision not in ('approve', 'reject') then
    raise exception 'weekly_plan_invalid_transition: p_decision must be ''approve'' or ''reject'', got ''%''', p_decision using errcode = 'P0001';
  end if;

  action_name := case p_decision when 'approve' then 'approve_edit_request' else 'reject_edit_request' end;

  select status, revision into current_status, current_revision
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  next_status := public.phx_weekly_plan_next_status(current_status, action_name, true);

  update public.employee_plan_headers
    set status = next_status,
        revision = revision + 1,
        updated_at = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role, action_name, current_status, next_status, p_comment);

  return query select next_status, current_revision + 1;
end;
$$;

ALTER FUNCTION public.phx_weekly_plan_decide_edit_request(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_decision text, p_comment text) OWNER TO postgres;

--
-- Name: phx_weekly_plan_next_status(text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_next_status(current_status text, action text, has_comment boolean, bypass_ceo boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  to_status text;
  requires_comment boolean := false;
begin
  case action
    when 'submit' then
      if current_status not in ('draft', 'manager_returned', 'ceo_returned') then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'submitted';
    when 'request_edit' then
      if current_status <> 'submitted' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'edit_requested';
    when 'approve_edit_request' then
      if current_status <> 'edit_requested' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'draft';
    when 'reject_edit_request' then
      if current_status <> 'edit_requested' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'submitted';
    when 'request_visit_details' then
      if current_status <> 'submitted' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'details_requested';
    when 'submit_visit_details' then
      if current_status <> 'details_requested' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'submitted';
    when 'manager_approve' then
      if current_status <> 'submitted' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := case when bypass_ceo then 'final_approved' else 'manager_approved' end;
    when 'manager_reject' then
      if current_status <> 'submitted' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      requires_comment := true;
      to_status := 'manager_rejected';
    when 'manager_return' then
      if current_status <> 'submitted' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      requires_comment := true;
      to_status := 'manager_returned';
    when 'ceo_approve' then
      if current_status <> 'manager_approved' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'final_approved';
    when 'ceo_reject' then
      if current_status <> 'manager_approved' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      requires_comment := true;
      to_status := 'ceo_rejected';
    when 'ceo_return' then
      if current_status <> 'manager_approved' then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      requires_comment := true;
      to_status := 'ceo_returned';
    when 'hr_acknowledge' then
      if current_status not in ('final_approved', 'hr_acknowledged') then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'hr_acknowledged';
    when 'cancel' then
      if current_status not in ('draft', 'submitted', 'edit_requested', 'details_requested', 'manager_returned', 'ceo_returned') then
        raise exception 'weekly_plan_invalid_transition: action ''%'' not allowed from status ''%''', action, current_status using errcode = 'P0001';
      end if;
      to_status := 'cancelled';
    else
      raise exception 'weekly_plan_invalid_transition: unknown action ''%''', action using errcode = 'P0001';
  end case;
  if requires_comment and not has_comment then
    raise exception 'weekly_plan_invalid_transition: action ''%'' requires a comment', action using errcode = 'P0001';
  end if;
  return to_status;
end;
$$;

ALTER FUNCTION public.phx_weekly_plan_next_status(current_status text, action text, has_comment boolean, bypass_ceo boolean) OWNER TO postgres;

--
-- Name: phx_weekly_plan_replace_items(uuid, integer, text, text, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_replace_items(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_items jsonb, p_submit boolean DEFAULT false) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  current_status text;
  current_revision integer;
  header_period_start date;
  header_period_end date;
  item_row jsonb;
  item_activity_date_text text;
  item_activity_date date;
  item_sort_order integer;
  next_status text;
  now_ts timestamptz := now();
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'weekly_plan_invalid_transition: plan items payload must be a JSON array' using errcode = 'P0001';
  end if;

  if jsonb_array_length(p_items) = 0 then
    raise exception 'weekly_plan_invalid_transition: plan must include at least one item' using errcode = 'P0001';
  end if;

  select status, revision, period_start_date, period_end_date
    into current_status, current_revision, header_period_start, header_period_end
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  if current_status not in ('draft', 'manager_returned', 'ceo_returned') then
    raise exception 'weekly_plan_invalid_transition: items cannot be replaced from status ''%''', current_status using errcode = 'P0001';
  end if;

  delete from public.employee_plan_items
    where plan_id = p_plan_id;

  for item_row in select * from jsonb_array_elements(p_items)
  loop
    item_activity_date_text := btrim(coalesce(item_row->>'activityDate', ''));

    if item_activity_date_text !~ '^\d{4}-\d{2}-\d{2}$'
       or to_char(to_date(item_activity_date_text, 'YYYY-MM-DD'), 'YYYY-MM-DD') <> item_activity_date_text then
      raise exception 'weekly_plan_invalid_transition: item activityDate must be a valid YYYY-MM-DD date' using errcode = 'P0001';
    end if;

    item_activity_date := to_date(item_activity_date_text, 'YYYY-MM-DD');

    if item_activity_date < header_period_start or item_activity_date > header_period_end then
      raise exception 'weekly_plan_invalid_transition: item activityDate % is outside plan period % to %',
        item_activity_date_text,
        header_period_start,
        header_period_end
        using errcode = 'P0001';
    end if;

    item_sort_order := coalesce(nullif(item_row->>'sortOrder', '')::integer, 0);

    insert into public.employee_plan_items (
      plan_id,
      activity_date,
      start_time,
      end_time,
      activity_type,
      activity_title,
      objective,
      attendees,
      location_text,
      area,
      double_visit_medical_rep_hr_id,
      double_visit_medical_rep_name,
      notes,
      sort_order
    )
    values (
      p_plan_id,
      item_activity_date,
      nullif(item_row->>'startTime', '')::time,
      nullif(item_row->>'endTime', '')::time,
      coalesce(nullif(btrim(item_row->>'activityType'), ''), 'Other'),
      coalesce(nullif(btrim(item_row->>'activityTitle'), ''), 'Activity'),
      nullif(btrim(coalesce(item_row->>'objective', '')), ''),
      nullif(btrim(coalesce(item_row->>'attendees', '')), ''),
      nullif(btrim(coalesce(item_row->>'locationText', '')), ''),
      nullif(btrim(coalesce(item_row->>'area', '')), ''),
      nullif(btrim(coalesce(item_row->>'doubleVisitMedicalRepHrId', '')), ''),
      nullif(btrim(coalesce(item_row->>'doubleVisitMedicalRepName', '')), ''),
      coalesce(item_row->>'notes', ''),
      item_sort_order
    );
  end loop;

  if p_submit then
    next_status := public.phx_weekly_plan_next_status(current_status, 'submit', true);

    update public.employee_plan_headers
      set status = next_status,
          submitted_at = coalesce(submitted_at, now_ts),
          submitted_by_login_id = coalesce(submitted_by_login_id, p_actor_login_id),
          revision = revision + 1,
          updated_at = now_ts
      where id = p_plan_id;

    insert into public.employee_plan_decisions
      (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
      values
      (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role, 'submit', current_status, next_status, null);
  else
    next_status := current_status;

    update public.employee_plan_headers
      set revision = revision + 1,
          updated_at = now_ts
      where id = p_plan_id;
  end if;

  return query select next_status, current_revision + 1;
end;
$_$;

ALTER FUNCTION public.phx_weekly_plan_replace_items(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_items jsonb, p_submit boolean) OWNER TO postgres;

--
