--
-- Name: phx_weekly_plan_request_details(uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_request_details(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status   text;
  current_revision integer;
  now_ts           timestamptz := now();
begin
  select status, revision
    into current_status, current_revision
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  -- Delegate transition validation to the central helper.
  perform public.phx_weekly_plan_next_status(current_status, 'request_visit_details', false);

  update public.employee_plan_headers
    set status                           = 'details_requested',
        visit_details_requested_at       = now_ts,
        visit_details_requested_by_hr_id = p_actor_hr_id,
        revision                         = revision + 1,
        updated_at                       = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role,
     'request_visit_details', current_status, 'details_requested', null);

  return query select 'details_requested'::text, current_revision + 1;
end;
$$;

ALTER FUNCTION public.phx_weekly_plan_request_details(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text) OWNER TO postgres;

--
-- Name: phx_weekly_plan_request_edit(uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_request_edit(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status text;
  current_revision integer;
  next_status text;
  now_ts timestamptz := now();
begin
  select status, revision into current_status, current_revision
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  next_status := public.phx_weekly_plan_next_status(current_status, 'request_edit', true);

  update public.employee_plan_headers
    set status = next_status,
        revision = revision + 1,
        updated_at = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role, 'request_edit', current_status, next_status, null);

  return query select next_status, current_revision + 1;
end;
$$;

ALTER FUNCTION public.phx_weekly_plan_request_edit(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text) OWNER TO postgres;

--
-- Name: phx_weekly_plan_submit(uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_submit(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status text;
  current_revision integer;
  next_status text;
  now_ts timestamptz := now();
begin
  -- Optimistic lock: SELECT FOR UPDATE blocks concurrent transitions on this
  -- header row. expected_revision must match the current revision or we
  -- raise a typed conflict exception that the TS layer maps to HTTP 409.
  select status, revision into current_status, current_revision
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  next_status := public.phx_weekly_plan_next_status(current_status, 'submit', true);

  update public.employee_plan_headers
    set status = next_status,
        submitted_at = coalesce(submitted_at, now_ts),
        submitted_by_login_id = coalesce(submitted_by_login_id, p_actor_login_id),
        revision = revision + 1,
        updated_at = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role, 'submit', current_status, next_status, null);

  return query select next_status, current_revision + 1;
end;
$$;

ALTER FUNCTION public.phx_weekly_plan_submit(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text) OWNER TO postgres;

--
-- Name: phx_weekly_plan_submit_details(uuid, integer, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plan_submit_details(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_visit_details jsonb) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status   text;
  current_revision integer;
  now_ts           timestamptz := now();
  detail           jsonb;
  item_id_val      uuid;
begin
  select status, revision
    into current_status, current_revision
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  -- Validate transition.
  perform public.phx_weekly_plan_next_status(current_status, 'submit_visit_details', false);

  -- Wipe existing visit details for this plan (clean slate on every submission).
  delete from public.employee_plan_visit_details
    where plan_id = p_plan_id;

  -- Insert the new set, validating each item belongs to this plan and is a Field row.
  for detail in select * from jsonb_array_elements(p_visit_details)
  loop
    item_id_val := (detail->>'itemId')::uuid;

    if not exists (
      select 1 from public.employee_plan_items
        where id = item_id_val
          and plan_id = p_plan_id
          and activity_type = 'Field'
    ) then
      raise exception 'weekly_plan_invalid_transition: item % is not a Field item belonging to plan %',
        detail->>'itemId', p_plan_id using errcode = 'P0001';
    end if;

    insert into public.employee_plan_visit_details
      (plan_id, item_id, doctor_name, speciality, address, objective, sort_order)
      values (
        p_plan_id,
        item_id_val,
        detail->>'doctorName',
        detail->>'speciality',
        detail->>'address',
        detail->>'objective',
        coalesce((detail->>'sortOrder')::integer, 0)
      );
  end loop;

  -- Advance the plan back to submitted.
  update public.employee_plan_headers
    set status     = 'submitted',
        revision   = revision + 1,
        updated_at = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role,
     'submit_visit_details', current_status, 'submitted', null);

  return query select 'submitted'::text, current_revision + 1;
end;
$$;

ALTER FUNCTION public.phx_weekly_plan_submit_details(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_visit_details jsonb) OWNER TO postgres;

--
-- Name: phx_weekly_plans_drift_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_weekly_plans_drift_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  d1_count integer := 0;
  d2_count integer := 0;
  d3_count integer := 0;
  d4_count integer := 0;
  d5_count integer := 0;
  d6_count integer := 0;
BEGIN
  -- D1: final_approved but no timestamp
  SELECT COUNT(*) INTO d1_count
  FROM employee_plan_headers
  WHERE status = 'final_approved' AND final_approved_at IS NULL;

  -- D2: advanced status but no submitted_at
  SELECT COUNT(*) INTO d2_count
  FROM employee_plan_headers
  WHERE status IN (
    'submitted', 'manager_approved', 'manager_rejected', 'manager_returned',
    'ceo_approved', 'ceo_rejected', 'ceo_returned', 'final_approved', 'hr_acknowledged'
  ) AND submitted_at IS NULL;

  -- D3: manager decision actor/timestamp XOR
  SELECT COUNT(*) INTO d3_count
  FROM employee_plan_headers
  WHERE (manager_decision_by_hr_id IS NULL) <> (manager_decision_at IS NULL);

  -- D4: orphan plans awaiting manager with NULL/missing/terminated manager
  SELECT COUNT(*) INTO d4_count
  FROM employee_plan_headers h
  LEFT JOIN employees e ON UPPER(e.hr_id) = UPPER(h.manager_hr_id)
  WHERE h.status IN ('submitted', 'manager_returned', 'ceo_returned')
    AND (h.manager_hr_id IS NULL OR e.hr_id IS NULL
         OR e.employment_status NOT IN ('active', 'on_leave'));

  -- D5: header status mismatched with most recent decision row
  SELECT COUNT(*) INTO d5_count
  FROM employee_plan_headers h
  JOIN LATERAL (
    SELECT to_status FROM employee_plan_decisions d
    WHERE d.plan_id = h.id ORDER BY created_at DESC LIMIT 1
  ) d ON true
  WHERE h.status <> d.to_status;

  -- D6: hr_acknowledged header but no acknowledgement row
  SELECT COUNT(*) INTO d6_count
  FROM employee_plan_headers h
  LEFT JOIN employee_plan_hr_acknowledgements a ON a.plan_id = h.id
  WHERE h.status = 'hr_acknowledged' AND a.id IS NULL;

  RETURN jsonb_build_object(
    'D1', d1_count,
    'D2', d2_count,
    'D3', d3_count,
    'D4', d4_count,
    'D5', d5_count,
    'D6', d6_count
  );
END;
$$;

ALTER FUNCTION public.phx_weekly_plans_drift_check() OWNER TO postgres;

--
-- Name: daily_deductions_lines; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.daily_deductions_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    publication_id uuid NOT NULL,
    category text NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    employee_name text,
    unit text DEFAULT 'days'::text NOT NULL,
    raw_days_count numeric(14,2) DEFAULT 0 NOT NULL,
    days_count numeric(14,2) DEFAULT 0 NOT NULL,
    amount numeric(14,2) DEFAULT 0 NOT NULL,
    dates jsonb DEFAULT '[]'::jsonb NOT NULL,
    source_system text DEFAULT ''::text NOT NULL,
    reason text,
    hr_note text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    released_at timestamp with time zone DEFAULT now() NOT NULL,
    released_by text,
    range_start date,
    range_end date,
    deduction_date date,
    CONSTRAINT daily_deductions_lines_counts_non_negative CHECK (((raw_days_count >= (0)::numeric) AND (days_count >= (0)::numeric) AND (amount >= (0)::numeric))),
    CONSTRAINT daily_deductions_lines_employee_hr_id_compact_not_blank CHECK ((btrim(employee_hr_id_compact) <> ''::text)),
    CONSTRAINT daily_deductions_lines_employee_hr_id_not_blank CHECK ((btrim(employee_hr_id) <> ''::text)),
    CONSTRAINT daily_deductions_lines_unit_check CHECK ((unit = ANY (ARRAY['days'::text, 'amount'::text])))
);

ALTER TABLE public.daily_deductions_lines OWNER TO postgres;

--
-- Name: TABLE daily_deductions_lines; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.daily_deductions_lines IS 'Daily Deductions module: the tally rows inside a snapshot. One row per (publication, employee, category). days_count is the clipped, weighted day count that drives amount; raw_days_count is the unweighted evidence count; dates are the specific in-range days.';

--
-- Name: COLUMN daily_deductions_lines.deduction_date; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.daily_deductions_lines.deduction_date IS 'The ONE day this row charges when it was released on its own (owner, 2026-11-13: "I want each deduction to be single"); dates is then exactly this day. Null on a row that carries a whole range.';

--
-- Name: phx_withdraw_daily_deduction_line(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_withdraw_daily_deduction_line(p_line_id uuid, p_actor text) RETURNS public.daily_deductions_lines
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_publication public.daily_deductions_publications;
  v_line        public.daily_deductions_lines;
  v_remaining   integer;
begin
  if btrim(coalesce(p_actor, '')) = '' then
    raise exception 'phx_withdraw_daily_deduction_line: an actor is required';
  end if;

  perform pg_advisory_xact_lock(hashtext('daily_deductions_snapshot'));

  select * into v_publication
    from public.daily_deductions_publications
   where status = 'published' and superseded_at is null
   for update;
  if not found then
    raise exception 'phx_withdraw_daily_deduction_line: nothing is published, so there is no line to withdraw';
  end if;

  delete from public.daily_deductions_lines
   where id = p_line_id and publication_id = v_publication.id
   returning * into v_line;
  if not found then
    raise exception 'phx_withdraw_daily_deduction_line: line % is not in the active snapshot', p_line_id;
  end if;

  select count(*)::int into v_remaining
    from public.daily_deductions_lines where publication_id = v_publication.id;

  if v_remaining = 0 then
    update public.daily_deductions_publications
       set status = 'superseded', superseded_at = now(),
           line_count = 0, employee_count = 0, category_totals = '{}'::jsonb
     where id = v_publication.id;
  else
    update public.daily_deductions_publications p
       set range_start = coalesce((
             select min(coalesce(l.range_start, p.range_start))
               from public.daily_deductions_lines l where l.publication_id = p.id
           ), p.range_start),
           range_end = coalesce((
             select max(coalesce(l.range_end, p.range_end))
               from public.daily_deductions_lines l where l.publication_id = p.id
           ), p.range_end),
           line_count = v_remaining,
           employee_count = (
             select count(distinct employee_hr_id_compact)::int
               from public.daily_deductions_lines where publication_id = p.id
           ),
           category_totals = coalesce((
             select jsonb_object_agg(category, cat_total)
               from (
                 select category, sum(amount) as cat_total
                   from public.daily_deductions_lines
                  where publication_id = p.id
                  group by category
               ) c
           ), '{}'::jsonb)
     where p.id = v_publication.id;
  end if;

  return v_line;
end;
$$;

ALTER FUNCTION public.phx_withdraw_daily_deduction_line(p_line_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: phx_withdraw_deduction(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_withdraw_deduction(p_line_id uuid, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_publication_id uuid;
  v_candidate_id   uuid;
  v_month_key      text;
begin
  select publication_id, candidate_id, month_key
    into v_publication_id, v_candidate_id, v_month_key
  from deductions_publication_lines
  where id = p_line_id and line_status = 'active'
  for update;

  if v_publication_id is null then
    return jsonb_build_object('ok', false, 'reason', 'line not found or already withdrawn');
  end if;

  update deductions_publication_lines
  set line_status = 'withdrawn'
  where id = p_line_id;

  update deductions_candidates
  set locked_at = null
  where id = v_candidate_id;

  with active as (
    select category, employee_hr_id_compact, applied_amount
    from deductions_publication_lines
    where publication_id = v_publication_id and line_status = 'active'
  ),
  by_cat as (
    select category, round(sum(applied_amount), 2) as amt
    from active
    group by category
  )
  update deductions_publications p set
    candidate_count = (select count(*) from active),
    employee_count  = (select count(distinct employee_hr_id_compact) from active),
    category_totals = coalesce((select jsonb_object_agg(category, amt) from by_cat), '{}'::jsonb)
  where p.id = v_publication_id;

  insert into deductions_audit (publication_id, candidate_id, actor_hr_id, action, detail)
  values (
    v_publication_id, v_candidate_id, p_actor, 'withdrawn',
    jsonb_build_object('line_id', p_line_id, 'month_key', v_month_key)
  );

  return jsonb_build_object(
    'ok', true,
    'publication_id', v_publication_id,
    'candidate_id', v_candidate_id,
    'line_id', p_line_id
  );
end;
$$;

ALTER FUNCTION public.phx_withdraw_deduction(p_line_id uuid, p_actor text) OWNER TO postgres;

--
-- Name: phx_write_monthly_store_split_net(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.phx_write_monthly_store_split_net(p_period text, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'au', 'public'
    AS $_$
declare
  v_written  integer := 0;
  v_bad      text;
  v_unmapped text;
  v_frozen   text[];
begin
  if p_period is null or p_period !~ '^\d{4}-\d{2}$' then
    raise exception 'phx_write_monthly_store_split_net: period must be YYYY-MM, got %', p_period;
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'phx_write_monthly_store_split_net: p_rows must be a jsonb array';
  end if;

  -- 🔒 A PUBLISHED LINE KEEPS ITS NET; THE OTHER LINES OF THE SAME MONTH DO NOT FREEZE WITH IT.
  -- Fails closed: a published line Phoenix cannot map to a line_code freezes the whole period.
  if exists (
    select 1 from public.monthly_closing_publications pub
    left join au.sos_official_line_map lm
      on lower(btrim(lm.official_line)) = lower(btrim(pub.line))
    where pub.period = p_period and pub.unpublished_at is null
      and lm.line_code is null
  ) then
    raise notice 'phx_write_monthly_store_split_net: % has a published line with no line_code — leaving the whole period frozen', p_period;
    return 0;
  end if;

  v_frozen := array(
    select distinct lm.line_code
    from public.monthly_closing_publications pub
    join au.sos_official_line_map lm
      on lower(btrim(lm.official_line)) = lower(btrim(pub.line))
    where pub.period = p_period and pub.unpublished_at is null
  );

  if not exists (select 1 from au.sos_official_line_map lm where lm.line_code <> all (v_frozen)) then
    raise notice 'phx_write_monthly_store_split_net: every line of % is published — leaving its store split frozen', p_period;
    return 0;
  end if;

  select string_agg(distinct r->>'official_line', ', ')
    into v_unmapped
  from jsonb_array_elements(p_rows) r
  left join au.sos_official_line_map lm
    on lower(btrim(lm.official_line)) = lower(btrim(r->>'official_line'))
  where lm.line_code is null;

  if v_unmapped is not null then
    raise exception
      'phx_write_monthly_store_split_net: no line_code for % - refusing to write a net that would join to nothing',
      v_unmapped;
  end if;

  select string_agg(format('%s/%s: qty %s, units %s', line_code, product_code, sq, se), '; ')
    into v_bad
  from (
    select lm.line_code,
           upper(btrim(r->>'product_code')) as product_code,
           sum((r->>'net_qty')::numeric)             as sq,
           sum((r->>'net_effective_units')::numeric) as se
    from jsonb_array_elements(p_rows) r
    join au.sos_official_line_map lm
      on lower(btrim(lm.official_line)) = lower(btrim(r->>'official_line'))
    where lm.line_code <> all (v_frozen)
    group by 1, 2
    having abs(sum((r->>'net_qty')::numeric)) > 1e-9
        or abs(sum((r->>'net_effective_units')::numeric)) > 1e-9
  ) unbalanced;

  if v_bad is not null then
    raise exception
      'phx_write_monthly_store_split_net: net does not balance to zero for % - refusing to write (%)',
      p_period, v_bad;
  end if;

  delete from au.monthly_store_split_net n
  where n.period = p_period
    and n.line_code <> all (v_frozen);

  insert into au.monthly_store_split_net
    (period, line_code, area_code, product_code, net_qty, net_effective_units, computed_at)
  select p_period,
         lm.line_code,
         upper(btrim(r->>'area_code')),
         upper(btrim(r->>'product_code')),
         sum((r->>'net_qty')::numeric),
         sum((r->>'net_effective_units')::numeric),
         now()
  from jsonb_array_elements(p_rows) r
  join au.sos_official_line_map lm
    on lower(btrim(lm.official_line)) = lower(btrim(r->>'official_line'))
  where lm.line_code <> all (v_frozen)
  group by 1, 2, 3, 4
  having abs(sum((r->>'net_qty')::numeric)) > 1e-9
      or abs(sum((r->>'net_effective_units')::numeric)) > 1e-9;

  get diagnostics v_written = row_count;
  return v_written;
end;
$_$;

ALTER FUNCTION public.phx_write_monthly_store_split_net(p_period text, p_rows jsonb) OWNER TO postgres;

--
-- Name: probation_provision_case_on_hire(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.probation_provision_case_on_hire() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_source text;
  v_line_name text;
  v_area_name text;
begin
  v_source := case when tg_op = 'INSERT' then 'hire_trigger' else 'hire_update_trigger' end;

  if new.hr_id is null or new.hire_date is null then
    return new;
  end if;
  if lower(coalesce(new.employment_status, 'active')) in ('terminated', 'resigned', 'inactive') then
    return new;
  end if;
  if position('medical rep' in lower(coalesce(new.job_title, ''))) = 0 then
    return new;
  end if;
  if (new.hire_date + interval '90 days')::date <= (now() at time zone 'Africa/Cairo')::date then
    return new;
  end if;

  select l.name into v_line_name from public.lines l where l.id = new.line_id;
  select a.name into v_area_name from public.areas a where a.id = new.area_id;

  begin
    insert into public.probation_cases (
      employee_hr_id, employee_name, job_title, line_name, area_name, manager_hr_id,
      hire_date, probation_start_date, probation_end_date, status, source, created_by
    ) values (
      new.hr_id, new.full_name, new.job_title, v_line_name, v_area_name, new.manager_hr_id,
      new.hire_date, new.hire_date, (new.hire_date + interval '90 days')::date,
      'active', v_source, 'system'
    )
    on conflict (employee_hr_id) do nothing;
  exception when others then
    begin
      insert into public.probation_provisioning_failures (employee_hr_id, source, error_message)
      values (new.hr_id, v_source, sqlerrm);
    exception when others then
      null;
    end;
  end;

  return new;
end;
$$;

ALTER FUNCTION public.probation_provision_case_on_hire() OWNER TO postgres;

--
-- Name: probation_reanchor_on_hire_date_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.probation_reanchor_on_hire_date_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old_end date;
  v_new_start date;
  v_new_end date;
begin
  if new.hr_id is null or new.hire_date is null then
    return new;
  end if;
  if old.hire_date is not distinct from new.hire_date then
    return new;
  end if;

  v_old_end := (old.hire_date + interval '90 days')::date;
  v_new_start := new.hire_date;
  v_new_end := (new.hire_date + interval '90 days')::date;

  begin
    update public.probation_cases
       set hire_date = new.hire_date,
           probation_start_date = v_new_start,
           probation_end_date = v_new_end,
           updated_at = now()
     where lower(employee_hr_id) = lower(new.hr_id)
       and status = 'active'
       and decision is null
       and hire_date is not distinct from old.hire_date
       and probation_start_date is not distinct from old.hire_date
       and probation_end_date is not distinct from v_old_end;
  exception when others then
    begin
      insert into public.probation_provisioning_failures (employee_hr_id, source, error_message)
      values (new.hr_id, 'reanchor_trigger', sqlerrm);
    exception when others then null;
    end;
  end;

  begin
    update public.notification_events
       set status = 'cancelled',
           updated_at = now()
     where category = 'probation'
       and lower(employee_hr_id) = lower(new.hr_id)
       and status in ('pending', 'scheduled')
       and metadata->>'reminder_type' in (
             'probation_day_30_check',
             'probation_30_days_remaining',
             'probation_15_days_remaining')
       and scheduled_for not in (
             new.hire_date + 30,
             new.hire_date + 60,
             new.hire_date + 75);
  exception when others then
    begin
      insert into public.probation_provisioning_failures (employee_hr_id, source, error_message)
      values (new.hr_id, 'reanchor_trigger_reminders', sqlerrm);
    exception when others then null;
    end;
  end;

  return new;
end;
$$;

ALTER FUNCTION public.probation_reanchor_on_hire_date_change() OWNER TO postgres;

