CREATE FUNCTION public.protect_base_salary() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.base_salary <> OLD.base_salary THEN
    RAISE EXCEPTION 'base_salary is immutable and cannot be changed after creation.';
  END IF;
  RETURN NEW;
END;
$$;

