--
-- Name: sos_claim_brick_move_file(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_claim_brick_move_file(p_old_brick text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_row public.source_of_sales_brick_move_files;
begin
  update public.source_of_sales_brick_move_files f
  set refresh_started_at = now()
  from (
    select f2.old_brick_id, f2.batch_id
    from public.source_of_sales_brick_move_files f2
    where f2.refreshed_at is null
      and (p_old_brick is null or f2.old_brick_id = btrim(p_old_brick))
      and (f2.refresh_started_at is null or f2.refresh_started_at < now() - interval '5 minutes')
    order by f2.moved_at, f2.batch_id
    limit 1
    for update skip locked
  ) pick
  where f.old_brick_id = pick.old_brick_id
    and f.batch_id = pick.batch_id
  returning f.* into v_row;

  if v_row.batch_id is null then
    return null;
  end if;
  return jsonb_build_object('oldBrickId', v_row.old_brick_id, 'batchId', v_row.batch_id, 'movedAt', v_row.moved_at);
end;
$$;

ALTER FUNCTION public.sos_claim_brick_move_file(p_old_brick text) OWNER TO postgres;

--
-- Name: sos_count_reconcilable_import_rows(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_count_reconcilable_import_rows(p_distributor text, p_customer text) RETURNS TABLE(affected_rows integer, affected_batch_ids uuid[], current_bricks jsonb, target_brick_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_target_brick text;
  v_rows integer;
  v_batches uuid[];
  v_current jsonb;
  v_files uuid[] := '{}'::uuid[];
  v_frozen uuid[] := '{}'::uuid[];
begin
  select m.brick_id into v_target_brick
  from public.source_of_sales_customer_map m
  where upper(btrim(m.distributor_code)) = upper(btrim(p_distributor))
    and m.customer_code = p_customer
    and m.active
    and m.brick_id is not null
  limit 1;

  if v_target_brick is null then
    return query select 0, '{}'::uuid[], '{}'::jsonb, null::text;
    return;
  end if;

  -- Files that touch a locked month are left out of the preview because the correction leaves them out.
  -- Collected first, then judged once per file (see the header).
  select coalesce(array_agg(distinct r.batch_id), '{}'::uuid[])
    into v_files
  from public.source_of_sales_import_rows r
  where upper(btrim(r.distributor_code)) = upper(btrim(p_distributor))
    and r.client_code = p_customer
    and r.brick_id is distinct from v_target_brick;

  select coalesce(array_agg(f.batch_id), '{}'::uuid[])
    into v_frozen
  from unnest(v_files) as f(batch_id)
  where public.sos_import_batch_touches_locked_closing(f.batch_id);

  select count(*), coalesce(array_agg(distinct r.batch_id), '{}'::uuid[])
    into v_rows, v_batches
  from public.source_of_sales_import_rows r
  where upper(btrim(r.distributor_code)) = upper(btrim(p_distributor))
    and r.client_code = p_customer
    and r.brick_id is distinct from v_target_brick
    and not (r.batch_id = any (v_frozen));

  select coalesce(jsonb_object_agg(brick_id, cnt), '{}'::jsonb) into v_current
  from (
    select coalesce(nullif(r.brick_id, ''), '(none)') as brick_id, count(*) as cnt
    from public.source_of_sales_import_rows r
    where upper(btrim(r.distributor_code)) = upper(btrim(p_distributor))
      and r.client_code = p_customer
      and r.brick_id is distinct from v_target_brick
      and not (r.batch_id = any (v_frozen))
    group by 1
  ) g;

  return query select v_rows, v_batches, v_current, v_target_brick;
end;
$$;

ALTER FUNCTION public.sos_count_reconcilable_import_rows(p_distributor text, p_customer text) OWNER TO postgres;

--
-- Name: FUNCTION sos_count_reconcilable_import_rows(p_distributor text, p_customer text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sos_count_reconcilable_import_rows(p_distributor text, p_customer text) IS 'Read-only dry-run: counts historical import rows that disagree with the active customer->brick mapping, grouped by their current brick, plus the distinct batch_ids affected. No side effects.';

--
-- Name: sos_customer_map_fill_blanks(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_customer_map_fill_blanks(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    return 0;
  end if;

  with incoming as (
    -- One candidate per key; a row that carries a value wins over one that does not.
    select distinct on (x.distributor_code, x.customer_code)
           x.distributor_code,
           x.customer_code,
           nullif(btrim(x.customer_name), '') as customer_name,
           nullif(btrim(x.address), '') as address
    from jsonb_to_recordset(p_rows)
           as x(distributor_code text, customer_code text, customer_name text, address text)
    where x.distributor_code is not null
      and x.customer_code is not null
    order by x.distributor_code,
             x.customer_code,
             (nullif(btrim(x.customer_name), '') is null),
             (nullif(btrim(x.address), '') is null)
  ),
  filled as (
    update public.source_of_sales_customer_map m
    set customer_name = case when nullif(btrim(m.customer_name), '') is null
                             then coalesce(i.customer_name, m.customer_name)
                             else m.customer_name end,
        address       = case when nullif(btrim(m.address), '') is null
                             then coalesce(i.address, m.address)
                             else m.address end
    from incoming i
    where m.distributor_code = i.distributor_code
      and m.customer_code = i.customer_code
      and (   (nullif(btrim(m.customer_name), '') is null and i.customer_name is not null)
           or (nullif(btrim(m.address), '') is null and i.address is not null))
    returning m.id
  )
  select count(*)::integer into v_count from filled;

  return v_count;
end;
$$;

ALTER FUNCTION public.sos_customer_map_fill_blanks(p_rows jsonb) OWNER TO postgres;

--
-- Name: FUNCTION sos_customer_map_fill_blanks(p_rows jsonb); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sos_customer_map_fill_blanks(p_rows jsonb) IS 'Fills a customer mapping''s blank customer_name / address from [{distributor_code, customer_code, customer_name, address}], matched exactly on the conflict key. Never overwrites a stored value and never touches the brick, area, region, source, confidence or active flag. Returns the number of mappings that gained a name or an address.';

--
-- Name: sos_finish_brick_move_file(text, uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_finish_brick_move_file(p_old_brick text, p_batch_id uuid, p_moved_at timestamp with time zone, p_refreshed boolean) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with done as (
    update public.source_of_sales_brick_move_files f
    set refreshed_at       = case when p_refreshed and f.moved_at = p_moved_at then now() else f.refreshed_at end,
        refresh_started_at = null
    where f.old_brick_id = btrim(p_old_brick)
      and f.batch_id = p_batch_id
    returning f.refreshed_at is not null as refreshed
  )
  select coalesce((select d.refreshed from done d), false);
$$;

ALTER FUNCTION public.sos_finish_brick_move_file(p_old_brick text, p_batch_id uuid, p_moved_at timestamp with time zone, p_refreshed boolean) OWNER TO postgres;

--
-- Name: sos_import_batch_touches_locked_closing(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_import_batch_touches_locked_closing(p_batch_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.source_of_sales_import_rows r
    join public.source_of_sales_import_batches b on b.id = r.batch_id
    join public.monthly_closing_locks l
      on l.unlocked_at is null
     and l.normalized_line = lower(btrim(coalesce(r.official_line, '')))
     and l.period in (r.invoice_period, b.period)
    where r.batch_id = p_batch_id
  );
$$;

ALTER FUNCTION public.sos_import_batch_touches_locked_closing(p_batch_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION sos_import_batch_touches_locked_closing(p_batch_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sos_import_batch_touches_locked_closing(p_batch_id uuid) IS 'True when any row of this sales file sits in an open monthly-closing lock (on its own month or the file''s). Such a file is left whole by every history heal and correction: its totals cannot be rebuilt while the lock stands.';

--
-- Name: sos_map_hold_distributor_facts(bigint[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_map_hold_distributor_facts(p_hold_ids bigint[]) RETURNS TABLE(hold_id bigint, period text, filed_name text, filed_address text, filed_brick_id text, filed_brick_name text, filed_area text, filed_region text, rows_filed bigint, last_filed timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select h.id,
         r.invoice_period,
         nullif(trim(coalesce(r.client_name, '')), ''),
         nullif(trim(coalesce(r.client_address, '')), ''),
         nullif(trim(coalesce(r.brick_id, '')), ''),
         nullif(trim(coalesce(b.brick_name, '')), ''),
         nullif(trim(coalesce(r.area_name, '')), ''),
         nullif(trim(coalesce(r.region_name, '')), ''),
         count(*)::bigint,
         max(r.created_at)
  from public.sos_map_change_holds h
  join public.source_of_sales_customer_map m on m.id = h.row_id
  join public.source_of_sales_import_rows r
    on upper(trim(coalesce(r.distributor_code, ''))) = upper(trim(coalesce(m.distributor_code, '')))
   and trim(coalesce(r.client_code, '')) = trim(coalesce(m.customer_code, ''))
  left join public.source_of_sales_bricks b
    on upper(trim(coalesce(b.brick_id, ''))) = upper(trim(coalesce(r.brick_id, '')))
  where h.id = any(p_hold_ids)
    and h.table_name = 'source_of_sales_customer_map'
  group by h.id, r.invoice_period, r.client_name, r.client_address, r.brick_id, b.brick_name,
           r.area_name, r.region_name
$$;

ALTER FUNCTION public.sos_map_hold_distributor_facts(p_hold_ids bigint[]) OWNER TO postgres;

--
-- Name: FUNCTION sos_map_hold_distributor_facts(p_hold_ids bigint[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sos_map_hold_distributor_facts(p_hold_ids bigint[]) IS 'What each distributor file itself carried for a held customer - name, address, brick, area and governorate as filed, per month and per distinct variant.';

--
-- Name: sos_map_hold_sales_impact(bigint[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_map_hold_sales_impact(p_hold_ids bigint[], p_lines text[]) RETURNS TABLE(hold_id bigint, period text, tracked_value numeric, row_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select h.id,
         r.invoice_period,
         sum(coalesce(r.value, 0))::numeric,
         count(*)::bigint
  from public.sos_map_change_holds h
  join public.source_of_sales_customer_map m on m.id = h.row_id
  join public.source_of_sales_import_rows r
    on upper(trim(coalesce(r.distributor_code, ''))) = upper(trim(coalesce(m.distributor_code, '')))
   and trim(coalesce(r.client_code, '')) = trim(coalesce(m.customer_code, ''))
  where h.id = any(p_hold_ids)
    and h.table_name = 'source_of_sales_customer_map'
    and r.official_line = any(p_lines)
    -- 'valid', never 'validated'. The other spelling matches nothing and reads as a customer with
    -- no sales at all, which on this screen is the difference between "nothing rides on this" and
    -- thirty thousand pounds.
    and r.validation_state = 'valid'
    and r.invoice_period is not null
  group by h.id, r.invoice_period
$$;

ALTER FUNCTION public.sos_map_hold_sales_impact(p_hold_ids bigint[], p_lines text[]) OWNER TO postgres;

--
-- Name: FUNCTION sos_map_hold_sales_impact(p_hold_ids bigint[], p_lines text[]); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sos_map_hold_sales_impact(p_hold_ids bigint[], p_lines text[]) IS 'Tracked sales value per month behind each held customer mapping - what releasing it would re-credit to another area.';

--
-- Name: sos_map_region_of_area(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_map_region_of_area(p_area_code text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select upper(trim(a.region_code))
  from public.source_of_sales_areas a
  where upper(trim(a.area_code)) = upper(trim(p_area_code))
  limit 1;
$$;

ALTER FUNCTION public.sos_map_region_of_area(p_area_code text) OWNER TO postgres;

--
-- Name: sos_move_brick_sales(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_move_brick_sales(p_old_brick text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
declare
  v_old         public.source_of_sales_bricks;
  v_new         public.source_of_sales_bricks;
  v_hops        integer := 0;
  v_area_name   text;
  v_region_name text;
  v_batches     uuid[];
  v_frozen      uuid[];
  v_moved       integer := 0;
  v_files       integer := 0;
  v_published   integer := 0;
  v_waiting     integer := 0;
  v_pending     integer := 0;
begin
  select * into v_old from public.source_of_sales_bricks b where b.brick_id = btrim(p_old_brick);
  if not found then
    raise exception 'That brick is no longer in the brick master.';
  end if;
  if v_old.superseded_by_brick_id is null then
    raise exception '% has not been moved, so it has no sales to carry.', v_old.brick_name;
  end if;

  -- A brick moved twice carries its sales to where it is today, not to the stop in between.
  select * into v_new from public.source_of_sales_bricks b where b.brick_id = v_old.superseded_by_brick_id;
  while found and v_new.superseded_by_brick_id is not null loop
    v_hops := v_hops + 1;
    if v_hops > 50 then
      raise exception 'The move history of % does not end. Nothing was moved.', v_old.brick_name;
    end if;
    select * into v_new from public.source_of_sales_bricks b where b.brick_id = v_new.superseded_by_brick_id;
  end loop;
  if v_new.brick_id is null then
    raise exception 'The brick % moved to is no longer in the brick master. Nothing was moved.', v_old.brick_name;
  end if;
  if v_new.active is false then
    raise exception '% is switched off, so the sales of % cannot move onto it.', v_new.brick_name, v_old.brick_name;
  end if;

  select a.area_name into v_area_name from public.source_of_sales_areas a where a.area_code = v_new.area_code;
  select g.region_name into v_region_name from public.source_of_sales_regions g where g.region_code = v_new.region_code;

  -- A file touching a locked month is left whole: its published rows cannot change, and its totals
  -- could never be rebuilt if any other row in it moved (the rule of 20260918143000).
  -- The files are collected first and each is judged once (see the header).
  select coalesce(array_agg(distinct r.batch_id), '{}'::uuid[]) into v_batches
  from public.source_of_sales_import_rows r
  where r.brick_id = v_old.brick_id;

  select coalesce(array_agg(f.batch_id), '{}'::uuid[]) into v_frozen
  from unnest(v_batches) as f(batch_id)
  where public.sos_import_batch_touches_locked_closing(f.batch_id);

  -- A row follows the brick unless its pharmacy's live mapping points somewhere else: still on the
  -- old brick (held on the Mapping guard, or kept there by the owner's rejection) or on another
  -- brick altogether (which the history correction answers for, not a move).
  with moved as (
    update public.source_of_sales_import_rows r
    set brick_id    = v_new.brick_id,
        block_code  = case when nullif(btrim(r.block_code), '') is null then r.block_code else v_new.block_code end,
        area_code   = v_new.area_code,
        area_name   = coalesce(v_area_name, r.area_name),
        region_code = v_new.region_code,
        region_name = coalesce(v_region_name, r.region_name)
    where r.brick_id = v_old.brick_id
      and r.batch_id <> all (v_frozen)
      and not exists (
        select 1
        from public.source_of_sales_customer_map m
        where m.active
          and m.distributor_code = r.distributor_code
          and m.customer_code = r.client_code
          and m.brick_id is distinct from v_new.brick_id
      )
    returning r.batch_id
  ),
  per_file as (
    select mv.batch_id, count(*)::integer as n
    from moved mv
    group by mv.batch_id
  ),
  saved as (
    insert into public.source_of_sales_brick_move_files as f (old_brick_id, batch_id, moved_rows)
    select v_old.brick_id, pf.batch_id, pf.n
    from per_file pf
    on conflict (old_brick_id, batch_id) do update
      set moved_rows   = f.moved_rows + excluded.moved_rows,
          moved_at     = now(),
          refreshed_at = null
    returning 1
  )
  select coalesce((select sum(pf.n) from per_file pf), 0)::integer,
         (select count(*) from saved)::integer
    into v_moved, v_files;

  select count(*)::integer into v_published
  from public.source_of_sales_import_rows r
  where r.brick_id = v_old.brick_id
    and r.batch_id = any (v_frozen);

  select count(*)::integer into v_waiting
  from public.source_of_sales_import_rows r
  join (
    select distinct h.before_json->>'distributor_code' as distributor_code,
                    h.before_json->>'customer_code'    as customer_code
    from public.sos_map_change_holds h
    where h.status = 'pending'
      and h.table_name = 'source_of_sales_customer_map'
      and h.before_json->>'brick_id' = v_old.brick_id
  ) w on w.distributor_code = r.distributor_code and w.customer_code = r.client_code
  where r.brick_id = v_old.brick_id
    and r.batch_id <> all (v_frozen);

  select count(*)::integer into v_pending
  from public.source_of_sales_brick_move_files f
  where f.old_brick_id = v_old.brick_id
    and f.refreshed_at is null;

  return jsonb_build_object(
    'toBrickId',     v_new.brick_id,
    'movedRows',     v_moved,
    'movedFiles',    v_files,
    'publishedRows', v_published,
    'waitingRows',   v_waiting,
    'pendingFiles',  v_pending
  );
end;
$$;

ALTER FUNCTION public.sos_move_brick_sales(p_old_brick text) OWNER TO postgres;

--
-- Name: sos_reconcile_import_rows_from_customer_map(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_reconcile_import_rows_from_customer_map(p_distributor text, p_customer text) RETURNS TABLE(updated_rows integer, affected_batch_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rows integer := 0;
  v_batches uuid[] := '{}'::uuid[];
  v_files uuid[] := '{}'::uuid[];
  v_frozen uuid[] := '{}'::uuid[];
  v_brick text;
  v_area text;
  v_region text;
  v_area_name text;
  v_region_name text;
begin
  select m.brick_id, b.area_code, b.region_code, a.area_name, g.region_name
    into v_brick, v_area, v_region, v_area_name, v_region_name
  from public.source_of_sales_customer_map m
  join public.source_of_sales_bricks b on b.brick_id = m.brick_id
  left join public.source_of_sales_areas a on a.area_code = b.area_code
  left join public.source_of_sales_regions g on g.region_code = b.region_code
  where m.distributor_code = p_distributor
    and m.customer_code = p_customer
    and m.active
    and m.brick_id is not null
  limit 1;

  if v_brick is null then
    return query select 0, '{}'::uuid[];
    return;
  end if;

  -- Files this correction would touch that hold a locked row. They stay whole (see 20260918143000).
  -- Collected first, then judged once per file (see 20260918143100).
  select coalesce(array_agg(distinct r.batch_id), '{}'::uuid[])
    into v_files
  from public.source_of_sales_import_rows r
  where r.distributor_code = p_distributor
    and r.client_code = p_customer
    and (   r.brick_id    is distinct from v_brick
         or r.area_code   is distinct from v_area
         or r.region_code is distinct from v_region );

  select coalesce(array_agg(f.batch_id), '{}'::uuid[])
    into v_frozen
  from unnest(v_files) as f(batch_id)
  where public.sos_import_batch_touches_locked_closing(f.batch_id);

  with updated as (
    update public.source_of_sales_import_rows r
    set brick_id = v_brick,
        area_code = v_area,
        area_name = coalesce(v_area_name, r.area_name),
        region_code = v_region,
        region_name = coalesce(v_region_name, r.region_name)
    -- The same row as the statement found it, so the brick each row LEFT can be returned.
    from public.source_of_sales_import_rows pre
    where pre.id = r.id
      and r.distributor_code = p_distributor
      and r.client_code = p_customer
      and (   r.brick_id    is distinct from v_brick
           or r.area_code   is distinct from v_area
           or r.region_code is distinct from v_region )
      -- A file that touches a locked month is never changed, so its totals never need a rebuild.
      and not (r.batch_id = any (v_frozen))
    returning r.batch_id, pre.brick_id as left_brick_id
  ),
  per_file as (
    select u.batch_id, count(*)::integer as moved_rows
    from updated u
    group by u.batch_id
  ),
  -- The brick most of a file's moved rows left, when the brick master holds it (the queue's key
  -- references the master; an empty or unknown brick cannot key a row).
  left_brick as (
    select distinct on (u.batch_id) u.batch_id, u.left_brick_id
    from updated u
    join public.source_of_sales_bricks b on b.brick_id = u.left_brick_id
    group by u.batch_id, u.left_brick_id
    order by u.batch_id, count(*) desc, u.left_brick_id
  ),
  -- A file already waiting for a rebuild keeps its row: re-stamped below, never queued twice.
  waiting as (
    select distinct on (q.batch_id) q.batch_id, q.old_brick_id
    from public.source_of_sales_brick_move_files q
    join per_file pf on pf.batch_id = q.batch_id
    where q.refreshed_at is null
    order by q.batch_id, q.moved_at desc, q.old_brick_id
  ),
  -- One key per file: the waiting row's, else the brick the rows left, else the brick they joined.
  keyed as (
    select coalesce(w.old_brick_id, lb.left_brick_id, v_brick) as old_brick_id, pf.batch_id, pf.moved_rows
    from per_file pf
    left join waiting w on w.batch_id = pf.batch_id
    left join left_brick lb on lb.batch_id = pf.batch_id
  ),
  -- Runs to completion with the update above, as one statement: a moved row's file is always queued.
  queued as (
    insert into public.source_of_sales_brick_move_files as f (old_brick_id, batch_id, moved_rows)
    select k.old_brick_id, k.batch_id, k.moved_rows
    from keyed k
    on conflict (old_brick_id, batch_id) do update
      set moved_rows   = f.moved_rows + excluded.moved_rows,
          moved_at     = now(),
          refreshed_at = null
    returning f.batch_id
  )
  select coalesce((select sum(pf.moved_rows) from per_file pf), 0)::integer,
         coalesce((select array_agg(q.batch_id order by q.batch_id) from queued q), '{}'::uuid[])
    into v_rows, v_batches;

  return query select v_rows, v_batches;
end;
$$;

ALTER FUNCTION public.sos_reconcile_import_rows_from_customer_map(p_distributor text, p_customer text) OWNER TO postgres;

--
-- Name: FUNCTION sos_reconcile_import_rows_from_customer_map(p_distributor text, p_customer text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.sos_reconcile_import_rows_from_customer_map(p_distributor text, p_customer text) IS 'Overwrites brick/area/region on EVERY historical import row for (distributor, customer) that disagrees with the active customer->brick mapping (not just NULL ones, unlike sos_backfill_import_rows_from_customer_map). Returns the updated row count and the distinct batch_ids touched so the caller can refresh their rollups. Always explicit/admin-triggered — never called automatically from a routine upload.';

--
-- Name: sos_relocate_brick(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_relocate_brick(p_brick_id text, p_block_code text, p_brick_name text, p_normalized_brick_name text, p_historical_name text, p_normalized_historical_name text, p_actor text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $_$
declare
  v_today           date := (now() at time zone 'Africa/Cairo')::date;
  v_old             public.source_of_sales_bricks;
  v_block           public.source_of_sales_blocks;
  v_block_label     text;
  v_from_area       text;
  v_to_area         text;
  v_pending         integer;
  v_prefix          text;
  v_seq             bigint;
  v_new             text;
  v_tries           integer := 0;
  v_until           date;
  v_customers_moved integer;
  v_switched_off    integer;
  v_customers_held  integer;
  v_aliases         integer;
  v_pharmacies      integer;
  v_codes           integer;
  v_answers         integer;
  v_sales           jsonb;
begin
  -- The mapping guard records who asked for every change it logs or holds.
  if nullif(btrim(coalesce(p_actor, '')), '') is not null then
    perform set_config('phoenix.actor', btrim(p_actor), true);
  end if;

  if nullif(btrim(coalesce(p_brick_name, '')), '') is null
     or nullif(btrim(coalesce(p_normalized_brick_name, '')), '') is null then
    raise exception 'The moved brick needs a name.';
  end if;
  if nullif(btrim(coalesce(p_historical_name, '')), '') is null
     or nullif(btrim(coalesce(p_normalized_historical_name, '')), '') is null then
    raise exception 'The old brick needs a name to keep as its history.';
  end if;
  if p_normalized_brick_name = p_normalized_historical_name then
    raise exception 'The moved brick and the history it leaves behind cannot share the name %.', btrim(p_brick_name);
  end if;

  select * into v_old
  from public.source_of_sales_bricks b
  where b.brick_id = btrim(p_brick_id)
  for update;
  if not found then
    raise exception 'That brick is no longer in the brick master. Reload the page and try again.';
  end if;
  if v_old.active is false then
    raise exception '% is switched off. Switch it back on before moving it.', v_old.brick_name;
  end if;
  if v_old.superseded_by_brick_id is not null then
    raise exception '% is kept only as history: it has already moved. Correct the brick it moved to instead.', v_old.brick_name;
  end if;

  select * into v_block
  from public.source_of_sales_blocks bl
  where upper(btrim(bl.block_code)) = upper(btrim(coalesce(p_block_code, '')))
  order by bl.block_code
  limit 1
  for share;
  if not found then
    raise exception 'The block you picked is not in the block master. Reload the page and try again.';
  end if;
  v_block_label := coalesce(
    nullif(btrim(v_block.display_name), ''),
    (select mb.brick_name from public.source_of_sales_bricks mb where mb.brick_id = v_block.master_brick_id),
    nullif(btrim(v_block.description), ''),
    v_block.block_code
  );
  if v_block.active is false then
    raise exception 'The block % is switched off. Switch it back on before moving a brick into it.', v_block_label;
  end if;
  if upper(btrim(v_block.block_code)) = upper(btrim(v_old.block_code)) then
    raise exception '% is already in that block.', v_old.brick_name;
  end if;

  select a.area_name into v_from_area from public.source_of_sales_areas a where a.area_code = v_old.area_code;
  select a.area_name into v_to_area from public.source_of_sales_areas a where a.area_code = v_block.area_code;
  v_from_area := coalesce(v_from_area, v_old.area_code);
  v_to_area := coalesce(v_to_area, v_block.area_code);

  -- A change already waiting on the Mapping guard would land on the wrong side of the move once
  -- approved (onto the history brick, or into a second hold for the same pharmacy).
  select count(*)::integer into v_pending
  from public.sos_map_change_holds h
  where h.status = 'pending'
    and (
      (h.table_name = 'source_of_sales_customer_map'
       and (upper(btrim(coalesce(h.before_json->>'brick_id', ''))) = upper(v_old.brick_id)
            or upper(btrim(coalesce(h.after_json->>'brick_id', ''))) = upper(v_old.brick_id)))
      or (h.table_name = 'source_of_sales_bricks'
          and upper(btrim(h.entity_key)) = upper(v_old.brick_id))
    );
  if v_pending > 0 then
    raise exception '% has % change(s) waiting for you on the Mapping guard. Decide those first, then move it.',
      v_old.brick_name, v_pending;
  end if;

  -- Brick names are unique by the owner's rule of 2026-09-11.
  if exists (
    select 1 from public.source_of_sales_bricks b
    where b.brick_id <> v_old.brick_id
      and b.normalized_brick_name = p_normalized_brick_name
  ) then
    raise exception 'Another brick is already named %. Pick a different name.', btrim(p_brick_name);
  end if;
  if exists (
    select 1 from public.source_of_sales_bricks b
    where b.brick_id <> v_old.brick_id
      and b.normalized_brick_name = p_normalized_historical_name
  ) then
    raise exception 'Another brick is already named %, the name % would keep as its history.',
      btrim(p_historical_name), v_old.brick_name;
  end if;

  -- The next "<block>-<n>" id. Skip any id that something already points at: the territory aliases
  -- hold references to ids that are not bricks, and a new brick must never inherit one.
  v_prefix := upper(btrim(v_block.block_code)) || '-';
  select coalesce(max(substr(b.brick_id, length(v_prefix) + 1)::bigint), 0) + 1 into v_seq
  from public.source_of_sales_bricks b
  where upper(left(b.brick_id, length(v_prefix))) = v_prefix
    and substr(b.brick_id, length(v_prefix) + 1) ~ '^[0-9]{1,9}$';
  loop
    v_new := v_prefix || v_seq::text;
    exit when not exists (select 1 from public.source_of_sales_bricks b where upper(btrim(b.brick_id)) = upper(v_new))
      and not exists (
        select 1 from public.source_of_sales_territory_aliases a
        where a.target_type = 'brick' and upper(btrim(a.target_code)) = upper(v_new))
      and not exists (select 1 from public.source_of_sales_customer_map m where upper(btrim(m.brick_id)) = upper(v_new))
      and not exists (select 1 from public.source_of_sales_import_rows r where r.brick_id = v_new)
      and not exists (select 1 from public.source_of_sales_customer_ai_answers x where upper(btrim(x.brick_id)) = upper(v_new))
      and not exists (select 1 from public.direct_order_pharmacies d where upper(btrim(d.brick_id)) = upper(v_new))
      and not exists (
        select 1 from public.direct_order_pharmacy_distributor_codes c
        where upper(btrim(c.mapped_brick_id)) = upper(v_new));
    v_seq := v_seq + 1;
    v_tries := v_tries + 1;
    if v_tries >= 500 then
      raise exception 'No free brick number was found in the block %. Nothing was moved.', v_block_label;
    end if;
  end loop;

  insert into public.source_of_sales_bricks (
    brick_id, brick_name, normalized_brick_name, block_code, area_code, region_code,
    description, normalized_description, active, effective_from, source_file, source_sheet
  ) values (
    v_new, btrim(p_brick_name), p_normalized_brick_name, v_block.block_code, v_block.area_code, v_block.region_code,
    btrim(p_brick_name), p_normalized_brick_name, true, v_today,
    'Database Mapping brick move ' || to_char(v_today, 'YYYY-MM-DD'), 'Bricks'
  );

  -- The old brick keeps its area (so the brick guard passes) and stays active (so published months
  -- keep resolving). Only its name, its description and its dates say it is history now. An end
  -- date it already carries is kept; otherwise it ends yesterday (never before it began).
  v_until := least(coalesce(v_old.effective_to, v_today - 1), v_today - 1);
  if v_old.effective_from is not null and v_until < v_old.effective_from then
    v_until := v_old.effective_from;
  end if;
  update public.source_of_sales_bricks b
  set brick_name             = btrim(p_historical_name),
      normalized_brick_name  = p_normalized_historical_name,
      description            = format('%s — %s up to %s (historical; moved to %s)',
                                      v_old.brick_name, v_from_area,
                                      to_char(v_until, 'FMDD FMMonth YYYY'), v_to_area),
      effective_to           = v_until,
      superseded_by_brick_id = v_new,
      updated_at             = now()
  where b.brick_id = v_old.brick_id;

  -- Through the mapping guard: a held row is dropped from this statement and filed as a hold, so the
  -- held count is read from the holds, never from what came back.
  with moved as (
    update public.source_of_sales_customer_map m
    set brick_id    = v_new,
        area_code   = v_block.area_code,
        region_code = v_block.region_code,
        updated_at  = now()
    where m.brick_id = v_old.brick_id
    returning m.active
  )
  select count(*) filter (where mv.active)::integer,
         count(*) filter (where mv.active is not true)::integer
    into v_customers_moved, v_switched_off
  from moved mv;

  select count(*)::integer into v_customers_held
  from public.sos_map_change_holds h
  where h.status = 'pending'
    and h.table_name = 'source_of_sales_customer_map'
    and h.before_json->>'brick_id' = v_old.brick_id
    and h.after_json->>'brick_id' = v_new;

  with moved as (
    update public.source_of_sales_territory_aliases a
    set target_code = v_new, updated_at = now()
    where a.target_type = 'brick'
      and upper(btrim(a.target_code)) = upper(v_old.brick_id)
    returning 1
  )
  select count(*)::integer into v_aliases from moved;

  with moved as (
    update public.direct_order_pharmacies d
    set brick_id    = v_new,
        area_code   = v_block.area_code,
        region_code = v_block.region_code,
        updated_at  = now()
    where d.brick_id = v_old.brick_id
    returning 1
  )
  select count(*)::integer into v_pharmacies from moved;

  with moved as (
    update public.direct_order_pharmacy_distributor_codes c
    set mapped_brick_id    = v_new,
        mapped_area_code   = v_block.area_code,
        mapped_region_code = v_block.region_code
    where c.mapped_brick_id = v_old.brick_id
    returning 1
  )
  select count(*)::integer into v_codes from moved;

  with moved as (
    update public.source_of_sales_customer_ai_answers x
    set brick_id = v_new
    where x.brick_id = v_old.brick_id
    returning 1
  )
  select count(*)::integer into v_answers from moved;

  v_sales := public.sos_move_brick_sales(v_old.brick_id);

  return jsonb_build_object(
    'newBrickId',            v_new,
    'newBrickName',          btrim(p_brick_name),
    'historicalName',        btrim(p_historical_name),
    'fromAreaName',          v_from_area,
    'toAreaName',            v_to_area,
    'toBlockLabel',          v_block_label,
    'customersMoved',        v_customers_moved,
    'switchedOffMoved',      v_switched_off,
    'customersHeld',         v_customers_held,
    'aliasesMoved',          v_aliases,
    'directPharmaciesMoved', v_pharmacies,
    'directCodesMoved',      v_codes,
    'aiAnswersMoved',        v_answers
  ) || v_sales;
end;
$_$;

ALTER FUNCTION public.sos_relocate_brick(p_brick_id text, p_block_code text, p_brick_name text, p_normalized_brick_name text, p_historical_name text, p_normalized_historical_name text, p_actor text) OWNER TO postgres;

--
-- Name: sos_unmapped_customers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sos_unmapped_customers() RETURNS TABLE(distributor_code text, customer_code text, customer_name text, address text, why text, last_brick_id text, last_area_code text, last_source text, switched_off_at timestamp with time zone, sales_rows bigint, first_period text, last_period text, lines text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
  with sales as (
    select r.distributor_code, r.client_code as customer_code, count(*) as sales_rows,
           min(r.invoice_period) as first_period, max(r.invoice_period) as last_period,
           string_agg(distinct r.official_line, ', ' order by r.official_line) as lines,
           (array_agg(r.client_name order by r.id desc))[1] as client_name,
           (array_agg(r.client_address order by r.id desc))[1] as client_address
      from public.source_of_sales_import_rows r
     where r.client_code is not null and btrim(r.client_code) <> ''
     group by r.distributor_code, r.client_code
  ), off_rows as (
    select distinct on (m.distributor_code, m.customer_code)
           m.distributor_code, m.customer_code, m.customer_name, m.address, m.brick_id, m.area_code, m.source, m.updated_at
      from public.source_of_sales_customer_map m
     where not m.active
     order by m.distributor_code, m.customer_code, m.updated_at desc
  )
  select coalesce(o.distributor_code, s.distributor_code),
         coalesce(o.customer_code, s.customer_code),
         coalesce(nullif(o.customer_name, ''), s.client_name),
         coalesce(nullif(o.address, ''), s.client_address),
         case when o.customer_code is not null then 'switched off' else 'never mapped' end,
         o.brick_id, o.area_code, o.source, o.updated_at,
         coalesce(s.sales_rows, 0), s.first_period, s.last_period, s.lines
    from sales s
    full join off_rows o on o.distributor_code = s.distributor_code and o.customer_code = s.customer_code
   where not exists (
     select 1 from public.source_of_sales_customer_map a
      where a.active
        and a.distributor_code = coalesce(o.distributor_code, s.distributor_code)
        and a.customer_code = coalesce(o.customer_code, s.customer_code)
   )
   order by 1, 2
$$;

ALTER FUNCTION public.sos_unmapped_customers() OWNER TO postgres;

--
-- Name: submit_coaching_report(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.submit_coaching_report(p_report_id uuid, p_actor_hr_id text, p_area_of_development text DEFAULT NULL::text, p_strength_points text DEFAULT NULL::text, p_general_remarks text DEFAULT NULL::text, p_scores jsonb DEFAULT NULL::jsonb) RETURNS public.coaching_reports
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_report public.coaching_reports%rowtype;
  v_updated public.coaching_reports%rowtype;
  v_actual_score numeric(10, 2);
  v_score_count int;
  v_final_percent numeric(6, 2);
  v_zone text;
begin
  select * into v_report from public.coaching_reports where id = p_report_id for update;
  if not found then raise exception 'Coaching report was not found.'; end if;
  if v_report.status <> 'draft' then raise exception 'Only draft coaching reports can be submitted.'; end if;

  if p_scores is not null then
    if jsonb_typeof(p_scores) <> 'object' then raise exception 'Coaching scores must be a JSON object.'; end if;

    with provided as (
      select key, case when jsonb_typeof(value) = 'object' then value ->> 'score' else value #>> '{}' end as score_text
      from jsonb_each(p_scores)
    )
    select count(*) into v_score_count from provided;

    if v_score_count <> 20 then raise exception 'Exactly 20 coaching scores are required before submission.'; end if;

    if exists (
      with expected(score_item_key) as (
        values
          ('medical_patient_knowledge'), ('product_knowledge'), ('competitor_knowledge'),
          ('opening_patient_profile_attractive_approach'), ('asking_questions_probing'),
          ('presentation_skills'), ('closing_asking_for_business'), ('handling_customer_objection'),
          ('body_language_tone_of_voice'), ('professional_pharmacy_feedback'),
          ('assertiveness_asking_for_business'), ('customer_adaptation_relationship'),
          ('time_territory_planning'), ('using_promotional_material'), ('pre_call_planning'),
          ('execution_follow_up'), ('appearance'), ('dress_code'), ('attitude'), ('discipline')
      ),
      provided as (
        select key, case when jsonb_typeof(value) = 'object' then value ->> 'score' else value #>> '{}' end as score_text
        from jsonb_each(p_scores)
      )
      select 1
      from provided p
      full outer join expected e on e.score_item_key = p.key
      where e.score_item_key is null or p.key is null or p.score_text is null
        or p.score_text !~ '^[0-9]+$' or p.score_text::int < 0 or p.score_text::int > 5
    ) then
      raise exception 'Coaching score payload contains missing, unknown, or out-of-range items.';
    end if;

    delete from public.coaching_score_items where report_id = p_report_id;

    insert into public.coaching_score_items (report_id, parameter_category, score_item_key, score_item_label, score, display_order, area_to_be_improved, strength_point)
    with expected(score_item_key, parameter_category, score_item_label, display_order) as (
      values
        ('medical_patient_knowledge', 'knowledge', 'Medical & Patient/Physician Knowledge', 1),
        ('product_knowledge', 'knowledge', 'Product Knowledge', 2),
        ('competitor_knowledge', 'knowledge', 'Competitor Knowledge', 3),
        ('opening_patient_profile_attractive_approach', 'call_structure_skills', 'Opening, Patient Profile & Attractive Approach', 4),
        ('asking_questions_probing', 'call_structure_skills', 'Asking Questions / Probing', 5),
        ('presentation_skills', 'call_structure_skills', 'Presentation Skills', 6),
        ('closing_asking_for_business', 'call_structure_skills', 'Closing & Asking for Business', 7),
        ('handling_customer_objection', 'business_intelligence', 'Handling Customer Objection', 8),
        ('body_language_tone_of_voice', 'business_intelligence', 'Body Language & Tone of Voice', 9),
        ('professional_pharmacy_feedback', 'business_intelligence', 'Professional Pharmacy Feedback', 10),
        ('assertiveness_asking_for_business', 'business_intelligence', 'Assertiveness in Asking for Business', 11),
        ('customer_adaptation_relationship', 'business_intelligence', 'Customer Adaptation & Relationship', 12),
        ('time_territory_planning', 'business_planning', 'Time & Territory Planning', 13),
        ('using_promotional_material', 'business_planning', 'Using Promotional Material', 14),
        ('pre_call_planning', 'business_planning', 'Pre-Call Planning', 15),
        ('execution_follow_up', 'business_planning', 'Execution & Follow-Up', 16),
        ('appearance', 'personal_skills', 'Appearance', 17),
        ('dress_code', 'personal_skills', 'Dress Code', 18),
        ('attitude', 'personal_skills', 'Attitude', 19),
        ('discipline', 'personal_skills', 'Discipline', 20)
    ),
    normalized as (
      select e.*, p_scores -> e.score_item_key as raw_value from expected e
    )
    select
      p_report_id,
      parameter_category,
      score_item_key,
      score_item_label,
      case when jsonb_typeof(raw_value) = 'object' then (raw_value ->> 'score')::int else (raw_value #>> '{}')::int end,
      display_order,
      nullif(btrim(case when jsonb_typeof(raw_value) = 'object' then raw_value ->> 'areaToBeImproved' else null end), ''),
      nullif(btrim(case when jsonb_typeof(raw_value) = 'object' then raw_value ->> 'strengthPoint' else null end), '')
    from normalized;
  end if;

  select count(*), coalesce(sum(score), 0) into v_score_count, v_actual_score
  from public.coaching_score_items where report_id = p_report_id;

  if v_score_count <> 20 then raise exception 'Exactly 20 coaching scores are required before submission.'; end if;

  v_final_percent := round((v_actual_score / 100) * 100, 2);
  v_zone := case
    when v_final_percent < 50 then 'critical_red'
    when v_final_percent <= 65 then 'red_zone'
    when v_final_percent <= 80 then 'yellow_zone'
    when v_final_percent <= 90 then 'green_zone'
    else 'excellence_zone'
  end;

  update public.coaching_reports
  set
    actual_score = v_actual_score,
    area_of_development = coalesce(p_area_of_development, area_of_development),
    final_score_percent = v_final_percent,
    general_remarks = coalesce(p_general_remarks, general_remarks),
    max_score = 100,
    performance_zone = v_zone,
    status = 'submitted',
    strength_points = coalesce(p_strength_points, strength_points),
    submitted_at = coalesce(submitted_at, now()),
    locked_at = null,
    updated_by = p_actor_hr_id
  where id = p_report_id
  returning * into v_updated;

  insert into public.coaching_report_audit_logs (report_id, actor_hr_id, action, old_values, new_values)
  values (
    p_report_id, p_actor_hr_id, 'submitted',
    jsonb_build_object('status', v_report.status),
    jsonb_build_object('status', 'submitted', 'actualScore', v_actual_score, 'finalScorePercent', v_final_percent, 'performanceZone', v_zone)
  );

  return v_updated;
end;
$_$;

ALTER FUNCTION public.submit_coaching_report(p_report_id uuid, p_actor_hr_id text, p_area_of_development text, p_strength_points text, p_general_remarks text, p_scores jsonb) OWNER TO postgres;

--
-- Name: system_audit_acquire_lease(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.system_audit_acquire_lease(p_detector text, p_holder text, p_seconds integer) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_ok boolean;
begin
  insert into public.system_audit_watermarks as w (detector, lease_holder, lease_until, updated_at)
  values (p_detector, p_holder, now() + make_interval(secs => greatest(p_seconds, 1)), now())
  on conflict (detector) do update
    set lease_holder = excluded.lease_holder, lease_until = excluded.lease_until, updated_at = now()
    where w.lease_until is null or w.lease_until < now() or w.lease_holder = excluded.lease_holder
  returning true into v_ok;
  return coalesce(v_ok, false);
end;
$$;

ALTER FUNCTION public.system_audit_acquire_lease(p_detector text, p_holder text, p_seconds integer) OWNER TO postgres;

--
-- Name: system_audit_alert_candidates(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.system_audit_alert_candidates() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    SET work_mem TO '64MB'
    AS $$
  with live as (
    select
      o.issue_id,
      (count(distinct o.hr_key) filter (where o.hr_key is not null))::integer as people,
      count(distinct coalesce(o.correlation_id, o.id))::integer as operations,
      max(o.occurred_at) as last_occurred_at
    from public.system_audit_occurrences o
    where not o.is_test and o.triage_override is null
    group by o.issue_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'issueId', i.id,
      'title', i.title,
      'family', i.family,
      'status', i.status,
      'people', l.people,
      'operations', l.operations,
      'lastOccurredAt', l.last_occurred_at,
      'reason', case
        when i.alerted_at is null then 'new'
        when i.status = 'not_fixed' and i.alerted_status is distinct from 'not_fixed' then 'reopened'
        else 'newly_shared'
      end
    ) order by l.people desc, l.last_occurred_at desc), '[]'::jsonb)
  from public.system_audit_issues i
  join live l on l.issue_id = i.id
  where i.status not in ('no_defect')
    and (
      i.alerted_at is null
      or (l.people >= 2 and i.alerted_people < 2)
      or (i.status = 'not_fixed' and i.alerted_status is distinct from 'not_fixed')
    );
$$;

ALTER FUNCTION public.system_audit_alert_candidates() OWNER TO postgres;

--
-- Name: system_audit_mark_alerted(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.system_audit_mark_alerted(p_issue_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_count integer;
begin
  with people as (
    select o.issue_id, (count(distinct o.hr_key) filter (where o.hr_key is not null))::integer as people
    from public.system_audit_occurrences o
    where o.issue_id = any (p_issue_ids) and not o.is_test
    group by o.issue_id
  )
  update public.system_audit_issues i
     set alerted_at = now(),
         alerted_people = coalesce(p.people, 0),
         alerted_status = i.status
    from (select unnest(p_issue_ids) as id) ids
    left join people p on p.issue_id = ids.id
   where i.id = ids.id;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

ALTER FUNCTION public.system_audit_mark_alerted(p_issue_ids uuid[]) OWNER TO postgres;

--
-- Name: system_audit_page(jsonb, text, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.system_audit_page(p_filters jsonb DEFAULT '{}'::jsonb, p_sort text DEFAULT 'occurred_desc'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_after jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    SET work_mem TO '64MB'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
declare
  v_filters jsonb := coalesce(p_filters, '{}'::jsonb);
  v_from date := nullif(v_filters ->> 'from', '')::date;
  v_to date := nullif(v_filters ->> 'to', '')::date;
  v_from_ts timestamptz;
  v_to_ts timestamptz;
  v_hr_keys text[];
  v_modules text[];
  v_statuses text[];
  v_levels text[];
  v_families text[];
  v_scope text := nullif(v_filters ->> 'scope', '');
  v_search text := nullif(btrim(coalesce(v_filters ->> 'search', '')), '');
  v_include_silent boolean := coalesce((v_filters ->> 'includeSilent')::boolean, true);
  v_include_test boolean := coalesce((v_filters ->> 'includeTest')::boolean, false);
  v_keyset boolean := p_after is not null;
  v_after_at timestamptz := nullif(p_after ->> 'occurredAt', '')::timestamptz;
  v_after_id uuid := nullif(p_after ->> 'id', '')::uuid;
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), case when p_after is not null then 5000 else 200 end));
  v_offset integer := case when p_after is not null then 0 else greatest(0, least(coalesce(p_offset, 0), 10000)) end;
  v_sort text := coalesce(nullif(p_sort, ''), 'occurred_desc');
  -- The export stops at the batch size while it scans, unless the only/shared filter needs the
  -- whole period's people counts first.
  v_stream_limit integer;
  v_result jsonb;
begin
  if v_sort not in ('occurred_desc', 'occurred_asc', 'employee', 'module', 'person_ops', 'people') then
    raise exception 'unknown sort %', v_sort using errcode = '22023';
  end if;
  if v_scope is not null and v_scope not in ('only', 'shared', 'system') then
    raise exception 'unknown scope %', v_scope using errcode = '22023';
  end if;
  if v_keyset then
    v_sort := 'occurred_desc';
  end if;
  v_stream_limit := case when v_keyset and v_scope is null then v_limit end;

  -- Cairo calendar days, turned into UTC bounds once (never a bare current_date).
  v_from_ts := case when v_from is null then null else (v_from::timestamp at time zone 'Africa/Cairo') end;
  v_to_ts := case when v_to is null then null else ((v_to + 1)::timestamp at time zone 'Africa/Cairo') end;

  select array_agg(x) into v_hr_keys from jsonb_array_elements_text(coalesce(v_filters -> 'hrKeys', '[]'::jsonb)) x;
  select array_agg(x) into v_modules from jsonb_array_elements_text(coalesce(v_filters -> 'modules', '[]'::jsonb)) x;
  select array_agg(x) into v_statuses from jsonb_array_elements_text(coalesce(v_filters -> 'statuses', '[]'::jsonb)) x;
  select array_agg(x) into v_levels from jsonb_array_elements_text(coalesce(v_filters -> 'rootCauseLevels', '[]'::jsonb)) x;
  select array_agg(x) into v_families from jsonb_array_elements_text(coalesce(v_filters -> 'families', '[]'::jsonb)) x;
  if v_search is not null then
    v_search := '%' || replace(replace(replace(v_search, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;

  with iss as materialized (
    select
      i.id, i.title, i.root_cause_level, i.root_cause, i.status,
      exists (
        select 1 from public.system_audit_issue_fixes f
        where f.issue_id = i.id and f.invalidated_at is null
      ) as has_fix
    from public.system_audit_issues i
  ),
  filtered as materialized (
    select x.id, x.occurred_at, x.signature_key, x.hr_key, x.sort_text, x.display_status
    from (
      select
        o.id, o.occurred_at, o.signature_key, o.hr_key,
        case v_sort
          when 'employee' then coalesce(o.employee_name, o.hr_id_display, '~')
          when 'module' then o.module_label
        end as sort_text,
        case
          when o.triage_override is not null then o.triage_override
          -- The fix that FOLLOWED this occurrence decides its status: a row that happened before a
          -- verified fix is fixed, a row after every fix shows the issue's live status. Only issues
          -- that have a fix pay for the lookup.
          when i.has_fix then coalesce((
            select case when f.verified_at is not null then 'fixed_verified' else 'fix_implemented' end
            from public.system_audit_issue_fixes f
            where f.issue_id = o.issue_id
              and f.invalidated_at is null
              and f.fix_live_at > o.occurred_at
            order by f.fix_live_at asc
            limit 1
          ), i.status)
          else i.status
        end as display_status
      from public.system_audit_occurrences o
      join iss i on i.id = o.issue_id
      where (v_from_ts is null or o.occurred_at >= v_from_ts)
        and (v_to_ts is null or o.occurred_at < v_to_ts)
        and (v_include_test or not o.is_test)
        and (v_after_at is null or (o.occurred_at, o.id) < (v_after_at, v_after_id))
        and (v_hr_keys is null or o.hr_key = any (v_hr_keys))
        and (v_modules is null or o.module_label = any (v_modules))
        and (v_levels is null or i.root_cause_level = any (v_levels))
        and (v_families is null or o.family = any (v_families))
        and (v_include_silent or not o.is_silent)
        and (
          v_search is null
          or i.title ilike v_search
          or o.technical_message ilike v_search
          or o.user_message ilike v_search
          or o.employee_name ilike v_search
          or o.hr_id_display ilike v_search
          or o.error_code ilike v_search
          or o.module_label ilike v_search
        )
    ) x
    where v_statuses is null or x.display_status = any (v_statuses)
    order by case when v_stream_limit is not null then x.occurred_at end desc,
             case when v_stream_limit is not null then x.id end desc
    limit v_stream_limit
  ),
  ops as (
    -- One row per signature x person x operation. coalesce(hr_key, '') keeps every join hashable;
    -- '' is never a real HR id key.
    select o.signature_key, coalesce(o.hr_key, '') as hr_k, o.correlation_id, count(*) as n
    from public.system_audit_occurrences o
    where (v_from_ts is null or o.occurred_at >= v_from_ts)
      and (v_to_ts is null or o.occurred_at < v_to_ts)
      and (v_include_test or not o.is_test)
      and o.signature_key in (select f.signature_key from filtered f)
    group by o.signature_key, coalesce(o.hr_key, ''), o.correlation_id
  ),
  per_person as (
    -- Column 10: operations per person for this signature, over the PERIOD. A correlation id
    -- (one lost visit seen in several modules) counts once.
    select op.signature_key, op.hr_k,
      sum(case when op.correlation_id is null then op.n else 1 end)::integer as person_ops
    from ops op
    group by op.signature_key, op.hr_k
  ),
  per_sig as (
    -- Column 11: distinct people for this signature, over the PERIOD. Rows with no person are
    -- system rows and are never counted as an employee.
    select pp.signature_key, (count(*) filter (where pp.hr_k <> ''))::integer as people
    from per_person pp
    group by pp.signature_key
  ),
  scoped as materialized (
    select f.id, f.occurred_at, f.sort_text, f.display_status, pp.person_ops, ps.people
    from filtered f
    join per_person pp on pp.signature_key = f.signature_key and pp.hr_k = coalesce(f.hr_key, '')
    join per_sig ps on ps.signature_key = f.signature_key
    where v_scope is null
      or (v_scope = 'only' and f.hr_key is not null and ps.people = 1)
      or (v_scope = 'shared' and f.hr_key is not null and ps.people >= 2)
      or (v_scope = 'system' and f.hr_key is null)
  ),
  picked as (
    select q.*, row_number() over (
      order by q.k_asc_ts asc, q.k_text asc, q.k_desc_int desc, q.occurred_at desc, q.id desc
    ) as ord
    from (
      select
        s.*,
        case when v_sort = 'occurred_asc' then s.occurred_at end as k_asc_ts,
        case when v_sort in ('employee', 'module') then s.sort_text end as k_text,
        case v_sort when 'person_ops' then s.person_ops when 'people' then s.people end as k_desc_int
      from scoped s
      order by k_asc_ts asc, k_text asc, k_desc_int desc, s.occurred_at desc, s.id desc
      limit v_limit offset v_offset
    ) q
  ),
  shaped as (
    select
      p.ord,
      p.occurred_at,
      p.id,
      jsonb_build_object(
        'id', o.id,
        'issueId', o.issue_id,
        'signatureKey', o.signature_key,
        'family', o.family,
        'hrKey', o.hr_key,
        'hrId', o.hr_id_display,
        'employeeName', o.employee_name,
        'roleAtEvent', o.role_at_event,
        'moduleLabel', o.module_label,
        'moduleLabelSource', o.module_label_source,
        'shell', o.shell,
        'route', o.route,
        'occurredAt', o.occurred_at,
        'occurredAtKind', o.occurred_at_kind,
        'affectedDate', o.affected_date,
        'userMessage', o.user_message,
        'isSilent', o.is_silent,
        'technicalMessage', o.technical_message,
        'errorCode', o.error_code,
        'title', i.title,
        'rootCauseLevel', i.root_cause_level,
        'rootCause', i.root_cause,
        'status', p.display_status,
        'issueStatus', i.status,
        'personOps', p.person_ops,
        'people', p.people,
        'attemptCount', o.attempt_count,
        'pageLoads', o.page_loads,
        'firstEventAt', o.first_event_at,
        'lastEventAt', o.last_event_at,
        'correlationId', o.correlation_id,
        'isRootSymptom', o.is_root_symptom,
        'relatedTable', o.related_table,
        'relatedId', o.related_id,
        'release', o.release,
        'preFixBuild', o.pre_fix_build,
        'triageOverride', o.triage_override,
        'triageReason', o.triage_reason,
        'isTest', o.is_test
      ) as row_json
    from picked p
    join public.system_audit_occurrences o on o.id = p.id
    join iss i on i.id = o.issue_id
  )
  select jsonb_build_object(
    -- The export is not counted: it walks to the end and the caller counts what it wrote.
    'total', case when v_keyset then null else (select count(*)::integer from scoped) end,
    'limit', v_limit,
    'offset', v_offset,
    'rows', coalesce((select jsonb_agg(sh.row_json order by sh.ord) from shaped sh), '[]'::jsonb),
    'next', (
      select case when v_keyset and count(*) = v_limit then
        jsonb_build_object('occurredAt', (array_agg(s3.occurred_at order by s3.ord desc))[1],
                           'id', (array_agg(s3.id order by s3.ord desc))[1])
      end
      from shaped s3
    )
  )
  into v_result;

  return v_result;
end;
$$;

ALTER FUNCTION public.system_audit_page(p_filters jsonb, p_sort text, p_limit integer, p_offset integer, p_after jsonb) OWNER TO postgres;

