--
-- Name: system_audit_transition_status(uuid, text, text, text, text, timestamp with time zone, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.system_audit_transition_status(p_issue_id uuid, p_to text, p_actor text, p_reason text DEFAULT NULL::text, p_fix_sha text DEFAULT NULL::text, p_fix_live_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_evidence jsonb DEFAULT '{}'::jsonb, p_occurrence_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_issue public.system_audit_issues%rowtype;
  v_is_verifier boolean := p_actor = 'system:verifier';
  v_is_seed boolean := p_actor like 'seed:%';
  v_live_at timestamptz;
  v_generation integer;
  v_fix_id uuid;
begin
  if p_to not in ('fixed_verified', 'not_fixed', 'investigating', 'fix_implemented', 'no_defect', 'unknown') then
    raise exception 'unknown status %', p_to using errcode = '22023';
  end if;
  if coalesce(btrim(p_actor), '') = '' then
    raise exception 'a status change needs an actor' using errcode = '22023';
  end if;

  select * into v_issue from public.system_audit_issues where id = p_issue_id for update;
  if not found then
    raise exception 'issue % not found', p_issue_id using errcode = 'P0002';
  end if;

  -- Nobody asserts a fix by hand: FIXED — VERIFIED comes from the verifier's re-measurement, or
  -- from the reviewed historical seed carrying that re-measurement as evidence.
  if p_to = 'fixed_verified' and not (v_is_verifier or (v_is_seed and coalesce(p_evidence, '{}'::jsonb) <> '{}'::jsonb)) then
    raise exception 'FIXED — VERIFIED is set only by the verifier, with evidence' using errcode = '42501';
  end if;
  if p_to in ('no_defect', 'unknown') and coalesce(btrim(p_reason), '') = '' then
    raise exception 'a reason is required for %', p_to using errcode = '22023';
  end if;

  if p_to = 'fix_implemented' or (p_to = 'fixed_verified' and p_fix_sha is not null) then
    if p_fix_sha is null or p_fix_sha !~ '^[0-9a-f]{40}$' then
      raise exception 'a fix needs its full 40-character commit' using errcode = '22023';
    end if;
    -- Staging has no release gate (production only), so the table is looked up, never assumed.
    if to_regclass('public.release_gates') is not null then
      execute 'select g.recorded_at from public.release_gates g where g.sha = $1' into v_live_at using p_fix_sha;
    end if;
    if v_live_at is null then
      -- release_gates starts on 2026-10-19; an older fix's live time comes only from the reviewed
      -- seed, which carries the merge time as evidence.
      if (v_is_seed or v_is_verifier) and p_fix_live_at is not null then
        v_live_at := p_fix_live_at;
      else
        raise exception 'commit % is not a released build', p_fix_sha using errcode = '22023';
      end if;
    end if;
    select coalesce(max(f.generation), 0) + 1 into v_generation
    from public.system_audit_issue_fixes f where f.issue_id = p_issue_id;
    insert into public.system_audit_issue_fixes (issue_id, generation, fix_commit_sha, fix_live_at, created_by)
    values (p_issue_id, v_generation, p_fix_sha, v_live_at, p_actor)
    returning id into v_fix_id;
  end if;

  if p_to = 'fixed_verified' then
    update public.system_audit_issue_fixes f
       set verified_at = now(), verification = coalesce(p_evidence, '{}'::jsonb)
     where f.id = coalesce(v_fix_id, (
       select f2.id from public.system_audit_issue_fixes f2
        where f2.issue_id = p_issue_id and f2.invalidated_at is null
        order by f2.generation desc limit 1));
    if not found then
      raise exception 'FIXED — VERIFIED needs a fix to verify' using errcode = '22023';
    end if;
  end if;

  if p_to = 'not_fixed' and v_is_verifier and p_occurrence_id is not null then
    -- A recurrence after the fix went live reopens it.
    update public.system_audit_issue_fixes f
       set invalidated_at = now(), invalidated_by_occurrence = p_occurrence_id
     where f.issue_id = p_issue_id and f.invalidated_at is null;
  end if;

  update public.system_audit_issues
     set status = p_to, updated_at = now()
   where id = p_issue_id;

  insert into public.system_audit_status_history (issue_id, occurrence_id, from_status, to_status, actor, reason, evidence)
  values (p_issue_id, p_occurrence_id, v_issue.status, p_to, p_actor, p_reason, coalesce(p_evidence, '{}'::jsonb));

  return jsonb_build_object('issueId', p_issue_id, 'from', v_issue.status, 'to', p_to, 'fixId', v_fix_id);
end;
$_$;

ALTER FUNCTION public.system_audit_transition_status(p_issue_id uuid, p_to text, p_actor text, p_reason text, p_fix_sha text, p_fix_live_at timestamp with time zone, p_evidence jsonb, p_occurrence_id uuid) OWNER TO postgres;

--
-- Name: system_audit_triage_occurrence(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.system_audit_triage_occurrence(p_occurrence_id uuid, p_override text, p_actor text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_occurrence public.system_audit_occurrences%rowtype;
begin
  if p_override is not null and p_override not in ('no_defect', 'unknown') then
    raise exception 'unknown triage %', p_override using errcode = '22023';
  end if;
  if p_override is not null and coalesce(btrim(p_reason), '') = '' then
    raise exception 'a reason is required' using errcode = '22023';
  end if;
  if coalesce(btrim(p_actor), '') = '' then
    raise exception 'a triage needs an actor' using errcode = '22023';
  end if;

  select * into v_occurrence from public.system_audit_occurrences where id = p_occurrence_id for update;
  if not found then
    raise exception 'occurrence % not found', p_occurrence_id using errcode = 'P0002';
  end if;

  update public.system_audit_occurrences
     set triage_override = p_override, triage_reason = case when p_override is null then null else p_reason end, updated_at = now()
   where id = p_occurrence_id;

  insert into public.system_audit_status_history (issue_id, occurrence_id, from_status, to_status, actor, reason)
  values (v_occurrence.issue_id, p_occurrence_id, coalesce(v_occurrence.triage_override, 'occurrence'),
          coalesce(p_override, 'occurrence'), p_actor, p_reason);

  return jsonb_build_object('occurrenceId', p_occurrence_id, 'triage', p_override);
end;
$$;

ALTER FUNCTION public.system_audit_triage_occurrence(p_occurrence_id uuid, p_override text, p_actor text, p_reason text) OWNER TO postgres;

--
-- Name: system_audit_upsert_occurrences(text, uuid, jsonb, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.system_audit_upsert_occurrences(p_detector text, p_run_id uuid, p_issues jsonb, p_rows jsonb, p_merge text DEFAULT 'max'::text, p_cursor jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_inserted integer := 0;
  v_updated integer := 0;
  v_issues integer := 0;
begin
  if p_merge not in ('add', 'max') then
    raise exception 'unknown merge mode %', p_merge using errcode = '22023';
  end if;

  -- Issues: created on first sight. Status and a triaged root cause are never overwritten here —
  -- they change only through system_audit_transition_status.
  with incoming as (
    select *
    from jsonb_to_recordset(coalesce(p_issues, '[]'::jsonb)) as x(
      signature_key text, family text, error_code text, title text,
      root_cause_level text, root_cause text, root_cause_evidence jsonb,
      status text, first_seen_at timestamptz, last_seen_at timestamptz)
  ),
  upserted as (
    insert into public.system_audit_issues as i (
      signature_key, family, error_code, title, status, root_cause_level, root_cause,
      root_cause_evidence, first_seen_at, last_seen_at)
    select
      x.signature_key, x.family, x.error_code, x.title,
      coalesce(nullif(x.status, ''), 'investigating'),
      coalesce(nullif(x.root_cause_level, ''), 'unknown'),
      x.root_cause,
      coalesce(x.root_cause_evidence, '{}'::jsonb),
      x.first_seen_at, x.last_seen_at
    from incoming x
    on conflict (signature_key) do update set
      first_seen_at = least(i.first_seen_at, excluded.first_seen_at),
      last_seen_at = greatest(i.last_seen_at, excluded.last_seen_at),
      root_cause_level = case when i.root_cause_level = 'unknown' then excluded.root_cause_level else i.root_cause_level end,
      root_cause = case when i.root_cause_level = 'unknown' and excluded.root_cause is not null then excluded.root_cause else i.root_cause end,
      root_cause_evidence = case when i.root_cause_level = 'unknown' and excluded.root_cause_evidence <> '{}'::jsonb then excluded.root_cause_evidence else i.root_cause_evidence end,
      updated_at = now()
    returning 1
  )
  select count(*) into v_issues from upserted;

  with incoming as (
    select *
    from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) as r(
      dedupe_key text, signature_key text, correlation_id uuid, is_root_symptom boolean,
      hr_key text, hr_id_display text, employee_name text, role_at_event text,
      module_label text, module_label_source text, shell text, route text,
      occurred_at timestamptz, occurred_at_kind text, affected_date date,
      user_message text, is_silent boolean, technical_message text, error_code text,
      related_table text, related_id text, attempt_count integer, page_loads integer,
      first_event_at timestamptz, last_event_at timestamptz, source_refs jsonb,
      release text, pre_fix_build boolean, evidence jsonb, is_test boolean)
  ),
  resolved as (
    select r.*, i.id as issue_id, i.family
    from incoming r
    join public.system_audit_issues i on i.signature_key = r.signature_key
  ),
  written as (
    insert into public.system_audit_occurrences as o (
      dedupe_key, issue_id, signature_key, family, correlation_id, is_root_symptom,
      hr_key, hr_id_display, employee_name, role_at_event, module_label, module_label_source,
      shell, route, occurred_at, occurred_at_kind, affected_date, user_message, is_silent,
      technical_message, error_code, related_table, related_id, attempt_count, page_loads,
      first_event_at, last_event_at, source_refs, release, pre_fix_build, evidence, is_test,
      detector_run_id)
    select
      r.dedupe_key, r.issue_id, r.signature_key, r.family, r.correlation_id, coalesce(r.is_root_symptom, true),
      r.hr_key, r.hr_id_display, r.employee_name, r.role_at_event, r.module_label, r.module_label_source,
      r.shell, r.route, r.occurred_at, r.occurred_at_kind, r.affected_date, r.user_message, coalesce(r.is_silent, false),
      left(r.technical_message, 1000), r.error_code, r.related_table, r.related_id,
      greatest(coalesce(r.attempt_count, 1), 1), greatest(coalesce(r.page_loads, 1), 1),
      coalesce(r.first_event_at, r.occurred_at), coalesce(r.last_event_at, r.occurred_at),
      coalesce(r.source_refs, '[]'::jsonb), r.release, coalesce(r.pre_fix_build, false),
      coalesce(r.evidence, '{}'::jsonb), coalesce(r.is_test, false), p_run_id
    from resolved r
    on conflict (dedupe_key) do update set
      attempt_count = case when p_merge = 'add' then o.attempt_count + excluded.attempt_count
                           else greatest(o.attempt_count, excluded.attempt_count) end,
      -- An extension of an open operation may bring NO new page load (a retry inside the same load):
      -- the column is clamped to 1 for the insert, so the true delta travels in
      -- evidence.newPageLoads and is what gets added.
      page_loads = case when p_merge = 'add' then o.page_loads + case
                          when (excluded.evidence ->> 'newPageLoads') ~ '^[0-9]{1,6}$'
                            then (excluded.evidence ->> 'newPageLoads')::integer
                          else excluded.page_loads end
                        else greatest(o.page_loads, excluded.page_loads) end,
      first_event_at = least(o.first_event_at, excluded.first_event_at),
      last_event_at = greatest(o.last_event_at, excluded.last_event_at),
      source_refs = case when p_merge = 'add' then
          coalesce((select jsonb_agg(e) from (
            select e from jsonb_array_elements(o.source_refs || excluded.source_refs) e limit 50) capped), '[]'::jsonb)
        else case when jsonb_array_length(excluded.source_refs) > 0 then excluded.source_refs else o.source_refs end end,
      technical_message = coalesce(excluded.technical_message, o.technical_message),
      evidence = case when excluded.evidence <> '{}'::jsonb then excluded.evidence else o.evidence end,
      release = coalesce(excluded.release, o.release),
      -- A detector that re-judges a day (the visit lifecycle) may mint a new correlation id when the
      -- day's lost visits change; the root row follows it, so its linked rows stay one operation.
      correlation_id = coalesce(excluded.correlation_id, o.correlation_id),
      detector_run_id = excluded.detector_run_id,
      updated_at = now()
    returning (xmax = 0) as was_inserted
  )
  select count(*) filter (where was_inserted), count(*) filter (where not was_inserted)
    into v_inserted, v_updated
  from written;

  if p_cursor is not null then
    insert into public.system_audit_watermarks as w (detector, cursor, updated_at)
    values (p_detector, p_cursor, now())
    on conflict (detector) do update set cursor = excluded.cursor, updated_at = now();
  end if;

  return jsonb_build_object('issues', v_issues, 'inserted', v_inserted, 'updated', v_updated);
end;
$_$;

ALTER FUNCTION public.system_audit_upsert_occurrences(p_detector text, p_run_id uuid, p_issues jsonb, p_rows jsonb, p_merge text, p_cursor jsonb) OWNER TO postgres;

--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

ALTER FUNCTION public.touch_updated_at() OWNER TO postgres;

--
-- Name: v2_freeze_request_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.v2_freeze_request_code() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.request_code is not null and new.request_code is distinct from old.request_code then
    raise exception
      'request_code is immutable: % cannot become %', old.request_code, new.request_code
      using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

ALTER FUNCTION public.v2_freeze_request_code() OWNER TO postgres;

--
-- Name: weekly_branch_area_is_consistent(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.weekly_branch_area_is_consistent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_region text;
begin
  if new.area_code is null or btrim(new.area_code) = '' then
    new.area_code := null;
    new.area_name := null;
    return new;
  end if;

  select a.region_code, a.area_name
    into v_region, new.area_name
    from public.source_of_sales_areas a
   where upper(btrim(a.area_code)) = upper(btrim(new.area_code))
     and a.active
   limit 1;

  if v_region is null then
    raise exception 'Area code % is not an active Source-of-Sales area', new.area_code
      using errcode = '23514';
  end if;

  if upper(btrim(v_region)) <> upper(btrim(coalesce(new.region_code, ''))) then
    raise exception 'Area % belongs to region %, not the branch''s mapped region %',
      new.area_code, v_region, new.region_code
      using errcode = '23514';
  end if;

  new.area_code := upper(btrim(new.area_code));
  return new;
end;
$$;

ALTER FUNCTION public.weekly_branch_area_is_consistent() OWNER TO postgres;

--
-- Name: whatsapp_inbox_apply_status(text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.whatsapp_inbox_apply_status(p_wamid text, p_status text, p_at timestamp with time zone, p_failure_detail text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_order text[] := array['accepted', 'sent', 'delivered', 'read'];
  v_changed integer;
begin
  if p_status not in ('sent', 'delivered', 'read', 'failed') then
    return false;
  end if;

  update public.whatsapp_inbox_messages m
  set status = p_status,
      status_at = p_at,
      failure_reason = case when p_status = 'failed' then 'failed' else null end,
      failure_detail = case when p_status = 'failed' then p_failure_detail else null end
  where m.wamid = p_wamid
    and m.direction = 'outbound'
    and (
      (p_status = 'failed' and m.status <> 'failed' and m.status <> 'read')
      or array_position(v_order, m.status) < array_position(v_order, p_status)
    );
  get diagnostics v_changed = row_count;
  return v_changed > 0;
end;
$$;

ALTER FUNCTION public.whatsapp_inbox_apply_status(p_wamid text, p_status text, p_at timestamp with time zone, p_failure_detail text) OWNER TO postgres;

--
-- Name: whatsapp_inbox_attach_conversation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.whatsapp_inbox_attach_conversation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_key text;
  v_id uuid;
  v_preview text;
  v_is_live_inbound boolean;
begin
  if new.wamid is not null
     and exists (select 1 from public.whatsapp_inbox_messages m where m.wamid = new.wamid) then
    return null;
  end if;

  v_key := coalesce(nullif(new.contact_wa_id, ''), 'user:' || nullif(new.contact_user_id, ''));
  if v_key is null then
    raise exception 'whatsapp_inbox_messages row has no contact';
  end if;

  v_preview := left(coalesce(
    nullif(new.body, ''),
    case new.message_type
      when 'image' then 'Photo'
      when 'video' then 'Video'
      when 'audio' then 'Voice note'
      when 'document' then coalesce(new.media_file_name, 'File')
      when 'sticker' then 'Sticker'
      when 'location' then 'Location'
      when 'contacts' then 'Contact card'
      when 'template' then 'Template message'
      else 'Message'
    end
  ), 240);
  v_is_live_inbound := new.direction = 'inbound' and not new.historical;

  insert into public.whatsapp_inbox_conversations as c (
    phone_number_id, contact_key, contact_wa_id, contact_user_id, contact_name, contact_username,
    last_message_at, last_inbound_at, last_message_preview, last_direction, unread_count
  )
  values (
    new.phone_number_id, v_key, new.contact_wa_id, new.contact_user_id, new.contact_name, new.contact_username,
    new.sent_at,
    case when v_is_live_inbound then new.sent_at end,
    v_preview,
    new.direction,
    case when v_is_live_inbound then 1 else 0 end
  )
  on conflict (phone_number_id, contact_key) do update
  set contact_wa_id = coalesce(excluded.contact_wa_id, c.contact_wa_id),
      contact_user_id = coalesce(excluded.contact_user_id, c.contact_user_id),
      contact_name = coalesce(excluded.contact_name, c.contact_name),
      contact_username = coalesce(excluded.contact_username, c.contact_username),
      last_message_preview = case
        when c.last_message_at is null or excluded.last_message_at >= c.last_message_at then excluded.last_message_preview
        else c.last_message_preview end,
      last_direction = case
        when c.last_message_at is null or excluded.last_message_at >= c.last_message_at then excluded.last_direction
        else c.last_direction end,
      last_message_at = greatest(c.last_message_at, excluded.last_message_at),
      last_inbound_at = greatest(c.last_inbound_at, excluded.last_inbound_at),
      unread_count = c.unread_count + excluded.unread_count,
      updated_at = now()
  returning c.id into v_id;

  new.conversation_id := v_id;
  return new;
end;
$$;

ALTER FUNCTION public.whatsapp_inbox_attach_conversation() OWNER TO postgres;

--
-- Name: whatsapp_inbox_link_chats_by_phone(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.whatsapp_inbox_link_chats_by_phone(p_limit integer DEFAULT 500) RETURNS TABLE(conversation_id uuid, candidate_id uuid)
    LANGUAGE sql
    SET search_path TO 'public'
    SET statement_timeout TO '30s'
    AS $$
  with only_holder as (
    select a.phone_norm, (array_agg(a.id))[1] as candidate_id
    from public.ats_candidates a
    where a.phone_norm is not null
    group by a.phone_norm
    having count(*) = 1
  ),
  eligible as (
    select c.id, h.candidate_id
    from public.whatsapp_inbox_conversations c
    join only_holder h on h.phone_norm = c.contact_wa_id
    where c.candidate_id is null
      and c.employee_hr_id is null
      and (c.linked_by_hr_id is null or c.linked_by_hr_id = 'phone-match')
      and not exists (
        select 1 from public.employees e
        where right(regexp_replace(coalesce(e.mobile_number::text, ''), '\D', '', 'g'), 10) = right(c.contact_wa_id, 10)
      )
      and not exists (
        select 1 from public.ats_cv_intake_events i
        where i.sender_identifier = '+' || c.contact_wa_id
          and i.candidate_id is not null
          and i.candidate_id <> h.candidate_id
      )
    order by c.last_message_at desc nulls last
    limit greatest(1, least(coalesce(p_limit, 500), 1000))
  )
  update public.whatsapp_inbox_conversations c
  set candidate_id = e.candidate_id,
      linked_at = now(),
      linked_by_hr_id = 'phone-match',
      updated_at = now()
  from eligible e
  where c.id = e.id
  returning c.id, c.candidate_id;
$$;

ALTER FUNCTION public.whatsapp_inbox_link_chats_by_phone(p_limit integer) OWNER TO postgres;

--
-- Name: FUNCTION whatsapp_inbox_link_chats_by_phone(p_limit integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.whatsapp_inbox_link_chats_by_phone(p_limit integer) IS 'Links a WhatsApp Inbox chat to the one candidate its number can only mean. Never touches a chat a person linked or unlinked. Called by the inbound-intake cron.';

--
-- Name: whatsapp_inbox_waiting_chats(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.whatsapp_inbox_waiting_chats(p_since timestamp with time zone) RETURNS TABLE(conversation_id uuid, waiting_since timestamp with time zone, phone_number_id text, candidate_id uuid, contact_wa_id text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    SET statement_timeout TO '10s'
    AS $$
  select c.id, w.first_at, c.phone_number_id, c.candidate_id, c.contact_wa_id
  from public.whatsapp_inbox_conversations c
  cross join lateral (
    select min(m.sent_at) as first_at, max(m.sent_at) as newest_at
    from public.whatsapp_inbox_messages m
    where m.conversation_id = c.id
      and m.direction = 'inbound'
      and not m.historical
      and m.message_type not in ('reaction', 'revoke', 'system')
      and m.sent_at > coalesce(
        (
          select max(o.sent_at)
          from public.whatsapp_inbox_messages o
          where o.conversation_id = c.id
            and o.direction = 'outbound'
            and o.status <> 'failed'
        ),
        '-infinity'::timestamptz
      )
  ) w
  where c.last_inbound_at >= p_since
    and w.newest_at >= p_since;
$$;

ALTER FUNCTION public.whatsapp_inbox_waiting_chats(p_since timestamp with time zone) OWNER TO postgres;

--
-- Name: FUNCTION whatsapp_inbox_waiting_chats(p_since timestamp with time zone); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.whatsapp_inbox_waiting_chats(p_since timestamp with time zone) IS 'The WhatsApp Inbox chats waiting for a reply since p_since: a real message from the contact with no successful reply after it. waiting_since is the oldest such message.';

--
-- Name: canonical_payload(text, text, text[]); Type: FUNCTION; Schema: recovery; Owner: postgres
--

CREATE FUNCTION recovery.canonical_payload(p_schema text, p_table text, p_pk text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_payload jsonb;
  v_order   text;
  v_sql     text;
begin
  select string_agg(format('t.%I', c.col), ', ') into v_order from unnest(p_pk) as c(col);
  v_sql := format(
    'select coalesce(jsonb_agg(to_jsonb(t) order by %s), ''[]''::jsonb) from %I.%I t',
    v_order, p_schema, p_table);
  execute v_sql into v_payload;
  return v_payload;
end;
$$;

ALTER FUNCTION recovery.canonical_payload(p_schema text, p_table text, p_pk text[]) OWNER TO postgres;

--
-- Name: fingerprint_table(text, text, text[], boolean); Type: FUNCTION; Schema: recovery; Owner: postgres
--

CREATE FUNCTION recovery.fingerprint_table(p_schema text, p_table text, p_pk text[], p_with_payload boolean DEFAULT false) RETURNS TABLE(fp_rows integer, fp_bytes bigint, fp_hash text, fp_payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_inner text;
  v_order text;
begin
  select string_agg(format('t.%I', c.col), ', ' order by c.ord),
         string_agg(format('r.%I', c.col), ', ' order by c.ord)
    into v_inner, v_order
  from unnest(p_pk) with ordinality as c(col, ord);

  return query execute format(
    'select count(*)::integer,
            (case when count(*) = 0 then 2
                  else 2 + sum(octet_length(r.recovery_row_text)) + 2 * (count(*) - 1) end)::bigint,
            ''r2:'' || md5(coalesce(string_agg(md5(r.recovery_row_text), '''' order by %1$s), '''')),
            %2$s
     from (select a.*, a.recovery_row_json::text as recovery_row_text
           from (select %3$s, to_jsonb(t) as recovery_row_json from %4$I.%5$I t offset 0) a
           offset 0) r',
    v_order,
    case when p_with_payload
      then format('coalesce(jsonb_agg(r.recovery_row_json order by %s), ''[]''::jsonb)', v_order)
      else 'null::jsonb'
    end,
    v_inner,
    p_schema,
    p_table);
end;
$_$;

ALTER FUNCTION recovery.fingerprint_table(p_schema text, p_table text, p_pk text[], p_with_payload boolean) OWNER TO postgres;

--
-- Name: payload_fingerprint(jsonb); Type: FUNCTION; Schema: recovery; Owner: postgres
--

CREATE FUNCTION recovery.payload_fingerprint(p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select 'r2:' || md5(coalesce(string_agg(md5(x.element_text), '' order by e.ord), ''))
  from jsonb_array_elements(p_payload) with ordinality as e(value, ord)
  cross join lateral (select e.value::text as element_text offset 0) x
$$;

ALTER FUNCTION recovery.payload_fingerprint(p_payload jsonb) OWNER TO postgres;

--
-- Name: purge_snapshots(); Type: FUNCTION; Schema: recovery; Owner: postgres
--

CREATE FUNCTION recovery.purge_snapshots() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_purged integer := 0;
  v_hit    integer;
begin
  -- Rules 1 and 2: keep each table's newest max_versions, plus any daily marker inside 30 days.
  -- Rule 3, the important one: a table's NEWEST row is never deleted, at any age. A table that
  -- has not changed in a year must still be restorable, so a purely time-based purge would drop
  -- the only copy of au.line_area_map, which changes about monthly.
  with ranked as (
    select s.id,
           s.keep_daily,
           s.taken_at,
           row_number() over (
             partition by s.source_schema, s.source_table order by s.taken_at desc, s.id desc) as rn,
           coalesce(pt.max_versions, 72) as cap
    from recovery.table_snapshots s
    left join recovery.protected_tables pt
      on pt.source_schema = s.source_schema and pt.source_table = s.source_table
  )
  delete from recovery.table_snapshots d
  using ranked r
  where d.id = r.id
    and r.rn > greatest(r.cap, 1)
    and not (r.keep_daily and r.taken_at >= now() - interval '30 days');
  get diagnostics v_hit = row_count;
  v_purged := v_purged + v_hit;

  -- Rule 4: a global byte ceiling, so a mis-registered table cannot grow the database without
  -- bound. Oldest first, and still never a table's newest row.
  while pg_total_relation_size('recovery.table_snapshots') > 512 * 1024 * 1024 loop
    with ranked as (
      select s.id,
             s.taken_at,
             row_number() over (
               partition by s.source_schema, s.source_table order by s.taken_at desc, s.id desc) as rn
      from recovery.table_snapshots s
    ),
    victims as (
      select r.id from ranked r where r.rn > 1 order by r.taken_at asc, r.id asc limit 10
    )
    delete from recovery.table_snapshots d using victims v where d.id = v.id;
    get diagnostics v_hit = row_count;
    exit when v_hit = 0;
    v_purged := v_purged + v_hit;
  end loop;

  -- Rule 5: the run log and the restore pre-images keep 90 days.
  delete from recovery.snapshot_runs sr where sr.started_at < now() - interval '90 days';
  get diagnostics v_hit = row_count;
  v_purged := v_purged + v_hit;

  delete from recovery.restore_preimages rp where rp.taken_at < now() - interval '90 days';
  get diagnostics v_hit = row_count;
  v_purged := v_purged + v_hit;

  return v_purged;
end;
$$;

ALTER FUNCTION recovery.purge_snapshots() OWNER TO postgres;

--
-- Name: restore_table(text, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: recovery; Owner: postgres
--

CREATE FUNCTION recovery.restore_table(p_schema text, p_table text, p_as_of timestamp with time zone, p_dry_run boolean DEFAULT true) RETURNS TABLE(snapshot_id bigint, snapshot_taken_at timestamp with time zone, rows_now integer, rows_in_snapshot integer, applied boolean, note text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_snap     record;
  v_pk       text[];
  v_now_rows integer;
  v_sql      text;
  v_pre      jsonb;
begin
  select pt.pk_columns into v_pk
  from recovery.protected_tables pt
  where pt.source_schema = p_schema and pt.source_table = p_table;

  if v_pk is null then
    raise exception 'recovery.restore_table: %.% is not a protected table', p_schema, p_table;
  end if;

  -- "The state at time T" is the newest snapshot AT OR BEFORE T. Because unchanged hours write
  -- nothing, the gaps are correct rather than missing: no snapshot between two points means the
  -- table did not change between them.
  select s.id, s.taken_at, s.row_count, s.payload
  into v_snap
  from recovery.table_snapshots s
  where s.source_schema = p_schema and s.source_table = p_table and s.taken_at <= p_as_of
  order by s.taken_at desc, s.id desc
  limit 1;

  if v_snap.id is null then
    raise exception 'recovery.restore_table: no snapshot of %.% at or before %', p_schema, p_table, p_as_of;
  end if;

  execute format('select count(*)::integer from %I.%I', p_schema, p_table) into v_now_rows;

  if p_dry_run then
    return query select v_snap.id, v_snap.taken_at, v_now_rows, v_snap.row_count, false,
      format('DRY RUN. Would replace %s live row(s) with %s row(s) from %s. '
             'Re-run with p_dry_run => false to apply. A pre-image is taken automatically.',
             v_now_rows, v_snap.row_count, v_snap.taken_at)::text;
    return;
  end if;

  -- Mandatory undo for the undo. There is no PITR behind a restore that was the wrong call.
  v_pre := recovery.canonical_payload(p_schema, p_table, v_pk);
  insert into recovery.restore_preimages (source_schema, source_table, payload, restored_to_snapshot_id)
  values (p_schema, p_table, v_pre, v_snap.id);

  -- DELETE, not TRUNCATE: TRUNCATE ignores deferred foreign keys, and check-migrations.mjs
  -- refuses an unannotated one.
  set constraints all deferred;
  execute format('delete from %I.%I', p_schema, p_table);
  execute format(
    'insert into %I.%I select * from jsonb_populate_recordset(null::%I.%I, $1)',
    p_schema, p_table, p_schema, p_table) using v_snap.payload;

  return query select v_snap.id, v_snap.taken_at, v_now_rows, v_snap.row_count, true,
    format('APPLIED. %s row(s) replaced by %s row(s) from %s. Pre-image kept in '
           'recovery.restore_preimages. Check any identity sequence before inserting again.',
           v_now_rows, v_snap.row_count, v_snap.taken_at)::text;
end;
$_$;

ALTER FUNCTION recovery.restore_table(p_schema text, p_table text, p_as_of timestamp with time zone, p_dry_run boolean) OWNER TO postgres;

--
-- Name: take_snapshots(); Type: FUNCTION; Schema: recovery; Owner: postgres
--

CREATE FUNCTION recovery.take_snapshots() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_row        record;
  v_payload    jsonb;
  v_hash       text;
  v_prev_id    bigint;
  v_prev_hash  text;
  v_rows       integer;
  v_bytes      bigint;
  v_started    timestamptz := clock_timestamp();
  v_checked    integer := 0;
  v_changed    integer := 0;
  v_purged     integer := 0;
  v_error      text := null;
  v_keep_daily boolean;
  v_total      bigint;
begin
  for v_row in
    select pt.source_schema, pt.source_table, pt.pk_columns, pt.max_rows
    from recovery.protected_tables pt
    where pt.enabled
    order by pt.source_schema, pt.source_table
  loop
    begin
      v_checked := v_checked + 1;

      -- Has it changed? Answered one row at a time, with nothing table-sized held in memory.
      select f.fp_rows, f.fp_bytes, f.fp_hash
        into v_rows, v_bytes, v_hash
      from recovery.fingerprint_table(v_row.source_schema, v_row.source_table, v_row.pk_columns) f;

      if v_rows > v_row.max_rows then
        v_error := coalesce(v_error, '') ||
          format('%s.%s skipped: %s rows exceeds max_rows %s. ',
                 v_row.source_schema, v_row.source_table, v_rows, v_row.max_rows);
        continue;
      end if;

      if v_bytes > 64 * 1024 * 1024 then
        v_error := coalesce(v_error, '') ||
          format('%s.%s skipped: payload %s bytes exceeds the 64 MB ceiling. ',
                 v_row.source_schema, v_row.source_table, v_bytes);
        continue;
      end if;

      v_prev_id := null;
      v_prev_hash := null;
      select s.id, s.content_hash
        into v_prev_id, v_prev_hash
      from recovery.table_snapshots s
      where s.source_schema = v_row.source_schema
        and s.source_table = v_row.source_table
      order by s.taken_at desc, s.id desc
      limit 1;

      -- A newest version stored before the 'r2:' scheme: fingerprint it from its own payload, once,
      -- and keep the result on the row, so the scheme change alone never captures a duplicate.
      if v_prev_id is not null and v_prev_hash not like 'r2:%' then
        select recovery.payload_fingerprint(s.payload)
          into v_prev_hash
        from recovery.table_snapshots s
        where s.id = v_prev_id;

        update recovery.table_snapshots s
        set content_hash = v_prev_hash
        where s.id = v_prev_id;
      end if;

      -- The whole point: unchanged tables cost nothing.
      if v_prev_hash is distinct from v_hash then
        -- Count, size and hash are re-read with the payload, from the same statement, so what is
        -- stored beside the copy describes that copy even if the table moved since the check.
        select f.fp_rows, f.fp_bytes, f.fp_hash, f.fp_payload
          into v_rows, v_bytes, v_hash, v_payload
        from recovery.fingerprint_table(v_row.source_schema, v_row.source_table, v_row.pk_columns, true) f;

        if v_rows > v_row.max_rows then
          v_error := coalesce(v_error, '') ||
            format('%s.%s skipped: %s rows exceeds max_rows %s. ',
                   v_row.source_schema, v_row.source_table, v_rows, v_row.max_rows);
          continue;
        end if;

        if v_bytes > 64 * 1024 * 1024 then
          v_error := coalesce(v_error, '') ||
            format('%s.%s skipped: payload %s bytes exceeds the 64 MB ceiling. ',
                   v_row.source_schema, v_row.source_table, v_bytes);
          continue;
        end if;

        v_keep_daily := not exists (
          select 1 from recovery.table_snapshots s
          where s.source_schema = v_row.source_schema
            and s.source_table = v_row.source_table
            and s.taken_at >= date_trunc('day', now())
        );
        insert into recovery.table_snapshots
          (source_schema, source_table, content_hash, row_count, payload, payload_bytes, keep_daily)
        values
          (v_row.source_schema, v_row.source_table, v_hash, v_rows, v_payload, v_bytes, v_keep_daily);
        v_changed := v_changed + 1;
      end if;
    exception when others then
      -- One bad table must not lose the run for the other six.
      v_error := coalesce(v_error, '') ||
        format('%s.%s: %s %s. ', v_row.source_schema, v_row.source_table, sqlstate, sqlerrm);
    end;
  end loop;

  v_purged := recovery.purge_snapshots();
  select coalesce(sum(s.payload_bytes), 0) into v_total from recovery.table_snapshots s;

  insert into recovery.snapshot_runs
    (started_at, duration_ms, tables_checked, tables_changed, rows_purged, total_bytes, error)
  values
    (v_started, (extract(epoch from clock_timestamp() - v_started) * 1000)::integer,
     v_checked, v_changed, v_purged, v_total, v_error);

  return jsonb_build_object(
    'checked', v_checked, 'changed', v_changed, 'purged', v_purged,
    'total_bytes', v_total, 'error', v_error);
end;
$$;

