--
-- Name: closing_fact; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.closing_fact AS
 WITH sos_periods AS (
         SELECT DISTINCT f.period
           FROM (public.source_of_sales_fact_rollup f
             JOIN public.source_of_sales_import_batches b ON (((b.id = f.batch_id) AND (b.status = 'validated'::text))))
        ), uploaded_periods AS (
         SELECT DISTINCT b.period
           FROM public.source_of_sales_import_batches b
          WHERE (lower(btrim(COALESCE(b.distributor_code, ''::text))) <> ALL (ARRAY['direct'::text, 'directreq'::text]))
        ), achievement AS (
         SELECT a_1.period,
            a_1.line_code,
            a_1.region_code,
            a_1.area_code,
            a_1.area_state,
            a_1.is_other,
            a_1.rep_seat_id,
            a_1.rep_hr_id,
            a_1.dm_seat_id,
            a_1.dm_hr_id,
            a_1.product_code,
            a_1.actual_units,
            a_1.actual_value,
            a_1.target_units,
            a_1.target_value,
            a_1.achievement_value,
            a_1.achievement_units,
            a_1.has_target,
            a_1.has_actual
           FROM (sos_periods p
             CROSS JOIN LATERAL au.f_monthly_achievement(p.period) a_1(period, line_code, region_code, area_code, area_state, is_other, rep_seat_id, rep_hr_id, dm_seat_id, dm_hr_id, product_code, actual_units, actual_value, target_units, target_value, achievement_value, achievement_units, has_target, has_actual))
        )
 SELECT ("left"(a.period, 4))::integer AS year,
    ("right"(a.period, 2))::integer AS month,
    "right"(a.period, 2) AS month_str,
    a.period,
    NULL::uuid AS batch_id,
    'source-of-sales-monthly-closing'::text AS batch_file,
    'approved'::text AS batch_status,
    l.line_name AS line,
    upper(btrim(a.rep_hr_id)) AS employee_hr_id,
    e.full_name AS employee_name,
    upper(btrim(a.dm_hr_id)) AS manager_hr_id,
    COALESCE(NULLIF(btrim(ar.area_name), ''::text), a.area_code) AS territory,
    ''::text AS sales_type,
    COALESCE(NULLIF(btrim(pr.product_name), ''::text), a.product_code) AS product,
    COALESCE(pr.family, ''::text) AS family,
    a.actual_units AS sales_units,
    a.actual_value AS sales_value,
        CASE
            WHEN (up.period IS NOT NULL) THEN a.target_units
            ELSE NULL::numeric
        END AS target_units,
        CASE
            WHEN (up.period IS NOT NULL) THEN a.target_value
            ELSE NULL::numeric
        END AS target_value,
    'valid'::text AS validation_state,
        CASE
            WHEN ((a.rep_hr_id IS NOT NULL) AND (btrim(a.rep_hr_id) <> ''::text)) THEN 'linked'::text
            ELSE 'unlinked'::text
        END AS link_status,
        CASE
            WHEN ((up.period IS NOT NULL) AND (a.target_value > (0)::numeric)) THEN round(((a.actual_value / a.target_value) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS achievement_pct,
    a.product_code
   FROM (((((achievement a
     JOIN au.lines l ON ((l.line_code = a.line_code)))
     LEFT JOIN uploaded_periods up ON ((up.period = a.period)))
     LEFT JOIN public.source_of_sales_areas ar ON ((upper(btrim(ar.area_code)) = upper(btrim(a.area_code)))))
     LEFT JOIN public.source_of_sales_products pr ON ((upper(btrim(pr.product_code)) = upper(btrim(a.product_code)))))
     LEFT JOIN public.employees e ON ((upper(btrim(e.hr_id)) = upper(btrim(a.rep_hr_id)))))
  WHERE (upper(btrim(COALESCE(a.product_code, ''::text))) <> ALL (ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text]));

ALTER VIEW analytics.closing_fact OWNER TO postgres;

--
-- Name: VIEW closing_fact; Type: COMMENT; Schema: analytics; Owner: postgres
--

COMMENT ON VIEW analytics.closing_fact IS 'Monthly closing at (period, line, area, product, rep) grain, sourced from SoS Monthly Closing via au.f_monthly_achievement. Targets and achievement_pct appear only for months whose distributor upload has landed. Confidential products excluded.';

--
-- Name: closing_by_employee; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.closing_by_employee AS
 SELECT year,
    month,
    period,
    batch_id,
    line,
    employee_hr_id,
    employee_name,
    manager_hr_id,
    territory,
    sum(sales_value) AS sales_value,
    sum(target_value) AS target_value,
    sum(sales_units) AS sales_units,
    sum(target_units) AS target_units,
        CASE
            WHEN (sum(target_value) > (0)::numeric) THEN round(((sum(sales_value) / sum(target_value)) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS achievement_pct
   FROM analytics.closing_fact
  GROUP BY year, month, period, batch_id, line, employee_hr_id, employee_name, manager_hr_id, territory;

