    net_qty numeric(18,6) DEFAULT 0 NOT NULL,
    cycle_month date,
    week_number smallint,
    area_code text,
    CONSTRAINT weekly_sales_rows_validation_state_check CHECK ((validation_state = ANY (ARRAY['valid'::text, 'warning'::text, 'failed'::text]))),
    CONSTRAINT weekly_sales_rows_week_number_chk CHECK (((week_number IS NULL) OR ((week_number >= 1) AND (week_number <= 4))))
);

ALTER TABLE public.weekly_sales_rows OWNER TO postgres;

--
-- Name: TABLE weekly_sales_rows; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.weekly_sales_rows IS 'Weekly Sales fact rows at branch x product x week grain. Sales value recomputed from factory price; stock is units only.';

--
-- Name: COLUMN weekly_sales_rows.cycle_month; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.weekly_sales_rows.cycle_month IS 'Mirror of the parent batch cycle_month (for fast per-month de-cumulation + Week filtering on rows).';

--
-- Name: COLUMN weekly_sales_rows.week_number; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.weekly_sales_rows.week_number IS 'Mirror of the parent batch week_number (1-4).';

--
-- Name: COLUMN weekly_sales_rows.area_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.weekly_sales_rows.area_code IS 'Area resolved from the branch mapping at import time. NULL when the branch has no area mapping, in which case the row is scoped by region_code exactly as before.';

--
-- Name: weekly_fact; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.weekly_fact AS
 SELECT b.week_start,
    (EXTRACT(year FROM b.week_start))::integer AS year,
    (EXTRACT(month FROM b.week_start))::integer AS month,
    (EXTRACT(week FROM b.week_start))::integer AS iso_week,
    to_char((b.week_start)::timestamp with time zone, 'YYYY-"W"IW'::text) AS week_label,
    "left"(to_char((b.week_start)::timestamp with time zone, 'YYYY-MM'::text), 7) AS period,
    r.distributor_code,
    COALESCE(d.distributor_name, r.distributor_name) AS distributor_name,
    r.region_code,
    COALESCE(ar.region_name, r.region_name) AS region_name,
    r.branch_code,
    r.branch_name,
    r.product_code,
    COALESCE(p.product_name, r.product_name) AS product_name,
    COALESCE(p.family, ''::text) AS family,
    COALESCE(p.family_code, ''::text) AS family_code,
    r.official_line AS line,
    sum(r.sales_qty) AS sales_qty,
    sum(r.bonus_qty) AS bonus_qty,
    sum(r.sales_value) AS sales_value,
    sum(r.stock_qty) AS stock_qty
   FROM ((((public.weekly_sales_rows r
     JOIN public.weekly_sales_batches b ON (((b.id = r.batch_id) AND (b.status = 'validated'::text))))
     LEFT JOIN public.source_of_sales_products p ON ((upper(btrim(p.product_code)) = upper(btrim(r.product_code)))))
     LEFT JOIN public.source_of_sales_distributors d ON ((d.distributor_code = r.distributor_code)))
     LEFT JOIN public.source_of_sales_area_regions ar ON ((ar.region_code = r.region_code)))
  WHERE ((upper(btrim(COALESCE(r.product_code, ''::text))) <> ALL (ARRAY['LA003'::text, 'LA004'::text, 'SS001'::text])) AND (r.validation_state = ANY (ARRAY['valid'::text, 'warning'::text])))
  GROUP BY b.week_start, r.distributor_code, d.distributor_name, r.distributor_name, r.region_code, ar.region_name, r.region_name, r.branch_code, r.branch_name, r.product_code, p.product_name, r.product_name, p.family, p.family_code, r.official_line;

ALTER VIEW analytics.weekly_fact OWNER TO postgres;

--
-- Name: cross_source_period_line; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.cross_source_period_line AS
 WITH sos AS (
         SELECT sos_by_line.period,
            sos_by_line.line,
            sum(sos_by_line.value) AS sos_value,
            sum(sos_by_line.units) AS sos_units
           FROM analytics.sos_by_line
          GROUP BY sos_by_line.period, sos_by_line.line
        ), closing AS (
         SELECT closing_by_line.period,
            closing_by_line.line,
            sum(closing_by_line.sales_value) AS closing_value,
            sum(closing_by_line.sales_units) AS closing_units,
            sum(closing_by_line.target_value) AS target_value,
            sum(closing_by_line.target_units) AS target_units
           FROM analytics.closing_by_line
          GROUP BY closing_by_line.period, closing_by_line.line
        ), weekly AS (
         SELECT weekly_fact.period,
            weekly_fact.line,
            sum(weekly_fact.sales_value) AS weekly_value,
            sum(weekly_fact.sales_qty) AS weekly_units
           FROM analytics.weekly_fact
          GROUP BY weekly_fact.period, weekly_fact.line
        )
 SELECT COALESCE(s.period, c.period, w.period) AS period,
    COALESCE(s.line, c.line, w.line) AS line,
    s.sos_value,
    s.sos_units,
    c.closing_value,
    c.closing_units,
    c.target_value,
    c.target_units,
    w.weekly_value,
    w.weekly_units,
        CASE
            WHEN (c.target_value > (0)::numeric) THEN round(((c.closing_value / c.target_value) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS closing_achievement_pct
   FROM ((sos s
     FULL JOIN closing c USING (period, line))
     FULL JOIN weekly w USING (period, line));

ALTER VIEW analytics.cross_source_period_line OWNER TO postgres;

--
-- Name: VIEW cross_source_period_line; Type: COMMENT; Schema: analytics; Owner: postgres
--

COMMENT ON VIEW analytics.cross_source_period_line IS 'Source of Sales, Monthly Closing and Weekly Sales aligned on (period, line). The three legs measure different things and are not expected to agree: SoS and Closing are the same measurement at this grain (Closing is SoS attributed down to seats), and Weekly is cumulative branch sell-out. No gap percentage is published here because none of them is meaningful before the view is re-cut at area grain.';

