--
-- Name: sos_by_block; Type: VIEW; Schema: analytics; Owner: postgres
--

CREATE VIEW analytics.sos_by_block AS
 SELECT f.period,
    f.year,
    f.month,
    f.region_code,
    f.region_name,
    f.area_code,
    f.area_name,
    b.block_code,
    COALESCE(bl.display_name, mb.brick_name, bl.description) AS group_label,
    bl.master_brick_id,
    f.channel,
    sum(f.units) AS units,
    sum(f.value) AS value
   FROM (((analytics.sos_fact f
     JOIN public.source_of_sales_bricks b ON ((b.brick_id = f.brick_id)))
     JOIN public.source_of_sales_blocks bl ON ((bl.block_code = b.block_code)))
     LEFT JOIN public.source_of_sales_bricks mb ON ((mb.brick_id = bl.master_brick_id)))
  GROUP BY f.period, f.year, f.month, f.region_code, f.region_name, f.area_code, f.area_name, b.block_code, bl.display_name, mb.brick_name, bl.description, bl.master_brick_id, f.channel;

