--
-- Name: v_org_tree; Type: VIEW; Schema: au; Owner: postgres
--

CREATE VIEW au.v_org_tree AS
 WITH RECURSIVE tree AS (
         SELECT s.seat_id,
            s.parent_seat_id,
            s.seat_tier,
            s.line_code,
            s.region_code,
            s.area_code,
            s.is_other_pseudo_dm,
            s.seat_label,
            0 AS depth,
            ARRAY[s.seat_id] AS path
           FROM au.seats s
          WHERE ((s.parent_seat_id IS NULL) AND s.is_active AND ((s.effective_to IS NULL) OR (s.effective_to > ((now() AT TIME ZONE 'Africa/Cairo'::text))::date)))
        UNION ALL
         SELECT c.seat_id,
            c.parent_seat_id,
            c.seat_tier,
            c.line_code,
            c.region_code,
            c.area_code,
            c.is_other_pseudo_dm,
            c.seat_label,
            (t_1.depth + 1),
            (t_1.path || c.seat_id)
           FROM (au.seats c
             JOIN tree t_1 ON ((c.parent_seat_id = t_1.seat_id)))
          WHERE (c.is_active AND ((c.effective_to IS NULL) OR (c.effective_to > ((now() AT TIME ZONE 'Africa/Cairo'::text))::date)))
        )
 SELECT t.seat_id,
    t.parent_seat_id,
    t.seat_tier,
    t.line_code,
    t.region_code,
    t.area_code,
    t.is_other_pseudo_dm,
    t.seat_label,
    t.depth,
    t.path,
    o.occupant_hr_id,
    o.node_type,
    (o.occupant_hr_id IS NULL) AS is_vacant,
    ca.area_name,
    rg.region_name,
    ln.line_name,
    ln.line_id,
        CASE
            WHEN (o.occupant_hr_id IS NULL) THEN (t.seat_label || ' (VACANT)'::text)
            ELSE t.seat_label
        END AS seat_display_label
   FROM ((((tree t
     LEFT JOIN au.occupancy_history o ON (((o.seat_id = t.seat_id) AND (o.effective_from <= ((now() AT TIME ZONE 'Africa/Cairo'::text))::date) AND ((o.effective_to IS NULL) OR (o.effective_to > ((now() AT TIME ZONE 'Africa/Cairo'::text))::date)))))
     LEFT JOIN au.canonical_areas ca ON ((ca.area_code = t.area_code)))
     LEFT JOIN au.regions rg ON ((rg.region_code = t.region_code)))
     LEFT JOIN au.lines ln ON ((ln.line_code = t.line_code)));

ALTER VIEW au.v_org_tree OWNER TO postgres;

--
-- Name: v_org_structure_kpis; Type: VIEW; Schema: au; Owner: postgres
--

CREATE VIEW au.v_org_structure_kpis AS
 SELECT COALESCE(line_code, '(root)'::text) AS line_code,
    seat_tier,
    count(*) AS total,
    count(*) FILTER (WHERE (NOT is_vacant)) AS filled,
    count(*) FILTER (WHERE is_vacant) AS vacant
   FROM au.v_org_tree t
  GROUP BY line_code, seat_tier;

ALTER VIEW au.v_org_structure_kpis OWNER TO postgres;

