ALTER TABLE public.ats_application_events OWNER TO postgres;

--
-- Name: ats_applications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_applications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    application_code text NOT NULL,
    requisition_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    stage text DEFAULT 'application_received'::text NOT NULL,
    source text,
    offer_id uuid,
    converted_employee_hr_id text,
    current_owner_hr_id text,
    decision_reason text,
    rejected_reason text,
    last_stage_changed_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    submitted_ip_hash text,
    senior_approval_status text,
    senior_approved_by text,
    senior_approved_at timestamp with time zone,
    attributed_channel_code text,
    attributed_by_hr_id text,
    attributed_at timestamp with time zone,
    CONSTRAINT recruitment_applications_stage_check CHECK ((stage = ANY (ARRAY['application_received'::text, 'in_candidate_pool'::text, 'cv_screening'::text, 'phone_screening'::text, 'interview_scheduling'::text, 'hr_interview'::text, 'hiring_manager_interview'::text, 'final_selection'::text, 'offer_initiated'::text, 'offer_sent'::text, 'offer_accepted'::text, 'offer_declined'::text, 'offer_expired'::text, 'pre_boarding'::text, 'hired'::text, 'application_rejected'::text, 'application_withdrawn'::text, 'shortlisted'::text, 'on_hold'::text, 'no_response'::text, 'call_back'::text, 'manager_interview_completed'::text, 'backup_candidate'::text, 'offer_draft'::text, 'offer_pending_approval'::text, 'offer_approved'::text, 'offer_generated'::text, 'offer_negotiation'::text])))
);

ALTER TABLE public.ats_applications OWNER TO postgres;

--
-- Name: COLUMN ats_applications.offer_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_applications.offer_id IS 'DEAD -- never populated. Superseded by ats_offers.application_id. Do not wire this up.';

--
-- Name: COLUMN ats_applications.attributed_channel_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_applications.attributed_channel_code IS 'Manually-tagged source advert (a PX- code from ats_job_post_channels). The effective source-of-hire = this ?? the earliest surviving source_channel_code across the candidate''s ats_cv_intake_events. Null when nobody has tagged it and no tracked code survived.';

--
-- Name: ats_candidate_call_actions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_call_actions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    manager_hr_id text NOT NULL,
    manager_name text,
    action text NOT NULL,
    note text,
    acted_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_candidate_call_actions_action_known CHECK ((action = ANY (ARRAY['will_call'::text, 'skipped'::text]))),
    CONSTRAINT ats_candidate_call_actions_hr_id_present CHECK ((length(btrim(manager_hr_id)) > 0)),
    CONSTRAINT ats_candidate_call_actions_hr_id_upper CHECK ((manager_hr_id = upper(manager_hr_id)))
);

ALTER TABLE public.ats_candidate_call_actions OWNER TO postgres;

--
-- Name: TABLE ats_candidate_call_actions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_call_actions IS 'What one manager did about one CV in his portal: will_call (he reserved it — the ONLY way the candidate''s phone number is revealed, and every other manager reading the same CV is told his name) or skipped (he passed — the CV leaves only HIS derived district folder, exactly like ats_candidate_district_returns). One row per (candidate, manager); a partial unique index on candidate_id where action = will_call is what keeps a claim single across everybody. Does not touch ats_candidates.status.';

--
-- Name: COLUMN ats_candidate_call_actions.action; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_call_actions.action IS 'will_call = reserved by this manager, phone revealed to him alone, notice shown to every other reader. skipped = this manager passed; suppresses the CV from his district folders only and releases any claim he held.';

--
-- Name: ats_candidate_call_results; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_call_results (
    id bigint NOT NULL,
    candidate_id uuid NOT NULL,
    result text NOT NULL,
    note text,
    hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_candidate_call_results_note_length CHECK (((note IS NULL) OR (char_length(note) <= 300))),
    CONSTRAINT ats_candidate_call_results_result_check CHECK ((result = ANY (ARRAY['called'::text, 'no_answer'::text, 'interested'::text, 'not_interested'::text, 'call_back'::text])))
);

ALTER TABLE public.ats_candidate_call_results OWNER TO postgres;

--
-- Name: ats_candidate_call_results_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.ats_candidate_call_results ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.ats_candidate_call_results_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: ats_candidate_comments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_comments (
    id bigint NOT NULL,
    candidate_id uuid NOT NULL,
    author_hr_id text,
    author_name text,
    author_job_title text,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_candidate_comments_body_length CHECK ((char_length(body) <= 2000)),
    CONSTRAINT ats_candidate_comments_body_not_blank CHECK ((btrim(body) <> ''::text))
);

ALTER TABLE public.ats_candidate_comments OWNER TO postgres;

--
-- Name: TABLE ats_candidate_comments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_comments IS 'What a manager said about a CV pushed to somebody in their team. UPDATE is refused by trigger; DELETE is allowed and the application restricts it to the author. author_* columns are stamped at write time, never joined at read time, because HR_IDs are reused when a seat is refilled.';

--
-- Name: COLUMN ats_candidate_comments.author_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_comments.author_hr_id IS 'HR_ID of whoever wrote it. NULL means "not recorded", never "system".';

--
-- Name: COLUMN ats_candidate_comments.author_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_comments.author_name IS 'The author''s name AS AT the moment of writing. Deliberately denormalised — see the table comment.';

--
-- Name: ats_candidate_comments_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.ats_candidate_comments ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.ats_candidate_comments_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: ats_candidate_cv_extractions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_cv_extractions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    file_id uuid,
    ai_model text NOT NULL,
    extracted_fields jsonb NOT NULL,
    applied_fields jsonb,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    position_key text DEFAULT 'medical_rep'::text NOT NULL,
    is_cv boolean,
    search_tsv tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, public.ats_candidate_cv_search_text(extracted_fields))) STORED
);

ALTER TABLE public.ats_candidate_cv_extractions OWNER TO postgres;

--
-- Name: TABLE ats_candidate_cv_extractions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_cv_extractions IS 'One row per AI CV-extraction run: extracted_fields is the AI''s raw {field: {value, confidence}} proposal, applied_fields is what Talent Acquisition actually saved after reviewing/correcting it. Audit trail and future prompt-tuning signal, not a model-training pipeline.';

--
-- Name: COLUMN ats_candidate_cv_extractions.position_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_cv_extractions.position_key IS 'Which CvPositionSchema (src/lib/recruitment/cv-field-schemas.ts) drove this extraction run.';

--
-- Name: COLUMN ats_candidate_cv_extractions.is_cv; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_cv_extractions.is_cv IS 'Did the read judge this document to be a CV/resume? Answered by the same AI call that extracted the fields. NULL = no judgement was recorded (every row written before 2026-08-21, and any read that never reached the model). Gate on `is_cv = false` only: NULL and true both mean "do not block", so a missing answer can never discard a real applicant.';

--
-- Name: ats_candidate_district_returns; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_district_returns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    manager_hr_id text NOT NULL,
    manager_name text,
    seat_id text,
    seat_label text,
    line_name text,
    region_name text,
    area_name text,
    reason_code text NOT NULL,
    reason_note text,
    status text DEFAULT 'open'::text NOT NULL,
    returned_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by_hr_id text,
    resolution_note text,
    CONSTRAINT ats_candidate_district_returns_hr_id_present CHECK ((length(btrim(manager_hr_id)) > 0)),
    CONSTRAINT ats_candidate_district_returns_hr_id_upper CHECK ((manager_hr_id = upper(manager_hr_id))),
    CONSTRAINT ats_candidate_district_returns_reason_known CHECK ((reason_code = ANY (ARRAY['area_not_match'::text, 'other'::text]))),
    CONSTRAINT ats_candidate_district_returns_resolution_paired CHECK ((((status = 'open'::text) AND (resolved_at IS NULL)) OR ((status = ANY (ARRAY['resolved'::text, 'reinstated'::text])) AND (resolved_at IS NOT NULL)))),
    CONSTRAINT ats_candidate_district_returns_status_known CHECK ((status = ANY (ARRAY['open'::text, 'resolved'::text, 'reinstated'::text])))
);

ALTER TABLE public.ats_candidate_district_returns OWNER TO postgres;

--
-- Name: TABLE ats_candidate_district_returns; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_district_returns IS 'A district manager''s "hand this CV back to the administrator" — a per-manager SUPPRESSION beside the derived district folders, not a move. The placement rule (district-manager-folders.ts) drops a CV from ONLY this manager''s folder while it carries an open/resolved row here; other lines that share the area keep it. The silent engagement report deliberately does NOT read this table. manager_hr_id is upper-case canonical, same as ats_candidate_views.viewer_hr_id.';

--
-- Name: COLUMN ats_candidate_district_returns.status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_district_returns.status IS 'open = in the admin Returned CVs queue and suppressing the CV from the manager''s folder; resolved = handled, out of the queue, still suppressing; reinstated = sent back to the manager, out of the queue, no longer suppressing. Suppression = status in (open, resolved).';

--
-- Name: ats_candidate_manager_folders; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_manager_folders (
    id bigint NOT NULL,
    candidate_id uuid NOT NULL,
    manager_hr_id text NOT NULL,
    manager_hr_id_norm text NOT NULL,
    kind text NOT NULL,
    folder_key text NOT NULL,
    filed_at timestamp with time zone DEFAULT now() NOT NULL,
    filed_by_hr_id text,
    CONSTRAINT ats_candidate_manager_folders_key_length CHECK ((char_length(folder_key) <= 120)),
    CONSTRAINT ats_candidate_manager_folders_key_not_blank CHECK ((btrim(folder_key) <> ''::text)),
    CONSTRAINT ats_candidate_manager_folders_kind_check CHECK ((kind = ANY (ARRAY['medical_rep'::text, 'district_manager'::text, 'other'::text, 'paramedical'::text]))),
    CONSTRAINT ats_candidate_manager_folders_manager_not_blank CHECK (((btrim(manager_hr_id) <> ''::text) AND (btrim(manager_hr_id_norm) <> ''::text)))
);

ALTER TABLE public.ats_candidate_manager_folders OWNER TO postgres;

--
-- Name: TABLE ats_candidate_manager_folders; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_manager_folders IS 'A manager''s own filing of a CV into one of the three recruitment shelves. Separate from ats_candidates.folder_kind/folder_key on purpose: that one is the recruitment team''s and filing there removes the CV from their pool. One row per candidate per manager, keyed on manager_hr_id_norm because HR_IDs here are mixed case.';

--
-- Name: COLUMN ats_candidate_manager_folders.manager_hr_id_norm; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_manager_folders.manager_hr_id_norm IS 'canonicalHrIdKey(manager_hr_id) — written by the application, not generated in SQL, because that function also folds the legacy alias aaa -> aa.';

--
-- Name: COLUMN ats_candidate_manager_folders.kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_manager_folders.kind IS 'medical_rep | district_manager | other | paramedical — the same four shelves as ats_candidates.folder_kind, duplicated so the two tables can be filed independently but cannot disagree about what a shelf is.';

--
-- Name: ats_candidate_manager_folders_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.ats_candidate_manager_folders ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.ats_candidate_manager_folders_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: ats_candidate_manager_sends; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_manager_sends (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    manager_hr_id text NOT NULL,
    manager_name text,
    manager_area text,
    manager_job_title text,
    manager_region text,
    sent_for_area text,
    sent_for_job_title text,
    sent_for_line text,
    sent_for_region text,
    sent_for_vacancy_id bigint,
    sent_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.ats_candidate_manager_sends OWNER TO postgres;

--
-- Name: TABLE ats_candidate_manager_sends; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_manager_sends IS 'Recruitment: one row per (candidate, manager) send. Replaces the single manager_notified_* columns on ats_candidates, which could only hold the LAST manager and silently removed a CV from the previous manager''s list. Owner 2026-08-30: "yes a CV can go to two managers". See src/lib/recruitment/manager-sends.ts.';

--
-- Name: COLUMN ats_candidate_manager_sends.manager_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_manager_sends.manager_hr_id IS 'HR_ID stored CANONICAL (lower case, per canonicalHrIdKey in src/lib/hr-id.ts) — unlike every other HR_ID column here, which are mixed case. Read it through hrIdLookupKeys(), which includes the lower-cased form; never a bare eq on a caller-supplied spelling.';

--
-- Name: COLUMN ats_candidate_manager_sends.sent_for_vacancy_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_manager_sends.sent_for_vacancy_id IS 'The vacancy this manager was sent the CV for. Per SEND, not per candidate: two managers can be sent the same person for two different seats.';

--
-- Name: ats_candidate_placements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_placements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    role_tab text NOT NULL,
    bot_role_family text,
    region_code text,
    area_code text,
    area_name text,
    placed_by text NOT NULL,
    session_id uuid,
    placed_by_hr_id text,
    placed_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_candidate_placements_placed_by_check CHECK ((placed_by = ANY (ARRAY['whatsapp'::text, 'website'::text, 'hr'::text, 'migration'::text]))),
    CONSTRAINT ats_candidate_placements_role_tab_check CHECK ((role_tab = ANY (ARRAY['medical_rep'::text, 'district_manager'::text, 'product_manager'::text, 'rm_am_nsm'::text, 'hr_section_head'::text, 'talent_acquisition'::text, 'office_coordinator'::text, 'personnel'::text, 'other'::text])))
);

ALTER TABLE public.ats_candidate_placements OWNER TO postgres;

--
-- Name: TABLE ats_candidate_placements; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_placements IS 'Which role tab (and region/area) a candidate is filed in — from the applicant''s own WhatsApp or careers-form reply, or placed by HR. No row = Needs placing. Never from a CV reading (owner, 2026-10-20).';

--
-- Name: ats_cv_intake_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_cv_intake_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel text NOT NULL,
    mailbox_label text,
    provider_message_id text,
    provider_uid text,
    sender_identifier text,
    sender_display_name text,
    subject text,
    outcome text DEFAULT 'processing'::text NOT NULL,
    candidate_id uuid,
    file_id uuid,
    match_reason text,
    error_message text,
    raw_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_channel_code text,
    CONSTRAINT ats_cv_intake_events_channel_check CHECK ((channel = ANY (ARRAY['email'::text, 'whatsapp'::text, 'website'::text]))),
    CONSTRAINT ats_cv_intake_events_outcome_check CHECK ((outcome = ANY (ARRAY['processing'::text, 'candidate_created'::text, 'candidate_matched'::text, 'ignored_no_attachment'::text, 'ignored_unsupported_attachment'::text, 'ignored_duplicate'::text, 'error'::text])))
);

ALTER TABLE public.ats_cv_intake_events OWNER TO postgres;

--
-- Name: TABLE ats_cv_intake_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_cv_intake_events IS 'One row per inbound email/WhatsApp message an intake poller or webhook attempted to turn into a candidate. The (channel, provider_message_id) unique index doubles as the idempotency claim key.';

--
-- Name: ats_candidate_source_context; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ats_candidate_source_context WITH (security_invoker='true') AS
 SELECT DISTINCT ON (candidate_id) candidate_id,
    channel,
    subject,
    sender_display_name,
    sender_identifier,
    raw_metadata,
    created_at
   FROM public.ats_cv_intake_events event
  WHERE (candidate_id IS NOT NULL)
  ORDER BY candidate_id, created_at DESC;

ALTER VIEW public.ats_candidate_source_context OWNER TO postgres;

--
-- Name: VIEW ats_candidate_source_context; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.ats_candidate_source_context IS 'One row per candidate: their most recent inbound-CV intake event. Reads the email subject (email) or the caption + first messages parked in raw_metadata (WhatsApp) for the candidate list/profile "source" column.';

--
-- Name: ats_candidate_status_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_status_events (
    id bigint NOT NULL,
    candidate_id uuid NOT NULL,
    from_status text,
    to_status text NOT NULL,
    note text,
    actor_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.ats_candidate_status_events OWNER TO postgres;

--
-- Name: TABLE ats_candidate_status_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_status_events IS 'Append-only history of every candidate status decision. candidate_id deliberately carries no FK so an event outlives a deleted candidate; actor_hr_id NULL means "not recorded", never "system".';

--
-- Name: ats_candidate_status_events_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.ats_candidate_status_events ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.ats_candidate_status_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: ats_candidate_views; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_candidate_views (
    candidate_id uuid NOT NULL,
    viewer_hr_id text NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    view_count integer DEFAULT 1 NOT NULL,
    claimed_until timestamp with time zone,
    CONSTRAINT ats_candidate_views_count_positive CHECK ((view_count > 0)),
    CONSTRAINT ats_candidate_views_hr_id_present CHECK ((length(btrim(viewer_hr_id)) > 0)),
    CONSTRAINT ats_candidate_views_hr_id_upper CHECK ((viewer_hr_id = upper(viewer_hr_id)))
);

ALTER TABLE public.ats_candidate_views OWNER TO postgres;

--
-- Name: TABLE ats_candidate_views; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_candidate_views IS 'Per-person "I have read this CV" marks for the screening queue. Separate from ats_candidates.status: seen is not decided, and a CV read but not judged must still be recallable as read. viewer_hr_id is upper-case canonical — ats_candidates stores lower-case hr ids and employees stores upper-case, so an un-normalised join returns nobody.';

--
-- Name: COLUMN ats_candidate_views.claimed_until; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_candidate_views.claimed_until IS 'Advisory short lease: this viewer has the CV open right now, until this instant. EXPIRES rather than being released, so a closed laptop cannot hold a CV away from the other screener. Nothing enforces it server-side; a stale claim costs a duplicated read, never a lost one. Added 2026-09-05 when screening became a two-person job.';

--
-- Name: ats_cv_field_settings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_cv_field_settings (
    field_key text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    updated_by text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.ats_cv_field_settings OWNER TO postgres;

--
-- Name: TABLE ats_cv_field_settings; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_cv_field_settings IS 'Per-field on/off switch for CV extraction. ABSENT ROW MEANS ENABLED — this table records only deviations from "capture everything", so it is normally near-empty. field_key matches a key in universalCvFields (src/lib/recruitment/cv-field-schemas.ts); a stale key for a field that no longer exists is ignored at read time rather than erroring.';

--
-- Name: COLUMN ats_cv_field_settings.enabled; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_cv_field_settings.enabled IS 'false removes the field from the AI request schema, the review board and the candidate panel. Identity fields (fullName/email/phone) are refused server-side regardless of what is stored here — candidate matching depends on them.';

--
-- Name: ats_cv_folder_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_cv_folder_items (
    id bigint NOT NULL,
    folder_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    filed_at timestamp with time zone DEFAULT now() NOT NULL,
    filed_by_hr_id text
);

ALTER TABLE public.ats_cv_folder_items OWNER TO postgres;

--
-- Name: TABLE ats_cv_folder_items; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_cv_folder_items IS 'Recruitment: which CVs are in which hand-built folder. One row per (folder, candidate) — a CV copied into a second folder has two rows, which is the whole reason this is a join table and not columns on ats_candidates. A candidate with AT LEAST ONE row here is hidden from the main pool (owner decision 2026-09-12); returning them to the pool deletes every row, never one.';

--
-- Name: COLUMN ats_cv_folder_items.filed_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_cv_folder_items.filed_by_hr_id IS 'Who pushed it here. NULL means not recorded (a dev-preview session has no HR_ID), never "system".';

--
-- Name: ats_cv_folder_items_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.ats_cv_folder_items ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.ats_cv_folder_items_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: ats_cv_folders; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_cv_folders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parent_id uuid,
    name text NOT NULL,
    name_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_hr_id text,
    CONSTRAINT ats_cv_folders_name_has_no_separator CHECK (((name !~ '[/\\]'::text) AND (name !~ '[[:cntrl:]]'::text))),
    CONSTRAINT ats_cv_folders_name_length CHECK ((char_length(name) <= 120)),
    CONSTRAINT ats_cv_folders_name_not_blank CHECK (((btrim(name) <> ''::text) AND (btrim(name_key) <> ''::text))),
    CONSTRAINT ats_cv_folders_not_its_own_parent CHECK (((parent_id IS NULL) OR (parent_id <> id)))
);

ALTER TABLE public.ats_cv_folders OWNER TO postgres;

--
-- Name: TABLE ats_cv_folders; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_cv_folders IS 'Recruitment: the hand-built CV folder tree — folders and subfolders a recruiter creates, as opposed to the four derived shelves in ats_candidates.folder_kind. Owner request 2026-09-12. Depth and cycles are enforced in src/lib/recruitment/cv-folder-tree.ts, not here.';

--
-- Name: COLUMN ats_cv_folders.parent_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_cv_folders.parent_id IS 'The folder this one sits inside. NULL is a top-level folder.';

--
-- Name: COLUMN ats_cv_folders.name_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_cv_folders.name_key IS 'Normalised name (lower-cased, whitespace collapsed) written by the application. Two folders under one parent cannot share it.';

--
-- Name: ats_cv_lifecycle_share_links; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_cv_lifecycle_share_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    token text NOT NULL,
    surface text DEFAULT 'feed'::text NOT NULL,
    label text,
    created_by_hr_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by_hr_id text,
    last_accessed_at timestamp with time zone,
    access_count integer DEFAULT 0 NOT NULL,
    refused_count integer DEFAULT 0 NOT NULL,
    last_refused_at timestamp with time zone,
    CONSTRAINT ats_cv_lifecycle_share_links_surface_check CHECK ((surface = 'feed'::text))
);

ALTER TABLE public.ats_cv_lifecycle_share_links OWNER TO postgres;

--
-- Name: TABLE ats_cv_lifecycle_share_links; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_cv_lifecycle_share_links IS 'Bearer tokens for the owner''s live CV-lifecycle Google Sheet. Mandatory expiry, one-click revoke, every read counted and stamped. Meant to sit inside a PRIVATE sheet''s Apps Script and never be handed to a person — the sheet''s own Google sharing is the real access control.';

--
-- Name: COLUMN ats_cv_lifecycle_share_links.refused_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_cv_lifecycle_share_links.refused_count IS 'Reads refused because this link is revoked or expired. See the direct-order column of the same name.';

--
-- Name: COLUMN ats_cv_lifecycle_share_links.last_refused_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_cv_lifecycle_share_links.last_refused_at IS 'When a dead-link read was last refused. Judged by src/lib/share-links/dead-token-polling.ts.';

--
-- Name: ats_email_intake_cursors; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_email_intake_cursors (
    mailbox_label text NOT NULL,
    imap_uidvalidity bigint,
    last_processed_uid bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.ats_email_intake_cursors OWNER TO postgres;

--
-- Name: TABLE ats_email_intake_cursors; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_email_intake_cursors IS 'IMAP polling watermark per mailbox (last_processed_uid). A UIDVALIDITY change resets the cursor to 0 for that mailbox; the ats_cv_intake_events claim key is the safety net against reprocessing in that case.';

--
-- Name: ats_files; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_files (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid,
    application_id uuid,
    kind text DEFAULT 'cv'::text NOT NULL,
    file_name text NOT NULL,
    mime_type text,
    size_bytes bigint,
    drive_file_id text,
    external_url text,
    uploaded_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    drive_mirror_file_id text,
    drive_mirror_path text,
    drive_mirror_at timestamp with time zone,
    drive_mirror_error text,
    content_md5 text,
    upload_origin text
);

ALTER TABLE public.ats_files OWNER TO postgres;

--
-- Name: COLUMN ats_files.drive_mirror_file_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_files.drive_mirror_file_id IS 'Google Drive file id of the mirrored copy in the owner''s Drive. NULL means not mirrored yet. Distinct from drive_file_id, which despite its name holds the Supabase Storage object path.';

--
-- Name: COLUMN ats_files.drive_mirror_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_files.drive_mirror_path IS 'The folder path the mirror was last filed under, slash-joined (e.g. "Medical Representative/Alex-BHR/Alex Center"). Compared against the candidate''s current folder to decide whether the file needs moving.';

--
-- Name: COLUMN ats_files.drive_mirror_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_files.drive_mirror_at IS 'When the mirror was last uploaded or moved.';

--
-- Name: COLUMN ats_files.drive_mirror_error; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_files.drive_mirror_error IS 'Last mirror failure, in words, or NULL. Set so a failure is visible without reading logs; cleared on the next success.';

--
-- Name: COLUMN ats_files.content_md5; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_files.content_md5 IS 'MD5 of the file bytes, written at upload time by uploadCandidateFile. The one duplicate signal in this pool that is proof rather than resemblance: an identical CV attaches to the candidate who already owns it instead of spawning a second record. Null on rows uploaded before 2026-09-05 that the backfill has not reached.';

--
-- Name: COLUMN ats_files.upload_origin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_files.upload_origin IS 'Which in-app path uploaded this file: interview_calendar, ats_upload, whatsapp_inbox. NULL means it arrived through inbound intake (email or WhatsApp), where ats_cv_intake_events carries the channel instead.';

--
-- Name: ats_interview_booking_changes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_booking_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    actor_hr_id text,
    kind text NOT NULL,
    summary text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.ats_interview_booking_changes OWNER TO postgres;

--
-- Name: TABLE ats_interview_booking_changes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_interview_booking_changes IS 'The change history of one interview booking: one row per recorded change (booked, rescheduled, interviewer set, confirmed, declined, CV replaced, outcome recorded …), with who did it and a short human summary. Append-only; written server-side after an app-level check.';

--
-- Name: ats_interview_booking_comments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_booking_comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    author_hr_id text NOT NULL,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_interview_booking_comments_body_length CHECK ((length(body) <= 1000)),
    CONSTRAINT ats_interview_booking_comments_body_not_blank CHECK ((length(btrim(body)) > 0))
);

ALTER TABLE public.ats_interview_booking_comments OWNER TO postgres;

--
-- Name: ats_interview_bookings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_bookings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid,
    starts_at timestamp with time zone NOT NULL,
    duration_minutes integer DEFAULT 30 NOT NULL,
    platform text NOT NULL,
    zoom_status text DEFAULT 'not_needed'::text NOT NULL,
    zoom_meeting_id text,
    zoom_join_url text,
    zoom_error text,
    notes text,
    created_by_hr_id text,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    session_id uuid,
    external_name text,
    external_phone text,
    external_email text,
    external_cv_file_id text,
    external_cv_file_name text,
    external_cv_mime_type text,
    interviewer_hr_id text,
    outcome text,
    outcome_set_by_hr_id text,
    outcome_set_at timestamp with time zone,
    request_id uuid,
    requested_by_hr_id text,
    panelist_hr_ids text[] DEFAULT '{}'::text[] NOT NULL,
    interview_area text,
    interview_line text,
    interviewer_confirmation text,
    interviewer_confirmation_at timestamp with time zone,
    interviewer_confirmation_by_hr_id text,
    decline_reason text,
    interview_job_title text,
    shared_with_hr_ids text[] DEFAULT '{}'::text[] NOT NULL,
    interview_round text,
    location text,
    CONSTRAINT ats_interview_bookings_confirmation_valid CHECK (((interviewer_confirmation IS NULL) OR (interviewer_confirmation = ANY (ARRAY['confirmed'::text, 'declined'::text])))),
    CONSTRAINT ats_interview_bookings_duration_valid CHECK ((((duration_minutes >= 15) AND (duration_minutes <= 480)) AND ((duration_minutes % 15) = 0))),
    CONSTRAINT ats_interview_bookings_external_lengths CHECK ((((external_name IS NULL) OR (length(external_name) <= 200)) AND ((external_phone IS NULL) OR (length(external_phone) <= 40)) AND ((external_email IS NULL) OR (length(external_email) <= 200)) AND ((external_cv_file_name IS NULL) OR (length(external_cv_file_name) <= 255)))),
    CONSTRAINT ats_interview_bookings_has_person CHECK (((candidate_id IS NOT NULL) OR ((external_name IS NOT NULL) AND (length(btrim(external_name)) > 0)))),
    CONSTRAINT ats_interview_bookings_location_length CHECK (((location IS NULL) OR (char_length(location) <= 300))),
    CONSTRAINT ats_interview_bookings_notes_length CHECK (((notes IS NULL) OR (length(notes) <= 1000))),
    CONSTRAINT ats_interview_bookings_office_has_no_meeting CHECK (((platform = 'zoom'::text) OR ((zoom_status = 'not_needed'::text) AND (zoom_meeting_id IS NULL) AND (zoom_join_url IS NULL)))),
    CONSTRAINT ats_interview_bookings_outcome_valid CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['attended'::text, 'shortlisted'::text, 'backup'::text, 'rejected'::text, 'prioritized'::text, 'did_not_come'::text, 'will_reschedule'::text, 'no_answer'::text, 'withdrew'::text])))),
    CONSTRAINT ats_interview_bookings_platform_valid CHECK ((platform = ANY (ARRAY['in_office'::text, 'zoom'::text, 'phone'::text]))),
    CONSTRAINT ats_interview_bookings_round_known CHECK (((interview_round IS NULL) OR (interview_round = ANY (ARRAY['hr_first'::text, 'dsm'::text, 'rsm'::text, 'hr_manager'::text, 'nsm_final'::text, 'joint_final'::text])))),
    CONSTRAINT ats_interview_bookings_zoom_status_valid CHECK ((zoom_status = ANY (ARRAY['not_needed'::text, 'created'::text, 'not_connected'::text, 'failed'::text])))
);

ALTER TABLE public.ats_interview_bookings OWNER TO postgres;

--
-- Name: TABLE ats_interview_bookings; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_interview_bookings IS 'Interviews booked from a CV onto the interview calendar. Hangs off the candidate, not an application; nothing is sent to the candidate.';

--
-- Name: COLUMN ats_interview_bookings.zoom_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.zoom_status IS 'not_needed (office) | created | not_connected (no Zoom account connected) | failed (see zoom_error).';

--
-- Name: COLUMN ats_interview_bookings.session_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.session_id IS 'The session whose slot this interview fills; it then uses the session''s meeting and has none of its own. Deleting the session deletes its slots.';

--
-- Name: COLUMN ats_interview_bookings.external_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.external_name IS 'An interview for someone outside Phoenix, kept on the calendar only (the booker chose not to add them to Recruitment). Set when candidate_id is null.';

--
-- Name: COLUMN ats_interview_bookings.external_cv_file_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.external_cv_file_id IS 'The outside person''s CV, in the recruitment file storage, reachable only through the calendar. Never an ats_files row.';

--
-- Name: COLUMN ats_interview_bookings.interviewer_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.interviewer_hr_id IS 'HR id of the employee conducting the interview; NULL when none was chosen. Stored as written, compared case-insensitively.';

--
-- Name: COLUMN ats_interview_bookings.outcome; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.outcome IS 'What happened at the interview. Attended, or one of its decisions (shortlisted, backup, rejected, prioritized); Didn''t come (did_not_come), or one of its reasons (will_reschedule, no_answer, withdrew). NULL until the interviewer (or the calendar owner) records it.';

--
-- Name: COLUMN ats_interview_bookings.requested_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.requested_by_hr_id IS 'HR id of the person who requested this interview (a DM-and-above or HR), NULL for a booking made directly. Lets the requester see it on their own calendar; compared case-insensitively.';

--
-- Name: COLUMN ats_interview_bookings.panelist_hr_ids; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.panelist_hr_ids IS 'Additional panel interviewers beyond the lead (interviewer_hr_id). Each sees the interview on their calendar, My interviews and .ics feed; the lead stays the outcome-setter and Zoom host.';

--
-- Name: COLUMN ats_interview_bookings.interview_area; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.interview_area IS 'The sales Area the interview is for (canonical area_name). Optional; auto-filled from the interviewer seat, editable. Shown in the calendar and share link.';

--
-- Name: COLUMN ats_interview_bookings.interview_line; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.interview_line IS 'The sales Line the interview is for (canonical line_name). Optional; auto-filled from the interviewer seat, editable. Shown in the calendar and share link.';

--
-- Name: COLUMN ats_interview_bookings.interviewer_confirmation; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.interviewer_confirmation IS 'The chosen interviewer''s answer to the assignment: confirmed | declined | NULL (not answered). A decline keeps the row for reassignment and stops the reminders to that interviewer.';

--
-- Name: COLUMN ats_interview_bookings.interview_job_title; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.interview_job_title IS 'The job this interview is for, as free text — chosen from offer_job_titles where the role is in that catalogue, typed otherwise. Carried onto a candidate the calendar creates as ats_candidates.applied_for_job_title.';

--
-- Name: COLUMN ats_interview_bookings.shared_with_hr_ids; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_interview_bookings.shared_with_hr_ids IS 'People the calendar owner shared this one interview with, view only: it shows on their calendar and they can open its CV. They cannot book, move, comment or share.';

--
-- Name: ats_interview_calendar_links; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_calendar_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    token text,
    access_level text NOT NULL,
    week_start date,
    guest_cvs boolean DEFAULT true NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_by_hr_id text,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_used_at timestamp with time zone,
    use_count integer DEFAULT 0 NOT NULL,
    token_hash text NOT NULL,
    token_preview text,
    expires_at timestamp with time zone,
    CONSTRAINT ats_interview_calendar_links_level_valid CHECK ((access_level = ANY (ARRAY['viewer'::text, 'commenter'::text, 'editor'::text]))),
    CONSTRAINT ats_interview_calendar_links_token_length CHECK ((length(token) >= 32)),
    CONSTRAINT ats_interview_calendar_links_week_is_sunday CHECK (((week_start IS NULL) OR (EXTRACT(dow FROM week_start) = (0)::numeric)))
);

ALTER TABLE public.ats_interview_calendar_links OWNER TO postgres;

--
-- Name: TABLE ats_interview_calendar_links; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_interview_calendar_links IS 'Bearer links to the interview calendar, owner-managed. Holding one VIEWS without signing in (the CVs too, unless guest_cvs is off); a signed-in holder gets access_level. week_start null = the whole calendar, else that Sunday''s week only. is_active false = switched off.';

--
-- Name: ats_interview_calendar_shares; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_calendar_shares (
    hr_id text NOT NULL,
    access_level text NOT NULL,
    shared_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_interview_calendar_shares_hr_id_not_blank CHECK ((length(btrim(hr_id)) > 0)),
    CONSTRAINT ats_interview_calendar_shares_level_valid CHECK ((access_level = ANY (ARRAY['viewer'::text, 'commenter'::text, 'editor'::text])))
);

ALTER TABLE public.ats_interview_calendar_shares OWNER TO postgres;

--
-- Name: TABLE ats_interview_calendar_shares; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_interview_calendar_shares IS 'Who the owner shared the interview calendar with. viewer sees it and opens CVs; commenter also comments; editor also books, moves and cancels.';

--
-- Name: ats_interview_ics_feed_tokens; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_ics_feed_tokens (
    hr_id text NOT NULL,
    token text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.ats_interview_ics_feed_tokens OWNER TO postgres;

--
-- Name: ats_interview_invitations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    recipient text NOT NULL,
    channel text NOT NULL,
    kind text DEFAULT 'invitation'::text NOT NULL,
    status text NOT NULL,
    destination text,
    detail text,
    sent_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_interview_invitations_channel_valid CHECK ((channel = ANY (ARRAY['whatsapp'::text, 'email'::text]))),
    CONSTRAINT ats_interview_invitations_kind_valid CHECK ((kind = ANY (ARRAY['invitation'::text, 'company_details'::text]))),
    CONSTRAINT ats_interview_invitations_recipient_valid CHECK ((recipient = ANY (ARRAY['candidate'::text, 'interviewer'::text]))),
    CONSTRAINT ats_interview_invitations_status_valid CHECK ((status = ANY (ARRAY['sent'::text, 'opened'::text, 'failed'::text])))
);

ALTER TABLE public.ats_interview_invitations OWNER TO postgres;

--
-- Name: TABLE ats_interview_invitations; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_interview_invitations IS 'Invitations the interview calendar prepared or sent for a booking. WhatsApp = opened (click-to-chat), e-mail = sent or failed.';

--
-- Name: ats_interview_poll_sets; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_poll_sets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    questions jsonb NOT NULL,
    created_by_hr_id text,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_interview_poll_sets_name_valid CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120))),
    CONSTRAINT ats_interview_poll_sets_questions_valid CHECK (((jsonb_typeof(questions) = 'array'::text) AND ((jsonb_array_length(questions) >= 1) AND (jsonb_array_length(questions) <= 25))))
);

ALTER TABLE public.ats_interview_poll_sets OWNER TO postgres;

--
-- Name: TABLE ats_interview_poll_sets; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_interview_poll_sets IS 'Interview polls saved once to attach to any Zoom interview. questions = [{name, type: single|multiple|short_answer, answers: [...]}].';

--
-- Name: ats_interview_request_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_request_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    candidate_id uuid,
    external_name text,
    external_phone text,
    external_email text,
    external_cv_file_id text,
    external_cv_file_name text,
    external_cv_mime_type text,
    booking_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_interview_request_items_has_person CHECK (((candidate_id IS NOT NULL) OR (length(btrim(COALESCE(external_name, ''::text))) > 0)))
);

ALTER TABLE public.ats_interview_request_items OWNER TO postgres;

--
-- Name: TABLE ats_interview_request_items; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_interview_request_items IS 'One CV on an interview request: a recruitment candidate or an outside person kept here only, and the booking it became once HR gave it a time.';

--
-- Name: ats_interview_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_interview_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    requested_by_hr_id text NOT NULL,
    interviewer_hr_id text NOT NULL,
    requested_day date NOT NULL,
    line text,
    note text,
    status text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_interview_requests_interviewer_not_blank CHECK ((length(btrim(interviewer_hr_id)) > 0)),
    CONSTRAINT ats_interview_requests_note_length CHECK (((note IS NULL) OR (length(note) <= 1000))),
    CONSTRAINT ats_interview_requests_requested_by_not_blank CHECK ((length(btrim(requested_by_hr_id)) > 0)),
    CONSTRAINT ats_interview_requests_status_valid CHECK ((status = ANY (ARRAY['pending'::text, 'scheduled'::text, 'cancelled'::text])))
);

