--
-- Name: ats_v_candidate_returns; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ats_v_candidate_returns WITH (security_invoker='true') AS
 SELECT DISTINCT ON (candidate_id) candidate_id,
    returned_at,
    returned_by_hr_id,
    returned_by_name,
    reason_code,
    reason_note,
    source
   FROM ( SELECT r.candidate_id,
            r.returned_at,
            r.manager_hr_id AS returned_by_hr_id,
            r.manager_name AS returned_by_name,
            r.reason_code,
            r.reason_note,
            'district_folder'::text AS source
           FROM public.ats_candidate_district_returns r
          WHERE (r.resolved_at IS NULL)
        UNION ALL
         SELECT e.candidate_id,
            e.created_at,
            e.actor_hr_id,
            NULL::text AS text,
            NULL::text AS text,
            e.note,
                CASE
                    WHEN (e.to_status = 'rejected'::text) THEN 'manager_skip'::text
                    ELSE 'taken_back'::text
                END AS "case"
           FROM public.ats_candidate_status_events e
          WHERE ((e.from_status = 'sent_to_manager'::text) AND (e.to_status = ANY (ARRAY['rejected'::text, 'shortlisted'::text])) AND (NOT (EXISTS ( SELECT 1
                   FROM public.ats_candidate_status_events later
                  WHERE ((later.candidate_id = e.candidate_id) AND ((later.created_at > e.created_at) OR ((later.created_at = e.created_at) AND (later.id > e.id))))))))) x
  ORDER BY candidate_id, returned_at DESC;

ALTER VIEW public.ats_v_candidate_returns OWNER TO postgres;

--
-- Name: ats_v_cv_lifecycle; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ats_v_cv_lifecycle WITH (security_invoker='on') AS
 SELECT f.id AS file_id,
    f.candidate_id,
    c.full_name AS candidate_name,
    COALESCE(NULLIF(c.whatsapp, ''::text), c.phone) AS candidate_phone,
    c.status AS candidate_status,
    c.applied_for_job_title,
    COALESCE(ev.channel, 'upload'::text) AS channel,
    ev.source_channel_code,
    ev.sender_display_name,
    ev.sender_identifier,
    ev.mailbox_label,
    ev.provider_message_id,
    ev.outcome AS intake_outcome,
    f.file_name,
    f.mime_type,
    f.size_bytes,
    q.created_at AS arrived_at,
    q.claimed_at AS picked_up_at,
    q.finished_at AS intake_finished_at,
    q.status AS queue_status,
    q.attempts AS queue_attempts,
    q.last_error AS queue_last_error,
    ev.intake_event_at,
    COALESCE(q.created_at, ev.intake_event_at, f.created_at) AS reached_phoenix_at,
        CASE
            WHEN (q.created_at IS NOT NULL) THEN 'queued'::text
            WHEN (ev.intake_event_at IS NOT NULL) THEN 'processed'::text
            ELSE 'saved'::text
        END AS timing_source,
    f.created_at AS saved_in_phoenix_at,
    f.drive_mirror_at AS saved_in_drive_at,
    f.drive_mirror_path AS drive_folder,
    f.drive_mirror_file_id AS drive_file_id,
    f.drive_mirror_error AS drive_error,
    c.preferences_declared_at,
    c.folder_filed_at,
    c.folder_kind,
    c.folder_key,
    c.preferred_region_code,
    c.preferred_area_name,
    c.governorate,
    c.address AS candidate_address,
    c.preferred_region_name,
    c.email AS candidate_email,
    c.linkedin_url,
    c.nationality,
    c.gender,
    c.date_of_birth,
    c.marital_status,
    c.military_status,
    c.faculty,
    c.university,
    c.degree,
    c.graduation_year,
    c.grade,
    c.current_employer,
    c.current_job_title,
    c.years_experience,
    c.has_prior_work_experience,
    c.has_medical_rep_experience,
    c.medical_rep_employer,
    c.medical_rep_experience_from,
    c.medical_rep_experience_to,
    c.expected_salary,
    c.notice_period,
    public.ats_cv_names_text((c.position_specific_fields -> 'skills'::text)) AS cv_skills,
    public.ats_cv_names_text((c.position_specific_fields -> 'languages'::text)) AS cv_languages,
    public.ats_cv_names_text((c.position_specific_fields -> 'certifications'::text)) AS cv_certifications,
    public.ats_cv_education_text((c.position_specific_fields -> 'educationHistory'::text)) AS cv_education,
    public.ats_cv_work_text((c.position_specific_fields -> 'workHistory'::text)) AS cv_work_history,
    c.professional_summary,
    c.declared_background,
    c.declared_experience,
    c.declared_expected_salary,
    (c.screening_extra_answers ->> 'oc_english_level'::text) AS screening_english_level,
    (c.screening_extra_answers ->> 'oc_ms_office_outlook'::text) AS screening_ms_office,
    (c.screening_extra_answers ->> 'oc_booking_experience'::text) AS screening_booking_experience,
    (c.screening_extra_answers ->> 'oc_sheraton_commute'::text) AS screening_commute,
    (c.screening_extra_answers ->> 'oc_start_date'::text) AS screening_start_date,
    COALESCE((c.screening_extra_answers ->> 'field_age_band'::text), (c.screening_extra_answers ->> 'oc_age_band'::text)) AS screening_age_band,
    c.source AS candidate_source,
    c.created_at AS candidate_created_at,
    c.status_changed_at AS candidate_status_changed_at,
    c.status_note AS candidate_status_note,
    c.manager_notified_name,
    c.manager_notified_at,
    c.manager_notified_area,
    c.manager_notified_region,
    c.sent_for_job_title,
    c.sent_for_area,
    c.sent_for_region,
    c.sent_for_line
   FROM (((public.ats_files f
     LEFT JOIN public.ats_candidates c ON ((c.id = f.candidate_id)))
     LEFT JOIN ( SELECT DISTINCT ON (e.file_id) e.file_id,
            e.channel,
            e.provider_message_id,
            e.provider_uid,
            e.sender_display_name,
            e.sender_identifier,
            e.mailbox_label,
            e.source_channel_code,
            e.outcome,
            e.created_at AS intake_event_at,
                CASE
                    WHEN (e.channel = 'whatsapp'::text) THEN e.provider_message_id
                    WHEN (e.channel = 'email'::text) THEN e.mailbox_label
                    ELSE NULL::text
                END AS queue_match_a,
                CASE
                    WHEN (e.channel = 'whatsapp'::text) THEN ''::text
                    WHEN (e.channel = 'email'::text) THEN e.provider_uid
                    ELSE NULL::text
                END AS queue_match_b
           FROM public.ats_cv_intake_events e
          WHERE (e.file_id IS NOT NULL)
          ORDER BY e.file_id, e.created_at) ev ON ((ev.file_id = f.id)))
     LEFT JOIN ( SELECT q_1.channel,
            q_1.created_at,
            q_1.claimed_at,
            q_1.finished_at,
            q_1.status,
            q_1.attempts,
            q_1.last_error,
                CASE
                    WHEN (q_1.channel = 'whatsapp'::text) THEN q_1.provider_message_id
                    WHEN (q_1.channel = 'email'::text) THEN split_part(q_1.provider_message_id, ':'::text, 2)
                    ELSE NULL::text
                END AS match_a,
                CASE
                    WHEN (q_1.channel = 'whatsapp'::text) THEN ''::text
                    WHEN (q_1.channel = 'email'::text) THEN split_part(q_1.provider_message_id, ':'::text, 4)
                    ELSE NULL::text
                END AS match_b
           FROM public.ats_inbound_intake_queue q_1) q ON (((q.channel = ev.channel) AND (q.match_a = ev.queue_match_a) AND (q.match_b = ev.queue_match_b))))
  WHERE (f.kind = 'cv'::text);

ALTER VIEW public.ats_v_cv_lifecycle OWNER TO postgres;

--
-- Name: VIEW ats_v_cv_lifecycle; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.ats_v_cv_lifecycle IS 'One row per CV file: arrival, intake, Phoenix save and Drive mirror, plus the candidate. Flattenable on purpose (no WITH) so ORDER BY/LIMIT readers defer the CV-text functions; the queue join is an equi-join on (channel, match_a, match_b). See 20260917190000.';

--
-- Name: ats_whatsapp_auto_replies; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_auto_replies (
    reply_key text NOT NULL,
    body_text text NOT NULL,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_whatsapp_auto_replies_body_check CHECK (((char_length(body_text) >= 1) AND (char_length(body_text) <= 1500))),
    CONSTRAINT ats_whatsapp_auto_replies_key_check CHECK ((reply_key = ANY (ARRAY['text_only_plain'::text, 'text_only_job_enquiry'::text, 'unreadable_photo'::text, 'unreadable_too_large'::text, 'closing_intro'::text, 'closing_outro'::text])))
);

ALTER TABLE public.ats_whatsapp_auto_replies OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_auto_replies; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_auto_replies IS 'Owner-editable wording for the automatic WhatsApp replies the recruitment bot sends by itself: the two ask-for-a-CV replies, the two unreadable-CV replies, and the first and last lines of the closing summary. One row per message; an ABSENT row means the code default in the sender module, which is why reset is a delete and no default text is ever stored here.';

--
-- Name: COLUMN ats_whatsapp_auto_replies.body_text; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_auto_replies.body_text IS 'The words an applicant reads, Arabic block then English. The too-large reply must contain the token {maxMb}, which the app replaces with the file-size limit actually in force (RECRUITMENT_INBOUND_CV_MAX_BYTES) - a fixed number would send applicants away to shrink a file Phoenix would have accepted.';

--
-- Name: ats_whatsapp_classification_sessions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_classification_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    wa_id text NOT NULL,
    phone_number_id text,
    step text DEFAULT 'job_title'::text NOT NULL,
    job_title_family text,
    region_code text,
    area_name text,
    cv_wamid text,
    last_prompt_wamid text,
    applied_candidate_id uuid,
    applied_at timestamp with time zone,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    job_title_other_text text,
    region_other_text text,
    area_other_text text,
    background text,
    background_other_text text,
    experience text,
    expected_salary text,
    extra_current_question_key text,
    extra_answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    reasked_at timestamp with time zone,
    CONSTRAINT ats_whatsapp_classification_sessions_step_check CHECK ((step = ANY (ARRAY['job_title'::text, 'job_title_other'::text, 'background'::text, 'background_other'::text, 'region'::text, 'region_other'::text, 'area'::text, 'area_other'::text, 'experience'::text, 'salary'::text, 'extra'::text, 'done'::text])))
);

ALTER TABLE public.ats_whatsapp_classification_sessions OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_classification_sessions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_classification_sessions IS 'Per-sender state of the three-question WhatsApp self-classification flow (role, region, area) asked when a CV arrives. Not the answer of record: completed answers are copied onto ats_candidates and the row is marked done.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.step; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.step IS 'Outstanding question: job_title -> (job_title_other) -> background -> (background_other) -> region -> (region_other) -> area -> (area_other) -> experience -> salary -> extra -> done. The bracketed steps and salary are typed (no menu). The area step is reached only by a Medical Rep. extra is the admin-defined question loop, entered only when at least one active question exists at the moment salary finishes; a session that never sees an active question goes straight from salary to done, exactly as before this migration.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.last_prompt_wamid; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.last_prompt_wamid IS 'wamid of the most recent prompt sent, so a Meta webhook retry cannot re-ask the same question.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.job_title_other_text; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.job_title_other_text IS 'The job title the applicant TYPED after choosing "Other" on question 1, cleaned and capped at 120 characters. Null for every other answer. Copied verbatim to ats_candidates.applied_for_job_title when the conversation completes.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.region_other_text; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.region_other_text IS 'The region the applicant TYPED after choosing "My region is not listed", cleaned and capped at 80 characters. Null for every other answer. Copied to ats_candidates.preferred_region_name when the conversation completes — never to preferred_region_code, which holds codes.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.area_other_text; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.area_other_text IS 'The area the applicant TYPED, either after choosing "My area is not listed" or because the region they chose has no areas drawn yet (Delta (3), 2026-08-28). Cleaned and capped at 80 characters. Copied to ats_candidates.preferred_area_name.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.background; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.background IS 'Graduation background the applicant chose: a code (pharmacy/science/vet), or "other" when they typed their own. Null until they answer. Read back through sessionBackgroundLabel, which resolves the code to a label or returns background_other_text.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.background_other_text; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.background_other_text IS 'What the applicant TYPED after choosing "Other" on the background question, cleaned and capped at 80 characters. Null for every other answer. Copied verbatim to ats_candidates.declared_background when it is their answer.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.experience; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.experience IS 'Years-of-experience band the applicant chose: a code (fresh/lt_1/1_3/3_5/gt_5). No "other" — the bands are exhaustive. Null until they answer. Read back through sessionExperienceLabel, which resolves the code to a label.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.expected_salary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.expected_salary IS 'Expected monthly salary the applicant TYPED, cleaned and capped at 60 characters, stored VERBATIM. May read "12000", a range, "negotiable", or Arabic numerals — never coerced to a number. Copied verbatim to ats_candidates.expected_salary.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.extra_current_question_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.extra_current_question_key IS 'Which admin-defined question is outstanding — a KEY, not a positional index, so a mid-flight reorder or deactivation of another question cannot strand this conversation. Null outside the extra-question loop.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.extra_answers; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.extra_answers IS 'Answers collected so far in the extra-question loop, keyed by question_key. Copied verbatim onto ats_candidates.screening_extra_answers when the loop finishes.';

--
-- Name: COLUMN ats_whatsapp_classification_sessions.reasked_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_classification_sessions.reasked_at IS 'When the in-window re-ask cron re-sent the current question (once per session). Null = never re-asked.';

--
-- Name: ats_whatsapp_cv_archive; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_cv_archive (
    id uuid NOT NULL,
    full_name text,
    phone text,
    whatsapp text,
    email text,
    job_title text,
    region text,
    area text,
    background text,
    experience text,
    expected_salary text,
    extra_answers jsonb DEFAULT '[]'::jsonb NOT NULL,
    received_at timestamp with time zone NOT NULL,
    folder_path text[] NOT NULL,
    original_row jsonb NOT NULL,
    archived_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ats_whatsapp_cv_archive_extra_answers_chk CHECK ((jsonb_typeof(extra_answers) = 'array'::text)),
    CONSTRAINT ats_whatsapp_cv_archive_folder_chk CHECK (((cardinality(folder_path) >= 1) AND (cardinality(folder_path) <= 6)))
);

ALTER TABLE public.ats_whatsapp_cv_archive OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_cv_archive; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_cv_archive IS 'Old WhatsApp applicants the owner kept when the CVs received before 11 Oct 2026 were cleaned out (2026-10-18). Not candidates: only the Archive on the WhatsApp Applicants page reads it. id = the deleted candidate''s id; original_row = that row as it was.';

--
-- Name: ats_whatsapp_cv_archive_files; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_cv_archive_files (
    id uuid NOT NULL,
    archive_id uuid NOT NULL,
    file_name text NOT NULL,
    mime_type text,
    size_bytes bigint,
    content_md5 text,
    storage_path text NOT NULL,
    received_at timestamp with time zone
);

ALTER TABLE public.ats_whatsapp_cv_archive_files OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_cv_archive_files; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_cv_archive_files IS 'CV files of ats_whatsapp_cv_archive rows, stored in the private recruitment-cv-archive bucket.';

--
-- Name: ats_whatsapp_inbound_messages; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_inbound_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    wa_id text NOT NULL,
    body text NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.ats_whatsapp_inbound_messages OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_inbound_messages; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_inbound_messages IS 'Short-lived buffer of inbound WhatsApp text messages per sender (wa_id), held until that sender''s CV document arrives so the first few messages can be attached to the candidate. Consumed on CV intake; swept by retention.';

--
-- Name: ats_whatsapp_message_templates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_message_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    category text,
    body text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_by_hr_id text,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    audience text DEFAULT 'any'::text NOT NULL,
    CONSTRAINT ats_whatsapp_message_templates_audience_check CHECK ((audience = ANY (ARRAY['any'::text, 'employee'::text]))),
    CONSTRAINT ats_whatsapp_message_templates_body_length CHECK ((length(body) <= 2000)),
    CONSTRAINT ats_whatsapp_message_templates_body_not_blank CHECK ((length(btrim(body)) > 0)),
    CONSTRAINT ats_whatsapp_message_templates_name_length CHECK ((length(name) <= 80)),
    CONSTRAINT ats_whatsapp_message_templates_name_not_blank CHECK ((length(btrim(name)) > 0))
);

ALTER TABLE public.ats_whatsapp_message_templates OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_message_templates; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_message_templates IS 'Owner-editable WhatsApp message templates for the ATS. Plain text with {{placeholders}}; NOT Meta-approved Cloud API templates.';

--
-- Name: COLUMN ats_whatsapp_message_templates.audience; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_message_templates.audience IS 'Who this template may be sent to: ''any'' (candidates and employees) or ''employee'' (kept off the candidate screen). Complements the derived rule in requiresEmployeeTarget, which keys on employee-only placeholders and cannot see a template whose fields are all typed — a salary increase being the case that forced this. Either signal is sufficient; neither can widen a template''s audience.';

--
-- Name: ats_whatsapp_outbound_messages; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_outbound_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    to_wa_id text NOT NULL,
    phone_number_id text NOT NULL,
    message_type text NOT NULL,
    body text,
    payload jsonb,
    event text NOT NULL,
    inbound_wamid text,
    context jsonb,
    ok boolean NOT NULL,
    provider_message_id text,
    failure_reason text,
    failure_detail text,
    CONSTRAINT ats_whatsapp_outbound_messages_failure_reason_check CHECK (((failure_reason IS NULL) OR (failure_reason = ANY (ARRAY['disabled'::text, 'invalid_menu'::text, 'window_closed'::text, 'failed'::text])))),
    CONSTRAINT ats_whatsapp_outbound_messages_outcome_check CHECK (((ok AND (failure_reason IS NULL)) OR ((NOT ok) AND (failure_reason IS NOT NULL))))
);

ALTER TABLE public.ats_whatsapp_outbound_messages OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_outbound_messages; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_outbound_messages IS 'Every WhatsApp message Phoenix sent: exact text, recipient, sending line, and outcome. Written by postToGraph after Meta answers. Never blocks a send.';

--
-- Name: COLUMN ats_whatsapp_outbound_messages.body; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_outbound_messages.body IS 'The exact text delivered to the recipient. This is the column that exists so "show me the reply that went out" is a query, not a reconstruction from source code.';

--
-- Name: COLUMN ats_whatsapp_outbound_messages.ok; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_outbound_messages.ok IS 'Whether Meta accepted the message. A false row is a message the person never received — do not read this table as a delivery receipt: Meta accepting is not the handset showing it.';

--
-- Name: ats_whatsapp_question_prompts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_question_prompts (
    question_key text NOT NULL,
    body_text text,
    option_labels jsonb DEFAULT '{}'::jsonb NOT NULL,
    hidden_options jsonb DEFAULT '[]'::jsonb NOT NULL,
    option_order jsonb DEFAULT '[]'::jsonb NOT NULL,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    applies_to_role_families text[],
    button_label text,
    section_title text,
    CONSTRAINT ats_whatsapp_question_prompts_audience_shape CHECK (((applies_to_role_families IS NULL) OR (cardinality(applies_to_role_families) = 0) OR ((array_position(applies_to_role_families, NULL::text) IS NULL) AND (array_to_string(applies_to_role_families, ','::text) ~ '^[a-z][a-z0-9_]*(,[a-z][a-z0-9_]*)*$'::text) AND (cardinality(applies_to_role_families) = cardinality(string_to_array(array_to_string(applies_to_role_families, ','::text), ','::text)))))),
    CONSTRAINT ats_whatsapp_question_prompts_body_check CHECK (((body_text IS NULL) OR ((char_length(body_text) >= 1) AND (char_length(body_text) <= 1024)))),
    CONSTRAINT ats_whatsapp_question_prompts_button_label_check CHECK (((button_label IS NULL) OR ((char_length(btrim(button_label)) >= 1) AND (char_length(btrim(button_label)) <= 20)))),
    CONSTRAINT ats_whatsapp_question_prompts_free_text_chrome_check CHECK (((question_key <> 'salary'::text) OR ((button_label IS NULL) AND (section_title IS NULL)))),
    CONSTRAINT ats_whatsapp_question_prompts_hidden_options_check CHECK ((jsonb_typeof(hidden_options) = 'array'::text)),
    CONSTRAINT ats_whatsapp_question_prompts_job_title_audience_check CHECK (((question_key <> 'job_title'::text) OR (applies_to_role_families IS NULL))),
    CONSTRAINT ats_whatsapp_question_prompts_key_check CHECK ((question_key = ANY (ARRAY['job_title'::text, 'background'::text, 'region'::text, 'area'::text, 'experience'::text, 'salary'::text]))),
    CONSTRAINT ats_whatsapp_question_prompts_not_empty_check CHECK (((body_text IS NOT NULL) OR (option_labels <> '{}'::jsonb) OR (hidden_options <> '[]'::jsonb) OR (option_order <> '[]'::jsonb) OR (applies_to_role_families IS NOT NULL) OR (button_label IS NOT NULL) OR (section_title IS NOT NULL))),
    CONSTRAINT ats_whatsapp_question_prompts_option_labels_check CHECK ((jsonb_typeof(option_labels) = 'object'::text)),
    CONSTRAINT ats_whatsapp_question_prompts_option_order_check CHECK ((jsonb_typeof(option_order) = 'array'::text)),
    CONSTRAINT ats_whatsapp_question_prompts_section_title_check CHECK (((section_title IS NULL) OR ((char_length(btrim(section_title)) >= 1) AND (char_length(btrim(section_title)) <= 24))))
);

ALTER TABLE public.ats_whatsapp_question_prompts OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_question_prompts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_question_prompts IS 'Owner-editable prompt text and answer LABELS for the six built-in WhatsApp screening questions. One row per step; an absent row, a null body_text, or a value missing from option_labels all mean the code default in whatsapp-classify-menus.ts. Answer VALUES are never stored here - they stay in code, because the rest of the app reads them.';

--
-- Name: COLUMN ats_whatsapp_question_prompts.body_text; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_question_prompts.body_text IS 'The prompt an applicant reads, or NULL for the code default. For question_key = ''area'' the token {region} is replaced with the region name they chose.';

--
-- Name: COLUMN ats_whatsapp_question_prompts.option_labels; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_question_prompts.option_labels IS 'Display overrides for the tappable answers, keyed by the option VALUE (the code the tap sends back): { "<value>": { "title": "...", "description": "..." } }. Rewrites what is shown only - never the value itself.';

--
-- Name: COLUMN ats_whatsapp_question_prompts.applies_to_role_families; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_question_prompts.applies_to_role_families IS 'Which candidate role families are asked this built-in question, as candidateRoleFamily codes (candidate-role-family.ts). THREE states, unlike the two-state column of the same name on ats_whatsapp_screening_questions: NULL means nothing configured, so the question takes its CODE default from BUILT_IN_DEFAULT_AUDIENCE (whatsapp-question-audience.ts) - which is every applicant for five of the six, and Medical Reps only for ''area''. An EMPTY array means configured as everyone, and beats that default; it is legal here and refused on the sibling table. A non-empty array narrows the question to those families. Membership is validated in TypeScript (audienceViolations), not by a CHECK, so opening a new kind of seat does not need a migration. NULL always, for question_key = ''job_title'': it establishes the role, so it cannot be scoped by it.';

--
-- Name: COLUMN ats_whatsapp_question_prompts.button_label; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_question_prompts.button_label IS 'The words on the button that opens this question''s WhatsApp list. NULL means use the code''s own ("Choose a role"). Max 20 — Meta refuses the whole message over it.';

--
-- Name: COLUMN ats_whatsapp_question_prompts.section_title; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_question_prompts.section_title IS 'The heading WhatsApp prints above this question''s answers. NULL means use the code''s own ("Roles"). Max 24 — Meta refuses the whole message over it.';

--
-- Name: ats_whatsapp_screening_questions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_screening_questions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    question_key text NOT NULL,
    body_text text NOT NULL,
    kind text NOT NULL,
    options jsonb,
    sort_order integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_by_hr_id text,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    applies_to_role_families text[],
    button_label text,
    section_title text,
    show_if jsonb,
    end_on jsonb,
    CONSTRAINT ats_whatsapp_screening_questions_body_length CHECK ((char_length(body_text) <= 1024)),
    CONSTRAINT ats_whatsapp_screening_questions_button_label_check CHECK (((button_label IS NULL) OR ((char_length(btrim(button_label)) >= 1) AND (char_length(btrim(button_label)) <= 20)))),
    CONSTRAINT ats_whatsapp_screening_questions_end_on_check CHECK (((end_on IS NULL) OR ((kind = 'tappable'::text) AND (jsonb_typeof(end_on) = 'object'::text) AND (jsonb_typeof((end_on -> 'values'::text)) = 'array'::text) AND (jsonb_array_length((end_on -> 'values'::text)) > 0) AND (jsonb_typeof((end_on -> 'message'::text)) = 'string'::text) AND ((char_length(btrim((end_on ->> 'message'::text))) >= 1) AND (char_length(btrim((end_on ->> 'message'::text))) <= 1024))))),
    CONSTRAINT ats_whatsapp_screening_questions_free_text_chrome_check CHECK (((kind <> 'free_text'::text) OR ((button_label IS NULL) AND (section_title IS NULL)))),
    CONSTRAINT ats_whatsapp_screening_questions_key_format CHECK ((question_key ~ '^[a-z][a-z0-9_]{1,62}$'::text)),
    CONSTRAINT ats_whatsapp_screening_questions_kind_check CHECK ((kind = ANY (ARRAY['tappable'::text, 'free_text'::text]))),
    CONSTRAINT ats_whatsapp_screening_questions_options_shape CHECK ((((kind = 'free_text'::text) AND (options IS NULL)) OR ((kind = 'tappable'::text) AND (options IS NOT NULL) AND (jsonb_typeof(options) = 'array'::text) AND ((jsonb_array_length(options) >= 1) AND (jsonb_array_length(options) <= 10))))),
    CONSTRAINT ats_whatsapp_screening_questions_role_scope_shape CHECK (((applies_to_role_families IS NULL) OR ((array_length(applies_to_role_families, 1) >= 1) AND (array_position(applies_to_role_families, NULL::text) IS NULL) AND (array_to_string(applies_to_role_families, ','::text) ~ '^[a-z][a-z0-9_]*(,[a-z][a-z0-9_]*)*$'::text) AND (cardinality(applies_to_role_families) = cardinality(string_to_array(array_to_string(applies_to_role_families, ','::text), ','::text)))))),
    CONSTRAINT ats_whatsapp_screening_questions_section_title_check CHECK (((section_title IS NULL) OR ((char_length(btrim(section_title)) >= 1) AND (char_length(btrim(section_title)) <= 24)))),
    CONSTRAINT ats_whatsapp_screening_questions_show_if_check CHECK (((show_if IS NULL) OR ((jsonb_typeof(show_if) = 'object'::text) AND (jsonb_typeof((show_if -> 'question_key'::text)) = 'string'::text) AND (jsonb_typeof((show_if -> 'values'::text)) = 'array'::text) AND (jsonb_array_length((show_if -> 'values'::text)) > 0))))
);

ALTER TABLE public.ats_whatsapp_screening_questions OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_screening_questions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_screening_questions IS 'Super-Admin-defined questions asked over WhatsApp after the fixed six (role/background/region/area/experience/salary) finish. Answers are stored on ats_candidates.screening_extra_answers, keyed by question_key.';

--
-- Name: COLUMN ats_whatsapp_screening_questions.question_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_screening_questions.question_key IS 'Immutable slug (enforced by ats_whatsapp_screening_questions_immutable_key below) — the key every collected answer is filed under. Never reused: retire with is_active = false, never delete a question with real answers.';

--
-- Name: COLUMN ats_whatsapp_screening_questions.options; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_screening_questions.options IS 'For kind = tappable: a JSON array of {value, title, description?}, 1-10 elements. Null for free_text.';

--
-- Name: COLUMN ats_whatsapp_screening_questions.applies_to_role_families; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_screening_questions.applies_to_role_families IS 'Which candidate role families are asked this question, as candidateRoleFamily codes (candidate-role-family.ts). NULL means every applicant — the behaviour every row had before this column existed. A non-empty array narrows it: only an applicant whose tapped role is in the list is asked. Membership is validated in TypeScript (screeningQuestionViolations), not by a CHECK, so opening a new kind of seat does not need a migration.';

--
-- Name: COLUMN ats_whatsapp_screening_questions.button_label; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_screening_questions.button_label IS 'The words on the button that opens this question''s WhatsApp list. NULL means use the code''s default ("Choose an option"). Max 20 — Meta refuses the whole message over it.';

--
-- Name: COLUMN ats_whatsapp_screening_questions.section_title; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_screening_questions.section_title IS 'The heading WhatsApp prints above this question''s answers. NULL means use the code''s default ("Options"). Max 24 — Meta refuses the whole message over it.';

--
-- Name: COLUMN ats_whatsapp_screening_questions.show_if; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_screening_questions.show_if IS 'Conditional question: {"question_key": "<other question>", "values": ["<option code>", ...]}. Asked only when the applicant''s answer to that question was one of those option codes. NULL = asked whenever the role matches.';

--
-- Name: COLUMN ats_whatsapp_screening_questions.end_on; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_screening_questions.end_on IS 'End-on-answer: {"values": ["<option code>", ...], "message": "<words>"}. Tapping one of those answers ends the conversation and sends message instead of the closing summary. The answers so far are still recorded. NULL = no answer ends it.';

--
-- Name: ats_whatsapp_template_sends; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ats_whatsapp_template_sends (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    template_id uuid,
    candidate_id uuid,
    to_number text NOT NULL,
    rendered_body text NOT NULL,
    variable_values jsonb DEFAULT '{}'::jsonb NOT NULL,
    opened_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    employee_hr_id text
);

ALTER TABLE public.ats_whatsapp_template_sends OWNER TO postgres;

--
-- Name: TABLE ats_whatsapp_template_sends; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ats_whatsapp_template_sends IS 'Append-only record of WhatsApp messages PREPARED (opened in WhatsApp) from a template. Not proof of delivery — a human still presses send.';

--
-- Name: COLUMN ats_whatsapp_template_sends.opened_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_template_sends.opened_by_hr_id IS 'Who opened the message in WhatsApp. Deliberately not named sent_by: delivery is unobservable from here.';

--
-- Name: COLUMN ats_whatsapp_template_sends.employee_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ats_whatsapp_template_sends.employee_hr_id IS 'The employee a message was prepared for, when the target was an employee rather than a candidate. Text rather than a FK because hr_id is mixed case and this table is an append-only record that must survive the person leaving the directory. NULL together with candidate_id means the number was typed by hand.';

--
-- Name: attendance_annual_balance_charges; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.attendance_annual_balance_charges (
    id bigint NOT NULL,
    settlement_id bigint,
    digest_line_id bigint,
    employee_hr_id text NOT NULL,
    work_date date NOT NULL,
    days numeric(8,3) NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reverses_charge_id bigint,
    reversal_reason text,
    source text DEFAULT 'weekly_review'::text NOT NULL,
    deduction_candidate_id uuid,
    comment text,
    CONSTRAINT attendance_annual_balance_charges_days_check CHECK ((((days > (0)::numeric) AND (reverses_charge_id IS NULL) AND (reversal_reason IS NULL) AND (source = 'weekly_review'::text) AND (settlement_id IS NOT NULL) AND (digest_line_id IS NOT NULL) AND (deduction_candidate_id IS NULL)) OR ((days > (0)::numeric) AND (reverses_charge_id IS NULL) AND (reversal_reason IS NULL) AND (source = 'deductions'::text) AND (settlement_id IS NULL) AND (digest_line_id IS NULL) AND (deduction_candidate_id IS NOT NULL) AND (comment IS NOT NULL) AND (btrim(comment) <> ''::text)) OR ((days < (0)::numeric) AND (reverses_charge_id IS NOT NULL) AND (settlement_id IS NULL) AND (reversal_reason IS NOT NULL)))),
    CONSTRAINT attendance_annual_balance_charges_source_check CHECK ((source = ANY (ARRAY['weekly_review'::text, 'deductions'::text])))
);

ALTER TABLE public.attendance_annual_balance_charges OWNER TO postgres;

--
-- Name: TABLE attendance_annual_balance_charges; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.attendance_annual_balance_charges IS 'Annual leave days spent on attendance deductions the employee chose to pay from balance, and (negative rows, reverses_charge_id set) days given back when that dispute was revised to upheld. Every annual balance read sums days, so a reversal nets itself. Charges are written only by phx_attendance_settle_digest_line, reversals only by phx_attendance_revise_digest_dispute; never updated or deleted.';

--
-- Name: COLUMN attendance_annual_balance_charges.source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_annual_balance_charges.source IS 'Who wrote the row: weekly_review (the attendance review settle function) or deductions (the Deductions workspace "Deduct from leave balance" button).';

--
-- Name: COLUMN attendance_annual_balance_charges.deduction_candidate_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_annual_balance_charges.deduction_candidate_id IS 'The deduction a deductions-source charge paid (and the reversal that gives it back).';

--
-- Name: COLUMN attendance_annual_balance_charges.comment; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_annual_balance_charges.comment IS 'The Super Admin''s comment on a deductions-source charge, shown to the employee exactly as written in their Vacation Report.';

--
-- Name: attendance_annual_balance_charges_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.attendance_annual_balance_charges_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.attendance_annual_balance_charges_id_seq OWNER TO postgres;

--
-- Name: attendance_annual_balance_charges_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: postgres
--

ALTER SEQUENCE public.attendance_annual_balance_charges_id_seq OWNED BY public.attendance_annual_balance_charges.id;

--
-- Name: attendance_raw_punches; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.attendance_raw_punches (
    id bigint NOT NULL,
    device_id text NOT NULL,
    device_user_id text NOT NULL,
    employee_hr_id text,
    punch_time timestamp with time zone NOT NULL,
    punch_type text,
    verify_mode text,
    raw_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    source_run_id text,
    ingested_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.attendance_raw_punches OWNER TO postgres;

--
-- Name: TABLE attendance_raw_punches; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.attendance_raw_punches IS 'Raw fingerprint attendance punches ingested from a local Windows attendance agent. No payroll or attendance calculations are stored here.';

--
-- Name: attendance_device_user_latest_punch; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.attendance_device_user_latest_punch AS
 SELECT device_id,
    device_user_id,
    max(punch_time) AS latest_punch_at
   FROM public.attendance_raw_punches p
  GROUP BY device_id, device_user_id;

ALTER VIEW public.attendance_device_user_latest_punch OWNER TO postgres;

--
-- Name: VIEW attendance_device_user_latest_punch; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.attendance_device_user_latest_punch IS 'Newest punch per (device_id, device_user_id). Exists so the device-mapping dashboard reads one row per device user instead of capping a raw-punch scan at 5,000 rows, where the OLDEST punches — the stale users the screen is for — silently fell off the end.';

--
-- Name: attendance_device_user_map; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.attendance_device_user_map (
    id bigint NOT NULL,
    device_id text NOT NULL,
    device_user_id text NOT NULL,
    employee_hr_id text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_punch_at timestamp with time zone,
    non_employee_label text,
    CONSTRAINT attendance_device_user_map_active_requires_employee CHECK (((is_active = false) OR (employee_hr_id IS NOT NULL))),
    CONSTRAINT attendance_device_user_map_non_employee_exclusive CHECK (((non_employee_label IS NULL) OR ((employee_hr_id IS NULL) AND (is_active = false) AND (btrim(non_employee_label) <> ''::text))))
);

ALTER TABLE public.attendance_device_user_map OWNER TO postgres;

--
-- Name: TABLE attendance_device_user_map; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.attendance_device_user_map IS 'Maps fingerprint device user IDs to Phoenix employees.hr_id for direct attendance ingestion.';

--
-- Name: COLUMN attendance_device_user_map.last_seen_punch_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_device_user_map.last_seen_punch_at IS 'Latest punch timestamp observed for this device user during raw ingestion. Used to help HR map discovered fingerprint users without storing unmapped raw punches.';

--
-- Name: COLUMN attendance_device_user_map.non_employee_label; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_device_user_map.non_employee_label IS 'Set ONLY for a device user who is deliberately not an employee - a driver, guard, cleaner or outsourced worker enrolled on the reader. Mutually exclusive with employee_hr_id and forces is_active = false, so the punches stay skipped: such a person is not on payroll and must never produce attendance days or deductions. Its purpose is to separate "identified, and not an employee" from "nobody knows who this is" in resolveDeviceMappingStatus - without it both read as unmapped. A blank string is rejected so the label cannot silently mean nothing.';

--
-- Name: attendance_device_user_map_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.attendance_device_user_map ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.attendance_device_user_map_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: attendance_digest_dispute_messages; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.attendance_digest_dispute_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    line_id bigint NOT NULL,
    author_hr_id text NOT NULL,
    author_is_reviewer boolean DEFAULT false NOT NULL,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT attendance_digest_dispute_messages_body_check CHECK ((length(btrim(body)) > 0))
);

ALTER TABLE public.attendance_digest_dispute_messages OWNER TO postgres;

--
-- Name: TABLE attendance_digest_dispute_messages; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.attendance_digest_dispute_messages IS 'Replies on one weekly attendance review dispute. The employee''s own dispute_reason is the opening message and is not copied here.';

--
-- Name: attendance_digest_lines; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.attendance_digest_lines (
    id bigint NOT NULL,
    digest_id bigint NOT NULL,
    work_date date NOT NULL,
    status text NOT NULL,
    late_minutes integer DEFAULT 0 NOT NULL,
    short_minutes integer DEFAULT 0 NOT NULL,
    worked_minutes integer DEFAULT 0 NOT NULL,
    deduction_days numeric(8,3) DEFAULT 0 NOT NULL,
    deduction_value numeric(12,2),
    reason text,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    action text DEFAULT 'pending'::text NOT NULL,
    acted_at timestamp with time zone,
    dispute_reason text,
    dispute_attachment_url text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    chosen_method text,
    removed_at timestamp with time zone,
    removed_by_hr_id text,
    remove_reason text,
    review_notes text,
    deduct boolean DEFAULT false NOT NULL,
    detected_days numeric(8,3),
    detected_value numeric(12,2),
    adjusted_by_hr_id text,
    adjusted_at timestamp with time zone,
    hr_ops_line_id uuid,
    hr_ops_decided_by_hr_id text,
    hr_ops_decided_at timestamp with time zone,
    CONSTRAINT attendance_digest_lines_action_check CHECK ((action = ANY (ARRAY['pending'::text, 'removed'::text, 'salary'::text, 'annual_balance'::text, 'auto_salary'::text, 'disputed'::text, 'dispute_upheld'::text, 'dispute_rejected'::text, 'confirmed'::text]))),
    CONSTRAINT attendance_digest_lines_chosen_method_check CHECK (((chosen_method IS NULL) OR (chosen_method = ANY (ARRAY['salary'::text, 'annual_balance'::text])))),
    CONSTRAINT attendance_digest_lines_disputed_method_check CHECK (((action <> 'disputed'::text) OR (chosen_method IS NOT NULL))),
    CONSTRAINT attendance_digest_lines_status_check CHECK ((status = ANY (ARRAY['late'::text, 'short_hours'::text, 'early_leave'::text, 'missing_punch'::text, 'field_review'::text])))
);

ALTER TABLE public.attendance_digest_lines OWNER TO postgres;

--
-- Name: TABLE attendance_digest_lines; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.attendance_digest_lines IS 'Per-day deductible items inside a weekly digest; carries the employee confirm/dispute action and the evidence that could contradict the charge.';

--
-- Name: COLUMN attendance_digest_lines.deduction_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_digest_lines.deduction_value IS 'NULL means the day is chargeable but could not be priced (no salary on file) — never that it is free.';

--
-- Name: COLUMN attendance_digest_lines.deduct; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_digest_lines.deduct IS 'Ticked by the Super Admin on the weekly review page before release. An unticked pending day is cleared (removed) when the week is released. Owner 2026-09-15: every day starts unticked.';

--
-- Name: COLUMN attendance_digest_lines.detected_days; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_digest_lines.detected_days IS 'The days the fingerprint report detected. deduction_days is the figure charged, which the Super Admin may change before release, up or down.';

--
-- Name: COLUMN attendance_digest_lines.hr_ops_line_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_digest_lines.hr_ops_line_id IS 'The HR operations report line (hr_ops_report_lines) whose decision set or added this day. The daily job never refreshes, overwrites or removes such a day (phx_attendance_sync_digest_days).';

--
-- Name: COLUMN attendance_digest_lines.hr_ops_decided_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_digest_lines.hr_ops_decided_by_hr_id IS 'Who decided this day in the HR operations report.';

--
-- Name: COLUMN attendance_digest_lines.hr_ops_decided_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_digest_lines.hr_ops_decided_at IS 'When this day was decided in the HR operations report.';

--
-- Name: attendance_digest_lines_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.attendance_digest_lines_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.attendance_digest_lines_id_seq OWNER TO postgres;

--
-- Name: attendance_digest_lines_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: postgres
--

ALTER SEQUENCE public.attendance_digest_lines_id_seq OWNED BY public.attendance_digest_lines.id;

--
-- Name: attendance_digest_settings; Type: TABLE; Schema: public; Owner: postgres
--

