    CONSTRAINT attendance_digest_settings_id_check CHECK ((id = 1))
);

ALTER TABLE public.attendance_digest_settings OWNER TO postgres;

--
-- Name: TABLE attendance_digest_settings; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.attendance_digest_settings IS 'Singleton config for the weekly-digest engine: dispute reviewers, channels, auto-confirm window, cycle anchor, dry-run and enabled flags.';

--
-- Name: COLUMN attendance_digest_settings.answer_working_days; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_digest_settings.answer_working_days IS 'Working days an employee has, after the week is released, to choose salary or annual balance. Unanswered days then settle to salary. Owner 2026-09-15: 2.';

--
-- Name: attendance_exceptions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.attendance_exceptions (
