ALTER TABLE public.attendance_exceptions OWNER TO postgres;

--
-- Name: attendance_exceptions_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.attendance_exceptions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
