--
-- Name: attendance_policy_groups; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.attendance_policy_groups (
    id bigint NOT NULL,
    policy_name text NOT NULL,
    target_type text NOT NULL,
    target_value text,
    scheduled_start time without time zone NOT NULL,
    scheduled_end time without time zone NOT NULL,
    grace_minutes integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    effective_from date DEFAULT CURRENT_DATE NOT NULL,
    effective_to date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    working_weekdays smallint[],
    flex_minutes integer,
    required_minutes integer,
    half_day_split_minutes integer DEFAULT 780 NOT NULL,
    judgment_mode text DEFAULT 'every_working_day'::text NOT NULL,
    CONSTRAINT attendance_policy_groups_default_target_check CHECK ((((target_type = 'default'::text) AND (target_value IS NULL)) OR ((target_type <> 'default'::text) AND (NULLIF(TRIM(BOTH FROM target_value), ''::text) IS NOT NULL)))),
    CONSTRAINT attendance_policy_groups_effective_range_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT attendance_policy_groups_flex_minutes_check CHECK (((flex_minutes IS NULL) OR ((flex_minutes >= 0) AND (flex_minutes <= 240)))),
    CONSTRAINT attendance_policy_groups_grace_minutes_check CHECK (((grace_minutes >= 0) AND (grace_minutes <= 240))),
    CONSTRAINT attendance_policy_groups_half_day_split_minutes_check CHECK (((half_day_split_minutes >= 0) AND (half_day_split_minutes <= 1440))),
    CONSTRAINT attendance_policy_groups_judgment_mode_check CHECK ((judgment_mode = ANY (ARRAY['every_working_day'::text, 'office_days_only'::text]))),
    CONSTRAINT attendance_policy_groups_required_minutes_check CHECK (((required_minutes IS NULL) OR ((required_minutes >= 0) AND (required_minutes <= 1440)))),
    CONSTRAINT attendance_policy_groups_target_type_check CHECK ((target_type = ANY (ARRAY['default'::text, 'job_title'::text, 'employee_hr_id'::text]))),
    CONSTRAINT attendance_policy_groups_working_weekdays_check CHECK (((working_weekdays IS NULL) OR ((cardinality(working_weekdays) >= 1) AND (cardinality(working_weekdays) <= 7) AND (array_position(working_weekdays, NULL::smallint) IS NULL) AND (working_weekdays <@ ARRAY[(0)::smallint, (1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint]))))
);

ALTER TABLE public.attendance_policy_groups OWNER TO postgres;

--
-- Name: TABLE attendance_policy_groups; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.attendance_policy_groups IS 'Attendance policy groups targeted by default, job title, or employee HR_ID. Used for report calculations only until HR approves payroll integration.';

--
-- Name: COLUMN attendance_policy_groups.working_weekdays; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_policy_groups.working_weekdays IS 'Optional custom expected attendance weekdays using JavaScript/Postgres DOW numbers: Sunday=0 through Saturday=6. Null keeps the standard company weekend policy.';

--
-- Name: COLUMN attendance_policy_groups.flex_minutes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_policy_groups.flex_minutes IS 'Arrival flexibility in minutes past scheduled_start before lateness is counted (30 = free until 09:30). Null falls back to the legacy grace model.';

--
-- Name: COLUMN attendance_policy_groups.required_minutes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_policy_groups.required_minutes IS 'Minimum required presence in minutes (470 = 7h50m). Null falls back to the legacy scheduled-duration model.';

--
-- Name: COLUMN attendance_policy_groups.half_day_split_minutes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_policy_groups.half_day_split_minutes IS 'Minute-of-day boundary that splits an AM/PM half-day leave (default 780 = 13:00).';

--
-- Name: COLUMN attendance_policy_groups.judgment_mode; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.attendance_policy_groups.judgment_mode IS 'every_working_day = judged every working day (head office); office_days_only = judged only on plan-office days with a punch (NSM/GPM/PM).';

