    is_active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT attendance_policy_rules_deduction_days_check CHECK (((deduction_days IS NULL) OR (deduction_days >= (0)::numeric))),
    CONSTRAINT attendance_policy_rules_deduction_value_check CHECK (((deduction_value IS NULL) OR (deduction_value >= (0)::numeric))),
    CONSTRAINT attendance_policy_rules_event_type_check CHECK ((event_type = ANY (ARRAY['late'::text, 'early_leave'::text, 'single_punch'::text, 'absence'::text, 'exception'::text, 'short_hours'::text]))),
    CONSTRAINT attendance_policy_rules_minutes_check CHECK ((((from_minutes IS NULL) OR (from_minutes >= 0)) AND ((to_minutes IS NULL) OR (to_minutes >= 0)) AND ((from_minutes IS NULL) OR (to_minutes IS NULL) OR (to_minutes >= from_minutes))))
);

