--
-- Name: au_v_employee_seat_drift; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.au_v_employee_seat_drift AS
 WITH seated AS (
         SELECT oh.occupant_hr_id AS hr_id,
            s.seat_id,
            s.seat_tier,
            s.line_code,
            s.area_code,
            s.parent_seat_id
           FROM (au.occupancy_history oh
             JOIN au.seats s ON ((s.seat_id = oh.seat_id)))
          WHERE ((oh.effective_to IS NULL) AND (oh.occupant_hr_id IS NOT NULL))
        )
 SELECT e.hr_id,
    e.full_name,
    se.seat_id,
    se.seat_tier,
    ar.id AS seat_area_id,
    e.area_id AS employee_area_id,
    ar.name AS seat_area_name,
    lam.operational_region_code AS seat_region_code,
    e.region_code AS employee_region_code,
    parent_occ.occupant_hr_id AS seat_manager_hr_id,
    e.manager_hr_id AS employee_manager_hr_id,
    e.pending_manager_replacement_for_hr_id AS pending_marker,
    ((se.seat_tier = 'REP'::text) AND (ar.id IS NOT NULL) AND (e.area_id IS DISTINCT FROM ar.id)) AS area_id_drifted,
    ((se.seat_tier = 'REP'::text) AND (lam.operational_region_code IS NOT NULL) AND (COALESCE(e.region_code, ''::text) IS DISTINCT FROM COALESCE(lam.operational_region_code, ''::text))) AS region_code_drifted,
    ((parent_occ.occupant_hr_id IS NOT NULL) AND (lower(btrim(parent_occ.occupant_hr_id)) IS DISTINCT FROM lower(btrim(e.hr_id))) AND (upper(COALESCE(e.manager_hr_id, ''::text)) IS DISTINCT FROM upper(parent_occ.occupant_hr_id))) AS manager_drifted,
    ((parent_occ.occupant_hr_id IS NOT NULL) AND (lower(btrim(parent_occ.occupant_hr_id)) IS DISTINCT FROM lower(btrim(e.hr_id))) AND (e.pending_manager_replacement_for_hr_id IS NOT NULL)) AS stale_marker
   FROM ((((seated se
     JOIN public.employees e ON ((upper(btrim(e.hr_id)) = upper(btrim(se.hr_id)))))
     LEFT JOIN public.areas ar ON (((ar.code = se.area_code) AND ar.is_active)))
     LEFT JOIN au.line_area_map lam ON (((lam.line_code = se.line_code) AND (lam.area_code = se.area_code) AND (lam.effective_to IS NULL))))
     LEFT JOIN LATERAL ( SELECT o.occupant_hr_id
           FROM au.occupancy_history o
          WHERE ((o.seat_id = se.parent_seat_id) AND (o.effective_to IS NULL) AND (o.occupant_hr_id IS NOT NULL))
         LIMIT 1) parent_occ ON (true))
  WHERE (lower(COALESCE(e.employment_status, ''::text)) = 'active'::text);

ALTER VIEW public.au_v_employee_seat_drift OWNER TO postgres;

--
-- Name: VIEW au_v_employee_seat_drift; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.au_v_employee_seat_drift IS 'Every active seated employee whose denormalized employees columns disagree with the au seat model. The seat is the source of truth; a true flag here means the copy is wrong, not the seat. Filter on the *_drifted / stale_marker booleans. The area_name label and its area_name_drifted flag were removed on 2026-09-29 with the column: area_id_drifted is the area check.';

