    m.staffed_in_line_code,
    m.carries_target,
    m.effective_from,
    m.effective_to,
    m.notes,
    ca.area_name
   FROM (au.line_area_map m
     JOIN au.canonical_areas ca ON ((ca.area_code = m.area_code)))
  WHERE (m.effective_to IS NULL);

ALTER VIEW public.au_v_line_area_map OWNER TO postgres;

