-- Name: au_v_org_tree; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.au_v_org_tree AS
 SELECT seat_id,
    parent_seat_id,
    seat_tier,
    line_code,
    region_code,
    area_code,
    is_other_pseudo_dm,
    seat_label,
    depth,
    path,
    occupant_hr_id,
    node_type,
    is_vacant,
    area_name,
    region_name,
    line_name,
    line_id,
    seat_display_label
   FROM au.v_org_tree;

ALTER VIEW public.au_v_org_tree OWNER TO postgres;

--
-- Name: au_v_org_tree_sales; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.au_v_org_tree_sales AS
 SELECT t.seat_id,
    t.parent_seat_id,
    t.seat_tier,
    t.line_code,
    t.region_code,
    t.area_code,
    t.is_other_pseudo_dm,
    t.seat_label,
    t.depth,
    t.path,
    t.occupant_hr_id,
    t.node_type,
    t.is_vacant,
    t.area_name,
    t.region_name,
    t.line_name,
    t.line_id,
    t.seat_display_label
   FROM au.v_org_tree t
UNION ALL
 SELECT s.seat_id,
    s.parent_seat_id,
    s.seat_tier,
    s.line_code,
    s.region_code,
    s.area_code,
    s.is_other_pseudo_dm,
    s.seat_label,
    (p.depth + 1) AS depth,
    (p.path || s.seat_id) AS path,
    o.occupant_hr_id,
    o.node_type,
    (o.occupant_hr_id IS NULL) AS is_vacant,
    NULL::text AS area_name,
    rg.region_name,
    p.line_name,
    p.line_id,
    s.seat_label AS seat_display_label
   FROM (((au.seats s
     JOIN LATERAL ( SELECT DISTINCT ON (t.seat_id) t.depth,
            t.path,
            t.line_name,
            t.line_id
           FROM au.v_org_tree t
          WHERE (t.seat_id = s.parent_seat_id)) p ON (true))
     LEFT JOIN au.occupancy_history o ON (((o.seat_id = s.seat_id) AND (o.effective_from <= ((now() AT TIME ZONE 'Africa/Cairo'::text))::date) AND ((o.effective_to IS NULL) OR (o.effective_to > ((now() AT TIME ZONE 'Africa/Cairo'::text))::date)))))
     LEFT JOIN au.regions rg ON ((rg.region_code = s.region_code)))
  WHERE (s.sales_only AND ((s.effective_from IS NULL) OR (s.effective_from <= ((now() AT TIME ZONE 'Africa/Cairo'::text))::date)) AND ((s.effective_to IS NULL) OR (s.effective_to > ((now() AT TIME ZONE 'Africa/Cairo'::text))::date)));

ALTER VIEW public.au_v_org_tree_sales OWNER TO postgres;

