--
-- Name: VIEW au_v_seat_occupancy_all; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.au_v_seat_occupancy_all IS 'Seat occupancy WITH history, for period-aware attribution. au_v_org_tree is today only; resolving a past month through it names the wrong person. Dating is half-open [effective_from, effective_to): a seat change closes and reopens on the same day, so an inclusive end matches both rows.';

--
-- Name: audit_log_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.audit_log_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payload jsonb NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.audit_log_outbox OWNER TO postgres;

--
-- Name: TABLE audit_log_outbox; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.audit_log_outbox IS 'audit_logs rows whose insert failed (usually a client-side request timeout under load). Drained opportunistically by src/lib/admin/audit-outbox.ts on the back of successful audit writes; a row is deleted the moment its audit_logs insert lands.';

--
