);

ALTER TABLE public.automated_payroll_draft_cell_history OWNER TO postgres;

--
-- Name: TABLE automated_payroll_draft_cell_history; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.automated_payroll_draft_cell_history IS 'Append-only history of every cell change on automated_payroll_draft_rows, written by trigger. No FK to the run on purpose: the record outlives a cancelled run.';

--
-- Name: automated_payroll_draft_cell_history_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.automated_payroll_draft_cell_history ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.automated_payroll_draft_cell_history_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: automated_payroll_draft_rows; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_draft_rows (
    run_id uuid NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    base_for_month numeric(14,2),
    ecol_paid numeric(14,2),
    fuel_paid numeric(14,2),
    fingerprint_days numeric(8,2),
    fingerprint_value numeric(14,2),
    expenses numeric(14,2),
    incentive numeric(14,2),
    bonus numeric(14,2),
    overtime numeric(14,2),
    unpaid_vacations numeric(14,2),
    crm numeric(14,2),
    manual_other_deductions numeric(14,2),
    manual_reason text,
    first_part_frozen numeric(14,2),
    on_hold boolean DEFAULT false NOT NULL,
    hold_reason text,
    source text DEFAULT 'inline'::text NOT NULL,
    edited_by text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    p1od_crm_days numeric(8,2),
    p1od_crm_value numeric(14,2),
    p1od_crm_reason text,
    p1od_vacation_days numeric(8,2),
    p1od_vacation_value numeric(14,2),
    p1od_vacation_reason text,
    p1od_no_record_days numeric(8,2),
    p1od_no_record_value numeric(14,2),
    p1od_no_record_reason text,
    p1od_loan_days numeric(8,2),
    p1od_loan_value numeric(14,2),
    p1od_loan_reason text,
    p1od_other_days numeric(8,2),
    p1od_other_value numeric(14,2),
    p1od_other_reason text,
    resignation_crm_days numeric(8,2),
    special_deduction_days numeric(8,2),
    special_deduction_value numeric(12,2),
    special_addition_days numeric(8,2),
    special_addition_value numeric(12,2),
    special_situation_part text,
    expenses_note text,
    excluded boolean DEFAULT false NOT NULL,
    excluded_reason text,
    days_worked numeric(10,2),
    settled_in_part1 boolean,
    additions_reason text,
    write_reason text,
    write_step_key text,
    other_additions numeric,
    held_release_value numeric,
    part1_withheld boolean,
    pay_deferral_value numeric(14,2),
    pay_deferral_month text,
    held_release_p1_value numeric(14,2),
    pay_deferral_p1_value numeric(14,2),
    pay_deferral_p1_month text,
    CONSTRAINT automated_payroll_draft_rows_part1_release_deferral_check CHECK ((((held_release_p1_value IS NULL) OR (held_release_p1_value >= (0)::numeric)) AND ((pay_deferral_p1_value IS NULL) OR (pay_deferral_p1_value >= (0)::numeric)) AND ((pay_deferral_p1_month IS NULL) OR (pay_deferral_p1_month = ANY (ARRAY['next'::text, 'after_next'::text]))))),
    CONSTRAINT automated_payroll_draft_rows_pay_deferral_check CHECK ((((pay_deferral_value IS NULL) OR (pay_deferral_value >= (0)::numeric)) AND ((pay_deferral_month IS NULL) OR (pay_deferral_month = ANY (ARRAY['next'::text, 'after_next'::text]))))),
    CONSTRAINT automated_payroll_draft_rows_source_check CHECK ((source = ANY (ARRAY['inline'::text, 'xlsx'::text]))),
    CONSTRAINT automated_payroll_draft_rows_special_situation_part_check CHECK (((special_situation_part IS NULL) OR (special_situation_part = ANY (ARRAY['first'::text, 'second'::text]))))
);

ALTER TABLE public.automated_payroll_draft_rows OWNER TO postgres;

--
-- Name: COLUMN automated_payroll_draft_rows.expenses_note; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.expenses_note IS 'Optional HR note explaining an outstation expense figure — required in practice for a manually added employee, whose amount has no trip behind it. Display/xlsx only; never affects money.';

--
-- Name: COLUMN automated_payroll_draft_rows.days_worked; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.days_worked IS 'Leaver/joiner days worked this month as CONFIRMED by HR on the Resignations step. The single source of truth for every Part 1 tab that needs a leaver day count (Resignations, Resignations CRM). NULL = not confirmed; fall back to the computed settlement. Never re-derive this from base_for_month — that is the bug this column closes (owner-reported 2026-08-30).';

--
-- Name: COLUMN automated_payroll_draft_rows.settled_in_part1; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.settled_in_part1 IS 'The Part 1 / Part 2 deduction routing, frozen at Part 1 confirm alongside first_part_frozen. NULL = not frozen yet, so the live rule answers. Cleared when a run is reopened to Part 1.';

--
-- Name: COLUMN automated_payroll_draft_rows.additions_reason; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.additions_reason IS 'Why this employee is being paid an incentive, bonus or overtime this month. Required by the Additions step confirm whenever any of the three is non-zero.';

--
-- Name: COLUMN automated_payroll_draft_rows.write_reason; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.write_reason IS 'Why the latest write to this row happened (step_saved, step_confirmed, part1_confirmed, ...). Read by the cell-history trigger; every writer in src/lib/automated-payroll/draft-store.ts sets it.';

--
-- Name: COLUMN automated_payroll_draft_rows.write_step_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.write_step_key IS 'The wizard step whose save or confirm made the latest write, when one did. Read by the cell-history trigger.';

--
-- Name: COLUMN automated_payroll_draft_rows.other_additions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.other_additions IS 'Additions step -> Other Additions (money). Recommended from dispute_refunds due this month; HR confirms. Paid in the Other Additions column beside Special Situations additions.';

--
-- Name: COLUMN automated_payroll_draft_rows.held_release_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.held_release_value IS 'Held Salary Release step -> amount of an earlier month''s withheld salary paid in this month''s Part 2 (Other Additions). Never above the outstanding held balance; Part 2 confirm reserves it and publish records it in automated_payroll_held_releases.';

--
-- Name: COLUMN automated_payroll_draft_rows.part1_withheld; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.part1_withheld IS 'Frozen at Part 1 confirm: on hold at that moment, so the Part 1 bank files did not pay the first instalment. NULL before Part 1 confirm or on runs confirmed before this column.';

--
-- Name: COLUMN automated_payroll_draft_rows.pay_deferral_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.pay_deferral_value IS 'Defer Pay step -> amount taken off this month''s Part 2 and owed again later. Never above the row''s Part 2; zero effect on a held row.';

--
-- Name: COLUMN automated_payroll_draft_rows.pay_deferral_month; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.pay_deferral_month IS 'Defer Pay step -> when the deferred amount falls due: next (the month after this run) or after_next (two months after).';

--
-- Name: COLUMN automated_payroll_draft_rows.held_release_p1_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.held_release_p1_value IS 'Part 1 Held Salary Release -> earlier held salary paid in this month''s Part 1. Nothing on a row held at Part 1 confirm.';

--
-- Name: COLUMN automated_payroll_draft_rows.pay_deferral_p1_value; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.pay_deferral_p1_value IS 'Part 1 Defer Pay -> amount taken off this month''s Part 1 and owed again later. Never above the row''s Part 1; nothing on a row held at Part 1 confirm.';

--
-- Name: COLUMN automated_payroll_draft_rows.pay_deferral_p1_month; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_draft_rows.pay_deferral_p1_month IS 'Part 1 Defer Pay -> when the deferred amount falls due: next or after_next.';

--
-- Name: automated_payroll_held_entered; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_held_entered (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    held_run_id uuid NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    employee_name text,
    amount numeric(14,2) NOT NULL,
    note text NOT NULL,
    recorded_in_run_id uuid,
    recorded_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automated_payroll_held_entered_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT automated_payroll_held_entered_note_check CHECK ((length(btrim(note)) > 0))
);

ALTER TABLE public.automated_payroll_held_entered OWNER TO postgres;

--
-- Name: TABLE automated_payroll_held_entered; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.automated_payroll_held_entered IS 'HR-typed held amount for a person an earlier published run withheld, for a run published before the payroll kept each held person (July and August 2026). Counts only for a run whose published audit row has no held list; ignored for a run that recorded names.';

--
-- Name: COLUMN automated_payroll_held_entered.note; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_held_entered.note IS 'Why HR knows the figure. Required.';

--
-- Name: COLUMN automated_payroll_held_entered.recorded_in_run_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_held_entered.recorded_in_run_id IS 'The run on whose Held Salary Release step the amount was entered.';

--
-- Name: automated_payroll_held_part1_unpaid; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_held_part1_unpaid (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    held_run_id uuid NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    employee_name text,
    amount numeric(14,2) NOT NULL,
    recorded_in_run_id uuid,
    recorded_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automated_payroll_held_part1_unpaid_amount_check CHECK ((amount >= (0)::numeric))
);

ALTER TABLE public.automated_payroll_held_part1_unpaid OWNER TO postgres;

--
-- Name: TABLE automated_payroll_held_part1_unpaid; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.automated_payroll_held_part1_unpaid IS 'HR record that an earlier published run''s Part 1 was not paid to this person (held at Part 1). Adds to the outstanding held balance; never above the frozen Part 1 of that run.';

--
-- Name: automated_payroll_held_releases; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_held_releases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    paying_run_id uuid NOT NULL,
    held_run_id uuid NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    amount numeric(14,2) NOT NULL,
    recorded_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automated_payroll_held_releases_amount_check CHECK ((amount >= (0)::numeric))
);

ALTER TABLE public.automated_payroll_held_releases OWNER TO postgres;

--
-- Name: TABLE automated_payroll_held_releases; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.automated_payroll_held_releases IS 'What a payroll run released of an earlier month''s held salary, per (paying run, held run, person). Separate from the by-hand held settlements. Outstanding held = withheld - settled by hand - released here (cancelled paying runs ignored).';

--
-- Name: automated_payroll_held_settlements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_held_settlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    amount numeric(14,2) DEFAULT 0 NOT NULL,
    paid_on date NOT NULL,
    method text,
    reference text,
    note text,
    recorded_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automated_payroll_held_settlements_amount_check CHECK ((amount >= (0)::numeric))
);

ALTER TABLE public.automated_payroll_held_settlements OWNER TO postgres;

--
-- Name: TABLE automated_payroll_held_settlements; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.automated_payroll_held_settlements IS 'Attestation that a HELD payroll row was transferred outside the payroll system. Publishing drops held rows and writes no salary_record, so without this there is no record that the money was ever paid and the next month can pay it again. A row is a human claim, not an observation — nothing here is verified against a bank.';

--
-- Name: COLUMN automated_payroll_held_settlements.amount; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_held_settlements.amount IS 'What was actually transferred. Deliberately separate from what was owed (which lives in the run''s assembled rows) so a short payment shows as a difference instead of overwriting the amount due.';

--
-- Name: automated_payroll_non_employee_recurring; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_non_employee_recurring (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    full_name_ar text NOT NULL,
    full_name_en text NOT NULL,
    total_salary numeric(14,2) DEFAULT 0 NOT NULL,
    bank_name text,
    bank_account text,
    part text DEFAULT 'first'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    note text,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automated_payroll_non_employee_recurring_part_check CHECK ((part = ANY (ARRAY['first'::text, 'second'::text]))),
    CONSTRAINT automated_payroll_non_employee_recurring_total_salary_check CHECK ((total_salary >= (0)::numeric))
);

ALTER TABLE public.automated_payroll_non_employee_recurring OWNER TO postgres;

--
-- Name: TABLE automated_payroll_non_employee_recurring; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.automated_payroll_non_employee_recurring IS 'Standing roster of people paid a fixed monthly salary with no employee/HR_ID record. Copied into each new run''s automated_payroll_non_employees list at run start. Never read directly by any sheet, total or bank file.';

--
-- Name: COLUMN automated_payroll_non_employee_recurring.part; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_non_employee_recurring.part IS 'Which installment this person is normally paid with: first (Part 1) or second (Part 2). Copied onto the run entry, where it stays independently editable.';

--
-- Name: COLUMN automated_payroll_non_employee_recurring.active; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_non_employee_recurring.active IS 'Inactive entries stay for history but are not copied into new runs. Deactivate rather than delete — a deleted register row cannot explain a past month''s sheet.';

--
-- Name: automated_payroll_non_employees; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_non_employees (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    full_name_ar text NOT NULL,
    full_name_en text NOT NULL,
    total_salary numeric(14,2) DEFAULT 0 NOT NULL,
    bank_name text,
    bank_account text,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    part text DEFAULT 'first'::text NOT NULL,
    recurring_id uuid,
    CONSTRAINT automated_payroll_non_employees_part_check CHECK ((part = ANY (ARRAY['first'::text, 'second'::text]))),
    CONSTRAINT automated_payroll_non_employees_total_salary_check CHECK ((total_salary >= (0)::numeric))
);

ALTER TABLE public.automated_payroll_non_employees OWNER TO postgres;

--
-- Name: COLUMN automated_payroll_non_employees.part; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_non_employees.part IS 'Which installment this non-employee is paid with: first (Part 1) or second (Part 2). Default first — the module''s original Part-1-only behaviour.';

--
-- Name: COLUMN automated_payroll_non_employees.recurring_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_non_employees.recurring_id IS 'The standing-roster entry this row was copied from, or null when HR added it by hand for this month only. Provenance only — the amount paid is always this row''s own total_salary.';

--
-- Name: automated_payroll_resync_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_resync_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payload jsonb NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.automated_payroll_resync_outbox OWNER TO postgres;

--
-- Name: TABLE automated_payroll_resync_outbox; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.automated_payroll_resync_outbox IS 'Payroll resyncs (Deductions / outstation expense decisions) refused by the run''s hold. Drained opportunistically by src/lib/automated-payroll/resync-outbox.ts, always under the hold; a row is deleted once its resync runs or is skipped.';

--
-- Name: automated_payroll_standing_additions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.automated_payroll_standing_additions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    field text DEFAULT 'incentive'::text NOT NULL,
    amount numeric(14,2) NOT NULL,
    every_months integer,
    first_month_key text NOT NULL,
    last_month_key text,
    reason text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT automated_payroll_standing_additions_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT automated_payroll_standing_additions_every_months_check CHECK (((every_months IS NULL) OR ((every_months >= 1) AND (every_months <= 12)))),
    CONSTRAINT automated_payroll_standing_additions_field_check CHECK ((field = ANY (ARRAY['incentive'::text, 'bonus'::text]))),
    CONSTRAINT automated_payroll_standing_additions_first_month_check CHECK ((first_month_key ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'::text)),
    CONSTRAINT automated_payroll_standing_additions_last_month_check CHECK (((last_month_key IS NULL) OR ((last_month_key ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'::text) AND (last_month_key >= first_month_key)))),
    CONSTRAINT automated_payroll_standing_additions_reason_check CHECK ((btrim(reason) <> ''::text))
);

ALTER TABLE public.automated_payroll_standing_additions OWNER TO postgres;

--
-- Name: TABLE automated_payroll_standing_additions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.automated_payroll_standing_additions IS 'Incentive or bonus an employee is owed on a fixed cadence (or once). Read only as the RECOMMENDATION for the Part 2 Additions step; HR still confirms, and a value saved on the run draft row wins.';

--
-- Name: COLUMN automated_payroll_standing_additions.every_months; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.automated_payroll_standing_additions.every_months IS 'null = one-off, due only in first_month_key; n = due in first_month_key and every n months after.';

--
