    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT contract_renewal_manager_recommendations_recommendation_check CHECK ((recommendation = ANY (ARRAY['renew'::text, 'do_not_renew'::text])))
);

ALTER TABLE public.contract_renewal_manager_recommendations OWNER TO postgres;

