--
-- Name: TABLE phoenix_crm_rep_entry_days_cache; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_rep_entry_days_cache IS 'Cache of phoenix_crm_rep_entry_days_calc(). Kept current by AFTER triggers on the four Phoenix CRM fact tables and rebuilt by phoenix_crm_rep_entry_days_reconcile() every 5 minutes. _calc() is the truth; this table is only its materialisation.';

--
-- Name: phoenix_crm_team_starts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_team_starts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
