    starts_on date NOT NULL,
    stops_on date,
    started_by text NOT NULL,
    started_by_hr_id text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    stopped_by_hr_id text,
    stopped_at timestamp with time zone,
    note text,
    day_activities_from date,
    CONSTRAINT phoenix_crm_team_starts_saturday CHECK ((EXTRACT(isodow FROM starts_on) = (6)::numeric)),
    CONSTRAINT phoenix_crm_team_starts_started_by CHECK ((started_by = ANY (ARRAY['owner_ruling'::text, 'super_admin'::text]))),
    CONSTRAINT phoenix_crm_team_starts_stop_after_start CHECK (((stops_on IS NULL) OR (stops_on > starts_on))),
    CONSTRAINT phoenix_crm_team_starts_stop_recorded CHECK (((stops_on IS NULL) = (stopped_at IS NULL))),
