ALTER TABLE public.phoenix_crm_team_starts OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_team_starts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_team_starts IS 'Each START of a TEAM (the territories under one district-manager seat, keyed by that seat): the Saturday it is counted from Phoenix CRM instead of iReports360 on every other screen, and the Saturday it stops (owner, 2026-10-02). Delta (1) is seeded from his ruling; every other team only by the Super Admin''s Start on the CRM hub (phoenix_crm_set_team_start, the one writer). crm_visits_unified reads it.';

--
-- Name: COLUMN phoenix_crm_team_starts.day_activities_from; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_team_starts.day_activities_from IS 'From this day a started team''s recorded Phoenix day activities count through crm_visits_unified even before starts_on (never later than it counts anyway). NULL = counted from starts_on only. Cairo and Giza: 2026-10-07, the go-live training day.';

--
-- Name: crm_checkins_unified; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.crm_checkins_unified WITH (security_invoker='true') AS
 SELECT c.id,
    c.crm_checkin_id,
    c.agent_crm_id,
    c.agent_hr_id,
    c.contact_crm_id,
    COALESCE(truth.name, c.contact_name) AS contact_name,
    c.lat,
    c.lon,
    c.address,
    c.check_date,
    c.raw_payload,
    c.synced_at,
    c.created_at,
    c.updated_at,
    'ireports360'::text AS source,
    c.agent_crm_id AS exclusion_crm_id
   FROM (( SELECT x.id,
            x.crm_checkin_id,
            x.agent_crm_id,
            x.agent_hr_id,
            x.contact_crm_id,
            x.contact_name,
            x.lat,
            x.lon,
            x.address,
            x.check_date,
            x.raw_payload,
            x.synced_at,
            x.created_at,
            x.updated_at
           FROM public.ireports360_checkins x
          WHERE ((x.check_date < COALESCE(( SELECT ((k.cutover_date)::timestamp without time zone AT TIME ZONE 'UTC'::text) AS timezone
                   FROM public.crm_cutover k
                  WHERE k.id), 'infinity'::timestamp with time zone)) AND (x.check_date < COALESCE(( SELECT ((((k.vendor_sync_retired_at AT TIME ZONE 'Africa/Cairo'::text))::date)::timestamp without time zone AT TIME ZONE 'UTC'::text) AS timezone
                   FROM public.crm_cutover k
                  WHERE k.id), 'infinity'::timestamp with time zone)) AND ((x.check_date < ( SELECT ((COALESCE(min(LEAST(t.starts_on, COALESCE(t.day_activities_from, t.starts_on))), 'infinity'::date))::timestamp without time zone AT TIME ZONE 'UTC'::text) AS timezone
                   FROM public.phoenix_crm_team_starts t)) OR ((NOT (EXISTS ( SELECT 1
                   FROM public.phoenix_crm_rep_entry_days_cache e
                  WHERE ((e.hr_key = lower(btrim(x.agent_hr_id))) AND (e.entry_day = ((x.check_date AT TIME ZONE 'UTC'::text))::date))))) AND (NOT (EXISTS ( SELECT 1
                   FROM public.phoenix_crm_rep_entry_days_cache e
                  WHERE ((NULLIF(btrim(x.agent_hr_id), ''::text) IS NULL) AND (e.agent_crm_id = x.agent_crm_id) AND (e.entry_day = ((x.check_date AT TIME ZONE 'UTC'::text))::date))))))))) c
     LEFT JOIN public.crm_contact_phoenix_truth truth ON ((truth.contact_crm_id = c.contact_crm_id)))
UNION ALL
 SELECT p.id,
    ('-1'::integer - ((('x'::text || substr(md5((p.id)::text), 1, 13)))::bit(52))::bigint) AS crm_checkin_id,
        CASE
            WHEN (agent.crm_id ~ '^[0-9]+$'::text) THEN (agent.crm_id)::bigint
            ELSE NULL::bigint
        END AS agent_crm_id,
    COALESCE(p.rep_hr_id, p.manager_hr_id) AS agent_hr_id,
    COALESCE(customer.reference_contact_crm_id, customer.own_contact_crm_id) AS contact_crm_id,
    customer.name AS contact_name,
    p.lat,
    p.lon,
    NULL::text AS address,
    ((p.captured_at AT TIME ZONE 'Africa/Cairo'::text) AT TIME ZONE 'UTC'::text) AS check_date,
    NULL::jsonb AS raw_payload,
    p.created_at AS synced_at,
    p.created_at,
    p.created_at AS updated_at,
    'phoenix'::text AS source,
    COALESCE(
        CASE
            WHEN (agent.crm_id ~ '^[0-9]+$'::text) THEN (agent.crm_id)::bigint
            ELSE NULL::bigint
        END, (- (1)::bigint)) AS exclusion_crm_id
   FROM (((public.phoenix_crm_countable_visits p
     JOIN public.phoenix_crm_counted_seat_windows() team(seat_id, starts_on, stops_on) ON (((team.seat_id = p.seat_id) AND (p.visit_date >= team.starts_on) AND ((team.stops_on IS NULL) OR (p.visit_date < team.stops_on)))))
     JOIN public.phoenix_crm_customers customer ON ((customer.id = p.customer_id)))
     LEFT JOIN public.crm_person_by_hr_key_cache agent ON ((agent.hr_key = upper(btrim(COALESCE(p.rep_hr_id, p.manager_hr_id))))))
  WHERE ((NOT p.is_test) AND (p.imported_from_ireports360_at IS NULL) AND (p.lat IS NOT NULL) AND (p.lon IS NOT NULL));

ALTER VIEW public.crm_checkins_unified OWNER TO postgres;

--
-- Name: VIEW crm_checkins_unified; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.crm_checkins_unified IS 'Every GPS check-in the read door serves: iReports360 check-ins, and — for a team in phoenix_crm_team_starts, within its start — each countable Phoenix CRM visit that carries a position, as that day''s check-in (time and position only), INSTEAD of its people''s iReports360 check-ins (owner, 2026-10-02). The app reads the Phoenix rows on SFE and manager screens only. contact_crm_id is the customer''s vendor id, or the id he owns in the reserved range when he was born in Phoenix CRM — the same expression as the visit and plan doors. See supabase/migrations/20261007193000_crm_doors_carry_every_person_and_every_customer.sql.';

--
-- Name: crm_contact_assignments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_contact_assignments (
    id bigint NOT NULL,
    contact_crm_id bigint NOT NULL,
    agent_crm_id bigint,
    agent_hr_id text,
    list_type text NOT NULL,
    grade text,
    effective_from date NOT NULL,
    effective_to date,
    last_seen_on date NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source text DEFAULT 'ireports360'::text NOT NULL,
    CONSTRAINT crm_contact_assignments_list_type CHECK ((list_type = ANY (ARRAY['PM'::text, 'AM'::text, 'Pharmacy'::text]))),
    CONSTRAINT crm_contact_assignments_period CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT crm_contact_assignments_source CHECK ((source = ANY (ARRAY['ireports360'::text, 'phoenix'::text, 'phoenix_crm'::text]))),
    CONSTRAINT crm_contact_assignments_source_identity CHECK (
CASE source
    WHEN 'ireports360'::text THEN (agent_crm_id IS NOT NULL)
    WHEN 'phoenix'::text THEN ((agent_hr_id IS NOT NULL) AND (btrim(agent_hr_id) <> ''::text))
    WHEN 'phoenix_crm'::text THEN ((agent_hr_id IS NOT NULL) AND (btrim(agent_hr_id) <> ''::text))
    ELSE false
END)
);

ALTER TABLE public.crm_contact_assignments OWNER TO postgres;

--
-- Name: TABLE crm_contact_assignments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.crm_contact_assignments IS 'Dated contact-list membership: one row per (contact, agent, list, rep, grade) period. effective_to is null while the contact is on that list today. Written only by crm_contact_master_refresh(); never delete a closed row, it is the only list history Phoenix has.';

--
-- Name: COLUMN crm_contact_assignments.source; Type: COMMENT; Schema: public; Owner: postgres
