--
-- Name: crm_contact_list_changes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_contact_list_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rep_hr_id text NOT NULL,
    action text NOT NULL,
    list_type text NOT NULL,
    contact_crm_id bigint,
    new_contact_name text,
    new_contact_speciality text,
    new_contact_address text,
    grade text,
    reason text NOT NULL,
    requested_by text NOT NULL,
    manager_hr_id text,
    direct boolean DEFAULT false NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    decided_by text,
    decided_at timestamp with time zone,
    decision_note text,
    applied_at timestamp with time zone,
    applied_contact_crm_id bigint,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_contact_list_changes_action CHECK ((action = ANY (ARRAY['add'::text, 'remove'::text, 'regrade'::text]))),
    CONSTRAINT crm_contact_list_changes_grade CHECK (((grade IS NULL) OR (grade = ANY (ARRAY['A'::text, 'B'::text, 'C'::text])))),
    CONSTRAINT crm_contact_list_changes_list_type CHECK ((list_type = ANY (ARRAY['AM'::text, 'PM'::text]))),
    CONSTRAINT crm_contact_list_changes_reason CHECK (((btrim(reason) <> ''::text) AND (char_length(reason) <= 1000))),
    CONSTRAINT crm_contact_list_changes_routing CHECK (
CASE
    WHEN direct THEN (manager_hr_id IS NULL)
    ELSE ((manager_hr_id IS NOT NULL) AND (requested_by = rep_hr_id) AND (manager_hr_id <> rep_hr_id))
END),
    CONSTRAINT crm_contact_list_changes_shape CHECK (
CASE action
    WHEN 'add'::text THEN ((grade IS NOT NULL) AND (((contact_crm_id IS NOT NULL) AND (new_contact_name IS NULL) AND (new_contact_speciality IS NULL) AND (new_contact_address IS NULL)) OR ((contact_crm_id IS NULL) AND (new_contact_name IS NOT NULL) AND (btrim(new_contact_name) <> ''::text) AND (char_length(new_contact_name) <= 200) AND (new_contact_speciality IS NOT NULL) AND (btrim(new_contact_speciality) <> ''::text) AND ((new_contact_address IS NULL) OR (char_length(new_contact_address) <= 500)))))
    WHEN 'remove'::text THEN ((contact_crm_id IS NOT NULL) AND (grade IS NULL) AND (new_contact_name IS NULL) AND (new_contact_speciality IS NULL) AND (new_contact_address IS NULL))
    WHEN 'regrade'::text THEN ((contact_crm_id IS NOT NULL) AND (grade IS NOT NULL) AND (new_contact_name IS NULL) AND (new_contact_speciality IS NULL) AND (new_contact_address IS NULL))
    ELSE false
END),
    CONSTRAINT crm_contact_list_changes_status CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text]))),
    CONSTRAINT crm_contact_list_changes_workflow CHECK (
CASE status
    WHEN 'pending'::text THEN ((decided_by IS NULL) AND (decided_at IS NULL) AND (decision_note IS NULL) AND (applied_at IS NULL) AND (cancelled_at IS NULL))
    WHEN 'approved'::text THEN ((decided_at IS NOT NULL) AND (applied_at IS NOT NULL) AND (cancelled_at IS NULL) AND (decided_by =
    CASE
        WHEN direct THEN requested_by
        ELSE manager_hr_id
    END))
    WHEN 'rejected'::text THEN ((NOT direct) AND (decided_by = manager_hr_id) AND (decided_at IS NOT NULL) AND (decision_note IS NOT NULL) AND (btrim(decision_note) <> ''::text) AND (applied_at IS NULL) AND (cancelled_at IS NULL))
    WHEN 'cancelled'::text THEN ((cancelled_at IS NOT NULL) AND (decided_by IS NULL) AND (applied_at IS NULL))
    ELSE false
END)
);

ALTER TABLE public.crm_contact_list_changes OWNER TO postgres;

--
-- Name: TABLE crm_contact_list_changes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.crm_contact_list_changes IS 'A change to one rep''s AM or PM doctor list (CRM phase 7): the rep asks and his stored manager decides, or the SFE Manager or administrator applies it directly. Applied only by crm_contact_list_change_apply(), from the CRM cutover date. Never decided by the system.';

