    last_visited_on date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_contacts_brick_matches_status CHECK (((brick_id IS NOT NULL) = (brick_status = ANY (ARRAY['customer'::text, 'region'::text])))),
    CONSTRAINT crm_contacts_brick_status CHECK ((brick_status = ANY (ARRAY['customer'::text, 'region'::text, 'pending'::text]))),
    CONSTRAINT crm_contacts_real_contact CHECK (((contact_crm_id > 0) AND (contact_crm_id <> 100000))),
    CONSTRAINT crm_contacts_source CHECK ((source = ANY (ARRAY['list'::text, 'visit'::text, 'plan'::text, 'phoenix'::text])))
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_vacuum_threshold='1000', autovacuum_analyze_scale_factor='0.05', autovacuum_analyze_threshold='1000');

