--
-- Name: crm_native_visit_vacation_day_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.crm_native_visit_vacation_day_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    hr_id text NOT NULL,
    visit_date date NOT NULL,
    reason text NOT NULL,
    line_name text,
    manager_hr_id text NOT NULL,
    manager_decision text DEFAULT 'pending'::text NOT NULL,
    manager_decided_by text,
    manager_decided_at timestamp with time zone,
    manager_note text,
    hr_decision text DEFAULT 'pending'::text NOT NULL,
    hr_decided_by text,
    hr_decided_at timestamp with time zone,
    hr_note text,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT crm_native_visit_vacation_day_requests_hr_decision CHECK ((hr_decision = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT crm_native_visit_vacation_day_requests_hr_workflow CHECK (
CASE hr_decision
    WHEN 'pending'::text THEN ((hr_decided_by IS NULL) AND (hr_decided_at IS NULL) AND (hr_note IS NULL))
    WHEN 'approved'::text THEN ((hr_decided_by IS NOT NULL) AND (hr_decided_at IS NOT NULL) AND (hr_decided_by <> hr_id) AND (hr_decided_by <> manager_hr_id))
    WHEN 'rejected'::text THEN ((hr_decided_by IS NOT NULL) AND (hr_decided_at IS NOT NULL) AND (hr_decided_by <> hr_id) AND (hr_decided_by <> manager_hr_id) AND (hr_note IS NOT NULL) AND (btrim(hr_note) <> ''::text))
    ELSE false
END),
    CONSTRAINT crm_native_visit_vacation_day_requests_manager_decision CHECK ((manager_decision = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT crm_native_visit_vacation_day_requests_manager_workflow CHECK (
CASE manager_decision
    WHEN 'pending'::text THEN ((manager_decided_by IS NULL) AND (manager_decided_at IS NULL) AND (manager_note IS NULL))
    WHEN 'approved'::text THEN ((manager_decided_by = manager_hr_id) AND (manager_decided_at IS NOT NULL))
    WHEN 'rejected'::text THEN ((manager_decided_by = manager_hr_id) AND (manager_decided_at IS NOT NULL) AND (manager_note IS NOT NULL) AND (btrim(manager_note) <> ''::text))
    ELSE false
END),
    CONSTRAINT crm_native_visit_vacation_day_requests_not_own_manager CHECK ((manager_hr_id <> hr_id)),
    CONSTRAINT crm_native_visit_vacation_day_requests_reason CHECK (((btrim(reason) <> ''::text) AND (char_length(reason) <= 1000)))
);

ALTER TABLE public.crm_native_visit_vacation_day_requests OWNER TO postgres;

