--
-- Name: TABLE ireports360_plan_entries; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ireports360_plan_entries IS 'Mirror of the iReports360 weekly/monthly PLAN endpoints -- one row per planned call (vendor `id`). This is the ASSIGNED doctor list per rep, the counterpart to ireports360_visits (what was actually done). Not related to Phoenix''s own weekly-planning module (src/lib/weekly-planning), which is a different thing with a similar name.';

--
-- Name: phoenix_crm_plan_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_plan_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    plan_date date NOT NULL,
    customer_id uuid NOT NULL,
    place_id uuid,
    list_type text NOT NULL,
    receives boolean NOT NULL,
    start_minute integer,
    exception_type text,
    exception_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_plan_items_exception CHECK (((receives AND (exception_type IS NULL) AND (exception_note IS NULL)) OR (NOT receives))),
    CONSTRAINT phoenix_crm_plan_items_exception_type CHECK (((exception_type IS NULL) OR (exception_type = ANY (ARRAY['another_place'::text, 'by_appointment'::text, 'timings_changed'::text, 'other'::text])))),
    CONSTRAINT phoenix_crm_plan_items_list_type CHECK ((list_type = ANY (ARRAY['AM'::text, 'PM'::text]))),
    CONSTRAINT phoenix_crm_plan_items_note CHECK (((exception_note IS NULL) OR (char_length(exception_note) <= 300))),
    CONSTRAINT phoenix_crm_plan_items_other_needs_note CHECK (((exception_type IS DISTINCT FROM 'other'::text) OR (exception_note IS NOT NULL))),
    CONSTRAINT phoenix_crm_plan_items_start CHECK (((start_minute IS NULL) OR ((start_minute >= 0) AND (start_minute <= 1439))))
)
WITH (autovacuum_enabled='true');

ALTER TABLE public.phoenix_crm_plan_items OWNER TO postgres;

--
-- Name: CONSTRAINT phoenix_crm_plan_items_list_type ON phoenix_crm_plan_items; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT phoenix_crm_plan_items_list_type ON public.phoenix_crm_plan_items IS 'AM and PM ONLY, deliberately: the owner ruled on 2026-10-02 that a pharmacy is never planned. Do not widen this to Pharmacy — it is the database''s own half of that rule.';

--
-- Name: phoenix_crm_plans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seat_id text NOT NULL,
    line_code text NOT NULL,
    week_start date NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    submitted_at timestamp with time zone,
    submitted_by_hr_id text,
    decided_at timestamp with time zone,
    decided_by_hr_id text,
    decided_by_role text,
    decision_note text,
    created_by_hr_id text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    due_on date,
    submitted_late boolean DEFAULT false NOT NULL,
    submitted_via text,
    returned_day date,
    CONSTRAINT phoenix_crm_plans_decision_note CHECK (((decision_note IS NULL) OR (char_length(decision_note) <= 500))),
    CONSTRAINT phoenix_crm_plans_returned_day CHECK (((returned_day IS NULL) OR ((status = 'returned'::text) AND ((returned_day >= week_start) AND (returned_day <= (week_start + 5)))))),
    CONSTRAINT phoenix_crm_plans_saturday CHECK ((EXTRACT(isodow FROM week_start) = (6)::numeric)),
    CONSTRAINT phoenix_crm_plans_status CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'returned'::text]))),
    CONSTRAINT phoenix_crm_plans_submitted_via CHECK (((submitted_via IS NULL) OR (submitted_via = ANY (ARRAY['week'::text, 'month'::text])))),
    CONSTRAINT phoenix_crm_plans_version CHECK ((version >= 1))
)
WITH (autovacuum_enabled='true');

ALTER TABLE public.phoenix_crm_plans OWNER TO postgres;

--
-- Name: COLUMN phoenix_crm_plans.due_on; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_plans.due_on IS 'The Thursday before the week (week_start − 2): when a week sent on its own is due (owner, 2026-09-29). A late week is accepted and stamped, never refused.';

--
-- Name: COLUMN phoenix_crm_plans.submitted_via; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_plans.submitted_via IS 'How the week was last sent: week (alone — judged against due_on) or month (with its month — judged against the month''s own due date).';

--
-- Name: COLUMN phoenix_crm_plans.returned_day; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_plans.returned_day IS 'The ONE day of this week a reviewer returned to the rep (owner, 2026-10-02: "Only that day" reopens). Null for a week returned whole and for every week that is not returned; cleared when the rep sends the week again.';

--
-- Name: crm_plan_entries_unified; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.crm_plan_entries_unified WITH (security_invoker='true') AS
 WITH reps AS MATERIALIZED (
         SELECT t.seat_id,
            t.hr_id,
            t.hr_key,
            t.agent_crm_id,
            t.counted_from,
            t.counted_until,
            row_number() OVER () AS rep_row
           FROM public.phoenix_crm_started_team_reps() t(seat_id, hr_id, hr_key, agent_crm_id, counted_from, counted_until)
        )
 SELECT pe.crm_plan_entry_id,
    pe.plan_kind,
    pe.crm_plan_id,
    pe.plan_date,
    pe.plan_month,
    pe.plan_year,
    pe.plan_frequency,
    pe.agent_crm_id,
    pe.agent_hr_id,
    pe.contact_crm_id,
    COALESCE(truth.name, pe.contact_name) AS contact_name,
    pe.contact_grade,
    pe.crm_region_name,
    COALESCE(truth.speciality, pe.speciality) AS speciality,
    pe.ampm,
    pe.start_am,
    pe.start_pm,
    pe.plan_status,
    pe.raw_payload,
    pe.synced_at,
    pe.created_at,
    pe.updated_at,
    'ireports360'::text AS source
   FROM (public.ireports360_plan_entries pe
     LEFT JOIN public.crm_contact_phoenix_truth truth ON ((truth.contact_crm_id = pe.contact_crm_id)))
  WHERE (((pe.plan_date IS NULL) OR (pe.plan_date < COALESCE(( SELECT c.cutover_date
           FROM public.crm_cutover c
          WHERE c.id), 'infinity'::date))) AND (NOT (EXISTS ( SELECT 1
           FROM reps r
          WHERE ((r.hr_key = lower(btrim(pe.agent_hr_id))) AND (pe.plan_date >= r.counted_from) AND ((r.counted_until IS NULL) OR (pe.plan_date < r.counted_until)))))) AND (NOT (EXISTS ( SELECT 1
           FROM reps r
          WHERE ((NULLIF(btrim(pe.agent_hr_id), ''::text) IS NULL) AND (r.agent_crm_id = pe.agent_crm_id) AND (pe.plan_date >= r.counted_from) AND ((r.counted_until IS NULL) OR (pe.plan_date < r.counted_until)))))))
UNION ALL
 SELECT ('-1'::integer - ((('x'::text || substr(md5((i.id)::text), 1, 13)))::bit(52))::bigint) AS crm_plan_entry_id,
    'weekly'::text AS plan_kind,
    ('-1'::integer - ((('x'::text || substr(md5((pd.plan_id)::text), 1, 8)))::bit(30))::integer) AS crm_plan_id,
    pd.plan_date,
    (EXTRACT(month FROM pd.plan_date))::smallint AS plan_month,
    (EXTRACT(year FROM pd.plan_date))::smallint AS plan_year,
    NULL::smallint AS plan_frequency,
    pd.agent_crm_id,
    pd.hr_id AS agent_hr_id,
    COALESCE(customer.reference_contact_crm_id, customer.own_contact_crm_id) AS contact_crm_id,
    customer.name AS contact_name,
    customer.grade AS contact_grade,
    NULL::text AS crm_region_name,
    customer.speciality,
    i.list_type AS ampm,
    NULL::text AS start_am,
    NULL::text AS start_pm,
    (
        CASE
            WHEN (pd.status_now = 'approved'::text) THEN 1
            ELSE 0
        END)::smallint AS plan_status,
    NULL::jsonb AS raw_payload,
    GREATEST(pd.plan_updated_at, i.updated_at) AS synced_at,
    i.created_at,
    i.updated_at,
    'phoenix'::text AS source
   FROM ((( SELECT x.plan_id,
            x.plan_date,
            r.agent_crm_id,
            r.hr_id,
            p.updated_at AS plan_updated_at,
            public.phoenix_crm_plan_day_status(x.plan_id, min(x.plan_date), now()) AS status_now,
            array_agg(x.id) AS item_ids,
            array_agg(x.customer_id) AS customer_ids,
            array_agg(x.list_type) AS list_types,
            array_agg(x.created_at) AS created_ats,
            array_agg(x.updated_at) AS updated_ats
           FROM ((public.phoenix_crm_plan_items x
             JOIN public.phoenix_crm_plans p ON (((p.id = x.plan_id) AND (NOT p.is_test))))
             JOIN reps r ON (((r.seat_id = p.seat_id) AND (x.plan_date >= r.counted_from) AND ((r.counted_until IS NULL) OR (x.plan_date < r.counted_until)))))
          GROUP BY x.plan_id, x.plan_date, r.rep_row, r.agent_crm_id, r.hr_id, p.updated_at
         HAVING (public.phoenix_crm_plan_day_status(x.plan_id, min(x.plan_date), LEAST(now(), (((min(x.plan_date) + 1))::timestamp without time zone AT TIME ZONE 'Africa/Cairo'::text))) IS NOT NULL)) pd
     CROSS JOIN LATERAL UNNEST(pd.item_ids, pd.customer_ids, pd.list_types, pd.created_ats, pd.updated_ats) i(id, customer_id, list_type, created_at, updated_at))
     JOIN ( SELECT c.id,
            c.reference_contact_crm_id,
            c.own_contact_crm_id,
            c.name,
            c.grade,
            c.speciality
           FROM public.phoenix_crm_customers c
         OFFSET 0) customer ON ((customer.id = i.customer_id)));

ALTER VIEW public.crm_plan_entries_unified OWNER TO postgres;

--
-- Name: VIEW crm_plan_entries_unified; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.crm_plan_entries_unified IS 'Every planned call the plan door serves: iReports360 plan entries, and — for a team in phoenix_crm_team_starts, within its start — that team''s Phoenix weekly plans, day by day as sent, INSTEAD of its reps'' iReports360 entries (owner, 2026-10-02). Phoenix rows: real only, source ''phoenix'', negative ids, plan_status 1 when the week is approved now. contact_crm_id is the customer''s vendor id, or the id he owns in the reserved range when he was born in Phoenix CRM — the same expression as the visit and check-in doors, because a visit with an id against a plan without one reads MISSED. See supabase/migrations/20261007193000_crm_doors_carry_every_person_and_every_customer.sql.';

--
-- Name: ireports360_visits; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.ireports360_visits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    crm_visit_id bigint NOT NULL,
    visit_date date NOT NULL,
    agent_crm_id bigint NOT NULL,
    agent_name text,
    agent_hr_id text,
    double_crm_id bigint,
    double_name text,
    double_hr_id text,
    contact_crm_id bigint,
    contact_name text,
    customer_name text,
    comment text,
    visit_type integer,
    visit_type_description text,
    call_type integer,
    ampm text,
    attendance integer,
    crm_save_date timestamp with time zone,
    raw_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    synced_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    visit_date_time timestamp with time zone,
    crm_region_id integer,
    crm_region_name text,
    speciality text,
    crm_contact_grade text
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_vacuum_threshold='1000', autovacuum_analyze_scale_factor='0.05', autovacuum_analyze_threshold='1000');

ALTER TABLE public.ireports360_visits OWNER TO postgres;

--
-- Name: TABLE ireports360_visits; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ireports360_visits IS 'Full mirror of every iReports360 CRM visit record (solo, campaign, double, leave/vacation), synced automatically. crm_visit_id is the CRM''s own stable id — upserts on it make re-syncing overlapping date ranges idempotent.';

--
-- Name: COLUMN ireports360_visits.agent_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits.agent_hr_id IS 'Phoenix employee HR ID mapped from agent_crm_id via employees.crm_id, if a match exists. Null when unmapped.';

--
-- Name: COLUMN ireports360_visits.double_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits.double_hr_id IS 'Phoenix employee HR ID mapped from double_crm_id via employees.crm_id, if a match exists. Null when there is no double visitor (double_crm_id is null/0) or the CRM id is unmapped.';

--
-- Name: COLUMN ireports360_visits.visit_date_time; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits.visit_date_time IS 'Full visitDate timestamp from iReports360 (visit_date is the date-only slice used for range filtering). Used to pick the nearest GPS check-in by time, not just by calendar day.';

--
-- Name: COLUMN ireports360_visits.crm_region_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits.crm_region_id IS 'iReports360''s own numeric region/locality id for the visited contact (vendor field: regionID). Finer-grained than Phoenix''s au.regions/canonical areas -- one Phoenix brick or area typically covers several distinct crm_region_id values. Null for non-customer visit types (campaign/meeting/leave), which carry no real contact.';

--
-- Name: COLUMN ireports360_visits.crm_region_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits.crm_region_name IS 'iReports360''s display name for crm_region_id (vendor field: region), e.g. "Dokki", "Nasr City".';

--
-- Name: COLUMN ireports360_visits.speciality; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits.speciality IS 'The visited contact''s medical specialty/type from iReports360 (e.g. "Internal Medicine", "Pediatrics", "Hospital"). Null for non-customer visit types.';

--
-- Name: COLUMN ireports360_visits.crm_contact_grade; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits.crm_contact_grade IS 'The visited contact''s commercial potential grade from iReports360 (vendor field: contactGrade), normalized to uppercase/trimmed (A+, A, B, C -- A is highest potential, C lowest). The vendor sends inconsistent casing/whitespace ("b", " A", "B   "); the sync engine normalizes before storing, so this column is always clean. Null for non-customer visit types (campaign/meeting/leave), which carry no real contact.';

--
-- Name: phoenix_crm_day_activities; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_day_activities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seat_id text NOT NULL,
    line_code text,
    rep_hr_id text,
    entered_by_hr_id text NOT NULL,
    activity_date date NOT NULL,
    activity_type text NOT NULL,
    half_day boolean DEFAULT false NOT NULL,
    note text,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_day_activities_note CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT phoenix_crm_day_activities_type CHECK ((activity_type = ANY (ARRAY['meeting'::text, 'training'::text, 'conference'::text, 'admin_work'::text, 'travel'::text, 'health_day'::text, 'sales_day'::text, 'rtd'::text, 'group_meeting'::text, 'interviews'::text])))
);

ALTER TABLE public.phoenix_crm_day_activities OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_day_activities; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_day_activities IS 'A working day that was not a call (owner, 2026-09-26). A RECORD ONLY: it changes no call rate, no coverage and no plan-against-actual. Leave is deliberately absent — HR''s vacation module is the only leave record.';

--
-- Name: COLUMN phoenix_crm_day_activities.half_day; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_day_activities.half_day IS 'He was in the field for part of the day. The visits he entered stand on their own; this does not scale anything.';

--
-- Name: phoenix_crm_imported_visit_sources; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_imported_visit_sources (
    crm_visit_id bigint NOT NULL,
    visit_id uuid NOT NULL,
    imported_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.phoenix_crm_imported_visit_sources OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_imported_visit_sources; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_imported_visit_sources IS 'iReports360 crm_visit_id -> the phoenix_crm_visits row the history import wrote for it. Several old ids can map to one visit (two old visits to one doctor on one day are one Phoenix row). Read by the import (a second run writes nothing) and by phx_crm_contact_visit_history (a copied visit is not counted twice). See 20261029212200_phoenix_crm_imports_ireports360_history.sql.';

--
-- Name: phoenix_crm_ireports360_checkin_matches; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_ireports360_checkin_matches (
    crm_visit_id bigint NOT NULL,
    crm_checkin_id bigint NOT NULL,
    lat double precision NOT NULL,
    lon double precision NOT NULL,
    check_date timestamp with time zone NOT NULL,
    matched_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_ireports360_checkin_matches_box CHECK ((((lat >= (21.5)::double precision) AND (lat <= (32)::double precision)) AND ((lon >= (24)::double precision) AND (lon <= (37.5)::double precision))))
);

ALTER TABLE public.phoenix_crm_ireports360_checkin_matches OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_ireports360_checkin_matches; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_ireports360_checkin_matches IS 'Each iReports360 regular visit that had a check-in location: the agent checked in at that contact on the visit''s day (the vendor wall clock), inside Egypt''s box; the check-in nearest the visit''s own time. The one answer the conversion, the importer and the archive read (owner, 2026-11-07).';

--
-- Name: phoenix_crm_visit_archive; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_visit_archive (
    crm_visit_id bigint NOT NULL,
    visit_date date NOT NULL,
    agent_crm_id bigint,
    agent_hr_id text,
    agent_name text,
    contact_crm_id bigint,
    customer_name text,
    visit_type integer NOT NULL,
    reason text NOT NULL,
    visit_id uuid,
    seat_id text,
    line_code text,
    archived_at timestamp with time zone DEFAULT now() NOT NULL,
    distance_meters integer,
    checkin_lat double precision,
    checkin_lon double precision,
    place_id uuid,
    place_lat double precision,
    place_lon double precision,
    CONSTRAINT phoenix_crm_visit_archive_campaign_wins CHECK (((visit_type = '-8'::integer) = (reason = 'campaign'::text))),
    CONSTRAINT phoenix_crm_visit_archive_far_measured CHECK (((reason = 'far'::text) = (distance_meters IS NOT NULL))),
    CONSTRAINT phoenix_crm_visit_archive_reason CHECK ((reason = ANY (ARRAY['campaign'::text, 'no_checkin_location'::text, 'far'::text]))),
    CONSTRAINT phoenix_crm_visit_archive_type CHECK ((visit_type = ANY (ARRAY[0, '-8'::integer])))
);

ALTER TABLE public.phoenix_crm_visit_archive OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_visit_archive; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_visit_archive IS 'The visits archive (owner, 2026-11-07): every retired iReports360 visit — each campaign visit, and each regular visit with no check-in location — copied into Phoenix or not. Counted in no visit figure and no KPI; read by the admin Visits archive screen only.';

--
-- Name: COLUMN phoenix_crm_visit_archive.distance_meters; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_visit_archive.distance_meters IS 'A far visit (reason far): metres from its check-in to the validated place it was measured against, more than 500 m. Null for every other reason.';

--
-- Name: phoenix_crm_visit_companions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_visit_companions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    visit_id uuid,
    manager_visit_id uuid,
    hr_id text NOT NULL,
    side text NOT NULL,
    "position" smallint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_visit_companions_hr_id CHECK ((((char_length(hr_id) >= 1) AND (char_length(hr_id) <= 40)) AND (hr_id = upper(btrim(hr_id))))),
    CONSTRAINT phoenix_crm_visit_companions_one_visit CHECK (((visit_id IS NULL) <> (manager_visit_id IS NULL))),
    CONSTRAINT phoenix_crm_visit_companions_position CHECK ((("position" >= 0) AND ("position" < 12))),
    CONSTRAINT phoenix_crm_visit_companions_side CHECK ((side = ANY (ARRAY['manager'::text, 'product'::text])))
);

ALTER TABLE public.phoenix_crm_visit_companions OWNER TO postgres;

--
-- Name: crm_visits_unified; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.crm_visits_unified WITH (security_invoker='true') AS
 SELECT v.id,
    v.crm_visit_id,
    v.visit_date,
    v.agent_crm_id,
        CASE
            WHEN (agent_person.full_name_nz IS NOT NULL) THEN concat_ws(' '::text, agent_person.full_name_nz, "substring"(v.agent_name, '(\([^()]*\))\s*$'::text))
            ELSE v.agent_name
        END AS agent_name,
    v.agent_hr_id,
    v.double_crm_id,
        CASE
            WHEN (double_person.full_name_nz IS NOT NULL) THEN concat_ws(' '::text, double_person.full_name_nz, "substring"(v.double_name, '(\([^()]*\))\s*$'::text))
            ELSE v.double_name
        END AS double_name,
    v.double_hr_id,
    v.contact_crm_id,
    COALESCE(truth.name, v.contact_name) AS contact_name,
    v.customer_name,
    v.comment,
    v.visit_type,
    v.visit_type_description,
    v.call_type,
    v.ampm,
    v.attendance,
    v.crm_save_date,
    v.raw_payload,
    v.synced_at,
    v.created_at,
    v.updated_at,
    v.visit_date_time,
    v.crm_region_id,
    v.crm_region_name,
    COALESCE(truth.speciality, v.speciality) AS speciality,
    v.crm_contact_grade,
    'ireports360'::text AS source,
    v.agent_crm_id AS exclusion_crm_id,
    NULL::boolean AS phoenix_customer_validated,
    NULL::bigint AS double2_crm_id,
    NULL::text AS double2_name,
    NULL::text AS double2_hr_id,
    NULL::text AS visit_kind,
    NULL::text AS entered_by_hr_id,
    NULL::text[] AS products,
    NULL::jsonb AS samples_given,
    NULL::jsonb AS product_availability,
    NULL::text AS objection,
    NULL::text AS objection_note,
    NULL::text AS next_step,
    NULL::date AS next_step_on,
    NULL::text AS visit_pharmacy_name,
    NULL::boolean AS is_unplanned,
    NULL::text AS unplanned_kind,
    NULL::text AS photo_path,
    NULL::text AS voice_note_path,
    NULL::integer AS voice_note_seconds,
    NULL::double precision AS lat,
    NULL::double precision AS lon,
    NULL::numeric AS accuracy_meters,
    NULL::integer AS distance_meters,
    NULL::text AS location_flag,
    NULL::double precision AS photo_lat,
    NULL::double precision AS photo_lon,
    NULL::numeric AS photo_accuracy_meters,
    NULL::integer AS dwell_seconds,
    NULL::integer AS form_open_seconds,
    NULL::text AS capture_source,
    NULL::integer AS offline_seconds,
    NULL::integer AS device_skew_minutes,
    NULL::timestamp with time zone AS phoenix_synced_at,
    NULL::text[] AS companion_hr_ids,
    ((v.visit_type IS DISTINCT FROM '-8'::integer) AND (NOT (EXISTS ( SELECT 1
           FROM public.phoenix_crm_visit_archive a
          WHERE (a.crm_visit_id = v.crm_visit_id)))) AND (NOT (EXISTS ( SELECT 1
           FROM (public.phoenix_crm_imported_visit_sources s
             JOIN public.phoenix_crm_visits pv ON ((pv.id = s.visit_id)))
          WHERE ((s.crm_visit_id = v.crm_visit_id) AND (NOT ((pv.archived_at IS NULL) AND (pv.ireports360_checkin_id IS NULL))) AND (NOT (pv.ireports360_kpi_counted AND (v.crm_visit_id = ( SELECT min(s2.crm_visit_id) AS min
                   FROM (public.phoenix_crm_imported_visit_sources s2
                     JOIN public.phoenix_crm_ireports360_checkin_matches m2 ON ((m2.crm_visit_id = s2.crm_visit_id)))
                  WHERE ((s2.visit_id = pv.id) AND (m2.crm_checkin_id = pv.ireports360_checkin_id))))))))))) AS counts_in_kpi
   FROM (((( SELECT x.id,
            x.crm_visit_id,
            x.visit_date,
            x.agent_crm_id,
            x.agent_name,
            x.agent_hr_id,
            x.double_crm_id,
            x.double_name,
            x.double_hr_id,
            x.contact_crm_id,
            x.contact_name,
            x.customer_name,
            x.comment,
            x.visit_type,
            x.visit_type_description,
            x.call_type,
            x.ampm,
            x.attendance,
            x.crm_save_date,
            x.raw_payload,
            x.synced_at,
            x.created_at,
            x.updated_at,
            x.visit_date_time,
            x.crm_region_id,
            x.crm_region_name,
            x.speciality,
            x.crm_contact_grade
           FROM public.ireports360_visits x
          WHERE ((x.visit_date < COALESCE(( SELECT c.cutover_date
                   FROM public.crm_cutover c
                  WHERE c.id), 'infinity'::date)) AND (x.visit_date < COALESCE(( SELECT ((c.vendor_sync_retired_at AT TIME ZONE 'Africa/Cairo'::text))::date AS timezone
                   FROM public.crm_cutover c
                  WHERE c.id), 'infinity'::date)) AND ((x.visit_date < ( SELECT COALESCE(min(LEAST(t.starts_on, COALESCE(t.day_activities_from, t.starts_on))), 'infinity'::date) AS "coalesce"
                   FROM public.phoenix_crm_team_starts t)) OR ((NOT (EXISTS ( SELECT 1
                   FROM public.phoenix_crm_rep_entry_days_cache e
                  WHERE ((e.hr_key = lower(btrim(x.agent_hr_id))) AND (e.entry_day = x.visit_date))))) AND (NOT (EXISTS ( SELECT 1
                   FROM public.phoenix_crm_rep_entry_days_cache e
                  WHERE ((NULLIF(btrim(x.agent_hr_id), ''::text) IS NULL) AND (e.agent_crm_id = x.agent_crm_id) AND (e.entry_day = x.visit_date))))))))) v
     LEFT JOIN public.crm_contact_phoenix_truth truth ON ((truth.contact_crm_id = v.contact_crm_id)))
     LEFT JOIN public.crm_person_by_hr_key_cache agent_person ON ((agent_person.hr_key = upper(btrim(v.agent_hr_id)))))
     LEFT JOIN public.crm_person_by_hr_key_cache double_person ON ((double_person.hr_key = upper(btrim(v.double_hr_id)))))
UNION ALL
 SELECT p.id,
    ('-1'::integer - ((('x'::text || substr(md5((p.id)::text), 1, 13)))::bit(52))::bigint) AS crm_visit_id,
    p.visit_date,
        CASE
            WHEN (agent.crm_id ~ '^[0-9]+$'::text) THEN (agent.crm_id)::bigint
            ELSE NULL::bigint
        END AS agent_crm_id,
    agent.full_name AS agent_name,
    COALESCE(p.rep_hr_id, p.manager_hr_id) AS agent_hr_id,
        CASE
            WHEN ((p.rep_hr_id IS NOT NULL) AND (partner1.crm_id ~ '^[0-9]+$'::text)) THEN (partner1.crm_id)::bigint
            ELSE NULL::bigint
        END AS double_crm_id,
        CASE
            WHEN (p.rep_hr_id IS NOT NULL) THEN partner1.full_name
            ELSE NULL::text
        END AS double_name,
        CASE
            WHEN (p.rep_hr_id IS NOT NULL) THEN COALESCE(p.manager_hr_id, p.product_manager_hr_id, p.senior_hr_id)
            ELSE NULL::text
        END AS double_hr_id,
    COALESCE(customer.reference_contact_crm_id, customer.own_contact_crm_id) AS contact_crm_id,
    customer.name AS contact_name,
    NULL::text AS customer_name,
    p.comment,
    0 AS visit_type,
    'Regular Visit'::text AS visit_type_description,
    NULL::integer AS call_type,
    p.list_type AS ampm,
    NULL::integer AS attendance,
    ((p.captured_at AT TIME ZONE 'Africa/Cairo'::text) AT TIME ZONE 'UTC'::text) AS crm_save_date,
    NULL::jsonb AS raw_payload,
    p.created_at AS synced_at,
    p.created_at,
    p.created_at AS updated_at,
    ((p.captured_at AT TIME ZONE 'Africa/Cairo'::text) AT TIME ZONE 'UTC'::text) AS visit_date_time,
    NULL::integer AS crm_region_id,
    NULL::text AS crm_region_name,
    customer.speciality,
    customer.grade AS crm_contact_grade,
    'phoenix'::text AS source,
    COALESCE(
        CASE
            WHEN (agent.crm_id ~ '^[0-9]+$'::text) THEN (agent.crm_id)::bigint
            ELSE NULL::bigint
        END, (- (1)::bigint)) AS exclusion_crm_id,
    p.customer_validated AS phoenix_customer_validated,
        CASE
            WHEN ((p.rep_hr_id IS NOT NULL) AND (partner2.crm_id ~ '^[0-9]+$'::text)) THEN (partner2.crm_id)::bigint
            ELSE NULL::bigint
        END AS double2_crm_id,
        CASE
            WHEN (p.rep_hr_id IS NOT NULL) THEN partner2.full_name
            ELSE NULL::text
        END AS double2_name,
        CASE
            WHEN (p.rep_hr_id IS NOT NULL) THEN
            CASE
                WHEN (p.manager_hr_id IS NOT NULL) THEN COALESCE(p.senior_hr_id, p.product_manager_hr_id)
                WHEN (p.product_manager_hr_id IS NOT NULL) THEN p.senior_hr_id
                ELSE NULL::text
            END
            ELSE NULL::text
        END AS double2_hr_id,
    p.kind AS visit_kind,
    p.entered_by_hr_id,
    p.products,
    p.samples_given,
    p.product_availability,
    p.objection,
    p.objection_note,
    p.next_step,
    p.next_step_on,
    p.pharmacy_name AS visit_pharmacy_name,
    p.is_unplanned,
    p.unplanned_kind,
    p.photo_path,
    p.voice_note_path,
    p.voice_note_seconds,
    p.lat,
    p.lon,
    p.accuracy_meters,
    p.distance_meters,
    p.location_flag,
    p.photo_lat,
    p.photo_lon,
    p.photo_accuracy_meters,
    p.dwell_seconds,
    p.form_open_seconds,
    p.capture_source,
    p.offline_seconds,
    p.device_skew_minutes,
    p.synced_at AS phoenix_synced_at,
        CASE
            WHEN (p.rep_hr_id IS NOT NULL) THEN ( SELECT array_agg(DISTINCT cv.hr_id ORDER BY cv.hr_id) AS array_agg
               FROM ( SELECT upper(btrim(h.h)) AS hr_id
                       FROM unnest(ARRAY[p.manager_hr_id, p.senior_hr_id, p.product_manager_hr_id]) h(h)
                      WHERE (NULLIF(btrim(COALESCE(h.h, ''::text)), ''::text) IS NOT NULL)
                    UNION
                     SELECT c.hr_id
                       FROM public.phoenix_crm_visit_companions c
                      WHERE (c.visit_id = p.id)) cv)
            ELSE NULL::text[]
        END AS companion_hr_ids,
    true AS counts_in_kpi
   FROM (((((public.phoenix_crm_countable_visits p
     JOIN public.phoenix_crm_counted_seat_windows() team(seat_id, starts_on, stops_on) ON (((team.seat_id = p.seat_id) AND (p.visit_date >= team.starts_on) AND ((team.stops_on IS NULL) OR (p.visit_date < team.stops_on)))))
     LEFT JOIN public.phoenix_crm_customers customer ON ((customer.id = p.customer_id)))
     LEFT JOIN public.crm_person_by_hr_key_cache agent ON ((agent.hr_key = upper(btrim(COALESCE(p.rep_hr_id, p.manager_hr_id))))))
     LEFT JOIN public.crm_person_by_hr_key_cache partner1 ON ((partner1.hr_key = upper(btrim(COALESCE(p.manager_hr_id, p.product_manager_hr_id, p.senior_hr_id))))))
     LEFT JOIN public.crm_person_by_hr_key_cache partner2 ON ((partner2.hr_key = upper(btrim(
        CASE
            WHEN (p.manager_hr_id IS NOT NULL) THEN COALESCE(p.senior_hr_id, p.product_manager_hr_id)
            WHEN (p.product_manager_hr_id IS NOT NULL) THEN p.senior_hr_id
            ELSE NULL::text
        END)))))
  WHERE ((NOT p.is_test) AND (p.imported_from_ireports360_at IS NULL))
UNION ALL
 SELECT a.id,
    ('-1'::integer - ((('x'::text || substr(md5((a.id)::text), 1, 13)))::bit(52))::bigint) AS crm_visit_id,
    a.activity_date AS visit_date,
        CASE
            WHEN (agent.crm_id ~ '^[0-9]+$'::text) THEN (agent.crm_id)::bigint
            ELSE NULL::bigint
        END AS agent_crm_id,
    agent.full_name AS agent_name,
    a.rep_hr_id AS agent_hr_id,
    NULL::bigint AS double_crm_id,
    NULL::text AS double_name,
    NULL::text AS double_hr_id,
    NULL::bigint AS contact_crm_id,
    NULL::text AS contact_name,
    NULL::text AS customer_name,
        CASE a.activity_type
            WHEN 'sales_day'::text THEN btrim(('Sales day '::text || COALESCE(a.note, ''::text)))
            WHEN 'interviews'::text THEN btrim(('Interviews '::text || COALESCE(a.note, ''::text)))
            ELSE a.note
        END AS comment,
        CASE a.activity_type
            WHEN 'meeting'::text THEN '-11'::integer
            WHEN 'conference'::text THEN '-1'::integer
            WHEN 'health_day'::text THEN '-15'::integer
            WHEN 'sales_day'::text THEN '-7'::integer
            WHEN 'training'::text THEN '-9'::integer
            WHEN 'admin_work'::text THEN '-20'::integer
            WHEN 'travel'::text THEN '-12'::integer
            WHEN 'group_meeting'::text THEN '-2'::integer
            WHEN 'rtd'::text THEN '-22'::integer
            WHEN 'interviews'::text THEN '-20'::integer
            ELSE NULL::integer
        END AS visit_type,
        CASE a.activity_type
            WHEN 'meeting'::text THEN 'Meeting'::text
            WHEN 'conference'::text THEN 'Conference'::text
            WHEN 'health_day'::text THEN 'Health Day'::text
            WHEN 'sales_day'::text THEN 'Sales day'::text
            WHEN 'training'::text THEN 'Training'::text
            WHEN 'admin_work'::text THEN 'Admin Work'::text
            WHEN 'travel'::text THEN 'Traveling'::text
            WHEN 'group_meeting'::text THEN 'Group Meeting'::text
            WHEN 'rtd'::text THEN 'RTD'::text
            WHEN 'interviews'::text THEN 'Admin Work'::text
            ELSE NULL::text
        END AS visit_type_description,
    NULL::integer AS call_type,
    NULL::text AS ampm,
    NULL::integer AS attendance,
    ((a.created_at AT TIME ZONE 'Africa/Cairo'::text) AT TIME ZONE 'UTC'::text) AS crm_save_date,
    NULL::jsonb AS raw_payload,
    a.created_at AS synced_at,
    a.created_at,
    a.updated_at,
    ((a.activity_date)::timestamp without time zone AT TIME ZONE 'UTC'::text) AS visit_date_time,
    NULL::integer AS crm_region_id,
    NULL::text AS crm_region_name,
    NULL::text AS speciality,
    NULL::text AS crm_contact_grade,
    'phoenix'::text AS source,
    COALESCE(
        CASE
            WHEN (agent.crm_id ~ '^[0-9]+$'::text) THEN (agent.crm_id)::bigint
            ELSE NULL::bigint
        END, (- (1)::bigint)) AS exclusion_crm_id,
    NULL::boolean AS phoenix_customer_validated,
    NULL::bigint AS double2_crm_id,
    NULL::text AS double2_name,
    NULL::text AS double2_hr_id,
    NULL::text AS visit_kind,
    NULL::text AS entered_by_hr_id,
    NULL::text[] AS products,
    NULL::jsonb AS samples_given,
    NULL::jsonb AS product_availability,
    NULL::text AS objection,
    NULL::text AS objection_note,
    NULL::text AS next_step,
    NULL::date AS next_step_on,
    NULL::text AS visit_pharmacy_name,
    NULL::boolean AS is_unplanned,
    NULL::text AS unplanned_kind,
    NULL::text AS photo_path,
    NULL::text AS voice_note_path,
    NULL::integer AS voice_note_seconds,
    NULL::double precision AS lat,
    NULL::double precision AS lon,
    NULL::numeric AS accuracy_meters,
    NULL::integer AS distance_meters,
    NULL::text AS location_flag,
    NULL::double precision AS photo_lat,
    NULL::double precision AS photo_lon,
    NULL::numeric AS photo_accuracy_meters,
    NULL::integer AS dwell_seconds,
    NULL::integer AS form_open_seconds,
    NULL::text AS capture_source,
    NULL::integer AS offline_seconds,
    NULL::integer AS device_skew_minutes,
    NULL::timestamp with time zone AS phoenix_synced_at,
    NULL::text[] AS companion_hr_ids,
    true AS counts_in_kpi
   FROM ((public.phoenix_crm_day_activities a
     JOIN public.phoenix_crm_counted_day_activity_windows() team(seat_id, counted_from, stops_on) ON ((team.seat_id = a.seat_id)))
     LEFT JOIN public.crm_person_by_hr_key_cache agent ON ((agent.hr_key = upper(btrim(a.rep_hr_id)))))
  WHERE ((NOT a.is_test) AND (a.activity_date >= team.counted_from) AND ((team.stops_on IS NULL) OR (a.activity_date < team.stops_on)) AND (a.activity_type = ANY (ARRAY['meeting'::text, 'conference'::text, 'health_day'::text, 'sales_day'::text, 'training'::text, 'admin_work'::text, 'travel'::text, 'group_meeting'::text, 'rtd'::text, 'interviews'::text])));

ALTER VIEW public.crm_visits_unified OWNER TO postgres;

--
-- Name: VIEW crm_visits_unified; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.crm_visits_unified IS 'Every CRM visit the read door serves: iReports360 rows, and — for a team in phoenix_crm_team_starts, within its start — that team''s Phoenix CRM visits and recorded day activities INSTEAD of its reps'' iReports360 rows (owner, 2026-10-02). Phoenix rows: real only, source ''phoenix'', negative crm_visit_id; a visit is countable, visit_type 0, ampm = the customer''s list; a day activity carries its worked-day code. phoenix_customer_validated says whether a visit''s customer is validated yet (null otherwise). TWO people stand beside the rep: double_* is the manager who rode along, else the product manager, else the senior; double2_* is the chain''s other person. Both are null on a vendor row, which carries one partner column. contact_crm_id is the customer''s vendor id, or the id he owns in the reserved range when he was born in Phoenix CRM — so no per-doctor report drops him (owner, 2026-10-07). See supabase/migrations/20261007193000_crm_doors_carry_every_person_and_every_customer.sql.';

--
-- Name: crm_visits_checkin_flags; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.crm_visits_checkin_flags WITH (security_invoker='true') AS
 SELECT v.id,
    v.crm_visit_id,
    v.visit_date,
    v.agent_crm_id,
    v.agent_name,
    v.agent_hr_id,
    v.double_crm_id,
    v.double_name,
    v.double_hr_id,
    v.contact_crm_id,
    v.contact_name,
    v.customer_name,
    v.comment,
    v.visit_type,
    v.visit_type_description,
    v.call_type,
    v.ampm,
    v.attendance,
    v.crm_save_date,
    v.raw_payload,
    v.synced_at,
    v.created_at,
    v.updated_at,
    v.visit_date_time,
    v.crm_region_id,
    v.crm_region_name,
    v.speciality,
    v.crm_contact_grade,
    v.source,
    v.exclusion_crm_id,
    ck.has_checkin,
    ((v.visit_type = 0) AND (NOT ck.has_checkin)) AS regular_no_checkin,
    v.double2_crm_id,
    v.double2_name,
    v.double2_hr_id,
    v.visit_kind,
    v.entered_by_hr_id,
    v.products,
    v.samples_given,
    v.product_availability,
    v.objection,
    v.objection_note,
    v.next_step,
    v.next_step_on,
    v.visit_pharmacy_name,
    v.is_unplanned,
    v.unplanned_kind,
    v.photo_path,
    v.voice_note_path,
    v.voice_note_seconds,
    v.lat,
    v.lon,
    v.accuracy_meters,
    v.distance_meters,
    v.location_flag,
    v.photo_lat,
    v.photo_lon,
    v.photo_accuracy_meters,
    v.dwell_seconds,
    v.form_open_seconds,
    v.capture_source,
    v.offline_seconds,
    v.device_skew_minutes,
    v.phoenix_synced_at
   FROM (public.crm_visits_unified v
     CROSS JOIN LATERAL ( SELECT
                CASE
                    WHEN (v.source = 'phoenix'::text) THEN true
                    ELSE (EXISTS ( SELECT 1
                       FROM public.crm_checkins_unified c
                      WHERE ((c.source = 'ireports360'::text) AND (c.agent_crm_id = v.agent_crm_id) AND (c.contact_crm_id = v.contact_crm_id) AND (c.check_date >= (v.visit_date)::timestamp without time zone) AND (c.check_date < ((v.visit_date + 1))::timestamp without time zone))))
                END AS has_checkin) ck);

ALTER VIEW public.crm_visits_checkin_flags OWNER TO postgres;

--
-- Name: VIEW crm_visits_checkin_flags; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.crm_visits_checkin_flags IS 'crm_visits_unified plus has_checkin and regular_no_checkin. A flag only: a regular visit with no GPS check-in stays regular (owner decisions 1 and 7). A Phoenix CRM row is its own check-in: a visit is captured live, a day activity is no call. Carries every column CRM Master''s VISIT_SELECT asks for (the second manager and the Phoenix visit detail, appended 20261021140001) — a column the page asks for and this view lacks fails the whole read.';

--
-- Name: customer_360_pharmacy_matches; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.customer_360_pharmacy_matches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name_key text NOT NULL,
    brick_id text NOT NULL,
    typed_example text NOT NULL,
    status text NOT NULL,
    method text NOT NULL,
    pairs jsonb DEFAULT '[]'::jsonb NOT NULL,
    decided_by_hr_id text,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    withdrawn_at timestamp with time zone,
    withdrawn_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_360_pharmacy_matches_admin_has_actor CHECK (((method <> 'admin'::text) OR (decided_by_hr_id IS NOT NULL))),
    CONSTRAINT customer_360_pharmacy_matches_brick_id_check CHECK ((length(btrim(brick_id)) > 0)),
    CONSTRAINT customer_360_pharmacy_matches_method_check CHECK ((method = ANY (ARRAY['one_shop_in_brick'::text, 'admin'::text]))),
    CONSTRAINT customer_360_pharmacy_matches_name_key_check CHECK ((length(btrim(name_key)) > 0)),
    CONSTRAINT customer_360_pharmacy_matches_pairs_check CHECK ((jsonb_typeof(pairs) = 'array'::text)),
    CONSTRAINT customer_360_pharmacy_matches_status_check CHECK ((status = ANY (ARRAY['auto'::text, 'confirmed'::text, 'rejected'::text]))),
    CONSTRAINT customer_360_pharmacy_matches_withdrawn_has_actor CHECK (((withdrawn_at IS NULL) OR (withdrawn_by_hr_id IS NOT NULL)))
);

ALTER TABLE public.customer_360_pharmacy_matches OWNER TO postgres;

--
-- Name: TABLE customer_360_pharmacy_matches; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.customer_360_pharmacy_matches IS 'Customer 360: the tie between a pharmacy name typed on a validated customer''s visit (name_key + brick) and the distributor customer codes of that shop. auto = exactly one shop of that name in the brick; confirmed / rejected = the Super Admin on the Pharmacy matches tab. One live row per name_key + brick; undo withdraws. Never copied into customer_identity_links. See supabase/migrations/20261018230827_customer_360_validated_relationships.sql.';

