--
-- Name: daily_deductions_disputes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.daily_deductions_disputes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    line_id uuid NOT NULL,
    publication_id uuid,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    employee_name text,
    category text NOT NULL,
    unit text DEFAULT 'days'::text NOT NULL,
    days_count numeric(14,2) DEFAULT 0 NOT NULL,
    amount numeric(14,2) DEFAULT 0 NOT NULL,
    dates jsonb DEFAULT '[]'::jsonb NOT NULL,
    range_start date,
    range_end date,
    reason text,
    claim_text text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    decided_by_hr_id text,
    decision_note text,
    decided_at timestamp with time zone,
    created_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT daily_deductions_disputes_claim_check CHECK ((length(btrim(claim_text)) > 0)),
    CONSTRAINT daily_deductions_disputes_decided_check CHECK ((((status = 'open'::text) AND (decided_at IS NULL)) OR ((status <> 'open'::text) AND (decided_at IS NOT NULL)))),
    CONSTRAINT daily_deductions_disputes_employee_check CHECK (((btrim(employee_hr_id) <> ''::text) AND (btrim(employee_hr_id_compact) <> ''::text))),
    CONSTRAINT daily_deductions_disputes_status_check CHECK ((status = ANY (ARRAY['open'::text, 'accepted'::text, 'rejected'::text]))),
    CONSTRAINT daily_deductions_disputes_unit_check CHECK ((unit = ANY (ARRAY['days'::text, 'amount'::text])))
);

ALTER TABLE public.daily_deductions_disputes OWNER TO postgres;

--
-- Name: TABLE daily_deductions_disputes; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.daily_deductions_disputes IS 'A dispute an employee raised on a RELEASED daily deduction line (owner, 2026-11-13). Keeps its own copy of the line, because a withdrawn line is deleted. Accepted = the line is withdrawn and month-end collection never charges those days for that category again (src/lib/daily-deductions/accepted-dispute-days.ts). Service-role only; the audience rule is in src/lib/dispute-center/daily.ts.';

--
-- Name: database_restarts; Type: TABLE; Schema: public; Owner: postgres
