--
-- Name: deductions_candidates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.deductions_candidates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    category text NOT NULL,
    source_system text NOT NULL,
    source_record_id text NOT NULL,
    candidate_key text NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    employee_name text,
    month integer NOT NULL,
    year integer NOT NULL,
    month_key text GENERATED ALWAYS AS ((((year)::text || '-'::text) || lpad((month)::text, 2, '0'::text))) STORED,
    unit text NOT NULL,
    raw_value numeric(14,2) DEFAULT 0 NOT NULL,
    estimated_amount numeric(14,2),
    calculation_status text DEFAULT 'requires_review'::text NOT NULL,
    severity text,
    reason text,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    dates jsonb DEFAULT '[]'::jsonb NOT NULL,
    hierarchy_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by text DEFAULT 'system'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    refreshed_at timestamp with time zone,
    locked_at timestamp with time zone,
    superseded_at timestamp with time zone,
    superseded_by_candidate_id uuid,
    CONSTRAINT deductions_candidates_calculation_status_check CHECK ((calculation_status = ANY (ARRAY['calculated'::text, 'requires_review'::text]))),
    CONSTRAINT deductions_candidates_candidate_key_not_blank CHECK ((btrim(candidate_key) <> ''::text)),
    CONSTRAINT deductions_candidates_employee_hr_id_compact_not_blank CHECK ((btrim(employee_hr_id_compact) <> ''::text)),
    CONSTRAINT deductions_candidates_employee_hr_id_not_blank CHECK ((btrim(employee_hr_id) <> ''::text)),
    CONSTRAINT deductions_candidates_estimated_amount_non_negative CHECK (((estimated_amount IS NULL) OR (estimated_amount >= (0)::numeric))),
    CONSTRAINT deductions_candidates_month_range CHECK (((month >= 1) AND (month <= 12))),
    CONSTRAINT deductions_candidates_raw_value_non_negative CHECK ((raw_value >= (0)::numeric)),
    CONSTRAINT deductions_candidates_severity_check CHECK (((severity IS NULL) OR (severity = ANY (ARRAY['Low'::text, 'Medium'::text, 'High'::text, 'Review'::text])))),
    CONSTRAINT deductions_candidates_source_record_id_not_blank CHECK ((btrim(source_record_id) <> ''::text)),
    CONSTRAINT deductions_candidates_unit_check CHECK ((unit = ANY (ARRAY['days'::text, 'amount'::text]))),
    CONSTRAINT deductions_candidates_year_range CHECK (((year >= 2000) AND (year <= 2100)))
);

ALTER TABLE public.deductions_candidates OWNER TO postgres;

--
-- Name: TABLE deductions_candidates; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.deductions_candidates IS 'Unified Deductions module: immutable-once-published ledger of deduction candidates. Governance/reporting layer only — no trigger or application path writes salary_records/salary_batches from this table; Automated Payroll only ever reads a Phase-2 published snapshot.';

--
-- Name: COLUMN deductions_candidates.locked_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.deductions_candidates.locked_at IS 'Set by the Phase-2 publish RPC when this candidate is captured into a snapshot. While NULL, raw_value/estimated_amount/evidence/dates may be refreshed in place as source data changes. Once set, the guard trigger below rejects further value mutation — correct it by superseding (new row + superseded_at/superseded_by_candidate_id on this one), never by editing a published number.';

--
-- Name: deductions_categories; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.deductions_categories (
    category text NOT NULL,
    label text NOT NULL,
    detection_engine text NOT NULL,
    requires_approval boolean DEFAULT true NOT NULL,
    salary_records_column text,
    sort_order smallint DEFAULT 0 NOT NULL,
    CONSTRAINT deductions_categories_category_check CHECK ((category = ANY (ARRAY['fingerprint'::text, 'crm'::text, 'crm_half_day'::text, 'no_records_activity'::text, 'unpaid_vacation'::text, 'insufficient_balance_vacation'::text, 'no_weekly_plan'::text, 'loan'::text, 'other'::text, 'field_review'::text]))),
    CONSTRAINT deductions_categories_salary_records_column_check CHECK (((salary_records_column IS NULL) OR (salary_records_column = ANY (ARRAY['finger_print'::text, 'crm'::text, 'unpaid_vacations'::text, 'loans'::text, 'other_deductions'::text]))))
);

ALTER TABLE public.deductions_categories OWNER TO postgres;

--
-- Name: TABLE deductions_categories; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.deductions_categories IS 'Unified Deductions module: the 7 category definitions (label, detection engine, whether a decision is required before payroll approval, which salary_records column it ultimately maps to).';

--
-- Name: COLUMN deductions_categories.requires_approval; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.deductions_categories.requires_approval IS 'false only for crm — the owner''s existing dictated rule: a field rep''s no-CRM-activity day is deducted by default unless HR explicitly clears it.';

--
-- Name: deductions_comment_attachments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.deductions_comment_attachments (
