    CONSTRAINT deductions_comment_attachments_size_check CHECK (((size_bytes > 0) AND (size_bytes <= 5242880))),
    CONSTRAINT deductions_comment_attachments_type_check CHECK ((content_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text])))
);

ALTER TABLE public.deductions_comment_attachments OWNER TO postgres;

--
-- Name: TABLE deductions_comment_attachments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.deductions_comment_attachments IS 'Pictures attached to a deduction dispute reply. Bytes live in the private deductions-dispute-attachments bucket; read only through a permission-checked route, never by a stored URL.';

--
-- Name: deductions_comments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.deductions_comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    author_login_id text DEFAULT 'system'::text NOT NULL,
    author_hr_id text,
    author_role text,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT deductions_comments_author_not_blank CHECK ((btrim(author_login_id) <> ''::text)),
    CONSTRAINT deductions_comments_body_not_blank CHECK ((btrim(body) <> ''::text))
);

ALTER TABLE public.deductions_comments OWNER TO postgres;

--
-- Name: TABLE deductions_comments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.deductions_comments IS 'Unified Deductions module: employee/HR comment thread on a published deduction candidate. Mirrors legacy deduction_comments 1:1 (candidate_id -> deductions_candidates). Access mediated entirely in application code via the service-role client, same as the legacy table.';

--
-- Name: deductions_decisions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.deductions_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_id uuid NOT NULL,
    decision_status text DEFAULT 'Pending'::text NOT NULL,
    decision_reason text DEFAULT ''::text NOT NULL,
    hr_note text DEFAULT ''::text NOT NULL,
    applied_value numeric(14,2),
    applied_amount numeric(14,2),
    decided_by text,
    decided_at timestamp with time zone,
    actor_role_at_decision text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_dates jsonb,
    CONSTRAINT deductions_decisions_applied_amount_non_negative CHECK (((applied_amount IS NULL) OR (applied_amount >= (0)::numeric))),
    CONSTRAINT deductions_decisions_applied_dates_is_array CHECK (((applied_dates IS NULL) OR (jsonb_typeof(applied_dates) = 'array'::text))),
    CONSTRAINT deductions_decisions_applied_value_non_negative CHECK (((applied_value IS NULL) OR (applied_value >= (0)::numeric))),
    CONSTRAINT deductions_decisions_status_check CHECK ((decision_status = ANY (ARRAY['Pending'::text, 'Approved for Payroll'::text, 'Do Not Take Action'::text, 'Needs Follow-up'::text, 'Disputed'::text])))
);

ALTER TABLE public.deductions_decisions OWNER TO postgres;

--
-- Name: TABLE deductions_decisions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.deductions_decisions IS 'Unified Deductions module: one HR decision per candidate. Super Admin gated (mirrors assertDeductionsGovernanceDecisionActor / assertAutomatedPayrollHrActor). Feeds the Phase-2 publish snapshot only — never writes payroll tables directly.';

--
-- Name: COLUMN deductions_decisions.applied_dates; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.deductions_decisions.applied_dates IS 'The exact days this decision charges, as a jsonb array of YYYY-MM-DD strings. NULL means the reviewer never narrowed the selection, so the candidate''s full `dates` array applies — NOT that nothing is charged. Always a subset of the parent candidate''s `dates`; the application layer rejects any day the detection engine did not find.';

--
-- Name: deductions_publication_lines; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.deductions_publication_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    publication_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    decision_id uuid,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    employee_name text,
    month_key text NOT NULL,
    category text NOT NULL,
    unit text NOT NULL,
    original_value numeric(14,2) NOT NULL,
    applied_value numeric(14,2) NOT NULL,
    applied_amount numeric(14,2) NOT NULL,
    dates jsonb DEFAULT '[]'::jsonb NOT NULL,
    reason text,
    hr_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    line_status text DEFAULT 'active'::text NOT NULL,
    pushed_by text,
    pushed_at timestamp with time zone,
    notified_at timestamp with time zone,
    notification_status text,
    superseded_by_line_id uuid,
    CONSTRAINT deductions_publication_lines_applied_amount_non_negative CHECK ((applied_amount >= (0)::numeric)),
    CONSTRAINT deductions_publication_lines_applied_value_non_negative CHECK ((applied_value >= (0)::numeric)),
    CONSTRAINT deductions_publication_lines_day_amount_positive CHECK (((unit <> 'days'::text) OR (applied_amount > (0)::numeric))),
    CONSTRAINT deductions_publication_lines_employee_hr_id_not_blank CHECK ((btrim(employee_hr_id) <> ''::text)),
    CONSTRAINT deductions_publication_lines_line_status_check CHECK ((line_status = ANY (ARRAY['active'::text, 'withdrawn'::text]))),
    CONSTRAINT deductions_publication_lines_unit_check CHECK ((unit = ANY (ARRAY['days'::text, 'amount'::text])))
);

ALTER TABLE public.deductions_publication_lines OWNER TO postgres;

--
-- Name: TABLE deductions_publication_lines; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.deductions_publication_lines IS 'Unified Deductions module: immutable per-employee-per-category snapshot rows captured at publish time. Automated Payroll (Phase 5) and the employee portal (Phase 4) read exclusively from here for a status=published publication — never from deductions_candidates/deductions_decisions directly.';

--
-- Name: COLUMN deductions_publication_lines.line_status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.deductions_publication_lines.line_status IS 'active = currently released to the employee and counted for payroll; withdrawn = pulled back by the Super Admin (kept for the audit trail, invisible to the portal and payroll).';

--
-- Name: COLUMN deductions_publication_lines.pushed_by; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.deductions_publication_lines.pushed_by IS 'HR id of the Super Admin who pushed this individual line; null for a legacy month-atomic (wholesale) publish.';

--
-- Name: COLUMN deductions_publication_lines.pushed_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.deductions_publication_lines.pushed_at IS 'When this individual line was pushed; null for a legacy month-atomic (wholesale) publish.';

--
-- Name: CONSTRAINT deductions_publication_lines_day_amount_positive ON deductions_publication_lines; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT deductions_publication_lines_day_amount_positive ON public.deductions_publication_lines IS 'A day-based deduction can never publish at 0.00 — that is "amount unknown" masquerading as "deduct nothing". Enforced in publish.ts first; this is the storage-layer backstop.';

--
-- Name: deductions_publications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.deductions_publications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    month integer NOT NULL,
    year integer NOT NULL,
    month_key text GENERATED ALWAYS AS ((((year)::text || '-'::text) || lpad((month)::text, 2, '0'::text))) STORED,
    status text DEFAULT 'published'::text NOT NULL,
    published_by text NOT NULL,
    published_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    superseded_by_publication_id uuid,
    candidate_count integer DEFAULT 0 NOT NULL,
    employee_count integer DEFAULT 0 NOT NULL,
    category_totals jsonb DEFAULT '{}'::jsonb NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT deductions_publications_counts_non_negative CHECK (((candidate_count >= 0) AND (employee_count >= 0))),
    CONSTRAINT deductions_publications_month_range CHECK (((month >= 1) AND (month <= 12))),
    CONSTRAINT deductions_publications_published_by_not_blank CHECK ((btrim(published_by) <> ''::text)),
    CONSTRAINT deductions_publications_status_check CHECK ((status = ANY (ARRAY['published'::text, 'superseded'::text]))),
    CONSTRAINT deductions_publications_year_range CHECK (((year >= 2000) AND (year <= 2100)))
);

ALTER TABLE public.deductions_publications OWNER TO postgres;

--
-- Name: TABLE deductions_publications; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.deductions_publications IS 'Unified Deductions module: the "press publish" record. At most one status=published row per month_key (enforced by the partial unique index below) — republishing atomically supersedes the previous one via phx_publish_deductions.';

--
-- Name: departments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.departments (
    id bigint NOT NULL,
    code text NOT NULL,
