--
-- Name: device_assignments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.device_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    device_id uuid NOT NULL,
    employee_hr_id text,
    employee_name text,
    job_title text,
    declaration_no text,
    handover_place text,
    issued_on date DEFAULT ((now() AT TIME ZONE 'Africa/Cairo'::text))::date NOT NULL,
    issued_by text,
    agreed_value_egp numeric(12,2),
    status text DEFAULT 'outstanding'::text NOT NULL,
    returned_on date,
    returned_by text,
    return_condition text,
    shortfall_note text,
    settlement_egp numeric(12,2),
    reason text,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    item_values_egp jsonb,
    is_placeholder boolean DEFAULT false NOT NULL,
    placeholder_name text,
    CONSTRAINT device_assignments_agreed_value_egp_check CHECK (((agreed_value_egp IS NULL) OR (agreed_value_egp >= (0)::numeric))),
    CONSTRAINT device_assignments_employee_hr_id_check CHECK ((char_length(TRIM(BOTH FROM employee_hr_id)) > 0)),
    CONSTRAINT device_assignments_holder_identity CHECK ((((is_placeholder = true) AND (employee_hr_id IS NULL) AND (placeholder_name IS NOT NULL) AND (char_length(TRIM(BOTH FROM placeholder_name)) > 0)) OR ((is_placeholder = false) AND (employee_hr_id IS NOT NULL) AND (char_length(TRIM(BOTH FROM employee_hr_id)) > 0) AND (employee_name IS NOT NULL)))),
    CONSTRAINT device_assignments_item_values_shape CHECK (public.phx_custody_item_values_valid(item_values_egp)),
    CONSTRAINT device_assignments_return_condition_check CHECK (((return_condition IS NULL) OR (return_condition = ANY (ARRAY['good'::text, 'damaged'::text, 'incomplete'::text])))),
    CONSTRAINT device_assignments_return_recorded CHECK (((status <> 'returned'::text) OR ((returned_on IS NOT NULL) AND (return_condition IS NOT NULL)))),
    CONSTRAINT device_assignments_settlement_egp_check CHECK (((settlement_egp IS NULL) OR (settlement_egp >= (0)::numeric))),
    CONSTRAINT device_assignments_settlement_within_agreed CHECK (((settlement_egp IS NULL) OR (agreed_value_egp IS NULL) OR (settlement_egp <= agreed_value_egp))),
    CONSTRAINT device_assignments_status_check CHECK ((status = ANY (ARRAY['outstanding'::text, 'returned'::text, 'written_off'::text, 'reserved'::text, 'revoked'::text]))),
    CONSTRAINT device_assignments_write_off_reason CHECK (((status <> 'written_off'::text) OR ((reason IS NOT NULL) AND (char_length(TRIM(BOTH FROM reason)) > 0))))
);

ALTER TABLE public.device_assignments OWNER TO postgres;

--
-- Name: TABLE device_assignments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.device_assignments IS 'One custody event: a named person signed for a named device on a date. Closed only by a recorded return (محضر رد العهدة, البند 8) or an explicit write-off carrying a reason.';

--
-- Name: COLUMN device_assignments.item_values_egp; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.device_assignments.item_values_egp IS 'Per-item estimated values in EGP, keyed by the custody template item number ("1".."7"). An absent key means the item was not handed over: it prints blank and is excluded from the total, per itemNoteAr. Frozen at issue like agreed_value_egp.';

--
-- Name: COLUMN device_assignments.is_placeholder; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.device_assignments.is_placeholder IS 'True while this row is a reservation for a not-yet-hired holder — no hr_id, no signed value. Cleared by phx_device_reconcile on day one, which turns it into a real signed custody.';

--
-- Name: CONSTRAINT device_assignments_settlement_within_agreed ON device_assignments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT device_assignments_settlement_within_agreed ON public.device_assignments IS 'البند (10) of the custody receipt caps recovery at the estimated value shown at signature. A settlement above it would be a wage deduction the signed instrument does not authorise.';

--
-- Name: device_screen_recordings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.device_screen_recordings (
    id uuid NOT NULL,
    device_number text NOT NULL,
    asset_tag text,
    requested_by_hr_id text NOT NULL,
    status text DEFAULT 'requested'::text NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    duration_requested_s integer NOT NULL,
    captured_seconds integer,
    size_bytes bigint,
    storage_path text NOT NULL,
    upload_token_hash text,
    uploaded_at timestamp with time zone,
    error text,
    CONSTRAINT device_screen_recordings_bytes CHECK (((size_bytes IS NULL) OR ((size_bytes >= 1) AND (size_bytes <= 268435456)))),
    CONSTRAINT device_screen_recordings_captured CHECK (((captured_seconds IS NULL) OR ((captured_seconds >= 1) AND (captured_seconds <= 600)))),
    CONSTRAINT device_screen_recordings_device CHECK (((char_length(device_number) >= 1) AND (char_length(device_number) <= 80))),
    CONSTRAINT device_screen_recordings_duration CHECK (((duration_requested_s >= 5) AND (duration_requested_s <= 300))),
    CONSTRAINT device_screen_recordings_path CHECK (((char_length(storage_path) >= 10) AND (char_length(storage_path) <= 200))),
    CONSTRAINT device_screen_recordings_status CHECK ((status = ANY (ARRAY['requested'::text, 'ready'::text, 'failed'::text, 'expired'::text])))
);

ALTER TABLE public.device_screen_recordings OWNER TO postgres;

--
-- Name: direct_order_approval_steps; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.direct_order_approval_steps (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    step_order integer NOT NULL,
    approver_kind text NOT NULL,
    approver_role text,
    approver_hr_id text,
    label text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    decision_comment text,
    decided_by_hr_id text,
    decided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT direct_order_approval_steps_approver_kind_check CHECK ((approver_kind = ANY (ARRAY['person'::text, 'role'::text]))),
    CONSTRAINT direct_order_approval_steps_approver_shape_check CHECK ((((approver_kind = 'person'::text) AND (approver_hr_id IS NOT NULL)) OR ((approver_kind = 'role'::text) AND (approver_role IS NOT NULL)))),
    CONSTRAINT direct_order_approval_steps_decision_ts_check CHECK ((((status = 'pending'::text) AND (decided_at IS NULL)) OR ((status = ANY (ARRAY['approved'::text, 'rejected'::text])) AND (decided_at IS NOT NULL)))),
    CONSTRAINT direct_order_approval_steps_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);

ALTER TABLE public.direct_order_approval_steps OWNER TO postgres;

