    CONSTRAINT direct_order_caps_discount_cap_pct_check CHECK (((discount_cap_pct IS NULL) OR ((discount_cap_pct >= (0)::numeric) AND (discount_cap_pct <= (100)::numeric))))
);

ALTER TABLE public.direct_order_caps OWNER TO postgres;

