--
-- Name: direct_order_pharmacy_validations; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.direct_order_pharmacy_validations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pharmacy_id uuid NOT NULL,
    request_id uuid,
    requested_by_hr_id text NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_pharmacy_name text NOT NULL,
    claimed_address text,
    claimed_doctor_name text,
    claimed_reason text,
    captured_latitude double precision,
    captured_longitude double precision,
    captured_accuracy_meters double precision,
    captured_at timestamp with time zone,
    captured_address text,
    requester_area_code text,
    gps_inside_requester_area boolean,
    storage_bucket text DEFAULT 'direct-order-evidence'::text NOT NULL,
    storage_path text,
    status text DEFAULT 'pending'::text NOT NULL,
    decided_by_hr_id text,
    decided_at timestamp with time zone,
    decision_notes text,
    matched_distributor_code text,
    matched_customer_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    suggestions_shown jsonb,
    suggestions_refused boolean DEFAULT false NOT NULL,
    evidence_check jsonb,
    license_storage_path text,
    license_content_type text,
    license_uploaded_at timestamp with time zone,
    license_name_matches_sign boolean,
    validation_route text DEFAULT 'field'::text NOT NULL,
    invoice_storage_path text,
    invoice_content_type text,
    invoice_uploaded_at timestamp with time zone,
    photo_captured_at timestamp with time zone,
    photo_latitude double precision,
    photo_longitude double precision,
    photo_accuracy_meters double precision,
    CONSTRAINT direct_order_pharmacy_validations_invoice_content_type_check CHECK (((invoice_content_type IS NULL) OR (invoice_content_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'application/pdf'::text])))),
    CONSTRAINT direct_order_pharmacy_validations_invoice_route_check CHECK (((invoice_storage_path IS NULL) OR (validation_route = 'invoice'::text))),
    CONSTRAINT direct_order_pharmacy_validations_license_content_type_check CHECK (((license_content_type IS NULL) OR (license_content_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'application/pdf'::text])))),
    CONSTRAINT direct_order_pharmacy_validations_license_verdict_check CHECK (((license_name_matches_sign IS NULL) OR (license_storage_path IS NOT NULL))),
    CONSTRAINT direct_order_pharmacy_validations_route_check CHECK ((validation_route = ANY (ARRAY['field'::text, 'invoice'::text]))),
    CONSTRAINT direct_order_pharmacy_validations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved_new'::text, 'matched_existing'::text, 'rejected'::text])))
);

ALTER TABLE public.direct_order_pharmacy_validations OWNER TO postgres;

--
-- Name: TABLE direct_order_pharmacy_validations; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.direct_order_pharmacy_validations IS 'Pharmacy Validation requests (spec A2). Mirrors marketing Customer Validation: live GPS-stamped storefront photo + claimed details, decided by a Super Admin who may match it to an existing directory customer, approve it as new (provisional), or reject it.';

--
-- Name: COLUMN direct_order_pharmacy_validations.suggestions_shown; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.suggestions_shown IS 'The candidates Phoenix offered before this claim was submitted, with their scores. Kept so the question "was this rep shown the real pharmacy and went ahead anyway?" has an answer.';

--
-- Name: COLUMN direct_order_pharmacy_validations.evidence_check; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.evidence_check IS 'Spec E2: advisory read of the storefront photo, taken once at filing. NULL means no answer (not yet run, or could not run) and must never be rendered or treated as a pass. Never gates a decision — the Super Admin decides.';

--
-- Name: COLUMN direct_order_pharmacy_validations.license_storage_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.license_storage_path IS 'Pharmacy trade licence, in the private pharmacy-licenses bucket. NULL = none attached.';

--
-- Name: COLUMN direct_order_pharmacy_validations.license_content_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.license_content_type IS 'image/jpeg, image/png or application/pdf — what the approver''s browser is asked to open.';

--
-- Name: COLUMN direct_order_pharmacy_validations.license_name_matches_sign; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.license_name_matches_sign IS 'Approver''s verdict that the licence trade name matches the shop sign. NULL = never asked.';

--
-- Name: COLUMN direct_order_pharmacy_validations.validation_route; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.validation_route IS 'field = live photo and location; invoice = a distributor invoice alone (limited to 5 open pharmacies per rep).';

--
-- Name: COLUMN direct_order_pharmacy_validations.invoice_storage_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.invoice_storage_path IS 'Distributor invoice, in the private direct-order-invoices bucket. Only on an invoice-route claim.';

--
-- Name: COLUMN direct_order_pharmacy_validations.invoice_content_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.invoice_content_type IS 'image/jpeg, image/png or application/pdf — what the reviewer''s browser is asked to open.';

--
-- Name: COLUMN direct_order_pharmacy_validations.photo_captured_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.photo_captured_at IS 'When the shutter fired, from the capturing device. Distinct from captured_at, which is when the location pin was taken. NULL on every row written before 2026-09-29.';

--
-- Name: COLUMN direct_order_pharmacy_validations.photo_latitude; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.photo_latitude IS 'The PHOTO''s own latitude, read fresh at the shutter. Never a copy of captured_latitude. NULL means not measured, never "same place as the pin".';

--
-- Name: COLUMN direct_order_pharmacy_validations.photo_longitude; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.photo_longitude IS 'The PHOTO''s own longitude, read fresh at the shutter. Never a copy of captured_longitude. NULL means not measured, never "same place as the pin".';

--
-- Name: COLUMN direct_order_pharmacy_validations.photo_accuracy_meters; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_pharmacy_validations.photo_accuracy_meters IS 'Reported accuracy of the shutter fix. Stored only; it refuses nothing and decides nothing.';

--
-- Name: direct_order_report_share_links; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.direct_order_report_share_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    token text NOT NULL,
    surface text DEFAULT 'live'::text NOT NULL,
    label text,
    created_by_hr_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    scope text NOT NULL,
    scope_hr_id text NOT NULL,
    filters jsonb,
    passcode_hash text,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by_hr_id text,
    last_accessed_at timestamp with time zone,
    access_count integer DEFAULT 0 NOT NULL,
    allow_files boolean DEFAULT false NOT NULL,
    file_access_count integer DEFAULT 0 NOT NULL,
    refused_count integer DEFAULT 0 NOT NULL,
    last_refused_at timestamp with time zone,
    CONSTRAINT direct_order_report_share_links_surface_check CHECK ((surface = ANY (ARRAY['live'::text, 'feed'::text])))
);

ALTER TABLE public.direct_order_report_share_links OWNER TO postgres;

--
-- Name: TABLE direct_order_report_share_links; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.direct_order_report_share_links IS 'Shareable live views of the Direct Orders report. A link is a bearer credential: mandatory expiry, one-click revoke, creator-frozen scope, and every open audited. The human surface also requires a passcode; the CSV feed cannot (IMPORTDATA cannot supply one) and is meant to sit inside a private Google Sheet formula rather than be given to a person.';

--
-- Name: COLUMN direct_order_report_share_links.scope; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_report_share_links.scope IS 'The creator''s report scope AT CREATION. Never re-resolved on read — a link must not silently widen when its creator is promoted, nor break when they are not.';

--
-- Name: COLUMN direct_order_report_share_links.allow_files; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_report_share_links.allow_files IS 'Whether this token may stream pharmacy-validation storefront photos. Separate from the CSV grant on purpose: the table leaks numbers, a file leaks a GPS-stamped photograph of a real shop front. Off unless explicitly asked for.';

--
-- Name: COLUMN direct_order_report_share_links.file_access_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_report_share_links.file_access_count IS 'File opens, counted separately from CSV pulls. "Nobody ever opened a photo" and "someone opened 200" are different facts, and only the second is worth investigating.';

--
-- Name: COLUMN direct_order_report_share_links.refused_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_report_share_links.refused_count IS 'Reads refused because this link is revoked or expired. Counted only for an existing row, so an unauthenticated caller cannot drive the write path. Never reset — the 24h window on last_refused_at is what makes the alert stop.';

--
-- Name: COLUMN direct_order_report_share_links.last_refused_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.direct_order_report_share_links.last_refused_at IS 'When a dead-link read was last refused. Judged by src/lib/share-links/dead-token-polling.ts.';

--
-- Name: direct_order_request_items; Type: TABLE; Schema: public; Owner: postgres
