    CONSTRAINT direct_order_request_items_bonus_check CHECK ((bonus >= (0)::numeric)),
    CONSTRAINT direct_order_request_items_deal_type_check CHECK ((deal_type = ANY (ARRAY['bonus'::text, 'discount'::text]))),
    CONSTRAINT direct_order_request_items_line_no_check CHECK ((line_no >= 1)),
    CONSTRAINT direct_order_request_items_qty_check CHECK ((qty > (0)::numeric)),
    CONSTRAINT direct_order_request_items_sales_value_check CHECK ((sales_value >= (0)::numeric))
);

ALTER TABLE public.direct_order_request_items OWNER TO postgres;

--
-- Name: dispute_assist_entries; Type: TABLE; Schema: public; Owner: postgres
