);

ALTER TABLE public.dispute_assist_entries OWNER TO postgres;

--
-- Name: TABLE dispute_assist_entries; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dispute_assist_entries IS 'Every Case Briefing and every question asked about a dispute, with the checked answer and the fingerprint of the records it was built from. Super Admin only, append-only.';

--
-- Name: dispute_attachments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dispute_attachments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_kind text NOT NULL,
