    CONSTRAINT dispute_attachments_size_check CHECK (((size_bytes > 0) AND (size_bytes <= 5242880))),
    CONSTRAINT dispute_attachments_type_check CHECK ((content_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text])))
);

ALTER TABLE public.dispute_attachments OWNER TO postgres;

--
-- Name: TABLE dispute_attachments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dispute_attachments IS 'Pictures on a calendar or weekly-review dispute, from either side. Bytes live in the private dispute-attachments bucket and are read only through /api/dispute-center/attachments/:id.';

--
-- Name: dispute_case_decision_claims; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dispute_case_decision_claims (
    case_kind text NOT NULL,
    case_ref text NOT NULL,
    claim_token uuid NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone DEFAULT now() NOT NULL,
    lapse_at timestamp with time zone NOT NULL,
    snapshot jsonb,
    CONSTRAINT dispute_case_decision_claims_kind_check CHECK ((case_kind = ANY (ARRAY['calendar'::text, 'deduction'::text, 'digest'::text])))
);

ALTER TABLE public.dispute_case_decision_claims OWNER TO postgres;

--
-- Name: TABLE dispute_case_decision_claims; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dispute_case_decision_claims IS 'One row while a dispute is being decided (F-PAY-005). Taken before the first write, released after the decided event. snapshot is the before-state the decision restores if it fails half-way. A row past lapse_at was left by a request that died and may be taken over.';

--
-- Name: dispute_case_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dispute_case_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_kind text NOT NULL,
    case_ref text NOT NULL,
    event_type text NOT NULL,
    actor_hr_id text,
    actor_role text,
    note text,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dispute_case_events_kind_check CHECK ((case_kind = ANY (ARRAY['calendar'::text, 'deduction'::text, 'digest'::text, 'daily'::text]))),
    CONSTRAINT dispute_case_events_type_check CHECK ((event_type = ANY (ARRAY['reopen_requested'::text, 'reopen_declined'::text, 'reopened'::text, 'decided'::text, 'refund_recommended'::text, 'refund_cancelled'::text, 'decision_interrupted'::text])))
);

ALTER TABLE public.dispute_case_events OWNER TO postgres;

--
-- Name: TABLE dispute_case_events; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dispute_case_events IS 'Everything that happened to a dispute besides its messages: decisions (every one, so a reopened case keeps the earlier ruling), reopen requests and reopenings, refunds. Append-only.';

--
-- Name: dispute_refunds; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.dispute_refunds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_kind text NOT NULL,
    case_ref text NOT NULL,
    candidate_id uuid,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    source_month_key text NOT NULL,
    target_month_key text NOT NULL,
    amount numeric(12,2) NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'recommended'::text NOT NULL,
    created_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cancelled_at timestamp with time zone,
    cancelled_by_hr_id text,
    cancel_reason text,
    CONSTRAINT dispute_refunds_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT dispute_refunds_cancel_shape_check CHECK ((((status = 'recommended'::text) AND (cancelled_at IS NULL)) OR ((status = 'cancelled'::text) AND (cancelled_at IS NOT NULL)))),
    CONSTRAINT dispute_refunds_kind_check CHECK ((case_kind = ANY (ARRAY['deduction'::text, 'digest'::text]))),
    CONSTRAINT dispute_refunds_month_check CHECK (((source_month_key ~ '^\d{4}-(0[1-9]|1[0-2])$'::text) AND (target_month_key ~ '^\d{4}-(0[1-9]|1[0-2])$'::text) AND (target_month_key > source_month_key))),
    CONSTRAINT dispute_refunds_status_check CHECK ((status = ANY (ARRAY['recommended'::text, 'cancelled'::text])))
);

ALTER TABLE public.dispute_refunds OWNER TO postgres;

--
-- Name: TABLE dispute_refunds; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.dispute_refunds IS 'A deduction a revised dispute decision gives back after its month was already paid. Feeds the NEXT open payroll''s Additions -> Other Additions as a recommendation HR confirms; never pays by itself.';

--
