--
-- Name: early_birds_audit; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.early_birds_audit (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_id uuid,
    candidate_id uuid,
    period_key text,
    actor_hr_id text,
