--
-- Name: early_birds_candidates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.early_birds_candidates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    snapshot_id uuid NOT NULL,
    period_key text NOT NULL,
    manager_hr_id text NOT NULL,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    employee_name text,
    candidate_key text NOT NULL,
    rank integer NOT NULL,
    candidate_rank integer,
    eligible boolean DEFAULT true NOT NULL,
    ineligible_reasons text[] DEFAULT '{}'::text[] NOT NULL,
    total_score numeric(9,6) NOT NULL,
    base_score numeric(9,6) NOT NULL,
    quality_weight numeric(9,6) NOT NULL,
    component_scores jsonb DEFAULT '{}'::jsonb NOT NULL,
    median_start_minutes integer,
    days_with_submission integer DEFAULT 0 NOT NULL,
    expected_working_days integer DEFAULT 0 NOT NULL,
    total_visits integer DEFAULT 0 NOT NULL,
    regular_visits integer DEFAULT 0 NOT NULL,
    campaign_visits integer DEFAULT 0 NOT NULL,
    gps_eligible_visits integer DEFAULT 0 NOT NULL,
    gps_verified_visits integer DEFAULT 0 NOT NULL,
    gps_share numeric(9,6),
    daily_wins integer DEFAULT 0 NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    regular_visits_with_checkin integer DEFAULT 0 NOT NULL,
    regular_visits_no_checkin integer DEFAULT 0 NOT NULL,
    CONSTRAINT early_birds_candidates_counts_non_negative CHECK (((days_with_submission >= 0) AND (expected_working_days >= 0) AND (total_visits >= 0) AND (regular_visits >= 0) AND (campaign_visits >= 0) AND (gps_eligible_visits >= 0) AND (gps_verified_visits >= 0) AND (daily_wins >= 0))),
    CONSTRAINT early_birds_candidates_eligible_rank_pairing CHECK (((eligible AND (candidate_rank IS NOT NULL) AND (candidate_rank >= 1)) OR ((NOT eligible) AND (candidate_rank IS NULL)))),
    CONSTRAINT early_birds_candidates_gps_share_bounded CHECK (((gps_share IS NULL) OR ((gps_share >= (0)::numeric) AND (gps_share <= (1)::numeric)))),
    CONSTRAINT early_birds_candidates_gps_within_eligible CHECK ((gps_verified_visits <= gps_eligible_visits)),
    CONSTRAINT early_birds_candidates_median_start_bounded CHECK (((median_start_minutes IS NULL) OR ((median_start_minutes >= 0) AND (median_start_minutes < 1440)))),
    CONSTRAINT early_birds_candidates_rank_positive CHECK ((rank >= 1)),
    CONSTRAINT early_birds_candidates_reasons_pairing CHECK (((eligible AND (cardinality(ineligible_reasons) = 0)) OR ((NOT eligible) AND (cardinality(ineligible_reasons) > 0)))),
    CONSTRAINT early_birds_candidates_scores_bounded CHECK ((((total_score >= (0)::numeric) AND (total_score <= (1)::numeric)) AND ((base_score >= (0)::numeric) AND (base_score <= (1)::numeric)) AND (quality_weight > (0)::numeric) AND (quality_weight <= (1)::numeric))),
    CONSTRAINT early_birds_candidates_typed_within_total CHECK (((regular_visits + campaign_visits) <= total_visits))
);

ALTER TABLE public.early_birds_candidates OWNER TO postgres;

