    ticket_go_amount numeric(12,2) DEFAULT 0 NOT NULL,
    ticket_return_amount numeric(12,2) DEFAULT 0 NOT NULL,
    meeting_amount numeric(12,2) DEFAULT 0 NOT NULL,
    other_amount numeric(12,2) DEFAULT 0 NOT NULL,
    claimed_total numeric(12,2) DEFAULT 0 NOT NULL,
    approved_total numeric(12,2),
    data_quality_hold boolean DEFAULT false NOT NULL,
    data_quality_reason text,
    decided_by_hr_id text,
    decided_at timestamp with time zone,
    decision_reason text,
    incurred_year integer,
    incurred_month integer,
    payout_year integer,
    payout_month integer,
    evidence_gate_status text,
    workload_gate_status text,
    legacy_request_id bigint,
    legacy_expense_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT expense_claims_amounts_non_negative CHECK (((fuel_amount >= (0)::numeric) AND (allowance_amount >= (0)::numeric) AND (ticket_go_amount >= (0)::numeric) AND (ticket_return_amount >= (0)::numeric) AND (meeting_amount >= (0)::numeric) AND (other_amount >= (0)::numeric) AND (claimed_total >= (0)::numeric))),
    CONSTRAINT expense_claims_approved_needs_decision CHECK (((status <> 'approved'::text) OR (decided_at IS NOT NULL))),
    CONSTRAINT expense_claims_approved_total_range CHECK (((approved_total IS NULL) OR ((approved_total >= (0)::numeric) AND (approved_total <= claimed_total)))),
    CONSTRAINT expense_claims_claim_ref_not_blank CHECK ((btrim(claim_ref) <> ''::text)),
    CONSTRAINT expense_claims_import_id_only_for_import CHECK (((import_id IS NULL) OR (source = 'import'::text))),
    CONSTRAINT expense_claims_incurred_month_valid CHECK (((incurred_month IS NULL) OR ((incurred_month >= 1) AND (incurred_month <= 12)))),
    CONSTRAINT expense_claims_payout_month_valid CHECK (((payout_month IS NULL) OR ((payout_month >= 1) AND (payout_month <= 12)))),
    CONSTRAINT expense_claims_source_check CHECK ((source = ANY (ARRAY['wizard'::text, 'admin_manual'::text, 'import'::text]))),
    CONSTRAINT expense_claims_status_check CHECK ((status = ANY (ARRAY['submitted'::text, 'returned'::text, 'approved'::text, 'rejected'::text, 'in_payroll'::text, 'paid'::text, 'cancelled'::text])))
);

ALTER TABLE public.expense_claims OWNER TO postgres;

--
-- Name: TABLE expense_claims; Type: COMMENT; Schema: public; Owner: postgres
