    dates jsonb DEFAULT '[]'::jsonb NOT NULL,
    days_count integer DEFAULT 0 NOT NULL,
    severity text DEFAULT 'Review'::text NOT NULL,
    recommendation_reason text NOT NULL,
    existing_coverage_status text DEFAULT 'not_applicable'::text NOT NULL,
    estimated_amount numeric(14,2),
    decision_status text DEFAULT 'Pending'::text NOT NULL,
    hr_note text DEFAULT ''::text NOT NULL,
    decided_by text,
    decided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    decision_reason text DEFAULT ''::text NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by text,
    CONSTRAINT field_workforce_decisions_coverage_check CHECK ((existing_coverage_status = ANY (ARRAY['already_covered'::text, 'needs_reconciliation'::text, 'leave_source_not_connected'::text, 'payroll_calculation_required'::text, 'not_applicable'::text]))),
    CONSTRAINT field_workforce_decisions_dates_array CHECK ((jsonb_typeof(dates) = 'array'::text)),
    CONSTRAINT field_workforce_decisions_days_non_negative CHECK ((days_count >= 0)),
    CONSTRAINT field_workforce_decisions_employee_code_not_blank CHECK ((btrim(employee_code) <> ''::text)),
    CONSTRAINT field_workforce_decisions_employee_name_not_blank CHECK ((btrim(employee_name) <> ''::text)),
    CONSTRAINT field_workforce_decisions_key_not_blank CHECK ((btrim(recommendation_key) <> ''::text)),
    CONSTRAINT field_workforce_decisions_month_key_not_blank CHECK ((btrim(month_key) <> ''::text)),
    CONSTRAINT field_workforce_decisions_severity_check CHECK ((severity = ANY (ARRAY['Low'::text, 'Medium'::text, 'High'::text, 'Review'::text]))),
    CONSTRAINT field_workforce_decisions_source_check CHECK ((source_type = ANY (ARRAY['approved_leave_request'::text, 'calendar_av'::text, 'n_retroactive_candidate'::text, 'no_activity_candidate'::text]))),
    CONSTRAINT field_workforce_decisions_status_check CHECK ((decision_status = ANY (ARRAY['Pending'::text, 'Approved for Leave Adjustment Report'::text, 'Approved for Payroll Deduction Report'::text, 'Do Not Take Action'::text, 'Needs Follow-up'::text, 'Disputed'::text, 'Resolved'::text, 'Cancelled'::text]))),
    CONSTRAINT field_workforce_decisions_type_check CHECK ((recommendation_type = ANY (ARRAY['leave_reconciliation'::text, 'payroll_deduction'::text])))
);

ALTER TABLE public.field_workforce_compliance_decisions OWNER TO postgres;

