    CONSTRAINT field_workforce_imports_sheet_name_not_blank CHECK ((btrim(sheet_name) <> ''::text)),
    CONSTRAINT field_workforce_imports_source_filename_not_blank CHECK ((btrim(source_filename) <> ''::text)),
    CONSTRAINT field_workforce_imports_status_check CHECK ((status = ANY (ARRAY['archived'::text, 'superseded'::text]))),
    CONSTRAINT field_workforce_imports_year_range CHECK (((year >= 2000) AND (year <= 2100)))
);

ALTER TABLE public.field_workforce_compliance_imports OWNER TO postgres;

