--
-- Name: headwind_enrollment_template; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.headwind_enrollment_template (
    id smallint NOT NULL,
    template_name text,
    qr_payload text NOT NULL,
    updated_by text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    configuration_id integer,
    configuration_name text,
    CONSTRAINT headwind_enrollment_template_configuration_id_check CHECK (((configuration_id IS NULL) OR (configuration_id > 0)))
);

ALTER TABLE public.headwind_enrollment_template OWNER TO postgres;

--
-- Name: TABLE headwind_enrollment_template; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.headwind_enrollment_template IS 'The Android provisioning JSON from the company''s own Headwind MDM server, one row per set of tablet rules (configuration_id), copied once from its console because the code pins the agent APK by signature checksum and cannot be minted elsewhere. The row with configuration_id NULL (id = 1) predates per-line rules and is kept as it was. CREDENTIAL: scanning it enrolls a tablet into the company fleet with the agent as device owner — service-role only, never logged, never audited.';

--
-- Name: COLUMN headwind_enrollment_template.qr_payload; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.headwind_enrollment_template.qr_payload IS 'The provisioning JSON exactly as Headwind generated it, re-serialised after validation. Phoenix renders it as a QR and never alters the com.hmdm.* admin extras bundle inside it.';

--
-- Name: COLUMN headwind_enrollment_template.updated_by; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.headwind_enrollment_template.updated_by IS 'Who last saved it — the acting HR id, employee identity or login, as the audit row records.';

--
-- Name: COLUMN headwind_enrollment_template.configuration_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.headwind_enrollment_template.configuration_id IS 'The Headwind configuration this code enrolls a tablet onto. Unique: each set of rules has its own QR key in Headwind, so each has exactly one code. NULL only on the pre-2026-11-09 row (id = 1).';

--
-- Name: COLUMN headwind_enrollment_template.configuration_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.headwind_enrollment_template.configuration_name IS 'The name of that configuration when the code was saved. Read only when the configuration is no longer on the Headwind server; otherwise the live name is shown.';

--
-- Name: headwind_enrollment_template_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.headwind_enrollment_template_id_seq
    AS smallint
    START WITH 2
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.headwind_enrollment_template_id_seq OWNER TO postgres;

--
-- Name: headwind_enrollment_template_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: postgres
--

ALTER SEQUENCE public.headwind_enrollment_template_id_seq OWNED BY public.headwind_enrollment_template.id;

--
-- Name: hiring_document_definitions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_document_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    display_order integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    hiring_pack_document text,
    is_exit_document boolean DEFAULT false NOT NULL,
    document_group text DEFAULT 'required'::text NOT NULL,
    sheet_header text,
    joining_form_upload text,
    CONSTRAINT hiring_document_definitions_document_group_check CHECK ((document_group = ANY (ARRAY['required'::text, 'onboarding'::text, 'offboarding'::text]))),
    CONSTRAINT hiring_document_definitions_hiring_pack_document_known CHECK (((hiring_pack_document IS NULL) OR (hiring_pack_document = ANY (ARRAY['contract'::text, 'form1'::text, 'nda'::text, 'form6'::text, 'resignation'::text, 'mutualTermination'::text, 'clearanceEmployee'::text, 'clearanceCompany'::text])))),
    CONSTRAINT hiring_document_definitions_joining_form_upload_known CHECK (((joining_form_upload IS NULL) OR (joining_form_upload = ANY (ARRAY['national_id'::text, 'photo'::text]))))
);

ALTER TABLE public.hiring_document_definitions OWNER TO postgres;

--
-- Name: COLUMN hiring_document_definitions.hiring_pack_document; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_document_definitions.hiring_pack_document IS 'Which built-in hiring-pack paper is filed into this slot when its signature is confirmed: one of contract, form1, form6, resignation, mutualTermination, clearanceEmployee, clearanceCompany. NULL means no paper files here automatically. Deliberately a column rather than a match on `name`, which is admin-editable free text — renaming a slot must not silently stop the filing. Company templates point the other way, via hiring_pack_custom_templates.files_under_document_id, because there are unboundedly many of them.';

--
-- Name: COLUMN hiring_document_definitions.is_exit_document; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_document_definitions.is_exit_document IS 'True when this document only applies once somebody leaves (clearances, resignation, Form 6). Such a document is not counted against an employee whose lifecycle status is active or on_leave.';

--
-- Name: COLUMN hiring_document_definitions.document_group; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_document_definitions.document_group IS 'Which block of the personnel file this paper belongs to: required (the candidate brings it), onboarding (signed on joining), offboarding (signed on leaving). Drives the section bands on the Employee Master sheet. Not the same question as is_exit_document, which decides whether an ACTIVE employee is chased for it.';

--
-- Name: COLUMN hiring_document_definitions.sheet_header; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_document_definitions.sheet_header IS 'What the Employee Master sheet prints as this document''s column header, when it differs from the computed "<name> (document)". Null for almost every row. It MUST still contain "(document)" — the builder ignores an override that does not, because that suffix is what keeps a document name out of the upload''s field alias table.';

--
-- Name: COLUMN hiring_document_definitions.joining_form_upload; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_document_definitions.joining_form_upload IS 'Which candidate upload on the offer joining form is filed into this slot: national_id (ticks it) or photo (filed, never ticks). NULL means nothing from the joining form files here. A column rather than a match on `name`, which is admin-editable free text.';

--
-- Name: hiring_document_employee_notes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_document_employee_notes (
    employee_hr_id text NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.hiring_document_employee_notes OWNER TO postgres;

--
-- Name: hiring_document_files; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_document_files (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_hr_id text NOT NULL,
    document_id uuid NOT NULL,
    storage_bucket text DEFAULT 'hiring-documents'::text NOT NULL,
    storage_path text NOT NULL,
    file_name text NOT NULL,
    content_type text NOT NULL,
    size_bytes integer NOT NULL,
    page_count integer,
    source text DEFAULT 'upload'::text NOT NULL,
    uploaded_by_hr_id text,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hiring_document_files_page_count_check CHECK (((page_count IS NULL) OR (page_count > 0))),
    CONSTRAINT hiring_document_files_size_bytes_check CHECK ((size_bytes > 0)),
    CONSTRAINT hiring_document_files_source_check CHECK ((source = ANY (ARRAY['upload'::text, 'scan'::text, 'issued'::text])))
);

ALTER TABLE public.hiring_document_files OWNER TO postgres;

--
-- Name: TABLE hiring_document_files; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.hiring_document_files IS 'Scans, photos and PDFs proving a hiring document was actually handed over. Private bucket; read only through the server-side file route.';

--
-- Name: COLUMN hiring_document_files.source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_document_files.source IS 'How this file came to be here. upload = a file somebody chose. scan = pages photographed and assembled into a PDF. issued = a paper this system generated for this employee and filed when its signature was confirmed — the document that was signed, never a photograph of the ink. The three are deliberately distinguishable: the slots these land in are named "Signed ...", and whoever opens one is entitled to know which they are looking at.';

--
-- Name: hiring_document_statuses; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_document_statuses (
    employee_hr_id text NOT NULL,
    document_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    due_date date,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hiring_document_statuses_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'submitted'::text, 'missing'::text])))
);

ALTER TABLE public.hiring_document_statuses OWNER TO postgres;

--
-- Name: hiring_joiner_contacts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_joiner_contacts (
