    storage_path text NOT NULL,
    content_type text NOT NULL,
    size_bytes integer NOT NULL,
    width_px integer NOT NULL,
    height_px integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hiring_pack_custom_template_pages_height_px_check CHECK ((height_px > 0)),
    CONSTRAINT hiring_pack_custom_template_pages_page_index_check CHECK ((page_index >= 0)),
    CONSTRAINT hiring_pack_custom_template_pages_size_bytes_check CHECK ((size_bytes > 0)),
    CONSTRAINT hiring_pack_custom_template_pages_width_px_check CHECK ((width_px > 0))
);

ALTER TABLE public.hiring_pack_custom_template_pages OWNER TO postgres;

--
-- Name: TABLE hiring_pack_custom_template_pages; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.hiring_pack_custom_template_pages IS 'One row per printed side of a custom template. storage_path points into the private hiring-pack-templates bucket; the artwork is served through an authenticated route, never a public URL.';

--
-- Name: hiring_pack_custom_templates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_pack_custom_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    key uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    name_ar text,
    page_width_pt numeric(10,2) NOT NULL,
    page_height_pt numeric(10,2) NOT NULL,
    status text DEFAULT 'current'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    effective_from date DEFAULT ((now() AT TIME ZONE 'Africa/Cairo'::text))::date NOT NULL,
    superseded_on date,
    superseded_by uuid,
    note text,
    printable_by_roles text[],
    applies_to jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_hr_id text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_hr_id text,
    document_group text DEFAULT 'other'::text NOT NULL,
    default_copies smallint DEFAULT 1 NOT NULL,
    print_sides text DEFAULT 'single'::text NOT NULL,
    files_under_document_id uuid,
    CONSTRAINT hiring_pack_custom_templates_archived_has_successor CHECK ((((status = 'current'::text) AND (superseded_by IS NULL)) OR ((status = 'archived'::text) AND (superseded_by IS NOT NULL)))),
    CONSTRAINT hiring_pack_custom_templates_default_copies_range CHECK (((default_copies >= 1) AND (default_copies <= 10))),
    CONSTRAINT hiring_pack_custom_templates_group_known CHECK ((document_group = ANY (ARRAY['joining'::text, 'leaving'::text, 'other'::text]))),
    CONSTRAINT hiring_pack_custom_templates_name_check CHECK ((length(btrim(name)) > 0)),
    CONSTRAINT hiring_pack_custom_templates_not_self_superseded CHECK (((superseded_by IS NULL) OR (superseded_by <> id))),
    CONSTRAINT hiring_pack_custom_templates_page_height_pt_check CHECK ((page_height_pt > (0)::numeric)),
    CONSTRAINT hiring_pack_custom_templates_page_width_pt_check CHECK ((page_width_pt > (0)::numeric)),
    CONSTRAINT hiring_pack_custom_templates_print_sides_known CHECK ((print_sides = ANY (ARRAY['single'::text, 'double'::text]))),
    CONSTRAINT hiring_pack_custom_templates_status_check CHECK ((status = ANY (ARRAY['current'::text, 'archived'::text]))),
    CONSTRAINT hiring_pack_custom_templates_supersede_pair CHECK (((superseded_on IS NULL) = (superseded_by IS NULL))),
    CONSTRAINT hiring_pack_custom_templates_version_check CHECK ((version > 0))
);

ALTER TABLE public.hiring_pack_custom_templates OWNER TO postgres;

--
-- Name: TABLE hiring_pack_custom_templates; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.hiring_pack_custom_templates IS 'Company templates uploaded through the HR Forms UI: one row per VERSION, mirroring template-registry.ts. `key` is the stable document identity (HiringPackDocument custom:<key>); `id` is this version''s identity and is the template_version_id the field layer scopes to. Archived versions are never deleted — a paper somebody signed has to stay reproducible as the document they signed.';

--
-- Name: COLUMN hiring_pack_custom_templates.key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_custom_templates.key IS 'Stable across versions. custom:<key> is the HiringPackDocument value, the slot `contract` or `form1` occupies for a built-in.';

--
-- Name: COLUMN hiring_pack_custom_templates.printable_by_roles; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_custom_templates.printable_by_roles IS 'Extra restriction ON TOP of the employee_documents permission. NULL means no extra restriction; an empty array means nobody.';

--
-- Name: COLUMN hiring_pack_custom_templates.document_group; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_custom_templates.document_group IS 'Which package this template prints in: joining (New hires), leaving (Leaver), or other. Set at upload and carried per version, so a template that changed package between versions still prints in the package it was in when it was signed.';

--
-- Name: COLUMN hiring_pack_custom_templates.default_copies; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_custom_templates.default_copies IS 'How many copies this template prints when nobody types a different number. Enforced by the print route. 1 to 10; the largest built-in paper is 2.';

--
-- Name: COLUMN hiring_pack_custom_templates.print_sides; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_custom_templates.print_sides IS 'single = one side per sheet, double = printed back-to-back. DISPLAYED, never enforced: no web API can set a printer duplex, so this is the instruction shown beside the Print button.';

--
-- Name: COLUMN hiring_pack_custom_templates.files_under_document_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_custom_templates.files_under_document_id IS 'Which hiring-document checklist slot a confirmed copy of this paper is filed under. NULL means it prints but is not filed. Deliberately a pointer at an EXISTING definition rather than one created per template: the hiring-documents dashboard is every employee crossed with every active definition, so inventing a slot here would assert a new missing document against every employee in the company.';

--
-- Name: hiring_pack_document_field_history; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_pack_document_field_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    field_id uuid NOT NULL,
    document text NOT NULL,
    template_version_id text NOT NULL,
    employee_hr_id text,
    default_key text,
    action text NOT NULL,
    hidden boolean NOT NULL,
    page smallint,
    anchor_selector text,
    anchor_dx numeric(8,2),
    anchor_dy numeric(8,2),
    x numeric(8,2) NOT NULL,
    y numeric(8,2) NOT NULL,
    w numeric(8,2) NOT NULL,
    h numeric(8,2) NOT NULL,
    align text NOT NULL,
    font_size numeric(5,2) NOT NULL,
    source_kind text NOT NULL,
    value_key text,
    literal_text text,
    was_updated_at timestamp with time zone NOT NULL,
    was_updated_by_hr_id text,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    changed_by_hr_id text,
    CONSTRAINT hiring_pack_document_field_history_action_known CHECK ((action = ANY (ARRAY['update'::text, 'delete'::text]))),
    CONSTRAINT hiring_pack_document_field_history_actor_upper CHECK (((changed_by_hr_id IS NULL) OR (changed_by_hr_id = upper(changed_by_hr_id)))),
    CONSTRAINT hiring_pack_document_field_history_was_actor_upper CHECK (((was_updated_by_hr_id IS NULL) OR (was_updated_by_hr_id = upper(was_updated_by_hr_id))))
);

ALTER TABLE public.hiring_pack_document_field_history OWNER TO postgres;

--
-- Name: TABLE hiring_pack_document_field_history; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.hiring_pack_document_field_history IS 'Append-only record of every superseded state of a hiring-pack field row: one row per update and per delete, holding the PREVIOUS source and geometry in full. Written by a trigger on hiring_pack_document_fields so no write path can forget it, including a bulk reset and hand-run SQL. field_id is deliberately NOT a foreign key — a cascade would erase exactly what a deletion exists to record, and it would run as the table owner, straight past the revokes. Inserts are not recorded: the live row''s created_at already says when a field was added. changed_by_hr_id is NULL on a delete on purpose — the only name available there is whoever last edited the field, not who deleted it.';

--
-- Name: COLUMN hiring_pack_document_field_history.changed_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_document_field_history.changed_by_hr_id IS 'Who superseded this state, on an update only. NULL on a delete: there is no incoming row to read an actor off, and the last editor is not the deleter. Read the timestamp, not the name — updated_by_hr_id is known to be unreliable across this system.';

--
-- Name: hiring_pack_document_fields; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_pack_document_fields (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    document text NOT NULL,
    template_version_id text NOT NULL,
    employee_hr_id text,
    default_key text,
    hidden boolean DEFAULT false NOT NULL,
    page smallint,
    anchor_selector text,
    anchor_dx numeric(8,2),
    anchor_dy numeric(8,2),
    x numeric(8,2) DEFAULT 0 NOT NULL,
    y numeric(8,2) DEFAULT 0 NOT NULL,
    w numeric(8,2) NOT NULL,
    h numeric(8,2) NOT NULL,
    align text DEFAULT 'right'::text NOT NULL,
    font_size numeric(5,2) DEFAULT 9 NOT NULL,
    source_kind text NOT NULL,
    value_key text,
    literal_text text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_hr_id text,
    updated_by_hr_id text,
    CONSTRAINT hiring_pack_document_fields_align_known CHECK ((align = ANY (ARRAY['right'::text, 'center'::text, 'left'::text]))),
    CONSTRAINT hiring_pack_document_fields_box_real CHECK (((w > (0)::numeric) AND (h > (0)::numeric) AND (font_size > (0)::numeric))),
    CONSTRAINT hiring_pack_document_fields_created_by_upper CHECK (((created_by_hr_id IS NULL) OR (created_by_hr_id = upper(created_by_hr_id)))),
    CONSTRAINT hiring_pack_document_fields_document_known CHECK (((document = ANY (ARRAY['contract'::text, 'form1'::text, 'workerDataForm'::text, 'custodyLaptop'::text, 'custodyMobile'::text, 'nda'::text, 'appointmentDocsReceipt'::text, 'socialStatusSheet'::text, 'absenceWarning'::text, 'deemedResignation'::text, 'disciplinaryWarning'::text, 'disciplinaryPenalty'::text, 'transferDecision'::text, 'salaryAdjustment'::text, 'socialInsuranceAuthorization'::text, 'healthInsuranceAuthorization'::text, 'insurancePrintLetter'::text, 'appointmentDocsReturn'::text, 'experienceCertificate'::text, 'experienceCertificateEn'::text, 'handoverRecord'::text, 'exitInterview'::text, 'salaryLetterEn'::text, 'salaryLetterAr'::text, 'maternityCompensation'::text, 'insuranceForm2'::text, 'carInsuranceCertificate'::text, 'wageProgressSheet'::text, 'officialHolidaysSheet'::text, 'sickLeaveSheet'::text, 'penaltiesSheet'::text, 'penaltyRegulationsApproval'::text, 'contractRenewal'::text, 'contractNonRenewal'::text, 'form6'::text, 'resignation'::text, 'mutualTermination'::text, 'clearanceEmployee'::text, 'clearanceCompany'::text])) OR (document ~* '^custom:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text))),
    CONSTRAINT hiring_pack_document_fields_employee_hr_id_upper CHECK (((employee_hr_id IS NULL) OR (employee_hr_id = upper(employee_hr_id)))),
    CONSTRAINT hiring_pack_document_fields_hide_is_an_override CHECK (((hidden = false) OR (default_key IS NOT NULL))),
    CONSTRAINT hiring_pack_document_fields_mark_is_an_addition CHECK (((source_kind <> 'mark'::text) OR (default_key IS NULL))),
    CONSTRAINT hiring_pack_document_fields_override_or_addition CHECK (((default_key IS NULL) OR (length(btrim(default_key)) > 0))),
    CONSTRAINT hiring_pack_document_fields_page_positive CHECK (((page IS NULL) OR (page >= 1))),
    CONSTRAINT hiring_pack_document_fields_placed_once CHECK ((((page IS NOT NULL) AND (anchor_selector IS NULL)) OR ((page IS NULL) AND (anchor_selector IS NOT NULL) AND (anchor_dx IS NOT NULL) AND (anchor_dy IS NOT NULL)))),
    CONSTRAINT hiring_pack_document_fields_source_paired CHECK ((((source_kind = 'value'::text) AND (value_key IS NOT NULL) AND (length(btrim(value_key)) > 0) AND (literal_text IS NULL)) OR ((source_kind = 'literal'::text) AND (literal_text IS NOT NULL) AND (value_key IS NULL)) OR ((source_kind = 'mark'::text) AND (value_key = ANY (ARRAY['stamp'::text, 'signature'::text])) AND (literal_text IS NULL)))),
    CONSTRAINT hiring_pack_document_fields_updated_by_upper CHECK (((updated_by_hr_id IS NULL) OR (updated_by_hr_id = upper(updated_by_hr_id))))
);

ALTER TABLE public.hiring_pack_document_fields OWNER TO postgres;

--
-- Name: TABLE hiring_pack_document_fields; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.hiring_pack_document_fields IS 'The hiring pack''s field layer: an OVERLAY on the compiled layout tables in src/lib/hiring-pack/*-layout.ts. A row moves a compiled placement, hides one, or adds a field that was never compiled. Scoped to a template version so an archived document reprints with the layout it was signed under, and so a flow-surface CSS anchor stays valid. employee_hr_id NULL means every employee, which is all the editor writes today. Reset = delete the rows; the compiled tables are the default and the measurement.';

--
-- Name: COLUMN hiring_pack_document_fields.document; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_document_fields.document IS 'Which document these coordinates belong to: one of the built-in papers in HIRING_PACK_DOCUMENTS (src/lib/hiring-pack/types.ts), or a company template as custom:<uuid> where the uuid is the template''s stable key. The CHECK constraint mirrors asPrintableDocument in src/lib/hiring-pack/document-registry.ts, and tests/hiring-pack-field-layout.test.ts pins the list.';

--
-- Name: COLUMN hiring_pack_document_fields.default_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_document_fields.default_key IS 'The compiled placement this row overrides, by key. NULL = the row adds a field no compiled table has. An override naming a key the current template version no longer declares is IGNORED at render time, never promoted to a new field — its coordinates refer to artwork nobody has re-checked.';

--
-- Name: COLUMN hiring_pack_document_fields.anchor_selector; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_document_fields.anchor_selector IS 'Flow surfaces only (contract, workerDataForm, custody*, clearance*). A CSS path into the rendered document, with anchor_dx/dy as an offset in points. Typeset documents flow across pages, so a page coordinate would drift the moment a longer name moved a page break; an anchored field travels with its clause instead. Stable because a template version''s markup never changes.';

--
-- Name: COLUMN hiring_pack_document_fields.source_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.hiring_pack_document_fields.source_kind IS 'What the field prints. ''value'' reads the employee''s record through the same values map every compiled placement reads. ''literal'' prints a fixed string and must never look like data. ''mark'' prints a PICTURE - the company stamp or the stored HR signature, named in value_key - placed by hand by an operator; no compiled table and no renderer ever produces one, which is what separates it from the auto-drawn seal the owner removed on 2026-09-29.';

--
-- Name: hiring_pack_paper_register_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.hiring_pack_paper_register_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.hiring_pack_paper_register_seq OWNER TO postgres;

--
-- Name: hiring_pack_paper_register; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hiring_pack_paper_register (
    id bigint NOT NULL,
    reference text DEFAULT ((('HR-'::text || to_char((now() AT TIME ZONE 'Africa/Cairo'::text), 'YYYY'::text)) || '-'::text) || lpad((nextval('public.hiring_pack_paper_register_seq'::regclass))::text, 6, '0'::text)) NOT NULL,
    document text NOT NULL,
    document_label text NOT NULL,
    hr_id text,
    subject_name text,
    mode text NOT NULL,
    copies integer DEFAULT 1 NOT NULL,
    issued_by_hr_id text,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hiring_pack_paper_register_copies CHECK (((copies >= 1) AND (copies <= 20))),
    CONSTRAINT hiring_pack_paper_register_document_not_blank CHECK ((btrim(document) <> ''::text)),
    CONSTRAINT hiring_pack_paper_register_mode CHECK ((mode = ANY (ARRAY['employee'::text, 'manual'::text])))
);

ALTER TABLE public.hiring_pack_paper_register OWNER TO postgres;

--
-- Name: TABLE hiring_pack_paper_register; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.hiring_pack_paper_register IS 'One row per paper printed from HR Forms; the reference column is the number printed on the paper. Written by the app through the service role only. Never renumber or delete a row: a printed paper carrying that number may already be signed and filed.';

--
-- Name: hiring_pack_paper_register_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.hiring_pack_paper_register ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.hiring_pack_paper_register_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: hr_clearance_checklists; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hr_clearance_checklists (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    resignation_id uuid NOT NULL,
