    line_name text,
    last_working_date date,
    status text DEFAULT 'open'::text NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    opened_by text,
    ready_at timestamp with time zone,
    settlement_released_at timestamp with time zone,
    settlement_released_by text,
    settlement_note text,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hr_clearance_checklists_status_check CHECK ((status = ANY (ARRAY['open'::text, 'ready'::text, 'released'::text, 'cancelled'::text])))
);

ALTER TABLE public.hr_clearance_checklists OWNER TO postgres;

--
-- Name: hr_clearance_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.hr_clearance_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    checklist_id uuid NOT NULL,
    station_key text NOT NULL,
    station_label text NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reason text,
    amount_due numeric(12,2),
    evidence_note text,
    decided_at timestamp with time zone,
    decided_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
