    CONSTRAINT hr_ops_report_lines_decided_days_check CHECK ((((decision = 'approved'::text) AND (decided_days IS NOT NULL) AND (decided_days >= (0)::numeric)) OR ((COALESCE(decision, ''::text) <> 'approved'::text) AND (decided_days IS NULL)))),
