    CONSTRAINT hr_ops_report_lines_review_reason_check CHECK (((review_action IS NULL) OR (review_action = 'confirm'::text) OR (NULLIF(btrim(COALESCE(review_reason, ''::text)), ''::text) IS NOT NULL))),
