--
-- Name: ireports360_visits_effective; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.ireports360_visits_effective WITH (security_invoker='true') AS
 SELECT v.id,
    v.crm_visit_id,
    v.visit_date,
    v.agent_crm_id,
    v.agent_name,
    v.agent_hr_id,
    v.double_crm_id,
    v.double_name,
    v.double_hr_id,
    v.contact_crm_id,
    v.contact_name,
    v.customer_name,
    v.comment,
    v.visit_type,
    v.visit_type_description,
    v.call_type,
    v.ampm,
    v.attendance,
    v.crm_save_date,
    v.raw_payload,
    v.synced_at,
    v.created_at,
    v.updated_at,
    v.visit_date_time,
    v.crm_region_id,
    v.crm_region_name,
    v.speciality,
    v.crm_contact_grade,
    ck.has_checkin,
    ((v.visit_type = 0) AND (NOT ck.has_checkin)) AS reclassified_no_checkin,
        CASE
            WHEN ((v.visit_type = 0) AND (NOT ck.has_checkin)) THEN '-8'::integer
            ELSE v.visit_type
        END AS effective_visit_type
   FROM (public.ireports360_visits v
     CROSS JOIN LATERAL ( SELECT (EXISTS ( SELECT 1
                   FROM public.ireports360_checkins c
                  WHERE ((c.agent_crm_id = v.agent_crm_id) AND (c.contact_crm_id = v.contact_crm_id) AND (c.check_date >= (v.visit_date)::timestamp without time zone) AND (c.check_date < ((v.visit_date + 1))::timestamp without time zone)))) AS has_checkin) ck);

ALTER VIEW public.ireports360_visits_effective OWNER TO postgres;

