    rows_deleted integer DEFAULT 0 NOT NULL,
    rows_skipped_invalid_date integer DEFAULT 0 NOT NULL,
    rows_skipped_reconcile integer DEFAULT 0 NOT NULL,
    blocked_post_exit_attributions integer DEFAULT 0 NOT NULL,
    blocked_pre_hire_attributions integer DEFAULT 0 NOT NULL,
    CONSTRAINT ireports360_visits_sync_runs_date_range_check CHECK ((date_to >= date_from)),
    CONSTRAINT ireports360_visits_sync_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'success'::text, 'failed'::text]))),
    CONSTRAINT ireports360_visits_sync_runs_trigger_check CHECK ((trigger = ANY (ARRAY['cron'::text, 'manual_backfill'::text, 'manual'::text])))
);

ALTER TABLE public.ireports360_visits_sync_runs OWNER TO postgres;

--
-- Name: TABLE ireports360_visits_sync_runs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.ireports360_visits_sync_runs IS 'Audit log of each iReports360 sync attempt (scheduled or manual backfill), so sync freshness/failures are visible instead of silent.';

--
-- Name: COLUMN ireports360_visits_sync_runs.rows_deleted; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits_sync_runs.rows_deleted IS 'Rows removed from ireports360_visits by this run''s delete-reconciliation: present in the mirror for this run''s [date_from, date_to] window but absent from the fresh CRM fetch, so voided/deleted upstream.';

--
-- Name: COLUMN ireports360_visits_sync_runs.rows_skipped_invalid_date; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits_sync_runs.rows_skipped_invalid_date IS 'Visits this run fetched but did not upsert because the CRM returned a missing/invalid visitDate.';

--
-- Name: COLUMN ireports360_visits_sync_runs.rows_skipped_reconcile; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits_sync_runs.rows_skipped_reconcile IS 'Stale rows this run found but did NOT delete because they exceeded the 50% sanity cap on the window''s existing rows — signals the fetch may have been partial/truncated rather than reflecting real CRM deletions. Investigate rather than assume these are safe to delete.';

--
-- Name: COLUMN ireports360_visits_sync_runs.blocked_post_exit_attributions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits_sync_runs.blocked_post_exit_attributions IS 'Visits this run refused to attribute because the CRM account resolved to an employee whose last working date precedes the visit date (see resolveEmployeeAttribution). >0 means a CRM account was probably handed to a replacement and needs an identity override, or the new rep''s work goes invisible. Rows created before 2026-08-01 carry 0 because the value was not captured then — read those as unknown, not as verified clean.';

--
-- Name: COLUMN ireports360_visits_sync_runs.blocked_pre_hire_attributions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.ireports360_visits_sync_runs.blocked_pre_hire_attributions IS 'Visits this run refused to credit because they are dated BEFORE the employee''s hire date. The counterpart to blocked_post_exit_attributions: both are the same account-handover bug seen from opposite ends, where the CRM admin hands a departing rep''s account to their replacement instead of creating a new one.';

--
-- Name: job_heartbeats; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.job_heartbeats (
    slug text NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_outcome text,
    last_success_at timestamp with time zone,
    last_fail_at timestamp with time zone,
    last_detail text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT job_heartbeats_last_outcome_check CHECK ((last_outcome = ANY (ARRAY['success'::text, 'fail'::text]))),
    CONSTRAINT job_heartbeats_slug_check CHECK ((char_length(TRIM(BOTH FROM slug)) > 0))
);

ALTER TABLE public.job_heartbeats OWNER TO postgres;

--
-- Name: TABLE job_heartbeats; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.job_heartbeats IS 'In-house dead-man''s switch. One row per scheduled job slug, recording what that job LAST REPORTED ABOUT ITSELF. A stale row means nothing has reported since — it is never an observation that the job is or is not running. Written by pingDeadMansSwitch(); swept by /api/cron/job-heartbeat-sweep.';

--
-- Name: COLUMN job_heartbeats.first_seen_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.job_heartbeats.first_seen_at IS 'Bootstrap anchor. A declared job that has never reported is not stranded until a scheduled fire has passed since this moment — otherwise every newly declared job alarms on deploy.';

--
-- Name: COLUMN job_heartbeats.last_outcome; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.job_heartbeats.last_outcome IS 'NULL = bootstrapped, never reported. ''fail'' = it ran and reported failure. The two are different signals and must not be collapsed.';

--
-- Name: job_leases; Type: TABLE; Schema: public; Owner: postgres
