ALTER TABLE public.job_leases OWNER TO postgres;

--
-- Name: TABLE job_leases; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.job_leases IS 'One row per singleton background loop (e.g. crm-live-poll): the process allowed to run it and until when. Claimed and renewed through claim_job_lease(); an unrenewed lease simply runs out.';

