--
-- Name: mailbox_offboarding_tasks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.mailbox_offboarding_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_hr_id text NOT NULL,
    employee_name text NOT NULL,
    work_email text NOT NULL,
    job_title text,
    last_working_date date,
    status text DEFAULT 'pending'::text NOT NULL,
    password_reset_at timestamp with time zone,
    password_reset_by text,
    app_passwords_cleared_at timestamp with time zone,
    app_passwords_cleared_by text,
    disposition text,
    disposition_at timestamp with time zone,
    disposition_by text,
    forwarding_to text,
    forwarding_expires_on date,
    reason text,
    note text,
    source text DEFAULT 'resignation'::text NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    opened_by text,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mailbox_offboarding_forwarding_target CHECK (((disposition IS DISTINCT FROM 'forwarding'::text) OR ((forwarding_to IS NOT NULL) AND (char_length(TRIM(BOTH FROM forwarding_to)) > 0)))),
    CONSTRAINT mailbox_offboarding_reason_required CHECK (((status <> 'not_applicable'::text) OR ((reason IS NOT NULL) AND (char_length(TRIM(BOTH FROM reason)) > 0)))),
    CONSTRAINT mailbox_offboarding_tasks_disposition_check CHECK (((disposition IS NULL) OR (disposition = ANY (ARRAY['deleted'::text, 'suspended'::text, 'forwarding'::text, 'retained'::text])))),
    CONSTRAINT mailbox_offboarding_tasks_employee_hr_id_check CHECK ((char_length(TRIM(BOTH FROM employee_hr_id)) > 0)),
    CONSTRAINT mailbox_offboarding_tasks_source_check CHECK ((source = ANY (ARRAY['resignation'::text, 'backfill'::text, 'sweep'::text]))),
    CONSTRAINT mailbox_offboarding_tasks_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'revoked'::text, 'not_applicable'::text]))),
    CONSTRAINT mailbox_offboarding_tasks_work_email_check CHECK ((POSITION(('@'::text) IN (work_email)) > 1))
);

ALTER TABLE public.mailbox_offboarding_tasks OWNER TO postgres;

--
-- Name: TABLE mailbox_offboarding_tasks; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.mailbox_offboarding_tasks IS 'Turbify mailbox revocation register for leavers. A row records that a named admin SAID a step was performed at a recorded time — Phoenix cannot verify Turbify, which has no email API.';

--
-- Name: COLUMN mailbox_offboarding_tasks.app_passwords_cleared_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.mailbox_offboarding_tasks.app_passwords_cleared_at IS 'The step that actually cuts IMAP. Yahoo app passwords survive a password change and must be deleted explicitly, so a reset alone leaves phone and Outlook access live.';

