--
-- Name: market_awareness_activities; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.market_awareness_activities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    activity_code text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    requester_hr_id text NOT NULL,
    manager_hr_id text,
    activity_type_id bigint NOT NULL,
    title text,
    venue text,
    city text,
    start_date date NOT NULL,
    end_date date,
    expected_attendees integer,
    speakers text,
    primary_line_id bigint NOT NULL,
    region_code text NOT NULL,
    area_code text NOT NULL,
    currency text DEFAULT 'EGP'::text NOT NULL,
    estimated_cost numeric(14,2) NOT NULL,
    amended_cost numeric(14,2),
    actual_cost numeric(14,2),
    duration_months integer DEFAULT 3 NOT NULL,
    baseline_months integer DEFAULT 3 NOT NULL,
    expected_uplift_pct numeric(6,2),
    finance_paid boolean DEFAULT false NOT NULL,
    finance_marked_at timestamp with time zone,
    finance_marked_by_hr_id text,
    rep_hr_id_at_approval text,
    dm_hr_id_at_approval text,
    executed_at date,
    outcome_note text,
    submitted_at timestamp with time zone,
    approved_at timestamp with time zone,
    rejected_at timestamp with time zone,
    returned_at timestamp with time zone,
    withdrawn_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_by_hr_id text,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    held_by_hr_id text,
    held_at timestamp with time zone,
    hold_reason text,
    step_opened_at timestamp with time zone,
    CONSTRAINT market_awareness_activities_actual_positive CHECK (((actual_cost IS NULL) OR (actual_cost >= (0)::numeric))),
    CONSTRAINT market_awareness_activities_amended_positive CHECK (((amended_cost IS NULL) OR (amended_cost > (0)::numeric))),
    CONSTRAINT market_awareness_activities_area_not_blank CHECK ((btrim(area_code) <> ''::text)),
    CONSTRAINT market_awareness_activities_baseline_range CHECK (((baseline_months >= 1) AND (baseline_months <= 12))),
    CONSTRAINT market_awareness_activities_code_not_blank CHECK ((btrim(activity_code) <> ''::text)),
    CONSTRAINT market_awareness_activities_cost_positive CHECK ((estimated_cost > (0)::numeric)),
    CONSTRAINT market_awareness_activities_dates_ordered CHECK (((end_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT market_awareness_activities_duration_range CHECK (((duration_months >= 1) AND (duration_months <= 12))),
    CONSTRAINT market_awareness_activities_hold_shape CHECK ((((status = 'on_hold'::text) AND (btrim(COALESCE(held_by_hr_id, ''::text)) <> ''::text) AND (held_at IS NOT NULL) AND (btrim(COALESCE(hold_reason, ''::text)) <> ''::text)) OR ((status <> 'on_hold'::text) AND (held_by_hr_id IS NULL) AND (held_at IS NULL) AND (hold_reason IS NULL)))),
    CONSTRAINT market_awareness_activities_region_not_blank CHECK ((btrim(region_code) <> ''::text)),
    CONSTRAINT market_awareness_activities_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_group'::text, 'on_hold'::text, 'pending_ceo'::text, 'returned'::text, 'rejected'::text, 'approved'::text, 'executed'::text, 'closed'::text, 'withdrawn'::text])))
);

ALTER TABLE public.market_awareness_activities OWNER TO postgres;

--
-- Name: TABLE market_awareness_activities; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.market_awareness_activities IS 'One awareness activity: a round table, symposium, workshop, speaker program, sponsorship, ad board or conference, raised by a Product Manager against targeted products in one brick. Holds no sales figure — tracking is read live from source_of_sales_fact_rollup.';

--
-- Name: COLUMN market_awareness_activities.primary_line_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.market_awareness_activities.primary_line_id IS 'The line whose au.line_area_map drives the region -> area -> brick cascade. Several lines may be targeted (see market_awareness_activity_lines) but only one can order the geography, because an area sits in a different region depending on the line.';

--
-- Name: COLUMN market_awareness_activities.amended_cost; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.market_awareness_activities.amended_cost IS 'Set ONLY by the CEO when he approves at a different figure. Nobody approves for the CEO, so this column is written by his decision alone. Payable is coalesce(amended_cost, estimated_cost).';

--
-- Name: COLUMN market_awareness_activities.rep_hr_id_at_approval; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.market_awareness_activities.rep_hr_id_at_approval IS 'Who held the rep seat when this was approved. The screen shows TODAY holder; this column is what lets it say the original was replaced.';

--
-- Name: COLUMN market_awareness_activities.hold_reason; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.market_awareness_activities.hold_reason IS 'Why it was frozen. Required — a hold with no reason is exactly what strands a request, the same way a return with no comment sends a Product Manager to ask in person.';

--
-- Name: COLUMN market_awareness_activities.step_opened_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.market_awareness_activities.step_opened_at IS 'When the CURRENT step started waiting. The nav badge measured lateness from updated_at, which an update trigger stamps on every write — so under a parallel group each partial approval would silently restart the clock for everyone still to answer. Set on entering a step, and advanced by the held duration on release, which is how a hold stops the clock rather than hiding a breach.';

--
-- Name: market_awareness_activity_approvers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.market_awareness_activity_approvers (
    id bigint NOT NULL,
    activity_id uuid NOT NULL,
    approver_role text NOT NULL,
    line_id bigint,
    is_primary_line boolean DEFAULT false NOT NULL,
    assigned_hr_id text,
    decision text,
    decided_by_hr_id text,
    decided_at timestamp with time zone,
    comment text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT market_awareness_approvers_decided_attributed CHECK (((decision IS NULL) OR ((btrim(COALESCE(decided_by_hr_id, ''::text)) <> ''::text) AND (decided_at IS NOT NULL)))),
    CONSTRAINT market_awareness_approvers_decision_check CHECK (((decision IS NULL) OR (decision = ANY (ARRAY['approve'::text, 'reject'::text, 'return'::text])))),
    CONSTRAINT market_awareness_approvers_line_shape CHECK ((((approver_role = 'nsm'::text) AND (line_id IS NOT NULL)) OR ((approver_role = 'marketing_manager'::text) AND (line_id IS NULL)))),
    CONSTRAINT market_awareness_approvers_role_check CHECK ((approver_role = ANY (ARRAY['marketing_manager'::text, 'nsm'::text])))
);

ALTER TABLE public.market_awareness_activity_approvers OWNER TO postgres;

--
-- Name: TABLE market_awareness_activity_approvers; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.market_awareness_activity_approvers IS 'The parallel approval group for one awareness activity: the Marketing Manager plus one National Sales Manager per targeted line, all asked at the same time. A slot is a ROLE and a LINE, not a person — the assigned holder is who it was sent to, and anyone currently holding that role for that line may answer it, which is what lets a stand-in clear the queue while somebody is on leave. Rebuilt from scratch on every resubmission, because a return resets the group.';

--
-- Name: market_awareness_activity_approvers_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.market_awareness_activity_approvers ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.market_awareness_activity_approvers_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

