ALTER TABLE public.market_awareness_activity_lines OWNER TO postgres;

--
-- Name: TABLE market_awareness_activity_lines; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.market_awareness_activity_lines IS 'Every line this activity targets, including the primary one. Tracking reports each line APART — never summed, because units of different products are never added and the two lines geography differs.';

--
-- Name: market_awareness_activity_lines_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
