    CACHE 1
);

--
-- Name: market_awareness_activity_types; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.market_awareness_activity_types (
    id bigint NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    sort_order integer DEFAULT 100 NOT NULL,
    active boolean DEFAULT true NOT NULL,
