    captured_latitude double precision,
    captured_longitude double precision,
    captured_accuracy_meters double precision,
    captured_at timestamp with time zone,
    evidence_photo_name text,
    evidence_photo_captured_at timestamp with time zone,
    evidence_has_timestamp boolean DEFAULT false NOT NULL,
    evidence_status text DEFAULT 'missing'::text NOT NULL,
    validation_status text DEFAULT 'pending'::text NOT NULL,
    validated_by_hr_id text,
