    chosen_area_name text,
    crm_list_source text,
    CONSTRAINT marketing_customers_accuracy_check CHECK (((captured_accuracy_meters IS NULL) OR (captured_accuracy_meters >= (0)::double precision))),
    CONSTRAINT marketing_customers_code_not_blank CHECK ((btrim(customer_code) <> ''::text)),
    CONSTRAINT marketing_customers_crm_list_source_check CHECK (((crm_list_source IS NULL) OR (crm_list_source = ANY (ARRAY['picked'::text, 'typed'::text, 'checked'::text])))),
    CONSTRAINT marketing_customers_crm_list_status_check CHECK (((crm_list_status IS NULL) OR (crm_list_status = ANY (ARRAY['on_list'::text, 'not_on_list'::text])))),
    CONSTRAINT marketing_customers_evidence_status_check CHECK ((evidence_status = ANY (ARRAY['missing'::text, 'pending'::text, 'complete'::text]))),
    CONSTRAINT marketing_customers_latitude_check CHECK (((captured_latitude IS NULL) OR ((captured_latitude >= ('-90'::integer)::double precision) AND (captured_latitude <= (90)::double precision)))),
    CONSTRAINT marketing_customers_longitude_check CHECK (((captured_longitude IS NULL) OR ((captured_longitude >= ('-180'::integer)::double precision) AND (captured_longitude <= (180)::double precision)))),
    CONSTRAINT marketing_customers_merged_not_self_check CHECK (((merged_into_customer_id IS NULL) OR (merged_into_customer_id <> id))),
    CONSTRAINT marketing_customers_name_not_blank CHECK ((btrim(display_name) <> ''::text)),
    CONSTRAINT marketing_customers_normalized_not_blank CHECK ((btrim(normalized_name) <> ''::text)),
    CONSTRAINT marketing_customers_type_check CHECK ((customer_type = ANY (ARRAY['doctor'::text, 'hospital'::text, 'clinic'::text, 'account'::text, 'other'::text]))),
    CONSTRAINT marketing_customers_validation_status_check CHECK ((validation_status = ANY (ARRAY['pending'::text, 'system_validated'::text, 'sfe_validated'::text, 'rejected'::text])))
);

