--
-- Name: marketing_pharmacies; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.marketing_pharmacies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pharmacy_code text NOT NULL,
    display_name text NOT NULL,
    normalized_name text NOT NULL,
    owner_hr_id text,
    manager_hr_id text,
    line_id bigint,
    area_id bigint,
    region_name text,
    extracted_area_name text,
    extracted_governorate_name text,
    captured_address text,
    captured_latitude double precision,
    captured_longitude double precision,
    captured_accuracy_meters double precision,
    captured_at timestamp with time zone,
    evidence_photo_name text,
    evidence_photo_captured_at timestamp with time zone,
    evidence_has_timestamp boolean DEFAULT false NOT NULL,
    evidence_status text DEFAULT 'missing'::text NOT NULL,
    validation_status text DEFAULT 'pending'::text NOT NULL,
    validated_by_hr_id text,
    validated_at timestamp with time zone,
    validation_notes text,
    active boolean DEFAULT true NOT NULL,
    created_by_hr_id text,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    venue_type text DEFAULT 'pharmacy'::text NOT NULL,
    merged_into_pharmacy_id uuid,
    merged_at timestamp with time zone,
    merged_by_hr_id text,
    license_name_matches_sign boolean,
    license_name_checked_by_hr_id text,
    license_name_checked_at timestamp with time zone,
    CONSTRAINT marketing_pharmacies_accuracy_check CHECK (((captured_accuracy_meters IS NULL) OR (captured_accuracy_meters >= (0)::double precision))),
    CONSTRAINT marketing_pharmacies_code_not_blank CHECK ((btrim(pharmacy_code) <> ''::text)),
    CONSTRAINT marketing_pharmacies_evidence_status_check CHECK ((evidence_status = ANY (ARRAY['missing'::text, 'pending'::text, 'complete'::text]))),
    CONSTRAINT marketing_pharmacies_latitude_check CHECK (((captured_latitude IS NULL) OR ((captured_latitude >= ('-90'::integer)::double precision) AND (captured_latitude <= (90)::double precision)))),
    CONSTRAINT marketing_pharmacies_license_verdict_check CHECK ((((license_name_matches_sign IS NULL) AND (license_name_checked_by_hr_id IS NULL) AND (license_name_checked_at IS NULL)) OR ((license_name_matches_sign IS NOT NULL) AND (license_name_checked_by_hr_id IS NOT NULL) AND (license_name_checked_at IS NOT NULL)))),
    CONSTRAINT marketing_pharmacies_longitude_check CHECK (((captured_longitude IS NULL) OR ((captured_longitude >= ('-180'::integer)::double precision) AND (captured_longitude <= (180)::double precision)))),
    CONSTRAINT marketing_pharmacies_merged_not_self_check CHECK (((merged_into_pharmacy_id IS NULL) OR (merged_into_pharmacy_id <> id))),
    CONSTRAINT marketing_pharmacies_name_not_blank CHECK ((btrim(display_name) <> ''::text)),
    CONSTRAINT marketing_pharmacies_normalized_not_blank CHECK ((btrim(normalized_name) <> ''::text)),
    CONSTRAINT marketing_pharmacies_validation_status_check CHECK ((validation_status = ANY (ARRAY['pending'::text, 'system_validated'::text, 'sfe_validated'::text, 'rejected'::text]))),
    CONSTRAINT marketing_pharmacies_venue_type_check CHECK ((venue_type = ANY (ARRAY['pharmacy'::text, 'nursery'::text])))
);

ALTER TABLE public.marketing_pharmacies OWNER TO postgres;

--
-- Name: COLUMN marketing_pharmacies.venue_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacies.venue_type IS 'pharmacy (default) or nursery. A nursery has no distributor account, so it may carry zero distributor codes and its customer/request links may hold a NULL distributor_code_id. Sales can never attribute to a nursery — ROI must report it as having no sales channel rather than a zero return.';

--
-- Name: COLUMN marketing_pharmacies.merged_into_pharmacy_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacies.merged_into_pharmacy_id IS 'The surviving venue this duplicate was folded into. Its customer links, request targets and distributor codes were moved there and this row deactivated. NULL for every venue that is not a duplicate, which is nearly all of them. Identity is proven by captured GPS and address, never by a similar name — venue names are typed by hand in two languages and prove nothing on their own.';

--
-- Name: COLUMN marketing_pharmacies.merged_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacies.merged_at IS 'When the merge was performed. NULL unless merged_into_pharmacy_id is set.';

--
-- Name: COLUMN marketing_pharmacies.merged_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacies.merged_by_hr_id IS 'Who performed the merge. NULL for rows backfilled from a duplicate the system had already deactivated, because no person made that call through the application.';

--
-- Name: COLUMN marketing_pharmacies.license_name_matches_sign; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacies.license_name_matches_sign IS 'Approver''s verdict that the trade name on the pharmacy licence matches the shop sign. NULL = never asked.';

--
-- Name: COLUMN marketing_pharmacies.license_name_checked_by_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacies.license_name_checked_by_hr_id IS 'HR id of the approver who compared the licence against the sign. NULL whenever the verdict is NULL.';

--
-- Name: COLUMN marketing_pharmacies.license_name_checked_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacies.license_name_checked_at IS 'When the comparison was recorded. NULL whenever the verdict is NULL.';

--
-- Name: marketing_pharmacy_code_references; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.marketing_pharmacy_code_references (
    id bigint NOT NULL,
    distributor_id bigint,
    raw_distributor_name text NOT NULL,
    normalized_distributor_name text NOT NULL,
    raw_pharmacy_code text NOT NULL,
    raw_pharmacy_address text,
    raw_region text,
    raw_area text,
    source_file text NOT NULL,
    source_row bigint NOT NULL,
    import_batch_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    normalized_pharmacy_code text GENERATED ALWAYS AS (lower(btrim(regexp_replace(COALESCE(raw_pharmacy_code, ''::text), '\s+'::text, ' '::text, 'g'::text)))) STORED,
    compact_pharmacy_code text GENERATED ALWAYS AS (
CASE
    WHEN (lower(btrim(regexp_replace(COALESCE(raw_pharmacy_code, ''::text), '\s+'::text, ' '::text, 'g'::text))) ~ '^[0-9]+$'::text) THEN COALESCE(NULLIF(ltrim(lower(btrim(regexp_replace(COALESCE(raw_pharmacy_code, ''::text), '\s+'::text, ' '::text, 'g'::text))), '0'::text), ''::text), '0'::text)
    ELSE lower(btrim(regexp_replace(COALESCE(raw_pharmacy_code, ''::text), '\s+'::text, ' '::text, 'g'::text)))
END) STORED,
    CONSTRAINT marketing_pharmacy_code_refs_code_not_blank CHECK ((btrim(raw_pharmacy_code) <> ''::text)),
    CONSTRAINT marketing_pharmacy_code_refs_distributor_not_blank CHECK ((btrim(raw_distributor_name) <> ''::text)),
    CONSTRAINT marketing_pharmacy_code_refs_norm_distributor_not_blank CHECK ((btrim(normalized_distributor_name) <> ''::text)),
    CONSTRAINT marketing_pharmacy_code_refs_source_file_not_blank CHECK ((btrim(source_file) <> ''::text)),
    CONSTRAINT marketing_pharmacy_code_refs_source_row_positive CHECK ((source_row > 0))
);

ALTER TABLE public.marketing_pharmacy_code_references OWNER TO postgres;

--
-- Name: COLUMN marketing_pharmacy_code_references.source_row; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacy_code_references.source_row IS 'Row this reference came from: the spreadsheet row number for a file import, or source_of_sales_customer_map.id for the Sales sync. bigint, not integer — the map id passed 736,844 in Aug 2026 and a hash is not substitutable because (source_file, source_row) is UNIQUE.';

--
-- Name: COLUMN marketing_pharmacy_code_references.compact_pharmacy_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacy_code_references.compact_pharmacy_code IS 'normalized_pharmacy_code with leading zeros stripped (numeric codes only). Lookup key for the Customer Validation vendor-code check, so a rep typing 1503246 finds POS row 0001503246.';

--
-- Name: marketing_pharmacy_code_references_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.marketing_pharmacy_code_references ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.marketing_pharmacy_code_references_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

