);

ALTER TABLE public.marketing_pharmacy_direct_order_venues OWNER TO postgres;

--
-- Name: marketing_pharmacy_distributor_codes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.marketing_pharmacy_distributor_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pharmacy_id uuid NOT NULL,
    distributor_id bigint NOT NULL,
    distributor_pharmacy_code text NOT NULL,
    normalized_pharmacy_code text NOT NULL,
    reference_status text DEFAULT 'pending'::text NOT NULL,
    reference_id bigint,
    reference_match_count integer DEFAULT 0 NOT NULL,
    validated_by_hr_id text,
    validated_at timestamp with time zone,
    validation_notes text,
    active boolean DEFAULT true NOT NULL,
    created_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    mapped_distributor_code text,
    mapped_customer_code text,
    mapped_brick_id text,
    mapped_area_code text,
    mapped_region_code text,
    master_match_kind text,
    master_resolved_at timestamp with time zone,
    CONSTRAINT marketing_pharmacy_distributor_codes_code_not_blank CHECK ((btrim(distributor_pharmacy_code) <> ''::text)),
    CONSTRAINT marketing_pharmacy_distributor_codes_master_match_kind_check CHECK (((master_match_kind IS NULL) OR (master_match_kind = ANY (ARRAY['exact'::text, 'digit_normalized'::text, 'ambiguous'::text, 'unresolved'::text])))),
    CONSTRAINT marketing_pharmacy_distributor_codes_match_count_non_negative CHECK ((reference_match_count >= 0)),
    CONSTRAINT marketing_pharmacy_distributor_codes_normalized_not_blank CHECK ((btrim(normalized_pharmacy_code) <> ''::text)),
    CONSTRAINT marketing_pharmacy_distributor_codes_status_check CHECK ((reference_status = ANY (ARRAY['pending'::text, 'matched'::text, 'ambiguous'::text, 'not_found'::text, 'manual_approved'::text, 'rejected'::text])))
);

ALTER TABLE public.marketing_pharmacy_distributor_codes OWNER TO postgres;

--
-- Name: COLUMN marketing_pharmacy_distributor_codes.mapped_brick_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacy_distributor_codes.mapped_brick_id IS 'Brick from source_of_sales_customer_map, copied ONLY when the code resolves to exactly one distinct brick. NULL for ambiguous and unresolved rows by design. The brick is the authoritative geography - area/region below are carried from the same master row, never inferred from the requester.';

--
-- Name: COLUMN marketing_pharmacy_distributor_codes.master_match_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacy_distributor_codes.master_match_kind IS 'How this code resolved against source_of_sales_customer_map: exact | digit_normalized | ambiguous | unresolved. NULL means the resolver has NOT RUN for this row, which is NOT the same as ''unresolved'' (resolver ran, found nothing in the master) - never collapse the two, never give this column a default, never backfill NULL to ''unresolved''. ''ambiguous'' (>1 candidate brick) deliberately leaves every mapped_* column NULL: guessing an identity would credit one pharmacy''s sales to another. Set only by phx_resolve_marketing_pharmacy_codes().';

--
-- Name: COLUMN marketing_pharmacy_distributor_codes.master_resolved_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_pharmacy_distributor_codes.master_resolved_at IS 'When phx_resolve_marketing_pharmacy_codes() last evaluated this row. Stamped for EVERY verdict including ambiguous and unresolved, so "checked recently, still no match" is visible. NULL means never evaluated.';

