-- Name: marketing_request_products; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.marketing_request_products (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    product_id bigint NOT NULL,
    product_name_snapshot text NOT NULL,
    line_snapshot text,
    factory_price_snapshot numeric(20,4) DEFAULT 0 NOT NULL,
    forecast_quantity numeric(20,2) DEFAULT 0 NOT NULL,
    expected_value numeric(20,2) GENERATED ALWAYS AS ((forecast_quantity * factory_price_snapshot)) STORED,
    value_share numeric(12,6) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT marketing_request_products_factory_price_non_negative CHECK ((factory_price_snapshot >= (0)::numeric)),
    CONSTRAINT marketing_request_products_name_snapshot_not_blank CHECK ((btrim(product_name_snapshot) <> ''::text)),
    CONSTRAINT marketing_request_products_quantity_non_negative CHECK ((forecast_quantity >= (0)::numeric)),
    CONSTRAINT marketing_request_products_value_share_check CHECK (((value_share >= (0)::numeric) AND (value_share <= (1)::numeric)))
);

ALTER TABLE public.marketing_request_products OWNER TO postgres;

--
-- Name: marketing_request_report_share_links; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.marketing_request_report_share_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    token text NOT NULL,
    surface text DEFAULT 'live'::text NOT NULL,
    label text,
    created_by_hr_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    scope text NOT NULL,
    scope_hr_id text NOT NULL,
    filters jsonb,
    passcode_hash text,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by_hr_id text,
    last_accessed_at timestamp with time zone,
    access_count integer DEFAULT 0 NOT NULL,
    allow_files boolean DEFAULT false NOT NULL,
    file_access_count integer DEFAULT 0 NOT NULL,
    refused_count integer DEFAULT 0 NOT NULL,
    last_refused_at timestamp with time zone,
    CONSTRAINT marketing_request_report_share_links_surface_check CHECK ((surface = ANY (ARRAY['live'::text, 'feed'::text])))
);

ALTER TABLE public.marketing_request_report_share_links OWNER TO postgres;

--
-- Name: TABLE marketing_request_report_share_links; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.marketing_request_report_share_links IS 'Shareable live views of the Marketing Request report. A link is a bearer credential: mandatory expiry, one-click revoke, creator-frozen scope, every open audited. The human surface also requires a passcode; the CSV feed cannot (a sheet formula cannot supply one) and is meant to sit inside a private Google Sheet rather than be given to a person.';

--
-- Name: COLUMN marketing_request_report_share_links.scope; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_request_report_share_links.scope IS 'The creator''s report scope AT CREATION. Never re-resolved on read — a link must not silently widen when its creator is promoted, nor break when they are not.';

--
-- Name: COLUMN marketing_request_report_share_links.allow_files; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_request_report_share_links.allow_files IS 'Whether this token may stream evidence photos, invoices and money-transfer proofs. Separate from the CSV grant on purpose: the table leaks numbers, a file leaks a photograph of a named doctor''s clinic. Off unless explicitly asked for.';

--
-- Name: COLUMN marketing_request_report_share_links.refused_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_request_report_share_links.refused_count IS 'Reads refused because this link is revoked or expired. See the direct-order column of the same name.';

--
-- Name: COLUMN marketing_request_report_share_links.last_refused_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_request_report_share_links.last_refused_at IS 'When a dead-link read was last refused. Judged by src/lib/share-links/dead-token-polling.ts.';

