--
-- Name: marketing_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.marketing_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_code text NOT NULL,
    requester_hr_id text NOT NULL,
    manager_hr_id text,
    line_id bigint,
    area_id bigint,
    customer_id uuid NOT NULL,
    customer_contact_id uuid,
    request_type_id bigint NOT NULL,
    other_request_type text,
    request_date date NOT NULL,
    pay_date date,
    roi_duration_months integer DEFAULT 1 NOT NULL,
    estimated_cost numeric(20,2) DEFAULT 0 NOT NULL,
    expected_roi_value numeric(20,2) DEFAULT 0 NOT NULL,
    roi_status text DEFAULT 'not_calculated'::text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    notes text,
    submitted_at timestamp with time zone,
    approved_at timestamp with time zone,
    rejected_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_by_hr_id text,
    updated_by_hr_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    executed_at timestamp with time zone,
    returned_at timestamp with time zone,
    returned_step_sequence integer,
    required_roi_value numeric(20,2) GENERATED ALWAYS AS ((estimated_cost * (10)::numeric)) STORED,
    roi_coverage_ratio numeric(20,4) GENERATED ALWAYS AS (
CASE
    WHEN (estimated_cost > (0)::numeric) THEN (expected_roi_value / (estimated_cost * (10)::numeric))
    WHEN (expected_roi_value > (0)::numeric) THEN (1)::numeric
    ELSE (0)::numeric
END) STORED,
    track_direct_sales boolean DEFAULT true NOT NULL,
    origin text DEFAULT 'phoenix'::text NOT NULL,
    CONSTRAINT marketing_requests_code_not_blank CHECK ((btrim(request_code) <> ''::text)),
    CONSTRAINT marketing_requests_estimated_cost_non_negative CHECK ((estimated_cost >= (0)::numeric)),
    CONSTRAINT marketing_requests_expected_roi_non_negative CHECK ((expected_roi_value >= (0)::numeric)),
    CONSTRAINT marketing_requests_origin_check CHECK ((origin = ANY (ARRAY['xlsx_import'::text, 'phoenix'::text]))),
    CONSTRAINT marketing_requests_roi_duration_positive CHECK ((roi_duration_months > 0)),
    CONSTRAINT marketing_requests_roi_status_check CHECK ((roi_status = ANY (ARRAY['not_calculated'::text, 'covers_required'::text, 'under_target'::text]))),
    CONSTRAINT marketing_requests_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_validation'::text, 'pending_approval'::text, 'returned'::text, 'rejected'::text, 'approved'::text, 'active'::text, 'roi_tracking'::text, 'closed'::text, 'finance_hold'::text, 'archived'::text, 'cancelled'::text])))
);

ALTER TABLE public.marketing_requests OWNER TO postgres;

--
-- Name: COLUMN marketing_requests.track_direct_sales; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_requests.track_direct_sales IS 'When true (the default since 2026-10-18), ROI actuals also include approved Direct Order Request sales at this campaign''s target pharmacies for its own products, matched by the shared distributor customer code and counted in the months of the campaign''s ROI window. A Super Admin can switch it off for one campaign; a service-fee settlement request is created with it off.';

--
-- Name: COLUMN marketing_requests.origin; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_requests.origin IS 'Provenance: xlsx_import = migrated from the historical Excel sheet (frozen, lower data quality, no live approval chain); phoenix = submitted in-app from 2026-08-01 onward (validated at entry). Drives the split between the Archived Marketing Requests module and the live one. NOT the same as status=''archived'', which is a lifecycle state.';

