    active boolean DEFAULT true NOT NULL,
    default_sla_days integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    step_kind text DEFAULT 'role'::text NOT NULL,
    chain_target_role text,
    cc_roles text[] DEFAULT '{}'::text[] NOT NULL,
    decision_labels jsonb DEFAULT '{"reject": "Reject", "return": "Return", "approve": "Approve"}'::jsonb NOT NULL,
    terminal_status text,
    allow_reject boolean DEFAULT true NOT NULL,
    allow_return boolean DEFAULT true NOT NULL,
    CONSTRAINT marketing_workflow_steps_code_not_blank CHECK ((btrim(step_code) <> ''::text)),
    CONSTRAINT marketing_workflow_steps_kind_check CHECK ((step_kind = ANY (ARRAY['managerial_chain'::text, 'role'::text, 'finance'::text]))),
    CONSTRAINT marketing_workflow_steps_name_not_blank CHECK ((btrim(step_name) <> ''::text)),
    CONSTRAINT marketing_workflow_steps_scope_check CHECK ((approval_scope = ANY (ARRAY['direct_manager'::text, 'role'::text, 'finance'::text, 'final'::text]))),
    CONSTRAINT marketing_workflow_steps_sequence_positive CHECK ((sequence > 0)),
    CONSTRAINT marketing_workflow_steps_sla_positive CHECK (((default_sla_days IS NULL) OR (default_sla_days > 0)))
);

ALTER TABLE public.marketing_workflow_steps OWNER TO postgres;

--
-- Name: COLUMN marketing_workflow_steps.step_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_workflow_steps.step_kind IS 'managerial_chain expands at submit time into one step per manager up the requester chain (stops at chain_target_role); role/finance resolve a single line-scoped seat.';

--
-- Name: COLUMN marketing_workflow_steps.cc_roles; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.marketing_workflow_steps.cc_roles IS 'Roles (by line) that are CC-notified for this step but do not gate it (e.g. Marketing = Product/Group Product Manager).';

