    created_at timestamp with time zone DEFAULT now() NOT NULL,
    subject_hr_id text NOT NULL,
    printed_name text NOT NULL,
    hire_date date,
    period_spec text NOT NULL,
    derived_on date NOT NULL,
    milestone_on date NOT NULL,
    format text NOT NULL,
    variant text NOT NULL,
    file_name text,
    photo_source text NOT NULL,
    actor_login_id text,
    actor_hr_id text,
    actor_name text,
    CONSTRAINT milestone_card_prints_format_known CHECK ((format = ANY (ARRAY['pdf'::text, 'png'::text]))),
    CONSTRAINT milestone_card_prints_name_not_blank CHECK ((btrim(printed_name) <> ''::text)),
    CONSTRAINT milestone_card_prints_photo_source_known CHECK ((photo_source = ANY (ARRAY['record'::text, 'upload'::text, 'none'::text]))),
    CONSTRAINT milestone_card_prints_spec_shape CHECK ((period_spec ~ '^(b[0-9]{1,3}|[0-9]{1,5}[dmy])$'::text)),
    CONSTRAINT milestone_card_prints_subject_not_blank CHECK ((btrim(subject_hr_id) <> ''::text)),
    CONSTRAINT milestone_card_prints_variant_known CHECK ((variant = ANY (ARRAY['trim'::text, 'safe'::text, 'bleed'::text])))
);

ALTER TABLE public.milestone_card_prints OWNER TO postgres;

--
-- Name: TABLE milestone_card_prints; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.milestone_card_prints IS 'Append-only log of every milestone or birthday card actually produced. A reprint is a second row, deliberately. Identity of one occasion is (subject_hr_id, period_spec, derived_on) — derived_on is the ARITHMETIC date, never the date typed over it on the card (that is milestone_on). Owner request, 2026-09-23.';

--
-- Name: COLUMN milestone_card_prints.derived_on; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.milestone_card_prints.derived_on IS 'The date milestoneDate(hire, spec) computed. THE IDENTITY of the occasion — never the printed date.';

--
-- Name: COLUMN milestone_card_prints.milestone_on; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.milestone_card_prints.milestone_on IS 'The date the sheet actually carried, which whoever printed it may have typed by hand.';

--
-- Name: COLUMN milestone_card_prints.photo_source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.milestone_card_prints.photo_source IS 'record | upload | none. An upload is a picture handed in for that one card.';

--
-- Name: milestone_notice_marks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.milestone_notice_marks (
    seen_by_hr_id text NOT NULL,
    subject_hr_id text NOT NULL,
    period_spec text NOT NULL,
    derived_on date NOT NULL,
    seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT milestone_notice_marks_spec_shape CHECK ((period_spec ~ '^(b[0-9]{1,3}|[0-9]{1,5}[dmy])$'::text)),
    CONSTRAINT milestone_notice_marks_viewer_not_blank CHECK ((btrim(seen_by_hr_id) <> ''::text))
);

ALTER TABLE public.milestone_notice_marks OWNER TO postgres;

--
-- Name: TABLE milestone_notice_marks; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.milestone_notice_marks IS 'One row per viewer per milestone occasion, written when that viewer opens the milestones page. This is what stops the daily reminder: the owner chose opening the page as the acknowledgement ("when I open it and the system confirm I see it, this pumping stops", 2026-09-23). Idempotent — on conflict do nothing.';

--
-- Name: monthly_closing_publications; Type: TABLE; Schema: public; Owner: postgres
