    rendered_html text NOT NULL,
    rendered_text text NOT NULL,
    checks jsonb DEFAULT '[]'::jsonb NOT NULL,
    confidence_percent integer NOT NULL,
    decision text NOT NULL,
    status text DEFAULT 'held'::text NOT NULL,
    gate_bypassed boolean DEFAULT false NOT NULL,
    provider_message_id text,
    decided_by text,
    decided_at timestamp with time zone,
    decision_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    held_attachments jsonb,
    held_from_address text,
    held_reply_to_address text,
    CONSTRAINT notification_send_reviews_decision_check CHECK ((decision = ANY (ARRAY['auto_send'::text, 'hold'::text]))),
    CONSTRAINT notification_send_reviews_status_check CHECK ((status = ANY (ARRAY['auto_sent'::text, 'held'::text, 'approved'::text, 'discarded'::text])))
);

ALTER TABLE public.notification_send_reviews OWNER TO postgres;

--
-- Name: TABLE notification_send_reviews; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.notification_send_reviews IS 'Audit log + pending-review queue for the Notification Confidence Gate. Every automated email (all modules) is recorded here before dispatch.';

--
-- Name: COLUMN notification_send_reviews.checks; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.notification_send_reviews.checks IS 'Array of {name, passed, detail} — every validator run for this send and its result.';

--
-- Name: COLUMN notification_send_reviews.status; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.notification_send_reviews.status IS 'auto_sent (passed, delivered) / held (failed, not delivered, awaiting review) / approved (was held, admin approved, delivered) / discarded (was held, admin discarded, never delivered).';

--
-- Name: COLUMN notification_send_reviews.held_attachments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.notification_send_reviews.held_attachments IS 'Set only on a held send that carried files: one entry per file (filename, contentType, contentId, remoteUrl, byteSize, storagePath in the notification-held-attachments bucket). storagePath null = the file could not be kept, and approval refuses rather than send without it.';

--
-- Name: COLUMN notification_send_reviews.held_from_address; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.notification_send_reviews.held_from_address IS 'Set only on a held send: the From the send resolved, reused when the held email is approved. Null = held before this was kept; approval uses the default sender.';

--
-- Name: COLUMN notification_send_reviews.held_reply_to_address; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.notification_send_reviews.held_reply_to_address IS 'Set only on a held send: the Reply-To the send resolved, reused when the held email is approved. Null = held before this was kept; approval uses the default Reply-To.';

