);

ALTER TABLE public.offer_job_titles OWNER TO postgres;

--
-- Name: COLUMN offer_job_titles.template_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offer_job_titles.template_id IS 'The letter design new offers for this title open on. Null means use whichever template holds is_default. Cleared automatically if that template is deleted, which falls back to the same default.';

--
-- Name: COLUMN offer_job_titles.role_summary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offer_job_titles.role_summary IS 'What the offer letter says this job IS - the paragraph after the greeting, reaching the letter as {{roleSummary}}. NULL means nobody has worded this position yet and the role-neutral standard sentence prints instead (src/lib/offers/role-summary.ts). Plain text, not HTML: it is escaped on the way into the letter, so write a real em dash, never &mdash;. {{territory}} and the other offer tokens DO work inside it.';

--
-- Name: offer_templates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.offer_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    is_default boolean DEFAULT false NOT NULL,
    blocks jsonb DEFAULT '[]'::jsonb NOT NULL,
    theme jsonb DEFAULT '{}'::jsonb NOT NULL,
    font_family text DEFAULT '''Open Sans'',Arial,Helvetica,sans-serif'::text NOT NULL,
    font_size_pt numeric(4,2) DEFAULT 9.9 NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    builtin_key text,
    variant text DEFAULT 'classic'::text NOT NULL,
    CONSTRAINT offer_templates_blocks_is_array CHECK ((jsonb_typeof(blocks) = 'array'::text)),
    CONSTRAINT offer_templates_builtin_key_known CHECK (((builtin_key IS NULL) OR (builtin_key = ANY (ARRAY['classic'::text, 'executive'::text, 'sato'::text, 'house'::text, 'premium'::text])))),
    CONSTRAINT offer_templates_font_size_sane CHECK (((font_size_pt >= (5)::numeric) AND (font_size_pt <= (24)::numeric))),
    CONSTRAINT offer_templates_name_not_blank CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT offer_templates_theme_is_object CHECK ((jsonb_typeof(theme) = 'object'::text)),
    CONSTRAINT offer_templates_variant_known CHECK ((variant = ANY (ARRAY['classic'::text, 'executive'::text, 'sato'::text, 'house'::text, 'premium'::text])))
);

ALTER TABLE public.offer_templates OWNER TO postgres;

--
-- Name: COLUMN offer_templates.builtin_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offer_templates.builtin_key IS 'Which shipped design this row is a copy of (classic | executive | sato | house | premium), or null for a template built in the designer. Restore matches on this, never on name.';

--
-- Name: COLUMN offer_templates.variant; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offer_templates.variant IS 'The CSS skin the blocks are drawn in (classic | executive | sato | house | premium). All built-ins share one block list and one renderer; this chooses the visual identity.';

--
-- Name: offers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.offers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    candidate_name text NOT NULL,
    salutation_name text DEFAULT ''::text NOT NULL,
    candidate_email text NOT NULL,
    title text NOT NULL,
    territory text DEFAULT ''::text NOT NULL,
    reports_to text DEFAULT ''::text NOT NULL,
    start_date text DEFAULT ''::text NOT NULL,
    contract_term text DEFAULT ''::text NOT NULL,
    reference text DEFAULT ''::text NOT NULL,
    date_of_issue text DEFAULT ''::text NOT NULL,
    valid_until text DEFAULT ''::text NOT NULL,
    total_monthly numeric(12,2) DEFAULT 0 NOT NULL,
    cost_of_living numeric(12,2) DEFAULT 0 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    template_id uuid,
    template_snapshot jsonb,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_by text,
    sent_at timestamp with time zone,
    cc_recipients text[] DEFAULT '{}'::text[] NOT NULL,
    bcc_recipients text[] DEFAULT '{}'::text[] NOT NULL,
    vacancy_id bigint,
    role_summary text DEFAULT ''::text NOT NULL,
    accepted_at timestamp with time zone,
    accepted_via text,
    employee_hr_id text,
    joining_claimed_at timestamp with time zone,
    approval_requested_at timestamp with time zone,
    approval_requested_by text,
    approved_at timestamp with time zone,
    approved_by text,
    approval_returned_at timestamp with time zone,
    approval_returned_by text,
    approval_return_reason text,
    email_message text,
    revision integer DEFAULT 0 NOT NULL,
    revision_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    revised_at timestamp with time zone,
    revised_by text,
    CONSTRAINT offers_accepted_via_check CHECK (((accepted_via IS NULL) OR (accepted_via = ANY (ARRAY['candidate_form'::text, 'hr'::text])))),
    CONSTRAINT offers_candidate_name_not_blank CHECK ((btrim(candidate_name) <> ''::text)),
    CONSTRAINT offers_cost_of_living_non_negative CHECK ((cost_of_living >= (0)::numeric)),
    CONSTRAINT offers_cost_of_living_within_package CHECK ((cost_of_living <= total_monthly)),
    CONSTRAINT offers_email_message_length CHECK (((email_message IS NULL) OR (char_length(email_message) <= 4000))),
    CONSTRAINT offers_revision_not_negative CHECK ((revision >= 0)),
    CONSTRAINT offers_sent_at_present_when_sent CHECK (((status = ANY (ARRAY['draft'::text, 'pending_approval'::text])) OR (sent_at IS NOT NULL))),
    CONSTRAINT offers_status_known CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'sent'::text, 'accepted'::text, 'declined'::text, 'withdrawn'::text]))),
    CONSTRAINT offers_total_monthly_non_negative CHECK ((total_monthly >= (0)::numeric))
);

ALTER TABLE public.offers OWNER TO postgres;

--
-- Name: COLUMN offers.cc_recipients; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offers.cc_recipients IS 'Addresses openly copied (CC) when the offer was sent. Empty for an offer sent to the candidate alone.';

--
-- Name: COLUMN offers.bcc_recipients; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offers.bcc_recipients IS 'Addresses secretly copied (BCC) when the offer was sent. Empty for an offer sent to the candidate alone.';

--
-- Name: COLUMN offers.vacancy_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offers.vacancy_id IS 'The open seat in position_vacancies this offer was written against. Null for an offer issued without one, which every offer before 2026-09-29 is. Never a candidate pointer — the offers module stays independent of recruitment (tests/candidate-offer-pointer.test.ts).';

--
-- Name: COLUMN offers.role_summary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offers.role_summary IS 'This letter''s own role paragraph, copied from the job title when it was chosen and overridable here. Empty prints the standard sentence. Never resolved from the live job title at render time - that would silently restate a letter already sent.';

--
-- Name: COLUMN offers.employee_hr_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.offers.employee_hr_id IS 'The employee record the candidate''s joining form created. Set only by the joining form; never a link to a candidate.';

