    CONSTRAINT outstation_workload_source_check CHECK ((workload_source = ANY (ARRAY['manual'::text, 'double_visit_import'::text, 'ireports360'::text, 'phoenix_crm'::text, 'override'::text])))
);

ALTER TABLE public.outstation_expense_requests OWNER TO postgres;

--
-- Name: COLUMN outstation_expense_requests.captured_accuracy_meters; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.captured_accuracy_meters IS 'GPS accuracy radius in metres as the device reported it. Null: the device reported none (the claim is held for Super Admin review). 0: written by the admin-entered and medical-rep manual paths as their marker, never by a live capture.';

--
-- Name: COLUMN outstation_expense_requests.car_evidence_image_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.car_evidence_image_path IS 'ARRIVAL photo (owner change 2026-08-04): the live in-app camera capture taken at the destination. Named car_* for history — it is now required for EVERY transportation type, not just car. Pairs with departure_evidence_image_path.';

--
-- Name: COLUMN outstation_expense_requests.workload_source_import_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.workload_source_import_id IS 'Legacy Double Visit import id (table dropped 2026-07). Historical/audit value only — no longer a live foreign key. New expense workload evidence writes null here; see workload_evidence_snapshot for the frozen evidence.';

--
-- Name: COLUMN outstation_expense_requests.workload_evidence_snapshot; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.workload_evidence_snapshot IS 'Frozen AM/PM workload evidence from Double Visit Analytics at submission/update time.';

--
-- Name: COLUMN outstation_expense_requests.report_trip_type; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.report_trip_type IS 'Report-facing trip type label used in Phoenix outstation expense XLSX exports, for example Return same day or Overnight.';

--
-- Name: COLUMN outstation_expense_requests.report_travel_cost; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.report_travel_cost IS 'Report-facing travel cost override. When null, exports fall back to calculated fuel plus ticket amount.';

--
-- Name: COLUMN outstation_expense_requests.report_meeting_amount; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.report_meeting_amount IS 'Report-facing meeting amount captured from admin or employee expense entry.';

--
-- Name: COLUMN outstation_expense_requests.report_other_amount; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.report_other_amount IS 'Report-facing other amount captured from admin or employee expense entry.';

--
-- Name: COLUMN outstation_expense_requests.report_am_workload; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.report_am_workload IS 'Report-facing AM workload value captured for expense reporting.';

--
-- Name: COLUMN outstation_expense_requests.report_pm_workload; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.report_pm_workload IS 'Report-facing PM workload value captured for expense reporting.';

--
-- Name: COLUMN outstation_expense_requests.departure_evidence_image_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.departure_evidence_image_path IS 'DEPARTURE photo: the live in-app camera capture the employee must take before leaving the destination. Null until captured; the request holds at pending_departure_photo until then.';

--
-- Name: COLUMN outstation_expense_requests.meeting_invoice_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.outstation_expense_requests.meeting_invoice_path IS 'Storage path (outstation-evidence bucket, meeting-invoice/ prefix) of the uploaded invoice for a Meeting-type manual expense. Null when no invoice was attached.';

--
-- Name: COLUMN outstation_expense_requests.meeting_invoice_metadata; Type: COMMENT; Schema: public; Owner: postgres
--

