    CONSTRAINT page_timings_kind_check CHECK ((kind = ANY (ARRAY['hard'::text, 'soft'::text]))),
    CONSTRAINT page_timings_max_ms_check CHECK ((max_ms >= 0)),
    CONSTRAINT page_timings_metric_check CHECK ((metric = ANY (ARRAY['ttfb'::text, 'fcp'::text, 'lcp'::text, 'interactive'::text, 'first_data'::text, 'soft'::text]))),
    CONSTRAINT page_timings_p50_ms_check CHECK ((p50_ms >= 0)),
    CONSTRAINT page_timings_p90_ms_check CHECK ((p90_ms >= 0)),
    CONSTRAINT page_timings_path_check CHECK (((char_length(path) <= 200) AND (path ~ '^/(employee-portals|admin)(/([a-z][a-z-]{0,48}|:id)){0,3}$'::text)))
);

ALTER TABLE public.page_timings OWNER TO postgres;

--
-- Name: TABLE page_timings; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.page_timings IS 'How long each page takes, by the hour: one row per hour, page shape, kind (hard load or tap), device class and metric, holding the count, the median, the 90th percentile and the worst in milliseconds. No person, login, address or user agent is ever stored. Written by phx_page_timings_record from the web process; read by the System Audit''s Slowest pages tab; pruned at 30 days by phx_prune_retention (owner, 2026-11-01).';

