--
-- Name: payroll_copilot_vacation_settlements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.payroll_copilot_vacation_settlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid,
    employee_hr_id text NOT NULL,
    employee_hr_id_compact text NOT NULL,
    vacation_request_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    start_date date NOT NULL,
    unpaid_days numeric(8,2) NOT NULL,
    settlement_method text NOT NULL,
    salary_deduction_amount numeric(14,2),
    balance_days_consumed numeric(8,2),
    decided_by text NOT NULL,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    superseded_at timestamp with time zone,
    superseded_by_settlement_id uuid,
    email_sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payroll_copilot_vacation_settlements_method_values_check CHECK ((((settlement_method = 'salary'::text) AND (salary_deduction_amount IS NOT NULL) AND (balance_days_consumed IS NULL)) OR ((settlement_method = 'balance'::text) AND (balance_days_consumed IS NOT NULL) AND (salary_deduction_amount IS NULL)) OR ((settlement_method = 'partial_balance'::text) AND (balance_days_consumed IS NOT NULL) AND (salary_deduction_amount IS NOT NULL)) OR ((settlement_method = 'defer_to_balance'::text) AND (balance_days_consumed IS NOT NULL) AND (salary_deduction_amount IS NULL)) OR ((settlement_method = 'holiday_bridge_excluded'::text) AND (salary_deduction_amount IS NULL) AND (balance_days_consumed IS NULL)))),
    CONSTRAINT payroll_copilot_vacation_settlements_unpaid_days_check CHECK ((unpaid_days > (0)::numeric))
);

ALTER TABLE public.payroll_copilot_vacation_settlements OWNER TO postgres;

--
-- Name: TABLE payroll_copilot_vacation_settlements; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.payroll_copilot_vacation_settlements IS 'Payroll Copilot: CEO decision to settle an unpaid-leave request''s cost against salary or vacation balance. Reversible via superseded_at; never mutates v2_vacation_requests.';

--
-- Name: COLUMN payroll_copilot_vacation_settlements.settlement_method; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.payroll_copilot_vacation_settlements.settlement_method IS 'How the unpaid leave cost was settled: salary (full salary deduction), balance (full balance consumption), partial_balance (balance consumed + remaining from salary), defer_to_balance (creates negative balance debt for future accruals), holiday_bridge_excluded (mandatory bridging deduction suppressed by HR).';

--
-- Name: CONSTRAINT payroll_copilot_vacation_settlements_method_values_check ON payroll_copilot_vacation_settlements; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT payroll_copilot_vacation_settlements_method_values_check ON public.payroll_copilot_vacation_settlements IS 'Five settlement methods. salary/balance/partial_balance/defer_to_balance each carry the figure(s) their method implies. holiday_bridge_excluded carries NEITHER — it is a payroll-sheet-only marker that HR excluded one mandatory holiday-bridging day, and it is deliberately outside the method set balanceSettledDaysInPeriod sums, so it can never move a leave balance.';

