    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_behaviour_integrity_month CHECK ((month ~ '^[0-9]{4}-[0-9]{2}$'::text)),
    CONSTRAINT phoenix_crm_behaviour_integrity_visits CHECK ((visits >= 0))
);

ALTER TABLE public.phoenix_crm_behaviour_integrity OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_behaviour_integrity; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_behaviour_integrity IS 'Phoenix CRM behaviour evidence, one row per rep per month, recomputed whole each nightly sweep. Service role only; no rep-facing screen reads it. See src/lib/phoenix-crm/behaviour-integrity.ts.';

--
-- Name: COLUMN phoenix_crm_behaviour_integrity.measured; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_behaviour_integrity.measured IS 'False when the month held too few visits to judge. NOT CHECKED, which is not the same as clean.';

--
-- Name: phoenix_crm_countable_visits_with_history; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.phoenix_crm_countable_visits_with_history WITH (security_invoker='true') AS
 SELECT v.id,
    v.seat_id,
    v.line_code,
    v.customer_id,
    v.list_type,
    v.visit_date,
    v.captured_at,
    v.kind,
    v.rep_hr_id,
    v.manager_hr_id,
    v.senior_hr_id,
    v.entered_by_hr_id,
    v.products,
    v.comment,
    v.photo_path,
    v.lat,
    v.lon,
    v.accuracy_meters,
    v.place_id,
    v.distance_meters,
    v.location_flag,
    v.device_skew_minutes,
    v.is_test,
    v.created_at,
    v.pharmacy_name,
    v.product_availability,
    v.voice_note_path,
    v.voice_note_seconds,
    v.voice_note_bytes,
    v.is_unplanned,
    v.next_step,
    v.next_step_on,
    v.objection,
    v.objection_note,
    v.samples_given,
    v.dwell_seconds,
    v.form_open_seconds,
    v.capture_source,
    v.time_anchor_id,
    v.offline_seconds,
    v.synced_at,
    v.photo_lat,
    v.photo_lon,
    v.photo_accuracy_meters,
    v.photo_captured_at,
    v.unplanned_kind,
    COALESCE(((c.validated_at IS NOT NULL) OR (c.list_type = 'Pharmacy'::text)), false) AS customer_validated,
    v.product_manager_hr_id,
    v.imported_from_ireports360_at,
    v.ireports360_checkin_id,
    v.ireports360_kpi_counted,
    v.archived_at
   FROM (public.phoenix_crm_visits v
     LEFT JOIN public.phoenix_crm_customers c ON ((c.id = v.customer_id)))
  WHERE (((NOT v.is_unplanned) OR (v.id IN ( SELECT uv.visit_id
           FROM public.phoenix_crm_unplanned_visits uv
          WHERE (uv.status = 'approved'::text))) OR (v.unplanned_kind = 'out_of_list'::text)) AND (NOT (EXISTS ( SELECT 1
           FROM public.phoenix_crm_visit_recordings r
          WHERE ((r.visit_id = v.id) AND (r.review_status <> 'approved'::text))))) AND (NOT (v.id IN ( SELECT h.visit_id
           FROM public.phoenix_crm_far_visit_holds h
          WHERE (h.status <> 'approved'::text)))) AND (v.archived_at IS NULL));

ALTER VIEW public.phoenix_crm_countable_visits_with_history OWNER TO postgres;

--
-- Name: VIEW phoenix_crm_countable_visits_with_history; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.phoenix_crm_countable_visits_with_history IS 'Every countable Phoenix CRM visit, iReports360 history copied by 20261029212200 included, an archived one (campaign, or no check-in location) never. For the screens that show a rep''s whole year (timeline, Visit Report, Frequency, calendar reports). A copied visit counts in a figure only when ireports360_kpi_counted.';

--
-- Name: phoenix_crm_customer_moves; Type: TABLE; Schema: public; Owner: postgres
