    CONSTRAINT phoenix_crm_customer_moves_reason CHECK (((char_length(btrim(reason)) >= 10) AND (char_length(btrim(reason)) <= 500))),
    CONSTRAINT phoenix_crm_customer_moves_seats CHECK (((btrim(from_seat_id) <> ''::text) AND (btrim(to_seat_id) <> ''::text) AND (from_seat_id <> to_seat_id)))
);

ALTER TABLE public.phoenix_crm_customer_moves OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_customer_moves; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_customer_moves IS 'Append-only: every time a Phoenix CRM customer was moved from one rep seat to another, with the written reason and who moved him. Written only by phoenix_crm_move_customer().';

--
-- Name: phoenix_crm_customer_moves_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.phoenix_crm_customer_moves ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
