    CONSTRAINT phoenix_crm_daily_forecasts_suggested CHECK (((suggested_units IS NULL) OR (suggested_units >= 0))),
    CONSTRAINT phoenix_crm_daily_forecasts_units CHECK (((units >= 0) AND (units <= 5000)))
);

ALTER TABLE public.phoenix_crm_daily_forecasts OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_daily_forecasts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_daily_forecasts IS 'The CNS daily forecast (owner, 2026-10-01): the boxes a rep expects to sell today, per product. CNS only. A re-send replaces the day''s lines and keeps the first send''s created_at.';

--
-- Name: COLUMN phoenix_crm_daily_forecasts.suggested_units; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_daily_forecasts.suggested_units IS 'The pre-filled figure offered to the rep: the month''s target units for this product and area, divided by the month''s working days (Saturday to Wednesday, less national holidays). Recomputed by the server, never taken from the screen.';

--
-- Name: phoenix_crm_day_interviews; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_day_interviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seat_id text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    activity_date date NOT NULL,
    person_hr_id text,
    source text NOT NULL,
    booking_id uuid,
    candidate_name text NOT NULL,
    scheduled_at timestamp with time zone NOT NULL,
    duration_minutes integer,
    calendar_cv_url text,
    cv_path text,
    cv_file_name text,
    cv_mime_type text,
    created_by_hr_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_day_interviews_calendar_cv_url CHECK (((calendar_cv_url IS NULL) OR (calendar_cv_url ~~ '/api/recruitment/interview-calendar/%'::text))),
    CONSTRAINT phoenix_crm_day_interviews_duration CHECK (((duration_minutes IS NULL) OR ((duration_minutes >= 1) AND (duration_minutes <= 1440)))),
    CONSTRAINT phoenix_crm_day_interviews_file_name CHECK (((cv_file_name IS NULL) OR ((char_length(cv_file_name) >= 1) AND (char_length(cv_file_name) <= 200)))),
    CONSTRAINT phoenix_crm_day_interviews_name CHECK (((char_length(btrim(candidate_name)) >= 1) AND (char_length(btrim(candidate_name)) <= 200))),
    CONSTRAINT phoenix_crm_day_interviews_shape CHECK ((((source = 'added'::text) AND (booking_id IS NULL) AND (cv_path IS NOT NULL) AND (cv_file_name IS NOT NULL) AND (cv_mime_type IS NOT NULL)) OR ((source = 'calendar'::text) AND (booking_id IS NOT NULL) AND (cv_path IS NULL)))),
    CONSTRAINT phoenix_crm_day_interviews_source CHECK ((source = ANY (ARRAY['calendar'::text, 'added'::text])))
);

ALTER TABLE public.phoenix_crm_day_interviews OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_day_interviews; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_day_interviews IS 'The interviews on an Interviews day in Phoenix CRM: the hiring-calendar bookings copied when the day was saved, and the ones added by hand with their CV. A record only. Written only by the application (service role).';

--
-- Name: phoenix_crm_day_starts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_day_starts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seat_id text NOT NULL,
    line_code text,
    rep_hr_id text NOT NULL,
    started_on date NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    lat double precision,
    lon double precision,
    accuracy_meters numeric(8,1),
    planned_am_minute integer,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
)
WITH (autovacuum_analyze_threshold='5', autovacuum_analyze_scale_factor='0.0');

ALTER TABLE public.phoenix_crm_day_starts OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_day_starts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_day_starts IS 'When a medical rep confirmed he started working, with where he was. Owner ruling 2026-10-03: shown only before his first AM visit, and sent to his district manager and the SFE Manager.';

--
-- Name: phoenix_crm_double_visit_plans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_double_visit_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    manager_hr_id text NOT NULL,
    week_start date NOT NULL,
    plan_date date NOT NULL,
    half text NOT NULL,
    seat_id text NOT NULL,
    rep_hr_id text NOT NULL,
    line_code text,
    entered_by_hr_id text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_double_visit_plans_half CHECK ((half = ANY (ARRAY['AM'::text, 'PM'::text]))),
    CONSTRAINT phoenix_crm_double_visit_plans_in_week CHECK (((plan_date >= week_start) AND (plan_date <= (week_start + 5)))),
    CONSTRAINT phoenix_crm_double_visit_plans_saturday CHECK ((EXTRACT(isodow FROM week_start) = (6)::numeric)),
    CONSTRAINT phoenix_crm_double_visit_plans_thursday_am CHECK ((NOT ((EXTRACT(isodow FROM plan_date) = (4)::numeric) AND (half = 'PM'::text)))),
    CONSTRAINT phoenix_crm_double_visit_plans_upper CHECK (((manager_hr_id = upper(manager_hr_id)) AND (rep_hr_id = upper(rep_hr_id))))
);

ALTER TABLE public.phoenix_crm_double_visit_plans OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_double_visit_plans; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_double_visit_plans IS 'The district manager''s double-visit plan (owner, 2026-10-02): for each field day and half of it, the rep seat of his team he joins. Read by that district manager, the SFE Manager and the Super Admin only; the rep never sees it and nothing notifies anyone. A planned half-day is done when the manager was on a countable visit on that seat that half-day.';

--
-- Name: phoenix_crm_double_visit_request_people; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_double_visit_request_people (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    asked_hr_id text NOT NULL,
    role text NOT NULL,
    status text DEFAULT 'waiting'::text NOT NULL,
    visit_on date,
    answered_at timestamp with time zone,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_double_visit_request_people_accepted CHECK (((status = 'accepted'::text) = (visit_on IS NOT NULL))),
    CONSTRAINT phoenix_crm_double_visit_request_people_answered CHECK (((status = 'waiting'::text) = (answered_at IS NULL))),
    CONSTRAINT phoenix_crm_double_visit_request_people_asked CHECK ((asked_hr_id = upper(asked_hr_id))),
    CONSTRAINT phoenix_crm_double_visit_request_people_role CHECK ((role = ANY (ARRAY['manager'::text, 'product_manager'::text]))),
    CONSTRAINT phoenix_crm_double_visit_request_people_status CHECK ((status = ANY (ARRAY['waiting'::text, 'accepted'::text, 'declined'::text])))
);

ALTER TABLE public.phoenix_crm_double_visit_request_people OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_double_visit_request_people; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_double_visit_request_people IS 'One person asked by a double-visit request, and his own answer: waiting, accepted with one of the request''s days, or declined (owner, 2026-10-16). Each answers independently.';

--
-- Name: phoenix_crm_double_visit_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_double_visit_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seat_id text NOT NULL,
    line_code text,
    customer_id uuid NOT NULL,
    rep_hr_id text NOT NULL,
    visit_id uuid,
    days date[] NOT NULL,
    edited_at timestamp with time zone,
    edit_count integer DEFAULT 0 NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_double_visit_requests_days CHECK ((((cardinality(days) >= 1) AND (cardinality(days) <= 3)) AND (EXTRACT(isodow FROM days[1]) <> (5)::numeric) AND ((days[2] IS NULL) OR (EXTRACT(isodow FROM days[2]) <> (5)::numeric)) AND ((days[3] IS NULL) OR (EXTRACT(isodow FROM days[3]) <> (5)::numeric)))),
    CONSTRAINT phoenix_crm_double_visit_requests_rep CHECK ((rep_hr_id = upper(rep_hr_id)))
);

ALTER TABLE public.phoenix_crm_double_visit_requests OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_double_visit_requests; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_double_visit_requests IS 'A rep''s request for a double visit with an AM or PM account, raised by the last question of the visit (owner, 2026-10-16): up to three field days, any number of the people offered. It can be edited (the days) and never cancelled. Each person asked answers on his own row in phoenix_crm_double_visit_request_people. The rep reads his own; every manager reads the requests of the territories in his scope, and each person asked reads his own. It never reads or writes the district manager''s own double-visit plan.';

--
-- Name: phoenix_crm_line_rollout; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_line_rollout (
    line_code text NOT NULL,
    opens_on date,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_hr_id text,
    CONSTRAINT phoenix_crm_line_rollout_code CHECK ((line_code ~ '^[a-z_]{2,40}$'::text))
);

ALTER TABLE public.phoenix_crm_line_rollout OWNER TO postgres;

