--
-- Name: phoenix_crm_list_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_list_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seat_id text NOT NULL,
    line_code text NOT NULL,
    kind text NOT NULL,
    customer_id uuid,
    reference_contact_crm_id bigint,
    list_type text NOT NULL,
    customer_name text NOT NULL,
    current_grade text,
    proposed_grade text,
    drop_reason text,
    note text,
    status text DEFAULT 'pending'::text NOT NULL,
    requested_by_hr_id text NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_by_hr_id text,
    decided_at timestamp with time zone,
    decision_note text,
    is_test boolean DEFAULT false NOT NULL,
    stage text,
    manager_decided_by_hr_id text,
    manager_decided_at timestamp with time zone,
    manager_note text,
    sfe_decided_by_hr_id text,
    sfe_decided_at timestamp with time zone,
    sfe_note text,
    approved_grade text,
    potential_grade text,
    admin_decided_by_hr_id text,
    admin_decided_at timestamp with time zone,
    admin_note text,
    return_note text,
    returned_by_hr_id text,
    returned_at timestamp with time zone,
    rep_reply text,
    replied_at timestamp with time zone,
    CONSTRAINT phoenix_crm_list_requests_approved_grade CHECK (((approved_grade IS NULL) OR (approved_grade = ANY (ARRAY['A'::text, 'B'::text, 'C'::text])))),
    CONSTRAINT phoenix_crm_list_requests_current_grade CHECK (((current_grade IS NULL) OR (current_grade = ANY (ARRAY['A'::text, 'B'::text, 'C'::text])))),
    CONSTRAINT phoenix_crm_list_requests_decided CHECK (((status = 'pending'::text) = (decided_at IS NULL))),
    CONSTRAINT phoenix_crm_list_requests_decision_note CHECK (((decision_note IS NULL) OR (char_length(decision_note) <= 500))),
    CONSTRAINT phoenix_crm_list_requests_drop_reason CHECK (((drop_reason IS NULL) OR (drop_reason = ANY (ARRAY['moved'::text, 'retired'::text, 'closed'::text, 'not_target'::text, 'duplicate'::text, 'other'::text])))),
    CONSTRAINT phoenix_crm_list_requests_kind CHECK ((kind = ANY (ARRAY['grade'::text, 'drop'::text, 'add'::text, 'restore'::text]))),
    CONSTRAINT phoenix_crm_list_requests_kind_fields CHECK ((((kind = ANY (ARRAY['grade'::text, 'add'::text])) = (proposed_grade IS NOT NULL)) AND ((kind = 'drop'::text) = (drop_reason IS NOT NULL)))),
    CONSTRAINT phoenix_crm_list_requests_list_type CHECK ((list_type = ANY (ARRAY['AM'::text, 'PM'::text, 'Pharmacy'::text]))),
    CONSTRAINT phoenix_crm_list_requests_note CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT phoenix_crm_list_requests_other_needs_note CHECK (((drop_reason IS DISTINCT FROM 'other'::text) OR (note IS NOT NULL))),
    CONSTRAINT phoenix_crm_list_requests_potential_grade CHECK (((potential_grade IS NULL) OR (potential_grade = ANY (ARRAY['AA'::text, 'AB'::text, 'AC'::text, 'BA'::text, 'BB'::text, 'BC'::text])))),
    CONSTRAINT phoenix_crm_list_requests_proposed_grade CHECK (((proposed_grade IS NULL) OR (proposed_grade = ANY (ARRAY['A'::text, 'B'::text, 'C'::text])))),
    CONSTRAINT phoenix_crm_list_requests_return_texts CHECK ((((return_note IS NULL) OR (char_length(return_note) <= 500)) AND ((rep_reply IS NULL) OR (char_length(rep_reply) <= 500)))),
    CONSTRAINT phoenix_crm_list_requests_stage CHECK (((stage IS NULL) OR (stage = ANY (ARRAY['manager'::text, 'sfe'::text, 'rep'::text])))),
    CONSTRAINT phoenix_crm_list_requests_stage_notes CHECK ((((manager_note IS NULL) OR (char_length(manager_note) <= 500)) AND ((sfe_note IS NULL) OR (char_length(sfe_note) <= 500)))),
    CONSTRAINT phoenix_crm_list_requests_stage_when_waiting CHECK ((((status = 'pending'::text) AND ((kind <> 'grade'::text) OR (stage = 'rep'::text))) = (stage IS NOT NULL))),
    CONSTRAINT phoenix_crm_list_requests_status CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'refused'::text, 'withdrawn'::text]))),
    CONSTRAINT phoenix_crm_list_requests_subject CHECK (((customer_id IS NOT NULL) OR (reference_contact_crm_id IS NOT NULL)))
);

ALTER TABLE public.phoenix_crm_list_requests OWNER TO postgres;

--
-- Name: COLUMN phoenix_crm_list_requests.stage; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_list_requests.stage IS 'Who decides next while the request waits: manager (the territory''s district manager), then sfe; rep while SFE has returned it for a comment. Null once decided, and null for a grade change, which is one step, unless it is with the rep.';

--
-- Name: COLUMN phoenix_crm_list_requests.return_note; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_list_requests.return_note IS 'What SFE asked the rep to explain when he returned the request for a comment. Kept after the rep answers.';

--
-- Name: COLUMN phoenix_crm_list_requests.rep_reply; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_list_requests.rep_reply IS 'The rep''s answer to the return. For a customer being dropped it is also added to `note`, so the Archive keeps the comment.';

--
-- Name: phoenix_crm_location_integrity; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_location_integrity (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_kind text NOT NULL,
    subject_id uuid NOT NULL,
    seat_id text,
    rep_hr_id text,
    customer_id uuid,
    captured_at timestamp with time zone NOT NULL,
    visit_date date,
    lat double precision,
    lon double precision,
    accuracy_meters numeric,
    device_mocked boolean,
    flags text[] DEFAULT '{}'::text[] NOT NULL,
    strong boolean DEFAULT false NOT NULL,
    signals jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    source text DEFAULT 'gps'::text NOT NULL,
    settled_at timestamp with time zone,
    settled_by text,
    settled_note text,
    settled_flags text[],
    CONSTRAINT phoenix_crm_location_integrity_settled CHECK ((((settled_at IS NULL) AND (settled_by IS NULL) AND (settled_note IS NULL) AND (settled_flags IS NULL)) OR ((settled_at IS NOT NULL) AND (settled_by IS NOT NULL) AND (settled_note IS NOT NULL) AND (settled_flags IS NOT NULL)))),
    CONSTRAINT phoenix_crm_location_integrity_source CHECK ((source = ANY (ARRAY['gps'::text, 'photo'::text, 'behaviour'::text, 'capture_trust'::text, 'signboard'::text, 'roster'::text, 'cadence'::text, 'coverage'::text, 'visit_photo'::text]))),
    CONSTRAINT phoenix_crm_location_integrity_subject_kind_check CHECK ((subject_kind = ANY (ARRAY['visit'::text, 'place'::text, 'shared_place'::text, 'customer'::text])))
);

ALTER TABLE public.phoenix_crm_location_integrity OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_location_integrity; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_location_integrity IS 'Phoenix CRM mock-location and GPS-plausibility evidence. Service role only; no rep-facing screen reads it. See src/lib/phoenix-crm/location-integrity.ts.';

--
-- Name: COLUMN phoenix_crm_location_integrity.subject_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_location_integrity.subject_kind IS 'What the case is about: visit, place, shared_place (a venue in phoenix_crm_shared_places) or customer (a cadence finding). Part of UNIQUE (subject_kind, subject_id, source). The reader derives its labels from INTEGRITY_SUBJECT_KINDS in server/integrity-board.ts — a value this CHECK allows and that list does not hold would print on the owner''s board as a visit.';

--
-- Name: COLUMN phoenix_crm_location_integrity.source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_location_integrity.source IS 'Which detector filed the case: gps, photo, behaviour, capture_trust, signboard, roster, cadence, coverage, or visit_photo (the rep''s own visit fix against the photograph taken at the place, added 2026-10-13). Part of UNIQUE (subject_kind, subject_id, source), so each detector''s verdict sits beside the others''. The reader derives its labels from INTEGRITY_SOURCES in server/integrity-board.ts — a value this CHECK allows and that list does not hold would be read as an unknown detector and printed as its raw code.';

--
-- Name: COLUMN phoenix_crm_location_integrity.settled_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_location_integrity.settled_at IS 'When the Super Admin settled this case, in UTC. Null = never settled, or reopened since.';

--
-- Name: COLUMN phoenix_crm_location_integrity.settled_by; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_location_integrity.settled_by IS 'The HR id of the person who settled it. The board prints his NAME, never this code.';

--
-- Name: COLUMN phoenix_crm_location_integrity.settled_note; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_location_integrity.settled_note IS 'Why it was settled, required, kept for ever. Never shown to the rep — nothing on this table is.';

--
-- Name: COLUMN phoenix_crm_location_integrity.settled_flags; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_location_integrity.settled_flags IS 'The flags as they stood when it was settled. The case counts as settled only while this still equals flags, so a NEW finding on the same subject reopens it with no filer knowing settling exists.';

--
-- Name: phoenix_crm_manager_customers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_manager_customers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    manager_hr_id text NOT NULL,
    line_code text,
    name text NOT NULL,
    speciality text,
    phone text,
    contact_note text,
    grade text NOT NULL,
    potential_grade text NOT NULL,
    comment text,
    area_seat_id text,
    area_code text,
    area_name text,
    pin_lat double precision,
    pin_lon double precision,
    pin_accuracy_meters numeric,
    pin_address text,
    pin_governorate text,
    pin_area_code text,
    pin_area_name text,
    pin_brick_id text,
    pin_brick_name text,
    pin_brick_distance_km numeric,
    pin_brick_lookup text,
    pinned_at timestamp with time zone,
    status text DEFAULT 'active'::text NOT NULL,
    removal_reason text,
    removal_requested_at timestamp with time zone,
    removal_requested_by_hr_id text,
    removal_approver_hr_id text,
    removal_decided_at timestamp with time zone,
    removal_decided_by_hr_id text,
    removal_decided_role text,
    removal_decision_note text,
    created_by_hr_id text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    removal_second_approver_hr_id text,
    removal_first_decided_at timestamp with time zone,
    removal_first_decided_by_hr_id text,
    removal_first_decided_role text,
    removal_first_decision_note text,
    CONSTRAINT phoenix_crm_manager_customers_comment CHECK (((comment IS NULL) OR (char_length(comment) <= 500))),
    CONSTRAINT phoenix_crm_manager_customers_contact_note CHECK (((contact_note IS NULL) OR (char_length(contact_note) <= 300))),
    CONSTRAINT phoenix_crm_manager_customers_grade CHECK ((grade = ANY (ARRAY['A'::text, 'B'::text, 'C'::text]))),
    CONSTRAINT phoenix_crm_manager_customers_name CHECK (((char_length(TRIM(BOTH FROM name)) >= 1) AND (char_length(TRIM(BOTH FROM name)) <= 200))),
    CONSTRAINT phoenix_crm_manager_customers_phone CHECK (((phone IS NULL) OR (phone ~ '^\+?[0-9]{7,15}$'::text))),
    CONSTRAINT phoenix_crm_manager_customers_pin CHECK ((((pin_lat IS NULL) = (pin_lon IS NULL)) AND ((pin_lat IS NULL) = (pin_brick_lookup IS NULL)) AND ((pin_lat IS NULL) = (pinned_at IS NULL)) AND ((pin_lat IS NULL) OR (((pin_lat >= (21.5)::double precision) AND (pin_lat <= (32)::double precision)) AND ((pin_lon >= (24)::double precision) AND (pin_lon <= (37.5)::double precision)))) AND ((pin_brick_lookup IS NULL) OR (pin_brick_lookup = ANY (ARRAY['matched'::text, 'none_nearby'::text, 'could_not_look'::text]))) AND ((pin_accuracy_meters IS NULL) OR (pin_accuracy_meters >= (0)::numeric)))),
    CONSTRAINT phoenix_crm_manager_customers_potential_grade CHECK ((potential_grade = ANY (ARRAY['AA'::text, 'AB'::text, 'AC'::text, 'BA'::text, 'BB'::text, 'BC'::text]))),
    CONSTRAINT phoenix_crm_manager_customers_removal CHECK ((((status = 'active'::text) OR ((removal_reason IS NOT NULL) AND (removal_requested_at IS NOT NULL) AND (removal_approver_hr_id IS NOT NULL))) AND ((status <> 'removed'::text) OR (removal_decided_at IS NOT NULL)) AND ((status <> 'removal_first_approved'::text) OR ((removal_second_approver_hr_id IS NOT NULL) AND (removal_first_decided_at IS NOT NULL))) AND ((removal_first_decided_at IS NULL) = (removal_first_decided_by_hr_id IS NULL)) AND ((removal_first_decided_at IS NULL) = (removal_first_decided_role IS NULL)) AND ((removal_reason IS NULL) OR (char_length(removal_reason) <= 500)) AND ((removal_decision_note IS NULL) OR (char_length(removal_decision_note) <= 500)) AND ((removal_first_decision_note IS NULL) OR (char_length(removal_first_decision_note) <= 500)) AND ((removal_decided_role IS NULL) OR (removal_decided_role = ANY (ARRAY['first'::text, 'second'::text, 'administrator'::text]))) AND ((removal_first_decided_role IS NULL) OR (removal_first_decided_role = ANY (ARRAY['first'::text, 'administrator'::text]))))),
    CONSTRAINT phoenix_crm_manager_customers_second_upper CHECK ((((removal_second_approver_hr_id IS NULL) OR (removal_second_approver_hr_id = upper(removal_second_approver_hr_id))) AND ((removal_first_decided_by_hr_id IS NULL) OR (removal_first_decided_by_hr_id = upper(removal_first_decided_by_hr_id))))),
    CONSTRAINT phoenix_crm_manager_customers_speciality CHECK (((speciality IS NULL) OR (char_length(speciality) <= 120))),
    CONSTRAINT phoenix_crm_manager_customers_status CHECK ((status = ANY (ARRAY['active'::text, 'removal_pending'::text, 'removal_first_approved'::text, 'removed'::text]))),
    CONSTRAINT phoenix_crm_manager_customers_upper CHECK (((manager_hr_id = upper(manager_hr_id)) AND (created_by_hr_id = upper(created_by_hr_id))))
);

ALTER TABLE public.phoenix_crm_manager_customers OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_manager_customers; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_manager_customers IS 'Manager''s own list (owner, 2026-10-16): the customers a district manager adds himself for his single visits, graded by him with no validation step. Never merged into his reps'' lists; taking one off needs his RSM/NSM''s approval. Nothing in it counts in a rep''s or the district''s coverage, call rate, frequency or target.';

--
-- Name: phoenix_crm_manager_plan_customers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_manager_plan_customers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slot_id uuid NOT NULL,
    customer_id uuid,
    manager_customer_id uuid,
    source_seat_id text,
    list_type text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_manager_plan_customers_list_type CHECK (((list_type IS NULL) OR (list_type = ANY (ARRAY['AM'::text, 'PM'::text, 'Pharmacy'::text])))),
    CONSTRAINT phoenix_crm_manager_plan_customers_one CHECK (((customer_id IS NULL) <> (manager_customer_id IS NULL))),
    CONSTRAINT phoenix_crm_manager_plan_customers_source CHECK (((customer_id IS NULL) OR (source_seat_id IS NOT NULL)))
);

ALTER TABLE public.phoenix_crm_manager_plan_customers OWNER TO postgres;

--
-- Name: phoenix_crm_manager_plan_edit_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_manager_plan_edit_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    manager_hr_id text NOT NULL,
    week_start date NOT NULL,
    approver_hr_id text NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    plan_status_at_raise text NOT NULL,
    decided_at timestamp with time zone,
    decided_by_hr_id text,
    decided_role text,
    decision_note text,
    reopened_plan_version integer,
    version integer DEFAULT 1 NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    second_approver_hr_id text,
    first_decided_at timestamp with time zone,
    first_decided_by_hr_id text,
    first_decided_role text,
    first_decision_note text,
    CONSTRAINT phoenix_crm_manager_plan_edit_requests_decided CHECK (((status = ANY (ARRAY['pending'::text, 'first_approved'::text])) = (decided_at IS NULL))),
    CONSTRAINT phoenix_crm_manager_plan_edit_requests_first_step CHECK ((((status <> 'first_approved'::text) OR ((second_approver_hr_id IS NOT NULL) AND (first_decided_at IS NOT NULL))) AND ((first_decided_at IS NULL) = (first_decided_by_hr_id IS NULL)) AND ((first_decided_at IS NULL) = (first_decided_role IS NULL)) AND ((first_decided_role IS NULL) OR (first_decided_role = ANY (ARRAY['first'::text, 'administrator'::text]))) AND ((first_decision_note IS NULL) OR (char_length(first_decision_note) <= 500)))),
    CONSTRAINT phoenix_crm_manager_plan_edit_requests_note CHECK (((decision_note IS NULL) OR (char_length(decision_note) <= 500))),
    CONSTRAINT phoenix_crm_manager_plan_edit_requests_reason CHECK (((char_length(reason) >= 3) AND (char_length(reason) <= 500))),
    CONSTRAINT phoenix_crm_manager_plan_edit_requests_role CHECK (((decided_role IS NULL) OR (decided_role = ANY (ARRAY['first'::text, 'second'::text, 'administrator'::text, 'system'::text])))),
    CONSTRAINT phoenix_crm_manager_plan_edit_requests_second_upper CHECK ((((second_approver_hr_id IS NULL) OR (second_approver_hr_id = upper(second_approver_hr_id))) AND ((first_decided_by_hr_id IS NULL) OR (first_decided_by_hr_id = upper(first_decided_by_hr_id))))),
    CONSTRAINT phoenix_crm_manager_plan_edit_requests_status CHECK ((status = ANY (ARRAY['pending'::text, 'first_approved'::text, 'reopened'::text, 'refused'::text, 'expired'::text]))),
    CONSTRAINT phoenix_crm_manager_plan_edit_requests_upper CHECK (((manager_hr_id = upper(manager_hr_id)) AND (approver_hr_id = upper(approver_hr_id))))
);

ALTER TABLE public.phoenix_crm_manager_plan_edit_requests OWNER TO postgres;

--
-- Name: phoenix_crm_manager_plan_events; Type: TABLE; Schema: public; Owner: postgres
