    CONSTRAINT phoenix_crm_manager_plan_events_role CHECK (((actor_role IS NULL) OR (actor_role = ANY (ARRAY['manager'::text, 'first'::text, 'second'::text, 'administrator'::text, 'system'::text])))),
    CONSTRAINT phoenix_crm_manager_plan_events_type CHECK ((event_type = ANY (ARRAY['created'::text, 'submitted'::text, 'first_approved'::text, 'approved'::text, 'returned'::text, 'edit_asked'::text, 'edit_first_approved'::text, 'reopened'::text, 'edit_refused'::text, 'edit_expired'::text, 'hr_acknowledged'::text])))
);

ALTER TABLE public.phoenix_crm_manager_plan_events OWNER TO postgres;

--
-- Name: phoenix_crm_manager_plan_events_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.phoenix_crm_manager_plan_events ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
