    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: phoenix_crm_manager_plan_slots; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_manager_plan_slots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    week_start date NOT NULL,
    plan_date date NOT NULL,
    half text NOT NULL,
    kind text NOT NULL,
    rep_seat_id text,
    rep_hr_id text,
    activity_type text,
    area_seat_id text,
    area_code text,
    area_name text,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    scope_dm_seat_id text,
    scope_line_code text,
    dm_visit jsonb,
    senior_visit jsonb,
    scope_region_code text,
    CONSTRAINT phoenix_crm_manager_plan_slots_dm_visit CHECK (((dm_visit IS NULL) OR (kind = ANY (ARRAY['with_dm'::text, 'with_area'::text])))),
    CONSTRAINT phoenix_crm_manager_plan_slots_half CHECK ((half = ANY (ARRAY['AM'::text, 'PM'::text]))),
    CONSTRAINT phoenix_crm_manager_plan_slots_in_week CHECK (((plan_date >= week_start) AND (plan_date <= (week_start + 5)))),
    CONSTRAINT phoenix_crm_manager_plan_slots_kind CHECK ((((kind = 'with_rep'::text) AND (rep_seat_id IS NOT NULL) AND (rep_hr_id IS NOT NULL) AND (activity_type IS NULL) AND (area_code IS NULL) AND (area_seat_id IS NULL)) OR ((kind = 'admin'::text) AND (activity_type = ANY (ARRAY['meeting'::text, 'training'::text, 'conference'::text, 'admin_work'::text, 'travel'::text, 'health_day'::text, 'sales_day'::text, 'rtd'::text, 'group_meeting'::text, 'interviews'::text, 'office'::text])) AND (rep_seat_id IS NULL) AND (rep_hr_id IS NULL) AND (area_code IS NULL) AND (area_seat_id IS NULL) AND (scope_dm_seat_id IS NULL) AND (scope_line_code IS NULL)) OR ((kind = 'single_visit'::text) AND (area_code IS NOT NULL) AND (rep_seat_id IS NULL) AND (rep_hr_id IS NULL) AND (activity_type IS NULL)) OR ((kind = 'with_dm'::text) AND (scope_dm_seat_id IS NOT NULL) AND (scope_line_code IS NOT NULL) AND (rep_seat_id IS NULL) AND (rep_hr_id IS NULL) AND (activity_type IS NULL) AND (area_code IS NULL) AND (area_seat_id IS NULL) AND (dm_visit IS NOT NULL) AND (COALESCE(jsonb_typeof(dm_visit), ''::text) = 'object'::text) AND ((
CASE
    WHEN (jsonb_typeof((dm_visit -> 'areas'::text)) = 'array'::text) THEN jsonb_array_length((dm_visit -> 'areas'::text))
    ELSE 0
END >= 1) AND (
CASE
    WHEN (jsonb_typeof((dm_visit -> 'areas'::text)) = 'array'::text) THEN jsonb_array_length((dm_visit -> 'areas'::text))
    ELSE 0
END <= 60))) OR ((kind = 'with_senior'::text) AND (((scope_dm_seat_id IS NULL) AND (scope_line_code IS NULL)) OR ((scope_dm_seat_id IS NOT NULL) AND (scope_line_code IS NOT NULL))) AND (rep_seat_id IS NULL) AND (rep_hr_id IS NULL) AND (activity_type IS NULL) AND (area_code IS NULL) AND (area_seat_id IS NULL) AND (senior_visit IS NOT NULL) AND (COALESCE(jsonb_typeof(senior_visit), ''::text) = 'object'::text) AND (COALESCE(NULLIF(TRIM(BOTH FROM (senior_visit ->> 'senior_hr_id'::text)), ''::text), ''::text) <> ''::text) AND ((
CASE
    WHEN (jsonb_typeof((senior_visit -> 'areas'::text)) = 'array'::text) THEN jsonb_array_length((senior_visit -> 'areas'::text))
    ELSE 0
END >= 1) AND (
CASE
    WHEN (jsonb_typeof((senior_visit -> 'areas'::text)) = 'array'::text) THEN jsonb_array_length((senior_visit -> 'areas'::text))
    ELSE 0
END <= 60))) OR ((kind = 'with_area'::text) AND (scope_region_code IS NOT NULL) AND (area_seat_id IS NOT NULL) AND (area_code IS NOT NULL) AND (rep_seat_id IS NULL) AND (rep_hr_id IS NULL) AND (activity_type IS NULL) AND (scope_dm_seat_id IS NULL) AND (scope_line_code IS NULL) AND (senior_visit IS NULL) AND (dm_visit IS NOT NULL) AND (COALESCE(jsonb_typeof(dm_visit), ''::text) = 'object'::text) AND (
CASE
    WHEN (jsonb_typeof((dm_visit -> 'areas'::text)) = 'array'::text) THEN jsonb_array_length((dm_visit -> 'areas'::text))
    ELSE 0
END = 1)))),
    CONSTRAINT phoenix_crm_manager_plan_slots_note CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT phoenix_crm_manager_plan_slots_region CHECK (((scope_region_code IS NULL) OR ((kind = ANY (ARRAY['with_rep'::text, 'with_area'::text])) AND (scope_dm_seat_id IS NULL) AND (scope_line_code IS NULL)))),
    CONSTRAINT phoenix_crm_manager_plan_slots_scope CHECK (((scope_dm_seat_id IS NULL) OR (scope_line_code IS NOT NULL))),
    CONSTRAINT phoenix_crm_manager_plan_slots_senior_visit CHECK (((senior_visit IS NULL) OR (kind = 'with_senior'::text))),
    CONSTRAINT phoenix_crm_manager_plan_slots_thursday_am CHECK ((NOT ((EXTRACT(isodow FROM plan_date) = (4)::numeric) AND (half = 'PM'::text)))),
    CONSTRAINT phoenix_crm_manager_plan_slots_upper CHECK (((rep_hr_id IS NULL) OR (rep_hr_id = upper(rep_hr_id))))
);

ALTER TABLE public.phoenix_crm_manager_plan_slots OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_manager_plan_slots; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_manager_plan_slots IS 'One half-day of a district manager''s week (owner, 2026-10-16): with a rep (his seat and the customers ticked), admin (one of the seven day activities), or a single visit in an area of his district.';

--
-- Name: COLUMN phoenix_crm_manager_plan_slots.dm_visit; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_plan_slots.dm_visit IS 'A with_dm half-day only: {dm_hr_id, areas: [{seat_id, area_code, area_name, seat_ids}]} — the district manager he goes with and the areas he ticked (owner, 2026-10-23).';

--
-- Name: COLUMN phoenix_crm_manager_plan_slots.senior_visit; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_plan_slots.senior_visit IS 'A with_senior half-day only: {senior_hr_id, role, title, areas: [{seat_id, area_code, area_name, seat_ids}]} — the manager or product manager a district manager goes with and the areas he ticked (owner, 2026-10-23).';

--
-- Name: COLUMN phoenix_crm_manager_plan_slots.scope_region_code; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_plan_slots.scope_region_code IS 'The Training Manager''s with_rep and with_area half-days only: the region she picked (au_v_org_tree.region_code), owner 2026-10-24.';

--
-- Name: phoenix_crm_manager_plans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_manager_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    manager_hr_id text NOT NULL,
    manager_seat_id text,
    line_code text,
    week_start date NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    due_on date NOT NULL,
    submitted_at timestamp with time zone,
    submitted_by_hr_id text,
    submitted_late boolean,
    first_approver_hr_id text,
    second_approver_hr_id text,
    first_decided_at timestamp with time zone,
    first_decided_by_hr_id text,
    first_decided_role text,
    first_decision_note text,
    decided_at timestamp with time zone,
    decided_by_hr_id text,
    decided_by_role text,
    decision_note text,
    returned_day date,
    returned_stage text,
    created_by_hr_id text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    planner_kind text DEFAULT 'dm'::text NOT NULL,
    hr_acknowledged_at timestamp with time zone,
    hr_acknowledged_by_hr_id text,
    CONSTRAINT phoenix_crm_manager_plans_hr_ack CHECK ((((hr_acknowledged_at IS NULL) = (hr_acknowledged_by_hr_id IS NULL)) AND (COALESCE(hr_acknowledged_by_hr_id, ''::text) = upper(COALESCE(hr_acknowledged_by_hr_id, ''::text))) AND ((hr_acknowledged_at IS NULL) OR (planner_kind <> 'dm'::text)))),
    CONSTRAINT phoenix_crm_manager_plans_notes CHECK (((char_length(COALESCE(first_decision_note, ''::text)) <= 500) AND (char_length(COALESCE(decision_note, ''::text)) <= 500))),
    CONSTRAINT phoenix_crm_manager_plans_planner_kind CHECK ((planner_kind = ANY (ARRAY['dm'::text, 'rsm'::text, 'nsm'::text, 'pm'::text, 'tm'::text]))),
    CONSTRAINT phoenix_crm_manager_plans_returned_day CHECK (((returned_day IS NULL) OR ((status = 'returned'::text) AND ((returned_day >= week_start) AND (returned_day <= (week_start + 5)))))),
    CONSTRAINT phoenix_crm_manager_plans_returned_stage CHECK (((returned_stage IS NULL) OR ((status = 'returned'::text) AND (returned_stage = ANY (ARRAY['first'::text, 'second'::text]))))),
    CONSTRAINT phoenix_crm_manager_plans_roles CHECK ((((first_decided_role IS NULL) OR (first_decided_role = ANY (ARRAY['first'::text, 'administrator'::text]))) AND ((decided_by_role IS NULL) OR (decided_by_role = ANY (ARRAY['first'::text, 'second'::text, 'administrator'::text]))))),
    CONSTRAINT phoenix_crm_manager_plans_saturday CHECK ((EXTRACT(isodow FROM week_start) = (6)::numeric)),
    CONSTRAINT phoenix_crm_manager_plans_seat_unless_pm CHECK (((planner_kind = ANY (ARRAY['pm'::text, 'tm'::text])) OR (manager_seat_id IS NOT NULL))),
    CONSTRAINT phoenix_crm_manager_plans_sent_has_approver CHECK (((status = 'draft'::text) OR (first_approver_hr_id IS NOT NULL))),
    CONSTRAINT phoenix_crm_manager_plans_status CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'first_approved'::text, 'approved'::text, 'returned'::text]))),
    CONSTRAINT phoenix_crm_manager_plans_upper CHECK (((manager_hr_id = upper(manager_hr_id)) AND (created_by_hr_id = upper(created_by_hr_id)) AND (COALESCE(first_approver_hr_id, ''::text) = upper(COALESCE(first_approver_hr_id, ''::text))) AND (COALESCE(second_approver_hr_id, ''::text) = upper(COALESCE(second_approver_hr_id, ''::text))) AND (first_approver_hr_id IS DISTINCT FROM manager_hr_id) AND (second_approver_hr_id IS DISTINCT FROM manager_hr_id))),
    CONSTRAINT phoenix_crm_manager_plans_version CHECK ((version >= 1))
);

ALTER TABLE public.phoenix_crm_manager_plans OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_manager_plans; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_manager_plans IS 'The district manager''s weekly plan in Phoenix CRM (owner, 2026-10-16): one row per manager, field week and world. Approved by his RSM/NSM in the Approvals Hub (Hany Saad''s district managers then by Ali Mohamed Ali); the Administrator may act in place of the holder. The rep never sees it, and nothing in it counts in a KPI.';

--
-- Name: COLUMN phoenix_crm_manager_plans.planner_kind; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_plans.planner_kind IS 'Who plans this week: dm (district manager), rsm (regional sales manager), nsm (national sales manager), pm (product manager — no seat), tm (the Training Manager — no seat, owner 2026-10-24). Only a week that is not a district manager''s is acknowledged by HR.';

--
-- Name: phoenix_crm_manager_single_visit_days; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_manager_single_visit_days (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    manager_hr_id text NOT NULL,
    manager_seat_id text,
    week_start date NOT NULL,
    visit_date date NOT NULL,
    reason text,
    status text DEFAULT 'pending'::text NOT NULL,
    approver_hr_id text NOT NULL,
    second_approver_hr_id text,
    first_decided_at timestamp with time zone,
    first_decided_by_hr_id text,
    first_decided_role text,
    first_decision_note text,
    decided_at timestamp with time zone,
    decided_by_hr_id text,
    decided_role text,
    decision_note text,
    version integer DEFAULT 1 NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_manager_single_visit_days_decided CHECK (((status = ANY (ARRAY['pending'::text, 'first_approved'::text])) = (decided_at IS NULL))),
    CONSTRAINT phoenix_crm_manager_single_visit_days_first_step CHECK ((((status <> 'first_approved'::text) OR ((second_approver_hr_id IS NOT NULL) AND (first_decided_at IS NOT NULL))) AND ((first_decided_at IS NULL) = (first_decided_by_hr_id IS NULL)) AND ((first_decided_at IS NULL) = (first_decided_role IS NULL)) AND ((first_decided_role IS NULL) OR (first_decided_role = ANY (ARRAY['first'::text, 'administrator'::text]))))),
    CONSTRAINT phoenix_crm_manager_single_visit_days_notes CHECK ((((decision_note IS NULL) OR (char_length(decision_note) <= 500)) AND ((first_decision_note IS NULL) OR (char_length(first_decision_note) <= 500)))),
    CONSTRAINT phoenix_crm_manager_single_visit_days_people CHECK (((approver_hr_id <> manager_hr_id) AND ((second_approver_hr_id IS NULL) OR ((second_approver_hr_id <> manager_hr_id) AND (second_approver_hr_id <> approver_hr_id))))),
    CONSTRAINT phoenix_crm_manager_single_visit_days_reason CHECK (((reason IS NULL) OR ((char_length(reason) >= 1) AND (char_length(reason) <= 500)))),
    CONSTRAINT phoenix_crm_manager_single_visit_days_role CHECK (((decided_role IS NULL) OR (decided_role = ANY (ARRAY['first'::text, 'second'::text, 'administrator'::text, 'system'::text])))),
    CONSTRAINT phoenix_crm_manager_single_visit_days_status CHECK ((status = ANY (ARRAY['pending'::text, 'first_approved'::text, 'approved'::text, 'refused'::text, 'expired'::text]))),
    CONSTRAINT phoenix_crm_manager_single_visit_days_upper CHECK (((manager_hr_id = upper(manager_hr_id)) AND (approver_hr_id = upper(approver_hr_id)) AND ((second_approver_hr_id IS NULL) OR (second_approver_hr_id = upper(second_approver_hr_id))) AND ((first_decided_by_hr_id IS NULL) OR (first_decided_by_hr_id = upper(first_decided_by_hr_id))) AND ((decided_by_hr_id IS NULL) OR (decided_by_hr_id = upper(decided_by_hr_id))))),
    CONSTRAINT phoenix_crm_manager_single_visit_days_week CHECK (((EXTRACT(isodow FROM week_start) = (6)::numeric) AND ((visit_date >= week_start) AND (visit_date <= (week_start + 5)))))
);

ALTER TABLE public.phoenix_crm_manager_single_visit_days OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_manager_single_visit_days; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_manager_single_visit_days IS 'A district manager''s ask for a second or third day of single visits on one named date (owner, 2026-10-20). His first day a week needs no approval; an APPROVED date holds single visits, planned and unplanned, on both its halves. Decided by his regional manager, then the national sales manager above him.';

--
-- Name: phoenix_crm_manager_visits; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_manager_visits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    manager_hr_id text NOT NULL,
    manager_seat_id text,
    line_code text,
    plan_slot_id uuid,
    is_unplanned boolean DEFAULT false NOT NULL,
    visit_date date NOT NULL,
    half text,
    customer_id uuid,
    manager_customer_id uuid,
    products text[] DEFAULT '{}'::text[] NOT NULL,
    comment text,
    lat double precision,
    lon double precision,
    accuracy_meters numeric,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    client_ref text NOT NULL,
    entered_by_hr_id text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    in_vacant_territory boolean DEFAULT false NOT NULL,
    address text,
    area_code text,
    area_name text,
    brick_id text,
    brick_name text,
    detail_comment text,
    detail_edited_at timestamp with time zone,
    CONSTRAINT phoenix_crm_manager_visits_address CHECK (((address IS NULL) OR ((char_length(address) >= 1) AND (char_length(address) <= 300)))),
    CONSTRAINT phoenix_crm_manager_visits_client_ref CHECK (((char_length(client_ref) >= 8) AND (char_length(client_ref) <= 100))),
    CONSTRAINT phoenix_crm_manager_visits_comment CHECK (((comment IS NULL) OR (char_length(comment) <= 1000))),
    CONSTRAINT phoenix_crm_manager_visits_half CHECK (((half IS NULL) OR (half = ANY (ARRAY['AM'::text, 'PM'::text])))),
    CONSTRAINT phoenix_crm_manager_visits_one CHECK (((customer_id IS NULL) <> (manager_customer_id IS NULL))),
    CONSTRAINT phoenix_crm_manager_visits_pin CHECK ((((lat IS NULL) = (lon IS NULL)) AND ((lat IS NULL) OR (((lat >= (21.5)::double precision) AND (lat <= (32)::double precision)) AND ((lon >= (24)::double precision) AND (lon <= (37.5)::double precision)))) AND ((accuracy_meters IS NULL) OR (accuracy_meters >= (0)::numeric)))),
    CONSTRAINT phoenix_crm_manager_visits_planned CHECK ((NOT (is_unplanned AND (plan_slot_id IS NOT NULL)))),
    CONSTRAINT phoenix_crm_manager_visits_products CHECK ((cardinality(products) <= 12)),
    CONSTRAINT phoenix_crm_manager_visits_upper CHECK (((manager_hr_id = upper(manager_hr_id)) AND (entered_by_hr_id = upper(entered_by_hr_id)))),
    CONSTRAINT phoenix_crm_manager_visits_vacant_place CHECK (((NOT in_vacant_territory) OR (address IS NOT NULL) OR (lat IS NOT NULL)))
)
WITH (autovacuum_analyze_threshold='5', autovacuum_analyze_scale_factor='0.0');

ALTER TABLE public.phoenix_crm_manager_visits OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_manager_visits; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_manager_visits IS 'The single visits a district manager logs himself (owner, 2026-10-16), planned or not. They count in HIS actual-versus-planned report and nowhere else: no KPI, coverage, call-rate, frequency or target reader reads this table.';

--
-- Name: COLUMN phoenix_crm_manager_visits.in_vacant_territory; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_visits.in_vacant_territory IS 'The doctor was on the list of a territory nobody held on the visit day (owner, 2026-10-19). Such a visit carries a typed address or a captured location.';

--
-- Name: COLUMN phoenix_crm_manager_visits.address; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_visits.address IS 'The doctor''s address as the manager saw it on the form: typed by hand, or filled in by Capture location.';

--
-- Name: COLUMN phoenix_crm_manager_visits.area_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_visits.area_name IS 'The area the captured location fell in; null when he typed the address and captured nothing.';

--
-- Name: COLUMN phoenix_crm_manager_visits.brick_name; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_visits.brick_name IS 'The brick the captured location fell in, when it is a brick of an area he plans in; null otherwise.';

--
-- Name: COLUMN phoenix_crm_manager_visits.detail_comment; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_visits.detail_comment IS 'The longer account the manager writes up after logging the visit. The door comment stays in `comment` and is never edited here.';

--
-- Name: COLUMN phoenix_crm_manager_visits.detail_edited_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_manager_visits.detail_edited_at IS 'When the write-up was last saved, for the "Edited" line on his own card. Null until he writes one.';

--
-- Name: phoenix_crm_master_decisions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_master_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
