    CONSTRAINT phoenix_crm_master_decisions_verdict CHECK ((verdict = ANY (ARRAY['confirmed'::text, 'rejected'::text])))
);

ALTER TABLE public.phoenix_crm_master_decisions OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_master_decisions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_master_decisions IS 'The owner''s confirm / not-the-same-place decision and best-photo pick per CRM Master List profile. Never moves a rep''s place. Written only by the application (service role) for the Super Admin.';

--
