--
-- Name: phoenix_crm_monthly_plans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_monthly_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
