    decision_note text,
    created_by_hr_id text NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    due_on date,
    submitted_late boolean DEFAULT false NOT NULL,
    CONSTRAINT phoenix_crm_monthly_plans_decision_note CHECK (((decision_note IS NULL) OR (char_length(decision_note) <= 500))),
    CONSTRAINT phoenix_crm_monthly_plans_first_of_month CHECK ((EXTRACT(day FROM month_start) = (1)::numeric)),
    CONSTRAINT phoenix_crm_monthly_plans_status CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'returned'::text]))),
    CONSTRAINT phoenix_crm_monthly_plans_version CHECK ((version >= 1))
)
WITH (autovacuum_enabled='true');

ALTER TABLE public.phoenix_crm_monthly_plans OWNER TO postgres;

--
-- Name: COLUMN phoenix_crm_monthly_plans.due_on; Type: COMMENT; Schema: public; Owner: postgres
--

