    CONSTRAINT phoenix_crm_pharmacy_distributor_links_name_score_check CHECK (((name_score >= 0) AND (name_score <= 100)))
);

ALTER TABLE public.phoenix_crm_pharmacy_distributor_links OWNER TO postgres;

