--
-- Name: phoenix_crm_photo_fingerprints; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_photo_fingerprints (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    photo_path text NOT NULL,
    subject_kind text NOT NULL,
    subject_id uuid NOT NULL,
    seat_id text,
    rep_hr_id text,
    customer_id uuid,
    captured_at timestamp with time zone NOT NULL,
    sha256 text,
    dhash text,
