    CONSTRAINT phoenix_crm_photo_fingerprints_dhash CHECK (((dhash IS NULL) OR (dhash ~ '^[0-9a-f]{16}$'::text))),
    CONSTRAINT phoenix_crm_photo_fingerprints_failure CHECK (((failure IS NULL) OR (char_length(failure) <= 200))),
    CONSTRAINT phoenix_crm_photo_fingerprints_sha CHECK (((sha256 IS NULL) OR (sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT phoenix_crm_photo_fingerprints_subject_kind_check CHECK ((subject_kind = ANY (ARRAY['visit'::text, 'place'::text])))
);

ALTER TABLE public.phoenix_crm_photo_fingerprints OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_photo_fingerprints; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_photo_fingerprints IS 'One fingerprint per Phoenix CRM photo, computed once by the nightly sweep. Service role only; no rep-facing screen reads it. See src/lib/phoenix-crm/duplicate-photos.ts.';

--
-- Name: COLUMN phoenix_crm_photo_fingerprints.failure; Type: COMMENT; Schema: public; Owner: postgres
--

