);

ALTER TABLE public.phoenix_crm_photo_uploads OWNER TO postgres;

--
-- Name: phoenix_crm_place_match_answers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_place_match_answers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_a text NOT NULL,
    subject_b text NOT NULL,
    answer text NOT NULL,
    decided_by_hr_id text NOT NULL,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
