    CONSTRAINT phoenix_crm_place_match_answers_shape_chk CHECK (((subject_a ~ '^(place|venue):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (subject_b ~ '^(place|venue):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text)))
);

ALTER TABLE public.phoenix_crm_place_match_answers OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_place_match_answers; Type: COMMENT; Schema: public; Owner: postgres
