    CONSTRAINT phoenix_crm_plan_activities_note CHECK (((note IS NULL) OR (char_length(note) <= 300))),
    CONSTRAINT phoenix_crm_plan_activities_type CHECK ((activity_type = ANY (ARRAY['meeting'::text, 'training'::text, 'conference'::text, 'admin_work'::text, 'travel'::text, 'health_day'::text, 'sales_day'::text, 'rtd'::text, 'group_meeting'::text, 'interviews'::text])))
)
WITH (autovacuum_enabled='true');

ALTER TABLE public.phoenix_crm_plan_activities OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_plan_activities; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_plan_activities IS 'The other activities a rep PLANS on a day — one of each kind, shown at the top of the day as the old CRM''s weekly plan did (owner, 2026-09-29). A plan record only: no call rate, coverage or plan-against-actual reads it.';

--
-- Name: phoenix_crm_plan_day_starts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_plan_day_starts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    plan_date date NOT NULL,
    start_am_minute integer,
    start_pm_minute integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_plan_day_starts_am CHECK (((start_am_minute IS NULL) OR ((start_am_minute >= 0) AND (start_am_minute <= 1439)))),
    CONSTRAINT phoenix_crm_plan_day_starts_pm CHECK (((start_pm_minute IS NULL) OR ((start_pm_minute >= 0) AND (start_pm_minute <= 1439)))),
    CONSTRAINT phoenix_crm_plan_day_starts_some CHECK (((start_am_minute IS NOT NULL) OR (start_pm_minute IS NOT NULL)))
)
WITH (autovacuum_enabled='true');

ALTER TABLE public.phoenix_crm_plan_day_starts OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_plan_day_starts; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_plan_day_starts IS 'When the rep means to start his AM round and his PM round on a planned day, in minutes of the Cairo day — the old CRM weekly plan''s Start AM and Start PM (owner''s walk, 2026-09-29). A plan record only: no call rate reads it and no visit is judged against it.';

--
-- Name: phoenix_crm_plan_edit_request_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_plan_edit_request_events (
    id bigint NOT NULL,
    request_id uuid NOT NULL,
    event_type text NOT NULL,
    actor_hr_id text NOT NULL,
    actor_role text,
    actor_stage text,
    from_status text,
    to_status text,
    version integer,
    note text,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_plan_edit_request_events_note CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT phoenix_crm_plan_edit_request_events_stage CHECK (((actor_stage IS NULL) OR (actor_stage = ANY (ARRAY['manager'::text, 'sfe'::text, 'hr'::text, 'administrator'::text])))),
    CONSTRAINT phoenix_crm_plan_edit_request_events_type CHECK ((event_type = ANY (ARRAY['raised'::text, 'approved'::text, 'refused'::text, 'acknowledged'::text, 'expired'::text])))
);

ALTER TABLE public.phoenix_crm_plan_edit_request_events OWNER TO postgres;

--
-- Name: phoenix_crm_plan_edit_request_events_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.phoenix_crm_plan_edit_request_events ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.phoenix_crm_plan_edit_request_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: phoenix_crm_plan_edit_requests; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_plan_edit_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    seat_id text NOT NULL,
    line_code text NOT NULL,
    week_start date NOT NULL,
    rep_hr_id text NOT NULL,
    status text NOT NULL,
    manager_hr_id text,
    plan_status_at_raise text NOT NULL,
    manager_decided_by_hr_id text,
    manager_decided_at timestamp with time zone,
    manager_note text,
    sfe_decided_by_hr_id text,
    sfe_decided_at timestamp with time zone,
    sfe_note text,
    hr_acknowledged_by_hr_id text,
    hr_acknowledged_at timestamp with time zone,
    reopened_plan_version integer,
    decided_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    admin_decided_by_hr_id text,
    admin_decided_at timestamp with time zone,
    admin_note text,
    CONSTRAINT phoenix_crm_plan_edit_requests_admin_note_len CHECK (((admin_note IS NULL) OR (char_length(admin_note) <= 500))),
    CONSTRAINT phoenix_crm_plan_edit_requests_notes CHECK ((((manager_note IS NULL) OR (char_length(manager_note) <= 500)) AND ((sfe_note IS NULL) OR (char_length(sfe_note) <= 500)))),
    CONSTRAINT phoenix_crm_plan_edit_requests_raised_from CHECK ((plan_status_at_raise = ANY (ARRAY['submitted'::text, 'approved'::text]))),
    CONSTRAINT phoenix_crm_plan_edit_requests_saturday CHECK ((EXTRACT(isodow FROM week_start) = (6)::numeric)),
    CONSTRAINT phoenix_crm_plan_edit_requests_settled CHECK (((status = ANY (ARRAY['reopened'::text, 'refused'::text, 'expired'::text])) = (decided_at IS NOT NULL))),
    CONSTRAINT phoenix_crm_plan_edit_requests_status CHECK ((status = ANY (ARRAY['manager_pending'::text, 'sfe_pending'::text, 'hr_pending'::text, 'reopened'::text, 'refused'::text, 'expired'::text]))),
    CONSTRAINT phoenix_crm_plan_edit_requests_version CHECK ((version >= 1))
);

ALTER TABLE public.phoenix_crm_plan_edit_requests OWNER TO postgres;

--
-- Name: phoenix_crm_plan_events; Type: TABLE; Schema: public; Owner: postgres
--

