    CONSTRAINT phoenix_crm_plan_events_type CHECK ((event_type = ANY (ARRAY['created'::text, 'saved'::text, 'submitted'::text, 'reopened'::text, 'approved'::text, 'returned'::text])))
)
WITH (autovacuum_enabled='true');

ALTER TABLE public.phoenix_crm_plan_events OWNER TO postgres;

