--
-- Name: phoenix_crm_ramadan_overrides; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_ramadan_overrides (
    hijri_year integer NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by_hr_id text,
    CONSTRAINT phoenix_crm_ramadan_overrides_span CHECK (((ends_on >= starts_on) AND (((ends_on - starts_on) >= 27) AND ((ends_on - starts_on) <= 30)))),
    CONSTRAINT phoenix_crm_ramadan_overrides_year CHECK (((hijri_year >= 1440) AND (hijri_year <= 1500)))
);

ALTER TABLE public.phoenix_crm_ramadan_overrides OWNER TO postgres;

--
-- Name: phoenix_crm_recording_required; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_recording_required (
    hr_id text NOT NULL,
    set_by_hr_id text NOT NULL,
    set_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_recording_required_hr_id CHECK (((char_length(hr_id) >= 1) AND (char_length(hr_id) <= 40)))
);

ALTER TABLE public.phoenix_crm_recording_required OWNER TO postgres;

--
-- Name: phoenix_crm_refused_readings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_refused_readings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_kind text NOT NULL,
    reason text NOT NULL,
    seat_id text,
    rep_hr_id text,
    customer_id uuid,
    refused_at timestamp with time zone DEFAULT now() NOT NULL,
    visit_date date,
    lat double precision,
    lon double precision,
    accuracy_meters numeric,
    photo_lat double precision,
    photo_lon double precision,
    photo_accuracy_meters numeric,
    max_accuracy_meters numeric,
    device_captured_at timestamp with time zone,
    device_mocked boolean,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    photo_path text,
    blocked_permission text,
    shared_place_id uuid,
    signboard_key text,
    place_id uuid,
    distance_meters integer,
    CONSTRAINT phoenix_crm_refused_readings_blocked_permission_check CHECK (
CASE
    WHEN (reason = 'blocked'::text) THEN ((blocked_permission IS NOT NULL) AND (blocked_permission = ANY (ARRAY['location'::text, 'camera'::text])))
    ELSE (blocked_permission IS NULL)
END),
    CONSTRAINT phoenix_crm_refused_readings_far_from_place_check CHECK (((reason = 'far_from_place'::text) OR ((reason = ANY (ARRAY['impossible_travel'::text, 'readings_apart'::text])) AND (place_id IS NULL)) OR ((place_id IS NULL) AND (distance_meters IS NULL)))),
    CONSTRAINT phoenix_crm_refused_readings_reason_check CHECK ((reason = ANY (ARRAY['no_fix'::text, 'rough'::text, 'off_listing'::text, 'blocked'::text, 'timetable_unreadable'::text, 'timetable_missing'::text, 'signboard_unreadable'::text, 'signboard_no_plate'::text, 'far_from_place'::text, 'impossible_travel'::text, 'readings_apart'::text]))),
    CONSTRAINT phoenix_crm_refused_readings_shared_place_check CHECK (((reason = ANY (ARRAY['timetable_unreadable'::text, 'timetable_missing'::text])) OR ((reason = 'far_from_place'::text) AND (subject_kind = 'place'::text)) OR (shared_place_id IS NULL))),
    CONSTRAINT phoenix_crm_refused_readings_signboard_key_check CHECK (((reason = ANY (ARRAY['signboard_unreadable'::text, 'signboard_no_plate'::text])) OR (signboard_key IS NULL))),
    CONSTRAINT phoenix_crm_refused_readings_subject_kind_check CHECK ((subject_kind = ANY (ARRAY['visit'::text, 'place'::text])))
);

ALTER TABLE public.phoenix_crm_refused_readings OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_refused_readings; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_refused_readings IS 'Phoenix CRM captures the server refused on their location, with the reading the phone sent. Service role only; no rep-facing screen reads it. See src/lib/phoenix-crm/server/refused-readings.ts.';

--
-- Name: COLUMN phoenix_crm_refused_readings.photo_path; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_refused_readings.photo_path IS 'Storage path of the live photo the refused capture was carrying (owner, 2026-10-03: "save the photo when a validation is refused"). The object already exists — the browser uploads it to its slot before the save is attempted — so this is a pointer kept, never a second copy. Null for a visit refused with no photo. Sign it through /api/phoenix-crm/photos/sign.';

--
-- Name: COLUMN phoenix_crm_refused_readings.blocked_permission; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_refused_readings.blocked_permission IS 'Which permission the BROWSER blocked, for reason = ''blocked'' only: ''location'' or ''camera''. Null for every server refusal. See src/lib/phoenix-crm/refused-readings-rules.ts.';

--
-- Name: COLUMN phoenix_crm_refused_readings.shared_place_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_refused_readings.shared_place_id IS 'The building whose TIMETABLE photo was refused, for reason timetable_unreadable / timetable_missing only. Null for every other reason. See src/lib/phoenix-crm/schedule-rules.ts, scheduleDoorAction.';

--
-- Name: COLUMN phoenix_crm_refused_readings.signboard_key; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_refused_readings.signboard_key IS 'What a refused SIGNBOARD photo was taken for (place:<id>, customer:<id> or name:<folded name>), for reason signboard_unreadable / signboard_no_plate only. Null for every other reason. See src/lib/phoenix-crm/signboard-rules.ts, signboardDoorAction.';

--
-- Name: COLUMN phoenix_crm_refused_readings.place_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_refused_readings.place_id IS 'For reason far_from_place only: the nearest validated place (phoenix_crm_places.id) the refused visit was measured to. No foreign key, deliberately — a refusal must outlive a place later retired or moved. Null for every other reason.';

--
-- Name: COLUMN phoenix_crm_refused_readings.distance_meters; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_refused_readings.distance_meters IS 'For reason far_from_place only: whole metres from the visit''s reading to that place''s validated photograph (or its validated point when the photograph carries no sharp reading). max_accuracy_meters holds the far line it was refused against. Null for every other reason.';

--
-- Name: phoenix_crm_removed_plans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_removed_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_kind text NOT NULL,
    plan_id uuid NOT NULL,
    removed_by_hr_id text,
    removed_at timestamp with time zone DEFAULT now() NOT NULL,
    plan jsonb NOT NULL,
    children jsonb NOT NULL
);

ALTER TABLE public.phoenix_crm_removed_plans OWNER TO postgres;

