    created_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.phoenix_crm_team_start_notices OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_team_start_notices; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_team_start_notices IS 'One row per team: the first real weekly plan sent on a territory whose team was not counted from Phoenix CRM. The app inserts it BEFORE telling the Super Admin, so a team is told about once (owner, 2026-10-02).';

--
-- Name: phoenix_crm_territory_readiness; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_territory_readiness (
    seat_id text NOT NULL,
