    reference_total integer NOT NULL,
    validated integer NOT NULL,
    dropped integer NOT NULL
);

ALTER TABLE public.phoenix_crm_territory_readiness OWNER TO postgres;

--
-- Name: phoenix_crm_time_anchors; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_time_anchors (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    hr_id text NOT NULL,
    seat_id text NOT NULL,
    boot_id text,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_time_anchors_boot CHECK (((boot_id IS NULL) OR ((char_length(boot_id) >= 1) AND (char_length(boot_id) <= 120)))),
    CONSTRAINT phoenix_crm_time_anchors_hr CHECK (((char_length(hr_id) >= 1) AND (char_length(hr_id) <= 40))),
    CONSTRAINT phoenix_crm_time_anchors_seat CHECK (((char_length(seat_id) >= 1) AND (char_length(seat_id) <= 80)))
);

ALTER TABLE public.phoenix_crm_time_anchors OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_time_anchors; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_time_anchors IS 'A server-minted time anchor. A phone measures elapsed MONOTONIC time against issued_at to date a visit captured with no signal, so it never has to send a timestamp its own clock could have moved (owner, 2026-09-27). See src/lib/phoenix-crm/offline-clock.ts.';

--
-- Name: COLUMN phoenix_crm_time_anchors.issued_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_time_anchors.issued_at IS 'The server''s own clock. Never supplied by a request. Every offline capture time is this plus an elapsed duration.';

--
-- Name: phoenix_crm_unplanned_visit_events; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_unplanned_visit_events (
    id bigint NOT NULL,
    visit_id uuid NOT NULL,
    event_type text NOT NULL,
    actor_hr_id text NOT NULL,
    actor_role text,
    actor_stage text,
    from_status text,
    to_status text,
    version integer,
    note text,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_unplanned_visit_events_note CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT phoenix_crm_unplanned_visit_events_stage CHECK (((actor_stage IS NULL) OR (actor_stage = ANY (ARRAY['manager'::text, 'sfe'::text, 'administrator'::text])))),
    CONSTRAINT phoenix_crm_unplanned_visit_events_type CHECK ((event_type = ANY (ARRAY['raised'::text, 'approved'::text, 'refused'::text])))
);

ALTER TABLE public.phoenix_crm_unplanned_visit_events OWNER TO postgres;

--
-- Name: phoenix_crm_unplanned_visit_events_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.phoenix_crm_unplanned_visit_events ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.phoenix_crm_unplanned_visit_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

--
-- Name: phoenix_crm_validation_reviews; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_validation_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seat_id text NOT NULL,
    customer_id uuid NOT NULL,
    place_id uuid NOT NULL,
    is_test boolean DEFAULT false NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    google jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by_hr_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_by_hr_id text,
    decided_at timestamp with time zone,
    decision_note text,
    refusal_reason text,
    CONSTRAINT phoenix_crm_validation_reviews_decided CHECK (((status = 'pending'::text) = (decided_at IS NULL))),
    CONSTRAINT phoenix_crm_validation_reviews_decision_note_check CHECK (((decision_note IS NULL) OR (char_length(decision_note) <= 500))),
    CONSTRAINT phoenix_crm_validation_reviews_kind_check CHECK ((kind = ANY (ARRAY['validation'::text, 'added_place'::text]))),
    CONSTRAINT phoenix_crm_validation_reviews_refusal_reason CHECK (((refusal_reason IS NULL) OR (refusal_reason = ANY (ARRAY['no_signboard'::text, 'wrong_name'::text, 'too_dark'::text, 'not_at_door'::text, 'photo_of_paper'::text, 'point_off'::text, 'schedule_other_name'::text, 'schedule_missing'::text, 'short_name'::text])))),
    CONSTRAINT phoenix_crm_validation_reviews_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);

ALTER TABLE public.phoenix_crm_validation_reviews OWNER TO postgres;

--
-- Name: COLUMN phoenix_crm_validation_reviews.refusal_reason; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_validation_reviews.refusal_reason IS 'What is wrong with the PHOTO, chosen by the Super Admin from the closed list in src/lib/phoenix-crm/validation-feedback.ts, and the one thing the rep is ever told. Null on a review decided before 08 Oct 2026, and on every approval. The free-text decision_note beside it is NEVER shown to the rep.';

--
-- Name: phoenix_crm_visit_asks; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_visit_asks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    seat_id text NOT NULL,
    line_code text,
    customer_id uuid NOT NULL,
    kind text NOT NULL,
    rep_hr_id text NOT NULL,
    asked_hr_id text NOT NULL,
    told_hr_id text,
    wished_on date,
    visit_id uuid,
    status text DEFAULT 'waiting'::text NOT NULL,
    visit_on date,
    answered_by_hr_id text,
    answered_at timestamp with time zone,
    cancelled_by_hr_id text,
    cancelled_at timestamp with time zone,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT phoenix_crm_visit_asks_accepted CHECK (((status = 'accepted'::text) = (visit_on IS NOT NULL))),
    CONSTRAINT phoenix_crm_visit_asks_answered CHECK (((status = ANY (ARRAY['accepted'::text, 'declined'::text])) = ((answered_at IS NOT NULL) AND (answered_by_hr_id IS NOT NULL)))),
    CONSTRAINT phoenix_crm_visit_asks_cancelled CHECK (((status = 'cancelled'::text) = ((cancelled_at IS NOT NULL) AND (cancelled_by_hr_id IS NOT NULL)))),
    CONSTRAINT phoenix_crm_visit_asks_field_days CHECK ((((visit_on IS NULL) OR (EXTRACT(isodow FROM visit_on) <> (5)::numeric)) AND ((wished_on IS NULL) OR (EXTRACT(isodow FROM wished_on) <> (5)::numeric)))),
    CONSTRAINT phoenix_crm_visit_asks_kind CHECK ((kind = ANY (ARRAY['double'::text, 'product_manager'::text, 'chain'::text]))),
    CONSTRAINT phoenix_crm_visit_asks_people CHECK (((rep_hr_id = upper(rep_hr_id)) AND (asked_hr_id = upper(asked_hr_id)) AND (asked_hr_id <> rep_hr_id) AND ((told_hr_id IS NULL) OR ((told_hr_id = upper(told_hr_id)) AND (told_hr_id <> rep_hr_id) AND (told_hr_id <> asked_hr_id))))),
    CONSTRAINT phoenix_crm_visit_asks_status CHECK ((status = ANY (ARRAY['waiting'::text, 'accepted'::text, 'declined'::text, 'cancelled'::text]))),
    CONSTRAINT phoenix_crm_visit_asks_told CHECK (
CASE kind
    WHEN 'double'::text THEN (told_hr_id IS NULL)
    WHEN 'chain'::text THEN (told_hr_id IS NOT NULL)
    ELSE true
END)
);

ALTER TABLE public.phoenix_crm_visit_asks OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_visit_asks; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_visit_asks IS 'A rep''s ask for a visit with somebody (owner, 2026-10-02): a double visit with his manager, a visit with a product manager he picks, or a chain visit with his district manager and the manager above. The person asked accepts it with a day or declines it; the rep may cancel one still waiting. The rep reads his own asks; the person asked and the person told read theirs; SFE and the Super Admin read them all. It never reads or writes the district manager''s own double-visit plan.';

--
-- Name: phoenix_crm_visit_capture_provenance; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_visit_capture_provenance (
    visit_id uuid NOT NULL,
    seat_id text,
    rep_hr_id text,
    visit_date date,
    captured_at timestamp with time zone NOT NULL,
    fix_taken_at timestamp with time zone,
    fix_age_seconds integer,
    device_install_id text,
    app_revision text,
    user_agent text,
    is_test boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    queued_seconds integer,
    CONSTRAINT phoenix_crm_visit_capture_provenance_fix_age_seconds_check CHECK (((fix_age_seconds IS NULL) OR (fix_age_seconds >= 0))),
    CONSTRAINT phoenix_crm_visit_capture_provenance_queued_seconds_check CHECK (((queued_seconds IS NULL) OR ((queued_seconds >= 1) AND (queued_seconds <= 7200))))
);

ALTER TABLE public.phoenix_crm_visit_capture_provenance OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_visit_capture_provenance; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_visit_capture_provenance IS 'Phoenix CRM capture provenance: when the phone took the position it sent (fix_taken_at/fix_age_seconds) and which browser install and build saved it. Service role only; no rep-facing screen reads it, nothing here refuses or flags a visit. See src/lib/phoenix-crm/server/capture-provenance.ts.';

--
-- Name: COLUMN phoenix_crm_visit_capture_provenance.fix_age_seconds; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_visit_capture_provenance.fix_age_seconds IS 'Seconds between the phone taking the position and the rep tapping Log visit — both on the phone''s clock, so no clock skew. NULL is NOT MEASURED, never 0.';

--
-- Name: COLUMN phoenix_crm_visit_capture_provenance.device_install_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_visit_capture_provenance.device_install_id IS 'A random id a browser install keeps in its own storage. Names a browser install, never a person and never a handset serial; cleared with the site data. Two reps on one browser profile share it.';

--
-- Name: COLUMN phoenix_crm_visit_capture_provenance.queued_seconds; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.phoenix_crm_visit_capture_provenance.queued_seconds IS 'Seconds the phone held this save before it arrived, measured on the phone''s own clock. A duration, never a date, and never read by the save. NULL is a save that was never held. Service role only.';

--
-- Name: phoenix_crm_visit_comment_readings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_visit_comment_readings (
    visit_id uuid NOT NULL,
    seat_id text NOT NULL,
    visit_date date NOT NULL,
    stock jsonb DEFAULT '[]'::jsonb NOT NULL,
    price jsonb DEFAULT '[]'::jsonb NOT NULL,
    follow_up text,
    heard boolean GENERATED ALWAYS AS (((jsonb_array_length(stock) > 0) OR (jsonb_array_length(price) > 0))) STORED,
    model text NOT NULL,
    read_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.phoenix_crm_visit_comment_readings OWNER TO postgres;

--
-- Name: TABLE phoenix_crm_visit_comment_readings; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.phoenix_crm_visit_comment_readings IS 'What a visit comment says about stock, price and a follow-up. Never a counted figure: no KPI, rank, payroll or coaching figure reads it.';

--
-- Name: phoenix_crm_visit_edits; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.phoenix_crm_visit_edits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    visit_id uuid NOT NULL,
    seat_id text NOT NULL,
    customer_id uuid,
