--
-- Name: phx_v_sales_pharmacy_code_candidates; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.phx_v_sales_pharmacy_code_candidates WITH (security_invoker='true') AS
 WITH candidates AS (
         SELECT md.id AS distributor_id,
            md.active AS distributor_active,
            sd.distributor_name AS raw_distributor_name,
            sd.normalized_distributor_name,
            btrim(m.customer_code) AS raw_pharmacy_code,
            lower(btrim(regexp_replace(btrim(m.customer_code), '\s+'::text, ' '::text, 'g'::text))) AS normalized_pharmacy_code,
            m.address AS raw_pharmacy_address,
            m.region_code AS raw_region,
            m.area_code AS raw_area,
            m.id AS source_row
           FROM ((public.source_of_sales_customer_map m
             JOIN public.source_of_sales_distributors sd ON ((sd.distributor_code = m.distributor_code)))
             JOIN public.marketing_distributors md ON ((md.normalized_name = sd.normalized_distributor_name)))
          WHERE (m.active AND (COALESCE(btrim(m.customer_code), ''::text) <> ''::text) AND (btrim(sd.distributor_name) <> ''::text) AND (sd.normalized_distributor_name IS NOT NULL))
        )
 SELECT DISTINCT ON (distributor_id, normalized_pharmacy_code) distributor_id,
    distributor_active,
    raw_distributor_name,
    normalized_distributor_name,
    raw_pharmacy_code,
    normalized_pharmacy_code,
        CASE
            WHEN (normalized_pharmacy_code ~ '^[0-9]+$'::text) THEN COALESCE(NULLIF(ltrim(normalized_pharmacy_code, '0'::text), ''::text), '0'::text)
            ELSE normalized_pharmacy_code
        END AS compact_pharmacy_code,
    raw_pharmacy_address,
    raw_region,
    raw_area,
    source_row
   FROM candidates c
  ORDER BY distributor_id, normalized_pharmacy_code, source_row;

ALTER VIEW public.phx_v_sales_pharmacy_code_candidates OWNER TO postgres;

--
-- Name: VIEW phx_v_sales_pharmacy_code_candidates; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.phx_v_sales_pharmacy_code_candidates IS 'One row per (marketing distributor, normalized pharmacy code) justified by the live Sales customer map. Read-only input to phx_sync_sales_pharmacy_codes_into_marketing(); safe to query to see what a sync would add without running it.';

