--
-- Name: prodplan_compositions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prodplan_compositions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    material_id uuid NOT NULL,
    unit_kind text NOT NULL,
    basis text NOT NULL,
    qty_per_basis numeric(24,6) NOT NULL,
    supplier text NOT NULL,
    overage_pct numeric(8,4),
    effective_from date DEFAULT ((now() AT TIME ZONE 'Africa/Cairo'::text))::date NOT NULL,
    effective_to date,
    notes text,
    created_by_hr_id text,
    created_by_login text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT prodplan_compositions_basis_check CHECK ((basis = ANY (ARRAY['per_dose'::text, 'per_packaging_set'::text, 'per_good_unit'::text, 'per_sample_unit'::text, 'per_box'::text, 'per_strip'::text]))),
    CONSTRAINT prodplan_compositions_count_whole_check CHECK (((unit_kind <> 'count'::text) OR (qty_per_basis = trunc(qty_per_basis)))),
    CONSTRAINT prodplan_compositions_overage_check CHECK (((overage_pct IS NULL) OR ((overage_pct >= (0)::numeric) AND (overage_pct <= (100)::numeric)))),
    CONSTRAINT prodplan_compositions_qty_check CHECK ((qty_per_basis > (0)::numeric)),
    CONSTRAINT prodplan_compositions_supplier_check CHECK ((supplier = ANY (ARRAY['sato'::text, 'factory'::text, 'shared_unsettled'::text]))),
    CONSTRAINT prodplan_compositions_window_check CHECK (((effective_to IS NULL) OR (effective_to > effective_from)))
);

ALTER TABLE public.prodplan_compositions OWNER TO postgres;

--
-- Name: TABLE prodplan_compositions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_compositions IS 'The bill of materials, versioned by date. A formula change closes the old row with effective_to and opens a new one; nothing is deleted, so a committed plan stays reproducible.';

--
-- Name: COLUMN prodplan_compositions.basis; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_compositions.basis IS 'What qty_per_basis is measured against: per 5 ml dose, per packaging set (bottle+cap+carton+sticker, one per unit INCLUDING a sample), per good unit, or per sample unit.';

--
-- Name: COLUMN prodplan_compositions.supplier; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_compositions.supplier IS 'Who brings it: sato (we buy and deliver it), factory (EGPI brings it), shared_unsettled (not yet decided - it contributes NOTHING to a buy list until a human settles it).';

--
-- Name: COLUMN prodplan_compositions.overage_pct; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_compositions.overage_pct IS 'Per-material overage override. Null means the settings default. Replaced by the measured figure once runs are recorded.';

