    CONSTRAINT prodplan_materials_cover_check CHECK (((reorder_cover_runs IS NULL) OR ((reorder_cover_runs >= (0)::numeric) AND (reorder_cover_runs <= (100)::numeric)))),
    CONSTRAINT prodplan_materials_display_unit_check CHECK (((char_length(btrim(display_unit)) >= 1) AND (char_length(btrim(display_unit)) <= 20))),
    CONSTRAINT prodplan_materials_increment_check CHECK (((purchase_increment IS NULL) OR (purchase_increment > (0)::numeric))),
    CONSTRAINT prodplan_materials_lead_time_check CHECK (((lead_time_days IS NULL) OR ((lead_time_days >= 0) AND (lead_time_days <= 1095)))),
    CONSTRAINT prodplan_materials_min_order_check CHECK (((min_order_qty IS NULL) OR (min_order_qty > (0)::numeric))),
    CONSTRAINT prodplan_materials_name_ar_check CHECK (((char_length(btrim(name_ar)) >= 1) AND (char_length(btrim(name_ar)) <= 160))),
    CONSTRAINT prodplan_materials_name_en_check CHECK (((char_length(btrim(name_en)) >= 1) AND (char_length(btrim(name_en)) <= 160))),
    CONSTRAINT prodplan_materials_unit_kind_check CHECK ((unit_kind = ANY (ARRAY['mass'::text, 'count'::text])))
);

ALTER TABLE public.prodplan_materials OWNER TO postgres;

--
-- Name: TABLE prodplan_materials; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_materials IS 'Raw-material and packaging master. Quantities everywhere are in base units: grams for a mass, pieces for a count. display_unit/base_per_display are presentation only.';

--
-- Name: COLUMN prodplan_materials.base_per_display; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_materials.base_per_display IS 'Base units in one display unit - 1000 for a material shown in kg, 1 for a piece. Changing it changes how a number is shown and typed, never what is stored.';

--
-- Name: COLUMN prodplan_materials.lead_time_days; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_materials.lead_time_days IS 'How long an order takes to arrive. The imported materials are about six months, which is why the reorder alarm exists at all.';

--
-- Name: COLUMN prodplan_materials.reorder_cover_runs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_materials.reorder_cover_runs IS 'Per-material override of the settings threshold: alarm when the stock held covers fewer than this many runs.';

