    CONSTRAINT prodplan_plan_lines_currency_check CHECK (((snap_price_currency IS NULL) OR (snap_price_currency = ANY (ARRAY['USD'::text, 'EGP'::text])))),
    CONSTRAINT prodplan_plan_lines_held_check CHECK ((held_qty >= (0)::numeric)),
    CONSTRAINT prodplan_plan_lines_needed_check CHECK ((needed_qty >= (0)::numeric)),
    CONSTRAINT prodplan_plan_lines_overage_check CHECK (((snap_overage_pct >= (0)::numeric) AND (snap_overage_pct <= (100)::numeric))),
    CONSTRAINT prodplan_plan_lines_qty_check CHECK ((snap_qty_per_basis > (0)::numeric)),
    CONSTRAINT prodplan_plan_lines_supplier_check CHECK ((snap_supplier = ANY (ARRAY['sato'::text, 'factory'::text]))),
    CONSTRAINT prodplan_plan_lines_to_buy_check CHECK ((to_buy_qty >= (0)::numeric)),
    CONSTRAINT prodplan_plan_lines_to_deliver_check CHECK ((to_deliver_qty >= (0)::numeric))
);

ALTER TABLE public.prodplan_plan_lines OWNER TO postgres;

--
-- Name: TABLE prodplan_plan_lines; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_plan_lines IS 'The per-material answer for a COMMITTED plan only. A draft computes its lines live, so there is never a stored line that disagrees with current settings.';

--
-- Name: prodplan_plans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prodplan_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    title text NOT NULL,
    request_mode text DEFAULT 'total_boxes'::text NOT NULL,
    requested_qty bigint NOT NULL,
    sample_units bigint DEFAULT 0 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    snap_overage_pct numeric(8,4),
    snap_run_volume_ml bigint,
    snap_dose_ml integer,
    snap_good_unit_ml integer,
    snap_sample_unit_ml integer,
    snap_units_per_box integer,
    snap_runs bigint,
    snap_good_units bigint,
    snap_packaging_sets bigint,
    snap_fx_usd_to_egp numeric(14,6),
    snap_fx_rate_date date,
    notes text,
    created_by_hr_id text,
    created_by_login text NOT NULL,
    committed_at timestamp with time zone,
    committed_by_hr_id text,
    committed_by_login text,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT prodplan_plans_cancelled_check CHECK (((status = 'cancelled'::text) = (cancelled_at IS NOT NULL))),
    CONSTRAINT prodplan_plans_commit_snapshot_check CHECK (((status <> 'committed'::text) OR ((snap_overage_pct IS NOT NULL) AND (snap_run_volume_ml IS NOT NULL) AND (snap_dose_ml IS NOT NULL) AND (snap_good_unit_ml IS NOT NULL) AND (snap_sample_unit_ml IS NOT NULL) AND (snap_units_per_box IS NOT NULL) AND (snap_runs IS NOT NULL) AND (snap_good_units IS NOT NULL) AND (snap_packaging_sets IS NOT NULL) AND (committed_at IS NOT NULL) AND (committed_by_login IS NOT NULL)))),
    CONSTRAINT prodplan_plans_mode_check CHECK ((request_mode = ANY (ARRAY['total_boxes'::text, 'good_units'::text, 'runs'::text]))),
    CONSTRAINT prodplan_plans_requested_check CHECK ((requested_qty > 0)),
    CONSTRAINT prodplan_plans_samples_check CHECK ((sample_units >= 0)),
    CONSTRAINT prodplan_plans_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'committed'::text, 'cancelled'::text]))),
    CONSTRAINT prodplan_plans_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 160)))
);

ALTER TABLE public.prodplan_plans OWNER TO postgres;

--
-- Name: TABLE prodplan_plans; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_plans IS 'A planned production order. request_mode says what requested_qty means - total boxes (the owner''s usual), good units only, or a run count. Committing freezes the snap_* snapshot.';

--
-- Name: COLUMN prodplan_plans.requested_qty; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_plans.requested_qty IS 'What was asked for, read through request_mode. total_boxes is the TOTAL including samples: asking for 100,000 with 10,000 samples means 90,000 good units and 10,000 samples, not 110,000 boxes.';

--
-- Name: COLUMN prodplan_plans.snap_packaging_sets; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_plans.snap_packaging_sets IS 'Good units PLUS samples: a sample holds less syrup but consumes a full bottle, cap, carton and sticker.';

--
-- Name: prodplan_product_materials; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prodplan_product_materials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    material_id uuid NOT NULL,
    sort_order integer DEFAULT 100 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    supplier text,
    CONSTRAINT prodplan_product_materials_supplier_check CHECK (((supplier IS NULL) OR (supplier = ANY (ARRAY['sato'::text, 'factory'::text, 'shared_unsettled'::text]))))
);

ALTER TABLE public.prodplan_product_materials OWNER TO postgres;

--
-- Name: TABLE prodplan_product_materials; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_product_materials IS 'Which materials belong to which product, and the order they are listed in. Without this the planner loops over every material in the system, so a second product puts its whole raw-material list on the first product''s screen.';

--
-- Name: COLUMN prodplan_product_materials.supplier; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_product_materials.supplier IS 'Who brings this material for this product when NO formula line is in force for it. A line in force always wins. Null means nobody has said.';

--
-- Name: prodplan_products; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prodplan_products (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name_ar text NOT NULL,
    name_en text NOT NULL,
    manufacturer_name text,
    run_volume_ml bigint NOT NULL,
    dose_ml integer NOT NULL,
    good_unit_ml integer NOT NULL,
    sample_unit_ml integer NOT NULL,
    whole_runs_only boolean DEFAULT true NOT NULL,
    units_per_box integer DEFAULT 1 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    measure_unit text DEFAULT 'ml'::text NOT NULL,
    factory_location_id uuid,
    default_sample_units integer DEFAULT 10000 NOT NULL,
    sample_in_own_box boolean DEFAULT false NOT NULL,
    strips_per_box integer,
    batch_weight_display numeric(14,4),
    unit_weight_display numeric(14,4),
    CONSTRAINT prodplan_products_batch_weight_display_check CHECK (((batch_weight_display IS NULL) OR ((batch_weight_display > (0)::numeric) AND (batch_weight_display <= (1000000)::numeric)))),
    CONSTRAINT prodplan_products_code_check CHECK (((code = upper(btrim(code))) AND ((char_length(code) >= 2) AND (char_length(code) <= 40)))),
    CONSTRAINT prodplan_products_default_sample_units_check CHECK (((default_sample_units >= 0) AND (default_sample_units <= 100000000))),
    CONSTRAINT prodplan_products_dose_check CHECK (((dose_ml >= 1) AND (dose_ml <= 1000))),
    CONSTRAINT prodplan_products_good_unit_check CHECK (((good_unit_ml >= 1) AND (good_unit_ml <= 100000))),
    CONSTRAINT prodplan_products_good_unit_dose_check CHECK (((good_unit_ml % dose_ml) = 0)),
    CONSTRAINT prodplan_products_measure_unit_check CHECK ((measure_unit = ANY (ARRAY['ml'::text, 'g'::text, 'mg'::text, 'mg_capsule'::text]))),
    CONSTRAINT prodplan_products_name_ar_check CHECK (((char_length(btrim(name_ar)) >= 1) AND (char_length(btrim(name_ar)) <= 160))),
    CONSTRAINT prodplan_products_name_en_check CHECK (((char_length(btrim(name_en)) >= 1) AND (char_length(btrim(name_en)) <= 160))),
    CONSTRAINT prodplan_products_run_holds_unit_check CHECK ((run_volume_ml >= good_unit_ml)),
    CONSTRAINT prodplan_products_run_volume_check CHECK (((run_volume_ml >= 1) AND (run_volume_ml <= 100000000))),
    CONSTRAINT prodplan_products_run_volume_dose_check CHECK (((run_volume_ml % (dose_ml)::bigint) = 0)),
    CONSTRAINT prodplan_products_sample_unit_check CHECK (((sample_unit_ml >= 1) AND (sample_unit_ml <= 100000))),
    CONSTRAINT prodplan_products_sample_unit_dose_check CHECK (((sample_unit_ml % dose_ml) = 0)),
    CONSTRAINT prodplan_products_strips_per_box_check CHECK (((strips_per_box IS NULL) OR ((strips_per_box >= 1) AND (strips_per_box <= 1000)))),
    CONSTRAINT prodplan_products_unit_weight_display_check CHECK (((unit_weight_display IS NULL) OR ((unit_weight_display > (0)::numeric) AND (unit_weight_display <= (1000000)::numeric)))),
    CONSTRAINT prodplan_products_units_per_box_check CHECK (((units_per_box >= 1) AND (units_per_box <= 1000)))
);

ALTER TABLE public.prodplan_products OWNER TO postgres;

--
-- Name: TABLE prodplan_products; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_products IS 'One row per product manufactured for us under toll manufacturing, with its FIXED run geometry. Samples are made out of the same run volume, so they reduce good units and raise packaging.';

--
-- Name: COLUMN prodplan_products.run_volume_ml; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.run_volume_ml IS 'The FIXED size of one run, in measure_unit — 1,250,000 ml for Ivyronc, 100,000 g for Guamusin. Not necessarily millilitres despite the column name.';

--
-- Name: COLUMN prodplan_products.dose_ml; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.dose_ml IS 'One dose, in measure_unit — 5 ml of syrup, or one 5 g sachet. Not necessarily millilitres despite the column name.';

--
-- Name: COLUMN prodplan_products.good_unit_ml; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.good_unit_ml IS 'One saleable unit, in measure_unit. Not necessarily millilitres despite the column name.';

--
-- Name: COLUMN prodplan_products.sample_unit_ml; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.sample_unit_ml IS 'One free medical sample, in measure_unit. Not necessarily millilitres despite the column name.';

--
-- Name: COLUMN prodplan_products.whole_runs_only; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.whole_runs_only IS 'True when the factory can only make whole runs, so the planner rounds the run count UP and reports the surplus.';

--
-- Name: COLUMN prodplan_products.units_per_box; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.units_per_box IS 'Bottles in one box as the owner counts them. 1 for Ivyronc: his "boxes" and his "bottles" are the same number.';

--
-- Name: COLUMN prodplan_products.measure_unit; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.measure_unit IS 'The unit the four geometry columns are counted in: ml for a liquid, g for a powder, mg for a tablet (155 mg is not a whole gram and the columns are integers). The arithmetic is unit-agnostic — only the words on the screen and in the Excel sheet change, and mg is still READ in kilograms.';

--
-- Name: COLUMN prodplan_products.factory_location_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.factory_location_id IS 'The location that IS this product''s factory, so "send to the factory" and "left after the run" mean something with more than one toll manufacturer. Null falls back to the first location flagged is_factory, which is how Ivyronc behaved before this column existed.';

--
-- Name: COLUMN prodplan_products.default_sample_units; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.default_sample_units IS 'The free-sample count the planner''s Samples field starts at for this product. 0 for a product that gives no samples (Royanoxicam).';

--
-- Name: COLUMN prodplan_products.sample_in_own_box; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.sample_in_own_box IS 'True when one free sample is a whole box of its own holding sample_unit_ml of product, as Saginkgo''s box of one 5-capsule strip is. False counts a sample as one more saleable unit, the rule for every older product.';

--
-- Name: COLUMN prodplan_products.strips_per_box; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.strips_per_box IS 'Blister strips in one saleable box: 3 for Saginkgo. Empty means the product does not count strips, and a per_strip formula line cannot be saved on it.';

--
-- Name: COLUMN prodplan_products.batch_weight_display; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.batch_weight_display IS 'One batch''s weight as the factory states it, in the large unit (kg). Shown on the batch tile and in the sentence instead of run_volume_ml; never used to count. NULL shows run_volume_ml.';

--
-- Name: COLUMN prodplan_products.unit_weight_display; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_products.unit_weight_display IS 'One saleable unit''s weight as the paper states it, in the small unit (mg). Shown instead of dose_ml; never used to count. NULL shows dose_ml.';

--
-- Name: prodplan_run_materials; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prodplan_run_materials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    material_id uuid NOT NULL,
    unit_kind text NOT NULL,
    opening_qty numeric(24,6) NOT NULL,
    delivered_qty numeric(24,6) DEFAULT 0 NOT NULL,
    closing_qty numeric(24,6) NOT NULL,
    consumed_qty numeric(24,6) GENERATED ALWAYS AS (((opening_qty + delivered_qty) - closing_qty)) STORED,
    theoretical_qty numeric(24,6),
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT prodplan_run_materials_balance_check CHECK ((closing_qty <= (opening_qty + delivered_qty))),
    CONSTRAINT prodplan_run_materials_closing_check CHECK ((closing_qty >= (0)::numeric)),
    CONSTRAINT prodplan_run_materials_count_whole_check CHECK (((unit_kind <> 'count'::text) OR ((opening_qty = trunc(opening_qty)) AND (delivered_qty = trunc(delivered_qty)) AND (closing_qty = trunc(closing_qty))))),
    CONSTRAINT prodplan_run_materials_delivered_check CHECK ((delivered_qty >= (0)::numeric)),
    CONSTRAINT prodplan_run_materials_opening_check CHECK ((opening_qty >= (0)::numeric)),
    CONSTRAINT prodplan_run_materials_theoretical_check CHECK (((theoretical_qty IS NULL) OR (theoretical_qty >= (0)::numeric)))
);

ALTER TABLE public.prodplan_run_materials OWNER TO postgres;

--
-- Name: TABLE prodplan_run_materials; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_run_materials IS 'What one run actually consumed of each material, beside what the model said it would. consumed_qty is a generated column so it cannot drift from its own inputs.';

--
-- Name: COLUMN prodplan_run_materials.theoretical_qty; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_run_materials.theoretical_qty IS 'What the model predicted for this run, snapshotted at the moment the run was recorded. The gap between this and consumed_qty is the measured overage.';

--
-- Name: prodplan_runs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prodplan_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    plan_id uuid,
    run_label text NOT NULL,
    runs_count integer DEFAULT 1 NOT NULL,
    actual_good_units bigint NOT NULL,
    actual_sample_units bigint DEFAULT 0 NOT NULL,
    snap_run_volume_ml bigint NOT NULL,
    snap_dose_ml integer NOT NULL,
    snap_good_unit_ml integer NOT NULL,
    snap_sample_unit_ml integer NOT NULL,
    produced_on date NOT NULL,
    is_excluded_from_learning boolean DEFAULT false NOT NULL,
    exclusion_reason text,
    notes text,
    recorded_by_hr_id text,
    recorded_by_login text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT prodplan_runs_count_check CHECK (((runs_count >= 1) AND (runs_count <= 1000))),
    CONSTRAINT prodplan_runs_dose_check CHECK ((snap_dose_ml > 0)),
    CONSTRAINT prodplan_runs_exclusion_check CHECK (((is_excluded_from_learning = false) OR (char_length(btrim(COALESCE(exclusion_reason, ''::text))) > 0))),
    CONSTRAINT prodplan_runs_good_unit_check CHECK ((snap_good_unit_ml > 0)),
    CONSTRAINT prodplan_runs_good_units_check CHECK ((actual_good_units >= 0)),
    CONSTRAINT prodplan_runs_label_check CHECK (((char_length(btrim(run_label)) >= 1) AND (char_length(btrim(run_label)) <= 120))),
    CONSTRAINT prodplan_runs_sample_unit_check CHECK ((snap_sample_unit_ml > 0)),
    CONSTRAINT prodplan_runs_samples_check CHECK ((actual_sample_units >= 0)),
    CONSTRAINT prodplan_runs_volume_check CHECK ((snap_run_volume_ml > 0))
);

ALTER TABLE public.prodplan_runs OWNER TO postgres;

--
-- Name: TABLE prodplan_runs; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_runs IS 'A finished production run as the factory reported it. Recording runs is what replaces the estimated overage with a measured one. A bad row is excluded from learning, never deleted.';

--
-- Name: COLUMN prodplan_runs.is_excluded_from_learning; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_runs.is_excluded_from_learning IS 'Set when the figures are known to be wrong. The row stays - it is still the record of what was reported - but the learner ignores it.';

--
-- Name: prodplan_settings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prodplan_settings (
    id smallint DEFAULT 1 NOT NULL,
    default_overage_pct numeric(8,4) DEFAULT 3 NOT NULL,
    reorder_cover_runs numeric(12,4) DEFAULT 1 NOT NULL,
    alarm_enabled boolean DEFAULT false NOT NULL,
    alarm_dry_run boolean DEFAULT true NOT NULL,
    fx_fetch_enabled boolean DEFAULT false NOT NULL,
    fx_fetch_dry_run boolean DEFAULT true NOT NULL,
    fx_fallback_usd_to_egp numeric(14,6),
    alarm_last_evaluated_on date,
    alarm_last_sent_on date,
    updated_by_hr_id text,
    updated_by_login text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    expiry_warn_days integer DEFAULT 90 NOT NULL,
    expiry_alarm_enabled boolean DEFAULT false NOT NULL,
    expiry_alarm_dry_run boolean DEFAULT true NOT NULL,
    expiry_last_evaluated_on date,
    expiry_last_sent_on date,
    CONSTRAINT prodplan_settings_cover_check CHECK (((reorder_cover_runs >= (0)::numeric) AND (reorder_cover_runs <= (100)::numeric))),
    CONSTRAINT prodplan_settings_expiry_warn_days_check CHECK (((expiry_warn_days >= 1) AND (expiry_warn_days <= 1095))),
    CONSTRAINT prodplan_settings_fallback_check CHECK (((fx_fallback_usd_to_egp IS NULL) OR (fx_fallback_usd_to_egp > (0)::numeric))),
    CONSTRAINT prodplan_settings_overage_check CHECK (((default_overage_pct >= (0)::numeric) AND (default_overage_pct <= (100)::numeric))),
    CONSTRAINT prodplan_settings_singleton_check CHECK ((id = 1))
);

ALTER TABLE public.prodplan_settings OWNER TO postgres;

--
-- Name: TABLE prodplan_settings; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_settings IS 'The single settings row. Two independent arming pairs: alarm_enabled/alarm_dry_run for the reorder email, fx_fetch_enabled/fx_fetch_dry_run for the daily rate. Both ship OFF and in dry run.';

--
-- Name: COLUMN prodplan_settings.alarm_enabled; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_settings.alarm_enabled IS 'Owner arms the reorder email here. False means the cron answers "skipped: disabled" - which is deliberately NOT the same answer as "0 sent".';

--
-- Name: COLUMN prodplan_settings.alarm_dry_run; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_settings.alarm_dry_run IS 'True records every alarm it would have raised and sends nothing. The loader reads it fail-safe (anything but an explicit false is a dry run).';

--
-- Name: COLUMN prodplan_settings.expiry_warn_days; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_settings.expiry_warn_days IS 'How many days before an expiry to start warning. 90 by default, which is the three months the owner asked for.';

--
-- Name: COLUMN prodplan_settings.expiry_alarm_enabled; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_settings.expiry_alarm_enabled IS 'The expiry warning sends nothing unless this is explicitly true. It ships false: arming it is the owner''s click, not a deployment. Independent of alarm_enabled, which is the reorder alarm.';

--
-- Name: prodplan_stock_entries; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.prodplan_stock_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    material_id uuid NOT NULL,
    unit_kind text NOT NULL,
    location_id uuid NOT NULL,
    qty numeric(24,6) NOT NULL,
    as_of_date date NOT NULL,
    source text DEFAULT 'factory_report'::text NOT NULL,
    note text,
    recorded_by_hr_id text,
    recorded_by_login text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expiry_date date,
    CONSTRAINT prodplan_stock_entries_count_whole_check CHECK (((unit_kind <> 'count'::text) OR (qty = trunc(qty)))),
    CONSTRAINT prodplan_stock_entries_qty_check CHECK ((qty >= (0)::numeric)),
    CONSTRAINT prodplan_stock_entries_source_check CHECK ((source = ANY (ARRAY['factory_report'::text, 'own_count'::text, 'delivery'::text, 'adjustment'::text])))
);

ALTER TABLE public.prodplan_stock_entries OWNER TO postgres;

--
-- Name: TABLE prodplan_stock_entries; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.prodplan_stock_entries IS 'APPEND-ONLY stock reports. One row is "this material, at this location, was this much on this date". The current figure is the newest row; nothing is ever overwritten.';

--
-- Name: COLUMN prodplan_stock_entries.as_of_date; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_stock_entries.as_of_date IS 'The date the quantity was true, which is NOT the date it was typed in. Two reports for one date are resolved by created_at.';

--
-- Name: COLUMN prodplan_stock_entries.expiry_date; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.prodplan_stock_entries.expiry_date IS 'When this lot expires. Null means not recorded — which is every Ivyronc row, and which keeps one current balance per material and location exactly as before. With a date, the current balance is the newest row per (material_id, location_id, expiry_date), so one material can hold several lots at one place.';

--
-- Name: push_subscriptions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.push_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    hr_id text NOT NULL,
    user_id text,
    onesignal_subscription_id text NOT NULL,
    device_type text DEFAULT 'unknown'::text NOT NULL,
    user_agent text,
    status text DEFAULT 'subscribed'::text NOT NULL,
    subscribed_at timestamp with time zone DEFAULT now() NOT NULL,
    unsubscribed_at timestamp with time zone,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT push_subscriptions_device_type_check CHECK ((device_type = ANY (ARRAY['desktop'::text, 'mobile'::text, 'unknown'::text]))),
    CONSTRAINT push_subscriptions_status_check CHECK ((status = ANY (ARRAY['subscribed'::text, 'unsubscribed'::text])))
);

ALTER TABLE public.push_subscriptions OWNER TO postgres;

--
-- Name: TABLE push_subscriptions; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.push_subscriptions IS 'One row per browser/device OneSignal Web Push subscription. Existence of a status=subscribed row for an hr_id is Phoenix''s local "is this recipient reachable by push" check; the actual send targets OneSignal''s External ID (= hr_id), which fans out to every subscribed device on its own.';

--
-- Name: record_conversation_comments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.record_conversation_comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    module text NOT NULL,
    record_id text NOT NULL,
    author_hr_id text,
    author_name text,
    author_role text,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT record_conversation_comments_body_length CHECK ((char_length(body) <= 2000)),
    CONSTRAINT record_conversation_comments_body_not_blank CHECK ((btrim(body) <> ''::text)),
    CONSTRAINT record_conversation_comments_module_known CHECK ((module = ANY (ARRAY['direct_orders'::text, 'marketing_requests'::text, 'manager_plans'::text])))
);

ALTER TABLE public.record_conversation_comments OWNER TO postgres;

--
-- Name: TABLE record_conversation_comments; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE public.record_conversation_comments IS 'A record-level conversation thread for direct orders and marketing requests, available at ANY status. UPDATE is refused by trigger (append-only); there is no retract. author_* columns are stamped at write time, never joined at read time, because HR_IDs are reused when a seat is refilled. Owner rule, 2026-09-22.';

--
