    line text,
    manager_hr_id text,
    phoenix_role text,
    scope_type text,
    CONSTRAINT user_access_profiles_phoenix_role_check CHECK (((phoenix_role IS NULL) OR (phoenix_role = ANY (ARRAY['Employee'::text, 'Medical Rep'::text, 'District Manager'::text, 'Regional Manager'::text, 'National Sales Manager'::text, 'Product Manager'::text, 'Group Product Manager'::text, 'SFE Manager'::text, 'Training Manager'::text, 'Marketing Manager'::text, 'Finance Manager'::text, 'Financial Advisor'::text, 'HR Advisory'::text, 'HR Operations'::text, 'HR Resourcing'::text, 'HR Administration'::text, 'Manager'::text, 'CEO'::text, 'Super Admin'::text])))),
    CONSTRAINT user_access_profiles_role_check CHECK ((role = ANY (ARRAY['employee'::text, 'manager'::text, 'hr'::text, 'finance'::text, 'company_reader'::text, 'super_admin'::text, 'admin'::text]))),
    CONSTRAINT user_access_profiles_scope_type_check CHECK (((scope_type IS NULL) OR (scope_type = ANY (ARRAY['SELF'::text, 'TEAM'::text, 'HIERARCHY'::text, 'LINE'::text, 'DEPARTMENT'::text, 'COMPANY_READ'::text, 'FINANCE'::text, 'SUPER_ADMIN'::text]))))
);

