--
-- Name: v_access_identity_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_access_identity_health WITH (security_invoker='true') AS
 WITH active_profiles AS (
         SELECT user_access_profiles.auth_user_id,
            lower(TRIM(BOTH FROM COALESCE(user_access_profiles.hr_id, ''::text))) AS hr_key,
            lower(TRIM(BOTH FROM COALESCE(user_access_profiles.login_id, ''::text))) AS login_key,
            count(*) OVER (PARTITION BY user_access_profiles.auth_user_id) AS auth_user_active_profile_count,
            count(*) OVER (PARTITION BY (lower(TRIM(BOTH FROM COALESCE(user_access_profiles.hr_id, ''::text))))) AS hr_id_active_profile_count,
            count(*) OVER (PARTITION BY (lower(TRIM(BOTH FROM COALESCE(user_access_profiles.login_id, ''::text))))) AS login_id_active_profile_count
           FROM public.user_access_profiles
          WHERE (COALESCE(user_access_profiles.is_active, true) = true)
        ), shared_identity AS (
         SELECT 'b-10'::text AS person_key,
            unnest(ARRAY['b-10'::text, 'phx-1'::text, 'admin-hr'::text]) AS hr_key
        )
 SELECT 'duplicate_active_auth_user_profile'::text AS issue_type,
    (active_profiles.auth_user_id)::text AS entity_key,
    jsonb_build_object('count', active_profiles.auth_user_active_profile_count) AS details
   FROM active_profiles
  WHERE ((active_profiles.auth_user_id IS NOT NULL) AND (active_profiles.auth_user_active_profile_count > 1))
UNION ALL
 SELECT 'duplicate_active_hr_id_profile'::text AS issue_type,
    active_profiles.hr_key AS entity_key,
    jsonb_build_object('count', active_profiles.hr_id_active_profile_count) AS details
   FROM active_profiles
  WHERE ((active_profiles.hr_key <> ''::text) AND (active_profiles.hr_id_active_profile_count > 1))
UNION ALL
 SELECT 'duplicate_active_login_id_profile'::text AS issue_type,
    active_profiles.login_key AS entity_key,
    jsonb_build_object('count', active_profiles.login_id_active_profile_count) AS details
   FROM active_profiles
  WHERE ((active_profiles.login_key <> ''::text) AND (active_profiles.login_id_active_profile_count > 1))
UNION ALL
 SELECT 'active_employee_without_auth_user'::text AS issue_type,
    e.hr_id AS entity_key,
    jsonb_build_object('employee_status', e.employment_status) AS details
   FROM public.employees e
  WHERE ((NULLIF(TRIM(BOTH FROM COALESCE(e.hr_id, ''::text)), ''::text) IS NOT NULL) AND (lower(COALESCE(e.employment_status, 'active'::text)) <> ALL (ARRAY['resigned'::text, 'terminated'::text, 'inactive'::text, 'left'::text, 'historical_payroll_record'::text, 'system_placeholder'::text])) AND (NOT (EXISTS ( SELECT 1
           FROM public.app_auth_users a
          WHERE (lower(TRIM(BOTH FROM COALESCE(a.hr_id, ''::text))) = lower(TRIM(BOTH FROM e.hr_id)))))) AND (NOT (EXISTS ( SELECT 1
           FROM ((shared_identity mine
             JOIN shared_identity theirs ON ((theirs.person_key = mine.person_key)))
             JOIN public.app_auth_users a2 ON ((lower(TRIM(BOTH FROM COALESCE(a2.hr_id, ''::text))) = theirs.hr_key)))
          WHERE (mine.hr_key = lower(TRIM(BOTH FROM e.hr_id)))))))
UNION ALL
 SELECT 'auth_user_without_employee'::text AS issue_type,
    a.login_id AS entity_key,
    jsonb_build_object('hr_id', a.hr_id, 'role', a.role) AS details
   FROM public.app_auth_users a
  WHERE ((NULLIF(TRIM(BOTH FROM COALESCE(a.hr_id, ''::text)), ''::text) IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM public.employees e
          WHERE (lower(TRIM(BOTH FROM COALESCE(e.hr_id, ''::text))) = lower(TRIM(BOTH FROM a.hr_id)))))))
UNION ALL
 SELECT 'auth_user_missing_role'::text AS issue_type,
    a.login_id AS entity_key,
    jsonb_build_object('hr_id', a.hr_id) AS details
   FROM public.app_auth_users a
  WHERE (NULLIF(TRIM(BOTH FROM COALESCE(a.role, ''::text)), ''::text) IS NULL);

ALTER VIEW public.v_access_identity_health OWNER TO postgres;

--
-- Name: VIEW v_access_identity_health; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_access_identity_health IS 'Identity-layer health: duplicate active profiles, employees with no login, logins with no employee, logins with no role. The active-employee branch excludes terminal lifecycle statuses (resigned, terminated, inactive, left, historical_payroll_record, system_placeholder) AND excludes shared-identity alias accounts whose person already holds a login elsewhere — see the shared_identity CTE, which mirrors sharedIdentityGroups in src/lib/auth/identity-aliases.ts. Add a group there and you must add it here too. Kept as a deny-list on purpose: a missed terminal status over-reports (visible), while an allow-list that missed an active status would hide a real person with no login.';

--
-- Name: v_db_health; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_db_health WITH (security_invoker='true') AS
 SELECT pg_size_pretty(pg_database_size(current_database())) AS db_size,
    ( SELECT count(*) AS count
           FROM pg_namespace
          WHERE ((pg_namespace.nspname ~ '_?[0-9]{8}$'::text) AND (pg_namespace.nspname <> ALL (ARRAY['public'::name, 'au'::name])))) AS abandoned_snapshot_schemas,
    ( SELECT COALESCE(pg_size_pretty(sum(pg_relation_size((s.indexrelid)::regclass))), '0 bytes'::text) AS "coalesce"
           FROM (pg_stat_user_indexes s
             JOIN pg_index i ON ((i.indexrelid = s.indexrelid)))
          WHERE ((s.idx_scan = 0) AND (s.last_idx_scan IS NULL) AND (NOT i.indisprimary) AND (NOT i.indisunique) AND (pg_relation_size((s.indexrelid)::regclass) >= 1048576))) AS unused_index_bytes_over_1mb,
    ( SELECT count(*) AS count
           FROM pg_constraint
          WHERE ((NOT pg_constraint.convalidated) AND (pg_constraint.connamespace = ('public'::regnamespace)::oid))) AS not_valid_constraints,
    ( SELECT count(*) AS count
           FROM pg_constraint con
          WHERE ((con.contype = 'f'::"char") AND (con.connamespace = ('public'::regnamespace)::oid) AND (NOT (EXISTS ( SELECT 1
                   FROM pg_index i
                  WHERE ((i.indrelid = con.conrelid) AND (( SELECT array_agg(q.x ORDER BY q.o) AS array_agg
                           FROM unnest((string_to_array((i.indkey)::text, ' '::text))::smallint[]) WITH ORDINALITY q(x, o)
                          WHERE (q.o <= array_length(con.conkey, 1))) @> con.conkey))))))) AS unindexed_foreign_keys,
    ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((c.relkind = 'r'::"char") AND (n.nspname = 'public'::name) AND (NOT c.relrowsecurity))) AS public_tables_without_rls,
    ( SELECT round(((100.0 * (max(age(pg_database.datfrozenxid)))::numeric) / (2000000000)::numeric), 4) AS round
           FROM pg_database) AS pct_to_wraparound,
    ( SELECT round(((100.0 * sum(pg_statio_user_tables.heap_blks_hit)) / NULLIF((sum(pg_statio_user_tables.heap_blks_hit) + sum(pg_statio_user_tables.heap_blks_read)), (0)::numeric)), 2) AS round
           FROM pg_statio_user_tables) AS heap_cache_hit_pct;

ALTER VIEW public.v_db_health OWNER TO postgres;

--
-- Name: VIEW v_db_health; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_db_health IS 'The 2026-08-10 health audit reduced to one row, so the score is reproducible on demand instead of requiring a manual session.';

