-- Name: v_employee_portal_sales; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_employee_portal_sales WITH (security_invoker='true') AS
 SELECT r.id,
    r.batch_id,
    COALESCE(r.employee_hr_id, r.manager_hr_id) AS hr_id,
    r.employee_hr_id,
    r.employee_name,
    r.manager_hr_id,
    r.employee_crm_id,
    r.employee_lookup_key,
    r.line,
    r.territory,
    r.sales_type,
    r.family,
    r.product,
    r.month,
    r.year,
    r.factory_price,
    r.sales_units,
    r.sales_value,
    r.target_units,
    r.target_value,
        CASE
            WHEN (r.target_value > (0)::numeric) THEN round(((r.sales_value / r.target_value) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS achievement_value_percent,
        CASE
            WHEN (r.target_units > (0)::numeric) THEN round(((r.sales_units / r.target_units) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS achievement_units_percent,
    r.validation_state,
    r.link_status,
    r.link_confidence,
    r.created_at
   FROM (public.sales_records r
     JOIN public.sales_import_batches b ON ((r.batch_id = b.id)))
  WHERE (((r.employee_hr_id IS NOT NULL) OR (r.manager_hr_id IS NOT NULL)) AND (b.status = 'approved'::text) AND (b.replaced_by_batch_id IS NULL) AND (r.validation_state <> 'failed'::text) AND (lower(btrim(regexp_replace(COALESCE(r.product, ''::text), '\s+'::text, ' '::text, 'g'::text))) <> ALL (ARRAY['lacto basic 1'::text, 'lacto basic 2'::text, 'satoslim'::text])));

