--
-- Name: v_expense_claims_parity; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_expense_claims_parity AS
 WITH legacy AS (
         SELECT ('OUTSTATION-'::text || r.id) AS claim_ref,
                CASE
                    WHEN (r.status ~~ 'rejected%'::text) THEN 'rejected'::text
                    WHEN ((r.status ~~ 'accepted%'::text) OR (r.status = 'approved'::text)) THEN 'approved'::text
                    ELSE 'submitted'::text
                END AS status,
            (
                CASE
                    WHEN (r.claimed_total_amount > (0)::double precision) THEN r.claimed_total_amount
                    ELSE r.expected_total_amount
                END)::numeric(12,2) AS claimed_total,
            (
                CASE
                    WHEN (((r.status ~~ 'accepted%'::text) OR (r.status = 'approved'::text)) AND ((COALESCE(e.approved_amount, e.total))::numeric(12,2) <= (
                    CASE
                        WHEN (r.claimed_total_amount > (0)::double precision) THEN r.claimed_total_amount
                        ELSE r.expected_total_amount
                    END)::numeric(12,2))) THEN COALESCE(e.approved_amount, e.total)
                    ELSE NULL::numeric
                END)::numeric(12,2) AS approved_total,
            lower(r.employee_hr_id) AS employee_key
           FROM (public.outstation_expense_requests r
             LEFT JOIN public.outstation_expenses e ON ((e.trip_id = ('OUTSTATION-'::text || r.id))))
        UNION ALL
         SELECT e.trip_id,
                CASE
                    WHEN e.hr_approved THEN 'approved'::text
                    WHEN (COALESCE(e.status, ''::text) ~~* '%reject%'::text) THEN 'rejected'::text
                    ELSE 'submitted'::text
                END AS "case",
            (e.total)::numeric(12,2) AS total,
            (
                CASE
                    WHEN (e.hr_approved AND ((COALESCE(e.approved_amount, e.total))::numeric(12,2) <= (e.total)::numeric(12,2))) THEN COALESCE(e.approved_amount, e.total)
                    ELSE NULL::numeric
                END)::numeric(12,2) AS "numeric",
            lower(e.hr_id) AS lower
           FROM public.outstation_expenses e
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM public.outstation_expense_requests r
                  WHERE (('OUTSTATION-'::text || r.id) = e.trip_id))))
        )
 SELECT COALESCE(c.claim_ref, l.claim_ref) AS claim_ref,
        CASE
            WHEN (c.claim_ref IS NULL) THEN 'MISSING_IN_NEW'::text
            WHEN (l.claim_ref IS NULL) THEN 'MISSING_IN_LEGACY'::text
            WHEN (c.status IS DISTINCT FROM l.status) THEN 'STATUS_DRIFT'::text
            WHEN (c.claimed_total IS DISTINCT FROM l.claimed_total) THEN 'CLAIMED_DRIFT'::text
            WHEN (COALESCE(c.approved_total, ('-1'::integer)::numeric) IS DISTINCT FROM COALESCE(l.approved_total, ('-1'::integer)::numeric)) THEN 'APPROVED_DRIFT'::text
            WHEN (c.employee_key IS DISTINCT FROM l.employee_key) THEN 'EMPLOYEE_DRIFT'::text
            ELSE 'OK'::text
        END AS verdict,
    c.status AS new_status,
    l.status AS legacy_status,
    c.claimed_total AS new_claimed,
    l.claimed_total AS legacy_claimed,
    c.approved_total AS new_approved,
    l.approved_total AS legacy_approved
   FROM (( SELECT expense_claims.claim_ref,
            expense_claims.status,
            expense_claims.claimed_total,
            expense_claims.approved_total,
            lower(expense_claims.employee_hr_id) AS employee_key
           FROM public.expense_claims) c
     FULL JOIN legacy l ON ((l.claim_ref = c.claim_ref)));

ALTER VIEW public.v_expense_claims_parity OWNER TO postgres;

--
-- Name: VIEW v_expense_claims_parity; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_expense_claims_parity IS 'PHASE 2 comparison harness. Every row where verdict <> OK is a real divergence between the new model and the legacy tables. Zero non-OK rows is the gate for phase 3.';

--
-- Name: v_expense_import_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_expense_import_summary AS
 SELECT i.id AS import_id,
    i.file_name,
    i.uploaded_at,
    count(c.id) AS row_count,
    count(c.id) FILTER (WHERE (c.status = 'approved'::text)) AS approved_rows,
    (COALESCE(sum(c.claimed_total), (0)::numeric))::numeric(14,2) AS total_claimed,
    (COALESCE(sum(c.approved_total), (0)::numeric))::numeric(14,2) AS total_approved,
    min(c.trip_start_date) AS trip_date_from,
    max(c.trip_end_date) AS trip_date_to
   FROM (public.expense_imports i
     LEFT JOIN public.expense_claims c ON ((c.import_id = i.id)))
  GROUP BY i.id, i.file_name, i.uploaded_at;

ALTER VIEW public.v_expense_import_summary OWNER TO postgres;

--
-- Name: VIEW v_expense_import_summary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_expense_import_summary IS 'Live replacement for outstation_expense_reports.row_count / approved_rows / total_expenses, which had no trigger and were wrong on 25 of 38 rows.';

--
-- Name: v_expense_payable; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_expense_payable AS
 SELECT payout_year,
    payout_month,
    employee_hr_id,
    lower(employee_hr_id) AS employee_hr_id_key,
    count(*) AS claim_count,
    (sum(COALESCE(approved_total, claimed_total)))::numeric(14,2) AS payable_amount
   FROM public.expense_claims c
  WHERE ((status = 'approved'::text) AND (payout_year IS NOT NULL) AND (payout_month IS NOT NULL) AND (COALESCE(evidence_gate_status, 'complete'::text) = ANY (ARRAY['complete'::text, 'grandfathered'::text])) AND (COALESCE(workload_gate_status, 'complete'::text) = ANY (ARRAY['complete'::text, 'grandfathered'::text, 'manual'::text])) AND (NOT (EXISTS ( SELECT 1
           FROM public.expense_payroll_links l
          WHERE (l.claim_id = c.id)))))
  GROUP BY payout_year, payout_month, employee_hr_id;

ALTER VIEW public.v_expense_payable OWNER TO postgres;

--
-- Name: VIEW v_expense_payable; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_expense_payable IS 'The payroll contract. Payroll PULLS this; Outstation never writes to salary_records.';

--
-- Name: v_expense_payroll_reconciliation; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_expense_payroll_reconciliation AS
 WITH claimed AS (
         SELECT c.incurred_year AS yr,
            c.incurred_month AS mo,
            count(*) AS claims,
            count(*) FILTER (WHERE (c.status = 'approved'::text)) AS approved_claims,
            count(*) FILTER (WHERE (c.status = 'rejected'::text)) AS rejected_claims,
            count(*) FILTER (WHERE (c.status = 'submitted'::text)) AS open_claims,
            (sum(c.claimed_total))::numeric(14,2) AS claimed_egp,
            (sum(COALESCE(c.approved_total, (0)::numeric)) FILTER (WHERE (c.status = ANY (ARRAY['approved'::text, 'in_payroll'::text, 'paid'::text]))))::numeric(14,2) AS approved_egp
           FROM public.expense_claims c
          WHERE (c.incurred_year IS NOT NULL)
          GROUP BY c.incurred_year, c.incurred_month
        ), linked AS (
         SELECT c.incurred_year AS yr,
            c.incurred_month AS mo,
            count(*) AS linked_claims,
            (sum(l.amount))::numeric(14,2) AS linked_egp
           FROM (public.expense_payroll_links l
             JOIN public.expense_claims c ON ((c.id = l.claim_id)))
          GROUP BY c.incurred_year, c.incurred_month
        )
 SELECT COALESCE(cl.yr, lk.yr) AS incurred_year,
    COALESCE(cl.mo, lk.mo) AS incurred_month,
    cl.claims,
    cl.approved_claims,
    cl.rejected_claims,
    cl.open_claims,
    cl.claimed_egp,
    cl.approved_egp,
    COALESCE(lk.linked_claims, (0)::bigint) AS linked_claims,
    (COALESCE(lk.linked_egp, (0)::numeric))::numeric(14,2) AS linked_egp,
    ((COALESCE(cl.approved_egp, (0)::numeric) - COALESCE(lk.linked_egp, (0)::numeric)))::numeric(14,2) AS approved_not_yet_linked_egp
   FROM (claimed cl
     FULL JOIN linked lk ON (((lk.yr = cl.yr) AND (lk.mo = cl.mo))));

ALTER VIEW public.v_expense_payroll_reconciliation OWNER TO postgres;

--
-- Name: VIEW v_expense_payroll_reconciliation; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_expense_payroll_reconciliation IS 'Per incurred month: what was claimed, what was approved, and what payroll actually carried. The gap column is what the July 2026 hand-carry lost (EGP 2,354 across B-175 and B-74).';

--
-- Name: v_hr_id_orphan_audit; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_hr_id_orphan_audit WITH (security_invoker='true') AS
 SELECT 'salary_records.hr_id'::text AS source,
    sr.hr_id,
