    max(sr.full_name) AS sample_name
   FROM (public.salary_records sr
     LEFT JOIN public.employees e ON ((e.hr_id = sr.hr_id)))
  WHERE ((sr.hr_id IS NOT NULL) AND (e.hr_id IS NULL))
