  GROUP BY sr.manager_hr_id;

ALTER VIEW public.v_hr_id_orphan_audit OWNER TO postgres;

--
-- Name: v_payroll_eligible_employees; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_payroll_eligible_employees WITH (security_invoker='true') AS
 SELECT hr_id,
    full_name,
    name_ar,
    crm_id,
    crm_username,
    work_email,
    mobile_number,
    job_title,
    hire_date,
    employment_status,
    education,
    manager_hr_id,
    department_id,
    line_id,
    area_id,
    team_id,
    position_id,
    created_at,
    updated_at,
    region_name,
    contract_signed_date,
    contract_renewal_date,
    probation_end_date,
    contract_start_date,
    contract_day,
    contract_month_number,
    contract_month_clean,
    birth_date,
    onboarding_source,
    onboarding_status,
    resignation_date,
    last_working_date,
    exit_reason,
    exit_status,
    payroll_eligible,
    organogram_visible
   FROM public.employees
  WHERE ((COALESCE(payroll_eligible, true) = true) AND (COALESCE(employment_status, 'active'::text) = 'active'::text));

ALTER VIEW public.v_payroll_eligible_employees OWNER TO postgres;

--
-- Name: v_slow_query_deltas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_slow_query_deltas WITH (security_invoker='true') AS
 WITH bounds AS (
         SELECT max(pg_stat_statements_snapshots.captured_at) AS newest
           FROM public.pg_stat_statements_snapshots
        ), newest AS (
         SELECT s.id,
            s.captured_at,
            s.queryid,
            s.query_sample,
            s.calls,
            s.total_exec_ms,
            s.mean_exec_ms,
            s.max_exec_ms,
            s.rows_returned,
            s.shared_blks_hit,
            s.shared_blks_read
           FROM public.pg_stat_statements_snapshots s,
            bounds b
          WHERE (s.captured_at = b.newest)
        ), previous AS (
         SELECT DISTINCT ON (s.queryid) s.id,
            s.captured_at,
            s.queryid,
            s.query_sample,
            s.calls,
            s.total_exec_ms,
            s.mean_exec_ms,
            s.max_exec_ms,
            s.rows_returned,
            s.shared_blks_hit,
            s.shared_blks_read
           FROM public.pg_stat_statements_snapshots s,
            bounds b
          WHERE (s.captured_at < b.newest)
          ORDER BY s.queryid, s.captured_at DESC
        )
 SELECT n.queryid,
    n.query_sample,
    n.captured_at,
    (n.calls - COALESCE(p.calls, (0)::bigint)) AS calls_since,
    round(((n.total_exec_ms - COALESCE(p.total_exec_ms, (0)::double precision)))::numeric, 1) AS total_ms_since,
    round((n.mean_exec_ms)::numeric, 1) AS mean_ms_now,
    round((COALESCE(p.mean_exec_ms, n.mean_exec_ms))::numeric, 1) AS mean_ms_before,
    round((n.max_exec_ms)::numeric) AS max_ms_now
   FROM (newest n
     LEFT JOIN previous p ON ((p.queryid = n.queryid)))
  WHERE (n.calls > COALESCE(p.calls, (0)::bigint))
  ORDER BY (n.total_exec_ms - COALESCE(p.total_exec_ms, (0)::double precision)) DESC;

ALTER VIEW public.v_slow_query_deltas OWNER TO postgres;

--
-- Name: VIEW v_slow_query_deltas; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.v_slow_query_deltas IS 'Per-query work done between the two most recent captures. This is the view that would have surfaced the 17.5s closing call.';

