--
-- Name: table_snapshots; Type: TABLE; Schema: recovery; Owner: postgres
--

CREATE TABLE recovery.table_snapshots (
    id bigint NOT NULL,
    taken_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    source_schema text NOT NULL,
    source_table text NOT NULL,
    content_hash text NOT NULL,
    row_count integer NOT NULL,
    payload jsonb NOT NULL,
    payload_bytes bigint NOT NULL,
    keep_daily boolean DEFAULT false NOT NULL
);

ALTER TABLE recovery.table_snapshots OWNER TO postgres;

--
-- Name: COLUMN table_snapshots.keep_daily; Type: COMMENT; Schema: recovery; Owner: postgres
--

COMMENT ON COLUMN recovery.table_snapshots.keep_daily IS 'True on the first snapshot of a UTC day for that table. Those survive the 72-version window for 30 days, so a slow-changing table still has older recovery points.';

--
-- Name: table_snapshots_id_seq; Type: SEQUENCE; Schema: recovery; Owner: postgres
--

ALTER TABLE recovery.table_snapshots ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME recovery.table_snapshots_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

