-- Name: outstation_expense_reports outstation_expense_reports_delete_payroll; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY outstation_expense_reports_delete_payroll ON public.outstation_expense_reports FOR DELETE TO authenticated USING (private.phx_can_manage_payroll());

--
-- Name: outstation_expense_reports outstation_expense_reports_insert_payroll; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY outstation_expense_reports_insert_payroll ON public.outstation_expense_reports FOR INSERT TO authenticated WITH CHECK (private.phx_can_manage_payroll());

--
-- Name: outstation_expense_reports outstation_expense_reports_select_access; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY outstation_expense_reports_select_access ON public.outstation_expense_reports FOR SELECT TO authenticated USING ((( SELECT private.phx_can_manage_payroll() AS phx_can_manage_payroll) OR (EXISTS ( SELECT 1
   FROM public.outstation_expenses pe
  WHERE ((pe.report_id = outstation_expense_reports.id) AND (( SELECT private.phx_has_company_access() AS phx_has_company_access) OR (((lower(COALESCE(pe.hr_id, ''::text)) = ( SELECT lower(COALESCE(private.phx_current_hr_id(), ''::text)) AS lower)) OR (lower(COALESCE(pe.hr_id, ''::text)) IN ( SELECT private.phx_visible_hr_ids() AS phx_visible_hr_ids))) AND (NOT (lower(COALESCE(pe.hr_id, ''::text)) IN ( SELECT private.phx_resigned_hr_ids() AS phx_resigned_hr_ids))))))))));

