CREATE POLICY salary_batches_select_access ON public.salary_batches FOR SELECT TO authenticated USING ((( SELECT private.phx_can_manage_payroll() AS phx_can_manage_payroll) OR (EXISTS ( SELECT 1
   FROM public.salary_records sr
  WHERE ((sr.batch_id = salary_batches.id) AND (( SELECT private.phx_has_company_access() AS phx_has_company_access) OR (((lower(COALESCE(sr.hr_id, ''::text)) = ( SELECT lower(COALESCE(private.phx_current_hr_id(), ''::text)) AS lower)) OR (lower(COALESCE(sr.hr_id, ''::text)) IN ( SELECT private.phx_visible_hr_ids() AS phx_visible_hr_ids))) AND (NOT (lower(COALESCE(sr.hr_id, ''::text)) IN ( SELECT private.phx_resigned_hr_ids() AS phx_resigned_hr_ids))))))))));

